import * as THREE from 'three';

/** 流星外形（头在 z = 0，尾巴往 -z 拉到 -1；半径最粗 1）：小而圆的头，前 3% 最粗，后面一条细尾（头的一半粗）慢慢收尖；低档截面点少一半、6 → 4 棱 */
export const DROP: [number, number][] = [[0, -0.008], [0.6, 0], [0.92, 0.012], [1, 0.03], [0.88, 0.06], [0.68, 0.1], [0.55, 0.17], [0.46, 0.28], [0.37, 0.42], [0.27, 0.58], [0.17, 0.74], [0.08, 0.88], [0, 1]];
export const DROP_LOW: [number, number][] = [[0, -0.008], [0.85, 0.008], [1, 0.03], [0.68, 0.1], [0.47, 0.27], [0.3, 0.55], [0.12, 0.82], [0, 1]];

export function dropGeometry(shape: [number, number][], sides: number): THREE.BufferGeometry {
  const g = new THREE.LatheGeometry(shape.map(([r, t]) => new THREE.Vector2(r, -t)), sides);
  g.rotateX(Math.PI / 2);
  const pos = g.getAttribute('position');
  const t = new Float32Array(pos.count);
  for (let i = 0; i < pos.count; i++) t[i] = THREE.MathUtils.clamp(-pos.getZ(i), 0, 1);
  g.setAttribute('aT', new THREE.BufferAttribute(t, 1));
  return g;
}

/**
 * 头部亮实（芯发白、正对视线最亮），往尾巴按距离渐隐；叠加混合，不写深度。
 * rim = 轮廓边缘淡到 0（T252 主炮弹尾焰：粗光带的外轮廓看不出棱角）
 */
export function dropMaterial(rim = false): THREE.ShaderMaterial {
  return new THREE.ShaderMaterial({
    defines: rim ? { RIM: '' } : {},
    vertexShader: /* glsl */ `
      attribute float aT;
      varying float vT;
      varying float vF;
      varying vec3 vC;
      void main() {
        vec4 mv = modelViewMatrix * instanceMatrix * vec4(position, 1.0);
        mat3 im = mat3(instanceMatrix);
        vec3 n = normalMatrix * (im * (normal / vec3(dot(im[0], im[0]), dot(im[1], im[1]), dot(im[2], im[2]))));
        vF = clamp(abs(dot(n, -mv.xyz)) * inversesqrt(max(dot(n, n) * dot(mv.xyz, mv.xyz), 1e-12)), 0.0, 1.0);
        vT = aT;
        vC = instanceColor;
        gl_Position = projectionMatrix * mv;
      }`,
    fragmentShader: /* glsl */ `
      varying float vT;
      varying float vF;
      varying vec3 vC;
      void main() {
        float head = 1.0 - smoothstep(0.0, 0.12, vT);
        float a = min(1.0, pow(clamp(1.0 - vT, 0.0, 1.0), 1.05) * (0.65 + 0.35 * vF) + 0.3 * head);
        #ifdef RIM
        a *= smoothstep(0.0, 0.55, vF);
        #endif
        vec3 tail = mix(vC * 1.6, vC * vec3(1.0, 0.65, 0.4), smoothstep(0.1, 0.95, vT));
        vec3 col = mix(tail, vec3(1.0, 0.93, 0.78) * vC.r, head * (0.5 + 0.4 * vF)) * (1.0 + 3.2 * head * (0.5 + 0.5 * vF));
        gl_FragColor = vec4(col, a);
        #include <colorspace_fragment>
      }`,
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    toneMapped: false,
  });
}
