/**
 * 激励视频广告（T030，策划 `T028-商业化运营策划案.md` 第 2 节 + `T030-策划补充说明.md` 第 6 节）：只做激励视频，不做插屏、不做横幅。
 * - 小游戏：`wx.createRewardedVideoAd` 单例；创建时关掉「没广告可放时弹分享页」的兜底（disableFallbackSharePage，否则就是「分享得奖励」）；
 *   只认看完（onClose 的 isEnded）；预拉成功才算 ready（按钮亮），拉不到 / 平台当天次数用完 = 灰色「广告暂不可用」。
 *   总开关 ADS_ENABLED + 广告位 AD_UNIT_ID：流量主开通前关着 → 广告按钮都不出现（换卡只有免费次数、新兵期免费抢修照旧）
 * - 网页：不放广告，换卡照旧不限次（T018 2.4）；`?ads=test` = 按小游戏规则走 + 假广告（3 秒，中途关 = 没看完），`?ads=empty` = 同样规则但永远拉不到
 * 每局 ≤ 5 条、两条换卡隔 60 秒、每天 ≤ 20 条、新兵期、首领战这些规则在 Game 里（要读存档和本局状态）
 */
export const ADS_ENABLED = false;
/** 激励视频广告位（流量主后台建好以后填这里） */
export const AD_UNIT_ID = '';
/** 上限：每局条数、每天条数、两条换卡广告的间隔（游戏秒）、每局换卡广告条数、每次加几张、每局免费换卡张数 */
export const AD_LIMIT = { run: 5, day: 20, gap: 60, reroll: 3, rerollAdd: 3, rerollFree: 3 };
/** 各个点每天最多几条（T028 2.1：军票翻倍 10、换任务 1、试驾 2） */
export const AD_DAY: Partial<Record<AdPlace, number>> = { double: 10, task: 1, drive: 2 };
/** 假广告时长（秒） */
export const FAKE_AD_SEC = 3;

export type AdMode = 'web' | 'wx' | 'test' | 'empty';
export type AdPlace = 'reroll' | 'revive' | 'double' | 'task' | 'drive';

interface WxRewarded {
  load(): Promise<void>;
  show(): Promise<void>;
  onLoad(cb: () => void): void;
  onError(cb: (e: unknown) => void): void;
  onClose(cb: (res?: { isEnded?: boolean }) => void): void;
}
type WxLike = { createCanvas?: unknown; createRewardedVideoAd?: (o: { adUnitId: string; disableFallbackSharePage?: boolean }) => WxRewarded };

function detect(): AdMode {
  const wx = (globalThis as { wx?: WxLike }).wx;
  if (wx && typeof wx.createCanvas === 'function') return 'wx';
  try {
    const q = new URLSearchParams(location.search).get('ads');
    if (q === 'test') return 'test';
    if (q === 'empty') return 'empty';
  } catch {
    /* 没有 location */
  }
  return 'web';
}

export class AdService {
  readonly mode = detect();
  /** 假广告的界面（Menu 给：DOM 版 / 画布版各一套）；done(true) = 看完 */
  fake: ((done: (ended: boolean) => void) => void) | null = null;
  /** 正在放（这期间界面上的广告按钮不再响应） */
  playing = false;
  /** 本次打开以来放了几条 / 看完几条（数据上报汇总第 38 条以后接这里） */
  readonly count = { shown: 0, ended: 0 };
  private ad: WxRewarded | null = null;
  private loaded = false;
  private pending: ((ended: boolean) => void) | null = null;

  constructor() {
    if (this.mode !== 'wx' || !ADS_ENABLED || !AD_UNIT_ID) return;
    const wx = (globalThis as { wx?: WxLike }).wx;
    if (typeof wx?.createRewardedVideoAd !== 'function') return;
    try {
      const ad = wx.createRewardedVideoAd({ adUnitId: AD_UNIT_ID, disableFallbackSharePage: true });
      ad.onLoad(() => (this.loaded = true));
      ad.onError(() => (this.loaded = false));
      ad.onClose((res) => {
        // 老基础库关掉时不带参数 = 看完
        const ended = !res || res.isEnded !== false;
        this.loaded = false;
        this.finish(ended);
        ad.load().catch(() => {});
      });
      this.ad = ad;
      ad.load().catch(() => {});
    } catch {
      this.ad = null;
    }
  }

  /** 小游戏规则（换卡有配额，复活卡 / 翻倍 / 试驾 / 换任务的按钮）：小游戏里、网页 ?ads=test / empty；网页试玩照旧不限次 */
  get rules(): boolean {
    return this.mode !== 'web';
  }

  /** 广告按钮出不出现：小游戏要总开关开着、广告位建好；网页测试模式出现 */
  get enabled(): boolean {
    return this.mode === 'test' || this.mode === 'empty' || this.ad !== null;
  }

  /** 现在拉得到广告（按钮亮；否则灰色「广告暂不可用」） */
  get ready(): boolean {
    return !this.playing && (this.mode === 'test' || (this.ad !== null && this.loaded));
  }

  /** 放一条：看完 resolve(true)；没看完 / 拉不到 resolve(false) */
  show(place: AdPlace): Promise<boolean> {
    void place;
    if (!this.ready) return Promise.resolve(false);
    this.playing = true;
    this.count.shown += 1;
    return new Promise((resolve) => {
      this.pending = resolve;
      if (this.mode === 'test') {
        if (this.fake) this.fake((ended) => this.finish(ended));
        else this.finish(true);
        return;
      }
      const ad = this.ad!;
      ad.show().catch(() =>
        ad
          .load()
          .then(() => ad.show())
          .catch(() => this.finish(false)),
      );
    });
  }

  private finish(ended: boolean): void {
    this.playing = false;
    if (ended) this.count.ended += 1;
    const p = this.pending;
    this.pending = null;
    p?.(ended);
  }
}
