import * as THREE from 'three';
import { copyGeometry, type CrushPartRange } from '../assets/GeoCache';
import type { Fx } from '../render/Fx';
import { SCN, SCN_META } from './sceneryTune';

/** 只标记原车站中的可损部件；轨道、站台和路基不参与变形。 */
export const STATION_PART = { canopy: 100, water: 200, wagon: 300, signal: 400 } as const;
interface Part {
  id: number;
  ranges: CrushPartRange[];
  box: THREE.Box3;
  center: THREE.Vector3;
  load: number;
  progress: number;
  target: number;
  heat: number;
  burn: number;
  soot: number;
  paintedSoot: number;
  fx: number;
}

/** 车站附属设施的显示状态，不挡弹、不加奖励或伤害，也不改变列车与轨道判定。 */
export class StationDamage {
  private readonly source: THREE.BufferGeometry;
  private readonly parts = new Map<number, Part>();
  private readonly v = new THREE.Vector3();
  private readonly q = new THREE.Quaternion();
  private readonly axis = new THREE.Vector3(0, 0, 1);
  private readonly lampAt: THREE.Vector3;

  constructor(private readonly mesh: THREE.Mesh, private readonly lamp: THREE.Mesh, private readonly fx: Fx) {
    this.source = mesh.geometry;
    this.lampAt = lamp.position.clone();
    const pos = this.source.getAttribute('position');
    for (const range of this.source.userData.crushParts as CrushPartRange[]) {
      if (range.role < STATION_PART.canopy) continue;
      let p = this.parts.get(range.role);
      if (!p) {
        p = { id: range.role, ranges: [], box: new THREE.Box3(), center: new THREE.Vector3(),
          load: 0, progress: 0, target: 0, heat: 0, burn: -1, soot: 0, paintedSoot: 0, fx: 0 };
        this.parts.set(p.id, p);
      }
      p.ranges.push(range);
      for (let i = range.start; i < range.start + range.count; i++) p.box.expandByPoint(this.v.fromBufferAttribute(pos, i));
      p.box.getCenter(p.center);
    }
  }

  reset(): void {
    if (this.mesh.geometry !== this.source) { this.mesh.geometry.dispose(); this.mesh.geometry = this.source; }
    this.lamp.visible = true; this.lamp.position.copy(this.lampAt);
    for (const p of this.parts.values()) {
      p.load = p.progress = p.target = p.heat = p.soot = p.paintedSoot = p.fx = 0; p.burn = -1;
    }
  }

  blast(x: number, z: number, radius: number, force: number, stationZ: number): void {
    for (const p of this.parts.values()) {
      const dx = Math.max(p.box.min.x - x, 0, x - p.box.max.x);
      const dz = Math.max(p.box.min.z - (z - stationZ), 0, z - stationZ - p.box.max.z);
      const d = Math.hypot(dx, dz);
      if (d <= radius) this.hurt(p, force * (1.25 - d / Math.max(.01, radius)), stationZ);
    }
  }

  beam(ox: number, oz: number, dx: number, dz: number, len: number, half: number, dt: number, rate: number, stationZ: number): void {
    for (const p of this.parts.values()) {
      // 与部件原占地求进入点，只响应已经到达这里的光束，不改变光束长度。
      let near = 0, far = len;
      for (const axis of ['x', 'z'] as const) {
        const o = axis === 'x' ? ox : oz - stationZ, dir = axis === 'x' ? dx : dz;
        const min = p.box.min[axis] - half, max = p.box.max[axis] + half;
        if (Math.abs(dir) < 1e-8) { if (o < min || o > max) { far = -1; break; } }
        else {
          const a = (min - o) / dir, b = (max - o) / dir;
          near = Math.max(near, Math.min(a, b)); far = Math.min(far, Math.max(a, b));
        }
      }
      if (far >= near) this.hurt(p, rate * dt, stationZ);
    }
  }

  flame(ox: number, oz: number, angle: number, range: number, cone: number, dt: number, stationZ: number): void {
    for (const p of this.parts.values()) {
      const x = p.center.x - ox, z = p.center.z + stationZ - oz, d = Math.hypot(x, z);
      const r = Math.hypot(p.box.max.x - p.box.min.x, p.box.max.z - p.box.min.z) / 2;
      const a = Math.atan2(-x, -z) - angle;
      if (d <= range + r && Math.abs(Math.atan2(Math.sin(a), Math.cos(a))) <= cone + r / Math.max(3, d)) this.heat(p, dt);
    }
  }

  ignite(x: number, z: number, rx: number, rz: number, stationZ: number): void {
    for (const p of this.parts.values()) {
      const dx = Math.max(p.box.min.x - x, 0, x - p.box.max.x) / rx;
      const dz = Math.max(p.box.min.z - (z - stationZ), 0, z - stationZ - p.box.max.z) / rz;
      if (dx * dx + dz * dz <= 1) this.heat(p, SCN.ignite.groundWood);
    }
  }

  private hurt(p: Part, force: number, stationZ: number): void {
    if (p.target >= 1 || force <= 0) return;
    p.load += force;
    const limit = p.id >= STATION_PART.signal ? SCN_META.pole.hp
      : p.id >= STATION_PART.wagon ? SCN_META.hulk.hp : SCN_META.log.hp;
    const target = p.load >= limit ? 1 : p.load >= SCN.house.hole ? .18 : 0;
    if (target <= p.target) return;
    p.target = target;
    this.fx.dust(p.center.x, p.center.z + stationZ, 1.4, 0x877761, .4);
    if (p.id !== STATION_PART.water) this.fx.sparks(p.center.x, 1.5, p.center.z + stationZ, 4, 0xffd090, 5);
  }

  private heat(p: Part, dt: number): void {
    p.heat += dt;
    p.soot = Math.min(.45, p.heat * .3);
    if (p.id === STATION_PART.water && p.burn < 0 && p.target < 1 && p.heat >= SCN.ignite.flameWood) p.burn = 0;
  }

  update(dt: number, stationZ: number): void {
    let dirty = false;
    for (const p of this.parts.values()) {
      let changed = false;
      if (p.burn >= 0 && p.burn < SCN.burn.pole) {
        p.burn += dt; p.fx -= dt;
        if (p.fx <= 0) {
          p.fx = .2;
          const angle = 1.42 * p.progress * p.progress;
          this.fx.fire(p.center.x - Math.sin(angle) * 9.8, Math.max(.5, Math.cos(angle) * 9.8), p.center.z + stationZ, 1.8);
        }
        if (p.burn >= SCN.burn.pole) p.target = 1;
      }
      if (p.progress < p.target) {
        p.progress = Math.min(p.target, p.progress + dt / (p.id === STATION_PART.water ? SCN.anim.fall : SCN.anim.tip));
        changed = true;
      }
      if (!changed && p.soot === p.paintedSoot) continue;
      if (this.mesh.geometry === this.source) this.mesh.geometry = copyGeometry(this.source);
      this.pose(p);
      dirty = true;
      p.paintedSoot = p.soot;
    }
    if (dirty) {
      for (const key of ['position', 'normal', 'color']) this.mesh.geometry.getAttribute(key).needsUpdate = true;
      this.mesh.geometry.computeBoundingSphere();
    }
  }

  private pose(p: Part): void {
    const src = this.source.getAttribute('position'), sn = this.source.getAttribute('normal'), sc = this.source.getAttribute('color');
    const pos = this.mesh.geometry.getAttribute('position') as THREE.BufferAttribute;
    const nor = this.mesh.geometry.getAttribute('normal') as THREE.BufferAttribute;
    const col = this.mesh.geometry.getAttribute('color') as THREE.BufferAttribute;
    const k = p.progress * p.progress, toppling = p.id === STATION_PART.water || p.id === STATION_PART.signal;
    const angle = toppling ? 1.42 * k : (p.id % 2 ? -.18 : .18) * k;
    this.q.setFromAxisAngle(this.axis, angle);
    for (const range of p.ranges) for (let i = range.start; i < range.start + range.count; i++) {
      this.v.fromBufferAttribute(src, i);
      if (toppling) this.v.x -= p.center.x;
      else { this.v.x -= p.center.x; this.v.y -= p.id >= STATION_PART.wagon ? 1.2 : .85; }
      if (toppling) this.v.applyQuaternion(this.q);
      else if (p.id >= STATION_PART.wagon) {
        if (this.v.y > 0) {
          this.v.x *= 1 + k * .12;
          this.v.y *= 1 - k * .76;
          this.v.x += Math.sin(this.v.z * 1.8) * k * .12;
        }
      } else if (src.getY(i) > 3.8) { this.v.applyQuaternion(this.q); this.v.y -= k * 2.9; }
      else { this.v.x += Math.max(0, this.v.y) * k * .38; this.v.y *= 1 - k * .84; }
      this.v.x += p.center.x;
      if (!toppling) this.v.y += p.id >= STATION_PART.wagon ? 1.2 : .85;
      pos.setXYZ(i, this.v.x, Math.max(.08, this.v.y), this.v.z);
      this.v.fromBufferAttribute(sn, i);
      if (toppling || (p.id < STATION_PART.water && src.getY(i) > 3.8)) this.v.applyQuaternion(this.q);
      nor.setXYZ(i, this.v.x, this.v.y, this.v.z);
      const tint = 1 - p.soot;
      col.setXYZ(i, sc.getX(i) * tint, sc.getY(i) * tint, sc.getZ(i) * tint);
    }
    if (p.id === STATION_PART.signal) {
      this.lamp.visible = p.progress < .2;
      this.lamp.position.copy(this.lampAt).sub(this.v.set(p.center.x, 0, 0)).applyQuaternion(this.q).add(this.v);
    }
  }

  describe() {
    return [...this.parts.values()].map(p => ({ part: p.id, load: p.load, progress: p.progress, target: p.target, burn: p.burn }));
  }
}
