import { MAT } from '../assets/materials';
import { sceneryMaterial } from '../assets/sceneryMaterial';
import { SCN_MAT, SCN_RICH, sceneryDetailFor, setSceneryDetail } from './sceneryDetail';
import type { Quality } from '../render/Post';
import { scenePatchGeo, sceneryGeo, sceneryVariantGeo, type SceneryVariant } from '../assets/models/environment';
import { isTreeLook, sceneryLookGeo, type SceneryLook } from '../assets/models/sceneryLooks';
import type { Fx } from '../render/Fx';
import { SceneryDebris } from '../systems/SceneryDebris';
import { SceneryDamage, type ScnHooks, type ScnHit, type ScnSolid } from './SceneryDamage';
