export type { ScnHooks, ScnHit, ScnSolid };

/** 一个实例槽的句柄：紧凑存放挪位时 index 跟着更新（防串号，见 InstancePool.check） */
export interface Handle {
  pool: InstancePool;
  index: number;
  item: ScnItem | null;
}

/**
 * 紧凑存放的实例池（T009 6.2）：删除时把最后一个挪到空位，绘制数量 = 实际数量；数量为 0 时不出绘制。
 * 条目拿的是句柄，挪位时句柄的 index 跟着改；这一帧真改过矩阵 / 颜色才上传
 */
export class InstancePool {
  readonly mesh: THREE.InstancedMesh;
  readonly slots: Handle[] = [];
  private dirtyM = false;
  private dirtyC = false;
  private readonly m = new THREE.Matrix4();
  private readonly c = new THREE.Color();

  constructor(
    readonly name: string,
    geo: THREE.BufferGeometry,
    readonly cap: number,
    shadow: boolean,
  ) {
    // T184：带表面类别的加细景物换程序纹理材质；其余照旧顶点色涂装
    this.mesh = new THREE.InstancedMesh(geo, geo.getAttribute('surf') && SCN_MAT ? sceneryMaterial() : MAT.painted, cap);
    this.mesh.castShadow = shadow;
    this.mesh.receiveShadow = true;
    this.mesh.frustumCulled = false;
    this.mesh.count = 0;
    this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    // 实例色和顶点色相乘：烧焦 / 熏黑 / 秃干的棕色都靠它，不加绘制
    for (let i = 0; i < cap; i++) this.mesh.setColorAt(i, this.c.setRGB(1, 1, 1));
    this.mesh.instanceColor!.setUsage(THREE.DynamicDrawUsage);
  }

  get full(): boolean {
    return this.slots.length >= this.cap;
  }

  add(item: ScnItem | null, m: THREE.Matrix4, tint = 1): Handle | null {
    if (this.full) return null;
    const h: Handle = { pool: this, index: this.slots.length, item };
    this.slots.push(h);
    this.mesh.setMatrixAt(h.index, m);
    this.mesh.setColorAt(h.index, this.c.setRGB(tint, tint, tint));
    this.mesh.count = this.slots.length;
    this.dirtyM = this.dirtyC = true;
    return h;
  }

  remove(h: Handle): void {
    if (h.index < 0 || this.slots[h.index] !== h) return;
    const last = this.slots.pop()!;
    if (last !== h) {
      this.mesh.getMatrixAt(last.index, this.m);
      this.mesh.setMatrixAt(h.index, this.m);
      this.mesh.getColorAt(last.index, this.c);
      this.mesh.setColorAt(h.index, this.c);
      last.index = h.index;
      this.slots[h.index] = last;
    }
    h.index = -1;
    this.mesh.count = this.slots.length;
    this.dirtyM = this.dirtyC = true;
  }

  set(h: Handle, m: THREE.Matrix4): void {
    if (h.index < 0) return;
    this.mesh.setMatrixAt(h.index, m);
    this.dirtyM = true;
  }

  tint(h: Handle, r: number, g = r, b = r): void {
    if (h.index < 0) return;
    this.mesh.setColorAt(h.index, this.c.setRGB(r, g, b));
    this.dirtyC = true;
  }

  flush(): void {
    if (this.dirtyM) this.mesh.instanceMatrix.needsUpdate = true;
    if (this.dirtyC) this.mesh.instanceColor!.needsUpdate = true;
    this.dirtyM = this.dirtyC = false;
  }

  clear(): void {
    for (const h of this.slots) h.index = -1;
    this.slots.length = 0;
    this.mesh.count = 0;
  }
}

/** 景物的破坏状态（最终形态由最后一击的破坏方式决定）；stump = 核弹火球汽化后剩的焦黑树桩，melted = 天火核心熔掉的熔渣堆 */
export type ScnState =
  | 'intact' | 'lean' | 'fallen' | 'broken' | 'uprooted' | 'bald' | 'bare' | 'flat'
  | 'half' | 'shell' | 'rubble' | 'strip' | 'pile' | 'split' | 'gone' | 'stump' | 'melted';

/** 一件景物（每个实例一份状态，甩到身后和实例一起回收，不存档） */
export interface ScnItem {
  id: number;
  kind: ScnKind;
  /** 外观不参与结构值、挡弹与奖励判定。 */
  look?: SceneryLook;
  /** 新增林簇 / 街屋；原景物仍先摆，原随机序列不变。 */
  dressing?: boolean;
  x: number;
  z: number;
  /** 地面高度（弹坑里会是负的） */
  y: number;
  rot: number;
  s: number;
  /** 0 = 原来的远景，1 = 路肩带 */
  band: 0 | 1;
  hp: number;
  state: ScnState;
  /** 主体实例（完好 / 破坏变体）、上半截 / 另一半（打断的树和杆、劈开的巨石） */
  main: Handle | null;
  top: Handle | null;
  /** 主体：倾斜方向（单位向量）和角度、绕哪个点倒（相对条目原点）、竖直压扁、下沉、实例色 */
  tdx: number;
  tdz: number;
  tilt: number;
  px: number;
  pz: number;
  fy: number;
  /** 结构形变接手前的高度比例；保留已有损伤，不再叠整件压缩。 */
  crushVisual?: number;
  /** 草垛烧小（T203）：绕两捆草的占地中心水平收缩；没有 = 1 */
  fxz?: number;
  sink: number;
  tint: number;
  /** 上半截：倒向、角度、断口离地高度、沿切面滑开的偏移 */
  udx: number;
  udz: number;
  utilt: number;
  uy: number;
  uox: number;
  uoz: number;
  /** 上半截竖直压扁（被坦克压过） */
  ufy: number;
  /** 抛飞 / 翻滚：位置速度和自转（only when flying） */
  vx: number;
  vy: number;
  vz: number;
  spin: number;
  roll: number;
  ox: number;
  oy: number;
  oz: number;
  /** 正在播的动画（null = 静止）、已播时间、时长、动画参数 */
  anim: string | null;
  at: number;
  dur: number;
  a0: number;
  a1: number;
  /** 燃烧：已烧秒数（-1 = 没着）、热量累积、燃烧加速、闷烧剩余 */
  burn: number;
  heat: number;
  burnRate: number;
  smolder: number;
  fxT: number;
  /** 光束接触累计、切口红热剩余 */
  cutT: number;
  hot: number;
  /** 墙洞 / 切痕贴片 */
  patches: Handle[];
  /** 已碎的窗户（位） */
  glass: number;
  bump: import('../systems/World').Bump | null;
  /** 打倒它的武器（砸到步兵记在这件武器名下） */
  src: string;
  bucket: number;
  alive: boolean;
  /** 冒过的一次性反馈（电弧焦痕等） */
  marks: number;
}

/** 每种基础景物的池容量（原来的远景 + 路肩带） */
const CAPACITY: Record<ScnKind, number> = {
  rock: 110, boulder: 36, pole: 18, trap: 50, pine: 230, bush: 120, house: 22, ruin: 24, wall: 64, hulk: 26, sandbag: 44, hay: 44, hedge: 220, log: 54,
};
/** 破坏变体池（出现时每种 +1 次绘制，不投影） */
const VARIANT_CAP: Record<SceneryVariant, number> = {
  pineStump: 60, pineTop: 60, pineRoot: 30, pineBald: 60, poleStump: 16, poleTop: 16, houseHalf: 12, houseShell: 12, houseRubble: 18, brickStrip: 44, boulderHalf: 16,
};

/** 体积大的景物离路远一点，免得挡住视线（原来的远景） */
const MIN_OFFSET: Partial<Record<ScnKind, number>> = { house: 12, ruin: 10, boulder: 6, pine: 4, hedge: 4 };
/** T184 加细档：灌木 / 篱墙也投影 */
const NO_SHADOW = new Set<ScnKind>(SCN_RICH ? ['rock', 'sandbag', 'hay', 'log', 'trap'] : ['rock', 'bush', 'hedge', 'sandbag', 'hay', 'log', 'trap']);
const BIG = new Set<ScnKind>(['house', 'ruin', 'boulder', 'wall', 'hulk']);
const STEP = 6;
const AHEAD = 300;
const BEHIND = 60;
const POLE_GAP = 34;
/** z 分桶（每 8 米一个桶，每桶约 2 件）：爆炸、弹道、光束都只查相关的几个桶 */
export const BUCKET = 8;

/**
 * 路边景物：每种一个 InstancedMesh，按当前主题权重在前方不断生成，身后回收。
 * T009：每个实例有破坏状态（SceneryDamage），全图的景物都能被打坏（远处的直接到终态）；另开一条路肩带（路边 16～27 米），保证默认视角看得见
 */
export class Scenery {
  readonly group = new THREE.Group();
  readonly pools = new Map<string, InstancePool>();
  readonly items: ScnItem[] = [];
  readonly buckets = new Map<number, ScnItem[]>();
  readonly patchPool: InstancePool;
  readonly debris: SceneryDebris;
  readonly damage: SceneryDamage;
  /** 地面高度（弹坑）：景物立在坑里 */
  groundAt: (x: number, z: number) => number = () => 0;
  playerX = 0;
  playerZ = 0;
  /** 离路中心最近的景物占地内沿（|x| − 半径，只减不增，重开复位）：弹道 / 光束 / 碾压都在这条线以内就不用查 */
  innerX = 14;
  private cursor = 40;
  private poleCursor = 20;
  private sideCursor = 30;
  private dressingCursor = 0;
  /** 这一帧 update 传进来的「这里不长东西」（河道、铁路路基、车站） */
  private blocked: (x: number, z: number, r?: number) => boolean = () => false;
  /** 这里是哪个主题（T122：摆的时候按主题染色，沙漠的灌木染成骆驼刺） */
  private themeAt: ((z: number) => Theme) | null = null;
  private nextId = 1;
  private readonly m = new THREE.Matrix4();
  private readonly q = new THREE.Quaternion();
  private readonly s = new THREE.Vector3();
  private readonly p = new THREE.Vector3();
  private seed = 7;
  private sideSeed = 911;
  private readonly geoFactories = new Map<InstancePool, () => THREE.BufferGeometry>();
  private readonly poolShadow = new Map<InstancePool, boolean>();
  private quality: Quality | null = null;
  /** 各池的基线（重开后的数量），scn.check 用 */
  readonly stats = {
    destroyed: { tree: 0, pole: 0, house: 0, wall: 0, other: 0 },
  };

  constructor(
    private readonly geo: GeoCache,
    readonly fx: Fx,
    hooks: ScnHooks,
  ) {
    for (const id of Object.keys(CAPACITY) as ScnKind[]) this.addPool(id, () => sceneryGeo(geo, id), CAPACITY[id], !NO_SHADOW.has(id));
    for (const id of Object.keys(VARIANT_CAP) as SceneryVariant[]) this.addPool(id, () => sceneryVariantGeo(geo, id), VARIANT_CAP[id], false);
    this.patchPool = this.addPool('patch', () => scenePatchGeo(geo), SCN.cap.patch, false);
    this.patchPool.mesh.receiveShadow = false;
    this.debris = new SceneryDebris(this.group, geo, SCN.cap.debrisPer, SCN.cap.debris);
    this.debris.groundAt = (x, z) => this.groundAt(x, z);
    this.damage = new SceneryDamage(this, hooks);
  }

  private addPool(name: string, makeGeo: () => THREE.BufferGeometry, cap: number, shadow: boolean): InstancePool {
    const pool = new InstancePool(name, makeGeo(), cap, this.quality !== 'low' && shadow);
    this.geoFactories.set(pool, makeGeo);
    this.poolShadow.set(pool, shadow);
    this.pools.set(name, pool);
    this.group.add(pool.mesh);
    return pool;
  }

  /** 换画质（T245 起网页也换）：面数倍数按 sceneryDetailFor，低档景物不投影；换下来的那套几何体移出缓存、释放显存 */
  setQuality(quality: Quality): void {
    if (this.quality === quality) return;
    this.quality = quality;
    setSceneryDetail(sceneryDetailFor(quality));
    for (const [pool, makeGeo] of this.geoFactories) {
      const old = pool.mesh.geometry;
      pool.mesh.geometry = makeGeo();
      if (old !== pool.mesh.geometry) this.geo.drop(old);
      const rich = !!pool.mesh.geometry.getAttribute('surf') && SCN_MAT;
      const painted = pool.mesh.material === MAT.painted;
      if (rich && painted) pool.mesh.material = sceneryMaterial();
      else if (!rich && !painted) {
        for (const material of [pool.mesh.material].flat()) material.dispose();
        pool.mesh.material = MAT.painted;
      }
      pool.mesh.castShadow = quality !== 'low' && this.poolShadow.get(pool)!;
    }
  }

  pool(name: string, look?: SceneryLook): InstancePool {
    if (look && ((isTreeLook(look) && name.startsWith('pine')) || (!isTreeLook(look) && name === 'house'))) {
      const key = `${look}:${name}`;
      let pool = this.pools.get(key);
      if (!pool) {
        const cap = name === 'pine' ? 200 : name === 'house' ? 48 : VARIANT_CAP[name as SceneryVariant];
        pool = this.addPool(key, () => sceneryLookGeo(this.geo, look, name), cap, name === 'pine' || name === 'house');
        pool.mesh.castShadow = this.quality !== 'low' && this.poolShadow.get(pool)!;
      }
      return pool;
    }
    return this.pools.get(name)!;
  }

  /** 形变结束的路边残留回到实例池。 */
  settleCrush(it: ScnItem, name: string, geo: THREE.BufferGeometry): boolean {
    const pool = this.pools.get(name) ?? this.addPool(name, () => geo, 32, false);
    if (pool.full) return false;
    if (it.main) it.main.pool.remove(it.main);
    it.main = pool.add(it, this.mainMatrix(it), it.tint);
    return true;
  }

  reset(): void {
    for (const it of [...this.items]) this.release(it);
    for (const p of this.pools.values()) p.clear();
    this.items.length = 0;
    this.buckets.clear();
    this.debris.clear();
    this.damage.reset();
    this.cursor = 40;
    this.poleCursor = 20;
    this.sideCursor = 30;
    this.dressingCursor = 0;
    this.innerX = 14;
  }

  /**
   * blocked(x, z)：这里不长东西（河道 + 岸边，T017-3A 起按 (x, z) 判断——河在田野里拐弯，景物沿河岸摆，不再整排空出来；
   * T017-4A：铁路路基 / 车站那一片也不长）
   */
  update(playerX: number, playerZ: number, delta: number, themeAt: (z: number) => Theme, blocked: (x: number, z: number, r?: number) => boolean = () => false, rear = playerZ): void {
    this.playerX = playerX;
    this.playerZ = playerZ;
    this.blocked = blocked;
    this.themeAt = themeAt;
    // 回收身后的（状态、变体、贴片、凸起、燃烧点一起释放）；rear = T107 停车攻坚时能退到的最远处（往前挪了再退回来，身后的景物还在）
    for (let i = this.items.length - 1; i >= 0; i--) if (this.items[i].z > rear + BEHIND) this.release(this.items[i]);
    while (this.cursor > playerZ - AHEAD) {
      const z = this.cursor;
      const theme = themeAt(z);
      for (const side of [-1, 1]) {
        if (this.rnd() < 0.72) this.spawn(this.pick(theme.scenery, () => this.rnd()), side, z + this.rnd() * STEP);
      }
      this.cursor -= STEP;
    }
    // 路肩带：另开一个游标（不影响原来的远景）
    while (SCN.roadside && this.sideCursor > playerZ - AHEAD) {
      const z = this.sideCursor;
      const rs = themeAt(z).roadside;
      for (const side of [-1, 1]) if (this.srnd() < rs.chance) this.spawnRoadside(rs, side, z - this.srnd() * rs.step * 0.5);
      this.sideCursor -= rs.step;
    }
    // 电线杆沿左侧等距排列，给速度感
    while (this.poleCursor > playerZ - AHEAD) {
      if (themeAt(this.poleCursor).poles && !blocked(-(ROAD_HALF_WIDTH + 5), this.poleCursor)) this.place('pole', -(ROAD_HALF_WIDTH + 5), this.poleCursor, 0, 1, 0);
      this.poleCursor -= POLE_GAP;
    }
    // 原远景提前三百米生成；加密层只到二百四十米，始终让原物件先占位。
    while (this.dressingCursor > playerZ - DRESS_AHEAD) {
      const z = this.dressingCursor, theme = themeAt(z - DRESS_STEP / 2).id;
      for (const side of [-1, 1]) sceneryLayout(z, side, theme, site => {
        if (themeAt(site.z).id === theme) this.placeDressing(site);
      });
      this.dressingCursor -= DRESS_STEP;
    }
    this.damage.update(delta);
    this.debris.update(delta);
    for (const p of this.pools.values()) p.flush();
  }

  private pick(weights: Partial<Record<SceneryId, number>>, rnd: () => number): SceneryId {
    const entries = Object.entries(weights) as [SceneryId, number][];
    const total = entries.reduce((s, [, w]) => s + w, 0);
    let roll = rnd() * total;
    for (const [id, w] of entries) {
      roll -= w;
      if (roll <= 0) return id;
    }
    return entries[0][0];
  }

  private spawn(id: SceneryId, side: number, z: number): void {
    const near = Math.pow(this.rnd(), 1.7);
    if (id === 'crater') {
      const x = side * (ROAD_HALF_WIDTH + 2 + near * 60);
      this.fx.decals.add(1, x, z, 4 + this.rnd() * 5, 4 + this.rnd() * 5, this.rnd() * 6.28, 0.75, 400);
      return;
    }
    const x = side * (ROAD_HALF_WIDTH + 3 + (MIN_OFFSET[id] ?? 0) + near * 90);
    if (this.blocked(x, z, this.reach(id))) return;
    const scale = id === 'house' || id === 'ruin' || id === 'hedge' ? 0.9 + this.rnd() * 0.3 : 0.7 + this.rnd() * 0.8;
    if (id === 'hedge') {
      // 12 米一条的篱墙拆成 3 段（每段 4 米单独破坏），大多顺着路、偶尔斜插
      const rot = Math.PI / 2 + (this.rnd() - 0.5) * 0.8;
      for (let k = -1; k <= 1; k++) this.place('hedge', x + Math.cos(rot) * k * 4 * scale, z - Math.sin(rot) * k * 4 * scale, rot + (this.rnd() - 0.5) * 0.12, scale, 0);
      return;
    }
    this.place(id, x, z, this.rnd() * Math.PI * 2, scale, 0);
  }

  /** 路肩带：软件放 16～20 米（坦克能碰到），硬件和高的放 20.5～27 米，房屋 / 残楼 23.5～27 米、正面朝路 */
  private spawnRoadside(rs: Theme['roadside'], side: number, z: number): void {
    const id = this.pick({ ...rs.soft, ...rs.hard }, () => this.srnd()) as ScnKind;
    const soft = id in rs.soft;
    const r = () => this.srnd();
    let x: number;
    let rot = r() * Math.PI * 2;
    let scale = 0.8 + r() * 0.5;
    if (id === 'house' || id === 'ruin') {
      x = side * (23.5 + r() * 3.5);
      // 正面（+z）朝路：主炮瞄着房子打，炸在迎面那堵墙上
      rot = -side * (Math.PI / 2) + (r() - 0.5) * 0.12;
      scale = 0.9 + r() * 0.2;
    } else if (soft) {
      x = side * (16 + r() * 4);
    } else {
      x = side * (20.5 + r() * 6.5);
    }
    if (this.blocked(x, z, this.reach(id))) return;
    if (id === 'wall') rot = Math.PI / 2 + (r() - 0.5) * 0.4;
    if (id === 'hedge') {
      rot = Math.PI / 2 + (r() - 0.5) * 0.2;
      scale = 0.9 + r() * 0.2;
      for (const k of [-0.5, 0.5]) this.place('hedge', x + Math.cos(rot) * k * 4 * scale, z - Math.sin(rot) * k * 4 * scale, rot + (r() - 0.5) * 0.1, scale, 1);
      return;
    }
    this.place(id, x, z, rot, scale, 1);
  }

  /** 摆一件景物（调试接口 scn.place 也走这里）；大件和已有的大件重叠就不摆 */
  place(id: ScnKind, x: number, z: number, rotY: number, scale: number, band: 0 | 1, force = false,
    appearance: { look?: SceneryLook; dressing?: boolean } = {}): ScnItem | null {
    const meta = SCN_META[id];
    if (!force && !appearance.dressing && BIG.has(id)) {
      const rad = this.radiusOf(id, scale);
      let clash = false;
      this.query(x, z, rad + 8, (o) => {
        if (!o.dressing && BIG.has(o.kind) && Math.hypot(o.x - x, o.z - z) < rad + this.radiusOf(o.kind, o.s) + 0.5) clash = true;
      });
      if (clash) return null;
    }
    const pool = appearance.dressing && !appearance.look
      ? this.pools.get(`dressing:${id}`) ?? this.addPool(`dressing:${id}`, () => sceneryGeo(this.geo, id), CAPACITY[id], !NO_SHADOW.has(id))
      : this.pool(id, appearance.look);
    if (pool.full) {
      if (appearance.dressing) return null;
      // 池满：复用最靠后的同类（状态整体释放）
      let far: ScnItem | null = null;
      for (const it of this.items) if (!it.dressing && it.kind === id && (!far || it.z > far.z)) far = it;
      if (far) this.release(far);
      if (pool.full) return null;
    }
    const it: ScnItem = {
      id: this.nextId++, kind: id, ...appearance, x, z, y: this.groundAt(x, z), rot: rotY, s: scale, band, hp: meta.hp, state: 'intact',
      main: null, top: null, tdx: 0, tdz: 1, tilt: 0, px: 0, pz: 0, fy: 1, sink: 0, tint: 1,
      udx: 0, udz: 1, utilt: 0, uy: 0, uox: 0, uoz: 0, ufy: 1, vx: 0, vy: 0, vz: 0, spin: 0, roll: 0, ox: 0, oy: 0, oz: 0,
      anim: null, at: 0, dur: 0, a0: 0, a1: 0, burn: -1, heat: 0, burnRate: 1, smolder: 0, fxT: 0, cutT: 0, hot: 0,
      patches: [], glass: 0, bump: null, src: 'other', bucket: Math.floor(z / BUCKET), alive: true, marks: 0,
    };
    it.main = pool.add(it, this.mainMatrix(it));
    const rgb = this.themeAt?.(z).scnTint?.[id as SceneryId];
    if (rgb && it.main) pool.tint(it.main, rgb[0], rgb[1], rgb[2]);
    this.items.push(it);
    this.innerX = Math.min(this.innerX, Math.abs(x) - this.radiusOf(id, scale) - 1);
    let b = this.buckets.get(it.bucket);
    if (!b) this.buckets.set(it.bucket, (b = []));
    b.push(it);
    return it;
  }

  private placeDressing(site: ScenerySite): void {
    const { kind, x, z, rot, scale, look } = site;
    const r = kind === 'pine' ? 2.2 * scale : this.radiusOf(kind, scale);
    if (this.blocked(x, z, r)) return;
    let clash = false;
    // 临街房屋按实际长宽留缝，外接圆会把相邻房屋推得过远。树冠可以相接，树干不重叠。
    const bounds = (id: ScnKind, s: number, angle: number): [number, number] => {
      if (id === 'pine') return [2.2 * s, 2.2 * s];
      const m = SCN_META[id], c = Math.abs(Math.cos(angle)), sn = Math.abs(Math.sin(angle));
      const hw = m.hw ?? m.r ?? 1, hd = m.hd ?? m.r ?? 1;
      return [(hw * c + hd * sn) * s, (hw * sn + hd * c) * s];
    };
    const [hw, hd] = bounds(kind, scale, rot);
    this.query(x, z, r + 6, o => {
      if (kind === 'pine' && o.kind === 'pine') {
        if (Math.hypot(o.x - x, o.z - z) < 2.5) clash = true;
      } else if (BIG.has(o.kind) || (kind === 'house' && o.kind === 'pine')) {
        const [ow, od] = bounds(o.kind, o.s, o.rot);
        if (Math.abs(o.x - x) < hw + ow + .3 && Math.abs(o.z - z) < hd + od + .3) clash = true;
      }
    });
    if (!clash) this.place(kind, x, z, rot, scale, 0, false, { look, dressing: true });
  }

  /** 条目回收：状态、破坏变体、贴片、凸起、燃烧一起释放 */
  release(it: ScnItem): void {
    if (!it.alive) return;
    it.alive = false;
    if (it.main) it.main.pool.remove(it.main);
    if (it.top) it.top.pool.remove(it.top);
    it.main = it.top = null;
    // dropPatch 会从 it.patches 里删掉自己：先拷一份再遍历（边删边遍历会漏掉一半，贴片留在池里成孤儿）
    for (const h of [...it.patches]) this.damage.dropPatch(h);
    it.patches.length = 0;
    if (it.bump) it.bump.alive = false;
    it.bump = null;
    this.damage.forget(it);
    const i = this.items.indexOf(it);
    if (i >= 0) {
      this.items[i] = this.items[this.items.length - 1];
      this.items.pop();
    }
    const b = this.buckets.get(it.bucket);
    if (b) {
      const j = b.indexOf(it);
      if (j >= 0) {
        b[j] = b[b.length - 1];
        b.pop();
      }
      if (b.length === 0) this.buckets.delete(it.bucket);
    }
  }

  /** 挪到别的桶（被炸飞 / 滚出去 4 米以上） */
  rebucket(it: ScnItem): void {
    this.innerX = Math.min(this.innerX, Math.abs(it.x) - this.radiusOf(it.kind, it.s) - 1);
    const nb = Math.floor(it.z / BUCKET);
    if (nb === it.bucket) return;
    const b = this.buckets.get(it.bucket);
    if (b) {
      const j = b.indexOf(it);
      if (j >= 0) {
        b[j] = b[b.length - 1];
        b.pop();
      }
      if (b.length === 0) this.buckets.delete(it.bucket);
    }
    it.bucket = nb;
    let nbList = this.buckets.get(nb);
    if (!nbList) this.buckets.set(nb, (nbList = []));
    nbList.push(it);
  }

  /** (x, z) 周围 r 米（按桶粗筛）的活条目 */
  query(x: number, z: number, r: number, fn: (it: ScnItem) => void): void {
    const b0 = Math.floor((z - r - 6) / BUCKET);
    const b1 = Math.floor((z + r + 6) / BUCKET);
    for (let b = b0; b <= b1; b++) {
      const list = this.buckets.get(b);
      if (!list) continue;
      for (let i = list.length - 1; i >= 0; i--) {
        const it = list[i];
        if (!it.alive || Math.abs(it.x - x) > r + 8) continue;
        fn(it);
      }
    }
  }

  /** 避河 / 避铁路用的占地半径（T034 第 2 批）：按这种景物最大的缩放算（不多抽随机数，摆放顺序不变）；篱墙是 3 段 4 米连成一条 */
  private reach(id: ScnKind): number {
    if (id === 'hedge') return 6.5;
    return this.radiusOf(id, id === 'house' || id === 'ruin' ? 1.2 : 1.5);
  }

  /** 占地的外接半径 */
  radiusOf(kind: ScnKind, s: number): number {
    const m = SCN_META[kind];
    return (m.r ?? Math.hypot(m.hw ?? 1, m.hd ?? 1)) * s;
  }

  /** 主体矩阵：T(原点 + 地面 + 倒点) · 竖直压扁 · 倾斜 · T(−倒点) · 自转 · 缩放 */
  mainMatrix(it: ScnItem, out = this.m): THREE.Matrix4 {
    const flying = it.anim === 'fly' || it.anim === 'roll';
    const bx = flying ? it.ox : it.x;
    const bz = flying ? it.oz : it.z;
    const by = flying ? it.oy : it.y - it.sink;
    this.q.setFromAxisAngle(this.p.set(0, 1, 0), it.rot);
    out.compose(this.p.set(0, 0, 0), this.q, this.s.set(it.s, it.s, it.s));
    if (it.tilt !== 0 || flying) {
      const t = tmpM.makeTranslation(-it.px, 0, -it.pz);
      out.premultiply(t);
      tmpQ.setFromAxisAngle(this.p.set(it.tdz, 0, -it.tdx), it.tilt);
      if (flying && it.roll !== 0) tmpQ.premultiply(tmpQ2.setFromAxisAngle(this.p.set(it.tdx, 0, it.tdz), it.roll));
      out.premultiply(tmpM.makeRotationFromQuaternion(tmpQ));
      out.premultiply(tmpM.makeTranslation(it.px, 0, it.pz));
    }
    if (it.fxz !== undefined && it.fxz !== 1) {
      const c = Math.cos(it.rot), s = Math.sin(it.rot);
      const cx = (HAY_CENTER.x * c + HAY_CENTER.z * s) * it.s, cz = (-HAY_CENTER.x * s + HAY_CENTER.z * c) * it.s;
      out.premultiply(tmpM.makeTranslation(-cx, 0, -cz));
      out.premultiply(tmpM.makeScale(it.fxz, 1, it.fxz));
      out.premultiply(tmpM.makeTranslation(cx, 0, cz));
    }
    const fy = it.crushVisual ?? it.fy;
    if (fy !== 1) out.premultiply(tmpM.makeScale(1, fy, 1));
    out.premultiply(tmpM.makeTranslation(bx, by, bz));
    return out;
  }

  /** 上半截矩阵：原点在断口（离地 uy），沿 (udx, udz) 倒 utilt，滑开 (uox, uoz) */
  topMatrix(it: ScnItem, out = this.m): THREE.Matrix4 {
    this.q.setFromAxisAngle(this.p.set(0, 1, 0), it.rot);
    out.compose(this.p.set(0, 0, 0), this.q, this.s.set(it.s, it.s, it.s));
    tmpQ.setFromAxisAngle(this.p.set(it.udz, 0, -it.udx), it.utilt);
    out.premultiply(tmpM.makeRotationFromQuaternion(tmpQ));
    if (it.ufy !== 1) out.premultiply(tmpM.makeScale(1, it.ufy, 1));
    out.premultiply(tmpM.makeTranslation(it.x + it.uox, it.y + it.uy, it.z + it.uoz));
    return out;
  }

  /** 把条目的当前姿态写进实例 */
  sync(it: ScnItem): void {
    if (this.damage.houses.sync(it)) return;
    if (this.damage.masonry.sync(it)) return;
    if (it.state === 'split') {
      this.damage.syncBoulder(it);
      return;
    }
    if (it.main) it.main.pool.set(it.main, this.mainMatrix(it));
    if (it.top) it.top.pool.set(it.top, this.topMatrix(it));
  }

  /** 换主体实例（破坏变体）；池满返回 false，调用方退化 */
  swapMain(it: ScnItem, variant: string): boolean {
    const pool = this.pool(variant, it.look);
    if (it.main?.pool === pool) return true;
    if (pool.full) return false;
    it.crushVisual = undefined;
    if (it.main) it.main.pool.remove(it.main);
    it.main = pool.add(it, this.mainMatrix(it), it.tint);
    return true;
  }

  /** 换成 / 加一个上半截实例；池满返回 false */
  addTop(it: ScnItem, variant: string): boolean {
    const pool = this.pool(variant, it.look);
    if (pool.full) return false;
    if (it.top) it.top.pool.remove(it.top);
    it.top = pool.add(it, this.topMatrix(it), it.tint);
    return true;
  }

  setTint(it: ScnItem, t: number): void {
    it.tint = t;
    if (it.main) it.main.pool.tint(it.main, t);
    if (it.top) it.top.pool.tint(it.top, t);
  }

  /** 前方多远以内算「在画面里」（T020-a：Game 每帧按画面上沿碰地的距离 + 10 米改，115～175） */
  aheadMax = 115;

  /** 这件景物在不在画面里（不在的直接到终态、不播动画、少放粒子） */
  visible(x: number, z: number): boolean {
    const ahead = this.playerZ - z;
    return ahead > -18 && ahead < this.aheadMax && Math.abs(x - this.playerX) < 26 + Math.max(0, ahead) * 0.12;
  }

  /** 调试：核对每个池的句柄（index 和槽位一致、条目回指）；返回错误数 */
  check(): { errors: number; detail: string[] } {
    const detail: string[] = [];
    for (const [name, pool] of this.pools) {
      if (pool.mesh.count !== pool.slots.length) detail.push(`${name}: count ${pool.mesh.count} ≠ ${pool.slots.length}`);
      pool.slots.forEach((h, i) => {
        if (h.index !== i) detail.push(`${name}[${i}]: index ${h.index}`);
        const it = h.item;
        if (name === 'patch') {
          if (it && !it.patches.includes(h)) detail.push(`patch[${i}]: 条目没有这块贴片`);
        } else if (!it || !it.alive || (it.main !== h && it.top !== h)) detail.push(`${name}[${i}]: 条目不指向它`);
      });
    }
    for (const it of this.items) {
      if (!it.alive) detail.push(`#${it.id}: 不活却在列表里`);
      for (const h of [it.main, it.top, ...it.patches]) if (h && h.pool.slots[h.index] !== h) detail.push(`#${it.id} ${it.kind}: 句柄串号`);
      if (!this.buckets.get(it.bucket)?.includes(it)) detail.push(`#${it.id}: 不在桶里`);
    }
    return { errors: detail.length, detail: detail.slice(0, 12) };
  }

  /** 各池数量（诊断 / 测试基线） */
  counts(): Record<string, number> {
    const out: Record<string, number> = {};
    for (const [name, pool] of this.pools) out[name] = pool.slots.length;
    return out;
  }

  /** 这一帧景物占的绘制次数（数量为 0 的池不出绘制；投影的再算一次阴影） */
  get draws(): number {
    let n = 0;
    for (const p of this.pools.values()) if (p.mesh.count > 0) n += p.mesh.castShadow ? 2 : 1;
    return n + this.debris.draws + this.damage.houses.stats().draws + this.damage.masonry.stats().draws;
  }

  private rnd(): number {
    this.seed = (this.seed * 16807) % 2147483647;
    return this.seed / 2147483647;
  }

  /** 路肩带用自己的随机序列（不影响原来远景的摆法） */
  private srnd(): number {
    this.sideSeed = (this.sideSeed * 16807) % 2147483647;
    return this.sideSeed / 2147483647;
  }
}

const tmpM = new THREE.Matrix4();
const tmpQ = new THREE.Quaternion();
const tmpQ2 = new THREE.Quaternion();
