import type { RouteAct, RoutePage, RouteRow } from './routeBook';

/**
 * 开始界面「作战模式」的三页（T110）：连续作战 / 自选关卡 / 首领挑战。纯函数，Game 把数据整理好给进来，
 * DOM 版（ui/Menu.ts）和画布版（ui/canvas/CanvasMenu.ts）各画一层皮（和局外成长各页同一套）；按钮 id 交给 Game.onAct：
 * mode:run / mode:zone:<区> / mode:boss:<序号> / mode:daily 出发，mode:picks:<次数> 选升级次数
 */
export interface ModeView {
  /** 有存档时出发要点两下：第一下点的那个按钮 id（变「再点出发」），页头换成原局怎么处理 */
  ask: string | null;
  askNote: string;
  /** 三页的页头都换成这一句（?all=1 全解锁试玩，T115）；没有 = 各页自己的 */
  note?: string;
  /** 自选关卡：lock = 没解锁的条件（解锁了 = null） */
  levels?: { zone: number; name: string; boss: string; picks: number; air: boolean; lock: string | null }[];
  /** 首领挑战：选中的升级次数、可选的几档、首领列表、今日任务 */
  boss?: { picks: number; options: readonly number[]; list: { kind: string; code: string; zone: number }[]; daily: DailyView | null };
}

/** 今日任务卡片：首领、词缀（名字 + 一句话）、先选几次升级、今天完成没有、奖励一行 */
export interface DailyView {
  boss: string;
  affixes: { name: string; line: string }[];
  picks: number;
  done: boolean;
  reward: string;
}

/** 有存档时出发按钮的第一下 */
export const GO_ASK = '再点出发';

export function modePages(v: ModeView): RoutePage[] {
  const go = (id: string, label = '出发'): RouteAct => (v.ask === id ? { id, label: GO_ASK, kind: 'warn' } : { id, label, kind: 'gold' });
  const head = (text: string) => (v.ask ? v.askNote : v.note ?? text);
  const pages: RoutePage[] = [
    {
      id: 'mode-run',
      label: '连续作战',
      head: head('军功、军票照常'),
      sections: [{ title: '从第 1 区打起', rows: [{ icon: 'threat', title: '连续作战', tag: '默认', lines: ['一路打到无尽，和「开始作战」一样'], state: 'now', acts: [go('mode:run')] }] }],
    },
  ];
  if (v.levels)
    pages.push({
      id: 'mode-zone',
      label: '自选关卡',
      head: head('从这一关打起，之后照常'),
      sections: [
        {
          title: '解锁了才能选',
          rows: v.levels.map((l): RouteRow => ({
            icon: l.air ? 'airfield' : 'threat',
            title: `区域 ${l.zone} · ${l.name}`,
            tag: l.lock ? '未解锁' : l.picks ? `先选 ${l.picks} 次升级` : '直接开打',
            lines: [l.lock ? `首领：${l.boss} · ${l.lock}` : `首领：${l.boss}`],
            state: l.lock ? 'off' : 'next',
            acts: l.lock ? undefined : [go(`mode:zone:${l.zone}`)],
          })),
        },
      ],
    });
  const b = v.boss;
  if (b) {
    const d = b.daily;
    pages.push({
      id: 'mode-boss',
      label: '首领挑战',
      head: head('练习用，不给军功军票'),
      sections: [
        ...(d
          ? [
              {
                title: '今日任务',
                rows: [
                  {
                    icon: 'tasks',
                    title: `今日 · ${d.boss}`,
                    tag: d.done ? '今日已完成' : `先选 ${d.picks} 次升级`,
                    lines: [...d.affixes.map((a) => `${a.name}：${a.line}`), d.reward],
                    state: d.done ? 'done' : 'now',
                    acts: [go('mode:daily', d.done ? '再打一次' : '出发')],
                  } satisfies RouteRow,
                ],
              },
            ]
          : []),
        {
          title: '自由挑战',
          rows: [{ icon: 'ammo', title: '开打前升级', tag: `${b.picks} 次`, lines: [], state: 'now', acts: b.options.map((n) => ({ id: `mode:picks:${n}`, label: `${n} 次`, kind: n === b.picks ? 'chipOn' : 'chip' })) }],
        },
        {
          title: '直接进首领战',
          cols: 2,
          rows: b.list.map((x, i): RouteRow => ({ icon: 'firecontrol', title: `「${x.code}」`, tag: `区域 ${x.zone}`, lines: [x.kind], state: 'next', acts: [go(`mode:boss:${i}`, '挑战')] })),
        },
      ],
    });
  }
  return pages;
}
