import * as THREE from 'three';
import { groundTexture, grayNoise, roadTexture, terrainNormal, type GroundKind, type RoadKind } from '../render/textures';
import type { Theme } from './themes';
import { CRATER_GLSL, Craters, MAX_CRATERS, type CraterRiver, type CraterUniforms } from './Craters';
import { APPROACH, BRIDGE, RIVER_BEND } from './Rivers';

const RIVER_BEND_INNER = RIVER_BEND.inner;
const RIVER_BEND_OUTER = RIVER_BEND.outer;

export const ROAD_HALF_WIDTH = 13;

/**
 * 河道网格（T034）：每条河一条顺着河弯的条带，横向行距集中在岸坡上——行参数 q（带符号，0 = 河心）：|q| ≤ QA 是水下（0 → 半宽），
 * QA → 1 是岸坡（水边线 → 坡顶），1 → QX 再往外多盖 OVER 米（和平地网格重叠一点，接缝不漏）；纵向（顺河）路面附近 1.5 米一列，越往两边越稀
 */
const CHAN = { QA: 0.4, QX: 1.12, OVER: 0.6, rows: [0.08, 0.16, 0.24, 0.32, 0.4, 0.475, 0.55, 0.625, 0.7, 0.775, 0.85, 0.925, 1, 1.12] };

const PARS = /* glsl */ `
uniform sampler2D uGroundA;
uniform sampler2D uGroundB;
uniform sampler2D uRoadA;
uniform sampler2D uRoadB;
uniform sampler2D uNoise;
uniform float uKindA;
uniform float uKindB;
uniform float uGKindA;
uniform float uGKindB;
uniform float uBoundary;
uniform float uRoadHalf;
uniform float uCrMesh;
uniform vec2 uRunway;
varying vec2 vWorldXZ;
float terrainRough;
// 沙漠的沙垄（T125）：这一点高度对世界 x / z 的坡度（MAP 里算，法线那一段拿去把法线掰过去）
vec2 duneG;
// 这里的路面半宽（T034 桥头收窄：路缘石 / 积水跟着收）
float rHalf;
${CRATER_GLSL}

vec3 roadSample(sampler2D tex, float kind, vec2 wp, float macro, inout float rough) {
  vec3 c = texture2D(tex, wp / 10.0).rgb;
  float ax = abs(wp.x);
  float n = texture2D(uNoise, wp * 0.018).r;
  if (kind < 0.5) {
    // 泥路：两道深车辙 + 成片积水，泥浆发亮
    float rut = (1.0 - smoothstep(0.0, 1.1, abs(ax - 3.3))) + (1.0 - smoothstep(0.0, 1.1, abs(ax - 8.6)));
    c *= 1.0 - rut * 0.32;
    float puddle = smoothstep(0.64, 0.68, n + rut * 0.06) * (1.0 - smoothstep(rHalf - 3.0, rHalf - 0.5, ax));
    // 积水倒映天光：偏灰蓝、很光滑
    c = mix(c, mix(c * 0.5, vec3(0.13, 0.14, 0.14), 0.3), puddle);
    rough = mix(mix(0.78, 0.6, rut), 0.12, puddle);
  } else if (kind < 1.5) {
    // 土路：浅车辙，路中间长草
    float rut = (1.0 - smoothstep(0.0, 0.9, abs(ax - 3.4))) + (1.0 - smoothstep(0.0, 0.9, abs(ax - 8.8))) * 0.7;
    c *= 1.0 - rut * 0.2;
    float grass = smoothstep(0.55, 0.75, texture2D(uNoise, wp * 0.09).g) * (1.0 - smoothstep(1.0, 2.0, abs(ax - 6.1)));
    c = mix(c, vec3(0.2, 0.24, 0.12), grass * 0.5);
    float puddle = smoothstep(0.72, 0.75, n) * (1.0 - smoothstep(rHalf - 3.0, rHalf - 1.0, ax));
    c = mix(c, mix(c * 0.5, vec3(0.13, 0.14, 0.14), 0.3), puddle);
    rough = mix(0.95, 0.12, puddle);
    c *= 1.12;
  } else if (kind < 2.5) {
    // 石子路：两侧路缘石
    float curb = 1.0 - smoothstep(0.25, 0.4, abs(ax - (rHalf - 0.6)));
    c = mix(c, vec3(0.42, 0.4, 0.37), curb * 0.8);
    rough = 0.82;
  } else if (kind < 3.5) {
    // 水泥板路（T019-a 钢铁厂区）：路缘一道浅色水泥边，偶尔一片油渍积水发亮
    float curb = 1.0 - smoothstep(0.2, 0.35, abs(ax - (rHalf - 0.5)));
    c = mix(c, vec3(0.5, 0.49, 0.46), curb * 0.7);
    float oil = smoothstep(0.7, 0.74, n) * (1.0 - smoothstep(rHalf - 3.0, rHalf - 1.0, ax));
    c = mix(c, c * 0.45, oil);
    rough = mix(0.86, 0.2, oil);
  } else if (kind > 4.5) {
    // 砾石古道（T122 区域 6）：碎石面 + 两道车辙 + 一片片半埋的旧石板（2.4 × 1.7 米一块，缝里塞着沙，越靠路肩越少）；沙吃进路肩在 MAP 里画
    float rut = (1.0 - smoothstep(0.0, 1.0, abs(ax - 3.6))) + (1.0 - smoothstep(0.0, 1.0, abs(ax - 8.4))) * 0.8;
    c *= 1.0 - rut * 0.16;
    vec2 sg = wp / vec2(2.4, 1.7);
    vec2 sf = fract(sg);
    float sh = texture2D(uNoise, (floor(sg) + 0.5) / 97.0).r;
    float buried = texture2D(uNoise, wp * 0.035 + 0.37).g;
    // T125：石板少一半、缝浅一点、石面浅一点、上面盖一层薄沙（原来一片片深色方格 + 黑缝，在浅沙上像开裂的土块）
    float slab = step(0.6, sh) * smoothstep(0.5, 0.64, buried) * (1.0 - smoothstep(rHalf - 5.5, rHalf - 2.5, ax));
    float seam = 1.0 - smoothstep(0.03, 0.1, min(min(sf.x, 1.0 - sf.x), min(sf.y, 1.0 - sf.y)));
    vec3 stoneC = vec3(0.36, 0.32, 0.25) * (0.8 + 0.4 * sh);
    c = mix(c, stoneC, slab * 0.7);
    c = mix(c, c * 0.72, slab * seam * 0.7);
    rough = mix(0.95, 0.78, slab);
  } else {
    // 机场水泥板（T093 区域 5）：滑行道 = 路中一道黄色滑行线 + 两侧黄边线；跑道段（uRunway：z 从 x 到 y）= 白色中线虚线 + 白边线 + 黑色胎痕 + 两头一排白色斑马线
    float rw = step(uRunway.y, wp.y) * step(wp.y, uRunway.x);
    float taxi = 1.0 - smoothstep(0.14, 0.22, ax);
    float lane = 1.0 - smoothstep(0.1, 0.18, abs(ax - (rHalf - 1.4)));
    c = mix(c, vec3(0.5, 0.33, 0.05), max(taxi, lane * 0.85) * (1.0 - rw));
    float center = (1.0 - smoothstep(0.3, 0.42, ax)) * step(fract(wp.y / 24.0), 0.55);
    float edgeL = 1.0 - smoothstep(0.22, 0.32, abs(ax - (rHalf - 1.2)));
    float into = uRunway.x - wp.y;
    float outo = wp.y - uRunway.y;
    float zebra = max(step(3.0, into) * step(into, 21.0), step(3.0, outo) * step(outo, 21.0)) * step(1.6, ax) * step(ax, rHalf - 2.4) * step(fract((ax - 1.6) / 1.5), 0.55);
    float tire = smoothstep(0.62, 0.8, texture2D(uNoise, vec2(wp.x * 0.35, wp.y * 0.012)).r) * (1.0 - smoothstep(1.0, 3.5, abs(ax - 3.5)));
    vec3 rc = mix(c, c * 0.4, tire * 0.65);
    rc = mix(rc, vec3(0.62, 0.62, 0.6), max(max(center, edgeL), zebra));
    c = mix(c, rc, rw);
    float oil = smoothstep(0.72, 0.75, n) * (1.0 - smoothstep(rHalf - 3.0, rHalf - 1.0, ax));
    c = mix(c, c * 0.55, oil);
    rough = mix(0.88, 0.3, oil);
  }
  return c * (0.9 + macro * 0.2);
}

// T195 原野（制作人「草地的贴图太规律了……做成欧洲乡下那种杂草或者麦田的感觉」）：哈希不用 sin；高频采样先按 256 米取模（频率都是 1/256 的整数倍，接缝处图案连续）
float fH(vec2 p) { vec3 q = fract(vec3(p.xyx) * 0.1031); q += dot(q, q.yzx + 33.33); return fract((q.x + q.y) * q.z); }
vec2 fH2(vec2 p) { vec3 q = fract(vec3(p.xyx) * vec3(0.1031, 0.103, 0.0973)); q += dot(q, q.yzx + 33.33); return fract((q.xx + q.yz) * q.zy); }
// 同一张地面贴图两种尺度、错开角度各采一次，按大块噪声混：不再 16 米一格重复
vec3 groundTiled(sampler2D tex, vec2 wp) {
  vec2 r = vec2(wp.x * 0.8 - wp.y * 0.6, wp.x * 0.6 + wp.y * 0.8);
  float k = smoothstep(0.38, 0.62, texture2D(uNoise, wp * 0.011 + 0.21).g);
  return mix(texture2D(tex, wp / 16.0).rgb, texture2D(tex, r / 21.0 + 0.37).rgb, k);
}
/**
 * 乡间田块：路边 6～10 米外按 46 × 38 米的扰动格子分成一块块田（Voronoi），每块随机一种——杂草地（野花、枯草斑、顺风倒伏的草纹）、
 * 熟麦田 / 青麦田（各自方向的垄沟，麦田边上零星虞美人）、割过的草茬地（一道道晒草垄）、翻耕地；田与田之间一道深色的田埂草带。
 * 垄 / 草纹 / 花按屏幕上一个像素多大淡出（远处不闪）
 */
vec3 fieldGround(vec2 wp, float ax, float edge) {
  vec2 wq = mod(wp, 256.0);
  float px = max(fwidth(wp.x), fwidth(wp.y));
  // 草丛的几层尺度：4 米大片、1 米 / 0.5 米 / 0.25 米一簇一簇（细的那几层远处淡掉，不闪）
  float n1 = texture2D(uNoise, wq * 0.03125).g;
  float c1 = texture2D(uNoise, wq * 0.03125 + 0.37).b;
  float c2 = texture2D(uNoise, wq * 0.0625 + 0.71).b;
  float c3 = texture2D(uNoise, wq * 0.125 + 0.5).b;
  float near = 1.0 - smoothstep(0.04, 0.16, px);
  float tuft = mix(0.5, c1 * 0.5 + c2 * 0.3 + c3 * 0.2, 0.55 + 0.45 * near);
  float dry = smoothstep(0.5, 0.8, texture2D(uNoise, wq * 0.0625 + 0.3).r + (c2 - 0.5) * 0.35);
  float comb = texture2D(uNoise, vec2(wq.x * 0.25, wq.y * 0.0625)).b;
  // 田块
  const vec2 CELL = vec2(46.0, 38.0);
  vec2 wj = wp + (vec2(texture2D(uNoise, wq * 0.0078125).r, texture2D(uNoise, wq * 0.0078125 + 0.5).g) - 0.5) * 14.0;
  vec2 g = wj / CELL, ip = floor(g), fp = fract(g);
  float d1 = 1e9, d2 = 1e9;
  vec2 id = vec2(0.0);
  for (int j = -1; j <= 1; j++) for (int i = -1; i <= 1; i++) {
    vec2 o = vec2(float(i), float(j));
    vec2 c = mod(ip + o, 512.0);
    vec2 r = (o + 0.18 + 0.64 * fH2(c) - fp) * CELL;
    float d = dot(r, r);
    if (d < d1) { d2 = d1; d1 = d; id = c; } else if (d < d2) d2 = d;
  }
  float border = (sqrt(d2) - sqrt(d1)) * 0.5;
  float kind = fH(id + 7.3);
  float ang = fH(id + 1.7) * 3.14159;
  vec2 dir = vec2(cos(ang), sin(ang));
  float s = dot(wp, vec2(-dir.y, dir.x)) + n1 * 0.9;
  float rowAA = 1.0 - smoothstep(0.12, 0.35, px / 0.8);
  float rows = (0.5 + 0.5 * cos(s * 7.854)) * rowAA;
  // 路边一圈总是杂草地，往外才分田
  float farm = smoothstep(edge + 6.0, edge + 11.0, ax);
  // 杂草地：橄榄绿底，一簇簇深浅不一，夹着枯黄的草、深色的三叶草和顺风倒伏的亮纹
  vec3 meadow = mix(vec3(0.045, 0.062, 0.022), vec3(0.11, 0.13, 0.045), smoothstep(0.25, 0.75, tuft));
  meadow = mix(meadow, vec3(0.19, 0.165, 0.07) * (0.8 + 0.4 * c2), dry * 0.6);
  meadow *= 0.88 + 0.24 * n1;
  meadow *= 1.0 + 0.22 * (comb - 0.5) * near;
  vec3 c = meadow;
  float flowerK = 1.0;
  if (farm > 0.0) {
    vec3 f;
    if (kind < 0.3) f = meadow;
    else if (kind < 0.55) {
      // 熟麦：赭金色，麦穗一簇簇深浅，垄间暗一点，风吹出大片明暗，夹几簇绿杂草
      f = mix(vec3(0.24, 0.165, 0.055), vec3(0.36, 0.26, 0.085), smoothstep(0.2, 0.8, tuft * 0.6 + n1 * 0.4));
      f *= 0.84 + 0.2 * rows;
      f = mix(f, f * 0.72, smoothstep(0.62, 0.9, texture2D(uNoise, wq * 0.0625 + 0.7).g) * 0.6);
      f = mix(f, vec3(0.08, 0.1, 0.03), smoothstep(0.78, 0.92, c2) * 0.6 * near);
      flowerK = 0.0;
    } else if (kind < 0.72) {
      // 青麦：嫩绿成行，行间露一点土
      f = mix(vec3(0.07, 0.11, 0.025), vec3(0.12, 0.16, 0.04), smoothstep(0.2, 0.8, tuft));
      f = mix(f, vec3(0.075, 0.055, 0.033), (1.0 - rows) * 0.5 * rowAA);
      flowerK = 0.0;
    } else if (kind < 0.86) {
      // 割过的草茬地：浅黄绿，一道道晒草垄
      float wind = smoothstep(0.8, 0.96, 0.5 + 0.5 * cos(s * 0.785 + n1 * 2.0)) * (1.0 - smoothstep(0.3, 0.8, px / 4.0));
      f = mix(vec3(0.15, 0.14, 0.055), vec3(0.22, 0.2, 0.08), smoothstep(0.2, 0.8, tuft)) * (0.9 + 0.12 * rows);
      f = mix(f, vec3(0.26, 0.21, 0.07) * (0.85 + 0.3 * c3), wind * 0.85);
      flowerK = 0.25;
    } else {
      // 翻耕地：深褐垄沟，土块深浅
      f = mix(vec3(0.06, 0.042, 0.026), vec3(0.1, 0.07, 0.042), smoothstep(0.2, 0.8, tuft)) * (0.7 + 0.42 * rows);
      flowerK = 0.0;
    }
    // 田埂：一道窄的深色乱草
    float bank = 1.0 - smoothstep(0.35, 1.3, border + (c1 - 0.5) * 0.7);
    f = mix(f, mix(vec3(0.04, 0.055, 0.02), meadow, 0.5), bank);
    c = mix(meadow, f, farm);
    flowerK = mix(1.0, max(flowerK, bank), farm);
    // 麦田边上的虞美人
    if (kind >= 0.3 && kind < 0.55) flowerK = max(flowerK, (1.0 - smoothstep(1.5, 4.0, border)) * 0.6 * farm);
  }
  // 野花：0.5 米一格，成片出现；黄（毛茛）/ 白（雏菊）/ 红（虞美人，麦田边多）/ 淡紫
  vec2 fc = floor(wq / 0.5);
  vec2 fr = fract(wq / 0.5) - 0.5 - (fH2(fc + 3.1) - 0.5) * 0.6;
  float drift = smoothstep(0.45, 0.75, texture2D(uNoise, wq * 0.0390625 + 0.9).r);
  float fl = step(1.0 - 0.07 * drift * flowerK, fH(fc)) * (1.0 - smoothstep(0.08, 0.14, length(fr))) * (1.0 - smoothstep(0.06, 0.12, px));
  float hue = fH(fc + 11.0);
  vec3 fcol = hue < 0.45 ? vec3(0.55, 0.42, 0.04) : hue < 0.75 ? vec3(0.55, 0.55, 0.48) : hue < 0.9 ? vec3(0.42, 0.035, 0.02) : vec3(0.26, 0.18, 0.38);
  return mix(c, fcol, fl * 0.8);
}
`;

const MAP = /* glsl */ `
vec2 wp = vWorldXZ;
// 河道带（T034）：先算离每条河的水边线 rD / 坡顶 rT 多远（chan = 离最近的坡顶，负 = 在河道里）。河道带里的地面由河道网格画：
// 平地网格整片挖掉、弹坑网格在河道深处挖掉（河道网格的高度里已经叠了弹坑），挖掉的像素不再往下算
float chan = 1000.0;
float rD[3];
float rT[3];
// 河道在路面上是直的、田野里最多弯开 25 米：离河心超过「半宽 + 坡顶 + 3 米 + 这里最多弯开多少」就不用细算
float reach = 10.0 + 25.0 * smoothstep(${RIVER_BEND_INNER.toFixed(1)}, ${RIVER_BEND_OUTER.toFixed(1)}, abs(wp.x));
for (int i = 0; i < 3; i++) {
  rD[i] = 1000.0;
  rT[i] = 0.0;
  vec4 rv = uCrRv[i];
  if (rv.y <= 0.0 || abs(wp.y - rv.x) > rv.y + reach) continue;
  float dz = wp.y - rv.x - crRiverBend(wp.x, rv.z, rv.w);
  rD[i] = abs(dz) - rv.y;
  rT[i] = riverBankW(wp.x, dz < 0.0 ? -1.0 : 1.0, rv.z, uCrRk[i].x > 0.0 ? 0.0 : 1.0);
  chan = min(chan, rD[i] - rT[i]);
}
if (uCrMesh < 0.5 ? chan < 0.0 : (uCrMesh < 1.5 && chan < -${CHAN.OVER.toFixed(2)})) discard;
float macro = texture2D(uNoise, wp * 0.0045).r;
// 1 = 旧主题（玩家这一侧，z 更大），0 = 新主题
float side = smoothstep(uBoundary - 12.0, uBoundary + 12.0, wp.y);
float wob = texture2D(uNoise, vec2(wp.y * 0.012, 0.31)).g;
// 泥路 / 土路边缘弯弯曲曲，石子路笔直；砾石古道（T122）两边被沙吃进来，也是弯的
float ampA = uKindA < 0.5 ? 3.4 : (uKindA < 1.5 || uKindA > 4.5 ? 2.6 : 0.3);
float ampB = uKindB < 0.5 ? 3.4 : (uKindB < 1.5 || uKindB > 4.5 ? 2.6 : 0.3);
// 沙漠（T122）：1 = 这一侧是砾石古道
float sandK = mix(step(4.5, uKindB), step(4.5, uKindA), side);
// 桥头收窄（T034 第 2 批）：有桥的河，路面在桥头坡道外 ${APPROACH.funnel} 米里从原宽收到桥面宽（路缘、路肩、草沿跟着收），和 Rivers.roadHalfAt 同一个公式；平板桥比路宽，不收
rHalf = uRoadHalf;
for (int i = 0; i < 3; i++) {
  vec4 rk = uCrRk[i];
  if (rk.x <= 0.0 || rk.x > uRoadHalf) continue;
  float a = abs(wp.y - uCrRv[i].x) - rk.y - ${BRIDGE.ramp.toFixed(1)};
  if (a < ${APPROACH.funnel.toFixed(1)}) rHalf = min(rHalf, rk.x - 0.2 + (uRoadHalf - rk.x + 0.2) * smoothstep(0.0, ${APPROACH.funnel.toFixed(1)}, a));
}
float edge = rHalf + (wob - 0.5) * mix(ampB, ampA, side) * (rHalf / uRoadHalf);
float ax = abs(wp.x);
float soft = mix(uKindB < 1.5 || uKindB > 4.5 ? 1.6 : 0.3, uKindA < 1.5 || uKindA > 4.5 ? 1.6 : 0.3, side);
float roadMask = 1.0 - smoothstep(edge - soft, edge + soft, ax);
// 沙吃进路肩 2～4 米、路面上零星几片薄沙（T122；T125 吃进来的多一点、路面上的沙片多一点）
if (sandK > 0.0) {
  float drift = smoothstep(edge - 4.5, edge - 0.6, ax) * (0.55 + 0.45 * wob) + smoothstep(0.54, 0.74, texture2D(uNoise, wp * 0.022 + 0.5).r) * 0.65;
  roadMask *= 1.0 - clamp(drift, 0.0, 0.9) * sandK;
}
float rA = 1.0;
float rB = 1.0;
vec3 roadC = mix(roadSample(uRoadB, uKindB, wp, macro, rB), roadSample(uRoadA, uKindA, wp, macro, rA), side);
// 地面（T195）：田野主题按田块画，林地主题错开两种尺度采样；其余主题照原贴图（只算这一侧用得到的那套）
vec3 gA = side > 0.001 ? (uGKindA < 0.5 ? fieldGround(wp, ax, edge) : uGKindA < 1.5 ? groundTiled(uGroundA, wp) : texture2D(uGroundA, wp / 16.0).rgb) : vec3(0.0);
vec3 gB = side < 0.999 ? (uGKindB < 0.5 ? fieldGround(wp, ax, edge) : uGKindB < 1.5 ? groundTiled(uGroundB, wp) : texture2D(uGroundB, wp / 16.0).rgb) : vec3(0.0);
vec3 groundC = mix(gB, gA, side);
groundC *= 0.86 + macro * 0.28;
duneG = vec2(0.0);
// 沙漠（T125）：风从左边略偏后吹来（W = 顺风，太阳在左后方，背风坡背着太阳；和沙丘 OIL.dune.rot、沙地贴图的沙纹同一个风向）。①风蚀拖痕：顺风拉长的深浅条纹；
// ②沙垄：横着风向一道道缓坡（脊线差不多顺着路，从车后看得到背光坡），间距约 16 米、迎风坡缓（七成）背风坡陡、高低不一，脊线被两道正弦扭弯——只掰法线（地面网格是平的），
// 迎光坡亮、背光坡暗，跟着太阳走；远处纹路挤成一团就淡掉（不闪）。路面上不画
if (sandK > 0.0) {
  const vec2 W = vec2(0.97, -0.243);
  vec2 Pw = vec2(-W.y, W.x);
  float along = dot(wp, W);
  float across = dot(wp, Pw);
  float off = (1.0 - roadMask) * sandK;
  float streak = texture2D(uNoise, vec2(along * 0.0045, across * 0.05)).g;
  groundC *= 1.0 + (streak - 0.5) * 0.16 * off;
  float s1 = across * 0.045 + 0.9 * sin(along * 0.011);
  float s2 = across * 0.13 + along * 0.017;
  float ph = along / 16.0 + 0.8 * sin(s1) + 0.2 * sin(s2);
  float dA = 1.0 / 16.0 + 0.8 * cos(s1) * 0.9 * cos(along * 0.011) * 0.011 + 0.2 * cos(s2) * 0.017;
  float dC = 0.8 * cos(s1) * 0.045 + 0.2 * cos(s2) * 0.13;
  float f = fract(ph);
  const float C = 0.72;
  float pf = f < C ? f / C : 0.5 + 0.5 * cos(3.14159 * (f - C) / (1.0 - C));
  float dp = f < C ? 1.0 / C : -1.5708 / (1.0 - C) * sin(3.14159 * (f - C) / (1.0 - C));
  float amp = 0.75 * (0.3 + 0.7 * smoothstep(0.3, 0.7, texture2D(uNoise, wp * 0.007 + 0.3).g)) * off * (1.0 - smoothstep(0.12, 0.35, fwidth(ph)));
  duneG = amp * dp * (dA * W + dC * Pw);
  // 脊上细沙亮一点、沟里粗沙暗一点
  groundC *= 1.0 + (pf - 0.5) * 0.06 * amp;
}
// 路肩：被车压出来的泥边，外面一圈长得更茂的草
float shoulder = (1.0 - smoothstep(edge, edge + 3.0, ax)) * (1.0 - roadMask);
groundC = mix(groundC, roadC * 0.9, shoulder * 0.35);
float verge = (1.0 - smoothstep(edge + 2.0, edge + 6.0, ax)) * smoothstep(edge + 0.5, edge + 2.0, ax);
groundC = mix(groundC, groundC * mix(vec3(0.8, 0.95, 0.7), vec3(0.96, 0.95, 0.92), sandK), verge * 0.5);
vec3 terrainCol = mix(groundC, roadC, roadMask);
terrainRough = mix(0.97, mix(rB, rA, side), roadMask);
// 河道（T034）：河床真的下沉（几何在河道网格里），这里上色——坡顶一圈 → 岸坡 → 水边湿泥 / 一道浅沙 → 水下河床（水面由单独的网格画）。
// 岸按路面类型分三种：泥路 / 土路 = 土岸（坡顶茂草、裸土坡上顺坡的冲沟），石子路 = 石砌护坡，水泥板路 = 混凝土护坡（板缝、锈水痕、水边青苔）
float wStone = mix(step(1.5, uKindB) * step(uKindB, 2.5), step(1.5, uKindA) * step(uKindA, 2.5), side);
float wConc = mix(step(2.5, uKindB), step(2.5, uKindA), side);
float wSoil = 1.0 - wStone - wConc;
for (int i = 0; i < 3; i++) {
  float d = rD[i];
  float T = rT[i];
  if (chan > 3.0 || d > T + 3.0) continue;
  vec4 rv = uCrRv[i];
  vec4 rk = uCrRk[i];
  float t = clamp(d / T, 0.0, 1.0);
  float h = riverProfile(d, T, rk.z, rk.w, riverUnder(rv.y, rk.z, rk.w));
  float n1 = texture2D(uNoise, vec2(wp.x * 0.33, d * 0.09)).r;
  float n2 = texture2D(uNoise, wp * 0.21).g;
  float n3 = texture2D(uNoise, wp * 0.9).r;
  float deep = clamp(-d / 3.0, 0.0, 1.0);
  float wet = 1.0 - smoothstep(0.0, 0.7 + 0.4 * n2, d);
  // 水下河床：卵石 / 淤泥，越深越暗（颜色都是线性空间的值）
  vec3 bedC = mix(vec3(0.07, 0.06, 0.04), vec3(0.12, 0.1, 0.07), smoothstep(0.5, 0.8, n3)) * (1.0 - 0.45 * deep);
  // 土岸：裸土坡（顺坡的冲沟）+ 上半截零星草皮；水边湿泥 + 一道湿沙
  vec3 soil = vec3(0.12, 0.085, 0.05) * (0.75 + 0.5 * n1);
  soil = mix(soil, groundC * 0.75, smoothstep(0.62, 0.95, t + (n2 - 0.5) * 0.5) * 0.85);
  soil = mix(soil, vec3(0.045, 0.035, 0.022), wet * 0.85);
  float sand = (1.0 - smoothstep(0.08, 0.3, abs(d - 0.12 - 0.15 * n2))) * (0.5 + 0.5 * smoothstep(0.3, 0.6, n1));
  soil = mix(soil, vec3(0.17, 0.14, 0.09) * (0.85 + 0.3 * n3), sand * 0.6);
  // 石砌护坡：石块纹理顺着岸铺，水边一圈青苔，坡顶一道压顶石
  float cope = smoothstep(T - 0.55, T - 0.45, d) * (1.0 - smoothstep(T - 0.05, T + 0.05, d));
  vec3 stone = vec3(0.0);
  if (wStone > 0.0) {
    vec2 suv = vec2(wp.x, d * 1.3) / 6.0;
    stone = mix(texture2D(uRoadB, suv).rgb, texture2D(uRoadA, suv).rgb, side) * vec3(0.8, 0.78, 0.74) * (0.85 + 0.3 * n2);
    stone = mix(stone, vec3(0.03, 0.045, 0.02), (1.0 - smoothstep(0.0, 0.7 + 0.4 * n1, d)) * 0.7);
    stone = mix(stone, vec3(0.24, 0.23, 0.2) * (0.9 + 0.2 * n3), cope);
  }
  // 混凝土护坡：顺河每 4 米一道板缝、顺坡每 1.2 米一道横缝，往下淌的锈水痕，水边青苔，坡顶压顶
  vec3 conc = vec3(0.0);
  if (wConc > 0.0) {
    float jx = fract(wp.x / 4.0);
    float jd = fract(d / 1.2 + 0.5);
    float joint = max(1.0 - smoothstep(0.0, 0.03, min(jx, 1.0 - jx)), 1.0 - smoothstep(0.0, 0.04, min(jd, 1.0 - jd)));
    conc = vec3(0.19, 0.185, 0.165) * (0.86 + 0.28 * n2);
    conc = mix(conc, vec3(0.11, 0.07, 0.04), smoothstep(0.55, 0.8, texture2D(uNoise, vec2(wp.x * 0.6, d * 0.04)).g) * 0.55);
    conc *= 1.0 - 0.5 * joint * step(0.0, d);
    conc = mix(conc, vec3(0.03, 0.04, 0.02), (1.0 - smoothstep(0.0, 0.6 + 0.3 * n1, d)) * 0.85);
    conc = mix(conc, vec3(0.3, 0.29, 0.26) * (0.92 + 0.16 * n3), cope);
  }
  vec3 bank = soil * wSoil + stone * wStone + conc * wConc;
  bank = d < 0.0 ? mix(bank, bedC * mix(1.0, 0.7, wConc), smoothstep(0.0, 0.7, -d)) : bank;
  // 浅滩的路面 = 过水路面：路面顺着缓坡铺下去，铺成碎石 / 石板（村镇用石块、厂区用水泥），越往下越湿、水下发暗；桥下没有路面
  float rm = rk.x > 0.0 ? 0.0 : roadMask;
  vec3 chanCol = bank;
  if (rm > 0.0) {
    vec3 gravel = mix(vec3(0.1, 0.09, 0.07), vec3(0.17, 0.155, 0.12), smoothstep(0.45, 0.75, n3)) * (0.85 + 0.3 * n2);
    vec3 pave = gravel * wSoil + vec3(0.2, 0.195, 0.18) * (0.88 + 0.24 * n2) * wConc;
    if (wStone > 0.0) pave += mix(texture2D(uRoadB, wp / 8.0).rgb, texture2D(uRoadA, wp / 8.0).rgb, side) * wStone;
    pave = mix(roadC, pave, (1.0 - smoothstep(0.2, 0.85, t + (n2 - 0.5) * 0.3)) * 0.7) * mix(1.0, 0.5, 1.0 - smoothstep(-0.3, 0.8, d));
    chanCol = mix(bank, pave, rm);
  }
  // 往下越深越暗：岸坡上越靠近水越背光（站在河道里的感觉）
  chanCol *= 1.0 - mix(0.4, 0.25, rm) * clamp(-h / rk.z, 0.0, 1.0) * step(0.0, d);
  float inside = 1.0 - smoothstep(T - 0.15, T + 0.15, d);
  terrainCol = mix(terrainCol, chanCol, inside);
  terrainRough = mix(terrainRough, d < 0.0 ? 0.85 : mix(0.95, 0.5, wet), inside);
  // 坡顶：土岸一道亮草沿（外面一圈长得更茂的草），沿下一道背光的阴影
  float lip = (1.0 - smoothstep(T, T + 2.5, d)) * smoothstep(T - 0.4, T + 0.1, d) * wSoil * (1.0 - rm);
  terrainCol = mix(terrainCol, terrainCol * vec3(0.78, 0.98, 0.66), lip * 0.55);
  terrainCol = mix(terrainCol, groundC * vec3(1.08, 1.12, 0.86), (1.0 - smoothstep(0.0, 0.3, abs(d - T + 0.2))) * 0.6 * wSoil * (1.0 - rm));
  terrainCol *= 1.0 - 0.25 * (1.0 - smoothstep(0.0, 0.9, abs(d - T + 1.1))) * (1.0 - rm * 0.6);
}
// 河道截断（T025）：坑里的新土 / 焦黑在河道里跟着淡掉（坑的高度在 craterH 里已经乘过）
float crRm = uCrN > 0 ? craterRiverMask(wp) : 1.0;
// 实体弹坑（T014-3）：地面网格在坑的圆盘里挖掉（坑由单独的下陷网格画）；坑里翻出来的新土、越往中心烧得越黑（核弹坑底烧成发亮的玻璃质黑土），
// 坑壁一道道往下淌的烟熏痕；坑口一圈刚翻出来的浅色新土，坑外放射状抛土 + 焦痕，到圆盘边上正好淡没（和外面的地面接得上）
for (int i = 0; i < ${MAX_CRATERS}; i++) {
  if (i >= uCrN) break;
  vec4 ca = uCrA[i];
  vec4 cb = uCrB[i];
  if (uCrMesh < 0.5 && length(wp - ca.xy) < cb.y * 1.15) discard;
  float cq;
  float cang;
  craterOne(wp, i, cq, cang);
  float qo = cb.y * 1.15 / ca.z;
  // 压平成印记的坑（T016-1）：深度压到 0 的过程中新土的颜色跟着淡掉，最后只剩弹坑贴花
  float fresh = clamp(ca.w / 0.06, 0.0, 1.0) * crRm;
  if (cq < 1.0) {
    float n = texture2D(uNoise, wp * 0.06).r;
    float n2 = texture2D(uNoise, wp * 0.21).g;
    terrainCol = mix(terrainCol, vec3(0.19, 0.155, 0.12) * (0.75 + n * 0.5), 0.85 * fresh);
    // 烟熏痕：噪声按极坐标采样（角度方向绕 3 个周期首尾相接、半径方向拉长），一道道顺着坑壁往下；
    // 梯度按世界坐标给（atan 在 ±π 处跳变，自动算的 mip 会在那里画出一条缝）
    float streak = textureGrad(uNoise, vec2(cang * 0.4774648, cq * 0.3 + cb.z), dFdx(wp) * 0.03, dFdy(wp) * 0.03).g;
    float soot = smoothstep(0.45, 0.7, streak + (n2 - 0.5) * 0.25) * smoothstep(0.25, 0.6, cq) * (1.0 - smoothstep(0.85, 1.0, cq));
    float burnt = (0.13 + 0.6 * cq * cq) * (0.85 + n2 * 0.3) * (1.0 - soot * 0.35);
    terrainCol *= mix(1.0, burnt, cb.w * crRm);
    // 坑底中心：烧熔的玻璃质黑土，略微发亮（只有烧得最狠的核弹坑）
    float glass = (1.0 - smoothstep(0.15, 0.4, cq)) * smoothstep(0.85, 1.0, cb.w);
    terrainCol = mix(terrainCol, vec3(0.05, 0.055, 0.045), glass * 0.6 * crRm);
    terrainRough = mix(0.96, 0.45, glass * smoothstep(0.4, 0.7, n2));
  } else if (cq < qo) {
    float n = texture2D(uNoise, wp * 0.045).r;
    float rays = smoothstep(0.45, 0.95, 0.5 + 0.5 * sin(cang * 23.0 + cb.z * 5.0) + (n - 0.5) * 0.9);
    float fall = 1.0 - smoothstep(1.0, qo * 0.97, cq);
    float lip = 1.0 - smoothstep(1.0, 1.25, cq);
    terrainCol = mix(terrainCol, vec3(0.23, 0.19, 0.15) * (0.8 + n * 0.4), (fall * (0.5 + 0.4 * rays) + lip * 0.2) * fresh);
    terrainCol *= 1.0 - cb.w * crRm * fall * (0.2 + 0.5 * rays) * (1.0 - lip * 0.7);
  }
}
diffuseColor.rgb *= terrainCol;
`;

/** 弹坑网格的顶点：极坐标圆盘按地面高度（弹坑 + 河道下沉，groundH）下陷，法线用高度场的梯度（模型矩阵是单位阵，位置就是世界坐标） */
const CRATER_VERT = /* glsl */ `
vec2 crXZ = iCrater.xy + position.xz * iCrater.z;
const float crE = 0.35;
float crHx = groundH(crXZ + vec2(crE, 0.0)) - groundH(crXZ - vec2(crE, 0.0));
float crHz = groundH(crXZ + vec2(0.0, crE)) - groundH(crXZ - vec2(0.0, crE));
vec3 objectNormal = normalize(vec3(-crHx / (2.0 * crE), 1.0, -crHz / (2.0 * crE)));
float crH0 = groundH(crXZ);
#ifdef USE_TANGENT
vec3 objectTangent = vec3(1.0, 0.0, 0.0);
#endif
`;

/**
 * 河道网格的顶点（T034）：position.x = 顺河的 x，position.z = 行参数 q（见 CHAN）；按这条河（实例属性 iRv = 河心 z, 半宽, 相位, 振幅倍率（取负 = 浅滩，路面那一段是缓坡））弯过去、
 * 横向按 q 摆到水下 / 岸坡 / 坡顶外，高度 = groundH（河道下沉 + 弹坑），法线用高度场梯度
 */
const CHAN_VERT = /* glsl */ `
float chQ = abs(position.z);
float chSd = position.z < 0.0 ? -1.0 : 1.0;
float chT = riverBankW(position.x, chSd, iRv.z, iRv.w < 0.0 ? 1.0 : 0.0);
float chDz = chQ <= ${CHAN.QA.toFixed(3)} ? chQ / ${CHAN.QA.toFixed(3)} * iRv.y
  : (chQ <= 1.0 ? iRv.y + (chQ - ${CHAN.QA.toFixed(3)}) / ${(1 - CHAN.QA).toFixed(3)} * chT : iRv.y + chT + (chQ - 1.0) / ${(CHAN.QX - 1).toFixed(3)} * ${CHAN.OVER.toFixed(2)});
vec2 crXZ = vec2(position.x, iRv.x + crRiverBend(position.x, iRv.z, abs(iRv.w)) + chSd * chDz);
const float chE = 0.3;
float crH0 = groundH(crXZ);
vec3 objectNormal = normalize(vec3(-(groundH(crXZ + vec2(chE, 0.0)) - crH0) / chE, 1.0, -(groundH(crXZ + vec2(0.0, chE)) - crH0) / chE));
#ifdef USE_TANGENT
vec3 objectTangent = vec3(1.0, 0.0, 0.0);
#endif
`;

interface Look {
  ground: THREE.Texture;
  road: THREE.Texture;
  kind: number;
  /** 地面画法（T195）：0 田野田块、1 林地错开采样、2 原贴图 */
  gkind: number;
}

/**
 * 一整块跟随玩家的地面：路面和两侧原野都在着色器里按世界坐标画出来（1 次 draw call）。
 * 切换区域时在前方设一条分界线，两套主题在分界处平滑过渡。
 */
export class Terrain {
  readonly mesh: THREE.Mesh;
  private readonly groundTex = new Map<GroundKind, THREE.Texture>();
  private readonly roadTex = new Map<RoadKind, THREE.Texture>();
  private readonly uniforms = {
    uGroundA: { value: null as THREE.Texture | null },
    uGroundB: { value: null as THREE.Texture | null },
    uRoadA: { value: null as THREE.Texture | null },
    uRoadB: { value: null as THREE.Texture | null },
    uNoise: { value: null as THREE.Texture | null },
    uKindA: { value: 0 },
    uKindB: { value: 0 },
    uGKindA: { value: 2 },
    uGKindB: { value: 2 },
    uBoundary: { value: -1e6 },
    uRoadHalf: { value: ROAD_HALF_WIDTH },
    uCrMesh: { value: 0 },
    uRunway: { value: new THREE.Vector2(-1e6, -1e6) },
  };
  /** 实体弹坑（T014-3）：高度场 + 坑的网格（一次绘制画完所有坑） */
  readonly craters: Craters;
  readonly craterMesh: THREE.Mesh;
  /** 下沉的河道（T034）：所有河一个实例化网格（一次绘制，没河时 instanceCount = 0 不出绘制） */
  readonly channelMesh: THREE.Mesh;
  private readonly channelGeo: THREE.InstancedBufferGeometry;
  private readonly channelInst: THREE.InstancedBufferAttribute;
  private pending: Look | null = null;
  private readonly normal: THREE.Texture;

  /** craterU = 弹坑的 uniform（Fx 那份，贴花 / 冲击波环 / 预警圈共用） */
  constructor(craterU: CraterUniforms) {
    this.craters = new Craters(craterU);
    this.uniforms.uNoise.value = grayNoise();
    this.normal = terrainNormal();
    // mode：0 = 平地网格、1 = 弹坑网格、2 = 河道网格（片元着色器按它决定挖不挖，见 MAP 末尾）
    const compile = (mode: 0 | 1 | 2) => (shader: THREE.WebGLProgramParametersWithUniforms) => {
      Object.assign(shader.uniforms, this.uniforms, this.craters.uniforms, { uCrMesh: { value: mode } });
      const attr = mode === 1 ? 'attribute vec3 iCrater;' : 'attribute vec4 iRv;';
      shader.vertexShader = shader.vertexShader
        .replace('#include <common>', `#include <common>\nvarying vec2 vWorldXZ;${mode ? `\n${attr}\n${CRATER_GLSL}` : ''}`)
        .replace(
          '#include <project_vertex>',
          '#include <project_vertex>\nvWorldXZ = (modelMatrix * vec4(transformed, 1.0)).xz;\n#ifdef USE_NORMALMAP\nvNormalMapUv = vWorldXZ * 0.16;\n#endif',
        );
      if (mode) {
        shader.vertexShader = shader.vertexShader
          .replace('#include <beginnormal_vertex>', mode === 1 ? CRATER_VERT : CHAN_VERT)
          .replace('#include <begin_vertex>', 'vec3 transformed = vec3(crXZ.x, crH0, crXZ.y);');
      }
      shader.fragmentShader = shader.fragmentShader
        .replace('#include <common>', `#include <common>\n${PARS}`)
        .replace('#include <map_fragment>', MAP)
        .replace('#include <roughnessmap_fragment>', 'float roughnessFactor = terrainRough;')
        .replace('#include <normal_fragment_maps>', '#include <normal_fragment_maps>\nnormal = normalize(normal + mat3(viewMatrix) * vec3(-duneG.x, 0.0, -duneG.y));');
    };
    const material = (mode: 0 | 1 | 2, key: string) => {
      const m = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 1, metalness: 0, normalMap: this.normal, normalScale: new THREE.Vector2(0.9, 0.9) });
      m.onBeforeCompile = compile(mode);
      m.customProgramCacheKey = () => key;
      return m;
    };

    this.mesh = new THREE.Mesh(new THREE.PlaneGeometry(760, 760), material(0, 'terrain-v8'));
    this.mesh.rotation.x = -Math.PI / 2;
    this.mesh.receiveShadow = true;

    // 弹坑：同一套地面着色器，顶点按坑的形状下陷；所有坑一个实例化网格（没有坑时 instanceCount = 0，不出绘制）
    this.craterMesh = new THREE.Mesh(this.craters.geometry, material(1, 'terrain-crater-v6'));
    this.craterMesh.frustumCulled = false;
    this.craterMesh.receiveShadow = true;

    // 河道（T034）：同一套地面着色器，每条河一个实例
    this.channelGeo = this.buildChannel();
    this.channelInst = new THREE.InstancedBufferAttribute(new Float32Array(12), 4);
    this.channelInst.setUsage(THREE.DynamicDrawUsage);
    this.channelGeo.setAttribute('iRv', this.channelInst);
    this.channelGeo.instanceCount = 0;
    this.channelMesh = new THREE.Mesh(this.channelGeo, material(2, 'terrain-channel-v3'));
    this.channelMesh.frustumCulled = false;
    this.channelMesh.receiveShadow = true;
  }

  /** 河道条带（见 CHAN）：顺河的列路面附近 1.5 米一列、往两边越来越稀（120 米外 6 → 14 米，雾里看不清），横向 2 × 14 + 1 行 */
  private buildChannel(): THREE.InstancedBufferGeometry {
    const xs: number[] = [0];
    for (let x = 0; x < 380; ) {
      const ax = Math.abs(x);
      x = Math.min(380, x + (ax < 30 ? 1.5 : ax < 120 ? 1.5 + ((ax - 30) / 90) * 4.5 : 6 + ((ax - 120) / 260) * 8));
      xs.push(x);
    }
    const cols = [...xs.slice(1).reverse().map((x) => -x), ...xs];
    const rows = [...CHAN.rows.slice().reverse().map((q) => -q), 0, ...CHAN.rows];
    const pos: number[] = [];
    for (const q of rows) for (const x of cols) pos.push(x, 0, q);
    const idx: number[] = [];
    const nc = cols.length;
    for (let r = 0; r < rows.length - 1; r++) {
      for (let c = 0; c < nc - 1; c++) {
        const a = r * nc + c;
        idx.push(a, a + nc, a + 1, a + 1, a + nc, a + nc + 1);
      }
    }
    const g = new THREE.InstancedBufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    g.setAttribute('normal', new THREE.Float32BufferAttribute(new Array(pos.length).fill(0).map((_, i) => (i % 3 === 1 ? 1 : 0)), 3));
    g.setAttribute('uv', new THREE.Float32BufferAttribute(new Array((pos.length / 3) * 2).fill(0), 2));
    g.setIndex(idx);
    return g;
  }

  /** 立即切到某个主题（开局 / 重开） */
  setTheme(theme: Theme): void {
    const look = this.look(theme);
    this.apply('A', look);
    this.apply('B', look);
    this.uniforms.uBoundary.value = -1e6;
    this.pending = null;
  }

  /** 在 boundaryZ 处过渡到新主题 */
  transitionTo(theme: Theme, boundaryZ: number): void {
    const look = this.look(theme);
    this.apply('B', look);
    this.uniforms.uBoundary.value = boundaryZ;
    this.pending = look;
  }

  /** 河（每帧由 Rivers 送进来）：弹坑的河道截断 + 地面高度的 uniform，河道网格每条河一个实例 */
  setRivers(list: readonly CraterRiver[]): void {
    this.craters.setRivers(list);
    const a = this.channelInst.array as Float32Array;
    const n = Math.min(3, list.length);
    let dirty = this.channelGeo.instanceCount !== n;
    for (let i = 0; i < n; i++) {
      const r = list[i];
      const amp = r.deck > 0 ? r.amp : -r.amp;
      if (a[i * 4] === r.z && a[i * 4 + 1] === r.half && a[i * 4 + 2] === r.phase && a[i * 4 + 3] === amp) continue;
      a[i * 4] = r.z;
      a[i * 4 + 1] = r.half;
      a[i * 4 + 2] = r.phase;
      a[i * 4 + 3] = amp;
      dirty = true;
    }
    this.channelGeo.instanceCount = n;
    if (dirty) this.channelInst.needsUpdate = true;
  }

  get boundary(): number {
    return this.uniforms.uBoundary.value;
  }

  update(playerZ: number): void {
    this.mesh.position.set(0, 0, playerZ - 120);
    // 分界线已经远远落在身后：新主题转正
    if (this.pending && playerZ < this.uniforms.uBoundary.value - 300) {
      this.apply('A', this.pending);
      this.uniforms.uBoundary.value = -1e6;
      this.pending = null;
    }
  }

  /** 区域 5 的跑道段（T093）：z 从 z0（近）到 z1（远，更小）这一段路面画跑道白线；关掉 = (-1e6, -1e6) */
  setRunway(z0: number, z1: number): void {
    this.uniforms.uRunway.value.set(z0, z1);
  }

  /** 弹坑圆盘网格换圈数 × 段数（T245 按画质，FX_TIERS.crater） */
  setCraterDetail(rings: number, seg: number): void {
    if (this.craters.setDetail(rings, seg)) this.craterMesh.geometry = this.craters.geometry;
  }

  dispose(): void {
    this.mesh.geometry.dispose();
    (this.mesh.material as THREE.Material).dispose();
    this.craters.geometry.dispose();
    (this.craterMesh.material as THREE.Material).dispose();
    this.channelGeo.dispose();
    (this.channelMesh.material as THREE.Material).dispose();
    for (const t of [...this.groundTex.values(), ...this.roadTex.values()]) t.dispose();
    this.uniforms.uNoise.value?.dispose();
    this.normal.dispose();
  }

  private apply(slot: 'A' | 'B', look: Look): void {
    const u = this.uniforms;
    if (slot === 'A') {
      u.uGroundA.value = look.ground;
      u.uRoadA.value = look.road;
      u.uKindA.value = look.kind;
      u.uGKindA.value = look.gkind;
    } else {
      u.uGroundB.value = look.ground;
      u.uRoadB.value = look.road;
      u.uKindB.value = look.kind;
      u.uGKindB.value = look.gkind;
    }
  }

  private look(theme: Theme): Look {
    let ground = this.groundTex.get(theme.ground);
    if (!ground) {
      ground = groundTexture(theme.ground);
      this.groundTex.set(theme.ground, ground);
    }
    let road = this.roadTex.get(theme.road);
    if (!road) {
      road = roadTexture(theme.road);
      this.roadTex.set(theme.road, road);
    }
    return { ground, road, kind: theme.roadIndex, gkind: theme.ground === 'field' ? 0 : theme.ground === 'forest' ? 1 : 2 };
  }
}
