/**
 * 「今天」的编号（T030）：本地时间凌晨 4 点换天（每日任务、每日广告上限、每日首局都按它），写成 20261014 这样的整数。
 * 时间往回调不刷新（调用方只在新编号比存着的大时才换天）
 */
export function dayKey(t = Date.now()): number {
  const d = new Date(t - 4 * 3600 * 1000);
  return d.getFullYear() * 10000 + (d.getMonth() + 1) * 100 + d.getDate();
}

/** 到下一次凌晨 4 点还有多少秒 */
export function secsToReset(t = Date.now()): number {
  const d = new Date(t);
  const next = new Date(d.getFullYear(), d.getMonth(), d.getDate(), 4, 0, 0, 0);
  if (next.getTime() <= t) next.setDate(next.getDate() + 1);
  return Math.max(0, Math.round((next.getTime() - t) / 1000));
}
