/** 两捆草沿用原模型的位置、朝向和尺寸；接触与火焰逐捆检查。 */
export const HAY_BALES = [
  { x: 0, z: 0, yaw: 0, color: 0xb8994e },
  { x: 1.6, z: .6, yaw: .4, color: 0xa88b45 },
] as const;

/** 两捆草合起来的占地中心（原点在第一捆）：烧小时往这里收，不是往第一捆收 */
export const HAY_CENTER = { x: .8, z: .3 } as const;

const smooth = (a: number, b: number, x: number) => {
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
};

/**
 * 草垛烧的外观（T203），k = 已烧时间 / 燃烧时长：
 * 先窜火、外层由金黄烧到焦黑（约 0～3 秒），再从约 2 秒起慢慢往里塌小（高度和四周一起收，矮得稍快一点，不压成扁饼），最后一小堆焦灰沉进地面。
 * char = 烧黑程度，wide / tall = 水平 / 竖直缩放，sink = 收尾下沉进度（0～1）
 */
export function hayBurnLook(k: number): { char: number; wide: number; tall: number; sink: number } {
  const shrink = smooth(.34, 1, k);
  return { char: smooth(.03, .5, k), wide: 1 - .62 * shrink, tall: 1 - .72 * shrink, sink: smooth(.84, 1, k) };
}

/** 烧黑的颜色倍率：红通道掉得慢一点，中途是焦棕，最后接近炭黑 */
export function hayCharRGB(c: number, out: { r: number; g: number; b: number }): typeof out {
  out.r = 1 - .955 * c;
  out.g = 1 - .965 * Math.pow(c, .85);
  out.b = 1 - .965 * Math.pow(c, .7);
  return out;
}

/** 草捆与车体矩形相交。不能只测第一捆的原点，第二捆向外伸了近一米。 */
export function hayTouches(x: number, z: number, yaw: number, scale: number,
  tx: number, tz: number, tw: number, tl: number, tyaw: number): boolean {
  const c = Math.cos(yaw), s = Math.sin(yaw), tc = Math.cos(tyaw), ts = Math.sin(tyaw);
  for (const b of HAY_BALES) {
    const dx = x + (b.x * c + b.z * s) * scale - tx;
    const dz = z + (-b.x * s + b.z * c) * scale - tz;
    const bc = Math.cos(yaw + b.yaw), bs = Math.sin(yaw + b.yaw);
    const w = .75 * scale, d = .95 * scale;
    const dot = Math.abs(bc * tc + bs * ts), cross = Math.abs(bs * tc - bc * ts);
    if (Math.abs(dx * tc - dz * ts) > tw + w * dot + d * cross ||
        Math.abs(dx * ts + dz * tc) > tl + w * cross + d * dot ||
        Math.abs(dx * bc - dz * bs) > w + tw * dot + tl * cross ||
        Math.abs(dx * bs + dz * bc) > d + tw * cross + tl * dot) continue;
    return true;
  }
  return false;
}

/** 火锥仍用原射程和角度；草捆自身的外沿也能接到火。 */
export function hayInFlame(x: number, z: number, yaw: number, scale: number,
  ox: number, oz: number, angle: number, range: number, cone: number): boolean {
  const c = Math.cos(yaw), s = Math.sin(yaw), rad = Math.hypot(.75, .95) * scale;
  for (const b of HAY_BALES) {
    const dx = x + (b.x * c + b.z * s) * scale - ox;
    const dz = z + (-b.x * s + b.z * c) * scale - oz;
    const d = Math.hypot(dx, dz);
    if (d > range + rad) continue;
    const diff = Math.atan2(Math.sin(Math.atan2(-dx, -dz) - angle), Math.cos(Math.atan2(-dx, -dz) - angle));
    if (Math.abs(diff) <= cone + rad / Math.max(3, d)) return true;
  }
  return false;
}

export function hayInFire(x: number, z: number, yaw: number, scale: number, fx: number, fz: number, r: number): boolean {
  const c = Math.cos(yaw), s = Math.sin(yaw);
  for (const b of HAY_BALES) if (Math.hypot(x + (b.x * c + b.z * s) * scale - fx,
    z + (-b.x * s + b.z * c) * scale - fz) <= r + Math.hypot(.75, .95) * scale * .6) return true;
  return false;
}

export function hayInEllipse(x: number, z: number, yaw: number, scale: number,
  fx: number, fz: number, rx: number, rz: number): boolean {
  const c = Math.cos(yaw), s = Math.sin(yaw), pad = Math.hypot(.75, .95) * scale * .6;
  for (const b of HAY_BALES) {
    const u = (x + (b.x * c + b.z * s) * scale - fx) / (rx + pad);
    const v = (z + (-b.x * s + b.z * c) * scale - fz) / (rz + pad);
    if (u * u + v * v <= 1) return true;
  }
  return false;
}
