import { BOSSES, type BossDef } from '../bosses/bosses';
import { THEMES } from '../world/themes';
import { AIR_RUN, AIR_ZONE, SAND_RUN, SAND_ZONE } from './cycle';

/**
 * 作战模式（T110，制作人「自选关卡 / 连续作战 / 首领挑战……以后每次设计新的关卡和 boss 的时候，都可以在主界面直接选择面对它进行测试」）。
 * 连续作战 = 原来的玩法（开始界面「开始作战」）；自选关卡 / 首领挑战的列表都从表里生成，不逐个写名字：
 * 关卡 = themes.ts 的 THEMES（第 i 项 = 第 i + 1 区），首领 = bosses.ts 的 BOSSES（同样一一对应）
 */

/** 这一局是哪种模式：zone = 自选关卡从第几区打起；boss = 首领挑战（第几个首领、先选几次升级；day = 今日任务那天的编号） */
export type RunMode = { kind: 'zone'; zone: number } | { kind: 'boss'; boss: number; picks: number; day?: number };

/** 首领挑战：开打前先选几次升级（制作人「15 次升级 20 次升级或者 30 次升级」） */
export const BOSS_PICKS = [15, 20, 30] as const;

/**
 * 自选关卡：从第 n 区打起，开打前先选几次升级（第 1 区 0 = 直接开打）。大约是正常打到那一区开头时的等级
 * （T036 实测：打完第 1 区约 10 级、第 2 区约 16 级、第 3 区约 19 级）；荒原机场照旧 AIR_RUN.picks、沙漠油井 SAND_RUN.picks（T122）。表里没有的区按最后一项
 */
export const LEVEL_PICKS = [0, 10, 15, 20];

export interface LevelDef {
  zone: number;
  name: string;
  boss: BossDef;
  /** 开打前先选几次升级 */
  picks: number;
  /** 荒原机场（单独一局，敌人倍率低一档，见 cycle.ts 的 AIR_RUN） */
  air: boolean;
}

/** 关卡表：按 THEMES 生成，新加一个主题（一区）就多一关 */
export const LEVELS: readonly LevelDef[] = THEMES.map((t, i) => {
  const zone = i + 1;
  const air = zone === AIR_ZONE;
  return { zone, name: t.name, boss: BOSSES[i % BOSSES.length], air, picks: air ? AIR_RUN.picks : zone === SAND_ZONE ? SAND_RUN.picks : (LEVEL_PICKS[i] ?? LEVEL_PICKS[LEVEL_PICKS.length - 1]) };
});

/** 首领挑战的首领在第几区（BOSSES 第 i 项 = 第 i + 1 区） */
export const bossZone = (i: number): number => i + 1;

/** 存档里读出来的模式（T110；老存档没有 / 不认识 = null） */
export function parseMode(m: unknown): RunMode | null {
  const x = m as Partial<{ kind: string; zone: number; boss: number; picks: number; day: number }> | null;
  if (x?.kind === 'zone' && Number.isInteger(x.zone) && x.zone! >= 1 && x.zone! <= LEVELS.length) return { kind: 'zone', zone: x.zone! };
  if (x?.kind === 'boss' && Number.isInteger(x.boss) && x.boss! >= 0 && x.boss! < BOSSES.length) {
    const picks = BOSS_PICKS.includes(x.picks as 15) ? x.picks! : BOSS_PICKS[1];
    return typeof x.day === 'number' ? { kind: 'boss', boss: x.boss!, picks, day: x.day } : { kind: 'boss', boss: x.boss!, picks };
  }
  return null;
}
