import type { UiSkin } from './types';
import { hatch, line, random, rivet } from './drawing';

export const scheme3: UiSkin = {
  id: 3, name: '防爆铁幕', shape: 'cut', radius: 7, ticks: 8,
  colors: {
    back: '#10191f', backHi: '#2a3a45', high: '#3e5260', low: '#202e38', line: '#7c909b',
    ink: '#f1f3ec', soft: '#d0dce0', dim: '#a6bbc5', accent: '#edaf62', cool: '#add5e6',
    mainHi: '#f0bd77', mainLow: '#d39145', mainInk: '#1c252b', shadow: '#080f14',
  },
  texture(c) {
    const rnd = random(320);
    for (let i = 0; i < 1300; i++) {
      const x = rnd() * 256, y = rnd() * 256;
      line(c, x, y, x + rnd() * 46 + 4, y, i % 3 ? 'rgba(193,215,222,.045)' : 'rgba(0,5,10,.13)', 0.4);
    }
  },
  detail(c, w, h, role) {
    line(c, 9, 4, w - 16, 4, '#b4c4c555');
    if (w < 65 || h < 34) {
      line(c, w - 10, h - 3, w - 3, h - 10, '#edaf62', 2);
      return;
    }
    if (role === 'primary') {
      hatch(c, 3, 5, 20, h - 10, '#263540', 10);
      hatch(c, w - 23, 5, 20, h - 10, '#263540', 10);
    } else {
      c.fillStyle = role === 'card' ? '#df9e4e' : '#94a5aa';
      c.fillRect(3, 14, 3, h - 28);
      for (let i = 0; i < 3; i++) line(c, w - 29 + i * 6, h - 7, w - 25 + i * 6, h - 11, '#7e959e', 2);
      if (role === 'title') hatch(c, 12, h - 5, w - 24, 4, '#c99047', 10);
    }
  },
  scene(c, w, h) {
    const l = Math.max(8, (w - 540) / 2), r = w - l;
    c.strokeStyle = '#647e8a'; c.lineWidth = 1;
    c.beginPath(); c.moveTo(l + 25, 13); c.lineTo(r - 25, 13); c.lineTo(r, 38);
    c.lineTo(r, h - 38); c.lineTo(r - 25, h - 13); c.lineTo(l + 25, h - 13);
    c.lineTo(l, h - 38); c.lineTo(l, 38); c.closePath(); c.stroke();
    hatch(c, l + 25, 17, 74, 7, '#b98543', 13);
    hatch(c, r - 99, h - 24, 74, 7, '#b98543', 13);
    for (const x of [l + 3, r - 3]) {
      for (const y of [56, h / 2, h - 56]) {
        c.fillStyle = '#1b2a33'; c.fillRect(x - 2, y - 17, 4, 34);
        rivet(c, x, y - 14, 1.8); rivet(c, x, y + 14, 1.8);
      }
    }
    line(c, l + 12, h - 33, l + 78, h - 33, '#abbcc3', 2);
    for (let x = l + 13; x < l + 80; x += 8) line(c, x, h - 40, x, h - 34, '#abbcc3');
  },
};
