import './styles.css';
import './ui/armor.css';
import './ui/skins/base.css';
import './ui/skins/scheme1.css';
import './ui/skins/scheme2.css';
import './ui/skins/scheme3.css';
import './ui/skins/scheme4.css';
import './ui/skins/scheme5.css';
import './ui/coreCarousel.css';
import './ui/turntable.css';
import './ui/gamepad.css';
import './ui/command.css';
import './ui/landscape.css';
import './ui/browserDisplay.css';
import './ui/mainMenu.css';
import './ui/subWorkshop.css';
import { browserDisplay, disposeBrowserDisplay } from './ui/browserDisplay';
import { installDomSkin } from './ui/skins/art';
import { Game } from './game/Game';
import { bootMark, getLoader, runBoot, type BootTask } from './boot';
import { PLAYER_PAINT } from './assets/models/playerTank';
import { sharedEnemyCamo, sharedMetalNormal } from './render/sharedTextures';
import { decalAtlas, grayNoise, groundTexture, particleAtlas, playerPaint, roadTexture, terrainNormal, trackTexture } from './render/textures';
import { THEMES } from './world/themes';

bootMark('bundle');
browserDisplay();
installDomSkin();

// 网页：正常从 DOM 拿 #game-canvas
// 微信小游戏：没有 HTML，适配层把 canvas 挂在全局（window.canvas / GameGlobal.screencanvas），
//   且适配层的 document.querySelector 只认 'head' / 'body' / 'canvas'
const g = globalThis as any;
const canvas: HTMLCanvasElement =
  document.querySelector<HTMLCanvasElement>('#game-canvas') ||
  document.querySelector<HTMLCanvasElement>('canvas') ||
  g.canvas ||
  (g.GameGlobal && g.GameGlobal.screencanvas);

if (!canvas) {
  throw new Error('Missing #game-canvas element.');
}

/**
 * 启动（T108）：加载页盖着，一步一步建（每步之间空出一帧，加载页的进度和动画接着走）：
 * 程序化贴图先算好（同样参数只算一次）→ 建游戏 → 整备台 → 编着色器 → 战场 / 开始界面各画一帧 → 读录音；
 * 全做完加载页才撤，一撤就是能点的开始界面
 */
const loader = getLoader();
let game: Game | null = null;
// 一张贴图一步（手机上没有 JIT，一张要算几百毫秒，进度条一步一步走）
const tex = (label: string, mark: string, run: () => unknown): BootTask => ({ label, mark, run: () => void run() });
const tasks: BootTask[] = [
  tex('正在铺设地面', 'tex-noise', () => grayNoise()),
  tex('正在铺设地面', 'tex-terrain', () => terrainNormal()),
  tex('正在铺设地面', 'tex-ground', () => groundTexture(THEMES[0].ground)),
  tex('正在铺设地面', 'tex-road', () => roadTexture(THEMES[0].road)),
  tex('正在喷涂装甲', 'tex-metal', () => sharedMetalNormal()),
  tex('正在喷涂装甲', 'tex-camo', () => sharedEnemyCamo()),
  tex('正在喷涂装甲', 'tex-armor', () => (playerPaint(PLAYER_PAINT.colors, PLAYER_PAINT.seed), trackTexture())),
  tex('正在准备特效', 'tex-fx', () => (particleAtlas(), decalAtlas())),
  {
    label: '正在装载战场',
    mark: 'game',
    run: () => {
      game = new Game(canvas);
    },
  },
  ...Game.WARM.map((w): BootTask => ({ label: w.label, mark: w.id, run: () => game!.warm(w.id) })),
];

runBoot(loader, tasks, () => game?.resetGl())
  .then(() => {
    loader.finish();
    game!.resetGl();
    game!.start();
    bootMark('ready');
    // 给小游戏入口用：标记已成功进入游戏循环（诊断超时用）
    g.__TANK_BOOTED__ = true;
  })
  .catch((error) => {
    loader.fail?.('加载失败，请重新打开');
    throw error;
  });

if (import.meta.hot) {
  import.meta.hot.dispose(() => {
    disposeBrowserDisplay();
    game?.dispose();
  });
}
