/** 录音归一化每帧最多算这么多个采样点（T108，手机上一帧十几毫秒） */
const SLICE = 1 << 17;

/** 把 [0, n) 分成每段 SLICE 个、一帧算一段 */
async function slices(n: number, fn: (i0: number, i1: number) => void): Promise<void> {
  for (let i = 0; i < n; i += SLICE) {
    fn(i, Math.min(n, i + SLICE));
    if (i + SLICE < n) await nextFrame();
  }
}

