import * as THREE from 'three';
import type { GeoCache, PartSpec } from '../GeoCache';
import { chamfer, frustum, rect } from '../ModelKit';
import { paint } from '../../render/textures';
import type { Branch } from '../../weapons/defs';

/**
 * 火神炮塔（D1-032 第 6.7 / 8.2 节）：基础一门短粗六管；弹幕线双联；重弹线长管（管长 1.6 倍、粗 1.3 倍，夹箍 + 散热罩）；
 * 四联火神 2 × 2 摇架 + 两侧大弹鼓；千钧火神一门七管巨炮伸出车头 + 炮塔后背圆柱弹鼓。
 * 5 级（T090，第 6.7 节「5 级」那一行）：弹幕线换整根散热罩 + 炮前防盾、弹箱加大加一层；重弹线炮口加制退器、弹箱加大、炮塔两侧加挂甲。
 * 每门炮一个子节点（分火时单独偏转）、一组转管（绕 z 轴转）、一圈转管虚影（转快了才显示）、管口发热件（共用一个自发光材质）；
 * 弹箱到机匣一条弹带（共用一张链节贴图，VulcanCore 按射速 / 补弹速度滚动贴图）
 */
export interface VulcanRig {
  /** 每门炮（rotation.y = 分火偏角） */
  guns: THREE.Group[];
  /** 每门炮的转管（rotation.z 转） */
  spinners: THREE.Object3D[];
  /** 转管虚影（转速过 15 弧度/秒才显示，低画质不显示） */
  blurs: THREE.Mesh[];
  /** 抛壳口（炮塔局部，世界坐标用 getWorldPosition 取）；side = 往哪边抛（+1 右 / −1 左） */
  ejects: { o: THREE.Object3D; side: number }[];
  /** 管口发红：所有火神炮管口共用 */
  heat: THREE.MeshStandardMaterial;
  /** 弹带贴图：offset.y 每走 1 = 一发弹往炮里走一格 */
  belt: THREE.Texture;
  /** 弹壳个头（千钧 ×1.8） */
  casing: number;
}

const OLIVE = 0xb8bca0;
const OLIVE_D = 0x9ea288;
const DARK = 0x34373a;
const STEEL = 0x5c6064;
const BRASS = 0x8a7038;
const GOLD = 0xd8a84a;
/** 弹带上一发弹占多长（米）：贴图 v 方向每格一发 */
const PITCH = 0.11;

let heatMat: THREE.MeshStandardMaterial | null = null;
let blurMat: THREE.MeshBasicMaterial | null = null;
let beltMat: THREE.MeshStandardMaterial | null = null;

/** 管口发热件：冷铁色，emissive 由 VulcanCore 每帧按热度写（暗红 → 橙白） */
export function vulcanHeat(): THREE.MeshStandardMaterial {
  return (heatMat ??= new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.5, metalness: 0.7, emissive: 0x000000, emissiveIntensity: 1 }));
}

function vulcanBlur(): THREE.MeshBasicMaterial {
  return (blurMat ??= new THREE.MeshBasicMaterial({ color: 0x7a7c78, transparent: true, opacity: 0.32, depthWrite: false }));
}

/** 弹带：一格一发，黄铜弹壳横着排、弹头铜红、中间钢链节；两面都画 */
function vulcanBelt(): THREE.MeshStandardMaterial {
  if (beltMat) return beltMat;
  const tex = paint(32, (u, v) => {
    const round = v > 0.16 && v < 0.84;
    const edge = Math.min(v - 0.16, 0.84 - v);
    const hl = round ? 0.75 + 0.35 * Math.max(0, 1 - Math.abs(v - 0.42) * 4) : 0;
    if (round && u > 0.06 && u < 0.74) return [0.72 * hl, 0.55 * hl, 0.22 * hl];
    if (round && u >= 0.74 && u < 0.95 && edge > 0.08) return [0.62 * hl, 0.34 * hl, 0.18 * hl];
    const link = u < 0.12 || (u > 0.4 && u < 0.52) ? 0.32 : 0.16;
    return [link, link, link * 1.05];
  });
  return (beltMat = new THREE.MeshStandardMaterial({ map: tex, roughness: 0.42, metalness: 0.7, side: THREE.DoubleSide }));
}

/** 几条弹带合成一个网格：每条沿折线走、宽 w，面朝上；uv 的 v = 沿带长 ÷ PITCH（贴图一格一发） */
function beltGeo(lines: [number, number, number][][], w: number): THREE.BufferGeometry {
  const pos: number[] = [];
  const uv: number[] = [];
  const idx: number[] = [];
  const up = new THREE.Vector3(0, 1, 0);
  const a = new THREE.Vector3();
  const b = new THREE.Vector3();
  const t = new THREE.Vector3();
  const side = new THREE.Vector3();
  for (const pts of lines) {
    // 折线按 6 段一节插值成平滑一点的弧
    const dense: THREE.Vector3[] = [];
    const curve = new THREE.CatmullRomCurve3(pts.map((p) => new THREE.Vector3(...p)));
    for (let i = 0; i <= (pts.length - 1) * 6; i++) dense.push(curve.getPoint(i / ((pts.length - 1) * 6)));
    let len = 0;
    const base = pos.length / 3;
    dense.forEach((p, i) => {
      a.copy(dense[Math.max(0, i - 1)]);
      b.copy(dense[Math.min(dense.length - 1, i + 1)]);
      t.subVectors(b, a).normalize();
      side.crossVectors(t, up);
      if (side.lengthSq() < 1e-6) side.set(1, 0, 0);
      side.normalize().multiplyScalar(w / 2);
      if (i > 0) len += p.distanceTo(dense[i - 1]);
      pos.push(p.x - side.x, p.y - side.y, p.z - side.z, p.x + side.x, p.y + side.y, p.z + side.z);
      uv.push(0, len / PITCH, 1, len / PITCH);
      if (i > 0) {
        const k = base + i * 2;
        idx.push(k - 2, k - 1, k, k - 1, k + 1, k);
      }
    });
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  g.setIndex(idx);
  g.computeVertexNormals();
  return g;
}

interface GunSpec {
  /** 管数 / 管长 / 单管半径 / 管簇半径 */
  n: number;
  len: number;
  r: number;
  rc: number;
  /** 机匣尺寸 */
  box: [number, number, number];
  /** 重弹线：散热罩 + 夹箍；千钧：粗夹箍 */
  shroud?: boolean;
  /** 5 级弹幕线：整根带散热槽的套筒 + 机匣前一块防盾 */
  jacket?: boolean;
  /** 5 级重弹线：炮口制退器 */
  brake?: boolean;
}

const BASE: GunSpec = { n: 6, len: 2.6, r: 0.075, rc: 0.2, box: [0.72, 0.62, 1.05] };
const BASE5: GunSpec = { ...BASE, jacket: true };
const LONG: GunSpec = { n: 6, len: 4.16, r: 0.0975, rc: 0.26, box: [0.82, 0.7, 1.15], shroud: true };
const LONG5: GunSpec = { ...LONG, brake: true };
const QUAD: GunSpec = { n: 6, len: 2.4, r: 0.065, rc: 0.17, box: [0.6, 0.52, 0.95] };
const MEGA: GunSpec = { n: 7, len: 5.2, r: 0.12, rc: 0.36, box: [1.15, 0.95, 1.5], shroud: true };

/** 一门炮：机匣 + 转管（管 / 夹箍 / 管口发热件）+ 虚影 + 炮口点 + 抛壳口（5 级加套筒 / 防盾 / 制退器） */
function gun(geo: GeoCache, key: string, s: GunSpec, metal: THREE.Material, side: number, rig: VulcanRig, muzzles: THREE.Object3D[], mk: (g: THREE.BufferGeometry, m: THREE.Material, parent: THREE.Object3D) => THREE.Mesh): THREE.Group {
  const g = new THREE.Group();
  const [bw, bh, bd] = s.box;
  const front = -bd / 2;
  const jr = s.rc + s.r + 0.07;
  mk(geo.merged(`vul-recv-${key}`, (): PartSpec[] => [
    { geo: new THREE.BoxGeometry(bw, bh, bd), color: DARK },
    { geo: new THREE.BoxGeometry(bw * 0.7, bh * 0.25, bd * 0.8), color: STEEL, pos: [0, bh * 0.6, 0.05] },
    // 抛壳口
    { geo: new THREE.BoxGeometry(0.04, bh * 0.35, bd * 0.4), color: 0x141414, pos: [side * (bw / 2 + 0.01), 0, 0.05] },
    // 电机
    { geo: new THREE.CylinderGeometry(bh * 0.28, bh * 0.28, bd * 0.5, 16), color: STEEL, pos: [0, -bh * 0.05, bd * 0.55], rot: [Math.PI / 2, 0, 0] },
    // 机匣侧面散热肋 + 电机端盖（T171）
    ...[-1, 1].flatMap((sx) => [-0.25, 0, 0.25].map((dz): PartSpec => ({ geo: new THREE.BoxGeometry(0.03, bh * 0.7, 0.06), color: STEEL, pos: [sx * (bw / 2 + 0.015), -bh * 0.05, dz * bd] }))),
    { geo: new THREE.CylinderGeometry(bh * 0.3, bh * 0.3, 0.05, 16), color: DARK, pos: [0, -bh * 0.05, bd * 0.81], rot: [Math.PI / 2, 0, 0] },
    ...(s.shroud ? [{ geo: new THREE.CylinderGeometry(jr, jr, s.len * 0.32, 12, 1, true), color: OLIVE_D, pos: [0, 0, front - s.len * 0.18], rot: [Math.PI / 2, 0, 0] } as PartSpec] : []),
    // 5 级：整根散热套筒（一圈箍 + 八条散热槽），机匣前一块防盾
    ...(!s.jacket ? [] : [
      { geo: new THREE.CylinderGeometry(jr, jr, s.len * 0.66, 14, 1, true), color: 0x6a6e56, pos: [0, 0, front - s.len * 0.33], rot: [Math.PI / 2, 0, 0] } as PartSpec,
      ...[0.1, 0.3, 0.5].map((k): PartSpec => ({ geo: new THREE.CylinderGeometry(jr + 0.03, jr + 0.03, 0.07, 14), color: DARK, pos: [0, 0, front - s.len * k], rot: [Math.PI / 2, 0, 0] })),
      ...Array.from({ length: 8 }, (_, i): PartSpec => {
        const a = (i / 8) * Math.PI * 2;
        return { geo: new THREE.BoxGeometry(0.03, 0.03, s.len * 0.5), color: 0x1a1a1a, pos: [Math.cos(a) * (jr + 0.005), Math.sin(a) * (jr + 0.005), front - s.len * 0.33] };
      }),
      { geo: new THREE.BoxGeometry(bw * 1.45, bh * 1.35, 0.09), color: OLIVE_D, pos: [0, bh * 0.05, front - 0.05] },
      { geo: new THREE.BoxGeometry(bw * 1.45, 0.06, 0.12), color: DARK, pos: [0, bh * 0.72, front - 0.05] },
    ] as PartSpec[]),
    // 5 级：炮口制退器（粗筒 + 两侧泄气口）
    ...(!s.brake ? [] : [
      { geo: new THREE.CylinderGeometry(jr + 0.06, jr + 0.06, 0.55, 12), color: DARK, pos: [0, 0, front - s.len - 0.27], rot: [Math.PI / 2, 0, 0] } as PartSpec,
      ...[-1, 1].flatMap((sx) => [0.12, 0.3].map((dz): PartSpec => ({ geo: new THREE.BoxGeometry(0.08, jr * 1.2, 0.1), color: 0x141414, pos: [sx * (jr + 0.05), 0, front - s.len - dz - 0.05] }))),
    ] as PartSpec[]),
  ]), metal, g);
  const spin = new THREE.Group();
  spin.position.z = front;
  g.add(spin);
  const body = s.len * 0.78;
  mk(geo.merged(`vul-barrels-${key}`, () => {
    const p: PartSpec[] = [];
    for (let k = 0; k < s.n; k++) {
      const a = (k / s.n) * Math.PI * 2;
      p.push({ geo: new THREE.CylinderGeometry(s.r, s.r * 1.08, body, 14), color: STEEL, pos: [Math.cos(a) * s.rc, Math.sin(a) * s.rc, -body / 2], rot: [Math.PI / 2, 0, 0] });
    }
    // 中轴 + 前中后三道夹箍（T171：管子 8 → 14 段、夹箍 12 → 20 段，多一道中箍）
    p.push({ geo: new THREE.CylinderGeometry(s.rc * 0.45, s.rc * 0.45, s.len, 14), color: DARK, pos: [0, 0, -s.len / 2], rot: [Math.PI / 2, 0, 0] });
    for (const z of [0.12, s.len * 0.36, s.len * (s.shroud ? 0.82 : 0.6)]) p.push({ geo: new THREE.CylinderGeometry(s.rc + s.r * 1.6, s.rc + s.r * 1.6, s.shroud ? 0.2 : 0.12, 20), color: DARK, pos: [0, 0, -z], rot: [Math.PI / 2, 0, 0] });
    return p;
  }), metal, spin);
  mk(geo.merged(`vul-tips-${key}`, () => {
    const p: PartSpec[] = [];
    const tip = s.len - body;
    for (let k = 0; k < s.n; k++) {
      const a = (k / s.n) * Math.PI * 2;
      p.push({ geo: new THREE.CylinderGeometry(s.r * 0.95, s.r, tip, 14), color: 0x3a3836, pos: [Math.cos(a) * s.rc, Math.sin(a) * s.rc, -body - tip / 2], rot: [Math.PI / 2, 0, 0] });
    }
    return p;
  }), vulcanHeat(), spin).castShadow = false;
  const blur = new THREE.Mesh(geo.get(`vul-blur-${key}`, () => new THREE.CylinderGeometry(s.rc + s.r, s.rc + s.r, s.len * 0.92, 16, 1, true).rotateX(Math.PI / 2).translate(0, 0, front - s.len * 0.46)), vulcanBlur());
  blur.visible = false;
  blur.renderOrder = 3;
  g.add(blur);
  const m = new THREE.Object3D();
  m.position.set(0, 0, front - s.len - (s.brake ? 0.65 : 0.15));
  g.add(m);
  muzzles.push(m);
  const ej = new THREE.Object3D();
  ej.position.set(side * (bw / 2 + 0.05), 0.05, 0.05);
  g.add(ej);
  rig.guns.push(g);
  rig.spinners.push(spin);
  rig.blurs.push(blur);
  rig.ejects.push({ o: ej, side });
  return g;
}

/** 搭火神炮塔；返回炮塔组、炮口、副武器挂点和火神的活动件；tier = 5 时换 5 级外形（终极形态不看它） */
export function vulcanTurret(geo: GeoCache, group: THREE.Group, branch: Branch | null, ultimate: boolean, body: THREE.Material, metal: THREE.Material, muzzles: THREE.Object3D[], tier = 1): { rig: VulcanRig; anchors: [number, number, number][] } {
  const mk = (g: THREE.BufferGeometry, m: THREE.Material, parent: THREE.Object3D) => {
    const mesh = new THREE.Mesh(g, m);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    parent.add(mesh);
    return mesh;
  };
  const quad = ultimate && branch === 'A';
  const mega = ultimate && branch === 'B';
  const belt = vulcanBelt();
  const rig: VulcanRig = { guns: [], spinners: [], blurs: [], ejects: [], heat: vulcanHeat(), belt: belt.map!, casing: mega ? 1.8 : 1 };
  const w = mega ? 3.0 : 2.7;
  const t5 = tier >= 5 && !ultimate;
  mk(geo.merged(`vul-turret-${mega ? 'mega' : 'std'}`, () => [
    // T175：炮塔 / 尾舱底面抬到 0.16（playerTank.ts 的 TURRET_GAP），和甲板之间露出座圈，顶面不变
    { geo: frustum(chamfer(w, 3.0, 0.55), chamfer(w - 0.5, 2.5, 0.45), 0.85 - 0.16, 0.16), color: OLIVE },
    // 尾舱
    { geo: frustum(rect(w - 0.7, 1.0, 0, 1.6), rect(w - 0.9, 0.85, 0, 1.55), 0.75 - 0.16, 0.16), color: OLIVE_D },
    // 炮耳座
    { geo: new THREE.BoxGeometry(1.5, 0.7, 0.9), color: OLIVE_D, pos: [0, 0.6, -1.2] },
    // 车长塔
    { geo: new THREE.CylinderGeometry(0.34, 0.38, 0.3, 10), color: OLIVE_D, pos: [-0.7, 1.0, 0.55] },
    { geo: new THREE.BoxGeometry(0.4, 0.12, 0.2), color: 0x1e2428, pos: [-0.7, 1.1, 0.35] },
    ...[-1, 1].map((s): PartSpec => ({ geo: new THREE.BoxGeometry(0.06, 0.34, 1.2), color: DARK, pos: [s * (w / 2 - 0.05), 0.45, 0.1], rot: [0, 0, s * 0.2] })),
    ...(ultimate ? [{ geo: frustum(chamfer(w + 0.02, 3.02, 0.55), chamfer(w, 3.0, 0.55), 0.1, 0.3), color: GOLD }] : []),
  ]), body, group);

  if (quad) {
    // 四联：2 × 2 摇架，两侧大弹鼓，四条弹带从弹鼓接到四门炮
    const cradle = new THREE.Group();
    cradle.position.set(0, 0.95, -1.2);
    group.add(cradle);
    mk(geo.merged('vul-cradle', () => [
      { geo: new THREE.BoxGeometry(1.9, 0.18, 1.3), color: DARK, pos: [0, -0.62, 0.2] },
      ...[-1, 1].map((s): PartSpec => ({ geo: new THREE.BoxGeometry(0.12, 1.5, 1.2), color: DARK, pos: [s * 0.98, 0, 0.2] })),
      ...[-1, 1].flatMap((s): PartSpec[] => [
        { geo: new THREE.CylinderGeometry(0.55, 0.55, 0.9, 16), color: OLIVE_D, pos: [s * 1.55, -0.2, 0.9], rot: [0, 0, Math.PI / 2] },
        { geo: new THREE.CylinderGeometry(0.57, 0.57, 0.08, 16), color: DARK, pos: [s * 1.55, -0.2, 0.9], rot: [0, 0, Math.PI / 2] },
      ]),
    ]), metal, cradle);
    const pos: [number, number][] = [[-0.45, 0.33], [0.45, 0.33], [-0.45, -0.33], [0.45, -0.33]];
    for (const [x, y] of pos) {
      const g = gun(geo, 'quad', QUAD, metal, Math.sign(x), rig, muzzles, mk);
      g.position.set(x, y, 0);
      cradle.add(g);
    }
    mk(geo.get('vul-belt-quad', () => beltGeo(pos.map(([x, y]) => {
      const s = Math.sign(x);
      return [[s * 1.5, 0.32, 0.95], [s * 1.25, y + 0.25, 0.7], [s * 0.82, y + 0.24, 0.3], [x + s * 0.12, y + 0.27, 0.05]];
    }), 0.15)), belt, cradle).castShadow = false;
    return { rig, anchors: [[0.9, 1.0, 1.35], [-0.9, 1.0, 1.35]] };
  }

  if (mega) {
    // 千钧：一门七管巨炮伸出车头一大截，后背一个圆柱大弹鼓，一条宽弹带从弹鼓顶上绕到炮尾
    mk(geo.merged('vul-mega-drum', () => [
      { geo: new THREE.CylinderGeometry(0.6, 0.6, 2.2, 18), color: OLIVE_D, pos: [0, 0.95, 1.75], rot: [0, 0, Math.PI / 2] },
      ...[-1, 0, 1].map((k): PartSpec => ({ geo: new THREE.CylinderGeometry(0.63, 0.63, 0.08, 18), color: DARK, pos: [k * 0.85, 0.95, 1.75], rot: [0, 0, Math.PI / 2] })),
    ]), metal, group);
    mk(geo.get('vul-belt-mega', () => beltGeo([[[0.4, 1.56, 1.6], [0.45, 1.62, 0.9], [0.42, 1.58, 0.0], [0.3, 1.49, -0.75]]], 0.32)), belt, group).castShadow = false;
    const g = gun(geo, 'mega', MEGA, metal, 1, rig, muzzles, mk);
    g.position.set(0, 1.0, -1.2);
    group.add(g);
    return { rig, anchors: [[1.3, 0.85, -0.3], [-1.3, 0.85, -0.3]] };
  }

  const twin = branch === 'A';
  const heavyB = branch === 'B';
  const spec = heavyB ? (t5 ? LONG5 : LONG) : twin && t5 ? BASE5 : BASE;
  const key = `${heavyB ? 'long' : 'base'}${t5 ? '5' : ''}`;
  const xs = twin ? [-0.62, 0.62] : [0];
  for (const x of xs) {
    const g = gun(geo, key, spec, metal, x < 0 ? -1 : 1, rig, muzzles, mk);
    g.position.set(x, 0.72, -1.35);
    group.add(g);
  }
  // 弹箱（双联两侧各一个；5 级加大、再摞一层）+ 一条弧形弹带从弹箱顶接到机匣侧面
  const sides = twin ? [-1, 1] : [1];
  const bk = t5 ? 1.3 : 1;
  mk(geo.merged(`vul-feed-${twin ? "twin" : "one"}${t5 ? "5" : ""}`, () => sides.flatMap((s): PartSpec[] => [
    { geo: new THREE.BoxGeometry(0.62 * bk, 0.55 * bk, 0.8 * bk), color: 0x5a5a3a, pos: [s * 0.95, 0.83 + 0.275 * bk, 0.75] },
    { geo: new THREE.BoxGeometry(0.66 * bk, 0.08, 0.84 * bk), color: DARK, pos: [s * 0.95, 0.83 + 0.55 * bk + 0.04, 0.75] },
    // 黄铜供弹槽的两条边（弹带从中间走）
    ...[-1, 1].map((e): PartSpec => ({ geo: new THREE.BoxGeometry(0.03, 0.08, 0.95), color: BRASS, pos: [s * 0.7 + e * 0.13, 1.2 + (bk - 1) * 0.25, -0.15], rot: [0.25, 0, s * 0.25] })),
    ...(t5 ? [
      { geo: new THREE.BoxGeometry(0.56, 0.34, 0.46), color: 0x4e4e34, pos: [s * 0.95, 0.83 + 0.55 * bk + 0.25, 1.02] } as PartSpec,
      { geo: new THREE.BoxGeometry(0.12, 0.06, 0.26), color: DARK, pos: [s * 0.95, 0.83 + 0.55 * bk + 0.45, 1.02] } as PartSpec,
    ] : []),
  ])), metal, group);
  const top = 0.83 + 0.55 * bk + 0.08;
  mk(geo.get(`vul-belt-${twin ? 'twin' : 'one'}${t5 ? '5' : ''}`, () => beltGeo(sides.map((s): [number, number, number][] => {
    const x = twin ? s * 0.62 : 0;
    return [[s * 0.95, top, t5 ? 0.66 : 0.95], [s * 0.92, top + 0.04, t5 ? 0.3 : 0.4], [s * 0.72, top - 0.08, -0.15], [x + s * 0.3, 1.12, -0.75], [x + s * 0.16, 1.04, -1.15]];
  }), 0.2)), belt, group).castShadow = false;
  // 5 级重弹线：炮塔两侧加挂甲
  if (t5 && heavyB) {
    mk(geo.merged('vul-cheeks5', () => [-1, 1].flatMap((s): PartSpec[] => [
      { geo: new THREE.BoxGeometry(0.12, 0.56, 1.7), color: OLIVE_D, pos: [s * (w / 2 + 0.08), 0.47, -0.35], rot: [0, s * -0.06, s * 0.12] },
      ...[-0.9, -0.35, 0.2].map((z): PartSpec => ({ geo: new THREE.BoxGeometry(0.06, 0.08, 0.08), color: DARK, pos: [s * (w / 2 + 0.16), 0.62, z] })),
    ])), body, group);
  }
  return { rig, anchors: [[1.2, 0.85, -0.25], [-1.2, 0.85, -0.25]] };
}
