import { cleanBindings, KEY_DEFAULT, KEY_LABEL, KEY_NAMES, PAD_DEFAULT, PAD_LABEL, PAD_NAMES, type ControlBindings, type KeyAction, type PadAction } from '../core/controlBindings';

export function controlsHtml(raw?: ControlBindings): string {
  const value = cleanBindings(raw);
  const options = (entries: [string, string][], selected: string) => entries.map(([id, name]) => `<option value="${id}"${id === selected ? ' selected' : ''}>${name}</option>`).join('');
  return `<div class="control-settings"><h3>操作</h3><p>改动即时保存</p><h4>一号键盘</h4>
    ${(Object.keys(KEY_DEFAULT) as KeyAction[]).map(a => `<label>${KEY_LABEL[a]}<select data-key-action="${a}">${options(Object.entries(KEY_NAMES), value.keyboard?.[a] ?? KEY_DEFAULT[a])}</select></label>`).join('')}
    <h4>二号手柄</h4>
    ${(Object.keys(PAD_DEFAULT) as PadAction[]).map(a => `<label>${PAD_LABEL[a]}<select data-pad-action="${a}">${options(a === 'move' || a === 'aim' ? [['0', '左摇杆'], ['2', '右摇杆']] : PAD_NAMES.map((n, i) => [String(i), n]), String(value.gamepad?.[a] ?? PAD_DEFAULT[a]))}</select></label>`).join('')}
    <p>字母区按行从左数起</p><button type="button" data-controls-reset>恢复默认</button><button type="button" data-controls-back>返回</button></div>`;
}

export function bindControls(box: HTMLElement, raw: ControlBindings | undefined, save: (value: ControlBindings) => void, back: () => void): void {
  box.querySelectorAll<HTMLSelectElement>('select[data-key-action], select[data-pad-action]').forEach(select => {
    select.addEventListener('change', () => {
      const value = cleanBindings(raw);
      const key = select.dataset.keyAction as KeyAction | undefined;
      if (key) {
        const previous = value.keyboard?.[key] ?? KEY_DEFAULT[key];
        // 冲突时互换，保持每个动作都有键可用。
        for (const a of Object.keys(KEY_DEFAULT) as KeyAction[]) if (a !== key && (value.keyboard?.[a] ?? KEY_DEFAULT[a]) === select.value) value.keyboard![a] = previous;
        value.keyboard![key] = select.value;
      } else {
        const action = select.dataset.padAction as PadAction;
        const previous = value.gamepad?.[action] ?? PAD_DEFAULT[action];
        const axis = action === 'move' || action === 'aim';
        for (const a of Object.keys(PAD_DEFAULT) as PadAction[]) if (a !== action && (a === 'move' || a === 'aim') === axis && (value.gamepad?.[a] ?? PAD_DEFAULT[a]) === Number(select.value)) value.gamepad![a] = previous;
        value.gamepad![action] = Number(select.value);
      }
      save(value);
    });
  });
  box.querySelector('[data-controls-reset]')?.addEventListener('click', () => save({}));
  box.querySelector('[data-controls-back]')?.addEventListener('click', back);
}
