import { dayKey } from './day';
import type { DailyState } from './Profile';

/**
 * 每日任务（T030，策划 `T028-商业化运营策划案.md` 3.6）：每天凌晨 4 点刷新 3 项（易 / 中 / 难各一），按走到过的最远区域挑；
 * 每项 150 军功 + 军票 60 / 80 / 120，三项全完成再 +120；大部分「今天累计」、少数「单局」。换一个：每天免费 1 次 + 看广告 1 次。
 * 不做「看 N 次广告」「分享 N 次」「登录 N 天」「打 N 局」
 */

/** 本局统计的键（Game.taskStats 每次存档时给一份快照，累计的按增量加、单局的按本局最大值） */
export type TaskStat =
  | 'dist'
  | 'kills'
  | 'scenery'
  | 'crush'
  | 'barrels'
  | 'fires'
  | 'boss'
  | 'fuse'
  | 'link'
  | 'distCannon'
  | 'distRocket'
  | 'distLaser'
  | 'distVulcan'
  | 'elite'
  | 'subKills'
  | 'titan'
  | 'runKills'
  | 'ultKills'
  | 'fullBoss'
  | 'six'
  | 'siege';

export interface TaskDef {
  id: string;
  tier: 0 | 1 | 2;
  /** 卡上的一句话（{n} = 目标数） */
  text: string;
  n: number;
  stat: TaskStat;
  /** 单局（不累计）：本局达到就算 */
  single?: boolean;
  /** 走到过第几区才会抽到 */
  zone?: number;
  /** 要解锁了这个流派才会抽到 */
  core?: 'cannon' | 'rocket' | 'laser' | 'vulcan';
  /** 装配车间开到几个副武器槽才会抽到（T033：「装满 6 件」要先有 6 个槽） */
  slots?: number;
  icon: string;
}

export const TASK_TIER = ['易', '中', '难'];
export const TASK_REWARD = { merit: 150, ticket: [60, 80, 120], bonus: 120 };

