export const TASK_BY_ID = new Map(TASKS.map((t) => [t.id, t]));

export const taskText = (t: TaskDef) => t.text.replace('{n}', String(t.n));

/** 这一档能抽到的任务（按最远区域 / 已解锁的流派 / 副武器槽数），except = 不要的 id（换一个时别换回原来那个） */
function pool(tier: number, bestZone: number, cores: readonly string[], except: readonly string[], weaponSlots: number): TaskDef[] {
  return TASKS.filter((t) => t.tier === tier && (t.zone ?? 1) <= bestZone && (!t.core || cores.includes(t.core)) && (t.slots ?? 0) <= weaponSlots && !except.includes(t.id));
}

/** 新的一天：易 / 中 / 难各抽一项 */
export function rollDay(bestZone: number, cores: readonly string[], day = dayKey(), weaponSlots = 6): DailyState {
  const tasks = [0, 1, 2].map((tier) => {
    const p = pool(tier, bestZone, cores, [], weaponSlots);
    return { id: p[Math.floor(Math.random() * p.length)].id, n: 0, done: false };
  });
  return { day, tasks, freeSwap: false, adSwap: false, bonus: false };
}

/** 换掉第 i 项：同一档重抽（不换回原来那个），进度清零 */
export function swapTask(d: DailyState, i: number, bestZone: number, cores: readonly string[], weaponSlots = 6): boolean {
  const t = d.tasks[i];
  const def = t && TASK_BY_ID.get(t.id);
  if (!t || !def || t.done) return false;
  const p = pool(def.tier, bestZone, cores, d.tasks.map((x) => x.id), weaponSlots);
  if (!p.length) return false;
  d.tasks[i] = { id: p[Math.floor(Math.random() * p.length)].id, n: 0, done: false };
  return true;
}
