/**
 * 存档读写（T116）：Profile / ModeSave 只认 SaveStore，不直接碰 localStorage。
 * 现在只有一个实现 = 浏览器本地存储（微信小游戏里适配层把它接到微信本地存储）；
 * 以后 Steam（文件 + Steam 云）/ 微信云各加一个实现，建 Game 之前 setSaveStore 换掉，玩法代码不动。
 * slot = 存档槽：profile / modes，新手存档加 .newbie；落成文件就是 <slot>.json
 */
export interface SaveStore {
  read(slot: string): string | null;
  /** 存不下 / 不让存返回 false，不抛错 */
  write(slot: string, text: string): boolean;
  remove(slot: string): void;
}

/** 本地存储的键 = 前缀 + 槽名，和 T116 以前的键一样（tank-rogue.profile / tank-rogue.modes），老存档原地读 */
const PREFIX = 'tank-rogue.';

export const localStore: SaveStore = {
  read(slot) {
    try {
      return localStorage.getItem(PREFIX + slot);
    } catch {
      return null;
    }
  },
  write(slot, text) {
    try {
      localStorage.setItem(PREFIX + slot, text);
      return true;
    } catch {
      return false;
    }
  },
  remove(slot) {
    try {
      localStorage.removeItem(PREFIX + slot);
    } catch {
      /* 隐私模式 */
    }
  },
};

let store: SaveStore = localStore;
let locked = false;

/** 游戏里读写存档都走这个；导入写完以后锁住，重新载入之前再存什么都不写，免得把刚导入的盖掉 */
export const saveStore: SaveStore = {
  read: (slot) => store.read(slot),
  write: (slot, text) => !locked && store.write(slot, text),
  remove: (slot) => {
    if (!locked) store.remove(slot);
  },
};

/** 换存档实现（Steam / 微信云）：要在 Profile.load 之前调 */
export function setSaveStore(s: SaveStore): void {
  store = s;
}

/** 导入完、重新载入之前：后面的写入一律不落地 */
export function lockSaves(): void {
  locked = true;
}

/** 读档时的原始对象（老版本 / 导入文件，字段可能不全） */
export type RawSave = Record<string, unknown>;

/**
 * 迁移链（T116）：steps[v] 把版本 v 的存档升到 v + 1，读档 / 导入时逐级升到 to。key = 版本号字段名（Profile 是 version，ModeSave 是 v）。
 * 改存档结构 = 在 steps 里加一级、版本号 + 1；老版本的步骤不删
 */
export function migrate(d: RawSave, key: string, to: number, steps: Record<number, (d: RawSave) => RawSave>): RawSave {
  for (let v = d[key] as number; v < to; v = d[key] as number) {
    const step = steps[v];
    if (!step) throw new Error(`存档缺 ${key} ${v} → ${v + 1} 的迁移`);
    d = step(d);
  }
  return d;
}

/** 存档导出 / 导入要用的平台能力：网页 = 下载 / 剪贴板 / 选文件；以后 Steam 壳换系统对话框，小游戏换微信接口 */
export interface SaveIo {
  /** 存成文件（网页 = 浏览器下载） */
  download(name: string, text: string): void;
  /** 复制成文本，成功返回 true */
  copy(text: string): Promise<boolean>;
  /** 选一个文件读成文本：取消返回 null，读不出来返回空串 */
  pick(): Promise<string | null>;
  /** 导入以后重新载入游戏 */
  reload(): void;
}

/** 选文件的上限：存档几十 KB，超过 1 MB 的肯定不是 */
const MAX_FILE = 1 << 20;

/** 网页的导出 / 导入；小游戏包没有这些（返回 null，设置页不出「存档」一行） */
export function webSaveIo(): SaveIo | null {
  if (__WX__ || typeof document === 'undefined' || typeof document.createElement !== 'function') return null;
  return {
    download(name, text) {
      const url = URL.createObjectURL(new Blob([text], { type: 'application/json' }));
      const a = document.createElement('a');
      a.href = url;
      a.download = name;
      document.body.append(a);
      a.click();
      a.remove();
      // 立刻回收 Safari 会下载失败
      setTimeout(() => URL.revokeObjectURL(url), 30000);
    },
    async copy(text) {
      try {
        await navigator.clipboard.writeText(text);
        return true;
      } catch {
        /* 老浏览器 / 不是 https：退回 execCommand */
      }
      const ta = document.createElement('textarea');
      ta.value = text;
      ta.setAttribute('readonly', '');
      ta.style.cssText = 'position:fixed;left:-9999px;top:0;opacity:0';
      document.body.append(ta);
      ta.select();
      ta.setSelectionRange(0, text.length);
      let ok = false;
      try {
        ok = document.execCommand('copy');
      } catch {
        ok = false;
      }
      ta.remove();
      return ok;
    },
    pick() {
      return new Promise((done) => {
        const input = document.createElement('input');
        input.type = 'file';
        input.accept = '.json,.txt,application/json,text/plain';
        input.style.display = 'none';
        const end = (v: string | null) => {
          input.remove();
          done(v);
        };
        input.addEventListener('change', () => {
          const f = input.files?.[0];
          if (!f) return end(null);
          if (f.size > MAX_FILE) return end('');
          const r = new FileReader();
          r.onload = () => end(String(r.result ?? ''));
          r.onerror = () => end('');
          r.readAsText(f);
        });
        input.addEventListener('cancel', () => end(null));
        document.body.append(input);
        input.click();
      });
    },
    reload: () => location.reload(),
  };
}
