import { MODS, SUPER_MODS, type SuperModId } from '../weapons/defs';
import { SUPER_INFO } from './superFx';

/**
 * 作战时的「已选超级改装」栏（T251，制作人「战斗界面看不到已经选过什么」）：两套界面共用这里的文字和尺寸。
 * 收起 = 槽位条右边一条紫边小铁牌，按拿到的顺序摆六边形小图标，一列最多 4 个，满了往右再起一列；没选任何一件不出现。
 * 点一下展开详情（名字、类别、两条关键数值，取自 SUPER_INFO），再点一下收起，开着 8 秒也自动收起；点槽位条也收起。
 * 详情竖屏挂在槽位条下面一列；横屏挂在小铁牌右边两列，碰到右上按键就挪到按键下面
 */
export const SUPER_BAR = {
  /** 小图标宽 / 高、列距 / 行距、一列最多几个 */
  hexW: 14,
  hexH: 15,
  gapX: 3,
  gapY: 2,
  rows: 4,
  /** 上沿紫条高、四周留白（上留白算上紫条） */
  bar: 2,
  padTop: 5,
  pad: 4,
  /** 最小尺寸（触区不低于 28 × 44），离槽位条多远 */
  minW: 28,
  minH: 44,
  gap: 6,
  /** 展开后几秒自动收起 */
  hold: 8,
};

/** 详情：每列宽、列距、每行高、行距、标题行高、四周留白 */
export const SUPER_LIST = { colW: 190, colGap: 10, rowH: 32, rowGap: 4, head: 22, pad: 8 };

export interface SuperRow {
  id: SuperModId;
  name: string;
  cat: string;
  line: string;
}

export const superRows = (ids: readonly SuperModId[]): SuperRow[] =>
  ids.map((id) => ({ id, name: MODS[id].name, cat: SUPER_INFO[id].cat, line: SUPER_INFO[id].keys.join(' · ') }));

/** 详情标题：已拿几件，下一件在几级出（next = 0 = 八件都拿到了） */
export const superHead = (n: number, next: number): { title: string; sub: string } => ({
  title: `超级改装 ${n} / ${SUPER_MODS.length}`,
  sub: next > 0 ? `下一件 ${next} 级` : '已集齐',
});

/** 小铁牌的尺寸（逻辑像素）和第 i 个图标的左上角 */
export function superBarSize(n: number): { w: number; h: number; cols: number; rows: number } {
  const B = SUPER_BAR;
  const rows = Math.min(B.rows, Math.max(1, n));
  const cols = Math.max(1, Math.ceil(n / B.rows));
  const w = Math.max(B.minW, B.pad * 2 + cols * B.hexW + (cols - 1) * B.gapX);
  const h = Math.max(B.minH, B.padTop + B.pad + rows * B.hexH + (rows - 1) * B.gapY);
  return { w, h, cols, rows };
}

export function superBarCell(i: number, n: number): { x: number; y: number } {
  const B = SUPER_BAR;
  const { w, h, cols, rows } = superBarSize(n);
  const gw = cols * B.hexW + (cols - 1) * B.gapX;
  const gh = rows * B.hexH + (rows - 1) * B.gapY;
  const col = Math.floor(i / B.rows);
  const row = i % B.rows;
  return { x: (w - gw) / 2 + col * (B.hexW + B.gapX), y: B.padTop + (h - B.padTop - B.pad - gh) / 2 + row * (B.hexH + B.gapY) };
}

/**
 * 详情摆在哪（屏幕像素；s = 界面缩放）：竖屏在槽位条下面一列、宽不超过右上按键左沿；
 * 横屏在小铁牌右边两列（放不下两列就一列），和右上按键横向重叠时往下挪到按键下面 8 像素
 */
export function superListPlace(o: {
  n: number;
  landscape: boolean;
  s: number;
  barRight: number;
  slotsLeft: number;
  slotsTop: number;
  slotsBottom: number;
  railLeft: number;
  railBottom: number;
  screenRight: number;
}): { x: number; y: number; w: number; h: number; cols: number } {
  const L = SUPER_LIST;
  const { s } = o;
  const width = (cols: number) => L.pad * 2 + cols * L.colW + (cols - 1) * L.colGap;
  const height = (cols: number) => {
    const rows = Math.max(1, Math.ceil(o.n / cols));
    return L.pad * 2 + L.head + rows * L.rowH + (rows - 1) * L.rowGap;
  };
  if (!o.landscape) {
    const w = Math.min(width(1), (o.railLeft - 8 * s - o.slotsLeft) / s);
    return { x: o.slotsLeft, y: o.slotsBottom + 6 * s, w, h: height(1), cols: 1 };
  }
  const x = o.barRight + 6 * s;
  const cols = x + width(2) * s <= o.screenRight ? 2 : 1;
  const w = width(cols);
  const y = x + w * s > o.railLeft - 8 * s ? Math.max(o.slotsTop, o.railBottom + 8 * s) : o.slotsTop;
  return { x, y, w, h: height(cols), cols };
}
