/** 整备台的作战压板：小切角、铜色顶面、下缘承重。 */
function launchButton(g: Ctx, w: number, h: number, label: string, sub = '', secondary = false, pressed = false): void {
  const bw = Math.min(296, w - 32), x = (w - bw) / 2, y = pressed ? 2 : 0;
  const fill = g.createLinearGradient(x, y, x + bw, y + h);
  fill.addColorStop(0, secondary ? '#29383b' : '#e1c695');
  fill.addColorStop(1, secondary ? '#202c30' : '#b99862');
  g.fillStyle = fill;
  g.beginPath(); g.moveTo(x + 4, y); g.lineTo(x + bw, y); g.lineTo(x + bw, y + h - 4);
  g.lineTo(x + bw - 4, y + h); g.lineTo(x, y + h); g.lineTo(x, y + 4); g.closePath(); g.fill();
  g.fillStyle = secondary ? '#647375' : '#5e4b2b'; g.fillRect(x, y + h - 3, bw - 4, 3);
  g.font = font(secondary ? 16 : 17, 900);
  text(g, label, w / 2, y + h / 2 - (sub ? 8 : 0), secondary ? '#c4b79b' : '#172326', 'center', 5);
  if (sub) {
    g.font = font(10);
    text(g, sub, w / 2, y + h / 2 + 13, secondary ? '#a1b1ad' : '#4b4839', 'center');
  }
}

