import * as THREE from 'three';
import type { Enemy } from '../entities/Enemy';
import type { Bullet } from '../systems/Bullets';
import { MAT } from '../assets/materials';
import { angleTo, type CombatContext } from './behaviors';
import { ARMOR_MULT, CORE_MAX, CORE_STATS, CORES, type Branch, type CoreDef, type CoreId, type ModStats } from './defs';
import { rng } from '../game/rng';
import { AmmoRefund, RateStack } from './superMods';

/** 影响玩法的随机走「我方武器」流（T117，可设种子）；只管好看的照用 Math.random */
const fireRand = (a: number, b: number) => a + rng.weapon() * (b - a);
const wrap = (a: number) => {
  while (a > Math.PI) a -= Math.PI * 2;
  while (a < -Math.PI) a += Math.PI * 2;
  return a;
};

/**
 * 开火画面后坐（T134，制作人「主炮的开火可以稍微加一点画面后坐力」）：[画面顶出去多少度, 回到 5% 以内的秒数]，走 ctx.recoil（CameraRig.recoil）。
 * 越猛越明显：雷霆 / 地毯 > 榴弹 > 没分支 / 穿甲 > 千钧起手 > 脉冲 / 火箭齐射 / 重弹线起手；twin2 = 雷霆第二发。
 * 激光光束、火神轻弹是持续开火，照旧只有嗡震
 */
export const RECOIL_KICK = {
  cannon: [0.55, 0.2],
  ap: [0.55, 0.17],
  howitzer: [0.65, 0.22],
  carpet: [0.8, 0.24],
  twin: [0.85, 0.26],
  twin2: [0.55, 0.22],
  salvo: [0.3, 0.18],
  pulse: [0.35, 0.16],
  heavy: [0.3, 0.16],
  heavyUlt: [0.5, 0.2],
} satisfies Record<string, [deg: number, settle: number]>;

/**
 * 流派核心：装在炮塔上的主炮，只在玩家点按 / 按住时开火。
 * 弹匣（能量格）自动装填，点一下打一发；3 级选分支（A / B），6 级 + 指定改装件 = 终极形态。
 */
export abstract class Core {
  level = 1;
  branch: Branch | null = null;
  ultimate = false;
  /** 当前装填好的发数（带小数 = 正在装填的那一发） */
  rounds = 0;
  /** 点一下会打向的目标（锁定框 / 瞄准线用） */
  target: Enemy | null = null;
  /** 是否画瞄准线（火箭只画锁定框） */
  showLine = true;
  /** 手指按住开火中（由游戏层每帧写入，激光持续输出用） */
  holding = false;
  /** 本局终极累计发出的脉冲数（诊断 / 测试用；目前只有激光 B 终极「脉冲长枪」在用，换核心时随新实例清零） */
  pulses = 0;
  /** 脚下光环按连续能量条显示（激光），否则按一段一发 */
  readonly continuous: boolean = false;
  protected extra = 0;
  readonly ammoRefund = new AmmoRefund();
  private loaded = false;
  protected readonly v = new THREE.Vector3();
  protected readonly w = new THREE.Vector3();

  constructor(readonly def: CoreDef) {}

  get id(): CoreId {
    return this.def.id;
  }

  get maxed(): boolean {
    return this.level >= CORE_MAX;
  }

  /** 弹匣容量（无尽弹仓额外加） */
  get maxRounds(): number {
    return this.baseRounds() + this.extra;
  }

  get ready(): boolean {
    return this.rounds >= 1;
  }

  /** 脚下光环显示的弹量（火神：正在打的那段跟着剩余发数往下掉） */
  get gauge(): number {
    return this.rounds;
  }

  /** 下一发还要多久装好（秒，有弹 = 0；T018-1「不抢主炮」：0.5 秒内会开火的目标副武器让给主炮） */
  readyIn(mods: ModStats): number {
    if (this.rounds >= 1) return 0;
    return (1 - this.rounds) * this.reload() * mods.cooldown / (this.id === 'laser' ? 1 : mods.rate);
  }

  /** 按住开火（激光、火神）：经典触屏手指按住不动 0.18 秒开火、开局提示「按住发射」 */
  get holdFire(): boolean {
    return this.continuous;
  }

  /** 脚下光环：0 一段一发 / 1 连续能量条（激光）/ 2 连续弹药条（火神，gauge 是剩几成） */
  get ring(): number {
    return this.continuous ? 1 : 0;
  }

  /** 光环上的刻度（火神重弹一梭一格；0 = 不画） */
  get ringTicks(): number {
    return 0;
  }

  /** 光环空着闪（火神打空、按补弹速度打） */
  get ringDry(): boolean {
    return false;
  }

  /** 正在持续开火（激光光束）时炮塔不跟随锁定目标 */
  get busy(): boolean {
    return false;
  }

  /** 正在出光时光束的方向（炮塔约定角）；不在出光 / 不是激光为 null（天火拖动落点、极光翼阵用） */
  get beamDir(): number | null {
    return null;
  }

  /** 激光光束阶段：0 蓝 / 1 紫 / 2 金（不是激光为 0；极光光带宽度和颜色跟着走） */
  get beamStage(): number {
    return 0;
  }

  /** 激光出光中正在烧的目标（A1 锁点开火时锁的那个 / B2 换过去的那个；被击毁也照样返回，由游戏层判断）；不在出光为 null */
  get beamTarget(): Enemy | null {
    return null;
  }

  /** 激光出光中的锁点（地面世界坐标，T016 A1）；不在出光为 null */
  get beamLock(): { x: number; z: number } | null {
    return null;
  }

  /** 激光主光束连续多久没打中敌人（秒；B1 提前收光用） */
  get beamMiss(): number {
    return 0;
  }

  /** 出光中换目标（B2，自动开火时目标被击毁）：锁点挪到它脚下，光束阶段保留 */
  retarget(_e: Enemy): void {}

  /** 提前收光（B1）：剩下的能量留着 */
  stopBeam(): void {}

  protected abstract baseRounds(): number;
  protected abstract reload(): number;
  /** 开火：angle 为炮塔约定角 */
  protected abstract shoot(ctx: CombatContext, angle: number, target: Enemy | null): void;
  /** 每帧的持续效果（火箭依次发射、光束持续） */
  protected tick(_ctx: CombatContext): void {}

  update(ctx: CombatContext): void {
    this.extra = this.id === 'rocket' ? 0 : ctx.mods.count;
    const max = this.maxRounds;
    if (this.rounds < max) {
      // 只取基础射速倍率，连射层数不参与装填。
      const k = ctx.mods.cooldown / ctx.mods.rate;
      const before = Math.floor(this.rounds);
      this.rounds = Math.min(max, this.rounds + ctx.dt / (this.reload() * k));
      if (Math.floor(this.rounds) > before) this.loaded = true;
    }
    this.tick(ctx);
  }

  protected markLoaded(): void {
    this.loaded = true;
  }

  /** 刚装好一发（上膛声 / 光环闪一下），读一次就清掉 */
  consumeLoaded(): boolean {
    const v = this.loaded;
    this.loaded = false;
    return v;
  }

  /** 平时炮塔跟着锁定目标转，点按时就不用再等炮塔转过去 */
  /** angle：没有目标时炮塔朝向，默认正前方 */
  aimAt(ctx: CombatContext, target: Enemy | null, angle = 0): void {
    this.target = target;
    if (this.busy) return;
    const P = ctx.tank.group.position;
    const want = target ? angleTo(P.x, P.z, target.group.position.x, target.group.position.z) : angle;
    this.turn(ctx, want, 6);
  }

  /** 扫射：持续开火中按住的手指左右移动（d：弧度，正数向右）。只有激光用 */
  sweep(_d: number): void {}

  /** 电脑鼠标按住出光（汇总第 63 条）：光束改成「按方向」——方向只由 steer 给，坦克横移 / 前进都不转。只有激光用 */
  holdDir(): void {}

  /** 电脑鼠标按住出光时，鼠标指的方向（炮塔约定角：0 = 正前方，正值向左）。只有激光用 */
  steer(_angle: number): void {}

  /** 返回是否开火（弹匣空了返回 false） */
  fire(ctx: CombatContext, angle: number, target: Enemy | null): boolean {
    if (!this.ready) return false;
    this.rounds -= 1;
    // 目标在天上（T091）：这一下出膛的炮弹走打天那一层
    ctx.bullets.aim = target;
    this.shoot(ctx, angle, target);
    if (this.ammoRefund.consume(1, 1, ctx.mods.count > 0)) {
      this.rounds = Math.min(this.maxRounds, this.rounds + 1);
      this.markLoaded();
      ctx.ammoReturn?.();
    }
    ctx.bullets.aim = null;
    return true;
  }

  /** 终极特种弹（炼狱弹）：不扣弹匣、不重置装填；只有主炮流有，其余返回 null */
  ultShell(_ctx: CombatContext, _angle: number, _speed: number, _range: number): Bullet | null {
    return null;
  }

  reset(): void {
    this.ammoRefund.reset();
    this.target = null;
    this.rounds = this.maxRounds;
  }

  /** 炮塔朝世界角 angle 转（T127：每秒最多 TURRET.slew，转不过去的地方绕前面、限位外停在限位上），返回转完的世界角 */
  protected turn(ctx: CombatContext, angle: number, rate: number): number {
    const t = ctx.tank;
    t.turnTurret(angle - t.group.rotation.y, rate, ctx.dt);
    return t.group.rotation.y + t.turret.rotation.y;
  }
}

// ======================================================================
// 主炮流：长管重炮。点一下一发重炮
// ======================================================================

/**
 * 榴弹线直接砸中倍率（T016 D2，制作人 2026-10-13 拍板「全按默认」）：被炮弹砸中的那个目标吃 榴弹伤害 × 1.5（= 1.8 × 基础伤害）、
 * 不按爆炸距离打折；溅射到的其他人照旧按距离打折。目标：榴弹打精英 ≈ 穿甲线的 1.3～1.4 倍时间
 */
const HOWITZER_DIRECT = 1.5;

class CannonCore extends Core {
  /** 双联重炮第二发的延迟 */
  private second = -1;
  private secondAngle = 0;
  private secondTarget: Enemy | null = null;

  protected baseRounds(): number {
    return CORE_STATS.cannon.rounds(this.level);
  }

  protected reload(): number {
    return CORE_STATS.cannon.reload(this.level);
  }

  protected shoot(ctx: CombatContext, angle: number, target: Enemy | null): void {
    if (this.ultimate && this.branch === 'A') {
      // 雷霆重炮：双联装，两发特大号穿甲弹先后出膛
      this.shell(ctx, angle, 0);
      this.second = 0.13;
      this.secondAngle = angle;
      this.secondTarget = target;
      return;
    }
    this.shell(ctx, angle, 0);
  }

  protected override tick(ctx: CombatContext): void {
    if (this.second < 0) return;
    this.second -= ctx.dt;
    if (this.second <= 0) {
      this.second = -1;
      ctx.bullets.aim = this.secondTarget?.alive && ctx.canElevate(this.secondTarget) ? this.secondTarget : null;
      this.shell(ctx, this.secondAngle, 1);
      ctx.bullets.aim = null;
    }
  }

  private shell(ctx: CombatContext, angle: number, muzzle: number): void {
    const st = CORE_STATS.cannon;
    const L = this.level;
    const pos = ctx.tank.muzzleWorld(muzzle, this.v);
    const dx = -Math.sin(angle);
    const dz = -Math.cos(angle);
    const mega = this.ultimate && this.branch === 'A';
    const dmg = st.damage(L) * (this.branch === 'B' ? 1.2 : mega ? 1.25 : 1);
    // 没选分支：4.5 米大爆炸；穿甲线：一路贯穿，每个命中点炸开小爆炸；榴弹线：更大的爆炸
    const radius = this.branch === 'A' ? 0 : (this.branch === 'B' ? st.blast(L) : 4.5) * ctx.mods.area;
    const speed = this.branch === 'A' ? 120 : 95;
    const b = ctx.bullets.spawn(mega ? 'mega' : 'heavy', pos.x, pos.z, dx * speed, dz * speed, dmg, true, radius);
    // 射程 100 米：打不到画面外、还没亮血条的敌人；巨炮在场时放到对轰射程（D5 A1）
    b.life = Math.max(100, ctx.duel) / speed;
    b.dtype = 'shell';
    b.ap = this.branch === 'A';
    b.pierce = mega ? 99 : this.branch === 'A' ? st.pierce(L) + ctx.mods.count : 0;
    b.splash = this.branch === 'A' ? (mega ? 4 : 2.6) * ctx.mods.area : 0;
    b.knock = this.branch === 'B' ? 14 : mega ? 13 : 9;
    b.bomblets = this.ultimate && this.branch === 'B' ? 4 : 0;
    b.grenade = this.branch === 'B';
    // 榴弹线（含地毯炮击主弹）直接砸中 = 重击：被砸中的目标吃 1.5 倍、不按爆炸距离打折（T016 D2）
    b.direct = this.branch === 'B' ? HOWITZER_DIRECT : 0;
    b.show = true;
    if (b.grenade) this.lob(ctx, b, pos.x, pos.z, dx, dz, radius, speed);
    ctx.tank.kick(mega ? 1.4 : 1);
    // 开炮后坐（T134）：画面朝车尾顶一下。原来是日常档随机抖 0.3 / 0.45（T017-15A 从 0.55 / 0.8 下调），按强度平方算镜头只挪几厘米，看不出来
    const kick = mega ? (muzzle ? RECOIL_KICK.twin2 : RECOIL_KICK.twin) : this.branch === 'B' ? (this.ultimate ? RECOIL_KICK.carpet : RECOIL_KICK.howitzer) : this.branch === 'A' ? RECOIL_KICK.ap : RECOIL_KICK.cannon;
    ctx.recoil(dx, dz, ...kick);
    ctx.punch(mega ? 0.85 : 0.6);
    ctx.fx.muzzle(pos.x, pos.y, pos.z, dx, dz, mega ? 2.8 : this.branch === 'B' ? 2.2 : 1.9);
    ctx.audio.play(mega ? 'bigboom' : 'charge');
  }

  /**
   * 榴弹画面抛物线（T247，只管画）：目标在弹道线上就按它的距离抛、落点出我方浅黄圈；没有目标按 45 米抛、不出圈。
   * 判定照旧贴地平飞、碰到什么炸什么
   */
  private lob(ctx: CombatContext, b: Bullet, x: number, z: number, dx: number, dz: number, radius: number, speed: number): void {
    const t = ctx.bullets.aim;
    const p = t && !t.flying ? t.group.position : null;
    const along = p ? (p.x - x) * dx + (p.z - z) * dz : 0;
    const hit = !!p && along > 4 && Math.abs((p.x - x) * dz - (p.z - z) * dx) < radius + t!.radius + 1;
    ctx.bullets.lob(b, hit ? along : 45);
    if (hit) ctx.hazards.marker(x + dx * along, z + dz * along, radius, along / speed, 'self');
  }

  /**
   * 炼狱弹：从尾部弹药箱直接上膛的特种弹，复用出膛流程（炮口火光、后坐、开炮声），不扣弹匣、不重置装填；
   * 雷霆（双联）从左炮管打出一发。弹本身不带伤害，第一次碰到东西时交给终极模块（ultShell → onShellHit）
   */
  override ultShell(ctx: CombatContext, angle: number, speed: number, range: number): Bullet {
    const pos = ctx.tank.muzzleWorld(0, this.v);
    const dx = -Math.sin(angle);
    const dz = -Math.cos(angle);
    const b = ctx.bullets.spawn('inferno', pos.x, pos.z, dx * speed, dz * speed, 0, true);
    b.life = range / speed;
    b.ultShell = true;
    ctx.tank.kick(1.3);
    ctx.shake(0.7);
    ctx.punch(0.8);
    ctx.fx.muzzle(pos.x, pos.y, pos.z, dx, dz, 2.6);
    ctx.fx.flash(pos.x, pos.y, pos.z, 1800);
    ctx.audio.play('bigboom');
    return b;
  }

  override reset(): void {
    super.reset();
    this.second = -1;
  }
}

// ======================================================================
// 火箭流：火箭炮塔。点一下一轮齐射
// ======================================================================

interface Launch {
  delay: number;
  target: Enemy | null;
  i: number;
  tx: number;
  tz: number;
  /** 伤害倍率（贴脸的锁定目标打折） */
  k: number;
}

/**
 * 喀秋莎（集束线终极）：每轮比集束线多 12 枚，单发 ×1.35、爆炸半径 4.5 米（仍怕重甲，重甲留给温压弹）；
 * 覆盖瞄准点 group 米内的敌人（普通火箭 16 米），火控按血量分配（allot），高抛弹落在分到的目标身边 spread 米内
 */
const KATYUSHA = { extra: 12, damage: 1.35, radius: 4.5, spread: 4, group: 22 };

/**
 * 齐射分配：火箭分散到瞄准点 group 米内（喀秋莎 KATYUSHA.group）的一群敌人；瞄准点近于 full 米时按同一扇面角度收窄
 * （最窄 floor 倍），近处的目标集中火力。min 米内的敌人分不到火箭，但锁定的目标一定有火箭朝它去；
 * 锁定目标在 min 米内时引信来不及解除保险，伤害 × close（火箭不适合贴脸）
 */
const SALVO = { group: 16, full: 25, floor: 0.3, min: 6, close: 0.5 };

/**
 * 温压弹（重型穿甲线终极）落点火场的每秒燃烧伤害（× 燃料罐）。火焰统一按 fire 结算后（拍板 1-8）火对重甲 ×0.5：
 * 策划案说超了就从 12 提到 14，实测 14 打单辆中坦一轮还是 −14.6%（标准靶 −14%），提到 21 才回到 −4.3%（标准靶 −1.7%），满足「下降 ≤ 5%」
 */
const THERMO_NAPALM = 21;

class RocketCore extends Core {
  readonly rateStack = new RateStack();
  private readonly queue: Launch[] = [];
  override showLine = false;

  protected baseRounds(): number {
    return CORE_STATS.rocket.rounds(this.level);
  }

  protected reload(): number {
    return CORE_STATS.rocket.reload(this.level);
  }

  protected shoot(ctx: CombatContext, angle: number, target: Enemy | null): void {
    const st = CORE_STATS.rocket;
    const P = ctx.tank.group.position;
    // 瞄准点：锁定目标，或者沿点按方向 45 米处
    const ax = target ? target.group.position.x : P.x - Math.sin(angle) * 45;
    const az = target ? target.group.position.z : P.z - Math.cos(angle) * 45;
    const katyusha = this.ultimate && this.branch === 'A';
    // 火箭分散到瞄准点周围的一群敌人（见 SALVO）：锁定目标排第一个（离瞄准点 0 米），一定分到火箭
    const reach = Math.hypot(ax - P.x, az - P.z);
    const spread = (katyusha ? KATYUSHA.group : SALVO.group) * THREE.MathUtils.clamp(reach / SALVO.full, SALVO.floor, 1);
    const group = ctx.enemies
      .filter((e) => {
        if (!e.alive) return false;
        if (e === target) return true;
        const d = Math.hypot(e.group.position.x - P.x, e.group.position.z - P.z);
        return d > SALVO.min && Math.hypot(e.group.position.x - ax, e.group.position.z - az) < spread;
      })
      .sort((a, b) => Math.hypot(a.group.position.x - ax, a.group.position.z - az) - Math.hypot(b.group.position.x - ax, b.group.position.z - az));
    const close = target && reach < SALVO.min ? SALVO.close : 1;
    let n = st.count(this.level) + ctx.mods.count * 2;
    if (this.branch === 'A') n = Math.round(n * 1.5) + (this.ultimate ? KATYUSHA.extra : 0);
    if (this.branch === 'B') n = Math.ceil(n / 2);
    const order = katyusha && group.length ? this.allot(group, n, this.warhead(ctx), target) : null;
    for (let i = 0; i < n; i++) {
      const t = order ? order[i] : group.length ? group[i % group.length] : null;
      this.queue.push({ delay: i * (this.branch === 'A' ? 0.04 : 0.06), target: t, i, tx: t ? t.group.position.x : ax + fireRand(-5, 5), tz: t ? t.group.position.z : az + fireRand(-5, 5), k: t && t === target ? close : 1 });
    }
    // 齐射后坐（T134，原来日常档随机抖 0.3）
    ctx.recoil(-Math.sin(angle), -Math.cos(angle), ...RECOIL_KICK.salvo);
    ctx.tank.kick(0.4);
  }

  /** 每发火箭的伤害与爆炸半径 */
  private warhead(ctx: CombatContext): { dmg: number; radius: number } {
    const dmg = CORE_STATS.rocket.damage(this.level);
    if (this.branch === 'B') return { dmg: dmg * 3.6, radius: (this.ultimate ? 6 : 4) * ctx.mods.area };
    if (this.branch !== 'A') return { dmg, radius: 3.0 * ctx.mods.area };
    if (this.ultimate) return { dmg: dmg * KATYUSHA.damage, radius: KATYUSHA.radius * ctx.mods.area };
    return { dmg: dmg * 0.75, radius: 2.6 * ctx.mods.area };
  }

  /**
   * 喀秋莎火控：从血厚的开始每个目标先分一发（血少、又站在已分到火箭的目标爆炸范围里的，靠溅射就够，不单独占一发；
   * 锁定的目标例外，一定直接分到），剩下的按「已分到 / 击毁要几发」最低的继续分，都够了再按比例摊开
   */
  private allot(group: Enemy[], n: number, { dmg, radius }: { dmg: number; radius: number }, lock: Enemy | null): Enemy[] {
    // 每发按平均 75% 伤害估算
    const per = group.map((e) => dmg * ARMOR_MULT[e.armor].blast * 0.75);
    const need = group.map((e, j) => Math.max(1, Math.ceil(e.hp / per[j])));
    const got = group.map(() => 0);
    const out: Enemy[] = [];
    const byHp = group.map((_, j) => j).sort((a, b) => Number(group[b] === lock) - Number(group[a] === lock) || group[b].hp - group[a].hp);
    for (const j of byHp) {
      if (out.length >= n) break;
      const e = group[j];
      if (e !== lock && e.hp < per[j] * 0.6 && out.some((t) => Math.hypot(t.group.position.x - e.group.position.x, t.group.position.z - e.group.position.z) < radius * 0.6 + e.radius)) {
        got[j] = need[j];
        continue;
      }
      got[j]++;
      out.push(e);
    }
    while (out.length < n) {
      const open = got.some((g, j) => g < need[j]);
      let best = -1;
      for (let j = 0; j < group.length; j++) {
        if (open && got[j] >= need[j]) continue;
        if (best < 0 || got[j] / need[j] < got[best] / need[best]) best = j;
      }
      got[best]++;
      out.push(group[best]);
    }
    return out;
  }

  protected override tick(ctx: CombatContext): void {
    const rate = this.rateStack.factor(ctx.mods.rate, ctx.time);
    for (let k = this.queue.length - 1; k >= 0; k--) {
      const q = this.queue[k];
      q.delay -= ctx.dt * rate;
      if (q.delay > 0) continue;
      this.queue.splice(k, 1);
      this.rateStack.fire(1, ctx.time, ctx.mods.rate);
      const p = ctx.tank.muzzleWorld(q.i, this.v);
      const { dmg: base, radius } = this.warhead(ctx);
      const dmg = base * q.k;
      // 弹坑档位（T016-1）：重型穿甲 / 温压弹中坑，集束 / 喀秋莎小坑，没选分支的普通火箭不挖坑
      const pit = this.branch === 'B' ? 2 : this.branch === 'A' ? 1 : 0;
      const opts = { ap: this.branch === 'B', knock: this.branch === 'B' ? 11 : 7, napalm: this.ultimate && this.branch === 'B' ? THERMO_NAPALM : 0, show: true, pit } as const;
      if (this.ultimate && this.branch === 'A') {
        const a = rng.weapon() * Math.PI * 2;
        const r = Math.sqrt(rng.weapon()) * KATYUSHA.spread;
        const tx = (q.target?.alive ? q.target.group.position.x : q.tx) + Math.cos(a) * r;
        const tz = (q.target?.alive ? q.target.group.position.z : q.tz) + Math.sin(a) * r;
        // 分到天上目标的（T105：直升机、「云垒」部件）落在它那个高度、在它身上空爆，地上不画落点圈；原来一律落到地面，天上的一个都打不到
        const sky = q.target?.alive && q.target.flying ? q.target : null;
        // 24 枚的落点圈叠成一片，只画一半（省绘制次数）
        const s = ctx.projectiles.shell(p.x, p.y, p.z, tx, tz, fireRand(0.9, 1.3), fireRand(24, 32), dmg, radius, { ...opts, noMarker: !!sky || q.i % 2 === 1 }, false, 'rocket');
        if (sky) {
          s.target = sky;
          s.ty = sky.group.position.y;
        }
      } else {
        const a = rng.weapon() * Math.PI * 2;
        ctx.projectiles.rocket(p.x, p.y, p.z, Math.cos(a) * 5, fireRand(7, 11), Math.sin(a) * 3 - 6, q.target?.alive ? q.target : null, dmg, radius, opts, this.branch === 'B', q.tx, q.tz);
      }
      ctx.tank.kick(0.12);
      ctx.fx.glow.emit({ x: p.x, y: p.y, z: p.z, life: 0.1, size: 1.8, color: 0xffd090, frame: 0 });
      ctx.fx.smoke(p.x, p.y, p.z, 0.9, 1.0, 0xb0a898, 0.5);
      ctx.audio.play('rocket');
    }
  }

  override reset(): void {
    super.reset();
    this.queue.length = 0;
    this.rateStack.reset();
  }
}

/** 激光升阶的时间点（秒）：按住 0.9 秒变紫，1.9 秒变金 */
const LASER_STAGE = [0.9, 1.9];
/** 点一下（或按住马上松开）至少输出这么久（秒） */
const LASER_MIN_BURST = 0.3;
/** 光棱开火声（S10）：起光放原调；升到紫 / 金阶再响一声、变调更高（按阶序号取，0 不用）、音量 ×PRISM_STAGE_VOL */
const PRISM_STAGE_RATE = [1, 1.12, 1.26];
const PRISM_STAGE_VOL = 0.65;
/** 扫射：光束最多偏离正前方这么多（弧度，和主炮点按方向的上限一致） */
const SWEEP_MAX = 1.2;
/** 光束跟手的炮塔转速（越小转动越有惯性） */
const BEAM_TURN = 12;
/**
 * A1 锁点（T016-3，制作人 2026-10-13「全按默认」）：开火时记下光束打到的地面点（有目标 = 目标脚下，没有 = 沿方向 ahead 米），
 * 之后每帧光束从炮塔指向这一点——坦克横移 / 前进时炮塔自己转回去对准，**不追敌人**（目标跑了光束不跟）；扫射挪的是这个点（按角度换算，手感不变）；
 * 离坦克不到 min 米就不再转、超出 SWEEP_MAX 限位就停在限位上。retarget = B2 换目标后这么多秒内用 snap 的转速转过去（0.15 秒到位）
 */
const LOCK = { ahead: 45, min: 6, retarget: 0.15, snap: 22 };
/**
 * 折射（汇总第 64 条「激光不穿透」）：range = 折射够得着多远（米，原来就是 13）；shadow = 主目标身后的「影子」有多宽——横向离它不到「它的半径 + 对方半径 × shadow」
 * 而且在它身后（顺着光的方向）的被它挡着、折不过去；scatter = 一道都折不出去时命中点分叉出的两道散射光（偏开 angle ± jitter/2 弧度、长 len 米，只是样子）
 */
const REFRACT = { range: 13, shadow: 0.5, scatter: { angle: 0.75, jitter: 0.25, len: 5 } };
/** 炉脊光矛镜片的发光：出光时是晶体的几成（镜片面积大，满亮会糊成一块）/ 不出光时（暗青色，看得出镜片的同心带） */
const LENS_GLOW = 0.5;
const LENS_IDLE = 0.1;
/** 三阶光束：颜色 / 粗细 / 伤害倍率（dmgB 为聚焦线） */
const LASER_LOOK = [
  { core: 0xf0faff, glow: 0x46c8ff, width: 1, dmg: 1, dmgB: 1 },
  { core: 0xfbe8ff, glow: 0xb45cff, width: 1.35, dmg: 1.7, dmgB: 1.9 },
  { core: 0xfffbe8, glow: 0xffb43a, width: 1.75, dmg: 2.6, dmgB: 3.0 },
];

/**
 * 脉冲长枪（聚焦线终极）：按住满 after 秒发第 1 发，之后每 gap 秒一发（满级按满一次 2.8 秒发 3 发）。
 * 一发脉冲沿发射那一刻的光束方向跑完整条光束（85 米 / 0.35 秒），线上的敌人各挨一次 dps × dmg × 透镜，
 * 前沿每 cutEvery 米切开一次沿线的掩体 / 路障 / 残骸（友方掩体不炸）
 */
const PULSE = { after: 1.0, gap: 0.8, dmg: 0.45, speed: 243, widthMul: 2.2, knock: 8, cutEvery: 5, cutR: 1.6, cutForce: 6 };

// ======================================================================
// 激光流：光棱炮塔。按住开始输出，手指不抬就一直输出、左右移动扫射；按得越久越粗越痛，命中后折射
// ======================================================================

/** 一发在飞的脉冲（脉冲长枪）：起点 / 方向 / 起始高度在发射那一刻确定，不跟着炮塔走 */
interface PulseShot {
  active: boolean;
  /** 起点（发射那一刻的炮口） */
  x: number;
  z: number;
  y: number;
  dx: number;
  dz: number;
  /** 前沿离起点的距离（米） */
  front: number;
  /** 已经切到第几个 cutEvery 米 */
  cuts: number;
  /** 这一发已经结算过的敌人（同一发对每个敌人只结算一次） */
  readonly hit: Set<Enemy>;
  /** 这一发已经切过的路边景物 */
  readonly scn: Set<object>;
}

class LaserCore extends Core {
  override readonly continuous = true;
  /** 0..1：剩余可输出能量 */
  private energy = 1;
  private beam = false;
  private held = 0;
  private beamAngle = 0;
  private tickT = 0;
  /** 距离下一发脉冲的时间（按住累计） */
  private pulseT = 0;
  /** 在飞的脉冲，最多 2 条（发射间隔 0.8 秒 > 飞行 0.35 秒，正常只有 1 条） */
  private readonly shots: PulseShot[] = Array.from({ length: 2 }, () => ({ active: false, x: 0, z: 0, y: 0, dx: 0, dz: -1, front: 0, cuts: 0, hit: new Set<Enemy>(), scn: new Set<object>() }));
  private readonly hits: Enemy[] = [];
  private readonly from = new THREE.Vector3();
  /** 当前光束阶段：0 蓝 / 1 紫 / 2 金 */
  private stage = 0;
  /** A1 锁点（地面世界坐标）、锁的目标（开火时 / B2 换过去的）、坦克位置（扫射换算锁点用） */
  private readonly lock = { x: 0, z: 0 };
  private lockTarget: Enemy | null = null;
  private tankPos: THREE.Vector3 | null = null;
  /** B2 换目标后的快速转向剩余时间 */
  private snapT = 0;
  /** 主光束连续多久没打中敌人 */
  private missT = 0;
  /** 这一跳已经被折射光打到的（同一个敌人一跳只挨一道，主目标也在里面，折射光不往回打） */
  private readonly lit = new Set<Enemy>();
  /** 主目标和主光束方向（汇总第 64 条：主目标身后「影子」里的，哪一层折射光都打不到） */
  private shade: Enemy | null = null;
  private shadeX = 0;
  private shadeZ = -1;
  /** 光束实际的世界朝向（炮塔约定角，按惯性追 beamAngle） */
  private aimWorld = 0;
  /** 这一束是在扫射限位外起的光（T127：自动瞄准打侧后方 / 身后的目标），锁点跟着走不夹限位 */
  private wide = false;
  /** 按方向出光（汇总第 63 条，电脑鼠标按住）：光束方向只听 steer，锁点每帧跟着坦克挪（不再钉在地面点上让炮塔转回去） */
  private dirMode = false;
  /** 命中点（T070）：烧着的那辆车、连续照了多久，烧金属特效的发射计时 */
  private heatOn: Enemy | null = null;
  private heatT = 0;
  private readonly burnAcc = { spark: 0, drip: 0, red: 0, smoke: 0 };
  /** 画出来的光束终点（车壳表面 / 地面） */
  private readonly hitPt = { x: 0, y: 0, z: 0 };

  /** 光束升阶：炮口爆闪一下 */
  private stageUp(ctx: CombatContext, stage: number): void {
    const m = ctx.tank.muzzleWorld(0, this.v);
    ctx.fx.glow.emit({ x: m.x, y: m.y, z: m.z, life: 0.25, size: 4 + stage * 2, size1: 1, color: LASER_LOOK[stage].core, frame: 0 });
    ctx.fx.sparks(m.x, m.y, m.z, 10, LASER_LOOK[stage].glow, 9);
    ctx.shake(0.25);
    // 升阶：同一声光棱开火，一阶比一阶高、轻一点（棱镜共鸣往上走）
    ctx.audio.play('prism', PRISM_STAGE_VOL, PRISM_STAGE_RATE[stage]);
  }

  protected baseRounds(): number {
    return 1;
  }

  override get maxRounds(): number {
    return 1;
  }

  protected reload(): number {
    return CORE_STATS.laser.recharge(this.level);
  }

  /** 能量至少两成才能开始输出 */
  override get ready(): boolean {
    return !this.beam && this.energy >= 0.2;
  }

  override get busy(): boolean {
    return this.beam;
  }

  override get beamDir(): number | null {
    return this.beam ? this.beamAngle : null;
  }

  override get beamStage(): number {
    return this.stage;
  }

  override get beamTarget(): Enemy | null {
    return this.beam ? this.lockTarget : null;
  }

  override get beamLock(): { x: number; z: number } | null {
    return this.beam ? this.lock : null;
  }

  override get beamMiss(): number {
    return this.beam ? this.missT : 0;
  }

  override retarget(e: Enemy): void {
    if (!this.beam) return;
    this.dirMode = false;
    this.lockTarget = e;
    this.lock.x = e.group.position.x;
    this.lock.z = e.group.position.z;
    this.snapT = LOCK.retarget;
    this.missT = 0;
  }

  override stopBeam(): void {
    this.beam = false;
  }

  private get output(): number {
    return CORE_STATS.laser.output(this.level) + this.extra * 0.4;
  }

  override update(ctx: CombatContext): void {
    this.extra = ctx.mods.count;
    if (!this.beam && this.energy < 1) {
      const k = ctx.mods.cooldown;
      this.energy = Math.min(1, this.energy + ctx.dt / (this.reload() * k));
      if (this.energy >= 1) this.markLoaded();
    }
    this.rounds = this.energy;
    this.tick(ctx);
    // 镜片亮度和颜色跟着光束阶段走
    MAT.prism.emissiveIntensity = this.beam ? 0.9 + this.stage * 0.5 : 0.7;
    MAT.prism.emissive.setHex(this.beam ? LASER_LOOK[this.stage].glow : LASER_LOOK[0].glow);
    MAT.prismLens.emissiveIntensity = this.beam ? MAT.prism.emissiveIntensity * LENS_GLOW : LENS_IDLE;
    MAT.prismLens.emissive.copy(MAT.prism.emissive);
  }

  override fire(ctx: CombatContext, angle: number, target: Enemy | null): boolean {
    if (!this.ready) return false;
    this.beam = true;
    this.held = 0;
    this.tickT = 0;
    this.pulseT = 0;
    this.beamAngle = angle;
    this.wide = Math.abs(wrap(angle)) > SWEEP_MAX;
    this.aimWorld = ctx.tank.group.rotation.y + ctx.tank.turret.rotation.y;
    this.stage = 0;
    this.snapT = 0;
    this.missT = 0;
    this.dirMode = false;
    this.heatOn = null;
    this.heatT = 0;
    // A1 锁点：有目标 = 目标脚下，没有 = 沿开火方向 45 米
    const P = ctx.tank.group.position;
    this.tankPos = P;
    this.lockTarget = target?.alive ? target : null;
    this.lock.x = this.lockTarget ? this.lockTarget.group.position.x : P.x - Math.sin(angle) * LOCK.ahead;
    this.lock.z = this.lockTarget ? this.lockTarget.group.position.z : P.z - Math.cos(angle) * LOCK.ahead;
    ctx.audio.play('prism');
    return true;
  }

  protected shoot(): void {}

  /**
   * 扫射：按住的手指左右移动挪的是锁点——绕坦克转 d 弧度、距离不变（手感和原来转光束一样）；
   * 起始方向在限位外（侧面的首领部件）时只允许往回扫
   */
  override sweep(d: number): void {
    if (!this.beam || d === 0) return;
    const a = this.beamAngle;
    this.beamAngle = THREE.MathUtils.clamp(a - d, Math.min(-SWEEP_MAX, a), Math.max(SWEEP_MAX, a));
    const P = this.tankPos;
    if (!P) return;
    const r = Math.max(LOCK.min, Math.hypot(this.lock.x - P.x, this.lock.z - P.z));
    this.lock.x = P.x - Math.sin(this.beamAngle) * r;
    this.lock.z = P.z - Math.cos(this.beamAngle) * r;
  }

  override holdDir(): void {
    if (this.beam) this.dirMode = true;
  }

  override steer(angle: number): void {
    if (!this.beam) return;
    this.dirMode = true;
    this.beamAngle = THREE.MathUtils.clamp(angle, -SWEEP_MAX, SWEEP_MAX);
  }

  /** A1：光束方向 = 坦克指向锁点（离坦克不到 LOCK.min 米就不转、超出限位停在限位上）；按方向出光时反过来，锁点跟着坦克按方向挪 */
  private steerToLock(ctx: CombatContext): void {
    const P = ctx.tank.group.position;
    this.tankPos = P;
    if (this.dirMode) {
      const r = Math.max(LOCK.min, Math.hypot(this.lock.x - P.x, this.lock.z - P.z));
      this.lock.x = P.x - Math.sin(this.beamAngle) * r;
      this.lock.z = P.z - Math.cos(this.beamAngle) * r;
      return;
    }
    const dx = this.lock.x - P.x;
    const dz = this.lock.z - P.z;
    if (Math.hypot(dx, dz) < LOCK.min) return;
    const a = this.beamAngle;
    // 朝锁点那边连着转，锁点跨过正后方也不翻到另一侧（T127）；限位外起的光（侧后方的目标）跟着锁点走，不夹
    const want = a + wrap(Math.atan2(-dx, -dz) - a);
    this.beamAngle = this.wide ? wrap(want) : THREE.MathUtils.clamp(want, Math.min(-SWEEP_MAX, a), Math.max(SWEEP_MAX, a));
  }

  protected override tick(ctx: CombatContext): void {
    // 在飞的脉冲不跟着光束走：松手 / 扫开以后照样跑完剩下的路
    this.stepPulses(ctx);
    if (!this.beam) return;
    // 松手（点射至少打满 LASER_MIN_BURST）或能量打空就停
    if ((!this.holding && this.held >= LASER_MIN_BURST) || this.energy <= 0) {
      this.beam = false;
      if (this.energy <= 0) {
        const m = ctx.tank.muzzleWorld(0, this.v);
        ctx.fx.steam(m.x, m.y + 0.4, m.z);
        ctx.audio.play('steam');
      }
      return;
    }
    const st = CORE_STATS.laser;
    this.held += ctx.dt;
    this.energy = Math.max(0, this.energy - ctx.dt / this.output);
    if (this.ammoRefund.consume(ctx.dt, 1, ctx.mods.count > 0)) {
      this.energy = this.rounds = 1;
      this.markLoaded();
      ctx.ammoReturn?.();
    }
    // 持续输出越久光束越高阶：蓝 → 紫 → 金，每升一阶伤害大涨（能量槽短的低等级激光打不到高阶）
    const fast = this.branch === 'B' ? 0.8 : 1;
    const stage = this.held < LASER_STAGE[0] * fast ? 0 : this.held < LASER_STAGE[1] * fast ? 1 : 2;
    if (stage > this.stage) this.stageUp(ctx, stage);
    this.stage = stage;
    const look = LASER_LOOK[stage];
    const ramp = stage > 0 ? 1 : Math.min(1, this.held / (LASER_STAGE[0] * fast));
    // A1 锁点：光束钉在开火时的地面点上（坦克走位炮塔自己转回去），不追敌人；按住的手指左右扫挪的是这个点（炮塔有转动惯性）
    // 锁的是空中目标（T091）：锁点跟着它走，光束画到它的高度，只打天上那一层、不被路障 / 房子挡
    let sky = this.lockTarget?.alive && this.lockTarget.flying ? this.lockTarget : null;
    // 照着的飞到头顶、超过激光的仰角（T131）：松开它，光束留在原来的方向打地上那一层
    if (sky && !ctx.canElevate(sky)) {
      ctx.tooHigh(sky);
      this.lockTarget = sky = null;
    }
    if (sky && !this.dirMode) {
      this.lock.x = sky.group.position.x;
      this.lock.z = sky.group.position.z;
    }
    this.steerToLock(ctx);
    this.snapT = Math.max(0, this.snapT - ctx.dt);
    // 炮塔稳定：光束按世界朝向追 beamAngle（有惯性），车身走位时的偏航不带着光束甩（原来按炮塔相对角追，换向那一下光束甩开 0.2 弧度、40 米外偏 8 米）
    this.aimWorld += wrap(this.beamAngle - this.aimWorld) * Math.min(1, ctx.dt * (this.snapT > 0 ? LOCK.snap : BEAM_TURN));
    // 车尾挂件挡着的地方转不进去（T127）
    this.aimWorld = ctx.tank.clampAim(this.aimWorld);
    ctx.tank.turret.rotation.y = this.aimWorld - ctx.tank.group.rotation.y;
    const angle = this.aimWorld;
    const ult = this.ultimate;
    const width = st.width(this.level) * (0.7 + ramp * 0.3) * look.width * (ult && this.branch === 'A' ? 1.4 : 1);
    const dps = st.dps(this.level) * (0.6 + ramp * 0.4) * (this.branch === 'B' ? look.dmgB : look.dmg);
    const o = ctx.tank.muzzleWorld(0, this.from);
    const dx = -Math.sin(angle);
    const dz = -Math.cos(angle);
    this.tickT -= ctx.dt;
    const doHit = this.tickT <= 0;
    if (doHit) this.tickT = 0.06;
    const dmg = dps * 0.06;
    const opts = { type: 'energy' as const, kind: 'energy' as const, show: true, burn: this.level >= 5 ? 3 : 0, beam: true };

    // 主光束（汇总第 64 条）：所有分支都打到第一个敌人为止——像普通炮弹一样被前面的挡住，前面的被摧毁了才烧到后面的
    // （原来聚焦线一路贯穿整条线、线上每个都挨满额）
    let len = Math.max(85, ctx.duel);
    let first: Enemy | null = null;
    for (const e of ctx.enemies) {
      if (!e.alive || e.flying !== !!sky) continue;
      if (e.hull) {
        // 首领本体的实体外形（T048，巨炮）：光束停在外墙上（原来停在中心的投影处，墙里 20 米）
        const c = e.hull.cross(o.x, o.z, o.x + dx * len, o.z + dz * len);
        if (!c) continue;
        len *= c.t;
        first = e;
        continue;
      }
      // 照天上的（T098）：直升机按机身 / 短翼 / 平尾的外形，光束第一次碰到的地方
      if (sky && e.spec.foot) {
        const a = e.airRay(o.x, o.z, dx, dz, width / 2, len);
        if (a < 0) continue;
        len = a;
        first = e;
        continue;
      }
      const px = e.group.position.x - o.x;
      const pz = e.group.position.z - o.z;
      const along = px * dx + pz * dz;
      if (along < 0 || along > len || Math.abs(px * dz - pz * dx) > width / 2 + e.radius) continue;
      len = along;
      first = e;
    }
    // 路上的路障 / 掩体（T017-14「材质 × 武器」）：车辆照够烧成空壳、再照切两截，木头点着，油桶引爆；完好的路障挡光束、烧穿了照过去（聚焦线一直穿过去）；
    // 钢铁厂的烟囱 / 储罐挡光束、照塌 / 照炸（T032 A1）
    const prop = sky ? len : ctx.beamProps(o.x, o.z, dx, dz, len, width, stage, this.branch === 'B', ctx.dt, ctx.mods.energy, dps * ctx.mods.energy);
    let blocked = !!sky;
    if (prop < len - 0.05) {
      len = prop;
      first = null;
      blocked = true;
    }
    // 路边景物：树 / 杆接触够时间切断（T032 A2：照到就点着），光束停在房墙上、按光束伤害掉结构照塌（T032 A1；聚焦线穿过房子、两面墙都留切痕）
    const wall = sky ? len : ctx.scenery.beam(o.x, o.z, dx, dz, len, width, stage, this.branch === 'B', ctx.dt, dps);
    if (wall < len - 0.05) {
      len = wall;
      first = null;
      blocked = true;
    }
    const ex = o.x + dx * len;
    const ez = o.z + dz * len;
    // 命中点脚下的草（T032 A2）：打在敌人身上、或者照到头落在空地上，脚下是草地就点着（停在墙 / 路障 / 烟囱上的不算）
    if (!blocked) ctx.groundHeat(ex, ez, ctx.dt);
    // 光束停在车壳表面（T070）：打谁、打多少照上面算，画出来的光束停在车身包围盒外面（原来停在中心，重坦 / 铁壁扎进去 2～3 米）；
    // 光斑高度在车身一半、大小不超过车高（金阶光晕不再从车顶冒出来）；首领外墙上面已经停在墙上
    const shell = first && !first.hull && !sky ? first.beamHit(o.x, o.z, dx, dz) : null;
    const metal = !!shell || !!first?.hull;
    const vlen = shell ? Math.max(0.3, Math.min(len, shell.t - 0.05)) : len;
    const hit = this.hitPt;
    hit.x = o.x + dx * vlen;
    hit.z = o.z + dz * vlen;
    hit.y = shell && first ? first.group.position.y + THREE.MathUtils.clamp(shell.top * 0.5, 0.6, 1.4) : first ? 1.4 : 1.0;
    if (sky) {
      // 打天上：画到它的高度；没打中（被它旁边的挡了 / 偏了）就按这个仰角接着往上
      const reach = Math.max(1, Math.hypot(sky.group.position.x - o.x, sky.group.position.z - o.z));
      hit.y = first ? first.group.position.y + first.aimLift : o.y + ((sky.group.position.y + sky.aimLift - o.y) * vlen) / reach;
    }
    ctx.streaks.add(o.x, o.y, o.z, hit.x, hit.y, hit.z, width * 0.45, look.core, 1, 0.05);
    ctx.streaks.add(o.x, o.y, o.z, hit.x, hit.y, hit.z, width * 1.6, look.glow, 0.45, 0.05, metal ? -0.01 : 0);
    ctx.fx.glow.emit({ x: o.x, y: o.y, z: o.z, life: 0.05, size: 1.2 + width * 1.5, color: look.core, frame: 0 });
    if (doHit && first) ctx.damage(first, dmg, o.x, o.z, opts);
    this.missT = first ? 0 : this.missT + ctx.dt;
    if (metal && first) {
      if (first !== this.heatOn) this.heatT = 0;
      this.heatOn = first;
      this.heatT += ctx.dt;
    } else this.heatT = Math.max(0, this.heatT - ctx.dt * 2);
    // 光棱折射：从命中点射向附近的敌人（聚焦线照旧不折射）；被主目标自己挡在身后的不折过去，折射光一路上也会被挡（见 refract）
    if (first) {
      // 命中点（T070）：车辆 = 白热光斑 + 火花 + 熔滴，照 0.6 秒起发红冒烟、2.4 秒最红；步兵照旧
      if (metal) ctx.fx.beamBurn(hit.x, hit.y, hit.z, -dx, -dz, THREE.MathUtils.clamp((this.heatT - 0.6) / 1.8, 0, 1), Math.min(0.5 + width * 0.8, (shell ? shell.top : 2.8) * 0.75), ctx.dt, this.burnAcc);
      else {
        ctx.fx.glow.emit({ x: ex, y: sky ? hit.y : 1.4, z: ez, life: 0.06, size: 1.6 + width * 2, color: look.core, frame: 0 });
        if (Math.random() < 0.4) ctx.fx.sparks(ex, sky ? hit.y : 1.4, ez, sky ? 4 : 2, look.glow, 6);
      }
      if (this.branch !== 'B') {
        const n = st.bounces(this.level) + (this.branch === 'A' ? 3 : 0) + (ult && this.branch === 'A' ? 4 : 0);
        this.lit.clear();
        this.lit.add(first);
        this.shade = first;
        this.shadeX = dx;
        this.shadeZ = dz;
        if (!this.refract(ctx, first, dx, dz, n, width * 0.5, dmg * 0.55, doHit, this.branch === 'A' ? 1 : 0, opts, look, hit)) this.scatter(ctx, hit, dx, dz, width, look, !!shell);
      }
    }
    // 脉冲长枪：按住满 1 秒发第 1 发，之后每 0.8 秒沿整条光束打出一发（点射不发）
    if (ult && this.branch === 'B') {
      this.pulseT += ctx.dt;
      if (this.pulseT >= PULSE.after) {
        this.pulseT -= PULSE.gap;
        this.launchPulse(ctx, o, angle);
      }
    }
    // 持续嗡震（T017-15A）：蓝 / 紫 / 金 0.12 / 0.16 / 0.2，平滑趋近，不再每帧叠加（原来 60 帧时按住 1 秒就顶到上限）
    ctx.hum(0.12 + stage * 0.04);
  }

  /** 发一发脉冲：起点（炮口）和方向在这一刻确定，之后不跟着炮塔 / 目标走 */
  private launchPulse(ctx: CombatContext, o: THREE.Vector3, angle: number): void {
    const s = this.shots.find((p) => !p.active);
    if (!s) return; // 最多 2 条在飞
    s.active = true;
    s.x = o.x;
    s.z = o.z;
    s.y = o.y;
    s.dx = -Math.sin(angle);
    s.dz = -Math.cos(angle);
    s.front = 0;
    s.cuts = 0;
    s.hit.clear();
    s.scn.clear();
    this.pulses += 1;
    // 炮口闪光 + 火花 + 后坐（T134，原来日常档随机抖 0.15）
    ctx.fx.glow.emit({ x: o.x, y: o.y, z: o.z, life: 0.15, size: 3.4, size1: 1, color: 0xffffff, frame: 0 });
    ctx.fx.sparks(o.x, o.y, o.z, 12, 0xffd070, 10);
    ctx.recoil(s.dx, s.dz, ...RECOIL_KICK.pulse);
    ctx.audio.play('zap');
  }

  /** 在飞的脉冲：前沿每帧扫过的那一段结算敌人，每 5 米切开一次沿线的障碍 */
  private stepPulses(ctx: CombatContext): void {
    const st = CORE_STATS.laser;
    const w = st.width(this.level) * PULSE.widthMul;
    const dmg = st.dps(this.level) * PULSE.dmg;
    const opts = { type: 'energy' as const, knock: PULSE.knock, show: true };
    for (const s of this.shots) {
      if (!s.active) continue;
      const prev = s.front;
      s.front = Math.min(Math.max(85, ctx.duel), s.front + PULSE.speed * ctx.dt);
      // 离脉冲线不超过半宽 + 半径的敌人各挨一次（击退方向 = 脉冲线方向）
      for (const e of ctx.enemies) {
        if (!e.alive || s.hit.has(e)) continue;
        const px = e.group.position.x - s.x;
        const pz = e.group.position.z - s.z;
        const along = px * s.dx + pz * s.dz;
        if (along < prev || along > s.front || Math.abs(px * s.dz - pz * s.dx) > w / 2 + e.radius) continue;
        s.hit.add(e);
        ctx.damage(e, dmg, e.group.position.x - s.dx, e.group.position.z - s.dz, opts);
      }
      // 路边景物（T009 第 8 节）：前沿这一帧扫过的那一段，线上的树 / 杆同一高度切断、房屋两面墙留切痕（每发对每件只切一次）
      ctx.scenery.slice(s.x + s.dx * prev, s.z + s.dz * prev, s.dx, s.dz, s.front - prev, w, s.scn);
      // 切开障碍（路障 / 掩体 / 残骸）：每过 5 米一次（一发 17 次），友方掩体不炸
      while ((s.cuts + 1) * PULSE.cutEvery <= s.front) {
        s.cuts += 1;
        ctx.cut(s.x + s.dx * s.cuts * PULSE.cutEvery, s.z + s.dz * s.cuts * PULSE.cutEvery, PULSE.cutR, PULSE.cutForce);
      }
      // 视觉：一颗 6 米长的白金色光弹往前跑，前沿身后 12 米那条线跟着变粗（0.1 秒淡出）
      const at = (d: number) => ({ x: s.x + s.dx * d, y: s.y + (1.2 - s.y) * (d / 85), z: s.z + s.dz * d });
      const f = at(s.front);
      const tail = at(Math.max(0, s.front - 6));
      ctx.streaks.add(tail.x, tail.y, tail.z, f.x, f.y, f.z, w, 0xffffff, 1, 0.05);
      ctx.streaks.add(tail.x, tail.y, tail.z, f.x, f.y, f.z, w * 2.4, 0xffcf6a, 0.4, 0.05);
      const thick = at(Math.max(0, s.front - 12));
      ctx.streaks.add(thick.x, thick.y, thick.z, f.x, f.y, f.z, w * 1.6, 0xffffff, 0.5, 0.1);
      ctx.fx.glow.emit({ x: f.x, y: f.y, z: f.z, life: 0.05, size: 1.6 + w, color: 0xffffff, frame: 0 });
      if (s.front >= 85) s.active = false;
    }
  }

  /**
   * 折射：从 src 射向最近的 n 个敌人（REFRACT.range 米内）；depth > 0 时每道折射光还会再折射一次。返回折出去了几道。
   * 遮挡（汇总第 64 条）：①src 自己身后的「影子」里（顺着入射方向 (inX, inZ) 在它后面、横向离得近）的不折过去，主目标身后影子里的哪一层折射都打不到——被它挡着，等它被摧毁了主光束才烧得到；
   * ②每道折射光也会被挡：射过去的路上先碰到谁就打谁；③同一跳里一个敌人只挨一道（lit，主目标也算，折射光不往回打）
   */
  private refract(ctx: CombatContext, src: Enemy, inX: number, inZ: number, n: number, width: number, dmg: number, doHit: boolean, depth: number, opts: Parameters<CombatContext['damage']>[4], look: (typeof LASER_LOOK)[number], from?: { x: number; y: number; z: number }): number {
    const sx = src.group.position.x;
    const sz = src.group.position.z;
    // 画出来的折射光从哪儿出发（T070：第一层从车壳上的命中点，判定照旧按车中心）
    const fx = from?.x ?? sx;
    const fy = from?.y ?? (src.flying ? src.group.position.y + src.aimLift : 1.4);
    const fz = from?.z ?? sz;
    const R = REFRACT;
    this.hits.length = 0;
    for (const e of ctx.enemies) {
      if (!e.alive || this.lit.has(e) || e.flying !== src.flying) continue;
      const ex = e.group.position.x - sx;
      const ez = e.group.position.z - sz;
      if (Math.hypot(ex, ez) >= R.range) continue;
      if (this.shaded(src, inX, inZ, e) || (this.shade && this.shaded(this.shade, this.shadeX, this.shadeZ, e))) continue;
      this.hits.push(e);
    }
    this.hits.sort((a, b) => Math.hypot(a.group.position.x - sx, a.group.position.z - sz) - Math.hypot(b.group.position.x - sx, b.group.position.z - sz));
    const done: Enemy[] = [];
    for (const aim of this.hits.slice(0, n)) {
      // 这道光射过去的路上先碰到谁就打谁
      const ax = aim.group.position.x - sx;
      const az = aim.group.position.z - sz;
      const len = Math.hypot(ax, az) || 1;
      const ux = ax / len;
      const uz = az / len;
      let t = aim;
      let best = len;
      for (const e of ctx.enemies) {
        if (!e.alive || e === aim || e === src || e.flying !== src.flying) continue;
        const px = e.group.position.x - sx;
        const pz = e.group.position.z - sz;
        const along = px * ux + pz * uz;
        if (along <= 0 || along >= best || Math.abs(px * uz - pz * ux) > width / 2 + e.radius) continue;
        best = along;
        t = e;
      }
      if (this.lit.has(t)) continue;
      this.lit.add(t);
      done.push(t);
      const tx = t.group.position.x;
      const tz = t.group.position.z;
      const ty = t.flying ? t.group.position.y + t.aimLift : 1.3;
      ctx.streaks.add(fx, fy, fz, tx, ty, tz, Math.max(0.12, width * 0.5), look.core, 0.95, 0.05);
      ctx.streaks.add(fx, fy, fz, tx, ty, tz, Math.max(0.3, width * 1.4), look.glow, 0.4, 0.05);
      if (doHit) ctx.damage(t, dmg, sx, sz, opts);
    }
    if (depth > 0) {
      for (const t of done) {
        if (!t.alive) continue;
        const ix = t.group.position.x - sx;
        const iz = t.group.position.z - sz;
        const il = Math.hypot(ix, iz) || 1;
        this.refract(ctx, t, ix / il, iz / il, 1, width * 0.7, dmg * 0.6, doHit, depth - 1, opts, look);
      }
    }
    return done.length;
  }

  /** e 在 src 身后的「影子」里（顺着光的方向 (inX, inZ) 在它后面、横向离得近）：被 src 挡着 */
  private shaded(src: Enemy, inX: number, inZ: number, e: Enemy): boolean {
    const ex = e.group.position.x - src.group.position.x;
    const ez = e.group.position.z - src.group.position.z;
    return ex * inX + ez * inZ > 0 && Math.abs(ex * inZ - ez * inX) < src.radius + e.radius * REFRACT.shadow;
  }

  /** 一道都折不出去（汇总第 64 条：身后的都被它挡着）：命中点照样分叉出两道短短的散射光（REFRACT.scatter，不伤人），棱镜的样子还在 */
  private scatter(ctx: CombatContext, p: { x: number; y: number; z: number }, dx: number, dz: number, width: number, look: (typeof LASER_LOOK)[number], bounce = false): void {
    const S = REFRACT.scatter;
    const { x, y, z } = p;
    // 打在车壳上（T070）：往回斜着弹开，不再往车里钻
    const base = bounce ? Math.atan2(-dx, -dz) : Math.atan2(dx, dz);
    const spread = bounce ? S.angle + 0.5 : S.angle;
    for (const s of [-1, 1]) {
      const a = base + s * (spread + (Math.random() - 0.5) * S.jitter);
      const l = S.len * (0.8 + Math.random() * 0.4);
      const ex = x + Math.sin(a) * l;
      const ez = z + Math.cos(a) * l;
      ctx.streaks.add(x, y, z, ex, y - 0.4, ez, Math.max(0.1, width * 0.22), look.core, 0.8, 0.05);
      ctx.streaks.add(x, y, z, ex, y - 0.4, ez, Math.max(0.25, width * 0.7), look.glow, 0.3, 0.05);
    }
  }

  override reset(): void {
    super.reset();
    this.energy = 1;
    this.rounds = 1;
    this.beam = false;
    for (const s of this.shots) s.active = false;
  }
}

/** 主炮 / 火箭 / 激光（火神在 vulcan.ts，Arsenal 按 id 选） */
export function createCore(id: Exclude<CoreId, 'vulcan'>): Core {
  const def = CORES[id];
  switch (id) {
    case 'cannon': return new CannonCore(def);
    case 'rocket': return new RocketCore(def);
    case 'laser': return new LaserCore(def);
  }
}
