import type { SceneryId } from './themes';

/** 景物的材质：决定碎片、颜色、声音、能不能烧、吃爆炸的系数 */
export type ScnMat = 'wood' | 'veg' | 'brick' | 'stone' | 'steel' | 'sand';

/** 破坏方式（T009 4.1）：扫 / 贯 / 爆 / 烧 / 切 / 电 / 压；爆·顶 = blast + top */
export type ScnVerb = 'small' | 'pierce' | 'blast' | 'fire' | 'cut' | 'shock' | 'crush';

export type ScnKind = Exclude<SceneryId, 'crater'>;

/**
 * 每种景物的占地与结构（尺寸都是缩放 1 时的，乘实例缩放）：
 * r = 圆形占地半径（树和杆是树干 / 杆身半径）；hw / hd = 矩形占地半宽 / 半深；h = 高度；hp = 结构值（Infinity = 不会坏）；
 * block = 挡直射：all = 敌我都挡（房屋 / 残楼 / 砖墙 / 巨石 / 车壳），player = 只挡玩家的炮弹和机枪（树干、杆身），none = 不挡
 */
export interface ScnMeta {
  mat: ScnMat;
  hp: number;
  r?: number;
  hw?: number;
  hd?: number;
  h: number;
  block: 'all' | 'player' | 'none';
  /** 树冠 / 屋顶的半径（爆·顶判定） */
  canopy?: number;
}

