  pole: { mat: 'wood', hp: 6, r: 0.2, h: 9.5, block: 'player' },
  house: { mat: 'brick', hp: 45, hw: 3.6, hd: 2.9, h: 6, block: 'all', canopy: 3.6 },
  ruin: { mat: 'brick', hp: 30, hw: 4, hd: 3.5, h: 6, block: 'all' },
  wall: { mat: 'brick', hp: 16, hw: 3.1, hd: 0.3, h: 3.6, block: 'all' },
  bush: { mat: 'veg', hp: 4, r: 1.3, h: 1.6, block: 'none' },
  hedge: { mat: 'veg', hp: 6, hw: 2.1, hd: 0.9, h: 1.8, block: 'none' },
  sandbag: { mat: 'sand', hp: 10, r: 2, h: 1, block: 'none' },
  hay: { mat: 'veg', hp: 3, r: 1.6, h: 1.9, block: 'none' },
  log: { mat: 'wood', hp: 8, hw: 3, hd: 0.55, h: 0.9, block: 'none' },
