import * as THREE from 'three';

const VERT = /* glsl */ `
attribute vec3 iPos;
attribute vec4 iColor;
attribute vec3 iMisc; // x = size, y = rotation, z = frame
varying vec2 vUv;
varying vec4 vColor;
void main() {
  float s = sin(iMisc.y);
  float c = cos(iMisc.y);
  vec2 p = position.xy * iMisc.x;
  vec4 mv = modelViewMatrix * vec4(iPos, 1.0);
  mv.xy += vec2(p.x * c - p.y * s, p.x * s + p.y * c);
  gl_Position = projectionMatrix * mv;
  vUv = vec2((uv.x + iMisc.z) * 0.5, uv.y);
  vColor = iColor;
}`;

const FRAG = /* glsl */ `
uniform sampler2D map;
varying vec2 vUv;
varying vec4 vColor;
void main() {
  vec4 t = texture2D(map, vUv);
  float a = t.a * vColor.a;
  if (a < 0.004) discard;
  gl_FragColor = vec4(vColor.rgb * t.rgb, a);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}`;

export interface EmitOpts {
  x: number;
  y: number;
  z: number;
  vx?: number;
  vy?: number;
  vz?: number;
  life: number;
  size: number;
  /** 结束时的尺寸，默认等于 size */
  size1?: number;
  color: number;
  /** 结束时的颜色，默认等于 color */
  color1?: number;
  alpha?: number;
  /** 0 = 柔光点，1 = 烟团 */
  frame?: number;
  rot?: number;
  spin?: number;
  /** 速度阻尼（每秒衰减比例） */
  drag?: number;
  /** 竖直加速度（烟往上飘为正，碎屑下落为负） */
  gravity?: number;
  /** 高烟柱（T027-c 巨弹落地）：飘到 CLEAR_SMOKE.tallY 米以上就不再按近身清烟变淡（挡不住坦克，柱子要看得出有多高） */
  tall?: boolean;
  /** 撑住（T057 蘑菇云的云帽 / 烟柱）：前大半段一直是浓的，最后一截才淡掉（不撑 = 一出来就线性变淡） */
  hold?: boolean;
}

/**
 * 实例化广告牌粒子：一次 draw call 画完所有粒子。
 * additive 用于火光、火花、能量；alpha 用于烟尘。
 */
/**
 * 近身清烟（T017-15c）：坦克周围 r 米内、以及镜头到坦克那条视线（地面投影）两侧 w 米内的烟变淡（远处的不变）；外面再留 fade 米过渡。
 * D4 / 汇总第 59 条（制作人 2026-10-13「近距离的烟雾效果可以进一步减弱，不然看不清画面」）在 T017-15c 的基础上再稀一层：
 * 一冒出来就只有 k0（原来刚冒出来那一下是满的），寿命 from → to 之间再降到 k（原来 0.4 → 0.6 降到 0.4）
 */
export const CLEAR_SMOKE = { r: 12, w: 8, k0: 0.6, k: 0.2, fade: 4, from: 0.2, to: 0.5, tallY: 12 };

/** 实例属性只传前 n 个（T245：池子按最多同时几颗开，平时只用一小段） */
export function uploadHead(a: THREE.InstancedBufferAttribute, n: number): void {
  a.clearUpdateRanges();
  a.addUpdateRange(0, n * a.itemSize);
  a.needsUpdate = true;
}

export class Particles {
  /** 近身清烟的中心（坦克）和镜头的地面投影；null = 不清（火光粒子） */
  clearZone: { x: number; z: number; cx: number; cz: number } | null = null;
  /**
   * 烟团寿命倍率（T036 无尽模式 0.7，制作人「无尽模式下战场的烟雾会消散的快 30%，不然太乱遮挡视野」）：发射时乘进寿命，只管烟团贴图（frame 1）
   * 而且不往下掉的（烟 / 尘 / 烟幕 / 烟柱 / 蘑菇云）；大小、浓度、数量都不动（照样长到 size1，只是更快长满、更早散掉）；
   * 往下掉的土块 / 碎叶（gravity < 0）、柔光点（飘灰、飞进车里的铁屑）、巨弹的高烟柱（tall）照旧
   */
  lifeMul = 1;
  readonly mesh: THREE.Mesh;
  private readonly cap: number;
  /** 这一档最多同时几颗（T245 按画质，≤ cap；调小时多出来的照常活完） */
  private limit: number;
  /** 满了以后从这里往后看一小段、顶掉其中最老的（不再每发一颗扫一遍整个池子） */
  private cursor = 0;
  private count = 0;
  // 每个粒子的状态（SoA）
  private readonly px: Float32Array;
  private readonly py: Float32Array;
  private readonly pz: Float32Array;
  private readonly vx: Float32Array;
  private readonly vy: Float32Array;
  private readonly vz: Float32Array;
  private readonly age: Float32Array;
  private readonly life: Float32Array;
  private readonly s0: Float32Array;
  private readonly s1: Float32Array;
  private readonly c0: Float32Array;
  private readonly c1: Float32Array;
  private readonly a0: Float32Array;
  private readonly rot: Float32Array;
  private readonly spin: Float32Array;
  private readonly drag: Float32Array;
  private readonly grav: Float32Array;
  private readonly frame: Float32Array;
  private readonly tall: Uint8Array;
  private readonly hold: Uint8Array;
  // GPU 属性
  private readonly aPos: THREE.InstancedBufferAttribute;
  private readonly aColor: THREE.InstancedBufferAttribute;
  private readonly aMisc: THREE.InstancedBufferAttribute;
  private readonly geometry: THREE.InstancedBufferGeometry;
  private readonly tmpA = new THREE.Color();
  private readonly tmpB = new THREE.Color();

  constructor(scene: THREE.Scene, map: THREE.Texture, additive: boolean, capacity: number) {
    this.cap = capacity;
    this.limit = capacity;
    const f = () => new Float32Array(capacity);
    this.px = f(); this.py = f(); this.pz = f();
    this.vx = f(); this.vy = f(); this.vz = f();
    this.age = f(); this.life = f();
    this.s0 = f(); this.s1 = f();
    this.c0 = new Float32Array(capacity * 3);
    this.c1 = new Float32Array(capacity * 3);
    this.a0 = f(); this.rot = f(); this.spin = f();
    this.drag = f(); this.grav = f(); this.frame = f();
    this.tall = new Uint8Array(capacity);
    this.hold = new Uint8Array(capacity);

    const base = new THREE.PlaneGeometry(1, 1);
    const geo = new THREE.InstancedBufferGeometry();
    geo.index = base.index;
    geo.setAttribute('position', base.getAttribute('position'));
    geo.setAttribute('uv', base.getAttribute('uv'));
    this.aPos = new THREE.InstancedBufferAttribute(new Float32Array(capacity * 3), 3);
    this.aColor = new THREE.InstancedBufferAttribute(new Float32Array(capacity * 4), 4);
    this.aMisc = new THREE.InstancedBufferAttribute(new Float32Array(capacity * 3), 3);
    for (const a of [this.aPos, this.aColor, this.aMisc]) a.setUsage(THREE.DynamicDrawUsage);
    geo.setAttribute('iPos', this.aPos);
    geo.setAttribute('iColor', this.aColor);
    geo.setAttribute('iMisc', this.aMisc);
    geo.instanceCount = 0;
    this.geometry = geo;

    const mat = new THREE.ShaderMaterial({
      vertexShader: VERT,
      fragmentShader: FRAG,
      uniforms: { map: { value: map } },
      transparent: true,
      depthWrite: false,
      blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
    });
    this.mesh = new THREE.Mesh(geo, mat);
    this.mesh.frustumCulled = false;
    this.mesh.renderOrder = additive ? 4 : 3;
    scene.add(this.mesh);
  }

  setLimit(n: number): void {
    this.limit = Math.max(1, Math.min(this.cap, n));
  }

  emit(o: EmitOpts): void {
    let i = this.count;
    if (i >= this.limit) {
      // 满了就顶掉最老的：从游标起看 32 颗，挑走得最远的那颗
      const n = this.count;
      let oldest = -1;
      for (let k = 0, j = this.cursor % n; k < 32; k++, j = j + 1 === n ? 0 : j + 1) {
        const r = this.age[j] / this.life[j];
        if (r > oldest) {
          oldest = r;
          i = j;
        }
      }
      this.cursor = (this.cursor + 32) % n;
    } else {
      this.count++;
    }
    this.px[i] = o.x; this.py[i] = o.y; this.pz[i] = o.z;
    this.vx[i] = o.vx ?? 0; this.vy[i] = o.vy ?? 0; this.vz[i] = o.vz ?? 0;
    this.age[i] = 0;
    const thin = this.lifeMul !== 1 && o.frame === 1 && (o.gravity ?? 0) >= 0 && !o.tall;
    this.life[i] = Math.max(0.01, thin ? o.life * this.lifeMul : o.life);
    this.s0[i] = o.size;
    this.s1[i] = o.size1 ?? o.size;
    this.tmpA.setHex(o.color);
    this.tmpB.setHex(o.color1 ?? o.color);
    const j = i * 3;
    this.c0[j] = this.tmpA.r; this.c0[j + 1] = this.tmpA.g; this.c0[j + 2] = this.tmpA.b;
    this.c1[j] = this.tmpB.r; this.c1[j + 1] = this.tmpB.g; this.c1[j + 2] = this.tmpB.b;
    this.a0[i] = o.alpha ?? 1;
    this.rot[i] = o.rot ?? Math.random() * Math.PI * 2;
    this.spin[i] = o.spin ?? 0;
    this.drag[i] = o.drag ?? 0;
    this.grav[i] = o.gravity ?? 0;
    this.frame[i] = o.frame ?? 0;
    this.tall[i] = o.tall ? 1 : 0;
    this.hold[i] = o.hold ? 1 : 0;
  }

  update(delta: number): void {
    const pos = this.aPos.array as Float32Array;
    const col = this.aColor.array as Float32Array;
    const misc = this.aMisc.array as Float32Array;
    let n = this.count;
    let i = 0;
    while (i < n) {
      this.age[i] += delta;
      if (this.age[i] >= this.life[i]) {
        n--;
        this.move(n, i);
        continue;
      }
      const k = 1 - Math.min(1, this.drag[i] * delta);
      this.vx[i] *= k;
      this.vy[i] = this.vy[i] * k + this.grav[i] * delta;
      this.vz[i] *= k;
      this.px[i] += this.vx[i] * delta;
      this.py[i] += this.vy[i] * delta;
      this.pz[i] += this.vz[i] * delta;
      this.rot[i] += this.spin[i] * delta;

      const t = this.age[i] / this.life[i];
      pos[i * 3] = this.px[i];
      pos[i * 3 + 1] = this.py[i];
      pos[i * 3 + 2] = this.pz[i];
      const j = i * 3;
      col[i * 4] = this.c0[j] + (this.c1[j] - this.c0[j]) * t;
      col[i * 4 + 1] = this.c0[j + 1] + (this.c1[j + 1] - this.c0[j + 1]) * t;
      col[i * 4 + 2] = this.c0[j + 2] + (this.c1[j + 2] - this.c0[j + 2]) * t;
      // 前 10% 淡入，之后线性淡出（撑住的：1 − t³，前大半段一直浓）
      let alpha = this.a0[i] * Math.min(1, t * 10) * (this.hold[i] ? 1 - t * t * t : 1 - t);
      const cz = this.clearZone;
      if (cz && !(this.tall[i] && this.py[i] > CLEAR_SMOKE.tallY)) alpha *= this.clearMul(cz, this.px[i], this.pz[i], t);
      col[i * 4 + 3] = alpha;
      misc[i * 3] = this.s0[i] + (this.s1[i] - this.s0[i]) * t;
      misc[i * 3 + 1] = this.rot[i];
      misc[i * 3 + 2] = this.frame[i];
      i++;
    }
    this.count = n;
    this.geometry.instanceCount = n;
    if (n === 0) return;
    // 只传活着的那一段（池子 2400 颗、平时只用几百颗，整块上传是白传）
    uploadHead(this.aPos, n);
    uploadHead(this.aColor, n);
    uploadHead(this.aMisc, n);
  }

  /** 近身清烟的倍率：离坦克 / 视线越近、活得越久，越淡 */
  private clearMul(c: { x: number; z: number; cx: number; cz: number }, x: number, z: number, t: number): number {
    const C = CLEAR_SMOKE;
    const d1 = Math.hypot(x - c.x, z - c.z);
    // 到「坦克 → 镜头」线段的距离
    const sx = c.cx - c.x;
    const sz = c.cz - c.z;
    const u = Math.max(0, Math.min(1, ((x - c.x) * sx + (z - c.z) * sz) / (sx * sx + sz * sz || 1)));
    const d2 = Math.hypot(x - c.x - sx * u, z - c.z - sz * u);
    const near = Math.max(Math.min(1, (C.r + C.fade - d1) / C.fade), Math.min(1, (C.w + C.fade - d2) / C.fade));
    if (near <= 0) return 1;
    const age = Math.max(0, Math.min(1, (t - C.from) / (C.to - C.from)));
    return 1 - near * (1 - C.k0 + (C.k0 - C.k) * age * age * (3 - 2 * age));
  }

  get active(): number {
    return this.count;
  }

  clear(): void {
    this.count = 0;
    this.geometry.instanceCount = 0;
  }

  dispose(): void {
    this.geometry.dispose();
    (this.mesh.material as THREE.Material).dispose();
  }

  /** 把 from 号粒子搬到 to 号槽位（删除时用最后一个填空） */
  private move(from: number, to: number): void {
    if (from === to) return;
    this.px[to] = this.px[from]; this.py[to] = this.py[from]; this.pz[to] = this.pz[from];
    this.vx[to] = this.vx[from]; this.vy[to] = this.vy[from]; this.vz[to] = this.vz[from];
    this.age[to] = this.age[from]; this.life[to] = this.life[from];
    this.s0[to] = this.s0[from]; this.s1[to] = this.s1[from];
    this.c0.copyWithin(to * 3, from * 3, from * 3 + 3);
    this.c1.copyWithin(to * 3, from * 3, from * 3 + 3);
    this.a0[to] = this.a0[from]; this.rot[to] = this.rot[from]; this.spin[to] = this.spin[from];
    this.drag[to] = this.drag[from]; this.grav[to] = this.grav[from]; this.frame[to] = this.frame[from];
    this.tall[to] = this.tall[from];
    this.hold[to] = this.hold[from];
  }
}
