import * as THREE from 'three';

// 每个实例是一段从 A 到 B 的发光条带，在视图空间里朝镜头展开（光束、闪电、尾迹都用它）
// |iMinPx| = 屏幕上最少这么多像素宽（T021-a：电弧不随镜头拉远变细）；iMinPx < 0 = 两头也软化（宽外晕，不然是一块方块）；uPx = 2 ÷ 画面高（像素）
const VERT = /* glsl */ `
attribute vec3 iA;
attribute vec3 iB;
attribute vec4 iColor;
attribute float iWidth;
attribute float iMinPx;
uniform float uPx;
varying vec4 vColor;
varying float vSide;
varying float vEnd;
varying float vSoft;
void main() {
  vec4 a = viewMatrix * vec4(iA, 1.0);
  vec4 b = viewMatrix * vec4(iB, 1.0);
  float end = position.y + 0.5;      // 0 = A，1 = B
  float side = position.x * 2.0;     // -1 .. 1
  vec4 p = mix(a, b, end);
  vec2 d = b.xy - a.xy;
  float len = max(length(d), 1e-4);
  vec2 n = vec2(-d.y, d.x) / len;
  float w = max(iWidth, abs(iMinPx) * uPx * max(-p.z, 0.05) / projectionMatrix[1][1]);
  p.xy += n * side * w * 0.5;
  gl_Position = projectionMatrix * p;
  vColor = iColor;
  vSide = side;
  vEnd = end;
  vSoft = iMinPx < 0.0 ? clamp(0.5 * w / max(length(b.xyz - a.xyz), 1e-3), 0.01, 0.5) : 0.0;
}`;

/** 电弧档位（T021-a）：芯宽 w（米）/ 寿命（秒）/ 重劈次数 / 每段长分叉的概率 / 抖幅 */
export type BoltTier = 'spark' | 't1' | 't3' | 't5' | 'evo' | 'enemy' | 'grid' | 'strike' | 'storm';
export interface BoltSpec { w: number; life: number; flicker: number; fork: number; jag: number }
export const BOLT_TIER: Record<BoltTier, BoltSpec> = {
  spark: { w: 0.16, life: 0.1, flicker: 1, fork: 0, jag: 0.4 },
  t1: { w: 0.45, life: 0.22, flicker: 2, fork: 0.25, jag: 1.6 },
  t3: { w: 0.55, life: 0.26, flicker: 2, fork: 0.35, jag: 1.8 },
  t5: { w: 0.7, life: 0.3, flicker: 3, fork: 0.45, jag: 2.0 },
  evo: { w: 0.9, life: 0.34, flicker: 3, fork: 0.55, jag: 2.2 },
  enemy: { w: 0.42, life: 0.22, flicker: 2, fork: 0.25, jag: 1.2 },
  grid: { w: 0.42, life: 0.2, flicker: 2, fork: 0.3, jag: 1.4 },
  strike: { w: 0.8, life: 0.34, flicker: 3, fork: 0.5, jag: 2.4 },
  storm: { w: 1.3, life: 0.42, flicker: 3, fork: 0.65, jag: 3.0 },
};
/** 三层：芯（白）/ 内晕（电蓝）/ 外晕（深电蓝，tint 可换）——宽度倍数、亮度、屏幕最小像素 */
const ARC = {
  core: 0xf4fbff, coreWide: 0xdff2ff, inner: 0x7cc8ff, outer: 0x3a8cff,
  innerW: 2.2, outerW: 5, coreA: 0.95, innerA: 0.45, outerA: 0.16,
  corePx: 3, innerPx: 7, outerPx: 12,
  /** 同一帧新出的电弧超过这么多道，后面的只画芯（防糊屏） */
  perFrame: 12,
};

const FRAG = /* glsl */ `
varying vec4 vColor;
varying float vSide;
varying float vEnd;
varying float vSoft;
void main() {
  float a = vColor.a * (1.0 - vSide * vSide);
  if (vSoft > 0.0) a *= smoothstep(0.0, vSoft, vEnd) * smoothstep(0.0, vSoft, 1.0 - vEnd);
  gl_FragColor = vec4(vColor.rgb, a);
  #include <colorspace_fragment>
}`;

/** 发光条带（加色混合）：激光、闪电、能量弧 */
export class Streaks {
  readonly mesh: THREE.Mesh;
  private readonly cap: number;
  private count = 0;
  private readonly data: Float32Array; // ax ay az bx by bz r g b alpha width age life minPx（age < 0 = 还没到出现的时候）
  private readonly aA: THREE.InstancedBufferAttribute;
  private readonly aB: THREE.InstancedBufferAttribute;
  private readonly aColor: THREE.InstancedBufferAttribute;
  private readonly aWidth: THREE.InstancedBufferAttribute;
  private readonly aMinPx: THREE.InstancedBufferAttribute;
  private readonly geometry: THREE.InstancedBufferGeometry;
  private readonly c = new THREE.Color();
  private readonly uPx = { value: 2 / 664 };
  private readonly size = new THREE.Vector2();
  /** 这一帧新出的电弧道数（`arc`，超过 ARC.perFrame 只画芯） */
  private arcsThisFrame = 0;
  private static readonly F = 14;

  constructor(scene: THREE.Scene, capacity = 600) {
    this.cap = capacity;
    this.data = new Float32Array(capacity * Streaks.F);
    const base = new THREE.PlaneGeometry(1, 1);
    const geo = new THREE.InstancedBufferGeometry();
    geo.index = base.index;
    geo.setAttribute('position', base.getAttribute('position'));
    this.aA = new THREE.InstancedBufferAttribute(new Float32Array(capacity * 3), 3);
    this.aB = new THREE.InstancedBufferAttribute(new Float32Array(capacity * 3), 3);
    this.aColor = new THREE.InstancedBufferAttribute(new Float32Array(capacity * 4), 4);
    this.aWidth = new THREE.InstancedBufferAttribute(new Float32Array(capacity), 1);
    this.aMinPx = new THREE.InstancedBufferAttribute(new Float32Array(capacity), 1);
    for (const a of [this.aA, this.aB, this.aColor, this.aWidth, this.aMinPx]) a.setUsage(THREE.DynamicDrawUsage);
    geo.setAttribute('iA', this.aA);
    geo.setAttribute('iB', this.aB);
    geo.setAttribute('iColor', this.aColor);
    geo.setAttribute('iWidth', this.aWidth);
    geo.setAttribute('iMinPx', this.aMinPx);
    geo.instanceCount = 0;
    this.geometry = geo;
    this.mesh = new THREE.Mesh(
      geo,
      new THREE.ShaderMaterial({
        vertexShader: VERT,
        fragmentShader: FRAG,
        uniforms: { uPx: this.uPx },
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
        side: THREE.DoubleSide,
      }),
    );
    this.mesh.frustumCulled = false;
    this.mesh.renderOrder = 6;
    this.mesh.onBeforeRender = (renderer) => {
      renderer.getSize(this.size);
      if (this.size.y > 0) this.uPx.value = 2 / this.size.y;
    };
    scene.add(this.mesh);
  }

  add(ax: number, ay: number, az: number, bx: number, by: number, bz: number, width: number, color: number, alpha: number, life: number, minPx = 0, delay = 0): void {
    const i = this.count < this.cap ? this.count++ : Math.floor(Math.random() * this.cap);
    this.c.setHex(color);
    this.data.set([ax, ay, az, bx, by, bz, this.c.r, this.c.g, this.c.b, alpha, width, -delay, life, minPx], i * Streaks.F);
  }

  /**
   * 电弧（T021-a）：所有「电攻击」都走这里，按档位取粗细 / 寿命 / 重劈 / 分叉。
   * 每段三根（白芯 + 电蓝内晕 + 深电蓝外晕，屏幕上最少 3 / 7 / 12 像素，拉远也不变细）；
   * 寿命里重劈 flicker 次（重新随机锯齿、每次 ×0.7 亮度、只画芯 + 内晕），看起来「啪—啪—啪」；主干每段按 fork 概率长分叉（二级分叉 25%）。
   * tint = 换外晕颜色（天罗偏青、聚雷跟光束阶段变色）；同一帧超过 12 道的只画芯。
   * long（T057，雷云从 58 米高的云底劈下来、天罗从天上罩下来）：超过 20 米的按长度多分段（最多 16 段）、锯齿和分叉跟着长度放大，不然一根长雷只有 7 段、像折了几下的棍
   */
  arc(ax: number, ay: number, az: number, bx: number, by: number, bz: number, tier: BoltTier, opts: { tint?: number; jag?: number; scale?: number; long?: boolean } = {}): void {
    const t = BOLT_TIER[tier];
    const w = t.w * (opts.scale ?? 1);
    const len = Math.hypot(bx - ax, by - ay, bz - az);
    const long = opts.long === true && len > 20;
    const grow = long ? Math.sqrt(len / 20) : 1;
    const jag = (opts.jag ?? t.jag) * grow;
    const reach = Math.min(3, grow);
    const seg = Math.max(3, Math.min(long ? 16 : 7, Math.round(len / (long ? 3.2 : 2.2))));
    const lite = ++this.arcsThisFrame > ARC.perFrame;
    const coreC = w > 1 ? ARC.coreWide : ARC.core;
    const outerC = opts.tint ?? ARC.outer;
    const n = Math.max(1, t.flicker);
    const s = t.life / (0.6 * n + 0.4);
    // 外晕：A → B 一整根（两头软化，不跟锯齿分段，不然宽外晕会拼出一块块方块），留满整个寿命，重劈在它上面一闪一闪
    if (!lite) this.add(ax, ay, az, bx, by, bz, w * ARC.outerW, outerC, ARC.outerA, t.life, -ARC.outerPx, 0);
    for (let f = 0; f < n; f++) {
      const delay = f * 0.6 * s;
      const am = 0.7 ** f;
      let px = ax;
      let py = ay;
      let pz = az;
      for (let k = 1; k <= seg; k++) {
        const u = k / seg;
        const amp = k === seg ? 0 : jag * Math.sin(u * Math.PI);
        const nx = ax + (bx - ax) * u + (Math.random() - 0.5) * amp;
        const ny = ay + (by - ay) * u + (Math.random() - 0.5) * amp * 0.6;
        const nz = az + (bz - az) * u + (Math.random() - 0.5) * amp;
        this.soft(px, py, pz, nx, ny, nz, w, coreC, ARC.coreA * am, s, ARC.corePx, delay);
        if (!lite) this.soft(px, py, pz, nx, ny, nz, w * ARC.innerW, ARC.inner, ARC.innerA * am, s, ARC.innerPx, delay);
        if (k < seg && Math.random() < t.fork) this.fork(nx, ny, nz, w * 0.5, s * 0.8, delay, am, lite, Math.random() < 0.25, reach);
        px = nx;
        py = ny;
        pz = nz;
      }
    }
  }

  /**
   * 宽条带的一节：两头各往外伸 0.25 × 宽、在 0.5 × 宽里软化（着色器 vSoft），相邻两节的软化区正好叠在一起、加起来是 1——
   * 拐角处不会支出方方的角，接缝也不会暗一截
   */
  private soft(ax: number, ay: number, az: number, bx: number, by: number, bz: number, w: number, color: number, alpha: number, life: number, minPx: number, delay: number): void {
    const len = Math.hypot(bx - ax, by - ay, bz - az) || 1;
    const e = (w * 0.25) / len;
    const dx = (bx - ax) * e;
    const dy = (by - ay) * e;
    const dz = (bz - az) * e;
    this.add(ax - dx, ay - dy, az - dz, bx + dx, by + dy, bz + dz, w, color, alpha, life, -minPx, delay);
  }

  /** 分叉：1.5～3 米（× reach，长雷的分叉更长）、两节锯齿，芯 + 内晕；deep = 再长一根二级分叉 */
  private fork(x: number, y: number, z: number, w: number, life: number, delay: number, am: number, lite: boolean, deep: boolean, reach = 1): void {
    const L = (1.5 + Math.random() * 1.5) * reach;
    const a = Math.random() * Math.PI * 2;
    const ex = x + Math.cos(a) * L;
    const ey = y + (Math.random() - 0.65) * L * 0.8;
    const ez = z + Math.sin(a) * L;
    const mx = (x + ex) / 2 + (Math.random() - 0.5) * L * 0.4;
    const my = (y + ey) / 2 + (Math.random() - 0.5) * L * 0.3;
    const mz = (z + ez) / 2 + (Math.random() - 0.5) * L * 0.4;
    for (const [x0, y0, z0, x1, y1, z1] of [[x, y, z, mx, my, mz], [mx, my, mz, ex, ey, ez]]) {
      this.soft(x0, y0, z0, x1, y1, z1, w, ARC.core, 0.8 * am, life, ARC.corePx * 0.6, delay);
      if (!lite) this.soft(x0, y0, z0, x1, y1, z1, w * ARC.innerW, ARC.inner, 0.35 * am, life, ARC.innerPx * 0.6, delay);
    }
    if (deep) this.fork(mx, my, mz, w * 0.6, life * 0.8, delay, am * 0.8, lite, false, reach);
  }

  /** 一道锯齿闪电：从 A 到 B 分若干段随机偏移，附带细分叉 */
  bolt(ax: number, ay: number, az: number, bx: number, by: number, bz: number, color: number, width = 0.35, life = 0.12, jag = 1.2): void {
    const seg = 7;
    let px = ax;
    let py = ay;
    let pz = az;
    for (let k = 1; k <= seg; k++) {
      const t = k / seg;
      const amp = k === seg ? 0 : jag * Math.sin(t * Math.PI);
      const nx = ax + (bx - ax) * t + (Math.random() - 0.5) * amp;
      const ny = ay + (by - ay) * t + (Math.random() - 0.5) * amp * 0.6;
      const nz = az + (bz - az) * t + (Math.random() - 0.5) * amp;
      this.add(px, py, pz, nx, ny, nz, width, color, 0.95, life);
      this.add(px, py, pz, nx, ny, nz, width * 4, color, 0.25, life);
      if (Math.random() < 0.3) {
        this.add(nx, ny, nz, nx + (Math.random() - 0.5) * 2.5, ny + (Math.random() - 0.3) * 1.5, nz + (Math.random() - 0.5) * 2.5, width * 0.6, color, 0.7, life * 0.8);
      }
      px = nx;
      py = ny;
      pz = nz;
    }
  }

  update(delta: number): void {
    const F = Streaks.F;
    const d = this.data;
    const A = this.aA.array as Float32Array;
    const B = this.aB.array as Float32Array;
    const C = this.aColor.array as Float32Array;
    const W = this.aWidth.array as Float32Array;
    const M = this.aMinPx.array as Float32Array;
    this.arcsThisFrame = 0;
    let n = this.count;
    let i = 0;
    while (i < n) {
      const o = i * F;
      d[o + 11] += delta;
      if (d[o + 11] >= d[o + 12]) {
        n--;
        if (i !== n) d.copyWithin(o, n * F, n * F + F);
        continue;
      }
      const fade = d[o + 11] < 0 ? 0 : 1 - d[o + 11] / d[o + 12];
      A[i * 3] = d[o]; A[i * 3 + 1] = d[o + 1]; A[i * 3 + 2] = d[o + 2];
      B[i * 3] = d[o + 3]; B[i * 3 + 1] = d[o + 4]; B[i * 3 + 2] = d[o + 5];
      C[i * 4] = d[o + 6]; C[i * 4 + 1] = d[o + 7]; C[i * 4 + 2] = d[o + 8]; C[i * 4 + 3] = d[o + 9] * fade;
      W[i] = d[o + 10];
      M[i] = d[o + 13];
      i++;
    }
    this.count = n;
    this.geometry.instanceCount = n;
    this.aA.needsUpdate = true;
    this.aB.needsUpdate = true;
    this.aColor.needsUpdate = true;
    this.aWidth.needsUpdate = true;
    this.aMinPx.needsUpdate = true;
  }

  /** 活着的条带数（诊断） */
  get active(): number {
    return this.count;
  }

  clear(): void {
    this.count = 0;
    this.geometry.instanceCount = 0;
  }

  dispose(): void {
    this.geometry.dispose();
    (this.mesh.material as THREE.Material).dispose();
  }
}
