import * as THREE from 'three';

/**
 * 车库纹章（T030，策划 T028 3.5）：炮塔 / 车体侧面的程序化图形，9 种——齿轮、交叉炮管、闪电、雄鹰、星芒（八道光芒，不是五角星）、铁拳、犀牛、龙、准星（T110 今日任务）。
 * 不用真实国家 / 部队徽记、不用骷髅、不用红五星、不画旗帜。
 * 一份多边形数据（24 × 24 坐标，非零环绕填充：同向叠加 = 合并，反向 = 挖洞），三处用：车上贴花（栅格成 64 × 64 的 DataTexture，小游戏也能用）、
 * DOM 版 SVG（emblemSvg）、画布版路径（paintEmblem）
 */

type Pt = [number, number];
type Poly = Pt[];

const ring = (cx: number, cy: number, r: number, n = 14, rev = false): Poly => {
  const p: Poly = [];
  for (let i = 0; i < n; i++) {
    const a = ((rev ? -i : i) / n) * Math.PI * 2;
    p.push([cx + Math.cos(a) * r, cy + Math.sin(a) * r]);
  }
  return p;
};

/** 绕 (12, 12) 转 deg 度的长条（宽 w、长 len） */
const bar = (deg: number, w: number, len: number): Poly => {
  const a = (deg * Math.PI) / 180;
  const c = Math.cos(a);
  const s = Math.sin(a);
  return ([[-w / 2, -len / 2], [w / 2, -len / 2], [w / 2, len / 2], [-w / 2, len / 2]] as Pt[]).map(([x, y]) => [12 + x * c - y * s, 12 + x * s + y * c]);
};

function gear(): Poly[] {
  const out: Poly = [];
  const n = 10;
  for (let i = 0; i < n; i++) {
    const a0 = (i / n) * Math.PI * 2;
    const st = (Math.PI * 2) / n;
    for (const [f, r] of [[0, 6.6], [0.15, 8.6], [0.5, 8.6], [0.65, 6.6]] as const) out.push([12 + Math.cos(a0 + f * st) * r, 12 + Math.sin(a0 + f * st) * r]);
  }
  return [out, ring(12, 12, 3, 12, true)];
}

function burst(): Poly[] {
  const p: Poly = [];
  for (let i = 0; i < 16; i++) {
    const a = (i / 16) * Math.PI * 2 + Math.PI / 16;
    const r = i % 2 === 0 ? 9.5 : 3.6;
    p.push([12 + Math.cos(a) * r, 12 + Math.sin(a) * r]);
  }
  return [p];
}

function dragon(): Poly[] {
  // 一条 S 形身子（一串圆）+ 头 + 背上几根刺
  const out: Poly[] = [];
  for (let i = 0; i <= 11; i++) {
    const t = i / 11;
    const x = 4.5 + t * 14;
    const y = 12 + Math.sin(t * Math.PI * 2) * 4.2;
    out.push(ring(x, y, 2.6 - t * 1.4, 10));
    if (i % 3 === 1) out.push([[x - 1.2, y - 2.2], [x, y - 4.6], [x + 1.2, y - 2.2]]);
  }
  out.push([[2, 9], [7.2, 9.6], [7.2, 14.6], [3, 13.6], [1.5, 11.5]]);
  out.push([[3.5, 9.3], [2.8, 6.5], [5.6, 9.2]]);
  return out;
}

export const EMBLEM_SHAPES: Record<string, Poly[]> = {
  gear: gear(),
  cannons: [bar(42, 2.6, 19), bar(-42, 2.6, 19), ring(12, 12, 3.4, 12)],
  bolt: [[[13.5, 2], [6, 13.2], [11, 13.2], [9, 22], [18.5, 9.5], [13.2, 9.5], [16, 2]]],
  eagle: [[[1.5, 8], [7.5, 10], [10.5, 6.5], [12, 3.5], [13.5, 6.5], [16.5, 10], [22.5, 8], [18.5, 14], [14, 13], [13.2, 19], [12, 21.5], [10.8, 19], [10, 13], [5.5, 14]]],
  star: burst(),
  fist: [
    [[6.5, 10], [17.5, 10], [18.5, 12], [18.5, 16.5], [16, 19], [9, 19], [6.5, 17]],
    ring(8.4, 9.6, 2, 10),
    ring(11.4, 8.9, 2, 10),
    ring(14.4, 8.9, 2, 10),
    ring(17, 9.8, 1.8, 10),
    [[5.2, 12.5], [9.5, 13], [10, 15.5], [5.2, 15]],
    [[8.8, 19], [15.8, 19], [15.8, 22], [8.8, 22]],
  ],
  rhino: [
    [[2.5, 15], [4.5, 11], [8, 9], [11, 8], [14, 8.5], [16, 7.2], [18.5, 2.5], [19.5, 7.5], [21.5, 11], [20.5, 14], [17.5, 15], [16.5, 18], [13.5, 18], [12.5, 16], [9.5, 16], [8.5, 19], [5, 19], [3.8, 17]],
    [[8.5, 9.2], [9.6, 5.2], [11.6, 8.4]],
    [[16.4, 8], [16.8, 5.4], [17.6, 7.6]],
  ],
  dragon: dragon(),
  // 准星（T110 今日任务累计 3 次）：一圈 + 四道刻线往里伸 + 中心一点
  sight: [
    ring(12, 12, 8.6, 20),
    ring(12, 12, 6.6, 20, true),
    [[11, 1.5], [13, 1.5], [13, 7.6], [11, 7.6]],
    [[11, 16.4], [13, 16.4], [13, 22.5], [11, 22.5]],
    [[1.5, 11], [7.6, 11], [7.6, 13], [1.5, 13]],
    [[16.4, 11], [22.5, 11], [22.5, 13], [16.4, 13]],
    ring(12, 12, 1.6, 10),
  ],
};

/** 星芒是金色，其余骨白 */
const INK: Record<string, string> = { star: '#ffd25a' };
const inkOf = (id: string) => INK[id] ?? '#ece2c6';

/** SVG / 画布路径（24 × 24） */
export function emblemPath(id: string): string {
  return (EMBLEM_SHAPES[id] ?? EMBLEM_SHAPES.gear).map((p) => `M${p.map(([x, y]) => `${x.toFixed(2)} ${y.toFixed(2)}`).join('L')}Z`).join('');
}

/** DOM 版：深色圆底 + 黄铜圈 + 图形 */
export function emblemSvg(id: string, size = 22): string {
  return `<svg class="emblem-g" width="${size}" height="${size}" viewBox="0 0 24 24"><circle cx="12" cy="12" r="11.4" fill="#22261c" stroke="#c8a050" stroke-width="1.1"/><path d="${emblemPath(id)}" fill="${inkOf(id)}"/></svg>`;
}

/** 画布版：左上角 (x, y)，边长 size */
export function paintEmblem(ctx: CanvasRenderingContext2D, x: number, y: number, size: number, id: string): void {
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(size / 24, size / 24);
  ctx.beginPath();
  ctx.arc(12, 12, 11.4, 0, Math.PI * 2);
  ctx.fillStyle = '#22261c';
  ctx.fill();
  ctx.lineWidth = 1.1;
  ctx.strokeStyle = '#c8a050';
  ctx.stroke();
  ctx.beginPath();
  for (const p of EMBLEM_SHAPES[id] ?? EMBLEM_SHAPES.gear) {
    p.forEach(([px, py], i) => (i ? ctx.lineTo(px, py) : ctx.moveTo(px, py)));
    ctx.closePath();
  }
  ctx.fillStyle = inkOf(id);
  ctx.fill();
  ctx.restore();
}

/** 点 (x, y) 的环绕数（非零 = 在图形里） */
function winding(polys: Poly[], x: number, y: number): number {
  let w = 0;
  for (const p of polys) {
    for (let i = 0, j = p.length - 1; i < p.length; j = i++) {
      const [x0, y0] = p[j];
      const [x1, y1] = p[i];
      if (y0 <= y) {
        if (y1 > y && (x1 - x0) * (y - y0) - (x - x0) * (y1 - y0) > 0) w++;
      } else if (y1 <= y && (x1 - x0) * (y - y0) - (x - x0) * (y1 - y0) < 0) w--;
    }
  }
  return w;
}

const hexRgb = (h: string): [number, number, number] => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];

/** 车上的贴花：64 × 64，圆外透明，2 × 2 超采样抗锯齿 */
export function emblemTexture(id: string, size = 64): THREE.DataTexture {
  const polys = EMBLEM_SHAPES[id] ?? EMBLEM_SHAPES.gear;
  const ink = hexRgb(inkOf(id));
  const base: [number, number, number] = [34, 38, 28];
  const brass: [number, number, number] = [200, 160, 80];
  const data = new Uint8Array(size * size * 4);
  for (let py = 0; py < size; py++) {
    for (let px = 0; px < size; px++) {
      let r = 0;
      let g = 0;
      let b = 0;
      let a = 0;
      for (const [sx, sy] of [[0.25, 0.25], [0.75, 0.25], [0.25, 0.75], [0.75, 0.75]]) {
        // 贴图第 0 行在下面：y 翻过来
        const x = ((px + sx) / size) * 24;
        const y = (1 - (py + sy) / size) * 24;
        const d = Math.hypot(x - 12, y - 12);
        if (d > 11.9) continue;
        const col = d > 10.8 ? brass : winding(polys, x, y) !== 0 ? ink : base;
        r += col[0];
        g += col[1];
        b += col[2];
        a += 1;
      }
      const i = (py * size + px) * 4;
      if (a) {
        data[i] = r / a;
        data[i + 1] = g / a;
        data[i + 2] = b / a;
      }
      data[i + 3] = (a / 4) * 255;
    }
  }
  const tex = new THREE.DataTexture(data, size, size, THREE.RGBAFormat);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.magFilter = THREE.LinearFilter;
  tex.minFilter = THREE.LinearMipmapLinearFilter;
  tex.generateMipmaps = true;
  tex.needsUpdate = true;
  return tex;
}
