import * as THREE from 'three';
import type { PartSpec } from '../../assets/GeoCache';
import { MAT } from '../../assets/materials';
import type { Enemy } from '../../entities/Enemy';
import { DRAPE_VERT } from '../../world/Craters';
import { ultHalf } from '../defs';
import { UltBase, type UltAim, type UltContext, type UltPreview } from './common';

const rand = (a: number, b: number) => a + Math.random() * (b - a);
/** 天罗电弧的外晕偏青一点，和玩家的特斯拉区分（T021-a） */
const SNARE_TINT = 0x8fe8ff;

/**
 * 「天罗」数值表（策划案 T007 v3 3.4 的起步值；冷却在 FUSIONS.snare.cd 里固定 30 秒（T066 翻倍））：
 * 炮塔中央竖井打出一枚电磁导弹，rise 秒垂直升空冲出画面，flight 秒落地起爆；落点 = 自动瞄准目标（没有目标 = 炮塔方向 preview 米），
 * 离「起爆那一刻坦克的位置」至少 R + gap 米（R = r × A，A = 爆破药半效），爆破兵被电弧击毁时殉爆炸不到自己；最后 homing 秒修正到目标当前位置，最多 homingMax 米。
 * warnAt 秒落点出现 R 米落点圈（我方浅黄，T130），whistleAt 秒尖啸。
 * 起爆：步兵（首领部件除外）直接击倒（倒地、爬电火花，不炸飞）；车辆 dmg ×（1 − (1 − edge) × 距离 / R）× 透镜半效（energy）+ 断电 power 秒（据点精英 powerElite 秒）；
 * 首领部件只吃伤害（全额），不断电、不会被直接击倒；arcs 道闪电劈向圈里的敌人 / 景物；顿帧 freeze、震屏 shake。
 * 电网：起爆后 grid 秒，同一个 R 米圆，pylons 根雷桩插在圆周上 + 1 根在中心，桩之间跳电弧；圈里的敌人减速（e.slow：移动 / 转向 ×0.4、开火 ×0.7，
 * 离开后保持 slowLinger 秒），不掉血；雷桩 barrelR 米内的油桶被电弧引爆。断电 / 减速的时长不吃任何改装件。只伤敌人。
 * T057（只是演出，上面的数值没动）：起爆时一张「天网」从 netY 米高罩下来（劈向敌人的前 sky 道改从高处劈，再补 net 道劈在圈边），
 * 紧接着全场像断电一样暗 blackout 秒（mood.out），之后电网期间压暗偏青（mood.grid），电网是最亮的东西；慢放 slow [秒, 倍数]；
 * 电网期间雷桩每 skyArc 秒往天上放一道电；落地前 static 秒地面冒静电火花
 */
export const SNARE = {
  // T017-5a：半径 18 → 26、车辆起爆 300 → 900、电网里每秒 gridDps（网里的车被电焦）、冷却 12 → 15（FUSIONS.snare.cd）
  flight: 2.4, rise: 1.0, warnAt: 1.2, whistleAt: 1.8, homing: 0.4, homingMax: 8, r: 26, gap: 8, preview: 45,
  dmg: 900, edge: 0.6, power: 3, powerElite: 2, grid: 4, gridDps: 120, slowLinger: 1, pylons: 6, barrelR: 3, arcs: 12,
  flash: 0.2, freeze: 0.08, shake: 0.8,
  netY: 42, net: 4, sky: 4, blackout: 0.35, slow: [0.35, 0.4], skyArc: 0.35, static: 0.5,
  mood: {
    out: { light: 0.32, exposure: 0.8, tint: 0x8fd8ff, tintK: 0.5, fog: 0x26303c, fogK: 0.5 },
    grid: { light: 0.66, exposure: 0.92, tint: 0x9fe0ff, tintK: 0.3, fog: 0x34404c, fogK: 0.3 },
  },
};

/** 电网的地面辉光：圆周一圈亮蓝、里面淡淡的网格纹，亮度慢慢起伏；uFade 收尾 */
const GRID_FRAG = /* glsl */ `
uniform float uTime;
uniform float uFade;
varying vec2 vP;
void main() {
  float r = length(vP);
  if (r > 1.0) discard;
  float a = atan(vP.y, vP.x);
  float rim = smoothstep(0.86, 0.97, r) * (1.0 - smoothstep(0.97, 1.0, r));
  float web = max(1.0 - smoothstep(0.0, 0.035, abs(fract(r * 4.0) - 0.5) - 0.44), 1.0 - smoothstep(0.0, 0.05, abs(fract(a * 0.9549297) - 0.5) - 0.44)) * 0.35;
  float flick = 0.75 + 0.25 * sin(uTime * 23.0 + a * 5.0) * sin(uTime * 7.0);
  float k = (rim * 0.9 + web * (1.0 - r * 0.5) + 0.08) * flick * uFade;
  if (k < 0.01) discard;
  gl_FragColor = vec4(vec3(0.55, 0.85, 1.0) * k, k);
  #include <colorspace_fragment>
}`;

/** 天罗 · 电磁网弹（火箭 + 特斯拉★ + 迫击炮★）：电磁导弹落地起爆，18 米内步兵全灭、车辆断电，之后 4 秒电网减速；对首领只有伤害 */
export class SnareUlt extends UltBase {
  /** 导弹已经飞了几秒；-1 = 没有在飞 */
  private t = -1;
  /** 电网已经开了几秒；-1 = 没有电网 */
  private g = -1;
  private sx = 0;
  private sy = 0;
  private sz = 0;
  /** 落点（发射时定下，最后 homing 秒修正） */
  private lx = 0;
  private lz = 0;
  private ox = 0;
  private oz = 0;
  private target: Enemy | null = null;
  private R = SNARE.r;
  private warned = false;
  private whistled = false;
  private arcT = 0;
  private gridT = 0;
  private scnT = 0;
  private missile: THREE.Mesh | null = null;
  private pylons: THREE.InstancedMesh | null = null;
  /** 这一发让几辆载具断电了（T018-3 成就「天罗地网」） */
  powered = 0;
  private field: THREE.Mesh<THREE.RingGeometry, THREE.ShaderMaterial> | null = null;
  private readonly pts: THREE.Vector3[] = [];
  /** 断电那一下还剩几秒（之后换成电网期间的压暗）、雷桩往天上放电的计时、氛围改过没有 */
  private outT = 0;
  private skyT = 0;
  private moody = false;
  private readonly m = new THREE.Matrix4();
  private readonly v = new THREE.Vector3();

  /** 落点价值评分（T017-13A）：R 米的圈，离起爆时的坦克至少 R + gap 米 */
  spot(ctx: UltContext): { r: number; min: number; max: number } {
    const R = SNARE.r * ultHalf(ctx.mods.area);
    return { r: R, min: R + SNARE.gap, max: Math.max(100, ctx.duel) };
  }

  /** 现在按下会落在哪（R 米的圈） */
  preview(ctx: UltContext, aim: UltAim): UltPreview {
    const p = this.landing(ctx, aim.target, aim.angle);
    return { x: p.x, z: p.z, r: SNARE.r * ultHalf(ctx.mods.area) };
  }

  protected override activeLabel(): string {
    return this.t >= 0 ? '飞行' : `电网 ${Math.ceil(this.active)}`;
  }

  protected fire(ctx: UltContext, aim: UltAim): void {
    const T = SNARE;
    this.clear();
    this.R = T.r * ultHalf(ctx.mods.area);
    this.target = aim.target;
    const p = this.landing(ctx, aim.target, aim.angle);
    this.lx = this.ox = p.x;
    this.lz = this.oz = p.z;
    // 炮塔中央竖井顶上出膛：竖直往上
    const s = ctx.tank.turretPoint(0, 1.7, 0.45, this.v);
    this.sx = s.x;
    this.sy = s.y;
    this.sz = s.z;
    this.t = 0;
    this.warned = this.whistled = false;
    this.active = T.flight + T.grid;
    this.missile ??= this.makeMissile(ctx);
    this.missile.visible = true;
    this.missile.position.copy(s);
    ctx.tank.kick(0.6);
    ctx.shake(0.3);
    ctx.audio.play('launch');
    ctx.audio.play('rocket');
    for (let i = 0; i < 10; i++) ctx.fx.smokeP.emit({ x: s.x + rand(-1, 1), y: s.y - 0.5, z: s.z + rand(-1, 1), vx: rand(-3, 3), vy: rand(0, 1), vz: rand(-3, 3), life: rand(0.8, 1.3), size: 1.2, size1: 3.2, color: 0xd8d4cc, alpha: 0.6, frame: 1, drag: 2 });
  }

  /**
   * 落点：自动瞄准目标处，没有目标就是炮塔方向 preview 米；离「起爆那一刻坦克的位置」（坦克一直往前开）不到 R + gap 就沿瞄准方向推出去
   */
  private landing(ctx: UltContext, target: Enemy | null, angle: number, left = SNARE.flight): { x: number; z: number } {
    const T = SNARE;
    const P = ctx.tank.group.position;
    const R = T.r * ultHalf(ctx.mods.area);
    const qx = P.x;
    const qz = P.z - ctx.speed * left;
    let x = target ? target.group.position.x : P.x - Math.sin(angle) * T.preview;
    let z = target ? target.group.position.z : P.z - Math.cos(angle) * T.preview;
    const dx = x - qx;
    const dz = z - qz;
    const d = Math.hypot(dx, dz);
    const min = R + T.gap;
    if (d < min) {
      const ux = d > 0.5 ? dx / d : -Math.sin(angle);
      const uz = d > 0.5 ? dz / d : -Math.cos(angle);
      x = qx + ux * min;
      z = qz + uz * min;
    }
    return { x, z };
  }

  /** 电磁导弹：火箭弹 ×3，弹头加两道铜环（1 次绘制，只在飞行时出现） */
  private makeMissile(ctx: UltContext): THREE.Mesh {
    const g = ctx.geo.merged('ult-snare-missile', (): PartSpec[] => [
      { geo: new THREE.CylinderGeometry(0.33, 0.33, 2.7, 10), color: 0x5a6058, rot: [Math.PI / 2, 0, 0] },
      { geo: new THREE.ConeGeometry(0.33, 0.9, 10), color: 0xd8dcd8, pos: [0, 0, -1.8], rot: [-Math.PI / 2, 0, 0] },
      ...[-1.1, -0.8].map((z): PartSpec => ({ geo: new THREE.TorusGeometry(0.36, 0.06, 6, 14), color: 0xb5653a, pos: [0, 0, z] })),
      { geo: new THREE.BoxGeometry(1.1, 0.08, 0.55), color: 0x3a3a32, pos: [0, 0, 1.2] },
      { geo: new THREE.BoxGeometry(0.08, 1.1, 0.55), color: 0x3a3a32, pos: [0, 0, 1.2] },
    ]);
    const mesh = new THREE.Mesh(g, MAT.painted);
    mesh.castShadow = true;
    mesh.frustumCulled = false;
    ctx.scene.add(mesh);
    return mesh;
  }

  protected step(ctx: UltContext): void {
    if (this.t >= 0) this.stepFlight(ctx);
    else if (this.g >= 0) this.stepGrid(ctx);
    else if (this.moody) {
      // 被 clear 打断（读档 / 重开 / 调试）：氛围退回平时
      this.moody = false;
      ctx.mood(null, 0.6);
    }
  }

  /** 飞行：rise 秒垂直升空（粗白烟柱）→ 从画面上方扎向落点；warnAt 秒出预警圈，whistleAt 秒尖啸，最后 homing 秒修正落点 */
  private stepFlight(ctx: UltContext): void {
    const T = SNARE;
    this.t += ctx.dt;
    const t = this.t;
    const m = this.missile!;
    if (t >= T.flight - T.homing && this.target?.alive) {
      // 修正到目标当前位置（最多 homingMax 米，仍然离坦克 R + gap 以外）
      const p = this.landing(ctx, this.target, 0, Math.max(0, T.flight - t));
      const dx = p.x - this.ox;
      const dz = p.z - this.oz;
      const d = Math.hypot(dx, dz);
      const k = d > T.homingMax ? T.homingMax / d : 1;
      this.lx = this.ox + dx * k;
      this.lz = this.oz + dz * k;
    }
    if (!this.warned && t >= T.warnAt) {
      this.warned = true;
      ctx.hazards.marker(this.lx, this.lz, this.R, T.flight - T.warnAt, 'self');
    }
    if (!this.whistled && t >= T.whistleAt) {
      this.whistled = true;
      ctx.audio.play('fall', 0.8);
    }
    // 落地前地面冒静电火花（T057：汗毛竖起来的那一下）
    if (t >= T.flight - T.static && Math.random() < 0.6) {
      const a = Math.random() * Math.PI * 2;
      const r = Math.sqrt(Math.random()) * this.R;
      const sx = this.lx + Math.cos(a) * r;
      const sz = this.lz + Math.sin(a) * r;
      ctx.fx.sparks(sx, ctx.fx.groundAt(sx, sz) + 0.3, sz, 3, 0xbfe6ff, 5);
    }
    if (t < T.rise) {
      // 垂直升空，越来越快
      const k = t / T.rise;
      m.position.set(this.sx, this.sy + 48 * k * k, this.sz);
      m.rotation.set(Math.PI / 2, 0, 0);
      if (Math.random() < 0.9) ctx.fx.smokeP.emit({ x: m.position.x + rand(-0.3, 0.3), y: m.position.y - 1.6, z: m.position.z + rand(-0.3, 0.3), vx: rand(-0.6, 0.6), vy: rand(-1, 0.5), vz: rand(-0.6, 0.6), life: rand(1.2, 1.8), size: 1.1, size1: 3.4, color: 0xe8e4dc, color1: 0xb0aca4, alpha: 0.7, frame: 1, drag: 1.2 });
      ctx.fx.glow.emit({ x: m.position.x, y: m.position.y - 1.7, z: m.position.z, life: 0.06, size: 1.6, size1: 0.6, color: 0xfff0c0, color1: 0xff7a20, frame: 0 });
    } else {
      // 从高空扎下来（弹头朝下、略带一点来向的斜度）
      const k = Math.min(1, (t - T.rise) / (T.flight - T.rise));
      const y = 70 * (1 - k * k);
      m.position.set(this.lx + (this.sx - this.lx) * (1 - k) * 0.15, y, this.lz + (this.sz - this.lz) * (1 - k) * 0.15);
      m.rotation.set(-Math.PI / 2 + 0.12, 0, 0);
      if (y < 45) ctx.fx.smokeP.emit({ x: m.position.x, y: y + 1.6, z: m.position.z, vy: 0.5, life: 0.6, size: 0.6, size1: 1.6, color: 0xd8d4cc, alpha: 0.5, frame: 1, drag: 1.5 });
    }
    if (t >= T.flight) this.detonate(ctx);
  }

  /** 起爆：步兵直接击倒、车辆断电 + 能量伤害、首领部件只吃伤害；景物电磁脉冲；闪光、闪电、顿帧、震屏；电网开始 */
  private detonate(ctx: UltContext): void {
    const T = SNARE;
    const { lx: x, lz: z, R } = this;
    this.t = -1;
    this.g = 0;
    this.gridT = 0;
    this.arcT = 0;
    this.scnT = 0.25;
    this.active = T.grid;
    if (this.missile) this.missile.visible = false;
    const lens = ultHalf(ctx.mods.energy);
    const hit: Enemy[] = [];
    this.powered = 0;
    for (const e of ctx.enemies) {
      if (!e.alive) continue;
      const d = Math.hypot(e.group.position.x - x, e.group.position.z - z);
      if (d > R + e.radius) continue;
      hit.push(e);
      const ex = e.group.position.x;
      const ez = e.group.position.z;
      if (e.spec.crushable && !e.controller) {
        // 步兵：直接击倒（不看区域），倒地、身上爬电火花冒青烟，不炸飞；爆破兵的炸药包照常殉爆
        ctx.damage(e, e.hp + 1, x, z, { type: 'energy', kind: 'elec', ult: true, fixed: true });
        ctx.fx.electric(ex, 1, ez, 6);
        ctx.fx.smoke(ex, 0.8, ez, 0.5, 1.6, 0x7a9a96, 0.45);
        continue;
      }
      const amount = T.dmg * (1 - (1 - T.edge) * Math.min(1, d / R)) * lens;
      ctx.damage(e, amount, x, z, { type: 'energy', kind: 'elec', ult: true });
      // 断电：普通车辆 power 秒、据点精英 powerElite 秒；首领部件不吃（控制效果一律无效）
      if (e.alive && !e.controller) {
        e.power = Math.max(e.power, e.spec.blocker ? T.powerElite : T.power);
        this.powered += 1;
      }
    }
    // 闪电：劈向圈里的敌人（近的先），再劈向景物（电线杆横担炸火花、树被雷劈、房子窗口闪蓝光；不推倒任何景物）
    hit.sort((a, b) => Math.hypot(a.group.position.x - x, a.group.position.z - z) - Math.hypot(b.group.position.x - x, b.group.position.z - z));
    let bolts = 0;
    // 天网（T057）：雷从高处（netY 米，画面上沿外面）劈下来，像一张网罩住整个圈
    const top = () => [x + rand(-0.3, 0.3) * R, T.netY + rand(-4, 6), z + rand(-0.3, 0.3) * R] as const;
    for (const e of hit) {
      if (bolts >= T.arcs) break;
      // 前 sky 道从高处劈（长雷分段多），后面的照旧从 9 米劈
      // 高处劈下来的用 grid 档放粗（重劈 2 下，长雷的光条数和原来 strike 档的短雷差不多），起爆那一帧光条池子才装得下
      if (bolts < T.sky) {
        const [tx, ty, tz] = top();
        ctx.streaks.arc(tx, ty, tz, e.group.position.x, 1.2 * e.size, e.group.position.z, 'grid', { tint: SNARE_TINT, scale: 1.6, long: true });
      } else ctx.streaks.arc(x + rand(-1, 1), 9, z + rand(-1, 1), e.group.position.x, 1.2 * e.size, e.group.position.z, 'strike', { tint: SNARE_TINT });
      ctx.fx.electric(e.group.position.x, 1.2 * e.size, e.group.position.z, 6, true);
      bolts += 1;
    }
    for (const p of ctx.scenery.emp(x, z, R, T.arcs)) {
      if (bolts >= T.arcs + 4) break;
      ctx.streaks.arc(x + rand(-1, 1), 9, z + rand(-1, 1), p.x, p.y, p.z, 'strike', { tint: SNARE_TINT, scale: 0.9 });
      bolts += 1;
    }
    // 网的边：再补几道劈在圈边上（均匀一圈，劈不到敌人也有网）
    const a0 = Math.random() * Math.PI * 2;
    for (let i = 0; i < T.net; i++) {
      const a = a0 + (i / T.net) * Math.PI * 2;
      const ex = x + Math.cos(a) * R;
      const ez = z + Math.sin(a) * R;
      const [tx, ty, tz] = top();
      ctx.streaks.arc(tx, ty, tz, ex, ctx.fx.groundAt(ex, ez) + 0.2, ez, 'grid', { tint: SNARE_TINT, scale: 1.3, long: true });
      ctx.fx.electric(ex, ctx.fx.groundAt(ex, ez) + 0.5, ez, 5, true);
    }
    // 蓝白半球闪光 + 贴地冲击环 + 补光
    ctx.fx.glow.emit({ x, y: 2, z, life: 0.35, size: R * 1.5, size1: R * 2.1, color: 0xe8f6ff, color1: 0x4aa0ff, alpha: 0.85, frame: 0 });
    ctx.fx.glow.emit({ x, y: 1, z, life: 0.2, size: 10, size1: 16, color: 0xffffff, frame: 0 });
    ctx.fx.flash(x, 8, z, 6000);
    ctx.fx.shockwave(x, z, R, 0xbfe6ff, 0.5);
    for (let i = 0; i < 24; i++) ctx.fx.sparks(x + rand(-R, R) * 0.6, rand(0.5, 3), z + rand(-R, R) * 0.6, 3, 0xbfe6ff, 9);
    ctx.flash(T.flash);
    ctx.freeze(T.freeze);
    ctx.slowmo(T.slow[0], T.slow[1]);
    ctx.shake(T.shake);
    ctx.audio.play('emp');
    ctx.audio.play('zap');
    // 电磁脉冲：全场像断电一样一下暗下去，只剩电网发光（之后在 stepGrid 里换成电网期间的压暗）
    this.moody = true;
    this.outT = T.blackout;
    this.skyT = T.skyArc;
    ctx.mood(T.mood.out, 0.06);
    this.raiseGrid(ctx);
  }

  /** 电网：圆周上 pylons 根雷桩 + 中心 1 根（实例化 1 次绘制）+ 地面辉光（1 次绘制）；雷桩附近的油桶被引爆 */
  private raiseGrid(ctx: UltContext): void {
    const T = SNARE;
    const n = T.pylons + 1;
    if (!this.pylons) {
      const g = ctx.geo.merged('ult-snare-pylon', (): PartSpec[] => [
        { geo: new THREE.CylinderGeometry(0.1, 0.16, 2.6, 6), color: 0x3a3e42, pos: [0, 1.3, 0] },
        ...[0.9, 1.4, 1.9].map((y): PartSpec => ({ geo: new THREE.TorusGeometry(0.2, 0.04, 5, 10), color: 0xb5653a, pos: [0, y, 0], rot: [Math.PI / 2, 0, 0] })),
        { geo: new THREE.SphereGeometry(0.2, 8, 6), color: 0xbfeeff, pos: [0, 2.75, 0] },
      ]);
      this.pylons = new THREE.InstancedMesh(g, MAT.painted, n);
      this.pylons.frustumCulled = false;
      ctx.scene.add(this.pylons);
      this.field = new THREE.Mesh(
        new THREE.RingGeometry(0.001, 1, 48, 12).rotateX(-Math.PI / 2),
        new THREE.ShaderMaterial({
          vertexShader: DRAPE_VERT,
          fragmentShader: GRID_FRAG,
          uniforms: { uTime: { value: 0 }, uFade: { value: 1 }, uDrape: { value: 1 }, ...ctx.fx.craterU },
          transparent: true,
          depthWrite: false,
          blending: THREE.AdditiveBlending,
        }),
      );
      this.field.renderOrder = 1;
      this.field.frustumCulled = false;
      ctx.scene.add(this.field);
    }
    this.pts.length = 0;
    const a0 = Math.random() * Math.PI * 2;
    for (let i = 0; i < n; i++) {
      const a = a0 + (i / T.pylons) * Math.PI * 2;
      const r = i === T.pylons ? 0 : this.R;
      this.pts.push(new THREE.Vector3(this.lx + Math.cos(a) * r, 0, this.lz + Math.sin(a) * r));
    }
    for (const [i, p] of this.pts.entries()) {
      p.y = ctx.fx.groundAt(p.x, p.z);
      this.pylons.setMatrixAt(i, this.m.makeTranslation(p.x, p.y, p.z));
      ctx.fx.dirt(p.x, p.z, 0.8);
      for (const [bx, bz] of ctx.barrels(p.x, p.z, T.barrelR)) ctx.detonate(bx, bz);
    }
    this.pylons.instanceMatrix.needsUpdate = true;
    this.pylons.visible = true;
    this.field!.visible = true;
    this.field!.position.set(this.lx, 0.12, this.lz);
    this.field!.scale.set(this.R, 1, this.R);
    this.field!.material.uniforms.uFade.value = 1;
  }

  /** 电网每帧：圈里的敌人续上减速（离开后保持 slowLinger 秒）；桩之间跳电弧；圈边的电线杆 / 树每秒最多被跳一次 */
  private stepGrid(ctx: UltContext): void {
    const T = SNARE;
    this.g += ctx.dt;
    const left = T.grid - this.g;
    if (this.outT > 0) {
      this.outT -= ctx.dt;
      if (this.outT <= 0) ctx.mood(T.mood.grid, 0.5);
    }
    // 雷桩往天上放电（「天罗」：网连着天）
    this.skyT -= ctx.dt;
    if (this.skyT <= 0 && this.pts.length) {
      this.skyT = T.skyArc * rand(0.7, 1.3);
      const p = this.pts[Math.floor(Math.random() * this.pts.length)];
      ctx.streaks.arc(p.x, p.y + 2.75, p.z, p.x + rand(-6, 6), p.y + rand(26, 36), p.z + rand(-6, 6), 'grid', { tint: SNARE_TINT, long: true });
    }
    // 电网伤害（T017-5a）：每 0.25 秒一跳，圈里的敌人每秒 gridDps × 透镜半效（energy；首领部件也吃伤害、不吃减速）
    this.gridT -= ctx.dt;
    const zap = this.gridT <= 0;
    if (zap) this.gridT += 0.25;
    const lens = ultHalf(ctx.mods.energy);
    for (const e of ctx.enemies) {
      if (!e.alive) continue;
      if (Math.hypot(e.group.position.x - this.lx, e.group.position.z - this.lz) > this.R + e.radius) continue;
      if (zap) ctx.damage(e, T.gridDps * 0.25 * lens, this.lx, this.lz, { type: 'energy', kind: 'elec', ult: true });
      if (e.alive && !e.controller) e.slow = Math.max(e.slow, T.slowLinger);
    }
    const u = this.field!.material.uniforms;
    u.uTime.value += ctx.dt;
    u.uFade.value = Math.min(1, left / 0.4);
    // 桩之间跳电弧：相邻两根、偶尔中心那根
    this.arcT -= ctx.dt;
    if (this.arcT <= 0) {
      this.arcT = rand(0.06, 0.12);
      const n = T.pylons;
      const i = Math.floor(Math.random() * n);
      const a = this.pts[i];
      const b = Math.random() < 0.25 ? this.pts[n] : this.pts[(i + 1) % n];
      ctx.streaks.arc(a.x, a.y + 2.75, a.z, b.x, b.y + 2.75, b.z, 'grid', { tint: SNARE_TINT });
      if (Math.random() < 0.4) ctx.fx.electric(a.x, a.y + 2.75, a.z, 3);
    }
    this.scnT -= ctx.dt;
    if (this.scnT <= 0) {
      this.scnT = 0.25;
      const p = ctx.scenery.gridArc(this.lx, this.lz, this.R, 4);
      if (p) {
        let best = this.pts[0];
        for (const q of this.pts) if (Math.hypot(q.x - p.x, q.z - p.z) < Math.hypot(best.x - p.x, best.z - p.z)) best = q;
        ctx.streaks.arc(best.x, best.y + 2.75, best.z, p.x, p.y, p.z, 'grid', { tint: SNARE_TINT, jag: 1.6 });
      }
    }
    if (left <= 0) {
      for (const p of this.pts) ctx.fx.smoke(p.x, p.y + 2, p.z, 0.6, 1.6, 0x4a4a48, 0.5);
      // 来电了：氛围退回平时
      this.moody = false;
      ctx.mood(null, 0.8);
      this.hideGrid();
      this.g = -1;
      this.finish();
      return;
    }
    this.active = left;
  }

  private hideGrid(): void {
    if (this.pylons) this.pylons.visible = false;
    if (this.field) this.field.visible = false;
  }

  protected clear(): void {
    this.t = -1;
    this.g = -1;
    this.target = null;
    if (this.missile) this.missile.visible = false;
    this.hideGrid();
  }

  override dispose(): void {
    super.dispose();
    this.missile?.removeFromParent();
    this.pylons?.removeFromParent();
    this.pylons?.dispose();
    this.field?.removeFromParent();
    this.field?.geometry.dispose();
    this.field?.material.dispose();
    this.missile = null;
    this.pylons = null;
    this.field = null;
  }
}
