export const KEY_DEFAULT = {
  forward: 'KeyW', back: 'KeyS', left: 'KeyA', right: 'KeyD',
  aimLeft: 'KeyQ', aimRight: 'KeyE', fire: 'Space', ult: 'KeyR', pause: 'Escape',
};
export const PAD_DEFAULT = { fire: 7, ult: 5, pause: 9, confirm: 0, cancel: 1, workshop: 4, move: 0, aim: 2 };
export type KeyAction = keyof typeof KEY_DEFAULT;
export type PadAction = keyof typeof PAD_DEFAULT;
export interface ControlBindings {
  keyboard?: Partial<Record<KeyAction, string>>;
  gamepad?: Partial<Record<PadAction, number>>;
}
export const KEY_LABEL: Record<KeyAction, string> = {
  forward: '前进', back: '后退', left: '左移', right: '右移',
  aimLeft: '向左瞄准', aimRight: '向右瞄准', fire: '开火', ult: '究极', pause: '暂停',
};
export const PAD_LABEL: Record<PadAction, string> = {
  fire: '开火', ult: '究极', pause: '暂停', confirm: '确认', cancel: '返回', workshop: '改装', move: '移动摇杆', aim: '瞄准摇杆',
};
export const PAD_NAMES = ['下侧面键', '右侧面键', '左侧面键', '上侧面键', '左肩键', '右肩键', '左扳机', '右扳机', '选择键', '菜单键', '左杆按下', '右杆按下', '方向上', '方向下', '方向左', '方向右'];
export const KEY_NAMES: Record<string, string> = {
  Space: '空格', Escape: '退出键', Enter: '回车', ShiftLeft: '左上档', ShiftRight: '右上档',
  ArrowUp: '方向上', ArrowDown: '方向下', ArrowLeft: '方向左', ArrowRight: '方向右',
};
for (const [row, letters] of ['QWERTYUIOP', 'ASDFGHJKL', 'ZXCVBNM'].entries()) {
  [...letters].forEach((letter, i) => { KEY_NAMES[`Key${letter}`] = `${['上', '中', '下'][row]}排第${i + 1}键`; });
}
for (let i = 0; i < 10; i++) KEY_NAMES[`Digit${i}`] = `数字${i}`;

let bindings: ControlBindings = {};
export function cleanBindings(value: ControlBindings | undefined): ControlBindings {
  const keyboard: NonNullable<ControlBindings['keyboard']> = {};
  const gamepad: NonNullable<ControlBindings['gamepad']> = {};
  for (const action of Object.keys(KEY_DEFAULT) as KeyAction[]) {
    const code = value?.keyboard?.[action];
    if (typeof code === 'string' && code in KEY_NAMES) keyboard[action] = code;
  }
  for (const action of Object.keys(PAD_DEFAULT) as PadAction[]) {
    const index = value?.gamepad?.[action];
    if (typeof index === 'number' && Number.isInteger(index) && (action === 'move' || action === 'aim' ? index === 0 || index === 2 : index >= 0 && index < 16)) gamepad[action] = index;
  }
  return { keyboard, gamepad };
}
export function setBindings(value?: ControlBindings): void { bindings = cleanBindings(value); }
export function keyBinding(action: KeyAction): string { return bindings.keyboard?.[action] ?? KEY_DEFAULT[action]; }
export function padBinding(action: PadAction, nintendo = false): number {
  return bindings.gamepad?.[action] ?? (nintendo && (action === 'confirm' || action === 'cancel') ? 1 - PAD_DEFAULT[action] : PAD_DEFAULT[action]);
}
/** 只转换已改键位；旧存档保留方向键和备用前进键。 */
export function gameplayKey(code: string): string {
  for (const action of Object.keys(KEY_DEFAULT) as KeyAction[]) {
    if (keyBinding(action) === code) return KEY_DEFAULT[action];
  }
  if (Object.values(KEY_DEFAULT).includes(code) && Object.keys(KEY_DEFAULT).some(a => KEY_DEFAULT[a as KeyAction] === code && keyBinding(a as KeyAction) !== code)) return '';
  return code;
}
