import * as THREE from 'three';
import { MARK_OUT, MARK_SELF } from '../render/markColors';

const VERT = /* glsl */ `
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}`;

// 沿弹道流动的虚线：越靠近目标越亮，开炮瞬间整条闪一下
const FRAG = /* glsl */ `
uniform float uTime;
uniform float uLen;
uniform float uFlash;
uniform vec3 uColor;
varying vec2 vUv;
void main() {
  float t = 1.0 - vUv.y;
  float d = fract(t * uLen / 2.4 - uTime * 2.2);
  float dash = smoothstep(0.0, 0.08, d) * (1.0 - smoothstep(0.45, 0.55, d));
  float across = 1.0 - abs(vUv.x - 0.5) * 2.0;
  float body = smoothstep(0.0, 0.12, t) * (1.0 - smoothstep(0.88, 1.0, t));
  float a = (dash * 0.55 + 0.18 + uFlash * 0.8) * across * across * body;
  gl_FragColor = vec4(uColor * (1.0 + uFlash), a);
  #include <colorspace_fragment>
}`;

const FACE = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(1, 0, 0), Math.PI / 2);
const SPIN = new THREE.Quaternion();
const UP = new THREE.Vector3(0, 1, 0);

type Mark = { x: number; z: number; radius: number; y?: number };

/** 主炮瞄准线 + 目标锁定框：让玩家一眼看清主炮在打谁（我方浅黄，T130；原来橙红）；主武器抬不上去的天上目标套灰框（T131） */
export class AimLine {
  /** 地面高度（实体弹坑）：锁定框贴着坑里的地面 */
  groundAt: (x: number, z: number) => number = () => 0;
  /** 天上的目标（T125）：锁定框立起来朝着镜头 */
  camera: THREE.Camera | null = null;
  readonly group = new THREE.Group();
  /** 瞄准线 + 锁定框（没有目标时整组藏起来；灰框另算） */
  private readonly lockGroup = new THREE.Group();
  private readonly line: THREE.Mesh<THREE.PlaneGeometry, THREE.ShaderMaterial>;
  private readonly bracket = new THREE.Group();
  private readonly bracketMat = new THREE.MeshBasicMaterial({ color: MARK_SELF, transparent: true, opacity: 0.9, depthWrite: false });
  /** 够不着的灰框（T131）：同样四个角标，不转、不闪 */
  private readonly outBracket = new THREE.Group();
  private readonly outMat = new THREE.MeshBasicMaterial({ color: MARK_OUT, transparent: true, opacity: 0.85, depthWrite: false });
  private readonly geos: THREE.BufferGeometry[] = [];
  private time = 0;
  private flash = 0;
  private readonly from = new THREE.Vector3();
  private readonly to = new THREE.Vector3();

  constructor() {
    const geo = new THREE.PlaneGeometry(1, 1);
    geo.rotateX(-Math.PI / 2);
    geo.translate(0, 0, 0.5);
    this.geos.push(geo);
    this.line = new THREE.Mesh(
      geo,
      new THREE.ShaderMaterial({
        vertexShader: VERT,
        fragmentShader: FRAG,
        uniforms: { uTime: { value: 0 }, uLen: { value: 10 }, uFlash: { value: 0 }, uColor: { value: new THREE.Color(MARK_SELF) } },
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
        side: THREE.DoubleSide,
      }),
    );
    this.line.renderOrder = 5;
    this.line.frustumCulled = false;
    this.lockGroup.add(this.line);

    // 四个 L 形角标
    const arm = new THREE.BoxGeometry(0.9, 0.06, 0.16);
    arm.translate(0.45, 0, 0);
    this.geos.push(arm);
    for (const [g, mat] of [[this.bracket, this.bracketMat], [this.outBracket, this.outMat]] as const) {
      for (let i = 0; i < 4; i++) {
        const corner = new THREE.Group();
        const a = new THREE.Mesh(arm, mat);
        const b = new THREE.Mesh(arm, mat);
        b.rotation.y = -Math.PI / 2;
        corner.add(a, b);
        corner.position.set(i === 0 || i === 3 ? -1 : 1, 0, i < 2 ? -1 : 1);
        corner.rotation.y = [0, -Math.PI / 2, Math.PI, Math.PI / 2][i];
        g.add(corner);
      }
      g.renderOrder = 5;
    }
    this.lockGroup.add(this.bracket);
    this.lockGroup.visible = false;
    this.outBracket.visible = false;
    this.group.add(this.lockGroup, this.outBracket);
  }

  /** 开炮时闪一下 */
  pulse(): void {
    this.flash = 1;
  }

  /** target.y = 天上目标的世界高度（T125）：线画到它身上、锁定框立在它身上朝着镜头；不给 = 地面目标，框贴地 */
  update(delta: number, muzzle: THREE.Vector3 | null, target: Mark | null, showLine = true): void {
    this.time += delta;
    this.flash = Math.max(0, this.flash - delta * 6);
    if (!muzzle || !target) {
      this.lockGroup.visible = false;
      return;
    }
    this.lockGroup.visible = true;
    this.line.visible = showLine;
    this.from.copy(muzzle);
    const sky = target.y !== undefined && this.camera !== null;
    this.to.set(target.x, sky ? target.y! : 1.4, target.z);
    const len = this.from.distanceTo(this.to);
    this.line.position.copy(this.from);
    this.line.lookAt(this.to);
    this.line.scale.set(0.42 + this.flash * 0.3, 1, len);
    const u = this.line.material.uniforms;
    u.uTime.value = this.time;
    u.uLen.value = len;
    u.uFlash.value = this.flash;

    this.place(this.bracket, target, (target.radius + 0.8) * (1 + this.flash * 0.25), Math.PI / 4 + Math.sin(this.time * 2) * 0.08);
  }

  /** 够不着的灰框（T131）：套在主武器抬不上去的天上目标身上；null = 收起 */
  out(target: Mark | null): void {
    this.outBracket.visible = target !== null;
    if (target) this.place(this.outBracket, target, target.radius + 0.8, Math.PI / 4);
  }

  /** 角标框摆到目标上：天上的（y 给了）立在它身上朝着镜头，地面的贴地 */
  private place(b: THREE.Group, target: Mark, s: number, spin: number): void {
    b.scale.set(s, 1, s);
    if (target.y !== undefined && this.camera) {
      b.position.set(target.x, target.y, target.z);
      b.quaternion.copy(this.camera.quaternion).multiply(FACE).multiply(SPIN.setFromAxisAngle(UP, spin));
    } else {
      b.position.set(target.x, 0.12 + this.groundAt(target.x, target.z), target.z);
      b.rotation.set(0, spin, 0);
    }
  }

  dispose(): void {
    for (const g of this.geos) g.dispose();
    this.line.material.dispose();
    this.bracketMat.dispose();
    this.outMat.dispose();
  }
}
