import { AIRSHIP } from '../bosses/airship';
import { ELITE, type EnemyKind } from '../entities/Enemy';
import { threatMods } from '../meta/econ';
import { ROAD_HALF_WIDTH } from '../systems/World';
import { RUN, airZone, cyc, sandZone } from './cycle';
import { rng } from './rng';

/** 每个区域的时长（秒）：到点出首领，击毁后进入下一区域；第 3 区之后无限推进 */
export const ZONE_TIME = 180;
const FIRST_ELITE = 50;
/** 精英（T017-9C）：50 秒起，之后每 55～80 秒随机来一个（原来固定每 65 秒） */
const ELITE_GAP: [number, number] = [55, 80];
/**
 * 精英随机池（T017-9A / 9C，按区解锁、不连续重复）：第 1 区巨像 / 铁壁，第 2 区起加冰雹王 / 破城槌。
 * 策划 §10 的池子里还有第 1 区的「蜂巢」母车、第 3 区的「血棱」光棱领主，这次按方案 B 只做了 3 种新精英，没做的这两种不在池子里
 */
const ELITE_POOL: EnemyKind[][] = [['heavy', 'bulwark'], ['heavy', 'bulwark', 'hailking', 'ram'], ['heavy', 'heavy', 'bulwark', 'bulwark', 'hailking', 'hailking', 'hailking', 'ram', 'ram']];
/**
 * 区域 5 的精英池（T093）：不放冰雹王（徐进弹幕和秃鹫的火箭红圈叠在一起就成了躲弹幕）；
 * T095 加「铁鹰」重型直升机，不和上一个重复；一次只有一个精英，所以场上最多一架铁鹰。
 * T099（制作人「第五关的空中敌人数量多一些，地面相对少一些」）：铁鹰两份 → 三份（抽到的比例 40% → 50%）
 */
const AIR_ELITES: EnemyKind[] = ['heavy', 'bulwark', 'ram', 'gunship', 'gunship', 'gunship'];
/**
 * 区域 5 的空中计时器（T093，D1-035《区域 5》5.2 节）：空中敌人不进地面敌潮的抽签，按这张定点表来（区内秒数 ± jitter）。
 * v = 秃鹫（pad 停坪起飞 / enter 正面进场）、l = 一队飞蝗几个、moto = 同一批的地面摩托（狼群）、mg = 守坪的机枪组。
 * T099 加密：10 批 → 16 批，秃鹫 6 → 9 架、飞蝗 22 → 45 个（每分钟 2 → 3 架、7.3 → 15 个）；地面敌潮相应变稀（AIR.wave、waveBody 第 5 列）
 */
type AirBatch = { t: number; v?: 'pad' | 'enter'; l?: number; moto?: number; mg?: number };
const AIR_PLAN: AirBatch[] = [
  { t: 12, l: 3 },
  { t: 20, v: 'pad' },
  { t: 32, l: 4 },
  { t: 42, v: 'enter' },
  { t: 52, l: 4, moto: 2 },
  { t: 62, v: 'pad', l: 3 },
  { t: 74, l: 4 },
  { t: 84, v: 'enter', mg: 2 },
  { t: 94, l: 4 },
  { t: 104, v: 'pad', l: 3 },
  { t: 116, l: 5 },
  { t: 126, v: 'enter', l: 3 },
  { t: 138, v: 'enter', l: 4 },
  { t: 150, l: 5 },
  { t: 158, v: 'enter', l: 3 },
  { t: 166, v: 'enter' },
];
/**
 * 区域 6「沙漠油井」的空中计时器（T122，制作人「这关的杂兵也多安排一些空军敌人」）：策划原稿只有 2 架秃鹫、不放飞蝗，改成 11 批——
 * 秃鹫 6 架、飞蝗 30 个，和伏兵定点表错开 2～4 秒，「地下钻出来 + 天上压下来」一起来；152 秒以后喘口气，不再来。
 * 规矩同区域 5（AIR：上限、警报、拦路 × 0.7、170 秒还没轮上就取消）。区域 1～4 照旧一个都不放，区域 5 照旧 AIR_PLAN
 */
const SAND_AIR: AirBatch[] = [
  { t: 18, l: 3 },
  { t: 30, v: 'enter' },
  { t: 46, l: 4 },
  { t: 58, v: 'enter', l: 3 },
  { t: 74, l: 4 },
  { t: 86, v: 'enter' },
  { t: 98, l: 4 },
  { t: 110, v: 'enter', l: 3 },
  { t: 124, l: 5 },
  { t: 134, v: 'enter' },
  { t: 146, v: 'enter', l: 4 },
];
/** 这一区的空中计时器（区域 5 / 6 有，别的区 null） */
const airPlanOf = (zone: number): AirBatch[] | null => (airZone(zone) ? AIR_PLAN : sandZone(zone) ? SAND_AIR : null);
/**
 * 区域 6 的精英池（T122）：巨像、冰雹王、破城槌 + 一架「铁鹰」（制作人要空中多一些）；不放铁壁（伏兵已经从侧面来，再绕侧面打盾太挤）
 */
const SAND_ELITES: EnemyKind[] = ['heavy', 'hailking', 'ram', 'gunship'];
/**
 * 区域 6 的沙下伏兵定点表（T122，D3 区域 6 策划 1.6 节；区内秒数 ± SAND.jitter）：small = 几个小包（同一侧）、smoke = 几个黑烟包、wave = 一条沙下车队、
 * string = 「一串」（同一侧 3 个小包，前后隔 6 米、一个比一个晚 0.4 秒冒）、both = 黑烟包左右各一（整区只有这一次）、near = 小包贴着磕头机、
 * pincer = 「钳」：同一刻正面强制来一波敌潮；tut = 每局第一次各弹一条教学提示（Ambush.TUT 第几条）
 */
export interface SandEvent {
  t: number;
  small?: number;
  smoke?: number;
  wave?: boolean;
  string?: boolean;
  both?: boolean;
  near?: boolean;
  pincer?: boolean;
  tut?: number;
}
const SAND_PLAN: SandEvent[] = [
  { t: 12, small: 1, tut: 0 },
  { t: 22, small: 1 },
  { t: 35, smoke: 1, tut: 1 },
  { t: 44, small: 1, near: true, tut: 2 },
  { t: 56, string: true, pincer: true },
  { t: 64, smoke: 1 },
  { t: 72, wave: true, tut: 3 },
  { t: 82, string: true },
  { t: 90, smoke: 1, small: 1, pincer: true },
  { t: 98, small: 2 },
  { t: 106, wave: true },
  { t: 114, string: true },
  { t: 122, smoke: 2, both: true, pincer: true },
  { t: 130, small: 2 },
  { t: 138, wave: true },
  { t: 146, string: true },
];
/**
 * 沙下伏兵的规矩（T122）：jitter = 每次 ± 秒；blocked = 精英拦路时定点表的钟 × 0.5、只出小包；quiet = 精英倒下后几秒不出；cap = 一屏最多几处（一串算一处，满了顺延）；
 * last = 几秒以后不再出；wave = 区域 6 的地面敌潮间隔 ×（伏兵分走一点压力）；calmAt / calm = 几秒起敌潮 × 多少（喘口气）；surge = 几秒大沙浪从车底下穿过去；
 * supply / heal = 几秒前方两个维修箱、各回多少
 */
export const SAND = { jitter: 2, blocked: 0.5, quiet: 8, cap: 2, last: 152, wave: 1.1, calmAt: 152, calm: 0.55, surge: 150, supply: 165, heal: 0.3 };
/** 「穿山」刷在车前多少米（沙浪从这里冲过来；T122） */
export const SAND_BOSS = 90;
/**
 * 空中计时器的规矩：jitter = 每批 ± 秒；blocked = 精英 / 卫队拦路时计时器 ×；siren = 每批之前几秒远处响一声防空警报（warm = 热身段那一声）；
 * cap = 同屏上限（秃鹫几架、飞蝗几队、空中单位总数），到了上限这一批往后顺延，last 秒还没轮上就取消；wave = 区域 5 的地面敌潮间隔 ×
 * （T099：上限 2 / 2 / 12 → 3 / 3 / 18，间隔 × 1.15 → 1.2）。
 * 空中卫队（7.1 节，180 秒压轴，首领没定前打完 = 区域 5 通关）：hp = 两架秃鹫的耐久倍率、stand = 压到车前几米（T098：20～24 → 50～54，停在机枪射程边上）、squads = 第几秒各来一队飞蝗（squad 个）、
 * at = 地面反坦克兵几个；rest / heal = 打完几秒不刷 / 两个维修箱各回耐久上限的多少
 */
export const AIR = {
  jitter: 2,
  blocked: 0.7,
  siren: 2.5,
  warm: 15,
  cap: { vulture: 3, squads: 3, total: 18 },
  last: 170,
  wave: 1.2,
  guard: { hp: 1.6, stand: [50, 54] as [number, number], squads: [0, 15, 30], squad: 4, at: 2, rest: 6, heal: 0.2 },
};
/** 巨炮「轰天」那一区（第 4 区，无尽里每轮一次，和 createBoss 的 index 3 对应；T093 起按本局轮回 cyc 算）：首领刷在 250 米外、100 秒起远方炮击 */
export const siegeZone = (zone: number) => cyc(zone) === 3;
/** 巨炮刷在前方多远（别的首领按据点距离；D5：280 → 250，冲锋约 20 秒、3 发巨弹） */
const SIEGE_AHEAD = 250;
/** 敌潮刷在前方这么远（再往前 0～15 米随机）；T020-a 起由 Game 每帧按画面上沿改 `spawnAhead`，这里是下限 */
export const SPAWN_AHEAD = 115;
/** spawnAhead 比画面上沿碰地远多少米（Game 按 上沿 + 10 摆）；一波里最近的那个至少在上沿外 EDGE_MARGIN 米 */
export const SPAWN_MARGIN = 10;
const EDGE_MARGIN = 3;
/** 据点距离：重坦刷在玩家前方这么远，掩体放在它前面（T020-a 起同上，`strongholdAhead`） */
export const STRONGHOLD_AHEAD = 118;
const COVER_OFFSET = 26;

export interface SpawnOpts {
  size?: number;
  boss?: boolean;
  /** 耐久倍率（T050 卫队） */
  hp?: number;
  /** 「轰天」卫队成员（T050） */
  gate?: boolean;
}

export interface DirectorHooks {
  spawn(kind: EnemyKind, x: number, z: number, opts?: SpawnOpts): void;
  /** 区域首领：zone 从 1 开始 */
  boss(zone: number, x: number, z: number): void;
  /** 刷点避河（T025）：(x, z) 压到河道（+ margin）就往前挪到对岸干地，返回挪完的 z */
  dry?(x: number, z: number, margin: number): number;
  /** 首领要刷在 z 附近（T027-d）：首领战场附近还没进画面的河收掉 */
  arena?(z: number): void;
  cover(x: number, z: number): void;
  /** 首领战前的补给：在玩家前方放两个维修箱（heal = 各回耐久上限的多少，默认三成） */
  supplies(heal?: number): void;
  announce(title: string, sub: string): void;
  /** 「轰天」卫队刚刷完（T050） */
  gate?(): void;
  /** 区域 5 的压轴打完了（T093；T100B 起由 Game 在空艇撤离演完时调，不再由 Director 直接调） */
  airCleared?(): void;
  /** 区域 5 的空中敌人（T093）：v = 一架秃鹫（停坪 / 正面进场，null = 不要）、l = 一队飞蝗几个（0 = 不要） */
  air?(v: 'pad' | 'enter' | null, l: number): void;
  /** 场上还在天上（或停在坪上）的：秃鹫几架、飞蝗几队、空中单位一共几个 */
  airCount?(): { v: number; l: number; n: number };
  /** 远处一声防空警报 */
  siren?(): void;
  /** 空中卫队（T093）：start = 刷两架秃鹫 + 反坦克兵 + 横幅，rest = 打完了（维修箱由 Director 放） */
  airGuard?(ev: 'start' | 'rest'): void;
  /** 区域 6 的沙下伏兵（T122）：按定点表的一次（鼓起几个包、哪一种，Game → Ambush 摆） */
  ambush?(ev: SandEvent): void;
  /** 场上还在鼓 / 在跑的伏兵几处（一串算一处） */
  ambushCount?(): number;
  /** 区域 6 的 150 秒：大沙浪从车底下穿过去 */
  surge?(): void;
}

const rand = (a: number, b: number) => a + rng.spawn() * (b - a);
const roadX = (margin = 3) => rand(-ROAD_HALF_WIDTH + margin, ROAD_HALF_WIDTH - margin);

/** 战场导演：按区域与时间安排敌潮、拦路精英、首领（T036 起没有空投箱了） */
export class Director {
  zone = 1;
  zoneTime = 0;
  private waveTimer = 2;
  private eliteTimer = FIRST_ELITE;
  private bossOut = false;
  /** 上一个精英（不连续重复） */
  private lastElite: EnemyKind | null = null;
  /** 「轰天」卫队（T050，只在巨炮区）：0 还没来 / 1 拦路中 / 2 清完、喘口气（gateT 秒）/ 3 打完了（该出巨炮） */
  gate = 0;
  private gateT = 0;
  /** 区域 5 的空中卫队（T093）：0 还没来 / 1 拦路中 / 2 清完、喘口气 / 3 打完了（区域 5 通关）；guardT = 拦路了几秒、guardN = 来了几队飞蝗 */
  airGuard = 0;
  private guardT = 0;
  private guardN = 0;
  /** 区域 5 的空中计时器（T093）：airClock = 计时器走到几秒（拦路时走得慢），airI = 下一批是表里第几个，airAt = 每批抖动后的时间，siren = 警报响到第几批 */
  airClock = 0;
  private airI = 0;
  private airAt: number[] = [];
  private sirenI = -1;
  /** 区域 6 的沙下伏兵定点表（T122）：sandClock = 钟走到几秒（精英拦路时走得慢）、sandI = 下一次是表里第几个、sandAt = 抖动后的时间、
   * sandQuiet = 精英倒下后还有几秒不出、sandHeld = 上一帧有没有精英拦路、surged / supplied = 150 秒大沙浪 / 165 秒维修箱放过没有 */
  private sandClock = 0;
  private sandI = 0;
  private sandAt: number[] = [];
  private sandQuiet = 0;
  private sandHeld = false;
  private surged = false;
  private supplied = false;
  /** 敌潮 / 据点刷在前方多远（T020-a：Game 每帧按画面上沿碰地的距离 + 10 / + 12 米改，下限 115 / 118、上限 175 / 178） */
  spawnAhead = SPAWN_AHEAD;
  strongholdAhead = STRONGHOLD_AHEAD;
  /** 战区威胁（T030）：这一局的等级和敌方加成（敌潮 / 耐久 / 精英 / 伤害；首领耐久 / 背景炮击 / 首领狂暴由 Game 用） */
  threat = 0;
  mods = threatMods(0);

  setThreat(lv: number): void {
    this.threat = lv;
    this.mods = threatMods(lv);
  }

  constructor(private readonly hooks: DirectorHooks) {}

  /** 这一区的首领已经刷出来了（T027-d：河不再往前摆） */
  get bossActive(): boolean {
    return this.bossOut;
  }

  /** 敌人血量倍率：区域内从 1 涨到 2（跟上玩家升级后的火力），每进一个区域整体 ×1.6（荒原机场那一局按低 RUN.ease 个区算，T099） */
  get hpScale(): number {
    return (1 + Math.min(this.zoneTime, ZONE_TIME) / ZONE_TIME) * Math.pow(1.6, this.zone - 1 - RUN.ease) * this.mods.hp;
  }

  /** 敌人伤害倍率：每进一个区域 ×1.3 */
  get dmgScale(): number {
    return Math.pow(1.3, this.zone - 1 - RUN.ease) * this.mods.dmg;
  }

  get label(): string {
    return (this.zone <= RUN.zones ? `区域 ${this.zone}` : `无尽 ${this.zone - RUN.zones}`) + (this.threat ? ` · 威胁 ${this.threat}` : '');
  }

  reset(): void {
    this.zone = 1;
    this.zoneTime = 0;
    this.waveTimer = 2;
    this.eliteTimer = FIRST_ELITE;
    this.bossOut = false;
    this.lastElite = null;
    this.gate = 0;
    this.gateT = 0;
    this.resetAir(0);
  }

  /** 空中计时器 / 沙下伏兵定点表从区内 t 秒开始（新进区 / 读档 / 直通：已经过了的批次不补） */
  private resetAir(t: number): void {
    this.airGuard = 0;
    this.guardT = 0;
    this.guardN = 0;
    this.airClock = t;
    const plan = airPlanOf(this.zone) ?? AIR_PLAN;
    this.airAt = plan.map((p) => p.t + rand(-AIR.jitter, AIR.jitter));
    this.airI = plan.findIndex((p) => p.t >= t);
    if (this.airI < 0) this.airI = plan.length;
    this.sirenI = t > AIR.warm ? this.airI - 1 : -2;
    this.sandClock = t;
    // 只在区域 6 抽（别的区随机源的顺序和以前一样）
    this.sandAt = sandZone(this.zone) ? SAND_PLAN.map((p) => p.t + rand(-SAND.jitter, SAND.jitter)) : [];
    this.sandI = SAND_PLAN.findIndex((p) => p.t >= t);
    if (this.sandI < 0) this.sandI = SAND_PLAN.length;
    this.sandQuiet = 0;
    this.sandHeld = false;
    this.surged = t >= SAND.surge;
    this.supplied = t >= SAND.supply;
  }

  /** 读档：回到存档时的区域与区域内时间 */
  restore(zone: number, zoneTime: number): void {
    this.reset();
    this.zone = zone;
    this.zoneTime = zoneTime;
    this.eliteTimer = zoneTime < FIRST_ELITE ? FIRST_ELITE - zoneTime : ELITE_GAP[0] * 0.5;
    this.resetAir(zoneTime);
  }

  /** 这次来哪种精英：当前区的池子里随机，不和上一个重复 */
  private pickElite(): EnemyKind {
    // 第 4 区起冰雹王（炮兵指挥车）权重 ×1.5（T019-a 4.1）；区域 5 不放冰雹王（T093）；区域 6 自己一池（T122）
    const pool = (airZone(this.zone) ? AIR_ELITES : sandZone(this.zone) ? SAND_ELITES : ELITE_POOL[Math.min(ELITE_POOL.length, this.zone) - 1]).filter((k) => k !== this.lastElite);
    const kind = pool[Math.floor(rng.spawn() * pool.length)];
    this.lastElite = kind;
    return kind;
  }

  /** blocked：场上还有存活的拦路精英/首领 */
  update(delta: number, px: number, pz: number, blocked: boolean): void {
    if (!this.bossOut) this.zoneTime += delta;

    // 巨炮战（D5 A2）：敌潮停掉，换成巨炮自己从炮台大门放出来的清杂小兵（SiegeGun.stepMinions）
    // 卫队清完到巨炮出场这几秒（T050）也不刷；空艇「云垒」（T100B）同样只有机库放兵门出来的小兵
    // 「穿山」（T122）同样整场停敌潮，只有它自己车厢里放出来的兵
    const siegeFight = (this.bossOut && (siegeZone(this.zone) || airZone(this.zone) || sandZone(this.zone))) || this.gate === 2 || this.airGuard === 2;
    const sand = sandZone(this.zone);
    const calm = sand && this.zoneTime >= SAND.calmAt ? SAND.calm : 1;
    this.waveTimer -= delta * (siegeFight ? 0 : blocked ? 0.55 : 1) * calm * this.mods.wave;
    if (this.waveTimer <= 0) {
      this.wave(pz);
      // 区域越往后敌潮越密：区域 1 从 4 秒一波压到约 2.6 秒，区域 3 约 1.5 秒；区域 5 再 × AIR.wave（空中分走一部分压力，T093 / T099）；区域 6 × SAND.wave（T122）
      this.waveTimer = Math.max(1.5, 4.4 - this.zone * 0.5 - (this.zoneTime / ZONE_TIME) * 1.3) * (airZone(this.zone) ? AIR.wave : sand ? SAND.wave : 1);
    }
    if (airPlanOf(this.zone) && !this.bossOut) this.stepAir(delta, pz, blocked);
    if (sand && !this.bossOut) this.stepSand(delta, pz, blocked);

    if (blocked || this.bossOut) return;
    if (this.zoneTime >= ZONE_TIME && airZone(this.zone)) {
      // 区域 5（T093）：180 秒空中卫队拦路；两架秃鹫都打掉 → 两个维修箱 + 6 秒不刷 → 首领「云垒」（T100B：机库正中在车前 AIRSHIP.ahead 米、T104 起在路右边，它撤离 = 区域 5 通关）
      if (this.airGuard === 0) {
        this.airGuard = 1;
        this.guardT = 0;
        this.guardN = 0;
        this.hooks.airGuard?.('start');
        return;
      }
      if (this.airGuard === 1) {
        this.airGuard = 2;
        this.gateT = AIR.guard.rest;
        this.hooks.supplies(AIR.guard.heal);
        this.hooks.airGuard?.('rest');
      }
      this.gateT -= delta;
      if (this.gateT > 0) return;
      this.airGuard = 3;
      this.bossOut = true;
      this.hooks.arena?.(pz - AIRSHIP.ahead);
      this.hooks.boss(this.zone, 0, pz - AIRSHIP.ahead);
      this.hooks.announce('区域首领来袭', '前方有维修补给');
      this.hooks.supplies();
      return;
    }
    if (this.zoneTime >= ZONE_TIME && sandZone(this.zone)) {
      // 区域 6（T122）：不放卫队，「穿山」在车前 SAND_BOSS 米的沙下冒出来（沙浪撕开路边冲过来，停车线在坦克前方 30 米），不摆掩体不带兵
      this.bossOut = true;
      this.hooks.arena?.(pz - SAND_BOSS);
      this.hooks.boss(this.zone, 0, pz - SAND_BOSS);
      this.hooks.announce('区域首领来袭', '前方有维修补给');
      this.hooks.supplies();
      return;
    }
    if (this.zoneTime >= ZONE_TIME) {
      // 巨炮区（T050）：先来「轰天」卫队；三个都打掉 → 两个维修箱 + 喘口气 → 巨炮
      if (siegeZone(this.zone) && this.gate < 3) {
        if (this.gate === 0) {
          this.gate = 1;
          this.guard(pz, this.strongholdAhead);
          return;
        }
        if (this.gate === 1) {
          this.gate = 2;
          this.gateT = ELITE.gate.rest;
          this.hooks.supplies(ELITE.gate.heal);
        }
        this.gateT -= delta;
        if (this.gateT > 0) return;
        this.gate = 3;
      }
      this.bossOut = true;
      this.stronghold(px, pz, true);
      return;
    }
    this.eliteTimer -= delta * this.mods.elite;
    if (this.eliteTimer <= 0) {
      this.eliteTimer = rand(ELITE_GAP[0], ELITE_GAP[1]);
      // 卫队前 30 秒不再来普通精英（T050；区域 5 的空中卫队一样，T093；区域 6 首领前喘口气，T122）
      if ((!siegeZone(this.zone) && !airZone(this.zone) && !sandZone(this.zone)) || this.zoneTime < ZONE_TIME - ELITE.gate.calm) this.stronghold(px, pz, false, this.pickElite());
    }
  }

  /** 拦路精英/首领被击毁；首领倒下进入下一区域（announce = 下一区的横幅交给谁放，D5：Game 让击破横幅先停一会儿再放） */
  blockerDown(boss: boolean, announce: (title: string, sub: string) => void = this.hooks.announce): void {
    if (!boss) return;
    this.bossOut = false;
    this.zone += 1;
    this.zoneTime = 0;
    this.eliteTimer = FIRST_ELITE;
    this.gate = 0;
    this.resetAir(0);
    announce(this.label, this.zone > RUN.zones ? '无尽推进开始' : cyc(this.zone) === 4 ? '荒原机场 · 小心头顶' : cyc(this.zone) === 5 ? '沙漠油井 · 小心脚下' : '敌军火力增强');
  }

  /**
   * 区域 5 的空中计时器（T093）：按 AIR_PLAN 一批一批来，每批之前 2.5 秒远处响一声防空警报；拦路时计时器 × 0.7；
   * 到了同屏上限往后顺延，170 秒还没轮上就取消。空中卫队拦路中：开场 / 15 / 30 秒各来一队飞蝗
   */
  private stepAir(delta: number, pz: number, blocked: boolean): void {
    const A = AIR;
    if (this.airGuard === 1) {
      this.guardT += delta;
      while (this.guardN < A.guard.squads.length && this.guardT >= A.guard.squads[this.guardN]) {
        this.guardN += 1;
        this.hooks.air?.(null, A.guard.squad);
      }
      return;
    }
    if (this.airGuard) return;
    const plan = airPlanOf(this.zone);
    if (!plan) return;
    this.airClock += delta * (blocked ? A.blocked : 1);
    if (this.sirenI === -2 && this.airClock >= A.warm) {
      this.sirenI = -1;
      this.hooks.siren?.();
    }
    while (this.airI < plan.length) {
      const p = plan[this.airI];
      const at = this.airAt[this.airI];
      if (this.sirenI < this.airI && this.airClock >= at - A.siren) {
        this.sirenI = this.airI;
        this.hooks.siren?.();
      }
      if (this.airClock < at) return;
      const c = this.hooks.airCount?.() ?? { v: 0, l: 0, n: 0 };
      const full = (!!p.v && c.v >= A.cap.vulture) || (!!p.l && c.l >= A.cap.squads) || c.n + (p.v ? 1 : 0) + (p.l ?? 0) > A.cap.total;
      if (full && this.airClock < A.last) return;
      this.airI += 1;
      if (full) continue;
      this.hooks.air?.(p.v ?? null, p.l ?? 0);
      const z = pz - this.spawnAhead;
      for (let i = 0; i < (p.moto ?? 0); i++) this.hooks.spawn('moto', (i % 2 ? -1 : 1) * (ROAD_HALF_WIDTH + 4), z + 30 - i * 6);
      for (let i = 0; i < (p.mg ?? 0); i++) this.hooks.spawn('mgteam', (i % 2 ? -1 : 1) * rand(ROAD_HALF_WIDTH - 4, ROAD_HALF_WIDTH), pz - 100 - i * 6);
    }
  }

  /**
   * 区域 6 的沙下伏兵（T122）：按 SAND_PLAN 一次一次来；精英拦路时钟 × 0.5、只出小包，精英倒下后 8 秒不出；场上已经有 cap 处就顺延，
   * last 秒以后不再出；标了「钳」的同一刻正面强制来一波敌潮。150 秒大沙浪从车底下穿过去、165 秒前方两个维修箱
   */
  private stepSand(delta: number, pz: number, blocked: boolean): void {
    if (this.sandHeld && !blocked) this.sandQuiet = SAND.quiet;
    this.sandHeld = blocked;
    this.sandQuiet -= delta;
    this.sandClock += delta * (blocked ? SAND.blocked : 1);
    if (this.zoneTime >= ZONE_TIME) return;
    if (!this.surged && this.zoneTime >= SAND.surge) {
      this.surged = true;
      this.hooks.surge?.();
    }
    if (!this.supplied && this.zoneTime >= SAND.supply) {
      this.supplied = true;
      this.hooks.supplies(SAND.heal);
    }
    while (this.sandI < SAND_PLAN.length) {
      if (this.zoneTime >= SAND.last) {
        this.sandI = SAND_PLAN.length;
        return;
      }
      if (this.sandClock < this.sandAt[this.sandI] || this.sandQuiet > 0 || (this.hooks.ambushCount?.() ?? 0) >= SAND.cap) return;
      const p = SAND_PLAN[this.sandI];
      this.sandI += 1;
      const ev: SandEvent = blocked ? { t: p.t, small: 1, tut: p.tut } : p;
      this.hooks.ambush?.(ev);
      if (ev.pincer) this.wave(pz);
    }
  }

  /** 调试 / 测试：立刻刷「轰天」卫队（T050；距离固定 118 米，和 forceStronghold 一样） */
  forceGate(pz: number): void {
    this.gate = 1;
    this.guard(pz, STRONGHOLD_AHEAD);
  }

  /**
   * 「轰天」卫队（T050）：铁壁居中、冰雹王 / 破城槌分在两边（左右随机），前面两个掩体、一班步兵；不带自行火炮 / 中坦 / 火箭兵。
   * 摆在平时据点的距离，巨炮远景这时在 250 米外，正好在它们身后；这一片还没进画面的河收掉
   */
  private guard(pz: number, ahead: number): void {
    const G = ELITE.gate;
    const side = rng.spawn() < 0.5 ? -1 : 1;
    this.hooks.arena?.(pz - ahead);
    const z = this.hooks.dry ? this.hooks.dry(0, pz - ahead + 8, 26) - 8 : pz - ahead;
    for (const [kind, dx, dz] of G.at) this.hooks.spawn(kind, dx * side, z + dz, { hp: G.hp, gate: true });
    for (const dx of [-5.5, 5.5]) this.hooks.cover(dx, z + COVER_OFFSET);
    this.squad(0, z + 8, G.squad);
    this.hooks.gate?.();
  }

  /**
   * 调试 / 截图用：立刻刷一个据点（kind = 哪种精英，默认巨像，测试 / 脚本的结果不变；'random' = 按当前区的池子随机）。
   * 距离固定在原来的 118 米（STRONGHOLD_AHEAD，T020-a 拉远之前），测试 / 脚本里「刷出来再 warp 多少米」的写法都不用改
   */
  forceStronghold(px: number, pz: number, boss = false, kind: EnemyKind | 'random' = 'heavy'): void {
    if (boss) this.bossOut = true;
    this.stronghold(px, pz, boss, kind === 'random' ? this.pickElite() : kind, STRONGHOLD_AHEAD);
  }

  /** 一波敌潮先攒在这里，整波摆好再刷（见 wave 末尾）；null = 直接刷（据点） */
  private batch: [EnemyKind, number, number][] | null = null;

  private put(kind: EnemyKind, x: number, z: number): void {
    if (this.batch) this.batch.push([kind, x, z]);
    else this.hooks.spawn(kind, x, z);
  }

  private wave(pz: number): void {
    this.batch = [];
    this.waveBody(pz);
    const units = this.batch;
    this.batch = null;
    // 整波往前方挪，最近的一个也在画面上沿外 EDGE_MARGIN 米（T038：摩托 +40、加特林 +22、机枪组 +18…这几种本来就往你这边错开摆，
    // 拉远（T020-a）以后会在画面上沿里面一点冒出来）；阵形和先后不变，只是这几种整波远一点
    const line = pz - (this.spawnAhead - SPAWN_MARGIN) - EDGE_MARGIN;
    const shift = Math.min(0, line - Math.max(...units.map((u) => u[2])));
    for (const [kind, x, z] of units) this.hooks.spawn(kind, x, z + shift);
  }

  private waveBody(pz: number): void {
    const z = pz - this.spawnAhead - rng.spawn() * 15;
    // 每个区域的敌潮构成：[类型, 区域1/2/3/4/5 权重]，第 4 区之后沿用第 4 区（T019-a：第 4 区偏炮兵——自行火炮 / 火箭炮车 / 反坦克炮 / 加特林 / 装甲更多）；
    // 区域 5「荒原机场」（T093，策划 5.1 节）单独一列：地面换成快的轻的（轻车 / 自爆卡车 / 摩托 / 运兵车多），少炮兵、少光棱，红圈留给天上；
    // T099 天上加密以后地面再让一点：装甲 2.4 → 2.0、运兵车 2.8 → 2.4、电击兵 2.0 → 1.6、混编 2.6 → 2.2（重的、成群的少一些）
    // 区域 6「沙漠油井」（T122，策划 1.5 节）单独一列：侧翼和近身多（反坦克兵 / 摩托 / 强攻冲锋 / 机枪组），炮兵 / 光棱少（红圈留给首领），步兵 / 轻车让给沙下伏兵
    const zi = airZone(this.zone) ? 4 : sandZone(this.zone) ? 5 : Math.min(3, this.zone - 1);
    const early = this.zone === 1 && this.zoneTime < 25;
    const table: [string, number][] = (
      [
        ['squad', [5, 4, 3.5, 3.5, 3.5, 3.0]],
        ['lights', [3, 2.8, 2.8, 2.8, 3.4, 2.4]],
        ['armor', [this.zoneTime > 40 || this.zone > 1 ? 1.8 : 0, 2.8, 3.2, 3.4, 2.0, 3.0]],
        ['gatling', [this.zoneTime > 45 || this.zone > 1 ? 1.4 : 0, 1.8, 2.0, 2.2, 1.2, 1.4]],
        ['rockets', [this.zoneTime > 100 || this.zone > 1 ? 1.1 : 0, 1.8, 2.0, 2.4, 1.0, 1.6]],
        ['prisms', [this.zoneTime > 125 ? 0.9 : 0, 1.6, 2.2, 2.2, 0.8, 1.2]],
        ['banzai', [this.zoneTime > 70 || this.zone > 1 ? 1.0 : 0, 1.5, 1.8, 1.8, 1.8, 2.2]],
        ['trucks', [this.zone > 1 || this.zoneTime > 45 ? 1.2 : 0, 1.8, 2, 2, 2.4, 2]],
        ['motos', [this.zoneTime > 30 || this.zone > 1 ? 1.4 : 0, 2, 2, 2, 3.0, 3.0]],
        ['antiTank', [early ? 0 : 2, 2.4, 2.6, 2.6, 2.6, 3.2]],
        ['apc', [0, 2.2, 2.4, 2.4, 2.4, 2.0]],
        ['artillery', [0, 1.4, 1.8, 2.6, 1.2, 2.0]],
        ['atguns', [0, 1.3, 1.6, 2.0, 1.2, 2.0]],
        ['shock', [0, 0, 2.6, 2.6, 1.6, 2.0]],
        ['mgnest', [this.zoneTime > 40 || this.zone > 1 ? 1.2 : 0, 1.6, 1.6, 1.6, 1.6, 2.0]],
        ['combined', [this.zoneTime > 60 || this.zone > 1 ? 1.6 : 0, 2.2, 2.4, 2.4, 2.2, 2.4]],
      ] as [string, number[]][]
    ).map(([id, w]) => [id, w[zi]] as [string, number]);
    const total = table.reduce((s, [, w]) => s + w, 0);
    let roll = rng.spawn() * total;
    let pick = 'squad';
    for (const [id, w] of table) {
      roll -= w;
      if (roll <= 0) {
        pick = id;
        break;
      }
    }
    switch (pick) {
      case 'squad': this.squad(roadX(), z, Math.min(18, 6 + this.zone * 2 + Math.floor(this.zoneTime / 50) + Math.floor(rng.spawn() * 4))); break;
      case 'lights': this.lights(z); break;
      case 'armor': this.armor(z); break;
      case 'banzai':
        // 强攻冲锋：一排爆破兵从两翼包抄冲向坦克，后面有步兵火力掩护
        for (let i = 0; i < 4 + this.zone * 2; i++) this.put('sapper', clampAbs((i % 2 ? -1 : 1) * rand(3, ROAD_HALF_WIDTH), ROAD_HALF_WIDTH), z + 15 + i * 2.5);
        this.squad(roadX(), z - 4, 4);
        break;
      case 'rockets':
        // 火箭炮车躲在后排，前面有步兵和轻坦顶着
        for (let i = 0; i < (this.zone >= 2 && rng.spawn() < 0.5 ? 2 : 1); i++) this.put('rocketTank', roadX(5), z - 14 - i * 8);
        this.squad(roadX(), z + 6, 5);
        if (this.zone >= 2) this.put('gunner', roadX(), z);
        break;
      case 'prisms': {
        // 光棱坦克成组出现：靠得近才能互相折射增幅
        const cx = roadX(6);
        const n = this.zone >= 3 ? 3 : 2;
        for (let i = 0; i < n; i++) this.put('prism', clampAbs(cx + (i - (n - 1) / 2) * 7, ROAD_HALF_WIDTH - 2), z - 6 + (i % 2) * 6);
        break;
      }
      case 'gatling':
        // 加特林机枪塔架在路边，前面有步兵顶着
        for (const side of this.zone >= 2 && rng.spawn() < 0.5 ? [-1, 1] : [rng.spawn() < 0.5 ? -1 : 1]) this.put('gatling', side * rand(ROAD_HALF_WIDTH - 5, ROAD_HALF_WIDTH - 1), z + 22);
        this.squad(roadX(), z + 10, 4);
        break;
      case 'trucks': for (let i = 0; i < 1 + Math.floor(rng.spawn() * Math.min(3, this.zone)); i++) this.put('rusher', roadX(), z - i * 10); break;
      case 'motos': for (let i = 0; i < 2 + Math.floor(rng.spawn() * 2); i++) this.put('moto', (rng.spawn() < 0.5 ? -1 : 1) * (ROAD_HALF_WIDTH + 4), z + 40 - i * 6); break;
      case 'antiTank': this.antiTank(z); break;
      case 'apc': this.put('apc', roadX(4), z); if (rng.spawn() < 0.5) this.put('apc', roadX(4), z - 14); break;
      case 'artillery':
        for (let i = 0; i < 1 + Math.floor(rng.spawn() * 2); i++) this.put('spg', roadX(4), z - 10 - i * 8);
        this.squad(roadX(), z + 10, 4);
        break;
      case 'atguns':
        for (const side of [-1, 1]) this.put('atgun', side * (ROAD_HALF_WIDTH + 1.5), z + 20 + rng.spawn() * 10);
        break;
      case 'shock': for (let i = 0; i < 4 + this.zone; i++) this.put('shock', roadX() , z + rng.spawn() * 8); break;
      case 'mgnest':
        // 机枪组趴在路边，前面有步兵顶着
        for (const side of rng.spawn() < 0.5 ? [-1, 1] : [rng.spawn() < 0.5 ? -1 : 1]) this.put('mgteam', side * rand(ROAD_HALF_WIDTH - 4, ROAD_HALF_WIDTH + 2), z + 18);
        this.squad(roadX(), z + 8, 5);
        break;
      case 'combined':
        // 混编突击：步兵 + 轻坦 / 运兵车 + 反坦克兵，左右两翼同时压上来
        this.squad(-ROAD_HALF_WIDTH * 0.55, z, 6);
        this.squad(ROAD_HALF_WIDTH * 0.55, z + 6, 6);
        this.put(this.zone >= 2 && rng.spawn() < 0.5 ? 'apc' : 'gunner', roadX(4), z - 10);
        this.put('rocketeer', roadX(4), z + 4);
        if (this.zone >= 2) this.put('rusher', roadX(), z - 20);
        break;
    }
  }

  /** 步兵班：成排推进；里面混着几个抱炸药包的爆破兵 */
  private squad(cx: number, z: number, count: number): void {
    const sappers = this.zone === 1 && this.zoneTime < 35 ? 0 : 0.1 + Math.min(2, this.zone - 1) * 0.07;
    for (let i = 0; i < count; i++) {
      const x = clampAbs(cx + ((i % 4) - 1.5) * 2.4 + rand(-0.5, 0.5), ROAD_HALF_WIDTH + 2);
      this.put(rng.spawn() < sappers ? 'sapper' : 'infantry', x, z + Math.floor(i / 4) * 2.6 + rand(-0.4, 0.4));
    }
  }

  private lights(z: number): void {
    const n = Math.min(4, 1 + Math.floor(rng.spawn() * (1 + this.zone * 0.7)));
    for (let i = 0; i < n; i++) this.put(rng.spawn() < 0.4 ? 'rusher' : 'gunner', roadX(), z - i * 8);
  }

  /** 装甲编队：两三辆中型坦克错开成楔形推进，后面跟着轻坦 */
  private armor(z: number): void {
    const n = Math.min(4, 2 + Math.floor(rng.spawn() * (this.zone - 0.5)));
    const cx = roadX(5);
    for (let i = 0; i < n; i++) {
      const side = i === 0 ? 0 : (i % 2 ? -1 : 1) * Math.ceil(i / 2);
      this.put('medium', clampAbs(cx + side * 6, ROAD_HALF_WIDTH - 2), z + Math.abs(side) * 7);
    }
    if (this.zone >= 2) this.put('gunner', roadX(), z - 12);
  }

  /** 反坦克小组：火箭兵 + 几个步兵掩护 */
  private antiTank(z: number): void {
    const cx = roadX(4);
    const rockets = 1 + (this.zone >= 2 ? Math.floor(rng.spawn() * 2) : 0);
    for (let i = 0; i < rockets; i++) this.put('rocketeer', clampAbs(cx + (i - (rockets - 1) / 2) * 4, ROAD_HALF_WIDTH), z);
    this.squad(cx, z + 4, 3);
  }

  /**
   * 据点：重坦 / 首领原地据守，前方摆掩体，周围有步兵。精英（T017-9A）：铁壁 / 巨像照旧据点；冰雹王身边跟 2 辆自行火炮；
   * 破城槌是遭遇型，一辆车从前方冲过来，不摆掩体、不带步兵
   */
  private stronghold(px: number, pz: number, boss: boolean, kind: EnemyKind = 'heavy', ahead = this.strongholdAhead): void {
    const x = clampAbs(px * 0.4, 6);
    if (boss && siegeZone(this.zone)) ahead = SIEGE_AHEAD;
    // 据点 / 首领整体避河（T025）：精英 + 前方 26 米的掩体 + 步兵纵深约 32 米，按中点 ± 18 米（首领 ± 30 米）挪到对岸
    const span = boss ? 30 : 18;
    if (boss) this.hooks.arena?.(pz - ahead);
    const z = this.hooks.dry ? this.hooks.dry(x, pz - ahead + 16, span) - 16 : pz - ahead;
    // 遭遇型精英：破城槌从前方开过来、铁鹰（T095）从前方飞过来，都不摆掩体不带兵
    if (!boss && (kind === 'ram' || kind === 'gunship')) {
      this.hooks.spawn(kind, x, z);
      return;
    }
    if (boss) this.hooks.boss(this.zone, x, z);
    else {
      this.hooks.spawn(kind, x, z);
      if (kind === 'hailking') for (const s of [-1, 1]) this.hooks.spawn('spg', clampAbs(x + s * 8, ROAD_HALF_WIDTH - 2), z - 5);
      else if (this.zone >= 2) this.hooks.spawn('medium', clampAbs(x + (rng.spawn() < 0.5 ? -9 : 9), ROAD_HALF_WIDTH - 2), z + 6);
    }
    for (const dx of boss ? [-7, 0, 7] : [-5.5, 5.5]) this.hooks.cover(clampAbs(x + dx, ROAD_HALF_WIDTH - 2), z + COVER_OFFSET + (boss ? 6 : 0));
    this.squad(x, z + 8, boss ? 8 : 4);
    if (boss || this.zone >= 2) {
      for (const s of boss ? [-1, 1] : [rng.spawn() > 0.5 ? 1 : -1]) this.hooks.spawn('rocketeer', clampAbs(x + s * 8, ROAD_HALF_WIDTH), z + 10);
    }
    if (boss) {
      this.hooks.announce('区域首领来袭', '前方有维修补给');
      this.hooks.supplies();
    }
  }
}

function clampAbs(v: number, limit: number): number {
  return Math.max(-limit, Math.min(limit, v));
}
