import type { BossContext } from '../bosses/Boss';
import { BOSSES } from '../bosses/bosses';
import { rng } from './rng';

/**
 * 首领词缀 + 今日任务（T110，制作人「boss 挑战里还可以有本日任务，打败某个带词缀的具体 boss 获得特殊奖励」）。
 * 词缀只在今日任务那一局挂在首领身上：伤害 / 耐久 / 炮弹这几样包在首领拿到的 BossContext 上（affixCtx），
 * 动作快慢 / 援军 / 回血 / 部件被毁砸炮弹由 Game 每帧管（Game.stepAffix / affixSpite）。首领自己的打法、数值表都没动
 */
export type AffixId = 'rage' | 'iron' | 'haste' | 'summon' | 'mend' | 'snipe' | 'salvo' | 'spite';

export interface AffixDef {
  id: AffixId;
  name: string;
  /** 一句话（模式页今日任务卡片、开打时左侧提示条） */
  line: string;
}

/**
 * 数值：rage 首领打你的伤害 ×；iron 首领耐久 ×；haste 首领的逻辑时间 ×（走、转、装填、出招间隔一起快）；
 * summon 第一队 first 秒后来、之后每 every 秒一队（步兵 infantry 个 + 轻车 light 辆，刷在首领和你之间）；
 * mend 耐久掉到 at 时一次性回每个还在的部件上限的 heal；snipe 首领的炮弹 / 火箭飞行时间 ×（红圈亮得更短）；
 * salvo 每发炮弹沿路往前或往后 gap 米再落一发（晚 delay 秒、伤害 × dmg，横着的缺口不变）；
 * spite 毁掉一个部件（不是核心）朝你砸 n 发炮弹（伤害 dmg、半径 r、飞 flight 秒、落点散开 spread 米）
 */
export const AFFIX = {
  rage: 1.4,
  iron: 1.5,
  haste: 1.25,
  summon: { first: 8, every: 15, infantry: 4, light: 1 },
  mend: { at: 0.5, heal: 0.3 },
  snipe: 0.7,
  salvo: { gap: 5, delay: 0.3, dmg: 0.8 },
  spite: { n: 3, dmg: 16, r: 3.6, flight: 1.4, spread: 7 },
};

export const AFFIXES: readonly AffixDef[] = [
  { id: 'rage', name: '狂暴', line: '伤害 +40%' },
  { id: 'iron', name: '铁壁', line: '耐久 +50%' },
  { id: 'haste', name: '急速', line: '动作快 25%' },
  { id: 'summon', name: '召唤', line: '每 15 秒来一队援军' },
  { id: 'mend', name: '复燃', line: '半血时回 30% 耐久，一次' },
  { id: 'snipe', name: '精准', line: '炮弹落得快，红圈更短' },
  { id: 'salvo', name: '弹幕', line: '每发炮弹后面再落一发' },
  { id: 'spite', name: '反扑', line: '毁一个部件，砸来三发炮弹' },
];
export const AFFIX_BY_ID = new Map(AFFIXES.map((a) => [a.id, a]));

/**
 * 今日任务：picks = 开打前先选几次升级；n = 挂几个词缀；ticket = 每天第一次打下来给的军票；
 * looks = 累计完成几次送的外观（纯外观，econ.ts 里 special 的那几套）
 */
export const DAILY = {
  picks: 20,
  n: 2,
  ticket: 300,
  looks: [
    { at: 3, kind: 'emblem', id: 'sight', name: '纹章「准星」' },
    { at: 7, kind: 'paint', id: 'rust', name: '涂装「赤锈」' },
  ] as const,
};

export interface Daily {
  day: number;
  boss: number;
  affixes: AffixId[];
}

/** 按日期编号当种子的小随机数（同一天所有人一样） */
function seeded(seed: number): () => number {
  let a = Math.imul(seed, 2654435761) >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** 这一天的今日任务：首领从 BOSSES 里抽（打不下来的「云垒」、标了 daily: false 的「穿山」不抽），词缀从 AFFIXES 里抽 DAILY.n 个不重样的 */
export function dailyOf(day: number): Daily {
  const rnd = seeded(day);
  const pool = BOSSES.flatMap((b, i) => (b.escape || b.daily === false ? [] : [i]));
  const boss = pool[Math.floor(rnd() * pool.length)];
  const ids = AFFIXES.map((a) => a.id);
  const affixes: AffixId[] = [];
  while (affixes.length < Math.min(DAILY.n, ids.length)) {
    const id = ids[Math.floor(rnd() * ids.length)];
    if (!affixes.includes(id)) affixes.push(id);
  }
  return { day, boss, affixes };
}

/**
 * 挂上词缀的首领上下文：伤害（狂暴）、耐久（铁壁）、炮弹飞行时间（精准）、多落一发（弹幕）包在这里，别的照原样转给 Game 的那一份。
 * 首领建出来时拿的就是这一份，之后它所有的开火 / 炮击都经过这里
 */
export function affixCtx(base: BossContext, ids: readonly AffixId[]): BossContext {
  const has = (id: AffixId) => ids.includes(id);
  const dmg = has('rage') ? AFFIX.rage : 1;
  const fl = has('snipe') ? AFFIX.snipe : 1;
  const salvo = has('salvo');
  const S = AFFIX.salvo;
  const side = () => (rng.boss() < 0.5 ? -1 : 1) * S.gap;
  const ctx = Object.create(base) as BossContext;
  Object.defineProperty(ctx, 'hpScale', {
    get: () => base.hpScale * (has('iron') ? AFFIX.iron : 1),
    set: (v: number) => {
      base.hpScale = v;
    },
  });
  ctx.fire = (shot, x, z, dx, dz, speed, damage) => base.fire(shot, x, z, dx, dz, speed, damage * dmg);
  ctx.damagePlayer = (amount, at) => base.damagePlayer(amount * dmg, at);
  ctx.artillery = (x, z, tx, tz, damage, radius, flight) => {
    const f = (flight ?? 1.6) * fl;
    base.artillery(x, z, tx, tz, damage * dmg, radius, f);
    if (salvo) base.artillery(x, z, tx, tz + side(), damage * dmg * S.dmg, radius, f + S.delay);
  };
  const siege = base.siegeShell;
  if (siege) ctx.siegeShell = (x, y, z, tx, tz, damage, radius, flight) => siege(x, y, z, tx, tz, damage * dmg, radius, flight * fl);
  const gun = base.gun;
  if (gun) ctx.gun = (x, y, z, tx, tz, speed, damage) => gun(x, y, z, tx, tz, speed, damage * dmg);
  const lob = base.lob;
  if (lob)
    ctx.lob = (x, y, z, tx, tz, damage, radius, flight, rocket, big) => {
      lob(x, y, z, tx, tz, damage * dmg, radius, flight * fl, rocket, big);
      if (salvo) lob(x, y, z, tx, tz + side(), damage * dmg * S.dmg, radius, flight * fl + S.delay, rocket, big);
    };
  return ctx;
}
