import { padBinding } from './controlBindings';
export type SeatId = 0 | 1;

export interface SeatBinding {
  readonly seats: Seats;
  readonly id: SeatId;
}

interface Device {
  index: number;
  id: string;
  connected: boolean;
}

/** 本地双人：一号键鼠，二号用第一只标准手柄；断开保留席位。 */
export class Seats {
  private readonly devices: [Device | null, Device | null] = [null, null];
  private readonly confirmed = new Map<number, boolean>();
  private frame: number | undefined;
  private pads: (Gamepad | null)[] = [];

  readonly keyboard: SeatId = 0;

  binding(id: SeatId): SeatBinding { return { seats: this, id }; }

  /** 同一帧的两个席位共用浏览器快照。工具没给帧号时每次重读。 */
  poll(frame?: number): (Gamepad | null)[] {
    if (frame === undefined || frame !== this.frame) {
      this.pads = Array.from(navigator.getGamepads());
      this.frame = frame;
    }
    return this.pads;
  }

  update(pads: readonly (Gamepad | null)[]): void {
    const supported = pads.filter((p): p is Gamepad =>
      !!p?.connected && p.mapping === 'standard' && p.axes.length >= 4 && p.buttons.length >= 16)
      .sort((a, b) => a.index - b.index);
    for (const device of this.devices) {
      if (device) device.connected = supported.some(p => p.index === device.index && p.id === device.id);
    }
    for (const index of this.confirmed.keys()) {
      if (!supported.some(p => p.index === index)) this.confirmed.delete(index);
    }
    for (const pad of supported) {
      const button = padBinding('confirm', /nintendo|switch|057e|^pro controller\b/i.test(pad.id));
      const down = pad.buttons[button].pressed || pad.buttons[button].value >= 0.5;
      const pressed = down && !this.confirmed.get(pad.index);
      this.confirmed.set(pad.index, down);
      if (this.devices.some(d => d?.connected && d.index === pad.index)) continue;
      if (!pressed) continue;
      // 原槽位优先；浏览器换槽位时，按确认认领第一个空缺席位。
      let seat = this.devices.findIndex(d => d && !d.connected && d.index === pad.index && d.id === pad.id);
      if (seat < 0) seat = this.devices.findIndex(d => d && !d.connected && d.id === pad.id);
      if (seat < 0 && pad === supported[0]) seat = this.devices.findIndex((d, id) => id !== this.keyboard && !d?.connected);
      if (seat >= 0) this.devices[seat] = { index: pad.index, id: pad.id, connected: true };
    }
  }

  index(id: SeatId): number | null {
    const d = this.devices[id];
    return d?.connected ? d.index : null;
  }

  acceptsKeyboard(id: SeatId): boolean {
    return this.keyboard === id;
  }

  snapshot() {
    return this.devices.map((device, id) => ({ seat: id, ...device }));
  }
}
