import * as THREE from 'three';
import { loadTex, saveTex } from './texCache';

/**
 * 程序化贴图：全部在运行时用噪声生成，不依赖外部图片。
 * 所有噪声按 period 取模，生成的贴图四边无缝可平铺。
 */

function hash(ix: number, iy: number, seed: number): number {
  let h = Math.imul(ix, 374761393) ^ Math.imul(iy, 668265263) ^ Math.imul(seed + 1, 2246822519);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}

/** 整数取模到 [0, p)（T108：原来两次取模，生成贴图时它最热，手机上解释执行更明显；结果一样） */
const wrap = (v: number, p: number) => {
  const m = v % p;
  return m < 0 ? m + p : m;
};

/**
 * 格点哈希表（T108）：noise2 的格点只有 period × period 个，按 (period, seed) 先算一张表，取值时查表、不再每次算哈希。
 * 值和 hash() 一模一样（Float64），贴图一个像素都不变；小游戏 iOS 普通模式没有 JIT，生成贴图快一倍多
 */
const lattices = new Map<number, Float64Array>();
function lattice(period: number, seed: number): Float64Array {
  const key = period * 100003 + seed;
  let t = lattices.get(key);
  if (!t) {
    t = new Float64Array(period * period);
    for (let y = 0; y < period; y++) for (let x = 0; x < period; x++) t[y * period + x] = hash(x, y, seed);
    lattices.set(key, t);
  }
  return t;
}

/** 可平铺值噪声，返回 0..1 */
export function noise2(x: number, y: number, period: number, seed: number): number {
  const x0 = Math.floor(x);
  const y0 = Math.floor(y);
  const fx = x - x0;
  const fy = y - y0;
  const sx = fx * fx * (3 - 2 * fx);
  const sy = fy * fy * (3 - 2 * fy);
  const xa = wrap(x0, period);
  const xb = xa + 1 >= period ? xa + 1 - period : xa + 1;
  const ya = wrap(y0, period);
  const yb = ya + 1 >= period ? ya + 1 - period : ya + 1;
  // 整数周期查表（贴图里的都是）；万一传了小数周期照旧现算
  let a: number, b: number, c: number, d: number;
  if (period === (period | 0) && period > 0 && period <= 512) {
    const t = lattice(period, seed);
    a = t[ya * period + xa];
    b = t[ya * period + xb];
    c = t[yb * period + xa];
    d = t[yb * period + xb];
  } else {
    a = hash(xa, ya, seed);
    b = hash(xb, ya, seed);
    c = hash(xa, yb, seed);
    d = hash(xb, yb, seed);
  }
  return a + (b - a) * sx + (c - a) * sy + (a - b - c + d) * sx * sy;
}

/** 分形噪声；u/v 为 0..1，freq 必须是整数才能无缝 */
export function fbm(u: number, v: number, freq: number, octaves: number, seed: number): number {
  let amp = 0.5;
  let sum = 0;
  let norm = 0;
  let f = freq;
  for (let o = 0; o < octaves; o++) {
    sum += amp * noise2(u * f, v * f, f, seed + o * 31);
    norm += amp;
    amp *= 0.5;
    f *= 2;
  }
  return sum / norm;
}

/** 脊状噪声：细裂纹 */
export function ridge(u: number, v: number, freq: number, seed: number): number {
  return 1 - Math.abs(fbm(u, v, freq, 3, seed) * 2 - 1);
}

type Painter = (u: number, v: number, x: number, y: number) => [number, number, number, number?];

const clamp255 = (v: number) => Math.max(0, Math.min(255, Math.round(v)));

/** 逐像素绘制一张贴图（RGB 0..1，可选 alpha） */
export function paint(size: number, fn: Painter, srgb = true): THREE.DataTexture {
  const data = new Uint8Array(size * size * 4);
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const [r, g, b, a = 1] = fn(x / size, y / size, x, y);
      const i = (y * size + x) * 4;
      data[i] = clamp255(r * 255);
      data[i + 1] = clamp255(g * 255);
      data[i + 2] = clamp255(b * 255);
      data[i + 3] = clamp255(a * 255);
    }
  }
  return finish(new THREE.DataTexture(data, size, size, THREE.RGBAFormat), srgb);
}

/** 非方形贴图（图集） */
export function paintRect(w: number, h: number, fn: Painter, srgb = true): THREE.DataTexture {
  const data = new Uint8Array(w * h * 4);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const [r, g, b, a = 1] = fn(x / w, y / h, x, y);
      const i = (y * w + x) * 4;
      data[i] = clamp255(r * 255);
      data[i + 1] = clamp255(g * 255);
      data[i + 2] = clamp255(b * 255);
      data[i + 3] = clamp255(a * 255);
    }
  }
  return finish(new THREE.DataTexture(data, w, h, THREE.RGBAFormat), srgb);
}

function finish(tex: THREE.DataTexture, srgb: boolean): THREE.DataTexture {
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.magFilter = THREE.LinearFilter;
  tex.minFilter = THREE.LinearMipmapLinearFilter;
  tex.generateMipmaps = true;
  tex.anisotropy = 4;
  tex.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
  tex.needsUpdate = true;
  return tex;
}

/**
 * 同样参数的贴图只算一次（T108 启动提速：整备台四辆展示车和战场坦克同一张迷彩 / 履带、地形和河道同一张噪声），
 * 之后发共用像素的副本：各自改平铺 / 释放互不影响；车库涂装（paintTexture）组合太多，不缓存
 */
const made = new Map<string, THREE.DataTexture>();
function once(key: string, make: () => THREE.DataTexture): THREE.DataTexture {
  let t = made.get(key);
  if (!t) made.set(key, (t = fromDisk(key, make)));
  return t.clone();
}

/** 小游戏：上次算好存在磁盘上的直接读（texCache.ts），没有就现算、算完存一份 */
function fromDisk(key: string, make: () => THREE.DataTexture): THREE.DataTexture {
  const hit = loadTex(key);
  if (hit) return finish(new THREE.DataTexture(hit.data, hit.w, hit.h, THREE.RGBAFormat), hit.srgb);
  const t = make();
  saveTex(key, t.image.data as Uint8Array, t.image.width, t.image.height, t.colorSpace === THREE.SRGBColorSpace);
  return t;
}

/** 由高度函数生成切线空间法线贴图 */
export function normalMap(size: number, height: (u: number, v: number) => number, strength: number): THREE.DataTexture {
  const h = new Float32Array(size * size);
  for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) h[y * size + x] = height(x / size, y / size);
  const at = (x: number, y: number) => h[wrap(y, size) * size + wrap(x, size)];
  return paint(
    size,
    (_u, _v, x, y) => {
      const dx = (at(x + 1, y) - at(x - 1, y)) * strength;
      const dy = (at(x, y + 1) - at(x, y - 1)) * strength;
      const len = Math.hypot(dx, dy, 1);
      return [(-dx / len) * 0.5 + 0.5, (-dy / len) * 0.5 + 0.5, 1 / len * 0.5 + 0.5];
    },
    false,
  );
}

const mix = (a: number, b: number, t: number) => a + (b - a) * t;
const mix3 = (a: number[], b: number[], t: number): [number, number, number] => [mix(a[0], b[0], t), mix(a[1], b[1], t), mix(a[2], b[2], t)];
const hex = (h: number) => [((h >> 16) & 255) / 255, ((h >> 8) & 255) / 255, (h & 255) / 255];
const smooth = (e0: number, e1: number, x: number) => {
  const t = Math.max(0, Math.min(1, (x - e0) / (e1 - e0)));
  return t * t * (3 - 2 * t);
};

// ------------------------------------------------------------------ 地面 / 路面

export type GroundKind = 'field' | 'forest' | 'rubble' | 'slag' | 'steppe' | 'sand';
export type RoadKind = 'mud' | 'dirt' | 'cobble' | 'concrete' | 'apron' | 'gravel';

export function groundTexture(kind: GroundKind, size = 256): THREE.DataTexture {
  return once(`ground:${kind}:${size}`, () => makeGround(kind, size));
}

export function roadTexture(kind: RoadKind, size = 256): THREE.DataTexture {
  return once(`road:${kind}:${size}`, () => makeRoad(kind, size));
}

function makeGround(kind: GroundKind, size: number): THREE.DataTexture {
  const seed = { field: 23, forest: 29, rubble: 37, slag: 41, steppe: 47, sand: 53 }[kind];
  return paint(size, (u, v) => {
    const big = fbm(u, v, 3, 4, seed);
    const mid = fbm(u, v, 12, 3, seed + 5);
    const fine = noise2(u * 96, v * 96, 96, seed + 9);
    let c: [number, number, number];
    if (kind === 'field') {
      // 草地 + 成片的麦茬地（垂直于路的田垄）+ 泥斑
      c = mix3(hex(0x4e5c2e), hex(0x6c763a), big);
      const rows = 0.5 + 0.5 * Math.sin(v * Math.PI * 2 * 14);
      const wheat = smooth(0.5, 0.62, fbm(u, v, 2, 3, seed + 11));
      c = mix3(c, mix3(hex(0x9a8a4e), hex(0x7e7040), rows), wheat * 0.85);
      c = mix3(c, hex(0x5a4a33), smooth(0.6, 0.8, mid) * 0.6);
      c = mix3(c, hex(0x86924a), smooth(0.65, 0.9, fine) * 0.3);
      c = mix3(c, hex(0x3a4422), smooth(0.72, 0.95, noise2(u * 48, v * 48, 48, seed + 4)) * 0.4);
    } else if (kind === 'forest') {
      // 林地：深色苔草、落叶松针、裸土
      c = mix3(hex(0x2c3a22), hex(0x3e4a2a), big);
      c = mix3(c, hex(0x4a3c2a), smooth(0.6, 0.8, mid) * 0.55);
      c = mix3(c, hex(0x6a5236), smooth(0.7, 0.95, fine) * 0.45);
      c = mix3(c, hex(0x26301e), smooth(0.68, 0.92, noise2(u * 40, v * 40, 40, seed + 4)) * 0.5);
    } else if (kind === 'steppe') {
      // 荒原（T093 区域 5）：浅赭黄枯草底 + 一簇簇灰绿草 + 碎石点 + 几片裸土；明度压在中间（浅色地面在泛光下容易发白）
      c = mix3(hex(0x8a7a52), hex(0x9e8c5e), big);
      c = mix3(c, hex(0x6e6a48), smooth(0.58, 0.82, mid) * 0.5);
      c = mix3(c, hex(0x5a6040), smooth(0.7, 0.92, noise2(u * 56, v * 56, 56, seed + 4)) * 0.55);
      c = mix3(c, hex(0x7a6a4a), smooth(0.66, 0.9, fbm(u, v, 9, 2, seed + 8)) * 0.4);
      c = mix3(c, hex(0xa8a294), smooth(0.86, 0.98, fine) * 0.45);
      c = mix3(c, hex(0x5e5444), smooth(0.9, 0.99, noise2(u * 140, v * 140, 140, seed + 6)) * 0.35);
    } else if (kind === 'sand') {
      // 沙地（T122 区域 6；T125 重做）：浅黄米色沙（原来土黄偏橙、带硬土块和黑砾石，像红土丘）+ 一道道细沙纹 + 大片细沙 / 粗沙的深浅 + 零星灰色小砾石，不画硬土块、不画裂纹。
      // 沙纹垂直于风向（风从左边略偏后吹来、太阳在左后方，贴图 u = 世界 x、v = 世界 z，一格 16 米、纹距约半米）：迎风坡缓、背风坡陡，背风那一窄条暗一点。
      // 沙丘起伏、风蚀拖痕在地面着色器里按世界坐标画（Terrain 的 sandK 段）
      const ph = u * 31 - v * 8 + fbm(u, v, 2, 3, seed + 2) * 4 + fbm(u, v, 6, 2, seed + 3) * 1.2;
      const f = ph - Math.floor(ph);
      const lee = smooth(0.6, 0.72, f) * (1 - smooth(0.9, 1, f));
      const ripK = 0.35 + 0.65 * smooth(0.3, 0.7, fbm(u, v, 4, 2, seed + 7));
      c = mix3(hex(0xd8c398), hex(0xe9d6aa), big);
      c = mix3(c, hex(0xcdb68a), smooth(0.55, 0.85, mid) * 0.35);
      const k = 1 + (0.03 - 0.11 * lee) * ripK;
      c = [c[0] * k, c[1] * k, c[2] * k];
      c = mix3(c, hex(0x968a76), smooth(0.93, 0.99, noise2(u * 90, v * 90, 90, seed + 6)) * 0.5);
      const g = 0.97 + 0.06 * fine;
      c = [c[0] * g, c[1] * g, c[2] * g];
    } else if (kind === 'slag') {
      // 煤渣地（T019-a 钢铁厂区）：黑褐底 + 铁锈斑 + 零星发亮的积水点 + 一点杂草
      c = mix3(hex(0x2e2a26), hex(0x403a33), big);
      c = mix3(c, hex(0x6a3e22), smooth(0.62, 0.85, mid) * 0.55);
      c = mix3(c, hex(0x1e1c1a), smooth(0.66, 0.9, noise2(u * 40, v * 40, 40, seed + 4)) * 0.5);
      c = mix3(c, hex(0x5a5650), smooth(0.85, 0.98, fine) * 0.4);
      c = mix3(c, hex(0x3e4428), smooth(0.72, 0.9, fbm(u, v, 18, 2, seed + 8)) * 0.25);
    } else {
      c = mix3(hex(0x5e5952), hex(0x7a736a), big);
      c = mix3(c, hex(0x3b3734), smooth(0.6, 0.82, mid) * 0.6);
      c = mix3(c, hex(0x9a8f80), smooth(0.78, 0.95, fine) * 0.5);
      c = mix3(c, hex(0x6b4e3a), smooth(0.7, 0.9, fbm(u, v, 20, 2, seed + 8)) * 0.3);
    }
    return c;
  });
}

function makeRoad(kind: RoadKind, size: number): THREE.DataTexture {
  const seed = { mud: 51, dirt: 63, cobble: 77, concrete: 83, apron: 89, gravel: 97 }[kind];
  return paint(size, (u, v) => {
    const big = fbm(u, v, 4, 4, seed);
    const fine = noise2(u * 128, v * 128, 128, seed + 3);
    let c: [number, number, number];
    if (kind === 'mud') {
      // 湿泥：深褐、发亮的泥浆、碎草和小石子
      c = mix3(hex(0x4a3a2a), hex(0x5e4a34), big);
      c = mix3(c, hex(0x3a2c20), smooth(0.5, 0.75, fbm(u, v, 9, 3, seed + 2)) * 0.7);
      c = mix3(c, hex(0x6e5a3e), smooth(0.8, 0.97, fine) * 0.45);
      c = mix3(c, hex(0x56603a), smooth(0.78, 0.95, noise2(u * 40, v * 40, 40, seed + 5)) * 0.35);
    } else if (kind === 'dirt') {
      c = mix3(hex(0x6e5a40), hex(0x86704f), big);
      c = mix3(c, hex(0x54442f), smooth(0.55, 0.8, fbm(u, v, 10, 3, seed + 2)) * 0.6);
      c = mix3(c, hex(0x9c8a6a), smooth(0.82, 0.98, fine) * 0.5);
      c = mix3(c, hex(0x4e4a2c), smooth(0.8, 0.95, noise2(u * 30, v * 30, 30, seed + 6)) * 0.3);
    } else if (kind === 'gravel') {
      // 砾石古道（T122 区域 6）：碎石 + 细沙 + 深浅不一的石子点；半埋的旧石板、车辙、沙吃进路肩在地面着色器里画。T125：灰褐偏红 → 灰黄（和浅黄沙配）
      c = mix3(hex(0xa69a80), hex(0xbaad92), big);
      c = mix3(c, hex(0x8c806a), smooth(0.55, 0.85, fbm(u, v, 10, 3, seed + 2)) * 0.45);
      c = mix3(c, hex(0xd0c4a8), smooth(0.8, 0.97, fine) * 0.5);
      c = mix3(c, hex(0x5e564a), smooth(0.86, 0.98, noise2(u * 64, v * 64, 64, seed + 5)) * 0.45);
    } else if (kind === 'apron') {
      // 机场水泥板（T093 区域 5）：浅灰白板面（10 米一格 = 横 2 × 纵 2 块，一块 5 × 5 米）+ 深一点的板缝 + 每块深浅略不同 + 零星补丁和胎痕
      const su = (u * 2) % 1;
      const sv = (v * 2) % 1;
      const seam = Math.max(smooth(0.978, 0.996, Math.abs(su - 0.5) * 2), smooth(0.978, 0.996, Math.abs(sv - 0.5) * 2));
      const slab = noise2(Math.floor(u * 2) * 3.7, Math.floor(v * 2) * 2.1, 64, seed + 1);
      c = mix3(hex(0x9a978e), hex(0xaeaba2), slab * 0.6 + big * 0.4);
      c = mix3(c, hex(0x5e5c56), seam * 0.65);
      c = mix3(c, hex(0x86847c), smooth(0.7, 0.85, fbm(u, v, 6, 3, seed + 6)) * 0.4);
      c = mix3(c, hex(0x6e6c66), smooth(0.93, 0.985, ridge(u, v, 7, seed + 7)) * 0.3);
      c = mix3(c, hex(0xbab7ae), smooth(0.9, 0.99, fine) * 0.2);
    } else if (kind === 'concrete') {
      // 水泥板路（T019-a）：灰色板面 + 板缝（10 米贴图一格 = 横 2 × 纵 1 块，一块 5 × 10 米）+ 油渍 + 少量细裂缝 + 煤灰
      const su = (u * 2) % 1;
      const sv = v % 1;
      const seam = Math.max(smooth(0.975, 0.995, Math.abs(su - 0.5) * 2), smooth(0.98, 0.997, Math.abs(sv - 0.5) * 2));
      const slab = noise2(Math.floor(u * 2) * 3.7, Math.floor(v) * 2.1, 64, seed + 1);
      c = mix3(hex(0x6e6c66), hex(0x807d74), slab * 0.5 + big * 0.5);
      c = mix3(c, hex(0x34322e), seam * 0.6);
      c = mix3(c, hex(0x3a3834), smooth(0.68, 0.82, fbm(u, v, 6, 3, seed + 6)) * 0.45);
      c = mix3(c, hex(0x48443e), smooth(0.92, 0.98, ridge(u, v, 7, seed + 7)) * 0.3);
      c = mix3(c, hex(0x9a978e), smooth(0.9, 0.99, fine) * 0.2);
    } else {
      // 村镇石子路：小块、不规则的旧石头，缝里塞满泥，路面盖着泥污
      const rows = 18;
      const row = Math.floor(v * rows);
      const off = noise2(row * 2.3, 0.5, 64, seed + 1) * 0.8;
      const cols = 12;
      const colF = u * cols + off;
      const col = Math.floor(colF);
      const cu = colF - col;
      const cv = v * rows - row;
      const jit = noise2(col * 3.1, row * 1.7, 64, seed + 4);
      const edge = Math.max(Math.abs(cu - 0.5) * 2 * (0.9 + jit * 0.2), Math.abs(cv - 0.5) * 2);
      const gap = smooth(0.7, 0.9, edge);
      c = mix3(hex(0x5e5a54), hex(0x7a756c), jit);
      c = mix3(c, hex(0x4a4540), smooth(0.4, 0.8, big) * 0.5);
      c = mix3(c, hex(0x2e2820), gap);
      c = mix3(c, hex(0x4a3e2e), smooth(0.55, 0.75, fbm(u, v, 5, 3, seed + 6)) * 0.55);
      c = mix3(c, hex(0x3e4a2a), gap * smooth(0.6, 0.8, fbm(u, v, 12, 2, seed + 8)) * 0.5);
      c = mix3(c, hex(0x9a9488), smooth(0.88, 0.99, fine) * 0.25);
    }
    return c;
  });
}

/** 地面共用的细节法线 */
export function terrainNormal(size = 256): THREE.DataTexture {
  return once(`terrainNormal:${size}`, () => normalMap(size, (u, v) => fbm(u, v, 16, 4, 91) + noise2(u * 64, v * 64, 64, 93) * 0.35, 3.2));
}

/** 灰度噪声（宏观变化、路边抖动、水坑分布等） */
export function grayNoise(size = 256): THREE.DataTexture {
  return once(`grayNoise:${size}`, () => paint(size, (u, v) => {
    const n = fbm(u, v, 4, 5, 101);
    return [n, fbm(u, v, 8, 3, 107), noise2(u * 32, v * 32, 32, 109)];
  }, false));
}

/** 小模型通用的脏污细节：乘在顶点色上，消除"纯色塑料感" */
export function grimeTexture(size = 128): THREE.DataTexture {
  return once(`grime:${size}`, () => paint(size, (u, v) => {
    const n = 0.78 + fbm(u, v, 4, 4, 121) * 0.3 - smooth(0.7, 0.95, noise2(u * 40, v * 40, 40, 123)) * 0.15;
    return [n, n * 0.98, n * 0.95];
  }));
}

/** 金属表面细节法线（划痕 + 铸造粗糙） */
export function metalNormal(size = 256): THREE.DataTexture {
  return once(`metalNormal:${size}`, () => normalMap(size, (u, v) => fbm(u, v, 8, 4, 131) * 0.6 + noise2(u * 96, v * 96, 96, 133) * 0.25 + ridge(u, v, 5, 137) * 0.15, 2.2));
}

// ------------------------------------------------------------------ 载具

/** 迷彩：底色 + 两层斑块 + 灰尘与掉漆（乘在顶点色上，所以整体偏亮） */
export function camoTexture(base: number, c1: number, c2: number, seed: number, size = 256): THREE.DataTexture {
  return once(`camo:${base},${c1},${c2},${seed},${size}`, () => paint(size, (u, v) => {
    const n1 = fbm(u, v, 3, 4, seed);
    const n2 = fbm(u, v, 4, 4, seed + 7);
    let c = hex(base);
    c = mix3(c, hex(c1), smooth(0.56, 0.6, n1));
    c = mix3(c, hex(c2), smooth(0.6, 0.64, n2) * 0.9);
    const grime = fbm(u, v, 10, 3, seed + 3);
    c = mix3(c, [c[0] * 0.7, c[1] * 0.68, c[2] * 0.62], smooth(0.5, 0.8, grime) * 0.5);
    const chip = smooth(0.82, 0.9, noise2(u * 48, v * 48, 48, seed + 5));
    c = mix3(c, [0.42, 0.4, 0.37], chip * 0.6);
    // 顶点色会再乘一次，这里整体提亮
    return [c[0] * 1.45, c[1] * 1.45, c[2] * 1.45];
  }));
}

/** T164 ～ T180 的默认迷彩（三色斑块，按米铺）：留给 preview/legacy 里的旧版模型对照 */
export function playerCamo(base: number, c1: number, c2: number, seed: number, size = 256): THREE.DataTexture {
  return once(`pcamo:${base},${c1},${c2},${seed},${size}`, () => paintTexture([base, c1, c2], 'blot', 0, seed, size));
}

/** 玩家车的默认车漆（T181 起纯色军绿）：和车库「军绿」涂装同一张图，按米铺（见 playerTank.ts 的 CAMO_REPEAT） */
export function playerPaint(colors: [number, number, number], seed: number, size = 256): THREE.DataTexture {
  return once(`ppaint:${colors.join(',')},${seed},${size}`, () => paintTexture(colors, 'plain', 0, seed, size));
}

/** 斑块色离底色再拉开 k 倍（T164：三色明度太近，远看糊成一片） */
const stretch = (base: number[], c: number[], k: number): [number, number, number] => [0, 1, 2].map((i) => Math.max(0, Math.min(1, base[i] + (c[i] - base[i]) * k))) as [number, number, number];

/**
 * 车库涂装（T030）：底色 + 图案（blot 斑块迷彩 / stripe 虎纹斜条 / digital 数码方块 / solid 素色 / plain 纯色，T181）+ 灰尘掉漆；
 * wear = 精工档：0 原样、1 战痕（更脏、掉漆多、泥点）、2 精工 / 3 鎏金（干净）。和 camoTexture 一样乘在顶点色上（整体提亮）
 */
export function paintTexture(colors: [number, number, number], pattern: 'blot' | 'stripe' | 'digital' | 'solid' | 'plain', wear = 0, seed = 211, size = 256): THREE.DataTexture {
  const [b0, b1, b2] = colors.map(hex);
  // 纯色（T181）灰尘减半：不让大片污渍读成迷彩斑块
  const grimeK = (wear === 1 ? 0.85 : wear >= 2 ? 0.18 : 0.5) * (pattern === 'plain' ? 0.5 : 1);
  const chipK = wear === 1 ? 0.95 : wear >= 2 ? 0.2 : 0.6;
  return paint(size, (u, v) => {
    let c: [number, number, number] = [b0[0], b0[1], b0[2]];
    if (pattern === 'blot') {
      // T164：车身按米铺图（一张 6 米），斑块大、边缘利，三色拉开
      c = mix3(c, stretch(b0, b1, 1.25), smooth(0.53, 0.555, fbm(u, v, 3, 3, seed)));
      c = mix3(c, stretch(b0, b2, 1.25), smooth(0.6, 0.625, fbm(u, v, 3, 3, seed + 7)));
    } else if (pattern === 'stripe') {
      // 斜着的波浪条带，边缘被噪声撕开（一张图 4 条，平铺无缝）
      const w = u + v + (fbm(u, v, 2, 3, seed) - 0.5) * 0.5;
      const band = Math.sin(w * Math.PI * 4) * 0.5 + 0.5 + (fbm(u, v, 8, 3, seed + 9) - 0.5) * 0.6;
      c = mix3(c, b1, smooth(0.68, 0.74, band));
      c = mix3(c, b2, smooth(0.6, 0.64, fbm(u, v, 3, 3, seed + 5)) * 0.6);
    } else if (pattern === 'digital') {
      // 数码迷彩：按 32 × 32 的方块取噪声（方块边缘硬），两层
      const g = 32;
      const qu = (Math.floor(u * g) + 0.5) / g;
      const qv = (Math.floor(v * g) + 0.5) / g;
      c = mix3(c, b1, fbm(qu, qv, 3, 3, seed) > 0.56 ? 1 : 0);
      c = mix3(c, b2, fbm(qu, qv, 4, 3, seed + 7) > 0.6 ? 1 : 0);
    } else if (pattern === 'solid') {
      c = mix3(c, b2, fbm(u, v, 2, 3, seed) * 0.35);
      c = mix3(c, b1, smooth(0.6, 0.8, fbm(u, v, 5, 3, seed + 3)) * 0.4);
    }
    const grime = fbm(u, v, 10, 3, seed + 3);
    c = mix3(c, [c[0] * 0.7, c[1] * 0.68, c[2] * 0.62], smooth(0.5, 0.8, grime) * grimeK);
    const chip = smooth(0.82, 0.9, noise2(u * 48, v * 48, 48, seed + 5));
    c = mix3(c, [0.42, 0.4, 0.37], chip * chipK);
    // 战痕：成片泥点
    if (wear === 1) c = mix3(c, [0.32, 0.26, 0.18], smooth(0.62, 0.7, fbm(u, v, 6, 3, seed + 11)) * 0.7);
    return [c[0] * 1.45, c[1] * 1.45, c[2] * 1.45];
  });
}

/** 履带图集：下半是横向踏板，上半是链板侧缘；沿弧长每米三节。 */
export function trackTexture(): THREE.DataTexture {
  return once('track', () => paintRect(192, 128, (u, v) => {
    const k = (u * 3) % 1;
    const across = (v * 2) % 1;
    const n = noise2(u * 32, v * 16, 32, 171) * 0.055;
    const link = smooth(0.035, 0.10, k) * (1 - smooth(0.88, 0.96, k));
    let g: number;
    if (v < 0.5) {
      const bar = smooth(0.24, 0.30, k) * (1 - smooth(0.50, 0.57, k));
      const edge = smooth(0.31, 0.44, Math.abs(across - 0.5));
      g = 0.13 + link * 0.10 + bar * 0.14 + edge * 0.055 + n;
    } else {
      const pin = 1 - smooth(0.08, 0.16, Math.hypot((k - 0.5) * 0.65, across - 0.5));
      const lip = smooth(0.30, 0.44, Math.abs(across - 0.5));
      g = 0.14 + link * 0.12 + pin * 0.12 + lip * 0.07 + n;
    }
    return [g * 1.05, g, g * 0.95];
  }));
}

// ------------------------------------------------------------------ 特效图集

/** 粒子图集（2 帧）：左 = 柔光点，右 = 烟团 */
export function particleAtlas(): THREE.DataTexture {
  const size = 128;
  return once('particles', () => paintRect(size * 2, size, (u, v) => {
    const frame = u < 0.5 ? 0 : 1;
    const lu = (u * 2) % 1;
    const dx = lu - 0.5;
    const dy = v - 0.5;
    const r = Math.hypot(dx, dy) * 2;
    if (frame === 0) {
      const a = Math.pow(Math.max(0, 1 - r), 2.2);
      return [1, 1, 1, a];
    }
    const n = fbm(lu, v, 4, 4, 141);
    const a = smooth(1.0, 0.35, r + (n - 0.5) * 0.55);
    const shade = 0.75 + n * 0.35;
    return [shade, shade, shade, a * 0.9];
  }));
}

/**
 * 副武器留痕图集（T143，512 × 256 = 4 × 2 帧，二次幂）：
 * 0 弹孔 / 1 树枝状电灼纹 / 2 扇形焦痕（朝 +X 张开）/ 3 冲击环焦痕 + 放射裂纹 / 4 长条焦痕（沿 X）/ 5 圆焦痕 / 6 轰炸机掠影 / 7 余烬点。
 * A = 焦黑浓度，R = 发光边（刚留下时按冷却时间从红热退到焦黑），G = 深浅起伏
 */
export function subDecalAtlas(): THREE.DataTexture {
  const size = 128;
  return once('subDecals', () => paintRect(size * 4, size * 2, (u, v) => {
    const frame = Math.floor(u * 4) + (v < 0.5 ? 0 : 4);
    const lu = (u * 4) % 1;
    const lv = (v * 2) % 1;
    const dx = lu - 0.5;
    const dy = lv - 0.5;
    const r = Math.hypot(dx, dy) * 2;
    const ang = Math.atan2(dy, dx);
    const n = noise2(lu * 8, lv * 8, 8, 171 + frame);
    const wob = (k: number, seed: number) => noise2(Math.cos(ang) * k + k, Math.sin(ang) * k + k, 64, seed) - 0.5;
    switch (frame) {
      case 0: {
        // 弹孔：中间黑点 + 一圈参差的翻土，边上一圈刚打出来的红热
        const rr = r * (1 + wob(3, 173) * 0.5);
        const a = Math.max(smooth(0.42, 0.18, rr), smooth(0.9, 0.5, rr) * 0.45 * (0.6 + n * 0.4));
        return [smooth(0.5, 0.25, Math.abs(rr - 0.32) * 3) * 0.9, n, 0, a];
      }
      case 1: {
        // 电灼纹：脊状噪声当树枝，越往外越细越淡
        const vein = Math.pow(ridge(lu, lv, 3, 177), 7);
        const fall = smooth(1, 0.15, r);
        const a = Math.min(1, vein * 1.6 * fall + smooth(0.35, 0, r) * 0.6);
        return [Math.min(1, vein * 2 * fall), n, 0, a];
      }
      case 2: {
        // 扇形焦痕：从左边中点往右张开 ±28°，远端参差
        const ax = lu;
        const half = Math.abs(dy) / Math.max(0.02, ax);
        const edge = smooth(0.55, 0.42, half + (n - 0.5) * 0.18) * smooth(0.02, 0.12, ax) * smooth(1, 0.82 + wob(4, 179) * 0.2, ax);
        // 发光的只有远端一圈碎的余烬（不是一整条），近处是焦黑
        const far = smooth(0.72, 0.9, ax) * smooth(1, 0.9, ax);
        return [edge * far * Math.pow(n, 2) * 1.4, n, 0, edge * (0.55 + n * 0.45)];
      }
      case 3: {
        // 冲击环：0.55～0.9 一圈焦黑 + 里面一道道放射裂纹，环上发光
        const rr = r * (1 + wob(5, 181) * 0.12);
        const ringK = smooth(0.45, 0.62, rr) * smooth(0.98, 0.82, rr);
        const crack = Math.pow(Math.max(0, noise2(Math.cos(ang) * 6 + 6, Math.sin(ang) * 6 + 6, 64, 183) * 2 - 1), 3) * smooth(0.75, 0.15, rr);
        const a = Math.max(ringK * (0.6 + n * 0.4), crack * 2.2, smooth(0.3, 0, rr) * 0.5);
        // 发光的是环内沿一道细边 + 裂纹（碎的）
        const rim = smooth(0.1, 0, Math.abs(rr - 0.56)) * (0.3 + n * 0.9);
        return [Math.min(1, rim + crack * 1.5), n, 0, Math.min(1, a)];
      }
      case 4: {
        // 长条：沿 X 一道焦黑，两头收尖，中线发光
        const w = Math.abs(dy) * 2 + (n - 0.5) * 0.25;
        const ends = smooth(0, 0.18, lu) * smooth(1, 0.82, lu);
        const a = smooth(0.85, 0.3, w) * ends;
        return [smooth(0.25, 0.02, w) * ends * Math.pow(n, 1.5) * 1.3, n, 0, a * (0.6 + n * 0.4)];
      }
      case 5: {
        // 圆焦痕：参差的一团焦黑，外缘一圈火边
        const rr = r * (1 + wob(4, 187) * 0.35);
        const a = smooth(0.95, 0.35, rr) * (0.6 + n * 0.4);
        return [smooth(0.12, 0, Math.abs(rr - 0.74)) * (0.25 + n * 0.9), n, 0, a];
      }
      case 6: {
        // 轰炸机掠影（俯视，机头朝 +X）：机身 + 主翼 + 平尾，边缘柔
        const body = smooth(0.1, 0.06, Math.abs(dy)) * smooth(0.48, 0.42, Math.abs(dx));
        const wing = smooth(0.06, 0.03, Math.abs(dx - 0.05 + Math.abs(dy) * 0.25)) * smooth(0.48, 0.42, Math.abs(dy));
        const tail = smooth(0.04, 0.02, Math.abs(dx + 0.38)) * smooth(0.18, 0.14, Math.abs(dy));
        return [0, 0, 0, Math.max(body, wing, tail) * 0.85];
      }
      default: {
        // 余烬点：几颗亮点散在焦黑里
        const dots = Math.pow(Math.max(0, noise2(lu * 16, lv * 16, 16, 191) * 2 - 1.1), 2) * 6;
        const a = smooth(0.95, 0.3, r) * (0.5 + n * 0.3);
        return [Math.min(1, dots) * smooth(0.9, 0.2, r), n, 0, Math.min(1, a + dots * 0.4)];
      }
    }
  }, false));
}

/** 地面贴花图集（4 帧）：焦痕 / 弹坑 / 履带印 / 油污 */
export function decalAtlas(): THREE.DataTexture {
  const size = 128;
  return once('decals', () => paintRect(size * 4, size, (u, v) => {
    const frame = Math.floor(u * 4);
    const lu = (u * 4) % 1;
    const dx = lu - 0.5;
    const dy = v - 0.5;
    const r = Math.hypot(dx, dy) * 2;
    const ang = Math.atan2(dy, dx);
    const n = fbm(lu, v, 4, 4, 151 + frame);
    if (frame === 0) {
      const edge = 0.75 + (noise2(Math.cos(ang) * 3 + 3, Math.sin(ang) * 3 + 3, 64, 157) - 0.5) * 0.5;
      const a = smooth(edge, edge * 0.35, r) * (0.65 + n * 0.35);
      return [0.08, 0.07, 0.06, a];
    }
    if (frame === 1) {
      // 弹坑：边缘随角度起伏、坑沿断续，外圈有几道放射状的溅土
      const wob = (noise2(Math.cos(ang) * 2 + 5, Math.sin(ang) * 2 + 5, 64, 161) - 0.5) * 0.5 + (n - 0.5) * 0.25;
      const rr = r * (1 + wob);
      const rays = smooth(0.5, 0.85, noise2(Math.cos(ang) * 6 + 9, Math.sin(ang) * 6 + 9, 64, 163));
      const rim = smooth(0.4, 0.6, rr) * smooth(0.9 + rays * 0.3, 0.68, rr) * (0.55 + noise2(Math.cos(ang) * 9 + 2, Math.sin(ang) * 9 + 2, 64, 167) * 0.45);
      const pit = smooth(0.58, 0.05, rr);
      const ejecta = rays * smooth(1.0, 0.65, rr) * smooth(0.5, 0.75, rr) * 0.55;
      const a = Math.max(rim * 0.7, pit * 0.85, ejecta) * (0.7 + n * 0.3);
      const c = mix3([0.1, 0.09, 0.07], [0.42, 0.36, 0.28], Math.max(rim, ejecta * 0.8));
      return [c[0], c[1], c[2], a];
    }
    if (frame === 2) {
      // 履带齿印：横条纹 + 两侧边
      const bar = smooth(0.25, 0.45, Math.abs(((v * 5) % 1) - 0.5) * 2);
      const side = smooth(0.48, 0.42, Math.abs(dx));
      const a = (1 - bar) * side * (0.75 + n * 0.25);
      return [0.12, 0.1, 0.08, a];
    }
    const a = smooth(0.8, 0.2, r + (n - 0.5) * 0.4) * 0.8;
    return [0.05, 0.05, 0.05, a];
  }));
}
