import type { MoveIntent } from './TankMovement';
import type { Trigger } from './TankInput';
import type { SeatBinding } from './seats';
import { padBinding } from './controlBindings';

export type PadFamily = 'xbox' | 'sony' | 'nintendo' | 'standard';
export type PadDirection = 'up' | 'down' | 'left' | 'right';

/** 两杆用圆形中心缓冲区；扳机用两个阈值，轻微抖动不补发一炮。 */
const CENTER = 0.18;
const TRIGGER_ON = 0.55;
const TRIGGER_OFF = 0.35;
const REPEAT_DELAY = 360;
const REPEAT_MS = 130;
const LABEL: Record<PadFamily, string> = { xbox: '微软手柄', sony: '索尼手柄', nintendo: '任天堂手柄', standard: '标准手柄' };

interface PadSample {
  id: string;
  buttons: number;
  axes: number[];
}

function family(id: string): PadFamily {
  if (/xbox|xinput|045e/i.test(id)) return 'xbox';
  if (/dualsense|dualshock|playstation|sony|054c/i.test(id)) return 'sony';
  if (/nintendo|switch|057e|^pro controller\b/i.test(id)) return 'nintendo';
  return 'standard';
}

function axis(pad: Gamepad, i: number): number {
  const v = pad.axes[i];
  return Number.isFinite(v) ? Math.max(-1, Math.min(1, v)) : 0;
}

function stick(x: number, y: number): [number, number] {
  const length = Math.hypot(x, y);
  if (length <= CENTER) return [0, 0];
  const scale = Math.min(1, (length - CENTER) / (1 - CENTER)) / length;
  return [x * scale, y * scale];
}

/**
 * 浏览器负责把硬件映射到标准布局。这里只读真实设备，不向键鼠派发事件。
 * 切菜单、换手柄、失焦后先等两杆回中、按键松开，再接下一次操作。
 */
export class GamepadInput {
  available = typeof navigator !== 'undefined' && typeof navigator.getGamepads === 'function';
  active = false;
  index: number | null = null;
  family: PadFamily = 'standard';
  mapping = '';
  waiting = true;
  fireHeld = false;
  confirm = false;
  cancel = false;
  pause = false;
  workshop = false;
  direction: PadDirection | null = null;
  scroll = 0;
  readonly move: MoveIntent = { active: false, x: 0, forward: 0 };
  aim: [number, number, number, number] | null = null;
  /** 菜单里的右摇杆（T183 开始页环视）：-1～1，回中 = null */
  look: [number, number] | null = null;
  notice = '';
  noticeUntil = 0;

  private readonly samples = new Map<number, PadSample>();
  private trigger: Trigger | null = null;
  private ultimate = false;
  private interrupted = false;
  private focused = typeof document === 'undefined' || !document.hasFocus || document.hasFocus();
  private playing = false;
  private navHeld: PadDirection | null = null;
  private repeatAt = 0;
  private unsupported = '';

  constructor(private readonly seat?: SeatBinding) {
    if (!this.available) return;
    window.addEventListener('gamepadconnected', this.onConnect);
    window.addEventListener('gamepaddisconnected', this.onDisconnect);
    window.addEventListener('blur', this.onBlur);
    window.addEventListener('focus', this.onFocus);
    document.addEventListener('visibilitychange', this.onVisibility);
    // 只记录输入来源；原键鼠监听器、按键含义和默认事件处理都不变。
    if (!seat) {
      window.addEventListener('keydown', this.onOtherInput, true);
      window.addEventListener('pointerdown', this.onOtherInput, true);
      window.addEventListener('pointermove', this.onPointerMove, true);
    }
  }

  get label(): string { return LABEL[this.family]; }

  update(playing: boolean, frame?: number): void {
    this.clearFrame();
    if (!this.available) return;
    if (playing !== this.playing) {
      this.playing = playing;
      this.suspend();
    }
    let pads: (Gamepad | null)[];
    try {
      pads = this.seat ? this.seat.seats.poll(frame) : Array.from(navigator.getGamepads());
    } catch {
      this.lose();
      this.available = false;
      this.tell('浏览器未开放手柄');
      return;
    }
    const connected = pads.filter((p): p is Gamepad => !!p?.connected);
    this.seat?.seats.update(pads);
    const valid = connected.filter(p => p.mapping === 'standard' && p.axes.length >= 4 && p.buttons.length >= 16);
    const supported = this.seat ? valid.filter(p => p.index === this.seat!.seats.index(this.seat!.id)) : valid;
    if (this.index !== null && !supported.some(p => p.index === this.index && p.id === this.samples.get(p.index)?.id)) this.lose();
    for (const index of this.samples.keys()) if (!connected.some(p => p.index === index)) this.samples.delete(index);
    const unknown = valid.length ? '' : connected.map(p => `${p.index}:${p.id}`).join('|');
    if (unknown && unknown !== this.unsupported) this.tell('手柄布局未识别，请换浏览器');
    this.unsupported = unknown;

    let selected: Gamepad | null = null;
    let pressed = 0;
    let held = 0;
    let moved = false;
    for (const pad of supported) {
      const old = this.samples.get(pad.index);
      const fresh = !old || old.id !== pad.id;
      const previous = fresh ? 0 : old.buttons;
      let buttons = 0;
      for (let i = 0; i < 16; i++) {
        const b = pad.buttons[i];
        const down = i === 6 || i === 7
          ? b.value >= ((previous & (1 << i)) ? TRIGGER_OFF : TRIGGER_ON)
          : b.pressed || b.value >= 0.5;
        if (down) buttons |= 1 << i;
      }
      const axes = [axis(pad, 0), axis(pad, 1), axis(pad, 2), axis(pad, 3)];
      const changed = [0, 2].some(i => Math.hypot(axes[i], axes[i + 1]) > CENTER && (fresh
        || Math.hypot(old.axes[i], old.axes[i + 1]) <= CENTER
        || Math.hypot(axes[i] - old.axes[i], axes[i + 1] - old.axes[i + 1]) > 0.08));
      const down = buttons & ~previous;
      const centered = Math.hypot(axes[0], axes[1]) <= CENTER && Math.hypot(axes[2], axes[3]) <= CENTER;
      this.samples.set(pad.index, { id: pad.id, buttons, axes: fresh || changed || centered ? axes : old.axes });
      // 单人沿用设备切换；分席位时 supported 只含本车认领的手柄。
      if (this.index === null || (pad.index !== this.index && (down || changed))) {
        this.index = pad.index;
        this.family = family(pad.id);
        this.mapping = pad.mapping;
        this.suspend();
        this.active = false;
        this.tell('手柄已连接，按键启用');
      }
      if (pad.index === this.index) {
        selected = pad;
        pressed = fresh ? 0 : down;
        held = buttons;
        moved = changed;
        if (fresh && (buttons || changed)) this.active = true;
      }
    }
    if (!selected || !this.focused || document.hidden) return;
    if (pressed || moved) this.active = true;
    const moveAxis = playing ? padBinding('move') : 0;
    const aimAxis = playing ? padBinding('aim') : 2;
    const [lx, ly] = stick(axis(selected, moveAxis), axis(selected, moveAxis + 1));
    const [rx, ry] = stick(axis(selected, aimAxis), axis(selected, aimAxis + 1));
    if (this.waiting) {
      if (!held && !lx && !ly && !rx && !ry) this.waiting = false;
      return;
    }
    if (!this.active) return;
    this.confirm = !!(pressed & (1 << padBinding('confirm', this.family === 'nintendo')));
    this.cancel = !!(pressed & (1 << padBinding('cancel', this.family === 'nintendo')));
    this.pause = !!(pressed & (1 << padBinding('pause')));
    const dx = ((held >> 15) & 1) - ((held >> 14) & 1);
    const dy = ((held >> 13) & 1) - ((held >> 12) & 1);
    if (playing) {
      const dpad = !!(held & 0xf000);
      const x = dpad ? dx : lx, y = dpad ? dy : ly;
      const length = Math.max(1, Math.hypot(x, y));
      this.move.active = dpad || !!(lx || ly);
      this.move.x = x / length;
      this.move.forward = -y / length;
      this.aim = rx || ry ? [0, 0, rx * 100, ry * 100] : null;
      this.fireHeld = !!(held & (1 << padBinding('fire')));
      if (pressed & (1 << padBinding('fire'))) this.trigger = { at: null, aim: null, stick: this.aim };
      this.ultimate = !!(pressed & (1 << padBinding('ult')));
      this.workshop = !!(pressed & (1 << padBinding('workshop')));
    } else {
      this.look = rx || ry ? [rx, ry] : null;
      const x = dx || lx, y = dy || ly;
      const threshold = this.navHeld ? 0.35 : 0.55;
      const dir: PadDirection | null = Math.max(Math.abs(x), Math.abs(y)) < threshold ? null
        : Math.abs(x) > Math.abs(y) ? x < 0 ? 'left' : 'right' : y < 0 ? 'up' : 'down';
      const now = performance.now();
      if (dir !== this.navHeld) {
        this.direction = dir;
        this.repeatAt = now + REPEAT_DELAY;
      } else if (dir && now >= this.repeatAt) {
        this.direction = dir;
        this.repeatAt = now + REPEAT_MS;
      }
      this.navHeld = dir;
      this.scroll = ry;
    }
  }

  consumeTrigger(): Trigger | null {
    const t = this.trigger;
    this.trigger = null;
    return t;
  }

  consumeUlt(): boolean {
    const v = this.ultimate;
    this.ultimate = false;
    return v;
  }

  consumeInterruption(): boolean {
    const v = this.interrupted;
    this.interrupted = false;
    return v;
  }

  suspend(): void {
    this.waiting = true;
    this.navHeld = null;
    this.clearFrame();
  }

  private clearFrame(): void {
    this.fireHeld = this.confirm = this.cancel = this.pause = this.workshop = false;
    this.move.active = false;
    this.move.x = this.move.forward = this.scroll = 0;
    this.aim = this.trigger = null;
    this.look = null;
    this.ultimate = false;
    this.direction = null;
  }

  private tell(text: string): void {
    this.notice = text;
    this.noticeUntil = performance.now() + 5000;
  }

  private lose(): void {
    if (this.index !== null) {
      this.interrupted ||= this.active || !!this.seat;
      this.tell(this.seat ? '手柄已断开，请重新连接' : '手柄已断开，可用键鼠继续');
    }
    this.index = null;
    this.mapping = '';
    this.active = false;
    this.suspend();
  }

  private readonly onConnect = () => { this.unsupported = ''; };
  private readonly onDisconnect = (e: GamepadEvent) => {
    this.samples.delete(e.gamepad.index);
    if (e.gamepad.index === this.index) this.lose();
  };
  private readonly onBlur = () => {
    this.focused = false;
    this.interrupted ||= this.active;
    this.suspend();
  };
  private readonly onFocus = () => { this.focused = true; this.suspend(); };
  private readonly onVisibility = () => { if (document.hidden) this.onBlur(); else this.onFocus(); };
  private readonly onOtherInput = () => {
    if (!this.active) return;
    this.active = false;
    this.suspend();
  };
  private readonly onPointerMove = (e: PointerEvent) => {
    if (e.movementX || e.movementY) this.onOtherInput();
  };

  dispose(): void {
    window.removeEventListener('gamepadconnected', this.onConnect);
    window.removeEventListener('gamepaddisconnected', this.onDisconnect);
    window.removeEventListener('blur', this.onBlur);
    window.removeEventListener('focus', this.onFocus);
    document.removeEventListener('visibilitychange', this.onVisibility);
    window.removeEventListener('keydown', this.onOtherInput, true);
    window.removeEventListener('pointerdown', this.onOtherInput, true);
    window.removeEventListener('pointermove', this.onPointerMove, true);
    this.samples.clear();
    this.lose();
  }
}
