import { CORES, type CoreId } from '../weapons/defs';

const wrapIndex = (i: number, n: number) => ((i % n) + n) % n;
const reducedMotion = () => typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches;

/** 两套开始页共用选项与手势；尺寸、绘制和点击区各自处理。 */
export class CoreCarousel {
  readonly ids = Object.keys(CORES) as CoreId[];
  index: number;
  position: number;
  private target: number;
  private from: number;
  private at = 0;
  private hand: { id: number; x: number; y: number; stride: number; axis: '' | 'x' | 'y'; moved: boolean } | null = null;

  constructor(core: CoreId, private readonly change: (core: CoreId) => void) {
    this.index = Math.max(0, this.ids.indexOf(core));
    this.position = this.target = this.from = this.index;
  }

  get value(): CoreId { return this.ids[this.index]; }
  get dragging(): boolean { return !!this.hand; }
  get moving(): boolean { return !this.hand && Math.abs(this.position - this.target) > 0.001; }

  /** 存档或解锁状态刷新时同步；正常切换不打断动画。 */
  sync(core: CoreId): void {
    const index = this.ids.indexOf(core);
    if (index < 0 || index === this.index) return;
    this.hand = null;
    this.index = this.position = this.target = this.from = index;
  }

  offset(index: number): number {
    const n = this.ids.length;
    return n < 2 ? 0 : wrapIndex(index - this.position + n / 2, n) - n / 2;
  }

  step(direction: number, now = performance.now()): void {
    if (this.ids.length < 2 || this.hand) return;
    this.go(this.target + Math.sign(direction), now);
  }

  select(core: CoreId, now = performance.now()): void {
    const index = this.ids.indexOf(core);
    if (index < 0 || this.hand) return;
    const n = this.ids.length;
    const delta = wrapIndex(index - this.index + n / 2, n) - n / 2;
    this.go(this.target + delta, now);
  }

  begin(id: number, x: number, y: number, stride: number): boolean {
    if (this.hand || this.ids.length < 2) return false;
    this.position = this.target;
    this.hand = { id, x, y, stride, axis: '', moved: false };
    return true;
  }

  move(id: number, x: number, y: number): void {
    const h = this.hand;
    if (!h || h.id !== id) return;
    const dx = x - h.x, dy = y - h.y;
    if (Math.hypot(dx, dy) > 12) h.moved = true;
    if (!h.axis && Math.max(Math.abs(dx), Math.abs(dy)) > 10) h.axis = Math.abs(dx) > Math.abs(dy) * 1.2 ? 'x' : 'y';
    if (h.axis === 'x') this.position = this.target - Math.max(-1, Math.min(1, dx / h.stride));
  }

  /** 松手最多切一项；竖拖、短拖和取消都不改选择。返回是否已消耗这次点按。 */
  end(id: number, x: number, y: number, now = performance.now()): boolean {
    const h = this.hand;
    if (!h || h.id !== id) return true;
    this.move(id, x, y);
    this.hand = null;
    const dx = x - h.x;
    const turn = h.axis === 'x' && Math.abs(dx) >= Math.min(52, h.stride * 0.22);
    this.go(this.target - (turn ? Math.sign(dx) : 0), now);
    return h.moved;
  }

  cancel(id?: number, now = performance.now()): void {
    if (!this.hand || (id !== undefined && this.hand.id !== id)) return;
    this.hand = null;
    this.go(this.target, now);
  }

  tick(now = performance.now()): void {
    if (!this.moving) return;
    const t = reducedMotion() ? 1 : Math.min(1, Math.max(0, (now - this.at) / 180));
    this.position = this.from + (this.target - this.from) * (1 - (1 - t) ** 3);
    if (t === 1) this.position = this.target = this.from = this.index;
  }

  private go(target: number, now: number): void {
    this.from = this.position;
    this.target = target;
    this.at = now;
    const index = wrapIndex(target, this.ids.length);
    if (reducedMotion()) this.position = target;
    if (index === this.index) return;
    this.index = index;
    this.change(this.value);
  }
}
