import { CORES } from '../weapons/defs';
import type { Seat } from './onlineLobby';

interface Action { id: string; label: string; style?: string; off?: boolean; sub?: string; tap(): void }
export interface WebLobbyView {
  room: string; note: string; status: string; lines: string[];
  seats: Seat[]; buttons: Action[]; result: string[];
}
/** 网页房间页沿用画布页的席位、状态和动作。 */
export class WebOnlineLobby {
  private el: HTMLElement | null = null;
  private signature = '';
  show(value: boolean): void {
    if (!value) { this.el?.remove(); this.el = null; this.signature = ''; return; }
    if (this.el) return;
    this.el = document.createElement('section');
    this.el.id = 'online-lobby';
    this.el.setAttribute('aria-label', '联机双人');
    document.body.append(this.el);
  }
  render(v: WebLobbyView): void {
    if (!this.el) return;
    const signature = JSON.stringify(v);
    if (signature === this.signature) return;
    this.signature = signature;
    const focused = (document.activeElement as HTMLElement)?.dataset.online;
    this.el.replaceChildren();
    const sheet = document.createElement('div'); sheet.className = 'online-sheet'; this.el.append(sheet);
    const add = (tag: string, cls: string, value: string, parent: HTMLElement = sheet) => {
      const el = document.createElement(tag); el.className = cls; el.textContent = value; parent.append(el); return el;
    };
    add('h2', 'online-heading', v.result.length ? '本局战报' : '联机双人');
    add('p', 'online-note', v.result.length ? v.result.join('\n') : v.note).setAttribute('aria-live', 'polite');
    if (!v.result.length) {
      const seats = add('div', 'online-seats', '');
      for (const s of v.seats) {
        const seat = add('article', `online-seat ${s.tone}`, '', seats);
        add('h3', '', `${s.name} · ${s.role}${s.me ? ' · 你' : ''}`, seat);
        const mark = { empty: '□', joined: '◎', ready: '✓', left: '×', away: '‖' }[s.tone];
        add('strong', 'online-state', `${mark} ${s.label}`, seat);
        add('span', 'online-core', s.core ? CORES[s.core].name : '—', seat);
        add('small', '', s.foot, seat);
      }
      const box = add('div', 'online-room-box', '');
      add('strong', '', v.room ? `房间码 ${v.room}` : '房间', box);
      add('span', 'online-validity', v.status, box);
      add('p', '', v.lines.join('\n'), box);
      for (const b of v.buttons.filter(b => ['copy', 'create', 'join'].includes(b.id))) this.button(box, b);
    }
    const picks = add('div', 'online-picks', '');
    for (const b of v.buttons.filter(b => b.id.startsWith('core-'))) this.button(picks, b);
    const actions = add('div', 'online-actions', '');
    for (const b of v.buttons.filter(b => ['ready', 'back', 'return'].includes(b.id))) this.button(actions, b);
    if (focused) this.el.querySelector<HTMLButtonElement>(`[data-online="${focused}"]`)?.focus({ preventScroll: true });
  }
  private button(parent: HTMLElement, b: Action): void {
    const el = document.createElement('button');
    el.type = 'button'; el.id = `online-${b.id}`; el.dataset.online = b.id;
    el.disabled = !!b.off; el.textContent = b.label;
    if (b.id.startsWith('core-')) el.setAttribute('aria-pressed', String(b.style === 'chipOn'));
    if (b.sub) { const sub = document.createElement('small'); sub.textContent = b.sub; el.append(sub); }
    el.onclick = b.tap; parent.append(el);
  }
}

export function webInvite(code: string): string {
  const url = new URL(location.pathname, location.origin);
  if (new URLSearchParams(location.search).get('ui') === 'canvas') url.searchParams.set('ui', 'canvas');
  url.searchParams.set('room', code);
  return url.href;
}

/** 浏览器原生输入框；两套网页界面共用，复制失败时保留可选中的链接。 */
export function roomDialog(code: string | null, enter: (code: string) => void): () => void {
  const dialog = document.createElement('dialog');
  dialog.className = 'web-room-dialog';
  const title = document.createElement('h2');
  title.textContent = code ? `房间码 ${code}` : '加入房间';
  const input = document.createElement('input');
  input.id = 'online-room-input';
  input.setAttribute('aria-label', code ? '邀请链接' : '六位房间码');
  input.value = code ? webInvite(code) : '';
  input.readOnly = !!code;
  if (!code) { input.inputMode = 'numeric'; input.maxLength = 6; input.placeholder = '输入六位房间码'; }
  const note = document.createElement('p');
  note.textContent = code ? '把链接发给队友' : '向房主索取房间码';
  const accept = document.createElement('button'); accept.type = 'button'; accept.id = 'online-room-confirm'; accept.textContent = code ? '复制链接' : '加入';
  const cancel = document.createElement('button'); cancel.type = 'button'; cancel.textContent = '返回';
  const close = () => { dialog.close(); dialog.remove(); };
  accept.onclick = () => {
    if (code) {
      input.select();
      void navigator.clipboard?.writeText(input.value).then(() => { note.textContent = '已复制，发给队友'; }).catch(() => { note.textContent = '长按链接，全选复制'; });
      if (!navigator.clipboard) note.textContent = '长按链接，全选复制';
    } else if (/^\d{6}$/.test(input.value.trim())) { const value = input.value.trim(); close(); enter(value); }
    else note.textContent = '请输入六位数字';
  };
  cancel.onclick = close;
  input.onkeydown = e => { if (e.key === 'Enter') { e.preventDefault(); accept.click(); } };
  dialog.oncancel = e => { e.preventDefault(); close(); };
  dialog.append(title, input, note, accept, cancel); document.body.append(dialog); dialog.showModal(); input.focus();
  return close;
}
