import type { Insets, Rect } from './canvas/Overlay';

export function isLandscape(w: number, h: number): boolean {
  return w >= 560 && w > h;
}

/** 按网页可用像素放大界面。手机不缩字，桌面最多两倍，不读取物理屏幕分辨率。 */
export function menuScale(w: number, h: number): number {
  return isLandscape(w, h) ? Math.max(1, Math.min(2, w / 1440, h / 900)) : 1;
}

/** 背景铺满；横屏菜单最多 1280 × 840 个排版像素，超宽屏两侧留给场景。 */
export function menuFrame(w: number, h: number, insets: Insets): Rect & { scale: number } {
  const scale = menuScale(w, h);
  const left = Math.max(16 * scale, insets.left), right = Math.max(16 * scale, insets.right);
  const top = Math.max(10 * scale, insets.top), bottom = Math.max(10 * scale, insets.bottom);
  const width = Math.min(1280 * scale, w - left - right), height = Math.min(840 * scale, h - top - bottom);
  return { x: left + (w - left - right - width) / 2, y: top + (h - top - bottom - height) / 2, w: width, h: height, scale };
}

/** 顶部中间不足 160 像素时，首领条进入左侧状态列，避免安全区挤掉名字。 */
export function landscapeStatus(w: number, insets: Insets, scale = 1): { width: number; stackBoss: boolean } {
  const available = (w - insets.left - insets.right) / scale;
  const width = Math.max(230, Math.min(310, available * .35));
  return { width, stackBoss: available - width - 250 < 160 };
}

/** 超宽显示器把战斗读数和工具收在中央，三维画面仍铺满。 */
export function hudViewport(w: number, h: number, insets: Insets): { scale: number; insets: Insets } {
  const scale = menuScale(w, h);
  const side = isLandscape(w, h) ? Math.max(0, (w - 1920 * scale) / 2) : 0;
  return { scale, insets: { ...insets, left: Math.max(insets.left, side), right: Math.max(insets.right, side) } };
}
