import type { ConfirmBox } from './missionUi';

/** 退出只关闭当前游戏。普通网页由玩家关闭页面，存档保留。 */
export function exitGame(confirm: (box: ConfirmBox, accept: () => void) => void): void {
  confirm({
    title: '退出游戏？',
    lines: ['已保存的进度会保留。'],
    accept: '退出游戏',
    cancel: '返回',
  }, () => {
    const guide = () => confirm({
      title: '退出游戏',
      lines: ['请关闭当前页面退出游戏。'],
      cancel: '返回',
    }, () => {});
    const wx = (globalThis as { wx?: { exitMiniProgram?: (opts: { fail: () => void }) => void } }).wx;
    try {
      if (wx?.exitMiniProgram) {
        wx.exitMiniProgram({ fail: guide });
        return;
      }
      if (window.opener) {
        window.close();
        if (window.closed) return;
      }
    } catch {
      // 平台未关闭时保留菜单，并给出退出方法。
    }
    guide();
  });
}
