import * as THREE from 'three';
import { Fingers } from '../cardPick';
import { cssInsets } from '../rail';

/**
 * 画布版界面的底座（微信小游戏 / 网页 ?ui=canvas）。
 *
 * 小游戏只有一块上屏画布（WebGL），界面必须画进同一帧：
 * - 界面拆成若干「面板」：每块面板一张离屏 2D 画布，只在内容变了的时候重画、上传一次纹理，
 *   每帧只是一个带透明度 / 位移 / 缩放的四边形（一次绘制），动画不重画。
 * - 上传走微信官方「混合渲染」的写法 `gl.texImage2D(…, canvas)`（three.js 的 CanvasTexture 走
 *   texStorage2D + texSubImage2D，小游戏真机没保证），纹理用 ExternalTexture 交给 three.js 绑定。
 * - 面板纹理按渲染器当前像素比画、位置对齐到像素，文字不糊；画质切换时全部重画。
 * - 主画面（含泛光合成）画完后，用正交相机把面板叠在上面（autoClear 关掉）。
 * - 点击：每帧各组件登记可点区域，手指落下时先问这里（`blocks`），落在界面上的手指不交给走位 / 开炮。
 */

export interface Rect {
  x: number;
  y: number;
  w: number;
  h: number;
}

export interface Insets {
  top: number;
  right: number;
  bottom: number;
  left: number;
}

/** 拖动区域；坐标由 Sheet 换成块内坐标，取消不会触发点按。 */
export interface Drag {
  start: (x: number, y: number, id: number) => boolean;
  move: (x: number, y: number, id: number) => void;
  end: (x: number, y: number, id: number, cancelled: boolean) => boolean;
}

/** 可点区域（逻辑像素）。z 大的在上；同 z 后登记的在上 */
export interface Region extends Rect {
  id: string;
  z: number;
  /** 点一下（落下到抬起位移 ≤ 12 像素；tapMs 有值时还要求时长不超过它） */
  tap?: () => void;
  tapMs?: number;
  /** 手指一落下就触发（槽位详情） */
  down?: () => void;
  drag?: Drag;
  /** 按住不动 ms 毫秒：start；之后松手 / 拖走：end（这次不算点） */
  hold?: { ms: number; start: () => void; end: () => void };
  /** 手指落下时问一次：不算数就不高亮、松手也不触发（选卡防误触，T058） */
  ready?: () => boolean;
  /** 按下时要重画的面板（按压高亮） */
  panel?: Panel;
}

interface Press {
  r: Region;
  x0: number;
  y0: number;
  t0: number;
  moved: boolean;
  held: boolean;
  /** 落下时 ready() 不算数 */
  early: boolean;
  dragging: boolean;
}

const TAP_SLOP = 12;

const VERT = /* glsl */ `
varying vec2 vUv;
void main() {
  vUv = vec2(uv.x, 1.0 - uv.y);
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}`;

const PANEL_FRAG = /* glsl */ `
uniform sampler2D map;
uniform float opacity;
varying vec2 vUv;
void main() {
  vec4 c = texture2D(map, vUv);
  gl_FragColor = vec4(c.rgb, c.a * opacity);
}`;

/** 受击警戒边：和网页版共用橙色，透明度与时序照旧。 */
const HIT_FRAG = /* glsl */ `
uniform float opacity;
varying vec2 vUv;
void main() {
  float d = length(vUv * 2.0 - 1.0) / 1.41421;
  float a = clamp((d - 0.42) / 0.58, 0.0, 1.0) * 0.85;
  gl_FragColor = vec4(0.843, 0.482, 0.137, a * opacity);
}`;

/** 核爆白闪：radial-gradient(ellipse at 50% 30%, #fff8ea, #ffe8c4) */
const ULT_FRAG = /* glsl */ `
uniform float opacity;
varying vec2 vUv;
void main() {
  float d = clamp(length(vec2((vUv.x - 0.5) / 0.5, (vUv.y - 0.3) / 0.7)) / 1.41421, 0.0, 1.0);
  gl_FragColor = vec4(mix(vec3(1.0, 0.973, 0.918), vec3(1.0, 0.910, 0.769), d), opacity);
}`;

const QUAD = new THREE.PlaneGeometry(1, 1);

function quadMaterial(frag: string, uniforms: Record<string, THREE.IUniform>): THREE.ShaderMaterial {
  return new THREE.ShaderMaterial({
    vertexShader: VERT,
    fragmentShader: frag,
    uniforms: { opacity: { value: 1 }, ...uniforms },
    transparent: true,
    depthTest: false,
    depthWrite: false,
  });
}

type StateCache = THREE.WebGLState & { pixelStorei?: (name: number, value: number | boolean) => void };

/**
 * 把 2D 画布整张传成纹理（tex 为 null 时新建）：`gl.texImage2D(…, canvas)`，小游戏官方支持的写法。
 * 绑定 / 解包参数经 three.js 的状态缓存设置，免得它以为没变而跳过；不翻转、不预乘（着色器里按普通透明度混合）
 */
export function uploadCanvas(renderer: THREE.WebGLRenderer, tex: WebGLTexture | null, canvas: HTMLCanvasElement): WebGLTexture {
  const gl = renderer.getContext() as WebGL2RenderingContext;
  const state = renderer.state as StateCache;
  const fresh = !tex;
  const t = tex ?? (gl.createTexture() as WebGLTexture);
  state.bindTexture(gl.TEXTURE_2D, t);
  if (fresh) {
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  }
  const store = (name: number, value: number | boolean) => (state.pixelStorei ? state.pixelStorei(name, value) : gl.pixelStorei(name, value as number));
  store(gl.UNPACK_FLIP_Y_WEBGL, false);
  store(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
  store(gl.UNPACK_ALIGNMENT, 4);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, canvas);
  return t;
}

/** 新建一块离屏 2D 画布：小游戏用 wx.createCanvas（第一块是上屏画布，适配层启动时已经建过），网页用 DOM */
export function createCanvas(): HTMLCanvasElement {
  const wx = (globalThis as { wx?: { createCanvas?: () => HTMLCanvasElement } }).wx;
  if (wx && typeof wx.createCanvas === 'function') return wx.createCanvas();
  return document.createElement('canvas');
}

/** 面板换着色器（T132 精良卡荧光）：frag 里有 map / opacity 两个现成的 uniform，uniforms 是另加的；blending 不给 = 普通透明混合 */
export interface PanelFx {
  frag: string;
  uniforms?: Record<string, THREE.IUniform>;
  blending?: THREE.Blending;
}

/** 一块面板：2D 画好 → texImage2D 上传 → 正交相机里一个四边形 */
export class Panel {
  /** 逻辑像素位置 / 尺寸（左上角） */
  x = 0;
  y = 0;
  w = 0;
  h = 0;
  visible = false;
  /** 动画：透明度、位移、绕中心缩放（都不触发重画） */
  alpha = 1;
  dx = 0;
  dy = 0;
  scale = 1;
  /** 排版放大：重绘纹理与点击区域一起换算，独立于入场动画的 scale。 */
  uiScale = 1;
  /** 两次重画的最小间隔（秒）：变化很快的数字（血量、推进距离）限到每秒十几次 */
  interval = 0;
  dirty = true;
  lastDraw = -1;
  tex: WebGLTexture | null = null;
  readonly canvas = createCanvas();
  readonly ctx = this.canvas.getContext('2d') as CanvasRenderingContext2D;
  readonly map = new THREE.ExternalTexture(null);
  readonly mat: THREE.ShaderMaterial;
  readonly mesh: THREE.Mesh;

  constructor(
    readonly name: string,
    order: number,
    readonly paint: (ctx: CanvasRenderingContext2D, w: number, h: number) => void,
    fx?: PanelFx,
  ) {
    this.mat = quadMaterial(fx?.frag ?? PANEL_FRAG, { map: { value: this.map }, ...fx?.uniforms });
    if (fx?.blending !== undefined) this.mat.blending = fx.blending;
    this.mesh = new THREE.Mesh(QUAD, this.mat);
    this.mesh.renderOrder = order;
    this.mesh.frustumCulled = false;
    this.mesh.visible = false;
  }

  /** 放到 (x, y)，尺寸 w × h；尺寸变了要重画 */
  place(x: number, y: number, w: number, h: number): void {
    if (Math.abs(w - this.w) > 0.01 || Math.abs(h - this.h) > 0.01) this.dirty = true;
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
  }

  placeUi(x: number, y: number, w: number, h: number, scale: number): void {
    if (this.uiScale !== scale) this.dirty = true;
    this.uiScale = scale;
    this.place(x, y, w * scale, h * scale);
  }

  get rect(): Rect {
    return { x: this.x, y: this.y, w: this.w, h: this.h };
  }
}

export class Overlay {
  /** 当前菜单的滚动入口，供右杆与翻页键共用。 */
  menuScroll: ((amount: number) => void) | null = null;
  readonly scene = new THREE.Scene();
  readonly camera = new THREE.OrthographicCamera(0, 390, 0, -844, -10, 10);
  /** 逻辑像素（CSS 像素 / 小游戏 windowWidth） */
  W = 390;
  H = 844;
  /** 面板纹理的像素比 = 渲染器当前像素比 */
  dpr = 1;
  insets: Insets = { top: 0, right: 0, bottom: 0, left: 0 };
  /** 小游戏右上角胶囊按钮（不能被界面盖住）；网页为 null */
  capsule: Rect | null = null;
  /** 开始界面显示中（HUD 隐藏） */
  inTitle = false;
  /** 正在按着的可点区域 id（组件画按压态用） */
  pressed: string | null = null;
  /** 正按在屏幕上的所有手指（按钮上的、战场上的都算） */
  readonly fingers = new Fingers();
  /** 秒（performance.now） */
  now = 0;
  readonly stats = { uploads: 0, uploadPx: 0, panels: 0, frameUploads: 0 };

  private readonly panels: Panel[] = [];
  private readonly frames: ((dt: number) => void)[] = [];
  private regions: Region[] = [];
  private readonly active = new Map<number, Press>();
  private last = 0;
  private readonly hitMesh: THREE.Mesh;
  private readonly ultMesh: THREE.Mesh;
  private hitT = 1;
  private ultT = 1;
  private ultA = 0.7;

  constructor(
    private readonly renderer: THREE.WebGLRenderer,
    layer: HTMLElement,
  ) {
    this.hitMesh = new THREE.Mesh(QUAD, quadMaterial(HIT_FRAG, {}));
    this.hitMesh.renderOrder = 2;
    this.ultMesh = new THREE.Mesh(QUAD, quadMaterial(ULT_FRAG, {}));
    this.ultMesh.renderOrder = 4;
    for (const m of [this.hitMesh, this.ultMesh]) {
      m.frustumCulled = false;
      m.visible = false;
      this.scene.add(m);
    }
    layer.addEventListener('pointerdown', this.onDown as EventListener);
    layer.addEventListener('pointermove', this.onMove as EventListener);
    layer.addEventListener('pointerup', this.onUp as EventListener);
    layer.addEventListener('pointercancel', this.onCancel as EventListener);
    layer.addEventListener('wheel', ((e: WheelEvent) => {
      if (!this.menuScroll || !this.gamepadMenu()) return;
      e.preventDefault();
      this.menuScroll(e.deltaY * (e.deltaMode === 1 ? 24 : 1));
    }) as EventListener, { passive: false });
    // 轮播拖动：丢了指针、切走窗口都算取消；其余点按照旧
    layer.addEventListener('lostpointercapture', ((e: PointerEvent) => this.cancelDrags(e.pointerId)) as EventListener);
    globalThis.addEventListener?.('blur', () => this.cancelDrags());
    document.addEventListener?.('visibilitychange', () => { if (document.hidden) this.cancelDrags(); });
    globalThis.addEventListener?.('resize', () => this.resize(true));
    this.resize(true);
    // 自动化测试 / 真机仿真器用：查可点区域（点它的中心）
    (globalThis as Record<string, unknown>).__TANK_UI__ = {
      mode: 'canvas',
      regions: () => this.regions.map((r) => ({ id: r.id, x: r.x, y: r.y, w: r.w, h: r.h, z: r.z })),
      stats: this.stats,
    };
  }

  panel(name: string, order: number, paint: (ctx: CanvasRenderingContext2D, w: number, h: number) => void, fx?: PanelFx): Panel {
    const p = new Panel(name, order, paint, fx);
    this.panels.push(p);
    this.scene.add(p.mesh);
    return p;
  }

  /** 每帧（渲染前）调用：组件在这里推进动画、摆放面板、登记可点区域 */
  onFrame(fn: (dt: number) => void): void {
    this.frames.push(fn);
  }

  region(r: Region): void {
    this.regions.push(r);
  }

  /** 这个点落在哪个可点区域上（最上面的那个） */
  hit(x: number, y: number): Region | null {
    if (!Number.isFinite(x) || !Number.isFinite(y)) return null;
    let best: Region | null = null;
    for (const r of this.regions) {
      if (x < r.x || y < r.y || x > r.x + r.w || y > r.y + r.h) continue;
      if (!best || r.z >= best.z) best = r;
    }
    return best;
  }

  /** 手指落在界面上（走位 / 开炮不接这根手指） */
  blocks(x: number, y: number): boolean {
    return this.hit(x, y) !== null;
  }

  flashDamage(): void {
    this.hitT = 0;
  }

  flashUlt(alpha: number): void {
    this.ultT = 0;
    this.ultA = alpha;
  }

  private prepared = false;

  /** 先排好界面，摄影棚才能取得本帧窗口坐标。 */
  prepare(): void {
    if (this.prepared) return;
    this.prepared = true;
    const now = performance.now() / 1000;
    const dt = this.last ? Math.min(0.1, Math.max(0, now - this.last)) : 0;
    this.last = now;
    this.now = now;
    this.resize(false);
    this.regions = [];
    for (const f of this.frames) f(dt);
    this.stepPresses(now);
    this.stepFlashes(dt);
  }

  /** 启动预热（T108 的「着色器」那一步）：面板的着色器先编好，含平时藏着的精良卡荧光 / 光爆（T132），第一次弹精良卡不卡一下 */
  compile(): void {
    const r = this.renderer;
    const target = r.getRenderTarget();
    r.setRenderTarget(null);
    r.compile(this.scene, this.camera);
    r.setRenderTarget(target);
  }

  rect(id: string): Rect | null {
    return this.regions.find((r) => r.id === id) ?? null;
  }

  /** 手柄只在最上层浮层内选按钮，不能穿过图鉴去选下面的升级卡。 */
  gamepadMenu(): { id: string; regions: Region[] } | null {
    const back = this.regions.reduce<Region | null>((top, r) => r.id.endsWith('-backdrop') && (!top || r.z >= top.z) ? r : top, null);
    if (!back) return null;
    return { id: back.id, regions: this.regions.filter(r => r.z > back.z && !!r.tap && r.w > 0 && r.h > 0) };
  }

  /** 主画面画完后调用：重画脏面板、叠到屏幕上。 */
  render(): void {
    this.prepare();
    this.prepared = false;
    const now = this.now;
    let up = 0;
    let shown = 0;
    for (const p of this.panels) {
      if (!p.visible || p.w < 1 || p.h < 1) {
        p.mesh.visible = false;
        // 藏起来的大面板（全屏浮层）把画布和纹理缩成 1×1，省内存（小游戏真机内存紧）；再显示时重画
        if (p.tex && p.canvas.width * p.canvas.height > 262144) {
          p.canvas.width = 1;
          p.canvas.height = 1;
          this.upload(p);
          p.dirty = true;
        }
        continue;
      }
      if (p.dirty && now - p.lastDraw >= p.interval) {
        this.draw(p);
        p.lastDraw = now;
        up++;
      }
      // 对齐到渲染像素：纹理一个像素对屏幕一个像素，字不糊
      const d = this.dpr;
      const x = Math.round((p.x + p.dx) * d) / d;
      const y = Math.round((p.y + p.dy) * d) / d;
      const w = p.canvas.width / d;
      const h = p.canvas.height / d;
      p.mesh.position.set(x + w / 2, -(y + h / 2), 0);
      p.mesh.scale.set(w * p.scale, h * p.scale, 1);
      p.mat.uniforms.opacity.value = p.alpha;
      p.mesh.visible = p.tex !== null && p.alpha > 0.004;
      if (p.mesh.visible) shown++;
    }
    this.stats.frameUploads = up;
    this.stats.panels = shown;
    const r = this.renderer;
    const auto = r.autoClear;
    r.setRenderTarget(null);
    r.autoClear = false;
    r.render(this.scene, this.camera);
    r.autoClear = auto;
  }

  private draw(p: Panel): void {
    const d = this.dpr;
    const bw = Math.max(1, Math.round(p.w * d));
    const bh = Math.max(1, Math.round(p.h * d));
    const cv = p.canvas;
    if (cv.width !== bw || cv.height !== bh) {
      cv.width = bw;
      cv.height = bh;
    }
    const ctx = p.ctx;
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalAlpha = 1;
    ctx.clearRect(0, 0, bw, bh);
    ctx.setTransform(d * p.uiScale, 0, 0, d * p.uiScale, 0, 0);
    p.paint(ctx, p.w / p.uiScale, p.h / p.uiScale);
    p.dirty = false;
    this.upload(p);
    this.stats.uploads++;
    this.stats.uploadPx += bw * bh;
  }

  private upload(p: Panel): void {
    p.tex = uploadCanvas(this.renderer, p.tex, p.canvas);
    p.map.sourceTexture = p.tex;
  }

  private stepFlashes(dt: number): void {
    // 受击：0.34 秒从 0.95 淡出（ease-out）
    if (this.hitT < 1) this.hitT = Math.min(1, this.hitT + dt / 0.34);
    const ha = this.hitT < 1 ? 0.95 * (1 - this.hitT) * (1 - this.hitT * 0.5) : 0;
    this.hitMesh.visible = ha > 0.004;
    (this.hitMesh.material as THREE.ShaderMaterial).uniforms.opacity.value = ha;
    // 核爆白闪：0.39 秒，前 10% 拉满、之后退完
    if (this.ultT < 1) this.ultT = Math.min(1, this.ultT + dt / 0.39);
    const k = this.ultT;
    const ua = k >= 1 ? 0 : k < 0.1 ? (k / 0.1) * this.ultA : this.ultA * (1 - (k - 0.1) / 0.9) ** 1.6;
    this.ultMesh.visible = ua > 0.004;
    (this.ultMesh.material as THREE.ShaderMaterial).uniforms.opacity.value = ua;
  }

  private resize(force: boolean): void {
    const cv = this.renderer.domElement;
    const W = Math.max(1, Math.floor(cv.clientWidth || this.W));
    const H = Math.max(1, Math.floor(cv.clientHeight || this.H));
    const dpr = this.renderer.getPixelRatio() || 1;
    if (!force && W === this.W && H === this.H && dpr === this.dpr) return;
    this.W = W;
    this.H = H;
    this.dpr = dpr;
    this.camera.right = W;
    this.camera.bottom = -H;
    this.camera.updateProjectionMatrix();
    for (const m of [this.hitMesh, this.ultMesh]) {
      m.position.set(W / 2, -H / 2, 0);
      m.scale.set(W, H, 1);
    }
    for (const p of this.panels) p.dirty = true;
    this.readInsets();
  }

  /** 安全区：小游戏读 safeArea + 胶囊按钮，网页读 CSS env(safe-area-inset-*) */
  private readInsets(): void {
    type WxRect = { left: number; top: number; right: number; bottom: number; width: number; height: number };
    const wx = (globalThis as { wx?: { getSystemInfoSync?: () => Record<string, unknown>; getMenuButtonBoundingClientRect?: () => WxRect } }).wx;
    if (wx?.getSystemInfoSync) {
      try {
        const si = wx.getSystemInfoSync();
        const sa = si.safeArea as WxRect | undefined;
        const sw = Number(si.screenWidth) || this.W;
        const sh = Number(si.screenHeight) || this.H;
        this.insets = sa
          ? { top: Math.max(0, sa.top), left: Math.max(0, sa.left), right: Math.max(0, sw - sa.right), bottom: Math.max(0, sh - sa.bottom) }
          : { top: Number(si.statusBarHeight) || 0, left: 0, right: 0, bottom: 0 };
        const m = wx.getMenuButtonBoundingClientRect?.();
        this.capsule = m && m.width > 0 ? { x: m.left, y: m.top, w: m.width, h: m.height } : null;
      } catch {
        /* 读不到就按没有刘海处理 */
      }
      return;
    }
    if (typeof document === 'undefined' || !document.body) return;
    // ?ui=canvas&notch=1：网页里模拟小游戏真机的刘海安全区 + 右上角胶囊按钮（iPhone 常见值），截图对照用
    if (new URLSearchParams(location.search).has('notch')) {
      this.insets = { top: 47, right: 0, bottom: 34, left: 0 };
      this.capsule = { x: this.W - 94, y: 51, w: 87, h: 32 };
      return;
    }
    this.insets = cssInsets();
  }

  // ---------------------------------------------------------------- 点击

  private setPressed(id: string | null, panel?: Panel): void {
    if (this.pressed === id) return;
    this.pressed = id;
    if (panel) panel.dirty = true;
  }

  private stepPresses(now: number): void {
    for (const a of this.active.values()) {
      const h = a.r.hold;
      if (!h || a.early || a.moved || a.held || now * 1000 - a.t0 < h.ms) continue;
      a.held = true;
      h.start();
    }
  }

  private readonly onDown = (e: PointerEvent) => {
    const r = this.hit(e.clientX, e.clientY);
    this.fingers.press(e.pointerId, !r);
    if (this.active.has(e.pointerId) || !r) return;
    const early = !!r.ready && !r.ready();
    const dragging = !early && (r.drag?.start(e.clientX, e.clientY, e.pointerId) ?? false);
    this.active.set(e.pointerId, { r, x0: e.clientX, y0: e.clientY, t0: performance.now(), moved: !!r.drag && !dragging, held: false, early, dragging });
    if (early) return;
    if (dragging) {
      try { (e.currentTarget as HTMLElement).setPointerCapture?.(e.pointerId); } catch { /* 小游戏适配层由触控层转发松手 */ }
    }
    if (r.tap) this.setPressed(r.id, r.panel);
    r.down?.();
  };

  private readonly onMove = (e: PointerEvent) => {
    const a = this.active.get(e.pointerId);
    if (a?.dragging) a.r.drag?.move(e.clientX, e.clientY, e.pointerId);
    if (!a || a.moved || Math.hypot(e.clientX - a.x0, e.clientY - a.y0) <= TAP_SLOP) return;
    a.moved = true;
    if (this.pressed === a.r.id) this.setPressed(null, a.r.panel);
    if (a.held) {
      a.held = false;
      a.r.hold?.end();
    }
  };

  private readonly onUp = (e: PointerEvent) => {
    this.fingers.lift(e.pointerId);
    const a = this.active.get(e.pointerId);
    if (!a) return;
    this.active.delete(e.pointerId);
    if (this.pressed === a.r.id) this.setPressed(null, a.r.panel);
    if (a.dragging && a.r.drag?.end(e.clientX, e.clientY, e.pointerId, false)) return;
    if (a.held) {
      a.r.hold?.end();
      return;
    }
    const moved = a.moved || Math.hypot(e.clientX - a.x0, e.clientY - a.y0) > TAP_SLOP;
    if (!a.early && !moved && (a.r.tapMs === undefined || performance.now() - a.t0 <= a.r.tapMs)) a.r.tap?.();
  };

  private readonly onCancel = (e: PointerEvent) => {
    this.fingers.lift(e.pointerId);
    const a = this.active.get(e.pointerId);
    if (!a) return;
    this.active.delete(e.pointerId);
    if (this.pressed === a.r.id) this.setPressed(null, a.r.panel);
    if (a.dragging) a.r.drag?.end(e.clientX, e.clientY, e.pointerId, true);
    if (a.held) a.r.hold?.end();
  };

  private cancelDrags(only?: number): void {
    for (const [id, a] of this.active) {
      if (!a.dragging || (only !== undefined && id !== only)) continue;
      this.active.delete(id);
      a.r.drag?.end(a.x0, a.y0, id, true);
      if (this.pressed === a.r.id) this.setPressed(null, a.r.panel);
    }
  }
}
