import * as THREE from 'three';
import type { GeoCache, PartSpec } from '../assets/GeoCache';
import { MAT } from '../assets/materials';
import type { Fx } from '../render/Fx';
import type { Bump } from '../systems/World';
import type { Theme } from './themes';

/**
 * 钢铁厂区的两种大件（T019-c，汇总第 24 条，策划 `T019-第四关-策划案.md` 2.3「新景物两种」）：只在 `foundry` 主题的路两边摆，
 * 不挡路、不减速、能破坏（照 T009 规则：景物不给伤害）——
 * - **烟囱**（砖砌圆柱，底径 4.4、高 22～30 米）：结构 hp，挨爆炸按 k = F × (1 − d ÷ 波及) + 0.25F 扣（和 World.blast 同一公式），
 *   扣光 = **整根朝背离爆心的方向倒下**（fall 秒慢倒、越倒越快），落地炸成一条碎砖带 + 大片扬尘 + 闷响；倒进路面的登记成软凸起（压过去车身抬起、不减速），砸到倒伏线上的步兵（fallKill）
 * - **储罐**（圆柱 + 穹顶，直径 8、高 7 米）：结构 hp，归零 = **炸开**（火球 + 罐顶的铁皮四散 + 原地烧 burn 秒 + 黑烟柱），变焦黑矮一截；点着 12 米内的植被 / 木头路障
 * 和路边景物分开管（它们只在第 4 区出现，没有接 SceneryDamage 那套 8 种破坏方式；只吃爆炸）
 */
export const FOUNDRY = {
  gap: [55, 95],
  side: [19, 34],
  chimney: { hp: 12, h: [22, 30], r: 2.2, fall: 2.2, chance: 0.55 },
  tank: { hp: 30, r: 4, h: 7, burn: 8, ignite: 12 },
  cap: { chimney: 14, tank: 10 },
};

interface Chimney {
  x: number;
  z: number;
  h: number;
  hp: number;
  /** 0 立着 / 1 正在倒 / 2 倒在地上 */
  state: 0 | 1 | 2;
  t: number;
  dx: number;
  dz: number;
}

interface Tank {
  x: number;
  z: number;
  hp: number;
  burst: boolean;
  t: number;
  rot: number;
}

export interface FoundryHooks {
  addBump(b: Omit<Bump, 'flat' | 'alive' | 'stage' | 'debris'> & { debris?: Bump['debris'] }): Bump;
  fallKill(x0: number, z0: number, x1: number, z1: number, w: number): void;
  ignite(x: number, z: number, r: number): void;
  sfx(tone: 'crunch' | 'bigboom' | 'explode', x: number, z: number, vol?: number): void;
  shake(x: number, z: number, a: number): void;
  chunks(x: number, y: number, z: number, n: number, kind: 'concrete' | 'metal'): void;
}

const _m = new THREE.Matrix4();
const _q = new THREE.Quaternion();
const _p = new THREE.Vector3();
const _s = new THREE.Vector3();
const _a = new THREE.Vector3();
const CHAR = new THREE.Color(0x3a3430);
const WHITE = new THREE.Color(0xffffff);

/** 战场与开始页共用几何；展示页只取景物，不启动战场逻辑。 */
export function foundryChimneyGeo(geo: GeoCache): THREE.BufferGeometry {
  return geo.merged('foundry-chimney', () => {
    const p: PartSpec[] = [
      { geo: new THREE.CylinderGeometry(1.5, 2.2, 26, 14), color: 0x8a4a38, pos: [0, 13, 0] },
      { geo: new THREE.CylinderGeometry(2.5, 2.6, 1.6, 14), color: 0x5e3a30, pos: [0, 0.8, 0] },
      { geo: new THREE.CylinderGeometry(1.75, 1.75, 1.2, 14), color: 0x4a2e26, pos: [0, 25.6, 0] },
      { geo: new THREE.CylinderGeometry(2.0, 2.0, 0.2, 14), color: 0x3a3836, pos: [0, 24.2, 0] },
    ];
    for (const y of [7, 13, 19]) p.push({ geo: new THREE.CylinderGeometry(2.25 - y * 0.027, 2.25 - y * 0.027, 0.5, 14), color: 0x4e2e26, pos: [0, y, 0] });
    return p;
  });
}

export function foundryTankGeo(geo: GeoCache): THREE.BufferGeometry {
  return geo.merged('foundry-tank', () => [
    { geo: new THREE.CylinderGeometry(4, 4, 5.6, 20), color: 0x9a948a, pos: [0, 2.8, 0] },
    { geo: new THREE.SphereGeometry(4, 20, 8, 0, Math.PI * 2, 0, Math.PI / 2), color: 0x8a847a, pos: [0, 5.6, 0], scale: [1, 0.35, 1] },
    { geo: new THREE.CylinderGeometry(4.05, 4.05, 0.5, 20), color: 0x7a4a34, pos: [0, 1.6, 0] },
    { geo: new THREE.CylinderGeometry(4.05, 4.05, 0.3, 20), color: 0x6a5a4a, pos: [0, 4.4, 0] },
    { geo: new THREE.BoxGeometry(0.6, 6.2, 0.2), color: 0x4a4642, pos: [0, 3.1, 4.1] },
    { geo: new THREE.BoxGeometry(1.4, 0.2, 1.4), color: 0x4a4642, pos: [0, 6.4, 3.2] },
  ]);
}

export class Foundry {
  readonly group = new THREE.Group();
  readonly chimneys: Chimney[] = [];
  readonly tanks: Tank[] = [];
  private readonly chimMesh: THREE.InstancedMesh;
  private readonly tankMesh: THREE.InstancedMesh;
  private cursor = -80;
  private rngSeed = 4242;

  constructor(
    geo: GeoCache,
    private readonly fx: Fx,
    private readonly hooks: FoundryHooks,
  ) {
    // 烟囱：高 26 的砖筒（缩放到 22～30），三道深色箍 + 顶部检修平台；原点在底座中心，倒的时候绕底座转
    const cg = foundryChimneyGeo(geo);
    this.chimMesh = new THREE.InstancedMesh(cg, MAT.painted, FOUNDRY.cap.chimney);
    // 储罐：圆柱 + 穹顶、外梯、锈斑
    const tg = foundryTankGeo(geo);
    this.tankMesh = new THREE.InstancedMesh(tg, MAT.painted, FOUNDRY.cap.tank);
    for (const m of [this.chimMesh, this.tankMesh]) {
      m.castShadow = true;
      m.receiveShadow = true;
      m.frustumCulled = false;
      m.count = 0;
      m.setColorAt(0, WHITE);
      this.group.add(m);
    }
  }

  private rnd(): number {
    this.rngSeed = (this.rngSeed * 16807) % 2147483647;
    return (this.rngSeed - 1) / 2147483646;
  }

  reset(): void {
    this.chimneys.length = 0;
    this.tanks.length = 0;
    this.cursor = -80;
    this.sync();
  }

  /** 前方摆、身后收；只在钢铁厂区，blocked = 河道 / 铁路；rear = 身后收掉按的位置（T107 停车攻坚时是能退到的最远处） */
  update(playerZ: number, delta: number, themeAt: (z: number) => Theme, blocked: (x: number, z: number) => boolean, rear = playerZ): void {
    const ahead = playerZ - 320;
    while (this.cursor > ahead) {
      const z = this.cursor;
      this.cursor -= FOUNDRY.gap[0] + this.rnd() * (FOUNDRY.gap[1] - FOUNDRY.gap[0]);
      if (themeAt(z).id !== 'foundry') continue;
      const side = this.rnd() < 0.5 ? -1 : 1;
      const x = side * (FOUNDRY.side[0] + this.rnd() * (FOUNDRY.side[1] - FOUNDRY.side[0]));
      if (blocked(x, z)) continue;
      if (this.rnd() < FOUNDRY.chimney.chance) {
        if (this.chimneys.length < FOUNDRY.cap.chimney) this.chimneys.push({ x, z, h: FOUNDRY.chimney.h[0] + this.rnd() * (FOUNDRY.chimney.h[1] - FOUNDRY.chimney.h[0]), hp: FOUNDRY.chimney.hp, state: 0, t: 0, dx: 0, dz: 0 });
      } else if (this.tanks.length < FOUNDRY.cap.tank) this.tanks.push({ x, z, hp: FOUNDRY.tank.hp, burst: false, t: 0, rot: this.rnd() * Math.PI * 2 });
    }
    for (let i = this.chimneys.length - 1; i >= 0; i--) if (this.chimneys[i].z > rear + 70) this.chimneys.splice(i, 1);
    for (let i = this.tanks.length - 1; i >= 0; i--) if (this.tanks[i].z > rear + 70) this.tanks.splice(i, 1);
    for (const c of this.chimneys) if (c.state === 1) this.stepFall(c, delta);
    for (const t of this.tanks) {
      if (!t.burst || t.t <= 0) continue;
      t.t -= delta;
      // 炸开的储罐原地烧，冒黑烟柱
      if (Math.random() < delta * 6) this.fx.fire(t.x + (Math.random() - 0.5) * 5, 2 + Math.random() * 2, t.z + (Math.random() - 0.5) * 5, 1.6);
      if (Math.random() < delta * 3) this.fx.column(t.x, 4, t.z, 2.2, 1);
    }
    this.sync();
  }

  /** 爆炸（World.blast 每一下都转进来）：按距离扣结构 */
  blast(x: number, z: number, radius: number, force: number): void {
    for (const c of this.chimneys) {
      if (c.state !== 0) continue;
      const k = this.k(c.x, c.z, FOUNDRY.chimney.r, x, z, radius, force);
      if (k <= 0) continue;
      c.hp -= k;
      if (k >= 3) this.hooks.chunks(c.x, 3 + Math.random() * 6, c.z, 2, 'concrete');
      if (c.hp > 0) continue;
      // 结构扣光：背离爆心倒下（正对着就随便挑一个方向）
      const len = Math.hypot(c.x - x, c.z - z);
      const a = Math.random() * Math.PI * 2;
      this.topple(c, len < 0.5 ? Math.cos(a) : (c.x - x) / len, len < 0.5 ? Math.sin(a) : (c.z - z) / len);
    }
    for (const t of this.tanks) {
      if (t.burst) continue;
      const k = this.k(t.x, t.z, FOUNDRY.tank.r, x, z, radius, force);
      if (k <= 0) continue;
      t.hp -= k;
      if (t.hp > 0) continue;
      this.burstTank(t);
    }
  }

  /**
   * 激光主光束（T032 A1，原来烟囱 / 储罐只吃爆炸、光束直接穿过去）：沿光束（起点 o、单位方向 d、长 len、半宽 half）照到的立着的烟囱 / 没炸开的储罐每秒扣 rate 结构，
   * 扣光照爆炸那一套（烟囱顺着光束往外倒、储罐炸开）；照着的时候入射点红热冒火星、偶尔崩碎块。光束停在第一座上（pierce = 聚焦线穿过去、沿线的都照），返回光束停在多远
   */
  beam(ox: number, oz: number, dx: number, dz: number, len: number, half: number, dt: number, rate: number, pierce: boolean): number {
    let stop = len;
    let first: Chimney | Tank | null = null;
    const hit = (s: Chimney | Tank, t: number): void => {
      const hx = ox + dx * t;
      const hz = oz + dz * t;
      const tank = 'burst' in s;
      if (Math.random() < dt * 25) this.fx.hot(hx - dx * 0.3, 1.3, hz - dz * 0.3, 1, 0.9);
      if (Math.random() < dt * 8) this.fx.sparks(hx, 1.3, hz, 3, 0xffd070, 6);
      if (Math.random() < dt * 1.5) this.hooks.chunks(hx, 1.6, hz, 1, tank ? 'metal' : 'concrete');
      s.hp -= rate * dt;
      if (s.hp > 0) return;
      if (tank) this.burstTank(s);
      else this.topple(s, dx, dz);
    };
    const each = (s: Chimney | Tank, r: number): void => {
      // 射线和圆柱（地面投影的圆，半径 r + 光束半宽）的进入点
      const px = s.x - ox;
      const pz = s.z - oz;
      const R = r + half;
      const side = Math.abs(px * dz - pz * dx);
      const along = px * dx + pz * dz;
      if (side > R || along < -R) return;
      const t = Math.max(0, along - Math.sqrt(R * R - side * side));
      if (t > stop) return;
      if (pierce) hit(s, t);
      else {
        stop = t;
        first = s;
      }
    };
    for (const c of this.chimneys) if (c.state === 0) each(c, FOUNDRY.chimney.r);
    for (const t of this.tanks) if (!t.burst) each(t, FOUNDRY.tank.r);
    if (first) hit(first, stop);
    return stop;
  }

  /** 烟囱结构扣光：朝 (dx, dz) 倒下（单位向量） */
  private topple(c: Chimney, dx: number, dz: number): void {
    c.state = 1;
    c.t = 0;
    c.dx = dx;
    c.dz = dz;
    this.hooks.sfx('crunch', c.x, c.z, 0.9);
    this.fx.dust(c.x, c.z, 4, 0x8a6a58, 0.6);
  }

  /** 波及半径 = 爆炸半径 + 物件半径 × 0.6，k = F × (1 − d ÷ 波及) + 0.25F（和 World.blast / 路边景物同一个公式） */
  private k(ox: number, oz: number, r: number, x: number, z: number, radius: number, force: number): number {
    const reach = radius + r * 0.6;
    const d = Math.max(0, Math.hypot(ox - x, oz - z) - r * 0.4);
    if (d > reach) return 0;
    return force * (1 - d / reach) + force * 0.25;
  }

  private burstTank(t: Tank): void {
    t.burst = true;
    t.t = FOUNDRY.tank.burn;
    this.fx.explosion(t.x, t.z, 5.5, 4);
    this.fx.flash(t.x, 6, t.z, 3500);
    this.fx.shockwave(t.x, t.z, 14, 0xffb070, 0.6);
    this.fx.burn(t.x, t.z, 3, FOUNDRY.tank.burn);
    for (let i = 0; i < 3; i++) this.fx.smoke(t.x + (Math.random() - 0.5) * 4, 6, t.z + (Math.random() - 0.5) * 4, 3.4, 4, 0x1e1b19, 0.7);
    this.hooks.chunks(t.x, 6, t.z, 10, 'metal');
    this.hooks.ignite(t.x, t.z, FOUNDRY.tank.ignite);
    this.hooks.sfx('bigboom', t.x, t.z);
    this.hooks.shake(t.x, t.z, 0.6);
  }

  /** 烟囱倒下：越倒越快（缓入），倒平了砸地 */
  private stepFall(c: Chimney, delta: number): void {
    c.t = Math.min(1, c.t + delta / FOUNDRY.chimney.fall);
    if (c.t < 1) return;
    c.state = 2;
    const x1 = c.x + c.dx * c.h;
    const z1 = c.z + c.dz * c.h;
    // 落地：一条碎砖带 + 大片扬尘 + 闷响；砸到倒伏线上的步兵
    for (let i = 0; i <= 6; i++) {
      const f = i / 6;
      this.fx.dust(c.x + c.dx * c.h * f, c.z + c.dz * c.h * f, 3.6, 0x8a6a58, 0.65);
      if (i % 2 === 0) this.hooks.chunks(c.x + c.dx * c.h * f, 1.2, c.z + c.dz * c.h * f, 3, 'concrete');
    }
    this.hooks.fallKill(c.x, c.z, x1, z1, 2.4);
    this.hooks.sfx('bigboom', (c.x + x1) / 2, (c.z + z1) / 2, 0.8);
    this.hooks.shake((c.x + x1) / 2, (c.z + z1) / 2, 0.5);
    // 倒进路面的那一段：软凸起（压过去车身抬起、压扁，不减速）
    const ROAD = 14;
    const t0 = Math.abs(c.dx) < 1e-3 ? (Math.abs(c.x) < ROAD ? 0 : 2) : Math.max(0, Math.min((ROAD - c.x) / (c.dx * c.h), (-ROAD - c.x) / (c.dx * c.h)));
    const t1 = Math.abs(c.dx) < 1e-3 ? 1 : Math.min(1, Math.max((ROAD - c.x) / (c.dx * c.h), (-ROAD - c.x) / (c.dx * c.h)));
    if (t1 > t0 && t0 <= 1) {
      const fm = (t0 + t1) / 2;
      this.hooks.addBump({ x: c.x + c.dx * c.h * fm, z: c.z + c.dz * c.h * fm, halfW: 1.8, halfD: (c.h * (t1 - t0)) / 2, rot: Math.atan2(c.dx, c.dz), h0: 1.4, h1: 0.5, debris: 'concrete', soft: true });
    }
  }

  private sync(): void {
    const cm = this.chimMesh;
    this.chimneys.forEach((c, i) => {
      const e = c.state === 0 ? 0 : c.state === 2 ? 1 : c.t * c.t;
      _q.setFromAxisAngle(_a.set(c.dz, 0, -c.dx), (Math.PI / 2) * e);
      _m.compose(_p.set(c.x, c.state === 2 ? 0.6 : 0, c.z), _q, _s.set(1, c.h / 26, 1));
      cm.setMatrixAt(i, _m);
      cm.setColorAt(i, c.state === 2 ? CHAR : WHITE);
    });
    cm.count = this.chimneys.length;
    cm.instanceMatrix.needsUpdate = true;
    if (cm.instanceColor) cm.instanceColor.needsUpdate = true;
    const tm = this.tankMesh;
    this.tanks.forEach((t, i) => {
      _q.setFromAxisAngle(_a.set(0, 1, 0), t.rot);
      _m.compose(_p.set(t.x, 0, t.z), _q, _s.set(t.burst ? 1.04 : 1, t.burst ? 0.72 : 1, t.burst ? 1.04 : 1));
      tm.setMatrixAt(i, _m);
      tm.setColorAt(i, t.burst ? CHAR : WHITE);
    });
    tm.count = this.tanks.length;
    tm.instanceMatrix.needsUpdate = true;
    if (tm.instanceColor) tm.instanceColor.needsUpdate = true;
  }
}
