/**
 * 局外成长各页的数据（T030）：军衔 / 军工厂 / 每日任务 / 车库 / 战区 / 勋章墙新页；装配车间（T033）。
 * 纯函数，DOM 版（ui/Menu.ts）和画布版（ui/canvas/CanvasMenu.ts）各画一层皮；按钮 id 交给 Game.onAct
 */

/** 整数加千分位（全中文界面里数字照常写） */
export const fmtInt = (n: number) => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ',');

/** 开始界面入口格子上的「下士开放」（T047：军衔不够的入口锁着显示）；开了 = undefined */
export const entryLock = (c: Career, entry: Entry): string | undefined => (c.open(entry) ? undefined : `${RANKS[ENTRY_RANK[entry] - 1]}开放`);

/** 锁着的入口点进去（T047）：页顶上一行「军衔升到「下士」开放 · 还差 N 军功」，里面的东西照常列、买不了；开了 = '' */
export function entryLockNote(c: Career, entry: Entry, merit: number): string {
  if (c.open(entry)) return '';
  const lv = ENTRY_RANK[entry];
  return `军衔升到「${RANKS[lv - 1]}」开放 · 还差 ${fmtInt(Math.max(0, meritFor(lv) - merit))} 军功`;
}

/** 军衔页：列兵～上尉 / 少校～元帅两页，每级一行（肩章 + 军衔名 + 要多少军功 + 这一级给什么） */
export function rankPages(c: Career, merit: number): RoutePage[] {
  const now = c.rank();
  const head = `${now.name} · 累计军功 ${fmtInt(merit)} · 军票 ${fmtInt(c.e.ticket)}`;
  const row = (lv: number): RouteRow => {
    const need = meritFor(lv);
    const next = lv === now.level + 1;
    return {
      icon: '',
      board: lv,
      title: RANKS[lv - 1],
      tag: lv === now.level ? '当前' : lv < now.level ? '已达成' : `${fmtInt(need)} 军功`,
      // 槽位（T033）：老存档本来就全开，还没到的那几级不再写「副武器槽 +1」；火神（T092）上校以前就开了的，上校那一行不再写「新战车」；荒原机场（T099）同理
      lines: [rankRewardLines(lv, (kind, id) => lv > now.level && (kind === 'bay' ? c.hasBay(id) : kind === 'core' ? c.hasCore(id as CoreId) : kind === 'area' && c.hasArea())).join(' · ')],
      state: lv < now.level ? 'done' : lv === now.level ? 'now' : next ? 'next' : 'off',
      bar: next ? { p: now.progress, text: `还差 ${fmtInt(need - merit)} 军功` } : undefined,
    };
  };
  const page = (id: 'rank-a' | 'rank-b', label: string, from: number, to: number): RoutePage => ({
    id,
    label,
    head,
    sections: [{ title: '每级都有奖励', rows: Array.from({ length: to - from + 1 }, (_, i) => row(from + i)) }],
  });
  return [page('rank-a', '列兵～上尉', 1, 10), page('rank-b', '少校～元帅', 11, 20)];
}

/** 军工厂：5 条线（等级小点、现在 → 下一级、升级按钮；没开放写几级开放）；战备预置开了以后下面一排选副武器 */
export function factoryPage(c: Career): RoutePage[] {
  const t = c.e.ticket;
  const rows = FACTORY.map((f): RouteRow => {
    const lv = c.fac(f.id);
    const open = c.facOpen(f.id);
    const cost = c.facCost(f.id);
    const acts: RouteRow['acts'] = [];
    if (open && cost !== null) acts.push(t >= cost ? { id: `fac:${f.id}`, label: `升级 · 军票 ${fmtInt(cost)}`, kind: 'gold' } : { id: `fac:${f.id}`, label: `军票不足 · 要 ${fmtInt(cost)}`, kind: 'off' });
    if (f.id === 'preset' && lv > 0) for (const w of c.presetPool()) acts.push({ id: `preset:${w}`, label: WEAPONS[w as WeaponId].name, kind: c.preset() === w ? 'chipOn' : 'chip' });
    return {
      icon: f.icon,
      title: f.name,
      pips: { max: f.cost.length, on: lv },
      tag: !open ? `${RANKS[f.rank - 1]}开放` : cost === null ? '已满' : `${lv} / ${f.cost.length} 级`,
      lines: [lv > 0 || !open ? `现在：${f.fx(lv)}` : '还没升级', cost !== null ? `下一级：${f.fx(lv + 1)}` : '已满级'],
      state: !open ? 'off' : cost === null ? 'done' : 'now',
      acts: acts.length ? acts : undefined,
    };
  });
  return [{ id: 'fac', label: '军工厂', head: `军票 ${fmtInt(t)}`, sections: [{ title: '花军票永久升级', rows }] }];
}

/**
 * 每日任务：3 项（进度条 + 奖励 + 换一个），下面一行「三项全完成 +120」；ad = 「看广告 · 换一个」按钮的状态；
 * ask = 点过一下「免费换一个」、等第二下的那一项（T053：有进度的换掉会清零，点两下才换）
 */
export function taskPage(c: Career, ad: AdBtn, ask: number | null = null): RoutePage[] {
  const d = c.daily();
  // 还没开放（T047 锁着也点得进来）：先列一下每天有什么、给多少
  if (!d)
    return [
      {
        id: 'task',
        label: '每日委托',
        sections: [
          {
            title: '每天凌晨 4 点刷新：易、中、难各一项',
            rows: [
              ...TASK_TIER.map((tier, i): RouteRow => ({ icon: 'tasks', title: tier, tag: '未开放', lines: [`奖励：军功 ${TASK_REWARD.merit} · 军票 ${TASK_REWARD.ticket[i]}`], state: 'off' })),
              { icon: 'shield', title: '三项全完成', tag: '未开放', lines: [`再奖励军票 ${TASK_REWARD.bonus}`], state: 'off' },
            ],
          },
        ],
      },
    ];
  const rows = d.tasks.map((t, i): RouteRow => {
    const def = TASK_BY_ID.get(t.id)!;
    const acts: RouteRow['acts'] = [];
    if (!t.done) {
      if (!d.freeSwap) acts.push(ask === i ? { id: `swap:${i}`, label: '再点一次', kind: 'warn' } : { id: `swap:${i}`, label: '免费换一个', kind: 'outline' });
      else if (!d.adSwap && ad !== 'none') acts.push({ id: `swapad:${i}`, label: ad === 'on' ? '看广告 · 换一个' : '广告暂不可用', kind: ad === 'on' ? 'ad' : 'off' });
    }
    return {
      icon: def.icon,
      title: `${TASK_TIER[def.tier]} · ${taskText(def)}`,
      tag: t.done ? '已完成' : def.single ? '单局' : '今日累计',
      lines: [`奖励：军功 ${TASK_REWARD.merit} · 军票 ${TASK_REWARD.ticket[def.tier]}`],
      state: t.done ? 'done' : 'now',
      bar: { p: Math.min(1, t.n / def.n), text: `${fmtInt(t.n)} / ${fmtInt(def.n)}` },
      acts: acts.length ? acts : undefined,
    };
  });
  const done = d.tasks.filter((t) => t.done).length;
  rows.push({ icon: 'shield', title: '三项全完成', tag: d.bonus ? '已领取' : `${done} / 3`, lines: [`再奖励军票 ${TASK_REWARD.bonus}`], state: d.bonus ? 'done' : 'off' });
  const s = secsToReset();
  // 小标题（T053）：三个「免费换一个」是同一次，用完写明（「单局」「今日累计」在每项右上角）
  return [{ id: 'task', label: '每日委托', head: `每天凌晨 4 点刷新 · 还有 ${Math.floor(s / 3600)} 小时 ${Math.floor((s % 3600) / 60)} 分`, sections: [{ title: d.freeSwap ? '免费次数已用完' : '三项共用免费 1 次', rows }] }];
}

// ------------------------------------------------------------------ 车库（T030 第 3 批）

/** 车库里正在预览的那一格（没选 = 预览装备中的） */
export interface GarageSel {
  kind: 'paint' | 'emblem';
  id: string;
}

const css = (h: number) => `#${h.toString(16).padStart(6, '0')}`;

/**
 * 车库三页：涂装 / 纹章 / 精工。上面一行是正在预览的那一套（装备 / 买下 / 看广告试驾一局），下面两列小格子（点一格 = 预览，车上马上换）；
 * drive = 「看广告 · 试驾一局」按钮的状态；note = 一次性提示（广告没看完 / 下一局试驾）
 */
export function garagePages(c: Career, sel: GarageSel | null, drive: AdBtn, note?: string): RoutePage[] {
  const e = c.e;
  const rank = c.rank().level;
  const head = note ?? `军票 ${fmtInt(e.ticket)} · 纯外观`;
  type Def = { id: string; name: string; gift?: number; shelf?: number; cost?: number; special?: string };
  const how = (d: Def) => (d.gift ? `${RANKS[d.gift - 1]}送` : d.shelf ? (rank >= d.shelf ? `军票 ${fmtInt(d.cost ?? 0)}` : `${RANKS[d.shelf - 1]}上架`) : d.special ?? '默认');
  const page = (kind: 'paint' | 'emblem', id: 'gar-p' | 'gar-e', label: string, defs: Def[]): RoutePage => {
    const k = kind === 'paint' ? 'p' : 'e';
    const on = kind === 'paint' ? e.paint : e.emblem;
    const visual = (d: Def): Partial<RouteRow> => (kind === 'paint' ? { swatch: (PAINT_BY_ID.get(d.id)!.colors as number[]).map(css) } : { emblem: d.id });
    const cur = defs.find((d) => sel?.kind === kind && sel.id === d.id) ?? defs.find((d) => d.id === on) ?? defs[0];
    const owned = c.owns(kind, cur.id);
    const driving = (kind === 'paint' ? e.drive?.paint : e.drive?.emblem) === cur.id;
    const acts: RouteRow['acts'] = [];
    // 装备用自己的前缀 equip:（T053）：勋章墙的佩戴是 wear:，以前车库也用 wear:，点「装备」进了勋章那一支
    if (owned && cur.id !== on) acts.push({ id: `equip:${k}:${cur.id}`, label: '装备', kind: 'gold' });
    if (!owned && cur.cost && c.onShelf(kind, cur.id)) acts.push(e.ticket >= cur.cost ? { id: `buy:${k}:${cur.id}`, label: `买下 · 军票 ${fmtInt(cur.cost)}`, kind: 'gold' } : { id: `buy:${k}:${cur.id}`, label: `军票不足 · 要 ${fmtInt(cur.cost)}`, kind: 'off' });
    if (!owned && !driving && drive !== 'none') acts.push(drive === 'on' ? { id: `drive:${k}:${cur.id}`, label: '看广告 · 试驾一局', kind: 'ad' } : { id: 'drive-off', label: '广告暂不可用', kind: 'off' });
    const top: RouteRow = {
      icon: '',
      ...visual(cur),
      title: cur.name,
      tag: cur.id === on ? '装备中' : owned ? '已拥有' : how(cur),
      lines: [cur.id === on ? '装备中' : owned ? '已拥有' : driving ? '下一局用它试驾（打完还原）' : cur.shelf && rank < cur.shelf ? `升到${RANKS[cur.shelf - 1]}上架，之后用军票买` : cur.gift ? `升到${RANKS[cur.gift - 1]}送` : cur.special ? `${cur.special}送` : '还没拥有'],
      state: 'now',
      acts: acts.length ? acts : undefined,
    };
    const grid = defs.map((d): RouteRow => {
      const own = c.owns(kind, d.id);
      return { icon: '', ...visual(d), title: d.name, tag: d.id === on ? '装备中' : own ? '已拥有' : how(d), lines: [], state: d.id === on ? 'now' : own ? 'done' : 'next', tap: `pick:${k}:${d.id}`, sel: d.id === cur.id };
    });
    return { id, label, head, sections: [{ title: '预览', rows: [top] }, { title: `${label} ${defs.filter((d) => c.owns(kind, d.id)).length} / ${defs.length}`, cols: 2, rows: grid }] };
  };
  const paints = PAINTS.filter((p) => !p.special || c.owns('paint', p.id));
  const polish: RoutePage = {
    id: 'gar-x',
    label: '精工',
    head,
    sections: [
      {
        title: '每套涂装三档：战痕 · 精工 · 鎏金',
        rows: paints.filter((p) => c.owns('paint', p.id)).map((p): RouteRow => {
          const lv = c.polish(p.id);
          const cost = c.polishCost(p.id);
          return {
            icon: '',
            swatch: (p.colors as number[]).map(css),
            title: p.name,
            pips: { max: POLISH.length, on: lv },
            tag: cost === null ? '已满' : lv ? POLISH[lv - 1].name : '原样',
            lines: [cost === null ? `${POLISH[2].name}：${POLISH[2].line}` : `下一档「${POLISH[lv].name}」：${POLISH[lv].line}`],
            state: cost === null ? 'done' : 'now',
            acts: cost === null ? undefined : [e.ticket >= cost ? { id: `pol:${p.id}`, label: `${POLISH[lv].name} · 军票 ${fmtInt(cost)}`, kind: 'gold' } : { id: `pol:${p.id}`, label: `军票不足 · 要 ${fmtInt(cost)}`, kind: 'off' }],
            tap: `pick:p:${p.id}`,
            sel: sel?.kind === 'paint' && sel.id === p.id,
          };
        }),
      },
    ],
  };
  return [page('paint', 'gar-p', '涂装', paints), page('emblem', 'gar-e', '纹章', EMBLEMS.filter((m) => !m.special || c.owns('emblem', m.id))), polish];
}

// ------------------------------------------------------------------ 满级之后（T030 第 4 批）：勋章墙「累计」「勋带」两页、将星页、战区页

/** 佩戴的那枚是什么样（结算页 / 战绩卡上画）：ach:<成就> / sum:<累计> / sash:<颗数> / thr:<级> */
export function medalOf(c: Career, id: string): { tier: MedalTier; icon: string } | null {
  const [k, v] = id.split(':');
  if (k === 'ach') {
    const a = ACH_BY_ID.get(v);
    return a ? { tier: a.tier, icon: a.icon } : null;
  }
  if (k === 'sum') {
    const d = SUMS.find((x) => x.id === v);
    const t = c.sumTier(v);
    return d && t ? { tier: SUM_TIERS[t - 1], icon: d.icon } : null;
  }
  if (k === 'sash') {
    const s = SASH.find((x) => x.n === Number(v));
    return s && c.stars() >= s.n ? { tier: s.tier, icon: 'shield' } : null;
  }
  if (k === 'thr') {
    const lv = Number(v);
    return c.e.threatClear.includes(lv) ? { tier: threatTier(lv), icon: 'threat' } : null;
  }
  return null;
}


const fmtSum = (d: SumDef, v: number) => (d.id === 'dist' ? (v >= 10000 ? `${(v / 10000).toFixed(1)} 万公里` : `${v >= 100 || Number.isInteger(v) ? fmtInt(Math.floor(v)) : v.toFixed(1)} 公里`) : v >= 10000 ? `${(v / 10000).toFixed(v >= 100000 ? 0 : 1)} 万${d.unit}` : `${fmtInt(v)}${d.unit ? ` ${d.unit}` : ''}`);

/** 勋章墙「累计」页：每条一行（这一档的勋章 + 进度条到下一档 + 五档门槛），拿到了点一下佩戴 */
export function wallSumPage(c: Career): RoutePage {
  const rows = SUMS.map((d): RouteRow => {
    const t = c.sumTier(d.id);
    const v = sumValue(d, c.e.sums[d.id] ?? 0);
    const next = d.tiers[t];
    const on = c.e.wear.includes(`sum:${d.id}`);
    return {
      icon: d.icon,
      title: d.name,
      medal: { tier: SUM_TIERS[Math.max(0, t - 1)], got: t > 0 },
      tag: on ? '佩戴中' : t ? `${TIER_NAME[SUM_TIERS[t - 1]]} · ${t} / 5` : '还没到铁',
      lines: [d.tiers.map((x, i) => `${TIER_NAME[SUM_TIERS[i]]} ${fmtSum(d, x)}`).join(' · ')],
      state: on ? 'now' : t >= 5 ? 'done' : t ? 'done' : 'next',
      bar: next !== undefined ? { p: v / next, text: `${fmtSum(d, v)} / ${fmtSum(d, next)}` } : { p: 1, text: `${fmtSum(d, v)} · 全满` },
      tap: t ? `wear:sum:${d.id}` : undefined,
    };
  });
  return { id: 'wall-sum', label: '累计', head: `佩戴 ${c.e.wear.length} / 3 · 点勋章佩戴`, sections: [{ title: `每档军票 ${SUM_TICKET.join(' / ')}`, rows }] };
}

/** 勋章墙「勋带」页：将星勋带四档 + 威胁勋章十级 */
export function wallSashPage(c: Career): RoutePage {
  const stars = c.stars();
  const sash = SASH.map((s): RouteRow => {
    const got = stars >= s.n;
    const on = c.e.wear.includes(`sash:${s.n}`);
    return { icon: 'shield', title: `将星勋带 · ${TIER_NAME[s.tier]}`, medal: { tier: s.tier, got }, tag: on ? '佩戴中' : got ? '已获得' : `★${s.n}`, lines: [`元帅以后攒到 ${s.n} 颗将星${s.title ? ` · 称号「${TITLE_BY_ID.get(s.title)?.name}」` : ''}`], state: on ? 'now' : got ? 'done' : 'off', tap: got ? `wear:sash:${s.n}` : undefined };
  });
  const thr = Array.from({ length: THREAT_MAX }, (_, i): RouteRow => {
    const lv = i + 1;
    const got = c.e.threatClear.includes(lv);
    const on = c.e.wear.includes(`thr:${lv}`);
    return { icon: 'threat', title: `威胁勋章 · ${lv} 级`, medal: { tier: threatTier(lv), got }, tag: on ? '佩戴中' : got ? '已获得' : '', lines: [`战区威胁 ${lv} 级打掉「轰天」`], state: on ? 'now' : got ? 'done' : 'off', tap: got ? `wear:thr:${lv}` : undefined };
  });
  return { id: 'wall-sash', label: '勋带', head: `将星 ★${stars}`, sections: [{ title: '将星勋带', cols: 2, rows: sash }, { title: '威胁勋章', cols: 2, rows: thr }] };
}

/** 军衔第三页「将星」：元帅以后每 12,000 军功一颗、每颗 300 军票，勋带 / 称号的节点 */
export function starPage(c: Career, merit: number): RoutePage {
  const stars = c.stars();
  const marshal = c.rank().level >= RANKS.length;
  const into = marshal ? merit - meritFor(RANKS.length) - stars * STAR.merit : 0;
  const rows: RouteRow[] = [
    {
      icon: 'shield',
      board: RANKS.length,
      title: marshal ? `元帅 ★${stars}` : '元帅以后开启',
      tag: marshal ? `${fmtInt(c.e.ticket)} 军票` : `${fmtInt(meritFor(RANKS.length))} 军功`,
      lines: [`每 ${fmtInt(STAR.merit)} 军功一颗，每颗军票 ${STAR.ticket}`],
      state: marshal ? 'now' : 'off',
      bar: marshal ? { p: into / STAR.merit, text: `下一颗还差 ${fmtInt(STAR.merit - into)} 军功` } : undefined,
    },
    ...SASH.map((s): RouteRow => ({ icon: 'shield', title: `★${s.n} · 将星勋带「${TIER_NAME[s.tier]}」`, medal: { tier: s.tier, got: stars >= s.n }, tag: stars >= s.n ? '已获得' : '', lines: [s.title ? `称号「${TITLE_BY_ID.get(s.title)?.name}」` : '挂在勋章墙「勋带」页'], state: stars >= s.n ? 'done' : 'off' })),
  ];
  return { id: 'rank-c', label: '将星', head: marshal ? `元帅 ★${stars} · 军票 ${fmtInt(c.e.ticket)}` : '升到元帅开启', sections: [{ title: '将星只加不减', rows }] };
}

/** 战区页（威胁 0～5 / 6～10 两页）：每级新增的敌方强化、奖励、打通没有；点一行选这一级 */
export function threatPages(c: Career): RoutePage[] {
  const cur = c.threat;
  const max = c.threatMax;
  const row = (lv: number): RouteRow => {
    const open = lv <= Math.max(0, max);
    const done = lv === 0 || c.e.threatClear.includes(lv);
    const prize = lv === 0 ? '军功 / 军票照常' : `军功 / 军票 +${lv * 10}% · 第一次打掉轰天 军票 ${fmtInt(THREAT_PRIZE.ticket * lv)}${lv === 5 ? ' + 称号「虎胆先锋」' : lv === 10 ? ' + 称号「钢铁意志」+ 涂装「战区黑金」' : ''}`;
    return {
      icon: 'threat',
      title: lv === 0 ? '威胁 0 · 常规' : `威胁 ${lv}`,
      tag: lv === cur ? '已选' : !open ? `${lv - 1} 级打通开放` : done && lv ? '已打通' : '可选',
      lines: [lv === 0 ? '敌人不加强' : `新增：${THREAT[lv - 1]}`, prize],
      state: lv === cur ? 'now' : !open ? 'off' : done ? 'done' : 'next',
      tap: open ? `thr:${lv}` : undefined,
    };
  };
  const head = `已选威胁 ${cur} · 点一行换`;
  return [
    { id: 'thr', label: '威胁 0～5', head, sections: [{ title: '每级多一条', rows: [0, 1, 2, 3, 4, 5].map(row) }] },
    { id: 'thr-b', label: '威胁 6～10', head, sections: [{ title: '每级多一条', rows: [6, 7, 8, 9, 10].map(row) }] },
  ];
}

// ------------------------------------------------------------------ 装配车间（T033）

/**
 * 装配车间一页（一屏放完）：装配板（局内左上槽位条的放大版：开着的空槽 / 锁着的盖板 + 哪一级开）、5 行解锁路线（下一个带进度条）；「槽位怎么用」T049 起挪进图鉴「玩法 · 成长」。
 * core = 开始界面选中的流派（核心格画它）；fresh = 这次打开时刚装上、还没看过的（金边 +「新」）
 */
export function bayPages(c: Career, merit: number, core: CoreId, fresh: readonly string[], sixOpen = false): RoutePage[] {
  if (sixOpen) return [{
    id: 'bay', label: '武器槽', head: '六个挂位已开放',
    sections: [
      { title: '装配板', rows: [], bay: { core: `core-${core}`, coreName: CORES[core].name, weapon: Array.from({ length: WEAPON_SLOTS }, () => ({ on: true })), head: '副武器槽 6 / 6', caption: '同型号也能同时装备' } },
      { title: '挂位对应', rows: [{ icon: 'slot-w', title: '车头朝上', lines: ['上排：左前、右前', '中排：左肩、右肩', '下排：左后、右后', '暂停或选卡时可整理，不消耗选卡'], state: 'done' }] },
    ],
  }];
  const s = c.slots();
  const rank = c.rank();
  const next = c.nextBay();
  const cells = (kind: BayKind): BayCell[] =>
    Array.from({ length: WEAPON_SLOTS }, (_, i) => {
      const b = BAY.find((x) => x.kind === kind && x.n === i + 1);
      if (!b || i < BAY_BASE[kind]) return { on: true };
      return c.hasBay(b.id) ? { on: true, fresh: fresh.includes(b.id) } : { on: false, label: RANKS[b.rank - 1] };
    });
  const board: BayView = {
    core: `core-${core}`,
    coreName: CORES[core].name,
    weapon: cells('weapon'),
    head: `副武器槽 ${s.weapon} / ${WEAPON_SLOTS}`,
    caption: next ? `一局最多装 ${s.weapon} 件副武器` : `满配：一局装得下 ${WEAPON_SLOTS} 件副武器`,
  };
  const rows = BAY.map((b): RouteRow => {
    const own = c.hasBay(b.id);
    const need = meritFor(b.rank);
    const what = `一局最多装 ${b.n} 件副武器`;
    return {
      icon: 'slot-w',
      title: `${BAY_NAME[b.kind]} · 第 ${b.n} 个`,
      tag: own ? (fresh.includes(b.id) ? '新装上' : '已装配') : `${RANKS[b.rank - 1]}装上`,
      // 一屏放完：只有下一个（带进度条）和刚装上的写一行说明，其余一行标题 + 哪一级
      lines: b === next ? [`升到「${RANKS[b.rank - 1]}」自动装上`] : own && fresh.includes(b.id) ? [`${what} · 下一局就能用`] : [],
      state: own ? (fresh.includes(b.id) ? 'now' : 'done') : b === next ? 'next' : 'off',
      bar: b === next ? { p: merit / need, text: `还差 ${fmtInt(need - merit)} 军功` } : undefined,
    };
  });
  return [
    {
      id: 'bay',
      label: '装配车间',
      head: next ? `${rank.name} · 累计军功 ${fmtInt(merit)}` : `${rank.name} · 槽位全开`,
      sections: [
        { title: '装配板', rows: [], bay: board },
        { title: '升军衔自动装上（只认军功）', rows },
      ],
    },
  ];
}
