/** 联机调试数据：地址带 ?netdebug=1 时显示面板，脚本从 window.__NET__ 读。 */
export const NET_DEBUG = !__WX__ && typeof location !== 'undefined' && new URLSearchParams(location.search).has('netdebug');

interface Window1 { at: number; frames: number; frameMax: number; work: number; workMax: number; rxBytes: number; rxMsgs: number; txBytes: number; txMsgs: number; states: number; gaps: number; gapSum: number; gapMax: number; sizeSum: number; sizeMax: number; behind: number; dropped: number; fix: number }
const blank = (at: number): Window1 => ({ at, frames: 0, frameMax: 0, work: 0, workMax: 0, rxBytes: 0, rxMsgs: 0, txBytes: 0, txMsgs: 0, states: 0, gaps: 0, gapSum: 0, gapMax: 0, sizeSum: 0, sizeMax: 0, behind: 0, dropped: 0, fix: 0 });
const avg = (list: number[]): number => list.length ? list.reduce((a, b) => a + b, 0) / list.length : 0;

export interface NetReport {
  role: string; fps: number; frameMax: number; work: number; workMax: number;
  stateHz: number; gapAvg: number; gapMax: number; sizeAvg: number; sizeMax: number;
  rxKBs: number; txKBs: number; rxMsgs: number; txMsgs: number; behind: number; dropped: number; fix: number;
  rtt: number; rttMax: number; inputLag: number; inputLagMax: number; buffer: number; keys: number; top: string;
}

export class NetStats {
  role = '房主';
  /** 上一秒的汇总；面板和脚本都读它。 */
  report: NetReport | null = null;
  /** 插值缓冲：等着播的快照数和对应毫秒。 */
  buffer = 0;
  /** 快照里的条目数，和按前缀分的字节（房主）。 */
  keys = 0;
  top = '';
  private w = blank(performance.now());
  private lastState = 0;
  private rtts: number[] = [];
  private lags: number[] = [];
  private inputSent = new Map<number, number>();
  private panel: HTMLDivElement | null = null;
  frame(dt: number, workMs: number): void {
    const w = this.w;
    w.frames++; w.frameMax = Math.max(w.frameMax, dt * 1000);
    w.work += workMs; w.workMax = Math.max(w.workMax, workMs);
    const now = performance.now();
    if (now - w.at >= 1000) this.roll(now);
  }
  tx(bytes: number): void { this.w.txBytes += bytes; this.w.txMsgs++; }
  rx(bytes: number): void { this.w.rxBytes += bytes; this.w.rxMsgs++; }
  /** 房主：这包的基线落后几包（1 = 每包都基于上一包）。 */
  behind(n: number): void { this.w.behind = Math.max(this.w.behind, n); }
  /** 队友：收到但拼不出来、或比已显示旧的包。 */
  dropped(): void { this.w.dropped++; }
  /** 队友：本车预测被房主纠正的距离（米），取一秒内最大。 */
  fix(m: number): void { this.w.fix = Math.max(this.w.fix, m); }
  /** 收到（或发出）一个新状态包。 */
  state(bytes: number): void {
    const now = performance.now(), w = this.w;
    if (this.lastState) { const gap = now - this.lastState; w.gaps++; w.gapSum += gap; w.gapMax = Math.max(w.gapMax, gap); }
    this.lastState = now;
    w.states++; w.sizeSum += bytes; w.sizeMax = Math.max(w.sizeMax, bytes);
  }
  rtt(ms: number): void { this.rtts.push(ms); if (this.rtts.length > 20) this.rtts.shift(); }
  inputOut(seq: number): void {
    this.inputSent.set(seq, performance.now());
    if (this.inputSent.size > 200) this.inputSent.delete(this.inputSent.keys().next().value!);
  }
  /** 房主回报已用到第几号输入：从发出到看见确认的时间。 */
  inputAck(seq: number): void {
    const at = this.inputSent.get(seq);
    if (at === undefined) return;
    for (const key of this.inputSent.keys()) { if (key > seq) break; this.inputSent.delete(key); }
    this.lags.push(performance.now() - at); if (this.lags.length > 30) this.lags.shift();
  }
  private roll(now: number): void {
    const w = this.w, sec = (now - w.at) / 1000;
    this.report = {
      role: this.role, fps: w.frames / sec, frameMax: w.frameMax, work: w.frames ? w.work / w.frames : 0, workMax: w.workMax,
      stateHz: w.states / sec, gapAvg: w.gaps ? w.gapSum / w.gaps : 0, gapMax: w.gapMax,
      sizeAvg: w.states ? w.sizeSum / w.states : 0, sizeMax: w.sizeMax,
      rxKBs: w.rxBytes / 1024 / sec, txKBs: w.txBytes / 1024 / sec, rxMsgs: w.rxMsgs / sec, txMsgs: w.txMsgs / sec, behind: w.behind, dropped: w.dropped, fix: w.fix,
      rtt: avg(this.rtts), rttMax: Math.max(0, ...this.rtts), inputLag: avg(this.lags), inputLagMax: Math.max(0, ...this.lags),
      buffer: this.buffer, keys: this.keys, top: this.top,
    };
    this.w = blank(now);
    (window as { __NET__?: NetReport }).__NET__ = this.report;
    if (NET_DEBUG) this.draw();
  }
  private draw(): void {
    const r = this.report!;
    if (!this.panel) {
      this.panel = document.createElement('div');
      this.panel.style.cssText = 'position:fixed;left:4px;top:4px;z-index:99999;pointer-events:none;background:rgba(0,0,0,.72);color:#e8f0c8;font:11px/1.35 monospace;padding:4px 6px;white-space:pre;border-radius:3px';
      document.body.appendChild(this.panel);
    }
    const f = (v: number, d = 0): string => v.toFixed(d);
    this.panel.textContent = [
      `联机调试 · ${r.role}`,
      `帧率 ${f(r.fps)}  最长帧 ${f(r.frameMax)}毫秒`,
      `每帧耗时 ${f(r.work, 1)} / 最长 ${f(r.workMax, 1)}毫秒`,
      `状态 ${f(r.stateHz, 1)}次每秒  间隔 ${f(r.gapAvg)} / 最长 ${f(r.gapMax)}毫秒`,
      `每包 ${f(r.sizeAvg / 1024, 1)} / 最大 ${f(r.sizeMax / 1024, 1)}千字节  条目 ${r.keys}`,
      `收 ${f(r.rxKBs, 1)}千字节每秒 ${f(r.rxMsgs)}条  发 ${f(r.txKBs, 1)}千字节每秒 ${f(r.txMsgs)}条`,
      `往返 ${f(r.rtt)} / 最长 ${f(r.rttMax)}毫秒  基线落后 ${r.behind}包  弃包 ${r.dropped}`,
      `输入到确认 ${f(r.inputLag)} / 最长 ${f(r.inputLagMax)}毫秒`,
      `插值缓冲 ${f(r.buffer)}毫秒  预测纠正 ${f(r.fix, 2)}米`,
      r.top ? `大头 ${r.top}` : '',
    ].filter(Boolean).join('\n');
  }
  dispose(): void { this.panel?.remove(); this.panel = null; }
}
