const TAU = Math.PI * 2;
const reducedMotion = () => typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches;
const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));

/** 整备窗角上的操作提示：鼠标给滚轮，触屏给双指 */
export function orbitHint(): string {
  const fine = typeof matchMedia === 'function' && matchMedia('(hover: hover) and (pointer: fine)').matches;
  return `拖动环视 · ${fine ? '滚轮' : '双指'}缩放 · 双击复位`;
}

/** 相对默认机位：yaw = 绕车水平转角，pitch = 仰角增量（弧度），zoom = 距离倍数。 */
export interface OrbitPose {
  yaw: number;
  pitch: number;
  zoom: number;
}

export const ORBIT = {
  /** 仰角增量范围：默认约 20.9°，可压到约 4° 贴地、抬到约 71° 俯看 */
  pitchMin: -0.29,
  pitchMax: 0.88,
  zoomMin: 0.62,
  zoomMax: 2.1,
  /** 横拖一个整备窗宽 ≈ 转 200° */
  yawPerWidth: Math.PI * 1.1,
  pitchPerHeight: 0.9,
  /** 无操作多久后恢复慢转（秒），慢转速度与原转台一样 */
  idle: 8,
  auto: Math.PI / 24,
} as const;

/**
 * T183：开始页整备台的 360° 环视。两套开始页与手柄共用：单指 / 鼠标拖动转视角（带惯性），双指张合 / 滚轮缩放，
 * 双击复位；无操作一段时间后镜头恢复慢转。只记目标姿态，渲染端自己缓动。
 */
export class StageOrbit implements OrbitPose {
  yaw = 0;
  pitch = 0;
  zoom = 1;
  private spin = 0;
  private touched = -Infinity;
  private last = 0;
  private lastTap = 0;
  private pinch = 0;
  private w = 360;
  private h = 300;
  private readonly hands = new Map<number, { x: number; y: number; x0: number; y0: number; t: number; pinched: boolean }>();

  get dragging(): boolean { return this.hands.size > 0; }

  /** 返回本帧目标姿态；stage = 整备窗尺寸（逻辑像素），决定拖动灵敏度。 */
  tick(w: number, h: number, now = performance.now()): OrbitPose {
    this.w = Math.max(200, w);
    this.h = Math.max(160, h);
    const dt = this.last ? Math.min(0.05, Math.max(0, (now - this.last) / 1000)) : 0;
    this.last = now;
    if (!this.dragging) {
      if (this.spin) {
        this.yaw += this.spin * dt;
        this.spin *= Math.exp(-dt * 3.2);
        if (Math.abs(this.spin) < 0.03) this.spin = 0;
      } else if (now - this.touched > ORBIT.idle * 1000 && !reducedMotion()) this.yaw += dt * ORBIT.auto;
    }
    return this;
  }

  begin(id: number, x: number, y: number, now = performance.now()): boolean {
    if (this.hands.has(id) || this.hands.size >= 2) return false;
    for (const h of this.hands.values()) h.pinched = true;
    this.hands.set(id, { x, y, x0: x, y0: y, t: now, pinched: this.hands.size > 0 });
    this.pinch = this.hands.size === 2 ? this.spread() : 0;
    this.spin = 0;
    this.touched = now;
    return true;
  }

  move(id: number, x: number, y: number, now = performance.now()): void {
    const h = this.hands.get(id);
    if (!h) return;
    const dx = x - h.x, dy = y - h.y;
    const dt = Math.max(0.001, (now - h.t) / 1000);
    h.x = x; h.y = y; h.t = now;
    this.touched = now;
    if (this.hands.size === 2) {
      const d = this.spread();
      if (this.pinch > 0 && d > 0) this.zoom = clamp(this.zoom * this.pinch / d, ORBIT.zoomMin, ORBIT.zoomMax);
      this.pinch = d;
      return;
    }
    if (h.pinched) return;
    const turn = -dx / this.w * ORBIT.yawPerWidth;
    this.yaw += turn;
    this.pitch = clamp(this.pitch + dy / this.h * ORBIT.pitchPerHeight, ORBIT.pitchMin, ORBIT.pitchMax);
    // 松手惯性取最近几帧的平均角速度
    this.spin = this.spin * 0.6 + turn / dt * 0.4;
  }

  /** 返回这次按下是否算拖动 / 张合（算的话不再当点按）。 */
  end(id: number, x: number, y: number, now = performance.now()): boolean {
    const h = this.hands.get(id);
    if (!h) return true;
    const stale = now - h.t > 90;
    if (x !== h.x || y !== h.y) this.move(id, x, y, now);
    this.hands.delete(id);
    this.pinch = 0;
    this.touched = now;
    const moved = h.pinched || Math.hypot(x - h.x0, y - h.y0) > 10;
    if (h.pinched || stale) this.spin = 0;
    this.spin = clamp(this.spin, -6, 6);
    if (!moved) {
      this.spin = 0;
      if (now - this.lastTap < 320) {
        this.reset();
        this.lastTap = 0;
      } else this.lastTap = now;
    }
    return moved;
  }

  cancel(id?: number): void {
    if (id === undefined) this.hands.clear();
    else if (!this.hands.delete(id)) return;
    this.pinch = 0;
    this.spin = 0;
  }

  wheel(deltaY: number, now = performance.now()): void {
    this.zoom = clamp(this.zoom * Math.exp(clamp(deltaY, -240, 240) * 0.0015), ORBIT.zoomMin, ORBIT.zoomMax);
    this.touched = now;
  }

  /** 手柄右摇杆：x / y 为 -1～1。 */
  stick(x: number, y: number, dt: number, now = performance.now()): void {
    if (!x && !y) return;
    this.yaw -= x * dt * 2.4;
    this.pitch = clamp(this.pitch - y * dt * 1.2, ORBIT.pitchMin, ORBIT.pitchMax);
    this.spin = 0;
    this.touched = now;
  }

  /** 回到默认机位：转角取最近的整圈，镜头走最短路回去。 */
  reset(now = performance.now()): void {
    this.yaw = Math.round(this.yaw / TAU) * TAU;
    this.pitch = 0;
    this.zoom = 1;
    this.spin = 0;
    this.touched = now;
  }

  private spread(): number {
    const [a, b] = [...this.hands.values()];
    return a && b ? Math.hypot(a.x - b.x, a.y - b.y) : 0;
  }
}
