import { BGM_VOL_MAX, type BgmId, type BgmPick } from './bgmList';

/**
 * 背景音乐（T206）：五首曲子全部程序合成（鼓 / 贝斯 / 铺底和弦 / 主旋律 / 琶音），0 字节素材，小游戏包不变大。
 * T210 再加四首红色进行曲系列（合唱 / 铜管 / 手风琴 / 军靴 / 定音鼓 / 失真吉他，同样程序合成），老五首不变。
 * 自己一条总线直通扬声器，不过音效的总音量：音效「关」不影响音乐，音乐「关」也不碰音效。
 * 调度：每 60 毫秒往前排 0.3 秒的十六分音符；音乐关掉 / 音量 0 时停掉调度，不占 CPU。
 * 原则同音效：出任何错只会没声音。
 */
export type MusicScene = 'title' | 'battle' | 'boss';

interface Song {
  bpm: number;
  /** 贝斯所在八度的主音（MIDI） */
  root: number;
  scale: number[];
  /** 每小节一个和弦：音阶级数（三和弦按 d / d+2 / d+4 叠） */
  chords: number[];
  /** 16 步一小节：x = 打；s 行 X = 重音 */
  kick: string;
  snare: string;
  hat: string;
  tom?: string;
  /** 每 4 小节的最后一小节换这条军鼓（过门） */
  fill?: string;
  /** r 根音 / f 五度 / o 高八度 / . 休止 */
  bass: string;
  /** 主旋律每小节 16 字：. 休止、- 延音、0-9a-k = 音阶级数（以主音高一个八度起算，7 = 再高八度的主音） */
  lead: string[];
  wave: OscillatorType;
  /** 主旋律滤波截止频率 */
  bright: number;
  pad: number;
  arp?: boolean;
  hatGain?: number;
  /* —— 以下是 T210 红色进行曲系列加的，老五首都不设，出声和原来一样 —— */
  /** 新编排：和弦 / 旋律 / 过门都从前奏后第 0 小节数起，旋律不再每 16 小节歇 4 小节（休止直接写进旋律）；军鼓 r = 双击滚奏 */
  form?: boolean;
  /** 主旋律音色：brass 铜管齐奏 / reed 手风琴簧片 */
  voice?: 'brass' | 'reed';
  /** 主旋律下面再叠低八度 */
  leadOct?: boolean;
  /** 铜管二声部：旋律下面补一个当前和弦的音 */
  harm?: boolean;
  /** 反拍短和弦（嘭-恰的「恰」），x = 打，音色跟 voice */
  stab?: string;
  /** 男声合唱铺底（「啊」元音），数值 = 音量 */
  choir?: number;
  /** 军靴踏步 */
  stomp?: string;
  /** 失真强力和弦，每小节一条轮换：x 闷音 / X 重音 */
  riff?: string[];
  /** 定音鼓：r 根音 / f 五度 */
  timp?: string;
  /** 琶音改成轮指：每个十六分音符都拨 */
  trem?: boolean;
}

