/** 自动：作战按区域轮换这三首 */
const BATTLE_ROTATION: BgmId[] = ['drive', 'scorch', 'night'];
/** 红色 · 自动：作战按区域轮换 */
const RED_ROTATION: BgmId[] = ['hellfire', 'bayan', 'redflag'];

const hz = (m: number) => 440 * 2 ** ((m - 69) / 12);

export class Music {
  private ctx: AudioContext | null = null;
  private main: GainNode | null = null;
  private noise: AudioBuffer | null = null;
  private on = true;
  private vol = 5;
  private pick: BgmPick = 'auto';
  private sceneNow: MusicScene = 'title';
  private zone = 1;
  /** 正在放的曲子和它自己的一路增益（换曲时旧的一路淡出） */
  private cur: { id: BgmId; song: Song; out: GainNode; echo: GainNode; delay: DelayNode; step: number; next: number; drive?: AudioNode } | null = null;
  private timer: ReturnType<typeof setInterval> | null = null;

  /** 音频上下文建好以后接上（AudioSystem.setup） */
  attach(ctx: AudioContext): void {
    try {
      this.ctx = ctx;
      const comp = ctx.createDynamicsCompressor();
      comp.threshold.value = -18;
      comp.knee.value = 8;
      comp.ratio.value = 4;
      comp.attack.value = 0.005;
      comp.release.value = 0.3;
      this.main = ctx.createGain();
      this.main.gain.value = this.level();
      comp.connect(this.main).connect(ctx.destination);
      this.bus = comp;
      const len = ctx.sampleRate;
      this.noise = ctx.createBuffer(1, len, ctx.sampleRate);
      const d = this.noise.getChannelData(0);
      for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
      this.sync();
    } catch {
      this.ctx = null;
    }
  }

  private bus: AudioNode | null = null;

  /** 设置页「音乐」里正在试听的曲子（T216）：盖过所选曲目和总开关，音量照用设置里的 */
  private listen: BgmId | null = null;

  preview(id: BgmId | null): void {
    this.listen = id;
    this.sync();
  }

  configure(on: boolean, vol: number, pick: BgmPick): void {
    this.on = on;
    this.vol = Math.max(0, Math.min(BGM_VOL_MAX, Math.round(vol)));
    this.pick = pick;
    this.sync();
  }

  scene(scene: MusicScene, zone: number): void {
    if (scene === this.sceneNow && zone === this.zone) return;
    this.sceneNow = scene;
    this.zone = zone;
    this.sync();
  }

  /** 调试读数：放的哪首 / 场景 / 目标音量 / 已排步数 / 上下文状态 */
  state(): { track: BgmId | null; listen: BgmId | null; scene: MusicScene; level: number; steps: number; ctx: string; timer: boolean } {
    return { track: this.cur?.id ?? null, listen: this.listen, scene: this.sceneNow, level: Math.round(this.level() * 1000) / 1000, steps: this.cur?.step ?? 0, ctx: this.ctx?.state ?? 'none', timer: !!this.timer };
  }

  /** 现在该放哪首 */
  private want(): BgmId | null {
    if (this.vol <= 0) return null;
    if (this.listen) return this.listen;
    if (!this.on) return null;
    if (this.pick !== 'auto' && this.pick !== 'autoRed') return this.pick;
    const red = this.pick === 'autoRed';
    if (this.sceneNow === 'title') return red ? 'redflag' : 'march';
    if (this.sceneNow === 'boss') return red ? 'redstorm' : 'boss';
    const rot = red ? RED_ROTATION : BATTLE_ROTATION;
    return rot[(Math.max(1, this.zone) - 1) % rot.length];
  }

  /** 音量曲线：10 档按 1.6 次方，满档 0.55（音效总线 0.8 × 压限后的响度，音乐垫在下面） */
  private level(): number {
    return this.on || this.listen ? (this.vol / BGM_VOL_MAX) ** 1.6 * 0.55 : 0;
  }

  private sync(): void {
    const ctx = this.ctx;
    if (!ctx || !this.main || !this.bus) return;
    try {
      this.main.gain.setTargetAtTime(this.level(), ctx.currentTime, 0.08);
      const id = this.want();
      if (id === (this.cur?.id ?? null)) return;
      this.fadeOut();
      if (id) {
        const song = SONGS[id];
        const out = ctx.createGain();
        out.gain.setValueAtTime(0, ctx.currentTime);
        out.gain.linearRampToValueAtTime(1, ctx.currentTime + 1.2);
        out.connect(this.bus);
        // 主旋律的附点八分回声
        const delay = ctx.createDelay(1);
        delay.delayTime.value = (60 / song.bpm) * 0.75;
        const fb = ctx.createGain();
        fb.gain.value = 0.28;
        const echo = ctx.createGain();
        echo.gain.value = 0.35;
        echo.connect(delay).connect(fb).connect(delay);
        delay.connect(out);
        this.cur = { id, song, out, echo, delay, step: 0, next: ctx.currentTime + 0.1 };
        this.timer ??= setInterval(() => this.tick(), 60);
      } else if (this.timer) {
        clearInterval(this.timer);
        this.timer = null;
      }
    } catch {
      /* 没声音照样玩 */
    }
  }

  private fadeOut(): void {
    const old = this.cur;
    this.cur = null;
    if (!old || !this.ctx) return;
    const t = this.ctx.currentTime;
    old.out.gain.cancelScheduledValues(t);
    old.out.gain.setValueAtTime(old.out.gain.value, t);
    old.out.gain.linearRampToValueAtTime(0, t + 0.8);
    setTimeout(() => {
      old.out.disconnect();
      old.delay.disconnect();
    }, 3000);
  }

  private tick(): void {
    const ctx = this.ctx;
    const c = this.cur;
    if (!ctx || !c || ctx.state !== 'running') return;
    try {
      const sd = 60 / c.song.bpm / 4;
      // 切后台回来：不补放落下的音符
      if (c.next < ctx.currentTime) c.next = ctx.currentTime + 0.05;
      while (c.next < ctx.currentTime + 0.3) {
        this.playStep(c, c.step, c.next, sd);
        c.step++;
        c.next += sd;
      }
    } catch {
      /* 没声音照样玩 */
    }
  }

  private playStep(c: NonNullable<Music['cur']>, step: number, t: number, sd: number): void {
    const s = c.song;
    const i = step % 16;
    const bar = Math.floor(step / 16);
    const intro = bar < 2;
    // 新编排从前奏后数小节（老五首 pos = bar，和原来一样）
    const pos = s.form ? Math.max(0, bar - 2) : bar;
    const chord = s.chords[pos % s.chords.length];
    const deg = (d: number) => s.root + 12 * Math.floor(d / 7) + s.scale[d % 7];
    const out = c.out;
    const tones = [chord, chord + 2, chord + 4];
    // 鼓：开头两小节只有踩镲
    const fillBar = !!s.fill && pos % 4 === 3;
    const sn = (fillBar ? s.fill! : s.snare)[i];
    if (!intro) {
      if (s.kick[i] === 'x') this.kick(t, out);
      if (sn === 'x' || sn === 'X') this.snare(t, out, sn === 'X' ? 1 : 0.45);
      if (sn === 'r') {
        this.snare(t, out, 0.38);
        this.snare(t + sd / 2, out, 0.3);
      }
      if (s.tom?.[i] === 'x') this.tom(t, out, i % 2 ? 0.8 : 1);
      const tp = s.timp?.[i];
      if (tp === 'r' || tp === 'f') this.timp(t, out, hz(deg(tp === 'f' ? chord + 4 : chord) - (tp === 'f' ? 12 : 0)));
      const rf = s.riff?.[pos % s.riff.length][i];
      if (rf === 'x' || rf === 'X') this.riff(t, c, hz(deg(chord)), rf === 'X' ? sd * 2.6 : sd * 0.75, rf === 'X' ? 1 : 0.7);
    }
    // 军靴：前奏里就踏
    if (s.stomp?.[i] === 'x') this.stomp(t, out, i % 8 === 0 ? 1 : 0.8);
    if (s.hat[i] === 'x') this.hat(t, out, (s.hatGain ?? 1) * (i % 4 === 0 ? 1 : 0.6));
    // 贝斯
    const b = s.bass[i];
    if (b !== '.' && b !== undefined) this.bass(t, out, hz(deg(chord) + (b === 'o' ? 12 : 0) + (b === 'f' ? deg(chord + 4) - deg(chord) : 0)), sd * 1.6);
    // 铺底和弦：每小节第一拍起一次
    if (i === 0 && s.pad > 0) this.pad(t, out, tones.map((d) => hz(deg(d) + 12)), sd * 16, s.pad);
    if (i === 0 && s.choir) this.choir(t, out, tones.map((d) => hz(deg(d) + 12)), sd * 16, s.choir);
    // 反拍短和弦
    if (s.stab?.[i] === 'x') this.stab(t, c, tones.map((d) => hz(deg(d) + 12)), sd * 1.5);
    // 琶音：和弦音十六分音符往上爬（轮指：每个十六分都拨，轻重交替，前奏就进）
    if (s.arp && (!intro || s.trem) && (s.trem || i % 2 === 0)) this.pluck(t, out, hz(deg(chord + [0, 2, 4, 7][Math.floor(i / 2) % 4]) + 24), s.trem ? (i % 2 ? 0.055 : 0.08) : 0.05);
    // 主旋律：开头两小节不进；老五首每 16 小节最后 4 小节歇一下
    if (intro || (!s.form && bar % 16 >= 12)) return;
    const line = s.lead[(bar - 2) % s.lead.length];
    const ch = line[i];
    if (ch === '.' || ch === '-') return;
    let len = 1;
    while (i + len < 16 && line[i + len] === '-') len++;
    const m = deg(parseInt(ch, 36)) + 12;
    this.lead(t, c, hz(m), sd * len);
    // 二声部：旋律下方至少小三度的和弦音里取最高的
    if (s.harm) {
      let h = -1;
      for (const d of tones) for (let o = -2; o <= 3; o++) {
        const p = deg(d) + 12 * o;
        if (p <= m - 3 && p > h) h = p;
      }
      if (h > 0) this.voiceLead(t, c, hz(h), sd * len, 0.55, false);
    }
  }

  private env(g: GainNode, t: number, peak: number, attack: number, dur: number): void {
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(peak, t + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  }

  private kick(t: number, out: AudioNode): void {
    const ctx = this.ctx!;
    const o = ctx.createOscillator();
    o.frequency.setValueAtTime(140, t);
    o.frequency.exponentialRampToValueAtTime(42, t + 0.12);
    const g = ctx.createGain();
    this.env(g, t, 0.85, 0.003, 0.34);
    o.connect(g).connect(out);
    o.start(t);
    o.stop(t + 0.36);
  }

  private noiseHit(t: number, out: AudioNode, type: BiquadFilterType, f: number, q: number, peak: number, dur: number): void {
    const ctx = this.ctx!;
    const src = ctx.createBufferSource();
    src.buffer = this.noise;
    const flt = ctx.createBiquadFilter();
    flt.type = type;
    flt.frequency.value = f;
    flt.Q.value = q;
    const g = ctx.createGain();
    this.env(g, t, peak, 0.002, dur);
    src.connect(flt).connect(g).connect(out);
    src.start(t, Math.random() * 0.8, dur + 0.02);
  }

  private snare(t: number, out: AudioNode, k: number): void {
    this.noiseHit(t, out, 'bandpass', 1800, 0.7, 0.55 * k, 0.17);
    const ctx = this.ctx!;
    const o = ctx.createOscillator();
    o.type = 'triangle';
    o.frequency.setValueAtTime(200, t);
    o.frequency.exponentialRampToValueAtTime(150, t + 0.08);
    const g = ctx.createGain();
    this.env(g, t, 0.28 * k, 0.002, 0.09);
    o.connect(g).connect(out);
    o.start(t);
    o.stop(t + 0.1);
  }

  private hat(t: number, out: AudioNode, k: number): void {
    this.noiseHit(t, out, 'highpass', 7500, 0.8, 0.13 * k, 0.04);
  }

  private tom(t: number, out: AudioNode, k: number): void {
    const ctx = this.ctx!;
    const o = ctx.createOscillator();
    o.frequency.setValueAtTime(130 * k, t);
    o.frequency.exponentialRampToValueAtTime(70 * k, t + 0.2);
    const g = ctx.createGain();
    this.env(g, t, 0.5, 0.003, 0.28);
    o.connect(g).connect(out);
    o.start(t);
    o.stop(t + 0.3);
  }

  private bass(t: number, out: AudioNode, f: number, dur: number): void {
    const ctx = this.ctx!;
    const o = ctx.createOscillator();
    o.type = 'sawtooth';
    o.frequency.value = f;
    const flt = ctx.createBiquadFilter();
    flt.type = 'lowpass';
    flt.Q.value = 3;
    flt.frequency.setValueAtTime(900, t);
    flt.frequency.exponentialRampToValueAtTime(220, t + dur);
    const g = ctx.createGain();
    this.env(g, t, 0.3, 0.006, dur);
    o.connect(flt).connect(g).connect(out);
    o.start(t);
    o.stop(t + dur + 0.02);
  }

  private pad(t: number, out: AudioNode, fs: number[], dur: number, k: number): void {
    const ctx = this.ctx!;
    const flt = ctx.createBiquadFilter();
    flt.type = 'lowpass';
    flt.frequency.value = 1100;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(0.05 * k, t + Math.min(0.5, dur * 0.25));
    g.gain.setValueAtTime(0.05 * k, t + dur * 0.8);
    g.gain.linearRampToValueAtTime(0.0001, t + dur + 0.15);
    flt.connect(g).connect(out);
    for (const f of fs) {
      for (const cents of [-8, 8]) {
        const o = ctx.createOscillator();
        o.type = 'sawtooth';
        o.frequency.value = f;
        o.detune.value = cents;
        o.connect(flt);
        o.start(t);
        o.stop(t + dur + 0.2);
      }
    }
  }

  private pluck(t: number, out: AudioNode, f: number, peak: number): void {
    const ctx = this.ctx!;
    const o = ctx.createOscillator();
    o.type = 'triangle';
    o.frequency.value = f;
    const g = ctx.createGain();
    this.env(g, t, peak, 0.003, 0.16);
    o.connect(g).connect(out);
    o.start(t);
    o.stop(t + 0.18);
  }

  private lead(t: number, c: NonNullable<Music['cur']>, f: number, dur: number): void {
    const ctx = this.ctx!;
    const s = c.song;
    if (s.voice) return this.voiceLead(t, c, f, dur, 1, !!s.leadOct);
    const o = ctx.createOscillator();
    o.type = s.wave;
    o.frequency.value = f;
    // 长音带一点颤音
    if (dur > 0.4) {
      const lfo = ctx.createOscillator();
      lfo.frequency.value = 5.5;
      const lg = ctx.createGain();
      lg.gain.setValueAtTime(0, t);
      lg.gain.linearRampToValueAtTime(f * 0.006, t + dur);
      lfo.connect(lg).connect(o.frequency);
      lfo.start(t);
      lfo.stop(t + dur + 0.1);
    }
    const flt = ctx.createBiquadFilter();
    flt.type = 'lowpass';
    flt.frequency.value = s.bright;
    flt.Q.value = 1;
    const g = ctx.createGain();
    const peak = s.wave === 'triangle' ? 0.16 : s.wave === 'square' ? 0.07 : 0.085;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(peak, t + 0.012);
    g.gain.setValueAtTime(peak * 0.8, t + Math.max(0.02, dur - 0.04));
    g.gain.linearRampToValueAtTime(0.0001, t + dur + 0.06);
    o.connect(flt).connect(g);
    g.connect(c.out);
    g.connect(c.echo);
    o.start(t);
    o.stop(t + dur + 0.1);
  }

  /* —— T210 红色进行曲系列的乐器 —— */

  /** 铜管齐奏 / 手风琴簧片的旋律音：k = 音量倍数，oct = 下面叠低八度 */
  private voiceLead(t: number, c: NonNullable<Music['cur']>, f: number, dur: number, k: number, oct: boolean): void {
    const ctx = this.ctx!;
    const s = c.song;
    const reed = s.voice === 'reed';
    const end = t + dur + 0.12;
    const flt = ctx.createBiquadFilter();
    flt.type = 'lowpass';
    if (reed) {
      flt.frequency.value = s.bright;
      flt.Q.value = 0.7;
    } else {
      // 铜管：起音时滤波从闷到亮，再回落一点
      flt.Q.value = 2;
      flt.frequency.setValueAtTime(320, t);
      flt.frequency.exponentialRampToValueAtTime(s.bright, t + 0.07);
      flt.frequency.setTargetAtTime(s.bright * 0.62, t + 0.08, 0.25);
    }
    const g = ctx.createGain();
    const peak = (reed ? 0.08 : 0.05) * k;
    const att = reed ? 0.015 : 0.03;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(peak, t + att);
    g.gain.setValueAtTime(peak * 0.85, t + Math.max(att + 0.01, dur - 0.04));
    g.gain.linearRampToValueAtTime(0.0001, t + dur + 0.08);
    // 长音颤音（音分）；手风琴另加风箱的音量抖动
    const lfo = ctx.createOscillator();
    lfo.frequency.value = reed ? 6.2 : 5.2;
    const vib = ctx.createGain();
    vib.gain.setValueAtTime(0, t);
    vib.gain.linearRampToValueAtTime(dur > 0.4 ? 14 : 4, t + Math.max(0.05, dur));
    lfo.connect(vib);
    let tail: AudioNode = g;
    if (reed) {
      const trem = ctx.createGain();
      trem.gain.value = 1;
      const tg = ctx.createGain();
      tg.gain.value = 0.12;
      lfo.connect(tg).connect(trem.gain);
      g.connect(trem);
      tail = trem;
    }
    // 手风琴三片簧（中、偏低、偏高）；铜管两支微失谐 + 起音往上滑
    const voices: [OscillatorType, number, number, number][] = reed
      ? [['sawtooth', 1, -11, 0.6], ['square', 1, 0, 0.5], ['sawtooth', 1, 11, 0.6]]
      : [['sawtooth', 1, -7, 1], ['sawtooth', 1, 7, 1]];
    if (oct) voices.push(['sawtooth', 0.5, 0, 0.7]);
    for (const [type, mul, cents, vol] of voices) {
      const o = ctx.createOscillator();
      o.type = type;
      o.frequency.value = f * mul;
      if (reed) o.detune.value = cents;
      else {
        o.detune.setValueAtTime(cents - 28, t);
        o.detune.linearRampToValueAtTime(cents, t + 0.06);
      }
      vib.connect(o.detune);
      const og = ctx.createGain();
      og.gain.value = vol;
      o.connect(og).connect(flt);
      o.start(t);
      o.stop(end);
    }
    flt.connect(g);
    tail.connect(c.out);
    tail.connect(c.echo);
    lfo.start(t);
    lfo.stop(end);
  }

  /** 反拍短和弦（嘭-恰的「恰」）：音色跟主旋律 */
  private stab(t: number, c: NonNullable<Music['cur']>, fs: number[], dur: number): void {
    const ctx = this.ctx!;
    const reed = c.song.voice === 'reed';
    const flt = ctx.createBiquadFilter();
    flt.type = 'lowpass';
    flt.frequency.setValueAtTime(reed ? 1900 : 1500, t);
    flt.frequency.exponentialRampToValueAtTime(reed ? 1400 : 600, t + dur);
    const g = ctx.createGain();
    this.env(g, t, reed ? 0.1 : 0.11, 0.008, dur);
    flt.connect(g).connect(c.out);
    for (const f of fs) {
      for (const [type, cents] of (reed ? [['square', -8], ['sawtooth', 8]] : [['sawtooth', -6], ['sawtooth', 6]]) as [OscillatorType, number][]) {
        const o = ctx.createOscillator();
        o.type = type;
        o.frequency.value = f;
        o.detune.value = cents;
        o.connect(flt);
        o.start(t);
        o.stop(t + dur + 0.02);
      }
    }
  }

  /** 男声合唱「啊」：失谐锯齿波过三个元音共振峰，慢起慢收，带颤音 */
  private choir(t: number, out: AudioNode, fs: number[], dur: number, k: number): void {
    const ctx = this.ctx!;
    const end = t + dur + 0.4;
    const bus = ctx.createGain();
    bus.gain.setValueAtTime(0.0001, t);
    bus.gain.linearRampToValueAtTime(0.14 * k, t + Math.min(0.35, dur * 0.3));
    bus.gain.setValueAtTime(0.14 * k, t + dur * 0.85);
    bus.gain.linearRampToValueAtTime(0.0001, t + dur + 0.3);
    bus.connect(out);
    const src = ctx.createGain();
    for (const [f, q, v] of [[700, 6, 1], [1150, 8, 0.5], [2600, 10, 0.22]]) {
      const bp = ctx.createBiquadFilter();
      bp.type = 'bandpass';
      bp.frequency.value = f;
      bp.Q.value = q;
      const bg = ctx.createGain();
      bg.gain.value = v;
      src.connect(bp).connect(bg).connect(bus);
    }
    // 低一点的胸腔共鸣
    const body = ctx.createBiquadFilter();
    body.type = 'lowpass';
    body.frequency.value = 400;
    const bodyG = ctx.createGain();
    bodyG.gain.value = 0.18;
    src.connect(body).connect(bodyG).connect(bus);
    const lfo = ctx.createOscillator();
    lfo.frequency.value = 5;
    const vib = ctx.createGain();
    vib.gain.value = 16;
    lfo.connect(vib);
    lfo.start(t);
    lfo.stop(end);
    for (const f of fs) {
      for (const cents of [-12, 0, 12]) {
        const o = ctx.createOscillator();
        o.type = 'sawtooth';
        o.frequency.value = f;
        o.detune.value = cents;
        vib.connect(o.detune);
        o.connect(src);
        o.start(t);
        o.stop(end);
      }
    }
  }

  /** 军靴踏地：低频闷响 + 鞋底砂砾，一排人略有先后 */
  private stomp(t: number, out: AudioNode, k: number): void {
    const ctx = this.ctx!;
    this.noiseHit(t, out, 'lowpass', 700, 1, 0.42 * k, 0.1);
    this.noiseHit(t + 0.014, out, 'lowpass', 900, 1, 0.26 * k, 0.09);
    this.noiseHit(t + 0.006, out, 'bandpass', 2600, 1.2, 0.1 * k, 0.05);
    const o = ctx.createOscillator();
    o.frequency.setValueAtTime(95, t);
    o.frequency.exponentialRampToValueAtTime(48, t + 0.1);
    const g = ctx.createGain();
    this.env(g, t, 0.32 * k, 0.003, 0.13);
    o.connect(g).connect(out);
    o.start(t);
    o.stop(t + 0.15);
  }

  /** 定音鼓：正弦基音带一点下滑 + 鼓槌噪声 */
  private timp(t: number, out: AudioNode, f: number): void {
    const ctx = this.ctx!;
    for (const [mul, v] of [[1, 0.5], [1.5, 0.12], [2, 0.08]]) {
      const o = ctx.createOscillator();
      o.frequency.setValueAtTime(f * mul * 1.02, t);
      o.frequency.exponentialRampToValueAtTime(f * mul, t + 0.08);
      const g = ctx.createGain();
      this.env(g, t, v, 0.004, 1.1);
      o.connect(g).connect(out);
      o.start(t);
      o.stop(t + 1.15);
    }
    this.noiseHit(t, out, 'lowpass', 600, 0.8, 0.22, 0.07);
  }

  /** 失真强力和弦（根音 + 五度 + 八度），整首共用一路失真 */
  private riff(t: number, c: NonNullable<Music['cur']>, f: number, dur: number, k: number): void {
    const ctx = this.ctx!;
    if (!c.drive) {
      const pre = ctx.createGain();
      pre.gain.value = 1.8;
      const sh = ctx.createWaveShaper();
      const curve = new Float32Array(1024);
      for (let i = 0; i < curve.length; i++) curve[i] = Math.tanh(4 * ((i / (curve.length - 1)) * 2 - 1));
      sh.curve = curve;
      sh.oversample = '2x';
      const hp = ctx.createBiquadFilter();
      hp.type = 'highpass';
      hp.frequency.value = 80;
      const lp = ctx.createBiquadFilter();
      lp.type = 'lowpass';
      lp.frequency.value = 2600;
      const g = ctx.createGain();
      g.gain.value = 0.17;
      pre.connect(sh).connect(hp).connect(lp).connect(g).connect(c.out);
      c.drive = pre;
    }
    const g = ctx.createGain();
    this.env(g, t, 0.45 * k, 0.004, dur);
    // 闷音：短音再压暗一点
    const mute = ctx.createBiquadFilter();
    mute.type = 'lowpass';
    mute.frequency.value = dur < 0.2 ? 900 : 3000;
    mute.connect(g).connect(c.drive);
    for (const mul of [1, 1.5, 2]) {
      const o = ctx.createOscillator();
      o.type = 'sawtooth';
      o.frequency.value = f * mul;
      o.connect(mute);
      o.start(t);
      o.stop(t + dur + 0.02);
    }
  }
}
