import * as THREE from 'three';
import { SKYFIRE_TIP } from '../../assets/models/playerTank';
import { DRAPE_VERT } from '../../world/Craters';
import { ultHalf } from '../defs';
import { UltBase, type UltAim, type UltContext, type UltPreview } from './common';

const rand = (a: number, b: number) => a + Math.random() * (b - a);

/**
 * 「天火」数值表（策划案 T007 v3 3.6；伤害 / 吸力半径按 S7 派活单：落下 300、核心每秒 360、穹顶每秒 110、坍缩 400、吸力 28 米；冷却在 FUSIONS.skyfire.cd 里固定 40 秒（T066 翻倍））：
 * calib 秒校准（细红光朝天、6 根细白光落到 R 米圆周上往圆心收）→ 主光柱落下（dropR × A 米内 dropDmg + 往外推 knock）→ 灌注 dur 秒 → collapseT 秒坍缩。
 * 落点：起始 = 自动瞄准目标（首领战对准首领核心，没有目标 = 炮塔方向 preview 米），限制在坦克前方 R + gap 到 maxDist 米（R = r × A，A = 爆破药半效），
 * 跟着坦克走（保持相对位置）；按住出光时朝「光束方向上、同样距离」那一点挪，最快每秒 drag 米。
 * 每 tick 秒结算（energy，打重甲不打折，× 透镜半效）：核心 coreR 米每秒 coreDps（已含穹顶）；穹顶 R 米每秒 dps + 点燃（离开后再烧 igniteT 秒、每秒 ignite × 燃料半效，fire）；
 * 吸力 pullR × A 米：往中心拉，步兵 / 轻甲每秒 pull[0] 米、重甲 pull[1] 米（精英、首领部件、固定阵地不拉）。
 * 坍缩：collapseR × A 米内 collapseDmg（边缘衰减）+ shockR × A 米冲击波推开（不推首领）；之后 pit 熔坑 + fires 处地面火（半径 fireR、fireT 秒、每秒 fireDps，fire）。
 * 画面：扁穹顶（横向 R、高 domeH）+ 能量核（半径 ball.r、球心离地 ball.y），白闪 flash、顿帧 freeze、震屏 shake [落下, 坍缩]、泛光 bloom；
 * 镜头不接管：▼ / ▼▼ 档在生效期间临时回默认档（cinema 0），HUD 不变淡（T060 起光柱落下前那一拍抬头看卫星，落下以后照旧）。
 * T057（只是演出，上面的数值没动）：校准时天色骤暗、天上压一层暗云（mood.dark），光柱成了唯一的光；光柱落下慢放 slow [秒, 倍数]、镜头抬头 look [弧度, 秒]
 * 看光柱从天上贯下来、光柱一下变粗 punch 倍再收回；灌注期间金光照亮四周（glow 功率，mood.burn 偏暖）、火星顺着光柱往上卷；
 * 坍缩：穹顶往里缩掉 shrink（原来缩 25%）、光柱收成一根线 → 顿帧 hush 秒（停一拍）→ 大一号的蘑菇云（cloud 宽 / cloudTall 高）+ 火柱 pillar [高, 粗, 秒] + 慢放 boom [秒, 倍数]，之后飘灰 / 火星 fall [秒, 每秒片数]、天色慢慢回来
 * T060（制作人「天火也加个类似核弹的俯视角，仰望一下云层中隐约有卫星炮打下来」；伤害 / 落点 / 落下时刻都没动）：
 * 卫星炮 sat 停在落点正上方 h 米（天幕上画成云里的背光剪影，半径 size 米：光从云后面透出来，只看得出轮廓，见 Environment.satellite）；
 * 按下就压低抬头看它（sky：机位 tilt、仰到卫星在画面中间偏上 aim 弧度，lift 限在 [下, 上]，hold / inT / back 是真实秒），
 * slow [从第几秒, 秒, 倍数] 慢放把这一拍拉长；校准的细光从卫星打到地上转着往里收，炮塔的上行天线连到卫星；
 * fireAt 秒卫星开火（透镜一闪、云里一圈光往外扫、天上一声闷雷），光柱头从卫星往下扎，镜头跟着落回来，calib 秒落地（和原来一样）；
 * 光柱 / 校准光都从卫星下面一点（往下 below 那一截藏在云里）画下来，顶端在镜头平面后面就挪回镜头前；灌注期间卫星一直亮着，坍缩时淡掉
 */
export const SKYFIRE = {
  // T017-5a / 5d：最远落点 55 → 85、光柱落下 300 → 900、坍缩 400 → 800
  calib: 1, dur: 6, collapseT: 0.6, gap: 10, maxDist: 85, preview: 45, drag: 6, tick: 0.2,
  dropR: 10, dropDmg: 900, knock: 10, coreR: 8, coreDps: 360, r: 24, dps: 110, ignite: 20, igniteT: 3,
  pullR: 28, pull: [3, 1.5], collapseR: 18, collapseDmg: 800, shockR: 32, shockKnock: 12,
  domeH: 8, ball: { r: 6, y: 2.5 }, pit: { r: 7, d: 1.4, rim: 0.5, out: 13 }, fires: 5, fireR: 4, fireT: 4, fireDps: 20,
  flash: 0.45, freeze: 0.06, shake: [0.7, 0.8], bloom: 1.2,
  slow: [0.3, 0.4], look: [0.16, 0.9], punch: 1.8, glow: 3200, shrink: 0.7, hush: 0.15, cloud: 0.55, cloudTall: 0.8, pillar: [34, 2.2, 1.2], boom: [0.45, 0.35], fall: [6, 26],
  sat: { h: 95, size: 6, below: 0.14 },
  sky: { tilt: -1.3, aim: -0.02, lift: [0.4, 0.9], hold: 1.1, inT: 0.4, back: 0.45, slow: [0.35, 0.7, 0.5], fireAt: 0.72 },
  mood: {
    dark: { light: 0.55, exposure: 0.86, tint: 0x9ab0d0, tintK: 0.35, fog: 0x34343e, fogK: 0.45, storm: 0.85, skyDark: 0x121218, skyLite: 0x3e3c48 },
    burn: { light: 0.62, exposure: 0.92, tint: 0xffc070, tintK: 0.45, fog: 0x4a3e34, fogK: 0.4, storm: 0.45, skyDark: 0x2a2018, skyLite: 0x6a5030 },
  },
};

/** 光柱 / 校准光的顶端离镜头平面至少多远（米）：顶点跑到镜头平面后面，条带会算歪（T060 起从卫星画下来，原来固定从 85 米高画） */
const FRONT = 6;

/** 穹顶 / 能量核：边缘亮（菲涅尔）、里面流动的光纹，白芯 → 金 → 橙红边，叠加混合；里面不超过 0.25、边缘不超过 0.8 */
const DOME_VERT = /* glsl */ `
varying vec3 vN;
varying vec3 vV;
varying vec3 vP;
void main() {
  vP = position;
  vec4 mv = modelViewMatrix * vec4(position, 1.0);
  vN = normalize(normalMatrix * normal);
  vV = normalize(-mv.xyz);
  gl_Position = projectionMatrix * mv;
}`;
const DOME_FRAG = /* glsl */ `
uniform float uTime;
uniform float uAlpha;
uniform float uCore;
varying vec3 vN;
varying vec3 vV;
varying vec3 vP;
void main() {
  float fres = pow(1.0 - abs(dot(normalize(vN), normalize(vV))), 2.0);
  vec3 p = vP * 6.0;
  float flow = 0.5 + 0.5 * sin(p.x * 1.3 + uTime * 2.1 + sin(p.y * 1.7 - uTime)) * sin(p.z * 1.1 - uTime * 1.6 + sin(p.x * 0.9));
  vec3 col = mix(vec3(1.0, 0.96, 0.84), vec3(1.0, 0.7, 0.28), smoothstep(0.1, 0.6, fres));
  col = mix(col, vec3(1.0, 0.34, 0.1), smoothstep(0.6, 1.0, fres) * (1.0 - uCore));
  float a = (mix(0.05, 0.2, flow) * (1.0 - fres) + fres * mix(0.5, 0.8, uCore)) * uAlpha;
  gl_FragColor = vec4(col * a, a);
  #include <colorspace_fragment>
}`;
/** 地面：R 米熔化圈（橙红）+ 里面一层熔化的橙光 + 核心白热（uCoreR = 核心半径 ÷ R），亮度跳动 */
const GROUND_FRAG = /* glsl */ `
uniform float uTime;
uniform float uFade;
uniform float uCoreR;
varying vec2 vP;
void main() {
  float r = length(vP);
  if (r > 1.0) discard;
  float a = atan(vP.y, vP.x);
  float ring = smoothstep(0.9, 0.975, r) * (1.0 - smoothstep(0.975, 1.0, r));
  float melt = (1.0 - smoothstep(0.0, 1.0, r)) * 0.32;
  float core = 1.0 - smoothstep(uCoreR * 0.6, uCoreR, r);
  float flick = 0.8 + 0.2 * sin(uTime * 13.0 + a * 7.0 + r * 20.0);
  vec3 col = vec3(1.0, 0.45, 0.12) * (ring * 1.3 + melt) + vec3(1.0, 0.9, 0.65) * core * 1.3;
  float k = min(1.0, ring + melt + core) * flick * uFade;
  if (k < 0.01) discard;
  gl_FragColor = vec4(col * flick * uFade, k);
  #include <colorspace_fragment>
}`;

/** 天火 · 轨道激光炮（激光 + 火焰★ + 空袭★）：光柱持续轰击 6 秒，灌出能量穹顶把敌人吸进来熔掉，按住激光拖动落点 */
export class SkyfireUlt extends UltBase {
  /** 按下后几秒；-1 = 不在生效 */
  private t = -1;
  /** 落点相对坦克的偏移（跟车） */
  private ox = 0;
  private oz = 0;
  private x = 0;
  private z = 0;
  private R = SKYFIRE.r;
  private A = 1;
  private dropped = false;
  private collapsed = false;
  private tickT = 0;
  private meltT = 0;
  private dustT = 0;
  private a0 = 0;
  private readonly chain: [number, number][] = [];
  private chainT = 0;
  /** 氛围改过（被 clear 打断时下一帧退回平时） */
  private moody = false;
  /** 仰望（T060）：慢放放过没有、卫星开过火没有；天幕上卫星炮的样子 */
  private slowed = false;
  private shot = false;
  private readonly sat = { x: 0, y: 0, z: 0, size: SKYFIRE.sat.size, vis: 0, charge: 0, fire: 0, ring: 0 };
  private readonly top = new THREE.Vector3();
  private dome: THREE.Mesh<THREE.SphereGeometry, THREE.ShaderMaterial> | null = null;
  private ball: THREE.Mesh<THREE.SphereGeometry, THREE.ShaderMaterial> | null = null;
  private ground: THREE.Mesh<THREE.RingGeometry, THREE.ShaderMaterial> | null = null;
  private readonly v = new THREE.Vector3();

  /** 落点价值评分（T017-13A）：R 米穹顶，坦克前方 R + gap ～ maxDist 米 */
  spot(ctx: UltContext): { r: number; min: number; max: number } {
    const R = SKYFIRE.r * ultHalf(ctx.mods.area);
    return { r: R, min: R + SKYFIRE.gap, max: Math.max(SKYFIRE.maxDist, ctx.duel) };
  }

  /** 现在按下会落在哪（R 米的圈，限制在 R + gap～maxDist 米） */
  preview(ctx: UltContext, aim: UltAim): UltPreview {
    const p = this.start(ctx, aim);
    return { x: p.x, z: p.z, r: SKYFIRE.r * ultHalf(ctx.mods.area) };
  }

  protected override activeLabel(): string {
    const T = SKYFIRE;
    if (this.t < T.calib) return '校准';
    if (this.t < T.calib + T.dur) return `灌注 ${Math.max(1, Math.ceil(T.calib + T.dur - this.t))}`;
    return '坍缩';
  }

  /** 起始落点：首领核心 / 自动瞄准目标 / 炮塔方向 preview 米；离坦克限制在 R + gap～maxDist 米 */
  private start(ctx: UltContext, aim: UltAim): { x: number; z: number } {
    const T = SKYFIRE;
    const P = ctx.tank.group.position;
    const tg = ctx.bossCore() ?? aim.target;
    const x = tg ? tg.group.position.x : P.x - Math.sin(aim.angle) * T.preview;
    const z = tg ? tg.group.position.z : P.z - Math.cos(aim.angle) * T.preview;
    return this.clamp(ctx, x - P.x, z - P.z, T.r * ultHalf(ctx.mods.area));
  }

  /** 把相对坦克的偏移限制在 R + gap～maxDist 米、而且在坦克前方；返回世界坐标 */
  private clamp(ctx: UltContext, dx: number, dz: number, R: number): { x: number; z: number } {
    const T = SKYFIRE;
    const P = ctx.tank.group.position;
    if (dz > -1) dz = -1;
    const d = Math.hypot(dx, dz);
    // 巨炮在场时最远放到对轰射程（D5）
    const k = THREE.MathUtils.clamp(d, R + T.gap, Math.max(T.maxDist, ctx.duel)) / d;
    return { x: P.x + dx * k, z: P.z + dz * k };
  }

  protected fire(ctx: UltContext, aim: UltAim): void {
    const T = SKYFIRE;
    this.clear();
    this.A = ultHalf(ctx.mods.area);
    this.R = T.r * this.A;
    const p = this.start(ctx, aim);
    const P = ctx.tank.group.position;
    this.ox = p.x - P.x;
    this.oz = p.z - P.z;
    this.x = p.x;
    this.z = p.z;
    this.t = 0;
    this.dropped = this.collapsed = false;
    this.tickT = this.meltT = this.dustT = 0;
    this.a0 = Math.random() * Math.PI * 2;
    this.active = T.calib + T.dur + T.collapseT;
    // 仰望（T060）：镜头压低、抬头看落点正上方云里的卫星炮（仰到它在画面中间偏上）；光柱落下时落回来，之后照旧不接管
    const S = T.sky;
    this.slowed = this.shot = false;
    this.placeSat(0);
    ctx.satellite(this.sat);
    const elev = Math.atan2(T.sat.h - 12, P.z + 45 - p.z);
    ctx.cinema(S.tilt, S.hold, S.back + 0.1, false);
    ctx.lookUp(THREE.MathUtils.clamp(elev + 0.12 - S.aim, S.lift[0], S.lift[1]), S.hold, S.back, S.inT);
    ctx.audio.play('laserCharge');
    ctx.audio.play('radio');
    // 天色骤暗（T057）：校准的细光成了画面上最亮的东西；T060 天上压满乌云（抬头看得到）
    this.moody = true;
    ctx.mood(T.mood.dark, 0.45);
  }

  /** 卫星炮在落点正上方；t = 按下后几秒：0.25 秒浮出来、充能到 fireAt 秒开火，灌注期间一直亮着，坍缩时淡掉 */
  private placeSat(t: number): void {
    const T = SKYFIRE;
    const s = this.sat;
    const end = T.calib + T.dur;
    s.x = this.x;
    s.y = T.sat.h;
    s.z = this.z;
    s.vis = Math.min(1, t / 0.25) * (t > end ? Math.max(0, 1 - (t - end) / T.collapseT) : 1);
    const since = t - T.sky.fireAt;
    s.charge = since < 0 ? Math.min(1, t / T.sky.fireAt) ** 1.5 : 0.65 + 0.35 * Math.exp(-since * 4) + 0.05 * Math.sin(t * 9);
    s.fire = since < 0 ? 0 : Math.exp(-since * 5);
    s.ring = since < 0 ? 0 : since * 7;
  }

  /** 从 (ax, ay, az) 到 (bx, by, bz) 的线：a 跑到镜头平面后面（离镜头平面不到 FRONT 米）就沿线挪回到镜头前；两头都在后面返回 null（不画） */
  private front(ctx: UltContext, ax: number, ay: number, az: number, bx: number, by: number, bz: number): THREE.Vector3 | null {
    const c = ctx.camPos();
    const f = ctx.camDir();
    const da = (ax - c.x) * f.x + (ay - c.y) * f.y + (az - c.z) * f.z;
    if (da >= FRONT) return this.top.set(ax, ay, az);
    const db = (bx - c.x) * f.x + (by - c.y) * f.y + (bz - c.z) * f.z;
    if (db <= FRONT) return null;
    const k = (db - FRONT) / (db - da);
    return this.top.set(bx + (ax - bx) * k, by + (ay - by) * k, bz + (az - bz) * k);
  }

  protected step(ctx: UltContext): void {
    if (this.t < 0) {
      if (this.moody) {
        this.moody = false;
        ctx.mood(null, 0.6);
        ctx.satellite(null);
        ctx.lookUp(0, 0, 0.6);
      }
      return;
    }
    const T = SKYFIRE;
    const dt = ctx.dt;
    this.t += dt;
    const t = this.t;
    this.follow(ctx, dt);
    this.placeSat(t);
    ctx.satellite(this.sat);
    // 仰望那一拍慢一点（T060）
    if (!this.slowed && t >= T.sky.slow[0]) {
      this.slowed = true;
      ctx.slowmo(T.sky.slow[1], T.sky.slow[2]);
    }
    if (t < T.calib) {
      this.calibrate(ctx, t);
      return;
    }
    if (!this.dropped) this.drop(ctx);
    const end = T.calib + T.dur;
    const live = t < end;
    // 光柱：三层（白芯 / 金色光晕 / 淡橙外晕），宽度抖动；坍缩时收细。从云里的卫星炮贯下来（T060；顶端跑到镜头平面后面就挪回镜头前，
    // 默认机位里顶端在画面上沿以外）
    // 光柱落下那一下一口气变粗再收回（T057），坍缩时收细
    const punch = 1 + (T.punch - 1) * Math.max(0, 1 - (t - T.calib) / 0.5);
    const thin = (live ? 1 : Math.max(0, 1 - (t - end) / T.collapseT)) * punch;
    const jit = 1 + rand(-0.08, 0.08);
    const gy = ctx.fx.groundAt(this.x, this.z);
    const a = thin > 0.02 ? this.front(ctx, this.x, T.sat.h - (T.sat.h - gy) * T.sat.below, this.z, this.x, gy, this.z) : null;
    if (a) {
      ctx.streaks.add(a.x, a.y, a.z, this.x, gy, this.z, 30 * thin * jit, 0xff8a3a, 0.22, 0.05);
      ctx.streaks.add(a.x, a.y, a.z, this.x, gy, this.z, 14 * thin * jit, 0xffd27a, 0.5, 0.05);
      ctx.streaks.add(a.x, a.y, a.z, this.x, gy, this.z, 5 * thin * jit, 0xffffff, 0.95, 0.05);
    }
    this.showDome(ctx, t);
    if (live) {
      this.pull(ctx, dt);
      this.tickT -= dt;
      while (this.tickT <= 0) {
        this.tickT += T.tick;
        this.burn(ctx);
      }
      this.stepScene(ctx, dt, (t - T.calib) / T.dur);
      // 金光照亮四周（T057）+ 火星顺着光柱往上卷
      ctx.fx.flash(this.x, gy + 6, this.z, T.glow * (0.85 + 0.15 * Math.sin(t * 11)), 0xffc070);
      if (Math.random() < 0.8) {
        const a = Math.random() * Math.PI * 2;
        const r = rand(2, 7);
        ctx.fx.glow.emit({ x: this.x + Math.cos(a) * r, y: gy + rand(0.5, 3), z: this.z + Math.sin(a) * r, vx: -Math.cos(a) * 2, vy: rand(14, 24), vz: -Math.sin(a) * 2, life: rand(1.2, 2), size: rand(0.3, 0.55), size1: 0.12, color: 0xffe0a0, color1: 0xff8a30, alpha: 0.95, frame: 0, drag: 0.3 });
      }
      // 表面电弧：每帧几根短光条在穹顶表面爬
      for (let i = 0; i < 4; i++) {
        const a = Math.random() * Math.PI * 2;
        const h = Math.random();
        const rr = this.domeR(t) * Math.sqrt(1 - h * h);
        const y = gy + T.domeH * h;
        const bx = this.x + Math.cos(a) * rr;
        const bz = this.z + Math.sin(a) * rr;
        ctx.streaks.bolt(bx, y, bz, bx + rand(-2.5, 2.5), y + rand(-1, 1.5), bz + rand(-2.5, 2.5), 0xfff0c0, 0.16, 0.08, 0.8);
      }
      if (Math.random() < dt * 3) ctx.audio.play('zap', 0.4);
    } else if (!this.collapsed && t >= end + T.collapseT) this.collapse(ctx);
    if (this.chain.length) {
      this.chainT -= dt;
      if (this.chainT <= 0) {
        this.chainT = 0.14;
        const [bx, bz] = this.chain.shift()!;
        ctx.detonate(bx, bz);
      }
    }
    if (this.collapsed) {
      this.t = -1;
      this.hide();
      ctx.satellite(null);
      this.finish();
      return;
    }
    this.active = Math.max(0.05, end + T.collapseT - t);
  }

  /** 跟车 + 按住出光时拖动：朝「光束方向上、同样距离」那一点挪，最快每秒 drag 米；限制在 R + gap～maxDist 米 */
  private follow(ctx: UltContext, dt: number): void {
    const T = SKYFIRE;
    const beam = ctx.beam();
    if (beam !== null && this.t >= T.calib) {
      const d = Math.hypot(this.ox, this.oz);
      const tx = -Math.sin(beam) * d;
      const tz = -Math.cos(beam) * d;
      const mx = tx - this.ox;
      const mz = tz - this.oz;
      const m = Math.hypot(mx, mz);
      const step = Math.min(m, T.drag * dt);
      if (m > 1e-3) {
        this.ox += (mx / m) * step;
        this.oz += (mz / m) * step;
      }
    }
    const p = this.clamp(ctx, this.ox, this.oz, this.R);
    const P = ctx.tank.group.position;
    this.ox = p.x - P.x;
    this.oz = p.z - P.z;
    this.x = p.x;
    this.z = p.z;
  }

  /**
   * 校准：炮塔上行天线打一道细光连到云里的卫星炮（T060，原来是朝天 32 米的细红光，抬头时一整条横在画面上，改橙色、不出现血红）；6 根细白光从卫星打到 R 米圆周上，转着往圆心收；
   * fireAt 秒卫星开火：天上一闪、一声闷雷，光柱头从卫星往下扎，calib 秒落地
   */
  private calibrate(ctx: UltContext, t: number): void {
    const T = SKYFIRE;
    const S = T.sat;
    const k = t / T.calib;
    const tp = ctx.tank.turretPoint(...SKYFIRE_TIP, this.v);
    const tx = tp.x;
    const ty = tp.y;
    const tz = tp.z;
    const from = (x: number, y: number, z: number) => this.front(ctx, this.x + (x - this.x) * S.below, S.h + (y - S.h) * S.below, this.z + (z - this.z) * S.below, x, y, z);
    let a = from(tx, ty, tz);
    if (a) ctx.streaks.add(a.x, a.y, a.z, tx, ty, tz, 0.12, 0xff7a22, 0.9, 0.05, 1.5);
    const r = this.R * (1 - k * 0.92);
    for (let i = 0; i < 6; i++) {
      const ang = this.a0 + (i / 6) * Math.PI * 2 + k * 2.2;
      const gx = this.x + Math.cos(ang) * r;
      const gz = this.z + Math.sin(ang) * r;
      const gy = ctx.fx.groundAt(gx, gz);
      a = from(gx, gy, gz);
      if (a) ctx.streaks.add(a.x, a.y, a.z, gx, gy, gz, 0.22, 0xfff6e0, 0.6, 0.05, 1.5);
      if (Math.random() < 0.5) ctx.fx.glow.emit({ x: gx, y: gy + 0.3, z: gz, life: 0.1, size: 1.4, size1: 0.6, color: 0xfff0c0, frame: 0 });
    }
    const since = t - T.sky.fireAt;
    if (since < 0) return;
    if (!this.shot) {
      this.shot = true;
      ctx.flash(0.16);
      ctx.audio.play('thunder', 0.9, 0.55);
    }
    // 光柱头从卫星往下扎（越扎越快），落地那一刻 = 原来的「光柱落下」
    const gy = ctx.fx.groundAt(this.x, this.z);
    const y0 = S.h + (gy - S.h) * S.below;
    const hy = y0 + (gy - y0) * Math.min(1, since / (T.calib - T.sky.fireAt)) ** 1.6;
    a = this.front(ctx, this.x, y0, this.z, this.x, hy, this.z);
    if (!a) return;
    ctx.streaks.add(a.x, a.y, a.z, this.x, hy, this.z, 9, 0xffd27a, 0.5, 0.05);
    ctx.streaks.add(a.x, a.y, a.z, this.x, hy, this.z, 3, 0xffffff, 0.95, 0.05);
    ctx.fx.glow.emit({ x: this.x, y: hy, z: this.z, life: 0.08, size: 9, size1: 5, color: 0xffffff, color1: 0xffd27a, frame: 0 });
  }

  /** 主光柱落下：dropR 米内 dropDmg + 往外推；白闪、顿帧、震屏、泛光；穹顶开始胀 */
  private drop(ctx: UltContext): void {
    const T = SKYFIRE;
    this.dropped = true;
    const lens = ultHalf(ctx.mods.energy);
    const r = T.dropR * this.A;
    for (const e of ctx.enemies) {
      if (!e.alive) continue;
      if (Math.hypot(e.group.position.x - this.x, e.group.position.z - this.z) > r + e.radius) continue;
      ctx.damage(e, T.dropDmg * lens, this.x, this.z, { type: 'energy', knock: T.knock, ult: true });
    }
    ctx.fx.explosion(this.x, this.z, 3.5, 1.2);
    ctx.fx.shockwave(this.x, this.z, r * 1.6, 0xfff0d0, 0.5);
    ctx.fx.glow.emit({ x: this.x, y: 3, z: this.z, life: 0.3, size: 26, size1: 34, color: 0xfff8ec, frame: 0 });
    ctx.fx.flash(this.x, 10, this.z, 7000);
    ctx.flash(T.flash * 0.7);
    ctx.freeze(T.freeze);
    ctx.slowmo(T.slow[0], T.slow[1]);
    // 仰望结束（T060）：机位缓回、之后照旧不接管（▼ / ▼▼ 档临时回默认档，玩家本来就是默认 / ▲ 档就不动），HUD 不变淡
    ctx.cinema(0, T.dur + T.collapseT + 0.5, 0.8, false);
    ctx.lookUp(T.look[0], T.look[1], 0.7, 0.3);
    ctx.shake(T.shake[0]);
    ctx.pulse(T.bloom, 0.3);
    ctx.mood(T.mood.burn, 0.5);
    ctx.audio.play('nuke', 0.5);
    ctx.audio.play('laser');
    ctx.fx.decals.add(0, this.x, this.z, this.R * 1.2, this.R * 1.2, Math.random() * 6.28, 0.8, 25);
  }

  /** 穹顶 1.2 秒内从 6 米胀到 R（坍缩时往里一缩），能量核每秒 4 次 ±5% 地脉动，地面熔化圈跟着落点 */
  private domeR(t: number): number {
    const T = SKYFIRE;
    const grow = Math.min(1, (t - T.calib) / 1.2);
    const end = T.calib + T.dur;
    const shrink = t > end ? 1 - SKYFIRE.shrink * Math.min(1, (t - end) / T.collapseT) ** 2 : 1;
    return (6 + (this.R - 6) * (1 - (1 - grow) ** 2)) * shrink;
  }

  private showDome(ctx: UltContext, t: number): void {
    const T = SKYFIRE;
    if (!this.dome) this.makeMeshes(ctx);
    const dome = this.dome!;
    const ball = this.ball!;
    const ground = this.ground!;
    const gy = ctx.fx.groundAt(this.x, this.z);
    const r = this.domeR(t);
    dome.visible = ball.visible = ground.visible = true;
    dome.position.set(this.x, gy, this.z);
    dome.scale.set(r, T.domeH, r);
    const pulse = 1 + 0.05 * Math.sin(t * Math.PI * 8);
    ball.position.set(this.x, gy + T.ball.y, this.z);
    ball.scale.setScalar(T.ball.r * pulse * (t > T.calib + T.dur ? 0.8 : 1));
    ground.position.set(this.x, 0.15, this.z);
    ground.scale.set(r, 1, r);
    const fade = t > T.calib + T.dur ? Math.max(0, 1 - (t - T.calib - T.dur) / T.collapseT) : 1;
    for (const m of [dome, ball]) {
      m.material.uniforms.uTime.value = t;
      m.material.uniforms.uAlpha.value = fade;
    }
    ground.material.uniforms.uTime.value = t;
    ground.material.uniforms.uFade.value = 0.4 + 0.6 * fade;
    ground.material.uniforms.uCoreR.value = T.coreR / Math.max(1, r);
  }

  private makeMeshes(ctx: UltContext): void {
    const mat = (core: number) =>
      new THREE.ShaderMaterial({
        vertexShader: DOME_VERT,
        fragmentShader: DOME_FRAG,
        uniforms: { uTime: { value: 0 }, uAlpha: { value: 1 }, uCore: { value: core } },
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
      });
    this.dome = new THREE.Mesh(new THREE.SphereGeometry(1, 40, 12, 0, Math.PI * 2, 0, Math.PI / 2), mat(0));
    this.ball = new THREE.Mesh(new THREE.SphereGeometry(1, 24, 16), mat(1));
    this.ground = new THREE.Mesh(
      new THREE.RingGeometry(0.001, 1, 48, 12).rotateX(-Math.PI / 2),
      new THREE.ShaderMaterial({
        vertexShader: DRAPE_VERT,
        fragmentShader: GROUND_FRAG,
        uniforms: { uTime: { value: 0 }, uFade: { value: 1 }, uCoreR: { value: 0.33 }, uDrape: { value: 1 }, ...ctx.fx.craterU },
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
      }),
    );
    this.dome.renderOrder = 4;
    this.ball.renderOrder = 4;
    this.ground.renderOrder = 1;
    for (const m of [this.dome, this.ball, this.ground]) {
      m.frustumCulled = false;
      ctx.scene.add(m);
    }
  }

  /** 吸力：pullR 米内往中心拉（步兵 / 轻甲每秒 pull[0] 米、重甲 pull[1] 米；精英、首领部件、固定阵地不拉） */
  private pull(ctx: UltContext, dt: number): void {
    const T = SKYFIRE;
    const R = T.pullR * this.A;
    for (const e of ctx.enemies) {
      if (!e.alive || e.controller || e.spec.blocker || e.spec.fixed) continue;
      const p = e.group.position;
      const dx = this.x - p.x;
      const dz = this.z - p.z;
      const d = Math.hypot(dx, dz);
      if (d > R + e.radius || d < 1.5) continue;
      const sp = (e.armor === 'heavy' ? T.pull[1] : T.pull[0]) * dt;
      p.x += (dx / d) * Math.min(sp, d - 1.5);
      p.z += (dz / d) * Math.min(sp, d - 1.5);
    }
  }

  /** 每 tick：核心 coreR 米每秒 coreDps（已含穹顶），穹顶 R 米每秒 dps + 点燃（离开后再烧 igniteT 秒） */
  private burn(ctx: UltContext): void {
    const T = SKYFIRE;
    const lens = ultHalf(ctx.mods.energy);
    const B = ultHalf(ctx.mods.burn);
    const R = this.R;
    for (const e of ctx.enemies) {
      if (!e.alive) continue;
      const d = Math.hypot(e.group.position.x - this.x, e.group.position.z - this.z);
      if (d > R + e.radius) continue;
      const dps = d <= T.coreR + e.radius ? T.coreDps : T.dps;
      ctx.damage(e, dps * T.tick * lens, this.x, this.z, { type: 'energy', ult: true });
      if (e.alive) {
        const fire = T.ignite * B;
        if (fire >= e.burnDps || e.burnTime <= 0) {
          e.burnDps = fire;
          e.burnTime = Math.max(e.burnTime, T.igniteT);
          e.burnSrc = 'ult';
          e.burnPlayer = ctx.playerId ?? 0;
          e.burnSummon = false;
        }
      }
    }
  }

  /** 场景：穹顶里的木头路障点着、车辆残骸烧成空壳、油桶引爆；核心 8 米内每 0.5 秒原地熔碎；景物被吸弯、点燃、熔化；尘土往中心滚 */
  private stepScene(ctx: UltContext, dt: number, k: number): void {
    const T = SKYFIRE;
    this.meltT -= dt;
    if (this.meltT <= 0) {
      this.meltT = 0.5;
      ctx.smash(this.x, this.z, T.coreR, 2);
      this.chain.push(...ctx.kindle(this.x, this.z, this.R, this.R));
      ctx.scenery.ignite(this.x, this.z, this.R, 0.5);
      ctx.scenery.melt(this.x, this.z, T.coreR, 0.25);
    }
    ctx.scenery.pull(this.x, this.z, T.pullR * this.A, Math.min(1, k), dt);
    this.dustT -= dt;
    if (this.dustT <= 0) {
      // 被吸进来的尘土：贴地往里滚的一圈（反向冲击波）
      this.dustT = 0.5;
      const R = T.pullR * this.A;
      const gy = ctx.fx.groundAt(this.x, this.z);
      for (let i = 0; i < 18; i++) {
        const a = (i / 18) * Math.PI * 2 + rand(-0.1, 0.1);
        const sp = rand(10, 16);
        ctx.fx.smokeP.emit({ x: this.x + Math.cos(a) * R, y: gy + rand(0.4, 1.2), z: this.z + Math.sin(a) * R, vx: -Math.cos(a) * sp, vy: rand(0, 0.6), vz: -Math.sin(a) * sp, life: rand(1.2, 1.6), size: rand(1.2, 2), size1: rand(2.5, 3.5), color: 0x9a8a6c, alpha: 0.45, frame: 1, drag: 0.6 });
      }
    }
  }

  /** 坍缩：collapseR 米内 collapseDmg（边缘衰减）+ shockR 米冲击波推开（不推首领）；熔坑 + 地面火 + 黑烟 */
  private collapse(ctx: UltContext): void {
    const T = SKYFIRE;
    this.collapsed = true;
    const lens = ultHalf(ctx.mods.energy);
    const { x, z, A } = this;
    const contact = ctx.groundContact(x, z, T.collapseR * A);
    // 路边景物（T009 第 8 节）：坍缩圈里还站着的树被这一下（energy = 切）背离圆心切倒，和灌注时被吸弯的方向正好相反；圈外被吸弯的弹回去
    // 坍缩这一下不另挖坑（pit 0，T016-1：坑只有下面的熔坑一个；原来按「爆炸半径 ≥ 5.5」又叠了一个 9.9 米的坑）
    ctx.explode(x, z, T.collapseR * A, T.collapseDmg * lens, { type: 'energy', knock: T.shockKnock, ult: true, pit: 0 });
    ctx.scenery.release(x, z, T.pullR * A, T.collapseR * A + 1.5);
    const S = T.shockR * A;
    for (const e of ctx.enemies) {
      if (!e.alive || e.controller || e.spec.blocker || e.spec.fixed) continue;
      const dx = e.group.position.x - x;
      const dz = e.group.position.z - z;
      const d = Math.hypot(dx, dz) || 1;
      if (d > S || d <= T.collapseR * A) continue;
      const k = T.shockKnock * (1 - d / S) * (e.armor === 'heavy' ? 0.3 : 0.8);
      e.kvx += (dx / d) * k;
      e.kvz += (dz / d) * k;
    }
    // 大一号的蘑菇云 + 火柱 + 两圈冲击波（T057）
    ctx.fx.mushroom(x, z, T.cloud, false, { tall: T.cloudTall });
    ctx.fx.pillar(x, z, T.pillar[0], T.pillar[1], T.pillar[2]);
    ctx.fx.shockwave(x, z, S, 0xffd8a0, 0.7);
    ctx.fx.shockwave(x, z, S * 1.5, 0xffe8c0, 1.1);
    ctx.fx.fallout(x, z, 22, 16, T.fall[0], T.fall[1], 0.5);
    ctx.freeze(T.hush);
    ctx.slowmo(T.boom[0], T.boom[1]);
    this.moody = false;
    ctx.mood(null, 2.2);
    ctx.dig(x, z, T.pit.r, T.pit.d, T.pit.rim, T.pit.out, 0.9, 3, contact);
    for (let i = 0; i < T.fires; i++) {
      const a = (i / T.fires) * Math.PI * 2 + rand(-0.4, 0.4);
      const rr = rand(2, 8);
      ctx.hazards.fire(x + Math.cos(a) * rr, z + Math.sin(a) * rr, T.fireR, T.fireT, T.fireDps, 'player', true);
    }
    for (let i = 0; i < 3; i++) ctx.fx.burn(x + rand(-5, 5), z + rand(-5, 5), 1.8, 10, false);
    ctx.shake(T.shake[1]);
    ctx.flash(0.25);
    ctx.audio.play('nuke', 0.65, 1, 0.12);
    ctx.audio.play('bigboom');
  }

  private hide(): void {
    if (this.dome) this.dome.visible = false;
    if (this.ball) this.ball.visible = false;
    if (this.ground) this.ground.visible = false;
  }

  protected clear(): void {
    this.t = -1;
    this.chain.length = 0;
    this.hide();
  }

  override dispose(): void {
    super.dispose();
    for (const m of [this.dome, this.ball, this.ground]) {
      if (!m) continue;
      m.removeFromParent();
      m.geometry.dispose();
      m.material.dispose();
    }
    this.dome = this.ball = null;
    this.ground = null;
  }
}
