export function cardCategory(kind: CardKind): string {
  if (kind === 'core' || kind === 'branch' || kind === 'coreEvo') return 'category-core';
  if (kind === 'weapon' || kind === 'evolve' || kind === 'link') return 'category-weapon';
  if (kind === 'fusion') return 'category-ult';
  return 'category-mod';
}

/** 图标的 SVG 内容（画布版界面 ui/canvas/paint.ts 解析后自己画） */
export const ICON_SVG: Readonly<Record<string, string>> = P;

export function icon(id: string): string {
  const body = P[id] ?? P.main;
  return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${body}</svg>`;
}
