import * as THREE from 'three';
import type { Theme } from './themes';

/**
 * 放平视角时把雾推远（T017-2A，策划 3.3 方案 A）：镜头俯仰 tilt = −1（▲▲）时雾的起点 / 终点 ×(1 + push)，▲（−0.5）一半，默认档和俯视档不变；
 * 随镜头的平滑俯仰一起过渡（乡间 240 → ▲ 270 → ▲▲ 300 米）。核弹「屏幕上的敌人」照旧按没推远的雾判（Environment.baseFar）
 */
const FOG_PUSH = 0.25;

/**
 * 远景层（T017-2B，策划 3.3 方案 B）：
 * - 天空：跟着相机的半球，头顶偏蓝灰（主题的天光色压暗）、往下过渡到一圈偏暖的亮带、到地平线正好是雾色（和雾里的地面接得上）；画在不透明物体最后，被地面挡住的像素不算
 * - 天际线：跟着相机的一圈开口圆柱（半径 RING_R、高 RING_H），着色器按方位角画剪影——乡间是缓坡 + 零星树团、林间是连成片的树冠线、村镇是屋顶 / 烟囱 / 残楼；
 *   剪影是雾色压暗一点（远处的轮廓），底下一段淡进雾色；换区时两种剪影跟着雾色一起过渡。共 2 次绘制、约 900 个三角形，不吃雾、不写深度
 * - 天边炮火：每 FLASH.gap 秒左右，前方天际线后面闪一下（暖白的一团光，FLASH.dur 秒），远处像有战场
 * - 远景层次（T198，制作人「远处地平线天边的剪影比较简陋……在不喧宾夺主的情况下做得更有设计感」）：剪影后面再垫一道远山（几乎是雾色，按主题高低不同），
 *   剪影和远山顶上一道顺光的亮边；剪影和远山之间几缕战场余烟慢慢往上飘、被风吹斜；天边一层很淡的层云慢慢飘。全部压在雾色附近，对比度不超过原剪影
 */
const SKY_R = 390;
const RING_R = 365;
const RING_H = 70;
/**
 * 天际线在半透明队列里排第一个画（T241）：特效都不写深度，排在它们后面画的话，剪影会盖住蘑菇云、烟柱。
 * 地形、车辆、景物是不透明的、写深度，照样挡得住它
 */
const RING_ORDER = -1000;
const FLASH = { gap: [3, 8] as [number, number], dur: 0.45 };

/**
 * 天际线剪影的色调（T048：远景巨炮 SiegeProxy 和城市剪影用同一套规则，见 bosses.ts 的 siegeFarMat）：color = 剪影色（雾色压暗 + 往地面色偏一点，换区时跟着雾色过渡，
 * 天际线着色器和远景巨炮共用这一个颜色对象）；alpha = 剪影色最多压到几成（其余是雾色），越往下越淡、最底下 fade 那一截淡进雾里
 */
export const SKYLINE = { color: { value: new THREE.Color() }, alpha: 0.55, fade: 0.05 };
/** 太阳摆在镜头焦点的哪儿（x / y / z 偏移）、照向焦点前方多远（tz）；直升机的软圆影顺着它往外偏（T098，Air.render）。T122 起主题可以换（Theme.sunAt，黄昏压低），换区时跟着过渡 */
export const SUN_AT = { x: -40, y: 62, z: 30, tz: -8 };
const SUN_NOON = { ...SUN_AT };
/** 黄昏的天（T122 沙漠油井）：天顶深蓝、地平线上方一道暖金（地平线那一圈照旧是雾色）；T125 天顶 0x2e2f60 蓝紫 → 0x3a4a74、亮带 0xeea078 橙粉 → 0xf2c88c（沙子发暖金不发红） */
const DUSK = { zenith: new THREE.Color(0x3a4a74), glow: new THREE.Color(0xf2c88c) };

const SKY_VERT = /* glsl */ `
varying vec3 vDir;
#include <fog_pars_vertex>
void main() {
  vDir = position;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}`;

const SKY_FRAG = /* glsl */ `
uniform vec3 uZenith;
uniform vec3 uWarm;
uniform vec4 uFlash;
uniform float uStorm;
uniform float uTime;
uniform vec4 uBolt;
uniform vec3 uStormDark;
uniform vec3 uStormLite;
uniform vec4 uSat;
uniform vec4 uSatFx;
uniform float uCloud;
varying vec3 vDir;
#include <fog_pars_fragment>
// 不带 sin 的哈希（输入是天幕上的小坐标）
float sh(vec2 p) { vec3 q = fract(p.xyx * 0.1031); q += dot(q, q.yzx + 33.33); return fract((q.x + q.y) * q.z); }
float sn(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(sh(i), sh(i + vec2(1.0, 0.0)), f.x), mix(sh(i + vec2(0.0, 1.0)), sh(i + vec2(1.0, 1.0)), f.x), f.y);
}
void main() {
  vec3 d = normalize(vDir);
  float up = max(d.y, 0.0);
  // 放平视角时画面顶上也只到仰角 10° 左右：渐变压在地平线上方这一小段里，才看得出「头顶偏蓝、天边偏暖」
  vec3 col = mix(uWarm, uZenith, smoothstep(0.02, 0.2, up));
  // 天边炮火：前方某个方位角上，地平线附近一团暖光
  float az = atan(d.x, -d.z);
  // 天边一层很淡的层云（T198）：贴着地平线上方一窄条、横着拉长，慢慢飘；只比天色亮一点
  float band = smoothstep(0.012, 0.045, up) * (1.0 - smoothstep(0.08, 0.2, up));
  if (band > 0.0) {
    float cl = sn(vec2(az * 6.0 + uCloud, up * 48.0)) * 0.6 + sn(vec2(az * 17.0 - uCloud * 1.4, up * 110.0 + 3.0)) * 0.4;
    col = mix(col, mix(uWarm, vec3(1.0), 0.18), smoothstep(0.5, 0.82, cl) * band * 0.4);
  }
  float fd = abs(az - uFlash.x);
  col += vec3(1.0, 0.72, 0.42) * uFlash.y * exp(-fd * fd * 60.0) * (1.0 - smoothstep(0.0, 0.16, up));
  // 乌云（T057 雷云）：方向投到一块天幕上（越靠地平线越远越密），三层噪声慢慢翻滚；主雷那个方位的云被照亮
  float n = 0.5;
  if (uStorm > 0.001) {
    vec2 p = d.xz / (up + 0.1) * 1.4;
    n = sn(p + vec2(uTime * 0.07, uTime * 0.11)) * 0.55 + sn(p * 2.3 - vec2(uTime * 0.13, 0.0)) * 0.3 + sn(p * 5.1 + uTime * 0.2) * 0.15;
    vec3 sc = mix(uStormDark, uStormLite, smoothstep(0.3, 0.85, n));
    float bd = abs(az - uBolt.x);
    sc += vec3(0.7, 0.82, 1.0) * uBolt.y * (0.3 + n) * exp(-bd * bd * 5.0);
    col = mix(col, sc, uStorm);
  }
  // 天火的卫星炮（T060）：云里一个背光的剪影——金光从云后面透出来，只看得出轮廓，云厚的地方挡住；
  // uSat = 方向 + 能见度，uSatFx = 充能 / 开火闪光 / 云里那圈光往外扫到多远 / 大小（1 = 环半径的两倍多）
  if (uSat.w > 0.001) {
    vec3 S = uSat.xyz;
    float c = dot(d, S);
    if (c > 0.6) {
      vec3 R = normalize(cross(S, vec3(0.0, 1.0, 0.0)));
      vec3 U = cross(R, S);
      vec2 q = vec2(dot(d, R), dot(d, U)) / (c * uSatFx.w);
      float ang = uTime * 0.1;
      q = mat2(cos(ang), -sin(ang), sin(ang), cos(ang)) * q;
      float r = length(q);
      // 卫星周围一层更碎的云（跟着剪影的坐标走、自己慢慢飘）：背后的金光把云边照亮，云缝里透出光
      vec2 w = q * 0.42;
      float cl = sn(w + vec2(uTime * 0.21, uTime * 0.08)) * 0.55 + sn(w * 2.2 - vec2(uTime * 0.33, 0.0)) * 0.3 + sn(w * 5.0 + uTime * 0.5) * 0.15;
      float dens = smoothstep(0.32, 0.72, cl) * (1.0 - smoothstep(6.0, 11.0, r));
      float glow = exp(-r * r * 0.07) * uSatFx.x;
      col = mix(col, mix(uStormDark * 1.3, vec3(0.62, 0.42, 0.24), glow * 0.8), dens * 0.8 * uSat.w);
      col += vec3(1.0, 0.68, 0.34) * glow * dens * (1.0 - dens) * 2.2 * uSat.w;
      // 光晕：云缝里亮、云厚的地方糊成一团
      float halo = exp(-r * r * 0.5) * (0.25 + 0.45 * (1.0 - dens)) * uSatFx.x * uSat.w;
      col += vec3(1.0, 0.7, 0.34) * halo;
      // 剪影：一圈环 + 横梁 + 两片带格子缝的太阳能板 + 三根往外伸的聚焦臂
      float ring = 1.0 - smoothstep(0.05, 0.09, abs(r - 0.46));
      float px = abs(q.x);
      float beam = step(abs(q.y), 0.045) * step(px, 0.9);
      float panel = step(abs(q.y), 0.28) * step(0.9, px) * step(px, 2.0) * step(0.1, fract(px * 4.0)) * step(0.04, fract(q.y * 3.0 + 0.5));
      float prong = 0.0;
      for (int k = 0; k < 3; k++) {
        float a = 1.5708 + float(k) * 2.0944;
        vec2 dk = vec2(cos(a), sin(a));
        float along = dot(q, dk);
        float perp = abs(dot(q, vec2(-dk.y, dk.x)));
        prong = max(prong, step(0.46, along) * step(along, 1.05) * step(perp, 0.06 * (1.15 - along)));
      }
      float sil = max(max(ring, beam), max(panel * 0.75, prong));
      // 云厚的地方挡住剪影，薄的地方透出来（最多也只压到七成：隐约看得出轮廓）
      float veil = uSat.w * (1.0 - 0.9 * dens);
      col = mix(col, vec3(0.04, 0.034, 0.04), sil * veil * 0.7);
      // 环中间的透镜：充能越满越亮，也隔着云
      float lens = 1.0 - smoothstep(0.16, 0.3, r);
      col += vec3(1.0, 0.86, 0.62) * lens * uSatFx.x * uSatFx.x * 1.3 * uSat.w * (1.0 - 0.6 * dens);
      // 开火：透镜一闪 + 一圈光在云里往外扫
      col += vec3(1.0, 0.92, 0.76) * uSatFx.y * exp(-r * r * 0.6) * 0.9 * uSat.w;
      float wave = (r - uSatFx.z) * 0.9;
      col += vec3(1.0, 0.78, 0.46) * exp(-wave * wave) * uSatFx.y * (0.2 + dens) * 0.9 * uSat.w;
    }
  }
  gl_FragColor = vec4(col, 1.0);
  #include <colorspace_fragment>
  #ifdef USE_FOG
  // 地平线正好是雾色（和雾里的地面同一种混法，接缝看不出来）
  gl_FragColor.rgb = mix(gl_FragColor.rgb, fogColor, 1.0 - smoothstep(0.0, 0.035, up));
  #endif
}`;

const RING_VERT = /* glsl */ `
varying vec2 vUv;
varying vec3 vDir;
#include <fog_pars_vertex>
void main() {
  vUv = uv;
  vDir = position;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}`;

const RING_FRAG = /* glsl */ `
uniform float uStyleA;
uniform float uStyleB;
uniform float uMix;
uniform vec3 uShade;
uniform vec3 uRim;
uniform float uTime;
uniform vec4 uFlash;
varying vec2 vUv;
varying vec3 vDir;
#include <fog_pars_fragment>
float hash(float n) { return fract(sin(n) * 43758.5453); }
float noise1(float x) { float i = floor(x); float f = fract(x); return mix(hash(i), hash(i + 1.0), f * f * (3.0 - 2.0 * f)); }
// 梯形（a 在 a0..a1 之间，两边各 s 的坡）
float trap(float a, float a0, float a1, float s) { return smoothstep(a0, a0 + s, a) * (1.0 - smoothstep(a1 - s, a1, a)); }
// 方位扭曲（T241）：格子按低频噪声挤宽拉窄，房子 / 厂棚 / 树的间距不再等宽。k × f ≤ 0.45，扭曲后方位不会倒折
float bend(float a, float f, float k) { return a + k * (noise1(a * f + 31.7) - 0.5); }
// 一排树冠（T241）：每格最多一棵，位置、冠宽、高矮、圆冠 / 尖冠都随机，左右邻格一起算（树冠互相叠）；dens = 有树的格子占比
float crowns(float x, float seed, float dens) {
  float c = floor(x);
  float r = 0.0;
  for (int j = -1; j <= 1; j++) {
    float id = c + float(j);
    float on = step(hash(id * 1.37 + seed), dens);
    float d = (x - (id + 0.5 + 0.8 * (hash(id + seed + 3.1) - 0.5))) / (0.35 + 0.6 * hash(id + seed + 7.7));
    float dome = sqrt(max(0.0, 1.0 - d * d));
    float cone = max(0.0, 1.0 - abs(d) * 1.7);
    r = max(r, on * (0.35 + 0.65 * hash(id + seed + 12.3)) * mix(dome, cone, step(0.6, hash(id + seed + 19.9))));
  }
  return r;
}
// 剪影高度（0..1 = 圆柱高度的比例）：style 0 乡间缓坡 + 零星树团，1 林间树冠线，2 村镇屋顶 / 烟囱 / 残楼
float skyline(float a, float style) {
  // 缓坡：倍频不取整、方位先扭一道，看不出周期
  float ah = bend(a, 1.7, 0.2);
  float hills = 0.065 + 0.06 * noise1(ah * 2.2) + 0.03 * noise1(ah * 6.3 + 3.0) + 0.015 * noise1(a * 13.7 + 8.0) + 0.006 * noise1(a * 31.0);
  if (style > 4.5) {
    // 沙漠油井（T122）：低缓的沙丘线 + 两座平顶石山 + 几座井架（细三角）+ 正前方偏右一片炼厂（细高烟囱、分馏塔、一排矮油罐、一根燃烧塔）。
    // 竖屏横向视角只有约 ±0.19 弧度，炼厂和石山都摆在这一段里
    float ad = bend(a, 4.1, 0.09);
    float dunes = 0.035 + 0.025 * noise1(ad * 14.0) + 0.012 * noise1(ad * 37.3 + 5.0) + 0.006 * noise1(a * 83.0);
    float mesa = max(trap(a, -0.27, -0.1, 0.035) * (0.12 + 0.01 * noise1(a * 90.0)), trap(a, 0.16, 0.34, 0.03) * (0.095 + 0.01 * noise1(a * 70.0)));
    float ar = bend(a, 9.0, 0.045);
    float c7 = floor(ar * 160.0);
    float f7 = fract(ar * 160.0);
    float rig = step(0.9, hash(c7 + 17.0)) * max(0.0, 1.0 - abs(f7 - 0.5) / 0.32) * (0.09 + 0.04 * hash(c7 + 3.0));
    float r0 = trap(a, -0.02, 0.13, 0.004);
    float c8 = floor(a * 250.0);
    float f8 = fract(a * 250.0);
    float stacks = r0 * step(0.5, hash(c8 + 29.0)) * step(abs(f8 - 0.5), 0.16) * (0.13 + 0.08 * hash(c8 + 7.0));
    float towers = r0 * step(0.62, hash(floor(a * 120.0) + 61.0)) * step(abs(fract(a * 120.0) - 0.5), 0.3) * (0.09 + 0.04 * hash(floor(a * 120.0) + 9.0));
    float tanks = r0 * (0.035 + 0.02 * step(0.5, hash(floor(a * 90.0) + 41.0))) * (0.7 + 0.3 * sqrt(max(0.0, 1.0 - pow(fract(a * 90.0) * 2.0 - 1.0, 2.0))));
    float flare = step(abs(a - 0.118), 0.0013) * 0.23 + (1.0 - smoothstep(0.0, 0.0028, abs(a - 0.118))) * 0.04;
    return max(dunes + max(max(mesa, rig), max(max(stacks, towers), tanks)), flare);
  }
  if (style < 0.5) {
    // 树团成簇、大小不一，簇外偶尔一棵孤树
    float zone = smoothstep(0.55, 0.85, 0.65 * noise1(bend(a, 3.0, 0.12) * 11.3 + 7.0) + 0.35 * noise1(a * 27.1 + 2.0));
    float clump = zone * (0.03 + 0.012 * noise1(a * 61.0) + 0.045 * crowns(bend(a, 7.0, 0.05) * 150.0, 3.0, 0.85));
    float lone = 0.055 * crowns(bend(a, 5.0, 0.07) * 52.0, 11.0, 0.14);
    return hills + max(clump, lone);
  }
  if (style < 1.5) {
    // 林冠：成片的树冠底子高低起伏，上面两层大小不同的树冠叠出参差的轮廓，偶尔一块林间空地
    float af = bend(a, 6.0, 0.06);
    float mass = 0.06 + 0.035 * noise1(af * 9.7 + 1.0) + 0.012 * noise1(a * 29.0 + 4.0);
    float small = 0.028 * crowns(af * 97.0, 5.0, 0.8);
    float tall = 0.065 * crowns(bend(a, 4.3, 0.08) * 41.0, 17.0, 0.4 + 0.45 * noise1(a * 7.9 + 3.0));
    float gap = smoothstep(0.78, 0.95, noise1(bend(a, 2.0, 0.15) * 5.3 + 11.0));
    return hills + (mass + max(small, tall)) * (1.0 - 0.6 * gap);
  }
  if (style > 3.5) {
    // 荒原机场（T093）：地势平、低缓坡；一排排拱顶机库（半圆顶）+ 细高塔台 + 远处一座系留塔（最高的一根细柱，顶上一点）
    float ab = bend(a, 6.0, 0.07);
    float c4 = floor(ab * 48.0);
    float f4 = fract(ab * 48.0);
    float aw = 0.55 + 0.45 * hash(c4 + 13.0);
    float ax = (f4 - 0.5 - 0.5 * (1.0 - aw) * (hash(c4 + 17.0) * 2.0 - 1.0)) / aw * 2.0;
    float arch = step(0.45, hash(c4 + 5.0)) * (0.03 + 0.03 * hash(c4 + 9.0)) * sqrt(max(0.0, 1.0 - ax * ax));
    float tower = step(0.86, hash(c4 + 23.0)) * step(abs(f4 - 0.2 - 0.6 * hash(c4 + 29.0)), 0.05) * (0.1 + 0.03 * hash(c4 + 2.0));
    float mast = step(abs(a - 0.42), 0.004) * 0.26 + step(abs(a - 0.42), 0.012) * 0.2;
    return hills * 0.45 + max(max(arch, tower), mast);
  }
  if (style > 2.5) {
    // 钢铁厂区（T019-a）：厂棚连成一片 + 细高烟囱 + 粗高炉（带斜料桥）+ 龙门吊
    float ab = bend(a, 7.0, 0.06);
    float c2 = floor(ab * 60.0);
    float f = fract(ab * 60.0);
    // 厂棚：三档高度；锯齿屋顶的齿数每格 2～4 个
    float shed = 0.045 + 0.03 * floor(hash(c2 + 3.0) * 3.0) * step(0.25, hash(c2 + 3.0)) + 0.02 * step(0.5, fract(f * (2.0 + floor(hash(c2 + 11.0) * 3.0))));
    float sx = 0.25 + 0.5 * hash(c2 + 37.0);
    float stack = step(0.72, hash(c2 + 19.0)) * step(abs(f - sx), 0.04 + 0.04 * hash(c2 + 43.0)) * (0.15 + 0.13 * hash(c2 + 7.0));
    float furnace = step(0.88, hash(c2 + 31.0)) * step(abs(f - 0.5), 0.22) * (0.16 + 0.04 * cos((f - 0.5) * 6.0));
    float ramp = step(0.88, hash(c2 + 31.0)) * step(0.72, f) * (0.16 * (1.0 - (f - 0.72) / 0.28));
    // 龙门吊：两条高腿（横梁画不出来——剪影是「从地平线往上填满」的高度函数）
    float crane = step(0.9, hash(c2 + 47.0)) * max(step(abs(f - 0.15), 0.03), step(abs(f - 0.85), 0.03)) * 0.15;
    return hills * 0.5 + max(max(shed, stack), max(max(furnace, ramp), crane));
  }
  // 村镇：两套宽窄不同的格子叠着排房子（宽窄不一、有的连成一排），疏密按低频噪声成村 / 留空；一部分是坡屋顶
  float av = bend(a, 9.0, 0.05);
  float dens = 0.3 + 0.55 * noise1(bend(a, 2.5, 0.15) * 6.1 + 2.0);
  float cell = floor(av * 70.0);
  float fv = fract(av * 70.0);
  float roof = 1.0 - step(0.5, hash(cell + 53.0)) * 0.5 * abs(fv * 2.0 - 1.0);
  float bld = step(1.0 - dens, hash(cell)) * (0.035 + 0.085 * hash(cell + 13.0)) * roof;
  float a2 = bend(a, 5.0, 0.07) * 43.0 + 0.37;
  float c3 = floor(a2);
  float f3 = fract(a2);
  float bld2 = step(1.0 - dens * 0.7, hash(c3 + 71.0)) * step(abs(f3 - 0.5), 0.2 + 0.25 * hash(c3 + 73.0)) * (0.03 + 0.06 * hash(c3 + 79.0));
  float chim = step(0.82, hash(cell + 27.0)) * step(abs(fv - 0.2 - 0.6 * hash(cell + 59.0)), 0.1) * (0.05 + 0.04 * hash(cell + 61.0));
  float ruin = step(0.9, hash(cell + 41.0)) * mix(fv, 1.0 - fv, step(0.5, hash(cell + 67.0))) * 0.06;
  return hills * 0.7 + max(bld + chim + ruin, bld2);
}
// 远山（T198）：剪影后面一道起伏的山脊（棱线用 |噪声| 折出尖），各主题高低不同：林区最高、乡间 / 村镇缓、机场很低、沙漠用自己的远沙丘
// T241：方位先扭一道，两层尖峰的倍频错开（5.3 / 12.9），主峰之间的距离和高低都不一样
float ridge(float a) {
  float ar = bend(a, 1.3, 0.3);
  float pk = 1.0 - abs(noise1(ar * 5.3 + 5.0) * 2.0 - 1.0);
  float pk2 = 1.0 - abs(noise1(bend(a, 3.1, 0.12) * 12.9 + 1.0) * 2.0 - 1.0);
  return 0.12 + 0.08 * noise1(ar * 2.3 + 17.0) + 0.05 * pk * pk * (0.55 + 0.45 * noise1(a * 1.9 + 4.0)) + 0.022 * pk2 * pk2 * pk + 0.012 * noise1(a * 31.0 + 2.0) + 0.005 * noise1(a * 90.0);
}
float farAmp(float s) { return s < 0.5 ? 1.0 : s < 1.5 ? 1.35 : s < 2.5 ? 1.0 : s < 3.5 ? 0.9 : s < 4.5 ? 0.6 : 0.0; }
// 战场余烟（T198）：剪影后面几缕细烟，越往上越粗越淡、被风吹斜，噪声撕成一团一团慢慢往上走（方位按主题错开）
float plume(float a, float y, float a0, float base, float s) {
  if (y < base) return 0.0;
  float k = y - base;
  float cx = a0 + 0.22 * k * k + 0.006 * sin(k * 9.0 - uTime * 0.5 + s);
  float w = 0.004 + k * 0.06;
  float u = (a - cx) / w;
  float n = noise1((k * 14.0 - uTime * 0.35) + s * 7.0) * 0.6 + noise1(a * 260.0 + k * 30.0 - uTime * 0.6 + s) * 0.4;
  return exp(-u * u) * smoothstep(0.25, 0.75, n) * (1.0 - smoothstep(0.08, 0.42, k)) * smoothstep(0.0, 0.02, k);
}
void main() {
  float a = atan(vDir.x, -vDir.z);
  float y = vUv.y;
  float h = mix(skyline(a, uStyleA), skyline(a, uStyleB), uMix);
  // 沙漠（T125）：前面那道沙丘线 + 炼厂 / 石山后面再垫一道高而缓的远沙丘，几乎淡成雾色（灰白），空气透视拉开两层
  float w5 = mix(step(4.5, uStyleA), step(4.5, uStyleB), uMix);
  float back = w5 * (0.07 + 0.045 * noise1(a * 5.0 + 2.0) + 0.012 * noise1(a * 19.0));
  float hf = max(back, mix(farAmp(uStyleA), farAmp(uStyleB), uMix) * ridge(a));
  float st = mix(uStyleA, uStyleB, uMix);
  float smoke = 0.0;
  if (y > h) {
    float sd = floor(st + 0.5) * 1.7;
    smoke = max(max(plume(a, y, -0.46 + 0.08 * sin(sd), h * 0.6, sd), plume(a, y, 0.21 + 0.06 * cos(sd * 1.3), h * 0.6, sd + 2.0)), plume(a, y, 0.63 - 0.05 * sin(sd * 0.7), h * 0.6, sd + 4.0) * 0.8);
  }
  if (y > max(h, hf) && smoke < 0.004) discard;
  vec3 fogC = uShade;
  #ifdef USE_FOG
  fogC = fogColor;
  #endif
  float px = max(fwidth(y), 1e-4);
  // 剪影：雾色压暗一点；越靠下越淡进雾色（地平线那一段和雾里的地面接上）
  vec3 col = uShade;
  float fd = abs(a - uFlash.x);
  col += vec3(1.0, 0.6, 0.3) * uFlash.y * 0.35 * exp(-fd * fd * 200.0);
  float near = step(y, h);
  float k = mix(0.27, ${SKYLINE.alpha.toFixed(2)}, near) * smoothstep(0.0, ${SKYLINE.fade.toFixed(2)}, y) * (0.6 + 0.4 * smoothstep(0.0, max(near > 0.5 ? h : hf, 0.001), y));
  // 远山偏一点冷色（空气透视：越远越蓝灰）
  col = mix(fogC, mix(col, col * vec3(0.92, 0.97, 1.08), 1.0 - near), k);
  // 顶上一道顺光的亮边（剪影两个像素、远山一个像素，远山更淡）
  float edge = near > 0.5 ? 1.0 - smoothstep(0.0, px * 2.2, h - y) : 1.0 - smoothstep(0.0, px * 1.4, hf - y);
  col = mix(col, uRim, edge * (near > 0.5 ? 0.36 : 0.26) * smoothstep(0.0, 0.03, y));
  float alpha = 1.0;
  if (y > max(h, hf) || (near < 0.5 && smoke > 0.0)) {
    // 余烟：雾色稍压暗一点的灰，盖在远山 / 天上
    vec3 sc = mix(fogC, uShade, 0.7);
    if (y > max(h, hf)) { col = sc; alpha = smoke * 0.5; }
    else col = mix(col, sc, smoke * 0.5);
  }
  gl_FragColor = vec4(col, alpha);
  #include <colorspace_fragment>
  // 沙漠炼厂燃烧塔顶上那一团火（T122）：橙黄，不吃雾
  float fl = w5 * step(0.232, vUv.y) * (1.0 - smoothstep(0.0, 0.0028, abs(a - 0.118)));
  gl_FragColor.rgb = mix(gl_FragColor.rgb, mix(vec3(1.0, 0.86, 0.5), vec3(1.0, 0.56, 0.18), smoothstep(0.24, 0.27, vUv.y)), fl);
}`;

const STYLE: Record<Theme['id'], number> = { farmland: 0, forest: 1, village: 2, foundry: 3, airfield: 4, desert: 5 };

/**
 * 终极的氛围（T057）：光照 × light、曝光 × exposure；太阳 / 天光的颜色往 tint 偏 tintK；雾色（天空、天际线跟着）往 fog 偏 fogK；
 * 天上的云 storm（0..1，雷云的乌云 / 核弹的高空云和尘霾）和它的暗部 / 亮部颜色 skyDark / skyLite；影子浓淡 shadow（乌云遮住太阳时影子变淡）。mood(null) = 回到平时
 */
export interface Mood {
  light: number;
  exposure: number;
  tint: number;
  tintK: number;
  fog: number;
  fogK: number;
  storm: number;
  skyDark: number;
  skyLite: number;
  shadow: number;
}
/** 天火的卫星炮在天幕上怎么画（T060，见 Environment.satellite） */
export interface SatView {
  x: number;
  y: number;
  z: number;
  size: number;
  vis: number;
  charge: number;
  fire: number;
  ring: number;
}
/** 天上的云默认是雷云的乌云色 */
const STORM_SKY = { dark: 0x1a1f27, lite: 0x48525e };
const CALM: Mood = { light: 1, exposure: 1, tint: 0xffffff, tintK: 0, fog: 0xffffff, fogK: 0, storm: 0, skyDark: STORM_SKY.dark, skyLite: STORM_SKY.lite, shadow: 1 };

/** 光照 / 雾 / 曝光 / 天空和天际线；进入新区域时在几秒内平滑过渡到新主题的色调 */
export class Environment {
  readonly sun = new THREE.DirectionalLight(0xffffff, 2.5);
  readonly hemi = new THREE.HemisphereLight(0xffffff, 0x444444, 1);
  private readonly fog: THREE.Fog;
  private from: Theme;
  private to: Theme;
  private t = 1;
  private readonly ca = new THREE.Color();
  private readonly cb = new THREE.Color();
  /** 没被放平视角推远的雾（主题过渡后的值）；push = 现在推远了多少（0..1） */
  private near = 0;
  private far = 0;
  private push = 0;
  private readonly sky: THREE.Mesh<THREE.BufferGeometry, THREE.ShaderMaterial>;
  private readonly ring: THREE.Mesh<THREE.BufferGeometry, THREE.ShaderMaterial>;
  private flashT = 0;
  private flashGap = 4;
  private sat: SatView | null = null;

  constructor(
    private readonly scene: THREE.Scene,
    private readonly renderer: THREE.WebGLRenderer,
    theme: Theme,
  ) {
    this.from = theme;
    this.to = theme;
    this.fog = new THREE.Fog(theme.fog, theme.fogNear, theme.fogFar);
    scene.fog = this.fog;
    scene.background = new THREE.Color(theme.fog);

    const sun = this.sun;
    sun.castShadow = true;
    sun.shadow.mapSize.set(1536, 1536);
    sun.shadow.camera.near = 1;
    sun.shadow.camera.far = 220;
    const d = 58;
    sun.shadow.camera.left = -d;
    sun.shadow.camera.right = d;
    sun.shadow.camera.top = d;
    sun.shadow.camera.bottom = -d;
    sun.shadow.bias = -0.0006;
    sun.shadow.normalBias = 0.04;
    scene.add(sun, sun.target, this.hemi);

    const flash = { value: new THREE.Vector4(0, 0, 0, 0) };
    const layer = (geo: THREE.BufferGeometry, vertexShader: string, fragmentShader: string, uniforms: Record<string, THREE.IUniform>, order: number) => {
      const mat = new THREE.ShaderMaterial({ vertexShader, fragmentShader, uniforms: { ...THREE.UniformsUtils.clone(THREE.UniformsLib.fog), ...uniforms, uFlash: flash }, fog: true, depthWrite: false, side: THREE.BackSide });
      const m = new THREE.Mesh(geo, mat);
      m.frustumCulled = false;
      m.renderOrder = order;
      m.matrixAutoUpdate = true;
      scene.add(m);
      return m;
    };
    // 半球（只画地平线以上一点，地平线以下本来就被地面盖住）；画在不透明物体的最后，被挡住的像素早早被深度测试丢掉
    this.sky = layer(new THREE.SphereGeometry(SKY_R, 24, 8, 0, Math.PI * 2, 0, Math.PI / 2 + 0.06), SKY_VERT, SKY_FRAG, {
      uZenith: { value: new THREE.Color() },
      uWarm: { value: new THREE.Color() },
      uStorm: { value: 0 },
      uTime: { value: 0 },
      uBolt: { value: new THREE.Vector4() },
      uStormDark: { value: new THREE.Color(STORM_SKY.dark) },
      uStormLite: { value: new THREE.Color(STORM_SKY.lite) },
      uSat: { value: new THREE.Vector4() },
      uSatFx: { value: new THREE.Vector4(0, 0, 0, 0.06) },
      uCloud: { value: 0 },
    }, 100);
    const ringGeo = new THREE.CylinderGeometry(RING_R, RING_R, RING_H, 128, 1, true);
    ringGeo.translate(0, RING_H / 2 - 1, 0);
    this.ring = layer(ringGeo, RING_VERT, RING_FRAG, { uStyleA: { value: 0 }, uStyleB: { value: 0 }, uMix: { value: 0 }, uShade: SKYLINE.color, uRim: { value: new THREE.Color() }, uTime: { value: 0 } }, RING_ORDER);
    // 余烟要叠在天上（半透明），剪影本身照旧是不透明的
    this.ring.material.transparent = true;
    this.apply(1);
  }

  set(theme: Theme, instant = false): void {
    if (instant) {
      this.from = this.to = theme;
      this.t = 1;
      this.apply(1);
      return;
    }
    if (theme === this.to) return;
    this.from = this.to;
    this.to = theme;
    this.t = 0;
  }

  /** 没被放平视角推远的雾终点（核弹判定「屏幕上的敌人」用这个，T017-2A：固定按主题的雾，不跟着视角变） */
  get baseFar(): number {
    return this.far;
  }

  /**
   * camera = 天空 / 天际线跟着它走；tilt = 镜头现在的俯仰（CameraRig.tiltNow，−1 = ▲▲ 放平），放平时雾推远；combat = 在作战（天边才闪炮火）
   */
  /** 终极的氛围（T021-b 压暗 → T057 Mood）：want = 要到的，now = 现在的（fade 秒进出）；主雷让曝光 / 天光闪几下（不改主题） */
  private readonly want: Mood = { ...CALM };
  private readonly now: Mood = { ...CALM };
  private readonly tintC = new THREE.Color(1, 1, 1);
  private readonly tintW = new THREE.Color(1, 1, 1);
  private readonly fogC = new THREE.Color(1, 1, 1);
  private readonly fogW = new THREE.Color(1, 1, 1);
  private readonly skyDarkW = new THREE.Color(STORM_SKY.dark);
  private readonly skyLiteW = new THREE.Color(STORM_SKY.lite);
  private dimRate = 2;
  private boltT = 0;
  private boltDur = 0.1;
  private boltK = 1;
  private boltN = 1;
  private baseSun = 2.5;
  private baseHemi = 1;
  private baseExp = 1.05;
  /** 黄昏的天染多少（T122：0 平时 / 1 沙漠油井，换区时跟着过渡） */
  private duskK = 0;
  /** 主题过渡后的太阳 / 天光 / 雾色（氛围在它们上面染色） */
  private readonly baseSunC = new THREE.Color();
  private readonly baseHemiC = new THREE.Color();
  private readonly baseFogC = new THREE.Color();

  /** 只压暗光照 / 曝光（首领亮相、老调用），别的氛围不动 */
  dim(light: number, exposure: number, fade = 0.5): void {
    this.want.light = light;
    this.want.exposure = exposure;
    this.dimRate = 1 / Math.max(0.05, fade);
  }

  /** 终极的整套氛围（T057）：没给的项回到平时；null = 全部回到平时；fade 秒过渡 */
  mood(m: Partial<Mood> | null, fade = 0.5): void {
    Object.assign(this.want, CALM, m ?? {});
    this.tintW.setHex(this.want.tint);
    this.fogW.setHex(this.want.fog);
    this.skyDarkW.setHex(this.want.skyDark);
    this.skyLiteW.setHex(this.want.skyLite);
    this.dimRate = 1 / Math.max(0.05, fade);
  }

  /** 天上那一片云被闪电照亮（T057 雷云）：dx / dz = 从镜头看过去的方向，k = 亮度（自己很快退掉） */
  skyBolt(dx: number, dz: number, k: number): void {
    const b = this.sky.material.uniforms.uBolt.value as THREE.Vector4;
    b.x = Math.atan2(dx, -dz);
    b.y = Math.max(b.y, k);
  }

  /**
   * 天火的卫星炮（T060）：在世界坐标 (x, y, z)、半径约 size 米（环半径的两倍多）的地方，天幕上画一个云里的背光剪影；
   * vis = 能见度、charge = 充能（光晕 / 透镜）、fire = 开火闪光（0..1）、ring = 云里那圈光扫到多远（剪影半径的几倍）；null = 收掉
   */
  satellite(s: SatView | null): void {
    if (!s) {
      this.sat = null;
      (this.sky.material.uniforms.uSat.value as THREE.Vector4).w = 0;
      return;
    }
    this.sat = s;
  }

  /** 远景巨炮开炮：正前方天边亮一大团火（天空 / 天际线上的暖光；T032 起天边那门炮是真模型 SiegeProxy，原来天际线着色器画的剪影删了） */
  gunFlash(): void {
    const f = this.sky.material.uniforms.uFlash.value as THREE.Vector4;
    f.x = 0.01;
    this.flashT = FLASH.dur * 1.6;
    this.flashGap = Math.max(this.flashGap, 3);
  }

  /** 一道主雷：曝光闪到 k 倍，t 秒退回；flicker = 这 t 秒里闪几下（T057：真的闪电是「啪—啪」两三下，后面一下比一下弱），天光跟着亮 */
  boltFlash(k = 1.15, t = 0.08, flicker = 1): void {
    if (this.boltT > 0 && k < this.boltK) return;
    this.boltK = k;
    this.boltT = this.boltDur = t;
    this.boltN = Math.max(1, flicker);
  }

  /** 闪电这一刻的倍率（亮的那半段 k，后面一下比一下弱；两下之间退到一成多） */
  private boltMul(): number {
    if (this.boltT <= 0) return 1;
    const seg = this.boltDur / this.boltN;
    const e = this.boltDur - this.boltT;
    const i = Math.min(this.boltN - 1, Math.floor(e / seg));
    return 1 + (this.boltK - 1) * (e - i * seg < seg * 0.5 ? 0.72 ** i : 0.12);
  }

  private applyLight(): void {
    const n = this.now;
    const flash = this.boltMul();
    this.sun.intensity = this.baseSun * n.light;
    this.sun.color.copy(this.baseSunC).lerp(this.tintC, n.tintK);
    // 闪电照亮整片战场：天光跟着亮（比曝光更明显，阴影里也亮）
    this.hemi.intensity = this.baseHemi * n.light * (1 + (flash - 1) * 2.5);
    this.hemi.color.copy(this.baseHemiC).lerp(this.tintC, n.tintK);
    this.renderer.toneMappingExposure = this.baseExp * n.exposure * flash;
    this.sun.shadow.intensity = n.shadow;
    this.fog.color.copy(this.baseFogC).lerp(this.fogC, n.fogK);
    (this.scene.background as THREE.Color).copy(this.fog.color);
    // 天空：头顶 = 雾色往天光色（蓝灰）靠一半、略压暗；地平线上方的亮带 = 雾色提亮偏暖
    const su = this.sky.material.uniforms;
    (su.uZenith.value as THREE.Color).copy(this.fog.color).lerp(this.baseHemiC, 0.6).multiplyScalar(0.86);
    (su.uWarm.value as THREE.Color).copy(this.fog.color).multiplyScalar(1.05).lerp(this.ca.setRGB(1, 0.84, 0.64), 0.14);
    // 黄昏（T122）：天顶压成深蓝紫、地平线上方一道橙粉（氛围染的雾色照样叠进来一点）
    if (this.duskK > 0) {
      (su.uZenith.value as THREE.Color).lerp(this.cb.copy(DUSK.zenith).lerp(this.fog.color, n.fogK * 0.5), this.duskK);
      (su.uWarm.value as THREE.Color).lerp(this.cb.copy(DUSK.glow).lerp(this.fog.color, n.fogK * 0.5), this.duskK * 0.85);
    }
    su.uStorm.value = n.storm;
    // 天际线剪影：雾色压暗 + 往地面色偏一点
    (this.ring.material.uniforms.uShade.value as THREE.Color).copy(this.fog.color).multiplyScalar(0.62).lerp(this.hemi.groundColor, 0.2);
    // 剪影顶上的亮边：天边亮带的颜色再提亮一点（T198）
    (this.ring.material.uniforms.uRim.value as THREE.Color).copy(su.uWarm.value as THREE.Color).lerp(this.ca.setRGB(1, 0.95, 0.85), 0.3);
  }

  update(delta: number, focus: THREE.Vector3, camera?: THREE.Camera, tilt = 0, combat = false): void {
    const mk = Math.min(1, delta * 3 * this.dimRate);
    const step = (now: number, want: number) => (Math.abs(want - now) < 1e-3 ? want : now + (want - now) * mk);
    const n = this.now;
    const w = this.want;
    const sd = this.sky.material.uniforms.uStormDark.value as THREE.Color;
    const sl = this.sky.material.uniforms.uStormLite.value as THREE.Color;
    const far = (a: THREE.Color, b: THREE.Color) => Math.abs(a.r - b.r) + Math.abs(a.g - b.g) + Math.abs(a.b - b.b) > 2e-3;
    const skyMoving = w.storm > 0 && (far(sd, this.skyDarkW) || far(sl, this.skyLiteW));
    if (n.light !== w.light || n.exposure !== w.exposure || n.tintK !== w.tintK || n.fogK !== w.fogK || n.storm !== w.storm || n.shadow !== w.shadow || this.boltT > 0 || skyMoving) {
      const clear = n.storm < 1e-3;
      n.light = step(n.light, w.light);
      n.exposure = step(n.exposure, w.exposure);
      n.tintK = step(n.tintK, w.tintK);
      n.fogK = step(n.fogK, w.fogK);
      n.storm = step(n.storm, w.storm);
      n.shadow = step(n.shadow, w.shadow);
      // 颜色：要染色时跟着过去；退回平时（k → 0）时颜色留着，跟着 k 一起淡掉
      if (w.tintK > 0) this.tintC.lerp(this.tintW, mk);
      if (w.fogK > 0) this.fogC.lerp(this.fogW, mk);
      // 天上的云换颜色（雷云的乌云 / 核弹的高空云 → 尘霾）：没云时直接换，有云时跟着过去
      if (clear) {
        sd.copy(this.skyDarkW);
        sl.copy(this.skyLiteW);
      } else if (skyMoving) {
        sd.lerp(this.skyDarkW, mk);
        sl.lerp(this.skyLiteW, mk);
      }
      this.boltT = Math.max(0, this.boltT - delta);
      this.applyLight();
    }
    const su = this.sky.material.uniforms;
    if (n.storm > 0) su.uTime.value += delta;
    // 层云 / 余烟慢慢飘（T198）；数值留在 0～4096 之间，手机精度不塌
    su.uCloud.value = (su.uCloud.value + delta * 0.006) % 64;
    this.ring.material.uniforms.uTime.value = (this.ring.material.uniforms.uTime.value + delta) % 4096;
    const bolt = su.uBolt.value as THREE.Vector4;
    if (bolt.y > 0) bolt.y = bolt.y < 0.01 ? 0 : bolt.y * Math.exp(-delta * 9);
    this.sun.position.set(focus.x + SUN_AT.x, SUN_AT.y, focus.z + SUN_AT.z);
    this.sun.target.position.set(focus.x, 0, focus.z + SUN_AT.tz);
    if (this.t < 1) {
      this.t = Math.min(1, this.t + delta / 4);
      this.apply(this.t * this.t * (3 - 2 * this.t));
    }
    const push = Math.max(0, Math.min(1, -tilt)) * FOG_PUSH;
    if (push !== this.push) {
      this.push = push;
      this.applyFog();
    }
    if (camera) {
      this.sky.position.set(camera.position.x, camera.position.y, camera.position.z);
      this.ring.position.set(camera.position.x, 0, camera.position.z);
      // 卫星炮：天幕按方向画，每帧按镜头位置重算方向和看上去多大（和从它那儿打下来的光柱对得上）
      const s = this.sat;
      if (s) {
        const u = this.sky.material.uniforms;
        const dir = u.uSat.value as THREE.Vector4;
        const dx = s.x - camera.position.x;
        const dy = s.y - camera.position.y;
        const dz = s.z - camera.position.z;
        const dist = Math.hypot(dx, dy, dz) || 1;
        dir.set(dx / dist, dy / dist, dz / dist, s.vis);
        (u.uSatFx.value as THREE.Vector4).set(s.charge, s.fire, s.ring, s.size / dist);
      }
    }
    // 天边炮火：前方 ±70° 里随便一个方向闪一下
    const f = this.sky.material.uniforms.uFlash.value as THREE.Vector4;
    this.flashGap -= delta;
    if (combat && this.flashGap <= 0) {
      this.flashGap = FLASH.gap[0] + Math.random() * (FLASH.gap[1] - FLASH.gap[0]);
      this.flashT = FLASH.dur;
      f.x = (Math.random() - 0.5) * 2.4;
    }
    this.flashT = Math.max(0, this.flashT - delta);
    const k = this.flashT / FLASH.dur;
    f.y = k * k * (0.55 + 0.45 * Math.sin(this.flashT * 40));
  }

  private applyFog(): void {
    this.fog.near = this.near * (1 + this.push);
    this.fog.far = this.far * (1 + this.push);
  }

  private apply(k: number): void {
    const a = this.from;
    const b = this.to;
    const lerpC = (target: THREE.Color, x: number, y: number) => target.copy(this.ca.setHex(x)).lerp(this.cb.setHex(y), k);
    lerpC(this.baseFogC, a.fog, b.fog);
    this.near = a.fogNear + (b.fogNear - a.fogNear) * k;
    this.far = a.fogFar + (b.fogFar - a.fogFar) * k;
    this.applyFog();
    lerpC(this.baseSunC, a.sun, b.sun);
    this.baseSun = a.sunIntensity + (b.sunIntensity - a.sunIntensity) * k;
    lerpC(this.baseHemiC, a.hemiSky, b.hemiSky);
    lerpC(this.hemi.groundColor, a.hemiGround, b.hemiGround);
    this.baseHemi = a.hemiIntensity + (b.hemiIntensity - a.hemiIntensity) * k;
    this.baseExp = a.exposure + (b.exposure - a.exposure) * k;
    this.duskK = (a.dusk ? 1 : 0) + ((b.dusk ? 1 : 0) - (a.dusk ? 1 : 0)) * k;
    // 太阳方位（T122：黄昏压低到左后方，换区时跟着转过去）
    const sa = a.sunAt ?? SUN_NOON;
    const sb = b.sunAt ?? SUN_NOON;
    SUN_AT.x = sa.x + (sb.x - sa.x) * k;
    SUN_AT.y = sa.y + (sb.y - sa.y) * k;
    SUN_AT.z = sa.z + (sb.z - sa.z) * k;
    SUN_AT.tz = sa.tz + (sb.tz - sa.tz) * k;
    // 雾色 / 天空 / 天际线剪影的颜色在 applyLight 里按氛围染（两种剪影跟着雾色一起过渡）
    this.applyLight();
    const ru = this.ring.material.uniforms;
    ru.uStyleA.value = STYLE[a.id];
    ru.uStyleB.value = STYLE[b.id];
    ru.uMix.value = k;
  }
}
