import type { MedalTier, PlateTier } from '../meta/achievements';
import { box, font, icon as paintIcon, shadow, text } from './canvas/paint';

type Ctx = CanvasRenderingContext2D;
import { ICON_SVG } from './icons';

/**
 * 勋章 / 铭牌图形（T018-3 没做的那条，D4 / 汇总第 26 条，策划 `T018-新想法-策划案.md` 5.2 方案 A）：全部程序化、0 图片，两套界面共用一份参数——
 * 勋章 = 12 齿齿轮外圈（铜 / 银 / 金三档金属渐变）+ 深色内盘 + 两根交叉炮管 + 中间的主题图标；没拿到的是灰色剪影。不仿任何真实国家的勋章、不用红五星、不带国旗元素
 * 铭牌 = 拉丝金属底（铁灰 / 钢蓝 / 赤金）+ 四颗铆钉 + 刻字
 * DOM 版用 SVG 字符串（medalSvg / plateHtml），画布版直接画（paintMedal / paintPlate）
 */
export const MEDAL_METAL: Record<MedalTier, { hi: string; mid: string; lo: string; face: string; ink: string }> = {
  // 铁 / 鎏金（T030 累计勋章的头尾两档）
  iron: { hi: '#c4c8cc', mid: '#7e8288', lo: '#3e4248', face: '#22252a', ink: '#e4e8ec' },
  gilt: { hi: '#fff8d0', mid: '#f4c444', lo: '#b4720e', face: '#4a300a', ink: '#fff6c8' },
  bronze: { hi: '#f0b37a', mid: '#b8743c', lo: '#6a3c1c', face: '#3a2416', ink: '#ffd2a0' },
  silver: { hi: '#f4f6f8', mid: '#a8b0b8', lo: '#5a626a', face: '#262c32', ink: '#eef4fa' },
  gold: { hi: '#fff0a8', mid: '#e0b048', lo: '#8a6018', face: '#3a2a0c', ink: '#fff0b0' },
};
const GRAY = { hi: '#6a6e74', mid: '#4a4e54', lo: '#2a2d32', face: '#1e2024', ink: '#7a7e86' };
export const PLATE_METAL: Record<PlateTier, { hi: string; lo: string; ink: string; rivet: string }> = {
  iron: { hi: '#8a8e94', lo: '#4a4e54', ink: '#1a1c20', rivet: '#c8ccd2' },
  steel: { hi: '#9cc0e0', lo: '#3e6488', ink: '#0e1a26', rivet: '#d8ecff' },
  gold: { hi: '#f4c870', lo: '#a0522a', ink: '#2a1206', rivet: '#fff0c0' },
};

/** 12 齿齿轮外圈的顶点（单位圆，齿顶 1、齿根 0.86） */
function gearPts(n = 12): [number, number][] {
  const pts: [number, number][] = [];
  for (let i = 0; i < n; i++) {
    const a0 = (i / n) * Math.PI * 2;
    const step = (Math.PI * 2) / n;
    for (const [f, r] of [[0, 0.86], [0.18, 1], [0.5, 1], [0.68, 0.86]] as const) pts.push([Math.cos(a0 + f * step), Math.sin(a0 + f * step)].map((v) => v * r) as [number, number]);
  }
  return pts;
}
const GEAR = gearPts();

let uid = 0;
/** DOM 版勋章（size 像素见方）：齿轮外圈渐变 + 内盘 + 交叉炮管 + 中间图标 */
export function medalSvg(tier: MedalTier, iconId: string, got: boolean, size = 30): string {
  const m = got ? MEDAL_METAL[tier] : GRAY;
  const id = `md${uid++}`;
  const gear = GEAR.map(([x, y], i) => `${i ? 'L' : 'M'}${(12 + x * 11.5).toFixed(2)} ${(12 + y * 11.5).toFixed(2)}`).join('') + 'Z';
  const barrels = [-1, 1].map((s) => `<rect x="11" y="3.2" width="2" height="17.6" rx="0.8" fill="${m.lo}" stroke="${m.hi}" stroke-width="0.4" transform="rotate(${s * 42} 12 12)"/>`).join('');
  const body = ICON_SVG[iconId] ?? ICON_SVG.main ?? '';
  return `<svg class="medal-g" width="${size}" height="${size}" viewBox="0 0 24 24"><defs><linearGradient id="${id}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${m.hi}"/><stop offset="0.5" stop-color="${m.mid}"/><stop offset="1" stop-color="${m.lo}"/></linearGradient></defs><path d="${gear}" fill="url(#${id})" stroke="${m.lo}" stroke-width="0.5"/><circle cx="12" cy="12" r="8.4" fill="${m.face}" stroke="${m.hi}" stroke-width="0.6"/>${barrels}<circle cx="12" cy="12" r="5.4" fill="${m.face}" stroke="${m.mid}" stroke-width="0.5"/><g transform="translate(7.2 7.2) scale(0.4)" fill="none" stroke="${m.ink}" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">${body}</g></svg>`;
}

/** DOM 版铭牌：拉丝金属底 + 四颗铆钉 + 刻字（样式在 styles.css 的 .plate） */
export function plateHtml(tier: PlateTier, name: string): string {
  return `<span class="plate ${tier}">${name}</span>`;
}

/** 画布版勋章：圆心 (cx, cy)、半径 r */
export function paintMedal(ctx: Ctx, cx: number, cy: number, r: number, tier: MedalTier, iconId: string, got: boolean): void {
  const m = got ? MEDAL_METAL[tier] : GRAY;
  ctx.save();
  const g = ctx.createLinearGradient(cx - r, cy - r, cx + r, cy + r);
  g.addColorStop(0, m.hi);
  g.addColorStop(0.5, m.mid);
  g.addColorStop(1, m.lo);
  ctx.beginPath();
  GEAR.forEach(([x, y], i) => (i ? ctx.lineTo(cx + x * r, cy + y * r) : ctx.moveTo(cx + x * r, cy + y * r)));
  ctx.closePath();
  ctx.fillStyle = g;
  ctx.fill();
  ctx.lineWidth = Math.max(0.5, r * 0.04);
  ctx.strokeStyle = m.lo;
  ctx.stroke();
  const disc = (rr: number, fill: string, stroke: string) => {
    ctx.beginPath();
    ctx.arc(cx, cy, r * rr, 0, Math.PI * 2);
    ctx.fillStyle = fill;
    ctx.fill();
    ctx.strokeStyle = stroke;
    ctx.stroke();
  };
  disc(0.73, m.face, m.hi);
  // 交叉炮管
  for (const s of [-1, 1]) {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate((s * 42 * Math.PI) / 180);
    box(ctx, -r * 0.087, -r * 0.77, r * 0.174, r * 1.53, r * 0.07, m.lo, m.hi, Math.max(0.4, r * 0.035));
    ctx.restore();
  }
  disc(0.47, m.face, m.mid);
  paintIcon(ctx, iconId, cx - r * 0.42, cy - r * 0.42, r * 0.84, m.ink, 2.2);
  ctx.restore();
}

/** 画布版铭牌：拉丝金属底 + 四颗铆钉 + 刻字，返回宽度 */
export function paintPlate(ctx: Ctx, x: number, y: number, h: number, tier: PlateTier, name: string, size = 12): number {
  const p = PLATE_METAL[tier];
  ctx.save();
  ctx.font = font(size, 900);
  const w = ctx.measureText(name).width + h * 1.4;
  const g = ctx.createLinearGradient(x, y, x, y + h);
  g.addColorStop(0, p.hi);
  g.addColorStop(0.55, p.lo);
  g.addColorStop(1, p.hi);
  box(ctx, x, y, w, h, 3, g, 'rgba(0, 0, 0, 0.5)');
  // 拉丝：几道很淡的横线
  ctx.globalAlpha = 0.18;
  ctx.fillStyle = '#ffffff';
  for (let i = 2; i < h - 1; i += 3) ctx.fillRect(x + 2, y + i, w - 4, 0.6);
  ctx.globalAlpha = 1;
  ctx.fillStyle = p.rivet;
  for (const [rx, ry] of [[x + 3.5, y + 3.5], [x + w - 3.5, y + 3.5], [x + 3.5, y + h - 3.5], [x + w - 3.5, y + h - 3.5]]) {
    ctx.beginPath();
    ctx.arc(rx, ry, 1.3, 0, Math.PI * 2);
    ctx.fill();
  }
  shadow(ctx, 'rgba(255, 255, 255, 0.35)', 0, 1);
  text(ctx, name, x + w / 2, y + h / 2, p.ink, 'center', 1);
  ctx.restore();
  return w;
}

/**
 * 军衔肩章（T030）：40 × 20 横放的一块肩章（一头尖、尖头一颗扣子），按军衔分五档——
 * 士（1～6 级）橄榄布 + 竖杠（列兵没有）/ 尉（7～10）钢蓝布 + 一道金线 + 菱形小钉 / 校（11～14）铜褐布 + 两道金线 + 菱形 /
 * 将（15～19）金色布 + 银菱形 / 元帅（20）金色布 + 齿轮章。不仿任何真实国家的军衔、不用五角星
 */
interface BoardLook {
  cloth: [string, string];
  edge: string;
  rails: number;
  pips: number;
  pip: string;
  bars: number;
  gear: boolean;
}
function boardLook(level: number): BoardLook {
  if (level <= 6) return { cloth: ['#6a7448', '#48502e'], edge: '#2a3018', rails: 0, pips: 0, pip: '#e8dca0', bars: level - 1, gear: false };
  if (level <= 10) return { cloth: ['#4e6480', '#2e3e52'], edge: '#1a2432', rails: 1, pips: level - 6, pip: '#ffd98a', bars: 0, gear: false };
  if (level <= 14) return { cloth: ['#7a5c3a', '#4a3420'], edge: '#2a1c10', rails: 2, pips: level - 10, pip: '#ffd98a', bars: 0, gear: false };
  if (level <= 19) return { cloth: ['#f0cc6a', '#a87820'], edge: '#5a3c0c', rails: 0, pips: level - 14, pip: '#eef4fa', bars: 0, gear: false };
  return { cloth: ['#ffe08a', '#b8862a'], edge: '#5a3c0c', rails: 0, pips: 0, pip: '#fff4c0', bars: 0, gear: true };
}
const BOARD_PATH = 'M2 3 Q2 2 3 2 H31 L38 10 L31 18 H3 Q2 18 2 17 Z';
/** 小钉 / 竖杠的位置（40 × 20 坐标） */
function boardMarks(L: BoardLook): { pips: [number, number][]; bars: number[] } {
  const pips: [number, number][] = [];
  for (let i = 0; i < L.pips; i++) pips.push([8 + i * (L.pips > 4 ? 4.6 : 5.6), 10]);
  const bars: number[] = [];
  for (let i = 0; i < L.bars; i++) bars.push(7 + i * 4.4);
  return { pips, bars };
}

/** DOM 版肩章（宽 size、高 size / 2） */
export function boardSvg(level: number, size = 40): string {
  const L = boardLook(level);
  const id = `bd${uid++}`;
  const m = boardMarks(L);
  const rails = L.rails === 1 ? '<path d="M3 10H30" stroke="#d9b45a" stroke-width="1.1"/>' : L.rails === 2 ? '<path d="M3 7H30M3 13H30" stroke="#d9b45a" stroke-width="1"/>' : '';
  const pips = m.pips.map(([x, y]) => `<path d="M${x} ${y - 2.4}L${x + 2} ${y}L${x} ${y + 2.4}L${x - 2} ${y}Z" fill="${L.pip}" stroke="rgba(0,0,0,0.45)" stroke-width="0.4"/>`).join('');
  const bars = m.bars.map((x) => `<rect x="${x}" y="4.5" width="1.8" height="11" rx="0.5" fill="${L.pip}"/>`).join('');
  const gear = L.gear ? `<g transform="translate(16 10)"><path d="${GEAR.map(([x, y], i) => `${i ? 'L' : 'M'}${(x * 6).toFixed(2)} ${(y * 6).toFixed(2)}`).join('')}Z" fill="#7a5410" stroke="#fff0b0" stroke-width="0.5"/><circle r="2.4" fill="#ffe08a"/></g><path d="M5 15 Q9 4 14 5M27 15 Q23 4 18 5" fill="none" stroke="#7a5410" stroke-width="1.1"/>` : '';
  return `<svg class="board-g" width="${size}" height="${size / 2}" viewBox="0 0 40 20"><defs><linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${L.cloth[0]}"/><stop offset="1" stop-color="${L.cloth[1]}"/></linearGradient></defs><path d="${BOARD_PATH}" fill="url(#${id})" stroke="${L.edge}" stroke-width="1"/>${rails}${bars}${pips}${gear}<circle cx="33" cy="10" r="2" fill="${L.pip}" stroke="${L.edge}" stroke-width="0.6"/></svg>`;
}

/** 画布版肩章：左上角 (x, y)，宽 w（高 w / 2） */
export function paintBoard(ctx: Ctx, x: number, y: number, w: number, level: number): void {
  const L = boardLook(level);
  const k = w / 40;
  const m = boardMarks(L);
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(k, k);
  const g = ctx.createLinearGradient(0, 0, 0, 20);
  g.addColorStop(0, L.cloth[0]);
  g.addColorStop(1, L.cloth[1]);
  ctx.beginPath();
  ctx.moveTo(2, 3);
  ctx.quadraticCurveTo(2, 2, 3, 2);
  ctx.lineTo(31, 2);
  ctx.lineTo(38, 10);
  ctx.lineTo(31, 18);
  ctx.lineTo(3, 18);
  ctx.quadraticCurveTo(2, 18, 2, 17);
  ctx.closePath();
  ctx.fillStyle = g;
  ctx.fill();
  ctx.lineWidth = 1;
  ctx.strokeStyle = L.edge;
  ctx.stroke();
  ctx.strokeStyle = '#d9b45a';
  for (const ry of L.rails === 1 ? [10] : L.rails === 2 ? [7, 13] : []) {
    ctx.beginPath();
    ctx.moveTo(3, ry);
    ctx.lineTo(30, ry);
    ctx.stroke();
  }
  ctx.fillStyle = L.pip;
  for (const bx of m.bars) ctx.fillRect(bx, 4.5, 1.8, 11);
  for (const [px, py] of m.pips) {
    ctx.beginPath();
    ctx.moveTo(px, py - 2.4);
    ctx.lineTo(px + 2, py);
    ctx.lineTo(px, py + 2.4);
    ctx.lineTo(px - 2, py);
    ctx.closePath();
    ctx.fill();
  }
  if (L.gear) {
    ctx.beginPath();
    GEAR.forEach(([gx, gy], i) => (i ? ctx.lineTo(16 + gx * 6, 10 + gy * 6) : ctx.moveTo(16 + gx * 6, 10 + gy * 6)));
    ctx.closePath();
    ctx.fillStyle = '#7a5410';
    ctx.fill();
    ctx.beginPath();
    ctx.arc(16, 10, 2.4, 0, Math.PI * 2);
    ctx.fillStyle = '#ffe08a';
    ctx.fill();
  }
  ctx.beginPath();
  ctx.arc(33, 10, 2, 0, Math.PI * 2);
  ctx.fillStyle = L.pip;
  ctx.fill();
  ctx.restore();
}
