import * as THREE from 'three';
import { CRATER_GLSL, WATER_GLSL, type CraterUniforms } from '../world/Craters';
import { subDecalAtlas } from './textures';
import type { Quality } from './Post';
import { SUB_PC, SUB_Q } from '../weapons/subTiers';

/** 留痕图集的帧（textures.subDecalAtlas） */
export const SubMark = { Hole: 0, Vein: 1, Fan: 2, Ring: 3, Strip: 4, Blob: 5, Shadow: 6, Embers: 7 } as const;
export type SubMark = (typeof SubMark)[keyof typeof SubMark];

// 留痕：淡出、发光边冷却全在着色器里按时间算（加的时候上传一次，之后每帧只改 uTime）；身后 70 米外不画
const DECAL_VERT = /* glsl */ `
${CRATER_GLSL}
attribute vec4 iXf;   // x, z, 转角, 帧
attribute vec4 iSz;   // 宽, 长, 浓度, 出生时刻
attribute vec2 iLf;   // 寿命, 发光边冷却秒数
attribute vec3 iGlow; // 发光边颜色
uniform float uTime;
uniform float uBehind;
varying vec2 vUv;
varying float vA;
varying float vHeat;
varying vec3 vGlow;
varying vec2 vWorldXZ;
#include <fog_pars_vertex>
void main() {
  float age = uTime - iSz.w;
  float life = iLf.x;
  vA = iSz.z * clamp((life - age) / (0.3 * life), 0.0, 1.0) * step(0.0, age) * step(iXf.y, uBehind);
  vHeat = iLf.y > 0.0 ? pow(clamp(1.0 - age / iLf.y, 0.0, 1.0), 1.5) : 0.0;
  vGlow = iGlow;
  vec2 p = position.xy * iSz.xy;
  float c = cos(iXf.z);
  float s = sin(iXf.z);
  vec4 world = vec4(iXf.x + p.x * c - p.y * s, 0.07, iXf.y + p.x * s + p.y * c, 1.0);
  world.y += floorH(world.xz);
  vWorldXZ = world.xz;
  vec4 mvPosition = viewMatrix * world;
  gl_Position = vA <= 0.0 ? vec4(2.0, 2.0, 2.0, 1.0) : projectionMatrix * mvPosition;
  vUv = vec2((uv.x + mod(iXf.w, 4.0)) * 0.25, (uv.y + floor(iXf.w / 4.0)) * 0.5);
  #include <fog_vertex>
}`;

const DECAL_FRAG = /* glsl */ `
${WATER_GLSL}
uniform sampler2D map;
varying vec2 vUv;
varying float vA;
varying float vHeat;
varying vec3 vGlow;
varying vec2 vWorldXZ;
#include <fog_pars_fragment>
void main() {
  if (waterH(vWorldXZ) > -999.0) discard;
  vec4 t = texture2D(map, vUv);
  float glow = t.r * vHeat;
  float a = max(t.a, glow * 0.9) * vA;
  if (a < 0.004) discard;
  vec3 col = vec3(0.075, 0.065, 0.055) * (0.75 + 0.5 * t.g) + vGlow * glow * 1.7;
  gl_FragColor = vec4(col, a);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
  #include <fog_fragment>
}`;

/** 副武器留痕池（弹孔 / 电灼纹 / 扇形焦痕 / 冲击环 / 轰炸线 / 掠影）：环形覆盖，1 次绘制（池空的时候不画） */
class SubDecals {
  readonly mesh: THREE.Mesh;
  private head = 0;
  private live = 0;
  private readonly aXf: THREE.InstancedBufferAttribute;
  private readonly aSz: THREE.InstancedBufferAttribute;
  private readonly aLf: THREE.InstancedBufferAttribute;
  private readonly aGlow: THREE.InstancedBufferAttribute;
  private readonly geometry: THREE.InstancedBufferGeometry;
  private readonly u: { uTime: { value: number }; uBehind: { value: number } };
  private readonly c = new THREE.Color();

  constructor(scene: THREE.Scene, craters: CraterUniforms, readonly cap: number) {
    this.limit = cap;
    const base = new THREE.PlaneGeometry(1, 1, 3, 3);
    const geo = new THREE.InstancedBufferGeometry();
    geo.index = base.index;
    geo.setAttribute('position', base.getAttribute('position'));
    geo.setAttribute('uv', base.getAttribute('uv'));
    const attr = (n: number) => new THREE.InstancedBufferAttribute(new Float32Array(cap * n), n).setUsage(THREE.DynamicDrawUsage);
    this.aXf = attr(4);
    this.aSz = attr(4);
    this.aLf = attr(2);
    this.aGlow = attr(3);
    geo.setAttribute('iXf', this.aXf);
    geo.setAttribute('iSz', this.aSz);
    geo.setAttribute('iLf', this.aLf);
    geo.setAttribute('iGlow', this.aGlow);
    geo.instanceCount = 0;
    this.geometry = geo;
    this.u = { uTime: { value: 0 }, uBehind: { value: 1e9 } };
    const mat = new THREE.ShaderMaterial({
      vertexShader: DECAL_VERT,
      fragmentShader: DECAL_FRAG,
      uniforms: { ...THREE.UniformsUtils.merge([THREE.UniformsLib.fog, { map: { value: null } }]), ...craters, ...this.u },
      transparent: true,
      depthWrite: false,
      fog: true,
      side: THREE.DoubleSide,
      polygonOffset: true,
      polygonOffsetFactor: -3,
      polygonOffsetUnits: -3,
    });
    mat.uniforms.map.value = subDecalAtlas();
    this.mesh = new THREE.Mesh(geo, mat);
    this.mesh.frustumCulled = false;
    this.mesh.renderOrder = 1;
    this.mesh.visible = false;
    scene.add(this.mesh);
  }

  /** 这一档的同屏上限（≤ cap，策划 4.2：手机高 60 / 电脑 160 / 中 40 / 低 20）：环形覆盖只在前 limit 块里转 */
  private limit: number;
  setLimit(n: number): void {
    this.limit = Math.max(1, Math.min(this.cap, n));
    this.head %= this.limit;
    this.live = Math.min(this.live, this.limit);
    this.geometry.instanceCount = this.live;
  }

  add(frame: SubMark, x: number, z: number, w: number, d: number, rot: number, alpha: number, life: number, cool: number, glow: number): number {
    const i = this.head;
    this.head = (this.head + 1) % this.limit;
    this.live = Math.min(this.limit, this.live + 1);
    (this.aXf.array as Float32Array).set([x, z, rot, frame], i * 4);
    (this.aSz.array as Float32Array).set([w, d, alpha, this.u.uTime.value], i * 4);
    (this.aLf.array as Float32Array).set([Math.max(0.05, life), cool], i * 2);
    this.c.setHex(glow);
    (this.aGlow.array as Float32Array).set([this.c.r, this.c.g, this.c.b], i * 3);
    for (const [a, n] of [[this.aXf, 4], [this.aSz, 4], [this.aLf, 2], [this.aGlow, 3]] as const) {
      a.addUpdateRange(i * n, n);
      a.needsUpdate = true;
    }
    this.geometry.instanceCount = this.live;
    this.mesh.visible = true;
    return i;
  }

  /** 挪一块（轰炸机掠影跟着飞机走） */
  move(i: number, x: number, z: number): void {
    const a = this.aXf.array as Float32Array;
    a[i * 4] = x;
    a[i * 4 + 1] = z;
    this.aXf.addUpdateRange(i * 4, 2);
    this.aXf.needsUpdate = true;
  }

  update(time: number, playerZ: number): void {
    this.u.uTime.value = time;
    this.u.uBehind.value = playerZ + 70;
  }

  clear(): void {
    this.head = 0;
    this.live = 0;
    this.geometry.instanceCount = 0;
    this.mesh.visible = false;
  }

  dispose(): void {
    this.geometry.dispose();
    (this.mesh.material as THREE.Material).dispose();
  }
}

// 光斑（假光）：贴地加色的圆，颜色 / 半径 / 亮度跟着原来那盏光走，只照地面；亮度按时间平方衰减、可以抖
const SPOT_VERT = /* glsl */ `
${CRATER_GLSL}
attribute vec4 iA; // x, z, 半径, 出生时刻
attribute vec4 iB; // r, g, b, 寿命
attribute vec2 iC; // 峰值亮度, 抖动
uniform float uTime;
varying vec2 vP;
varying vec3 vCol;
varying vec2 vWorldXZ;
void main() {
  float age = uTime - iA.w;
  float k = clamp(1.0 - age / iB.w, 0.0, 1.0) * step(0.0, age);
  float fl = 1.0 + iC.y * (sin(uTime * 37.0 + iA.x * 3.1) * 0.6 + sin(uTime * 23.0 + iA.y * 1.7) * 0.4);
  vCol = iB.rgb * iC.x * k * k * fl;
  vP = position.xy * 2.0;
  vec4 world = vec4(iA.x + position.x * iA.z * 2.0, 0.1, iA.y + position.y * iA.z * 2.0, 1.0);
  world.y += floorH(world.xz);
  vWorldXZ = world.xz;
  gl_Position = k <= 0.0 ? vec4(2.0, 2.0, 2.0, 1.0) : projectionMatrix * viewMatrix * world;
}`;
const SPOT_FRAG = /* glsl */ `
${WATER_GLSL}
varying vec2 vP;
varying vec3 vCol;
varying vec2 vWorldXZ;
void main() {
  if (waterH(vWorldXZ) > -999.0) discard;
  float a = 1.0 - length(vP);
  if (a <= 0.0) discard;
  gl_FragColor = vec4(vCol * a * a * a, 1.0);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}`;

/** 光斑池（64 张，1 次绘制，低画质不画）：爆炸 / 放电 / 喷火 / 枪口照亮地面 */
class LightSpots {
  readonly mesh: THREE.Mesh;
  private head = 0;
  private live = 0;
  private readonly aA: THREE.InstancedBufferAttribute;
  private readonly aB: THREE.InstancedBufferAttribute;
  private readonly aC: THREE.InstancedBufferAttribute;
  private readonly geometry: THREE.InstancedBufferGeometry;
  private readonly uTime = { value: 0 };
  private readonly c = new THREE.Color();

  constructor(scene: THREE.Scene, craters: CraterUniforms, readonly cap = 64) {
    const base = new THREE.PlaneGeometry(1, 1, 4, 4);
    const geo = new THREE.InstancedBufferGeometry();
    geo.index = base.index;
    geo.setAttribute('position', base.getAttribute('position'));
    const attr = (n: number) => new THREE.InstancedBufferAttribute(new Float32Array(cap * n), n).setUsage(THREE.DynamicDrawUsage);
    this.aA = attr(4);
    this.aB = attr(4);
    this.aC = attr(2);
    geo.setAttribute('iA', this.aA);
    geo.setAttribute('iB', this.aB);
    geo.setAttribute('iC', this.aC);
    geo.instanceCount = 0;
    this.geometry = geo;
    this.mesh = new THREE.Mesh(
      geo,
      new THREE.ShaderMaterial({ vertexShader: SPOT_VERT, fragmentShader: SPOT_FRAG, uniforms: { ...craters, uTime: this.uTime }, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, side: THREE.DoubleSide }),
    );
    this.mesh.frustumCulled = false;
    this.mesh.renderOrder = 2;
    this.mesh.visible = false;
    scene.add(this.mesh);
  }

  /** 放一张（slot ≥ 0 = 覆盖这一张：跟着走的持续光每帧重放，返回用的是哪一张） */
  put(x: number, z: number, r: number, color: number, life: number, peak: number, flicker: number, slot = -1): number {
    let i = slot;
    if (i < 0) {
      i = this.head;
      this.head = (this.head + 1) % this.cap;
      this.live = Math.min(this.cap, this.live + 1);
    }
    this.c.setHex(color);
    (this.aA.array as Float32Array).set([x, z, r, this.uTime.value], i * 4);
    (this.aB.array as Float32Array).set([this.c.r, this.c.g, this.c.b, life], i * 4);
    (this.aC.array as Float32Array).set([peak, flicker], i * 2);
    for (const [a, n] of [[this.aA, 4], [this.aB, 4], [this.aC, 2]] as const) {
      a.addUpdateRange(i * n, n);
      a.needsUpdate = true;
    }
    this.geometry.instanceCount = this.live;
    this.mesh.visible = true;
    return i;
  }

  update(time: number): void {
    this.uTime.value = time;
  }

  clear(): void {
    this.head = 0;
    this.live = 0;
    this.geometry.instanceCount = 0;
    this.mesh.visible = false;
  }

  dispose(): void {
    this.geometry.dispose();
    (this.mesh.material as THREE.Material).dispose();
  }
}

// 喷火火锥（T198，制作人「火焰喷射器的攻击特效太扁平」）：原来是一横一竖两片扇面，俯视只剩一张平贴的扇形。
// 改成两层套着的锥形火管（外焰 + 内芯，各 1 次绘制、加色）：截面是扁一点的椭圆、越往前越粗、末端往上飘；
// 顶点按时间扭动（火舌一鼓一鼓地往前翻），片元按「视线穿过多厚」给浓淡（正对镜头的中间浓、侧缘薄 → 从哪个角度看都是一团有体积的火），
// 再叠两层往前滚的三维噪声撕出火舌、末端碎开；贴地那一截淡掉（和地面不出硬切线）。哈希不用 sin，手机上不塌
const FLAME_VERT = /* glsl */ `
uniform float uTime;
uniform float uCore;
varying vec2 vUv;
varying vec3 vN;
varying vec3 vV;
varying float vY;
varying vec3 vP;
void main() {
  vUv = uv;
  float t = uv.x;
  float a = uv.y * 6.2832;
  // 火舌一鼓一鼓：沿火锥往前跑的波 + 绕一圈的扭动（内芯幅度小）
  float tt = mod(uTime, 64.0);
  float wob = 1.0 + (0.16 - uCore * 0.08) * t * sin(t * 11.0 - tt * 15.0 + a * 2.0) + 0.08 * t * sin(t * 23.0 - tt * 27.0 - a * 3.0);
  vec3 p = vec3(position.x * wob, position.y * wob, position.z);
  // 末端往上飘（热气上浮）
  p.y += t * t * 0.32;
  vP = vec3(t * 7.0, cos(a) * 1.7, sin(a) * 1.7);
  vec4 wp = modelMatrix * vec4(p, 1.0);
  vY = wp.y;
  vec4 mv = viewMatrix * wp;
  vV = normalize(-mv.xyz);
  vN = normalize(normalMatrix * normal);
  gl_Position = projectionMatrix * mv;
}`;
const FLAME_FRAG = /* glsl */ `
uniform float uTime;
uniform float uAlpha;
uniform float uCore;
uniform vec3 uHot;
uniform vec3 uMid;
uniform vec3 uEdge;
varying vec2 vUv;
varying vec3 vN;
varying vec3 vV;
varying float vY;
varying vec3 vP;
float h3(vec3 p) { p = fract(p * 0.1031); p += dot(p, p.zyx + 31.32); return fract((p.x + p.y) * p.z); }
float n3(vec3 p) {
  vec3 i = floor(p); vec3 f = fract(p); f = f * f * (3.0 - 2.0 * f);
  return mix(mix(mix(h3(i), h3(i + vec3(1, 0, 0)), f.x), mix(h3(i + vec3(0, 1, 0)), h3(i + vec3(1, 1, 0)), f.x), f.y),
             mix(mix(h3(i + vec3(0, 0, 1)), h3(i + vec3(1, 0, 1)), f.x), mix(h3(i + vec3(0, 1, 1)), h3(i + vec3(1, 1, 1)), f.x), f.y), f.z);
}
void main() {
  float t = vUv.x;
  float tt = mod(uTime, 64.0);
  vec3 q = vP;
  float n = n3(q - vec3(tt * 8.0, 0.0, 0.0)) * 0.55 + n3(q * vec3(2.3, 2.2, 2.2) - vec3(tt * 14.0, tt * 0.7, 0.0)) * 0.3 + n3(q * vec3(5.1, 4.6, 4.6) - vec3(tt * 22.0, 0.0, tt)) * 0.15;
  // 视线穿过多厚：正对镜头的中间浓、侧缘薄
  float thick = pow(abs(dot(normalize(vN), normalize(vV))), 1.3);
  // 喷口淡入、末端被噪声撕碎
  float body = smoothstep(0.0, 0.06, t) * (1.0 - smoothstep(0.35 + n * 0.45 - uCore * 0.15, 0.95 - uCore * 0.25, t));
  float tongue = smoothstep(0.32, 0.78, n + (1.0 - t) * (0.42 + uCore * 0.3));
  // 侧缘（视线擦着火管表面）不留轮廓：薄的地方被噪声吃掉，看不出「一层壳」
  float a = body * tongue * thick * smoothstep(0.05, 0.55, thick + n * 0.35 - 0.12) * uAlpha * 1.35;
  // 贴地那一截淡掉
  a *= smoothstep(-0.15, 0.55, vY);
  // 颜色：喷口白热 → 中段橙 → 末端暗红；内芯整体更亮更黄
  vec3 col = mix(uHot, uMid, smoothstep(0.02, 0.22 + uCore * 0.25, t + (1.0 - thick) * 0.3 - n * 0.12));
  col = mix(col, uEdge, smoothstep(0.35, 0.95, t + (1.0 - thick) * 0.35 - n * 0.25) * (1.0 - uCore * 0.6));
  col *= 0.5 + 0.75 * n;
  gl_FragColor = vec4(min(col * a, vec3(0.9)), 1.0);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}`;

/** 一层锥形火管：沿 -Z 长 1（尖在喷口），末端截面半宽 1、半高 1（实际扁度由缩放给），nr 圈 × ns 段 */
function flameTube(nr: number, ns: number): THREE.BufferGeometry {
  const pos: number[] = [];
  const nor: number[] = [];
  const uv: number[] = [];
  const idx: number[] = [];
  for (let i = 0; i <= nr; i++) {
    const t = i / nr;
    // 喷口很细、前三成迅速张开、之后慢慢变粗，末端收一点（火舌碎开的地方不是平口）
    const r = (0.06 + 0.94 * Math.pow(t, 0.62)) * (1 - 0.18 * Math.pow(t, 6));
    for (let j = 0; j <= ns; j++) {
      const u = j / ns;
      const a = u * Math.PI * 2;
      const c = Math.cos(a);
      const s = Math.sin(a);
      pos.push(c * r, s * r, -t);
      nor.push(c, s, 0.35);
      uv.push(t, u);
    }
  }
  for (let i = 0; i < nr; i++) {
    for (let j = 0; j < ns; j++) {
      const a = i * (ns + 1) + j;
      const b = a + ns + 1;
      idx.push(a, b, a + 1, a + 1, b, b + 1);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('normal', new THREE.Float32BufferAttribute(nor, 3));
  g.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  g.setIndex(idx);
  return g;
}

/**
 * 喷火器的火锥（T198 起每一级都有，原来 4 级起才有一层扇面）：外焰 + 内芯两层火管，不喷的那一帧藏起来。
 * 只是画面：射程、张角、伤害判定都在 FlamerWeapon 里，这里只按它给的射程 / 张角摆
 */
class FlameSheet {
  readonly mesh: THREE.Group;
  private readonly outer: THREE.Mesh;
  private readonly inner: THREE.Mesh;
  private readonly uo: Record<string, THREE.IUniform>;
  private readonly ui: Record<string, THREE.IUniform>;
  private readonly geo = flameTube(14, 18);
  private readonly mounts = new Map<number, FlameSheet>();
  private shown = false;

  constructor(private readonly scene: THREE.Scene) {
    const make = (core: number) => {
      const u = { uTime: { value: 0 }, uAlpha: { value: 1 }, uCore: { value: core }, uHot: { value: new THREE.Color() }, uMid: { value: new THREE.Color() }, uEdge: { value: new THREE.Color() } };
      const m = new THREE.Mesh(this.geo, new THREE.ShaderMaterial({ vertexShader: FLAME_VERT, fragmentShader: FLAME_FRAG, uniforms: u, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, side: THREE.DoubleSide }));
      m.frustumCulled = false;
      m.renderOrder = 4;
      return { m, u };
    };
    const o = make(0);
    const i = make(1);
    this.outer = o.m;
    this.inner = i.m;
    this.uo = o.u;
    this.ui = i.u;
    this.inner.scale.set(0.5, 0.55, 0.78);
    this.inner.position.y = -0.05;
    this.mesh = new THREE.Group();
    this.mesh.add(this.outer, this.inner);
    this.mesh.visible = false;
    scene.add(this.mesh);
  }

  /** 重复喷火器各占自己的面片，不覆盖上一件的火锥。 */
  forSlot(slot: number): FlameSheet {
    if (slot === 0) return this;
    let sheet = this.mounts.get(slot);
    if (!sheet) { sheet = new FlameSheet(this.scene); this.mounts.set(slot, sheet); }
    return sheet;
  }

  /** 这一帧在喷：喷口 (x, y, z)、朝向角 ang（0 = -Z）、射程、半张角；颜色三段（芯 / 中段 / 外层）；alpha = 浓淡（1 级淡、5 级 / ★ 满） */
  show(x: number, y: number, z: number, ang: number, range: number, cone: number, core: number, mid: number, edge: number, alpha: number): void {
    this.shown = true;
    const m = this.mesh;
    m.visible = true;
    m.position.set(x, y, z);
    m.rotation.set(0, ang, 0);
    const hw = range * Math.tan(cone) * 0.82;
    m.scale.set(hw, Math.min(hw * 0.42, 2.2 + range * 0.03), range * 0.95);
    for (const [u, k] of [[this.uo, 0.4], [this.ui, 0.5]] as const) {
      (u.uHot.value as THREE.Color).setHex(core);
      (u.uMid.value as THREE.Color).setHex(mid);
      (u.uEdge.value as THREE.Color).setHex(edge);
      u.uAlpha.value = alpha * k;
    }
  }

  update(time: number): void {
    this.uo.uTime.value = time;
    this.ui.uTime.value = time * 1.15 + 7;
    for (const sheet of this.mounts.values()) sheet.update(time);
    if (!this.shown) this.mesh.visible = false;
    this.shown = false;
  }

  clear(): void {
    this.shown = this.mesh.visible = false;
    for (const sheet of this.mounts.values()) sheet.clear();
  }

  dispose(): void {
    for (const sheet of this.mounts.values()) sheet.dispose();
    this.mounts.clear();
    this.mesh.removeFromParent();
    this.geo.dispose();
    (this.outer.material as THREE.Material).dispose();
    (this.inner.material as THREE.Material).dispose();
  }
}

/** 粒子闸门的先后（策划 4.3：到线先砍低档武器的，再砍远的，联动 / 究极的最后砍） */
export const SubPrio = { Low: 0, Normal: 1, Link: 2 } as const;

/**
 * 副武器特效（T143 第 3 / 4 段）：留痕池、光斑池、喷火面片 + 三档画质开关（SUB_Q）+ 闸门。
 * 闸门（策划 2.3 / 4.3）：新加的光粒子 / 烟粒子各一个每秒计数，按画质乘系数，到开始砍的线就按比例往下砍（低档武器的先砍、联动 / 究极的最后）；
 * 离坦克 far 米外的点缀不放；同 0.2 秒内只放 N 个完整大命中，其余只留焦痕；究极释放中 / 首领战中留痕时长减半（busy）
 */
export class SubFx {
  private readonly decals: SubDecals;
  private readonly spots: LightSpots;
  readonly sheet: FlameSheet;
  private time = 0;
  /** 画质档 + 电脑加成（非触屏电脑 + 高画质：粒子 / 留痕多一点，形状、段数、可数的东西两端一样） */
  q: Quality = 'high';
  readonly pc: boolean;
  /** 究极释放中 / 首领战中（Game 每帧写）：留痕时长减半 */
  busy = false;
  /** 坦克在哪（Game 每帧写）：离得远的点缀不放 */
  private tx = 0;
  private tz = 0;
  /** 最近 1 秒新发的光粒子 / 烟粒子数（衰减计数）、最近 0.2 秒放过的完整大命中 */
  private rate = { glow: 0, smoke: 0 };
  private bigs: number[] = [];

  constructor(scene: THREE.Scene, craters: CraterUniforms) {
    this.decals = new SubDecals(scene, craters, 160);
    this.spots = new LightSpots(scene, craters, 64);
    this.sheet = new FlameSheet(scene);
    this.pc = typeof matchMedia === 'function' && matchMedia('(hover: hover) and (pointer: fine) and (min-width: 720px)').matches;
    this.pick();
  }

  /** 这一档的开关表（电脑高画质叠加成；q 变了在 update 里换） */
  cfg: (typeof SUB_Q)['high'] = SUB_Q.high;
  private cfgFor: Quality | null = null;
  private pick(): void {
    if (this.cfgFor === this.q) return;
    this.cfgFor = this.q;
    const c = SUB_Q[this.q];
    this.cfg = this.pc && this.q === 'high' ? { ...c, ...SUB_PC, mul: c.mul * SUB_PC.mul, life: c.life * SUB_PC.life } : c;
    this.decals.setLimit(this.cfg.decals);
  }

  /**
   * 想发 n 个新粒子（kind = 光 / 烟）：按画质乘系数，这一秒的总数过了开始砍的线就按比例往下砍（不等顶满）；
   * prio 低的先砍（低档武器的按 1.3 倍算已经发了多少，联动 / 究极的按 0.75 倍）；返回实际发几个
   */
  allow(n: number, kind: 'glow' | 'smoke' = 'glow', prio: number = SubPrio.Normal): number {
    const c = this.cfg;
    const cap = c[kind];
    const used = this.rate[kind] * (prio === SubPrio.Low ? 1.3 : prio === SubPrio.Link ? 0.75 : 1);
    const k = used < cap * c.cut ? 1 : Math.max(0, (cap - used) / (cap * (1 - c.cut)));
    const out = Math.floor(n * c.mul * k + Math.random() * Math.min(1, k));
    this.rate[kind] += out;
    return out;
  }

  /** (x, z) 离坦克够近、这一档要命中残留（尘柱 / 尘环 / 落点火花 / 余烬 / 麻痹小电弧）：低档没有，far 米外不放 */
  residue(x: number, z: number): boolean {
    const c = this.cfg;
    return c.residue && Math.hypot(x - this.tx, z - this.tz) < c.far;
  }

  /** Game 每帧给坦克位置 */
  tank(x: number, z: number): void {
    this.tx = x;
    this.tz = z;
  }

  /** 这一下能不能放完整大命中（同 0.2 秒最多 cfg.big 个）；不能就放小一号的 */
  big(): boolean {
    const now = this.time;
    this.bigs = this.bigs.filter((t) => now - t < 0.2);
    if (this.bigs.length >= this.cfg.big) return false;
    this.bigs.push(now);
    return true;
  }

  /** 留一块地面痕迹：life 秒（按画质 / 忙的时候减半；keep = 不打折，掠影要跟满整趟）、刚留下时发光边 cool 秒冷却（低画质不发光） */
  mark(frame: SubMark, x: number, z: number, w: number, d: number, rot: number, life: number, cool = 0, glow = 0xff6a20, alpha = 0.85, keep = false): number {
    const c = this.cfg;
    const l = keep ? life : life * c.life * (this.busy ? 0.5 : 1);
    if (l <= 0.05) return -1;
    return this.decals.add(frame, x, z, w, d, rot, alpha, l, c.glowEdge ? cool * c.life : 0, glow);
  }

  moveMark(i: number, x: number, z: number): void {
    if (i >= 0) this.decals.move(i, x, z);
  }

  /** 光斑（假光）：低画质不放；亮度压到 0.55 倍再封顶 0.5（副武器的光不抢主武器，策划 2.3 第 3 条）；slot = 跟着走的那一张（持续光每帧重放），返回用的哪一张 */
  spot(x: number, z: number, r: number, color: number, life: number, peak: number, flicker = 0, slot = -1): number {
    if (!this.cfg.spots) return -1;
    return this.spots.put(x, z, r, color, life, Math.min(peak * 0.55, 0.5), flicker, slot);
  }

  update(delta: number, playerZ: number): void {
    this.pick();
    this.time += delta;
    const k = Math.max(0, 1 - delta);
    this.rate.glow *= k;
    this.rate.smoke *= k;
    this.decals.update(this.time, playerZ);
    this.spots.update(this.time);
    this.sheet.update(this.time);
  }

  clear(): void {
    this.decals.clear();
    this.spots.clear();
    this.sheet.clear();
    this.rate.glow = this.rate.smoke = 0;
    this.bigs.length = 0;
  }

  dispose(): void {
    this.decals.dispose();
    this.spots.dispose();
    this.sheet.dispose();
  }
}
