import * as THREE from 'three';
import type { PartSpec } from './GeoCache';

/**
 * 程序化建模工具：棱台（倾斜装甲）、车床体（炮管/车轮）、岩石变形等。
 * 产出的几何体都是非索引的，可直接交给 GeoCache.merged 合并。
 */

export type V2 = [number, number];
export type V3 = [number, number, number];

/**
 * 棱台：底面多边形 bottom（y = y0）到顶面多边形 top（y = y0 + h），点为 [x, z]，逆时针（俯视）。
 * 顶点数必须相同。用来做倾斜的车体、炮塔、碉堡。
 */
export function frustum(bottom: V2[], top: V2[], h: number, y0 = 0): THREE.BufferGeometry {
  const pos: number[] = [];
  const uv: number[] = [];
  const n = bottom.length;
  const push = (p: V3, u: number, v: number) => {
    pos.push(p[0], p[1], p[2]);
    uv.push(u, v);
  };
  const B = (i: number): V3 => [bottom[i][0], y0, bottom[i][1]];
  const T = (i: number): V3 => [top[i][0], y0 + h, top[i][1]];
  let perim = 0;
  for (let i = 0; i < n; i++) {
    const j = (i + 1) % n;
    const len = Math.hypot(bottom[j][0] - bottom[i][0], bottom[j][1] - bottom[i][1]);
    const u0 = perim / 4;
    const u1 = (perim + len) / 4;
    perim += len;
    // 侧面两个三角形（外法线朝外：俯视逆时针 → 侧面顺序 b_i, t_i, b_j）
    push(B(i), u0, 0); push(B(j), u1, 0); push(T(i), u0, h / 4);
    push(T(i), u0, h / 4); push(B(j), u1, 0); push(T(j), u1, h / 4);
  }
  // 顶面 / 底面扇形
  for (let i = 1; i < n - 1; i++) {
    push(T(0), top[0][0] / 4, top[0][1] / 4); push(T(i + 1), top[i + 1][0] / 4, top[i + 1][1] / 4); push(T(i), top[i][0] / 4, top[i][1] / 4);
    push(B(0), bottom[0][0] / 4, bottom[0][1] / 4); push(B(i), bottom[i][0] / 4, bottom[i][1] / 4); push(B(i + 1), bottom[i + 1][0] / 4, bottom[i + 1][1] / 4);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  g.computeVertexNormals();
  fixWinding(g);
  return g;
}

/** 确保三角形外法线朝外（以几何中心为参照），避免手写顶点顺序出错导致面被剔除 */
function fixWinding(g: THREE.BufferGeometry): void {
  const p = g.getAttribute('position') as THREE.BufferAttribute;
  g.computeBoundingBox();
  const c = new THREE.Vector3();
  g.boundingBox!.getCenter(c);
  const a = new THREE.Vector3();
  const b = new THREE.Vector3();
  const d = new THREE.Vector3();
  const nrm = new THREE.Vector3();
  const mid = new THREE.Vector3();
  for (let i = 0; i < p.count; i += 3) {
    a.fromBufferAttribute(p, i);
    b.fromBufferAttribute(p, i + 1);
    d.fromBufferAttribute(p, i + 2);
    nrm.subVectors(b, a).cross(mid.subVectors(d, a));
    mid.copy(a).add(b).add(d).multiplyScalar(1 / 3).sub(c);
    if (nrm.dot(mid) < 0) {
      // 交换 b、d
      p.setXYZ(i + 1, d.x, d.y, d.z);
      p.setXYZ(i + 2, b.x, b.y, b.z);
    }
  }
  g.computeVertexNormals();
}

/** 矩形 → 多边形点（中心在原点） */
export function rect(w: number, d: number, cx = 0, cz = 0): V2[] {
  return [
    [cx - w / 2, cz - d / 2],
    [cx - w / 2, cz + d / 2],
    [cx + w / 2, cz + d / 2],
    [cx + w / 2, cz - d / 2],
  ];
}

/** 倒角矩形（八边形），做铸造炮塔、碉堡 */
export function chamfer(w: number, d: number, c: number, cx = 0, cz = 0): V2[] {
  const x = w / 2;
  const z = d / 2;
  return [
    [cx - x + c, cz - z], [cx - x, cz - z + c], [cx - x, cz + z - c], [cx - x + c, cz + z],
    [cx + x - c, cz + z], [cx + x, cz + z - c], [cx + x, cz - z + c], [cx + x - c, cz - z],
  ];
}

/** 侧面轮廓（z-y 平面）沿 x 方向拉伸成实体：倾斜首上装甲、车尾等 */
export function profileExtrude(profile: V2[], width: number): THREE.BufferGeometry {
  const shape = new THREE.Shape(profile.map(([z, y]) => new THREE.Vector2(z, y)));
  const g = new THREE.ExtrudeGeometry(shape, { depth: width, bevelEnabled: true, bevelThickness: 0.06, bevelSize: 0.06, bevelSegments: 1 });
  // shape 在 XY 平面、沿 +Z 拉伸 → 旋转后：轮廓的 z 仍是世界 z，拉伸方向变成 x（宽度）
  g.translate(0, 0, -width / 2);
  g.rotateY(-Math.PI / 2);
  return g;
}

/** 车床体：profile 为 [半径, y]，绕 y 轴旋转；炮管、车轮、油桶 */
export function lathe(profile: V2[], seg = 12): THREE.BufferGeometry {
  return new THREE.LatheGeometry(profile.map(([r, y]) => new THREE.Vector2(r, y)), seg).toNonIndexed();
}

/** 沿 +z 方向的炮管：带抽烟器和炮口制退器 */
export function barrel(length: number, r: number, opts: { evacuator?: boolean; brake?: boolean } = {}): THREE.BufferGeometry {
  const p: V2[] = [[0, 0], [r * 1.25, 0], [r * 1.15, length * 0.12], [r, length * 0.18]];
  if (opts.evacuator) p.push([r, length * 0.52], [r * 1.45, length * 0.56], [r * 1.45, length * 0.68], [r, length * 0.72]);
  p.push([r * 0.92, length * (opts.brake ? 0.9 : 1)]);
  if (opts.brake) p.push([r * 1.7, length * 0.9], [r * 1.7, length * 0.95], [r * 1.2, length * 0.95], [r * 1.7, length * 0.96], [r * 1.7, length], [r * 0.6, length]);
  else p.push([r * 0.6, length]);
  const g = lathe(p, 14);
  g.rotateX(Math.PI / 2);
  return g;
}

/** 让多面体变得像石头：按顶点位置哈希做位移（同位置的顶点位移相同，保证不开裂） */
export function rockify(g: THREE.BufferGeometry, amount: number, seed: number): THREE.BufferGeometry {
  const geo = g.index ? g.toNonIndexed() : g;
  const p = geo.getAttribute('position') as THREE.BufferAttribute;
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i);
    const y = p.getY(i);
    const z = p.getZ(i);
    const h = Math.sin(x * 12.9898 + y * 78.233 + z * 37.719 + seed) * 43758.5453;
    const k = 1 + ((h - Math.floor(h)) - 0.5) * amount;
    p.setXYZ(i, x * k, y * k * 0.85, z * k);
  }
  geo.computeVertexNormals();
  return geo;
}

// --------------------------------------------------------------- 常用组件

/** 一圈铆钉/螺栓（小方块），沿 x 方向排开 */
export function rivets(count: number, span: number, y: number, z: number, color: number, size = 0.08): PartSpec[] {
  const out: PartSpec[] = [];
  for (let i = 0; i < count; i++) {
    const x = -span / 2 + (span * i) / Math.max(1, count - 1);
    out.push({ geo: new THREE.BoxGeometry(size, size, size), color, pos: [x, y, z] });
  }
  return out;
}

/** 车轮（轴沿 x） */
export function wheel(r: number, w: number, color: number, hub: number, pos: V3): PartSpec[] {
  return [
    { geo: new THREE.CylinderGeometry(r, r, w, 14), color, pos, rot: [0, 0, Math.PI / 2] },
    { geo: new THREE.CylinderGeometry(r * 0.45, r * 0.45, w + 0.04, 8), color: hub, pos, rot: [0, 0, Math.PI / 2] },
  ];
}

/** 一个木箱 / 弹药箱：箱体 + 两道箍 */
export function crate(w: number, h: number, d: number, color: number, band: number, pos: V3, rotY = 0): PartSpec[] {
  return [
    { geo: new THREE.BoxGeometry(w, h, d), color, pos, rot: [0, rotY, 0] },
    { geo: new THREE.BoxGeometry(w + 0.04, h * 0.12, d + 0.04), color: band, pos: [pos[0], pos[1] + h * 0.3, pos[2]], rot: [0, rotY, 0] },
    { geo: new THREE.BoxGeometry(w + 0.04, h * 0.12, d + 0.04), color: band, pos: [pos[0], pos[1] - h * 0.3, pos[2]], rot: [0, rotY, 0] },
  ];
}

/** 汽油桶 */
export function drum(color: number, pos: V3, tilt: [number, number] = [0, 0]): PartSpec[] {
  return [
    { geo: new THREE.CylinderGeometry(0.42, 0.42, 1.2, 12), color, pos, rot: [tilt[0], 0, tilt[1]] },
    { geo: new THREE.CylinderGeometry(0.44, 0.44, 0.06, 12), color: 0x2a2622, pos: [pos[0], pos[1] + 0.25, pos[2]], rot: [tilt[0], 0, tilt[1]] },
    { geo: new THREE.CylinderGeometry(0.44, 0.44, 0.06, 12), color: 0x2a2622, pos: [pos[0], pos[1] - 0.25, pos[2]], rot: [tilt[0], 0, tilt[1]] },
  ];
}
