import * as THREE from 'three';
import type { GeoCache } from '../assets/GeoCache';
import { sceneryGeo } from '../assets/models/environment';
import { foundryChimneyGeo, foundryTankGeo } from '../world/Foundry';
import { themeForZone } from '../world/themes';
import { groundTexture, roadTexture } from './textures';

export type BattlefieldBackdrop = 'foundry' | 'forest';

type Placement = [x: number, z: number, scale: number, yaw?: number];

/** 只取路边一小块。景物固定，同类合批，不运行刷景、碰撞、破坏或水面。 */
export function buildBattlefieldBackdrop(geo: GeoCache, kind: BattlefieldBackdrop) {
  const theme = themeForZone(kind === 'foundry' ? 4 : 2);
  const group = new THREE.Group();
  group.name = `turntable-${kind}`;
  group.rotation.y = Math.atan2(0.76, 1);
  const materials = new Set<THREE.Material>();
  const textures = new Set<THREE.Texture>();
  const props = new THREE.MeshStandardMaterial({
    color: 0x7b857c, vertexColors: true, roughness: 0.94, metalness: kind === 'foundry' ? 0.14 : 0,
  });
  materials.add(props);
  const instance = (name: string, geometry: THREE.BufferGeometry, places: Placement[]) => {
    const mesh = new THREE.InstancedMesh(geometry, props, places.length);
    mesh.name = name;
    const pose = new THREE.Object3D();
    places.forEach(([x, z, scale, yaw = 0], i) => {
      pose.position.set(x, -0.21, z);
      pose.scale.setScalar(scale);
      pose.rotation.y = yaw;
      pose.updateMatrix();
      mesh.setMatrixAt(i, pose.matrix);
    });
    mesh.instanceMatrix.needsUpdate = true;
    mesh.computeBoundingSphere();
    group.add(mesh);
  };
  const plane = (name: string, map: THREE.Texture, w: number, h: number, x: number, z: number, y: number, color: number) => {
    textures.add(map);
    const material = new THREE.MeshStandardMaterial({ color, map, roughness: 1, metalness: 0 });
    materials.add(material);
    const mesh = new THREE.Mesh(new THREE.PlaneGeometry(w, h), material);
    mesh.name = name;
    mesh.rotation.x = -Math.PI / 2;
    mesh.position.set(x, y, z);
    mesh.receiveShadow = true;
    group.add(mesh);
  };
  const ground = groundTexture(theme.ground);
  ground.repeat.set(14, 14);
  plane('battlefield-ground', ground, 140, 140, 0, 0, -0.22, 0x737b71);
  const road = roadTexture(theme.road);
  road.repeat.set(kind === 'foundry' ? 2.4 : 1, 7);
  plane('battlefield-road', road, kind === 'foundry' ? 24 : 12, 70, 0, 18, -0.21, 0x4f5a52);

  if (kind === 'foundry') {
    // 取储罐与烟囱之间的空坪；中央不摆高物，能看清炮塔。
    instance('foundry-chimneys', foundryChimneyGeo(geo), [[-8.5, 13, 0.27], [-6.5, 21, 0.22]]);
    instance('foundry-tanks', foundryTankGeo(geo), [[8.5, 10, 0.7, Math.PI], [10.5, 19, 0.6, Math.PI - 0.3]]);
    instance('foundry-walls', sceneryGeo(geo, 'wall'), [[-8.5, 8, 0.75, 0.2], [6, 21, 0.7, -0.1]]);
    instance('foundry-ruin', sceneryGeo(geo, 'ruin'), [[-13, 15, 0.85, 0.4]]);
  } else {
    // 取林道两侧的树、岩石和倒木。近景低、远景高，路口留空。
    instance('forest-pines', sceneryGeo(geo, 'pine'), [
      [-9, 8, 0.85], [-12, 13, 1, 0.7], [-8, 21, 0.8, 1.4],
      [-16, 22, 1.15, 2.1], [-20, 29, 1.1], [-4.5, 25, 0.65, 1],
      [9, 9, 0.85, 2], [12, 15, 1], [7.5, 22, 0.8, 0.7],
      [17, 24, 1.2, 1.5], [4.5, 29, 0.65, 2.3],
    ]);
    instance('forest-boulders', sceneryGeo(geo, 'boulder'), [[-9, 6, 0.7, 0.5], [10, 12, 0.8, -0.4]]);
    instance('forest-logs', sceneryGeo(geo, 'log'), [[9, 7, 0.7, -0.7], [-9, 17, 0.6, 0.6]]);
    instance('forest-bushes', sceneryGeo(geo, 'bush'), [[-8, 7, 1], [12, 9, 1.1], [-12, 16, 1.3]]);
  }
  const sky = new THREE.Color(theme.fog).multiplyScalar(0.14);
  return { group, materials, textures, sky, update: (_time: number) => {} };
}
