import * as THREE from 'three';
import type { GeoCache, PartSpec } from '../assets/GeoCache';
import { MAT } from '../assets/materials';
import { frustum, rect } from '../assets/ModelKit';
import type { Bump } from '../systems/World';
import { bankW, riverBend, type River } from './Rivers';
import { ROAD_HALF_WIDTH } from './Terrain';
import type { Fx } from '../render/Fx';
import { StationDamage, STATION_PART } from './StationDamage';

/** 铁轨中心线（路左侧路肩，装甲列车「铁砧」就跑在这上面） */
export const RAIL_X = -(ROAD_HALF_WIDTH - 1.5);

/**
 * 预铺铁轨 + 铁路桥 + 车站（T017-4A / 4B，策划 5.2 方案 A + B，制作人「铁轨是突然出现的，太突兀」）：
 * - 铁轨和首领分开：列车首领那一区（第 2 区，无尽里每 3 区一次）一开始就在路左侧铺一条铁路，像电线杆那样「前方生成、身后回收」，两头永远在雾外 / 画面外；
 *   区域开始时从路左边 OUT_X 米外（画面外、雾里）沿 CURVE 米长的缓弯接到路肩（open），区域结束（列车被打掉）时过了车站再往前 250 米弯出去（close）——
 *   打完继续往前开，铁轨一直陪到区域结束，不会整条在同一帧消失
 * - 分段实例化：每段 SEG 米（碎石路基 + 3 根枕木 + 两条钢轨），按世界坐标对齐的格子摆（不跟着坦克游动）；弯道上的段按切线转向、沿长度拉长；
 *   过河的段换成铁路桥（钢板梁 + 桁架 + 桥墩，另一个实例化网格）；共 2 次绘制
 * - 直的那一段铺一条长凸起（路面，开上去车身抬一点、不减速）
 * - 车站（station）：列车区 150 秒（首领 180 秒出来）时在前方 300 米的路左边摆：站台 + 雨棚、站房（路边景物的房子，按 T009 规则能开洞、能塌）、水塔、
 *   信号机、侧线上停着三节货车厢；站台是一个能压碎的凸起；首领战就在站前打
 */
const SEG = 7.08;
const CURVE = 260;
const OUT_X = -200;
const AHEAD = 330;
const BEHIND = 70;
const MAX_TRACK = 64;
const MAX_BRIDGE = 16;
/** 站房、站台、侧线占的那一片（景物不往这里长）：相对车站中心 z 的范围、x 范围 */
const STATION = { x0: -36, x1: -8.6, z0: -118, z1: 58, house: { x: -29.5, s: 1.3 }, platform: { x: -19.5, w: 4, len: 60, h: 0.85 } };

const smooth = (t: number) => t * t * (3 - 2 * t);

export class Railway {
  readonly group = new THREE.Group();
  /** 铁路从哪儿开始弯进来（z，最靠后的一端）/ 从哪儿开始弯出去；null = 没铺 / 还没收尾 */
  start: number | null = null;
  end: number | null = null;
  /** 车站中心 z（null = 这一区还没摆） */
  stationZ: number | null = null;
  private readonly track: THREE.InstancedMesh;
  private readonly bridge: THREE.InstancedMesh;
  private station: THREE.Group | null = null;
  private damage: StationDamage | null = null;
  private bump: Bump | null = null;
  private platform: Bump | null = null;
  private lastKey = '';
  private readonly m = new THREE.Matrix4();
  private readonly q = new THREE.Quaternion();
  private readonly p = new THREE.Vector3();
  private readonly s = new THREE.Vector3();
  private readonly up = new THREE.Vector3(0, 1, 0);

  constructor(
    private readonly geo: GeoCache,
    private readonly addBump: (b: Omit<Bump, 'flat' | 'alive' | 'stage' | 'debris'> & { debris?: Bump['debris'] }) => Bump,
    private readonly fx: Fx,
  ) {
    this.track = new THREE.InstancedMesh(this.trackGeo(), MAT.painted, MAX_TRACK);
    this.bridge = new THREE.InstancedMesh(this.bridgeGeo(), MAT.painted, MAX_BRIDGE);
    for (const m of [this.track, this.bridge]) {
      m.count = 0;
      m.frustumCulled = false;
      m.receiveShadow = true;
      m.castShadow = m === this.bridge;
      this.group.add(m);
    }
  }

  get active(): boolean {
    return this.start !== null;
  }

  /** 列车区开始：铁路从 z（前方，一般是换景的分界线）开始从画面外弯进来 */
  open(z: number): void {
    this.reset();
    this.start = z;
  }

  /** 直接铺好（读档 / 调试跳区 / 首领出来时铁路还没弯到路边）：从坦克身后 BEHIND + CURVE 米开始，坦克身边和前方全是直的 */
  layNow(playerZ: number): void {
    const keep = this.stationZ;
    this.open(playerZ + BEHIND + CURVE + 10);
    if (keep !== null) this.stationZ = keep;
  }

  /** 首领（装甲列车）出来时：坦克前后 140 米里铁轨必须是直的（极端情况——调试跳区、开局一直卡在精英前——还没弯到路边就直接铺好） */
  ensureStraight(playerZ: number): void {
    if (this.start === null || this.start - CURVE < playerZ + 140 || this.end !== null) this.layNow(playerZ);
  }

  /** 列车区结束：再往前 ahead 米开始弯出去 */
  close(playerZ: number, ahead = 250): void {
    if (this.start === null || this.end !== null) return;
    this.end = playerZ - ahead;
  }

  reset(): void {
    this.start = this.end = this.stationZ = null;
    this.track.count = this.bridge.count = 0;
    this.lastKey = '';
    if (this.bump) this.bump.alive = false;
    if (this.platform) this.platform.alive = false;
    this.bump = this.platform = null;
    this.station?.removeFromParent();
    this.damage?.reset();
  }

  /** 铁轨中心线在 z 处的 x（不在铺设范围里 = null） */
  xAt(z: number): number | null {
    if (this.start === null || z > this.start) return null;
    if (this.end !== null && z < this.end - CURVE) return null;
    let x = RAIL_X;
    const tin = (this.start - z) / CURVE;
    if (tin < 1) x = OUT_X + (RAIL_X - OUT_X) * smooth(Math.max(0, tin));
    if (this.end !== null && z < this.end) x = RAIL_X + (OUT_X - RAIL_X) * smooth(Math.min(1, (this.end - z) / CURVE));
    return x;
  }

  /** 景物不往铁路路基（中心线 ±5 米）和车站那一片长 */
  blocked(x: number, z: number): boolean {
    const rx = this.xAt(z);
    if (rx !== null && Math.abs(x - rx) < 5) return true;
    const s = this.stationZ;
    return s !== null && x > STATION.x0 && x < STATION.x1 && z > s + STATION.z0 && z < s + STATION.z1;
  }

  /** 在 z 处摆车站（列车区 150 秒时由 Game 调，摆在前方 300 米）；place = 摆路边景物（站房用房子，能打塌） */
  placeStation(z: number, place: (kind: 'house', x: number, z: number, rot: number, scale: number) => void): void {
    if (this.stationZ !== null) return;
    this.stationZ = z;
    if (!this.station) this.station = this.buildStation();
    this.damage?.reset();
    this.station.position.set(0, 0, z);
    this.group.add(this.station);
    place('house', STATION.house.x, z, Math.PI / 2, STATION.house.s);
    const P = STATION.platform;
    this.platform = this.addBump({ x: P.x, z, halfW: P.w / 2, halfD: P.len / 2, rot: 0, h0: P.h, h1: 0.35, debris: 'concrete' });
  }

  /** rear = 身后收掉按的位置（T107 停车攻坚时是能退到的最远处，往前挪了再退回来身后的铁轨还在；平时就是玩家） */
  update(playerZ: number, rivers: readonly River[], rear = playerZ, dt = 0): void {
    if (this.station?.parent && this.stationZ !== null) this.damage?.update(dt, this.stationZ);
    if (this.station && this.stationZ !== null && this.stationZ > rear + 140) {
      this.station.removeFromParent();
      this.damage?.reset();
      if (this.platform) this.platform.alive = false;
      this.platform = null;
    }
    if (this.start === null) return;
    // 整条都甩到身后了：收掉
    if (this.end !== null && this.end - CURVE > rear + BEHIND) {
      const keep = this.stationZ;
      this.reset();
      this.stationZ = keep;
      return;
    }
    this.updateBump(playerZ);
    // 按世界格子摆段：坦克每开过一段、或河 / 收尾变了才重摆
    const k0 = Math.floor((rear + BEHIND) / SEG);
    const key = `${k0}|${this.start}|${this.end}|${rivers.length}|${rivers.length ? rivers[rivers.length - 1].z : 0}`;
    if (key === this.lastKey) return;
    this.lastKey = key;
    let nt = 0;
    let nb = 0;
    const kEnd = Math.floor((playerZ - AHEAD) / SEG);
    for (let k = k0; k >= kEnd; k--) {
      const z = (k + 0.5) * SEG;
      const x = this.xAt(z);
      if (x === null) continue;
      const x1 = this.xAt(z - 0.5) ?? x;
      const x0 = this.xAt(z + 0.5) ?? x;
      // 切线：沿 −z 前进时 x 每米变多少；段绕 y 转到切线方向、沿长度按弧长拉长
      const slope = x0 - x1;
      // 过河（T034：水面 + 两边岸坡整个河道）的段换成铁路桥，桥墩插到河床
      const wet = rivers.some((r) => Math.abs(z - r.z - riverBend(x, r.phase, r.amp)) < r.half + bankW(x, z < r.z ? -1 : 1, r.phase, !r.deck) + 0.5);
      const mesh = wet ? this.bridge : this.track;
      const i = wet ? nb : nt;
      if (i >= (wet ? MAX_BRIDGE : MAX_TRACK)) continue;
      this.q.setFromAxisAngle(this.up, Math.atan(slope));
      this.s.set(1, 1, Math.sqrt(1 + slope * slope));
      this.m.compose(this.p.set(x, 0, z), this.q, this.s);
      mesh.setMatrixAt(i, this.m);
      if (wet) nb++;
      else nt++;
    }
    this.track.count = nt;
    this.bridge.count = nb;
    this.track.instanceMatrix.needsUpdate = true;
    this.bridge.instanceMatrix.needsUpdate = true;
  }

  /** 直的那一段铁轨：坦克身边一条长凸起（路面，开上去车身抬一点、不减速） */
  private updateBump(playerZ: number): void {
    if (this.start === null) return;
    const hi = Math.min(this.start - CURVE, playerZ + 30);
    const lo = Math.max(this.end ?? -Infinity, playerZ - 80);
    if (hi <= lo) {
      if (this.bump) this.bump.alive = false;
      this.bump = null;
      return;
    }
    // 绝对高度（T034：铁轨模型一直在 y = 0 上，过河是铁路桥；凸起不跟着河道 / 弹坑往下陷）
    if (!this.bump || !this.bump.alive) this.bump = this.addBump({ x: RAIL_X, z: 0, halfW: 2.3, halfD: 1, rot: 0, h0: 0.42, h1: 0.42, debris: 'concrete', road: true, rampD: 0.8, base: 0 });
    this.bump.z = (hi + lo) / 2;
    this.bump.halfD = (hi - lo) / 2;
  }

  /** 一段铁轨（SEG 米）：碎石路基 + 3 根枕木 + 两条钢轨（宽轨 ±1.45，铁砧的大轮子跑在上面） */
  private trackGeo(): THREE.BufferGeometry {
    return this.geo.merged('rail-seg', () => {
      const p: PartSpec[] = [{ geo: frustum(rect(5.4, SEG + 0.02), rect(4.2, SEG + 0.02), 0.35), color: 0x5e5850 }];
      for (let i = 0; i < 3; i++) p.push({ geo: new THREE.BoxGeometry(4.0, 0.18, 0.55), color: i === 1 ? 0x3e3026 : 0x463628, pos: [0, 0.42, -SEG / 2 + SEG / 6 + (i * SEG) / 3] });
      for (const s of [-1, 1]) {
        p.push({ geo: new THREE.BoxGeometry(0.22, 0.26, SEG + 0.02), color: 0x56524c, pos: [s * 1.45, 0.62, 0] });
        p.push({ geo: new THREE.BoxGeometry(0.14, 0.03, SEG + 0.02), color: 0x8e8a82, pos: [s * 1.45, 0.76, 0] });
      }
      return p;
    });
  }

  /** 一段铁路桥（SEG 米）：两根钢板梁 + 两侧桁架（上弦 + 斜杆）+ 枕木 + 钢轨 + 一对桥墩 */
  private bridgeGeo(): THREE.BufferGeometry {
    return this.geo.merged('rail-bridge', () => {
      const p: PartSpec[] = [];
      for (const s of [-1, 1]) {
        p.push({ geo: new THREE.BoxGeometry(0.3, 1.3, SEG + 0.02), color: 0x4a4844, pos: [s * 1.7, -0.3, 0] });
        p.push({ geo: new THREE.BoxGeometry(0.22, 0.22, SEG + 0.02), color: 0x4e4a44, pos: [s * 2.6, 3.0, 0] });
        p.push({ geo: new THREE.BoxGeometry(0.22, 0.22, SEG + 0.02), color: 0x4e4a44, pos: [s * 2.6, 0.45, 0] });
        p.push({ geo: new THREE.BoxGeometry(0.16, Math.hypot(2.6, SEG / 2), 0.16), color: 0x5a3e2c, pos: [s * 2.6, 1.72, -SEG / 4], rot: [Math.atan2(SEG / 2, 2.6), 0, 0] });
        p.push({ geo: new THREE.BoxGeometry(0.16, Math.hypot(2.6, SEG / 2), 0.16), color: 0x5a3e2c, pos: [s * 2.6, 1.72, SEG / 4], rot: [-Math.atan2(SEG / 2, 2.6), 0, 0] });
        p.push({ geo: new THREE.BoxGeometry(0.2, 2.6, 0.2), color: 0x4e4a44, pos: [s * 2.6, 1.72, -SEG / 2] });
        p.push({ geo: new THREE.CylinderGeometry(0.45, 0.6, 3.2, 8), color: 0x5e5a52, pos: [s * 1.7, -2.4, 0] });
        p.push({ geo: new THREE.BoxGeometry(0.22, 0.26, SEG + 0.02), color: 0x56524c, pos: [s * 1.45, 0.62, 0] });
        p.push({ geo: new THREE.BoxGeometry(0.14, 0.03, SEG + 0.02), color: 0x8e8a82, pos: [s * 1.45, 0.76, 0] });
      }
      p.push({ geo: new THREE.BoxGeometry(5.4, 0.12, SEG + 0.02), color: 0x3a3632, pos: [0, 0.3, 0] });
      for (let i = 0; i < 3; i++) p.push({ geo: new THREE.BoxGeometry(4.0, 0.18, 0.55), color: 0x3e3026, pos: [0, 0.42, -SEG / 2 + SEG / 6 + (i * SEG) / 3] });
      return p;
    });
  }

  /** 车站（站房另外用路边景物的房子）：站台 + 雨棚、水塔、信号机、侧线 + 三节货车厢；坐标相对车站中心，x 是世界坐标 */
  private buildStation(): THREE.Group {
    const g = new THREE.Group();
    const P = STATION.platform;
    const body = this.geo.merged('rail-station', () => {
      const p: PartSpec[] = [];
      const mark = (start: number, id: number) => { for (let i = start; i < p.length; i++) p[i].crush = id; };
      // 站台：混凝土台面 + 靠铁路一侧的黄线 + 台壁
      p.push({ geo: new THREE.BoxGeometry(P.w, P.h, P.len), color: 0x6a645a, pos: [P.x, P.h / 2, 0] });
      p.push({ geo: new THREE.BoxGeometry(0.25, 0.02, P.len), color: 0x8a7a48, pos: [P.x + P.w / 2 - 0.35, P.h + 0.01, 0] });
      p.push({ geo: new THREE.BoxGeometry(0.15, P.h + 0.1, P.len), color: 0x55504a, pos: [P.x + P.w / 2, P.h / 2, 0] });
      // 雨棚：外侧一排立柱 + 斜挑的棚顶 + 檐板
      for (let i = 0; i <= 8; i++) p.push({ geo: new THREE.BoxGeometry(0.24, 3.4, 0.24), color: 0x3a3a36, pos: [P.x - P.w / 2 + 0.5, P.h + 1.7, -P.len / 2 + 3 + i * ((P.len - 6) / 8)], crush: STATION_PART.canopy + Math.min(i, 7) });
      const panel = (P.len - 4) / 8;
      for (let i = 0; i < 8; i++) {
        const z = -(P.len - 4) / 2 + (i + .5) * panel;
        p.push({ geo: new THREE.BoxGeometry(P.w + 0.8, 0.16, panel), color: 0x4a4640, pos: [P.x + 0.2, P.h + 3.45, z], rot: [0, 0, -0.08], crush: STATION_PART.canopy + i });
        p.push({ geo: new THREE.BoxGeometry(0.1, 0.4, panel), color: 0x5a3e2c, pos: [P.x + P.w / 2 + 0.6, P.h + 3.2, z], crush: STATION_PART.canopy + i });
      }
      // 侧线：一段铁轨（站台外侧再往外，货车厢停在上面）
      const sx = -24.5;
      const sz0 = -112;
      const sz1 = -40;
      p.push({ geo: frustum(rect(4.4, sz1 - sz0, sx, (sz0 + sz1) / 2), rect(3.4, sz1 - sz0, sx, (sz0 + sz1) / 2), 0.3), color: 0x5a544c });
      for (let z = sz0 + 1; z < sz1; z += 2.36) p.push({ geo: new THREE.BoxGeometry(3.4, 0.16, 0.5), color: 0x3e3026, pos: [sx, 0.38, z] });
      for (const s of [-1, 1]) p.push({ geo: new THREE.BoxGeometry(0.18, 0.22, sz1 - sz0), color: 0x56524c, pos: [sx + s * 1.1, 0.55, (sz0 + sz1) / 2] });
      // 三节棚车：锈红车厢 + 车顶 + 推拉门 + 底架 + 转向架
      for (const [i, cz] of [-54, -69, -84].entries()) {
        const start = p.length;
        const col = [0x5a3a2a, 0x4e3a2e, 0x5e4030][i];
        p.push({ geo: new THREE.BoxGeometry(2.4, 0.4, 12.2), color: 0x2a2826, pos: [sx, 1.0, cz] });
        p.push({ geo: new THREE.BoxGeometry(2.9, 2.7, 12), color: col, pos: [sx, 2.55, cz] });
        p.push({ geo: new THREE.BoxGeometry(3.1, 0.18, 12.3), color: 0x3e3832, pos: [sx, 3.98, cz], rot: [0, 0, 0.02] });
        for (const s of [-1, 1]) {
          p.push({ geo: new THREE.BoxGeometry(0.06, 2.2, 3), color: 0x3e2a20, pos: [sx + s * 1.47, 2.4, cz + 0.5] });
          for (const dz of [-4.4, -3.2, 3.2, 4.4]) p.push({ geo: new THREE.CylinderGeometry(0.42, 0.42, 0.2, 10), color: 0x262422, pos: [sx + s * 1.1, 0.95, cz + dz], rot: [0, 0, Math.PI / 2] });
        }
        mark(start, STATION_PART.wagon + i);
      }
      // 水塔：四条腿 + 斜撑 + 木桶水箱 + 锥顶 + 出水管
      const wx = -24;
      const wz = 46;
      const waterStart = p.length;
      for (const [dx, dz] of [[-1.6, -1.6], [1.6, -1.6], [-1.6, 1.6], [1.6, 1.6]]) p.push({ geo: new THREE.BoxGeometry(0.3, 7, 0.3), color: 0x3e3a34, pos: [wx + dx, 3.5, wz + dz] });
      for (const s of [-1, 1]) p.push({ geo: new THREE.BoxGeometry(0.12, 4.6, 0.12), color: 0x4a443c, pos: [wx, 3.5, wz + s * 1.6], rot: [0, 0, 0.6 * s] });
      p.push({ geo: new THREE.CylinderGeometry(2.2, 2.2, 3.2, 14), color: 0x4e4438, pos: [wx, 8.6, wz] });
      for (const y of [7.4, 8.6, 9.8]) p.push({ geo: new THREE.CylinderGeometry(2.24, 2.24, 0.12, 14), color: 0x2e2a26, pos: [wx, y, wz] });
      p.push({ geo: new THREE.ConeGeometry(2.45, 1.1, 14), color: 0x3a3632, pos: [wx, 10.75, wz] });
      p.push({ geo: new THREE.BoxGeometry(2.4, 0.22, 0.22), color: 0x3a3632, pos: [wx + 2.2, 8.0, wz], rot: [0, 0, -0.5] });
      mark(waterStart, STATION_PART.water);
      // 信号机：立柱 + 机头（灯另外画，发光）
      p.push({ geo: new THREE.CylinderGeometry(0.12, 0.16, 6, 8), color: 0x3a3a36, pos: [-22, 3, -36], crush: STATION_PART.signal });
      p.push({ geo: new THREE.BoxGeometry(0.7, 1.5, 0.35), color: 0x1e1e1e, pos: [-22, 6.1, -36], crush: STATION_PART.signal });
      return p;
    });
    const mesh = new THREE.Mesh(body, MAT.painted);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    g.add(mesh);
    const lamp = new THREE.Mesh(this.geo.get('rail-lamp', () => new THREE.SphereGeometry(0.2, 8, 6)), new THREE.MeshBasicMaterial({ color: 0xff3020, toneMapped: false }));
    lamp.position.set(-22, 6.5, -35.8);
    g.add(lamp);
    this.damage = new StationDamage(mesh, lamp, this.fx);
    return g;
  }

  blast(x: number, z: number, r: number, force: number): void {
    if (this.station?.parent && this.stationZ !== null) this.damage?.blast(x, z, r, force, this.stationZ);
  }

  beam(ox: number, oz: number, dx: number, dz: number, len: number, half: number, dt: number, rate: number): void {
    if (this.station?.parent && this.stationZ !== null) this.damage?.beam(ox, oz, dx, dz, len, half, dt, rate, this.stationZ);
  }

  flame(ox: number, oz: number, angle: number, range: number, cone: number, dt: number): void {
    if (this.station?.parent && this.stationZ !== null) this.damage?.flame(ox, oz, angle, range, cone, dt, this.stationZ);
  }

  ignite(x: number, z: number, rx: number, rz: number): void {
    if (this.station?.parent && this.stationZ !== null) this.damage?.ignite(x, z, rx, rz, this.stationZ);
  }
}
