import { rng } from '../game/rng';
import type { Enemy } from '../entities/Enemy';
import { atkKind, ultHalf, type ModStats } from './defs';
import type { DamageOpts } from './behaviors';
import type { ImpactOpts } from '../systems/Projectiles';

/** 出超级改装的等级：开局、7、14、20、25，之后每 5 级一次（T186）。 */
export const SUPER_LEVELS = [1, 7, 14, 20, 25] as const;
export const SUPER_EVERY = 5;

/** level 之后下一个出超级改装的等级 */
export function superAfter(level: number): number {
  const last = SUPER_LEVELS[SUPER_LEVELS.length - 1];
  if (level < last) return SUPER_LEVELS.find((l) => l > level)!;
  return last + (Math.floor((level - last) / SUPER_EVERY) + 1) * SUPER_EVERY;
}

/** 超级三选一：到点只弹这一组，不再接普通三选一；直通、老存档不补领以前的等级。 */
export class SuperSchedule {
  next = 1;

  due(level: number, remaining: number): boolean {
    return remaining > 0 && level >= this.next;
  }

  claim(level: number): void {
    this.next = superAfter(level);
  }
}

/** 连射状态按武器保存；发数允许是火神伤害包里的小数。 */
export class RateStack {
  layers = 0;
  private shots = 0;
  private last = -Infinity;

  factor(base: number, now: number): number {
    if (now - this.last >= 1 || base <= 1) this.reset();
    return base + 0.2 * this.layers;
  }

  fire(shots: number, now: number, base: number): void {
    this.factor(base, now);
    if (base <= 1 || shots <= 0) return;
    this.last = now;
    this.shots = Math.min(10, this.shots + shots);
    this.layers = Math.min(10, Math.floor(this.shots + 1e-8));
  }

  reset(): void {
    this.layers = this.shots = 0;
    this.last = -Infinity;
  }
}

/** 一格只抽一次。火神按每条发数累积，激光按实际出光秒数累积。 */
export class AmmoRefund {
  private spent = 0;
  returned = 0;

  consume(amount: number, per: number, enabled: boolean): number {
    if (!enabled) { this.spent = 0; return 0; }
    this.spent += amount / per;
    let slots = 0;
    while (this.spent + 1e-8 >= 1) {
      this.spent = Math.max(0, this.spent - 1);
      if (rng.weapon() < 0.2) slots++;
    }
    this.returned += slots;
    return slots;
  }

  reset(): void {
    this.spent = this.returned = 0;
  }
}

export function summonBatch(base: number, multiplier: number, cap = Infinity): { count: number; damage: number } {
  const intended = base * multiplier;
  const count = Math.min(cap, intended);
  return { count, damage: count > 0 ? intended / count : 1 };
}

export const summonDuration = (mods: ModStats): number => mods.summon > 1 ? 1.5 : 1;

/** 究极的元素加成仍在各自模块里按 ultHalf 算；召唤和易伤在统一入口全额算。 */
export function attackMultiplier(opts: DamageOpts, mods: ModStats, vulnerable = false): number {
  const kind = opts.kind ?? atkKind(opts.type);
  let k = opts.summon && mods.summon > 1 ? 1.5 : 1;
  if (vulnerable) k *= 1.2;
  if (!opts.ult && !opts.fixed) {
    if (kind === 'energy' || kind === 'elec') k *= mods.energy;
    if (kind === 'fire' && !opts.burnTick) k *= mods.burn;
  }
  return k;
}

/** 取强的那份余烧，记录其来源；再次命中只刷新，不把低伤害的来源盖过去。 */
export function igniteHit(e: Enemy, opts: DamageOpts, mods: ModStats, src: string, player = 0): void {
  const kind = opts.kind ?? atkKind(opts.type);
  const native = (opts.burn ?? 0) * (opts.ult ? ultHalf(mods.burn) : mods.burn);
  const added = mods.burn > 1 && kind !== 'fire' && !opts.ult ? 8 : 0;
  const dps = Math.max(native, added);
  if (!dps) return;
  if (e.burnTime <= 0 || dps >= e.burnDps) {
    e.burnDps = dps;
    e.burnSrc = src;
    e.burnPlayer = player;
    e.burnSummon = !!opts.summon;
  }
  e.burnTime = 3;
}

/** 透镜的电磁麻痹与原生麻痹取长；有透镜时同一辆车共用三秒间隔。 */
export function electricStun(e: Enemy, opts: DamageOpts, mods: ModStats, now: number): number {
  if (e.boss || e.controller || e.charging) return 0;
  const native = opts.stun ?? 0;
  if (opts.kind !== 'elec' || mods.energy <= 1 || e.armor === 'none') return native;
  if (now < e.lensStunUntil) return 0;
  const seconds = Math.max(native, rng.weapon() < 0.2 ? 1 : 0);
  if (seconds > 0) e.lensStunUntil = now + 3;
  return seconds;
}

export function grenadeImpact<T extends ImpactOpts>(opts: T): T {
  return opts.grenade && opts.crit && !opts.ult && !opts.fixed
    ? { ...opts, knock: (opts.knock ?? 6) * 3, heave: true }
    : opts;
}

interface Chain {
  x: number; y: number; z: number;
  next: number;
  jumps: number;
  hit: Set<Enemy>;
  damage: number;
  source: string;
  tag: string;
  opts: DamageOpts;
}

/** 追加电弧独立计时，不挤进一次伤害循环；每链最多 30 跳。 */
export class ElectricChains {
  private readonly chains: Chain[] = [];
  started = 0;
  jumps = 0;

  start(e: Enemy, damage: number, opts: DamageOpts, now: number, source: string, enabled: boolean, tag = ''): boolean {
    if (!enabled || opts.kind !== 'elec' || opts.ult || opts.chain || rng.weapon() >= 0.3) return false;
    const p = e.group.position;
    this.chains.push({ x: p.x, y: p.y, z: p.z, next: now + 0.1, jumps: 0, hit: new Set([e]), damage: damage * 0.5, source, tag, opts: { ...opts, chain: true, crit: false } });
    this.started++;
    return true;
  }

  update(now: number, enemies: readonly Enemy[], hit: (e: Enemy, chain: Readonly<Chain>) => void): void {
    for (let i = this.chains.length - 1; i >= 0; i--) {
      const chain = this.chains[i];
      while (now + 1e-8 >= chain.next && chain.jumps < 30) {
        let next: Enemy | null = null;
        let nearest = 12;
        for (const e of enemies) {
          if (!e.alive || chain.hit.has(e)) continue;
          const p = e.group.position;
          const d = Math.hypot(p.x - chain.x, p.y - chain.y, p.z - chain.z);
          if (d <= nearest) { next = e; nearest = d; }
        }
        if (!next) { chain.jumps = 30; break; }
        const p = next.group.position;
        const x = p.x, y = p.y, z = p.z;
        chain.hit.add(next);
        hit(next, chain);
        chain.x = x; chain.y = y; chain.z = z;
        chain.next += 0.1;
        chain.jumps++;
        this.jumps++;
      }
      if (chain.jumps >= 30) this.chains.splice(i, 1);
    }
  }

  reset(): void {
    this.chains.length = this.started = this.jumps = 0;
  }
}
