import * as THREE from 'three';
import { MARK_SELF } from '../render/markColors';
import { CRATER_GLSL, craterUniforms, type CraterUniforms } from '../world/Craters';

// 环贴着实体弹坑的地面（坦克开在坑壁上时环不会一半埋进土里；T034 起贴最上面那层：桥上贴桥面、涉水时浮在水面上）
const RING_VERTEX = /* glsl */ `
${CRATER_GLSL}
varying vec2 vPos;
void main() {
  vPos = position.xy;
  vec4 w = modelMatrix * vec4(position, 1.0);
  w.y += surfaceH(w.xz);
  gl_Position = projectionMatrix * viewMatrix * w;
}`;

// 环在 XY 平面建模，放倒后 +Y 朝前、-Y 朝后（靠近镜头）。
// 进度从车尾中线沿左右两侧同时往前长，满了在车头合拢。
// 环分成 uMax 段（每段一发），从车尾往车头依次装填；装好的段亮金色，正在装填的段按进度填一半亮度。
const RING_FRAGMENT = /* glsl */ `
uniform float uRounds;
uniform float uMax;
uniform float uPulse;
uniform float uDeny;
uniform float uFlash;
uniform float uCont;
uniform float uTicks;
uniform float uDry;
varying vec2 vPos;
void main() {
  float a = abs(atan(vPos.x, -vPos.y)) / 3.14159265;
  float pos = a * uMax;
  float seg = floor(pos);
  float local = fract(pos);
  vec3 col = vec3(0.12, 0.11, 0.1);
  float alpha = 0.32;
  // 连续弹药条（火神，T089）：琥珀色按剩几成填；重弹按梭画刻度，攒够的梭亮、正在攒的那一梭暗；打空降速时整圈一闪一闪
  if (uCont > 1.5) {
    if (uTicks > 0.0 && a * uTicks - floor(a * uTicks) < 0.04 && a > 0.01) discard;
    if (a <= uRounds) {
      bool whole = uTicks <= 0.0 || a <= floor(uRounds * uTicks + 0.0001) / uTicks;
      col = whole ? vec3(1.0, 0.72, 0.28) + uPulse * 0.15 : vec3(0.75, 0.45, 0.16);
      alpha = whole ? 0.7 : 0.5;
    }
    col = mix(col, vec3(1.0, 0.95, 0.85), uFlash * 0.6);
    col = mix(col, vec3(1.0, 0.42, 0.18), uDry);
    gl_FragColor = vec4(col, max(alpha, uDry * 0.6));
    return;
  }
  // 连续能量条（激光）：亮青色按比例填充，不够起步时偏暗
  if (uCont > 0.5) {
    if (a <= uRounds) {
      col = uRounds >= 0.2 ? vec3(0.55, 0.9, 1.0) + uPulse * 0.15 : vec3(0.3, 0.5, 0.6);
      alpha = 0.7;
    }
    col = mix(col, vec3(1.0), uFlash * 0.6);
    col = mix(col, vec3(1.0, 0.28, 0.22), uDeny);
    gl_FragColor = vec4(col, max(alpha, uDeny * 0.85));
    return;
  }
  // 段与段之间留缝
  if (seg > 0.0 && local < 0.06) discard;
  float full = floor(uRounds + 0.0001);
  if (seg < full) {
    col = vec3(1.0, 0.78, 0.3) + uPulse * 0.2;
    alpha = 0.66 + uPulse * 0.24;
    // 刚装好的那一段闪白
    if (seg > full - 1.5) {
      col = mix(col, vec3(1.0, 1.0, 0.9), uFlash);
      alpha = max(alpha, 0.66 + uFlash * 0.34);
    }
  } else if (seg < full + 1.0 && local <= fract(uRounds)) {
    col = vec3(0.8, 0.5, 0.18);
    alpha = 0.55;
  }
  col = mix(col, vec3(1.0, 0.28, 0.22), uDeny);
  alpha = max(alpha, uDeny * 0.85);
  gl_FragColor = vec4(col, alpha);
}`;

/** 坦克脚下的弹匣环（每段一发；激光连续能量条、火神连续弹药条）+ 点一下会打向的目标标记 */
export class ChargeGauge {
  /** 地面高度（实体弹坑）：光环和锁定框贴着坑里的地面 */
  groundAt: (x: number, z: number) => number = () => 0;
  /** 天上的目标（T125）：锁定框立起来朝着镜头 */
  camera: THREE.Camera | null = null;
  readonly group = new THREE.Group();

  private readonly ring: THREE.Mesh<THREE.RingGeometry, THREE.ShaderMaterial>;
  private readonly marker = new THREE.Group();
  private readonly markerSpin = new THREE.Group();
  private readonly markerGeo: THREE.RingGeometry;
  private readonly markerMat: THREE.MeshBasicMaterial;
  private time = 0;
  private deny = 0;
  private load = 0;

  /** craters = 实体弹坑的 uniform（Fx 那份） */
  constructor(craters: CraterUniforms = craterUniforms()) {
    this.ring = new THREE.Mesh(
      new THREE.RingGeometry(4.7, 5.5, 64, 1),
      new THREE.ShaderMaterial({
        vertexShader: RING_VERTEX,
        fragmentShader: RING_FRAGMENT,
        uniforms: { uRounds: { value: 0 }, uMax: { value: 2 }, uPulse: { value: 0 }, uDeny: { value: 0 }, uFlash: { value: 0 }, uCont: { value: 0 }, uTicks: { value: 0 }, uDry: { value: 0 }, ...craters },
        transparent: true,
        depthWrite: false,
      }),
    );
    this.ring.rotation.x = -Math.PI / 2;
    this.ring.position.y = 0.06;
    this.ring.renderOrder = 1;
    this.group.add(this.ring);

    // 四段弧组成的锁定框，旋转起来才看得出在"锁定"（我方浅黄，T130）
    this.markerGeo = new THREE.RingGeometry(1, 1.25, 10, 1, 0, Math.PI / 3);
    this.markerMat = new THREE.MeshBasicMaterial({ color: MARK_SELF, transparent: true, opacity: 0.9, depthWrite: false });
    for (let i = 0; i < 4; i++) {
      const arc = new THREE.Mesh(this.markerGeo, this.markerMat);
      arc.rotation.z = (i * Math.PI) / 2;
      arc.renderOrder = 1;
      this.markerSpin.add(arc);
    }
    this.marker.add(this.markerSpin);
    this.marker.visible = false;
    this.group.add(this.marker);
  }

  /** 弹匣打空还点按时闪红 */
  flashDeny(): void {
    this.deny = 1;
  }

  /** 装好一发：那一段闪白 */
  flashLoad(): void {
    this.load = 1;
  }

  update(
    delta: number,
    rounds: number,
    max: number,
    tankX: number,
    tankZ: number,
    target: { x: number; z: number; radius: number; y?: number } | null,
    mode = 0,
    ticks = 0,
    dry = false,
  ): void {
    this.time += delta;
    this.deny = Math.max(0, this.deny - delta * 4);
    this.load = Math.max(0, this.load - delta * 3);
    const pulse = 0.5 + 0.5 * Math.sin(this.time * 9);

    const u = this.ring.material.uniforms;
    u.uRounds.value = rounds;
    u.uMax.value = Math.max(1, max);
    u.uPulse.value = rounds >= 1 || (mode === 2 && rounds > 0.02) ? pulse * 0.6 : 0;
    u.uDeny.value = this.deny;
    u.uFlash.value = this.load;
    u.uCont.value = mode;
    u.uTicks.value = ticks;
    u.uDry.value = dry ? 0.35 + 0.35 * Math.sin(this.time * 14) : 0;
    this.ring.position.x = tankX;
    this.ring.position.z = tankZ;

    this.marker.visible = target !== null;
    if (target) {
      // 天上的目标（target.y = 世界高度，T125）：框立在它身上、朝着镜头；地面目标照旧贴地
      const sky = target.y !== undefined && this.camera !== null;
      this.marker.position.set(target.x, sky ? target.y! : 0.08 + this.groundAt(target.x, target.z), target.z);
      if (sky) this.marker.quaternion.copy(this.camera!.quaternion);
      else this.marker.quaternion.identity();
      this.marker.scale.setScalar((target.radius + 0.9) * (1 + pulse * 0.08));
      this.markerSpin.rotation.set(sky ? 0 : -Math.PI / 2, 0, this.time * 1.6);
    }
  }

  dispose(): void {
    this.ring.geometry.dispose();
    this.ring.material.dispose();
    this.markerGeo.dispose();
    this.markerMat.dispose();
  }
}
