import type { UiSkin } from './types';
import { hatch, line, rivet, scratches } from './drawing';

/** 前线装甲：厚漆钢板、白漆刻线、角部铆接。 */
export const scheme1: UiSkin = {
  id: 1, name: '前线装甲', shape: 'square', radius: 2, ticks: 10,
  colors: {
    back: '#101611', backHi: '#303a2a', high: '#424c38', low: '#20291e', line: '#818b6c',
    ink: '#f0efde', soft: '#d1d5c3', dim: '#a6b09c', accent: '#e0d8b6', cool: '#a9c9bf',
    mainHi: '#d5d7b6', mainLow: '#a1a783', mainInk: '#202a1c', shadow: '#0b100a',
  },
  texture: (c) => scratches(c, 71, 1900),
  detail(c, w, h, role) {
    if (w < 55 || h < 32) {
      line(c, 4, 3, w - 4, 3, 'rgba(234,241,211,.24)');
      return;
    }
    for (const x of [6, w - 6]) for (const y of [6, h - 6]) rivet(c, x, y, role === 'title' ? 2.6 : 1.7);
    line(c, 9, h - 4, w - 9, h - 4, 'rgba(0,0,0,.55)', 2);
    if (role === 'card') {
      c.fillStyle = 'rgba(4,10,4,.32)'; c.fillRect(4, 15, 3, h - 30);
      line(c, 18, h - 10, 39, h - 10, 'rgba(228,229,205,.3)', 2);
    }
    if (role === 'primary') {
      line(c, 12, 9, 12, h - 9, '#535d41', 3);
      line(c, w - 12, 9, w - 12, h - 9, '#535d41', 3);
    }
  },
  scene(c, w, h) {
    const left = Math.max(8, (w - 520) / 2), right = w - left;
    c.strokeStyle = '#636d50'; c.lineWidth = 1;
    c.strokeRect(left + 0.5, 9.5, right - left - 1, h - 19);
    c.strokeStyle = 'rgba(0,0,0,.65)';
    c.strokeRect(left + 5.5, 14.5, right - left - 11, h - 29);
    for (let y = 28; y < h - 18; y += 94) {
      rivet(c, left + 4, y, 2);
      rivet(c, right - 4, y, 2);
    }
    hatch(c, left + 14, 18, 62, 5, '#8b9170', 10);
    hatch(c, right - 76, h - 23, 62, 5, '#8b9170', 10);
    line(c, left + 18, h - 32, left + 44, h - 32, '#d0d2b6', 3);
    line(c, left + 18, h - 27, left + 35, h - 27, '#d0d2b6', 2);
  },
};
