import * as THREE from 'three';
import { TURRET, type Tank } from '../entities/Tank';
import type { Weapon } from './behaviors';

/**
 * 炮塔转身限位（T127，制作人「炮塔转到后方时，炮管不能插进车体」）：车尾平台的两个挂点（Tank.anchors 3 / 5）正好在炮管转到车尾的路上。
 * 按模型算：挂件每个零件的包围盒切出炮管那一层高度（炮管上面的天线、斜着的炮筒上半截不算），炮塔每转 1°，看炮管那截（Tank.gun）俯视下和它们有没有重叠
 * （机枪 / 迫击炮 / 喷火器的头会转，按 16 个朝向都算）；从 TURRET.free 往外，往左 / 往右碰到的第一个角度往回让 1.5° 就是限位，写进 Tank.arc。
 * 车尾没装东西 = 一圈都能转。换炮塔、车尾挂件换模型（新装 / 升级 / 进化）时才重算
 */
const REAR = [3, 5];
const STEP = Math.PI / 180;
const GAP = 1.5 * STEP;
const YAWS = 16;

/** 俯视下的一块：凸多边形（x, z 交替）、外接圆、高度范围 */
interface Piece {
  pts: number[];
  cx: number;
  cz: number;
  r: number;
  y0: number;
  y1: number;
}

const UP = new THREE.Vector3(0, 1, 0);
const ONE = new THREE.Vector3(1, 1, 1);
const NONE = new THREE.Quaternion();

/** 一组点（x, z 交替）的凸包，逆时针 */
function hull(xz: number[]): number[] {
  const p: [number, number][] = [];
  for (let i = 0; i < xz.length; i += 2) p.push([xz[i], xz[i + 1]]);
  p.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const cross = (o: number[], a: number[], b: number[]) => (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
  const lo: [number, number][] = [];
  const hi: [number, number][] = [];
  for (const q of p) {
    while (lo.length >= 2 && cross(lo[lo.length - 2], lo[lo.length - 1], q) <= 1e-9) lo.pop();
    lo.push(q);
  }
  for (let i = p.length - 1; i >= 0; i--) {
    while (hi.length >= 2 && cross(hi[hi.length - 2], hi[hi.length - 1], p[i]) <= 1e-9) hi.pop();
    hi.push(p[i]);
  }
  return [...lo.slice(0, -1), ...hi.slice(0, -1)].flat();
}

function piece(xz: number[], y0: number, y1: number): Piece {
  const pts = hull(xz);
  let cx = 0;
  let cz = 0;
  const n = pts.length / 2;
  for (let i = 0; i < pts.length; i += 2) {
    cx += pts[i] / n;
    cz += pts[i + 1] / n;
  }
  let r = 0;
  for (let i = 0; i < pts.length; i += 2) r = Math.max(r, Math.hypot(pts[i] - cx, pts[i + 1] - cz));
  return { pts, cx, cz, r, y0, y1 };
}

/** 两块凸多边形在 a 的边法线上有没有分开 */
function apart(a: number[], b: number[]): boolean {
  for (let i = 0; i < a.length; i += 2) {
    const j = (i + 2) % a.length;
    const nx = a[i + 1] - a[j + 1];
    const nz = a[j] - a[i];
    let a0 = Infinity;
    let a1 = -Infinity;
    let b0 = Infinity;
    let b1 = -Infinity;
    for (let k = 0; k < a.length; k += 2) {
      const d = a[k] * nx + a[k + 1] * nz;
      a0 = Math.min(a0, d);
      a1 = Math.max(a1, d);
    }
    for (let k = 0; k < b.length; k += 2) {
      const d = b[k] * nx + b[k + 1] * nz;
      b0 = Math.min(b0, d);
      b1 = Math.max(b1, d);
    }
    if (a1 < b0 || b1 < a0) return true;
  }
  return false;
}

function overlap(a: Piece, b: Piece): boolean {
  return a.y0 < b.y1 && b.y0 < a.y1 && Math.hypot(a.cx - b.cx, a.cz - b.cz) < a.r + b.r && !apart(a.pts, b.pts) && !apart(b.pts, a.pts);
}

export class Traverse {
  private key: unknown[] = [];
  private readonly m = new THREE.Matrix4();
  private readonly t = new THREE.Matrix4();
  private readonly q = new THREE.Quaternion();
  private readonly v = new THREE.Vector3();
  private readonly s = new THREE.Vector3();

  update(tank: Tank, weapons: readonly Weapon[]): void {
    const rear = REAR.map((slot) => weapons.find((w) => w.slot === slot)?.model ?? null);
    const key = [tank.gun, ...rear];
    if (key.every((k, i) => k === this.key[i])) return;
    this.key = key;
    // 挂件的每个零件：局部包围盒 + 换到车身坐标的矩阵（会转的头每个朝向一份）
    const parts: { box: THREE.Box3; m: THREE.Matrix4 }[] = [];
    rear.forEach((model, k) => {
      if (!model) return;
      const anchor = tank.anchors[REAR[k]];
      const yaws = model.turns ? Array.from({ length: YAWS }, (_, i) => (i / YAWS) * Math.PI * 2) : [model.head.rotation.y];
      model.root.traverse((o) => {
        const mesh = o as THREE.Mesh;
        // 安装演出时单独画的新零件（T143）还在滑进来的路上：不算，演完换成最终模型时会重算
        if (!mesh.isMesh || mesh.userData.noArc) return;
        const chain: THREE.Object3D[] = [];
        let head = false;
        for (let p: THREE.Object3D | null = mesh; p && p !== model.root; p = p.parent) {
          chain.push(p);
          if (p === model.head) head = true;
        }
        if (!mesh.geometry.boundingBox) mesh.geometry.computeBoundingBox();
        const box = mesh.geometry.boundingBox!;
        // 实例化的一排（T143 立弹 / 停着的无人机 / 舱盖）：每个实例位都算（按满额，不按这一刻显示几个）
        const inst = (mesh as THREE.InstancedMesh).isInstancedMesh ? (mesh as THREE.InstancedMesh) : null;
        for (const yaw of head ? yaws : [0]) {
          this.m.compose(anchor.position, NONE, this.s.setScalar(model.scale));
          for (let i = chain.length - 1; i >= 0; i--) {
            const c = chain[i];
            if (c === model.head) this.t.compose(c.position, this.q.setFromAxisAngle(UP, yaw), c.scale);
            else this.t.compose(c.position, c.quaternion, c.scale);
            this.m.multiply(this.t);
          }
          if (!inst) parts.push({ box, m: this.m.clone() });
          else for (let i = 0; i < inst.instanceMatrix.count; i++) {
            inst.getMatrixAt(i, this.t);
            parts.push({ box, m: this.m.clone().multiply(this.t) });
          }
        }
      });
    });
    let left = Math.PI;
    let right = Math.PI;
    const tp = tank.turret.position;
    // 炮管每一截：挂件零件切到它那一层高度（炮塔只绕竖轴转，高度不变）
    const gun = tank.gun.filter((b) => !b.isEmpty()).map((b) => ({ b, near: parts.map((p) => this.slab(p.box, p.m, b.min.y + tp.y, b.max.y + tp.y)).filter((p): p is Piece => !!p) }));
    if (gun.some((g) => g.near.length)) {
      const hit = (th: number) => gun.some(({ b, near }) => {
        const g = this.boxPiece(b, this.m.compose(tp, this.q.setFromAxisAngle(UP, th), ONE));
        return near.some((p) => overlap(g, p));
      });
      // 往一边转，第一个碰上的角度（一圈都没碰上 = -1）；左边碰上了右边一定也碰得上
      const sweep = (dir: number) => {
        for (let th = TURRET.free; th < Math.PI * 2 - TURRET.free; th += STEP) if (hit(dir * th)) return th;
        return -1;
      };
      const l = sweep(1);
      if (l > 0) {
        left = Math.max(TURRET.free, l - GAP);
        right = Math.max(TURRET.free, sweep(-1) - GAP);
      }
    }
    tank.arc.left = left;
    tank.arc.right = right;
  }

  /** 包围盒（局部）经矩阵 m 换到车身坐标，俯视的凸包 + 高度范围 */
  private boxPiece(b: THREE.Box3, m: THREE.Matrix4): Piece {
    const xz: number[] = [];
    let y0 = Infinity;
    let y1 = -Infinity;
    for (let i = 0; i < 8; i++) {
      this.v.set(i & 1 ? b.max.x : b.min.x, i & 2 ? b.max.y : b.min.y, i & 4 ? b.max.z : b.min.z).applyMatrix4(m);
      xz.push(this.v.x, this.v.z);
      y0 = Math.min(y0, this.v.y);
      y1 = Math.max(y1, this.v.y);
    }
    return piece(xz, y0, y1);
  }

  /** 包围盒（局部）经矩阵 m 换到车身坐标后，夹在高度 y0～y1 之间那一片的俯视凸包；碰不到这一层返回 null */
  private slab(b: THREE.Box3, m: THREE.Matrix4, y0: number, y1: number): Piece | null {
    const c: THREE.Vector3[] = [];
    for (let i = 0; i < 8; i++) c.push(new THREE.Vector3(i & 1 ? b.max.x : b.min.x, i & 2 ? b.max.y : b.min.y, i & 4 ? b.max.z : b.min.z).applyMatrix4(m));
    const xz: number[] = [];
    for (const p of c) if (p.y >= y0 && p.y <= y1) xz.push(p.x, p.z);
    // 12 条棱和上下两个平面的交点
    for (let i = 0; i < 8; i++) {
      for (const bit of [1, 2, 4]) {
        if (i & bit) continue;
        const a = c[i];
        const e = c[i | bit];
        for (const y of [y0, y1]) {
          if ((a.y - y) * (e.y - y) >= 0) continue;
          const t = (y - a.y) / (e.y - a.y);
          xz.push(a.x + (e.x - a.x) * t, a.z + (e.z - a.z) * t);
        }
      }
    }
    return xz.length >= 6 ? piece(xz, y0, y1) : null;
  }
}
