import { allOpen, newbieMode } from './Profile';
import { migrate, saveStore, type RawSave } from './saveStore';

/** 模式页的三页（T110） */
export type ModeTab = 'mode-run' | 'mode-zone' | 'mode-boss';

/**
 * 作战模式的局外记录（T110）：单独一份存档，不进 Profile（出了问题不碰正式存档）。
 * tab = 模式页上次看的哪一页；picks = 首领挑战上次选的升级次数；
 * days = 完成过今日任务的日子（dayKey，留最近 60 个）；clears = 累计完成几次（外观奖励按它）；at = 最近一次完成的时间戳
 */
export interface ModeData {
  v: typeof MODES_VERSION;
  tab: ModeTab;
  picks: number;
  days: number[];
  clears: number;
  at: number;
}

/** 存档槽（本地存储的键是 tank-rogue.modes） */
const SLOT = 'modes';
/** 版本号（T116）：改结构 = MIGRATIONS 加一级、这里 + 1（现在只有版本 1，链是空的） */
export const MODES_VERSION = 1;
const MIGRATIONS: Record<number, (d: RawSave) => RawSave> = {};
const TABS: readonly ModeTab[] = ['mode-run', 'mode-zone', 'mode-boss'];
const KEEP_DAYS = 60;
const fresh = (): ModeData => ({ v: MODES_VERSION, tab: 'mode-run', picks: 20, days: [], clears: 0, at: 0 });

export class ModeSave {
  /** slot = null：只读不写（?all=1；存档版本比游戏新） */
  private constructor(
    readonly data: ModeData,
    readonly slot: string | null,
  ) {}

  /** 跟着局外存档走：?newbie=1 用另一份，?newbie=reset 一起清掉，?all=1 只读不写 */
  static load(): ModeSave {
    const nb = newbieMode();
    const slot = nb ? `${SLOT}.newbie` : SLOT;
    const keep = allOpen() ? null : slot;
    if (nb === 'reset' && keep) saveStore.remove(slot);
    const p = nb === 'reset' ? null : ModeSave.parse(saveStore.read(slot));
    // 存档损坏：从空的开始，不影响正式存档
    return p ? new ModeSave(p.data, p.newer ? null : keep) : new ModeSave(fresh(), keep);
  }

  /** 解析（读档 / 导入共用）：JSON 文本或对象 → 迁移链 → 页名 / 日子不对的回默认；不是模式存档返回 null；newer = 版本比游戏新 */
  static parse(src: unknown): { data: ModeData; newer: boolean } | null {
    try {
      const obj = (typeof src === 'string' ? JSON.parse(src) : src) as RawSave | null;
      if (!obj || typeof obj !== 'object' || typeof obj.v !== 'number' || obj.v < 1) return null;
      const from = obj.v;
      const p = migrate(obj, 'v', MODES_VERSION, MIGRATIONS) as Partial<ModeData>;
      const base = fresh();
      const tab = TABS.includes(p.tab as ModeTab) ? (p.tab as ModeTab) : base.tab;
      const days = Array.isArray(p.days) ? p.days.filter((d) => typeof d === 'number') : [];
      return { data: { ...base, ...p, v: MODES_VERSION, tab, days, clears: Math.max(Number(p.clears) || 0, days.length) }, newer: from > MODES_VERSION };
    } catch {
      return null;
    }
  }

  /** 这一天的今日任务完成过没有 */
  doneOn(day: number): boolean {
    return this.data.days.includes(day);
  }

  /** 记一次今日任务完成：这一天第一次返回 true（发奖），已经完成过返回 false */
  finish(day: number): boolean {
    const d = this.data;
    if (d.days.includes(day)) return false;
    d.days = [...d.days, day].sort((a, b) => a - b).slice(-KEEP_DAYS);
    d.clears += 1;
    d.at = Date.now();
    this.save();
    return true;
  }

  set(patch: Partial<Pick<ModeData, 'tab' | 'picks'>>): void {
    Object.assign(this.data, patch);
    this.save();
  }

  /** 存不了就算了 */
  private save(): void {
    if (this.slot) saveStore.write(this.slot, JSON.stringify(this.data));
  }
}
