/** 瓦楞板贴图（T093）：一道道亮暗相间的楞（沿 v 方向），叠一点锈斑；和顶点色相乘 */
let corrugated: THREE.DataTexture | null = null;
function corrugatedTexture(): THREE.DataTexture {
  if (corrugated) return corrugated;
  corrugated = paint(128, (u, v) => {
    const rib = 0.78 + 0.22 * Math.sin(v * Math.PI * 2 * 24);
    const rust = Math.max(0, Math.sin(u * 17.3 + Math.sin(v * 9.1) * 2) * Math.sin(v * 13.7 + u * 3)) ** 3;
    return [rib * (1 - rust * 0.25), rib * (1 - rust * 0.4), rib * (1 - rust * 0.55)];
  });
  corrugated.wrapS = corrugated.wrapT = THREE.RepeatWrapping;
  corrugated.needsUpdate = true;
  return corrugated;
}

