/** 仓库残骸（T099）：后墙半截歪着、侧墙剩几截墙根，卷帘门拍在装卸台上，屋面塌进去叠成一堆 */
function shedRuinParts(): PartSpec[] {
  const S = AIRFIELD.shed;
  const half = S.w / 2;
  const r = seeded(131);
  const p: PartSpec[] = [
    { geo: box(0.3, 3.6, S.w - 2), color: 0x5c5c56, pos: [S.d - 0.2, 1.8, 0.6], rot: [0.06, 0, 0.12] },
    { geo: box(S.d * 0.5, 1.6, 0.3), color: 0x56564f, pos: [S.d * 0.65, 0.8, half], rot: [0, 0.05, 0.08] },
    { geo: box(S.d * 0.35, 2.6, 0.3), color: 0x4e4e48, pos: [S.d * 0.25, 1.3, -half], rot: [0.12, -0.04, 0] },
    { geo: box(4.8, 0.2, 7.4), color: 0x3a3c38, pos: [-2.2, 0.95, -3.2], rot: [0, 0.08, 0.22] },
    { geo: box(1.8, 0.9, 9.4), color: 0x7a766c, pos: [-0.9, 0.45, -3.2] },
  ];
  for (let i = 0; i < 7; i++) p.push({ geo: box(4 + r() * 3, 0.16, 4 + r() * 3), color: [0x5a5c56, 0x46463f, 0x64665e, 0x3a3632][i % 4], pos: [1.5 + r() * (S.d - 3), 0.5 + r() * 2.2, (r() - 0.5) * (S.w - 4)], rot: [(r() - 0.5) * 0.8, r() * Math.PI, (r() - 0.5) * 0.8] });
  for (let i = 0; i < 5; i++) p.push({ geo: box(1 + r() * 1.4, 0.5 + r() * 0.8, 1 + r() * 1.2), color: 0x4a4440, pos: [1 + r() * (S.d - 2), 0.3, (r() - 0.5) * (S.w - 2)], rot: [r(), r() * 3, r()] });
  return p;
}

/** 停机棚（T099）：门朝 −X 的敞棚，前高后低单坡顶，前后两排方柱 + 横梁 + 椽子，后墙 + 两侧半墙；棚里一辆加油拖车、一台发电车、一摞油桶 */
function shelterParts(): PartSpec[] {
  const S = AIRFIELD.shelter;
  const back = S.h - 1.2;
  const half = S.w / 2;
  const b = Math.atan2(S.h - back, S.d);
  const p: PartSpec[] = [];
  for (const z of [-half + 0.3, -2.6, 2.6, half - 0.3]) {
    p.push({ geo: box(0.36, S.h, 0.36), color: 0x5a5c58, pos: [0.3, S.h / 2, z] });
    p.push({ geo: box(0.36, back, 0.36), color: 0x5a5c58, pos: [S.d - 0.3, back / 2, z] });
    p.push({ geo: box(S.d, 0.3, 0.24), color: 0x4e504c, pos: [S.d / 2, (S.h + back) / 2 - 0.2, z], rot: [0, 0, -b] });
  }
  p.push(
    { geo: box(0.4, 0.5, S.w + 0.4), color: 0x4a4c48, pos: [0.3, S.h - 0.2, 0] },
    { geo: box(0.4, 0.5, S.w + 0.4), color: 0x4a4c48, pos: [S.d - 0.3, back - 0.2, 0] },
    { geo: box(Math.hypot(S.d, S.h - back) + 1.2, 0.16, S.w + 0.8), color: 0x74766e, pos: [S.d / 2, (S.h + back) / 2 + 0.1, 0], rot: [0, 0, -b] },
    { geo: box(0.12, back, S.w), color: 0x7e8078, pos: [S.d, back / 2, 0] },
    ...[-1, 1].map((s): PartSpec => ({ geo: box(S.d - 0.4, 2.6, 0.12), color: 0x787a72, pos: [S.d / 2 + 0.2, back - 1.5, s * half] })),
    { geo: box(4.2, 0.5, 1.8), color: 0x3e4636, pos: [5.6, 0.75, -3.6] },
    { geo: cyl(0.8, 0.8, 3.6, 12).rotateZ(HALF), color: 0x56603e, pos: [5.6, 1.7, -3.6] },
    ...[4.2, 7.0].map((x): PartSpec => ({ geo: cyl(0.4, 0.4, 2.0, 10).rotateX(HALF), color: 0x1c1c1c, pos: [x, 0.4, -3.6] })),
    { geo: box(2.2, 1.4, 1.6), color: 0x8a7a3a, pos: [6.4, 0.7, 3.4] },
    { geo: box(1.0, 0.8, 1.4), color: 0x2a2e30, pos: [5.4, 1.8, 3.4] },
    ...[[8.6, 5.6], [9.3, 5.6], [8.9, 6.3]].map(([x, z]): PartSpec => ({ geo: cyl(0.32, 0.32, 0.95, 10), color: 0x7a3a2a, pos: [x, 0.48, z] })),
  );
  return p;
}

/** 停机棚残骸（T099）：顶棚整块塌下来（前沿砸地、后沿搭在弯掉的后排柱子上），柱子折弯，拖车烧黑、油桶侧翻 */
function shelterRuinParts(): PartSpec[] {
  const S = AIRFIELD.shelter;
  const half = S.w / 2;
  const r = seeded(211);
  const p: PartSpec[] = [
    { geo: box(S.d + 1, 0.16, S.w + 0.6), color: 0x4e504a, pos: [S.d / 2, 1.3, 0.3], rot: [0.05, 0.04, 0.2] },
    { geo: box(0.12, 2.6, S.w * 0.6), color: 0x5a5c56, pos: [S.d, 1.3, -half * 0.35], rot: [0.1, 0, 0.18] },
  ];
  for (const z of [-half + 0.3, -2.6, 2.6, half - 0.3]) {
    p.push({ geo: box(0.36, 1.2 + r() * 1.2, 0.36), color: 0x3e3e3a, pos: [0.3, 0.6, z], rot: [(r() - 0.5) * 0.5, 0, 0.3 + r() * 0.4] });
    p.push({ geo: box(0.36, 2.6, 0.36), color: 0x3e3e3a, pos: [S.d - 0.5, 1.2, z], rot: [(r() - 0.5) * 0.3, 0, 0.35] });
  }
  p.push(
    { geo: cyl(0.8, 0.8, 3.6, 12).rotateZ(HALF), color: 0x2e2c28, pos: [5.6, 0.8, -3.6], rot: [0.25, 0.2, 0] },
    { geo: box(2.2, 1.0, 1.6), color: 0x2e2a26, pos: [6.6, 0.5, 3.6], rot: [0, 0.4, 0.15] },
    ...[[9.4, 5.2], [10.6, 6.6], [8.2, 7.2]].map(([x, z]): PartSpec => ({ geo: cyl(0.32, 0.32, 0.95, 10).rotateZ(HALF), color: 0x3a2a22, pos: [x, 0.32, z], rot: [0, r() * 3, 0] })),
  );
  return p;
}

/** 补给堆（T099，原点在中间）：托盘上几只弹药箱 / 木箱（叠两层）、一只带黄带的长弹药箱、一组油桶、旁边一堆盖篷布的 */
