/**
 * 玩家车（T117 联机伏笔）：敌人选目标、受伤、拾取、镜头按「哪一辆」走，不直接读 Game.tank。
 * 现在场上只有一辆，结果和以前一样；以后加车往 Game.players 里加，这里的函数不用改
 */
export interface PlayerTarget {
  alive?: boolean;
  /** 位置（世界坐标） */
  x: number;
  z: number;
  /** 速度（敌人算提前量用；坦克往前开 vz < 0）。vx 是平滑过的横向速度（空中单位用） */
  vx: number;
  vz: number;
}

interface XZ {
  readonly alive?: boolean;
  readonly x: number;
  readonly z: number;
}

const self = (p: unknown) => p as XZ;

/** 离 (x, z) 最近的玩家（list 不能空；只有一辆直接返回它）。pos 取每一项的位置，默认就是它自己 */
export function nearestPlayer<T>(list: readonly T[], x: number, z: number, pos: (p: T) => XZ = self): T {
  if (list.length === 1) return list[0];
  let best = list[0];
  let bd = Infinity;
  for (const p of list) {
    const q = pos(p);
    if (q.alive === false) continue;
    const d = (q.x - x) ** 2 + (q.z - z) ** 2;
    if (d < bd) {
      bd = d;
      best = p;
    }
  }
  return best;
}
