/** 究极助攻演出几秒（策划 3.8） */
const ASSIST_SEC = 1;

export interface DamageOpts extends AttackOpts {
  type?: DmgType;
  burn?: number;
  stun?: number;
  /** 穿甲：对重甲额外 +50% */
  ap?: boolean;
  /** 击退力度（活着的敌人被推开，被毁的被炸飞得更远） */
  knock?: number;
  /** 显示伤害数字（主炮命中） */
  show?: boolean;
  /** 终极伤害（来源 'ult'）：不暴击，计入 dmgUlt */
  ult?: boolean;
  /** 固定伤害（核弹 999）：打谁都是这个数，不吃护甲克制 / 首领瘫痪 +40% / 暴击 */
  fixed?: boolean;
  /** 护甲不打折（T017-5a：炼狱火海对车辆不打折；对步兵的加成照旧） */
  pure?: boolean;
  /** 从天上落下的爆炸（迫击炮 / 空袭 / 无人机 / 火箭落地）：精英「铁壁」的正面能量盾挡不住（T017-9A） */
  top?: boolean;
  /** 掀飞档（T024）：Game.explode 传入；T154 火控只让暴击榴弹进这一档。 */
  heave?: boolean;
  /** 激光持续照射（T070）：车辆不再每跳都「中弹放大」 */
  beam?: boolean;
  /** 不弹伤害数字（火神：同一目标按住时每 1 秒合成一个数，暴击也并进去） */
  quiet?: boolean;
}

/** 武器运行时能用到的一切 */
export interface CombatContext {
  /** 发起攻击的席位；旧工具上下文省略时按单人处理。 */
  readonly playerId?: number;
  time: number;
  dt: number;
  tankX: number;
  tankZ: number;
  /**
   * 对轰射程（D5 A1，米）：巨炮「轰天」在场时 = 150，主武器（主炮弹飞多远、激光多长、自动瞄准够多远打首领）和四件究极（天火 / 炼狱 / 天罗 / 黑潮）最远放到这么远；
   * 平时 0（各用各的射程）。由游戏层每帧写入
   */
  duel: number;
  enemies: Enemy[];
  /** 威胁分（T106）：自动瞄准的威胁值（正在瞄准玩家 ×1.5）× 这种伤害对它的护甲克制。副武器排目标、挑一团都按它，不按身份排除 */
  threat(e: Enemy, type: DmgType): number;
  /** 等效距离（T106，越小越先打）=（离 (x, z) 多远 + 10 米）÷ 威胁分：威胁优先、同威胁看距离，和主炮自动瞄准同一个算法（主炮另加方向、扎堆） */
  rank(e: Enemy, x: number, z: number, type: DmgType): number;
  /**
   * 迫击炮 / 空袭挑落点（T106 起按威胁）：[minR, maxR] 环里挑一个，它和 6 米内邻居的威胁分加起来最高（一样高选近的），返回这一团的中心。
   * sky = 首领「云垒」在场时先挑射程里的部件（T100B 能打天上那几件；T106 起按这件武器自己的射程 maxR 算，不放到对轰射程）
   */
  cluster(x: number, z: number, minR: number, maxR: number, sky?: boolean, type?: DmgType): { x: number; z: number; e: Enemy } | null;
  bullets: Bullets;
  projectiles: Projectiles;
  streaks: Streaks;
  hazards: Hazards;
  fx: Fx;
  /** 副武器分级特效（T143）：留痕 / 光斑 / 喷火面片 + 三档开关和闸门 */
  sub: SubFx;
  audio: AudioSystem;
  mods: ModStats;
  scene: THREE.Scene;
  /** 发起这次武器更新的车辆；每车上下文固定绑定，不随镜头切换。 */
  readonly tank: Tank;
  aimLine: AimLine;
  damage(e: Enemy, amount: number, fromX: number, fromZ: number, opts?: DamageOpts): boolean;
  electricShot?(e: Enemy, damage: number, opts: DamageOpts): void;
  ammoReturn?(): void;
  explode(x: number, z: number, radius: number, damage: number, opts?: ImpactOpts): void;
  /** 切开沿线的障碍（掩体 / 路障 / 残骸；不伤敌人，友方掩体不炸；路边景物不在这里，走 scenery.slice）：脉冲长枪沿线切割用 */
  cut(x: number, z: number, radius: number, force: number): void;
  /** 路边景物（T009）：光束 / 喷火 / 引雷这些不走爆炸的破坏入口 */
  scenery: SceneryDamage;
  /**
   * 激光主光束照到路上的路障 / 掩体（T017-14，World.beam 的「材质 × 武器」表）：按材质累计照射时间（金属烧成空壳再切两截、木头点着烧塌、油桶引爆、掩体打矮）；
   * 钢铁厂的烟囱 / 储罐每秒掉结构 = dps（光束这一刻的每秒伤害）× SCN.cut.dps（T032 A1）；
   * 返回光束停在多远（非聚焦线停在第一个立着的路障 / 烟囱 / 储罐上，pierce = 聚焦线穿过去）
   */
  beamProps(ox: number, oz: number, dx: number, dz: number, len: number, width: number, stage: number, pierce: boolean, dt: number, energy: number, dps: number): number;
  /** 喷火锥扫到路上的路障（T017-11A，World.flame）：木头路障（草垛 / 栅栏 / 木箱 / 马车 / 原木）烤 0.6 秒点着、0.5～2 秒后烧塌 */
  flameProps(ox: number, oz: number, ang: number, range: number, cone: number, dt: number): void;
  /** 激光主光束打在敌人身上 / 照到头落在空地上的那一点（T032 A2）：脚下是草地就照够时间点着那一格（Wildfire.heat） */
  groundHeat(x: number, z: number, dt: number): void;
  /**
   * 主炮马上要打的目标（T018-1「不抢主炮」）：主炮 / 火箭有弹（或 0.5 秒内装好）时它锁定的那个，否则 null；
   * 机枪 / 特斯拉选目标时跳过它（只剩它一个时照打）
   */
  coreLock(): Enemy | null;
  /** 本局打出的联动改装（T018-link） */
  links: ReadonlySet<LinkId>;
  /** 引导轰炸的指示烟（我方浅黄，T130；最新的在最后；无人机扎中时 Game 加，6 秒后去掉） */
  linkMarks: { x: number; z: number; t: number }[];
  /** 电磁轰炸的电离带：(x, z) 在不在带里（带里特斯拉跳跃 +50%） */
  ionAt(x: number, z: number): boolean;
  /** 某件副武器现在的一个数值（联动要用别的武器的单发伤害 / 燃烧；没装为 0） */
  weaponStat(id: WeaponId, key: '伤害' | '燃烧'): number;
  /** 联动效果发生了（T143）：两件挂件上的联动模块一起闪 0.2 秒 */
  linkFlash(id: LinkId): void;
  /** 日常震动（走合并窗口、封顶 0.6，T017-15A）；终极模块的 UltContext 里这一项走重事件档 */
  shake(amount: number): void;
  /** 持续嗡震（激光出光，每帧给目标强度，不累加） */
  hum(amount: number): void;
  /** 镜头下压（大炮开火） */
  punch(amount: number): void;
  /** 主武器开火的画面后坐（T134，CameraRig.recoil）：(dx, dz) = 出膛方向，deg = 顶出去多少度，settle = 回位秒数；震动设置照乘，低画质再打折 */
  recoil(dx: number, dz: number, deg: number, settle?: number): void;
  /** 画质档（火神曳光 / 弹壳 / 弹沟按档减，D1-032 第 8.7 节） */
  tier: 'high' | 'medium' | 'low';
  /** 自动瞄准开着没有（火神换目标用；手动瞄准时目标倒了不换） */
  autoAim: boolean;
  /**
   * 和点按开炮同一套评分选目标（Game.pickChargeTarget）：aim = 世界方向（0 = 正前方，正数向右；null = 自动瞄准，一圈里炮塔转得到的都算），cone = 吸附半角，
   * reach = 普通敌人够多远（首领部件 / 拦路精英另按 100 米或对轰射程）
   */
  aimPick(aim: number | null, cone?: number, reach?: number): Enemy | null;
  /** 主武器抬不抬得上去（T131 对空仰角）：天上的目标仰角超过 AA.elev 就够不着；地面目标都够得着 */
  canElevate(e: Enemy): boolean;
  /** 主武器想打却抬不上去（T131）：目标头上弹「仰角不够」（同一时间只弹一个） */
  tooHigh(e: Enemy): void;
}

/** 仰角（度，T131）：从坦克炮塔中心（坦克地面往上 AA.mount 米）看 e（飞蝗看胸口） */
export function elevation(e: Enemy, tank: THREE.Vector3): number {
  const p = e.group.position;
  return THREE.MathUtils.radToDeg(Math.atan2(p.y + e.aimLift - tank.y - AA.mount, Math.max(0.01, Math.hypot(p.x - tank.x, p.z - tank.z))));
}

/** 主武器 id 抬不抬得上去打 e（T131）：地面目标、不限仰角的（火箭 / 火神）都行 */
export function canElevate(id: CoreId, e: Enemy, tank: THREE.Vector3): boolean {
  const lim = AA.elev[id];
  return !e.flying || lim >= 90 || elevation(e, tank) <= lim;
}

const rand = (a: number, b: number) => a + Math.random() * (b - a);
// 挂件动作用的临时量（舱盖矩阵、灯色）
const _m = new THREE.Matrix4();
const _p = new THREE.Vector3();
const _qq = new THREE.Quaternion();
const _x = new THREE.Vector3(1, 0, 0);
const _s1 = new THREE.Vector3(1, 1, 1);
const _c = new THREE.Color();
const _fd = new THREE.Vector3();
const _fp = new THREE.Vector3();
/** 影响玩法的随机走「我方武器」流（T117，可设种子）；只管好看的照用 rand */
const fireRand = (a: number, b: number) => a + rng.weapon() * (b - a);
/** 进化后的单发伤害（T018-1 对齐；燃烧 = 喷火器进化后的燃烧） */
/** 一件副武器现在的数值（联动用）：进化后的单发 / 燃烧按上面两张表 */
export function weaponStatOf(w: Weapon, key: '伤害' | '燃烧'): number {
  const value = w.evolved ? key === '伤害' ? EVO_SHOT[w.def.id] : w.def.id === 'flamer' ? EVO_BURN : 0 : w.def.stats(w.form)[key] ?? 0;
  return value * w.power;
}
/** 迫击炮 / 空袭的爆炸画面随等级放大（T018-1）：1 级 ×1 → 5 级 / 进化 ×1.3 */
const subFx = (w: Weapon) => (w.evolved ? 1.3 : 1 + (Math.min(5, w.form) - 1) * 0.075);
/** 炮塔约定的朝向角：0 = -Z，正值向左 */
export const angleTo = (x: number, z: number, tx: number, tz: number) => Math.atan2(-(tx - x), -(tz - z));

/**
 * 副武器挑一个目标（T106，制作人「武器都会优先攻击最大射程内的高威胁目标」「打不到是因为打不到，不是强制不打」）：
 * 射程里等效距离（ctx.rank）最小的那个。不按身份排除（首领部件、精英、步兵一起排），只看够不够得着（平面距离 range）、
 * 打不打得到天上（air）；身后的照样排（T127，原来身后 6 米外的不算）。yieldTo = 让给主炮的那个（T018-1「不抢主炮」：射程里只剩它一个时照打）
 */
function pickTarget(ctx: CombatContext, x: number, z: number, range: number, type: DmgType, air: boolean, yieldTo: Enemy | null = null, mount?: Weapon): Enemy | null {
  let best: Enemy | null = null;
  let bs = Infinity;
  let only = false;
  for (const e of ctx.enemies) {
    if (!e.alive || (!air && e.flying)) continue;
    if (mount && !mount.canTarget(ctx, e)) continue;
    if (Math.hypot(e.group.position.x - x, e.group.position.z - z) >= range) continue;
    if (e === yieldTo) {
      only = true;
      continue;
    }
    const s = ctx.rank(e, x, z, type);
    if (s < bs) {
      bs = s;
      best = e;
    }
  }
  return best ?? (only ? yieldTo : null);
}

/**
 * 画出来的挂件朝向（T242，同 T195 VULCAN.look）：临界阻尼弹簧跟着瞄准走，ω = w、角速度上限 max（弧度 / 秒）、
 * 最多落后逻辑朝向 lag 弧度。只管画面：索敌、枪口、伤害、弹道照旧按逻辑朝向
 */
export const SUB_LOOK: Record<WeaponId, { w: number; max: number; lag: number }> = {
  mg: { w: 12, max: 8, lag: 0.6 },
  mortar: { w: 8, max: 5, lag: Math.PI },
  flamer: { w: 14, max: 9, lag: 0.3 },
  tesla: { w: 10, max: 6, lag: 0.5 },
  drones: { w: 10, max: 6, lag: 0.5 },
  airstrike: { w: 10, max: 6, lag: 0.5 },
};

export abstract class Weapon {
  /** 同型号也有独立编号；换位、合成和读档都保留幸存件的编号。 */
  uid = 0;
  level = 1;
  evolved = false;
  /** 获得顺序（槽位条排序） */
  order = 0;
  model: MountModel;
  protected readonly v = new THREE.Vector3();
  protected readonly w = new THREE.Vector3();
  private headYaw = 0;
  /** 画出来的朝向和角速度（T242，相对挂点）；lookYaw = 这一帧画面要压的朝向（机枪不带扫射摆动），null = 跟逻辑朝向 */
  private drawYaw = 0;
  private drawV = 0;
  private drawOn = false;
  private lookYaw: number | null = null;
  protected frameYaw = 0;
  get form(): number { return subForm(this.def.id, this.level); }
  get power(): number { return subPower(this.def.id, this.level); }

  canTarget(ctx: CombatContext, enemy: Enemy): boolean {
    const p = enemy.group.position;
    return subCanAim(this.def.id, this.slot, this.frameYaw, p.x - ctx.tankX, p.z - ctx.tankZ);
  }

  /** 索敌、枪口和画出来的车头使用同一朝向；主炮仍走原来的瞄准姿态。 */
  prepareFrame(ctx: CombatContext): void {
    this.model.head.rotation.y = this.headYaw;
    this.lookYaw = null;
    this.anchor.getWorldDirection(this.w);
    const parentYaw = Math.atan2(this.w.x, this.w.z);
    this.frameYaw = TURRET_SLOTS.includes(this.slot) ? parentYaw : ctx.tank.hullYaw;
    const current = parentYaw + this.headYaw;
    const arc = subArc(this.def.id, this.slot);
    if (arc.half < Math.PI && Math.abs(subAngle(current - this.frameYaw - arc.center)) > arc.half) this.aim(this.frameYaw + arc.center, 1, 1);
  }

  /** 只存会影响下一轮开火的剩余量，不保存模型或目标引用。 */
  saveRuntime(): Record<string, number> { return {}; }
  restoreRuntime(_state: Record<string, number>): void {}
  absorbRuntime(other: Weapon): void {
    const state = this.saveRuntime();
    for (const [key, value] of Object.entries(other.saveRuntime())) state[key] = Math.max(state[key] ?? 0, value);
    this.restoreRuntime(state);
  }
  /** 画质档（每帧从 ctx.tier 记下来；低画质安装演出不滑出、只白闪，策划 2.4） */
  protected q: 'high' | 'medium' | 'low' = 'high';
  /** 参与的联动 / 合成的究极（Arsenal 打出联动 / 合成时设好再 rebuild，挂件插上联动模块 / 究极配套，T143） */
  link: LinkId | null = null;
  ult: FusionId | null = null;
  /** 联动模块闪一下的剩余秒数 */
  private flashT = 0;

  /** 联动效果发生了：这件挂件的联动模块闪 0.2 秒（策划 3.7） */
  linkFlash(): void {
    this.flashT = LINK_GLOW.flash;
  }

  /** 究极助攻演出（策划 3.8：按下究极时配方两件各做 1 秒助攻动作）：还剩几秒、哪件究极 */
  protected assistT = 0;
  protected assistId: FusionId | null = null;
  private assistFirst = false;
  assist(id: FusionId): void {
    this.assistT = ASSIST_SEC;
    this.assistId = id;
    this.assistFirst = true;
  }
  /** 每帧 update 之后（Arsenal 调）：究极助攻演出压在这一帧的挂件动作上面 */
  after(ctx: CombatContext): void {
    this.stepLook(ctx.dt);
    if (this.assistT <= 0) return;
    this.assistT -= ctx.dt;
    this.assistStep(ctx, Math.min(1, 1 - this.assistT / ASSIST_SEC), this.assistFirst);
    this.assistFirst = false;
  }
  /** 每件自己的助攻动作（k = 0 → 1 演到哪，first = 第一帧）；默认只让发光件全亮 */
  protected assistStep(_ctx: CombatContext, _k: number, _first: boolean): void {
    if (this.model.glow) this.model.glow.value = GLOW_MAX;
  }
  /** 留一块地面痕迹（转角随机）：究极配方两件留 10 秒、发光边换主题色、至少冷 2 秒（策划 3.9 一级比一级高） */
  protected mark(ctx: CombatContext, frame: SubMark, x: number, z: number, w: number, d: number, life: number, cool: number, glow: number, alpha?: number, rot = Math.random() * 6.28): number {
    return this.ult ? ctx.sub.mark(frame, x, z, w, d, rot, ULT_TRACE, Math.max(cool, 2), ULT_THEME[this.ult], alpha) : ctx.sub.mark(frame, x, z, w, d, rot, life, cool, glow, alpha);
  }
  /** 低画质挂件不投影（策划 2.4）：按模型 + 档记一下，变了才改 */
  private castFor: MountModel | null = null;
  private castOn = true;

  constructor(
    readonly def: WeaponDef,
    public anchor: THREE.Object3D,
    public slot: number,
    protected readonly geo: GeoCache,
  ) {
    this.model = this.build([]);
    anchor.add(this.model.root);
  }

  /**
   * 焊装演出（T143 安装反馈，策划 2.6）：t 已演秒数、dur 总长；cross = 跨档（→3 / →5）、evolve = 进化变身（旧主体 ghost 先收进去）；
   * 新零件（model.fresh）单独画，滑出 / 升起 0.6 秒 + 白闪 0.3 秒，演完整个模型按最终形态重搭一遍
   */
  private inst: { t: number; dur: number; cross: boolean; evolve: boolean; ghost: MountModel | null; clicked: boolean } | null = null;
  private popScale = 1;
  /** 第一次 rebuild 是新装上（只弹一下 + 焊花），之后才是升级 */
  private installed = false;

  private build(fresh: string[]): MountModel {
    return mountModel(this.geo, this.def.id, this.form, this.evolved, { side: this.anchor.position.x < 0 ? -1 : 1, rear: REAR_SLOTS.includes(this.slot), turret: TURRET_SLOTS.includes(this.slot), paint: this.anchor.userData.paint, uvAt: this.anchor.position.toArray(), fresh, link: this.link, ult: this.ult });
  }

  moveTo(anchor: THREE.Object3D, slot: number): void {
    this.finishInstall();
    this.anchor = anchor;
    this.slot = slot;
    this.rebuild();
  }

  /** 换上 m（朝向接着上一个模型），旧的拿掉、释放它自己建的材质 */
  private swap(m: MountModel, keepOld = false): void {
    const old = this.model;
    if (!keepOld) {
      old.root.removeFromParent();
      for (const mat of old.mats) mat.dispose();
    }
    this.model = m;
    this.anchor.add(m.root);
    m.head.rotation.y = this.drawOn ? this.drawYaw : this.headYaw;
  }

  /** 等级 / 进化变化后换模型：新零件单独画、演一段安装反馈（第一次装上只弹一下） */
  rebuild(): void {
    this.finishInstall();
    const prev = this.model;
    const lv = this.form;
    const first = !this.installed;
    this.installed = true;
    const fresh = first ? [] : formKeys(this.def.id, lv, this.link, this.ult).filter((k) => !prev.keys.includes(k));
    const evolve = !first && lv >= EVO && prev.lv < EVO;
    const cross = !first && gradeOf(lv) !== gradeOf(prev.lv);
    this.swap(this.build(fresh), evolve);
    this.popScale = this.model.scale;
    this.inst = { t: 0, dur: evolve ? INSTALL.evolve : cross ? INSTALL.cross : INSTALL.pop, cross, evolve, ghost: evolve ? prev : null, clicked: false };
    if (this.model.fresh.length && this.q === 'low') for (const f of this.model.fresh) f.enter = { kind: 'pop', hinge: f.enter.hinge };
    this.stepInstall(0);
  }

  /** 进化变身收进去的旧主体：拿掉、释放它的材质 */
  private dropGhost(): void {
    const g = this.inst?.ghost;
    if (!g) return;
    this.inst!.ghost = null;
    g.root.removeFromParent();
    for (const mat of g.mats) mat.dispose();
  }

  /** 演完（或被下一次升级打断）：按最终形态重搭，ghost 拿掉 */
  private finishInstall(): void {
    if (!this.inst) return;
    this.dropGhost();
    this.inst = null;
    if (this.model.fresh.length) this.swap(this.build([]));
    this.model.root.scale.setScalar(this.model.scale);
  }

  /** 一帧焊装演出：整体弹一下（进化 = 旧的先收进去、新的再升上来）+ 新零件进场 + 白闪 */
  private stepInstall(dt: number): void {
    const s = this.inst;
    if (!s) return;
    s.t += dt;
    const I = INSTALL;
    // 进化：前 0.5 秒旧主体往下收、压扁，新主体还没出来；之后新主体 0.7 秒弹出来
    const t0 = s.evolve ? I.sink : 0;
    if (s.ghost) {
      const g = Math.min(1, s.t / I.sink);
      const gs = s.ghost.scale;
      s.ghost.root.scale.set(gs * (1 - g * 0.5), gs * Math.max(0.05, 1 - g), gs * (1 - g * 0.5));
      if (g >= 1) this.dropGhost();
    }
    const pd = s.evolve ? s.dur - I.sink : s.cross ? I.cross : I.pop;
    const k = Math.max(0, Math.min(1, (s.t - t0) / pd));
    // 先放大过冲再回落（进化开头那一截缩成 0，等旧主体收完）
    const pop = s.t < t0 ? 0 : k < 0.5 ? 0.3 + k * 2 * 0.95 : 1.25 - (k - 0.5) * 2 * 0.25;
    this.model.root.scale.setScalar(this.popScale * pop);
    // 新零件：t0 + 0.1 秒起滑出 / 升起 0.6 秒（回弹一点），到位前后白闪 0.3 秒
    const e0 = t0 + 0.1;
    const e = Math.max(0, Math.min(1, (s.t - e0) / I.enter));
    const ease = e >= 1 ? 1 : 1 + 2.2 * (e - 1) ** 3 + 1.2 * (e - 1) ** 2;
    for (const f of this.model.fresh) {
      const h = f.holder;
      const hinge = f.enter.hinge ?? [0, 0, 0];
      h.position.set(hinge[0], hinge[1], hinge[2]);
      h.scale.setScalar(1);
      if (f.enter.kind === 'slide' && f.enter.from) h.position.set(hinge[0] + f.enter.from[0] * (1 - ease), hinge[1] + f.enter.from[1] * (1 - ease), hinge[2] + f.enter.from[2] * (1 - ease));
      else if (f.enter.kind === 'rise') h.scale.set(1, Math.max(0.03, ease), 1);
      else h.scale.setScalar(Math.max(0.01, ease));
      // 进场时淡淡发白，到位前后白闪一下（进化整个新主体都是新零件，白闪压低一点）
      const fl = s.t - e0 - I.enter * 0.6;
      f.mat.emissiveIntensity = fl < 0 ? Math.min(1, e / 0.6) * 0.35 : Math.max(0, (s.evolve ? 1 : 1.3) * (1 - fl / I.flash));
    }
    if (s.t >= s.dur && s.t - e0 >= I.enter + I.flash * 0.4) this.finishInstall();
  }

  /** 每帧：联动模块 / 究极配套的灯 + 焊装演出 + 焊花 / 声音 */
  animate(ctx: CombatContext): void {
    this.q = ctx.tier;
    // 究极配套的灯跟炮塔究极套件的指示灯同色同步（装载中暗、最后几秒慢闪、待发常亮）；联动模块平时半亮，联动触发时两件一起闪
    const g2 = this.model.glow2;
    if (g2) {
      this.flashT = Math.max(0, this.flashT - ctx.dt);
      const kit = this.ult ? ctx.tank.kitLamp() : null;
      if (this.flashT > 0) g2.value.setScalar(GLOW_MAX);
      else if (kit) g2.value.copy(kit).multiplyScalar(this.assistT > 0 ? GLOW_MAX * 1.2 : 1.4);
      else g2.value.setScalar(LINK_GLOW.base);
    }
    const cast = !!ctx.sub.cfg.shadow;
    if (this.castFor !== this.model || this.castOn !== cast) {
      this.castFor = this.model;
      this.castOn = cast;
      this.model.root.traverse((o) => {
        if ((o as THREE.Mesh).isMesh) o.castShadow = cast && o.userData.cast === true;
      });
    }
    const s = this.inst;
    if (!s) return;
    const begin = s.t === 0;
    this.stepInstall(ctx.dt);
    if (begin || Math.random() < 0.5) {
      this.anchor.getWorldPosition(this.v);
      ctx.fx.sparks(this.v.x, this.v.y + 0.3, this.v.z, begin ? (s.cross || s.evolve ? 16 : 10) : 2, 0xfff0b0, 6);
      if (begin) {
        ctx.fx.glint(this.v.x, this.v.y + 0.5, this.v.z, 0xffe0a0, s.evolve ? 3.4 : 2.2);
        ctx.audio.play('crunch');
      }
    }
    // 跨档 / 进化：新零件到位那一下补一声上膛「咔嗒」
    if ((s.cross || s.evolve) && !s.clicked && s.t >= (s.evolve ? INSTALL.sink : 0) + 0.1 + INSTALL.enter * 0.6) {
      s.clicked = true;
      ctx.audio.play('reload', 0.9);
    }
  }

  dispose(): void {
    this.dropGhost();
    this.inst = null;
    this.model.root.removeFromParent();
    for (const mat of this.model.mats) mat.dispose();
  }

  abstract update(ctx: CombatContext): void;

  protected stat(key: string): number {
    return (this.def.stats(this.form)[key] ?? 0) * (key === '伤害' || key === '燃烧' ? this.power : 1);
  }

  /** 第 i 个枪口的世界坐标 */
  protected muzzle(i: number, out: THREE.Vector3): THREE.Vector3 {
    const m = this.model.muzzles[i % Math.max(1, this.model.muzzles.length)];
    return m ? m.getWorldPosition(out) : this.anchor.getWorldPosition(out);
  }

  /** 让挂件的转动部分朝向世界角 angle（平滑） */
  protected aim(angle: number, rate = 10, dt = 0.016, look = angle): void {
    const arc = subArc(this.def.id, this.slot);
    const fit = (a: number) => arc.half < Math.PI ? this.frameYaw + arc.center + THREE.MathUtils.clamp(subAngle(a - this.frameYaw - arc.center), -arc.half, arc.half) : a;
    angle = fit(angle);
    this.anchor.getWorldDirection(this.w);
    const parentYaw = Math.atan2(this.w.x, this.w.z);
    let diff = angle - parentYaw - this.headYaw;
    while (diff > Math.PI) diff -= Math.PI * 2;
    while (diff < -Math.PI) diff += Math.PI * 2;
    this.headYaw += diff * Math.min(1, rate * dt);
    this.model.head.rotation.y = this.headYaw;
    this.lookYaw = this.headYaw + subAngle(fit(look) - parentYaw - this.headYaw);
  }

  /** 每帧逻辑做完：画出来的朝向弹簧跟上（T242），转动部分换成画出来的朝向；下一帧 prepareFrame 换回逻辑朝向 */
  private stepLook(dt: number): void {
    const L = SUB_LOOK[this.def.id];
    if (!this.drawOn) {
      this.drawYaw = this.headYaw;
      this.drawV = 0;
      this.drawOn = true;
    }
    const goal = this.lookYaw ?? this.headYaw;
    this.drawV = THREE.MathUtils.clamp(this.drawV + (subAngle(goal - this.drawYaw) * L.w * L.w - this.drawV * 2 * L.w) * dt, -L.max, L.max);
    this.drawYaw += this.drawV * dt;
    const lag = subAngle(this.drawYaw - this.headYaw);
    this.drawYaw = this.headYaw + (Math.abs(lag) > L.lag ? Math.sign(lag) * L.lag : lag);
    this.model.head.rotation.y = this.drawYaw;
  }

  /** 画出来的朝向比逻辑朝向多转了多少（弧度） */
  protected drawTurn(): number {
    return this.drawOn ? this.drawYaw - this.headYaw : 0;
  }

  /** 逻辑枪口 p 绕转动部分转到画出来的朝向（T242，只给枪口焰 / 曳光用） */
  protected drawMuzzle(p: THREE.Vector3, out: THREE.Vector3): THREE.Vector3 {
    const d = this.drawTurn();
    const c = this.model.head.getWorldPosition(_p);
    const dx = p.x - c.x, dz = p.z - c.z, cs = Math.cos(d), sn = Math.sin(d);
    return out.set(c.x + dx * cs + dz * sn, p.y, c.z - dx * sn + dz * cs);
  }
}

// ---------------------------------------------------------------- 机枪

class MgWeapon extends Weapon {
  readonly rateStack = new RateStack();
  private heat = 0;
  private overheat = 0;
  private burst = 1;
  private pause = 0;
  private timer = 0;
  private shot = 0;
  /** 上一发离现在多久（★ 管口热点、弹鼓转动按它） */
  private idle = 9;
  /** 画出来的枪口（T242：枪口焰、曳光从画出来的枪管出） */
  private readonly dm = new THREE.Vector3();
  /** T244：每根管上一发离现在多久（枪口焰按它亮）、火球计数、烟计时 */
  private readonly fired = [9, 9];
  private balls = 0;
  private puff = 0;

  override saveRuntime(): Record<string, number> { return { heat: this.heat, overheat: this.overheat, pause: this.pause, timer: this.timer }; }
  override restoreRuntime(s: Record<string, number>): void {
    this.heat = s.heat ?? this.heat; this.overheat = s.overheat ?? this.overheat;
    this.pause = s.pause ?? this.pause; this.timer = s.timer ?? this.timer;
  }

  update(ctx: CombatContext): void {
    this.rateStack.factor(ctx.mods.rate, ctx.time);
    const dt = ctx.dt;
    const evo = this.evolved;
    const o = this.muzzle(0, this.v);
    if (this.model.spinner) this.model.spinner.rotation.z += dt * (this.heat > 0.05 || evo ? 40 : 4);
    // T143：5 级枪管跟着连射热度从钢灰烧到暗红；★ 6 个管口热点开火时亮、停火慢慢暗下去，弹鼓跟着射速转
    this.idle += dt;
    for (let i = 0; i < this.fired.length; i++) this.fired[i] += dt;
    const md = this.model;
    if (md.heat) md.heat.emissiveIntensity = Math.min(GLOW_MAX, this.heat ** 1.6 * 1.4);
    if (md.glow) md.glow.value = 0.3 + (GLOW_MAX - 0.3) * Math.max(0, 1 - this.idle / 0.5);
    if (md.pivots.drum && this.idle < 0.2) md.pivots.drum.rotation.x -= dt * 7;
    // T018-1：射程 44 → 60（进化 66），不抢主炮马上要打的目标；T106：射程里按威胁排（小口径打重甲只崩火花，克制算进威胁分）
    const target = pickTarget(ctx, o.x, o.z, evo ? 66 : this.stat('射程'), 'small', true, ctx.coreLock(), this);
    if (this.overheat > 0) {
      this.overheat -= dt;
      this.heat = Math.max(0, this.heat - dt * 0.8);
      if (Math.random() < 0.4) ctx.fx.steam(o.x, o.y + 0.2, o.z);
      return;
    }
    if (!target) {
      this.heat = Math.max(0, this.heat - dt * 0.5);
      return;
    }
    const tx = target.group.position.x;
    const tz = target.group.position.z;
    const base = angleTo(o.x, o.z, tx, tz);
    const sweep = Math.sin(ctx.time * 6.5) * (evo ? 0.22 : 0.08);
    // T242：逻辑照旧带扫射摆动，画出来的枪管只压着目标
    this.aim(base + sweep, 16, dt, base);
    if (!evo) {
      if (this.pause > 0) {
        this.pause -= dt;
        this.heat = Math.max(0, this.heat - dt * 0.4);
        return;
      }
      this.burst -= dt;
      if (this.burst <= 0) {
        this.pause = 0.25;
        this.burst = fireRand(0.9, 1.8);
      }
    }
    const guns = evo ? 2 : this.stat('枪管');
    const rate = (evo ? 30 : this.stat('射速') * (1 + this.heat * 0.5)) * (guns > 1 ? 1.6 : 1);
    const dmg = evo ? EVO_SHOT.mg * this.power : this.stat('伤害');
    const dist = Math.hypot(tx - o.x, tz - o.z);
    // 曳光按档（T143 SUB_FX.mg，原来 T018-1 的 0.42 / 5 级 0.6 / 进化 0.7）：0.42 / 0.5 / 0.6 / 0.75，每 3 发一发更亮更长；
    // 5 级起三段（枪口白热短芯 → 黄铜主段 → 末段暗红拖尾，中画质两段、低画质一段），飞行中的弹头跟着加粗、换黄铜色
    const F = SUB_FX.mg;
    const g = gradeOf(this.form);
    const tw = F.tracer[g];
    const segs = Math.min(F.segs[g], ctx.sub.cfg.seg);
    this.timer -= dt;
    while (this.timer <= 0) {
      this.timer += 1 / (rate * this.rateStack.factor(ctx.mods.rate, ctx.time));
      this.rateStack.fire(1, ctx.time, ctx.mods.rate);
      this.idle = 0;
      const mi = this.shot++ % Math.max(1, this.model.muzzles.length);
      const p = this.muzzle(mi, this.w);
      if (mi < this.fired.length) this.fired[mi] = 0;
      this.balls++;
      const arc = subArc(this.def.id, this.slot), center = this.frameYaw + arc.center;
      const spread = base + sweep + (rng.weapon() - 0.5) * 0.05;
      const dir = arc.half === Math.PI ? spread : center + THREE.MathUtils.clamp(subAngle(spread - center), -arc.half, arc.half);
      const dx = -Math.sin(dir);
      const dz = -Math.cos(dir);
      // 曳光弹：极快，飞到目标附近落地（没打中就在地上溅起尘土）；目标在天上（T091）就斜着往上打，打空了接着往上飞
      ctx.bullets.aim = target;
      const b = ctx.bullets.spawn('mg', p.x, p.z, dx * 150, dz * 150, dmg, true);
      ctx.bullets.aim = null;
      // T242：枪口焰、近段曳光从画出来的枪管出、顺着画出来的枪管（子弹本身照旧）
      const q = this.drawMuzzle(p, this.dm);
      const fd = dir + this.drawTurn();
      const fx = -Math.sin(fd);
      const fz = -Math.cos(fd);
      b.life = (dist + (b.air ? fireRand(2, 10) : fireRand(-1, 6))) / 150;
      b.dtype = 'small';
      b.pierce = evo || this.form >= 5 ? 1 : 0;
      b.sizeW = F.bulletW[g];
      b.sizeL = F.bulletL[g];
      // 究极换装（策划 3.8）：炼狱曳光橙红、铁雨白热芯
      b.tint = this.ult === 'inferno' ? 0xff7a3a : this.ult === 'gunship' ? 0xfff4e0 : F.color[g];
      b.grade = g;
      // 枪口火光：中心亮点 + 前向与两侧的星芒（5 级起换成 flame() 的火舌）
      if (g < 2) ctx.fx.glow.emit({ x: q.x + fx * 0.3, y: q.y, z: q.z + fz * 0.3, life: 0.05, size: 1.5, size1: 0.6, color: 0xfff2c0, frame: 0 });
      const hot = this.shot % 3 === 0;
      const len = hot ? F.hot[g] : 1.6;
      if (segs >= 3) ctx.streaks.add(q.x, q.y, q.z, q.x + fx * 1.2, q.y, q.z + fz * 1.2, tw * 0.75, 0xfff6e2, 1, 0.04);
      ctx.streaks.add(q.x, q.y, q.z, q.x + fx * len, q.y, q.z + fz * len, hot ? tw * 1.25 : tw, g >= 2 ? (hot ? 0xffe0a0 : F.color[g]) : hot ? 0xfff0c8 : 0xffd890, hot ? 1 : 0.95, hot ? 0.06 : 0.045);
      if (segs >= 2 && g >= 2) ctx.streaks.add(q.x + fx * len, q.y, q.z + fz * len, q.x + fx * (len + 1.5), q.y, q.z + fz * (len + 1.5), tw * 0.8, 0xc0461a, 0.7, 0.06);
      if (g < 2) ctx.streaks.add(q.x - fz * 0.5, q.y, q.z + fx * 0.5, q.x + fz * 0.5, q.y, q.z - fx * 0.5, 0.22, 0xffc070, 0.8, 0.035);
      // 抛壳
      ctx.fx.glow.emit({ x: q.x, y: q.y, z: q.z, vx: -fz * rand(2, 4), vy: rand(2.5, 4.5), vz: fx * rand(2, 4), life: 0.45, size: 0.16, color: 0xe0b860, frame: 0, gravity: -22 });
      ctx.fx.flash(q.x, q.y, q.z, 60);
      // 枪口光斑：5 级起每 3 发、3～4 级每 6 发在车前地面亮一下（假光，低画质不放）
      if (g >= 1 && this.shot % (g >= 2 ? 3 : 6) === 0) ctx.sub.spot(q.x + fx * 1.5, q.z + fz * 1.5, 2.4, 0xffd890, 0.07, 0.4);
      // 音效：3 级起两挺交替音高各偏 ±3%；4 级起每 3 发叠一层 0.05 秒低频「咚」；★ 转管嗡鸣垫底
      ctx.audio.play('mg', 1, g >= 1 ? (this.shot % 2 ? 0.97 : 1.03) : 1);
      if (this.form >= 4 && this.shot % 3 === 0) ctx.audio.play('subThud', 0.45);
      if (g === 3) ctx.audio.play('brrt', 0.4);
    }
    if (g >= 2) this.flame(ctx, g);
    if (!evo) {
      this.heat += dt / 3.2;
      if (this.heat >= 1) {
        // 空爆霰弹（T018-link）：机枪过热时间 −30%
        this.overheat = this.link === 'airburst' ? 0.84 : 1.2;
        ctx.audio.play('steam');
        // 5 级：过热「嘶」之后一声枪管余响
        if (g >= 2) ctx.audio.play('subRing', 0.8, 1, 0.35);
      }
    }
  }

  /**
   * T244 枪口焰（5 级 / ★，只是画面）：原来 ★ 是枪口一团不分方向的圆光。现在每根管刚打过就在它管口亮一片火舌
   * （MuzzleFlash：白热芯 + 橙黄外焰，朝枪管实际指向，绕管轴跟转管一起转，形状每帧换种子）；
   * 刚开枪最亮，hold 秒里退到一半，★ 两管交替接成一片不断的火。火舌外：每几发一团往前冲就散的火球，
   * 一缕烟、几颗火星（车往前开，它们自然往后飘）。高画质加一圈淡橙溢光；中低档的粒子走 sub.allow，低画质火舌只亮开枪那一帧
   */
  private flame(ctx: CombatContext, g: number): void {
    const L = SUB_FX.mg.flame;
    const q = ctx.sub.q;
    const hold = q === 'low' ? 0 : L.hold[g];
    const head = this.model.head.getWorldDirection(_fd);
    const yaw = Math.atan2(head.x, head.z);
    const fx = -Math.sin(yaw), fz = -Math.cos(yaw);
    const roll = this.model.spinner?.rotation.z ?? 0;
    const n = Math.min(this.fired.length, this.model.muzzles.length);
    for (let i = 0; i < n; i++) {
      const t = this.fired[i];
      if (t > hold) continue;
      const k = (0.5 + 0.5 * Math.exp(-t / 0.018)) * rand(0.85, 1.1);
      const p = this.muzzle(i, _fp);
      ctx.fx.muzzleFlash.add(p.x + fx * 0.05, p.y, p.z + fz * 0.05, yaw, L.len[g] * k * rand(0.85, 1.15), L.wid[g] * Math.sqrt(k), Math.min(1.05, 0.55 + 0.5 * k), roll + i * Math.PI * 0.5);
      if (q === 'high' && t === 0 && ctx.sub.allow(1, 'glow', SubPrio.Low)) ctx.fx.glow.emit({ x: p.x + fx * 0.5, y: p.y, z: p.z + fz * 0.5, life: 0.05, size: 0.9, size1: 1.4, color: 0xffa040, color1: 0xc8401a, alpha: 0.35, frame: 0 });
    }
    const o = this.muzzle(this.shot % Math.max(1, this.model.muzzles.length), _fp);
    if (this.balls >= L.ball[g]) {
      this.balls = 0;
      if (ctx.sub.allow(1)) {
        const d = rand(0.4, 0.8);
        ctx.fx.glow.emit({ x: o.x + fx * d, y: o.y, z: o.z + fz * d, vx: fx * 5, vz: fz * 5, life: rand(0.05, 0.07), size: rand(0.8, 1.1), size1: 1.5, color: 0xffb050, color1: 0xc8401a, alpha: 0.6, frame: 0, drag: 8 });
      }
      if (g === 3 && Math.random() < 0.5 && ctx.sub.allow(1, 'glow', SubPrio.Low)) {
        const s = Math.random() < 0.5 ? -1 : 1;
        ctx.fx.glow.emit({ x: o.x + fx * 0.3, y: o.y, z: o.z + fz * 0.3, vx: fx * rand(1, 2.5) - fz * s * rand(0.5, 1.5), vy: rand(1, 2.5), vz: fz * rand(1, 2.5) + fx * s * rand(0.5, 1.5), life: rand(0.3, 0.5), size: rand(0.12, 0.18), size1: 0.05, color: 0xffd890, color1: 0xff5a10, frame: 0, gravity: -6, drag: 1.2 });
      }
    }
    this.puff -= ctx.dt;
    if (this.puff <= 0) {
      this.puff = L.smoke[g];
      if (ctx.sub.allow(1, 'smoke', SubPrio.Low)) ctx.fx.smoke(o.x + fx * 0.3, o.y, o.z + fz * 0.3, 0.3, 1.1, 0x9a9286, 0.18);
    }
  }

  /** 究极助攻：炼狱 = 枪管跟套件一起烧到红热；铁雨 = 朝天打一串白热曳光指向炮艇；黑潮 = 发光件全亮 */
  protected override assistStep(ctx: CombatContext, k: number, first: boolean): void {
    super.assistStep(ctx, k, first);
    const md = this.model;
    if (this.assistId === 'inferno' && md.heat) md.heat.emissiveIntensity = GLOW_MAX;
    if (this.assistId !== 'gunship' || Math.random() > 0.5 * ctx.sub.cfg.assist) return;
    const p = this.muzzle(0, this.w);
    ctx.streaks.add(p.x, p.y, p.z, p.x + rand(-4, 4), p.y + 42, p.z - 14 + rand(-4, 4), 0.35, 0xfff4e0, 0.95, 0.08, 2);
    ctx.audio.play('mg', 0.5);
  }
}

// ---------------------------------------------------------------- 迫击炮

/**
 * 迫击炮进化「重磅炮弹」（D4 / 汇总第 62 条，制作人「迫击炮的满级效果太影响视野了，建议改成一发大炮弹，而不是现在这样两排很多炮弹」）：
 * 原来每 4.5 秒两排共 14 发（每发 EVO_SHOT.mortar、半径 4.6）由近及远铺满画面；改成每 4.5 秒（冷却不变）一发大炮弹砸进敌群中间——
 * 单发 = EVO_SHOT.mortar（已经是第 58 条 × 0.8 之后的数）× dmg，爆炸半径 × r，弹体 × look、拖尾加粗，飞得更高更久（flight / apex），
 * 落地中坑（pit 2）+ 大爆炸演出（Game.bigShellFx）；照旧是普通档（不掀车），联动（空爆霰弹 / 燃烧炮击）的写法不动，跟着这一发走。
 * T237（制作人「四级保留子母弹」：只有一发巨弹时单目标反而比三级低）：落地再撒 bomblets 枚子母弹，落点圈、每枚半径、每枚伤害见 spread（主爆炸的倍数）
 */
export const MORTAR_BIG = { dmg: 3.5, r: 1.6, look: 2.6, flight: 1.35, apex: 1.5, bomblets: 6, spread: { ring: 0.35, size: 0.4, dmg: 0.2 } };

class MortarWeapon extends Weapon {
  private timer = 1.5;
  /** 排队要打的炮弹（big = 进化后的重磅炮弹；按入队那一刻算，进化前排好的照旧是普通炮弹） */
  private readonly queue: { delay: number; x: number; z: number; big: boolean }[] = [];
  /** 上一发出膛多久了（炮管后坐 + 复进） */
  private kick = 9;
  /** 这一轮装好了（立弹满、装填臂抬着巨弹）；齐射一开始就不算 */
  private loaded = true;

  override saveRuntime(): Record<string, number> { return { timer: this.timer }; }
  override restoreRuntime(s: Record<string, number>): void { this.timer = s.timer ?? this.timer; this.loaded = this.timer <= 0; }

  /**
   * T143 挂件动作：立着的炮弹数 = 每轮几发（最多 4 发），打一发少一发、冷却里一发一发补回；每发炮管后坐 0.3 米再复进；
   * ★ 装填臂打完往外放下、冷却里抬回来托着下一发巨弹（引信冷白亮着 = 装好了）；5 级测距仪镜片常亮
   */
  private pose(ctx: CombatContext): void {
    const md = this.model;
    const m = ctx.mods;
    this.kick += ctx.dt;
    if (this.timer <= 0) this.loaded = true;
    const full = (this.evolved ? 4.5 : this.stat('间隔')) * m.cooldown;
    const ready = 1 - Math.max(0, Math.min(1, this.timer / full));
    const rack = md.racks.shells;
    if (rack) {
      const n = Math.min(rack.instanceMatrix.count, this.stat('炮弹') + m.count);
      rack.count = this.queue.length ? Math.min(n, this.queue.length) : this.loaded ? n : Math.min(n, Math.floor(n * ready + 1e-6));
    }
    const back = this.kick < 0.05 ? this.kick / 0.05 : Math.max(0, 1 - (this.kick - 0.05) / 0.3);
    if (md.pivots.rec) md.pivots.rec.position.y = (-0.3 / md.scale) * back;
    const arm = md.pivots.arm;
    if (arm) {
      const down = this.loaded ? 0 : Math.max(0, Math.min(1, this.kick < 0.3 ? this.kick / 0.3 : 1 - (ready - 0.55) / 0.35));
      arm.rotation.z = (this.anchor.position.x < 0 ? 1 : -1) * down * 1.1;
      if (md.glow) md.glow.value = (1 - down) * 1.3;
    } else if (md.glow) md.glow.value = 0.9 + (this.kick < 0.3 ? 0.6 : 0);
  }

  /** 这一轮的测距光打过了没有（5 级：开火前 0.3 秒测距仪朝落点打一道细光，我方浅黄 T130） */
  private ranged = false;

  update(ctx: CombatContext): void {
    const dt = ctx.dt;
    const m = ctx.mods;
    this.timer -= dt * m.rate;
    this.pose(ctx);
    const o = this.muzzle(0, this.v);
    const lv = this.form;
    const g = gradeOf(lv);
    const F = SUB_FX.mortar;
    if (F.range[g] && !this.ranged && this.timer > 0 && this.timer < 0.3) {
      this.ranged = true;
      const pre = ctx.cluster(ctx.tankX, ctx.tankZ, 16, 80, true);
      if (pre) {
        const lens = this.model.head.localToWorld(this.w.set((this.anchor.position.x < 0 ? -1 : 1) * 0.27, 0.46, -0.2));
        ctx.streaks.add(lens.x, lens.y, lens.z, pre.x, 0.4, pre.z + 2, 0.06, MARK_SELF, 0.85, 0.3, 1.5);
        ctx.fx.glow.emit({ x: lens.x, y: lens.y, z: lens.z, life: 0.12, size: 0.9, size1: 0.4, color: SUB_ID.mortar, frame: 0 });
      }
    }
    if (this.timer <= 0) {
      this.ranged = false;
      const cl = ctx.cluster(ctx.tankX, ctx.tankZ, 16, 80, true);
      if (!cl) {
        this.timer = 0.4;
      } else if (this.evolved) {
        // 重磅炮弹（汇总第 62 条）：一发大炮弹砸在扎堆的敌人中间（原来是两排 14 发徐进弹幕）
        this.loaded = false;
        this.timer = 4.5 * m.cooldown;
        this.queue.push({ delay: 0, x: cl.x, z: cl.z + 2, big: true });
        this.aim(angleTo(o.x, o.z, cl.x, cl.z), 20, 1);
      } else {
        this.loaded = false;
        this.timer = this.stat('间隔') * m.cooldown;
        const n = this.stat('炮弹') + m.count;
        for (let i = 0; i < n; i++) this.queue.push({ delay: i * 0.18, x: cl.x + (i ? fireRand(-3, 3) : 0), z: cl.z + 2 + (i ? fireRand(-3, 3) : 0), big: false });
        this.aim(angleTo(o.x, o.z, cl.x, cl.z), 20, 1);
      }
    }
    for (let k = this.queue.length - 1; k >= 0; k--) {
      const q = this.queue[k];
      q.delay -= dt;
      if (q.delay > 0) continue;
      this.queue.splice(k, 1);
      const p = this.muzzle(k, this.w);
      const dist = Math.hypot(q.x - p.x, q.z - p.z);
      const big = q.big ? MORTAR_BIG : null;
      const radius = (big ? 4.6 * big.r : this.form >= 4 ? 5.5 : 4.5) * m.area;
      // 进化单发 30 → 40（T018-1：原来进化后单发比 5 级 34 还低）；爆炸画面随等级 1 → 1.3；进化后一发重磅炮弹 = 单发 × 3.5（汇总第 62 条）
      // 联动（T018-link）：燃烧炮击 = 落点烧一片火（每秒 = 喷火器燃烧 × 1.5）；空爆霰弹 = 主爆炸 × 0.6 + 头顶 6 米洒 24 道霰弹（每道 = 机枪单发 × 2）
      const air = this.link === 'airburst';
      const flight = (1.0 + dist * 0.006) * (big?.flight ?? 1);
      ctx.projectiles.shell(p.x, p.y, p.z, q.x, q.z, flight, (13 + dist * 0.12) * (big?.apex ?? 1), (big ? EVO_SHOT.mortar * big.dmg * this.power : this.stat('伤害')) * (air ? 0.6 : 1), radius, {
        fling: true, grenade: true, bomblets: big ? big.bomblets : this.form >= 5 ? 4 : 0, spread: big?.spread, pit: big ? 2 : 1, fxScale: subFx(this), big: big?.look,
        napalm: this.link === 'firemortar' ? ctx.weaponStat('flamer', '燃烧') * 1.5 : undefined,
        airburst: air ? { n: 24, dmg: ctx.weaponStat('mg', '伤害') * 2 } : undefined,
        look: lv, subLink: this.link ?? undefined,
      });
      ctx.fx.muzzle(p.x, p.y, p.z, 0, -0.3, big ? 1.6 : 0.7);
      // 音效（T143）：4 级起「嗵」降调到 0.9（口径大了）；3 级起落地前一声短哨、★ 巨弹下坠尖啸（哨音录音那一段正好在落地那一刻结束）
      ctx.audio.play('mortar', big ? 1 : undefined, big ? 0.7 : this.form >= 4 ? 0.9 : undefined);
      if (F.whistle[g]) ctx.audio.play(big ? 'siegeFall' : 'fall', big ? 0.5 : 0.3, 1, Math.max(0, flight - (big ? 1.3 : 1.4)));
      if (big) ctx.shake(0.15);
      this.kick = 0;
    }
  }

  /** 究极助攻：核弹 = 朝天打一发红色信号弹（升到 25 米）；钢幕 = 一起打 4 发烟弹；天罗 = 管口一团青光 */
  protected override assistStep(ctx: CombatContext, k: number, first: boolean): void {
    super.assistStep(ctx, k, first);
    const p = this.muzzle(0, this.w);
    if (first) {
      this.kick = 0;
      ctx.audio.play('mortar', 0.7, 1.25);
    }
    if (this.assistId === 'nuke') {
      if (Math.random() < ctx.sub.cfg.assist) ctx.fx.glow.emit({ x: p.x, y: p.y + 25 * (1 - (1 - k) ** 2), z: p.z, life: 0.45, size: 1.5, size1: 0.4, color: 0xff7a5a, color1: 0xff2a10, frame: 0 });
    } else if (this.assistId === 'curtain') {
      if (first) for (let i = 0; i < 4; i++) ctx.fx.smokeP.emit({ x: p.x + (i - 1.5) * 0.4, y: p.y, z: p.z, vx: (i - 1.5) * 1.4, vy: 15, vz: -2, life: 1.6, size: 0.5, size1: 3, color: 0xd8d4cc, alpha: 0.5, frame: 1, drag: 1.4 });
    } else if (Math.random() < 0.4 * ctx.sub.cfg.assist) ctx.fx.glow.emit({ x: p.x, y: p.y, z: p.z, life: 0.2, size: 1.2, size1: 0.3, color: ULT_THEME.snare, frame: 0 });
  }
}

// ---------------------------------------------------------------- 特斯拉线圈

/** T021-a 特斯拉分档：1～2 级 / 3～4 级 / 5 级 / 进化「雷暴」——电弧档位、索敌射程、链条跳跃（米）、落点大号电火花、zap 变调 */
export const TESLA_GRADE: { tier: BoltTier; range: number; jump: number; big: boolean; pitch: number }[] = [
  { tier: 't1', range: 32, jump: 11, big: false, pitch: 1 },
  { tier: 't3', range: 36, jump: 13, big: false, pitch: 0.95 },
  { tier: 't5', range: 40, jump: 15, big: true, pitch: 0.9 },
  { tier: 'evo', range: 46, jump: 17, big: true, pitch: 0.85 },
];

class TeslaWeapon extends Weapon {
  private cd = 0.8;
  override saveRuntime(): Record<string, number> { return { cd: this.cd }; }
  override restoreRuntime(s: Record<string, number>): void { this.cd = s.cd ?? this.cd; }
  /** 上一次到点没找到目标（待机：线圈不点亮） */
  private idle = false;

  /** 分档下标（TESLA_GRADE） */
  grade(): number {
    return gradeOf(this.form);
  }

  update(ctx: CombatContext): void {
    const dt = ctx.dt;
    const m = ctx.mods;
    const o = this.muzzle(0, this.v);
    const md = this.model;
    const orb = md.spinner;
    if (orb) orb.scale.setScalar(1 + Math.sin(ctx.time * 20) * 0.08 + (this.cd < 0.25 ? 0.3 : 0));
    // T143：球 1 级暗蓝不发光、2 级亮一半、3 级大半、4 级起全亮（★ 双塔的球全亮）；放电前 0.4 秒线圈从下往上逐圈点亮（低画质整体一起亮），没目标时不亮
    const charge = this.idle ? 0 : 1 - Math.max(0, Math.min(1, this.cd / 0.4));
    if (md.glow) md.glow.value = (this.evolved ? 1.3 : [0.05, 0.6, 0.85, 1.3, 1.3][Math.min(5, this.form) - 1]) + charge * 0.3;
    if (md.coil) {
      // T177：线圈改成分段密绕（每段中心 teslaBandY），从第一段底下扫到最上一段顶上
      const top = teslaBandY((this.evolved ? 5 : this.form >= 3 ? 4 : 3) - 1);
      md.coil.fill.value = this.q === 'low' ? (charge > 0 ? 9 : 0) : 0.3 + charge * (top - 0.2);
      md.coil.glow.value = charge > 0 ? Math.min(1, charge * 3) : 0;
    }
    if (Math.random() < dt * 4) ctx.streaks.arc(o.x, o.y, o.z, o.x + rand(-1.2, 1.2), o.y + rand(-0.8, 0.4), o.z + rand(-1.2, 1.2), 'spark');
    const gi = this.grade();
    const F = SUB_FX.tesla;
    this.ladder(ctx);
    this.crawlArcs(ctx);
    this.cd -= dt;
    if (this.cd > 0) return;
    const chains = this.evolved ? 3 : 1;
    const jumps = this.evolved ? 5 : this.stat('连锁');
    const dmg = this.evolved ? EVO_SHOT.tesla * this.power : this.stat('伤害');
    const stun = this.evolved ? 0.3 : this.form >= 5 ? 0.6 : 0;
    // T021-a：按等级分档加粗，射程 / 链条跳跃跟着涨
    const g = TESLA_GRADE[gi];
    let any = false;
    const hit = new Set<Enemy>();
    for (let c = 0; c < chains; c++) {
      let cur = c === 0 ? this.densest(ctx, o.x, o.z, g.range, g.jump) : this.randomNear(ctx, o.x, o.z, g.range, hit);
      if (!cur) continue;
      if (!any) ctx.electricShot?.(cur, dmg, { type: 'energy', kind: 'elec', stun });
      if (!any) ctx.sub.spot(cur.group.position.x, cur.group.position.z, 3.2, 0x7cc0ff, 0.14, F.spot[gi]);
      any = true;
      let px = o.x;
      let py = o.y;
      let pz = o.z;
      const plasma = this.link === 'plasma';
      for (let k = 0; k < jumps && cur; k++) {
        const ex = cur.group.position.x;
        const ez = cur.group.position.z;
        const burning = plasma && cur.burnTime > 0;
        if (burning) ctx.linkFlash('plasma');
        // 究极换装（策划 3.8）：雷云的电弧外晕偏紫白
        ctx.streaks.arc(px, py, pz, ex, 1.3, ez, g.tier, burning ? { tint: 0xffb070 } : this.ult === 'aurora' ? { tint: ULT_THEME.aurora } : {});
        ctx.fx.electric(ex, 1.3, ez, 4, g.big);
        // T143：3 级起落点地面一圈小火花；5 级起被麻痹的敌人身上爬几道小电弧；★ 每一跳的地上都留电灼纹
        const near = ctx.sub.residue(ex, ez);
        if (F.ground[gi] && near) ctx.fx.sparks(ex, 0.25, ez, ctx.sub.allow(3, 'glow', gi < 2 ? SubPrio.Low : SubPrio.Normal), 0x9fd8ff, 5);
        if (F.crawl[gi] && near && !this.crawl.some((w) => w.e === cur) && this.crawl.length < 6) this.crawl.push({ e: cur, t: 0.6, next: 0 });
        if (gi === 3) this.mark(ctx, SubMark.Vein, ex, ez, 3.6, 3.6, F.vein[gi], 2, 0x9fd8ff);
        hit.add(cur);
        // 等离子焰（T018-link）：对着火的敌人 +40%
        ctx.damage(cur, dmg * (burning ? 1.4 : 1), px, pz, { type: 'energy', kind: 'elec', stun });
        px = ex;
        py = 1.3;
        pz = ez;
        // 电磁轰炸的电离带里跳跃 +50%；等离子焰：从着火的敌人往外跳 +5 米、优先跳着火的
        const jump = g.jump * (this.link === 'emp' && ctx.ionAt(ex, ez) ? 1.5 : 1) + (burning ? 5 : 0);
        cur = this.closest(ctx, ex, ez, jump, hit, plasma);
      }
      // 5 级起链的最后一跳再往地上劈一道，留一块电灼纹（★ 每一跳都留，上面留过了）
      if (F.strike[gi]) {
        const sx = px + rand(-1.4, 1.4);
        const sz = pz + rand(-1.4, 1.4);
        ctx.streaks.arc(px, py, pz, sx, 0.05, sz, 'spark', { scale: 1.8 });
        if (gi === 2) this.mark(ctx, SubMark.Vein, sx, sz, 3.6, 3.6, F.vein[gi], 2, 0x9fd8ff);
      }
      // 引雷（纯视觉）：链条打完最后一个敌人，9 米内有电线杆 / 树就可能多跳一道电弧到它身上
      const rod = ctx.scenery.arc(px, pz, this);
      if (rod) ctx.streaks.arc(px, py, pz, rod.x, rod.y, rod.z, g.tier);
    }
    this.idle = !any;
    if (any) {
      this.cd = (this.evolved ? 0.55 : this.stat('冷却')) * m.cooldown;
      ctx.audio.play('zap', 1, g.pitch);
      // 5 级起叠一声高压嗡（T143）
      if (gi >= 2) ctx.audio.play('subHum', 0.8, g.pitch);
      ctx.fx.flash(o.x, o.y, o.z, 160);
      ctx.sub.spot(o.x, o.z, 3, 0x7cc0ff, 0.12, F.spot[gi] * 0.8);
    } else {
      this.cd = 0.2;
    }
  }

  /** 究极助攻：天罗 = 打一道青色电弧连到炮塔顶的竖井；雷云 = 自放电频率翻倍 */
  protected override assistStep(ctx: CombatContext, k: number, first: boolean): void {
    super.assistStep(ctx, k, first);
    const o = this.muzzle(0, this.w);
    if (this.assistId === 'snare') {
      if (Math.random() < 0.35 * ctx.sub.cfg.assist) ctx.streaks.arc(o.x, o.y, o.z, ctx.tankX, 3.6, ctx.tankZ, 't3', { tint: ULT_THEME.snare });
    } else if (Math.random() < 0.6 * ctx.sub.cfg.assist) ctx.streaks.arc(o.x, o.y, o.z, o.x + rand(-1.6, 1.6), o.y + rand(-0.8, 1), o.z + rand(-1.6, 1.6), 'spark', { tint: ULT_THEME.aurora });
  }

  /** 5 级起被麻痹的敌人：0.6 秒里每 0.1 秒身上重新爬 2～3 道小电弧（中画质不重抖、低画质不画） */
  private readonly crawl: { e: Enemy; t: number; next: number }[] = [];
  private crawlArcs(ctx: CombatContext): void {
    for (let i = this.crawl.length - 1; i >= 0; i--) {
      const w = this.crawl[i];
      w.t -= ctx.dt;
      w.next -= ctx.dt;
      if (w.t <= 0 || !w.e.alive || ctx.tier === 'low') {
        this.crawl.splice(i, 1);
        continue;
      }
      if (w.next > 0) continue;
      w.next = ctx.tier === 'medium' ? 0.3 : 0.1;
      const p = w.e.group.position;
      const h = Math.max(0.8, w.e.size * 1.2);
      const r = w.e.radius * 0.8;
      for (let k = 0; k < (ctx.tier === 'medium' ? 2 : 3); k++) {
        const a = Math.random() * Math.PI * 2;
        ctx.streaks.arc(p.x + Math.cos(a) * r, p.y + h * rand(0.2, 0.9), p.z + Math.sin(a) * r, p.x + Math.cos(a + 1.4) * r, p.y + h * rand(0.2, 0.9), p.z + Math.sin(a + 1.4) * r, 'spark', { scale: 0.9 });
      }
    }
  }

  /** ★ 雅各布天梯：两根往上张开的导轨之间一道电弧从下往上爬，每 1.2 秒一轮（挂件局部坐标，跟着挂件走） */
  private ladder(ctx: CombatContext): void {
    if (!this.evolved || ctx.tier === 'low') return;
    const k = (ctx.time % 1.2) / 1.2;
    const y = 0.4 + k * 0.92;
    const w = 0.08 + k * 0.12;
    const head = this.model.head;
    const a = head.localToWorld(this.w.set(-w, y, 0));
    const ax = a.x;
    const ay = a.y;
    const az = a.z;
    const b = head.localToWorld(this.w.set(w, y, 0));
    const mid = head.localToWorld(_p.set(rand(-0.03, 0.03), y + rand(0.02, 0.08), 0));
    const col = 0xcfeaff;
    ctx.streaks.add(ax, ay, az, mid.x, mid.y, mid.z, 0.07, col, 0.95, 0.05, 2);
    ctx.streaks.add(mid.x, mid.y, mid.z, b.x, b.y, b.z, 0.07, col, 0.95, 0.05, 2);
    ctx.streaks.add(ax, ay, az, b.x, b.y, b.z, 0.3, 0x5aa8ff, 0.25, 0.05, -6);
  }

  /** burning = 着火的敌人优先（等离子焰：距离按一半算） */
  private closest(ctx: CombatContext, x: number, z: number, range: number, skip: Set<Enemy>, burning = false): Enemy | null {
    let best: Enemy | null = null;
    let bd = range * range;
    const r2 = range * range;
    for (const e of ctx.enemies) {
      if (!e.alive || skip.has(e) || e.flying) continue;
      const raw = (e.group.position.x - x) ** 2 + (e.group.position.z - z) ** 2;
      if (raw >= r2) continue;
      const d = burning && e.burnTime > 0 ? raw * 0.25 : raw;
      if (d < bd) {
        bd = d;
        best = e;
      }
    }
    return best;
  }

  /**
   * T018-1：链条起点 = 射程里的一团（一样的选近的）；主炮马上要打的那个让给主炮（只剩它一个时照打）。
   * T106 起按威胁算：它和跳跃距离内邻居的威胁分加起来（原来数个数），一辆坦克顶几个步兵
   */
  private densest(ctx: CombatContext, x: number, z: number, range: number, jump: number): Enemy | null {
    const lock = ctx.coreLock();
    const pool = ctx.enemies.filter((e) => e.alive && !e.flying && Math.hypot(e.group.position.x - x, e.group.position.z - z) < range);
    let best: Enemy | null = null;
    let bs = -Infinity;
    for (const e of pool) {
      if (e === lock && pool.length > 1) continue;
      let n = ctx.threat(e, 'energy');
      for (const f of pool) if (f !== e && Math.hypot(f.group.position.x - e.group.position.x, f.group.position.z - e.group.position.z) < jump) n += ctx.threat(f, 'energy');
      // 等离子焰（T018-link）：着火的敌人优先当链条起点
      const s = n - Math.hypot(e.group.position.x - x, e.group.position.z - z) / range + (this.link === 'plasma' && e.burnTime > 0 ? 2 : 0);
      if (s > bs) {
        bs = s;
        best = e;
      }
    }
    return best;
  }

  private randomNear(ctx: CombatContext, x: number, z: number, range: number, skip: Set<Enemy>): Enemy | null {
    const pool = ctx.enemies.filter((e) => e.alive && !e.flying && !skip.has(e) && Math.hypot(e.group.position.x - x, e.group.position.z - z) < range);
    return pool.length ? pool[Math.floor(rng.weapon() * pool.length)] : null;
  }
}

// ---------------------------------------------------------------- 火焰喷射器

class FlamerWeapon extends Weapon {
  private tick = 0;
  private patch = 0;
  private nova = 2.8;
  /** 刚喷过（秒）：喷口炽红跟着闪 */
  private lit = 0;
  /** 扇形焦痕 / 低频呼噜的节拍、跟着火锥走的光斑占的那一张、火环前的泄压声放过没有（T143） */
  private scorchT = 0;
  private spotSlot = -1;
  private hissed = false;

  override saveRuntime(): Record<string, number> { return { tick: this.tick, patch: this.patch, nova: this.nova }; }
  override restoreRuntime(s: Record<string, number>): void {
    this.tick = s.tick ?? this.tick; this.patch = s.patch ?? this.patch; this.nova = s.nova ?? this.nova;
  }

  update(ctx: CombatContext): void {
    const dt = ctx.dt;
    const m = ctx.mods;
    const o = this.muzzle(0, this.v);
    // T018-1：射程 14 / 17 / 18 → 18 / 21 / 24（进化 21 → 28）；燃烧炮击（T018-link）+3 米
    const range = (this.evolved ? 28 : this.stat('射程')) + (this.link === 'firemortar' ? 3 : 0);
    // 等离子焰（T018-link）：火变成蓝白色等离子，一半伤害改成能量
    const plasma = this.link === 'plasma';
    const cone = this.evolved ? 0.6 : this.form >= 4 ? 0.5 : 0.38;
    const burn = this.evolved ? EVO_BURN * this.power : this.stat('燃烧');
    const g = gradeOf(this.form);
    const F = SUB_FX.flamer;
    // T143：5 级喷口一圈炽红常亮、喷的时候一闪一闪；★ 罐上灯条跟着火环 2.8 秒周期由暗到亮，亮满就爆
    const glow = this.model.glow;
    if (glow) glow.value = this.evolved ? 0.12 + (GLOW_MAX - 0.12) * Math.max(0, Math.min(1, 1 - this.nova / (2.8 * m.cooldown))) : this.lit > 0 ? 1.1 + Math.random() * 0.4 : 0.9;
    // 5 级起不喷的时候喷口一朵小引火苗
    if (g >= 2 && this.lit <= 0 && Math.random() < 0.5 && ctx.sub.allow(1)) ctx.fx.glow.emit({ x: o.x, y: o.y - 0.15, z: o.z, vy: 0.8, life: 0.16, size: 0.35, size1: 0.12, color: 0xffd080, color1: 0xff6a20, frame: 0 });
    this.lit = Math.max(0, this.lit - dt);
    if (this.evolved) {
      this.nova -= dt;
      // ★ 火环前 0.3 秒泄压阀「噗」一口白汽
      if (!this.hissed && this.nova < 0.3) {
        this.hissed = true;
        ctx.audio.play('steam', 0.8);
        for (let i = 0; i < 3; i++) ctx.fx.steam(o.x + rand(-0.6, 0.6), o.y + 0.5, o.z + rand(-0.6, 0.6));
      }
      if (this.nova <= 0) {
        this.nova = 2.8 * m.cooldown;
        this.hissed = false;
        for (let i = 0; i < 48; i++) {
          const a = (i / 48) * Math.PI * 2;
          if (!subCanAim(this.def.id, this.slot, this.frameYaw, Math.cos(a), Math.sin(a))) continue;
          ctx.fx.glow.emit({ x: ctx.tankX, y: 1, z: ctx.tankZ, vx: Math.cos(a) * 26, vz: Math.sin(a) * 26, vy: rand(0, 2), life: 0.5, size: 2.4, size1: 3.6, color: 0xffd080, color1: 0xc83010, frame: 0, drag: 2.5 });
          if (i % 4 === 0) this.mark(ctx, SubMark.Embers, ctx.tankX + Math.cos(a) * 10, ctx.tankZ + Math.sin(a) * 10, 4, 4, F.ring[g], 2, plasma ? SUB_ID.tesla : 0xff6a20, 0.55);
        }
        for (const e of ctx.enemies) {
          if (e.alive && !e.flying && this.canTarget(ctx, e) && Math.hypot(e.group.position.x - ctx.tankX, e.group.position.z - ctx.tankZ) < 12 + e.radius) ctx.damage(e, 30 * SUB_DMG * this.power, ctx.tankX, ctx.tankZ, { type: 'fire', burn, knock: 6 });
        }
        // 火环和焦痕只铺当前挂位能喷到的半圈。
        ctx.sub.spot(ctx.tankX, ctx.tankZ, 9, plasma ? 0xc8e4ff : 0xffa050, 0.35, 0.6);
        ctx.shake(0.25);
        ctx.audio.play('flame');
      }
    }
    // T106：射程里按威胁排（火对重甲打五折，克制算进威胁分），喷火锥对着它，锥里的照样都烧；够不着就不喷
    const target = pickTarget(ctx, o.x, o.z, range + 2, 'fire', false, null, this);
    if (!target) return;
    const arc = subArc(this.def.id, this.slot);
    const center = this.frameYaw + arc.center;
    const ang = center + THREE.MathUtils.clamp(subAngle(angleTo(o.x, o.z, target.group.position.x, target.group.position.z) - center), -arc.half + cone, arc.half - cone);
    this.aim(ang, 9, dt);
    this.lit = 0.15;
    const sp0 = range / 0.42;
    const dx = -Math.sin(ang);
    const dz = -Math.cos(ang);
    // 火锥（T198 起每一级都有，原来 4 级起才有一层扁平面片）：外焰 + 内芯两层锥形火管，1～3 级窄一点、淡一点；
    // 粒子每帧 3 个（中画质 2 个），翻滚着往上飘（火团有体积、尾巴往上卷），4 级起个头 × 1.3；5 级起火芯黄白，★ 外层暗红；等离子焰蓝白
    const sheet = this.form >= 4 || this.evolved;
    const core = plasma ? 0xf4fbff : F.core[g];
    ctx.sub.sheet.forSlot(this.slot).show(o.x, o.y, o.z, ang, range, cone * (sheet ? 0.75 : 0.66), core, plasma ? 0x8fc8ff : F.mid[g], plasma ? 0x2a5cff : F.edge[g], ctx.sub.cfg.sheet * (sheet ? 1 : 0.75));
    const n = ctx.tier === 'medium' ? 2 : 3;
    const sz = sheet ? 1.3 : 1.05;
    for (let i = 0; i < n; i++) {
      const a = ang + (Math.random() - 0.5) * cone * 1.4;
      const sp = sp0 * rand(0.6, 1.0);
      ctx.fx.glow.emit({ x: o.x, y: o.y, z: o.z, vx: -Math.sin(a) * sp, vy: rand(0.4, 2), vz: -Math.cos(a) * sp, life: rand(0.36, 0.5), size: 0.5 * sz, size1: 3.6 * sz, color: plasma ? 0xeaf6ff : g >= 2 ? 0xfffbe0 : 0xfff0b0, color1: plasma ? 0x3a7cff : g === 3 ? 0x9a2008 : 0xc8401a, frame: 0, drag: 1.3, gravity: 5, spin: rand(-4, 4), alpha: 0.8 });
    }
    // 火舌舔到地面：火锥末段贴地往两边铺开一团（只是画面）
    if (Math.random() < 0.45 && ctx.sub.allow(1, 'glow', g < 2 ? SubPrio.Low : SubPrio.Normal)) {
      const a = ang + (Math.random() - 0.5) * cone * 1.2;
      const d = range * rand(0.55, 0.9);
      const side = rand(-1, 1) * 3;
      ctx.fx.glow.emit({ x: o.x - Math.sin(a) * d, y: 0.45, z: o.z - Math.cos(a) * d, vx: -Math.sin(a) * 4 + Math.cos(a) * side, vy: rand(0.6, 1.6), vz: -Math.cos(a) * 4 - Math.sin(a) * side, life: rand(0.4, 0.6), size: 1.6 * sz, size1: 3.8 * sz, color: plasma ? 0xc8e4ff : 0xffb050, color1: plasma ? 0x2a5cff : 0x8a1a08, frame: 0, drag: 1.5, gravity: 3, spin: rand(-2, 2), alpha: 0.55 });
    }
    if (Math.random() < 0.5) {
      const a = ang + (Math.random() - 0.5) * cone;
      // ★ 黑烟个头 × 1.5（数量不加）；从火舌末端翻着往上冒
      const ss = g === 3 ? 1.5 : 1;
      const d = range * rand(0.65, 0.95);
      ctx.fx.smokeP.emit({ x: o.x - Math.sin(a) * d, y: 2.2, z: o.z - Math.cos(a) * d, vx: -Math.sin(a) * 2, vy: 2.8, vz: -Math.cos(a) * 2, life: 1.3, size: 1.5 * ss, size1: 4.4 * ss, color: 0x2e2a28, color1: 0x4a4440, alpha: 0.4, frame: 1, drag: 0.6, spin: rand(-1.2, 1.2) });
    }
    // 3 级起火锥末端火星落地弹一下；喷过的地面每 0.5 秒留一块扇形焦痕（5 级起远端余烬发光慢慢冷，等离子焰带蓝）+ 一声低频呼噜
    const a0 = ang + (Math.random() - 0.5) * cone;
    const d0 = range * rand(0.8, 1);
    if (F.embers[g] && Math.random() < 0.6 && ctx.sub.residue(o.x - Math.sin(a0) * d0, o.z - Math.cos(a0) * d0) && ctx.sub.allow(1, 'glow', g < 2 ? SubPrio.Low : SubPrio.Normal)) {
      const a = a0;
      const d = d0;
      ctx.fx.glow.emit({ x: o.x - Math.sin(a) * d, y: 1.2, z: o.z - Math.cos(a) * d, vx: rand(-1.5, 1.5), vy: rand(2, 4), vz: rand(-1.5, 1.5), life: rand(0.5, 0.8), size: 0.32, size1: 0.1, color: 0xffc060, color1: 0xc8401a, frame: 0, gravity: -14, drag: 0.6 });
    }
    this.scorchT -= dt;
    if (F.fan[g] && this.scorchT <= 0) {
      this.scorchT = 0.5;
      this.mark(ctx, SubMark.Fan, o.x + dx * range * 0.5, o.z + dz * range * 0.5, range, range * Math.tan(cone) * 2.2, F.fan[g], g >= 2 ? 1.5 : 0, plasma ? SUB_ID.tesla : 0xff6a20, 0.55, Math.atan2(dz, dx));
      ctx.audio.play('subThud', 0.35, 0.6);
    }
    // 车头路面一块橙光斑跟着火锥中段走、亮度抖 ±25%（等离子焰冷白）
    this.spotSlot = ctx.sub.spot(o.x + dx * range * 0.4, o.z + dz * range * 0.4, range * 0.28, plasma ? 0xc8e4ff : 0xffa050, 0.12, 0.3 + g * 0.08, ctx.tier === 'high' ? 0.25 : 0, this.spotSlot);
    ctx.audio.play('flame');
    // 喷火锥扫到的路边景物：植被 / 木头烤够时间点着，砖石熏黑；路上的木头路障也点着（T017-11A）
    ctx.scenery.flame(o.x, o.z, ang, range, cone, dt);
    ctx.flameProps(o.x, o.z, ang, range, cone, dt);
    this.tick -= dt;
    if (this.tick <= 0) {
      this.tick = 0.12;
      const dmg = this.evolved ? EVO_SHOT.flamer * this.power : this.stat('伤害');
      for (const e of ctx.enemies) {
        if (!e.alive || e.flying || !this.canTarget(ctx, e)) continue;
        const dx = e.group.position.x - o.x;
        const dz = e.group.position.z - o.z;
        const d = Math.hypot(dx, dz);
        if (d > range + e.radius) continue;
        let diff = Math.atan2(-dx, -dz) - ang;
        while (diff > Math.PI) diff -= Math.PI * 2;
        while (diff < -Math.PI) diff += Math.PI * 2;
        if (Math.abs(diff) > cone + e.radius / Math.max(4, d)) continue;
        if (plasma) {
          ctx.linkFlash('plasma');
          ctx.damage(e, dmg * 0.5, o.x, o.z, { type: 'fire', burn });
          ctx.damage(e, dmg * 0.5, o.x, o.z, { type: 'energy' });
          if (Math.random() < 0.08) ctx.streaks.arc(o.x, o.y, o.z, e.group.position.x, 1.2, e.group.position.z, 'spark', { scale: 2 });
        } else ctx.damage(e, dmg, o.x, o.z, { type: 'fire', burn });
      }
    }
    if (this.evolved || this.form >= 5) {
      this.patch -= dt;
      if (this.patch <= 0) {
        this.patch = 0.5;
        const fx = o.x - Math.sin(ang) * range * 0.75;
        const fz = o.z - Math.cos(ang) * range * 0.75;
        ctx.hazards.fire(fx, fz, 3, 3, 8 * SUB_DMG * this.power, 'player');
        // T143：地面火摊边上一圈焦黑（余烬画进焦痕，不用火苗，免得看着像还在烧）
        this.mark(ctx, SubMark.Embers, fx, fz, 5, 5, 5, 3, 0xff7a2a, 0.7);
      }
    }
  }

  /** 究极助攻：炼狱 = 朝炮口方向往前喷一口长火（火焰面片拉到 34 米）；天火 / 钢幕 = 发光件全亮 */
  protected override assistStep(ctx: CombatContext, k: number, first: boolean): void {
    super.assistStep(ctx, k, first);
    if (this.assistId !== 'inferno') return;
    const o = this.muzzle(0, this.w);
    const f = this.model.head.getWorldDirection(_p);
    const ang = Math.atan2(f.x, f.z);
    ctx.sub.sheet.forSlot(this.slot).show(o.x, o.y, o.z, ang, 34 * Math.min(1, k * 4), 0.32, 0xfffbe0, 0xffa848, 0x9a2008, 1.1);
    if (first) ctx.audio.play('flame', 1, 0.8);
    if (Math.random() < ctx.sub.cfg.assist) ctx.fx.glow.emit({ x: o.x, y: o.y, z: o.z, vx: -Math.sin(ang) * 70, vy: rand(0, 1.5), vz: -Math.cos(ang) * 70, life: 0.45, size: 0.8, size1: 4, color: 0xfffbe0, color1: 0x9a2008, frame: 0, drag: 1, alpha: 0.85 });
  }
}

// ---------------------------------------------------------------- 自动无人机

class DroneWeapon extends Weapon {
  private timer = 1;
  private readonly escorts: THREE.Mesh[] = [];
  private escortFire = 0;
  /** 这一轮装好了 / 上一轮放飞多久了（停着的无人机数、舱盖按它） */
  private loaded = true;
  private launchT = 9;
  /** 航行灯已经按这个模型点上了 */
  private litFor: MountModel | null = null;

  override saveRuntime(): Record<string, number> { return { timer: this.timer, escortFire: this.escortFire }; }
  override restoreRuntime(s: Record<string, number>): void {
    this.timer = s.timer ?? this.timer; this.escortFire = s.escortFire ?? this.escortFire; this.loaded = this.timer <= 0;
  }

  /**
   * T143 挂件动作：车上停着的无人机数 = 每轮几架（放飞就空了，冷却里一架一架补回）；2 级起每架机尾一盏绿航行灯；
   * ★ 蜂巢 5 个格子，放飞时舱盖按顺序掀开、0.7 秒后合上，格子前的绿灯 = 装好的格子
   */
  private pose(ctx: CombatContext): void {
    const md = this.model;
    const m = ctx.mods;
    this.launchT += ctx.dt;
    if (this.timer <= 0) this.loaded = true;
    const full = (this.evolved ? 2.0 : this.stat('间隔')) * m.cooldown;
    const ready = 1 - Math.max(0, Math.min(1, this.timer / full));
    const { parked, navs, lids } = md.racks;
    const cap = (parked ?? lids)?.instanceMatrix.count ?? 0;
    const n = Math.min(cap, (this.evolved ? 5 : this.stat('每轮')) * m.summon);
    const shown = this.loaded ? n : Math.min(n, Math.floor(n * ready + 1e-6));
    if (parked) parked.count = shown;
    if (navs) {
      if (this.litFor !== md) {
        this.litFor = md;
        _c.setHex(SUB_ID.drones);
        for (let i = 0; i < navs.instanceMatrix.count; i++) navs.setColorAt(i, _c);
        if (navs.instanceColor) navs.instanceColor.needsUpdate = true;
      }
      navs.count = shown;
    }
    if (lids && this.launchT < 1.6) {
      const rest = lids.userData.rest as { pos: [number, number, number] }[];
      rest.forEach((r, i) => {
        const k = Math.max(0, Math.min(1, (this.launchT - i * 0.07) / 0.12)) * (1 - Math.max(0, Math.min(1, (this.launchT - 0.75 - i * 0.07) / 0.4)));
        lids.setMatrixAt(i, _m.compose(_p.set(...r.pos), _qq.setFromAxisAngle(_x, k * 1.7), _s1));
      });
      lids.instanceMatrix.needsUpdate = true;
    }
  }

  update(ctx: CombatContext): void {
    const dt = ctx.dt;
    const m = ctx.mods;
    this.timer -= dt * m.rate;
    this.pose(ctx);
    if (this.timer <= 0) {
      const o = this.muzzle(0, this.v);
      // 95 米内的按威胁排（T106，原来是精英先、再挑血多的；T127 起身后的也算）：首领部件 / 精英 / 自爆卡车先，步兵最后，同威胁先近的；一轮几架轮着分给排在前面的
      const targets = ctx.enemies
        .filter((e) => e.alive && Math.hypot(e.group.position.x - o.x, e.group.position.z - o.z) < 95)
        .sort((a, b) => ctx.rank(a, o.x, o.z, 'blast') - ctx.rank(b, o.x, o.z, 'blast'));
      if (targets.length === 0) {
        this.timer = 0.3;
      } else {
        const n = (this.evolved ? 5 : this.stat('每轮')) * m.summon;
        for (let i = 0; i < n; i++) {
          const radius = (this.form >= 5 || this.evolved ? 4.4 : 3.6) * m.area;
          // 进化单发 28 → 48（T018-1）；武装无人机（T018-link）：扎下去之前先悬停扫射 2 秒（每秒 10 发）
          ctx.projectiles.drone(o.x + fireRand(-0.6, 0.6), o.y, o.z + fireRand(-0.6, 0.6), targets[i % targets.length], this.evolved ? EVO_SHOT.drones * this.power : this.stat('伤害'), radius, this.evolved, this.link === 'armed' ? { dur: 2 * summonDuration(m), rate: 10 } : null, this.form, this.link ?? undefined);
        }
        this.timer = (this.evolved ? 2.0 : this.stat('间隔')) * m.cooldown;
        this.loaded = false;
        this.launchT = 0;
        // T143：起飞时导轨一串火花；★ 一群电机呼啸
        ctx.fx.sparks(o.x, o.y - 0.2, o.z, ctx.sub.allow(8), 0xffd090, 6);
        ctx.audio.play('launch');
        if (this.evolved) ctx.audio.play('swoop', 0.5, 1.2);
      }
    }
    if (!this.evolved) return;
    // 护航机：绕车飞并扫射
    while (this.escorts.length < 2) {
      const e = new THREE.Mesh(droneGeo(this.geo, false), MAT.painted);
      e.castShadow = true;
      ctx.scene.add(e);
      this.escorts.push(e);
    }
    this.escortFire -= dt;
    this.escorts.forEach((d, i) => {
      const a = ctx.time * 1.6 + i * Math.PI + this.uid * 0.7;
      d.position.set(ctx.tankX + Math.cos(a) * 6, 4.2 + Math.sin(ctx.time * 3 + i) * 0.3, ctx.tankZ + Math.sin(a) * 4);
      d.rotation.y = -a;
      if (this.escortFire > 0) return;
      const t = pickTarget(ctx, d.position.x, d.position.z, 46, 'small', false);
      if (!t) return;
      const dx = t.group.position.x - d.position.x;
      const dz = t.group.position.z - d.position.z;
      const len = Math.hypot(dx, dz) || 1;
      const b = ctx.bullets.spawn('mg', d.position.x, d.position.z, (dx / len) * 120, (dz / len) * 120, 6 * SUB_DMG * this.power, true);
      b.dtype = 'small';
      b.summon = true;
    });
    if (this.escortFire <= 0) this.escortFire = this.link === 'armed' ? 0.09 : 0.18;
  }

  /** 究极助攻：黑潮 / 雷云 = 蜂巢舱盖全开 1 秒；雷云再放几架小灯升空进乌云 */
  protected override assistStep(ctx: CombatContext, k: number, first: boolean): void {
    super.assistStep(ctx, k, first);
    const lids = this.model.racks.lids;
    if (lids) {
      const open = k < 0.75 ? Math.min(1, k * 6) : (1 - k) / 0.25;
      (lids.userData.rest as { pos: [number, number, number] }[]).forEach((r, i) => lids.setMatrixAt(i, _m.compose(_p.set(...r.pos), _qq.setFromAxisAngle(_x, open * 1.7), _s1)));
      lids.instanceMatrix.needsUpdate = true;
    }
    if (this.assistId === 'aurora' && Math.random() < 0.4 * ctx.sub.cfg.assist) {
      const o = this.muzzle(0, this.w);
      ctx.fx.glow.emit({ x: o.x + rand(-0.6, 0.6), y: o.y, z: o.z + rand(-0.6, 0.6), vy: rand(8, 12), life: 1, size: 0.4, size1: 0.2, color: ULT_THEME.aurora, frame: 0 });
    }
  }

  override dispose(): void {
    super.dispose();
    for (const e of this.escorts) e.removeFromParent();
    this.escorts.length = 0;
  }
}

// ---------------------------------------------------------------- 空袭信标

class AirstrikeWeapon extends Weapon {
  private timer = 4;

  override saveRuntime(): Record<string, number> { return { timer: this.timer }; }
  override restoreRuntime(s: Record<string, number>): void { this.timer = s.timer ?? this.timer; this.loaded = this.timer <= 0; }

  /** 引导轰炸：每架无人机扎中，冷却 −s 秒 */
  hasten(s: number): void {
    this.timer -= s;
  }
  private beacon: { x: number; z: number; t: number } | null = null;
  /** 上一次呼叫多久了；★ 三架轰炸机各在呼叫后几秒飞过落点（飞过一架灭一盏信号灯） */
  private callT = 9;
  private passAt: number[] = [];
  private loaded = true;
  /** ★ 桅杆信号灯上一次亮了几盏（变了才改颜色） */
  private litN = -1;

  /**
   * T143 挂件动作：顶灯（5 级起连两只信号烟罐的罐帽）一闪一闪，呼叫的那 1.5 秒常亮；3 级起抛物面天线慢慢转、★ 雷达条转，呼叫时转快；
   * ★ 桅杆 3 盏信号灯 = 3 架轰炸机，呼叫后每飞过落点一架灭一盏，冷却好了重新亮满
   */
  private pose(ctx: CombatContext): void {
    const md = this.model;
    this.callT += ctx.dt;
    if (this.timer <= 0) this.loaded = true;
    if (md.glow) md.glow.value = this.callT < 1.5 ? GLOW_MAX : Math.sin(ctx.time * 8) > 0 ? 1.2 : 0.12;
    if (md.spinner) md.spinner.rotation.y += ctx.dt * (this.evolved ? 2.2 : 0.6) * (this.callT < 2 ? 2.5 : 1);
    // 5 级起每次呼叫，两只信号烟罐冒一股信号烟 1.5 秒（我方浅黄，T130）
    // 近身的烟压淡（策划 2.3：车身 6 米内的新烟透明度压低，不糊住自己的车）
    if (this.form >= 5 && !this.evolved && this.callT < 1.5 && Math.random() < 0.5 && ctx.sub.allow(1, 'smoke')) {
      const s = Math.random() < 0.5 ? -1 : 1;
      const p = md.head.localToWorld(this.w.set(s * 0.34, 0.45, 0.12));
      ctx.fx.smokeP.emit({ x: p.x, y: p.y, z: p.z, vx: rand(-0.3, 0.3), vy: rand(2, 3), vz: rand(-0.3, 0.3) + 1, life: rand(1.2, 1.8), size: 0.4, size1: 1.4, color: MARK_SELF, color1: 0xb8a878, alpha: 0.3, frame: 1, drag: 0.8 });
    }
    const lamps = md.racks.lamps;
    if (lamps) {
      const n = this.loaded ? 3 : this.passAt.filter((t) => this.callT < t).length;
      if (n !== this.litN || lamps.userData.lit !== true) {
        this.litN = n;
        lamps.userData.lit = true;
        for (let i = 0; i < 3; i++) lamps.setColorAt(i, _c.setHex(i < n ? SUB_ID.airstrike : 0x2a1c0a));
        if (lamps.instanceColor) lamps.instanceColor.needsUpdate = true;
      }
    }
  }

  /** 究极助攻：天火 = 信标朝天打一道细校准光（白金）；核弹 / 铁雨 = 雷达 / 天线转快、灯全亮 */
  protected override assistStep(ctx: CombatContext, k: number, first: boolean): void {
    super.assistStep(ctx, k, first);
    const md = this.model;
    if (md.spinner) md.spinner.rotation.y += ctx.dt * 8;
    if (this.assistId !== 'skyfire') return;
    const top = md.head.localToWorld(this.w.set(this.evolved ? 0 : 0.18, this.evolved ? 1.8 : 2.1, this.evolved ? 0.08 : 0.1));
    ctx.streaks.add(top.x, top.y, top.z, top.x, top.y + 45, top.z, 0.12, ULT_THEME.skyfire, 0.9 * (1 - k * 0.5), 0.05, 2);
    if (first) ctx.audio.play('radio', 0.7);
  }

  update(ctx: CombatContext): void {
    const dt = ctx.dt;
    const m = ctx.mods;
    this.pose(ctx);
    if (this.beacon) {
      this.beacon.t -= dt;
      // 落点指示烟：我方浅黄（T130，原来红烟）
      if (Math.random() < 0.5) ctx.fx.smoke(this.beacon.x, 0.6, this.beacon.z, 0.8, 2, MARK_SELF, 0.55);
      if (this.beacon.t <= 0) this.beacon = null;
    }
    // 引导轰炸（T018-link）：有指示烟时冷却快 1.5 倍，好了优先炸最新的指示点
    const marks = this.link === 'guide' ? ctx.linkMarks : null;
    this.timer -= dt * m.rate * (marks?.length ? 1.5 : 1);
    if (this.timer > 0) return;
    const mark = marks?.length ? marks[marks.length - 1] : null;
    const cl = mark ? { x: mark.x, z: mark.z } : ctx.cluster(ctx.tankX, ctx.tankZ, 20, 90, true);
    if (!cl) {
      this.timer = 0.5;
      return;
    }
    this.timer = (this.evolved ? 8 : this.stat('冷却')) * m.cooldown;
    const bombs = (this.evolved ? 10 : this.stat('炸弹')) * m.summon;
    const dmg = this.evolved ? EVO_SHOT.airstrike * this.power : this.stat('伤害');
    const radius = (this.evolved ? 5 : 4.2) * m.area;
    const fx = { fxScale: subFx(this), look: this.form, subLink: this.link ?? undefined };
    const napalm = this.evolved || this.form >= 5 ? 9 * SUB_DMG * this.power : 0;
    this.beacon = { x: cl.x, z: cl.z, t: 2.2 };
    ctx.hazards.marker(cl.x, cl.z, 7, 1.6, 'self');
    this.callT = 0;
    this.loaded = false;
    // 5 级起呼叫时一声无线电「咔哒」（T143）
    if (this.form >= 5 || this.evolved) ctx.audio.play('radio', 0.7);
    if (this.evolved) {
      // 轰炸机从 x = −110 − 延迟 × 60 起、每秒 60 米飞过来（Projectiles.bomber）：飞到落点那一刻灭一盏信号灯
      this.passAt = [0, 0.3, 0.45].map((d) => (cl.x + 110) / 60 + d);
      for (const [dz, delay] of [[0, 0], [-7, 0.3], [7, 0.3]] as const) ctx.projectiles.bomber(cl.z + dz, cl.x - 18, cl.x + 18, bombs, dmg, radius, napalm, delay, 0, fx);
    } else {
      ctx.projectiles.bomber(cl.z, cl.x - 18, cl.x + 18, bombs, dmg, radius, napalm, 0, 0, fx);
    }
    ctx.audio.play('plane');
  }
}

export function createWeapon(def: WeaponDef, anchor: THREE.Object3D, slot: number, geo: GeoCache): Weapon {
  switch (def.id) {
    case 'mg': return new MgWeapon(def, anchor, slot, geo);
    case 'mortar': return new MortarWeapon(def, anchor, slot, geo);
    case 'tesla': return new TeslaWeapon(def, anchor, slot, geo);
    case 'flamer': return new FlamerWeapon(def, anchor, slot, geo);
    case 'drones': return new DroneWeapon(def, anchor, slot, geo);
    case 'airstrike': return new AirstrikeWeapon(def, anchor, slot, geo);
  }
}
