import type { GeoCache } from '../../assets/GeoCache';
import type { Enemy } from '../../entities/Enemy';
import type { Bullet } from '../../systems/Bullets';
import type { CraterTier } from '../../world/Craters';
import type { Mood, SatView } from '../../world/Environment';
import type { CombatContext } from '../behaviors';
import type { FusionDef } from '../defs';

/**
 * 终极武器（T007）：合成后车上多一件独立的武器（Arsenal.ult），伤害来源记成 'ult'，战报单独一行。
 * 装载与发射的硬规则（八件统一）：
 * 1. 合成完成直接待发；2. 玩家点终极键 / 终极行（键盘 R、电脑右键）时发射；设置「究极 自动」（汇总第 60 条，默认）时待发后附近敌人够、选得到目标也会自己放（Game.ultAutoAim）；
 * 3. 和主武器无关：不占弹匣、不打断装填，点终极入口永远不会顺带开一炮；
 * 4. 按下时写入基础冷却 × 电容倍率，最多存 1 发；5. 生效中再点没有反应（键抖一下）；
 * 6. 升级弹窗、暂停、合成演出、阵亡期间不能发射（两个入口隐藏）
 */

/**
 * 终极打向哪里（T017-13A）：自动瞄准 = 落点价值评分选出来的那一坨的中心敌人（有 spot() 的终极；没有的照旧 = 点在拇指区开一炮的目标）、
 * 首领战 = 首领核心；手动 = 炮塔正前方（target = null）
 */
export interface UltAim {
  target: Enemy | null;
  /** 炮塔约定角：0 = 正前方（-Z），正值向左 */
  angle: number;
}

/** 待发时的地面落点预览（20% 不透明度、不闪）：圆（核弹）或顺着道路的椭圆（rz = 前后半轴，炼狱）；颜色统一我方浅黄（T130），不按究极分 */
export interface UltPreview {
  x: number;
  z: number;
  r: number;
  rz?: number;
}

/** 炼狱弹命中：位置 + 弹道方向 */
export interface UltHit {
  x: number;
  z: number;
  dx: number;
  dz: number;
}

/** 终极运行时能用到的一切：CombatContext + 演出 / 场景 / 首领钩子（Game 提供，终极逻辑全部放在各自模块里） */
export interface UltContext extends CombatContext {
  geo: GeoCache;
  /** 坦克推进速度（米/秒，每帧由游戏层写入） */
  speed: number;
  /** 当前画质（凝结环等只在高画质开） */
  quality: string;
  /** 正在打的首领的核心部件（不在首领战为 null） */
  bossCore(): Enemy | null;
  /** 这一刻的终极重点目标（落点价值评分，评分半径 = 这件终极的 spot().r；手动瞄准时为 null） */
  pick(): Enemy | null;
  /** 激光正在出光时光束的方向（炮塔约定角），否则 null（天火：按住出光拖动落点；极光：切翼阵） */
  beam(): number | null;
  /** 激光光束阶段：0 蓝 / 1 紫 / 2 金 */
  beamStage(): number;
  /** 激光出光中的锁点（地面世界坐标，T016-3 A1）；不在出光为 null（T021-b 闪电风暴的「引雷针」劈在这里） */
  beamLock(): { x: number; z: number } | null;
  /** 这一刻屏幕上（镜头视锥内、雾里还看得见）的活着的敌人，首领部件各算一个 */
  screenFoes(): Enemy[];
  /**
   * 镜头放平到 maxTilt（玩家本来更平就不动），保持 hold 秒后用 back 秒缓回；同一时段左上 HUD 变淡（body.cinema，fade = false 时不变淡）；不改玩家设置。
   * maxTilt < −1（T057）= 比 ▲▲ 更低更远的机位（抬头看天时用，坦克在画面下半截）
   */
  cinema(maxTilt: number, hold: number, back?: number, fade?: boolean): void;
  /** 镜头再往上仰 rad 弧度看天（T057），inT 秒仰到位、保持 hold 秒、back 秒缓回；rad = 0 = 马上缓回 */
  lookUp(rad: number, hold: number, back?: number, inT?: number): void;
  /** 冲击波扫到坦克：镜头一缩一放（CameraRig.blastKick，k = 0..1） */
  kick(k: number): void;
  /** 低频余震 */
  rumble(amount: number, seconds: number): void;
  /** 全屏暖白闪光（最高不透明度） */
  flash(alpha: number): void;
  /** 全场压暗（T021-b 雷云）：光照 × light、曝光 × exposure，fade 秒过渡；dim(1, 1) 退回 */
  dim(light: number, exposure: number, fade?: number): void;
  /** 整套氛围（T057）：压暗 / 染色 / 雾色 / 天空乌云 / 影子浓淡，没给的项回到平时；null = 全部回到平时 */
  mood(m: Partial<Mood> | null, fade?: number): void;
  /** 一道主雷：曝光（和天光）闪回 k 倍 t 秒，flicker = 闪几下 */
  boltFlash(k?: number, t?: number, flicker?: number): void;
  /** 天上 (x, z) 那个方向的云被闪电照亮（雷云抬头时看得到） */
  skyBolt(x: number, z: number, k: number): void;
  /** 关键那一下慢放（T057）：seconds 秒（真实时间），前一半 k 倍、后一半缓回 */
  slowmo(seconds: number, k: number): void;
  /** 镜头现在的位置（按距离晚一拍放声音：先见光后闻声） */
  camPos(): { x: number; y: number; z: number };
  /** 镜头现在朝哪（单位向量；T060 天火：光柱顶端别跑到镜头平面后面） */
  camDir(): { x: number; y: number; z: number };
  /** 天幕上画天火的卫星炮（T060，Environment.satellite）；null = 收掉 */
  satellite(s: SatView | null): void;
  /** 泛光脉冲（中 / 高画质）：拉到 strength，seconds 秒回落 */
  pulse(strength: number, seconds: number): void;
  /** 顿帧（强制，不受击毁顿帧冷却限制） */
  freeze(t: number): void;
  /** 场景：路障推开 / 烧毁 / 炸碎、掩体炸矮炸碎（友方掩体不炸）、残骸推开或炸碎；cut = 碰到的残骸直接切碎；scenery = false 时路边景物不管（核弹的景物走 scenery.nuke） */
  smash(x: number, z: number, radius: number, force: number, cut?: boolean, scenery?: boolean): void;
  /** 范围内的车辆路障烧成燃烧空壳（不推、不炸碎） */
  ignite(x: number, z: number, radius: number): void;
  /** 取出范围内的油桶（已从场上移除，由近到远），调用方逐个 detonate，形成一串二次爆炸 */
  barrels(x: number, z: number, radius: number): [number, number][];
  /** 引爆一个油桶（范围伤害 + 原地燃烧） */
  detonate(x: number, z: number): void;
  /** 在结算伤害前记住载具遮挡，目标被移除后仍能传给地面效果。 */
  groundContact(x: number, z: number, radius: number): 'vehicle' | 'ground';
  /** 实体弹坑（T014-3）：坑口半径 r、深 d、坑沿高 rim、抛土到 out、烧焦程度 char；河道上不挖；tier = 档位（T016-1：3 大 = 天火，4 特大 = 核弹，吃掉坑口里的低档坑） */
  dig(x: number, z: number, r: number, d: number, rim: number, out: number, char: number, tier?: CraterTier, contact?: 'vehicle' | 'ground'): void;
  /** 接下来最多几辆车 / 几块残骸走完整的碎裂流程（超出的只放尘土和火球）；Infinity = 不限 */
  breaks(n: number): void;
  /**
   * 主炮打出一发终极特种弹（炼狱弹）：炮塔转到 angle、炮口火光 / 后坐 / 开炮声照旧，但不扣弹匣、不重置装填；
   * 弹上带 ultShell 标记（第一次命中敌人 / 撞上障碍 / 打中油桶 / 飞到射程尽头调一次 onShellHit）。不是主炮流返回 null
   */
  shell(angle: number, speed: number, range: number): Bullet | null;
  /** 场景点火（炼狱火场，顺着道路的椭圆）：木质路障点着后陆续烧塌、车辆烧成空壳、敌方残骸重新烧起来；返回取出的油桶（由近到远），调用方逐个 detonate */
  kindle(x: number, z: number, rx: number, rz: number): [number, number][];
}

export type UltState = 'loading' | 'ready' | 'active' | 'result';
/** 车上套件指示灯：装载中不亮、最后 5 秒慢闪、待发常亮、生效中快闪 */
export type UltLamp = 'off' | 'slow' | 'on' | 'fast';

export interface Ultimate {
  readonly def: FusionDef;
  /** 剩余冷却秒数，0 = 待发 */
  readonly cd: number;
  /** 按下时写入的本轮总冷却，进度条和读档用同一个分母。 */
  readonly cooldown: number;
  /** 生效剩余秒数，0 = 不在生效 */
  readonly active: number;
  readonly state: UltState;
  /** 冷却进度 0..1（入口的进度条 / 进度环） */
  readonly progress: number;
  /** 入口上的状态字：「12」「发射」「已呼叫」「×23」 */
  readonly label: string;
  /** 本次事件击毁数 */
  readonly kills: number;
  /** 本局发射次数（诊断） */
  readonly fired: number;
  readonly lamp: UltLamp;
  /** 发射：没装好或在生效中返回 false（不发射、不开炮） */
  trigger(ctx: UltContext, aim: UltAim): boolean;
  /** 待发时每帧调用：现在按下会落在哪 */
  preview(ctx: UltContext, aim: UltAim): UltPreview | null;
  update(ctx: UltContext): void;
  /** 本次事件里有敌人被终极伤害击毁（伤害来源 'ult'） */
  noteKill(): void;
  /** 终极特种弹第一次落地（炼狱弹） */
  onShellHit?(ctx: UltContext, hit: UltHit): void;
  /** 熔甲：这一刻主武器打这个敌人的伤害倍率（不在火场里返回 1） */
  coreMult?(e: Enemy): number;
  /** 敌方直射炮弹 / 火箭这一帧从 (x0, z0) 飞到 (x1, z1)：被终极拦下返回 true（极光：帘幕 / 横连线 / 三角盾） */
  intercept?(x0: number, z0: number, x1: number, z1: number): boolean;
  /** 火箭核心开了一轮齐射（锁定的目标；黑潮记成重点目标） */
  onSalvo?(target: Enemy | null): void;
  /**
   * 落点价值评分的参数（T017-13A）：r = 一发能罩住多大（米），min / max = 落点离坦克能多近 / 多远（够不着的打折）；
   * 不给 = 不用选点（核弹全屏、极光跟车），终极瞄准照旧用主炮的自动瞄准
   */
  spot?(ctx: UltContext): { r: number; min: number; max: number };
  /** 生效中点了一下屏幕（地面坐标，铁雨：火力圈挪过去）；用上了返回 true */
  tapAt?(x: number, z: number): boolean;
  /** 自己挑方向（钢幕：走廊里数敌人，够 min 个才返回）；自动释放、自动瞄准时 Game 用它代替落点评分 */
  aimAuto?(ctx: UltContext, min?: number): UltAim | null;
  /** 锁定框旁边的「×N」（黑潮扫射期间：重点目标会分到几枚）；没有为 null */
  mark?(ctx: UltContext): { e: Enemy; n: number } | null;
  /** 读档：剩余冷却（老存档没有 = 0，直接待发） */
  restore(cdLeft: number, cooldown?: number): void;
  reset(): void;
  dispose(): void;
}

/** 结算（「×23」）停留的秒数 */
const RESULT_HOLD = 2;

/** 冷却 / 生效 / 结算 / 状态字的公共部分；各终极只管自己的事件（fire / step / preview） */
export abstract class UltBase implements Ultimate {
  cd = 0;
  cooldown: number;
  active = 0;
  kills = 0;
  fired = 0;
  private resultT = 0;

  constructor(readonly def: FusionDef) { this.cooldown = def.cd; }

  get state(): UltState {
    if (this.active > 0) return 'active';
    if (this.resultT > 0) return 'result';
    return this.cd > 0 ? 'loading' : 'ready';
  }

  get progress(): number {
    return 1 - this.cd / this.cooldown;
  }

  get label(): string {
    switch (this.state) {
      case 'active': return this.activeLabel();
      case 'result': return `×${this.kills}`;
      case 'ready': return '发射';
      default: return String(Math.ceil(this.cd));
    }
  }

  get lamp(): UltLamp {
    switch (this.state) {
      case 'active': return 'fast';
      case 'ready': return 'on';
      default: return this.cd <= 5 ? 'slow' : 'off';
    }
  }

  /** 生效中的状态字 */
  protected activeLabel(): string {
    return `生效 ${Math.ceil(this.active)}`;
  }

  trigger(ctx: UltContext, aim: UltAim): boolean {
    if (this.cd > 0 || this.active > 0) return false;
    this.cd = this.cooldown = this.def.cd * ctx.mods.cooldown;
    this.kills = 0;
    this.resultT = 0;
    this.fired += 1;
    this.fire(ctx, aim);
    return true;
  }

  update(ctx: UltContext): void {
    if (this.cd > 0) this.cd = Math.max(0, this.cd - ctx.dt);
    if (this.active <= 0 && this.resultT > 0) this.resultT = Math.max(0, this.resultT - ctx.dt);
    this.step(ctx);
  }

  noteKill(): void {
    this.kills += 1;
  }

  /** 生效结束：开始显示本次击毁数 */
  protected finish(): void {
    this.active = 0;
    this.resultT = RESULT_HOLD;
  }

  restore(cdLeft: number, cooldown = this.def.cd): void {
    this.clear();
    this.cooldown = cooldown;
    this.cd = Math.min(cooldown, Math.max(0, cdLeft));
    this.active = 0;
    this.resultT = 0;
  }

  reset(): void {
    this.restore(0);
  }

  dispose(): void {
    this.clear();
  }

  abstract preview(ctx: UltContext, aim: UltAim): UltPreview | null;
  /** 按下的那一刻（冷却已经开始算） */
  protected abstract fire(ctx: UltContext, aim: UltAim): void;
  /** 每帧（伤害来源已是 'ult'） */
  protected abstract step(ctx: UltContext): void;
  /** 收掉事件里的网格和状态（重开 / 读档 / 释放） */
  protected abstract clear(): void;
}
