import * as THREE from 'three';

/**
 * 车体骑上去的绘制支撑（T185）：按物件这一帧实际画出来的网格取顶面高度（世界米，0.2 米一格）。
 * 原来按凸起的矩形 × 外形高度表估，和模型对不上（残骸比矩形宽、比表高；翻滚后转了向），车体就压进残骸里。
 * 只管绘制：凸起的 h0 / h1 / flat、碾压判定、减速都不读它。
 */
const CELL = 0.2;
/** 三角面撒点间距（查的时候取周围 ±1 格最高，撒得比格子稀一点也不漏） */
const STEP = 0.24;
/** 顺着车头方向放坡：多远、每米降多少 */
const RAMP = 1.4;
const RAMP_K = 1.1;
/** 只有几何在变（局部碾压正往下压）时最多隔几帧重建一次：旧的只会比实际高，车体只是多托一点 */
const GEO_EVERY = 3;
const PAD = 0.6;

/** 每份几何在自身坐标里的撒点，位置属性改过（局部碾压重算顶点）就重撒；同一份几何连着在变时隔 GEO_EVERY 帧才重撒 */
const clouds = new WeakMap<THREE.BufferGeometry, { version: number; frame: number; pts: Float32Array }>();

function cloud(geo: THREE.BufferGeometry, frame: number): Float32Array {
  const pos = geo.getAttribute('position') as THREE.BufferAttribute | undefined;
  if (!pos) return new Float32Array(0);
  const hit = clouds.get(geo);
  if (hit && (hit.version === pos.version || frame - hit.frame < GEO_EVERY)) return hit.pts;
  const idx = geo.index;
  const n = idx ? idx.count : pos.count;
  // 统一摊成 [ax, ay, az, bx, ...]（非索引、非交错的直接用原数组）
  let tri = pos.array as Float32Array;
  if (idx || pos.itemSize !== 3 || (pos as unknown as THREE.InterleavedBufferAttribute).isInterleavedBufferAttribute) {
    tri = new Float32Array(n * 3);
    for (let t = 0; t < n; t++) {
      const v = idx ? idx.getX(t) : t;
      tri[t * 3] = pos.getX(v); tri[t * 3 + 1] = pos.getY(v); tri[t * 3 + 2] = pos.getZ(v);
    }
  }
  // 先数点数再一次填好，不用临时数组
  const steps = new Uint8Array(Math.floor(n / 3));
  let count = 0;
  for (let t = 0, q = 0; t + 2 < n; t += 3, q++) {
    const o = t * 3;
    const ux = tri[o + 3] - tri[o], uy = tri[o + 4] - tri[o + 1], uz = tri[o + 5] - tri[o + 2];
    const vx = tri[o + 6] - tri[o], vy = tri[o + 7] - tri[o + 1], vz = tri[o + 8] - tri[o + 2];
    const l = Math.max(ux * ux + uy * uy + uz * uz, vx * vx + vy * vy + vz * vz, (ux - vx) ** 2 + (uy - vy) ** 2 + (uz - vz) ** 2);
    const k = l <= STEP * STEP ? 1 : Math.min(24, Math.ceil(Math.sqrt(l) / STEP));
    steps[q] = k;
    count += ((k + 1) * (k + 2)) / 2;
  }
  const pts = new Float32Array(count * 3);
  let w = 0;
  for (let t = 0, q = 0; t + 2 < n; t += 3, q++) {
    const o = t * 3, k = steps[q];
    const ax = tri[o], ay = tri[o + 1], az = tri[o + 2];
    const ux = tri[o + 3] - ax, uy = tri[o + 4] - ay, uz = tri[o + 5] - az;
    const vx = tri[o + 6] - ax, vy = tri[o + 7] - ay, vz = tri[o + 8] - az;
    for (let i = 0; i <= k; i++) for (let j = 0; j <= k - i; j++) {
      const s = i / k, r = j / k;
      pts[w++] = ax + ux * s + vx * r;
      pts[w++] = ay + uy * s + vy * r;
      pts[w++] = az + uz * s + vz * r;
    }
  }
  clouds.set(geo, { version: pos.version, frame, pts });
  return pts;
}

const _box = new THREE.Box3();

export class RideSurface {
  x0 = 0;
  z0 = 0;
  nx = 0;
  nz = 0;
  /** 这一格里最高的点（世界 y），空格 = -Infinity */
  top = new Float32Array(0);
  /** 这一帧车体底面压在它上面（World.visualTopAt 记） */
  carried = false;
  /** 建好以后整体平移过多少（推着走时不重建，只挪格子） */
  private yOff = 0;
  private built = -Infinity;
  private readonly meshes: THREE.Mesh[] = [];
  /** 上一次的网格、几何、位置版本、世界矩阵（判断这一帧要不要重建） */
  private readonly last: { mesh: THREE.Mesh; geo: THREE.BufferGeometry; version: number; e: number[] }[] = [];

  constructor(readonly obj: THREE.Object3D) {}

  /**
   * 按物件当前的姿态 / 几何刷新（frame = 第几帧）：都没变就沿用；只是整体平移就挪格子；
   * 只是几何在变（局部碾压）隔 GEO_EVERY 帧重建一次；姿态变了（转向、压扁、翻滚）当帧重建
   */
  refresh(frame: number): void {
    const list = this.meshes;
    list.length = 0;
    if (!this.obj.visible) {
      this.nx = this.nz = 0;
      this.last.length = 0;
      return;
    }
    this.obj.updateWorldMatrix(true, true);
    this.obj.traverseVisible((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh || (m as unknown as THREE.InstancedMesh).isInstancedMesh) return;
      if ((m.material as THREE.Material).transparent) return;
      list.push(m);
    });
    const last = this.last;
    let same = last.length === list.length, posed = same, geoOnly = false;
    let dx = 0, dy = 0, dz = 0;
    for (let i = 0; same && i < list.length; i++) {
      const m = list[i], l = last[i], e = m.matrixWorld.elements;
      const version = (m.geometry.getAttribute('position') as THREE.BufferAttribute | undefined)?.version ?? 0;
      if (l.mesh !== m || l.geo !== m.geometry) { same = false; break; }
      if (l.version !== version) geoOnly = true;
      for (let k = 0; k < 12; k++) if (e[k] !== l.e[k]) posed = false;
      const tx = e[12] - l.e[12], ty = e[13] - l.e[13], tz = e[14] - l.e[14];
      if (i === 0) { dx = tx; dy = ty; dz = tz; }
      else if (Math.abs(tx - dx) + Math.abs(ty - dy) + Math.abs(tz - dz) > 1e-6) posed = false;
    }
    if (same && posed && !geoOnly && dx === 0 && dy === 0 && dz === 0) return;
    if (same && posed && (!geoOnly || frame - this.built < GEO_EVERY)) {
      // 整体平移：挪格子；几何同时在变的先不管（隔几帧重建时一起算）
      this.x0 += dx;
      this.z0 += dz;
      this.yOff += dy;
      for (let i = 0; i < list.length; i++) for (let k = 12; k < 15; k++) last[i].e[k] = list[i].matrixWorld.elements[k];
      return;
    }
    this.rebuild(frame);
  }

  private rebuild(frame: number): void {
    const list = this.meshes, last = this.last;
    last.length = 0;
    this.built = frame;
    this.yOff = 0;
    // 范围按各网格包围盒算，不用多扫一遍点
    let x0 = Infinity, x1 = -Infinity, z0 = Infinity, z1 = -Infinity;
    for (const m of list) {
      const g = m.geometry;
      last.push({ mesh: m, geo: g, version: (g.getAttribute('position') as THREE.BufferAttribute | undefined)?.version ?? 0, e: m.matrixWorld.elements.slice() });
      // 局部碾压会把顶点往外摊一点：包围盒只算一次，四周留 PAD
      if (!g.boundingBox) g.computeBoundingBox();
      _box.copy(g.boundingBox!).applyMatrix4(m.matrixWorld);
      if (_box.isEmpty()) continue;
      x0 = Math.min(x0, _box.min.x - PAD); x1 = Math.max(x1, _box.max.x + PAD);
      z0 = Math.min(z0, _box.min.z - PAD); z1 = Math.max(z1, _box.max.z + PAD);
    }
    if (x0 > x1) {
      this.nx = this.nz = 0;
      return;
    }
    this.x0 = x0;
    this.z0 = z0;
    const nx = (this.nx = Math.floor((x1 - x0) / CELL) + 1);
    const nz = (this.nz = Math.floor((z1 - z0) / CELL) + 1);
    const size = nx * nz;
    if (this.top.length < size) this.top = new Float32Array(size);
    const top = this.top;
    top.fill(-Infinity, 0, size);
    for (const m of list) {
      const pts = cloud(m.geometry, frame);
      const e = m.matrixWorld.elements;
      for (let i = 0; i < pts.length; i += 3) {
        const x = pts[i], y = pts[i + 1], z = pts[i + 2];
        const wx = e[0] * x + e[4] * y + e[8] * z + e[12], wz = e[2] * x + e[6] * y + e[10] * z + e[14];
        const ix = Math.floor((wx - x0) / CELL), iz = Math.floor((wz - z0) / CELL);
        if (ix < 0 || iz < 0 || ix >= nx || iz >= nz) continue;
        const wy = e[1] * x + e[5] * y + e[9] * z + e[13], k = iz * nx + ix;
        if (wy > top[k]) top[k] = wy;
      }
    }
  }

  /** 包围范围离 (x, z) 不到 reach 米 */
  near(x: number, z: number, reach: number): boolean {
    if (this.nx === 0) return false;
    return x + reach > this.x0 && x - reach < this.x0 + this.nx * CELL && z + reach > this.z0 && z - reach < this.z0 + this.nz * CELL;
  }

  /**
   * (x, z) 处托车体的高度（世界 y；不在物件上 = -Infinity）。顺着车头方向 (dx, dz) 前后 RAMP 米内再按 RAMP_K 的坡度往下取：
   * 车头撞上残骸竖直的侧面时从前面一点就开始抬（顶着推的那一段车头就慢慢翘上去），不是一帧跳上去。base = 这一点的实际顶面（cell）
   */
  ramped(x: number, z: number, dx: number, dz: number, base = this.cell(x, z)): number {
    let h = base;
    for (let t = CELL * 2; t <= RAMP + 1e-6; t += CELL * 2) {
      const drop = RAMP_K * t;
      h = Math.max(h, this.cell(x + dx * t, z + dz * t) - drop, this.cell(x - dx * t, z - dz * t) - drop);
    }
    return h;
  }

  /** (x, z) 周围 ±1 格里最高处（实际顶面） */
  cell(x: number, z: number): number {
    const fx = Math.floor((x - this.x0) / CELL), fz = Math.floor((z - this.z0) / CELL);
    let h = -Infinity;
    for (let j = Math.max(0, fz - 1); j <= Math.min(this.nz - 1, fz + 1); j++) {
      for (let i = Math.max(0, fx - 1); i <= Math.min(this.nx - 1, fx + 1); i++) {
        const v = this.top[j * this.nx + i];
        if (v > h) h = v;
      }
    }
    return h + this.yOff;
  }

  /**
   * 被车头顶着的物件要往前（世界 −z）挪多少才不进车体：物件上高出地面 clear 米的格子，落在车体前半段轮廓（yaw 朝向、半宽 hw、
   * 车头 nose）里的，按车体局部前后方向推到车头前 gap 米
   */
  shove(x: number, z: number, yaw: number, hw: number, nose: number, floor: number, clear: number, gap: number): number {
    const c = Math.cos(yaw), s = Math.sin(yaw);
    // 只沿世界 −z 推：车头偏出 45° 以上（攻坚时横着走）就不推
    if (this.nx === 0 || c < 0.7) return 0;
    let need = 0;
    for (let j = 0; j < this.nz; j++) {
      const wz = this.z0 + (j + 0.5) * CELL;
      for (let i = 0; i < this.nx; i++) {
        if (this.top[j * this.nx + i] + this.yOff < floor + clear) continue;
        const wx = this.x0 + (i + 0.5) * CELL;
        const dx = wx - x, dz = wz - z;
        // 车体局部：lx 向右、lz 向车尾（和 Tank 一样，车头在 −lz）
        const lx = dx * c - dz * s, lz = dx * s + dz * c;
        if (Math.abs(lx) > hw + CELL || lz > 0 || lz < -nose - gap - CELL) continue;
        need = Math.max(need, (lz + nose + gap + CELL * 0.5) / c);
      }
    }
    return need;
  }
}
