import { fmtNum, reportTitle, type ReportData } from '../../systems/Hud';
import type { Overlay, Panel, Rect, Region } from './Overlay';
import { skinBox as box, ellipsize, font, hgrad, icon, measure, rr, shadow, text, vgrad, wrap } from './paint';
import { UI_SKIN } from '../skins';
import { skinBackdrop, skinSurface } from '../skins/art';
import { menuScale } from '../viewport';

type Ctx = CanvasRenderingContext2D;

/** 装甲切角；不改面板位置和点击区域。 */
export function armorPanel(ctx: Ctx, x: number, y: number, w: number, h: number, fill: string | CanvasGradient, edge: string, cut = 7, line = 1): void {
  cut = Math.min(cut, w / 2, h / 2);
  const o = line / 2;
  ctx.beginPath();
  ctx.moveTo(x + cut, y + o);
  ctx.lineTo(x + w - cut, y + o);
  ctx.lineTo(x + w - o, y + cut);
  ctx.lineTo(x + w - o, y + h - cut);
  ctx.lineTo(x + w - cut, y + h - o);
  ctx.lineTo(x + cut, y + h - o);
  ctx.lineTo(x + o, y + h - cut);
  ctx.lineTo(x + o, y + cut);
  ctx.closePath();
  ctx.fillStyle = fill;
  ctx.fill();
  ctx.lineWidth = line;
  ctx.strokeStyle = edge;
  ctx.stroke();
}

/** 菜单与提示牌共用战斗装甲；只画原框内部。 */
export function armorSurface(ctx: Ctx, x: number, y: number, w: number, h: number, edge = '#53624f', face = '#19251f', cut = 6): void {
  if (skinSurface(ctx, x, y, w, h, 'panel', edge === '#e4c682')) return;
  armorPanel(ctx, x, y, w, h, vgrad(ctx, y, y + h, face, '#141e19'), edge, cut);
  ctx.fillStyle = '#94a28033';
  ctx.fillRect(x + cut + 2, y + 2, Math.max(0, w - cut * 2 - 4), 1);
  if (w >= 100 && h >= 38) {
    ctx.fillStyle = edge;
    for (let i = 0; i < 4; i++) ctx.fillRect(x + w - 31 + i * 6, y + h - 5, 4, 2);
  }
}

/** 分段刻度：进度只读，文字仍由调用处绘制。 */
export function armorMeter(ctx: Ctx, x: number, y: number, w: number, h: number, progress: number, color = '#7f956e'): void {
  const k = Math.max(0, Math.min(1, progress));
  if (UI_SKIN) {
    box(ctx, x, y, w, h, Math.min(3, h / 2), 'rgba(255, 255, 255, 0.08)');
    if (k > 0) box(ctx, x, y, w * k, h, Math.min(3, h / 2), color);
    return;
  }
  ctx.fillStyle = '#354332';
  ctx.fillRect(x, y, w, h);
  ctx.fillStyle = color;
  ctx.fillRect(x, y, w * k, h);
  ctx.fillStyle = '#101a1490';
  for (let i = 1; i < 10; i++) ctx.fillRect(x + w * i / 10 - 2, y, 2, h);
  ctx.fillStyle = '#dce3bf40';
  ctx.fillRect(x, y, w * k, 1);
}

const KEY_TONES = {
  brass: { hi: '#e1c695', low: '#b99862', edge: '#b9a06b', inner: '#ac945f', top: '#f3e3b8', base: '#5e4b2b' },
  warn: { hi: '#4a3527', low: '#30271f', edge: '#b87745', inner: '#765037', top: '#c9976a', base: '#17130f' },
  muted: { hi: '#27312b', low: '#18221c', edge: '#414f43', inner: '#364337', top: '#596553', base: '#0b1211' },
  cool: { hi: '#354b43', low: '#1a2c25', edge: '#78948b', inner: '#4b665a', top: '#a1bcb1', base: '#0b1211' },
};

/** 机械键帽：浅顶边、内框、深底边；按下只压键面。 */
export function mechanicalKey(ctx: Ctx, x: number, y: number, w: number, h: number, pressed = false, on = false, cut = 4, tone?: keyof typeof KEY_TONES): void {
  const t = tone ? KEY_TONES[tone] : null;
  armorPanel(ctx, x, y, w, h, t?.base ?? '#0b1211', t?.edge ?? (on ? '#cdb879' : '#667166'), cut);
  const dy = pressed ? 2 : 0;
  armorPanel(ctx, x + 2, y + 2 + dy, w - 4, h - 7 + (pressed ? 2 : 0),
    vgrad(ctx, y, y + h, pressed ? '#26372e' : t?.hi ?? '#3a4739', pressed ? '#1b2621' : t?.low ?? '#1b2621'),
    t?.inner ?? (on ? '#a99e70' : '#57634f'), Math.max(2, cut - 2));
  ctx.strokeStyle = t?.top ?? (on ? '#e5d4a1' : '#9aa38b');
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(x + cut + 2, y + 3 + dy);
  ctx.lineTo(x + w - cut - 2, y + 3 + dy);
  ctx.stroke();
}

/** 类别底座：核心切角、副武器圆盘、改装盾形、究极菱形；fill = 底色（精良卡是深蓝，T132） */
export function categoryPlate(ctx: Ctx, id: string, x: number, y: number, size: number, color: string, fill = '#2b392d'): void {
  if (id === 'category-core') {
    armorPanel(ctx, x, y, size, size, fill, color, 8);
    return;
  }
  ctx.beginPath();
  if (id === 'category-weapon') ctx.arc(x + size / 2, y + size / 2, size / 2 - 0.5, 0, Math.PI * 2);
  else if (id === 'category-ult') {
    ctx.moveTo(x + size / 2, y);
    ctx.lineTo(x + size, y + size / 2);
    ctx.lineTo(x + size / 2, y + size);
    ctx.lineTo(x, y + size / 2);
    ctx.closePath();
  } else {
    ctx.moveTo(x + 1, y + 1);
    ctx.lineTo(x + size - 1, y + 1);
    ctx.lineTo(x + size - 1, y + size * 0.7);
    ctx.lineTo(x + size / 2, y + size);
    ctx.lineTo(x + 1, y + size * 0.7);
    ctx.closePath();
  }
  ctx.fillStyle = fill;
  ctx.fill();
  ctx.strokeStyle = color;
  ctx.lineWidth = 1;
  ctx.stroke();
}

/** 小键图标 24 像素，状态字只作补充。 */
export function iconKey(ctx: Ctx, x: number, y: number, w: number, h: number, id: string, label = '', pressed = false, on = false): void {
  mechanicalKey(ctx, x, y, w, h, pressed, on);
  const dy = pressed ? 2 : 0;
  const color = on ? '#edcf8b' : '#e2e5ce';
  icon(ctx, id, x + (w - 24) / 2, y + (label ? 2 : (h - 26) / 2) + dy, 24, color);
  if (label) {
    ctx.font = font(8, 600);
    text(ctx, label, x + w / 2, y + h - 7 + dy, color, 'center');
  }
  if (on) {
    ctx.fillStyle = '#e9c375';
    rr(ctx, x + w - 7, y + 5 + dy, 3, 3, 1);
    ctx.fill();
  }
}

/** 块内可点区域（块内坐标） */
export interface Hit {
  x: number;
  y: number;
  w: number;
  h: number;
  id: string;
  tap?: () => void;
  tapMs?: number;
  down?: () => void;
  ready?: () => boolean;
  drag?: Region['drag'];
}

/** 竖排浮层里的一块：高 h，paint 在块内坐标（0..列宽, 0..h）里画 */
export interface Block {
  h: number;
  /** 和上一块的间距（默认用整列的 gap） */
  gap?: number;
  paint: (ctx: Ctx, w: number) => void;
  hits?: Hit[] | (() => Hit[]);
}

/**
 * 全屏浮层的竖排布局（开始界面 / 选卡 / 结算 / 暂停 / 排行榜）：
 * 一列居中，内容比屏幕高就整体等比缩小（不滚动），可点区域跟着同一个变换。
 */
export class Sheet {
  blocks: Block[] = [];
  cw = 300;
  private ys: number[] = [];
  private s = 1;
  private x0 = 0;
  private y0 = 0;
  private viewport: Rect | null = null;
  private scroll = 0;
  private scrollMax = 0;

  constructor(private readonly ov: Overlay) {}

  /**
   * 摆一列：cw = 列宽，gap = 块间距，pad = 屏幕四周留白；bottom = 贴着下面排（车库：上面留给坦克）、top = 上面最少留多高；
   * lift = 从这个高度往下排（屏幕坐标，选卡：耐久块下面，T058），放不下就往上挪到刚好放下；0 = 居中
   */
  set(blocks: Block[], cw: number, gap = 10, pad = 24, bottom = false, top0 = 0, lift = 0): void {
    this.viewport = null;
    const { W, H, insets } = this.ov;
    this.blocks = blocks;
    this.cw = cw;
    this.ys = [];
    let y = 0;
    blocks.forEach((b, i) => {
      if (i > 0) y += b.gap ?? gap;
      this.ys.push(y);
      y += b.h;
    });
    const top = insets.top + pad * 0.5 + top0;
    const avail = H - top - insets.bottom - pad * 0.5;
    this.s = Math.min(menuScale(W, H), avail / Math.max(1, y), (W - insets.left - insets.right - 16) / cw);
    this.x0 = insets.left + (W - insets.left - insets.right - cw * this.s) / 2;
    this.y0 = lift > 0 ? Math.max(top, Math.min(lift, top + avail - y * this.s)) : top + Math.max(0, (avail - y * this.s) * (bottom ? 1 : 0.5));
  }

  /** 长菜单按原字号滚动；底部可以给固定的出击按钮留位置。 */
  setScrolling(blocks: Block[], cw: number, gap = 10, reserve = 0, top0 = 0): void {
    this.set(blocks, cw, gap, 24);
    const { W, H, insets } = this.ov;
    this.s = Math.min(menuScale(W, H), (W - insets.left - insets.right - 24) / cw);
    this.x0 = insets.left + (W - insets.left - insets.right - cw * this.s) / 2;
    const top = insets.top + 12 * this.s + top0;
    const h = Math.max(44, H - top - insets.bottom - (12 + reserve) * this.s);
    const total = (this.ys.at(-1) ?? 0) + (blocks.at(-1)?.h ?? 0);
    this.scrollMax = Math.max(0, total * this.s - h);
    this.scroll = Math.max(0, Math.min(this.scroll, this.scrollMax));
    this.y0 = top - this.scroll;
    this.viewport = { x: this.x0, y: top, w: cw * this.s, h };
  }

  /** 横屏的一栏；大屏同步放大文字和点击区，滚动距离仍按屏幕像素。 */
  setInRect(blocks: Block[], rect: Rect, gap = 10, scale = 1): void {
    this.set(blocks, rect.w / scale, gap);
    this.s = scale;
    this.x0 = rect.x;
    const total = (this.ys.at(-1) ?? 0) + (blocks.at(-1)?.h ?? 0);
    this.scrollMax = Math.max(0, total * scale - rect.h);
    this.scroll = Math.max(0, Math.min(this.scroll, this.scrollMax));
    this.y0 = rect.y - this.scroll;
    this.viewport = rect;
  }

  resetScroll(): void {
    this.scrollBy(-this.scroll);
    this.scroll = 0;
  }

  scrollBy(amount: number): boolean {
    if (!this.viewport) return false;
    const next = Math.max(0, Math.min(this.scrollMax, this.scroll + amount));
    if (next === this.scroll) return false;
    this.y0 -= next - this.scroll;
    this.scroll = next;
    return true;
  }

  /** 第 i 块在屏幕上的位置（逻辑像素）和整列的缩放 s */
  blockRect(i: number): { x: number; y: number; w: number; h: number; s: number } {
    return { x: this.x0, y: this.y0 + this.ys[i] * this.s, w: this.cw * this.s, h: this.blocks[i].h * this.s, s: this.s };
  }

  paint(ctx: Ctx): void {
    ctx.save();
    if (this.viewport) {
      const r = this.viewport;
      ctx.beginPath(); ctx.rect(r.x, r.y, r.w, r.h); ctx.clip();
    }
    ctx.translate(this.x0, this.y0);
    ctx.scale(this.s, this.s);
    this.blocks.forEach((b, i) => {
      ctx.save();
      ctx.translate(0, this.ys[i]);
      b.paint(ctx, this.cw);
      ctx.restore();
    });
    ctx.restore();
  }

  regions(z: number, panel: Panel, scrollId = 'menu-scroll'): void {
    let lastY = 0;
    const drag: Region['drag'] = {
      start: (_x, y) => { lastY = y; return true; },
      move: (_x, y) => { if (this.scrollBy(lastY - y)) panel.dirty = true; lastY = y; },
      end: () => false,
    };
    if (this.viewport) this.ov.region({ id: scrollId, z, ...this.viewport, drag, panel });
    this.blocks.forEach((b, i) => {
      for (const h of (typeof b.hits === 'function' ? b.hits() : b.hits) ?? []) {
        const local = (x: number, y: number) => [(x - this.x0) / this.s, (y - this.y0) / this.s - this.ys[i]] as const;
        const r: Region = {
          id: h.id,
          z,
          x: this.x0 + h.x * this.s,
          y: this.y0 + (this.ys[i] + h.y) * this.s,
          w: h.w * this.s,
          h: h.h * this.s,
          tap: h.tap,
          tapMs: h.tapMs,
          down: h.down,
          ready: h.ready,
          drag: h.drag ? {
            start: (x, y, id) => h.drag!.start(...local(x, y), id),
            move: (x, y, id) => h.drag!.move(...local(x, y), id),
            end: (x, y, id, cancelled) => h.drag!.end(...local(x, y), id, cancelled),
          } : this.viewport ? drag : undefined,
          panel,
        };
        if (this.viewport && (r.y < this.viewport.y - 0.5 || r.y + r.h > this.viewport.y + this.viewport.h + 0.5)) continue;
        this.ov.region(r);
      }
    });
  }
}

export type ButtonStyle = 'gold' | 'amber' | 'ghost' | 'outline' | 'warn' | 'chip' | 'chipOn';

/** 按钮共用机械键帽；主操作铜色，选中亮边，确认橙边。sub = 下面一行小字。 */
export function button(ctx: Ctx, x: number, y: number, w: number, h: number, style: ButtonStyle, label: string, opts: { size?: number; ls?: number; sub?: string; pressed?: boolean; r?: number } = {}): void {
  const size = opts.size ?? 15;
  const p = opts.pressed ? 1 : 0;
  let color = '#241a08';
  let subColor = '#5a2a08';
  if (UI_SKIN) {
    const main = style === 'gold' || style === 'amber';
    skinSurface(ctx, x, y + p * 2, w, h, main ? 'primary' : 'panel', !!p || style === 'chipOn' || style === 'outline');
    color = main ? UI_SKIN.colors.mainInk : UI_SKIN.colors.ink;
    subColor = main ? UI_SKIN.colors.mainInk : UI_SKIN.colors.dim;
    y += p * 2;
  } else {
    const main = style === 'gold' || style === 'amber';
    const on = style === 'chipOn' || style === 'outline';
    mechanicalKey(ctx, x, y, w, h, !!p, on, 4, main ? 'brass' : style === 'warn' ? 'warn' : undefined);
    color = p ? '#edcf8b' : main ? '#172326' : style === 'warn' ? '#ffb67e' : on ? '#edcf8b' : '#e2e5ce';
    subColor = main && !p ? '#4b4839' : '#c6c6a7';
    y += p * 2;
  }
  ctx.font = font(size, style.startsWith('chip') ? 700 : style === 'gold' ? 900 : 800);
  if (opts.sub) {
    text(ctx, label, x + w / 2, y + h / 2 - size * 0.42, color, 'center', opts.ls ?? 0);
    ctx.font = font(style === 'gold' ? 12 : 11, style === 'gold' ? 800 : 600);
    text(ctx, ellipsize(ctx, opts.sub, w - 16), x + w / 2, y + h / 2 + size * 0.62, subColor, 'center', 1);
  } else {
    text(ctx, label, x + w / 2, y + h / 2 + 0.5, color, 'center', opts.ls ?? 0);
  }
}

/** 说明气泡（槽位详情 / 终极说明）：标题 + 小字副标题 + 若干行 */
export interface TipLayout {
  w: number;
  h: number;
  title: string;
  sub: string;
  lines: string[];
}

export function layoutTip(ctx: Ctx, info: { title: string; sub: string; lines: string[] }, maxW: number): TipLayout {
  const inner = maxW - 22;
  ctx.font = font(12);
  const lines = info.lines.flatMap((l) => wrap(ctx, l, inner));
  let w = 0;
  for (const l of lines) w = Math.max(w, ctx.measureText(l).width);
  ctx.font = font(14, 700);
  w = Math.max(w, ctx.measureText(info.title).width);
  ctx.font = font(11);
  const sub = info.sub ? ellipsize(ctx, info.sub, inner) : '';
  w = Math.max(w, ctx.measureText(sub).width);
  const h = 9 + 21 + (sub ? 18 : 0) + lines.length * 18 + 9;
  return { w: Math.min(maxW, Math.ceil(w) + 22), h, title: info.title, sub, lines };
}

export function paintTip(ctx: Ctx, t: TipLayout): void {
  armorSurface(ctx, 0, 0, t.w, t.h);
  let y = 9 + 10.5;
  ctx.font = font(14, 700);
  text(ctx, t.title, 11, y, '#e2c790');
  y += 10.5;
  if (t.sub) {
    ctx.font = font(11);
    text(ctx, t.sub, 11, y + 9, '#a1b29b');
    y += 18;
  }
  ctx.font = font(12);
  for (const l of t.lines) {
    text(ctx, l, 11, y + 9, '#bac4b3');
    y += 18;
  }
}

export { fmtNum };

const ROW_H = 24;
const SEC_H = 18;
const KILL_H = 16;

/** 战报（战斗中的面板和结算页共用）：最多画到 maxH 高，返回实际高度 */
export function reportHeight(d: ReportData, maxH: number, killLimit = 99): number {
  return paintReport(null, d, 0, maxH, killLimit);
}

export function paintReport(ctx: Ctx | null, d: ReportData, w: number, maxH: number, killLimit = 99): number {
  if (d.players) {
    let y = 0;
    const share = maxH / d.players.length;
    for (const p of d.players) {
      if (ctx) {
        ctx.save(); ctx.translate(0, y);
        ctx.font = font(12, 700);
        text(ctx, `${p.name} · 输出 ${fmtNum(p.report.total)}`, 0, 12, '#ead8ac');
        ctx.translate(0, 25);
      }
      y += 25 + paintReport(ctx, p.report, w, Math.max(0, share - 25), killLimit);
      ctx?.restore();
    }
    return y;
  }
  let y = 0;
  const fits = (h: number) => y + h <= maxH;
  const sec = (label: string) => {
    if (!fits(SEC_H)) return false;
    if (ctx) {
      ctx.font = font(10);
      const tw = text(ctx, label, 0, y + 11, '#acb9a2', 'left', 2);
      ctx.fillStyle = '#73816940';
      ctx.fillRect(tw + 8, y + 11, Math.max(0, w - tw - 8), 1);
    }
    y += SEC_H;
    return true;
  };
  const max = Math.max(1, ...d.rows.map((r) => r.value));
  if (!sec(reportTitle(d))) return y;
  if (!d.rows.length) {
    if (ctx) {
      ctx.font = font(11);
      text(ctx, '还没有输出', 0, y + 8, '#e8e2d0');
    }
    y += KILL_H;
  }
  for (const r of d.rows) {
    if (!fits(ROW_H)) break;
    if (ctx) {
      const ind = r.sub ? 14 : 0;
      const nameColor = r.sub ? '#d7a977' : '#d4daca';
      if (r.icon) icon(ctx, r.icon, ind + 1, y + 2, 14, nameColor, 1.8);
      ctx.font = font(11, r.sub ? 600 : 700);
      const val = `${fmtNum(r.value)} · ${Math.round((r.value / Math.max(1, d.total)) * 100)}%`;
      const vw = measure(ctx, val);
      text(ctx, val, w, y + 9, r.sub ? '#d7a977' : '#e2c790', 'right');
      ctx.font = font(r.sub ? 10 : 11);
      text(ctx, ellipsize(ctx, r.label, w - vw - ind - 30), ind + 22, y + 9, nameColor);
      const bx = ind + 22;
      const fw = ((w - bx) * r.value) / max;
      if (UI_SKIN) {
        box(ctx, bx, y + 17, w - bx, 3, 1.5, 'rgba(255, 255, 255, 0.08)');
        if (fw > 0.5) box(ctx, bx, y + 17, fw, 3, 1.5, r.sub ? hgrad(ctx, bx, bx + fw, '#b8501e', '#ff9a4a') : hgrad(ctx, bx, bx + fw, '#c88a2a', '#ffcf6a'));
      } else armorMeter(ctx, bx, y + 17, w - bx, 3, r.value / max, r.sub ? '#bd8d5b' : '#c6b67e');
    }
    y += ROW_H;
  }
  // 「生存」一栏（T023-a）
  if (d.survive) {
    if (!sec('生存')) return y;
    for (const r of d.survive) {
      if (!fits(KILL_H)) break;
      if (ctx) {
        ctx.font = font(11);
        text(ctx, r.label, 0, y + 8, '#e8e2d0');
        ctx.font = font(11, 700);
        text(ctx, fmtNum(r.value), w, y + 8, '#b9ce96', 'right');
      }
      y += KILL_H;
    }
  }
  if (!sec('击毁敌军')) return y;
  const kills = d.kills.slice(0, killLimit);
  if (!kills.length) {
    if (fits(KILL_H) && ctx) {
      ctx.font = font(11);
      text(ctx, '还没有击毁', 0, y + 8, '#e8e2d0');
    }
    return y + (fits(KILL_H) ? KILL_H : 0);
  }
  for (const k of kills) {
    if (!fits(KILL_H)) break;
    if (ctx) {
      ctx.font = font(11);
      text(ctx, k.label, 0, y + 8, '#e8e2d0');
      ctx.font = font(11, 700);
      text(ctx, `×${k.n}`, w, y + 8, '#e4b27a', 'right');
    }
    y += KILL_H;
  }
  return y;
}

/** 浮层背景：半透明深色（开始界面另有暖色径向渐变） */
export function backdrop(ctx: Ctx, w: number, h: number, title = false, solid = false): void {
  if (skinBackdrop(ctx, w, h)) return;
  ctx.fillStyle = vgrad(ctx, 0, h, solid ? '#18231df5' : '#18231ded', solid ? '#0b1210fa' : '#0b1210e8');
  if (title) {
    ctx.fillStyle = 'rgba(8, 9, 12, 0.55)';
    ctx.fillRect(0, 0, w, h);
    const g = ctx.createRadialGradient(w / 2, h * 0.3, 0, w / 2, h * 0.3, Math.max(w, h) * 0.75);
    g.addColorStop(0, 'rgba(30, 26, 20, 0.35)');
    g.addColorStop(1, 'rgba(8, 9, 12, 0.9)');
    ctx.fillStyle = g;
  }
  ctx.fillRect(0, 0, w, h);
  if (!title) {
    ctx.fillStyle = '#72816c18';
    ctx.fillRect(12, 0, 1, h);
    ctx.fillRect(w - 13, 0, 1, h);
  }
}

/** 标题字（大字 + 字间距 + 投影） */
export function heading(ctx: Ctx, s: string, x: number, y: number, size: number, color: string, ls: number, weight = 700): void {
  ctx.font = font(size, weight);
  shadow(ctx, UI_SKIN?.light ? 'rgba(255,255,245,0.65)' : 'rgba(0,0,0,0.8)', UI_SKIN && !UI_SKIN.light ? 6 : 0, UI_SKIN?.light ? 1 : 2);
  text(ctx, s, x, y, color, 'center', ls);
  shadow(ctx, null);
  if (!UI_SKIN) {
    ctx.fillStyle = '#d8bc7c';
    for (let i = 0; i < 4; i++) ctx.fillRect(x - 14 + i * 8, y + size / 2 + 3, 6, 2);
  }
}
