export class Loop {
  private frameId = 0;
  private lastTime = 0;
  private running = false;
  /** 帧率上限（0 = 跟屏幕刷新）：高刷屏 / 低画质时跳过多余的帧；自动化测试（webdriver）不封顶，固定步长脚本照旧 */
  maxFps = 0;
  private readonly bot = typeof navigator !== 'undefined' && navigator.webdriver === true;

  constructor(
    private readonly update: (deltaSeconds: number, elapsedSeconds: number) => void,
    private readonly render: () => void,
  ) {}

  start(): void {
    if (this.running) return;
    this.running = true;
    this.lastTime = performance.now();
    this.frameId = requestAnimationFrame(this.tick);
  }

  stop(): void {
    this.running = false;
    cancelAnimationFrame(this.frameId);
  }

  private readonly tick = (time: number) => {
    if (!this.running) return;
    // 留 2 毫秒余量：60 Hz 屏封 60 帧不会误跳，120 Hz 屏封 60 帧隔一帧画一帧
    if (this.maxFps > 0 && !this.bot && time - this.lastTime < 1000 / this.maxFps - 2) {
      this.frameId = requestAnimationFrame(this.tick);
      return;
    }
    const deltaSeconds = Math.min(Math.max((time - this.lastTime) / 1000, 0), 0.05);
    this.lastTime = time;
    this.update(deltaSeconds, time / 1000);
    this.render();
    this.frameId = requestAnimationFrame(this.tick);
  };
}
