import * as THREE from 'three';
import { BRIDGE, RIVER_BED_GLSL, RIVER_BEND_GLSL, SURFACE_RING, riverBend } from './Rivers';

/** 同一时间最多几个实体弹坑（着色器里的 uniform 数组长度；T016-1 从 10 加到 24） */
export const MAX_CRATERS = 24;

/** 弹坑档位（T016-1）：1 小 / 2 中 / 3 大（首领被击毁、天火）/ 4 特大（核弹） */
export type CraterTier = 1 | 2 | 3 | 4;

/**
 * 小 / 中坑的尺寸（T017-6，制作人「老版本的弹坑大小、深度都是可以的」→ 恢复 T016-1 之前的公式；size = 爆炸半径，米）：
 * 坑口半径 r = size × 0.55、深 d = size × 0.14（单个坑最深 dMax）、坑沿 rim = size × 0.06、抛土外半径 out = size × 1.1（Game.dig）。
 * 首领被击毁 / 天火 / 核弹的大坑由调用方给参数（不变）
 */
export const CRATER_SIZE = { r: 0.55, d: 0.14, dMax: 1.4, rim: 0.06, out: 1.1 };

/** 载具吸收冲击：只留原坑口 35%、原深度 15% 的压痕，不起坑沿、不累加。 */
export const VEHICLE_DENT = { radius: 0.35, depth: 0.15 };

/**
 * 小 / 中坑反复炸的「下限」（T017-6，制作人「让坑不要越炸越高……让它在当前的平面上往下探」）：同一处反复炸坑底一直往下加深，
 * 但最深 floor 米、而且不超过坑口半径 × slope（坑壁不会陡成竖井，坦克开过去不至于一头扎进去）
 */
export const CRATER_TIER = {
  1: { floor: 1.8, slope: 0.42 },
  2: { floor: 2.6, slope: 0.42 },
} as const;

/**
 * 坑的去留（T016-1 + T017-6）：
 * - merge：新的小 / 中坑中心落在已有小 / 中坑坑口 ×1.2 以内就不新增，**累加到它身上、只往下**：坑底加深新坑深度 × acc（偏到坑口边上的减半），
 *   坑口按「两个圆的外接圆」往新坑那边扩一点（同心的也扩 grow 倍）、最大扩到第一次挖的坑口 × maxR；**坑沿不累加**（取两者里高的那个）；
 *   落进大坑 / 特大坑的小 / 中坑照常单独挖一个（坑底按 CRATER_GLSL 往下叠）
 *   （「以内」= 坑口 × merge 和「两个坑口之和 × overlap」取大的：T017-6 的坑比 T016-1 大，挨得近的并成一个，省池子）
 * - behind = 整个坑甩到身后这么多米（出了画面）才回收，不按时间消失；池子快满（只剩 reserve 个空位）时先回收镜头看不见的
 *   （整个在身后 hide.behind 米外，或者横向离镜头中线超过 hide.side + hide.k × 前方距离：两边田野里画面外的），
 *   还不够就把最老的小坑 flatT 秒压平成印记（贴花留着；刚被炸过的坑算新的）；中坑及以上在画面里永不压平
 */
const RULE = { merge: 1.2, overlap: 0.75, acc: 0.55, grow: 0.06, maxR: 1.6, behind: 40, reserve: 2, flatT: 0.8, hide: { behind: 24, side: 16, k: 0.2 } };

/** 几个坑的坑底叠在一起时，比最深的那个单坑最多再深多少米（渐近，GLSL 和 heightAt 同一个数） */
export const CRATER_STACK = 1.0;

/**
 * 弹坑的形状（GLSL，和 Craters.heightAt 同一个公式）：坑口半径按角度抖动（不规则），
 * 坑里是抛物面（中心深 d，到坑口升到坑沿 rim），坑沿外 rim → 0 平滑落到外半径 out。
 * 几个坑重叠（T017-6）：**坑底往下叠、坑沿不叠**——负的部分相加（比最深那个单坑多出来的按 CRATER_STACK 渐近封底），正的部分只取最高的；
 * 同一处反复炸只会越来越深，不会越来越高（T016-1 两边都取最值，坑落进坑里看不出来；T016-1 之前两边都相加，连炸 10 炮坑沿叠到 3 米高）
 */
/**
 * 河道截断（T025，策划 5.3 方案丙）：河道（水面 + 岸边 bank 米）和桥面（含两头坡道）里坑的高度 × 0 → 1 的过渡（再往外 fade 米过渡完），
 * 水面、桥面、桥头一点不动，两岸照常是坑（T034 起叠在岸坡上）。
 * 策划写的是「岸边 3 米 + 过渡 3 米」，实测核弹（坑口 16 米）落在河心时两岸只剩一道坑沿、几乎看不到坑，收成岸边 1 米 + 过渡 2.5 米
 */
export const RIVER_CUT = { bank: 1, fade: 2.5 };
/** 水面判定供贴花、火场和冲击环共用；只读现有三条河的数据，桥面不算水。 */
export const WATER_GLSL = /* glsl */ `
uniform vec4 uCrRv[3];
uniform vec4 uCrRk[3];
${RIVER_BEND_GLSL.replace('float riverBend(', 'float crRiverBend(')}
float waterH(vec2 p) {
  float h = -1000.0;
  for (int i = 0; i < 3; i++) {
    vec4 rv = uCrRv[i];
    if (rv.y <= 0.0 || abs(p.y - rv.x) > rv.y + 26.0) continue;
    vec4 rk = uCrRk[i];
    if (abs(p.y - rv.x - crRiverBend(p.x, rv.z, rv.w)) <= rv.y && !(rk.x > 0.0 && abs(p.x) < rk.x - ${(BRIDGE.halfW - BRIDGE.dry).toFixed(2)})) h = max(h, -rk.z);
  }
  return h;
}
`;
/**
 * 地面高度的几层（GLSL，T034）：uCrRv[i] = (河心 z, 半宽（0 = 没有这条河）, 弯曲相位, 振幅倍率)，uCrRk[i] = (桥面半宽（0 = 没桥）, 桥面半长, 水面低于地面, 河床最深)
 * - groundH = 弹坑 + 河道下沉（地面网格、弹坑网格、河道网格的顶点）
 * - floorH = groundH 和桥面取高的（贴花、弹匣环：东西「放」在上面的那一层）
 * - surfaceH = floorH 和水面取高的（冲击波环、预警圈、终极落点这些「浮」在最上面的）
 * CPU 版：World.groundAt / floorAt / surfaceAt
 */
export const CRATER_GLSL = /* glsl */ `
uniform vec4 uCrA[${MAX_CRATERS}];
uniform vec4 uCrB[${MAX_CRATERS}];
uniform int uCrN;
${WATER_GLSL}
${RIVER_BED_GLSL}
float craterRiverMask(vec2 p) {
  float m = 1.0;
  for (int i = 0; i < 3; i++) {
    vec4 rv = uCrRv[i];
    if (rv.y <= 0.0) continue;
    float d = abs(p.y - rv.x - crRiverBend(p.x, rv.z, rv.w)) - rv.y - ${RIVER_CUT.bank.toFixed(1)};
    vec4 rk = uCrRk[i];
    if (rk.x > 0.0) d = min(d, max(abs(p.x) - rk.x, abs(p.y - rv.x) - rk.y - ${BRIDGE.ramp.toFixed(1)}));
    m = min(m, smoothstep(0.0, ${RIVER_CUT.fade.toFixed(1)}, d));
  }
  return m;
}
float riverBedH(vec2 p) {
  float h = 0.0;
  for (int i = 0; i < 3; i++) {
    vec4 rv = uCrRv[i];
    if (rv.y <= 0.0 || abs(p.y - rv.x) > rv.y + 32.0) continue;
    vec4 rk = uCrRk[i];
    float dz = p.y - rv.x - crRiverBend(p.x, rv.z, rv.w);
    float T = riverBankW(p.x, dz < 0.0 ? -1.0 : 1.0, rv.z, rk.x > 0.0 ? 0.0 : 1.0);
    float d = abs(dz) - rv.y;
    if (d < T) h = min(h, riverProfile(d, T, rk.z, rk.w, riverUnder(rv.y, rk.z, rk.w)));
  }
  return h;
}
float deckH(vec2 p) {
  float h = -1000.0;
  for (int i = 0; i < 3; i++) {
    vec4 rk = uCrRk[i];
    if (rk.x <= 0.0 || abs(p.x) > rk.x) continue;
    float end = rk.y + ${BRIDGE.ramp.toFixed(1)};
    float dz = abs(p.y - uCrRv[i].x);
    if (dz < end) h = max(h, ${BRIDGE.deck.toFixed(2)} * min(1.0, (end - dz) / ${BRIDGE.ramp.toFixed(1)}));
  }
  return h;
}
float craterOne(vec2 p, int i, out float q, out float ang) {
  vec4 a = uCrA[i];
  vec4 b = uCrB[i];
  vec2 d = p - a.xy;
  float dist = length(d);
  q = 9.0;
  ang = 0.0;
  if (dist > b.y * 1.15) return 0.0;
  ang = atan(d.y, d.x);
  float wob = 1.0 + 0.07 * sin(3.0 * ang + b.z) + 0.05 * sin(7.0 * ang + b.z * 2.3) + 0.025 * sin(13.0 * ang + b.z * 3.7);
  float r = a.z * wob;
  q = dist / r;
  if (q < 1.0) return -a.w + (a.w + b.x) * q * q;
  float s = clamp((dist - r) / max(0.01, b.y * wob - r), 0.0, 1.0);
  return b.x * (1.0 - s * s * (3.0 - 2.0 * s));
}
float craterH(vec2 p) {
  float lo = 0.0;
  float sum = 0.0;
  float hi = 0.0;
  float q;
  float ang;
  for (int i = 0; i < ${MAX_CRATERS}; i++) {
    if (i >= uCrN) break;
    float v = craterOne(p, i, q, ang);
    lo = min(lo, v);
    sum += min(v, 0.0);
    hi = max(hi, v);
  }
  float h = lo - ${CRATER_STACK.toFixed(2)} * (1.0 - exp((sum - lo) / ${CRATER_STACK.toFixed(2)})) + hi;
  return h == 0.0 ? 0.0 : h * craterRiverMask(p);
}
float groundH(vec2 p) {
  return craterH(p) + riverBedH(p);
}
float floorH(vec2 p) {
  return max(groundH(p), deckH(p));
}
float surfaceH(vec2 p) {
  return max(floorH(p), waterH(p));
}
`;

/** 弹坑的 uniform（地面、贴花、冲击波环、预警圈共用同一份对象，坑一变全部跟着变）；uCrRv / uCrRk = 河（见 CRATER_GLSL） */
export type CraterUniforms = { uCrA: { value: THREE.Vector4[] }; uCrB: { value: THREE.Vector4[] }; uCrN: { value: number }; uCrRv: { value: THREE.Vector4[] }; uCrRk: { value: THREE.Vector4[] } };

/** 一份空的弹坑 uniform（还没接上地面的那份之前先用它，0 个坑） */
export function craterUniforms(): CraterUniforms {
  return {
    uCrA: { value: Array.from({ length: MAX_CRATERS }, () => new THREE.Vector4()) },
    uCrB: { value: Array.from({ length: MAX_CRATERS }, () => new THREE.Vector4()) },
    uCrN: { value: 0 },
    uCrRv: { value: [new THREE.Vector4(), new THREE.Vector4(), new THREE.Vector4()] },
    uCrRk: { value: [new THREE.Vector4(), new THREE.Vector4(), new THREE.Vector4()] },
  };
}

/**
 * 贴地的平面特效（冲击波环、预警圈、火场辉光）的顶点着色器：顶点贴着最上面那层（弹坑 / 河道下沉 / 桥面 / 水面取高的，surfaceH；网格要有足够的细分）；
 * uDrape = 0 时不贴（悬在半空的凝结环）。vP = 本地 xz（片元着色器按它画图案）
 */
export const DRAPE_VERT = /* glsl */ `
${CRATER_GLSL}
uniform float uDrape;
varying vec2 vP;
varying vec2 vWorldXZ;
void main() {
  vP = position.xz;
  vec4 w = modelMatrix * vec4(position, 1.0);
  vWorldXZ = w.xz;
  w.y += uDrape * surfaceH(w.xz);
  gl_Position = projectionMatrix * viewMatrix * w;
}`;

/** 河道截断 / 地面高度要的河（Rivers.River 的子集） */
export interface CraterRiver {
  z: number;
  half: number;
  phase: number;
  amp: number;
  deck: number;
  deckLen: number;
  water: number;
  bed: number;
}

export interface Crater {
  x: number;
  z: number;
  /** 坑口半径 / 中心深度 / 坑沿高度 / 外半径（坑沿抛土落到 0 的地方） */
  r: number;
  d: number;
  rim: number;
  out: number;
  /** 不规则形状的相位 */
  seed: number;
  /** 烧焦程度（0..1，核弹 1） */
  char: number;
  /** 档位（T016-1）：1 小 / 2 中 / 3 大 / 4 特大 */
  tier: CraterTier;
  /** 压平进度（0 = 正常；0..1 = 池子满了正在压平成印记，深度 / 坑沿 / 烧焦跟着 × (1 − flat)，到 1 回收） */
  flat: number;
  /** 挖出来的先后（池子满了压平最老的小坑） */
  serial: number;
  /** 这个坑配的弹坑贴花有多大（直径，米；坑加宽到比它大一截再补一块，Game.dig 用） */
  decal: number;
  /** 第一次挖的坑口半径（T017-6：反复炸最多扩到它 × RULE.maxR） */
  r0: number;
  /** 载具压痕与普通弹坑分开合并，重复命中不会越压越深。 */
  dent: boolean;
}

/** 挖坑的结果：c = 现在盖着这一点的坑（新挖的 / 落进去加深加宽的那个；null = 河道上或池子实在腾不出位置），gone = 这次被吃掉 / 腾掉的坑 */
export interface CraterAdd {
  c: Crater | null;
  gone: Crater[];
}

/**
 * 实体弹坑（T014-3）：地面真的往下陷。高度场 heightAt 给坦克 / 敌人 / 景物 / 碎屑共用（负高度）；
 * 画面上地面网格在坑里挖掉（Terrain 的片元 discard），坑本身用一个实例化的极坐标圆盘画（同一套地面着色器 + 顶点按 craterH 下陷），一次绘制画完所有坑；
 * 坑里烧焦变深、坑外一圈放射状抛土（Terrain 着色器里按坑的 uniform 画）
 */
export class Craters {
  /** 队友端只恢复地形显示，不执行爆炸、压平或伤害。 */
  networkApply(list: Crater[]): void {
    this.list.splice(0, this.list.length, ...list.slice(0, MAX_CRATERS).map(c => ({ ...c })));
    this.sync();
  }
  readonly list: Crater[] = [];
  /** 玩家最近一次的 z / x（回收 / 顶掉坑时判断哪些已经甩到身后、在画面外） */
  private pz = 0;
  private px = 0;
  private serial = 0;
  /** 河道截断（T025）用的河：和 uCrRv / uCrRk 同一份 */
  private rivers: CraterRiver[] = [];
  /** 实例化圆盘：每个坑一个实例（中心 + 圆盘半径）；换画质时整个换掉（setDetail），实例属性 inst 共用 */
  geometry: THREE.InstancedBufferGeometry;
  private readonly inst: THREE.InstancedBufferAttribute;
  private rings = 16;
  private seg = 56;

  /** uniforms = 着色器共用的那份（地面、坑、贴花、冲击波环、预警圈） */
  constructor(readonly uniforms: CraterUniforms = craterUniforms()) {
    this.inst = new THREE.InstancedBufferAttribute(new Float32Array(MAX_CRATERS * 3), 3);
    this.inst.setUsage(THREE.DynamicDrawUsage);
    this.geometry = this.disc(this.rings, this.seg);
  }

  /**
   * 圆盘网格的圈数 × 段数（T245：中 / 低档少画几圈几段，坑底每个顶点要算 5 次地面高度；坑的形状、heightAt 不变）。
   * 换了返回 true，调用方把网格的 geometry 换成 this.geometry
   */
  setDetail(rings: number, seg: number): boolean {
    if (rings === this.rings && seg === this.seg) return false;
    this.rings = rings;
    this.seg = seg;
    const old = this.geometry;
    this.geometry = this.disc(rings, seg);
    this.geometry.instanceCount = old.instanceCount;
    old.dispose();
    this.inst.needsUpdate = true;
    return true;
  }

  private disc(RINGS: number, SEG: number): THREE.InstancedBufferGeometry {
    // 极坐标网格：半径方向 RINGS 圈（靠中心密一点）、角度 SEG 段；外圈稍微外扩，盖住地面 discard 的圆（多边形内接会留缝；
    // 正好外切时每条边的中点和圆相切，浮点误差会漏出一串亮点，再多放 1%）
    const pos: number[] = [0, 0, 0];
    for (let i = 1; i <= RINGS; i++) {
      const k = i / RINGS;
      const r = (Math.pow(k, 1.25) * (i === RINGS ? 1.01 : 1)) / Math.cos(Math.PI / SEG);
      for (let j = 0; j < SEG; j++) {
        const a = (j / SEG) * Math.PI * 2;
        pos.push(Math.cos(a) * r, 0, Math.sin(a) * r);
      }
    }
    const idx: number[] = [];
    for (let j = 0; j < SEG; j++) idx.push(0, 1 + ((j + 1) % SEG), 1 + j);
    for (let i = 1; i < RINGS; i++) {
      const a0 = 1 + (i - 1) * SEG;
      const b0 = 1 + i * SEG;
      for (let j = 0; j < SEG; j++) {
        const j1 = (j + 1) % SEG;
        idx.push(a0 + j, a0 + j1, b0 + j, a0 + j1, b0 + j1, b0 + j);
      }
    }
    const g = new THREE.InstancedBufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    g.setAttribute('normal', new THREE.Float32BufferAttribute(new Array(pos.length).fill(0).map((_, i) => (i % 3 === 1 ? 1 : 0)), 3));
    g.setAttribute('uv', new THREE.Float32BufferAttribute(new Array((pos.length / 3) * 2).fill(0), 2));
    g.setIndex(idx);
    g.setAttribute('iCrater', this.inst);
    g.instanceCount = 0;
    return g;
  }

  /**
   * 挖一个坑（规则见 RULE）：
   * 1. 小 / 中坑落进已有的小 / 中坑（中心在坑口 ×1.2 以内）：不新增，累加到它身上——坑底往下加深、坑口往这边扩一点，坑沿不累加（T017-6）
   * 2. 大坑 / 特大坑把坑口里的小 / 中坑吃掉
   * 3. 快满时（只剩 reserve 个空位）：先回收镜头看不见的（hidden），还不够就把最老的小坑压平成印记；还是满的这一坑就不挖（调用方只留贴花）
   */
  add(x: number, z: number, r: number, d: number, rim: number, out: number, char = 0, tier: CraterTier = 3, dent = false): CraterAdd {
    const gone: Crater[] = [];
    if (dent) {
      for (const c of this.list) {
        if (Math.hypot(x - c.x, z - c.z) > c.r + r) continue;
        // 已有普通坑不再加深；浅压痕只取两次里较大的那次，不累积尺寸。
        if (c.dent) {
          c.r = Math.max(c.r, r);
          c.r0 = c.r;
          c.d = Math.max(c.d, d);
          c.out = Math.max(c.out, out);
          c.flat = 0;
          c.serial = ++this.serial;
          this.sync();
        }
        return { c, gone };
      }
    }
    if (tier <= 2) {
      for (const c of this.list) {
        const dist = Math.hypot(x - c.x, z - c.z);
        if (dent || c.dent || c.flat > 0 || c.tier > 2 || dist > Math.max(c.r * RULE.merge, (c.r + r) * RULE.overlap)) continue;
        this.stack(c, x, z, dist, r, d, rim, out, tier);
        return { c, gone };
      }
    }
    for (let i = this.list.length - 1; i >= 0; i--) {
      const c = this.list[i];
      if (!dent && ((tier >= 3 && c.tier < tier) || c.dent) && Math.hypot(c.x - x, c.z - z) < r) gone.push(...this.list.splice(i, 1));
    }
    if (this.list.length >= MAX_CRATERS - RULE.reserve) {
      // 快满了：镜头看不见的（身后 / 两边画面外）直接回收，最老的先
      const hid = this.list.filter((c) => this.hidden(c)).sort((a, b) => a.serial - b.serial);
      for (const c of hid.slice(0, this.list.length - (MAX_CRATERS - RULE.reserve) + 1)) gone.push(...this.list.splice(this.list.indexOf(c), 1));
    }
    if (this.list.length >= MAX_CRATERS - RULE.reserve) {
      // 快满了：最老的一个小坑开始压平成印记（贴花留着）
      let old: Crater | null = null;
      for (const c of this.list) if (c.tier === 1 && c.flat === 0 && (!old || c.serial < old.serial)) old = c;
      if (old) old.flat = 1e-3;
    }
    if (this.list.length >= MAX_CRATERS) {
      // 压平的还没压完（一下子落了一大片）：小 / 中坑这一坑先不挖、只留贴花，不把画面里的坑当帧弹平；
      // 首领被击毁 / 天火 / 核弹的大坑一定要挖：拿掉压得最平的（没有就最老的）一个小 / 中坑
      let f: Crater | null = null;
      if (tier >= 3) for (const c of this.list) if (c.tier <= 2 && (!f || c.flat > f.flat || (c.flat === f.flat && c.serial < f.serial))) f = c;
      if (!f) {
        this.sync();
        return { c: null, gone };
      }
      gone.push(...this.list.splice(this.list.indexOf(f), 1));
    }
    const c: Crater = { x, z, r, d, rim, out, seed: Math.random() * 6.28, char, tier, flat: 0, serial: ++this.serial, decal: 0, r0: r, dent };
    this.list.push(c);
    this.sync();
    return { c, gone };
  }

  /**
   * 小 / 中坑落进已有的小 / 中坑（T017-6「往下探」）：坑底加深 d × acc（偏到坑口边上的减半），到 CRATER_TIER 的下限为止；
   * 坑口扩成两个圆的外接圆（中心往新坑那边挪），同心的也扩一点，最多扩到第一次的 maxR 倍；坑沿只取高的、不累加；刚被炸过算新坑（不先被压平）
   */
  private stack(c: Crater, x: number, z: number, dist: number, r: number, d: number, rim: number, out: number, tier: CraterTier): void {
    c.tier = Math.max(c.tier, tier) as CraterTier;
    c.r0 = Math.max(c.r0, r);
    const enc = dist + r > c.r ? (c.r + dist + r) / 2 : c.r;
    const R = Math.min(c.r0 * RULE.maxR, Math.max(enc, c.r + r * RULE.grow, c.r));
    const shift = Math.min(dist, Math.max(0, Math.min(R, enc) - c.r));
    if (dist > 1e-3 && shift > 0) {
      c.x += ((x - c.x) / dist) * shift;
      c.z += ((z - c.z) / dist) * shift;
    }
    const w = 1 - 0.5 * Math.min(1, dist / (c.r * RULE.merge));
    c.r = R;
    const T = CRATER_TIER[c.tier as 1 | 2];
    c.d = Math.max(c.d, Math.min(T.floor, R * T.slope, c.d + d * RULE.acc * w));
    c.rim = Math.max(c.rim, rim);
    c.out = Math.max(c.out, R * (out / r));
    c.serial = ++this.serial;
    this.sync();
  }

  /** 镜头看不见这个坑（T017-6）：整个在身后 hide.behind 米外，或者横向离镜头中线（镜头跟着坦克 x 的 55%）超过 hide.side + hide.k × 前方距离 */
  hidden(c: Crater): boolean {
    const R = c.out * 1.15;
    const H = RULE.hide;
    if (c.z - R > this.pz + H.behind) return true;
    return Math.abs(c.x - this.px * 0.55) - R > H.side + H.k * Math.max(0, this.pz - c.z);
  }

  /**
   * 压平中的坑往下压、压完回收；整个甩到身后 RULE.behind 米外的坑回收。返回这一帧形状变了 / 被回收的坑（调用方把那里的景物贴回地面）。
   * rear = 回收 / 判「镜头看不见」按的位置（T107 停车攻坚时是能退到的最远处：往前挪了再退回来，身后的坑还在；平时就是玩家）
   */
  update(playerZ: number, delta = 0, playerX = this.px, rear = playerZ): Crater[] {
    this.pz = rear;
    this.px = playerX;
    const changed: Crater[] = [];
    for (let i = this.list.length - 1; i >= 0; i--) {
      const c = this.list[i];
      if (c.flat > 0) {
        c.flat = Math.min(1, c.flat + delta / RULE.flatT);
        changed.push(c);
        if (c.flat >= 1) this.list.splice(i, 1);
      } else if (c.z - c.out * 1.15 > rear + RULE.behind) {
        this.list.splice(i, 1);
        changed.push(c);
      }
    }
    if (changed.length) this.sync();
    return changed;
  }

  clear(): void {
    this.list.length = 0;
    this.sync();
  }

  /** 河道截断（T025）+ 河道下沉 / 桥面 / 水面（T034）：每帧由 Rivers 经 Terrain.setRivers 送进来 */
  setRivers(list: readonly CraterRiver[]): void {
    const v = this.uniforms.uCrRv.value;
    const k = this.uniforms.uCrRk.value;
    this.rivers = list.slice(0, 3);
    for (let i = 0; i < 3; i++) {
      const r = this.rivers[i];
      if (r) {
        v[i].set(r.z, r.half, r.phase, r.amp);
        k[i].set(r.deck, r.deckLen, r.water, r.bed);
      } else {
        v[i].set(0, 0, 0, 0);
        k[i].set(0, 0, 0, 0);
      }
    }
  }

  /** 河道截断的系数（0 = 河道 / 桥面里坑不陷不鼓，1 = 岸外 3.5 米起照常），和 CRATER_GLSL 的 craterRiverMask 同一个公式 */
  riverMask(x: number, z: number): number {
    let m = 1;
    for (const r of this.rivers) {
      let d = Math.abs(z - r.z - riverBend(x, r.phase, r.amp)) - (r.half + RIVER_CUT.bank);
      if (r.deck > 0) d = Math.min(d, Math.max(Math.abs(x) - r.deck, Math.abs(z - r.z) - r.deckLen - BRIDGE.ramp));
      const t = Math.min(1, Math.max(0, d / RIVER_CUT.fade));
      m = Math.min(m, t * t * (3 - 2 * t));
    }
    return m;
  }

  /** 完全被水面 / 桥面掩膜遮住的坑不占池子；跨岸的仍交给原高度场逐点裁切。 */
  canDig(x: number, z: number, radius: number): boolean {
    if (this.riverMask(x, z) > 0) return true;
    for (const [dx, dz] of SURFACE_RING) if (this.riverMask(x + dx * radius, z + dz * radius) > 0) return true;
    return false;
  }

  private sync(): void {
    const A = this.uniforms.uCrA.value;
    const B = this.uniforms.uCrB.value;
    const arr = this.inst.array as Float32Array;
    this.list.forEach((c, i) => {
      const k = 1 - c.flat;
      A[i].set(c.x, c.z, c.r, c.d * k);
      B[i].set(c.rim * k, c.out, c.seed, c.char * k);
      arr[i * 3] = c.x;
      arr[i * 3 + 1] = c.z;
      arr[i * 3 + 2] = c.out * 1.15;
    });
    this.uniforms.uCrN.value = this.list.length;
    this.geometry.instanceCount = this.list.length;
    this.inst.needsUpdate = true;
  }

  /** (x, z) 处被弹坑改变的地面高度（坑里是负的，坑沿是正的），和 CRATER_GLSL 同一个公式：坑底往下叠（渐近封底）+ 最高的坑沿（不叠） */
  heightAt(x: number, z: number): number {
    let lo = 0;
    let sum = 0;
    let hi = 0;
    for (const c of this.list) {
      const dx = x - c.x;
      const dz = z - c.z;
      const dist = Math.hypot(dx, dz);
      if (dist > c.out * 1.15) continue;
      const ang = Math.atan2(dz, dx);
      const wob = 1 + 0.07 * Math.sin(3 * ang + c.seed) + 0.05 * Math.sin(7 * ang + c.seed * 2.3) + 0.025 * Math.sin(13 * ang + c.seed * 3.7);
      const r = c.r * wob;
      const q = dist / r;
      const k = 1 - c.flat;
      const d = c.d * k;
      const rim = c.rim * k;
      let v: number;
      if (q < 1) v = -d + (d + rim) * q * q;
      else {
        const s = Math.min(1, Math.max(0, (dist - r) / Math.max(0.01, c.out * wob - r)));
        v = rim * (1 - s * s * (3 - 2 * s));
      }
      lo = Math.min(lo, v);
      sum += Math.min(v, 0);
      hi = Math.max(hi, v);
    }
    const h = lo - CRATER_STACK * (1 - Math.exp((sum - lo) / CRATER_STACK)) + hi;
    return h === 0 || !this.rivers.length ? h : h * this.riverMask(x, z);
  }

  /** (x, z) 在不在某个坑的范围里（外半径内） */
  near(x: number, z: number, pad = 0): boolean {
    for (const c of this.list) if (Math.hypot(x - c.x, z - c.z) < c.out * 1.15 + pad) return true;
    return false;
  }
}
