/**
 * 启动（T108）：计时标记 + 加载页进度。
 * 小游戏：game.js 一启动就画加载页（loader.js），建好 __TANK_BOOT__ / __TANK_LOADER__，游戏包接着往上报进度。
 * 网页：index.html 的 #boot 和内联脚本建好 __TANK_BOOT__，这里接上进度条。
 * 进度按任务数走：每一步开始前报「第几步 / 共几步 + 在干什么」，空出一帧（加载页画出来）再干活。
 */

/** 标记：[名字, 毫秒]；网页从开始导航算，小游戏从 game.js 开始执行算 */
export type BootMark = [string, number];
interface BootRecord {
  marks: BootMark[];
  /** 最近一次进度变化（毫秒，同一时间轴）：网页内联脚本拿它判断卡住没有 */
  last?: number;
  /** 游戏包之前的步数（小游戏 game.js 自己那几步） */
  pre?: number;
}
/** 加载页：done / total = 已完成步数 / 总步数，part = 当前这一步做了几成（下载按字节） */
export interface Loader {
  step(done: number, total: number, label: string, part?: number): void;
  finish(): void;
  /** 启动出错：加载页停在这一步，提示重开 */
  fail?(text: string): void;
}
export interface BootTask {
  label: string;
  /** 计时标记名 */
  mark: string;
  run: () => void | Promise<void>;
}

const g = globalThis as {
  __TANK_BOOT__?: BootRecord;
  __TANK_LOADER__?: Loader;
  __TANK_BOOT_HOLD__?: (done: number, total: number) => boolean;
  requestAnimationFrame?: (cb: (t: number) => void) => number;
};
const now = () => (typeof performance !== 'undefined' && performance.now ? performance.now() : Date.now());
export const boot: BootRecord = (g.__TANK_BOOT__ ??= { marks: [] });

export function bootMark(name: string): void {
  boot.marks.push([name, Math.round(now())]);
}

/** 空出一帧：加载页趁这一帧画出来 */
export function nextFrame(): Promise<void> {
  return new Promise((resolve) => {
    const raf = g.requestAnimationFrame;
    if (raf) raf(() => resolve());
    else setTimeout(resolve, 16);
  });
}

/** 网页的加载页：index.html 里的 #boot */
function domLoader(): Loader | null {
  if (typeof document === 'undefined' || typeof document.getElementById !== 'function') return null;
  const el = document.getElementById('boot');
  if (!el) return null;
  const fill = el.querySelector<HTMLElement>('.boot-fill');
  const label = el.querySelector<HTMLElement>('.boot-label');
  const pct = el.querySelector<HTMLElement>('.boot-pct');
  let shown = 0;
  return {
    step(done, total, text, part = 0) {
      const k = Math.max(shown, Math.min(1, (done + part) / Math.max(1, total)));
      shown = k;
      if (fill) fill.style.transform = `scaleX(${k})`;
      if (pct) pct.textContent = `${Math.floor(k * 100)}%`;
      if (label) label.textContent = text;
      el.setAttribute('aria-valuenow', String(Math.floor(k * 100)));
      boot.last = now();
    },
    finish() {
      el.classList.add('boot-done');
      setTimeout(() => el.remove(), 360);
    },
    fail(text) {
      el.classList.add('boot-fail');
      if (label) label.textContent = text;
    },
  };
}

/** 加载页：小游戏 game.js 给的、网页 #boot，都没有（测试页 / 单独打开）就不画 */
export function getLoader(): Loader {
  return g.__TANK_LOADER__ ?? domLoader() ?? { step() {}, finish() {} };
}

/**
 * 按顺序跑完启动任务：每一步先报进度、空出一帧（加载页画上这一步的名字），再干活；
 * beforeEach = 每一步干活前（小游戏加载页直接用 WebGL 画，three.js 要重置状态缓存）
 */
export async function runBoot(loader: Loader, tasks: BootTask[], beforeEach?: () => void): Promise<void> {
  const pre = boot.pre ?? 0;
  const total = pre + tasks.length;
  for (let i = 0; i < tasks.length; i++) {
    loader.step(pre + i, total, tasks[i].label);
    await nextFrame();
    // 截图脚本（scripts/bootshots.mjs）停在某一步拍加载页；平时没有这个钩子
    while (g.__TANK_BOOT_HOLD__?.(pre + i, total)) await nextFrame();
    beforeEach?.();
    await tasks[i].run();
    bootMark(tasks[i].mark);
  }
  loader.step(total, total, tasks[tasks.length - 1]?.label ?? '');
}
