import * as THREE from 'three';
import type { GeoCache, PartSpec } from '../GeoCache';
import { chamfer, crate, drum, frustum, rect, rockify, wheel } from '../ModelKit';
import { CRUSH_PART as C, markCrush } from './crush';
import { HAY_BALES } from './hay';
import { richBush, richFarmHouse, richHedge, richPine, richRuin, richWall, type PineState } from './sceneryRich';
import { SCN_DETAIL, SCN_RICH } from '../../world/sceneryDetail';
import type { PropKind, SceneryId } from '../../world/themes';

/** 路边景物与可碾压物件的几何体（顶点色合并，一种一个 draw call） */

const r = (a: number, b: number, s: number) => {
  const h = Math.sin(s * 91.7) * 43758.5453;
  return a + (h - Math.floor(h)) * (b - a);
};

/** T184 加细档换模型的景物（建筑 / 树木 / 草丛）；草垛、原木、石头等不动 */
const RICH: Partial<Record<Exclude<SceneryId, 'crater'>, () => PartSpec[]>> = {
  pine: () => richPine('pine'), bush: richBush, hedge: richHedge, house: richFarmHouse, ruin: richRuin, wall: richWall,
};

export function sceneryGeo(geo: GeoCache, id: Exclude<SceneryId, 'crater'>): THREE.BufferGeometry {
  const rich = SCN_RICH ? RICH[id] : undefined;
  if (rich) return geo.merged(`scenery-${id}-x${SCN_DETAIL}`, rich);
  return geo.merged(`scenery-${id}`, () => {
    switch (id) {
      case 'rock':
        return [{ geo: rockify(new THREE.IcosahedronGeometry(1, 1), 0.55, 3), color: 0x7a7266, pos: [0, 0.35, 0] }];
      case 'boulder':
        return [
          { geo: rockify(new THREE.DodecahedronGeometry(2.2, 1), 0.45, 7), color: 0x6e675c, pos: [0, 0.9, 0] },
          { geo: rockify(new THREE.IcosahedronGeometry(1.1, 1), 0.5, 9), color: 0x7d7569, pos: [1.9, 0.4, 0.8] },
        ];
      case 'pole':
        return [
          { geo: new THREE.CylinderGeometry(0.14, 0.2, 9.5, 7), color: 0x5a4632, pos: [0, 4.75, 0] },
          { geo: new THREE.BoxGeometry(2.6, 0.16, 0.16), color: 0x4e3d2b, pos: [0, 8.6, 0] },
          ...[-1.1, -0.4, 0.4, 1.1].map((x): PartSpec => ({ geo: new THREE.CylinderGeometry(0.07, 0.09, 0.3, 6), color: 0x5f8a7a, pos: [x, 8.85, 0] })),
        ];
      case 'trap': {
        // 捷克刺猬：三根角钢交叉
        const beam = () => new THREE.BoxGeometry(0.28, 0.28, 3.0);
        return [
          { geo: beam(), color: 0x4a3f36, pos: [0, 0.95, 0], rot: [0.62, 0, 0] },
          { geo: beam(), color: 0x433931, pos: [0, 0.95, 0], rot: [-0.62, Math.PI / 2, 0] },
          { geo: beam(), color: 0x50443a, pos: [0, 0.95, 0], rot: [Math.PI / 2, 0.7, 0] },
        ];
      }
      case 'pine':
        return [
          { geo: new THREE.CylinderGeometry(0.2, 0.32, 2.4, 7), color: 0x4a3a2a, pos: [0, 1.2, 0] },
          { geo: rockify(new THREE.ConeGeometry(2.2, 3.2, 8), 0.12, 1), color: 0x2f4027, pos: [0, 3.4, 0] },
          { geo: rockify(new THREE.ConeGeometry(1.7, 2.8, 8), 0.12, 2), color: 0x34482b, pos: [0, 5.0, 0] },
          { geo: rockify(new THREE.ConeGeometry(1.1, 2.3, 7), 0.12, 3), color: 0x3a5030, pos: [0, 6.4, 0] },
        ];
      case 'bush':
        return [
          { geo: rockify(new THREE.IcosahedronGeometry(1.1, 0), 0.3, 4), color: 0x46572e, pos: [0, 0.7, 0] },
          { geo: rockify(new THREE.IcosahedronGeometry(0.85, 0), 0.3, 5), color: 0x50633a, pos: [0.9, 0.55, 0.3] },
          { geo: rockify(new THREE.IcosahedronGeometry(0.75, 0), 0.3, 6), color: 0x3f5029, pos: [-0.7, 0.5, -0.4] },
        ];
      case 'house': {
        // 农舍：白墙、木门窗、坡屋顶、烟囱
        const parts: PartSpec[] = [
          { geo: new THREE.BoxGeometry(7, 3.6, 5.6), color: 0xcfc6b2, pos: [0, 1.8, 0] },
          { geo: new THREE.BoxGeometry(7.2, 0.4, 5.8), color: 0x6a5e4c, pos: [0, 0.2, 0] },
          { geo: frustum(rect(7.6, 6.2), rect(7.6, 0.3), 2.4, 3.6), color: 0x7a3b2c },
          { geo: new THREE.BoxGeometry(0.7, 2.2, 0.7), color: 0x8a7b68, pos: [2.2, 5.2, 0.8] },
          { geo: new THREE.BoxGeometry(1.1, 2.0, 0.1), color: 0x4a3626, pos: [0, 1.0, 2.82] },
        ];
        for (const x of [-2.4, 2.4]) parts.push({ geo: new THREE.BoxGeometry(1.1, 1.0, 0.1), color: 0x2e3438, pos: [x, 2.1, 2.82] });
        for (const z of [-1.4, 1.4]) parts.push({ geo: new THREE.BoxGeometry(0.1, 1.0, 1.0), color: 0x2e3438, pos: [3.52, 2.1, z] });
        return parts;
      }
      case 'ruin': {
        // 被炸塌的砖楼：残墙高低不齐、无顶、焦黑
        const parts: PartSpec[] = [{ geo: new THREE.BoxGeometry(8, 0.5, 7), color: 0x5a524a, pos: [0, 0.25, 0] }];
        const brick = [0x8a5440, 0x7a4a38, 0x6a4234];
        for (let i = 0; i < 6; i++) {
          const h = r(2.5, 7.5, i + 1);
          parts.push({ geo: new THREE.BoxGeometry(1.4, h, 0.6), color: brick[i % 3], pos: [-3.3 + i * 1.32, h / 2, 3.2], crush: C.masonry });
        }
        for (let i = 0; i < 5; i++) {
          const h = r(1.5, 6.5, i + 11);
          parts.push({ geo: new THREE.BoxGeometry(0.6, h, 1.4), color: brick[(i + 1) % 3], pos: [-3.7, h / 2, 2.5 - i * 1.4], crush: C.masonry });
        }
        for (let i = 0; i < 3; i++) parts.push({ geo: new THREE.BoxGeometry(0.9, 1.2, 0.08), color: 0x1e1a18, pos: [-2.4 + i * 2.2, r(3, 5, i + 21), 3.52], crush: C.glass });
        for (let i = 0; i < 7; i++) {
          parts.push({ geo: rockify(new THREE.BoxGeometry(1.2, 0.7, 1.0), 0.3, i), color: 0x6e5a4a, pos: [r(-3, 3, i + 31), 0.5, r(-2.5, 2, i + 41)], rot: [r(0, 1, i), r(0, 3, i + 5), 0] });
        }
        return parts;
      }
      case 'wall': {
        const parts: PartSpec[] = [];
        for (let i = 0; i < 5; i++) {
          const h = r(1.2, 3.6, i + 3);
          parts.push({ geo: new THREE.BoxGeometry(1.25, h, 0.5), color: i % 2 ? 0x84503e : 0x7a4a3a, pos: [-2.5 + i * 1.24, h / 2, 0], crush: C.masonry });
        }
        for (let i = 0; i < 4; i++) parts.push({ geo: new THREE.BoxGeometry(0.5, 0.25, 0.3), color: 0x8a5a44, pos: [r(-2.5, 2.5, i + 9), 0.15, r(0.5, 1.4, i + 13)], rot: [0, r(0, 3, i), 0] });
        return parts;
      }
      case 'hulk':
        return [
          { geo: new THREE.BoxGeometry(2.0, 0.7, 4.3), color: 0x3a2e26, pos: [0, 0.55, 0], rot: [0, 0, 0.08], crush: C.skin },
          { geo: frustum(rect(1.7, 2.1), rect(1.4, 1.4), 0.6, 0.9), color: 0x2a221e, crush: C.roof },
          { geo: new THREE.BoxGeometry(2.04, 0.12, 4.34), color: 0x6a3a22, pos: [0, 0.3, 0], crush: C.frame },
        ];
      case 'sandbag': {
        const parts: PartSpec[] = [];
        for (let row = 0; row < 2; row++) {
          for (let i = 0; i < 6; i++) {
            const a = (i / 5 - 0.5) * 1.6;
            parts.push({ geo: new THREE.SphereGeometry(0.5, 6, 4), color: row ? 0x9a8a62 : 0x8a7b56, pos: [Math.sin(a) * 3, 0.32 + row * 0.5, Math.cos(a) * 3 - 3], scale: [1.4, 0.55, 0.8], rot: [0, a, 0], crush: C.sack });
          }
        }
        return parts;
      }
      case 'hedge': {
        // 诺曼底式灌木篱墙的一段（4 米）：原来 12 米一整条，T009 拆成 3 段，每段单独破坏
        const parts: PartSpec[] = [];
        for (let i = 0; i < 2; i++) {
          parts.push({ geo: rockify(new THREE.IcosahedronGeometry(1.1, 0), 0.3, i + 31), color: [0x3e4e28, 0x46582e][i], pos: [-1 + i * 2, 0.9 + r(-0.2, 0.3, i + 3), r(-0.3, 0.3, i + 7)], scale: [1.3, r(0.9, 1.3, i + 11), 1.0] });
        }
        parts.push({ geo: new THREE.BoxGeometry(4.1, 0.5, 1.6), color: 0x4a3e2a, pos: [0, 0.2, 0] });
        return parts;
      }
      case 'log':
        return [
          { geo: new THREE.CylinderGeometry(0.42, 0.5, 6.0, 9), color: 0x5a4632, pos: [0, 0.45, 0], rot: [0, 0, Math.PI / 2] },
          { geo: new THREE.CylinderGeometry(0.44, 0.44, 0.06, 9), color: 0x9a7e56, pos: [3.02, 0.45, 0], rot: [0, 0, Math.PI / 2] },
          { geo: new THREE.CylinderGeometry(0.08, 0.12, 1.6, 5), color: 0x4a3a2a, pos: [-1.2, 0.9, 0.4], rot: [0.6, 0, 0.3] },
          { geo: new THREE.CylinderGeometry(0.06, 0.1, 1.2, 5), color: 0x4a3a2a, pos: [1.0, 0.85, -0.4], rot: [-0.7, 0, -0.2] },
          { geo: rockify(new THREE.IcosahedronGeometry(0.6, 1), 0.4, 5), color: 0x3a4a26, pos: [-2.8, 0.6, 0.2] },
        ];
      case 'hay':
        return HAY_BALES.map(b => ({
          geo: new THREE.CylinderGeometry(.95, .95, 1.5, 12), color: b.color,
          pos: [b.x, .95, b.z], rot: [0, b.yaw, Math.PI / 2], crush: C.straw,
        }));
    }
  });
}

/** 景物的破坏变体（T009 4.4）：出现时每种 +1 次绘制、不投影；一种变体会被几种武器复用（颜色靠实例色区分） */
export type SceneryVariant =
  | 'pineStump' | 'pineTop' | 'pineRoot' | 'pineBald'
  | 'poleStump' | 'poleTop'
  | 'houseHalf' | 'houseShell' | 'houseRubble'
  | 'brickStrip' | 'boulderHalf';

/** 树 / 电线杆打断、切断的高度（缩放 1 时）：打断和切断共用一对「桩 + 上半截」 */
export const CUT_HEIGHT = 1.0;

/** 房屋的窗户（局部坐标 + 朝向）：机枪每扇只碎一次，特斯拉闪蓝光，燃烧时往外冒火 */
export const HOUSE_WINDOWS: [number, number, number, number, number][] = [
  [-2.4, 2.1, 2.86, 0, 1],
  [2.4, 2.1, 2.86, 0, 1],
  [3.56, 2.1, -1.4, 1, 0],
  [3.56, 2.1, 1.4, 1, 0],
];

export function sceneryVariantGeo(geo: GeoCache, id: SceneryVariant): THREE.BufferGeometry {
  if (SCN_RICH && id.startsWith('pine')) return geo.merged(`scn-${id}-x${SCN_DETAIL}`, () => richPine(id as PineState));
  return geo.merged(`scn-${id}`, () => {
    const splinters = (y: number, rad: number, seed: number, color = 0x9a7e56): PartSpec[] =>
      Array.from({ length: 4 }, (_, i) => {
        const a = (i / 4) * Math.PI * 2 + r(0, 1, seed + i);
        return { geo: new THREE.BoxGeometry(0.09, r(0.18, 0.42, seed + i + 9), 0.07), color, pos: [Math.cos(a) * rad * 0.7, y, Math.sin(a) * rad * 0.7], rot: [r(-0.3, 0.3, seed + i + 3), a, r(-0.3, 0.3, seed + i + 5)] };
      });
    switch (id) {
      case 'pineStump':
        return [
          { geo: new THREE.CylinderGeometry(0.27, 0.34, CUT_HEIGHT, 7), color: 0x4a3a2a, pos: [0, CUT_HEIGHT / 2, 0] },
          { geo: new THREE.CylinderGeometry(0.255, 0.255, 0.04, 7), color: 0x9a7e56, pos: [0, CUT_HEIGHT, 0] },
          ...splinters(CUT_HEIGHT + 0.12, 0.27, 3),
          ...[0, 2.1, 4.2].map((a, i): PartSpec => ({ geo: new THREE.CylinderGeometry(0.05, 0.12, 0.9, 5), color: 0x463626, pos: [Math.cos(a) * 0.35, 0.08, Math.sin(a) * 0.35], rot: [Math.sin(a) * 1.3, 0, -Math.cos(a) * 1.3 + r(-0.2, 0.2, i)] })),
        ];
      case 'pineTop':
        // 上半截：原点在断口（y = 0），沿 +y 长上去
        return [
          { geo: new THREE.CylinderGeometry(0.2, 0.265, 1.4, 7), color: 0x4a3a2a, pos: [0, 0.7, 0] },
          { geo: rockify(new THREE.ConeGeometry(2.2, 3.2, 8), 0.12, 1), color: 0x2f4027, pos: [0, 2.4, 0] },
          { geo: rockify(new THREE.ConeGeometry(1.7, 2.8, 8), 0.12, 2), color: 0x34482b, pos: [0, 4.0, 0] },
          { geo: rockify(new THREE.ConeGeometry(1.1, 2.3, 7), 0.12, 3), color: 0x3a5030, pos: [0, 5.4, 0] },
          ...splinters(-0.1, 0.26, 7),
        ];
      case 'pineRoot':
        // 连根拔起的整棵：树根带着一大块土盘
        return [
          { geo: new THREE.CylinderGeometry(0.2, 0.32, 2.4, 7), color: 0x4a3a2a, pos: [0, 1.2, 0] },
          { geo: rockify(new THREE.ConeGeometry(2.2, 3.2, 8), 0.12, 1), color: 0x2f4027, pos: [0, 3.4, 0] },
          { geo: rockify(new THREE.ConeGeometry(1.7, 2.8, 8), 0.12, 2), color: 0x34482b, pos: [0, 5.0, 0] },
          { geo: rockify(new THREE.ConeGeometry(1.1, 2.3, 7), 0.12, 3), color: 0x3a5030, pos: [0, 6.4, 0] },
          { geo: rockify(new THREE.DodecahedronGeometry(1.15, 0), 0.35, 5), color: 0x4e3e2c, pos: [0, -0.05, 0], scale: [1, 0.38, 1] },
          ...[0, 1.3, 2.6, 3.9, 5.2].map((a, i): PartSpec => ({ geo: new THREE.CylinderGeometry(0.04, 0.1, 1.1, 5), color: 0x3e3024, pos: [Math.cos(a) * 0.7, -0.25, Math.sin(a) * 0.7], rot: [Math.sin(a) * 1.1, 0, -Math.cos(a) * 1.1 + r(-0.3, 0.3, i + 2)] })),
        ];
      case 'pineBald': {
        // 秃干：针叶没了，只剩树干和几根光秃的枝杈（火烧后实例色调暗成焦黑，削顶后是棕色）
        const parts: PartSpec[] = [
          { geo: new THREE.CylinderGeometry(0.2, 0.32, 2.4, 7), color: 0x5a4a3a, pos: [0, 1.2, 0] },
          { geo: new THREE.CylinderGeometry(0.05, 0.2, 4.2, 6), color: 0x544434, pos: [0, 4.5, 0] },
        ];
        for (let i = 0; i < 7; i++) {
          const a = i * 2.3;
          const y = 2.6 + i * 0.55;
          const len = r(0.6, 1.3, i + 41) * (1 - i * 0.08);
          parts.push({ geo: new THREE.CylinderGeometry(0.02, 0.05, len, 4), color: 0x4e3e30, pos: [Math.cos(a) * len * 0.45, y + 0.15, Math.sin(a) * len * 0.45], rot: [Math.sin(a) * 1.1, 0, -Math.cos(a) * 1.1] });
        }
        return parts;
      }
      case 'poleStump':
        return [
          { geo: new THREE.CylinderGeometry(0.185, 0.2, CUT_HEIGHT, 7), color: 0x5a4632, pos: [0, CUT_HEIGHT / 2, 0] },
          ...splinters(CUT_HEIGHT + 0.1, 0.18, 13),
        ];
      case 'poleTop':
        return [
          { geo: new THREE.CylinderGeometry(0.14, 0.185, 8.5, 7), color: 0x5a4632, pos: [0, 4.25, 0] },
          { geo: new THREE.BoxGeometry(2.6, 0.16, 0.16), color: 0x4e3d2b, pos: [0, 7.6, 0] },
          ...[-1.1, -0.4, 0.4, 1.1].map((x): PartSpec => ({ geo: new THREE.CylinderGeometry(0.07, 0.09, 0.3, 6), color: 0x5f8a7a, pos: [x, 7.85, 0] })),
          ...splinters(-0.1, 0.18, 17, 0x8a6e4a),
        ];
      case 'houseHalf': {
        // 半塌：-x 一端还立着（带半截坡屋顶），+x 一端塌成矮墙 + 瓦砾，屋顶板斜插进去；前后对称（被打的是另一端时整栋转 180°）
        const wall = 0xcfc6b2;
        const parts: PartSpec[] = [
          { geo: new THREE.BoxGeometry(7.2, 0.4, 5.8), color: 0x6a5e4c, pos: [0, 0.2, 0] },
          { geo: new THREE.BoxGeometry(3.4, 3.6, 0.3), color: wall, pos: [-1.8, 1.8, 2.65] },
          { geo: new THREE.BoxGeometry(3.4, 3.6, 0.3), color: wall, pos: [-1.8, 1.8, -2.65] },
          { geo: new THREE.BoxGeometry(0.3, 3.6, 5.6), color: wall, pos: [-3.35, 1.8, 0] },
          { geo: frustum(rect(3.8, 6.2, -1.9, 0), rect(3.8, 0.3, -1.9, 0), 2.4, 3.6), color: 0x7a3b2c },
          { geo: new THREE.BoxGeometry(4.2, 0.22, 3.3), color: 0x6e3628, pos: [1.6, 2.0, 1.2], rot: [0.5, 0, -0.42] },
          { geo: new THREE.BoxGeometry(3.6, 0.22, 3.0), color: 0x6a3426, pos: [1.9, 1.3, -1.3], rot: [-0.4, 0.1, -0.6] },
        ];
        for (let i = 0; i < 4; i++) {
          const h = r(0.8, 2.1, i + 61);
          parts.push({ geo: new THREE.BoxGeometry(0.9, h, 0.3), color: wall, pos: [0.4 + i * 0.85, h / 2, 2.65] });
          parts.push({ geo: new THREE.BoxGeometry(0.9, h * 0.8, 0.3), color: wall, pos: [0.4 + i * 0.85, (h * 0.8) / 2, -2.65] });
        }
        for (let i = 0; i < 10; i++) {
          parts.push({ geo: rockify(new THREE.BoxGeometry(r(0.6, 1.3, i + 71), r(0.3, 0.7, i + 81), r(0.5, 1.1, i + 91)), 0.3, i + 3), color: [0xbab2a0, 0x8a5a44, 0x7a3b2c][i % 3], pos: [r(0.6, 3.6, i + 101), 0.35, r(-2.4, 2.4, i + 111)], rot: [r(0, 1, i + 121), r(0, 3, i + 131), r(0, 1, i + 141)] });
        }
        return parts;
      }
      case 'houseShell': {
        // 烧成 / 掀顶后的空壳：四面墙还在、窗洞发黑，屋顶没了，几根焦黑的房梁搭在墙头
        const wall = 0xb8b0a0;
        const parts: PartSpec[] = [
          { geo: new THREE.BoxGeometry(7.2, 0.4, 5.8), color: 0x3a342c, pos: [0, 0.2, 0] },
          { geo: new THREE.BoxGeometry(7, 3.6, 0.3), color: wall, pos: [0, 1.8, 2.65] },
          { geo: new THREE.BoxGeometry(7, 3.2, 0.3), color: wall, pos: [0, 1.6, -2.65] },
          { geo: new THREE.BoxGeometry(0.3, 3.6, 5.6), color: wall, pos: [-3.35, 1.8, 0] },
          { geo: new THREE.BoxGeometry(0.3, 3.4, 5.6), color: wall, pos: [3.35, 1.7, 0] },
          { geo: new THREE.BoxGeometry(0.7, 1.6, 0.7), color: 0x6a5e50, pos: [2.2, 4.4, 0.8] },
          { geo: new THREE.BoxGeometry(0.7, 3.2, 0.7), color: 0x6a5e50, pos: [2.2, 2.4, 0.8] },
          { geo: new THREE.BoxGeometry(1.1, 2.0, 0.12), color: 0x141210, pos: [0, 1.0, 2.82] },
        ];
        for (const x of [-2.4, 2.4]) parts.push({ geo: new THREE.BoxGeometry(1.1, 1.0, 0.12), color: 0x141210, pos: [x, 2.1, 2.82] });
        for (const z of [-1.4, 1.4]) parts.push({ geo: new THREE.BoxGeometry(0.12, 1.0, 1.0), color: 0x141210, pos: [3.52, 2.1, z] });
        for (let i = 0; i < 4; i++) parts.push({ geo: new THREE.BoxGeometry(0.22, 0.22, r(4.2, 6, i + 151)), color: 0x1e1a16, pos: [-2.4 + i * 1.6, 3.4 + r(-0.4, 0.2, i + 161), r(-0.6, 0.6, i + 171)], rot: [r(-0.25, 0.25, i + 181), 0, r(-0.2, 0.2, i + 191)] });
        return parts;
      }
      case 'houseRubble': {
        // 全塌：一堆砖石 / 白灰 / 碎瓦，一个残角 + 烟囱桩
        const parts: PartSpec[] = [
          { geo: rockify(new THREE.DodecahedronGeometry(2.6, 1), 0.3, 31), color: 0x8a8070, pos: [0, 0.2, 0], scale: [1.45, 0.38, 1.1] },
          { geo: new THREE.BoxGeometry(2.6, 2.4, 0.32), color: 0xcfc6b2, pos: [-2.2, 1.2, 2.5] },
          { geo: new THREE.BoxGeometry(0.32, 2.0, 1.9), color: 0xc8bfab, pos: [-3.3, 1.0, 1.6] },
          { geo: new THREE.BoxGeometry(0.7, 1.7, 0.7), color: 0x8a7b68, pos: [2.2, 0.85, 0.8], rot: [0.08, 0, -0.1] },
        ];
        for (let i = 0; i < 18; i++) {
          parts.push({ geo: rockify(new THREE.BoxGeometry(r(0.5, 1.4, i + 201), r(0.25, 0.6, i + 211), r(0.4, 1.2, i + 221)), 0.32, i + 7), color: [0xcfc6b2, 0x8a5a44, 0x7a3b2c, 0x9a9282][i % 4], pos: [r(-3.4, 3.4, i + 231), r(0.3, 0.9, i + 241), r(-2.6, 2.6, i + 251)], rot: [r(0, 1.2, i + 261), r(0, 3, i + 271), r(0, 1.2, i + 281)] });
        }
        for (let i = 0; i < 3; i++) parts.push({ geo: new THREE.BoxGeometry(0.2, 0.2, r(3, 4.5, i + 291)), color: 0x3a2e24, pos: [r(-2, 2, i + 301), 0.9 + i * 0.15, r(-1.5, 1.5, i + 311)], rot: [r(-0.4, 0.4, i + 321), r(0, 3, i + 331), r(-0.3, 0.3, i + 341)] });
        return parts;
      }
      case 'brickStrip': {
        // 推倒 / 炸碎的砖墙：一条 0.5 米高的碎砖带
        const parts: PartSpec[] = [];
        for (let i = 0; i < 14; i++) {
          parts.push({ geo: rockify(new THREE.BoxGeometry(r(0.5, 1.1, i + 351), r(0.2, 0.45, i + 361), r(0.4, 0.8, i + 371)), 0.3, i + 11), color: [0x84503e, 0x7a4a3a, 0x8a5a44, 0x6e6458][i % 4], pos: [-3 + i * 0.46 + r(-0.2, 0.2, i + 381), r(0.15, 0.35, i + 391), r(-0.7, 0.7, i + 401)], rot: [r(0, 1, i + 411), r(0, 3, i + 421), r(0, 1, i + 431)] });
        }
        return parts;
      }
      case 'boulderHalf':
        return [{ geo: rockify(new THREE.DodecahedronGeometry(2.0, 1), 0.4, 23), color: 0x6e675c, pos: [0, 0.8, 0], scale: [0.55, 0.85, 1.0] }];
    }
  });
}

/** 墙洞 / 屋顶洞 / 切痕的贴片：不规则黑洞 + 一圈砖色破边（朝 +z，单位尺寸；切痕把它拉长压扁） */
export function scenePatchGeo(geo: GeoCache): THREE.BufferGeometry {
  return geo.get('scn-patch', () => {
    const n = 12;
    const pos: number[] = [0, 0, 0];
    const col: number[] = [0.06, 0.05, 0.045];
    const inner = new THREE.Color(0x14110e);
    const rim = new THREE.Color(0x8a5a44);
    for (let i = 0; i < n; i++) {
      const a = (i / n) * Math.PI * 2;
      const ri = 0.36 + r(0, 0.14, i + 1);
      const ro = 0.5 + r(0, 0.08, i + 7);
      pos.push(Math.cos(a) * ri, Math.sin(a) * ri, 0, Math.cos(a) * ro, Math.sin(a) * ro, 0);
      col.push(inner.r, inner.g, inner.b, rim.r, rim.g, rim.b);
    }
    const idx: number[] = [];
    for (let i = 0; i < n; i++) {
      const a = 1 + i * 2;
      const b = 1 + ((i + 1) % n) * 2;
      idx.push(0, a, b, a, a + 1, b + 1, a, b + 1, b);
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    g.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
    g.setAttribute('uv', new THREE.Float32BufferAttribute(new Array((pos.length / 3) * 2).fill(0), 2));
    g.setIndex(idx);
    g.computeVertexNormals();
    return g;
  });
}

/** 可碾压物件：[几何体, 宽(x), 深(z), 凸起高度, 压扁后高度（0 = 一压就碎）] */
export interface PropShape {
  geo: THREE.BufferGeometry;
  w: number;
  d: number;
  h: number;
  flat: number;
  /** sand = 沙袋墙掩体（T017-12B，路障本身没有这一种） */
  debris: 'metal' | 'wood' | 'concrete' | 'sand';
}

export function propShape(geo: GeoCache, kind: PropKind, variant: number): PropShape {
  switch (kind) {
    case 'car': {
      // 40 年代老式轿车（T249 简化）：同一个车型换漆色，variant 0 灰蓝 / 1 棕 / 2 军绿 / 3 烧毁的空壳
      const v = Math.min(3, variant);
      return { geo: geo.merged(`prop-car49-${v}`, () => carParts(v)), w: 2.0, d: 4.6, h: 1.65, flat: 0.6, debris: 'metal' };
    }
    case 'truckProp': {
      // variant 4 = 加油车（T093 区域 5）：车头照旧，货厢换成一个横放的油罐
      if (variant === 4) return { geo: geo.merged('prop-fueler', () => truckParts(1, true)), w: 2.3, d: 6.6, h: 2.2, flat: 0.95, debris: 'metal' };
      return {
        geo: geo.merged(`prop-truck40-${Math.min(2, variant)}`, () => truckParts(variant)),
        w: 2.3, d: 6.6, h: 2.2, flat: 0.95, debris: 'metal',
      };
    }
    case 'fence':
      return {
        geo: geo.merged('prop-fence', () => markCrush([
          ...[-2.2, -0.75, 0.75, 2.2].map((x): PartSpec => ({ geo: new THREE.BoxGeometry(0.2, 1.5, 0.2), color: 0x5e4630, pos: [x, 0.75, 0] })),
          { geo: new THREE.BoxGeometry(4.8, 0.2, 0.1), color: 0x7a5e40, pos: [0, 1.15, 0] },
          { geo: new THREE.BoxGeometry(4.8, 0.2, 0.1), color: 0x7a5e40, pos: [0, 0.6, 0] },
        ], C.board)),
        w: 4.8, d: 0.6, h: 0.45, flat: 0, debris: 'wood',
      };
    case 'crates':
      return {
        geo: geo.merged('prop-crates', () => markCrush([
          ...crate(1.3, 1.3, 1.3, 0x8f6c42, 0x4a3a26, [-0.7, 0.65, 0]),
          ...crate(1.3, 1.3, 1.3, 0x5f6a42, 0x34382a, [0.72, 0.65, 0.2], 0.2),
          ...crate(1.2, 1.1, 1.2, 0x7b5d38, 0x4a3a26, [0, 1.85, 0.1], -0.3),
        ], C.board)),
        w: 2.8, d: 1.6, h: 1.3, flat: 0, debris: 'wood',
      };
    case 'barrels':
      return {
        geo: geo.merged('prop-barrels', () => [
          ...crushDrum(0x7a2e22, [-0.55, 0.6, 0]),
          ...crushDrum(0x4e5a3a, [0.5, 0.6, 0.3]),
          ...crushDrum(0x7a2e22, [0.1, 0.42, -0.9], [Math.PI / 2, 0.3]),
        ]),
        w: 2.2, d: 2.0, h: 1.1, flat: 0, debris: 'metal',
      };
    case 'hay':
      return { geo: sceneryGeo(geo, 'hay'), w: 3.2, d: 2.2, h: 1.1, flat: 0, debris: 'wood' };
    case 'log':
      return { geo: sceneryGeo(geo, 'log'), w: 6.2, d: 1.2, h: 0.9, flat: 0, debris: 'wood' };
    case 'cart':
      return {
        geo: geo.merged('prop-cart', () => markCrush([
          { geo: new THREE.BoxGeometry(1.8, 0.5, 2.8), color: 0x7a5a3a, pos: [0, 0.95, 0] },
          { geo: new THREE.BoxGeometry(1.9, 0.6, 0.1), color: 0x6a4e32, pos: [0, 1.4, 1.4] },
          { geo: new THREE.BoxGeometry(1.9, 0.6, 0.1), color: 0x6a4e32, pos: [0, 1.4, -1.4] },
          { geo: new THREE.BoxGeometry(0.12, 0.12, 2.2), color: 0x5a4430, pos: [0, 0.8, 2.4] },
          ...[-1, 1].flatMap((s) => wheel(0.65, 0.12, 0x4a3828, 0x2a2018, [s * 1.0, 0.65, 0])),
        ], C.board)),
        w: 2.0, d: 3.2, h: 1.3, flat: 0.4, debris: 'wood',
      };
    case 'rubble':
      return {
        geo: geo.merged('prop-rubble', () =>
          Array.from({ length: 9 }, (_, i): PartSpec => ({
            geo: rockify(new THREE.BoxGeometry(r(0.8, 1.6, i), r(0.4, 0.9, i + 3), r(0.8, 1.4, i + 7)), 0.25, i),
            color: [0x7a7468, 0x8a5a44, 0x5e5850][i % 3],
            pos: [r(-1.2, 1.2, i + 11), r(0.2, 0.6, i + 13), r(-1.2, 1.2, i + 17)],
            rot: [r(0, 1, i + 19), r(0, 3, i + 23), r(0, 1, i + 29)],
          })),
        ),
        w: 3.0, d: 3.0, h: 0.85, flat: 0.7, debris: 'concrete',
      };
  }
}

/**
 * 老式轿车的零件表（T249 简化）：倒角车身、长机盖、方正驾驶室、一圈车窗、独立挡泥板、竖格栅、圆灯，车顶干净不加东西。
 * 一种车一个合并网格，约 700 面。外形尺寸不变（宽 2、长 4.6、凸起高 1.65），碾压、碎片、炸飞都照旧
 */
function carParts(v: number): PartSpec[] {
  const burnt = v === 3;
  const paint = [0x5e6c72, 0x7a5a3e, 0x4e5a3e, 0x2a2420][v];
  const wing = [0x3c4448, 0x4e3a28, 0x3a4430, 0x1e1a16][v];
  const chrome = burnt ? 0x3a3430 : 0x9a968c;
  const dark = burnt ? 0x141210 : 0x222220;
  const box = (w: number, h: number, d: number) => new THREE.BoxGeometry(w, h, d);
  return [
    // 车身下半截（倒角）、长机盖、行李箱、驾驶室
    { geo: frustum(chamfer(1.5, 4.0, 0.16), chamfer(1.5, 3.96, 0.2), 0.53, 0.42), color: paint, crush: C.skin },
    { geo: frustum(rect(1.2, 1.45, 0, 1.275), rect(1.06, 1.4, 0, 1.25), 0.2, 0.95), color: paint, crush: C.skin },
    { geo: frustum(rect(1.44, 0.58, 0, -1.74), rect(1.3, 0.4, 0, -1.66), 0.25, 0.95), color: paint, crush: C.skin },
    { geo: frustum(chamfer(1.5, 2.0, 0.12, 0, -0.45), chamfer(1.28, 1.45, 0.24, 0, -0.6), 0.67, 0.95), color: paint, crush: C.roof },
    // 一圈车窗：比驾驶室外扩一点的玻璃带，两侧各一根门柱
    { geo: frustum(chamfer(1.46, 1.84, 0.16, 0, -0.5), chamfer(1.35, 1.58, 0.22, 0, -0.57), 0.33, 1.17), color: burnt ? 0x141210 : 0x2a333a, crush: C.glass },
    ...[-1, 1].map((sd): PartSpec => ({ geo: box(0.04, 0.34, 0.1), color: paint, pos: [sd * 0.69, 1.33, -0.45], rot: [0, 0, sd * 0.19], crush: C.roof })),
    // 挡泥板：前长后短，比车身深一号；踏板
    ...[-1, 1].map((sd): PartSpec => ({ geo: frustum(rect(0.32, 1.4, sd * 0.84, 1.3), rect(0.28, 1.0, sd * 0.83, 1.36), 0.42, 0.5), color: wing, crush: C.skin })),
    ...[-1, 1].map((sd): PartSpec => ({ geo: frustum(rect(0.32, 1.2, sd * 0.84, -1.35), rect(0.28, 0.85, sd * 0.83, -1.4), 0.4, 0.5), color: wing, crush: C.skin })),
    ...[-1, 1].map((sd): PartSpec => ({ geo: box(0.3, 0.06, 1.35), color: dark, pos: [sd * 0.84, 0.5, -0.075] })),
    // 竖格栅（框 + 3 根竖条）、圆灯、前后保险杠、尾灯
    { geo: box(0.5, 0.58, 0.06), color: dark, pos: [0, 0.9, 2.02] },
    ...[-0.12, 0, 0.12].map((x): PartSpec => ({ geo: box(0.04, 0.52, 0.04), color: chrome, pos: [x, 0.9, 2.06] })),
    ...[-1, 1].map((sd): PartSpec => ({ geo: new THREE.CylinderGeometry(0.13, 0.12, 0.2, 8), color: burnt ? 0x2a2622 : 0xe8e2c8, pos: [sd * 0.62, 1.04, 1.92], rot: [Math.PI / 2, 0, 0], crush: C.glass })),
    { geo: box(1.86, 0.12, 0.12), color: chrome, pos: [0, 0.48, 2.14] },
    { geo: box(1.86, 0.12, 0.12), color: chrome, pos: [0, 0.48, -2.1] },
    ...[-1, 1].map((sd): PartSpec => ({ geo: box(0.1, 0.14, 0.04), color: burnt ? 0x2a2420 : 0x7a2a22, pos: [sd * 0.62, 0.92, -2.03] })),
    // 车轮（黑胎 + 亮轮毂）
    ...[-1, 1].flatMap((sd) => [-1.35, 1.35].flatMap((z) => markCrush(wheel(0.38, 0.24, 0x1c1c1c, chrome, [sd * 0.86, 0.38, z]), C.wheel))),
  ];
}

/** 二战卡车的零件表：长机盖 + 驾驶室 + 木栏货厢 + 帆布篷；variant 2 是烧毁的只剩篷架 */
function crushDrum(color: number, pos: [number, number, number], tilt: [number, number] = [0, 0]): PartSpec[] {
  return drum(color, pos, tilt).map((p, i) => ({ ...p, crush: i === 0 ? C.drum : C.hoop }));
}

function truckParts(variant: number, fuel = false): PartSpec[] {
  const burnt = variant === 2;
  const body = burnt ? 0x3a302a : variant % 3 === 0 ? 0x5a6046 : 0x6a6450;
  const wood = burnt ? 0x2a2420 : 0x7a5e40;

  const p: PartSpec[] = [
    // 大梁
    ...[-0.55, 0.55].map((x): PartSpec => ({ geo: new THREE.BoxGeometry(0.16, 0.22, 6.2), color: 0x222220, pos: [x, 0.78, -0.2], crush: C.frame })),
    // 机盖、格栅、前挡泥板、保险杠、大灯
    { geo: frustum(rect(1.3, 1.6, 0, 2.35), rect(1.1, 1.5, 0, 2.4), 0.75, 0.9), color: body },
    { geo: new THREE.BoxGeometry(1.1, 0.8, 0.08), color: 0x2a2a28, pos: [0, 1.28, 3.16] },
    ...[-0.4, -0.2, 0, 0.2, 0.4].map((x): PartSpec => ({ geo: new THREE.BoxGeometry(0.05, 0.72, 0.05), color: 0x5a5a56, pos: [x, 1.28, 3.21] })),
    ...[-1, 1].map((sd): PartSpec => ({ geo: frustum(rect(0.6, 1.4, 0, 2.4), rect(0.55, 0.9, 0, 2.5), 0.3, 0.9), color: body, pos: [sd * 0.98, 0, 0] })),
    ...[-1, 1].map((sd): PartSpec => ({ geo: new THREE.CylinderGeometry(0.16, 0.16, 0.14, 10), color: burnt ? 0x2a2a2a : 0xe8e2c8, pos: [sd * 0.98, 1.36, 2.9], rot: [Math.PI / 2, 0, 0] })),
    { geo: new THREE.BoxGeometry(2.1, 0.16, 0.18), color: 0x2a2a28, pos: [0, 0.75, 3.25] },
    // 驾驶室
    { geo: new THREE.BoxGeometry(2.0, 1.3, 1.5), color: body, pos: [0, 1.55, 0.9], crush: C.skin },
    { geo: frustum(rect(2.0, 1.5, 0, 0.9), rect(1.9, 1.3, 0, 0.85), 0.18, 2.2), color: body, crush: C.roof },
    ...[-0.45, 0.45].map((x): PartSpec => ({ geo: new THREE.BoxGeometry(0.8, 0.5, 0.06), color: burnt ? 0x1a1a1a : 0x2a3438, pos: [x, 1.85, 1.66], crush: C.glass })),
    ...[-1, 1].map((sd): PartSpec => ({ geo: new THREE.BoxGeometry(0.06, 0.5, 0.7), color: burnt ? 0x1a1a1a : 0x2a3438, pos: [sd * 1.01, 1.85, 0.9], crush: C.glass })),
    // 货厢：底板 + 木栏板 + 尾板（加油车只留底板）
    { geo: new THREE.BoxGeometry(2.2, 0.18, 3.8), color: wood, pos: [0, 1.0, -1.25], crush: C.bed },
    ...(fuel ? [] : [-1, 1].flatMap((sd) => [0, 1, 2].map((k): PartSpec => ({ geo: new THREE.BoxGeometry(0.06, 0.16, 3.8), color: wood, pos: [sd * 1.08, 1.2 + k * 0.22, -1.25], crush: C.bed })))),
    ...(fuel ? [] : [0, 1, 2].map((k): PartSpec => ({ geo: new THREE.BoxGeometry(2.2, 0.16, 0.06), color: wood, pos: [0, 1.2 + k * 0.22, -3.13], crush: C.bed }))),
    // 车轮：前单后双，备胎挂在侧面
    ...[-1, 1].flatMap((sd) => markCrush(wheel(0.5, 0.3, 0x1c1c1c, 0x55574f, [sd * 1.0, 0.5, 2.2]), C.wheel)),
    ...[-1, 1].flatMap((sd) => [-1.2, -2.2].flatMap((z) => markCrush(wheel(0.5, 0.42, 0x1c1c1c, 0x55574f, [sd * 0.98, 0.5, z]), C.wheel))),
    { geo: new THREE.CylinderGeometry(0.45, 0.45, 0.24, 14), color: 0x1c1c1c, pos: [1.2, 1.15, 0.1], rot: [0, 0, Math.PI / 2], crush: C.wheel },
  ];
  if (fuel) {
    // 加油车：横放的油罐（两头圆封头）+ 一道橙色警示带 + 顶上的人孔 + 尾部的油管卷盘
    const tank = 0x8a8e7a;
    p.push({ geo: new THREE.CylinderGeometry(0.98, 0.98, 3.4, 16), color: tank, pos: [0, 2.0, -1.25], rot: [Math.PI / 2, 0, 0], crush: C.canopy });
    for (const z of [0.45, -2.95]) p.push({ geo: new THREE.SphereGeometry(0.98, 14, 8), color: tank, pos: [0, 2.0, z], scale: [1, 1, 0.3] });
    p.push({ geo: new THREE.CylinderGeometry(1.0, 1.0, 0.24, 16), color: 0xc86a2a, pos: [0, 2.0, -1.25], rot: [Math.PI / 2, 0, 0] });
    p.push({ geo: new THREE.CylinderGeometry(0.3, 0.3, 0.2, 10), color: 0x4a4c44, pos: [0, 3.0, -0.6] });
    p.push({ geo: new THREE.CylinderGeometry(0.34, 0.34, 0.5, 12), color: 0x2a2a28, pos: [0, 1.25, -3.1], rot: [0, 0, Math.PI / 2] });
    return p;
  }
  // 帆布篷 / 烧剩的篷架
  if (!burnt) {
    p.push({ geo: new THREE.CylinderGeometry(1.12, 1.12, 3.7, 12, 1, true, -Math.PI / 2, Math.PI), color: 0x8a8462, pos: [0, 1.75, -1.25], rot: [-Math.PI / 2, 0, 0], crush: C.canopy });
    p.push({ geo: new THREE.BoxGeometry(2.24, 0.7, 3.7), color: 0x857f5e, pos: [0, 1.45, -1.25], crush: C.canopy });
    p.push({ geo: new THREE.CircleGeometry(1.12, 12, 0, Math.PI), color: 0x7a7458, pos: [0, 1.75, 0.6], crush: C.canopy });
  }
  for (const z of [-0.2, -1.25, -2.3]) p.push({ geo: new THREE.TorusGeometry(1.1, 0.04, 4, 10, Math.PI), color: burnt ? 0x2a2420 : 0x4a4636, pos: [0, 1.75, z], crush: C.canopy });
  // 油桶
  if (!burnt) p.push(...drum(0x4e5a3a, [0.6, 1.6, -2.6]));
  return p;
}

/**
 * 卡车被炸成两截：车头（机盖 + 驾驶室 + 前轮）和车尾（货厢 + 后轮），按零件中心在车身上的前后位置分。
 * 返回 [车头, 车尾] 两个合并网格。
 */
export function truckHalves(geo: GeoCache, variant: number): [THREE.BufferGeometry, THREE.BufferGeometry] {
  const v = Math.min(2, variant);
  const split = (front: boolean) => () =>
    truckParts(v).filter((p) => {
      p.geo.computeBoundingBox();
      const bb = p.geo.boundingBox!;
      const cz = (bb.min.z + bb.max.z) / 2 + (p.pos?.[2] ?? 0);
      const keep = (cz > 0.2) === front;
      if (!keep) p.geo.dispose();
      return keep;
    });
  return [geo.merged(`truck-half-f-${v}`, split(true)), geo.merged(`truck-half-r-${v}`, split(false))];
}
