import type { InkContext, UiSkin } from './types';
import { line, random, rivet, scratches } from './drawing';

function gear(c: InkContext, x: number, y: number, r: number): void {
  c.save(); c.translate(x, y);
  c.fillStyle = '#312a20'; c.strokeStyle = '#6b5940'; c.lineWidth = 1.5;
  c.beginPath();
  for (let i = 0; i < 96; i++) {
    const a = Math.PI * 2 * i / 96, rr = r * (i % 4 < 2 ? 1 : 0.9);
    if (i === 0) c.moveTo(Math.cos(a) * rr, Math.sin(a) * rr);
    else c.lineTo(Math.cos(a) * rr, Math.sin(a) * rr);
  }
  c.closePath(); c.fill(); c.stroke();
  for (const k of [0.78, 0.56, 0.28]) {
    c.beginPath(); c.arc(0, 0, r * k, 0, Math.PI * 2); c.stroke();
  }
  for (let i = 0; i < 8; i++) {
    const a = i * Math.PI / 4;
    rivet(c, Math.cos(a) * r * 0.66, Math.sin(a) * r * 0.66, 2.6, true);
  }
  c.restore();
}

export const scheme2: UiSkin = {
  id: 2, name: '铸造车间', shape: 'round', radius: 10, ticks: 16,
  colors: {
    back: '#161411', backHi: '#393022', high: '#574630', low: '#27231b', line: '#947c52',
    ink: '#f0e8d4', soft: '#d8cbb3', dim: '#b4a990', accent: '#d9ae76', cool: '#9bc6c3',
    mainHi: '#aa8350', mainLow: '#715333', mainInk: '#fff0cf', shadow: '#17150f',
  },
  texture(c) {
    scratches(c, 204, 1600);
    const rnd = random(812);
    for (let i = 0; i < 13; i++) {
      const x = rnd() * 256, y = rnd() * 256, r = 5 + rnd() * 13;
      c.fillStyle = 'rgba(130,87,41,.16)';
      c.beginPath();
      for (let j = 0; j < 13; j++) {
        const a = j / 13 * Math.PI * 2, s = r * (0.4 + rnd() * 0.6);
        const px = x + Math.cos(a) * s, py = y + Math.sin(a) * s;
        if (j === 0) c.moveTo(px, py); else c.lineTo(px, py);
      }
      c.closePath(); c.fill();
    }
    for (let i = 0; i < 16; i++) {
      const x = rnd() * 256, y = rnd() * 256, r = 10 + rnd() * 38;
      const g = c.createRadialGradient(x, y, 0, x, y, r);
      g.addColorStop(0, 'rgba(4,8,5,.19)'); g.addColorStop(1, 'rgba(4,8,5,0)');
      c.fillStyle = g; c.fillRect(x - r, y - r, r * 2, r * 2);
      line(c, x, y, x + 1, y + r * 1.5, 'rgba(7,9,5,.13)', 2);
    }
  },
  detail(c, w, h, role) {
    if (h < 32) return;
    if (w < 64 && h > 28) {
      c.strokeStyle = '#9c8457'; c.lineWidth = 1.5;
      c.beginPath(); c.arc(w / 2, h / 2, Math.min(w, h) / 2 - 4, 0, Math.PI * 2); c.stroke();
      return;
    }
    c.strokeStyle = 'rgba(187,157,99,.45)'; c.lineWidth = 1;
    c.strokeRect(4.5, 4.5, w - 9, h - 9);
    for (let y = 14; y < h - 10; y += 4) {
      line(c, 2, y, 5, y, '#191b13', 2);
      line(c, w - 5, y, w - 2, y, '#191b13', 2);
    }
    for (const x of [9, w - 9]) {
      rivet(c, x, 9, 2, true); rivet(c, x, h - 9, 2, true);
    }
    if (role === 'primary') {
      line(c, 18, 5, w - 18, 5, '#c9a46c', 2);
      line(c, 18, h - 5, w - 18, h - 5, '#2c281c', 3);
    }
  },
  scene(c, w, h) {
    const left = Math.max(10, (w - 530) / 2), right = w - left;
    gear(c, left - 34, 112, 90);
    gear(c, right + 32, h - 100, 118);
    for (const x of [left, right]) {
      line(c, x + 2, 28, x + 2, h - 28, '#080c08', 8);
      line(c, x, 28, x, h - 28, '#80683f', 5);
      line(c, x - 1, 28, x - 1, h - 28, '#b49b6d', 1);
      for (let y = 36; y < h - 20; y += 122) {
        c.fillStyle = '#2a281d'; c.fillRect(x - 5, y, 10, 16);
        line(c, x - 5, y, x + 5, y, '#9d8556');
        line(c, x - 5, y + 15, x + 5, y + 15, '#11150e', 2);
        rivet(c, x, y + 8, 2, true);
      }
    }
    line(c, left + 12, 19, right - 12, 19, '#776746', 2);
    line(c, left + 12, h - 19, right - 12, h - 19, '#776746', 2);
    for (let x = w / 2 - 42; x < w / 2 + 42; x += 6) line(c, x, h - 34, x, h - 27, '#a99874');
  },
};
