/** 两点之间一根细管（几何体直接摆好，PartSpec 不用再转） */
function rod(a: [number, number, number], b: [number, number, number], r: number): THREE.BufferGeometry {
  const A = new THREE.Vector3(...a);
  const B = new THREE.Vector3(...b);
  const g = new THREE.CylinderGeometry(r, r, A.distanceTo(B), 6);
  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), B.clone().sub(A).normalize());
  g.applyMatrix4(new THREE.Matrix4().compose(A.add(B).multiplyScalar(0.5), q, new THREE.Vector3(1, 1, 1)));
  return g;
}

/** 火苗：两个喷口各一个外焰锥 + 内焰锥 + 一圈橙色光环；顶点色从喷口的黄白渐变到尖上的橙红（超过 1 吃泛光，叠加混合） */
function flameGeo(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  const paint = (g: THREE.BufferGeometry, top: number, tip: number, len: number) => {
    const p = g.getAttribute('position') as THREE.BufferAttribute;
    const c = new Float32Array(p.count * 3);
    const a = new THREE.Color(top);
    const b = new THREE.Color(tip);
    const col = new THREE.Color();
    for (let i = 0; i < p.count; i++) {
      const k = len > 0 ? THREE.MathUtils.clamp(-p.getY(i) / len, 0, 1) : 0;
      col.copy(a).lerp(b, k).multiplyScalar(1.7 * (1 - k * 0.7));
      c.set([col.r, col.g, col.b], i * 3);
    }
    g.setAttribute('color', new THREE.BufferAttribute(c, 3));
    return g;
  };
  for (const x of [-0.15, 0.15]) {
    const outer = new THREE.ConeGeometry(0.15, 1, 8, 1, true).rotateX(Math.PI).translate(x, -0.5, 0);
    const inner = new THREE.ConeGeometry(0.075, 0.6, 6, 1, true).rotateX(Math.PI).translate(x, -0.3, 0);
    const ring = new THREE.TorusGeometry(0.1, 0.03, 4, 12).rotateX(Math.PI / 2).translate(x, 0, 0);
    parts.push(paint(outer.toNonIndexed(), 0xffa040, 0xff3a08, 1), paint(inner.toNonIndexed(), 0xffe6a0, 0xff8a30, 0.6), paint(ring.toNonIndexed(), 0xff8a30, 0xff8a30, 0));
  }
  for (const g of parts) for (const k of Object.keys(g.attributes)) if (k !== 'position' && k !== 'color') g.deleteAttribute(k);
  const out = mergeGeometries(parts, false);
  if (!out) throw new Error('合并几何体失败: jet-flame');
  return out;
}

