const CAP: Record<PartId, number> = { torso: 200, head: 200, thigh: 400, shin: 400, upper: 400, fore: 400, rifle: 200, launcher: 40, coil: 60, glow: 60, mg: 30, satchel: 60, jet: 40, flame: 40 };

/** 一个人形的姿势（关节角，弧度） */
interface Pose {
  /** 整体下沉（跪 / 趴） */
  drop: number;
  /** 整个人绕髋部前倾（趴下 / 倒地，负数向后倒） */
  prone: number;
  /** 上身前倾 / 扭腰 */
  lean: number;
  twist: number;
  headYaw: number;
  headPitch: number;
  /** 大腿前后摆（负数向前）、膝盖弯曲（正数小腿向后） */
  thighL: number;
  thighR: number;
  kneeL: number;
  kneeR: number;
  splay: number;
  /** 上臂前后摆（负数向前抬）、外展、手肘弯曲（负数前臂向前） */
  armL: number;
  armR: number;
  rollL: number;
  rollR: number;
  elbowL: number;
  elbowR: number;
  /** 0 = 端枪，1 = 抵肩瞄准 */
  aim: number;
  bob: number;
  sway: number;
  recoil: number;
}

const clamp01 = (v: number) => Math.max(0, Math.min(1, v));

/**
 * 步兵被毁的烟火按画质（T248）：busy = 同一帧最多几个人放烟火（多的只演动作和变色），rate = 发射间隔倍数，
 * extra = 第二层（烧着冒的黑烟、电击的蓝光晕、灰的第二团、飞行烟迹）只在高档
 */
const DEATH_FX: Record<Quality, { busy: number; rate: number; extra: boolean }> = {
  high: { busy: 12, rate: 1, extra: true },
  medium: { busy: 8, rate: 1.8, extra: false },
  low: { busy: 4, rate: 3, extra: false },
};
/** 电击过曝色（乘在军服色上）；同时被电的人多于 crowd 个换成 dim，免得一片白 */
const ZAP_LOOK = { hot: [2.0, 2.5, 3.2], dim: [1.4, 1.7, 2.2], dark: [0.3, 0.38, 0.55], ash: [0.62, 0.62, 0.6], crowd: 6 };
/** 烧焦的颜色（乘在军服色上） */
const CHAR = [0.16, 0.14, 0.13];

export class Infantry {
  private readonly meshes = new Map<PartId, THREE.InstancedMesh>();
  private readonly counts = new Map<PartId, number>();
  private readonly m = new THREE.Matrix4();
  private readonly root = new THREE.Matrix4();
  private readonly fig = new THREE.Matrix4();
  private readonly tmp = new THREE.Matrix4();
  private readonly hip = new THREE.Matrix4();
  private readonly chest = new THREE.Matrix4();
  private readonly limb = new THREE.Matrix4();
  private readonly e = new THREE.Euler();
  private readonly q = new THREE.Quaternion();
  private readonly p = new THREE.Vector3();
  private readonly one = new THREE.Vector3(1, 1, 1);
  private readonly c = new THREE.Color();
  /** 被毁特效（T248）：Game 注入烟火和当前画质；shade 乘在这个人每块肢体的颜色上（烧焦 / 过曝 / 化灰） */
  fx: Fx | null = null;
  quality: Quality = 'high';
  private readonly shade = new THREE.Color(1, 1, 1);
  private busy = 0;
  private zaps = 0;
  private zapsLast = 0;
  private readonly pose: Pose = {
    drop: 0, prone: 0, lean: 0, twist: 0, headYaw: 0, headPitch: 0, thighL: 0, thighR: 0, kneeL: 0, kneeR: 0, splay: 0,
    armL: 0, armR: 0, rollL: 0, rollR: 0, elbowL: 0, elbowR: 0, aim: 0, bob: 0, sway: 0, recoil: 0,
  };

  constructor(scene: THREE.Scene, geo: GeoCache) {
    // 飞蝗的火苗（T093）：不受光、叠加混合、超过 1 的亮度吃泛光；实例颜色管明暗（推进时亮、滑翔时暗）
    const flameMat = new THREE.MeshBasicMaterial({ vertexColors: true, toneMapped: false, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide });
    for (const id of Object.keys(CAP) as PartId[]) {
      const mat = id === 'glow' ? MAT.energyBlue : id === 'flame' ? flameMat : MAT.painted;
      const mesh = new THREE.InstancedMesh(id === 'flame' ? geo.get('inf2-flame', flameGeo) : partGeo(geo, id), mat, CAP[id]);
      mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
      mesh.frustumCulled = false;
      mesh.castShadow = id === 'torso' || id === 'thigh';
      mesh.count = 0;
      if (id === 'flame') mesh.renderOrder = 3;
      if (id !== 'glow') mesh.setColorAt(0, this.c.setRGB(1, 1, 1));
      scene.add(mesh);
      this.meshes.set(id, mesh);
    }
  }

  update(delta: number, list: Enemy[], time: number): void {
    for (const id of this.meshes.keys()) this.counts.set(id, 0);
    this.busy = 0;
    this.zapsLast = this.zaps;
    this.zaps = 0;
    for (const e of list) {
      if (e.state === 'dead' || !e.group.visible) continue;
      const k = e.kind;
      if (!FOOT.has(k)) continue;
      this.animate(e, delta);
      if (e.state === 'wreck' && e.death && delta > 0) this.deathFx(e, delta);
      e.group.updateMatrix();
      const r = e.bodyRoot;
      r.updateMatrix();
      this.root.multiplyMatrices(e.group.matrix, r.matrix);
      // 每个兵身材和军服深浅略有差别
      const tint = 0.85 + e.tint * 0.3;
      const size = 0.94 + e.tint * 0.12;
      // 烧完 / 电完以后整个人往地上塌成一摊（T248）
      const crumble = this.deathLook(e, time);
      const sy = 1 - 0.88 * crumble;
      const sxz = 1 + 0.15 * crumble;
      if (k === 'mgteam') {
        // 机枪组：两个人趴在机枪后面
        for (const side of [-0.55, 0.55]) {
          this.fig.makeTranslation(side, 0, side < 0 ? 0 : -0.3).premultiply(this.root);
          if (crumble > 0) this.fig.multiply(this.m.makeScale(sxz, sy, sxz));
          this.buildPose(e, time, true, side);
          this.figure(e, tint, false);
        }
        this.add('mg', this.root, tint);
        continue;
      }
      this.fig.copy(this.root).multiply(this.m.makeScale(size * sxz, size * sy, size * sxz));
      this.buildPose(e, time, false, 0);
      this.figure(e, tint, true);
      if (e.gearY > -50) this.gear(e, delta);
    }
    for (const [id, mesh] of this.meshes) {
      mesh.count = this.counts.get(id) ?? 0;
      mesh.instanceMatrix.needsUpdate = true;
      if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
    }
  }

  /** 这个人现在的颜色倍数（写进 shade），返回塌下去的进度 0..1（T248） */
  private deathLook(e: Enemy, time: number): number {
    const S = this.shade.setRGB(1, 1, 1);
    if (e.state !== 'wreck') return 0;
    const t = e.deadT;
    if (e.death === 'burn') {
      // 从军服色烧到焦黑；着火那阵带一点跳动的暖光
      const B = INF_DEATH.burn;
      const char = clamp01(t / 1.3);
      const flick = t < B.crumble ? (0.5 + 0.5 * Math.sin(time * 31 + e.tint * 20)) * (1 - char * 0.6) : 0;
      S.setRGB(1 - (1 - CHAR[0]) * char + flick * 0.5, 1 - (1 - CHAR[1]) * char + flick * 0.18, 1 - (1 - CHAR[2]) * char);
      return clamp01((t - B.crumble) / B.crumbleT);
    }
    if (e.death === 'zap') {
      // 抽搐时在过曝的蓝白和发暗之间闪，之后褪成灰白
      const Z = INF_DEATH.zap;
      if (t < Z.jolt) {
        this.zaps += 1;
        const on = Math.floor(t * 18 + e.tint * 7) % 2 === 0;
        const c = on ? (this.zapsLast > ZAP_LOOK.crowd ? ZAP_LOOK.dim : ZAP_LOOK.hot) : ZAP_LOOK.dark;
        S.setRGB(c[0], c[1], c[2]);
      } else {
        const k = clamp01((t - Z.jolt) / 0.2);
        const a = ZAP_LOOK.dark;
        const b = ZAP_LOOK.ash;
        S.setRGB(a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k);
      }
      return clamp01((t - Z.crumble) / Z.crumbleT);
    }
    return 0;
  }

  /** 被毁以后按类型放烟火（T248，按画质限量；同一帧放烟火的人数有上限） */
  private deathFx(e: Enemy, delta: number): void {
    const fx = this.fx;
    if (!fx) return;
    const Q = DEATH_FX[this.quality];
    const p = e.group.position;
    const g = p.y;
    const t = e.deadT;
    // 正在演的每个人都占一个名额，超出的只演动作和变色（中弹仰倒只扬一点土，不占）
    if (e.death !== 'shot' && ++this.busy > Q.busy) return;
    e.fxAcc -= delta;
    if (e.fxAcc > 0) return;
    switch (e.death) {
      case 'burn': {
        const B = INF_DEATH.burn;
        if (t < B.crumble) {
          // 一身火苗，跑着的时候在胸口，倒下以后贴地；高档再冒黑烟
          e.fxAcc = 0.07 * Q.rate;
          const y = g + (t < B.run + 0.3 ? 1.1 : 0.45);
          fx.fire(p.x, y, p.z, 0.55);
          if (Q.extra && Math.random() < 0.5) fx.smoke(p.x, y + 0.5, p.z, 0.35, 1.6, 0x1e1b19, 0.55);
          if (e.fxStep === 0 && t > B.run + 0.5) {
            e.fxStep = 1;
            fx.decals.add(DecalKind.Scorch, p.x, p.z, 1.6, 1.6, Math.random() * 6.28, 0.6, 12);
          }
        } else {
          // 塌下去时冒几团灰烟
          e.fxAcc = 0.3 * Q.rate;
          fx.smoke(p.x, g + 0.3, p.z, 0.4, 1.4, 0x4a4640, 0.45);
        }
        return;
      }
      case 'zap': {
        const Z = INF_DEATH.zap;
        if (t < Z.jolt) {
          // 身上乱窜的蓝色电火花；高档加一圈淡蓝光晕
            e.fxAcc = 0.1 * Q.rate;
          fx.sparks(p.x + (Math.random() - 0.5) * 0.5, g + 0.5 + Math.random() * 1.1, p.z + (Math.random() - 0.5) * 0.5, Q.extra ? 3 : 2, 0x9fd8ff, 6);
          if (Q.extra) fx.glow.emit({ x: p.x, y: g + 1.1, z: p.z, life: 0.09, size: 1.4, size1: 1.1, color: 0xbfe0ff, color1: 0x3a7cff, alpha: 0.3, frame: 0 });
        } else if (t > Z.crumble + e.fxStep * 0.3 && e.fxStep < 2) {
          // 化灰：一团（高档两团）灰白的烟
            e.fxStep += Q.extra ? 1 : 2;
          fx.smoke(p.x, g + 0.5, p.z, 0.45, 1.5, 0x8a8680, 0.5);
        }
        return;
      }
      case 'shot':
        // 倒地那一下扬一点土（低档不放）
        if (e.fxStep === 0 && t > 0.55) {
          e.fxStep = 1;
          if (this.quality !== 'low') fx.dust(p.x, p.z, 0.45, 0x8a7a60, 0.35);
        }
        return;
      case 'blast':
      case 'shell': {
        // 飞在空中拖一缕黑烟（高档）；落地扬一团土（低档不放）
        const air = g > e.groundY + 0.3;
        if (air && Q.extra) {
            e.fxAcc = 0.08;
          fx.smoke(p.x, g + 0.8, p.z, 0.25, 0.8, 0x2a2624, 0.45);
        } else if (!air && e.fxStep === 0 && t > 0.2) {
          e.fxStep = 1;
          if (this.quality !== 'low') fx.dust(p.x, p.z, 0.6, 0x8a7a60, 0.4);
        }
        return;
      }
    }
  }

  /** 主炮直击打脱手的步枪（T248）：抛物线翻着飞，落地平躺 */
  private gear(e: Enemy, delta: number): void {
    if (e.gearVy !== 0 || e.gearVx !== 0) {
      e.gearVy -= 22 * delta;
      e.gearX += e.gearVx * delta;
      e.gearY += e.gearVy * delta;
      e.gearZ += e.gearVz * delta;
      e.gearA += e.gearSpin * delta;
      if (e.gearY <= e.groundY + 0.06) {
        e.gearY = e.groundY + 0.06;
        e.gearVx = e.gearVy = e.gearVz = 0;
        e.gearA = 0;
      }
    }
    this.shade.setRGB(1, 1, 1);
    this.q.setFromEuler(this.e.set(e.gearA, e.gearA * 0.4, 0));
    this.m.compose(this.p.set(e.gearX, e.gearY, e.gearZ), this.q, this.one);
    this.add('rifle', this.m, 1);
  }

  /** 从位移推算步频；每个兵的步幅节奏略有不同 */
  private animate(e: Enemy, delta: number): void {
    const x = e.group.position.x;
    const z = e.group.position.z;
    const d = Math.hypot(x - e.lastX, z - e.lastZ);
    e.lastX = x;
    e.lastZ = z;
    const sp = delta > 0 ? Math.min(12, d / delta) : 0;
    e.animSpeed += (sp - e.animSpeed) * Math.min(1, delta * 6);
    e.animPhase += delta * (1.5 + e.animSpeed * (2.2 + e.tint * 0.6));
    e.fireAnim = Math.max(0, e.fireAnim - delta);
    if (e.state === 'wreck') e.deadT += delta;
  }

  private buildPose(e: Enemy, time: number, prone: boolean, seat: number): void {
    const P = this.pose;
    const wreck = e.state === 'wreck';
    // 飞蝗（T093）：天上不迈腿；被打下来打旋迫降时身子僵着、不甩手脚（过审），落地以后照步兵倒地
    const jet = e.jet && !e.jet.landed && !!e.fly && (e.alive || e.fly.crash >= 0) ? e.jet : null;
    const flying = wreck && e.fall === 0 && e.bodyRoot.scale.y > 0.5 && !jet;
    const move = jet ? 0 : Math.min(1, e.animSpeed / 2.6);
    const ph = e.animPhase;
    const s = Math.sin(ph);
    const c = Math.cos(ph);
    const idle = 1 - move;
    const seed = e.tint * 13;

    // ---- 跑动：前倾、屈膝、扭腰、摆臂，头部反向转稳住视线；不动时呼吸、左右张望、重心换脚
    P.drop = 0;
    P.prone = 0;
    P.splay = 0.03;
    P.lean = 0.24 * move + Math.sin(time * 2.1 + seed) * 0.025 * idle;
    P.twist = s * 0.16 * move;
    P.headYaw = -P.twist * 0.8 + Math.sin(time * 0.45 + seed) * 0.55 * idle;
    P.headPitch = -0.1 * move;
    P.thighL = -s * 0.85 * move;
    P.thighR = s * 0.85 * move;
    P.kneeL = move * (0.15 + 1.15 * Math.max(0, c)) + idle * 0.06;
    P.kneeR = move * (0.15 + 1.15 * Math.max(0, -c)) + idle * 0.06;
    P.bob = Math.abs(c) * 0.09 * move - move * 0.05;
    P.sway = Math.sin(time * 0.8 + seed) * 0.04 * idle;
    P.armL = s * 0.75 * move;
    P.armR = -s * 0.75 * move;
    P.rollL = 0.1;
    P.rollR = 0.1;
    P.elbowL = -0.35 - 0.6 * move;
    P.elbowR = -0.35 - 0.6 * move;
    P.aim = 0;
    P.recoil = 0;

    const holdsRifle = e.kind === 'infantry' || e.kind === 'shock' || e.kind === 'locust';
    if (holdsRifle) {
      // 端枪：枪斜挎在胸前，双手一上一下握着，跑起来跟着身体晃
      P.armL = -0.55 + s * 0.08 * move;
      P.elbowL = -1.35;
      P.rollL = 0.42;
      P.armR = -0.15 - s * 0.08 * move;
      P.elbowR = -1.55;
      P.rollR = 0.12;
    }
    if (e.kind === 'rocketeer' && !e.aiming && e.fireAnim <= 0) {
      // 火箭筒扛在右肩：右手扶筒，左手摆臂
      P.armR = -1.1;
      P.elbowR = -1.4;
      P.rollR = 0.2;
    }
    if (e.kind === 'sapper') {
      // 爆破兵：压低身子狂奔，右手把炸药包举过头顶，左手猛摆
      P.lean = 0.4 * move + 0.1;
      P.armR = -2.7;
      P.elbowR = -0.4;
      P.rollR = 0.15;
      P.armL = s * 1.0 * move;
      P.elbowL = -1.1;
      P.headPitch = -0.25;
    }
    if (e.panic > 0 && !wreck) {
      // 吓跑：抱头鼠窜，枪也顾不上端
      P.lean = 0.35;
      P.armL = -2.3 + s * 0.2;
      P.armR = -2.3 - s * 0.2;
      P.elbowL = -1.9;
      P.elbowR = -1.9;
      P.rollL = 0.5;
      P.rollR = 0.5;
      P.headPitch = 0.35;
      P.headYaw = Math.sin(time * 6 + seed) * 0.4;
    }
    if (e.fireAnim > 0 && holdsRifle) {
      // 抵肩射击：左手前伸托枪、右手扣扳机，开枪瞬间上身被后坐顶一下；一部分兵单膝跪下打
      P.aim = 1;
      P.armL = -1.3;
      P.elbowL = -0.3;
      P.rollL = 0.3;
      P.armR = -0.75;
      P.elbowR = -1.25;
      P.rollR = -0.15;
      P.headPitch = 0.12;
      P.headYaw = 0.12;
      P.twist = -0.25;
      P.lean = 0.12;
      P.recoil = Math.max(0, e.fireAnim - 0.22) * 2.2;
      if (e.tint > 0.55) {
        P.drop = 0.42;
        P.thighL = -1.45;
        P.kneeL = 1.5;
        P.thighR = 0.35;
        P.kneeR = 2.1;
        P.bob = 0;
      }
    }
    if (e.kind === 'rocketeer' && (e.aiming || e.fireAnim > 0)) {
      // 跪姿扛筒瞄准
      P.drop = 0.44;
      P.thighL = -1.45;
      P.kneeL = 1.5;
      P.thighR = 0.35;
      P.kneeR = 2.1;
      P.armL = -1.25;
      P.elbowL = -0.55;
      P.rollL = 0.25;
      P.armR = -1.15;
      P.elbowR = -1.3;
      P.lean = 0.1;
      P.twist = -0.15;
      P.bob = 0;
      P.recoil = Math.max(0, e.fireAnim - 0.3) * 2;
    }
    if (prone) {
      // 趴地：手肘撑地扶着机枪，偶尔动动腿
      P.prone = 1.45;
      P.drop = 0.74;
      P.lean = 0;
      P.twist = 0;
      P.headPitch = -1.1;
      P.headYaw = Math.sin(time * 0.7 + seat * 5) * 0.2;
      P.thighL = 0.05 + Math.sin(time * 1.6 + seat * 3) * 0.06;
      P.thighR = -0.05;
      P.kneeL = 0.3 + Math.max(0, Math.sin(time * 0.9 + seat)) * 0.5;
      P.kneeR = 0.15;
      P.splay = 0.22;
      P.armL = -2.5;
      P.elbowL = 0.9;
      P.armR = -2.4;
      P.elbowR = 1.0;
      P.rollL = 0.35;
      P.rollR = 0.35;
      P.bob = 0;
      P.recoil = e.fireAnim > 0 ? Math.sin(time * 60) * 0.03 : 0;
    }
    // 中弹缩一下
    if (e.hitFlash > 0 && !wreck) {
      P.lean -= e.hitFlash * 1.2;
      P.headPitch += e.hitFlash;
    }
    if (e.stunTime > 0 && !wreck) {
      // 被冲击波掀得踉跄：双臂乱挥、上身后仰
      P.armL = -1.6 + Math.sin(time * 26) * 0.7;
      P.armR = -1.6 + Math.cos(time * 23) * 0.7;
      P.rollL = 0.7;
      P.rollR = 0.7;
      P.elbowL = -0.4;
      P.elbowR = -0.4;
      P.lean = -0.35;
      P.headPitch = 0.3;
      P.kneeL = 0.5;
      P.kneeR = 0.3;
    }
    if (jet) {
      // 飞蝗在天上：两腿并拢微屈垂着，前倾跟着蛙跳走（推进 25°、扑近更多）；迫降时缩着身子
      P.headYaw = 0;
      P.headPitch = 0;
      P.thighL = -0.12 - jet.lean * 0.3;
      P.thighR = -0.02 - jet.lean * 0.3;
      P.kneeL = 0.35 + jet.lean * 0.4;
      P.kneeR = 0.5 + jet.lean * 0.3;
      P.splay = 0.06;
      P.bob = 0;
      P.sway = 0;
      P.drop = 0;
      if (P.aim <= 0) P.lean = jet.lean;
      if (wreck) {
        P.lean = 0.55;
        P.kneeL = 0.9;
        P.kneeR = 1.1;
        P.thighL = -0.5;
        P.thighR = -0.4;
        P.armL = -0.4;
        P.armR = -0.3;
        P.elbowL = -1.2;
        P.elbowR = -1.3;
        P.rollL = 0.25;
        P.rollR = 0.25;
        P.aim = 0;
        P.recoil = 0;
      }
    } else if (flying) {
      // 被炸飞：四肢乱甩
      P.rollL = 1.3;
      P.rollR = 1.3;
      P.armL = Math.sin(time * 17 + seed) * 1.4;
      P.armR = Math.cos(time * 15) * 1.4;
      P.elbowL = -0.8;
      P.elbowR = -0.6;
      P.splay = 0.45;
      P.thighL = Math.sin(time * 13) * 0.7;
      P.thighR = -Math.sin(time * 11) * 0.7;
      P.kneeL = 0.9;
      P.kneeR = 0.6;
      P.headPitch = Math.sin(time * 9) * 0.5;
      P.bob = 0;
      P.lean = 0;
      P.twist = 0;
    } else if (wreck && e.death === 'burn') {
      const B = INF_DEATH.burn;
      const t = e.deadT;
      if (t < B.run && !prone) {
        // 浑身着火乱跑两步：两手在头上乱挥，身子前后晃，头左右甩
        const w = time * 17 + seed;
        P.drop = 0;
        P.prone = 0;
        P.splay = 0.05;
        P.lean = 0.25 + Math.sin(w * 0.7) * 0.15;
        P.twist = Math.sin(w * 0.5) * 0.3;
        P.headYaw = Math.sin(w * 0.8) * 0.6;
        P.headPitch = 0.3;
        P.thighL = -s * 0.9;
        P.thighR = s * 0.9;
        P.kneeL = 0.2 + 1.1 * Math.max(0, c);
        P.kneeR = 0.2 + 1.1 * Math.max(0, -c);
        P.bob = Math.abs(c) * 0.08;
        P.armL = -2.5 + Math.sin(w) * 0.7;
        P.armR = -2.3 + Math.cos(w * 1.1) * 0.7;
        P.rollL = 0.5 + Math.sin(w * 0.9) * 0.2;
        P.rollR = 0.5 + Math.cos(w * 0.8) * 0.2;
        P.elbowL = -0.9 + Math.sin(w * 1.3) * 0.5;
        P.elbowR = -0.8 + Math.cos(w * 1.2) * 0.5;
        P.aim = 0;
        P.recoil = 0;
      } else this.fallPose(prone ? t : t - B.run, e.fall);
    } else if (wreck && e.death === 'zap') {
      // 电击：浑身绷直、双臂张开，短促抽搐；抽完就定在最后那一下，等着化灰
      const tt = Math.min(e.deadT, INF_DEATH.zap.jolt);
      const w = tt * 60 + seed;
      const j = (a: number, k: number) => Math.sin(w * k + a);
      if (prone) {
        P.headPitch += j(0, 1.7) * 0.3;
        P.armL += j(1, 1.2) * 0.3;
        P.armR += j(2, 1.4) * 0.3;
        P.kneeL += Math.abs(j(3, 1.5)) * 0.4;
      } else {
        P.drop = -0.04 + j(0, 1.3) * 0.03;
        P.prone = 0;
        P.lean = -0.25 + j(1, 1) * 0.12;
        P.twist = j(2, 0.7) * 0.15;
        P.headPitch = -0.35 + j(3, 1.7) * 0.2;
        P.headYaw = j(4, 0.9) * 0.25;
        P.thighL = 0.05 + j(5, 1.1) * 0.1;
        P.thighR = -0.05 - j(6, 1.2) * 0.1;
        P.kneeL = 0.1 + Math.abs(j(7, 1.5)) * 0.15;
        P.kneeR = 0.1 + Math.abs(j(8, 1.6)) * 0.15;
        P.splay = 0.22;
        P.armL = -1.3 + j(9, 1.2) * 0.35;
        P.armR = -1.2 + j(10, 1.4) * 0.35;
        P.rollL = 1.0 + j(11, 0.8) * 0.3;
        P.rollR = 1.0 + j(12, 0.9) * 0.3;
        P.elbowL = -0.3 + j(13, 2) * 0.25;
        P.elbowR = -0.3 + j(14, 2.1) * 0.25;
        P.bob = 0;
        P.sway = 0;
      }
      P.aim = 0;
      P.recoil = 0;
    } else if (wreck && e.fall !== 0) this.fallPose(e.deadT, e.fall);
  }

  /** 中枪倒地：先腿一软跪下去，再整个人前扑或后仰倒地，手脚摊开（t = 开始倒下多久，fall = 1 前扑 / -1 后仰） */
  private fallPose(t: number, fall: number): void {
    const P = this.pose;
    const buckle = clamp01(t / 0.18);
    const topple = clamp01((t - 0.12) / 0.45);
    const ease = topple * topple;
    P.drop = buckle * 0.35 + ease * 0.42;
    P.kneeL = 0.9 * buckle * (1 - ease) + 0.2;
    P.kneeR = 1.2 * buckle * (1 - ease) + 0.3;
    P.thighL = -0.6 * buckle * (1 - ease);
    P.thighR = -0.3 * buckle * (1 - ease);
    P.prone = fall * 1.5 * ease;
    P.lean = 0.3 * buckle * (1 - ease);
    P.twist = 0;
    P.headPitch = fall * 0.4 * ease;
    P.headYaw = 0.5 * ease;
    P.armL = -0.8 * (1 - ease) + (fall > 0 ? -2.2 : 2.0) * ease;
    P.armR = -0.4 * (1 - ease) + (fall > 0 ? -1.6 : 2.4) * ease;
    P.rollL = 0.3 + ease * 0.6;
    P.rollR = 0.3 + ease * 0.9;
    P.elbowL = -0.4;
    P.elbowR = -0.9 * ease;
    P.splay = 0.2 * ease;
    P.aim = 0;
    P.bob = 0;
    P.recoil = 0;
  }

  /** 把一个人形的各个肢体写进实例矩阵（以 this.fig 为人形根） */
  private figure(e: Enemy, tint: number, extras: boolean): void {
    const P = this.pose;
    // 髋部：下沉 + 上下起伏 + 左右晃 + 趴下 / 倒地（绕髋部转）
    const base = this.tmp.makeTranslation(P.sway, 0.95 - P.drop + P.bob, 0);
    base.multiply(this.m.makeRotationX(P.prone));
    const hip = this.hip.multiplyMatrices(this.fig, base);

    // 上身：前倾 + 扭腰 + 后坐
    this.q.setFromEuler(this.e.set(P.lean - P.recoil * 0.25, P.twist, 0, 'YXZ'));
    this.m.compose(this.p.set(0, 0, -P.recoil * 0.08), this.q, this.one);
    const chest = this.chest.multiplyMatrices(hip, this.m);
    this.add('torso', chest, tint);
    const j = e.jet;
    if (j) {
      // 飞蝗：背包和头一个件；火苗按长度拉伸（低档放大 1.3 倍），燃料烧完落地后熄火
      this.add('jet', chest, tint);
      const lit = !j.landed && !!e.fly && e.alive;
      if (lit) {
        const L = JET_LOOK.flame;
        this.q.identity();
        this.m.compose(this.p.set(...JET_NOZZLE), this.q, this.one.set(L, (0.5 + j.flame * 1.35) * L, L)).premultiply(chest);
        this.one.set(1, 1, 1);
        const mesh = this.meshes.get('flame')!;
        const n = this.counts.get('flame') ?? 0;
        if (n < CAP.flame) {
          mesh.setMatrixAt(n, this.m);
          const b = 0.55 + j.flame * 0.45;
          mesh.setColorAt(n, this.c.setRGB(b, b, b));
          this.counts.set('flame', n + 1);
        }
      }
    } else this.addLocal('head', chest, 0, 0.82, 0.02, P.headPitch, P.headYaw, 0, tint);

    // 腿：大腿 → 小腿
    this.limbPair('thigh', 'shin', hip, -0.15, 0, 0, P.thighL, -P.splay, THIGH, P.kneeL, tint);
    this.limbPair('thigh', 'shin', hip, 0.15, 0, 0, P.thighR, P.splay, THIGH, P.kneeR, tint);
    // 手臂：上臂 → 前臂
    this.limbPair('upper', 'fore', chest, -0.37, 0.72, 0.02, P.armL, -P.rollL, UPPER, P.elbowL, tint);
    this.limbPair('upper', 'fore', chest, 0.37, 0.72, 0.02, P.armR, P.rollR, UPPER, P.elbowR, tint);
    if (!extras) return;
    if (e.kind === 'sapper') {
      // 炸药包握在右手（前臂末端）
      this.limb.copy(this.m);
      this.addLocal('satchel', this.limb, 0, -0.42, 0.04, 0, 0, 0, 1);
      return;
    }
    const k = e.kind;
    const downed = e.state === 'wreck';
    if ((k === 'infantry' || k === 'shock' || k === 'locust') && !downed) {
      // 端枪斜挎胸前 / 抵肩瞄准（后坐时枪口上跳）
      if (P.aim > 0) this.addLocal('rifle', chest, 0.14, 0.66, 0.46 - P.recoil * 0.12, -P.recoil * 0.5, 0, 0, 1);
      else this.addLocal('rifle', chest, 0.02, 0.48, 0.34, -0.35, -0.55, 0.5, 1);
    }
    if (k === 'rocketeer' && !downed) this.addLocal('launcher', chest, 0.3, 0.86, 0.12, e.aiming ? -P.recoil * 0.4 : -0.12, 0, 0, 1);
    if (k === 'shock') {
      this.addLocal('coil', chest, 0, 0.6, -0.4, 0, 0, 0, 1);
      if (!downed) this.addLocal('glow', chest, 0, 1.06, -0.4, 0, 0, 0, 1);
    }
  }

  /** 两段式肢体：近端绕 (x, y, z) 关节摆动 + 外展，远端在 len 处再弯一次 */
  private limbPair(near: PartId, far: PartId, parent: THREE.Matrix4, x: number, y: number, z: number, pitch: number, roll: number, len: number, bend: number, tint: number): void {
    this.q.setFromEuler(this.e.set(pitch, 0, roll));
    this.limb.compose(this.p.set(x, y, z), this.q, this.one).premultiply(parent);
    this.add(near, this.limb, tint);
    this.q.setFromEuler(this.e.set(bend, 0, 0));
    this.m.compose(this.p.set(0, -len, 0), this.q, this.one).premultiply(this.limb);
    this.add(far, this.m, tint);
  }

  private addLocal(id: PartId, parent: THREE.Matrix4, x: number, y: number, z: number, rx: number, ry: number, rz: number, tint: number): void {
    this.q.setFromEuler(this.e.set(rx, ry, rz));
    this.m.compose(this.p.set(x, y, z), this.q, this.one).premultiply(parent);
    this.add(id, this.m, tint);
  }

  private add(id: PartId, matrix: THREE.Matrix4, tint: number): void {
    const mesh = this.meshes.get(id)!;
    const n = this.counts.get(id) ?? 0;
    if (n >= CAP[id]) return;
    mesh.setMatrixAt(n, matrix);
    const S = this.shade;
    if (mesh.instanceColor) mesh.setColorAt(n, this.c.setRGB(tint * S.r, tint * S.g, tint * 0.97 * S.b));
    this.counts.set(id, n + 1);
  }
}
