  len: { head: 16, car: 11, gap: 1 },
  r: 4.87,
  axis: 4.5,
  deep: -6.6,
  /** 停车线：刷出来那一刻坦克前方 line 米（泵站入口） */
  line: 30,
  /** 震荡：一次潜行里打到浪头的伤害攒到最大耐久的 full 就震出来；浪头伤害 × wave 记到钻头；浪头 fuelR 米内油料殉爆 +fuel；每轮下潜清零 */
  conc: { full: 0.05, wave: 0.3, fuel: 0.5, fuelR: 10 },
