interface Seg {
  g: THREE.Group;
  len: number;
  /** 额外的抬高（破土拱出来 / 沉下去，按弹簧走）、侧翻角度；delay = 晚几秒才开始拱（一节接一节） */
  lift: number;
  liftTo: number;
  liftV: number;
  roll: number;
  rollTo: number;
  delay: number;
  car: Car | null;
}

interface Slot {
  id: string;
  hp: number;
  max: number;
  e: Enemy | null;
  anchor: THREE.Object3D;
  r: number;
  mult: number;
  dead: boolean;
  core: boolean;
}

const v1 = new THREE.Vector3();
const v2 = new THREE.Vector3();
