export class Drill extends Boss {
  readonly name = '钻地机车「穿山」';
  /** 首领镜头：放平、拉远（同轰天 / 云垒） */
  override readonly cameraTilt = -0.85;
  override readonly cameraZoom = 0.85;
  override readonly cameraRange = 220;
  override readonly engageDist = 40;
  override readonly showNear = 75;
  protected override readonly showR = 12;
  protected override readonly showY = 2;
  protected override readonly stunOnLoss = false;
  protected override readonly followGround = false;

  private readonly segs: Seg[] = [];
  private readonly cars: Car[] = [];
  private readonly slots: Slot[] = [];
  private readonly core: Slot;
  private readonly vents: Slot[] = [];
  /** 浪头：潜行时登记的部件（打它攒震荡，伤害 × 0.3 记到钻头） */
  private wave: Enemy | null = null;
  private readonly waveAt = new THREE.Object3D();
  /** 钻头尖走过的路（trail[0] = 钻头尖），车厢跟着走；cum = 每个点离钻头尖的路程 */
  private readonly trail: THREE.Vector3[] = [];
  private readonly cum: number[] = [];
  private readonly tip = new THREE.Vector3();
  /** 钻头朝向（水平，弧度） */
  private yaw = 0;
  private act: Act = 'intro';
  private actT = 0;
  /** 这一轮潜行几秒、绕圈几秒、往哪边绕；震荡（1 = 满） */
  private prowlT = 5;
  private circleT = 2;
  private circleDir = 1;
  private conc = 0;
  /** 锁住的点、竖起来的起点、砸下去的点、砸下去那条弧的控制点 */
  private readonly lockAt = new THREE.Vector3();
  private readonly riseFrom = new THREE.Vector3();
  private readonly slamAt = new THREE.Vector3();
  private readonly ctrl = new THREE.Vector3();
  /** 窗口还剩几秒、这次窗口钻进了油料（+2 秒） */
  private winT = 0;
  private baitHit = false;
  private chainN = 0;
  private round = 0;
  private minionT = 10;
  private troopsOut: Enemy[] = [];
  /** 停车线（世界 z）：坦克开到这里停下 */
  private readonly lineZ: number;
  /** 阶段三：冲锋方向、还能冲多远、这一冲撞上过你没有 */
  private readonly dir = new THREE.Vector3();
  private chargeLeft = 0;
  private hitTank = false;
  /** 刀盘（正转 / 反转）、散热口、震荡圈、沙浪、钻头烧红 */
  private readonly teethA: THREE.Mesh;
  private readonly teethB: THREE.Mesh;
  private readonly ring: THREE.Mesh<THREE.RingGeometry, THREE.ShaderMaterial>;
  private readonly ridge: THREE.Mesh;
  private readonly heatMat: THREE.MeshBasicMaterial;
  private heat = 0;
  private spinA = 0;
  /** 甩在路上的车厢残骸（阶段三撞上卡 5 秒，结局一起炸） */
  private readonly drops: Seg[] = [];
  /** 结局：放了几秒、哪几节还没炸、钻头飞起来 */
  private endT = -1;
  private readonly blasts: { seg: Seg; t: number; done: boolean }[] = [];
  private headFly: { v: THREE.Vector3; spin: THREE.Vector3; land: THREE.Vector3; landed: boolean } | null = null;
  private readonly roof: THREE.Mesh;
  /** 转场去哪个阶段；躺平时躺在哪一侧（x） */
  private transTo = 0;
  private lieX = 0;
  /** 提示条弹过没有（首次遭遇 / 第一次锁你 / 第一次震出来 / 开场有油料） */
  private readonly told = { intro: false, lock: false, flip: false, bait: false };

  constructor(ctx: BossContext, x: number, z: number) {
    super(ctx, x, z);
    // 车身按世界坐标摆：root 放回原点（甩下来的车厢、残骸都挂在它下面）
    this.root.position.set(0, 0, 0);
    this.lineZ = z + 90 - DRILL.line;
    const hp = ctx.hpScale;
    const head = this.group(this.root, 0, 0, 0);
    this.mesh(head, 'drill-head', headParts);
    this.teethA = this.mesh(head, 'drill-teeth-a', teethA);
    this.teethB = this.mesh(head, 'drill-teeth-b', teethB);
    head.add(new THREE.Mesh(ctx.geo.merged('drill-vents', ventParts), new THREE.MeshBasicMaterial({ vertexColors: true, toneMapped: false })));
    this.heatMat = new THREE.MeshBasicMaterial({ color: 0xff6a1a, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false });
    const heat = new THREE.Mesh(new THREE.ConeGeometry(4.55, 7.6, 12).rotateX(HALF), this.heatMat);
    heat.position.set(0, 0, 4.8);
    head.add(heat);
    this.segs.push({ g: head, len: DRILL.len.head, lift: 0, liftTo: 0, liftV: 0, roll: 0, rollTo: 0, delay: 0, car: null });
    const coreAt = new THREE.Object3D();
    coreAt.position.set(0, 0, 0.6);
    head.add(coreAt);
    this.core = { id: 'core', hp: DRILL.hp.core * hp, max: DRILL.hp.core * hp, e: null, anchor: coreAt, r: 4.6, mult: 1, dead: false, core: true };
    this.slots.push(this.core);
    for (let i = 0; i < 3; i++) {
      const a = new THREE.Object3D();
      a.position.set(0, -4.6, [-1.6, -4.0, -6.4][i]);
      head.add(a);
      const s: Slot = { id: `vent${i}`, hp: DRILL.hp.vent * hp, max: DRILL.hp.vent * hp, e: null, anchor: a, r: 1.6, mult: DRILL.mult.vent, dead: false, core: false };
      this.vents.push(s);
      this.slots.push(s);
    }
    // 车厢装载：弹药 2 / 油料 1 / 运兵 2 / 空 1，每局随机排（6 节 180 种排法）
    const loads: Load[] = ['ammo', 'ammo', 'fuel', 'troop', 'troop', 'empty'];
    for (let i = loads.length - 1; i > 0; i--) {
      const j = Math.floor(rng.boss() * (i + 1));
      [loads[i], loads[j]] = [loads[j], loads[i]];
    }
    for (let i = 0; i < 6; i++) {
      const g = this.group(this.root, 0, 0, 0);
      const load = loads[i];
      const chimney = i === 0 || i === 2 || i === 4;
      this.mesh(g, `drill-car-${load}-${chimney ? 1 : 0}-${i === 0 ? 1 : 0}`, () => carParts(load, chimney, i === 0));
      const a = new THREE.Object3D();
      a.position.set(0, 0, DRILL.len.car / 2 + 0.6);
      g.add(a);
      const slot: Slot = { id: `car${i}`, hp: DRILL.hp.car * hp, max: DRILL.hp.car * hp, e: null, anchor: a, r: 3.2, mult: DRILL.mult.car, dead: false, core: false };
      this.slots.push(slot);
      const car: Car = { i, load, slot, dead: false, dropped: false, done: false, door: -1, burn: 0 };
      this.cars.push(car);
      this.segs.push({ g, len: DRILL.len.car, lift: 0, liftTo: 0, liftV: 0, roll: 0, rollTo: 0, delay: 0, car });
    }
    // 震荡圈 + 沙浪 + 结局里掀上天的车顶板（一块模板，按需抛出去）
    this.ring = new THREE.Mesh(new THREE.RingGeometry(0.2, 1, 48, 1).rotateX(-HALF), new THREE.ShaderMaterial({ vertexShader: RING_VERT, fragmentShader: RING_FRAG, uniforms: { uK: { value: 0 }, uT: { value: 0 } }, transparent: true, depthWrite: false }));
    this.ring.renderOrder = 3;
    this.ring.visible = false;
    ctx.scene.add(this.ring);
    this.ridge = new THREE.Mesh(new THREE.SphereGeometry(1, 16, 6, 0, Math.PI * 2, 0, HALF), new THREE.MeshStandardMaterial({ color: 0xb8946a, roughness: 1 }));
    this.ridge.receiveShadow = true;
    this.ridge.visible = false;
    ctx.scene.add(this.ridge);
    this.roof = new THREE.Mesh(box(6, 0.3, 9), enemyPaint());
    this.roof.visible = false;
    this.root.add(this.roof);
    // 开场：沙浪在车前 90 米迎着你冲过来，车身全在沙下
    this.tip.set(THREE.MathUtils.clamp(x, -8, 8) + (rng.boss() < 0.5 ? -6 : 6), DRILL.deep, z);
    this.layLine(this.tip, 0, 0, 0);
    this.arena();
    this.pose(0);
  }

  // ---------------------------------------------------------- 车身跟着钻头尖走

  /** 从钻头尖往后铺一条路（yaw = 钻头朝向）：前 surface 米和钻头尖一样高、再 dip 米斜着钻到 deep、之后一直在 deep（都不给 = 整条和钻头尖一样高） */
  private layLine(tip: THREE.Vector3, yaw: number, surface: number, dip: number): void {
    this.trail.length = 0;
    const bx = -Math.sin(yaw);
    const bz = -Math.cos(yaw);
    const total = this.bodyLen() + 30;
    const flat = surface <= 0 && dip <= 0;
    for (let s = 0; s <= total; s += 1) {
      let y = tip.y;
      if (!flat && s > surface) y = s <= surface + dip ? tip.y + (DRILL.deep - tip.y) * ((s - surface) / dip) : DRILL.deep;
      this.trail.push(new THREE.Vector3(tip.x + bx * s, y, tip.z + bz * s));
    }
  }

  /** 车身多长（甩掉的车厢不算） */
  private bodyLen(): number {
    let n = DRILL.len.head;
    for (const s of this.segs) if (s.car && !s.car.dropped) n += s.len + DRILL.len.gap;
    return n;
  }

  /** 钻头尖挪到 tip（记进路里：离上一个点 0.8 米以上才插一个点） */
  private moveTip(): void {
    const t = this.trail;
    if (!t.length) t.push(this.tip.clone());
    t[0].copy(this.tip);
    if (t.length < 2 || t[0].distanceTo(t[1]) > 0.8) t.splice(1, 0, this.tip.clone());
    const keep = Math.ceil((this.bodyLen() + 40) / 0.8);
    if (t.length > keep) t.length = keep;
  }

  /** 路上离钻头尖 s 米那一点（超出记下的路就顺着最后一段往外推） */
  private sample(s: number, out: THREE.Vector3): THREE.Vector3 {
    const t = this.trail;
    const c = this.cum;
    for (let i = 1; i < t.length; i++) {
      if (c[i] >= s) {
        const k = (s - c[i - 1]) / Math.max(1e-6, c[i] - c[i - 1]);
        return out.copy(t[i - 1]).lerp(t[i], k);
      }
    }
    const n = t.length;
    if (n < 2) return out.copy(t[0] ?? this.tip);
    const d = v3.copy(t[n - 1]).sub(t[n - 2]).normalize();
    return out.copy(t[n - 1]).addScaledVector(d, s - c[n - 1]);
  }

  /** 每一节按路摆好：中心、朝向（车头朝钻头那边）、侧翻、额外抬高（弹簧） */
  private pose(dt: number): void {
    const t = this.trail;
    this.cum.length = t.length;
    this.cum[0] = 0;
    for (let i = 1; i < t.length; i++) this.cum[i] = this.cum[i - 1] + t[i].distanceTo(t[i - 1]);
    let s = 0;
    for (const seg of this.segs) {
      if (seg.car?.dropped) continue;
      if (seg.delay > 0) seg.delay -= dt;
      else {
        seg.liftV += ((seg.liftTo - seg.lift) * 40 - seg.liftV * 9) * dt;
        seg.lift += seg.liftV * dt;
        seg.roll += (seg.rollTo - seg.roll) * Math.min(1, dt * 5);
      }
      const a = this.sample(s, v1);
      const b = this.sample(s + seg.len, v2);
      seg.g.position.copy(a).add(b).multiplyScalar(0.5);
      seg.g.position.y += seg.lift;
      const dx = a.x - b.x;
      const dy = a.y - b.y;
      const dz = a.z - b.z;
      seg.g.rotation.set(-Math.atan2(dy, Math.hypot(dx, dz)), Math.atan2(dx, dz), seg.roll, 'YXZ');
      s += seg.len + DRILL.len.gap;
    }
  }

  /** 所有还挂在车上的节：抬高 / 侧翻的目标（from = 从多低拱出来，0 = 不动；stagger = 一节比一节晚几秒） */
  private heave(from: number, stagger: number, roll = 0, rollN = 0): void {
    this.segs.forEach((seg, i) => {
      if (seg.car?.dropped) return;
      if (from) {
        seg.lift = from;
        seg.liftV = 0;
      }
      seg.liftTo = 0;
      seg.delay = i * stagger;
      seg.rollTo = i < rollN ? roll : 0;
    });
  }

  // ---------------------------------------------------------- 首领场地：油料诱饵 + 硬东西

  /**
   * 场地（策划 2.8 节，三种布局抽签；「车前米数 / 横向」，停车线为 0）：加油车 4 + 油桶垛 4 + 路边磕头机 4（诱饵，炸一个少一个）、风化石柱 2 + 半埋残骸 2（阶段三撞上就卡住）。
   * 这一段先清掉随机路障 / 掩体 / 景物 / 油田大件，再按布局摆（摆的那一下扬一团沙）
   */
  private arena(): void {
    const w = this.ctx.world;
    const L = this.lineZ;
    w.keepOut(L + 20, L - 48, [-20, 20]);
    w.clearKeep();
    const pick = Math.floor(rng.boss() * 3);
    const T: [number, number][][] = [
      [[12, -10], [12, 10], [28, -6], [28, 6]],
      [[6, -12], [18, 8], [30, -8], [-6, 12]],
      [[8, -14], [20, -14], [30, -12], [-4, -10]],
    ];
    const B: [number, number][][] = [
      [[-8, -13], [-8, 13], [20, 0], [32, 0]],
      [[0, 0], [24, -14], [12, 15], [32, 2]],
      [[14, 12], [26, 6], [2, 14], [-12, 0]],
    ];
    const pop = (x: number, z: number) => {
      for (let i = 0; i < 3; i++) this.ctx.fx.dust(x + (Math.random() - 0.5) * 3, z + (Math.random() - 0.5) * 3, 2.6, 0xb89a76, 0.5);
    };
    for (const [a, x] of T[pick]) {
      w.placeArena('truckProp', x, L - a, true);
      pop(x, L - a);
    }
    for (const [a, x] of B[pick]) {
      w.placeArena('barrels', x, L - a);
      pop(x, L - a);
    }
    for (const x of [-11, 11]) w.placeArena('car', x, L + 14);
    for (const [a, x] of [[0, -17.5], [0, 17.5], [24, -18], [24, 18]] as [number, number][]) w.oil.placeAt('jack', x, L - a);
    w.oil.placeAt('pillar', -19, L - 10, rng.boss() * 6, 10);
    w.oil.placeAt('pillar', 19, L - 30, rng.boss() * 6, 11);
  }

  // ---------------------------------------------------------- 部件（只在窗口里登记）

  /** 部件进窗口：登记成敌人（耐久接着上次剩下的），mult = 这个窗口的倍率 */
  private open(s: Slot, mult: number): void {
    s.mult = mult;
    if (s.dead || s.e) return;
    this.root.updateMatrixWorld(true);
    s.anchor.getWorldPosition(v1);
    const spec: EnemySpec = {
      hp: s.max, speed: 0, radius: s.r, contactDamage: 0, fireInterval: 0, shot: 'none', bulletDamage: 0, bulletSpeed: 0,
      scrap: s.core ? 40 : 10, standoff: 0, crushable: false, blocker: true, fixed: true, armor: s.core ? 'heavy' : 'light', threat: ENEMY_SPECS.part.threat,
    };
    const e = this.ctx.spawnPart(spec, v1.x, v1.z);
    if (!e) return;
    e.controller = this;
    e.hp = s.hp;
    s.e = e;
    this.parts.push({ e, anchor: s.anchor, core: s.core, visual: null, dead: false, label: s.id });
  }

  /** 部件出窗口：耐久记下来、敌人收掉 */
  private close(s: Slot): void {
    const e = s.e;
    if (!e) return;
    s.e = null;
    s.hp = Math.max(1, e.hp);
    e.kill();
    const i = this.parts.findIndex((p) => p.e === e && !p.dead);
    if (i >= 0) this.parts.splice(i, 1);
  }

  private closeAll(): void {
    for (const s of this.slots) this.close(s);
  }

  /** 浪头（潜行时）：打它攒震荡；耐久每帧补满，掉的那一截 × 0.3 记到钻头 */
  private openWave(): void {
    if (this.wave) return;
    const spec: EnemySpec = {
      hp: WAVE_HP, speed: 0, radius: 2.8, contactDamage: 0, fireInterval: 0, shot: 'none', bulletDamage: 0, bulletSpeed: 0,
      scrap: 0, standoff: 0, crushable: false, blocker: true, fixed: true, armor: 'light', threat: ENEMY_SPECS.part.threat,
    };
    const e = this.ctx.spawnPart(spec, this.tip.x, this.tip.z);
    if (!e) return;
    e.controller = this;
    this.wave = e;
    this.parts.push({ e, anchor: this.waveAt, core: false, visual: null, dead: false, label: 'wave' });
  }

  private closeWave(): void {
    const e = this.wave;
    this.ring.visible = false;
    this.ridge.visible = false;
    if (!e) return;
    this.wave = null;
    e.kill();
    const i = this.parts.findIndex((p) => p.e === e && !p.dead);
    if (i >= 0) this.parts.splice(i, 1);
  }

  /** 首领总耐久比例（按自己记的，部件开着就读活的） */
  override hpRatio(): number {
    let hp = 0;
    let max = 0;
    for (const s of this.slots) {
      max += s.max;
      if (!s.dead) hp += Math.max(0, s.e ? s.e.hp : s.hp);
    }
    return max > 0 ? hp / max : 0;
  }

  private get maxHp(): number {
    let m = 0;
    for (const s of this.slots) m += s.max;
    return m;
  }

  /** 直接扣钻头（油料殉爆 / 石柱砸 / 弹药车厢）：按最大耐久的比例；开着就走部件（打掉照常结算），没开着最少留 1 */
  private hurtCore(k: number): void {
    const amount = this.maxHp * k;
    if (this.core.e?.alive) this.ctx.hurt?.(this.core.e, amount);
    else this.core.hp = Math.max(1, this.core.hp - amount);
  }

  /** 核心替身（核弹 / 天火 / 自动瞄准）：钻头开着就是钻头，潜行时是浪头 */
  override get coreEnemy(): Enemy | null {
    if (this.core.e?.alive) return this.core.e;
    return this.wave?.alive ? this.wave : null;
  }

  /** 窗口倍率：钻头按窗口（自己钻出来 × 1 / 震出来 × 1.5 / 躺平 × 1 / 卡住 × 2），散热口 × 2，车厢节 × 1.5；究极打到浪头 = 震荡直接满 */
  override damageMul(part: Enemy): number {
    if (part === this.wave) {
      if (dmgSrc.cur === 'ult') this.conc = Math.max(this.conc, 1);
      return 1;
    }
    const s = this.slots.find((x) => x.e === part);
    return s ? s.mult : 1;
  }

  override onPartKilled(e: Enemy): void {
    const s = this.slots.find((x) => x.e === e);
    if (!s) return;
    if (s.core) {
      s.dead = true;
      s.hp = 0;
      super.onPartKilled(e);
      s.e = null;
      this.startEnd();
      return;
    }
    const p = this.parts.find((x) => x.e === e && !x.dead);
    if (p) p.dead = true;
    s.dead = true;
    s.hp = 0;
    s.e = null;
    const ctx = this.ctx;
    this.root.updateMatrixWorld(true);
    s.anchor.getWorldPosition(v1);
    ctx.fx.explosion(v1.x, v1.z, 2.6, Math.max(1, v1.y));
    ctx.audio.play('bigboom');
    ctx.shake(0.6);
    if (s.id.startsWith('vent')) {
      // 散热口拆掉：喷一股白汽，之后每个窗口 +1 秒
      for (let i = 0; i < 8; i++) ctx.fx.steam(v1.x, Math.max(1, v1.y) + i * 0.3, v1.z);
      if (this.vents.every((x) => x.dead)) ctx.announce('散热口全拆了', '以后窗口更长');
      return;
    }
    const car = this.cars.find((c) => c.slot === s);
    if (car) this.carDown(car);
  }

  /** 车厢打瘫：装载效果——弹药殉爆（前后两节吃 150、钻头掉 3%，弹药挨着一炸一串）/ 油料往前后喷火 4 秒 + 地上一条火 / 运兵不再放兵 */
  private carDown(car: Car): void {
    if (car.dead) return;
    car.dead = true;
    car.slot.dead = true;
    car.slot.hp = 0;
    if (car.slot.e) {
      const e = car.slot.e;
      car.slot.e = null;
      e.kill();
      const i = this.parts.findIndex((p) => p.e === e && !p.dead);
      if (i >= 0) this.parts.splice(i, 1);
    }
    const ctx = this.ctx;
    const g = this.segOf(car).g;
    g.getWorldPosition(v1);
    const y = Math.max(1.5, v1.y + 1);
    ctx.fx.smoke(v1.x, y + 2, v1.z, 2.4, 4, 0x24201e, 0.7);
    if (car.load === 'ammo') {
      ctx.fx.explosion(v1.x, v1.z, 4.5, y + 1);
      ctx.fx.flash(v1.x, y + 4, v1.z, 4000);
      for (let i = 0; i < 6; i++) ctx.fx.column(v1.x + (Math.random() - 0.5) * 4, y + i * 1.6, v1.z + (Math.random() - 0.5) * 4, 2.2, 1);
      ctx.debris.chunks(v1.x, y + 2, v1.z, 8, 'metal', 1.6);
      ctx.audio.play('bigboom');
      ctx.shake(0.9);
      this.hurtCore(DRILL.bait.ammo);
      // 前后两节吃 150（× 血量倍率）；挨着的弹药车厢跟着炸
      for (const n of this.cars) if (!n.dead && !n.dropped && Math.abs(n.i - car.i) === 1) this.hurtCar(n, DRILL.hp.car * ctx.hpScale);
      ctx.announce('弹药车厢殉爆', '');
    } else if (car.load === 'fuel') {
      car.burn = 4;
      ctx.fx.explosion(v1.x, v1.z, 3.4, y);
      ctx.audio.play('bigboom', 0.8);
      for (let i = -1; i <= 1; i++) ctx.hazards.fire(v1.x + Math.sin(this.yaw) * i * 4, v1.z + Math.cos(this.yaw) * i * 4, 3, 6, 12, 'neutral');
    } else ctx.fx.explosion(v1.x, v1.z, 2.4, y);
  }

  /** 车厢节吃一下（开着走部件、没开着直接扣，扣光了打瘫） */
  private hurtCar(c: Car, amount: number): void {
    if (c.slot.e?.alive) this.ctx.hurt?.(c.slot.e, amount);
    else {
      c.slot.hp -= amount;
      if (c.slot.hp <= 0) this.carDown(c);
    }
  }

  private segOf(c: Car): Seg {
    return this.segs.find((s) => s.car === c)!;
  }

  // ---------------------------------------------------------- 主循环

  /** 你这辆车上一帧在哪、速度（锁点按你的车速外推） */
  private readonly lastP = new THREE.Vector3();
  private readonly pv = new THREE.Vector3();

  override update(delta: number): void {
    this.t += delta;
    if (this.dead) {
      this.stepEnd(delta);
      return;
    }
    const P = this.target;
    if (delta > 0) this.pv.set((P.x - this.lastP.x) / delta, 0, (P.z - this.lastP.z) / delta).clampLength(0, 20);
    this.lastP.copy(P);
    // 阶段：剩 66% 进二、剩 33% 进三（一次只往前走一段；窗口 / 冲锋中途不打断，下潜 / 潜行 / 转向时插转场）
    const ratio = this.hpRatio();
    const want = ratio <= 1 / 3 ? 2 : ratio <= 2 / 3 ? 1 : 0;
    if (want > this.phase && this.calmAct()) this.startTrans(this.phase + 1);
    this.step(delta);
    this.pose(delta);
    this.stepFx(delta);
    // 部件跟着模型走；浪头跟着钻头尖
    this.waveAt.position.set(this.tip.x, 0, this.tip.z);
    this.root.updateMatrixWorld(true);
    for (const p of this.parts) {
      if (p.dead || !p.e.alive) continue;
      p.anchor.getWorldPosition(v1);
      p.e.group.position.set(v1.x, 0, v1.z);
    }
    this.stepWave();
    this.stepCars(delta);
  }

  private calmAct(): boolean {
    return this.act === 'prowl' || this.act === 'dive' || this.act === 'sink' || this.act === 'turn' || this.act === 'slide' || this.act === 'chainGap';
  }

  protected step(dt: number): void {
    this.actT += dt;
    const P = this.target;
    switch (this.act) {
      case 'intro':
        // 沙浪迎着你冲过来，进到车前 48 米开始第一轮
        this.steer(P.x * 0.4, P.z - 40, 18, dt, DRILL.deep);
        if (this.tip.z > P.z - 48 || this.actT > 6) this.startProwl(true);
        break;
      case 'prowl':
        this.stepProwl(dt, P);
        break;
      case 'lock':
        // 烟囱缩回去（再往下沉）、钻头尖挪到锁住的点底下；流沙圈预警完就破土
        this.steer(this.lockAt.x, this.lockAt.z + 3, 9, dt, DRILL.deep - 3);
        this.stepQuicksand(dt);
        if (this.actT >= DRILL.lock.retract + DRILL.lock.warn) this.startRise();
        break;
      case 'rise': {
        const k = Math.min(1, this.actT / DRILL.burst.rise);
        this.tip.lerpVectors(this.riseFrom, v1.set(this.lockAt.x, DRILL.burst.apex, this.lockAt.z - 3), k * k * (3 - 2 * k));
        this.moveTip();
        if (k >= 1) this.go('hold');
        break;
      }
      case 'hold':
        if (this.actT >= DRILL.burst.hold) {
          this.riseFrom.copy(this.tip);
          const B = DRILL.burst;
          // 斜着砸过路面（侧面朝着你，钻头那一头不被车厢挡住）：扎在路的另一边
          const side = this.lockAt.x > 0 ? -1 : 1;
          this.slamAt.set(side * B.side, -2.6, P.z - (B.ahead[0] + rng.boss() * (B.ahead[1] - B.ahead[0])));
          this.ctrl.set(this.lockAt.x, B.apex + 3, (this.riseFrom.z + this.slamAt.z) / 2);
          this.go('slam');
        }
        break;
      case 'slam': {
        // 往前砸下去：二次贝塞尔弧，钻头扎进车前 15～22 米的沙里，钻头节 + 第 1 节拱成一道桥
        const k = Math.min(1, this.actT / DRILL.burst.slam);
        const e = k * k;
        const a = 1 - e;
        const f = this.riseFrom;
        const c = this.ctrl;
        const s = this.slamAt;
        this.tip.set(a * a * f.x + 2 * a * e * c.x + e * e * s.x, a * a * f.y + 2 * a * e * c.y + e * e * s.y, a * a * f.z + 2 * a * e * c.z + e * e * s.z);
        this.moveTip();
        if (k >= 1) this.slammed();
        break;
      }
      case 'bridge':
        this.winT -= dt;
        if (this.winT <= 0) this.startDive();
        break;
      case 'flip':
        this.winT -= dt;
        if (this.winT <= 0) {
          if (this.phase === 1) this.startLie();
          else this.startSink();
        }
        break;
      case 'dive':
        // 钻头接着往前钻进沙里，车厢一节节跟着从桥上钻下去
        this.steer(this.tip.x + Math.sin(this.yaw) * 20, this.tip.z + Math.cos(this.yaw) * 20, 18, dt, DRILL.deep);
        if (this.actT >= DRILL.dive) this.startProwl(false);
        break;
      case 'chainLock':
        this.steer(this.lockAt.x, this.lockAt.z + 2, 14, dt, DRILL.deep - 2);
        this.stepQuicksand(dt);
        if (this.actT >= DRILL.lock.warn2) this.chainBurst();
        break;
      case 'chainUp': {
        // 连钻：冒出来 8 米马上缩回去
        const k = this.actT / 0.9;
        const h = Math.sin(Math.min(1, k) * Math.PI);
        this.tip.set(this.lockAt.x, DRILL.deep - 2 + (10 - DRILL.deep) * h, this.lockAt.z - 1.5 * h);
        this.moveTip();
        if (k >= 1) {
          if (this.chainN >= DRILL.chain.n) this.startLie();
          else this.go('chainGap');
        }
        break;
      }
      case 'chainGap':
        this.steer(P.x, P.z - 8, 14, dt, DRILL.deep);
        if (this.actT >= DRILL.chain.gap - DRILL.lock.warn2) this.chainLock();
        break;
      case 'lie':
        this.winT -= dt;
        if (this.winT <= 0) this.startSink();
        break;
      case 'sink':
        if (this.actT >= DRILL.sink) {
          this.resurface();
          this.startProwl(false);
        }
        break;
      case 'trans':
        if (this.actT >= DRILL.trans) this.endTrans();
        break;
      case 'turn':
        this.stepTurn(dt, P);
        break;
      case 'warn':
        if (this.actT >= DRILL.charge.warn) {
          this.go('charge');
          this.ctx.audio.play('bigboom', 0.6, 0.7);
        }
        break;
      case 'charge':
        this.stepCharge(dt, P);
        break;
      case 'stuck':
        this.winT -= dt;
        if (this.winT <= 0) {
          this.closeAll();
          this.segs[0].liftTo = 0;
          this.dropDead();
          this.go('turn');
        }
        break;
      case 'slide':
        this.slideOn(dt);
        if (this.actT >= DRILL.stuck.miss) {
          this.closeAll();
          this.go('turn');
        }
        break;
    }
  }

  private go(a: Act): void {
    this.act = a;
    this.actT = 0;
  }

  /** 钻头尖朝 (gx, gz) 拐过去（转弯半径 ≥ prowl.turn）、以 v 米/秒走，深度往 y 靠；不出车道 */
  private steer(gx: number, gz: number, v: number, dt: number, y: number): void {
    const want = Math.atan2(gx - this.tip.x, gz - this.tip.z);
    const d = Math.atan2(Math.sin(want - this.yaw), Math.cos(want - this.yaw));
    const maxTurn = (v / DRILL.prowl.turn) * dt;
    this.yaw += THREE.MathUtils.clamp(d, -maxTurn, maxTurn);
    this.tip.x += Math.sin(this.yaw) * v * dt;
    this.tip.z += Math.cos(this.yaw) * v * dt;
    this.tip.x = THREE.MathUtils.clamp(this.tip.x, -DRILL.prowl.lane, DRILL.prowl.lane);
    this.tip.y += (y - this.tip.y) * Math.min(1, dt * 3);
    this.moveTip();
  }

  // ---------------------------------------------------------- 阶段一 / 二：潜行、锁定、钻出来

  /** 新一轮潜行（每轮清零震荡）：进场方向抽签（正前方五成、左右路肩各两成、身后一成，前两轮不从身后来） */
  private startProwl(first: boolean): void {
    if (this.phase === 2) return this.startTurnPhase();
    this.go('prowl');
    this.round += 1;
    this.conc = 0;
    (this.ring.material.uniforms.uK as { value: number }).value = 0;
    const [a, b] = this.phase === 1 ? DRILL.chain.prowl : DRILL.prowl.t;
    this.prowlT = a + rng.boss() * (b - a);
    this.circleT = this.prowlT * (0.3 + rng.boss() * 0.35);
    this.circleDir = rng.boss() < 0.5 ? -1 : 1;
    const P = this.target;
    if (!first && this.tip.y < 0) {
      // 换个地方冒头（下潜那段已经在沙下，直接挪过去，看不见）
      const r = rng.boss();
      const behind = r > 0.9 && this.round > 2;
      const side = !behind && r > 0.5 ? (r > 0.7 ? 1 : -1) : 0;
      const x = side ? side * 15 : THREE.MathUtils.clamp(P.x + (rng.boss() - 0.5) * 10, -12, 12);
      const z = behind ? P.z + 10 : side ? P.z - 28 : P.z - (50 + rng.boss() * 10);
      // 车身还在桥上 / 地面上的那几节先让它跟着钻下去，路不重铺
      if (!this.bodyUp()) {
        this.tip.set(x, DRILL.deep, z);
        this.yaw = Math.atan2(P.x - x, P.z - z);
        this.layLine(this.tip, this.yaw, 0, 0);
      }
    }
    this.openWave();
    this.ring.visible = true;
    this.ridge.visible = true;
    if (!this.told.intro) {
      this.told.intro = true;
      this.ctx.announce(this.name, '打沙浪，把它震出来');
    } else if (this.phase === 0 && !this.told.bait) {
      this.told.bait = true;
      this.ctx.announce('靠着油车油桶', '引它来钻');
    }
  }

  /** 车身还有露在地面上的节没有 */
  private bodyUp(): boolean {
    for (const s of this.segs) if (!s.car?.dropped && s.g.position.y > -1) return true;
    return false;
  }

  private stepProwl(dt: number, P: THREE.Vector3): void {
    const D = DRILL.prowl;
    const v = D.speed[this.phase === 1 ? 1 : 0];
    // 阶段一每 14 秒一个小包（场上最多 1 个）
    if (this.phase === 0 && (this.minionT -= dt) <= 0) {
      this.minionT = DRILL.minion.every;
      if ((this.ctx.ambushCount?.() ?? 1) < 1) this.ctx.ambushSmall?.();
    }
    if (this.conc >= 1) return this.knockOut();
    if (this.actT < this.circleT) {
      // 绕着你兜（离你 18～24 米），不从你正下方擦过
      const ang = Math.atan2(this.tip.x - P.x, this.tip.z - P.z) + this.circleDir * 0.6;
      const r = (D.r[0] + D.r[1]) / 2;
      this.steer(P.x + Math.sin(ang) * r, P.z + Math.cos(ang) * r, v, dt, DRILL.deep);
      return;
    }
    // 冲你：进到 10 米锁定（潜行时间到了也锁）
    this.steer(P.x, P.z, D.rush, dt, DRILL.deep);
    const dist = Math.hypot(this.tip.x - P.x, this.tip.z - P.z);
    if (dist < D.lock || this.actT > this.prowlT + 3) {
      if (this.phase === 1) {
        this.chainN = 0;
        this.chainLock();
      } else this.startLock();
    }
  }

  /** 锁你（阶段一）：烟囱一缩，按你 1 秒后的位置锁住，脚下一圈流沙 1.5 秒（红圈，T130 起和别的敌方预警一样，原来深褐） */
  private startLock(): void {
    const L = DRILL.lock;
    this.go('lock');
    this.closeWave();
    this.lockOn(L.lead);
    this.ctx.hazards.marker(this.lockAt.x, this.lockAt.z, L.r, L.retract + L.warn, 'enemy');
    this.ctx.audio.play('crunch', 0.8, 0.6);
    if (!this.told.lock) {
      this.told.lock = true;
      this.ctx.announce('烟囱一缩', '它要钻出来');
    }
  }

  /** 锁点：按你现在的车速外推 lead 秒（压在车道里） */
  private lockOn(lead: number): void {
    const P = this.target;
    this.lockAt.set(THREE.MathUtils.clamp(P.x + this.pv.x * lead, -15, 15), 0, P.z + this.pv.z * lead);
  }

  /** 流沙圈：沙子往中间流、外圈扬尘 */
  private stepQuicksand(dt: number): void {
    const f = this.ctx.fx;
    const L = this.lockAt;
    if (Math.random() < dt * 16) {
      const a = Math.random() * Math.PI * 2;
      const r = DRILL.lock.r * (0.7 + Math.random() * 0.4);
      f.smokeP.emit({ x: L.x + Math.cos(a) * r, y: 0.4, z: L.z + Math.sin(a) * r, vx: -Math.cos(a) * 2.5, vy: 0.4, vz: -Math.sin(a) * 2.5, life: 1, size: 0.8, size1: 1.8, color: 0xb89a76, alpha: 0.55, frame: 1, drag: 0.8 });
    }
    if (Math.random() < dt * 4) f.dust(L.x + (Math.random() - 0.5) * 8, L.z + (Math.random() - 0.5) * 8, 2.4, 0xa88a66, 0.4);
  }

  /** 破土：钻头 70° 冲出地面竖到 14 米 */
  private startRise(): void {
    this.go('rise');
    this.riseFrom.set(this.lockAt.x, DRILL.deep - 3, this.lockAt.z + 3);
    this.tip.copy(this.riseFrom);
    this.moveTip();
    this.baitHit = this.breach(this.lockAt.x, this.lockAt.z, DRILL.lock.dmg, DRILL.lock.push);
  }

  /** 破土那一下：沙柱、坑（不消失，同一处再钻只往下探）、掀起一块碎石岩板、砸碎路障、震出伏兵；流沙圈里的挨打 + 推开；圈里有油料 = 当场殉爆炸在它头上 */
  private breach(x: number, z: number, dmg: number, push: number): boolean {
    const ctx = this.ctx;
    const f = ctx.fx;
    const P = this.target;
    for (let i = 0; i < 16; i++) {
      const a = Math.random() * Math.PI * 2;
      f.smokeP.emit({ x: x + Math.cos(a) * 2, y: 0.8, z: z + Math.sin(a) * 2, vx: Math.cos(a) * 3, vy: 8 + Math.random() * 7, vz: Math.sin(a) * 3, life: 1.6, size: 1.4, size1: 4, color: 0xd8c09a, color1: 0xa88a66, alpha: 0.75, frame: 1, gravity: -8, drag: 0.5 });
    }
    f.shockwave(x, z, 14, 0xd8c098, 0.6);
    ctx.world.crater(x, z, 4.5, 1.2, 0.4, 7, 0.35, 3);
    ctx.smash?.(x, z, 5, 26);
    ctx.quake?.(x, z, 8);
    ctx.audio.play('breach');
    ctx.audio.play('bigboom', 0.6);
    ctx.shake(0.9);
    if (dmg > 0) {
      ctx.world.placeArena('rubble', THREE.MathUtils.clamp(x + (rng.boss() < 0.5 ? -4.5 : 4.5), -15, 15), z + (rng.boss() - 0.5) * 3);
      if (Math.hypot(P.x - x, P.z - z) < DRILL.lock.r + 1.8) {
        ctx.damagePlayer(dmg / 1.2, P);
        ctx.push?.(x, z, push, P);
      }
    }
    const bait = ctx.fuelAt?.(x, z, DRILL.lock.r) ?? false;
    if (bait) {
      this.hurtCore(DRILL.bait.fuel);
      ctx.announce('钻进油料里了', '窗口多 2 秒');
    }
    return bait;
  }

  /**
   * 砸下去：扎下去那点一个坑、砸碎路障；钻头节 + 第 1 节拱成一道桥（离地约 10 米），卡 3 秒（钻头 × 1）。
   * 桥的后脚往前挪到你前方 arch 米（竖在你车头上的那一截会把镜头整个挡住）：后脚那里再扑一团沙
   */
  private slammed(): void {
    const ctx = this.ctx;
    const s = this.slamAt;
    const P = this.target;
    ctx.world.crater(s.x, s.z, 3.5, 1.0, 0.35, 5.5, 0.3, 3);
    ctx.smash?.(s.x, s.z, 4, 20);
    ctx.quake?.(s.x, s.z, 8);
    for (let i = 0; i < 6; i++) ctx.fx.dust(s.x + (Math.random() - 0.5) * 6, s.z + (Math.random() - 0.5) * 6, 3.4, 0xb89a76, 0.6);
    ctx.audio.play('breach', 0.8);
    ctx.shake(0.7);
    // 桥：钻头扎在 S，后脚 E 在你前方 arch 米，中间拱起来；E 往后照旧钻在沙下
    const ex = -Math.sign(s.x || 1) * DRILL.burst.side * 0.8;
    const ez = Math.max(P.z - DRILL.burst.arch, s.z + 8);
    this.trail.length = 0;
    for (let i = 0; i <= 40; i++) {
      const k = i / 40;
      this.trail.push(new THREE.Vector3(s.x + (ex - s.x) * k, s.y + (-4 - s.y) * k + Math.sin(k * Math.PI) * DRILL.burst.bridge, s.z + (ez - s.z) * k));
    }
    for (let d = 1; d < this.bodyLen() + 30; d += 1) this.trail.push(new THREE.Vector3(ex, Math.max(DRILL.deep, -4 - d), ez + d));
    this.tip.copy(this.trail[0]);
    for (let i = 0; i < 5; i++) ctx.fx.dust(ex + (Math.random() - 0.5) * 6, ez + (Math.random() - 0.5) * 4, 3.4, 0xb89a76, 0.6);
    ctx.world.crater(ex, ez, 3.8, 1.0, 0.35, 5.5, 0.3, 3);
    this.yaw = Math.atan2(s.x - ex, s.z - ez);
    this.go('bridge');
    this.winT = DRILL.win.burst + this.ventBonus() + (this.baitHit ? DRILL.win.fuel : 0);
    this.baitHit = false;
    this.open(this.core, DRILL.mult.burst);
  }

  /** 每拆掉一个散热口，之后每个窗口 +1 秒（最多 +3） */
  private ventBonus(): number {
    return Math.min(3, this.vents.filter((v) => v.dead).length) * DRILL.win.vent;
  }

  private startDive(): void {
    this.closeAll();
    this.dropDead();
    this.go('dive');
  }

  /** 震荡攒满：被震出地面侧翻 5 秒（阶段二 4 秒，然后直接躺平）；肚子朝上，散热口 × 2、钻头 × 1.5 */
  private knockOut(): void {
    const P = this.target;
    this.closeWave();
    // 位置压在你前后 −5～+45 米里、车道里；横着躺太宽的顺着路偏一点
    const x = THREE.MathUtils.clamp(this.tip.x, -10, 10);
    const z = THREE.MathUtils.clamp(this.tip.z, P.z - 45, P.z + 5);
    let yaw = this.yaw;
    if (Math.abs(Math.sin(yaw)) > 0.7) yaw = Math.atan2(Math.sign(Math.sin(yaw)) * 0.7, Math.cos(yaw) >= 0 ? 0.7 : -0.7);
    this.yaw = yaw;
    this.tip.set(x, DRILL.axis, z);
    this.layLine(this.tip, yaw, 40, 14);
    this.heave(-9, 0.08, (rng.boss() < 0.5 ? 1 : -1) * 2.5, 3);
    this.breach(x, z, 0, 0);
    this.go('flip');
    this.winT = (this.phase === 1 ? DRILL.win.flip2 : DRILL.win.flip) + this.ventBonus();
    this.open(this.core, DRILL.mult.flip);
    for (const v of this.vents) this.open(v, DRILL.mult.vent);
    this.ctx.announce(`${this.name}被震出来了`, this.told.flip ? '' : '震出来了，打肚子');
    this.told.flip = true;
  }

  /** 沉回沙里（躺平 / 侧翻以后）：一节节往下陷，扬沙 */
  private startSink(): void {
    this.closeAll();
    // 打瘫的车厢趁还在地面上甩下来
    this.dropDead();
    this.go('sink');
    this.segs.forEach((seg, i) => {
      seg.liftTo = -12;
      seg.liftV = -2;
      seg.delay = i * 0.1;
      seg.rollTo = 0;
    });
    const f = this.ctx.fx;
    for (const seg of this.segs) {
      if (seg.car?.dropped) continue;
      seg.g.getWorldPosition(v1);
      if (v1.y < -2) continue;
      for (let i = 0; i < 3; i++) f.dust(v1.x + (Math.random() - 0.5) * 8, v1.z + (Math.random() - 0.5) * 8, 4, 0xb89a76, 0.55);
    }
  }

  /** 沉下去以后：车身回到沙下（路铺在 deep），抬高 / 侧翻清零 */
  private resurface(): void {
    this.tip.y = DRILL.deep;
    this.layLine(this.tip, this.yaw, 0, 0);
    for (const seg of this.segs) {
      seg.lift = seg.liftTo = seg.liftV = 0;
      seg.roll = seg.rollTo = 0;
      seg.delay = 0;
    }
  }

  // ---------------------------------------------------------- 阶段二：连钻 + 躺平

  private chainLock(): void {
    const L = DRILL.lock;
    this.go('chainLock');
    this.closeWave();
    this.lockOn(L.lead2);
    this.ctx.hazards.marker(this.lockAt.x, this.lockAt.z, L.r, L.warn2, 'enemy');
    this.ctx.audio.play('crunch', 0.7, 0.7);
  }

  /** 连钻一下：流沙圈 20 + 推开 3 米；崩 4 块碎石（落点红圈，各 8） */
  private chainBurst(): void {
    this.chainN += 1;
    this.go('chainUp');
    this.breach(this.lockAt.x, this.lockAt.z, DRILL.lock.dmg2, DRILL.lock.push2);
    const R = DRILL.rocks;
    // 敌方抛射物的伤害范围 = 半径 + 2.4（红圈画的就是它）：要 3 米的圈，半径给 0.6
    const radius = Math.max(0.3, R.r - 2.4);
    for (let i = 0; i < R.n; i++) {
      const a = rng.boss() * Math.PI * 2;
      const d = R.d[0] + rng.boss() * (R.d[1] - R.d[0]);
      const tx = THREE.MathUtils.clamp(this.lockAt.x + Math.cos(a) * d, -16, 16);
      const tz = this.lockAt.z + Math.sin(a) * d;
      if (this.ctx.lob) this.ctx.lob(this.lockAt.x, 4, this.lockAt.z, tx, tz, R.dmg, radius, R.warn + i * 0.05);
      else this.ctx.artillery(this.lockAt.x, this.lockAt.z, tx, tz, R.dmg, radius, R.warn);
    }
  }

  /** 躺平：整条冲出地面顺着路躺 6 秒（头在车前 15 米、躺在离你远的那半边路，尾巴伸进雾里）；车厢节 × 1.5、钻头 × 1；运兵车厢开门放兵 */
  private startLie(): void {
    const P = this.target;
    this.closeWave();
    this.closeAll();
    this.lieX = (P.x > 0 ? -1 : 1) * 7.5;
    this.tip.set(this.lieX, DRILL.axis, P.z - 15);
    this.yaw = 0;
    this.layLine(this.tip, 0, 0, 0);
    this.heave(-10, 0.12);
    this.go('lie');
    this.winT = DRILL.win.lie + this.ventBonus();
    this.open(this.core, DRILL.mult.lie);
    for (const c of this.cars) {
      if (c.dead || c.dropped) continue;
      this.open(c.slot, DRILL.mult.car);
      if (c.load === 'troop' && !c.done) c.door = DRILL.troop.door;
    }
    for (let i = 0; i < 10; i++) this.ctx.fx.dust(this.lieX + (Math.random() - 0.5) * 8, P.z - 15 - i * 8, 4, 0xb89a76, 0.6);
    this.ctx.quake?.(this.lieX, P.z - 30, 14);
    this.ctx.audio.play('bigboom');
    this.ctx.shake(1);
  }

  /** 打瘫的车厢在下潜时甩在路上（变成残骸：阶段三撞上卡住，结局一起炸）；身子越打越短 */
  private dropDead(): void {
    for (const seg of this.segs) {
      const c = seg.car;
      if (!c || !c.dead || c.dropped) continue;
      c.dropped = true;
      seg.g.getWorldPosition(v1);
      // 不在地面上的（沙下 / 半截在沙里）就跟着沉没了，不留
      if (v1.y < 1.5) {
        seg.g.visible = false;
        continue;
      }
      seg.g.position.y = DRILL.axis - 0.8;
      seg.g.rotation.set(0, seg.g.rotation.y, 0.14, 'YXZ');
      this.drops.push(seg);
      this.ctx.fx.smoke(v1.x, 3, v1.z, 2, 3, 0x2a2624, 0.6);
    }
  }

  // ---------------------------------------------------------- 转场（各 3 秒，全场停火）

  private startTrans(to: number): void {
    this.transTo = to;
    this.phase = to;
    this.closeWave();
    this.closeAll();
    this.go('trans');
    const P = this.target;
    // 整条冲出地面：车前 60 米（转场二 50 米）破土，七节一节接一节拱出来摔在路上
    this.lieX = THREE.MathUtils.clamp(P.x * 0.3, -6, 6);
    this.tip.set(this.lieX, DRILL.axis, P.z - (to === 1 ? 60 : 50));
    this.yaw = 0;
    this.layLine(this.tip, 0, 0, 0);
    this.heave(-11, 0.2);
    this.breach(this.lieX, this.tip.z, 0, 0);
    this.ctx.ceasefire?.(true);
    this.ctx.audio.play('alarm');
    if (to === 1) this.ctx.announce('「穿山」', '黄黑条车厢，一炸一串');
    else this.ctx.announce('钻头过热', '引它撞石柱和残骸');
  }

  private endTrans(): void {
    this.ctx.ceasefire?.(false);
    if (this.transTo === 2) {
      this.dropDead();
      this.startTurnPhase();
      return;
    }
    this.startSink();
  }

  // ---------------------------------------------------------- 阶段三：暴走

  private startTurnPhase(): void {
    this.closeWave();
    if (this.tip.y < DRILL.axis - 0.5) {
      this.tip.y = DRILL.axis;
      this.layLine(this.tip, this.yaw, 0, 0);
      this.heave(-10, 0.1);
    }
    this.go('turn');
  }

  /** 转向你 2 秒（贴着地面慢慢拐过来），然后地上一条 9 米宽的红色裂纹线 1.5 秒 */
  private stepTurn(dt: number, P: THREE.Vector3): void {
    const want = Math.atan2(P.x - this.tip.x, P.z - this.tip.z);
    const d = Math.atan2(Math.sin(want - this.yaw), Math.cos(want - this.yaw));
    this.yaw += THREE.MathUtils.clamp(d, -1.6 * dt, 1.6 * dt);
    this.tip.x = THREE.MathUtils.clamp(this.tip.x + Math.sin(this.yaw) * 3 * dt, -15, 15);
    this.tip.z += Math.cos(this.yaw) * 3 * dt;
    this.tip.y = DRILL.axis;
    this.moveTip();
    if (this.actT < DRILL.charge.turn) return;
    // 锁线：从它的头穿过你，再往后伸 14 米（伸到车道边为止）
    const C = DRILL.charge;
    this.dir.set(P.x - this.tip.x, 0, P.z - this.tip.z);
    const dist = Math.max(1, this.dir.length());
    this.dir.normalize();
    let len = dist + C.over;
    if (Math.abs(this.dir.x) > 1e-3) len = Math.min(len, Math.max(dist, (Math.sign(this.dir.x) * C.edge - this.tip.x) / this.dir.x));
    this.chargeLeft = len;
    this.yaw = Math.atan2(this.dir.x, this.dir.z);
    this.hitTank = false;
    const fast = this.cars.every((c) => c.dead || c.dropped) ? C.fast : 1;
    this.ctx.hazards.marker(this.tip.x + this.dir.x * len * 0.5, this.tip.z + this.dir.z * len * 0.5, C.w / 2, C.warn + len / (C.speed * fast), 'enemy', len / 2, this.yaw);
    this.ctx.audio.play('horn', 0.9, 0.6);
    this.go('warn');
  }

  /** 冲：每秒 24 米照着线冲；钻头撞到你 30 + 推开 6，车厢擦到推开 2；撞上硬东西卡住、扎进路边沙丘卡住，冲到线头什么都没撞上就滑出去掉头 */
  private stepCharge(dt: number, P: THREE.Vector3): void {
    const C = DRILL.charge;
    const fast = this.cars.every((c) => c.dead || c.dropped) ? C.fast : 1;
    const step = C.speed * fast * dt;
    this.tip.x += this.dir.x * step;
    this.tip.z += this.dir.z * step;
    this.tip.y = DRILL.axis;
    this.moveTip();
    this.chargeLeft -= step;
    const f = this.ctx.fx;
    if (Math.random() < dt * 30) f.dust(this.tip.x - this.dir.x * 6 + (Math.random() - 0.5) * 6, this.tip.z - this.dir.z * 6, 3, 0xb89a76, 0.5);
    if (!this.hitTank && Math.hypot(this.tip.x - P.x, this.tip.z - P.z) < 3.8) {
      this.hitTank = true;
      this.ctx.damagePlayer(C.dmg / 1.2, P);
      this.ctx.push?.(this.tip.x - this.dir.x * 4, this.tip.z - this.dir.z * 4, C.push, P);
      this.ctx.shake(1);
    }
    for (const seg of this.segs) {
      if (!seg.car || seg.car.dropped) continue;
      if (Math.hypot(seg.g.position.x - P.x, seg.g.position.z - P.z) < 5.5) {
        this.ctx.push?.(seg.g.position.x, seg.g.position.z, C.brush * dt * 3, P);
        break;
      }
    }
    // 撞上什么：车道边 / 甩下来的车厢残骸 / 场上的硬东西（Game 查：石柱、磕头机、车壳、岩板、油料）
    const ax = this.tip.x + this.dir.x * 2;
    const az = this.tip.z + this.dir.z * 2;
    let hit: 'pillar' | 'hard' | 'slab' | 'fuel' | 'edge' | null = Math.abs(ax) > C.edge ? 'edge' : null;
    if (!hit) for (const d of this.drops) if (Math.hypot(d.g.position.x - ax, d.g.position.z - az) < 6) hit = 'hard';
    if (!hit) hit = this.ctx.hardAt?.(ax, az, 2.6, this.tip.x - this.dir.x * 6, this.tip.z - this.dir.z * 6) ?? null;
    if (hit) this.crash(hit);
    else if (this.chargeLeft <= 0) {
      this.go('slide');
      this.segs[0].liftTo = 0;
      this.open(this.core, 1);
    }
  }

  /** 撞上：火花 + 碎块 + 扬尘 + 闷响 + 震屏；卡几秒按撞上什么（石柱倒下砸在它身上再掉 5%，油料殉爆掉 8%）；钻头 × 2、散热口半露 × 2、近处两节车厢 × 1.5 */
  private crash(hit: 'pillar' | 'hard' | 'slab' | 'fuel' | 'edge'): void {
    const ctx = this.ctx;
    ctx.fx.sparks(this.tip.x, 3, this.tip.z, 30, 0xffd090, 14);
    ctx.debris.chunks(this.tip.x, 3, this.tip.z, 6, hit === 'pillar' || hit === 'slab' || hit === 'edge' ? 'concrete' : 'metal', 1.5);
    for (let i = 0; i < 6; i++) ctx.fx.dust(this.tip.x + (Math.random() - 0.5) * 8, this.tip.z + (Math.random() - 0.5) * 8, 4, 0xb89a76, 0.6);
    ctx.audio.play('slam');
    ctx.audio.play('breach', 0.9);
    ctx.shake(1.1);
    ctx.quake?.(this.tip.x, this.tip.z, 8);
    if (hit === 'pillar') this.hurtCore(DRILL.bait.pillar);
    if (hit === 'fuel') this.hurtCore(DRILL.bait.fuel);
    this.go('stuck');
    this.winT = DRILL.stuck[hit] + this.ventBonus();
    this.segs[0].liftTo = 1.2;
    this.open(this.core, DRILL.mult.stuck);
    for (const v of this.vents) this.open(v, DRILL.mult.vent);
    let n = 0;
    for (const c of this.cars) {
      if (c.dead || c.dropped || n >= 2) continue;
      this.open(c.slot, DRILL.mult.car);
      n++;
    }
    ctx.announce('撞上了', '卡住了，贴上去打');
  }

  /** 冲到线头什么都没撞上：顺着冲劲滑出去、慢慢停（这 2 秒钻头 × 1） */
  private slideOn(dt: number): void {
    const k = Math.max(0, 1 - this.actT / DRILL.stuck.miss);
    const step = DRILL.charge.speed * 0.4 * k * dt;
    this.tip.x = THREE.MathUtils.clamp(this.tip.x + this.dir.x * step, -16, 16);
    this.tip.z += this.dir.z * step;
    this.moveTip();
  }

  // ---------------------------------------------------------- 浪头 / 车厢 / 特效

  /** 浪头挨的打：补满耐久，掉的那一截攒震荡（按最大耐久的 5% 算满）、× 0.3 记到钻头；一下打掉一大截（核弹这种固定伤害）= 震荡直接满 */
  private stepWave(): void {
    const e = this.wave;
    if (!e) return;
    if (!e.alive) {
      this.wave = null;
      return;
    }
    const drop = WAVE_HP - e.hp;
    e.hp = WAVE_HP;
    if (drop <= 0) return;
    if (drop >= 900) this.conc = 1;
    else this.conc += drop / (this.maxHp * DRILL.conc.full);
    this.core.hp = Math.max(1, this.core.hp - drop * DRILL.conc.wave);
  }

  /** 爆炸（Game.explode 转进来）：浪头 10 米内油料殉爆，震荡 +50% */
  blastAt(x: number, z: number, fuel: boolean): void {
    if (!fuel || this.act !== 'prowl') return;
    if (Math.hypot(x - this.tip.x, z - this.tip.z) <= DRILL.conc.fuelR) this.conc += DRILL.conc.fuel;
  }

  private stepCars(dt: number): void {
    const ctx = this.ctx;
    this.troopsOut = this.troopsOut.filter((e) => e.alive);
    for (const c of this.cars) {
      // 运兵车厢：开门 1 秒后放兵（离你远的那一侧放，场上最多 8 个）
      if (c.door > 0 && !c.dead && !c.dropped) {
        c.door -= dt;
        if (c.door <= 0 && !c.done) {
          c.done = true;
          this.segOf(c).g.getWorldPosition(v1);
          const side = v1.x > this.target.x ? -1 : 1;
          const D = DRILL.troop;
          for (let i = 0; i < D.n + D.at && this.troopsOut.length < D.cap; i++) {
            const e = ctx.spawn(i < D.n ? 'infantry' : 'rocketeer', THREE.MathUtils.clamp(v1.x + side * (5.5 + (i % 2) * 1.2), -16, 16), v1.z - 3 + i * 1.6);
            if (e) this.troopsOut.push(e);
          }
          ctx.fx.dust(v1.x + side * 5, v1.z, 2.4, 0xb89a76, 0.5);
        }
      }
      // 油料车厢喷火：前后两节各吃 80（4 秒里分 4 跳）
      if (c.burn > 0) {
        const before = Math.ceil(c.burn);
        c.burn -= dt;
        const g = this.segOf(c).g;
        g.getWorldPosition(v1);
        if (v1.y > -2 && Math.random() < dt * 10) ctx.fx.fire(v1.x + (Math.random() - 0.5) * 6, Math.max(1, v1.y) + 2, v1.z + (Math.random() - 0.5) * 6, 2.4);
        if (Math.ceil(c.burn) < before) for (const n of this.cars) if (!n.dead && !n.dropped && Math.abs(n.i - c.i) === 1) this.hurtCar(n, 20 * ctx.hpScale);
      }
    }
  }

  /** 沙下隆隆声 / 近处地面一震一震的计时 */
  private rumbleT = 0;

  /** 刀盘转、钻头烧红（阶段三）、烟囱冒烟、沙浪 + 震荡圈跟着浪头、打瘫的车厢冒烟；沙下钻的隆隆声（越近越响）、离你 14 米内地面一震一震 */
  private stepFx(dt: number): void {
    const f = this.ctx.fx;
    const moving = this.act === 'prowl' || this.act === 'intro' || this.act === 'dive' || this.act === 'chainGap' || this.act === 'charge';
    if (moving && (this.rumbleT -= dt) <= 0) {
      this.rumbleT = this.act === 'charge' ? 0.5 : 1.1;
      const P = this.target;
      const d = Math.hypot(this.tip.x - P.x, this.tip.z - P.z);
      this.ctx.audio.play('burrow', THREE.MathUtils.clamp(1.2 - d / 60, 0.15, 1));
      if (d < 14) this.ctx.shake(0.18 * (1 - d / 14) + 0.06);
    }
    const surface = this.tip.y > -1;
    const spin = this.act === 'prowl' || this.act === 'intro' || this.act === 'charge' || this.act === 'rise' || this.act === 'chainUp' || this.act === 'dive' ? 9 : this.act === 'stuck' || this.act === 'bridge' ? 3 : 1.2;
    this.spinA += spin * dt;
    this.teethA.rotation.z = this.spinA;
    this.teethB.rotation.z = -this.spinA * 1.3;
    this.heat += ((this.phase === 2 ? 1 : 0) - this.heat) * Math.min(1, dt * 1.5);
    this.heatMat.opacity = this.heat * (0.35 + 0.15 * Math.sin(this.t * 7));
    // 阶段三：散热口喷白汽
    if (this.phase === 2 && Math.random() < dt * 4) {
      this.segs[0].g.localToWorld(v1.set(0, -4.6, -4));
      f.steam(v1.x, Math.max(0.5, v1.y), v1.z);
    }
    // 烟囱（露在地面上的顶）冒黑烟
    if (Math.random() < dt * 6) {
      for (const seg of this.segs) {
        const c = seg.car;
        if (!c || c.dropped || (c.i !== 0 && c.i !== 2 && c.i !== 4)) continue;
        seg.g.localToWorld(v1.set(1.6, 8.3, -1.5));
        if (v1.y > 0.2) f.smoke(v1.x, v1.y, v1.z, 0.7, 2, 0x26221f, 0.55);
      }
    }
    // 打瘫的车厢冒烟着火
    if (Math.random() < dt * 3) {
      for (const seg of this.segs) {
        if (!seg.car?.dead) continue;
        seg.g.getWorldPosition(v1);
        if (v1.y < -1) continue;
        f.smoke(v1.x, v1.y + 3, v1.z, 1.8, 2.6, 0x2a2624, 0.6);
        if (Math.random() < 0.5) f.fire(v1.x, v1.y + 2.5, v1.z, 1.6);
      }
    }
    // 沙浪：浪头一道沙脊 + 翻沙（透一点橙光），身后一串鼓起；震荡圈跟着浪头
    const underground = !surface && (this.act === 'prowl' || this.act === 'intro' || this.act === 'dive' || this.act === 'lock' || this.act === 'chainLock' || this.act === 'chainGap');
    this.ridge.visible = underground;
    if (underground) {
      const hgt = this.act === 'lock' || this.act === 'chainLock' ? 0.5 : 1.4;
      this.ridge.position.set(this.tip.x - Math.sin(this.yaw) * 3, -0.25, this.tip.z - Math.cos(this.yaw) * 3);
      this.ridge.rotation.y = this.yaw;
      this.ridge.scale.set(3.2, hgt * (0.9 + 0.1 * Math.sin(this.t * 11)), 7);
      if (Math.random() < dt * 30) f.smokeP.emit({ x: this.tip.x + (Math.random() - 0.5) * 5, y: 0.8, z: this.tip.z + (Math.random() - 0.5) * 2, vx: Math.sin(this.yaw) * 3 + (Math.random() - 0.5) * 3, vy: 3 + Math.random() * 4, vz: Math.cos(this.yaw) * 3 + (Math.random() - 0.5) * 3, life: 1, size: 1, size1: 3, color: Math.random() < 0.3 ? 0x8a6a48 : 0xe0cca8, color1: 0xa88a66, alpha: 0.7, frame: 1, gravity: -6 });
      if (Math.random() < dt * 5) f.glow.emit({ x: this.tip.x, y: 0.6, z: this.tip.z, life: 0.4, size: 2.6, size1: 1.2, color: 0xff9a3a, frame: 0 });
      if (Math.random() < dt * 10) {
        const s = 8 + Math.random() * Math.min(60, this.bodyLen());
        this.sample(s, v2);
        f.dust(v2.x + (Math.random() - 0.5) * 4, v2.z, 2.4, 0xb89a76, 0.4);
      }
    }
    this.ring.visible = !!this.wave;
    if (this.wave) {
      this.ring.position.set(this.tip.x, 0.18, this.tip.z);
      this.ring.scale.setScalar(6);
      const u = this.ring.material.uniforms;
      (u.uK as { value: number }).value = Math.min(1, this.conc);
      (u.uT as { value: number }).value = this.t;
    }
  }

  // ---------------------------------------------------------- 停车线 / 车身限位 / 特写

  /** 坦克开到停车线停下（打完、结局演完才放行） */
  override holds(z: number, speed: number): boolean {
    return !this.finished && z - this.lineZ < 1.5 + (speed * speed) / 14;
  }

  /** 躺在地上（侧翻 / 躺平 / 转场 / 卡住 / 结局）时车身挡在前面：你这条线上、在你前面的那几节，往前最远到它们靠你的一头（钻出来竖着、拱桥时不挡，照样砸你） */
  override front(x: number, halfW: number): number {
    // 阶段三绕着你冲来冲去，不挡（挡了会一下下把你顶到后面去）
    const lying = this.dead || this.act === 'flip' || this.act === 'lie' || this.act === 'trans';
    if (!lying) return -Infinity;
    const P = this.target;
    let best = -Infinity;
    for (const seg of this.segs) {
      if (seg.car?.dropped || seg.g.position.y < 1 || seg.g.position.z > P.z - 3) continue;
      const p = seg.g.position;
      const half = Math.abs(Math.sin(seg.g.rotation.y)) * seg.len * 0.5 + 4.6;
      if (Math.abs(x - p.x) > half + halfW) continue;
      best = Math.max(best, p.z + Math.abs(Math.cos(seg.g.rotation.y)) * seg.len * 0.5 + 0.5);
    }
    return best;
  }

  /** 特写对准钻头（潜行时对准浪头） */
  override showcase(out: THREE.Vector3): number {
    const h = this.segs[0].g.position;
    if (h.y > -1) out.set(h.x, Math.max(2, h.y), h.z);
    else out.set(this.tip.x, this.showY, this.tip.z);
    return this.showR;
  }

  override isBehind(pz: number): boolean {
    return this.finished && this.segs[0].g.position.z > pz + 60 && this.drops.every((d) => d.g.position.z > pz + 60);
  }

  override dispose(): void {
    this.closeWave();
    this.ring.removeFromParent();
    this.ridge.removeFromParent();
    for (const m of [this.ring, this.ridge]) {
      m.geometry.dispose();
      (m.material as THREE.Material).dispose();
    }
    this.ctx.ceasefire?.(false);
    super.dispose();
  }

  // ---------------------------------------------------------- 结局：七节从雾里一节节往你车头前炸

  /**
   * 钻头被打掉（6 秒，全程你无敌）：它末一次冲出地面，整条摔在路上、头冲你、停在车前 14 米；1.2 秒起从尾巴往前一节一节炸（每 0.3 秒一节，
   * 车顶板掀飞 + 火柱 + 沙子塌一条坑；甩在路上的车厢残骸按远近插在队里一起炸），末一炸是车头；3.0 秒钻头大爆炸（只看不伤的冲击波 + 白闪）、
   * 3.3 秒钻头飞起来 22 米、翻着斜插在车前 26 米右边 15 米；6 秒演完，残骸登记成能碾的、掉战利品箱
   */
  private startEnd(): void {
    const P = this.target;
    const E = DRILL.end;
    this.closeWave();
    for (const s of this.slots) if (s.e) this.close(s);
    this.ctx.ceasefire?.(true);
    this.endT = 0;
    const x = THREE.MathUtils.clamp(P.x * 0.4, -6, 6);
    this.tip.set(x, DRILL.axis, P.z - E.near);
    this.yaw = 0;
    this.layLine(this.tip, 0, 0, 0);
    this.heave(-8, 0.06);
    this.cum.length = 0;
    this.pose(0);
    // 炸的顺序：从最远的往近处（车厢从尾巴往前，残骸按远近插进去），末一炸 = 钻头那一节
    const list: Seg[] = [...this.segs.filter((s) => s.car && !s.car.dropped), ...this.drops].sort((a, b) => a.g.position.z - b.g.position.z);
    list.forEach((seg, i) => this.blasts.push({ seg, t: E.start + i * E.gap, done: false }));
    this.ring.visible = false;
    this.ridge.visible = false;
  }

  private stepEnd(dt: number): void {
    if (this.endT < 0) return;
    const E = DRILL.end;
    const ctx = this.ctx;
    const f = ctx.fx;
    this.endT += dt;
    if (!this.headFly) this.pose(dt);
    for (const b of this.blasts) {
      if (b.done || this.endT < b.t) continue;
      b.done = true;
      const p = b.seg.g.position;
      f.explosion(p.x, p.z, 4.2, Math.max(2, p.y + 1.5));
      for (let i = 0; i < 5; i++) f.column(p.x + (Math.random() - 0.5) * 3, Math.max(2, p.y) + 2 + i * 2.2, p.z + (Math.random() - 0.5) * 3, 2.4, 1);
      f.smoke(p.x, p.y + 5, p.z, 3.4, 5, 0x1e1b19, 0.75);
      // 车顶板掀飞
      this.roof.position.set(p.x, p.y + 4.7, p.z);
      this.roof.rotation.set(0, b.seg.g.rotation.y, 0);
      this.roof.visible = true;
      ctx.debris.launchPart(this.roof, 2.2, (Math.random() - 0.5) * 0.6, -0.4);
      this.roof.visible = false;
      ctx.debris.chunks(p.x, p.y + 3, p.z, 6, 'metal', 1.6);
      ctx.world.crater(p.x, p.z, 4.2, 1.5, 0.3, 6, 0.6, 3);
      b.seg.g.scale.set(1.04, 0.62, 1);
      b.seg.g.position.y = Math.max(1.6, p.y - 1.6);
      ctx.audio.play('bigboom', 0.8);
      ctx.shake(0.55);
    }
    // 钻头那一节：大爆炸（周围残骸掀飞、你的车只重晃一下）+ 只看不伤的冲击波 + 白闪
    const head = this.segs[0].g;
    if (this.endT >= E.boom && this.endT - dt < E.boom) {
      const p = head.position;
      f.explosion(p.x, p.z, 7, Math.max(2, p.y));
      f.fireball(p.x, p.y + 2, p.z, 3, 9, 10, 1.6);
      f.shockwave(p.x, p.z, 34, 0xffd8a0, 0.9);
      f.flash(p.x, p.y + 4, p.z, 9000);
      ctx.smash?.(p.x, p.z, 14, 30);
      ctx.world.crater(p.x, p.z, 6, 1.8, 0.5, 9, 0.7, 3);
      ctx.audio.play('bigboom');
      ctx.shake(1.6);
    }
    // 钻头飞起来 22 米、翻着斜插在车前 26 米右边 15 米
    if (this.endT >= E.fly && !this.headFly) {
      const P = this.target;
      const land = new THREE.Vector3(THREE.MathUtils.clamp(P.x + E.land[1], -17, 18), 2.2, P.z - E.land[0]);
      const vy = Math.sqrt(2 * E.g * (E.apex - head.position.y));
      const tFly = vy / E.g + Math.sqrt((2 * (E.apex - land.y)) / E.g);
      this.headFly = { v: new THREE.Vector3((land.x - head.position.x) / tFly, vy, (land.z - head.position.z) / tFly), spin: new THREE.Vector3(3.2, 1.1, 2.4), land, landed: false };
    }
    const hf = this.headFly;
    if (hf && !hf.landed) {
      hf.v.y -= E.g * dt;
      head.position.addScaledVector(hf.v, dt);
      head.rotation.x += hf.spin.x * dt;
      head.rotation.y += hf.spin.y * dt;
      head.rotation.z += hf.spin.z * dt;
      if (Math.random() < dt * 20) f.smoke(head.position.x, head.position.y, head.position.z, 1.6, 2, 0x24201e, 0.6);
      if (hf.v.y < 0 && head.position.y <= hf.land.y) {
        hf.landed = true;
        head.position.copy(hf.land);
        // 钻头朝下斜插进沙里
        head.rotation.set(0.95, -0.5, 0.3, 'YXZ');
        f.explosion(hf.land.x, hf.land.z, 2.6, 1.2);
        for (let i = 0; i < 8; i++) f.dust(hf.land.x + (Math.random() - 0.5) * 8, hf.land.z + (Math.random() - 0.5) * 8, 4, 0xb89a76, 0.6);
        ctx.world.crater(hf.land.x, hf.land.z, 3.5, 1.0, 0.4, 5, 0.4, 3);
        ctx.audio.play('explode');
        ctx.shake(0.8);
      }
    }
    // 演完：残骸能碾、掉战利品箱、放行
    if (this.endT >= E.dur && !this.finished) {
      this.finished = true;
      this.ctx.ceasefire?.(false);
      this.settleWreck();
      const box = new THREE.Box3();
      for (const s of this.segs) if (s.g.visible) box.expandByObject(s.g);
      this.ctx.wrecked?.(box, this.wreckEdge(box));
      // 散热口三个全拆了：再掉一个精英战利品箱（落在旁边一点）
      if (this.vents.every((v) => v.dead)) this.ctx.wrecked?.(box.clone().translate(v1.set(box.getCenter(v2).x > 0 ? -7 : 7, 0, 0)), this.wreckEdge(box) - 3);
    }
    if (this.finished && Math.random() < dt * 3) {
      const s = this.segs[Math.floor(Math.random() * this.segs.length)];
      if (s.g.visible) f.smoke(s.g.position.x, s.g.position.y + 3, s.g.position.z, 2, 2.4, 0x2a2624, 0.55);
    }
  }

  protected override settleWreck(): void {
    for (const s of this.segs) {
      if (!s.g.visible) continue;
      if (s === this.segs[0]) this.crushable(s.g, 0.8, 3, 6, [4.6, 6]);
      else this.crushable(s.g, 0.6, 2.4, 5, [4.4, 5.5]);
    }
  }

  protected override wreckEdge(box: THREE.Box3): number {
    // 战利品箱落在车头那一节前面（结局里车头停在你前方 14 米）
    let z = -Infinity;
    for (const s of this.segs) if (s.car && !s.car.dropped && s.g.visible) z = Math.max(z, s.g.position.z + 6);
    return Number.isFinite(z) ? z : box.max.z;
  }
}
