import type { Insets } from './canvas/Overlay';
import { hudViewport } from './viewport';

/**
 * 右侧工具（T055 横屏支持；两套界面各自调用、各画各的，DOM 版写成 styles.css 的 CSS 变量，画布版直接摆面板）。
 * 竖屏（T214）：耐久条下面、贴右边（安全区里 14 像素）一块两列小键盘，每格 44 × 44、间隔 6——
 * 第一行 暂停（最外角）/ 改装，第二行 分享 / 战报，第三行 瞄准 / 开火，究极开关（可合成起出现）在第四行外侧。
 * 原来一列六格 + 改装挂在暂停左边，按钮只有 38 像素，竖着占到屏幕中部；现在高度少一半多、触区都是 44。
 * 究极键（右下）判定圆上沿留 RAIL_CLEAR 像素：放不下的行挪到左边再起两列（只有很矮的竖窗口会这样）。
 * 横屏排成两行，改装紧挨暂停。
 * 只看屏幕尺寸和安全区，不看究极键这时出没出来（合成前后按钮不跳）。
 * 纯函数，不碰 DOM（cssInsets 除外）
 */
export type RailId = 'shot' | 'pause' | 'workshop' | 'aim' | 'report' | 'fire' | 'ult';

/** 竖屏小键盘：col 0 = 贴右边那一列，row 0 = 最上面一行 */
export const RAIL: readonly { id: RailId; col: number; row: number; seat?: 2 }[] = [
  { id: 'pause', col: 0, row: 0 },
  { id: 'workshop', col: 1, row: 0 },
  { id: 'shot', col: 0, row: 1 },
  { id: 'report', col: 1, row: 1 },
  { id: 'aim', col: 0, row: 2 },
  { id: 'fire', col: 1, row: 2 },
  { id: 'ult', col: 0, row: 3 },
  { id: 'ult', col: 0, row: 0, seat: 2 },
  { id: 'workshop', col: 1, row: 0, seat: 2 },
  { id: 'report', col: 2, row: 0, seat: 2 },
];
/** 每格触区边长（画出来的键每边再收 RAIL_INSET），格间距，第一行离安全区顶多远（耐久条 12 + 46 下面再空 8） */
export const RAIL_W = 44;
const RAIL_GAP = 6;
const RAIL_TOP = 66;
const RAIL_EDGE = 14;
const RAIL_INSET = 2;
export const RAIL_CLEAR = 8;
/** 究极键：直径 64，离右边 14、离底边 40（都在安全区里）；判定圆半径 36（两套界面一样） */
export const ULT_KEY = { size: 64, bottom: 40, r: 36 };
/** 成就提示（右侧滑入那条）的默认高度位置和高 */
const ACH = { y: 300, h: 56 };

export interface RailCell {
  x: number;
  y: number;
  w: number;
  h: number;
  /** 0 = 贴右边那一列，1 = 左边一列… */
  col: number;
  /** 画出来的键比触区每边小多少（竖屏 2：键 40、触区 44，键之间看着有 10 的缝；横屏 0） */
  inset: number;
}

export interface RailLayout {
  cells: Record<RailId, RailCell>;
  /** 究极键判定圆（圆心、半径） */
  key: { x: number; y: number; r: number };
  /** 按钮列最左边一列的左沿（成就提示摆在它左边） */
  left: number;
  /** 成就提示的上沿：默认 300，压到究极圆就往上收 */
  achY: number;
}

export function railLayout(W: number, H: number, ins: Insets): RailLayout {
  const view = hudViewport(W, H, ins), s = view.scale;
  ins = view.insets;
  const right = W - RAIL_EDGE * s - ins.right;
  const key = { x: right - ULT_KEY.size * s / 2, y: H - ins.bottom - (ULT_KEY.bottom + ULT_KEY.size / 2) * s, r: ULT_KEY.r * s };
  if (W >= 560 && W > H) {
    const cells = {} as Record<RailId, RailCell>;
    const rows: RailId[][] = [['pause', 'workshop', 'shot', 'report'], ['aim', 'fire', 'ult']];
    rows.forEach((row, y) => row.forEach((id, col) => {
      cells[id] = { x: right - (44 + col * 50) * s, y: ins.top + (12 + y * 50) * s, w: 44 * s, h: 44 * s, col, inset: 0 };
    }));
    return { cells, key, left: right - 194 * s, achY: ins.top + 116 * s };
  }
  const limit = key.y - key.r - RAIL_CLEAR;
  const pitch = RAIL_W + RAIL_GAP;
  // 究极圆上面放得下几行；一行都放不下（没法玩的窗口）就照默认摆
  const rows = Math.floor((limit - ins.top - RAIL_TOP + RAIL_GAP) / pitch);
  const fit = rows >= 1 ? rows : 4;
  const cells = {} as Record<RailId, RailCell>;
  let left = right;
  for (const c of RAIL) {
    if (c.seat === 2) continue;
    const col = c.col + Math.floor(c.row / fit) * 2;
    const x = right - RAIL_W - col * pitch;
    cells[c.id] = { x, y: ins.top + RAIL_TOP + (c.row % fit) * pitch, w: RAIL_W, h: RAIL_W, col, inset: RAIL_INSET };
    left = Math.min(left, x);
  }
  return { cells, key, left, achY: Math.min(ins.top + ACH.y, limit - ACH.h) };
}

/** 网页读 CSS env(safe-area-inset-*)（DOM 版 / 网页画布版）；没有 DOM 时全 0 */
export function cssInsets(): Insets {
  if (typeof document === 'undefined' || !document.body) return { top: 0, right: 0, bottom: 0, left: 0 };
  const probe = document.createElement('div');
  probe.style.cssText = 'position:fixed;left:0;top:0;visibility:hidden;pointer-events:none;padding:env(safe-area-inset-top) env(safe-area-inset-right) env(safe-area-inset-bottom) env(safe-area-inset-left)';
  document.body.appendChild(probe);
  const cs = getComputedStyle(probe);
  const out = { top: parseFloat(cs.paddingTop) || 0, right: parseFloat(cs.paddingRight) || 0, bottom: parseFloat(cs.paddingBottom) || 0, left: parseFloat(cs.paddingLeft) || 0 };
  probe.remove();
  return out;
}
