/** 开始界面「局外成长」一块里的入口（T047：6 个常驻，军衔不够的锁着显示） */
export type EntryId = 'factory' | 'garage' | 'bay' | 'tasks' | 'rank' | 'medal';

/** 开始界面的局外成长部分（T030，两套界面一样）：军衔章一条、流派锁、「局外成长」入口 */
export interface TitleData {
  rank: { level: number; name: string; progress: number };
  ticket: number;
  frame: 'bronze' | 'silver' | 'gold' | null;
  /** 没解锁的流派 → 条件 */
  locks: Partial<Record<CoreId, CoreLock>>;
  /** 新解锁、还没点过的流派 */
  fresh: CoreId[];
  /**
   * 「局外成长」6 个入口（T047 起常驻）：sub = 名字下面一行小字（锁着时 = lock）；lock = 军衔不够时「下士开放」（变暗 + 锁，点进去只能看）；
   * dot = 有能买 / 新的东西；flash = 刚开放第一次出现轻闪一下
   */
  entries: { id: EntryId; label: string; sub: string; icon: string; dot: boolean; flash: boolean; lock?: string }[];
  /** 战区威胁：选中的等级（打掉过轰天才有这一行，没开 = null） */
  threat: number | null;
  /**
   * 「作战模式」入口（T110，原来的「荒原机场」那一行换成它；荒原机场挪进「自选关卡」）：sub = 名字下面一行小字；tab = 点开先看哪一页（上次在哪页出发的）；
   * null = 不显示（试玩 / 直通链接）
   */
  modes: { sub: string; tab: RoutePageId } | null;
  resume?: ResumeSummary;
}

