/** 入口和它对应打开的页（军衔：上尉以上先看「少校～元帅」那页，和点军衔章一样） */
const ENTRY_PAGE: Record<EntryId, RoutePageId> = { bay: 'bay', garage: 'gar-p', factory: 'fac', tasks: 'task', rank: 'rank-a', medal: 'medal-b' };
export const entryPage = (id: EntryId, rankLevel: number): RoutePageId => (id === 'rank' && rankLevel > 10 ? 'rank-b' : ENTRY_PAGE[id]);

/**
 * 装配板（T033 装配车间，DOM 版）：左边核心一格，右边两排（副武器 6 / 改装 6），开着的是铜边空槽 + 编号、锁着的是铆钉盖板 + 锁 + 哪一级开，
 * 刚装上的金边 +「新」；画布版 CanvasMenu.paintBay 照这个画
 */
export function bayHtml(b: BayView): string {
  const cell = (c: BayCell, i: number, kind: 'w' | 'm') =>
    `<span class="bc ${kind}${c.on ? ' on' : ' lock'}${c.fresh ? ' fresh' : ''}"><i class="box">${c.on ? `<b>${i + 1}</b>` : LOCK_SVG}${c.fresh ? '<em class="new">新</em>' : ''}</i><small>${c.on ? '' : (c.label ?? '')}</small></span>`;
  const row = (cells: BayCell[], kind: 'w' | 'm', head: string) => `<div class="bay-grp"><p>${head}</p><div class="bay-cells">${cells.map((c, i) => cell(c, i, kind)).join('')}</div></div>`;
  return `<div class="bay-board"><div class="bay-core">${icon(b.core)}<small>${b.coreName}</small></div><div class="bay-rows">${row(b.weapon, 'w', b.head)}</div><p class="bay-cap">${b.caption}</p></div>`;
}

export interface Settings {
  quality: QualitySetting;
  muted: boolean;
  /** 显示伤害数字 */
  numbers: boolean;
  /** 主炮自动瞄准（关掉后纯按点按方向开火，点在拇指区朝正前方） */
  autoAim: boolean;
  /** 视角俯仰档位：-2 放平看远 … 0 默认 … +2 俯视 */
  camTilt: number;
  /** 自动开火（可选开关，默认关）：主炮 / 火箭有弹、前方有目标就开炮；激光能量充满就开始输出，打空才停 */
  autoFire: boolean;
  /** 镜头拉远档位：0 默认 / 1 远 / 2 更远（和俯仰档位叠加） */
  camZoom: number;
  /** 震动档位（T017-15b）：0 强 / 1 标准 / 2 弱 / 3 关，倍率见 CameraRig 的 SHAKE_LEVELS */
  shake: number;
  /** 操作（T017-18c）：经典（单指拖动走位 + 点哪打哪）/ 双摇杆（拇指区左手走位、右手瞄准松手开炮），默认经典 */
  ctrl: 'classic' | 'twin';
  /** 究极（汇总第 60 条）：自动 = 冷却好了、附近敌人够多、选得到目标就自己放（六件一起管）；手动 = 只在点究极键 / 右键时放。默认自动 */
  ultAuto: boolean;
  /** 背景音乐（T206）：开关 / 音量 0..10 档 / 曲目（auto = 按场景切换）；和「音效」各管各的 */
  bgm: boolean;
  bgmVol: number;
  bgmTrack: BgmPick;
}

