import { scheme1 } from './scheme1';
import { scheme2 } from './scheme2';
import { scheme3 } from './scheme3';
import { scheme4 } from './scheme4';
import { scheme5 } from './scheme5';
import type { UiSkin } from './types';

const SKINS: UiSkin[] = [scheme1, scheme2, scheme3, scheme4, scheme5];

/** 只在设计副本启用。网页用 skin 参数；小游戏入口可指定全局编号。 */
function selected(): UiSkin | null {
  const g = globalThis as { __TANK_SKIN__?: number };
  let id = g.__TANK_SKIN__ ?? 0;
  try { id = Number(new URLSearchParams(location.search).get('skin') ?? id); } catch { /* 小游戏用全局编号 */ }
  return SKINS.find((s) => s.id === id) ?? null;
}

export const UI_SKIN = selected();

const INK = new Set(['#eceff4', '#ffffff', '#fff', '#f2ead8', '#e8e2d0', '#fff2dc', '#fff2d6']);
const SOFT = new Set(['#c9ced6', '#c9c2b0', '#e9dcc4', '#e8dcc0', '#e8d6b0', '#e8d8b0', '#c9b68a', '#b8bcc4']);
const DIM = new Set(['#9aa0a8', '#9aa3b0', '#8d939c', '#8a8e96', '#a8adb5', '#7a7e86']);
const ACCENT = new Set(['#ffd98a', '#ffe0a0', '#ffcf6a', '#ffe08a', '#ffd8a0', '#d9a64a', '#e0b458', '#ffcf8a', '#e8d6a6', '#d9c9a0', '#ffe9b8']);
const WARN = new Set(['#ff6a52', '#ff5a46', '#ff9b7a', '#ff8066', '#ff7a4a', '#e0533f', '#d4402c', '#b8331f', '#c8402a', '#ff6a4a', '#ff6a3a', '#f2705a']);

/** 共用文字色；排版仍由两套界面各自管理。 */
export function skinColor(color: string): string {
  if (!UI_SKIN) return color;
  const p = UI_SKIN.colors;
  const key = color.toLowerCase();
  if (UI_SKIN.light && (key === '#7fe08f' || key === '#7fe08a')) return '#356b52';
  if (UI_SKIN.light && key === '#8a8f96') return p.dim;
  if (INK.has(key)) return p.ink;
  if (SOFT.has(key)) return p.soft;
  if (DIM.has(key)) return p.dim;
  if (ACCENT.has(key)) return p.accent;
  if (WARN.has(key)) return UI_SKIN.light ? '#a65316' : '#ffc078';
  if (key === '#58d3f0' || key === '#9ccaff') return p.cool;
  return color;
}
