import * as THREE from 'three';

/**
 * 推荐机位：俯视 45°(A) 与第三人称(B) 的中间值。
 * 既保留足够的前方预警距离，又能看出坦克的立体轮廓。
 */
export const CAM = {
  height: 27,
  back: 25,
  lookHeight: 2.0,
  fov: 46,
  /** 蓄力炮开火瞬间压低拉近，强化爽感 */
  chargeHeight: 20,
  chargeBack: 21,
  chargeFov: 41,
  /** 坦克落在画面纵向的位置：0=正中，1=贴下边缘 */
  subjectAnchor: 0.42,
};

/**
 * 震动预算（T017-15A）：
 * - 日常档（开炮 / 命中 / 爆炸 / 碾压 / 挨打）：merge 秒内的多次只补上比之前更强的那一截，总强度封顶 cap；
 * - 重事件档（核弹 / 天火等终极、首领换阶段 / 被击破、合成演出、玩家重伤、阵亡）：另走一档，上限 heavyCap，真正的大爆炸反而更突出；
 * - 嗡震（激光出光）：目标强度每帧给一次，平滑趋近，不累加、不看帧率；算在日常档里。
 * 抖动是平滑噪声（几路正弦叠加），同样的强度不再每帧乱跳
 */
export const SHAKE = { cap: 0.6, heavyCap: 1.4, merge: 0.25, decay: 2.6, hum: 6 };
/** 设置里的「震动 强 / 标准 / 弱 / 关」（T017-15b，Settings.shake 是下标，默认 1 = 标准） */
export const SHAKE_LEVELS = [1.3, 1, 0.5, 0];
/**
 * 玩家的镜头拉远档位（0 默认 / 1 远 / 2 更远）：机位高度和后退距离同比放大这么多（坦克在画面上的位置不变，只是变小、看得更广）；首领战拉远（+38%）和它取大的那个，不叠加。
 * T020-a（制作人「整个镜头再拉远」）：三档整体推远 ×1 / ×1.2 / ×1.4 → ×1.3 / ×1.55 / ×1.8，存档里的档位下标不变（老玩家自动变远）
 */
export const CAM_ZOOM = [0.3, 0.55, 0.8];
/**
 * 首领特写（T017-6，制作人「首领亮相并没有看到特写，或者说镜头没有拉近到首领上」）：镜头转过去对着首领看、往它那边推 dolly（0..1，
 * 推到「从首领朝原来机位的方向、仰角 elev、它的半径占画面宽度 fill」那个机位的这么多），剩下的靠收窄视角补（最窄 minFov 度）；
 * 推过去 / 收回来各 inT / outT 秒（缓入缓出）；不改玩家设置，收回来就是平时的机位
 */
export const SHOWCASE = { elev: 0.38, fill: 0.78, dolly: 0.5, minFov: 16, inT: 0.4, outT: 0.5 };
/**
 * 巨弹冲击波扫到坦克（T035，blastKick）：镜头先往里一缩 punch 度（in 秒，像被气浪拍了一下），再往外一放到 +out 度、同时抬高 up 米（peak 秒到顶，
 * 正好是坦克被掀在空中、翻到最高的时候，拉开一点看得见它飞出去），back 秒缓回；都 × 力度，震动设置为「关」时不动
 */
export const BLAST_KICK = { punch: 3.5, out: 5, up: 2.4, in: 0.07, peak: 0.5, back: 1.5 };
/**
 * 停车攻坚（T106 方案 A）：镜头锚在停车点，坦克在画面里上下动；坦克脚下那一点最低到画面纵向 low（车尾再往下一截，底下还有操作提示 / 究极键）、最高到 high（顶上是血条 / 槽位条），
 * 到了就镜头跟过去。rate = 停车时注视点追过去的快慢、back = 打完松开以后回到贴着坦克的快慢（每秒）
 */
export const PIN = { low: 0.86, high: 0.3, rate: 8, back: 1.6 };
/**
 * 主武器开火的画面后坐（T134，制作人「主炮的开火可以稍微加一点画面后坐力」）：和震屏分开记——震屏是随机抖、按强度平方算，后坐是朝车尾方向的一下。
 * 单位是度（画面整体偏移，竖屏 844 高 1° 约 18 像素）；cap = 叠起来最多偏多少；settle = 默认回到 5% 以内的秒数；
 * 日常 / 重事件震屏到了日常上限时新来的一发只给 duck 倍；low = 低画质再乘；震动设置（SHAKE_LEVELS）照乘，关 = 不动
 */
export const RECOIL = { cap: 1.2, settle: 0.2, duck: 0.5, low: 0.75 };
const DEG = Math.PI / 180;

export class CameraRig {
  /** 日常档 / 重事件档的当前强度，合并窗口里的最强值和剩余时间，嗡震（当前 / 这一帧的目标） */
  private shake = 0;
  private heavyShake = 0;
  private peak = 0;
  private window = 0;
  private humNow = 0;
  private humWant = 0;
  /** 震动设置的倍率（SHAKE_LEVELS） */
  shakeScale = 1;
  private x = 0;
  private z = 0;
  private h = CAM.height;
  private b = CAM.back;
  private fov = CAM.fov;
  /** 首领战拉远：0..1；以及横向偏移 */
  private wide = 0;
  private wideTarget = 0;
  private wideZoom = 0.38;
  private offX = 0;
  private offXTarget = 0;
  /** 首领战偏轴（T104 机库在路边）：机位绕坦克转多少弧度（+ = 机位往右摆、朝左前方看），和横向偏移一样乘 wide */
  private yaw = 0;
  private yawTarget = 0;
  /** 首领战上仰（T105 空艇横舷）：在平时的朝向上再往上仰多少弧度，和终极抬头叠加，乘 wide */
  private rise = 0;
  private riseTarget = 0;
  /** 玩家调的视角俯仰：-1 放平看远（能看到天边），+1 更俯视 */
  private tilt = 0;
  private tiltTarget = 0;
  /** 玩家调的镜头拉远（CAM_ZOOM 里的倍率增量，平滑过去） */
  private zoom = 0;
  private zoomTarget = 0;
  /** 推近特写（合成演出）：0..1 */
  private focus = 0;
  private focusTarget = 0;
  /** 终极镜头（核弹）：保持期间俯仰目标 = min(玩家档, cinemaTilt)，结束后按 backRate 缓回；不改玩家设置 */
  private cinemaTilt = 0;
  private cinemaT = 0;
  private cinemaFade = true;
  private backRate = 4;
  private returning = false;
  /** 低频余震：强度 / 剩余 / 总时长，以及余震相位 */
  private rumbleA = 0;
  private rumbleT = 0;
  private rumbleDur = 1;
  private clock = 0;
  /** 巨弹冲击波的镜头一缩一放（BLAST_KICK）：力度 / 已经过了多少秒 */
  private kickK = 0;
  private kickT = 99;
  /** 首领特写（SHOWCASE）：对准的点 / 半径 / 推近比例 / 进度 k（0..1，缓入缓出前）/ 要不要推着 */
  private readonly show = { x: 0, y: 0, z: 0, r: 8, dolly: SHOWCASE.dolly, k: 0, on: false, inT: SHOWCASE.inT, outT: SHOWCASE.outT, elev: SHOWCASE.elev };
  /** 停车攻坚（T106）：镜头锚住的停车点（世界 z；null = 平时贴着坦克）、注视点比坦克靠前多少（世界 z 差，平滑过的） */
  private pinZ: number | null = null;
  private lead = 0;
  /** 终极抬头（T057）：在平时的朝向上再往上仰 lift 弧度（现在 / 目标 / 还保持几秒 / 仰上去和缓回的速度） */
  private lift = 0;
  private liftWant = 0;
  private liftT = 0;
  private liftIn = 5;
  private liftBack = 4;
  /** 后坐（RECOIL）：画面现在偏了多少 / 偏移速度（弧度，x 右 y 上）、弹簧角频率；镜头跟的那一点（算炮口在屏幕上的方向） */
  private recX = 0;
  private recY = 0;
  private recVX = 0;
  private recVY = 0;
  private recW = 5.7 / RECOIL.settle;
  private eyeX = 0;
  private eyeZ = 0;
  /** 同一个机位、不带震屏 / 余震 / 后坐（aimCamera） */
  private readonly still = new THREE.PerspectiveCamera();
  private readonly pa = new THREE.Vector3();
  private readonly pb = new THREE.Vector3();

  constructor(readonly camera: THREE.PerspectiveCamera) {
    camera.fov = CAM.fov;
    camera.updateProjectionMatrix();
  }

  snapTo(target: THREE.Vector3): void {
    this.cinemaT = 0;
    this.returning = false;
    this.rumbleT = 0;
    this.kickT = 99;
    this.tilt = this.tiltTarget;
    this.zoom = this.zoomTarget;
    this.wide = this.wideTarget = 0;
    this.offX = this.offXTarget = 0;
    this.yaw = this.yawTarget = 0;
    this.rise = this.riseTarget = 0;
    this.focus = this.focusTarget = 0;
    this.show.k = 0;
    this.show.on = false;
    this.lift = this.liftWant = this.liftT = 0;
    this.pinZ = null;
    this.lead = 0;
    this.recX = this.recY = this.recVX = this.recVY = 0;
    this.eyeX = target.x;
    this.eyeZ = target.z;
    this.x = target.x * 0.55;
    this.z = target.z;
    this.h = CAM.height;
    this.b = CAM.back;
    this.apply();
  }

  setTilt(t: number): void {
    this.tiltTarget = THREE.MathUtils.clamp(t, -1, 1);
  }

  /** 镜头拉远档位（0 / 1 / 2，见 CAM_ZOOM），约 0.5 秒平滑过去 */
  setZoom(level: number): void {
    this.zoomTarget = CAM_ZOOM[THREE.MathUtils.clamp(Math.round(level), 0, CAM_ZOOM.length - 1)];
  }

  /** zoom：这个首领的拉远量（体型越大拉得越远，默认 +38%）；首领没了以后保持原值慢慢收回；yaw = 偏轴弧度（见 yaw 字段）；lift = 上仰弧度（见 rise 字段） */
  setWide(k: number, offsetX: number, zoom?: number, yaw = 0, lift = 0): void {
    this.wideTarget = k;
    this.offXTarget = offsetX;
    this.yawTarget = yaw;
    this.riseTarget = lift;
    if (zoom !== undefined) this.wideZoom = zoom;
  }

  /** 现在实际的偏轴（弧度）：画面竖中线在坦克前方 d 米处偏到 x − d · tan(它)（飞蝗跟飞框按它挪） */
  get yawNow(): number {
    return this.yaw * this.wide;
  }

  /** 停车攻坚（T106 方案 A）：z = 停车点，镜头锚在这里、坦克在画面里上下动（出了 PIN.low / high 镜头才跟）；null = 松开，慢慢回到贴着坦克 */
  pin(z: number | null): void {
    this.pinZ = z;
  }

  /** 镜头注视点现在的世界 z（平时约等于坦克；停车攻坚时在停车点附近） */
  get focusZ(): number {
    return this.z;
  }

  /** 镜头推近（合成演出）：1 = 特写，0 = 回到平时 */
  setFocus(k: number): void {
    this.focusTarget = k;
  }

  /** 首领特写（T017-6）：每帧给一次对准的点（首领会动）和要框住的半径 r，dolly = 推近比例（SHOWCASE.dolly）；release() 收回来；elev = 机位仰角（T100B 机库开顶：升高看进库坑里） */
  showcase(x: number, y: number, z: number, r: number, dolly = SHOWCASE.dolly, inT = SHOWCASE.inT, elev = SHOWCASE.elev): void {
    const s = this.show;
    s.inT = inT;
    s.elev = elev;
    s.x = x;
    s.y = y;
    s.z = z;
    s.r = r;
    s.dolly = dolly;
    s.on = true;
  }

  /** 首领特写收回来（outT 秒缓回平时的机位） */
  release(outT = SHOWCASE.outT): void {
    this.show.on = false;
    this.show.outT = outT;
  }

  /** 镜头完全回到平时机位（T022-a 定格：特写收完、终极镜头不在、俯仰到了玩家档位）——恢复时间的条件 */
  get settled(): boolean {
    // 首领战镜头（巨炮每帧续上的 cinema）在场时，到位 = 到了它的俯仰
    const want = this.cinemaT > 0 ? Math.min(this.tiltTarget, this.cinemaTilt) : this.tiltTarget;
    return this.show.k <= 0 && Math.abs(this.tilt - want) < 0.03 && this.lift < 0.02;
  }

  /** 首领特写的进度（0 = 平时，1 = 推到位） */
  get showcaseK(): number {
    return this.show.k;
  }

  /** 终极镜头：放平到 maxTilt（玩家本来就更平就不动），保持 hold 秒，再用约 back 秒缓回玩家原来的档位；fade = 这段时间 HUD 要不要变淡（天火不变淡） */
  cinema(maxTilt: number, hold: number, back = 0.8, fade = true): void {
    this.cinemaTilt = maxTilt;
    this.cinemaT = hold;
    this.cinemaFade = fade;
    this.backRate = 3 / Math.max(0.1, back);
  }

  /**
   * 终极抬头看天（T057）：镜头在平时的朝向上再往上仰 rad 弧度，约 inT 秒仰到位，保持 hold 秒，back 秒缓回；rad = 0 = 马上开始缓回。
   * 和 cinema 分开记（首领战每帧续上的 cinema 不会把它清掉）；配 cinema 压低到 −1 以下（机位更低、更远），坦克留在画面下半截
   */
  lookUp(rad: number, hold: number, back = 0.8, inT = 0.6): void {
    this.liftWant = rad;
    this.liftT = rad > 0 ? hold : 0;
    this.liftIn = 3 / Math.max(0.1, inT);
    this.liftBack = 3 / Math.max(0.1, back);
  }

  /**
   * 画面上沿碰地离坦克多远（米，T020-a）：按当前的拉远倍率（玩家档 / 首领战拉远取大的）、俯仰按 max(0, 玩家档) 算——
   * ▲ / ▲▲ 本来就看得到天边、刷怪点本来就在雾里露出来，不再往外推。刷怪 / 据点 / 景物动画的距离跟着它走（防敌人在画面里凭空出现）。
   * 默认档 121、远 140、更远 160 米（原来默认 98）
   */
  groundTop(): number {
    const t = Math.max(0, this.tiltTarget);
    const zoom = 1 + Math.max(this.wide * this.wideZoom, this.zoom);
    const h = CAM.height * zoom * (1 + t * 0.14);
    const b = CAM.back * zoom * (1 - t * 0.32);
    const drop = h - CAM.lookHeight;
    const half = THREE.MathUtils.degToRad(CAM.fov) / 2;
    const look = Math.max(0.12, Math.atan2(drop, b) - half * (CAM.subjectAnchor + t * 0.14));
    const top = look - half;
    return top <= 0.02 ? 999 : h / Math.tan(top) - b;
  }

  /** 镜头现在的俯仰（平滑过的，−1 = ▲▲ 放平看远，+1 = 更俯视；T017-2A 雾跟着它推远） */
  get tiltNow(): number {
    return this.tilt;
  }

  /** 终极镜头保持中、而且要 HUD 变淡（核弹） */
  get cinemaOn(): boolean {
    return this.cinemaT > 0 && this.cinemaFade;
  }

  /** 低频余震：amount 强度，seconds 秒内逐渐消失（和随机抖动的震屏叠加） */
  rumble(amount: number, seconds: number): void {
    this.rumbleA = amount;
    this.rumbleT = this.rumbleDur = Math.max(0.01, seconds);
  }

  /** 现在的震动强度（未乘设置倍率）：重事件档和日常档（含嗡震）取大的 */
  get shakeAmount(): number {
    return Math.max(this.heavyShake, Math.min(SHAKE.cap, this.shake + this.humNow));
  }

  /** 日常震动（开炮 / 命中 / 碾压 / 挨打…）：合并窗口里只补上比之前更强的那一截，封顶 SHAKE.cap */
  impulse(amount: number): void {
    if (this.window <= 0) {
      this.window = SHAKE.merge;
      this.peak = 0;
    }
    if (amount <= this.peak) return;
    this.shake = Math.min(SHAKE.cap, this.shake + amount - this.peak);
    this.peak = amount;
  }

  /** 爆炸震屏：和日常震动同一个合并窗口（一轮火箭雨不会把镜头晃到顶） */
  blast(amount: number): void {
    this.impulse(amount);
  }

  /** 重事件档（终极、首领换阶段 / 被击破、合成演出、玩家重伤）：直接叠加，上限 SHAKE.heavyCap */
  heavy(amount: number): void {
    this.heavyShake = Math.min(SHAKE.heavyCap, this.heavyShake + amount);
  }

  /** 巨弹冲击波扫到坦克（T035）：镜头先缩后放（BLAST_KICK），k = 0..1 力度；正在放的那一下更强就不打断 */
  blastKick(k: number): void {
    const now = this.kickT < BLAST_KICK.back ? this.kickK * (1 - this.kickT / BLAST_KICK.back) : 0;
    if (k < now) return;
    this.kickK = k;
    this.kickT = 0;
  }

  /** 镜头一缩一放现在的视角增量（度）/ 抬高（米） */
  private kick(): [number, number] {
    const K = BLAST_KICK;
    const t = this.kickT;
    if (t >= K.back || this.kickK <= 0) return [0, 0];
    const k = this.kickK * Math.min(1, this.shakeScale);
    const ease = (x: number) => x * x * (3 - 2 * x);
    if (t < K.in) return [-K.punch * k * (t / K.in), K.up * k * ease(t / K.peak)];
    if (t < K.peak) {
      const e = ease((t - K.in) / (K.peak - K.in));
      return [(-K.punch + (K.punch + K.out) * e) * k, K.up * k * ease(t / K.peak)];
    }
    const e = 1 - ease((t - K.peak) / (K.back - K.peak));
    return [K.out * k * e, K.up * k * e];
  }

  /** 持续嗡震（激光出光）：每帧给一次目标强度，平滑趋近；不给就慢慢停 */
  hum(amount: number): void {
    this.humWant = Math.max(this.humWant, amount);
  }

  /**
   * 主武器开火的画面后坐（T134）：(dx, dz) = 炮弹出膛的世界方向，deg = 这一发把画面顶出去多少度，settle = 回到 5% 以内几秒。
   * 画面朝炮口在屏幕上的反方向（车尾那边）挪；临界阻尼弹簧，settle / 5.7 秒顶到头，不回弹不晃。
   * 同方向已经顶着的那一截从这一发里扣掉（连发不越叠越大），震屏正大时这一发打折（RECOIL.duck）
   */
  recoil(dx: number, dz: number, deg: number, settle = RECOIL.settle): void {
    if (deg <= 0) return;
    const cam = this.aimCamera;
    const a = this.pa.set(this.eyeX, 0, this.eyeZ).project(cam);
    const b = this.pb.set(this.eyeX + dx * 4, 0, this.eyeZ + dz * 4).project(cam);
    let sx = (b.x - a.x) * this.camera.aspect;
    let sy = b.y - a.y;
    const len = Math.hypot(sx, sy);
    if (len < 1e-6) return;
    sx /= len;
    sy /= len;
    const pushed = Math.max(0, -(this.recX * sx + this.recY * sy));
    const room = Math.max(0, 1 - pushed / (RECOIL.cap * DEG));
    const duck = 1 - (1 - RECOIL.duck) * Math.min(1, Math.max(this.shake, this.heavyShake) / SHAKE.cap);
    this.recW = 5.7 / Math.max(0.05, settle);
    const v = deg * DEG * room * duck * this.recW * Math.E;
    this.recVX -= sx * v;
    this.recVY -= sy * v;
  }

  /** 后坐现在把画面偏了多少度（乘过震动设置） */
  get recoilDeg(): number {
    return (Math.hypot(this.recX, this.recY) * this.shakeScale) / DEG;
  }

  /** 同一个机位、不带震屏 / 余震 / 后坐（T134）：点按 / 鼠标换算瞄准方向用，画面在抖、算出来的方向不跟着抖 */
  get aimCamera(): THREE.PerspectiveCamera {
    const s = this.still;
    s.projectionMatrix.copy(this.camera.projectionMatrix);
    s.projectionMatrixInverse.copy(this.camera.projectionMatrixInverse);
    return s;
  }

  /** 后坐弹簧走 dt 秒（临界阻尼的解析解，和帧率无关）；偏移超过 RECOIL.cap 就夹住、往外的速度清掉 */
  private stepRecoil(dt: number): void {
    const w = this.recW;
    const e = Math.exp(-w * dt);
    const kx = (this.recVX + w * this.recX) * dt;
    const ky = (this.recVY + w * this.recY) * dt;
    this.recX = (this.recX + kx) * e;
    this.recY = (this.recY + ky) * e;
    this.recVX = (this.recVX - w * kx) * e;
    this.recVY = (this.recVY - w * ky) * e;
    const cap = RECOIL.cap * DEG;
    const len = Math.hypot(this.recX, this.recY);
    if (len > cap) {
      this.recX *= cap / len;
      this.recY *= cap / len;
      const out = (this.recVX * this.recX + this.recVY * this.recY) / cap;
      if (out > 0) {
        this.recVX -= (out * this.recX) / cap;
        this.recVY -= (out * this.recY) / cap;
      }
    } else if (len < 1e-5 && Math.hypot(this.recVX, this.recVY) < 1e-4) this.recX = this.recY = this.recVX = this.recVY = 0;
  }

  update(delta: number, target: THREE.Vector3, punch: number): void {
    this.eyeX = target.x;
    this.eyeZ = target.z;
    if (this.recX || this.recY || this.recVX || this.recVY) this.stepRecoil(delta);
    // 相机横向只跟随 55%，让玩家走位时有"相对位移"的速度感
    this.wide += (this.wideTarget - this.wide) * Math.min(1, delta * 1.2);
    this.offX += (this.offXTarget - this.offX) * Math.min(1, delta * 1.2);
    this.yaw += (this.yawTarget - this.yaw) * Math.min(1, delta * 0.8);
    this.rise += (this.riseTarget - this.rise) * Math.min(1, delta * 0.8);
    const targetX = target.x * 0.55 + this.offX * this.wide;
    const k = Math.min(1, delta * 5.5);
    this.x += (targetX - this.x) * k;
    // 停车攻坚（T106）：注视点锚在停车点，坦克前后挪只在画面里上下动；坦克快出 PIN.low / high 的那一截镜头跟过去
    const pz = this.pinZ;
    const lead = pz === null ? 0 : THREE.MathUtils.clamp(pz, target.z - this.slack(PIN.low), target.z + this.slack(PIN.high)) - target.z;
    this.lead += (lead - this.lead) * Math.min(1, delta * (pz === null ? PIN.back : PIN.rate));
    this.z += (target.z + this.lead - this.z) * Math.min(1, delta * 9);

    const kh = Math.min(1, delta * 4);
    // 终极镜头：约 0.6 秒放平到位，保持期间玩家调档也只能更平；结束后按 back 缓回
    let want = this.tiltTarget;
    let rate = 4;
    if (this.cinemaT > 0) {
      this.cinemaT -= delta;
      want = Math.min(want, this.cinemaTilt);
      this.returning = this.cinemaT <= 0;
    } else if (this.returning) {
      rate = this.backRate;
      if (Math.abs(this.tilt - want) < 0.01) this.returning = false;
    }
    this.tilt += (want - this.tilt) * Math.min(1, delta * rate);
    const t = this.tilt;
    // 放平：相机降低、拉远；俯视：相机升高、拉近
    const hMul = t < 0 ? 1 + t * 0.5 : 1 + t * 0.14;
    const bMul = t < 0 ? 1 - t * 0.3 : 1 - t * 0.32;
    this.focus += (this.focusTarget - this.focus) * Math.min(1, delta * 4);
    this.zoom += (this.zoomTarget - this.zoom) * Math.min(1, delta * 4);
    // 首领战拉远和玩家的拉远档位取大的那个（不叠加，免得拉到看不清）
    const zoom = (1 + Math.max(this.wide * this.wideZoom, this.zoom)) * (1 - this.focus * 0.38);
    this.h += (THREE.MathUtils.lerp(CAM.height * zoom, CAM.chargeHeight * zoom, punch) * hMul - this.h) * kh;
    this.b += (THREE.MathUtils.lerp(CAM.back * zoom, CAM.chargeBack * zoom, punch) * bMul - this.b) * kh;

    const targetFov = THREE.MathUtils.lerp(CAM.fov, CAM.chargeFov, punch);
    if (Math.abs(targetFov - this.fov) > 0.01) this.fov += (targetFov - this.fov) * kh;
    const sh = this.show;
    sh.k = sh.on ? Math.min(1, sh.k + delta / sh.inT) : Math.max(0, sh.k - delta / sh.outT);

    this.shake = Math.max(0, this.shake - delta * SHAKE.decay);
    this.heavyShake = Math.max(0, this.heavyShake - delta * SHAKE.decay);
    this.window -= delta;
    this.humNow += (this.humWant - this.humNow) * Math.min(1, delta * SHAKE.hum);
    this.humWant = 0;
    this.clock += delta;
    if (this.rumbleT > 0) this.rumbleT = Math.max(0, this.rumbleT - delta);
    if (this.kickT < BLAST_KICK.back) this.kickT += delta;
    const up = this.liftT > 0;
    if (up) this.liftT -= delta;
    this.lift += ((up ? this.liftWant : 0) - this.lift) * Math.min(1, delta * (up ? this.liftIn : this.liftBack));
    if (!up && this.lift < 1e-3) this.lift = 0;
    this.apply();
  }

  /**
   * 根据当前机位反算注视点，让坦克始终落在画面固定高度上。
   * 否则一压低相机，坦克就被挤出下边缘。
   */
  private lookAheadDistance(): number {
    const drop = this.h - CAM.lookHeight;
    const angleToSubject = Math.atan2(drop, this.b);
    const halfFov = THREE.MathUtils.degToRad(this.fov) / 2;
    // 放平视角时坦克放低一点，留出上方看远处
    const anchor = CAM.subjectAnchor + Math.abs(this.tilt) * (this.tilt < 0 ? 0.2 : 0.14);
    const lookAngle = Math.max(0.12, angleToSubject - halfFov * anchor);
    return this.b - drop / Math.tan(lookAngle);
  }

  /**
   * 坦克脚下那一点（地面）能比注视点往后（f 在画面下半）/ 往前（f 在上半）挪多少米，还落在画面纵向 f 以内（T106）：
   * 镜头朝向照 lookAheadDistance 算（机位高度、后退距离、视角、俯仰决定的锚点、上仰）；坦克平时的位置已经过了 f 就是 0（不为了它把镜头挪开）
   */
  private slack(f: number): number {
    const half = THREE.MathUtils.degToRad(this.fov) / 2;
    const anchor = CAM.subjectAnchor + Math.abs(this.tilt) * (this.tilt < 0 ? 0.2 : 0.14);
    const axis = Math.max(0.12, Math.atan2(this.h - CAM.lookHeight, this.b) - half * anchor) - (this.lift + this.rise * this.wide);
    const edge = axis + Math.atan((2 * f - 1) * Math.tan(half));
    if (f >= 0.5) return Math.max(0, this.b - this.h / Math.tan(Math.min(edge, Math.PI / 2 - 0.01)));
    return edge <= 0.02 ? 999 : Math.max(0, this.h / Math.tan(edge) - this.b);
  }

  private apply(): void {
    const a = this.shakeAmount * this.shakeScale;
    const s = a * a;
    // 平滑噪声：三路不成整数比的正弦叠加（-1..1），和原来每帧随机跳的均方根差不多，但不糊
    const c = this.clock;
    const nx = Math.sin(c * 37.1) * 0.5 + Math.sin(c * 23.3 + 1.7) * 0.3 + Math.sin(c * 53.9 + 0.4) * 0.2;
    const ny = Math.sin(c * 31.7 + 2.1) * 0.5 + Math.sin(c * 19.9 + 0.6) * 0.3 + Math.sin(c * 47.3 + 2.9) * 0.2;
    // 余震：低频的上下左右晃（不是每帧随机抖），越来越弱；震动设置为「关」时也不晃
    const r = this.rumbleA * (this.rumbleT / this.rumbleDur) * Math.min(1, this.shakeScale);
    const fov = this.place(this.camera, nx * 0.6 * s * 1.6 + Math.sin(c * 9.3) * r * 0.5, ny * 0.6 * s * 1.2 + Math.sin(c * 12.7 + 1.3) * r * 0.7);
    if (Math.abs(this.camera.fov - fov) > 0.01) {
      this.camera.fov = fov;
      this.camera.updateProjectionMatrix();
    }
    // 后坐（T134）：机位不动，朝向偏一点，画面整体平移；震动设置照乘
    const k = this.shakeScale;
    if (k > 0 && (this.recX !== 0 || this.recY !== 0)) {
      this.camera.rotateY(this.recX * k);
      this.camera.rotateX(-this.recY * k);
    }
    this.place(this.still, 0, 0);
    this.still.updateMatrixWorld();
  }

  /** 按现在的机位摆好 cam：jx / jy = 震屏和余震叠在机位上的横向 / 竖向偏移（米）；返回这一帧的视角 */
  private place(cam: THREE.PerspectiveCamera, jx: number, jy: number): number {
    const [kf, kh] = this.kick();
    let px = this.x + jx;
    let py = this.h + jy + kh;
    let pz = this.z + this.b;
    let lx = this.x * 0.7;
    let ly = CAM.lookHeight;
    let lz = this.z + this.lookAheadDistance();
    let fov = this.fov + kf;
    // 首领战偏轴（T104）：机位和注视点一起绕坦克那一点转，坦克留在画面原来的位置
    const yaw = this.yawNow;
    if (Math.abs(yaw) > 1e-4) {
      const c = Math.cos(yaw);
      const s = Math.sin(yaw);
      const turn = (x: number, z: number): [number, number] => [this.x + (x - this.x) * c + (z - this.z) * s, this.z - (x - this.x) * s + (z - this.z) * c];
      [px, pz] = turn(px, pz);
      [lx, lz] = turn(lx, lz);
    }
    // 首领特写（T017-6）：转过去对着首领、往它那边推一段，剩下的靠收窄视角，让它占满画面宽度的 fill
    const S = this.show;
    const e = S.k * S.k * (3 - 2 * S.k);
    if (e > 1e-4) {
      const C = SHOWCASE;
      let hx = this.x - S.x;
      let hz = this.z + this.b - S.z;
      const hl = Math.hypot(hx, hz) || 1;
      hx /= hl;
      hz /= hl;
      // 竖屏按画面宽度框（横屏按高度）
      const fit = THREE.MathUtils.clamp(this.camera.aspect, 0.2, 1);
      const dist = S.r / (C.fill * Math.tan(THREE.MathUtils.degToRad(CAM.fov) / 2) * fit);
      const k = e * S.dolly;
      px += (S.x + hx * Math.cos(S.elev) * dist - px) * k;
      py += (S.y + Math.sin(S.elev) * dist - py) * k;
      pz += (S.z + hz * Math.cos(S.elev) * dist - pz) * k;
      lx += (S.x - lx) * e;
      ly += (S.y - ly) * e;
      lz += (S.z - lz) * e;
      const d = Math.hypot(px - S.x, py - S.y, pz - S.z);
      const need = THREE.MathUtils.radToDeg(2 * Math.atan(S.r / (C.fill * d) / fit));
      fov += (THREE.MathUtils.clamp(need, C.minFov, this.fov) - fov) * e;
    }
    cam.position.set(px, py, pz);
    cam.lookAt(lx, ly, lz);
    const lift = this.lift + this.rise * this.wide * (1 - e);
    if (lift > 0) cam.rotateX(lift);
    return fov;
  }
}
