/** 背景音乐曲目（T206）：设置页「曲目」子菜单和 Music 共用；全部程序合成，0 字节素材 */
export type BgmId = 'march' | 'drive' | 'scorch' | 'night' | 'boss' | 'redflag' | 'hellfire' | 'bayan' | 'redstorm';
/** auto = 按场景换：开始界面「钢铁进行曲」、作战按区域轮换、首领战「首领来袭」；autoRed = 同样按场景换，只放红色进行曲系列（T210） */
export type BgmPick = 'auto' | 'autoRed' | BgmId;

export const BGM_TRACKS: { id: BgmPick; name: string; note: string }[] = [
  { id: 'auto', name: '自动', note: '整备 · 推进 · 首领战按场景切换' },
  { id: 'march', name: '钢铁进行曲', note: '军鼓进行曲 · 开始界面' },
  { id: 'drive', name: '履带推进', note: '快节奏推进 · 作战' },
  { id: 'scorch', name: '焦土', note: '低沉紧张 · 作战' },
  { id: 'night', name: '夜巡', note: '稳步脉冲 · 作战' },
  { id: 'boss', name: '首领来袭', note: '高速压迫 · 首领战' },
  { id: 'autoRed', name: '红色 · 自动', note: '红色进行曲系列按场景切换' },
  { id: 'redflag', name: '红旗进行曲', note: '男声合唱 + 铜管 · 开始界面' },
  { id: 'hellfire', name: '钢铁洪流', note: '军靴踏步 + 失真吉他 · 作战' },
  { id: 'bayan', name: '风雪手风琴', note: '手风琴 + 轮指弹拨 · 作战' },
  { id: 'redstorm', name: '红色风暴', note: '合唱 + 铜管 + 定音鼓 · 首领战' },
];

/** 音量 0..10 档（每档 10%） */
export const BGM_VOL_MAX = 10;

export const bgmName = (id: string): string => BGM_TRACKS.find((t) => t.id === id)?.name ?? BGM_TRACKS[0].name;

/** 「自动」两项是播放方式，不是一首曲子：音乐列表里只能选用，不能试听 */
export const isBgmAuto = (id: BgmPick): id is 'auto' | 'autoRed' => id === 'auto' || id === 'autoRed';

/** 设置页「音乐」入口右边那行（T216）：开着写曲目和音量，关着写「已关闭」 */
export const musicStatus = (on: boolean, vol: number, pick: BgmPick): string => (on ? `${bgmName(pick)} · ${vol * 10}%` : '已关闭');

/** 音乐列表（T216）的提示行和每行右边的选用键 */
export const MUSIC_HINT = '点曲名试听，再点一下停止';
export const useLabel = (picked: boolean, on: boolean): string => (picked ? (on ? '使用中' : '已选') : '选用');
