import * as THREE from 'three';

/**
 * 预警 / 标记的颜色（T130，制作人「红色应该是敌人攻击预警的配色」）。新加的圈、线、框、弧标一律从这里取，不许各处各写。
 * 只管预警和标记；炮口火、电弧、爆炸、火焰这些特效本身的颜色不归这里。
 */

/** 敌方攻击预警：红圈、冲撞线、瞄准线、部件预警亮光、画面边缘弧标。全游戏只用这一个红 */
export const WARN_ENEMY = 0xff3a2a;
/**
 * 我方落点 / 范围 / 瞄准：迫击炮、空袭、究极落点、锁定框、指示烟。浅暖黄，我方不用红。
 * 3D 画面出图有 ACES 色调映射，亮色会发白：这个值在战场上显示成 #e6d996 左右的浅黄（再淡就成了奶白，和缺口白分不开）
 */
export const MARK_SELF = 0xffdc6e;
/** 弹幕缺口（能躲进去的那一格）：冷白，和我方浅黄分开 */
export const MARK_GAP = 0xe8f0ff;
/** 我方够不着（T131 对空仰角）：天上的目标太高、主武器抬不上去时套在它身上的框和「仰角不够」，灰色 */
export const MARK_OUT = 0xa4abb4;

/** '#rrggbb'（画布 / CSS 用） */
export const cssHex = (c: number): string => `#${c.toString(16).padStart(6, '0')}`;

/** 'r, g, b'（拼 rgba 用；CSS 里写 rgba(var(--mark-self-rgb), 0.8)） */
export const cssRgb = (c: number): string => `${(c >> 16) & 255}, ${(c >> 8) & 255}, ${c & 255}`;

/** 着色器里直接写的颜色：线性色 × k（超过 1 吃泛光），写成 GLSL 的 vec3 */
export function glslColor(c: number, k = 1): string {
  const v = new THREE.Color(c);
  return `vec3(${(v.r * k).toFixed(3)}, ${(v.g * k).toFixed(3)}, ${(v.b * k).toFixed(3)})`;
}

/** 网页版界面的 CSS 变量：--warn-enemy / --mark-self / --mark-out，各带一份 -rgb */
export function markCssVars(el: HTMLElement): void {
  for (const [k, c] of [['warn-enemy', WARN_ENEMY], ['mark-self', MARK_SELF], ['mark-out', MARK_OUT]] as const) {
    el.style.setProperty(`--${k}`, cssHex(c));
    el.style.setProperty(`--${k}-rgb`, cssRgb(c));
  }
}
