import { createCanvas } from './canvas/Overlay';
import { box, font, icon, shadow, text } from './canvas/paint';
import type { MedalTier } from '../meta/achievements';
import { paintMedal } from './medals';

/**
 * 战绩卡（T018-2 / 策划 `T018-新想法-策划案.md` 第 4 节方案 A）：9:16 竖版 720 × 1280，底图 = 这局抓到的高光截图（没有就用深色渐变），
 * 叠评级 / 推进米数 / 区域 · 击毁 · 等级 · 用时 / 构筑条（核心 + 究极 + 副武器图标，★ = 进化）/ 首领 / 日期。
 * 纯 2D 画布、只用真机 2D 上下文有的接口（paint.ts 的圆角 / 字间距 / SVG 图标），DOM 版和画布版（微信小游戏）共用这一份画法。
 * 分享不给任何奖励、卡上不写任何「分享领取」之类的文案（T015 红线）；不用大面积红色、没有国旗 / 真实徽记，全中文
 */
export interface ShareData {
  runs: number;
  /** 评级：新兵 / 老兵 / 精英 / 王牌（0..3） */
  tier: number;
  distance: number;
  zone: number;
  kills: number;
  level: number;
  /** 本局用时（秒） */
  time: number;
  core: { icon: string; name: string };
  ult: { icon: string; name: string; fired: number } | null;
  weapons: { icon: string; evolved: boolean }[];
  bosses: { name: string; ok: boolean }[];
  newBest: boolean;
  /** 本局高光那一刻的说明（底图的出处，比如「核弹（究极）」「击破猛犸」） */
  moment: string;
  /** 佩戴的称号（T018-3） */
  title?: string;
  /** 佩戴的勋章（T030 勋章墙挑的最多 3 枚） */
  medals?: { tier: MedalTier; icon: string }[];
}

export const RATING = ['新兵', '老兵', '精英', '王牌'];
/** 评级的分数线（第一次玩按固定线；策划写的「按本地排行榜分位」没做，见报告） */
export const RATING_LINE = [3000, 8000, 15000];
const TIER_COLOR = ['#8a8f96', '#7fa6c9', '#c9925a', '#ffd25a'];

export const ratingOf = (score: number) => RATING_LINE.filter((l) => score >= l).length;

const time = (s: number) => `${Math.floor(s / 60)} 分 ${Math.floor(s % 60)} 秒`;

/** 画一张战绩卡；bg = 高光截图（任意宽高，按 cover 铺满）；返回画布（调用方 toDataURL / toTempFilePathSync） */
export function shareCard(d: ShareData, bg: CanvasImageSource & { width: number; height: number } | null): HTMLCanvasElement {
  const W = 720;
  const H = 1280;
  const cv = createCanvas();
  cv.width = W;
  cv.height = H;
  const g = cv.getContext('2d') as CanvasRenderingContext2D;
  g.fillStyle = '#0c0e12';
  g.fillRect(0, 0, W, H);
  if (bg && bg.width > 0) {
    // 底图 cover 铺满，上 3/5 是画面主体
    const k = Math.max(W / bg.width, (H * 0.78) / bg.height);
    const bw = bg.width * k;
    const bh = bg.height * k;
    g.drawImage(bg, (W - bw) / 2, Math.max(0, H * 0.36 - bh / 2), bw, bh);
    // 调色：偏暖 + 提一点对比（叠一层暖色，再压暗角）
    g.fillStyle = 'rgba(255, 170, 90, 0.08)';
    g.fillRect(0, 0, W, H);
  } else {
    const lg = g.createLinearGradient(0, 0, 0, H);
    lg.addColorStop(0, '#2a241c');
    lg.addColorStop(1, '#0c0e12');
    g.fillStyle = lg;
    g.fillRect(0, 0, W, H);
  }
  const vg = g.createRadialGradient(W / 2, H * 0.36, H * 0.18, W / 2, H * 0.4, H * 0.75);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(1, 'rgba(0,0,0,0.55)');
  g.fillStyle = vg;
  g.fillRect(0, 0, W, H);
  // 顶栏
  const top = g.createLinearGradient(0, 0, 0, 170);
  top.addColorStop(0, 'rgba(8, 9, 12, 0.85)');
  top.addColorStop(1, 'rgba(8, 9, 12, 0)');
  g.fillStyle = top;
  g.fillRect(0, 0, W, 170);
  shadow(g, 'rgba(0,0,0,0.8)', 10, 3);
  g.font = font(48, 900);
  text(g, '钢铁破坏者', 40, 64, '#f2ead8', 'left', 8);
  g.font = font(22, 700);
  text(g, `第 ${d.runs} 次出击`, W - 40, 64, '#d9c9a0', 'right', 1);
  shadow(g, null);
  // 评级铭牌
  const tc = TIER_COLOR[d.tier] ?? TIER_COLOR[0];
  box(g, 40, 104, 196, 46, 10, 'rgba(14, 16, 20, 0.78)', tc, 2);
  g.font = font(22, 800);
  text(g, `评级：${RATING[d.tier] ?? RATING[0]}`, 40 + 98, 127, tc, 'center', 2);
  if (d.title) {
    g.font = font(22, 800);
    shadow(g, 'rgba(0,0,0,0.8)', 6, 2);
    text(g, `「${d.title}」`, 252, 127, '#ffe08a', 'left', 2);
    shadow(g, null);
  }
  // 佩戴的勋章：评级铭牌下面一排
  (d.medals ?? []).forEach((m, i) => paintMedal(g, 66 + i * 58, 196, 24, m.tier, m.icon, true));
  if (d.newBest) {
    box(g, W - 196, 104, 156, 46, 10, 'rgba(60, 40, 10, 0.85)', '#ffd25a', 2);
    g.font = font(22, 900);
    text(g, '新纪录', W - 118, 127, '#ffe08a', 'center', 4);
  }
  // 下半：数据板
  const bot = g.createLinearGradient(0, H * 0.56, 0, H);
  bot.addColorStop(0, 'rgba(8, 9, 12, 0)');
  bot.addColorStop(0.22, 'rgba(8, 9, 12, 0.82)');
  bot.addColorStop(1, 'rgba(8, 9, 12, 0.96)');
  g.fillStyle = bot;
  g.fillRect(0, H * 0.56, W, H * 0.44);
  if (d.moment) {
    g.font = font(20, 600);
    text(g, `本局高光 · ${d.moment}`, W / 2, 790, '#c9c2b0', 'center', 1);
  }
  shadow(g, 'rgba(0,0,0,0.9)', 14, 4);
  g.font = font(24, 700);
  text(g, '推进', W / 2, 840, '#d9a64a', 'center', 6);
  g.font = font(110, 900);
  const nw = text(g, String(Math.floor(d.distance)), W / 2 - 24, 920, '#fff2d6', 'center', 2);
  g.font = font(40, 800);
  text(g, '米', W / 2 - 24 + nw / 2 + 12, 936, '#fff2d6', 'left');
  shadow(g, null);
  g.font = font(28, 600);
  text(g, `区域 ${d.zone} · 击毁 ${d.kills} · ${d.level} 级 · 用时 ${time(d.time)}`, W / 2, 1000, '#e8e2d0', 'center');
  g.fillStyle = 'rgba(255, 255, 255, 0.16)';
  g.fillRect(60, 1036, W - 120, 2);
  // 构筑条：核心 + 究极，下面一排副武器（★ = 进化）
  let x = 60;
  const chip = (ic: string, label: string, gold: boolean) => {
    g.font = font(24, 800);
    const w = 64 + label.length * 25;
    box(g, x, 1058, w, 52, 12, gold ? 'rgba(70, 52, 20, 0.88)' : 'rgba(22, 24, 28, 0.88)', gold ? '#ffcf6a' : 'rgba(255,255,255,0.22)', 2);
    icon(g, ic, x + 12, 1068, 32, gold ? '#ffe08a' : '#e8d8b0', 1.8);
    text(g, label, x + 54, 1085, '#f2ead8');
    x += w + 14;
  };
  chip(d.core.icon, d.core.name, false);
  if (d.ult) chip(d.ult.icon, `${d.ult.name} ×${d.ult.fired}`, true);
  x = 60;
  for (const w of d.weapons) {
    box(g, x, 1126, 56, 56, 12, 'rgba(22, 24, 28, 0.88)', w.evolved ? '#ffcf6a' : 'rgba(255,255,255,0.22)', 2);
    icon(g, w.icon, x + 12, 1138, 32, '#e8d8b0', 1.8);
    if (w.evolved) {
      g.font = font(20, 900);
      text(g, '★', x + 50, 1176, '#ffd25a', 'right');
    }
    x += 66;
  }
  // 首领 + 日期
  g.font = font(22, 600);
  const bossLine = d.bosses.map((b) => `${b.name} ${b.ok ? '✓' : '✗'}`).join('　');
  text(g, `首领　${bossLine}`, 60, 1216, '#c9c2b0');
  const now = new Date();
  g.font = font(20, 500);
  text(g, `${now.getFullYear()}.${now.getMonth() + 1}.${now.getDate()}`, W - 60, 1216, '#8a8f96', 'right');
  return cv;
}

/** 局内分享键截的图套一条底部战绩条（T018-2 3c）：游戏名 + 区域 · 米数 + 究极名；src = 画好的游戏画面 */
export function shotWithBar(src: CanvasImageSource & { width: number; height: number }, line: string): HTMLCanvasElement {
  const w = Math.min(1080, src.width);
  const k = w / src.width;
  const h = Math.round(src.height * k);
  const bar = Math.round(w * 0.12);
  const cv = createCanvas();
  cv.width = w;
  cv.height = h + bar;
  const g = cv.getContext('2d') as CanvasRenderingContext2D;
  g.drawImage(src, 0, 0, w, h);
  g.fillStyle = '#0c0e12';
  g.fillRect(0, h, w, bar);
  g.fillStyle = 'rgba(255, 207, 106, 0.7)';
  g.fillRect(0, h, w, Math.max(2, bar * 0.03));
  const s = bar / 120;
  g.font = font(Math.round(40 * s), 900);
  text(g, '钢铁破坏者', Math.round(32 * s), h + bar / 2, '#f2ead8', 'left', Math.round(6 * s));
  g.font = font(Math.round(28 * s), 600);
  text(g, line, w - Math.round(32 * s), h + bar / 2, '#d9c9a0', 'right');
  return cv;
}
