export interface FoeCell {
  key: string;
  title: string;
  line: string;
  locked: boolean;
  fresh: boolean;
  boss: boolean;
}

export interface FoeDetail {
  key: string;
  locked: boolean;
  title: string;
  tag: string;
  bars: [string, number][];
  armor: string;
  lines: [string, string][];
  parts: string[];
  partsTitle: string;
  prev: string | null;
  next: string | null;
}

/** 图鉴需要的存档状态：unlocks（遇到过 / 看过）、累计击毁、本局遇到过的键 */
export interface FoeState {
  unlocks: readonly string[];
  kills: Readonly<Record<string, number>>;
  run: ReadonlySet<string>;
  /** 「云垒」单局最多拆几件（T100B，图鉴「交手 N 次 · 最多拆 X/6」） */
  skyBest?: number;
}

const step = (v: number, cuts: number[]) => 1 + cuts.filter((c) => v >= c).length;

/** 普通敌人的三条格：耐久 / 火力 / 速度（各 5 格），按 ENEMY_SPECS 自动换算（改数值自动跟着变） */
function barsOf(kind: EnemyKind): [number, number, number] {
  const s = ENEMY_SPECS[kind];
  const dps = (s.fireInterval > 0 ? (s.bulletDamage * (s.burst ?? 1)) / s.fireInterval : 0) + (s.explode ? s.explode[1] * 0.3 : 0) + s.contactDamage * 0.05;
  return [step(s.hp, [8, 30, 90, 300]), step(dps, [0.5, 2, 4, 7]), s.speed <= 0 ? 1 : step(s.speed, [1.5, 3.2, 4.8, 7])];
}

export const foeSeen = (st: FoeState, key: string) => st.unlocks.includes(key);
export const foeFresh = (st: FoeState, key: string) => st.run.has(key) && !st.unlocks.includes(`foe-read:${key}`);
/** 有没有本局新遇到、还没看过的（暂停页「图鉴」键上的金色小点） */
export const foeAnyFresh = (st: FoeState) => FOES.some((f) => foeFresh(st, f.key));

export function foeCells(st: FoeState, page: FoePageId): FoeCell[] {
  return FOES.filter((f) => f.page === page).map((f) => {
    const locked = !foeSeen(st, f.key);
    return { key: f.key, title: locked ? '?' : f.title, line: locked ? '' : `${f.role} · 第 ${f.zone} 区`, locked, fresh: !locked && foeFresh(st, f.key), boss: f.page === 'foe-boss' };
  });
}

export function foeDetail(st: FoeState, key: string): FoeDetail | null {
  const f = FOES.find((x) => x.key === key);
  if (!f) return null;
  const list = FOES.filter((x) => x.page === f.page);
  const i = list.indexOf(f);
  const locked = !foeSeen(st, key);
  const [hp, fire, speed] = f.bars ?? barsOf(f.kind!);
  const spec = f.kind ? ENEMY_SPECS[f.kind] : null;
  const armor = f.armor ?? (!spec ? '重甲 · 几个部件分开打' : spec.armor === 'heavy' ? '重甲 · 火箭 / 机枪 / 火神打折' : spec.crushable ? '无甲 · 能直接碾过去' : '轻甲');
  const where = `第 ${f.zone} 区起${f.zoneNote ? `（${f.zoneNote}）` : ''}`;
  return {
    key,
    locked,
    title: locked ? '?' : f.title,
    tag: locked ? '' : f.role,
    bars: locked ? [] : [['耐久', hp], ['火力', fire], ['速度', speed]],
    armor: locked ? '' : armor,
    lines: locked ? [] : [['行为', f.behavior], ['打法', f.tactics], ['出没', where], ['战绩', key === 'boss:4' ? `交手 ${st.kills[key] ?? 0} 次 · 最多拆 ${st.skyBest ?? 0}/6` : `累计击毁 ${st.kills[key] ?? 0}`]],
    parts: locked ? [] : f.parts ?? [],
    partsTitle: f.partsTitle ?? '部件',
    prev: i > 0 ? list[i - 1].key : null,
    next: i < list.length - 1 ? list[i + 1].key : null,
  };
}
