export interface EnemySpec {
  hp: number;
  speed: number;
  radius: number;
  /** 撞上玩家造成的伤害（轻坦 / 运兵车） */
  contactDamage: number;
  /** 开火间隔，0 表示不开火 */
  fireInterval: number;
  shot: ShotKind;
  bulletDamage: number;
  bulletSpeed: number;
  /** 掉落的废铁总量（= 经验） */
  scrap: number;
  /** 保持的交战距离，0 表示一路冲上来 */
  standoff: number;
  /** 步兵类：被履带碾过直接被毁，不伤玩家 */
  crushable: boolean;
  /** 拦路精英：原地据守，玩家进入交战距离后必须停车攻坚 */
  blocker: boolean;
  /** 自动瞄准的威胁值（步枪兵 = 1，越大越先打）：等效距离 = (距离 + 10 米) ÷ 威胁值，见 Game.ts 的 PICK */
  threat: number;
  /** 开火前亮瞄准线（反坦克兵、反坦克炮） */
  telegraph?: boolean;
  /** 被毁 / 撞上时爆炸：[半径, 伤害]（自爆卡车） */
  explode?: [number, number];
  /** 到位后放下几个步兵（运兵车） */
  unload?: number;
  /** 绕到玩家侧面（摩托） */
  flank?: boolean;
  /** 不会移动（阵地） */
  fixed?: boolean;
  /** 护甲等级（默认：步兵类无甲，其余轻甲） */
  armor?: ArmorClass;
  /** 连发：一次开火打出几发（机枪组 / 加特林） */
  burst?: number;
  /** 连发间隔（秒），默认 0.09 */
  burstGap?: number;
  /** 连发时枪口左右扫的幅度（弧度），默认 0.06；火箭炮车扫得很开 */
  burstSpread?: number;
  /** 遭遇型精英（破城槌）：不据守、来回冲撞；冲到跟前坦克就停车跟它周旋（它冲到身后 90 米内也不开走） */
  charger?: boolean;
  /** 空中单位（T091）：飞行高度（米，离路面）；行为、开火、坠落都归 systems/Air.ts */
  air?: number;
  /** 空中单位的平面判定外形（T098）：几段胶囊 [x0, z0, x1, z1, 半径]（模型坐标，机头 +Z，乘体型、跟着机头转），和判定圆一起用，见 Enemy.airReach */
  foot?: [number, number, number, number, number][];
}

