/** 瞄准线：开火前瞄准时长 / 最后锁定不再跟踪的时长 */
/** 残骸用的凹凸变形版几何体：按顶点位置哈希做三维位移（同位置顶点位移相同，不开裂），顶面往下塌 */
const dentCache = new WeakMap<THREE.BufferGeometry, THREE.BufferGeometry>();
export function dented(src: THREE.BufferGeometry): THREE.BufferGeometry {
  let g = dentCache.get(src);
  if (g) return g;
  g = copyGeometry(src);
  const p = g.getAttribute('position') as THREE.BufferAttribute;
  g.computeBoundingBox();
  const top = g.boundingBox!.max.y;
  const h = (x: number, y: number, z: number, k: number) => {
    const v = Math.sin(x * 12.9898 + y * 78.233 + z * 37.719 + k) * 43758.5453;
    return v - Math.floor(v) - 0.5;
  };
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i);
    const y = p.getY(i);
    const z = p.getZ(i);
    // 低频大坑 + 高频小坑
    const qx = Math.round(x * 2) / 2;
    const qy = Math.round(y * 2) / 2;
    const qz = Math.round(z * 2) / 2;
    const big = h(qx, qy, qz, 3.1);
    const amt = 0.12 + 0.18 * Math.max(0, y / Math.max(0.5, top));
    p.setXYZ(i, x + h(x, y, z, 1.7) * 0.12, y + big * amt * 1.6 - Math.max(0, big) * 0.1 + h(x, y, z, 5.3) * 0.08, z + h(x, y, z, 9.1) * 0.12);
  }
  g.computeVertexNormals();
  dentCache.set(src, g);
  return g;
}

