/**
 * 每个部件原来的材质 / 几何体（残骸换成焦黑、凹陷，复用时换回来）。
 * 不放 userData：Object3D.clone() 把 userData 过一遍 JSON，材质连贴图一起序列化，小游戏里会调到 toDataURL 红屏（T118）
 */
const BASE = new WeakMap<THREE.Mesh, { mat: THREE.Material; geo?: THREE.BufferGeometry }>();

/** beamHit 的返回值（复用一个） */
const BEAM_HIT = { t: 0, top: 0 };

/** 车身包围盒（模型本地坐标）：车体 + 挂板，不算炮塔（炮管伸出车头 3 米，算进去光束会停在半空） */
function shellBox(body: Body): THREE.Box3 {
  const box = new THREE.Box3();
  const tmp = new THREE.Box3();
  for (const m of body.meshes) {
    if (m.userData.glow || m.parent !== body.root) continue;
    if (!m.geometry.boundingBox) m.geometry.computeBoundingBox();
    box.union(tmp.copy(m.geometry.boundingBox!).translate(m.position));
  }
  return box;
}

/** 车身在地上占的那一块（模型本地坐标）：shellBox 再加上铁壁车头那片能量盾（T109：贴车身不钻进盾里） */
function footBox(body: Body): THREE.Box3 {
  const box = (body.shell ??= shellBox(body)).clone();
  const tmp = new THREE.Box3();
  for (const m of body.meshes) {
    if (!m.userData.shield) continue;
    if (!m.geometry.boundingBox) m.geometry.computeBoundingBox();
    box.union(tmp.copy(m.geometry.boundingBox!).translate(m.position));
  }
  return box;
}

/** 包围盒在地上绕 y 转 yaw 以后朝 +z（朝玩家）最远到哪（离原点多远；T109 车身限位，精英 / 首领共用） */
export function boxFront(b: THREE.Box3, yaw: number): number {
  const c = Math.cos(yaw);
  const s = Math.sin(yaw);
  return Math.max(b.min.z * c, b.max.z * c) + Math.max(-b.min.x * s, -b.max.x * s);
}

