import type { Listener, RoomTransport } from './onlineTransport';
import { ONLINE_VERSION } from './onlineProtocol';

type Options = { success?: Listener; fail?: Listener; [key: string]: unknown };
/** 同源 /ws；生产网页与房间服务由同一进程提供。 */
export class WebRoomTransport implements RoomTransport {
  private socket: WebSocket | null = null;
  private seq = 0;
  private pending = new Map<number, { resolve: Listener; reject: Listener; timer: ReturnType<typeof setTimeout> }>();
  private listeners = new Map<string, Set<Listener>>();
  private closed = false;
  // 导航进入浏览器页面缓存也算离场，不能留下占位连接。
  private readonly pageHide = (): void => { this.socket?.close(1000); };

  async login(): Promise<void> {
    const url = new URL('/ws', location.href);
    url.protocol = location.protocol === 'https:' ? 'wss:' : 'ws:';
    const ws = this.socket = new WebSocket(url);
    await new Promise<void>((resolve, reject) => {
      const timer = setTimeout(() => { reject(new Error('连接超时')); this.close(); }, 10_000);
      ws.onopen = () => { clearTimeout(timer); resolve(); };
      ws.onerror = () => { clearTimeout(timer); reject(new Error('无法连接房间服务')); };
      ws.onclose = () => {
        window.removeEventListener('pagehide', this.pageHide);
        clearTimeout(timer);
        reject(new Error('连接已断开'));
        for (const p of this.pending.values()) { clearTimeout(p.timer); p.reject(new Error('连接已断开')); }
        this.pending.clear();
        if (!this.closed) this.emit('Disconnect');
      };
      ws.onmessage = event => {
        let m;
        try { m = JSON.parse(event.data); } catch { return; }
        if (m.id) {
          const p = this.pending.get(m.id);
          if (!p) return;
          this.pending.delete(m.id); clearTimeout(p.timer);
          if (m.error) p.reject(m.error); else p.resolve(m.result);
        } else if (typeof m.event === 'string') this.emit(m.event, m.data);
      };
      window.addEventListener('pagehide', this.pageHide);
    });
  }
  private emit(name: string, data?: unknown): void { this.listeners.get(name)?.forEach(fn => fn(data)); }
  private on(name: string, fn: Listener): void {
    if (!this.listeners.has(name)) this.listeners.set(name, new Set());
    this.listeners.get(name)!.add(fn);
  }
  private off(name: string, fn: Listener): void { this.listeners.get(name)?.delete(fn); }
  private call(op: string, options: Options = {}): void {
    const { success, fail, ...data } = options;
    const ws = this.socket;
    if (ws?.readyState !== WebSocket.OPEN || ws.bufferedAmount > 2_000_000) { fail?.(new Error('连接中断或拥堵')); return; }
    const id = ++this.seq;
    const timer = setTimeout(() => {
      this.pending.delete(id); fail?.(new Error('请求超时'));
    }, 10_000);
    this.pending.set(id, { resolve: value => success?.(value), reject: error => fail?.(error), timer });
    ws.send(JSON.stringify({ id, op, data: { ...data, version: ONLINE_VERSION } }));
  }
  createRoom(o: Options): void { this.call('create', o); }
  joinRoom(o: Options): void { this.call('join', o); }
  getRoomInfo(o: Options): void { this.call('info', o); }
  broadcastInRoom(o: Options): void { this.call('relay', o); }
  startGame(o: Options): void { this.call('start', o); }
  endGame(o: Options): void { this.call('end', o); }
  restart(o: Options): void { this.call('restart', o); }
  ownerLeaveRoom(o: Options): void { this.call('leave', o); }
  memberLeaveRoom(o: Options): void { this.call('leave', o); }
  onBroadcast(fn: Listener): void { this.on('Broadcast', fn); }
  offBroadcast(fn: Listener): void { this.off('Broadcast', fn); }
  onRoomInfoChange(fn: Listener): void { this.on('RoomInfoChange', fn); }
  offRoomInfoChange(fn: Listener): void { this.off('RoomInfoChange', fn); }
  onGameStart(fn: Listener): void { this.on('GameStart', fn); }
  offGameStart(fn: Listener): void { this.off('GameStart', fn); }
  onGameEnd(fn: Listener): void { this.on('GameEnd', fn); }
  offGameEnd(fn: Listener): void { this.off('GameEnd', fn); }
  onDisconnect(fn: Listener): void { this.on('Disconnect', fn); }
  offDisconnect(fn: Listener): void { this.off('Disconnect', fn); }
  close(): void {
    this.closed = true;
    window.removeEventListener('pagehide', this.pageHide);
    this.socket?.close();
  }
}
