import * as THREE from 'three';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
import { GeoCache, type PartSpec } from '../assets/GeoCache';
import { buildCoreTurret, buildPlayerTank } from '../assets/models/playerTank';
import { MAT } from '../assets/materials';
import { sharedMetalNormal } from './sharedTextures';
import { createCanvas } from '../ui/canvas/Overlay';
import type { CoreId } from '../weapons/defs';
import { buildShowroomBackdrop, buildTurntableBackdrop } from './TurntableBackdrop';
import { buildBattlefieldBackdrop } from './BattlefieldBackdrop';
import { buildGarageBackdrop } from './GarageBackdrops';
import { pickBackdrop } from './backdropPick';
import type { OrbitPose } from '../ui/StageOrbit';

/** 坐标用界面逻辑像素；偏移沿用轮播的连续位置。 */
export interface TurntableView {
  x: number;
  y: number;
  w: number;
  h: number;
  core: CoreId;
  items: { id: CoreId; offset: number }[];
  /** T183 环视目标姿态（相对默认机位）；不给 = 默认机位 */
  orbit?: OrbitPose;
}

const BACK = 0x10181b;
const IDS: CoreId[] = ['cannon', 'rocket', 'laser', 'vulcan'];
type Backdrop = ReturnType<typeof buildTurntableBackdrop> & { sky?: THREE.Color; fog?: [number, number] };
/** 默认机位：原三分之四前侧俯视（方向 -0.76, 0.48, -1）；车头固定在原转台起始角 */
const BASE_YAW = Math.atan2(-0.76, -1);
const BASE_PITCH = Math.atan2(0.48, Math.hypot(0.76, 1));
const HEADING = -0.08;
const REST: OrbitPose = { yaw: 0, pitch: 0, zoom: 1 };

/**
 * Studio 的实时整备台。只借用游戏渲染器，不创建画布或动画循环。
 * 四辆展示车（T083 加火神）与地台各建一次；离开菜单停转，关游戏时统一释放。
 * T183：车不再自转，改成镜头绕车 360° 环视（姿态由开始页的 StageOrbit 给），画面铺满整屏，整备窗只决定取景中心与大小。
 */
export class Turntable {
  readonly stats = {
    active: false, frames: 0, angle: 0, models: IDS.length, calls: 0, triangles: 0,
    backdrop: 'showroom', bg: '0', yaw: 0, pitch: 0, zoom: 1, distance: 0,
  };
  private readonly scene = new THREE.Scene();
  private readonly camera = new THREE.PerspectiveCamera(32, 1, 0.1, 400);
  private readonly geo = new GeoCache();
  private readonly materials = new Set<THREE.Material>();
  private readonly textures = new Set<THREE.Texture>();
  private readonly geometries = new Set<THREE.BufferGeometry>();
  private readonly vehicles = new Map<CoreId, THREE.Group>();
  private readonly rotors = new Map<CoreId, THREE.Group>();
  private readonly shadow: THREE.DirectionalLight;
  private readonly environment: THREE.WebGLRenderTarget;
  private readonly dust: THREE.Points;
  private readonly backdrop: Backdrop;
  private readonly viewport = new THREE.Vector4();
  private readonly scissor = new THREE.Vector4();
  private readonly clearColor = new THREE.Color();
  private readonly size = new THREE.Vector2();
  private readonly target = new THREE.Vector3(0, 1.4, 0);
  private readonly right = new THREE.Vector3();
  private readonly reduced = typeof matchMedia === 'function' ? matchMedia('(prefers-reduced-motion: reduce)') : null;
  private readonly pose: OrbitPose = { ...REST };
  private readonly band = new THREE.Vector2(1, 0);
  private readonly aspectU = { value: 1 };
  private last = 0;
  private time = 0;

  constructor(private readonly renderer: THREE.WebGLRenderer, lights: THREE.Group) {
    this.scene.background = new THREE.Color(BACK);
    this.scene.fog = new THREE.Fog(BACK, 35, 85);
    this.scene.add(lights);
    (lights.children[0] as THREE.HemisphereLight).intensity = 0.85;
    this.shadow = lights.getObjectByName('studio-key') as THREE.DirectionalLight;
    this.shadow.position.set(-8, 14, -9);
    this.shadow.color.setHex(0xffdfaf);
    this.shadow.intensity = 3.1;
    this.shadow.castShadow = true;
    this.shadow.shadow.mapSize.set(1024, 1024);
    Object.assign(this.shadow.shadow.camera, { left: -14, right: 14, top: 14, bottom: -14, near: 0.5, far: 50 });
    this.shadow.shadow.bias = -0.0003;
    this.shadow.shadow.normalBias = 0.035;
    const rim = lights.getObjectByName('studio-rim') as THREE.DirectionalLight;
    rim.color.setHex(0x8fbad0);
    rim.intensity = 2.6;
    const room = new RoomEnvironment();
    const pmrem = new THREE.PMREMGenerator(renderer);
    this.environment = pmrem.fromScene(room, 0.04);
    this.scene.environment = this.environment.texture;
    this.scene.environmentIntensity = 0.35;
    room.dispose();
    pmrem.dispose();

    const deck = this.deck();
    const crystal = this.material((MAT.prism as THREE.MeshStandardMaterial).clone());
    crystal.color.setHex(0x338dab);
    crystal.emissive.setHex(0x167da3);
    crystal.emissiveIntensity = 0.55;
    crystal.opacity = 0.97;
    const glass = this.material(MAT.prismLens.clone());
    glass.emissive.setHex(0x167da3);
    glass.emissiveIntensity = 0.22;
    const pilot = this.material((MAT.energyCyan as THREE.MeshStandardMaterial).clone());
    pilot.emissiveIntensity = 0.7;
    for (const id of IDS) {
      const slot = new THREE.Group();
      const rotor = new THREE.Group();
      const model = buildPlayerTank(this.geo);
      const body = model.body as THREE.MeshStandardMaterial;
      const metal = model.metal as THREE.MeshStandardMaterial;
      body.color.setHex(0xa4ad9b);
      body.normalScale.setScalar(0.12);
      body.roughness = 0.64;
      metal.color.setHex(0x9ca7aa);
      metal.normalScale.setScalar(0.1);
      metal.roughness = 0.36;
      for (const m of model.materials) this.materials.add(m);
      if (body.map) this.textures.add(body.map);
      for (const map of model.trackMaps) this.textures.add(map);
      const turret = buildCoreTurret(this.geo, id, null, false, model.body, model.metal);
      model.turret.add(turret.group);
      // T181：火箭发射舱不再换成未涂漆的青灰金属（和车身差一大截），和战场上一样刷车身车漆
      turret.group.traverse((o) => {
        if (!(o instanceof THREE.Mesh)) return;
        // 战场会改变全局镜片材质；展示车用独立材质，不跟随战斗充能。
        if (o.material === MAT.prism) o.material = crystal;
        if (o.material === MAT.prismLens) o.material = glass;
        if (o.material === MAT.energyCyan) o.material = pilot;
      });
      model.hull.scale.setScalar(id === 'cannon' ? 1 : 1.08);
      const bounds = new THREE.Box3().setFromObject(model.hull);
      const center = bounds.getCenter(new THREE.Vector3());
      model.hull.position.set(-center.x, 0.35 - bounds.min.y, -center.z);
      rotor.add(model.hull, deck.clone(true));
      slot.add(rotor);
      this.scene.add(slot);
      this.vehicles.set(id, slot);
      this.rotors.set(id, rotor);
    }
    this.backdrop = this.buildBackdrop();
    const lamp = new THREE.PointLight(0xffb56b, 30, 20, 2);
    lamp.position.set(-6, 6, -3);
    this.scene.add(lamp);
    this.dust = this.makeDust();
    this.scene.add(this.dust);
    this.edges();
    this.scene.traverse((o) => {
      if (o instanceof THREE.Mesh || o instanceof THREE.Points) this.geometries.add(o.geometry);
    });
  }

  /** 背景只建一次（?bg= 选的那一套，见 backdropPick.ts） */
  private buildBackdrop(): Backdrop {
    const pick = pickBackdrop();
    const k = pick.key;
    const backdrop: Backdrop = k === 'showroom' ? buildShowroomBackdrop()
      : k === 'foundry' || k === 'forest' ? buildBattlefieldBackdrop(this.geo, k)
      : k === 'workshop' ? buildTurntableBackdrop(this.geo) : buildGarageBackdrop(this.geo, k);
    this.scene.add(backdrop.group);
    for (const mat of backdrop.materials) this.materials.add(mat);
    for (const map of backdrop.textures) this.textures.add(map);
    (this.scene.background as THREE.Color).set(backdrop.sky ?? BACK);
    const fog = this.scene.fog as THREE.Fog;
    fog.color.copy(this.scene.background as THREE.Color);
    if (backdrop.fog) [fog.near, fog.far] = backdrop.fog;
    this.stats.backdrop = k;
    this.stats.bg = pick.id;
    return backdrop;
  }

  private material<T extends THREE.Material>(m: T): T {
    this.materials.add(m);
    return m;
  }

  private mesh(geometry: THREE.BufferGeometry, material: THREE.Material, parent: THREE.Object3D = this.scene): THREE.Mesh {
    const m = new THREE.Mesh(geometry, material);
    parent.add(m);
    return m;
  }

  private deck(): THREE.Group {
    const g = new THREE.Group();
    const iron = this.material(new THREE.MeshStandardMaterial({ color: 0x252d30, metalness: 0.72, roughness: 0.44 }));
    const brass = this.material(new THREE.MeshStandardMaterial({ color: 0x9b7950, metalness: 0.72, roughness: 0.4 }));
    const texture = this.deckTexture();
    const top = this.material(new THREE.MeshStandardMaterial({
      map: texture, color: 0xc7c9c2, metalness: 0.48, roughness: 0.63,
      normalMap: sharedMetalNormal(), normalScale: new THREE.Vector2(0.07, 0.07),
    }));
    this.mesh(new THREE.LatheGeometry([
      new THREE.Vector2(0, -0.18), new THREE.Vector2(6.45, -0.18),
      new THREE.Vector2(6.65, -0.05), new THREE.Vector2(6.65, 0.18),
      new THREE.Vector2(6.48, 0.31), new THREE.Vector2(0, 0.31),
    ], 96), iron, g).receiveShadow = true;
    const plate = this.mesh(new THREE.CircleGeometry(6.48, 96), top, g);
    plate.rotation.x = -Math.PI / 2;
    plate.position.y = 0.32;
    plate.receiveShadow = true;
    const lip = this.mesh(new THREE.TorusGeometry(6.52, 0.035, 5, 96), brass, g);
    lip.rotation.x = Math.PI / 2;
    lip.position.y = 0.24;
    const bolts: PartSpec[] = [];
    for (let i = 0; i < 40; i++) {
      const a = i * Math.PI * 2 / 40;
      bolts.push({ geo: new THREE.CylinderGeometry(0.055, 0.055, 0.05, 6), color: 0x9fa59d, pos: [Math.sin(a) * 6.22, 0.35, Math.cos(a) * 6.22] });
    }
    this.mesh(this.geo.merged('turntable-bolts', () => bolts), iron, g);
    return g;
  }

  private deckTexture(): THREE.CanvasTexture {
    const c = createCanvas();
    c.width = c.height = 512;
    const g = c.getContext('2d')!;
    g.fillStyle = '#414b4e';
    g.fillRect(0, 0, 512, 512);
    for (let i = 0; i < 12; i++) {
      const a = i * Math.PI / 6;
      g.beginPath(); g.moveTo(256, 256);
      g.arc(256, 256, 252, a, a + Math.PI / 6);
      g.closePath(); g.fillStyle = i % 2 ? '#3d474a' : '#465053'; g.fill();
      g.strokeStyle = '#273336'; g.lineWidth = 1.5; g.stroke();
    }
    for (let i = 0; i < 96; i++) {
      g.save(); g.translate(256, 256); g.rotate(i * Math.PI / 48);
      g.fillStyle = i % 8 === 0 ? '#bdab7a' : '#7d8984';
      g.fillRect(-1, 229, 2, i % 8 === 0 ? 16 : 6);
      g.restore();
    }
    // 稀疏磨痕；固定种子，切换与重进不换材质。
    let seed = 127;
    const rand = () => ((seed = Math.imul(seed, 1664525) + 1013904223 | 0) >>> 0) / 4294967296;
    for (let i = 0; i < 1800; i++) {
      g.fillStyle = i % 2 ? '#0a161619' : '#cbd6cc12';
      g.fillRect(rand() * 512, rand() * 512, 1 + rand() * 9, 0.5);
    }
    g.strokeStyle = '#8c8061'; g.lineWidth = 2;
    g.beginPath(); g.arc(256, 256, 216, 0, Math.PI * 2); g.stroke();
    g.strokeStyle = '#293538';
    g.beginPath(); g.arc(256, 256, 119, 0, Math.PI * 2); g.stroke();
    const map = new THREE.CanvasTexture(c);
    map.colorSpace = THREE.SRGBColorSpace;
    this.textures.add(map);
    return map;
  }

  private makeDust(): THREE.Points {
    const g = new THREE.BufferGeometry();
    const points = new Float32Array(48 * 3);
    for (let i = 0; i < 48; i++) {
      points[i * 3] = Math.sin(i * 13.1) * 12;
      points[i * 3 + 1] = 0.6 + (i % 19) * 0.48;
      points[i * 3 + 2] = Math.cos(i * 7.3) * 10;
    }
    g.setAttribute('position', new THREE.BufferAttribute(points, 3));
    return new THREE.Points(g, this.material(new THREE.PointsMaterial({
      color: 0xb7b9a3, size: 0.025, transparent: true, opacity: 0.24, depthWrite: false,
    })));
  }

  /**
   * 整屏压暗：整备窗以上（标题、军衔、局外成长）和以下（流派名、说明、开始按钮）渐暗到界面底色，四角再收一圈，
   * 字压在 3D 场景上仍看得清。band = 整备窗上下沿（屏幕 uv）。
   */
  private edges(): void {
    const mat = this.material(new THREE.ShaderMaterial({
      transparent: true, depthTest: false, depthWrite: false, toneMapped: false,
      uniforms: { ink: { value: new THREE.Color(BACK).convertLinearToSRGB() }, band: { value: this.band }, aspect: this.aspectU },
      vertexShader: 'varying vec2 vUv; void main(){ vUv=uv; gl_Position=vec4(position.xy,0.,1.); }',
      fragmentShader: `
        uniform vec3 ink;
        uniform vec2 band;
        uniform float aspect;
        varying vec2 vUv;
        void main() {
          float above = smoothstep(band.x - .02, band.x + .14, vUv.y);
          float below = 1. - smoothstep(band.y - .16, band.y + .02, vUv.y);
          float corner = smoothstep(.5, 1.15, length((vUv - .5) * vec2(aspect, 1.)));
          gl_FragColor = vec4(ink, max(max(above * .74, below * .8), corner * .5));
        }`,
    }));
    const fade = this.mesh(new THREE.PlaneGeometry(2, 2), mat);
    fade.frustumCulled = false;
    fade.renderOrder = 1000;
  }

  render(view: TurntableView): void {
    const r = this.renderer;
    const now = performance.now() / 1000;
    const dt = this.last ? Math.min(0.05, Math.max(0, now - this.last)) : 0;
    this.last = now;
    if (!this.reduced?.matches) this.time += dt;
    // 镜头追目标姿态；重新进开始页（last = 0）直接到位
    const goal = view.orbit ?? REST, p = this.pose;
    const k = dt ? 1 - Math.exp(-dt * 11) : 1;
    p.yaw += (goal.yaw - p.yaw) * k;
    p.pitch += (goal.pitch - p.pitch) * k;
    p.zoom += (goal.zoom - p.zoom) * k;
    r.getSize(this.size);
    this.camera.aspect = view.w / Math.max(1, view.h);
    // 按整圈轮廓留边，炮口与天线在转到侧面时仍在整备窗内；默认再退一成留出四周空间，拉近 / 拉远只改距离。
    const height = Math.max(10.2, 15.4 / this.camera.aspect) * 1.1;
    const distance = height / (2 * Math.tan(THREE.MathUtils.degToRad(16))) * p.zoom;
    const az = BASE_YAW + p.yaw, el = BASE_PITCH + p.pitch;
    this.camera.position.set(Math.sin(az) * Math.cos(el), Math.sin(el), Math.cos(az) * Math.cos(el))
      .multiplyScalar(distance).add(this.target);
    this.camera.lookAt(this.target);
    // 整备窗是取景框，画面向四周铺满整屏
    this.camera.setViewOffset(view.w, view.h, -view.x, -view.y, this.size.x, this.size.y);
    this.camera.updateProjectionMatrix();
    this.camera.updateMatrixWorld();
    this.band.set(1 - view.y / this.size.y, 1 - (view.y + view.h) / this.size.y);
    this.aspectU.value = this.size.x / Math.max(1, this.size.y);
    this.right.setFromMatrixColumn(this.camera.matrixWorld, 0);
    for (const item of view.items) {
      const slot = this.vehicles.get(item.id);
      if (!slot) continue;
      slot.visible = Math.abs(item.offset) < 0.98;
      slot.position.copy(this.right).multiplyScalar(item.offset * height / 1.1 * this.camera.aspect * 0.91 * p.zoom);
      this.rotors.get(item.id)!.rotation.y = HEADING;
    }
    this.dust.position.y = Math.sin(this.time * 0.16) * 0.25;
    this.backdrop.update(this.time);
    r.getViewport(this.viewport);
    r.getScissor(this.scissor);
    r.getClearColor(this.clearColor);
    const wasScissor = r.getScissorTest();
    const alpha = r.getClearAlpha();
    const auto = r.autoClear;
    const target = r.getRenderTarget();
    const shadows = r.shadowMap.enabled;
    const exposure = r.toneMappingExposure;
    try {
      r.info.reset();
      r.setRenderTarget(null);
      r.setScissorTest(false);
      r.setViewport(0, 0, this.size.x, this.size.y);
      r.setClearColor(BACK, 1);
      r.autoClear = true;
      r.shadowMap.enabled = true;
      r.toneMappingExposure = 1.08;
      r.render(this.scene, this.camera);
      this.stats.active = true;
      this.stats.frames++;
      this.stats.angle = az;
      this.stats.yaw = p.yaw;
      this.stats.pitch = el;
      this.stats.zoom = p.zoom;
      this.stats.distance = distance;
      this.stats.calls = r.info.render.calls;
      this.stats.triangles = r.info.render.triangles;
    } finally {
      r.setRenderTarget(target);
      r.setViewport(this.viewport);
      r.setScissor(this.scissor);
      r.setScissorTest(wasScissor);
      r.setClearColor(this.clearColor, alpha);
      r.autoClear = auto;
      r.shadowMap.enabled = shadows;
      r.toneMappingExposure = exposure;
    }
  }

  /** 启动预热（T108）：照 render 的设置（直接画到屏幕、开阴影）先编好整备台的着色器 */
  compile(): void {
    const r = this.renderer;
    const shadows = r.shadowMap.enabled;
    const target = r.getRenderTarget();
    r.setRenderTarget(null);
    r.shadowMap.enabled = true;
    r.compile(this.scene, this.camera);
    r.shadowMap.enabled = shadows;
    r.setRenderTarget(target);
  }

  pause(): void {
    this.last = 0;
    this.stats.active = false;
  }

  dispose(): void {
    this.pause();
    this.shadow.shadow.map?.dispose();
    this.environment.dispose();
    this.scene.traverse((o) => { if (o instanceof THREE.InstancedMesh) o.dispose(); });
    for (const g of this.geometries) g.dispose();
    this.geo.dispose();
    for (const m of this.materials) m.dispose();
    for (const t of this.textures) t.dispose();
    this.scene.clear();
    this.vehicles.clear();
    this.rotors.clear();
  }
}
