export interface BossContext {
  scene: THREE.Scene;
  geo: GeoCache;
  fx: Fx;
  streaks: Streaks;
  hazards: Hazards;
  debris: Debris;
  audio: AudioSystem;
  world: World;
  /** 主玩家位置（实时引用；镜头 / 演出 / 开场触发按它，打谁走 nearest） */
  player: THREE.Vector3;
  /** 离 (x, z) 最近的玩家车位置（T117，实时引用；现在只有一辆 = player） */
  nearest(x: number, z: number): THREE.Vector3;
  hpScale: number;
  spawnPart(spec: EnemySpec, x: number, z: number): Enemy | null;
  fire(shot: ShotKind, x: number, z: number, dirX: number, dirZ: number, speed: number, damage: number): void;
  artillery(x: number, z: number, tx: number, tz: number, damage: number, radius: number, flight?: number): void;
  /** at = 打中的是哪一辆（nearest 给的那个位置，T117）；不给 = 主玩家 */
  damagePlayer(amount: number, at?: THREE.Vector3): void;
  shake(amount: number): void;
  onDefeated(boss: Boss): void;
  /** 呼叫援军（返回刷出来的那个；刷不出来 null） */
  spawn(kind: EnemyKind, x: number, z: number): Enemy | null | void;
  /** 放一块混凝土掩体 */
  cover(x: number, z: number): void;
  announce(title: string, sub: string): void;
  /** 实体弹坑（T014-3）：首领被击毁大爆炸在残骸底下炸出一个浅坑 */
  crater?(x: number, z: number): void;
  /** 坍塌完、最后一声大爆炸那一刻（T041）：box = 残骸的包围盒（世界坐标，只在这次调用里有效）、edge = 残骸靠玩家这一侧的边（世界 z）——Game 从这里抛出首领战利品箱 */
  wrecked?(box: THREE.Box3, edge: number): void;
  /** 弹坑改变的地面高度（首领开进坑里跟着下沉） */
  groundAt?(x: number, z: number): number;
  /** 踩碎（S11 泰坦落脚 / 跺脚 / 地裂）：(x, z) 半径内的路障、掩体、车辆残骸、路边景物按爆炸力度 force 结算，不伤人 */
  smash?(x: number, z: number, radius: number, force: number): void;
  /** 巨炮的巨弹（T019-b）：从 (x, y, z) 高抛到 (tx, tz)，红圈 = 半径 + 2.4，落地中坑 */
  siegeShell?(x: number, y: number, z: number, tx: number, tz: number, damage: number, radius: number, flight: number): void;
  /** 低画质（D5 巨炮开炮的尘浪 / 硝烟粒子减半） */
  lowFx?(): boolean;
  /** 画质档（T142「云垒」按它降级；自动档降档时跟着变） */
  quality?(): 'high' | 'medium' | 'low';
  /** 从 (x, y, z) 抛一发敌方炮弹 / 火箭到 (tx, tz)，落点带红圈（T100B 空艇：从天上的部件打下来）；big = 弹体 / 落地爆炸放大 */
  lob?(x: number, y: number, z: number, tx: number, tz: number, damage: number, radius: number, flight: number, rocket?: boolean, big?: number): void;
  /** 机枪一发（T142「云垒」蜂鸣机枪）：从 (x, y, z) 斜着往下打向 (tx, tz)，小口径（复合装甲再减半），地上的掩体不挡 */
  gun?(x: number, y: number, z: number, tx: number, tz: number, speed: number, damage: number): void;
  /** 在 (x, z) 放一队 n 个飞蝗（T100B 蝗巢舱口） */
  locusts?(n: number, x: number, z: number): void;
  /** 直接扣部件耐久（固定伤害，T100B 加注罐火柱）：走 Game.damageEnemy，打掉照常结算 */
  hurt?(e: Enemy, amount: number): void;
  /** 把坦克从 (x, z) 往外推开 dist 米（T122 穿山破土 / 冲撞；at = 哪一辆） */
  push?(x: number, z: number, dist: number, at?: THREE.Vector3): void;
  /** (x, z) r 米里的油料（加油车 / 油桶垛 / 磕头机 / 储油罐）当场殉爆，返回炸了没有（T122 穿山钻进油料） */
  fuelAt?(x: number, z: number, r: number): boolean;
  /** (x, z) r 米里撞上的硬东西（T122 穿山第三阶段）：石柱（倒下砸在它身上）/ 磕头机、车壳这类 / 碎石岩板 / 油料（殉爆）；没有 null。(fx, fz) = 撞过来的方向 */
  hardAt?(x: number, z: number, r: number, fx: number, fz: number): 'pillar' | 'hard' | 'slab' | 'fuel' | null;
  /** 地面一震（T122）：r 米里的沙下伏兵掀出来 */
  quake?(x: number, z: number, r: number): void;
  /** 沙下伏兵：贴着坦克冒一个小包 / 场上还有几处（T122 穿山阶段一） */
  ambushSmall?(): void;
  ambushCount?(): number;
  /** 全场停火（T122 转场） */
  ceasefire?(on: boolean): void;
}

interface Part {
  e: Enemy;
  anchor: THREE.Object3D;
  core: boolean;
  /** 被击毁时炸飞 / 隐藏的那块模型 */
  visual: THREE.Object3D | null;
  dead: boolean;
  label: string;
}

/** 残骸上能被坦克压扁的一块（击败后坍塌完注册到 World 的凸起系统） */
export interface WreckPiece {
  /** 被压扁的那块模型：绕父节点原点沿 y 压，顶面始终和凸起一样高（不穿模） */
  obj: THREE.Object3D;
  bump: Bump;
  /** 压扁前的顶高 / 压完剩多高（世界坐标）、父节点离地高度、obj 原来的 y */
  top: number;
  low: number;
  base: number;
  y0: number;
  /** 压扁时四周鼓出来多少 */
  bulge: number;
  /** 撞上 / 压到底各响应过几次（每块只该各一次） */
  hits: number;
  done: number;
  /** 碎铁块数的倍数（每块碎铁一次绘制；泰坦的四条腿是细长的小块，只崩一两块） */
  chunks: number;
}

/** o 是不是 root 或它的子孙 */
function isUnder(o: THREE.Object3D, root: THREE.Object3D): boolean {
  for (let p: THREE.Object3D | null = o; p; p = p.parent) if (p === root) return true;
  return false;
}

