const toRoot = new THREE.Matrix4();
const toRootMesh = new THREE.Matrix4();

/** Boss：一组由控制器驱动的"部件"敌人 + 一整套大模型；核心部件被毁 = 击败 */
/**
 * 首领收走时（T245）：它自己 new 出来的几何体和实例矩阵放掉显存（不放的话一局打几个首领，显存只涨不落）；
 * 缓存里共享的（GeoCache）不动。材质不放：多是全局共用的，放了别处要重编着色器
 */
function releaseGeometry(root: THREE.Object3D, geo: GeoCache): void {
  const own = new Set<THREE.BufferGeometry>();
  root.traverse((o) => {
    const g = (o as THREE.Mesh).geometry as THREE.BufferGeometry | undefined;
    if (g && !geo.owns(g)) own.add(g);
    if ((o as THREE.InstancedMesh).isInstancedMesh) (o as THREE.InstancedMesh).dispose();
  });
  for (const g of own) g.dispose();
}

export abstract class Boss implements EnemyController {
  abstract readonly name: string;
  /** 战斗期间玩家可走的最左位置（列车占道时用） */
  readonly laneMin: number = -Infinity;
  /** 体型大，开到 30 米内才停车，免得被顶部界面挡住 */
  readonly engageDist: number = 30;
  /** 首领战自由走位（T107）：停车点往后最多多少米（按「不穿帮」实测，见 HOLD_MOVE）；往前按车身限位（front），没有车身挡着才按 holdFwd */
  readonly holdFwd: number = HOLD_MOVE.fwd;
  readonly holdBack: number = HOLD_MOVE.back;
  /** 停车攻坚的停车点（世界 z，Game.startHold / endHold 写；null = 没在停车攻坚）：会追着玩家走的首领按它收住，不把停车点占掉 */
  anchorZ: number | null = null;
  /** 首领战镜头横向偏移（列车在左边） */
  readonly cameraX: number = 0;
  /** 首领战镜头偏轴（弧度，+ = 朝左前方看、− = 朝右前方看；T104 空艇机库在路边） */
  readonly cameraYaw: number = 0;
  /** 首领战镜头再往上仰多少（弧度，T105 空艇横在头顶：整条艇压到界面下面） */
  readonly cameraLift: number = 0;
  /** 首领战镜头拉远多少（机位高度和后退距离 × (1 + 它)；和玩家的拉远档位取大的那个） */
  readonly cameraZoom: number = 0.38;
  /** 首领战镜头的俯仰（T019-b 巨炮：放平到 −0.8，整门炮和身边的红圈同时在画面里）；null = 用玩家自己的档位 */
  readonly cameraTilt: number | null = null;
  /** 离坦克多远以内算首领战（镜头拉远 / 放平；巨炮 280 米外就开打） */
  readonly cameraRange: number = 200;
  /** 登场定格（T022-a）：核心进到前方多少米亮相、特写推近比例（巨炮 300 米、0 = 不推机位只收窄视角的望远镜特写） */
  readonly showNear: number = 80;
  readonly showDolly: number | null = null;
  /** 首领特写（T017-6：亮相 / 击破时镜头推向它）要框住的半径和对准的离地高度（米） */
  protected readonly showR: number = 7;
  protected readonly showY: number = 3;
  /** 开进弹坑时整体跟着地面下沉（列车跑在自己的铁轨上，不跟） */
  protected readonly followGround: boolean = true;
  /** 击败后换的残骸材质（T048：都是不发光的烧黑钢，和车辆残骸同一套着色器；首领花纹放大到 3 米，巨炮 8 米 = MAT.steelWreck） */
  protected readonly wreckMat: THREE.Material = MAT.bossWreck;
  /** 击毁大爆炸在残骸底下炸出实体弹坑（T032 A10：巨炮的废墟是一座开得过去的小山，底下不挖坑——坑的地面一凹，履带的高度场就和小山的台面对不上） */
  protected readonly wreckCrater: boolean = true;
  /** 每掉两成血瘫痪 5 秒（D5：巨炮主炮全程不停，单独关掉；另外三个首领照旧） */
  protected readonly stunOnLoss: boolean = true;
  readonly root = new THREE.Group();
  dead = false;
  /** 击毁演出结束、可以回收 */
  finished = false;
  protected readonly parts: Part[] = [];
  protected t = 0;
  /** 0 / 1 / 2：血量降到 2/3、1/3 时进入下一阶段 */
  protected phase = 0;
  /** 瘫痪：每掉两成血瘫痪 5 秒，期间停火、受到的伤害 +40% */
  private stunT = 0;
  private nextStun = 0.8;
  private stunFxT = 0;
  private deathT = 0;
  private smokeT = 0;
  private readonly meshes: THREE.Mesh[] = [];
  private readonly glows: THREE.Mesh[] = [];
  /** 残骸上能碾压的几块（调试接口 wrecks() 也读它） */
  readonly pieces: WreckPiece[] = [];
  private crushFxT = 0;
  private readonly box = new THREE.Box3();
  private readonly pieceBox = new THREE.Box3();

  constructor(protected readonly ctx: BossContext, x: number, z: number) {
    this.root.position.set(x, 0, z);
    ctx.scene.add(this.root);
  }

  /** 打谁（T117）：离本体最近的玩家车位置（实时引用；现在只有一辆 = ctx.player） */
  protected get target(): THREE.Vector3 {
    return this.ctx.nearest(this.root.position.x, this.root.position.z);
  }

  // ---------------------------------------------------------- 建模辅助

  protected mesh(parent: THREE.Object3D, key: string, parts: () => PartSpec[], mat: THREE.Material = enemyPaint()): THREE.Mesh {
    const m = new THREE.Mesh(this.ctx.geo.merged(key, parts), mat);
    m.castShadow = true;
    m.receiveShadow = true;
    parent.add(m);
    if (mat === enemyPaint() || mat.userData.bossPaint) this.meshes.push(m);
    return m;
  }

  /** 实例化的同款小零件（液压杆等）：一类一次绘制，实例矩阵由子类每帧写；和整体模型一起换残骸材质、凹凸变形 */
  protected instanced(parent: THREE.Object3D, key: string, parts: () => PartSpec[], count: number): THREE.InstancedMesh {
    const m = new THREE.InstancedMesh(this.ctx.geo.merged(key, parts), enemyPaint(), count);
    m.castShadow = true;
    m.receiveShadow = true;
    // 实例跟着关节到处动，包围球不准，不做视锥剔除
    m.frustumCulled = false;
    parent.add(m);
    this.meshes.push(m);
    return m;
  }

  /** 登场定格（T022-a）：首领整个定住，只有发光件（炮口 / 射孔红灯、能量球）按真实时间呼吸；t < 0 = 收回原样 */
  breathe(t: number): void {
    const k = t < 0 ? 1 : 1 + 0.28 * Math.sin(t * 7);
    for (const g of this.glows) g.scale.setScalar(k);
  }

  protected glow(parent: THREE.Object3D, r: number, color: 'red' | 'blue', x: number, y: number, z: number): THREE.Mesh {
    const m = new THREE.Mesh(this.ctx.geo.sphere(r, 12), color === 'red' ? MAT.signalRed : MAT.energyBlue);
    m.position.set(x, y, z);
    parent.add(m);
    this.glows.push(m);
    return m;
  }

  protected group(parent: THREE.Object3D, x: number, y: number, z: number): THREE.Group {
    const g = new THREE.Group();
    g.position.set(x, y, z);
    parent.add(g);
    return g;
  }

  /** 注册一个可被攻击的部件 */
  protected addPart(anchor: THREE.Object3D, hp: number, radius: number, core: boolean, visual: THREE.Object3D | null, label: string): Part | null {
    this.root.updateMatrixWorld(true);
    anchor.getWorldPosition(tmp);
    const spec: EnemySpec = {
      hp, speed: 0, radius, contactDamage: 0, fireInterval: 0, shot: 'none', bulletDamage: 0, bulletSpeed: 0,
      scrap: core ? 40 : 10, standoff: 0, crushable: false, blocker: true, fixed: true, armor: 'heavy', threat: ENEMY_SPECS.part.threat,
    };
    const e = this.ctx.spawnPart(spec, tmp.x, tmp.z);
    if (!e) return null;
    e.controller = this;
    const p: Part = { e, anchor, core, visual, dead: false, label };
    this.parts.push(p);
    return p;
  }

  /** 核心部件（打掉 = 击败）；已击败为 null。终极「核弹」首领战对准它 */
  get coreEnemy(): Enemy | null {
    const p = this.parts.find((x) => x.core && !x.dead);
    return p && p.e.alive ? p.e : null;
  }

  hpRatio(): number {
    let hp = 0;
    let max = 0;
    for (const p of this.parts) {
      max += p.e.maxHp;
      if (!p.dead) hp += Math.max(0, p.e.hp);
    }
    return max > 0 ? hp / max : 0;
  }

  /** 部件存活（未被摧毁） */
  protected alive(label: string): Part | null {
    const p = this.parts.find((x) => x.label === label);
    return p && !p.dead ? p : null;
  }

  protected partPos(p: Part, out = new THREE.Vector3()): THREE.Vector3 {
    return p.anchor.getWorldPosition(out);
  }

  /** 首领特写（T017-6）：镜头对准的点（核心部件那里、离地 showY 米；击破后照样是核心原来的位置）写进 out，返回要框住的半径 */
  showcase(out: THREE.Vector3): number {
    const p = this.parts.find((x) => x.core);
    if (p) this.partPos(p, out);
    else this.root.getWorldPosition(out);
    out.y = this.root.position.y + this.showY;
    return this.showR;
  }

  onPartKilled(e: Enemy): void {
    const p = this.parts.find((x) => x.e === e);
    if (!p || p.dead) return;
    p.dead = true;
    const pos = this.partPos(p);
    this.ctx.fx.explosion(pos.x, pos.z, p.core ? 3 : 2, pos.y);
    this.ctx.audio.play('bigboom');
    this.ctx.shake(p.core ? 1.2 : 0.6);
    if (p.visual) {
      p.visual.visible = false;
      this.ctx.debris.launchPart(p.visual, 1.4);
    }
    if (p.core) this.defeat();
  }

  update(delta: number): void {
    this.t += delta;
    // 开进弹坑：整体跟着地面下沉（残骸登记凸起时按这时的高度算绝对高度）
    if (this.followGround && !this.finished && this.ctx.groundAt) {
      const r = this.root.position;
      r.y += (this.ctx.groundAt(r.x, r.z) - r.y) * Math.min(1, delta * 4);
    }
    if (this.dead) {
      this.stepDeath(delta);
      return;
    }
    // 阶段切换：换攻势 + 呼叫援军
    const ratio = this.hpRatio();
    const ph = ratio <= 1 / 3 ? 2 : ratio <= 2 / 3 ? 1 : 0;
    if (ph > this.phase) {
      this.phase = ph;
      this.ctx.announce(this.name, ph === 1 ? '第二阶段 · 援军到达' : '最终阶段：狂暴');
      this.ctx.shake(0.8);
      this.ctx.audio.play('alarm');
      this.onPhase(ph);
    }
    // 每掉两成血瘫痪一次：停火停车、冒烟冒火花，趁机输出
    if (this.stunOnLoss && ratio <= this.nextStun && this.nextStun > 0.05) {
      this.nextStun -= 0.2;
      this.stunT = 5;
      for (const p of this.parts) p.e.laser.visible = false;
      this.ctx.announce(`${this.name}瘫痪`, '5 秒内打它伤害 +40%');
      this.ctx.shake(0.6);
      this.ctx.audio.play('bigboom');
    }
    if (this.stunT > 0) {
      this.stunT -= delta;
      this.stunFxT -= delta;
      if (this.stunFxT <= 0) {
        this.stunFxT = 0.12;
        const alive = this.parts.filter((p) => !p.dead);
        const p = alive[Math.floor(Math.random() * alive.length)];
        if (p) {
          const pos = this.partPos(p);
          this.ctx.fx.sparks(pos.x, pos.y + 0.5, pos.z, 6, 0x9fd8ff, 8);
          this.ctx.fx.column(pos.x, pos.y + 1, pos.z, 1.2, 1);
        }
      }
    } else {
      this.step(delta);
    }
    // 部件跟着模型走
    this.root.updateMatrixWorld(true);
    for (const p of this.parts) {
      if (p.dead) continue;
      p.anchor.getWorldPosition(tmp);
      p.e.group.position.set(tmp.x, 0, tmp.z);
    }
    // 被毁部件的位置冒烟
    this.smokeT -= delta;
    if (this.smokeT <= 0) {
      this.smokeT = 0.2;
      for (const p of this.parts) {
        if (!p.dead) continue;
        const pos = this.partPos(p);
        this.ctx.fx.smoke(pos.x, pos.y, pos.z, 1.3);
        if (Math.random() < 0.5) this.ctx.fx.fire(pos.x, pos.y, pos.z, 1.2);
      }
    }
  }

  /** 子类：移动与攻击 */
  protected abstract step(delta: number): void;

  /**
   * 停车攻坚往前的车身限位（T109，按模型算）：车身在地上的投影朝玩家（+z）最远到哪（世界 z）；x / halfW = 坦克的横向位置、车体半宽（泰坦的脚掌按左右算）。
   * Game 加上坦克车头和 HOLD_MOVE.gap 就是往前最远开到哪，车身自己贴上来就把坦克顶回去；−Infinity = 没有车身挡着（列车在旁边轨道上跟着走），往前按 holdFwd
   */
  front(_x: number, _halfW: number): number {
    return -Infinity;
  }

  /** 部件受伤倍率（T019-b 巨炮：装填发光时打炮管 ×1.5）；Game.damageEnemy 每一下都问 */
  damageMul(_part: Enemy): number {
    return 1;
  }

  /** 额外的瘫痪（巨炮哑火 2.5 秒；规则同掉血瘫痪：停火、受伤 +40%） */
  protected stun(sec: number): void {
    this.stunT = Math.max(this.stunT, sec);
  }

  get stunned(): boolean {
    return this.stunT > 0;
  }

  /** 攻击频率倍率：每进一个阶段 +40% */
  protected get rage(): number {
    return 1 + this.phase * 0.4;
  }

  /** 子类：进入新阶段（呼叫援军等） */
  protected onPhase(_phase: number): void {}

  /**
   * 横跨道路的一排炮击，留一个缺口给玩家钻（四个首领共用）。D5：缺口两侧两发的真实伤害圈（半径 3.4 + 溅射 2.4 = 5.8 米）之间至少留 CARPET_GAP 米——
   * 原来按 3.4 米的圈排，加上溅射以后缺口基本合上了（D4 实测缺口中位 0.49 米、7% 没缺口）。
   * 默认：缺口中心在 −6～6 米随机（两边都至少有一发，原来缺口可以贴着路边），两边每 step 米一发铺到路边（−14～16 米）；o.gapX = 指定缺口中心、o.n = 最多几发（离 o.near 近的优先）、o.span = 往两边铺多远、o.band = 缺口处地上画一条白亮带
   */
  protected carpetLine(fromX: number, fromZ: number, z: number, damage: number, flight = 1.5, o: { gapX?: number; step?: number; n?: number; near?: number; span?: [number, number]; band?: boolean } = {}): void {
    const R = 3.4;
    const half = R + ENEMY_SPLASH + CARPET_GAP / 2;
    const gx = o.gapX ?? -6 + rng.boss() * 12;
    const step = o.step ?? 3.75;
    const [lo, hi] = o.span ?? [-14, 16];
    let xs: number[] = [];
    for (let x = gx - half; x >= lo; x -= step) xs.push(x);
    for (let x = gx + half; x <= hi; x += step) xs.push(x);
    if (o.n !== undefined) {
      const near = o.near ?? gx;
      xs = xs.sort((a, b) => Math.abs(a - near) - Math.abs(b - near)).slice(0, o.n);
    }
    xs.sort((a, b) => a - b).forEach((x, i) => this.ctx.artillery(fromX, fromZ, x, z + (rng.boss() - 0.5) * 2, damage, R, flight + i * 0.03));
    if (o.band) this.ctx.hazards.marker(gx, z, CARPET_GAP / 2 + 1, flight, 'gap', 9);
  }

  /** 子类：被毁姿态（坍塌等） */
  protected collapse(_k: number): void {}

  /** 残骸模型的根（击毁爆炸、弹坑、冒烟的范围；列车不算路基铁轨） */
  protected get wreckRoot(): THREE.Object3D {
    return this.root;
  }

  /** 子类：坍塌完以后，把残骸登记成能碾压的几块（crushable） */
  protected settleWreck(): void {}

  /** 残骸靠玩家这一侧的边（世界 z，越大越靠近玩家；T041 首领战利品箱落在它前面）：默认 = 包围盒的近边 */
  protected wreckEdge(box: THREE.Box3): number {
    return box.max.z;
  }

  /** 子类：残骸自己的动画（被顶下车体的炮塔等） */
  protected stepWreck(_delta: number): void {}

  /**
   * 残骸的一块登记成可碾压的凸起（复用 World 的凸起系统：坦克压上去抬起、倾斜，残骸被压扁，见 World.pressWreck）。
   * low：压完剩多高；sag：坦克撞上来那一下先塌到多高；len：塌完后再压着开多少米压到底；
   * size：[半宽, 半长] 只取 obj 原点周围这么大一块（不给 = 看得见部分的包围盒）；chunks：碎铁块数的倍数；
   * shape：root 坐标系里的包围盒（obj 底下是实例化画的、没有网格时由子类算好给进来）
   */
  protected crushable(obj: THREE.Object3D, low: number, sag: number, len: number, size?: [number, number], bulge = 0.1, chunks = 1, shape?: THREE.Box3): void {
    this.root.updateMatrixWorld(true);
    const box = shape ?? this.visibleBox(obj, this.pieceBox);
    if (box.isEmpty() || box.max.y < low + 0.3) return;
    const top = box.max.y;
    let x: number;
    let z: number;
    let halfW: number;
    let halfD: number;
    let rot: number;
    if (size) {
      obj.getWorldPosition(tmp);
      x = tmp.x;
      z = tmp.z;
      [halfW, halfD] = size;
      rot = tmpE.setFromQuaternion(obj.getWorldQuaternion(tmpQ), 'YXZ').y;
    } else {
      this.root.localToWorld(box.getCenter(tmp));
      x = tmp.x;
      z = tmp.z;
      // 包围盒四周往里收一点：细小的凸出物（炮管、护栏）不算
      halfW = (box.max.x - box.min.x) / 2 - 0.2;
      halfD = (box.max.z - box.min.z) / 2 - 0.2;
      rot = this.root.rotation.y;
    }
    const base = obj.parent ? obj.parent.getWorldPosition(tmp2).y : 0;
    const piece: WreckPiece = { obj, bump: null as unknown as Bump, top, low, base, y0: obj.position.y, bulge, hits: 0, done: 0, chunks };
    piece.bump = this.ctx.world.addBump({
      x, z, halfW, halfD, rot, h0: top, h1: low, debris: 'metal', base: this.root.position.y,
      wreck: { sag: THREE.MathUtils.clamp((top - sag) / (top - low), 0, 1), len, ridden: 0 },
      onPress: (f) => this.crush(piece, f),
    });
    this.pieces.push(piece);
  }

  /** obj 里看得见的网格在 root 坐标系下的包围盒（被炸飞、隐藏的部件不算） */
  private visibleBox(obj: THREE.Object3D, out: THREE.Box3): THREE.Box3 {
    out.makeEmpty();
    toRoot.copy(this.root.matrixWorld).invert();
    obj.traverseVisible((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh) return;
      // 凹凸变形版几何体是拷贝出来改过顶点的，包围盒要重算
      m.geometry.computeBoundingBox();
      out.union(tmpBox.copy(m.geometry.boundingBox!).applyMatrix4(toRootMesh.multiplyMatrices(toRoot, m.matrixWorld)));
    });
    return out;
  }

  /**
   * 被坦克压扁（0..1）：沿 y 压到顶面和凸起一样高、四周鼓出来；
   * 撞上那一下大块扬尘、碎铁、火花，压的过程中断续冒火花、掉碎铁、嘎吱响，压到底再扬起一圈尘土
   */
  protected crush(p: WreckPiece, f: number): void {
    const h = p.top + (p.low - p.top) * f;
    const s = Math.max(0.04, (h - p.base) / (p.top - p.base));
    p.obj.scale.set(1 + f * p.bulge, s, 1 + f * p.bulge * 0.6);
    p.obj.position.y = p.y0 * s;
    const b = p.bump;
    const fx = this.ctx.fx;
    const P = this.ctx.player;
    if (p.hits === 0) {
      p.hits = 1;
      // 压碎了，上面的信号灯 / 能量核心也灭了
      for (const g of this.glows) if (g.visible && isUnder(g, p.obj)) g.visible = false;
      const c = this.ctx.world.nearestOn(b, P.x, P.z);
      this.ctx.debris.chunks(c.x, Math.min(h, 3), c.z, Math.max(1, Math.round(4 * p.chunks)), 'metal', 1.3);
      for (let i = 0; i < 4; i++) fx.dust(c.x + (Math.random() - 0.5) * 4, c.z + (Math.random() - 0.5) * 4, 2.4, 0x9c8a68, 0.55);
      fx.sparks(c.x, 1.6, c.z, 14, 0xffd090, 10);
      fx.smoke(c.x, 2.4, c.z, 2.6, 2.4, 0x3a3532, 0.55);
      this.ctx.audio.play('hit');
      this.ctx.shake(0.45);
    }
    if (this.t >= this.crushFxT && f < 1) {
      // 压的过程：残骸边上断续崩火花、冒灰，偶尔掉几块碎铁，嘎吱作响
      this.crushFxT = this.t + 0.09;
      const c = Math.cos(b.rot);
      const sn = Math.sin(b.rot);
      const lx = (Math.random() * 2 - 1) * b.halfW;
      const lz = (Math.random() < 0.5 ? -1 : 1) * b.halfD * (0.6 + Math.random() * 0.4);
      const x = b.x + lx * c + lz * sn;
      const z = b.z - lx * sn + lz * c;
      fx.sparks(x, h, z, 4, 0xffc070, 7);
      fx.dust(x, z, 1.8, 0x8c7c62, 0.45);
      if (Math.random() < 0.15 * p.chunks) this.ctx.debris.chunks(x, h, z, 2, 'metal', 0.8);
      if (Math.random() < 0.3) this.ctx.audio.play('crunch', 0.5);
    }
    if (f >= 1 && p.done === 0) {
      // 压塌到底：残骸一下子瘫平，四周扑出一圈尘土
      p.done = 1;
      fx.shockwave(b.x, b.z, Math.max(b.halfW, b.halfD) + 3, 0xb8a888, 0.55);
      const c = Math.cos(b.rot);
      const sn = Math.sin(b.rot);
      for (let i = 0; i < 10; i++) {
        const a = (i / 10) * Math.PI * 2;
        const lx = Math.cos(a) * b.halfW;
        const lz = Math.sin(a) * b.halfD;
        fx.dust(b.x + lx * c + lz * sn, b.z - lx * sn + lz * c, 2.6, 0x9c8a68, 0.5);
      }
      this.ctx.debris.chunks(b.x, p.low + 0.5, b.z, Math.max(1, Math.round(5 * p.chunks)), 'metal', 1.2);
      fx.smoke(b.x, 2, b.z, 3.2, 3, 0x3a3532, 0.6);
      this.ctx.audio.play('explode', 0.5);
      this.ctx.shake(0.6);
    }
  }

  private defeat(): void {
    this.dead = true;
    for (const p of this.parts) {
      if (!p.dead) {
        p.dead = true;
        p.e.kill();
      }
    }
    // 和普通车辆残骸一样：烧黑 + 凹凸变形（压扁时一起压下去）
    for (const m of this.meshes) {
      m.material = this.wreckMat;
      if (isUnder(m, this.wreckRoot)) m.geometry = dented(m.geometry);
    }
    this.ctx.onDefeated(this);
  }

  private stepDeath(delta: number): void {
    this.deathT += delta;
    // 坍塌姿态只在前 1.6 秒播（之后交给碾压，不再每帧覆盖）
    if (this.deathT - delta < 1.6) this.collapse(Math.min(1, this.deathT / 1.6));
    const box = this.box.setFromObject(this.wreckRoot);
    if (this.deathT < 1.8 && Math.random() < delta * 9) {
      const x = THREE.MathUtils.lerp(box.min.x, box.max.x, Math.random());
      const z = THREE.MathUtils.lerp(box.min.z, box.max.z, Math.random());
      this.ctx.fx.explosion(x, z, 2 + Math.random() * 1.5, 1 + Math.random() * 3);
      this.ctx.debris.chunks(x, 2, z, 4, 'metal', 1.3);
      this.ctx.audio.play('explode');
      this.ctx.shake(0.4);
    }
    if (this.deathT > 1.8 && !this.finished) {
      this.finished = true;
      const c = box.getCenter(new THREE.Vector3());
      this.ctx.fx.explosion(c.x, c.z, 6, 3);
      this.ctx.fx.crater(c.x, c.z, 14);
      if (this.wreckCrater) this.ctx.crater?.(c.x, c.z);
      this.ctx.audio.play('bigboom');
      this.ctx.shake(1.6);
      // 坍塌完：残骸登记成可碾压的凸起（开上去抬起、倾斜，把它压扁，不会穿模也不会挡路）
      this.settleWreck();
      this.ctx.wrecked?.(box, this.wreckEdge(box));
    }
    if (!this.finished) return;
    if (Math.random() < delta * 4) {
      const c = box.getCenter(tmp);
      this.ctx.fx.smoke(c.x + (Math.random() - 0.5) * 6, 3, c.z + (Math.random() - 0.5) * 6, 2.2);
    }
    this.stepWreck(delta);
  }

  /** 坦克（z、车速）该不该刹车：首领 5 撤离完以前停在机库旁的停车线（T100B / T104）；别的首领靠部件拦路，不用它 */
  holds(_z: number, _speed: number): boolean {
    return false;
  }

  /** 玩家已把残骸甩在身后很远 */
  isBehind(pz: number): boolean {
    return this.finished && this.root.position.z > pz + 60;
  }

  dispose(): void {
    for (const p of this.parts) if (!p.dead) p.e.kill();
    for (const p of this.pieces) p.bump.alive = false;
    this.root.removeFromParent();
    releaseGeometry(this.root, this.ctx.geo);
  }
}

