import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import type { GeoCache, PartSpec } from '../GeoCache';
import type { V2 } from '../ModelKit';

/**
 * 主角车加细的零件库（T171）：实体履带链板、双联负重轮、主动轮 / 诱导轮、高段数炮管、并网工具。
 * 规则：只做 0.1 米以上看得出轮廓的几何；加出来的面一律合进已有网格（augment / geo.merged 同一个键），不新建对象、不加材质。
 */

/** 一圈轴沿 x 的车床体：profile = [半径, x]（按顺序连成剖面），seg 段 */
export function latheX(profile: V2[], seg: number): THREE.BufferGeometry {
  const g = new THREE.LatheGeometry(profile.map(([r, x]) => new THREE.Vector2(r, x)), seg);
  g.rotateZ(-Math.PI / 2);
  return g;
}

/** 一圈轴沿 z 的车床体（炮管）：profile = [半径, z] */
export function latheZ(profile: V2[], seg: number): THREE.BufferGeometry {
  const g = new THREE.LatheGeometry(profile.map(([r, z]) => new THREE.Vector2(r, z)), seg);
  g.rotateX(Math.PI / 2);
  return g;
}

/** 侧面轮廓（z-y 平面，[z, y] 点）沿 x 拉成棱柱，x 从 x0 到 x1，不倒角 */
export function prismX(profile: V2[], x0: number, x1: number): THREE.BufferGeometry {
  const shape = new THREE.Shape(profile.map(([z, y]) => new THREE.Vector2(z, y)));
  const g = new THREE.ExtrudeGeometry(shape, { depth: x1 - x0, bevelEnabled: false });
  g.rotateY(-Math.PI / 2);
  g.translate(x1, 0, 0);
  return g;
}

/** 两点之间的圆管（栏杆 / 支架） */
export function tube(a: [number, number, number], b: [number, number, number], r: number, seg = 6): THREE.BufferGeometry {
  const A = new THREE.Vector3(...a), B = new THREE.Vector3(...b);
  const len = A.distanceTo(B);
  const g = new THREE.CylinderGeometry(r, r, len, seg, 1);
  g.applyQuaternion(new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), B.clone().sub(A).normalize()));
  g.translate((A.x + B.x) / 2, (A.y + B.y) / 2, (A.z + B.z) / 2);
  return g;
}

/** 倒角方块：八边形截面（z-y）沿 x 拉伸，c = 倒角 */
export function bevelBox(w: number, h: number, d: number, c = 0.03): THREE.BufferGeometry {
  const z = d / 2, y = h / 2;
  return prismX([[-z + c, -y], [z - c, -y], [z, -y + c], [z, y - c], [z - c, y], [-z + c, y], [-z, y - c], [-z, -y + c]], -w / 2, w / 2);
}

/**
 * 把额外零件并进一个已有网格（同一个材质、同一次绘制）：零件按炮塔组坐标给，自动换算到网格自己的坐标里。
 * 结果按 key 缓存在 GeoCache 里，同一个炮塔再建一次直接复用
 */
export function augment(geo: GeoCache, mesh: THREE.Mesh, key: string, parts: PartSpec[] | (() => PartSpec[])): void {
  if (!mesh.parent) return;
  const base = mesh.geometry;
  mesh.updateMatrix();
  const inv = mesh.matrix.clone().invert();
  mesh.geometry = geo.get(`aug:${key}`, () => {
    const extra = geo.merged(`aug-parts:${key}`, () => (typeof parts === 'function' ? parts() : parts)).clone();
    extra.applyMatrix4(inv);
    const keep = Object.keys(base.attributes);
    for (const k of Object.keys(extra.attributes)) if (!keep.includes(k)) extra.deleteAttribute(k);
    const out = mergeGeometries([base.index ? base.toNonIndexed() : base, extra], false);
    if (!out) throw new Error(`并网失败: ${key}`);
    return out;
  });
}

// ------------------------------------------------------------------ 履带

/** 链板销轴到链板内面的距离：销轴线绕轮子走的半径 = 轮子半径 + PIN_OFF */
const PIN_OFF = 0.05;
/**
 * 行走机构布局（T175，侧视 z-y，车头朝 -z）：主动轮在车头、诱导轮在车尾，都比负重轮高，履带两头斜着往上收；
 * 6 个负重轮落在底边，前后两个和主动轮 / 诱导轮之间留出空隙（T171 版主动轮 / 诱导轮和两头负重轮同高、圆心只差 0.43 米，叠在一起只露半个）。
 * 顶边压到 1.15（外缘 1.24），从车体侧伸出的下沿底下走
 */
export const GEAR = {
  /** 负重轮：半径、圆心高、6 个的 z */
  road: { r: 0.42, y: 0.09 + PIN_OFF + 0.42, z: [-2.2, -1.32, -0.44, 0.44, 1.32, 2.2] },
  /** 主动轮（车头）/ 诱导轮（车尾）：z、圆心高、销轴线半径 */
  sprocket: { z: -3.08, y: 0.75, rp: 0.4 },
  idler: { z: 3.08, y: 0.75, rp: 0.4 },
};
export const TRACK = { width: 0.9 };

type Seg = { k: 'line'; s0: number; len: number; p: V2; t: V2; n: V2 } | { k: 'arc'; s0: number; len: number; c: V2; r: number; a0: number };
/**
 * 走行线（销轴线）：前负重轮 → 后负重轮（底边）→ 诱导轮 → 主动轮（顶边）→ 前负重轮，侧视 (z, y) 逆时针，几个圆的外公切线 + 圆弧。
 * 中间四个负重轮和前后两个同高同径，正好切在底边上
 */
function buildRun(): { segs: Seg[]; P: number } {
  const { road, sprocket, idler } = GEAR;
  const rr = road.r + PIN_OFF;
  const circles: [V2, number][] = [
    [[road.z[0], road.y], rr],
    [[road.z[road.z.length - 1], road.y], rr],
    [[idler.z, idler.y], idler.rp],
    [[sprocket.z, sprocket.y], sprocket.rp],
  ];
  // 相邻两圆的外公切线：外法线 n 满足 d·n = ra - rb，取在前进方向右手边（逆时针走，右手边朝外）
  const tangents = circles.map(([ca, ra], i) => {
    const [cb, rb] = circles[(i + 1) % circles.length];
    const dz = cb[0] - ca[0], dy = cb[1] - ca[1], L = Math.hypot(dz, dy);
    const ez = dz / L, ey = dy / L, sin = (ra - rb) / L, cos = Math.sqrt(1 - sin * sin);
    const n: V2 = [cos * ey + sin * ez, cos * -ez + sin * ey];
    const p0: V2 = [ca[0] + ra * n[0], ca[1] + ra * n[1]], p1: V2 = [cb[0] + rb * n[0], cb[1] + rb * n[1]];
    const len = Math.hypot(p1[0] - p0[0], p1[1] - p0[1]);
    return { p0, n, len, t: [(p1[0] - p0[0]) / len, (p1[1] - p0[1]) / len] as V2 };
  });
  const segs: Seg[] = [];
  let s = 0;
  tangents.forEach((tg, i) => {
    segs.push({ k: 'line', s0: s, len: tg.len, p: tg.p0, t: tg.t, n: tg.n });
    s += tg.len;
    const [c, r] = circles[(i + 1) % circles.length];
    const nx = tangents[(i + 1) % tangents.length].n;
    const a0 = Math.atan2(tg.n[1], tg.n[0]);
    let da = Math.atan2(nx[1], nx[0]) - a0;
    while (da < 0) da += Math.PI * 2;
    segs.push({ k: 'arc', s0: s, len: da * r, c, r, a0 });
    s += da * r;
  });
  return { segs, P: s };
}
const RUN = buildRun();
const TRACK_P = RUN.P;
/** 链板数：节距尽量接近原来贴图的每米三节，贴图偏移每走 1 正好走 3 节，无缝 */
export const LINKS = Math.round(TRACK_P * 3);
const PITCH = TRACK_P / LINKS;

/** 走行线上 s 米处的中心、切线（往 s 增大的方向）、外法线；s 从前负重轮底下开始，底下往后、绕诱导轮往上、顶上往前、绕主动轮往下 */
function trackFrame(s: number, C: THREE.Vector3, T: THREE.Vector3, N: THREE.Vector3): void {
  s = ((s % TRACK_P) + TRACK_P) % TRACK_P;
  const g = RUN.segs.find((q) => s < q.s0 + q.len) ?? RUN.segs[RUN.segs.length - 1];
  const u = s - g.s0;
  if (g.k === 'line') {
    C.set(0, g.p[1] + g.t[1] * u, g.p[0] + g.t[0] * u); T.set(0, g.t[1], g.t[0]); N.set(0, g.n[1], g.n[0]);
  } else {
    const a = g.a0 + u / g.r;
    C.set(0, g.c[1] + g.r * Math.sin(a), g.c[0] + g.r * Math.cos(a)); N.set(0, Math.sin(a), Math.cos(a)); T.set(0, Math.cos(a), -Math.sin(a));
  }
}

/** 同一张分段表生成着色器里的 trackFrame（一串 if，常量直接写进去） */
function runGLSL(): string {
  const f = (v: number) => v.toFixed(5);
  const body = RUN.segs.map((g, i) => {
    const head = i === RUN.segs.length - 1 ? 'else' : `${i ? 'else ' : ''}if (s < ${f(g.s0 + g.len)})`;
    if (g.k === 'line') return `${head} { float u = s - ${f(g.s0)}; C = vec3(0.0, ${f(g.p[1])} + ${f(g.t[1])} * u, ${f(g.p[0])} + ${f(g.t[0])} * u); T = vec3(0.0, ${f(g.t[1])}, ${f(g.t[0])}); N = vec3(0.0, ${f(g.n[1])}, ${f(g.n[0])}); }`;
    return `${head} { float a = ${f(g.a0)} + (s - ${f(g.s0)}) / ${f(g.r)}; C = vec3(0.0, ${f(g.c[1])} + ${f(g.r)} * sin(a), ${f(g.c[0])} + ${f(g.r)} * cos(a)); N = vec3(0.0, sin(a), cos(a)); T = vec3(0.0, cos(a), -sin(a)); }`;
  });
  return `void trackFrame(float s, out vec3 C, out vec3 T, out vec3 N) {\n  s = mod(s, ${f(TRACK_P)});\n  ${body.join('\n  ')}\n}`;
}

/**
 * 一节链板（局部坐标：x 横向、y = 离销轴线往外、z = 沿履带）：
 * 履带板（八边形截面）+ 外侧抓地齿 + 内侧导向齿（卡在双联负重轮中间）+ 两端连接器
 */
export function linkParts(withPins = true): PartSpec[] {
  const W = 0.43;
  const p: PartSpec[] = [
    { geo: prismX([[-0.15, -0.05], [0.15, -0.05], [0.166, -0.02], [0.166, 0.035], [0.15, 0.055], [-0.15, 0.055], [-0.166, 0.035], [-0.166, -0.02]], -W, W), color: 0xffffff },
    { geo: prismX([[-0.075, 0.05], [0.015, 0.05], [0.0, 0.092], [-0.06, 0.092]], -W + 0.02, W - 0.02), color: 0xe0e0e0 },
    { geo: prismX([[-0.07, -0.045], [0.07, -0.045], [0.035, -0.15], [-0.035, -0.15]], -0.045, 0.045), color: 0xd0d0d0 },
  ];
  if (withPins) for (const s of [-1, 1]) p.push({ geo: new THREE.CylinderGeometry(0.048, 0.048, 0.07, 10), color: 0x9a9a9a, pos: [s * 0.47, 0, PITCH / 2], rot: [0, 0, Math.PI / 2] });
  return p;
}

/**
 * 实体链板履带（T171，代替原来的空心履带环）：LINKS 节链板合成一个网格，仍是原来那次绘制、原来那份材质。
 * 每个顶点记着自己那节的走行位置 linkS 和节内局部坐标；顶点着色器按 uTrackShift 把整节沿走行线搬过去（刚体，绕轮时链板一节节折过去）。
 * position 存的是静止时的姿态（视锥裁剪 / 包围盒用）
 */
export function trackLinks(): THREE.BufferGeometry {
  const parts = linkParts().map(({ geo, pos = [0, 0, 0], rot = [0, 0, 0] }) => {
    const g = (geo.index ? geo.toNonIndexed() : geo).applyMatrix4(new THREE.Matrix4().compose(new THREE.Vector3(...pos), new THREE.Quaternion().setFromEuler(new THREE.Euler(...rot)), new THREE.Vector3(1, 1, 1)));
    for (const k of Object.keys(g.attributes)) if (!['position', 'normal'].includes(k)) g.deleteAttribute(k);
    return g;
  });
  const one = mergeGeometries(parts, false)!;
  const lp = one.getAttribute('position'), ln = one.getAttribute('normal');
  const n = lp.count;
  const pos = new Float32Array(n * LINKS * 3), nor = new Float32Array(n * LINKS * 3), uv = new Float32Array(n * LINKS * 2);
  const loc = new Float32Array(n * LINKS * 3), lnor = new Float32Array(n * LINKS * 3), ls = new Float32Array(n * LINKS);
  const C = new THREE.Vector3(), T = new THREE.Vector3(), N = new THREE.Vector3();
  for (let k = 0; k < LINKS; k++) {
    const s0 = k * PITCH;
    trackFrame(s0, C, T, N);
    for (let i = 0; i < n; i++) {
      const j = k * n + i;
      const x = lp.getX(i), y = lp.getY(i), z = lp.getZ(i);
      const nx = ln.getX(i), ny = ln.getY(i), nz = ln.getZ(i);
      loc.set([x, y, z], j * 3);
      lnor.set([nx, ny, nz], j * 3);
      ls[j] = s0;
      // 局部 x 取反：(-x, 外法线, 切线) 才是右手系，不然整条履带是镜像、三角形背面朝外
      pos.set([-x, C.y + T.y * z + N.y * y, C.z + T.z * z + N.z * y], j * 3);
      nor.set([-nx, T.y * nz + N.y * ny, T.z * nz + N.z * ny], j * 3);
      // 贴图：一节链板对应贴图里的一节（u 每 1/3 一节）；侧面用图集上半，踏面 / 内面用下半
      const u = (z / PITCH + 0.5) / 3;
      const side = Math.abs(nx) > 0.7;
      const v = side ? 0.53 + THREE.MathUtils.clamp((y + 0.05) / 0.14, 0, 1) * 0.44 : 0.025 + THREE.MathUtils.clamp((x + 0.45) / 0.9, 0, 1) * 0.45;
      uv.set([u, v], j * 2);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  g.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
  g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
  g.setAttribute('linkLocal', new THREE.BufferAttribute(loc, 3));
  g.setAttribute('linkNormal', new THREE.BufferAttribute(lnor, 3));
  g.setAttribute('linkS', new THREE.BufferAttribute(ls, 1));
  g.computeBoundingBox();
  g.boundingBox!.expandByScalar(0.08);
  g.computeBoundingSphere();
  g.boundingSphere!.radius += 0.08;
  return g;
}

const TRACK_GLSL = /* glsl */ `
attribute vec3 linkLocal;
attribute vec3 linkNormal;
attribute float linkS;
uniform float uTrackShift;
${runGLSL()}
`;

/**
 * 链板跟着履带贴图的偏移走（Tank.update 照旧只改 trackMap.offset.x，一点没动）：
 * 贴图本身不再滚（matrixAutoUpdate 关掉，贴图钉在链板上），偏移换算成沿走行线的米数交给着色器。
 * 主画面材质改着色器；投影那一遍用同样改过的深度材质（只在阴影里用，不是新的绘制）
 */
export function rigTrack(mesh: THREE.Mesh, mat: THREE.MeshStandardMaterial, map: THREE.Texture): void {
  map.matrixAutoUpdate = false;
  map.updateMatrix();
  const shift = { get value() { return -map.offset.x * 3 * PITCH; } };
  const patch = (shader: THREE.WebGLProgramParametersWithUniforms, normal: boolean) => {
    shader.uniforms.uTrackShift = shift;
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', `#include <common>\n${TRACK_GLSL}`)
      .replace('#include <begin_vertex>', 'vec3 transformed;\n{ vec3 tC, tT, tN; trackFrame(linkS + uTrackShift, tC, tT, tN); transformed = tC + tT * linkLocal.z + tN * linkLocal.y - vec3(linkLocal.x, 0.0, 0.0); }');
    if (normal) shader.vertexShader = shader.vertexShader.replace('#include <beginnormal_vertex>', 'vec3 objectNormal;\n{ vec3 tC, tT, tN; trackFrame(linkS + uTrackShift, tC, tT, tN); objectNormal = tT * linkNormal.z + tN * linkNormal.y - vec3(linkNormal.x, 0.0, 0.0); }');
  };
  mat.onBeforeCompile = (s) => patch(s, true);
  mat.customProgramCacheKey = () => 'player-track-links';
  const depth = new THREE.MeshDepthMaterial();
  depth.onBeforeCompile = (s) => patch(s, false);
  depth.customProgramCacheKey = () => 'player-track-links-depth';
  mat.addEventListener('dispose', () => depth.dispose());
  mesh.customDepthMaterial = depth;
}

// ------------------------------------------------------------------ 轮子

const RUBBER = 0x262626;

/** 轮子车漆（T175）：负重轮 / 主动轮 / 诱导轮的轮辐改刷车身漆（原来是钢件材质的浅钢色，镜头里发白），轮毂、齿圈压暗一档 */
const WHEEL_PAINT = 0xbabea2;
const WHEEL_DARK = 0x6e715c;

/** 双联负重轮（半径 r，T175 起 0.42）：两片轮，每片橡胶胎 + 碟形轮辐 + 轮毂盖，中间留缝给导向齿；径向尺寸按 r / 0.48 缩放，宽度不变；轮子小了一圈，一圈 20 段减到 19 段（车体本体 ≥ 4 万、满配 ≤ 5 万两头卡着） */
export function roadWheelParts(r = GEAR.road.r): PartSpec[] {
  const k = r / 0.48;
  const one = (s: number): PartSpec[] => {
    const lathe = (pts: V2[], color: number): PartSpec => {
      const q = pts.map(([rad, x]): V2 => [rad * k, s * x]);
      return { geo: latheX(s > 0 ? q : q.reverse(), 19), color };
    };
    return [
      lathe([[0.4, 0.075], [0.465, 0.075], [0.48, 0.095], [0.48, 0.255], [0.465, 0.275], [0.4, 0.275]], RUBBER),
      lathe([[0.4, 0.275], [0.37, 0.285], [0.3, 0.255], [0.17, 0.25], [0.13, 0.29], [0.075, 0.31], [0.0, 0.31]], WHEEL_PAINT),
      lathe([[0.09, 0.0], [0.09, 0.07], [0.4, 0.075]], WHEEL_DARK),
    ];
  };
  return [...one(1), ...one(-1)];
}

/** 齿圈：n 个齿，齿顶 ro、齿根 ri，厚 w，中心 x */
function sprocketRing(n: number, ro: number, ri: number, w: number, x: number): PartSpec {
  const shape = new THREE.Shape();
  for (let i = 0; i < n; i++) {
    const a0 = (i / n) * Math.PI * 2, step = (Math.PI * 2) / n;
    const pts: [number, number][] = [[ri, a0], [ri, a0 + step * 0.22], [ro, a0 + step * 0.36], [ro, a0 + step * 0.64], [ri, a0 + step * 0.78]];
    pts.forEach(([r, a], k) => (i === 0 && k === 0 ? shape.moveTo(Math.cos(a) * r, Math.sin(a) * r) : shape.lineTo(Math.cos(a) * r, Math.sin(a) * r)));
  }
  const g = new THREE.ExtrudeGeometry(shape, { depth: w, bevelEnabled: false, curveSegments: 1 });
  g.translate(0, 0, -w / 2);
  g.rotateY(Math.PI / 2);
  return { geo: g, color: WHEEL_DARK, pos: [x, 0, 0] };
}

/**
 * 主动轮（车头）：两片 11 齿齿圈（齿顶比销轴线高 3 厘米，咬进链板）+ 两片轮盘 + 减速器外壳 / 轮毂盖。
 * T175：跟着销轴线半径从 0.58 缩到 0.40；两片轮盘中间收成细轴（半径 0.15），链板导向齿从中间过（T171 版中间是实心轮毂，导向齿插在里面）
 */
export function sprocketParts(): PartSpec[] {
  const rp = GEAR.sprocket.rp, ri = rp - 0.07, mid = rp - PIN_OFF - 0.15;
  return [
    sprocketRing(11, rp + 0.03, ri, 0.07, 0.11),
    sprocketRing(11, rp + 0.03, ri, 0.07, -0.11),
    { geo: latheX([[0.0, -0.34], [0.18, -0.34], [0.24, -0.3], [0.24, -0.17], [ri + 0.005, -0.16], [ri + 0.005, -0.07], [mid - 0.05, -0.065], [mid - 0.05, 0.065], [ri + 0.005, 0.07], [ri + 0.005, 0.16], [0.2, 0.2], [0.18, 0.27], [0.12, 0.31], [0.0, 0.31]], 22), color: WHEEL_PAINT },
  ];
}

/** 诱导轮（车尾）：双片碟形轮 + 张紧曲臂座；T175 起外缘贴着链板内面（销轴线半径 - 5 厘米） */
export function idlerParts(): PartSpec[] {
  const k = (GEAR.idler.rp - PIN_OFF) / 0.45;
  return [
    { geo: latheX(([[0.0, 0.3], [0.1, 0.3], [0.16, 0.25], [0.36, 0.25], [0.42, 0.27], [0.45, 0.25], [0.45, 0.08], [0.4, 0.07], [0.12, 0.06], [0.12, -0.06], [0.4, -0.07], [0.45, -0.08], [0.45, -0.25], [0.42, -0.27], [0.36, -0.25], [0.16, -0.25], [0.1, -0.3], [0.0, -0.3]] as V2[]).map(([r, x]): V2 => [r * k, x]).reverse(), 22), color: WHEEL_PAINT },
  ];
}

// ------------------------------------------------------------------ 炮管

/**
 * 高段数炮管（沿 +z）：炮尾套筒 + 三道炮管箍 + 抽气装置 + 多孔制退器（上下板 + 两道挡板框，侧面开窗看得见）+ 炮口内膛
 */
export function barrelHi(len: number, r: number, opts: { evacuator?: boolean } = {}): PartSpec[] {
  const p: [number, number][] = [[0, 0], [r * 1.3, 0], [r * 1.3, len * 0.07], [r * 1.18, len * 0.09], [r * 1.12, len * 0.16], [r, len * 0.2]];
  const band = (z: number) => p.push([r, z - 0.05], [r * 1.16, z - 0.04], [r * 1.16, z + 0.04], [r, z + 0.05]);
  band(len * 0.3);
  if (opts.evacuator) p.push([r, len * 0.47], [r * 1.5, len * 0.51], [r * 1.5, len * 0.63], [r, len * 0.67]);
  else band(len * 0.52);
  band(len * 0.76);
  const b0 = len * 0.88;
  p.push([r * 0.94, b0], [r * 0.94, len], [r * 0.62, len], [r * 0.62, len - 0.5], [0.001, len - 0.52]);
  const out: PartSpec[] = [{ geo: latheZ(p, 28), color: 0xffffff }];
  // 制退器：上下两块板 + 前后两道挡板框（中间留膛口），侧面是两扇窗
  const w = r * 3.1, h = r * 2.2, bl = len - b0;
  out.push(
    { geo: bevelBox(w, r * 0.38, bl, 0.02), color: 0xe8e8e8, pos: [0, (h - r * 0.38) / 2, b0 + bl / 2] },
    { geo: bevelBox(w, r * 0.38, bl, 0.02), color: 0xe8e8e8, pos: [0, -(h - r * 0.38) / 2, b0 + bl / 2] },
  );
  for (const z of [b0 + 0.03, b0 + bl * 0.55, len - 0.03]) for (const s of [-1, 1]) out.push({ geo: new THREE.BoxGeometry((w - r * 1.3) / 2, h * 0.64, 0.06), color: 0xe8e8e8, pos: [s * (r * 0.65 + (w - r * 1.3) / 4), 0, z] });
  return out;
}
