import * as THREE from 'three';
import type { GeoCache, PartSpec } from '../GeoCache';
import { rockify } from '../ModelKit';
import { styledHouseParts, type HouseLook } from './houseStyles';
import { richLookTree, richStyledHouse } from './sceneryRich';
import { SCN_DETAIL, SCN_RICH } from '../../world/sceneryDetail';

export type TreeLook = 'spruce' | 'oak' | 'birch';
export type SceneryLook = TreeLook | HouseLook;
const TREE_LOOKS = new Set<string>(['spruce', 'oak', 'birch']);
export const isTreeLook = (look: string): look is TreeLook => TREE_LOOKS.has(look);

/** 树冠和断树共用一套部件；倒伏、切断和拔根后仍保留树种轮廓。 */
function treeParts(look: TreeLook, state: string): PartSpec[] {
  const birch = look === 'birch', spruce = look === 'spruce';
  const bark = birch ? 0xb9b6a4 : spruce ? 0x514432 : 0x63513b;
  const stump = state === 'pineStump', top = state === 'pineTop', bare = state === 'pineBald';
  const parts: PartSpec[] = [
    { geo: new THREE.CylinderGeometry(stump ? .27 : .14, .32, stump ? 1 : 5.9, 7), color: bark, pos: [0, stump ? .5 : 2.95, 0] },
  ];
  if (stump) parts.push({ geo: new THREE.CylinderGeometry(.27, .27, .035, 7), color: 0xa18a63, pos: [0, 1, 0] });
  else {
    for (let i = 0; i < (spruce ? 4 : 5); i++) {
      const a = i * 2.4 + .4, y = 2.2 + i * .6;
      parts.push({ geo: new THREE.CylinderGeometry(.045, .12, 1.6, 5), color: bark,
        pos: [Math.cos(a) * .52, y + .45, Math.sin(a) * .52], rot: [Math.sin(a) * .9, 0, -Math.cos(a) * .9] });
    }
    if (birch) for (let i = top ? 1 : 0; i < 6; i++) parts.push({
      geo: new THREE.BoxGeometry(.3, .07, .34), color: 0x655e4d, pos: [i % 2 ? .03 : -.03, .7 + i * .72, .02],
    });
    if (!bare) {
      if (spruce) for (let i = 0; i < 4; i++) parts.push({
        geo: rockify(new THREE.ConeGeometry(1.9 - i * .36, 2.8 - i * .26, 7), .1, 53 + i),
        color: [0x354b36, 0x3b533b, 0x425940, 0x496246][i], pos: [i % 2 * .12, 2.9 + i * 1.12, 0],
      });
      else for (let i = 0; i < 5; i++) {
        const a = i * 2.4, radius = birch ? .58 : .88;
        parts.push({
          geo: rockify(new THREE.IcosahedronGeometry(1, 1), .25, 71 + i * 7),
          color: (birch ? [0x677348, 0x72804d, 0x5e7147] : [0x485b35, 0x596b3b, 0x53663c])[i % 3],
          pos: [Math.cos(a) * radius, 3.7 + i * .57, Math.sin(a) * radius],
          scale: birch ? [1.04, 1.45, .92] : [1.47, 1.25, 1.27],
        });
      }
    }
  }
  if (state === 'pineRoot') {
    parts.push({ geo: rockify(new THREE.IcosahedronGeometry(.85, 0), .25, 81), color: 0x64573b, pos: [0, .05, 0], scale: [1.4, .45, 1.1] });
  }
  if (top) {
    // 截面在一米高处；树干重建上段，树冠和枝条只平移，不换回松树。
    parts[0].geo.dispose();
    parts[0] = { geo: new THREE.CylinderGeometry(.14, .27, 4.9, 7), color: bark, pos: [0, 3.45, 0] };
    for (const p of parts) if (p.pos) p.pos[1] -= 1;
  }
  return parts;
}

export function sceneryLookGeo(geo: GeoCache, look: SceneryLook, state: string): THREE.BufferGeometry {
  if (SCN_RICH) return geo.merged(`scenery-look-${look}-${state}-x${SCN_DETAIL}`, () =>
    isTreeLook(look) ? richLookTree(look, state) : richStyledHouse(look));
  return geo.merged(`scenery-look-${look}-${state}`, () =>
    isTreeLook(look) ? treeParts(look, state) : styledHouseParts(look));
}
