import type { Overlay, Panel } from './canvas/Overlay';
import { armorPanel, backdrop, button, type ButtonStyle } from './canvas/widgets';
import { ellipsize, font, text } from './canvas/paint';
import { CORES, type CoreId } from '../weapons/defs';
import { OnlineRoom, onlineWx, clipFail, inviteText, parseInvite } from '../game/onlineRoom';
import { WebOnlineLobby, roomDialog } from './webOnlineLobby';

type Tone = 'empty' | 'joined' | 'ready' | 'left' | 'away';
/** 状态色：字、框、底；字和形状标记一起表达，不只靠颜色。 */
const TONES: Record<Tone, { label: string; ink: string; edge: string; face: string }> = {
  empty: { label: '待加入', ink: '#97a293', edge: '#4b574b', face: '#121a16' },
  joined: { label: '已加入·未准备', ink: '#ecc56a', edge: '#a98a45', face: '#2a2414' },
  ready: { label: '已准备', ink: '#a6e07e', edge: '#73a955', face: '#17291a' },
  left: { label: '已离开', ink: '#f2a066', edge: '#b8703f', face: '#2c1b12' },
  away: { label: '暂时离开', ink: '#f2a066', edge: '#b8703f', face: '#2c1b12' },
};
const PICKS: CoreId[] = ['cannon', 'rocket', 'laser', 'vulcan'];
const NAMES = ['一号', '二号'] as const;
/** 提示条停留秒数。 */
const TOAST_S = 3;

interface Box { x: number; y: number; w: number; h: number }
interface Layout {
  w: number; h: number;
  title: Box; hint: Box; seats: [Box, Box]; picks: Box; room: Box; ready: Box; back: Box;
  /** 未建房时房间区占掉流派和准备的位置。 */
  roomBare: Box;
}
/** 竖屏一列；横屏左边席位、右边操作。设计尺寸，整页按屏幕等比缩小。 */
const PORTRAIT: Layout = {
  w: 340, h: 616,
  title: { x: 0, y: 0, w: 340, h: 30 },
  hint: { x: 0, y: 40, w: 340, h: 42 },
  seats: [{ x: 0, y: 94, w: 164, h: 172 }, { x: 176, y: 94, w: 164, h: 172 }],
  picks: { x: 0, y: 278, w: 340, h: 62 },
  room: { x: 0, y: 352, w: 340, h: 140 },
  ready: { x: 0, y: 504, w: 340, h: 56 },
  back: { x: 0, y: 572, w: 340, h: 44 },
  roomBare: { x: 0, y: 278, w: 340, h: 282 },
};
const LANDSCAPE: Layout = {
  w: 660, h: 316,
  title: { x: 0, y: 0, w: 320, h: 30 },
  hint: { x: 0, y: 40, w: 320, h: 42 },
  seats: [{ x: 0, y: 94, w: 154, h: 222 }, { x: 166, y: 94, w: 154, h: 222 }],
  room: { x: 340, y: 0, w: 320, h: 140 },
  picks: { x: 340, y: 150, w: 320, h: 62 },
  ready: { x: 340, y: 220, w: 320, h: 44 },
  back: { x: 340, y: 272, w: 320, h: 44 },
  roomBare: { x: 340, y: 0, w: 320, h: 264 },
};

export interface Seat { name: string; role: string; me: boolean; tone: Tone; label: string; core: CoreId | null; foot: string }
interface Btn { id: string; label: string; x: number; y: number; w: number; h: number; style: ButtonStyle; off?: boolean; sub?: string; tap(): void }
interface Snap { room: string; connected: boolean; peerReady: boolean; left: boolean; held: boolean }

export class OnlineLobby {
  private readonly panel: Panel | null = null;
  private readonly web: WebOnlineLobby | null = null;
  private closeKeyboard: (() => void) | null = null;
  visible = false;
  result: string[] = [];
  private toast = { text: '', seat: -1, t: 0 };
  private last: Snap | null = null;
  private signature = '';
  private frame = { x: 0, y: 0, k: 1, l: PORTRAIT };
  constructor(private readonly ov: Overlay | null, readonly room: OnlineRoom, private readonly back: () => void) {
    if (!ov) { this.web = new WebOnlineLobby(); return; }
    this.panel = ov.panel('online-lobby', 45, (g, w, h) => {
      backdrop(g, w, h, false, true);
      const { x, y, k } = this.frame;
      g.save(); g.translate(x, y); g.scale(k, k);
      if (this.result.length) this.paintResult(g);
      else this.paintRoom(g);
      g.restore();
    });
    this.panel.visible = false;
    ov.onFrame(dt => {
      if (!this.visible) return;
      this.panel!.place(0, 0, ov.W, ov.H);
      this.frame = this.fit();
      this.watch(dt);
      const { x, y, k } = this.frame;
      ov.region({ id: 'online-block', z: 45, x: 0, y: 0, w: ov.W, h: ov.H });
      for (const b of this.buttons()) ov.region({ id: `online-${b.id}`, z: 46, x: x + b.x * k, y: y + b.y * k, w: b.w * k, h: b.h * k, panel: this.panel!, tap: b.tap });
      // 倒计时按秒、提示条按帧闪；画面内容变了才重画。
      const sig = `${ov.W}x${ov.H}|${this.toast.t > 0 ? Math.floor(this.toast.t * 4) : 0}|${this.validity().text}|${this.room.starting}|${this.room.held}`;
      if (sig !== this.signature) { this.signature = sig; this.panel!.dirty = true; }
    });
  }
  show(value: boolean): void {
    if (!value) this.closeKeyboard?.();
    this.last = null; this.toast.t = 0;
    this.visible = value;
    if (this.panel) { this.panel.visible = value; this.panel.dirty = true; }
    this.web?.show(value);
    this.tick(0);
  }
  refresh(): void { if (this.panel) this.panel.dirty = true; this.tick(0); }
  tick(dt: number): void {
    if (!this.web || !this.visible) return;
    this.watch(dt);
    this.web.render({
      room: this.room.view.room, note: this.toastText() || this.room.view.note,
      status: this.validity().text, lines: this.roomLines(), seats: this.seats(),
      buttons: this.buttons(), result: this.result,
    });
  }
  /** 当前提示条文字；收起后为空。 */
  toastText(): string { return this.toast.t > 0 ? this.toast.text : ''; }

  private fit(): { x: number; y: number; k: number; l: Layout } {
    const { W, H, insets, capsule } = this.ov!;
    const l = W > H ? LANDSCAPE : PORTRAIT;
    const top = Math.max(insets.top, l === PORTRAIT && capsule ? capsule.y + capsule.h : 0) + 8;
    const left = insets.left + 8, availW = W - left - insets.right - 8, availH = H - top - insets.bottom - 8;
    const k = Math.min(1, availW / l.w, availH / l.h);
    return { x: left + (availW - l.w * k) / 2, y: top + (availH - l.h * k) / 2, k, l };
  }
  private peerName(): string { return NAMES[1 - this.room.player]; }
  /** 每帧比对房间状态，队友进出、准备变化弹一条提示，对应格子闪三秒。 */
  private watch(dt: number): void {
    const v = this.room.view, peer = 1 - this.room.player;
    const now: Snap = { room: v.room, connected: v.connected, peerReady: v.ready[peer], left: v.left, held: this.room.held };
    const was = this.last;
    this.last = now;
    if (this.toast.t > 0) this.toast.t = Math.max(0, this.toast.t - dt);
    if (!was) return;
    const name = this.peerName();
    let say = '';
    if (!was.connected && now.connected) say = v.host ? `${name}已加入` : '已进入一号的房间';
    else if (was.connected && !now.connected && now.left) say = `${name}已离开`;
    else if (now.connected && was.held !== now.held) say = now.held ? `${name}暂时离开` : `${name}回来了`;
    else if (now.connected && was.connected && was.peerReady !== now.peerReady) say = now.peerReady ? `${name}已准备` : `${name}取消准备`;
    if (say) this.flash(say, peer);
  }
  private flash(text: string, seat = -1): void {
    this.toast = { text, seat, t: TOAST_S };
    if (this.panel) this.panel.dirty = true;
  }

  seats(): [Seat, Seat] {
    const v = this.room.view, me = this.room.player;
    const make = (i: 0 | 1): Seat => {
      const mine = i === me;
      let tone: Tone = 'empty';
      if (v.room && (mine || v.connected)) tone = !mine && this.room.held ? 'away' : v.ready[i] ? 'ready' : 'joined';
      else if (!mine && v.left) tone = 'left';
      const both = v.ready[0] && v.ready[1];
      const foot = {
        empty: v.room && v.host ? (__WX__ ? '等队友粘贴邀请' : '等队友输入房间码') : '',
        joined: mine ? '选好流派点准备' : '正在选流派',
        ready: both ? '马上开局' : '等待开局',
        left: v.room ? '可再邀请新队友' : '',
        away: '等他回来',
      }[tone];
      return { name: NAMES[i], role: i === 0 ? '房主' : '队友', me: !!v.room && mine, tone, label: TONES[tone].label, core: tone === 'empty' || tone === 'left' ? null : v.cores[i], foot };
    };
    return [make(0), make(1)];
  }
  /** 房间是否还有效：一个短标签加语气。 */
  private validity(): { text: string; warn: boolean; good: boolean } {
    const v = this.room.view, r = this.room;
    if (!v.room) return v.busy ? { text: '连接中', warn: false, good: false } : v.lost ? { text: '房间已失效', warn: true, good: false } : { text: '未建房', warn: false, good: false };
    if (r.reconnecting) return { text: '重连中', warn: true, good: false };
    if (r.starting) return { text: '开局中', warn: false, good: true };
    const left = r.waitLeft();
    if (left >= 0) {
      const s = Math.ceil(left / 1000);
      return { text: `有效 · 剩${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`, warn: s <= 60, good: false };
    }
    return { text: v.connected ? '已连通' : '连接中', warn: false, good: v.connected };
  }
  private roomLines(): string[] {
    const v = this.room.view;
    if (!__WX__) {
      if (!v.room) return v.help.length ? v.help : ['房主创建房间，队友输入房间码', '也可打开邀请链接直接加入'];
      return v.connected ? ['两人都准备后自动开局'] : ['把房间码或邀请链接发给队友'];
    }
    if (!v.room) {
      const extra = [...(v.detail ? v.detail.split('\n') : []), ...v.help];
      return extra.length ? extra : ['房主点创建房间，再点复制邀请', '队友复制整条邀请，点粘贴并加入', '两人进入同一个体验版'];
    }
    if (!v.connected) return v.host ? ['点复制邀请，到微信发给队友', '切到微信不会关房间'] : ['正在连接一号'];
    return ['房间已满两人', '两人都准备后自动开局'];
  }

  buttons(): Btn[] {
    const v = this.room.view, l = this.frame.l, out: Btn[] = [];
    const at = (b: Box, id: string, label: string, style: ButtonStyle, tap: () => void, more: Partial<Btn> = {}): Btn => ({ id, label, x: b.x, y: b.y, w: b.w, h: b.h, style, tap, ...more });
    if (this.result.length) {
      out.push(at(l.ready, 'return', '回房间', 'gold', () => { this.result = []; void this.room.finish(); this.refresh(); }));
      return out;
    }
    if (v.room) {
      const p = l.picks, w = (p.w - 18) / 4;
      for (const [i, core] of PICKS.entries()) out.push(at({ x: p.x + i * (w + 6), y: p.y + 18, w, h: 44 }, `core-${core}`, CORES[core].name,
        v.cores[this.room.player] === core ? 'chipOn' : 'chip', () => this.room.choose(core), { off: this.room.starting }));
      if (v.host && !v.connected) out.push(at({ x: l.room.x + 12, y: l.room.y + l.room.h - 54, w: l.room.w - 24, h: 44 }, 'copy', __WX__ ? '复制邀请' : '邀请链接', 'outline', () => this.copy()));
      const mine = v.ready[this.room.player];
      const off = this.room.starting ? '正在准备战场' : v.busy ? '请稍候' : !v.connected ? '等待队友加入' : '';
      out.push(at(l.ready, 'ready', this.room.starting ? '开局中' : mine ? '取消准备' : '准备', mine || off ? 'outline' : 'gold',
        () => { if (off) this.flash(off); else this.room.ready(); },
        { off: !!off, sub: off || (mine && !v.ready[1 - this.room.player] ? `等${this.peerName()}准备` : '') }));
    } else if (!v.busy) {
      const r = l.roomBare, w = (r.w - 34) / 2, y = r.y + r.h - 56;
      out.push(at({ x: r.x + 12, y, w, h: 44 }, 'create', v.lost ? '重新建房' : '创建房间', 'gold', () => void this.room.enter()));
      out.push(at({ x: r.x + 22 + w, y, w, h: 44 }, 'join', __WX__ ? '粘贴并加入' : '输入房间码', 'outline', () => this.join()));
    }
    out.push(at(l.back, 'back', v.room ? '离开房间' : '主菜单', 'ghost', () => { void this.room.leave(); this.show(false); this.back(); }));
    return out;
  }

  private paintResult(g: CanvasRenderingContext2D): void {
    const l = this.frame.l, cx = l.w / 2;
    g.font = font(24, 800);
    text(g, '本局战报', cx, 20, '#ead5a6', 'center');
    g.font = font(14);
    this.result.slice(0, 9).forEach((line, i) => text(g, ellipsize(g, line, l.w - 20), cx, 64 + i * 24, '#d8dec9', 'center'));
    this.paintButtons(g);
  }
  private paintRoom(g: CanvasRenderingContext2D): void {
    const v = this.room.view, l = this.frame.l;
    g.font = font(24, 800);
    text(g, '联机双人', l.title.x + l.title.w / 2, l.title.y + 15, '#ead5a6', 'center');
    // 提示条：平时显示房间说明；队友进出时换成亮条三秒。
    const h = l.hint, on = this.toast.t > 0;
    const warn = v.lost || /失败|过期|结束|离开|超时/.test(v.note);
    armorPanel(g, h.x, h.y, h.w, h.h, on ? '#3a3018' : '#141d18', on ? '#e8c877' : warn ? '#b8703f' : '#4b574b', 6, on ? 2 : 1);
    g.font = font(on ? 17 : 15, on ? 800 : 600);
    text(g, ellipsize(g, on ? this.toast.text : v.note, h.w - 24), h.x + h.w / 2, h.y + h.h / 2, on ? '#ffe2a0' : warn ? '#f2a066' : '#d8dec9', 'center');
    const seats = this.seats();
    seats.forEach((s, i) => this.paintSeat(g, s, l.seats[i], on && this.toast.seat === i));
    if (v.room) {
      const p = l.picks;
      g.font = font(12, 600);
      text(g, '我的流派', p.x + 2, p.y + 8, '#97a293');
    }
    this.paintRoomBox(g, v.room ? l.room : l.roomBare);
    this.paintButtons(g);
  }
  private paintSeat(g: CanvasRenderingContext2D, s: Seat, b: Box, hot: boolean): void {
    const t = TONES[s.tone];
    const blink = hot && Math.floor(this.toast.t * 4) % 2 === 0;
    armorPanel(g, b.x, b.y, b.w, b.h, s.tone === 'empty' ? '#101814' : '#18221d', blink ? '#ffe2a0' : t.edge, 8, hot ? 3 : 2);
    if (s.tone === 'empty') {
      // 空位：内圈虚线框。
      g.fillStyle = '#4b574b';
      for (let x = b.x + 12; x < b.x + b.w - 12; x += 10) { g.fillRect(x, b.y + 6, 5, 1); g.fillRect(x, b.y + b.h - 7, 5, 1); }
    }
    const x = b.x + 12, r = b.x + b.w - 12;
    g.font = font(22, 800);
    text(g, s.name, x, b.y + 24, s.tone === 'empty' ? '#a7b0a2' : '#f0e2bc');
    g.font = font(12, 700);
    let tx = r;
    const tag = (label: string, ink: string, face: string) => {
      const w = g.measureText(label).width + 12;
      tx -= w;
      g.fillStyle = face; g.fillRect(tx, b.y + 14, w, 20);
      text(g, label, tx + w / 2, b.y + 24, ink, 'center');
      tx -= 4;
    };
    tag(s.role, '#c9d0c0', '#2b362e');
    if (s.me) tag('你', '#172326', '#e1c695');
    g.fillStyle = '#ffffff1a'; g.fillRect(x, b.y + 44, b.w - 24, 1);
    // 状态牌：形状标记 + 状态字。
    const by = b.y + 56, bh = 40;
    armorPanel(g, x, by, b.w - 24, bh, t.face, t.edge, 5, 2);
    g.font = font(15, 800);
    if (g.measureText(t.label).width > b.w - 60) g.font = font(13, 800);
    const lw = g.measureText(t.label).width, mx = b.x + (b.w - lw - 22) / 2;
    this.mark(g, s.tone, mx + 7, by + bh / 2, t.ink);
    text(g, t.label, mx + 22, by + bh / 2, t.ink);
    g.font = font(12, 600);
    const cy = by + bh + Math.max(26, (b.h - (by - b.y) - bh - 22) / 2);
    text(g, '流派', x, cy - 14, '#97a293');
    g.font = font(20, 800);
    text(g, s.core ? CORES[s.core].name : '—', x, cy + 8, s.core ? '#ead5a6' : '#5f6b5d');
    if (s.foot) {
      g.font = font(12, 600);
      text(g, ellipsize(g, s.foot, b.w - 24), x, b.y + b.h - 18, '#a7b0a2');
    }
  }
  /** 状态标记：空框 / 圆点 / 对勾 / 叉 / 暂停。 */
  private mark(g: CanvasRenderingContext2D, tone: Tone, x: number, y: number, ink: string): void {
    g.strokeStyle = ink; g.fillStyle = ink; g.lineWidth = 2.2; g.lineCap = 'round';
    g.beginPath();
    if (tone === 'empty') g.strokeRect(x - 6, y - 6, 12, 12);
    else if (tone === 'joined') { g.arc(x, y, 5.5, 0, Math.PI * 2); g.stroke(); g.beginPath(); g.arc(x, y, 2.2, 0, Math.PI * 2); g.fill(); }
    else if (tone === 'ready') { g.moveTo(x - 6, y); g.lineTo(x - 2, y + 5); g.lineTo(x + 7, y - 6); g.stroke(); }
    else if (tone === 'left') { g.moveTo(x - 5, y - 5); g.lineTo(x + 5, y + 5); g.moveTo(x + 5, y - 5); g.lineTo(x - 5, y + 5); g.stroke(); }
    else { g.fillRect(x - 5, y - 6, 3.5, 12); g.fillRect(x + 1.5, y - 6, 3.5, 12); }
  }
  private paintRoomBox(g: CanvasRenderingContext2D, b: Box): void {
    armorPanel(g, b.x, b.y, b.w, b.h, '#141d18', '#4b574b', 6, 1);
    g.font = font(15, 800);
    text(g, !__WX__ && this.room.view.room ? `房间 ${this.room.view.room}` : '房间', b.x + 12, b.y + 20, '#ead5a6');
    const s = this.validity();
    g.font = font(13, 700);
    const w = g.measureText(s.text).width + 16, ink = s.warn ? '#f2a066' : s.good ? '#a6e07e' : '#c9d0c0';
    armorPanel(g, b.x + b.w - 12 - w, b.y + 8, w, 24, s.warn ? '#2c1b12' : s.good ? '#17291a' : '#222c26', s.warn ? '#b8703f' : s.good ? '#73a955' : '#4b574b', 4, 1);
    text(g, s.text, b.x + b.w - 12 - w / 2, b.y + 20, ink, 'center');
    g.font = font(13);
    this.roomLines().slice(0, 6).forEach((line, i) => text(g, ellipsize(g, line, b.w - 24), b.x + 12, b.y + 48 + i * 19, '#c4ccbd'));
  }
  private paintButtons(g: CanvasRenderingContext2D): void {
    for (const b of this.buttons()) {
      g.globalAlpha = b.off ? 0.55 : 1;
      button(g, b.x, b.y, b.w, b.h, b.off ? 'ghost' : b.style, b.label, { size: b.h >= 50 ? 18 : 15, sub: b.sub || undefined, pressed: !b.off && this.ov?.pressed === `online-${b.id}` });
      g.globalAlpha = 1;
    }
  }
  private say(note: string): void { this.room.view.note = note; this.refresh(); }
  private editable(): boolean { return onlineWx()?.canIUse?.('showModal.object.editable') !== false; }
  /** 复制整条邀请；剪贴板接口不能用时，弹系统输入框让房主自己全选复制（系统输入框的复制不走小游戏接口）。 */
  private copy(): void {
    if (!__WX__) { this.closeKeyboard?.(); this.closeKeyboard = roomDialog(this.room.view.room, () => {}); return; }
    const wx = onlineWx(), code = this.room.view.room;
    if (!wx || !code) return;
    const data = inviteText(code);
    const fail = (error: unknown) => {
      console.warn('[online] copy', error);
      if (!this.editable()) { this.say(clipFail(error)); return; }
      this.say(`${clipFail(error)}，请手动复制`);
      wx.showModal({ title: '长按全选后复制', editable: true, content: data, confirmText: '复制好了', success: () => this.say('切到微信，发给队友') });
    };
    try { wx.setClipboardData({ data, success: () => this.say('已复制，切到微信发给队友'), fail }); } catch (error) { fail(error); }
  }
  /** 先读剪贴板，读到完整邀请直接加入；读不到再弹输入框让队友长按粘贴。 */
  private join(): void {
    if (!__WX__) { this.closeKeyboard?.(); this.closeKeyboard = roomDialog(null, code => void this.room.enter(code)); return; }
    const wx = onlineWx();
    if (!wx) return;
    const enter = (value: string) => {
      const code = parseInvite(value);
      if (code) void this.room.enter(code);
      else this.say('粘贴的不是完整房间号');
    };
    const ask = () => {
      if (this.editable()) {
        wx.showModal({
          title: '粘贴邀请', editable: true, placeholderText: '长按这里，粘贴房主发的整条邀请',
          success: (res: { confirm: boolean; content?: string }) => { if (res.confirm) enter(res.content ?? ''); },
        });
      } else this.keyboard(enter);
    };
    if (!wx.getClipboardData) { ask(); return; }
    try {
      wx.getClipboardData({
        success: (res: { data?: string }) => { const code = parseInvite(res?.data ?? ''); if (code) void this.room.enter(code); else ask(); },
        fail: (error: unknown) => { console.warn('[online] paste', error); ask(); },
      });
    } catch (error) { console.warn('[online] paste', error); ask(); }
  }
  private keyboard(enter: (value: string) => void): void {
    const wx = onlineWx();
    if (!wx) return;
    // 可编辑弹窗晚于基础库 2.8.0；老版本用小游戏原生键盘。
    this.closeKeyboard?.();
    const done = () => {
      wx.offKeyboardConfirm(confirm); wx.offKeyboardComplete(done);
      this.closeKeyboard = null;
    };
    const confirm = (res: { value: string }) => { done(); wx.hideKeyboard({}); enter(res.value); };
    this.closeKeyboard = () => { done(); wx.hideKeyboard({}); };
    wx.onKeyboardConfirm(confirm); wx.onKeyboardComplete(done);
    wx.showKeyboard({ defaultValue: '', maxLength: 4096, multiple: false, confirmHold: false, confirmType: 'done', fail: () => {
      done(); this.room.view.note = '键盘未打开，请重试'; this.refresh();
    } });
    this.room.view.note = '粘贴整条邀请后确认'; this.refresh();
  }
}
