import { FUSIONS, type FusionId } from '../defs';
import { AURORA, AuroraUlt } from './aurora';
import { CURTAIN, CurtainUlt } from './curtain';
import { GUNSHIP, GunshipUlt } from './gunship';
import type { Ultimate } from './common';
import { INFERNO, InfernoUlt } from './inferno';
import { NUKE, NukeUlt } from './nuke';
import { SKYFIRE, SkyfireUlt } from './skyfire';
import { SNARE, SnareUlt } from './snare';
import { SWARM, SwarmUlt } from './swarm';

export type { UltAim, UltContext, UltHit, UltLamp, UltPreview, UltState, Ultimate } from './common';

/** 各终极的数值表（调试 __TANK_DEBUG__.tune.<id> 直接改，改了立刻生效；scripts/fusion.mjs 的 TUNE 也改这里） */
export const FUSION_TUNE: Record<FusionId, object> = { nuke: NUKE, inferno: INFERNO, snare: SNARE, swarm: SWARM, skyfire: SKYFIRE, aurora: AURORA, gunship: GUNSHIP, curtain: CURTAIN };

export function createUlt(id: FusionId): Ultimate {
  switch (id) {
    case 'nuke': return new NukeUlt(FUSIONS.nuke);
    case 'inferno': return new InfernoUlt(FUSIONS.inferno);
    case 'snare': return new SnareUlt(FUSIONS.snare);
    case 'swarm': return new SwarmUlt(FUSIONS.swarm);
    case 'skyfire': return new SkyfireUlt(FUSIONS.skyfire);
    case 'aurora': return new AuroraUlt(FUSIONS.aurora);
    case 'gunship': return new GunshipUlt(FUSIONS.gunship);
    case 'curtain': return new CurtainUlt(FUSIONS.curtain);
  }
}
