import * as THREE from 'three';
import type { GeoCache } from '../assets/GeoCache';
import { SMOKE_BEHIND } from '../render/Fx';
import { ELITE, Enemy, ROCKET_AIM_TIME, ROCKET_LOCK_TIME, type EnemyKind, type EnemySpec, type ShotKind } from '../entities/Enemy';
import { BRIDGE } from '../world/Rivers';
import type { AirFleet } from './Air';
import { nearestPlayer, type PlayerTarget } from '../game/players';
import { rng } from '../game/rng';
import type { Push } from '../world/footBlock';

const DESPAWN_BEHIND = 45;
/** 浅滩里敌人和坦克一样减速（T025，坦克是 Game.stepPlayer 的 × 0.55） */
const WADE = 0.55;
/** 深水河的桥口（T027-d）：被深水挡住的敌人沿岸挪到离路中间这么近就能上桥（T034：桥加宽到 13.2 米，桥面 |x| < 6.2，跟着 BRIDGE.enemyX） */
const BRIDGE_X = BRIDGE.enemyX;

export interface EnemyHooks {
  /** 在浅滩里走（T025）：溅一下水花 */
  wade?(e: Enemy): void;
  /** 直射类开火：dirX/dirZ 为单位方向 */
  fire(shot: ShotKind, x: number, z: number, dirX: number, dirZ: number, speed: number, damage: number): void;
  /** 自行火炮：抛射到 (tx, tz) */
  artillery(x: number, z: number, tx: number, tz: number, damage: number): void;
  /** 电击兵：近距离电弧 */
  zap(e: Enemy, damage: number): void;
  /** 运兵车放兵 */
  spawnUnit(kind: EnemyKind, x: number, z: number): void;
  /** 残骸冒烟 */
  smoke(x: number, z: number, big: boolean, burning: boolean): void;
  /** 开始瞄准（提示音；光棱坦克是充能声） */
  aimStart(e: Enemy): void;
  /** 爆破兵贴到坦克身边引爆 */
  detonate(e: Enemy): void;
  /** 光棱坦克充能中：urgency 0..1 越接近开火越大 */
  charge(e: Enemy, urgency: number): void;
  /** 燃烧伤害结算（每 0.25 秒一次） */
  burn(e: Enemy, damage: number): void;
  /** 被冲击波掀起来的车落回地面（二次扬尘，size 按体型） */
  land?(x: number, z: number, size: number): void;
  /** 断电中（天罗）：车身爬蓝色电火花；done = 这一帧刚恢复供电（「咔」一声 + 冒一股黑烟） */
  powered?(e: Enemy, done: boolean): void;
  /** 被打爆的摩托（S10）每帧一次：空中拖烟火、落地（e.landed）扬尘、滑行擦火花、刚躺稳（e.rested）开始原地烧 */
  moto?(e: Enemy): void;
  /** 精英「冰雹王」呼叫一轮徐进弹幕（T017-9A；e.mode = 这是第几轮，指挥车被击毁还没落的排就不打了） */
  barrage?(e: Enemy): void;
  /** 精英「破城槌」（T017-9A）：warn = 开始预警（喇叭 + 扬尘 + 冲撞线红圈）、charge = 冲出去、hit = 撞上坦克、plow = 冲撞中推开路上的东西、brake = 刹车、crash = 一头撞在地形上停下（汇总第 61 条） */
  ram?(e: Enemy, ev: 'warn' | 'charge' | 'hit' | 'plow' | 'brake' | 'crash'): void;
  /** 破城槌冲撞中（汇总第 61 条）：撞角从 (x, z) 往前 step 米之间有没有挡路的地形（房子 / 残墙 / 砖墙 / 巨石 / 车壳）；撞上了返回 true（顺带在墙上撞出痕迹） */
  ramWall?(e: Enemy, x: number, z: number, step: number): boolean;
  /** 破城槌冲撞中每帧一次：把撞角前面的敌人 / 路障 / 残骸推到一边，返回这一帧的车速倍率（每撞上一个只轻微减速） */
  ramPush?(e: Enemy, delta: number): number;
  /** 「轰天」卫队（T050）想出大招（dur = 要躲多少秒）：轮到它返回 true，没轮到就接着等（每帧再要） */
  turn?(e: Enemy, dur: number): boolean;
}

/**
 * 履带约束（T017-8A）：这些载具只能沿车头方向前进 / 倒车，想去的方向和车头夹角大就先原地转向（车头转速，弧度/秒：重 0.6 / 中 1.2 / 轻 2.5）；
 * 炮塔单独朝玩家（炮塔转速 = 车头 × TRACK.turret）。原来车头一直对着玩家、车身直接朝想去的方向平移，据守精英 100% 是横着走
 */
export const TRACK_TURN: Partial<Record<EnemyKind, number>> = { heavy: 0.6, medium: 1.2, apc: 1.2, spg: 1.2, rocketTank: 1.2, prism: 1.2, rusher: 2.5, gunner: 2.5, bulwark: 0.5, hailking: 0.9 };
/** go：车头和要去的方向夹角的 cos 到这里才开始走（≈ 49°），越正越快；back：倒车比前进慢多少；idle：停下多久后车头慢慢转回来对着玩家；homeZ：据守精英离刷出位置前后最多挪多远 */
export const TRACK = { go: 0.65, back: 0.8, turret: 2, idle: 0.8, homeZ: 3 };

const wrapAngle = (a: number) => {
  while (a > Math.PI) a -= Math.PI * 2;
  while (a < -Math.PI) a += Math.PI * 2;
  return a;
};

/**
 * 履带车走一帧：(vx, vz) = 想走的速度。reverse = 想去的方向在车尾一侧时允许倒车（后撤 / 据守对位），否则掉头。
 * 返回 [新的车头朝向（atan2(x, z) 约定）, 这一帧位移 x, z]
 */
export function trackStep(rot: number, vx: number, vz: number, turn: number, delta: number, reverse: boolean): [number, number, number] {
  const sp = Math.hypot(vx, vz);
  if (sp < 1e-4) return [rot, 0, 0];
  const h = Math.atan2(vx, vz);
  const fwd = wrapAngle(h - rot);
  const rev = wrapAngle(h + Math.PI - rot);
  const back = reverse && Math.abs(rev) < Math.abs(fwd);
  const d = back ? rev : fwd;
  const step = Math.max(-turn * delta, Math.min(turn * delta, d));
  const r = rot + step;
  const k = Math.max(0, Math.min(1, (Math.cos(d - step) - TRACK.go) / (1 - TRACK.go)));
  const v = sp * k * (back ? -TRACK.back : 1) * delta;
  return [r, Math.sin(r) * v, Math.cos(r) * v];
}

/** 电网减速（天罗）：移动 / 转向倍率、开火计时倍率 */
const SLOW_MOVE = 0.4;
const SLOW_FIRE = 0.7;

/** 敌人池 + AI：移动、开火、瞄准线、绕侧、放兵、残骸动画 */
/** 提前量：子弹飞到时坦克会在哪 */
function lead(x: number, z: number, px: number, pz: number, pvz: number, speed: number): number {
  const t = Math.hypot(px - x, pz - z) / Math.max(1, speed);
  return Math.atan2(px - x, pz + pvz * t - z);
}

export class Enemies {
  readonly list: Enemy[] = [];
  /** 只在绘制时托起深坑里的单位；逻辑位置、命中和走位不读这份高度。 */
  drawLift: ((x: number, z: number, maxDrop: number) => number) | null = null;
  private readonly drawY: number[] = [];
  /** 停火（T017-16A 首领出场亮相期间）：照常走，不开火、不亮瞄准线 */
  ceasefire = false;
  /** 「轰天」卫队可以开打了（T050，Game 每帧设）：之前冰雹王不叫弹幕、破城槌原地待命 */
  gateOpen = true;
  /** 停车攻坚中铁壁往前压，车头最多压到这里（世界 z，Game 每帧设；null = 没在停车攻坚）：你往后撤它跟上来，也不占掉停车点（T109） */
  pressCap: number | null = null;
  private time = 0;
  /** 地面高度（实体弹坑；T025 起含桥面）：活着的敌人和车辆残骸贴着地面走，开进坑里跟着下沉 */
  groundAt: ((x: number, z: number) => number) | null = null;
  /**
   * 河（T025）：(x, z) 在水里就返回这条河（deep = 有桥的深水河，桥面上不算水；near / far = 这个 x 上两岸的 z），不在水里 null。
   * 浅滩里敌人和坦克一样 × WADE 减速、溅水花（wade 钩子）；深水敌人不下水：走到岸边停在岸上（只保留顺着岸的横向挪动，挪到桥上就能过），已经在深水里的就近上岸
   */
  river: ((x: number, z: number) => { deep: boolean; near: number; far: number } | null) | null = null;
  /** 空中单位（T091）：活着的 / 正在坠落的交给它走 */
  air: AirFleet | null = null;
  /**
   * 步兵脚下的障碍（T246）：(x, z) 半径 r 的人被没毁掉的障碍物 / 活着的车（不含 self）推出去，位移累加进 out，碰到返回 true。
   * 被压扁、炸飞的路障和车辆残骸不挡
   */
  foot: ((x: number, z: number, r: number, out: Push, self: Enemy) => boolean) | null = null;
  private readonly push: Push = { x: 0, z: 0 };

  constructor(
    scene: THREE.Scene,
    geo: GeoCache,
    private readonly hooks: EnemyHooks,
    poolSize = 180,
  ) {
    for (let i = 0; i < poolSize; i++) {
      const e = new Enemy(geo);
      this.list.push(e);
      scene.add(e.group);
    }
  }

  spawn(kind: EnemyKind, x: number, z: number, hpScale: number, size = 1, boss = false, override: EnemySpec | null = null): Enemy | null {
    const e = this.list.find((item) => item.state === 'dead');
    if (!e) return null;
    e.spawn(kind, x, z, hpScale, size, boss, override);
    return e;
  }

  clear(): void {
    for (const e of this.list) e.kill();
  }

  beginGroundDraw(): void {
    if (!this.drawLift) return;
    for (let i = 0; i < this.list.length; i++) {
      const e = this.list[i];
      this.drawY[i] = NaN;
      if (e.state === 'dead' || e.flying || e.controller || !e.group.visible) continue;
      const p = e.group.position;
      const lift = this.drawLift(p.x, p.z, Math.min(0.35, 0.25 * e.size));
      if (lift <= 0) continue;
      this.drawY[i] = p.y;
      p.y += lift;
    }
  }

  endGroundDraw(): void {
    for (let i = 0; i < this.drawY.length; i++) {
      const y = this.drawY[i];
      if (!Number.isFinite(y)) continue;
      const e = this.list[i];
      e.group.position.y = y;
      e.group.updateMatrixWorld(true);
      this.drawY[i] = NaN;
    }
  }

  get aliveCount(): number {
    let n = 0;
    for (const e of this.list) if (e.alive) n++;
    return n;
  }

  hasBlocker(): boolean {
    return this.list.some((e) => e.alive && (e.spec.blocker || e.guard));
  }

  /** 前方纵向距离 range 内存活的拦路精英 / Boss 部件（破城槌冲到身后 90 米内也算：坦克停着跟它周旋，T017-9A） */
  blockerAhead(pz: number, range: number): Enemy | null {
    let best: Enemy | null = null;
    let bestAhead = range;
    for (const e of this.list) {
      if (!e.alive || !(e.spec.blocker || e.guard)) continue;
      const ahead = pz - e.group.position.z;
      if (ahead < bestAhead && ahead > (e.spec.charger ? -90 : -10)) {
        bestAhead = ahead;
        best = e;
      }
    }
    return best;
  }

  /** 只找前方（含身侧一点）的最近存活敌人 */
  nearest(x: number, z: number, range: number): Enemy | null {
    let best: Enemy | null = null;
    let bestD = range * range;
    for (const e of this.list) {
      if (!e.alive || e.flying) continue;
      if (e.group.position.z > z + 6) continue;
      const dx = e.group.position.x - x;
      const dz = e.group.position.z - z;
      const d = dx * dx + dz * dz;
      if (d < bestD) {
        bestD = d;
        best = e;
      }
    }
    return best;
  }

  /**
   * players：每辆玩家车的位置 / 速度（T117；每个敌人打离自己最近的那辆，vz 给炮兵算提前量），第一辆是镜头跟的主玩家（残骸冒烟按它）；
   * rear：甩到身后多远回收按的位置（T106 停车攻坚时是能退到的最远处，平时就是玩家）；wreckRear = 残骸按的（T240 比 rear 再靠后，见 Game.worldRear）
   */
  update(delta: number, players: readonly PlayerTarget[], rear = players[0].z, wreckRear = rear): void {
    this.time += delta;
    const lead = players[0];
    for (const e of this.list) {
      if (e.state === 'wreck') {
        if (e.fly && e.fly.crash >= 0 && this.air) this.air.crash(e, delta);
        else this.stepWreck(e, delta, lead.z, wreckRear);
        continue;
      }
      if (!e.alive) continue;
      if (e.fly && this.air) {
        this.air.step(e, delta);
        continue;
      }
      // 破城槌冲过头会跑到坦克身后几十米再掉头回来（T017-9A），不按普通敌人回收
      if (e.group.position.z > rear + (e.spec.charger ? 120 : DESPAWN_BEHIND) && !e.controller) {
        e.kill();
        continue;
      }
      const ox = e.group.position.x;
      const oz = e.group.position.z;
      const p = nearestPlayer(players, ox, oz);
      this.stepAlive(e, delta, p.x, p.z, p.vz);
      if (e.alive && !e.controller && this.river) this.stepRiver(e, ox, oz, delta);
      if (e.alive && !e.controller && this.foot && e.spec.crushable && e.kind !== 'moto' && !e.spec.fixed && !e.flying) this.stepFoot(e, ox, oz);
      if (e.alive && !e.controller) {
        e.group.position.y = (this.groundAt ? this.groundAt(e.group.position.x, e.group.position.z) : 0) + this.stepHop(e, delta);
        // 被侧向爆炸掀起来的车落回去（T017-7a，只是演出）
        e.stepTilt(delta);
      }
    }
  }

  /** 河（T025，见 river）：浅滩减速 + 水花；深水不下水、退回岸上，已经在深水里的就近上岸 */
  private stepRiver(e: Enemy, ox: number, oz: number, delta: number): void {
    const pos = e.group.position;
    const w = this.river!(pos.x, pos.z);
    if (!w) return;
    if (!w.deep) {
      pos.x = ox + (pos.x - ox) * WADE;
      pos.z = oz + (pos.z - oz) * WADE;
      if (Math.abs(pos.x - ox) + Math.abs(pos.z - oz) > delta * 0.5 && Math.random() < delta * (e.spec.crushable ? 3 : 7)) this.hooks.wade?.(e);
      return;
    }
    if (!this.river!(ox, oz)) {
      // 刚要下水：退回岸上；顺着岸的横向挪动保留（挪到桥面上就能过河）
      if (this.river!(pos.x, oz)) pos.x = ox;
      pos.z = oz;
      // 沿着岸往桥口挪（T027-d：原来只会停在岸边，对岸一堆敌人站着不动）——按自己的速度 × 0.8 往路中间（桥）走，
      // 岸在田野里是弯的：这一步横移会下水就顺着岸往外让一点（离水那一侧）
      if (Math.abs(pos.x) > BRIDGE_X && e.spec.speed > 0) {
        const nx = pos.x - Math.sign(pos.x) * Math.min(Math.abs(pos.x) - BRIDGE_X, Math.max(1.5, e.spec.speed) * 0.8 * delta);
        const away = oz < (w.near + w.far) / 2 ? -1 : 1;
        for (const dz of [0, 0.4, 0.9, 1.6, 2.5]) {
          if (this.river!(nx, oz + away * dz)) continue;
          pos.x = nx;
          pos.z = oz + away * dz;
          break;
        }
      }
      return;
    }
    // 已经在深水里（被推进来的）：就近上岸
    const bank = Math.abs(pos.z - w.near) < Math.abs(pos.z - w.far) ? w.near : w.far;
    const step = Math.max(2, e.spec.speed) * delta;
    pos.z += Math.max(-step, Math.min(step, bank - pos.z));
  }

  /**
   * 步兵不穿障碍（T246）：这一帧走完后被障碍推出去；正面顶上去的那部分步子改成沿着边走，离开障碍前不换边。
   * 绕过去以后接着按原来的路线走。速度、交战距离都不变
   */
  private stepFoot(e: Enemy, ox: number, oz: number): void {
    const pos = e.group.position;
    const P = this.push;
    P.x = P.z = 0;
    if (!this.foot!(pos.x, pos.z, e.radius, P, e)) {
      e.footDir = 0;
      return;
    }
    const mx = pos.x - ox;
    const mz = pos.z - oz;
    const step = Math.hypot(mx, mz);
    const n = Math.hypot(P.x, P.z);
    pos.x += P.x;
    pos.z += P.z;
    if (step < 1e-4 || n < 1e-6) return;
    let tx = -P.z / n;
    let tz = P.x / n;
    let along = (tx * mx + tz * mz) / step;
    if (!e.footDir) e.footDir = (Math.abs(along) < 0.2 ? e.side : along) < 0 ? -1 : 1;
    if (e.footDir < 0) {
      tx = -tx;
      tz = -tz;
      along = -along;
    }
    const slide = step * (1 - Math.abs(along));
    pos.x += tx * slide;
    pos.z += tz * slide;
    P.x = P.z = 0;
    if (this.foot!(pos.x, pos.z, e.radius, P, e)) {
      pos.x += P.x;
      pos.z += P.z;
    }
  }

  /** 冲击波把车 / 人掀起来：受重力落回去，落地弹一下、扬一团尘（T014-4） */
  private stepHop(e: Enemy, delta: number): number {
    if (e.hop === 0 && e.hopV === 0) return 0;
    e.hopV -= e.hopG * delta;
    e.hop += e.hopV * delta;
    if (e.hop <= 0) {
      if (e.hopV < -4) this.hooks.land?.(e.group.position.x, e.group.position.z, e.radius);
      e.hop = 0;
      e.hopV = Math.abs(e.hopV) > 5 ? -e.hopV * 0.25 : 0;
      e.hopG = 26;
    }
    return e.hop;
  }

  private stepWreck(e: Enemy, delta: number, pz: number, rear: number): void {
    const g = this.groundAt ? this.groundAt(e.group.position.x, e.group.position.z) : 0;
    e.groundY = g;
    // 车辆残骸贴地（坑挖在它底下时跟着落下去），被冲击波掀起来的落回去；正在翻滚的（T017-7a）由 Enemy.stepTumble 管高度
    if (!e.spec.crushable && e.kind !== 'part' && (e.tumble === 0 || e.tumble === 3)) e.group.position.y = g + this.stepHop(e, delta);
    if (e.group.position.z > rear + DESPAWN_BEHIND || !e.updateWreck(delta)) {
      e.kill();
      return;
    }
    if (e.tumble > 0) {
      this.hooks.moto?.(e);
      e.landed = 0;
      e.rested = false;
      // 翻滚的车辆残骸：压扁用的凸起跟着走（T017-7a）
      if (e.bump && e.tumble < 3) {
        e.bump.x = e.group.position.x;
        e.bump.z = e.group.position.z;
      }
    }
    if (e.spec.crushable || e.kind === 'part') return;
    // 被爆炸推着滑一段，压扁用的凸起跟着走
    if (e.kvx !== 0 || e.kvz !== 0) {
      const pos = e.group.position;
      pos.x += e.kvx * delta;
      pos.z += e.kvz * delta;
      e.group.rotation.y += (e.kvx - e.kvz) * delta * 0.05;
      const damp = Math.exp(-delta * 3.5);
      e.kvx *= damp;
      e.kvz *= damp;
      if (Math.abs(e.kvx) + Math.abs(e.kvz) < 0.15) e.kvx = e.kvz = 0;
      if (e.bump) {
        e.bump.x = pos.x;
        e.bump.z = pos.z;
      }
    }
    e.smokeTimer -= delta;
    // 甩到坦克身后 8 米就不再冒烟（T017-15c：原来一直冒到 45 米回收，烟柱正好升到镜头和坦克之间）
    if (e.smokeTimer <= 0 && e.group.position.z <= pz + SMOKE_BEHIND.wreck) {
      // 前 35 秒熊熊燃烧冒浓烟，之后只剩闷烧的烟
      const burning = e.wreckTime > 55;
      e.smokeTimer = burning ? (e.spec.blocker ? 0.12 : 0.16) : 0.4;
      this.hooks.smoke(e.group.position.x, e.group.position.z, e.spec.blocker, burning);
    }
  }

  private stepAlive(e: Enemy, delta: number, px: number, pz: number, pvz: number): void {
    const spec = e.spec;
    const pos = e.group.position;
    if (e.burnTime > 0) {
      e.burnTime -= delta;
      e.burnTick -= delta;
      if (e.burnTick <= 0) {
        e.burnTick = 0.25;
        this.hooks.burn(e, e.burnDps * 0.25);
        if (!e.alive) return;
      }
    }
    // 破城槌冲撞中（汇总第 61 条）：横冲直撞——不吃麻痹（硬直）/ 击退 / 减速 / 断履带，照常掉血；预警、刹车、掉头照旧
    if (spec.charger && e.mode === 2) e.stunTime = e.kvx = e.kvz = e.slow = e.track = 0;
    // 被爆炸推开：车辆滑一段，步兵踉跄
    if (e.kvx !== 0 || e.kvz !== 0) {
      pos.x += e.kvx * delta;
      pos.z += e.kvz * delta;
      const damp = Math.exp(-delta * (spec.crushable ? 4 : 6));
      e.kvx *= damp;
      e.kvz *= damp;
      if (Math.abs(e.kvx) + Math.abs(e.kvz) < 0.2) e.kvx = e.kvz = 0;
    }
    // Boss 部件由 Boss 自己驱动
    if (e.controller) {
      e.updateFlash(delta);
      return;
    }
    // 翻倒的「火葬」卡车（T126）：没了动力，躺在原地（被炸开的那一下照样滑一段），不追、不转向
    if (e.upset) {
      e.updateFlash(delta);
      return;
    }
    if (e.stunTime > 0) {
      // 麻痹：原地抽搐，不移动不开火
      e.stunTime -= delta;
      e.group.rotation.y += (Math.random() - 0.5) * 0.3;
      e.laser.visible = false;
      e.updateFlash(delta);
      return;
    }
    if (e.power > 0) {
      // 断电（天罗）：停车、停火，掐断瞄准线和连射，运兵车不放兵、自爆卡车原地停；恢复后带瞄准线的要重新瞄 1.3 秒
      e.power -= delta;
      e.laser.visible = false;
      e.aiming = false;
      e.burstLeft = 0;
      const done = e.power <= 0;
      if (done) {
        e.power = 0;
        if (spec.telegraph) e.fireTimer = Math.max(e.fireTimer, ROCKET_AIM_TIME);
      }
      this.hooks.powered?.(e, done);
      e.updateFlash(delta);
      return;
    }
    // 电网减速（离开电网后再保持 1 秒，由终极每帧续上）、断履带（停车，照常转炮塔、开火）
    if (e.slow > 0) e.slow = Math.max(0, e.slow - delta);
    if (e.track > 0) e.track = Math.max(0, e.track - delta);
    if (e.supp > 0) e.supp = Math.max(0, e.supp - delta);
    const mv = e.track > 0 ? 0 : e.slow > 0 ? SLOW_MOVE : 1;
    const turn = e.slow > 0 ? SLOW_MOVE : 1;

    const dx = px - pos.x;
    const dz = pz - pos.z;
    const dist = Math.hypot(dx, dz) || 1;

    // 被炮火吓跑：背对爆炸方向撒腿狂奔，不开火
    if (e.panic > 0) {
      e.panic -= delta;
      const sp = spec.speed * 1.9 * mv;
      pos.x += e.panicX * sp * delta;
      pos.z += e.panicZ * sp * delta;
      let face = Math.atan2(e.panicX, e.panicZ) - e.group.rotation.y;
      while (face > Math.PI) face -= Math.PI * 2;
      while (face < -Math.PI) face += Math.PI * 2;
      e.group.rotation.y += face * Math.min(1, delta * 8);
      e.laser.visible = false;
      e.aiming = false;
      e.updateFlash(delta);
      return;
    }
    // 爆破兵冲到身边就拉响炸药包
    if (e.kind === 'sapper' && dist < 3.8) {
      this.hooks.detonate(e);
      return;
    }
    // 精英「破城槌」：自己的一套冲撞流程（不据守、不开火）
    if (spec.charger) {
      this.stepRam(e, px, pz, dx, dz, dist, delta, mv, turn);
      e.updateFlash(delta);
      return;
    }

    const rate = TRACK_TURN[e.kind];
    if (rate === undefined && !spec.flank) {
      // 步兵 / 阵地：朝向玩家（阵地转得慢）
      const diff = wrapAngle(Math.atan2(dx, dz) - e.group.rotation.y);
      e.group.rotation.y += diff * Math.min(1, delta * (spec.blocker || spec.fixed ? 1.6 : 4) * turn);
    }

    if (rate !== undefined) {
      this.stepTracked(e, dx, dz, dist, delta, mv, turn, rate);
    } else if (spec.flank) {
      // 摩托：绕到玩家侧前方，贴着跑
      const tx = px + e.side * 11;
      const tz = pz - 12 + Math.sin(this.time * 0.8 + e.side) * 5;
      const fx = tx - pos.x;
      const fz = tz - pos.z;
      const fd = Math.hypot(fx, fz) || 1;
      const sp = spec.speed * Math.min(1, fd / 4) * mv;
      const mx = (fx / fd) * sp * delta;
      const mz = (fz / fd) * sp * delta + pvz * delta * (fd < 6 ? mv : 0);
      pos.x += mx;
      pos.z += mz;
      // 摩托车头跟着行驶方向转，不再横着漂移；几乎停住时才转向玩家
      if (Math.hypot(mx, mz) > delta * 1.5) {
        let h = Math.atan2(mx, mz) - e.group.rotation.y;
        while (h > Math.PI) h -= Math.PI * 2;
        while (h < -Math.PI) h += Math.PI * 2;
        e.group.rotation.y += h * Math.min(1, delta * 6 * turn);
      }
    } else if (!spec.fixed) {
      // 步兵：有交战距离的到位后缓慢后撤；玩家推进更快，迟早会被追上碾过去
      const approach = spec.standoff > 0 && dist < spec.standoff ? -0.35 : 1;
      pos.x += (dx / dist) * spec.speed * approach * mv * delta;
      pos.z += (dz / dist) * spec.speed * approach * mv * delta;
    }

    // 运兵车到位放兵
    if (spec.unload && !e.unloaded && dist < spec.standoff + 8) {
      e.unloaded = true;
      for (let i = 0; i < spec.unload; i++) this.hooks.spawnUnit('infantry', pos.x + (i - (spec.unload - 1) / 2) * 1.8, pos.z - 3);
    }

    if (this.ceasefire) {
      e.burstLeft = 0;
      e.laser.visible = false;
      e.aiming = false;
      e.updateFlash(delta);
      return;
    }
    // 精英「冰雹王」：坦克到了跟前（停车攻坚的距离）才开始，每 every 秒呼叫一轮徐进弹幕（电网减速时按开火计时一起变慢）；
    // 卫队里的（T050）等开打、等轮到它（这一轮要躲到最后一排落地）
    if (e.kind === 'hailking' && dz > 0 && dz < ELITE.hailking.range && (!e.gate || this.gateOpen)) {
      const H = ELITE.hailking;
      e.modeT -= delta * (e.slow > 0 ? SLOW_FIRE : 1);
      if (e.modeT <= 0 && (!e.gate || (this.hooks.turn?.(e, (H.rows.length - 1) * H.step + H.flight) ?? true))) {
        e.modeT = H.every;
        e.mode += 1;
        this.hooks.barrage?.(e);
      }
    }
    // 机枪组 / 加特林连发：枪口左右扫
    if (e.burstLeft > 0) {
      e.burstTimer -= delta;
      if (e.burstTimer <= 0) {
        e.burstTimer = spec.burstGap ?? 0.09;
        e.burstLeft--;
        e.fireAnim = 0.3;
        const a = lead(pos.x, pos.z, px, pz, pvz, spec.bulletSpeed) + Math.sin(e.burstLeft * 0.9) * (spec.burstSpread ?? 0.06);
        this.hooks.fire(spec.shot, pos.x, pos.z, Math.sin(a), Math.cos(a), spec.bulletSpeed, spec.bulletDamage);
      }
    }

    const engageRange = spec.shot === 'artillery' ? 95 : spec.fixed ? 75 : Math.max(spec.standoff, 26) * 1.6;
    if (spec.fireInterval > 0 && dist < engageRange) {
      // 火神压制（D1-032 第 6.6 节）：开火间隔 × suppK
      e.fireTimer -= (delta * (e.slow > 0 ? SLOW_FIRE : 1)) / (e.supp > 0 ? e.suppK : 1);
      if (spec.telegraph) this.stepTelegraph(e, dx, dz, dist);
      else if (e.fireTimer <= 0) {
        e.fireTimer = spec.fireInterval * (0.85 + rng.foe() * 0.3);
        this.fireAt(e, px, pz, pvz, dist);
      }
    }

    e.updateFlash(delta);
  }

  /**
   * 履带车（T017-8A）：据守精英横向对位玩家（在刷出位置前后 ±TRACK.homeZ 米里），其余朝玩家开、到交战距离后倒车后撤；
   * 都只能沿车头走（trackStep）；停着久了车头慢慢转回来对着玩家；炮塔单独朝玩家
   */
  private stepTracked(e: Enemy, dx: number, dz: number, dist: number, delta: number, mv: number, turn: number, rate: number): void {
    const spec = e.spec;
    const pos = e.group.position;
    let vx = 0;
    let vz = 0;
    let reverse = false;
    if (e.kind === 'bulwark') {
      // 精英「铁壁」（T017-9A）：「往前压」和「横移换位」交替——压的时候车头（盾）对着坦克、据守位置每秒往坦克挪 creep 米（压到 near 米停）；
      // 换位时横着开到旁边 shiftDist 米（履带车要先把车身转过去，盾跟着车头转开，这几秒露出侧面），再转回来接着压
      const B = ELITE.bulwark;
      e.modeT -= delta;
      if (e.modeT <= 0) {
        e.mode = e.mode === 1 ? 0 : 1;
        e.modeT = e.mode === 1 ? B.shift : B.press;
        if (e.mode === 1) e.dirX = Math.max(-9, Math.min(9, pos.x + (Math.abs(pos.x) > 5 ? -Math.sign(pos.x) : rng.foe() < 0.5 ? -1 : 1) * B.shiftDist));
      }
      if (e.mode === 1) {
        if (Math.abs(e.dirX - pos.x) > 0.6) vx = Math.sign(e.dirX - pos.x) * spec.speed;
      } else {
        if (dz > B.near) {
          e.homeZ = Math.min(e.homeZ + B.creep * delta, pos.z + dz - B.near);
          if (this.pressCap !== null) e.homeZ = Math.min(e.homeZ, this.pressCap - ((e.footFront() ?? pos.z) - pos.z));
        }
        const off = e.homeZ - pos.z;
        vz = Math.abs(off) > 0.5 ? Math.max(-spec.speed, Math.min(spec.speed, off * 0.8)) : 0;
      }
      reverse = true;
    } else if (spec.blocker) {
      if (Math.abs(dx) > 1.5) vx = Math.sign(dx) * spec.speed;
      const off = e.homeZ - pos.z;
      vz = Math.abs(off) > 0.5 ? Math.max(-spec.speed, Math.min(spec.speed, off * 0.8)) : 0;
      if (Math.abs(off) > TRACK.homeZ) vx *= 0.3;
      reverse = true;
    } else {
      const approach = spec.standoff > 0 && dist < spec.standoff ? -0.35 : 1;
      vx = (dx / dist) * spec.speed * approach;
      vz = (dz / dist) * spec.speed * approach;
      reverse = approach < 0;
    }
    if (mv > 0 && (vx !== 0 || vz !== 0)) {
      e.idleT = 0;
      const [r, mx, mz] = trackStep(e.group.rotation.y, vx * mv, vz * mv, rate * turn, delta, reverse);
      e.group.rotation.y = r;
      pos.x += mx;
      pos.z += mz;
    } else if (mv > 0) {
      e.idleT += delta;
      if (e.idleT > TRACK.idle) {
        const d = wrapAngle(Math.atan2(dx, dz) - e.group.rotation.y);
        const step = rate * turn * 0.6 * delta;
        e.group.rotation.y += Math.max(-step, Math.min(step, d));
      }
    }
    const t = e.turretNode;
    if (t) {
      const d = wrapAngle(wrapAngle(Math.atan2(dx, dz) - e.group.rotation.y) - t.rotation.y);
      const step = rate * TRACK.turret * turn * delta;
      t.rotation.y += Math.max(-step, Math.min(step, d));
    }
  }

  /**
   * 精英「破城槌」（T017-9A）：0 接近（朝坦克开到 engage 米）→ 1 预警（停车、喇叭 + 扬尘、锁定朝坦克现在位置的冲撞线，车头转过去）
   * → 2 冲撞（沿锁定的线全速冲过去，撞上坦克一次，冲过坦克 overshoot 米）→ 3 刹车 → 4 掉头（边往前挪边转，朝路中间拐；在坦克身后、画面外时转得快）
   * → 离得近就直接预警下一次，远就先接近。坦克停着跟它周旋（blockerAhead），冲过头在前方掉头的那几秒露出背面油箱
   */
  private stepRam(e: Enemy, px: number, pz: number, dx: number, dz: number, dist: number, delta: number, mv: number, turnK: number): void {
    const R = ELITE.ram;
    const pos = e.group.position;
    e.modeT += delta;
    const toward = (tx: number, tz: number, rate: number): number => {
      const d = wrapAngle(Math.atan2(tx, tz) - e.group.rotation.y);
      const step = rate * delta;
      e.group.rotation.y += Math.max(-step, Math.min(step, d));
      return Math.abs(d) - Math.min(Math.abs(d), step);
    };
    const drive = (v: number) => {
      pos.x += Math.sin(e.group.rotation.y) * v * delta;
      pos.z += Math.cos(e.group.rotation.y) * v * delta;
    };
    const warn = () => {
      e.mode = 1;
      e.modeT = 0;
      e.dirX = dx / dist;
      e.dirZ = dz / dist;
      this.hooks.ram?.(e, 'warn');
    };
    // 卫队（T050）：开打以后、轮到它才冲（这一次要躲到冲过坦克）
    const turn = () => !e.gate || (this.gateOpen && (this.hooks.turn?.(e, R.warn + (dist + R.overshoot) / R.speed + 0.6) ?? true));
    switch (e.mode) {
      case 0: {
        const err = toward(dx, dz, 1.6 * turnK);
        // 卫队：开打前原地待命，到了冲撞距离没轮到也停着对着坦克
        if (e.gate && (!this.gateOpen || dist <= R.engage)) {
          if (dist <= R.engage && turn()) warn();
          break;
        }
        drive(R.approach * mv * Math.max(0, Math.cos(err)));
        if (dist <= R.engage) warn();
        break;
      }
      case 1:
        toward(e.dirX, e.dirZ, 3 * turnK);
        if (e.modeT >= R.warn) {
          e.mode = 2;
          e.modeT = 0;
          e.vel = 0;
          e.rammed = false;
          e.group.rotation.y = Math.atan2(e.dirX, e.dirZ);
          this.hooks.ram?.(e, 'charge');
        }
        break;
      case 2: {
        // 横冲直撞（汇总第 61 条）：不看减速 / 断履带（mv），撞角前面是地形（房子 / 墙 / 巨石 / 车壳、深水）就一头撞停，不穿墙
        e.vel = Math.min(R.speed, e.vel + R.accel * delta);
        const step = e.vel * delta;
        const nose = R.nose * e.size;
        const nx = pos.x + e.dirX * nose;
        const nz = pos.z + e.dirZ * nose;
        const wet = this.river?.(nx + e.dirX * step, nz + e.dirZ * step);
        if ((wet?.deep && !this.river?.(pos.x, pos.z)?.deep) || this.hooks.ramWall?.(e, nx, nz, step)) {
          e.vel = 0;
          e.mode = 3;
          e.modeT = 0;
          this.hooks.ram?.(e, 'crash');
          break;
        }
        pos.x += e.dirX * step;
        pos.z += e.dirZ * step;
        // 路上的敌人 / 路障 / 残骸：推到一边，每撞上一个只轻微减速
        e.vel *= this.hooks.ramPush?.(e, delta) ?? 1;
        // 撞上坦克：坦克离「车身中心 → 撞角」这一段够近（撞角先碰到就算，不等车身中心冲到跟前）
        const t = Math.max(0, Math.min(nose, (px - pos.x) * e.dirX + (pz - pos.z) * e.dirZ));
        if (!e.rammed && Math.hypot(px - pos.x - e.dirX * t, pz - pos.z - e.dirZ * t) < R.hitW) {
          e.rammed = true;
          e.vel *= R.hitSlow;
          this.hooks.ram?.(e, 'hit');
        }
        if (rng.foe() < delta * 9) this.hooks.ram?.(e, 'plow');
        // 冲过坦克多远（沿冲撞方向）；撞了一路东西慢下来太多也收（不会一直蹭着往前挪）
        const past = (pos.x - px) * e.dirX + (pos.z - pz) * e.dirZ;
        if (past > R.overshoot || e.modeT > 4 || (e.modeT > 1 && e.vel < R.speed * 0.25)) {
          e.mode = 3;
          e.modeT = 0;
          this.hooks.ram?.(e, 'brake');
        }
        break;
      }
      case 3:
        e.vel = Math.max(0, e.vel - R.brake * delta);
        pos.x += e.dirX * e.vel * mv * delta;
        pos.z += e.dirZ * e.vel * mv * delta;
        if (e.vel <= 0) {
          e.mode = 4;
          e.modeT = 0;
          // 掉头往哪边转（转完之前不变）：几乎背对坦克时朝路中间拐（不往田野里越开越远），否则走近的那一边
          const d = wrapAngle(Math.atan2(dx, dz) - e.group.rotation.y);
          const mid = Math.abs(pos.x) > 0.5 ? -Math.sign(pos.x) : rng.foe() < 0.5 ? -1 : 1;
          e.turnDir = Math.abs(d) > 2.6 ? mid * (Math.sign(Math.cos(e.group.rotation.y)) || 1) : Math.sign(d) || 1;
        }
        break;
      default: {
        // 掉头：边往前挪边转（坦克身后、画面外时转得快）
        const behind = pos.z > pz + 4;
        const rate = R.turn * (behind ? R.behindTurn : 1) * turnK;
        const d = wrapAngle(Math.atan2(dx, dz) - e.group.rotation.y);
        e.group.rotation.y += e.turnDir * Math.min(rate * delta, Math.sign(d) === e.turnDir ? Math.abs(d) : rate * delta);
        drive(R.turnSpeed * (behind ? 1.5 : 1) * mv);
        if (Math.abs(wrapAngle(Math.atan2(dx, dz) - e.group.rotation.y)) < 0.15) {
          if (dist > R.engage + 15 || !turn()) {
            e.mode = 0;
            e.modeT = 0;
          } else warn();
        }
      }
    }
    pos.x = Math.max(-24, Math.min(24, pos.x));
    e.group.rotation.y = wrapAngle(e.group.rotation.y);
  }

  /** 瞄准线：先亮线跟踪玩家，最后一小段锁定方向，然后沿锁定方向开火 */
  private stepTelegraph(e: Enemy, dx: number, dz: number, dist: number): void {
    if (e.fireTimer > ROCKET_AIM_TIME) return;
    if (!e.aiming) {
      e.aiming = true;
      this.hooks.aimStart(e);
    }
    if (e.fireTimer > ROCKET_LOCK_TIME) e.lockAngle = Math.atan2(dx, dz);

    // 越接近开火闪得越快
    const urgency = 1 - Math.max(0, e.fireTimer) / ROCKET_AIM_TIME;
    if (e.spec.shot === 'beam') this.hooks.charge(e, urgency);
    const blink = Math.sin(this.time * (10 + urgency * 30)) > -0.3;
    e.laser.visible = e.fireTimer <= ROCKET_LOCK_TIME || blink;
    e.laser.rotation.y = e.lockAngle - e.group.rotation.y;
    e.laser.scale.set(e.spec.fixed ? 1.8 : 1, 1, (dist + 10) / e.size);

    if (e.fireTimer > 0) return;
    e.fireTimer = e.spec.fireInterval + ROCKET_AIM_TIME;
    e.aiming = false;
    e.fireAnim = 0.5;
    e.laser.visible = false;
    this.hooks.fire(e.spec.shot, e.group.position.x, e.group.position.z, Math.sin(e.lockAngle), Math.cos(e.lockAngle), e.spec.bulletSpeed, e.spec.bulletDamage);
  }

  private fireAt(e: Enemy, px: number, pz: number, pvz: number, dist: number): void {
    const spec = e.spec;
    const { x, z } = e.group.position;
    e.fireAnim = 0.35;
    if (spec.burst) {
      e.burstLeft = spec.burst;
      e.burstTimer = 0;
      return;
    }
    if (spec.shot === 'artillery') {
      const flight = 1.6 + dist * 0.006;
      this.hooks.artillery(x, z, px + (rng.foe() - 0.5) * 4, pz + pvz * flight * 0.8 + (rng.foe() - 0.5) * 4, spec.bulletDamage);
      return;
    }
    if (spec.shot === 'zap') {
      if (dist < spec.standoff + 3) this.hooks.zap(e, spec.bulletDamage);
      return;
    }
    // 带提前量瞄准（坦克在往前开），子弹基本都会打在车上
    const a = lead(x, z, px, pz, pvz, spec.bulletSpeed);
    // 首领三连发扇形；步兵 / 摩托有少量散布；运兵车机枪三连
    // 坦克炮弹散布较大：大约一半直接命中，其余落在身边炸开
    const spreads = e.boss ? [-0.14, 0, 0.14] : e.kind === 'apc' ? [-0.04, 0, 0.04] : [spec.shot === 'rifle' ? (rng.foe() - 0.5) * 0.09 : (rng.foe() - 0.5) * 0.24];
    for (const s of spreads) this.hooks.fire(spec.shot, x, z, Math.sin(a + s), Math.cos(a + s), spec.bulletSpeed, spec.bulletDamage);
  }
}
