/**
 * 拦路时的走位参数：米、秒、弧度。位移和普通推进的横移是同一套「目标点 + 跟手」，前后也一样；车头跟着实际行驶方向转。
 * accel / gain 取推进横移的 strafeAccel / STEER_GAIN；coast = 进停车没有前后输入时停到停车点的减速度；exit = 离场时倒车速度的刹车。
 * slip = 车头和行驶方向垂直时的速度比例（拐弯那一下侧滑的上限）；flip = 正开 / 倒车互换的防抖；face = 车头偏向朝前（迎着拦路的）的权重。
 */
export const MOVE = {
  speed: 8.5,
  gain: 3.2,
  accel: 22,
  coast: 10,
  exit: 24,
  turn: Math.PI * 4 / 3,
  slip: 0.4,
  flip: 0.2,
  face: 0.5,
};

const TAU = Math.PI * 2;
const wrap = (a: number) => a - TAU * Math.round(a / TAU);
const EPS = 1e-6;
/** 低于这个速度车头不转：手指按着不动时的细小抖动不晃车头 */
const STILL = 0.8;
/** 到这个速度车头转向才到全速，慢慢挪时车头也慢慢转 */
const TURN_FULL = 3.5;

export interface MoveIntent {
  active: boolean;
  x: number;
  forward: number;
}

/** 拦路后的走位：速度追目标点，车头追行驶方向；往车头背面走就倒车，不原地掉头。世界坐标，前方 −Z，车头角正值朝左。 */
export class TankMovement {
  yaw = 0;
  turnRate = 0;
  vx = 0;
  vz = 0;
  /** 现在是倒着开（车头背对行驶方向） */
  reverse = false;
  /** 刚进停车、还没有前后输入：前进速度按 coast 匀减速停到停车点 */
  coasting = false;

  get speed(): number { return Math.hypot(this.vx, this.vz); }

  get state(): 'idle' | 'coasting' | 'moving' | 'reversing' {
    if (this.speed < EPS) return 'idle';
    return this.coasting ? 'coasting' : this.reverse ? 'reversing' : 'moving';
  }

  reset(): void {
    this.yaw = this.turnRate = this.vx = this.vz = 0;
    this.reverse = this.coasting = false;
  }

  /** forward = 推进时的前进速度（米/秒，往 −Z 为正） */
  enter(vx: number, forward: number, yaw: number): void {
    this.reset();
    this.yaw = yaw;
    this.vx = vx;
    this.vz = -forward;
    this.coasting = forward > EPS;
  }

  /** dx / dz = 目标点减当前位置；速度朝目标点走，大小按离得多远、车头偏了多少封顶，变化量不超过 accel。 */
  steer(dx: number, dz: number, maxSpeed: number, accel: number, dt: number): void {
    if (dt <= 0) return;
    const moving = this.speed > STILL;
    const cap = maxSpeed * this.grip(moving ? this.vx : dx, moving ? this.vz : dz);
    let wx = dx * MOVE.gain;
    let wz = this.coasting ? Math.sign(dz) * Math.sqrt(2 * MOVE.coast * Math.abs(dz)) : dz * MOVE.gain;
    const want = Math.hypot(wx, wz);
    if (want > cap) { wx *= cap / want; wz *= cap / want; }
    let ax = wx - this.vx, az = wz - this.vz;
    const change = Math.hypot(ax, az), most = accel * dt;
    if (change > most) { ax *= most / change; az *= most / change; }
    this.vx += ax;
    this.vz += az;
    if (this.coasting && Math.abs(dz) < 0.02 && Math.abs(this.vz) < 0.1) this.coasting = false;
  }

  /** 按这一帧实际走出的速度转车头（边界挡掉的那一轴已经清零）：挑转得少、又更朝前的一头，背对着就倒车。 */
  face(dt: number): void {
    this.turnRate = 0;
    const sp = this.speed;
    if (sp < STILL || dt <= 0) return;
    const ahead = Math.atan2(-this.vx, -this.vz), back = wrap(ahead + Math.PI);
    const cost = (c: number, rev: boolean) => Math.abs(wrap(c - this.yaw)) + MOVE.face * Math.abs(wrap(c)) + (rev !== this.reverse ? MOVE.flip : 0);
    this.reverse = cost(back, true) < cost(ahead, false);
    const most = MOVE.turn * dt * Math.min(1, sp / TURN_FULL);
    const step = Math.max(-most, Math.min(most, wrap((this.reverse ? back : ahead) - this.yaw)));
    this.yaw = wrap(this.yaw + step);
    this.turnRate = step / dt;
  }

  /** 车身轴线和行驶方向的夹角越大越慢：顺着走全速，横着走 slip */
  private grip(x: number, z: number): number {
    if (Math.hypot(x, z) < EPS) return 1;
    const a = Math.abs(wrap(Math.atan2(-x, -z) - this.yaw));
    return Math.max(MOVE.slip, Math.cos(Math.min(a, Math.PI - a)));
  }
}
