import * as THREE from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { SCN_SHADOW_HIGH } from '../world/sceneryDetail';

export type Quality = 'high' | 'medium' | 'low';
export type QualitySetting = Quality | 'auto';

/** 网页版跑在手机 / 平板上（同 styles.css 的电脑判定取反，拿不准的按手机） */
const PHONE = !__WX__ && !(typeof matchMedia === 'function' && matchMedia('(hover: hover) and (pointer: fine) and (min-width: 720px)').matches);

/**
 * 每档画质（T082，T245 中 / 低档压低）：3D 像素比上限、泛光分辨率（占 3D 画面边长的比例，0 = 关）、阴影贴图、合成多重采样、帧率上限（0 = 跟屏幕）、
 * 阴影覆盖半宽 reach（米，越小投影的物体越少、同样的贴图越清楚）。
 * 网页手机的高档只退两处：阴影 4096 → 2048、多重采样 4 → 2（推算省几十 MB 显存），其余同电脑。粒子减半另外看 quality === 'low'
 */
type Tier = { dpr: number; bloom: number; shadow: number; msaa: number; fps: number; reach: number };
const MEDIUM: Tier = { dpr: 1.25, bloom: 0.2, shadow: 1024, msaa: 2, fps: 60, reach: 46 };
const LOW: Tier = { dpr: 1, bloom: 0, shadow: 1024, msaa: 2, fps: 30, reach: 26 };
const TIERS: Record<Quality, Tier> = {
  high: __WX__ ? { dpr: 2, bloom: 0.5, shadow: 2048, msaa: 4, fps: 60, reach: 58 }
    : PHONE ? { dpr: 2, bloom: 0.5, shadow: Math.min(2048, SCN_SHADOW_HIGH), msaa: 2, fps: 0, reach: 58 }
    : { dpr: 2, bloom: 0.5, shadow: SCN_SHADOW_HIGH, msaa: 4, fps: 0, reach: 58 },
  medium: MEDIUM,
  low: LOW,
};

/**
 * 每档的特效池上限（T245，只管画面，不碰判定）：烟 / 光粒子、地面贴花、飞散碎块（满了顶掉最老的）、弹坑圆盘网格的圈数 × 段数。
 * 高档同改前
 */
export const FX_TIERS: Record<Quality, { smoke: number; glow: number; decals: number; debris: number; crater: [number, number] }> = {
  high: { smoke: 2400, glow: 1600, decals: 1100, debris: Infinity, crater: [16, 56] },
  medium: { smoke: 1500, glow: 1000, decals: 700, debris: 160, crater: [12, 40] },
  low: { smoke: 900, glow: 600, decals: 420, debris: 90, crater: [10, 32] },
};

function hdrSamples(renderer: THREE.WebGLRenderer): number[] | null {
  if (!__WX__) return [4, 2, 1];
  if (!renderer.extensions.has('EXT_color_buffer_float')) return null;
  try {
    const gl = renderer.getContext() as WebGL2RenderingContext;
    const supported = gl.getInternalformatParameter(gl.RENDERBUFFER, gl.RGBA16F, gl.SAMPLES) as ArrayLike<number>;
    const samples = Array.from(supported).filter((n) => Number.isFinite(n) && n > 0);
    return samples.length ? samples : null;
  } catch {
    return null;
  }
}

const ORDER: Quality[] = ['high', 'medium', 'low'];
/** 平时的泛光强度 */
const BLOOM = 0.55;
/** 自动档降档线（T084）：最近 3 秒里七成的帧（p30）都比这个慢（连续守不住 50 帧）就降一档；卡一两下、卡一秒都不算 */
const SLOW = 1 / 50;
/** 看最近几秒的帧 */
const SPAN = 3;
/**
 * 自动档升回（T245）：只从中档升回高档（低档锁 30 帧，看不出余量）。降到中档 30 秒以后，连续 20 秒里每次检查 p90 都快过 FAST 才升；
 * 升回去 30 秒内又降下来，就当这台机器扛不住，这次设置里不再升；最多升 times 次，免得来回切
 */
const UP = { after: 30, hold: 20, fail: 30, times: 2 };
const FAST = 1 / 56;

/**
 * 渲染出口：高 / 中档走 HDR 合成 + 泛光（炮口火、爆炸、激光、能量件会发光），微信能力不够时回退 LDR 并关泛光。
 * 自动档从高档起步（T084），按实测帧时间逐级降档；中档稳够帧才试着升回高档一次（T245，见 UP）。
 * 画布版界面（uiDpr > 0）：画布像素比不低于 uiDpr，3D 画面低于它时走合成放大，界面字照旧清楚。
 */
export class Post {
  quality: Quality;
  private readonly composer: EffectComposer;
  private readonly bloom: UnrealBloomPass;
  private readonly hdr: boolean;
  private readonly samples: number[];
  /** 最近 SPAN 秒的帧时间（先进先出） */
  private readonly frames: number[] = [];
  /** frames 的总和 */
  private span = 0;
  private checkT = 0;
  private settle = 3;
  private auto = true;
  /** 这一档待了多久、连续够快多久（秒）；升回高档后过了多久（−1 = 没升过，30 秒内又降 = 失败）；这次设置里还能升几次 */
  private stay = 0;
  private fastFor = 0;
  private upAt = -1;
  private upsLeft: number = UP.times;
  private setting: QualitySetting | null = null;
  /** 泛光脉冲（核弹白闪）：拉到 pulseTo，pulseDur 秒内回落到平时的 BLOOM */
  private pulseTo = BLOOM;
  private pulseAt = 0;
  private pulseDur = 0;

  constructor(
    private readonly renderer: THREE.WebGLRenderer,
    private readonly scene: THREE.Scene,
    private readonly camera: THREE.PerspectiveCamera,
    private readonly sun: THREE.DirectionalLight,
    setting: QualitySetting,
    private readonly uiDpr = 0,
    private readonly onQuality: (quality: Quality) => void = () => {},
  ) {
    const supported = hdrSamples(renderer);
    this.hdr = supported !== null;
    this.samples = supported ?? [];
    const target = new THREE.WebGLRenderTarget(1, 1, {
      type: this.hdr ? THREE.HalfFloatType : THREE.UnsignedByteType,
      samples: this.msaa(4),
    });
    this.composer = new EffectComposer(renderer, target);
    this.composer.addPass(new RenderPass(scene, camera));
    this.bloom = new UnrealBloomPass(new THREE.Vector2(256, 256), BLOOM, 0.45, 0.9);
    this.composer.addPass(this.bloom);
    this.composer.addPass(new OutputPass());
    this.quality = 'high';
    // 合成会多次调用 render，手动清零统计才能看到整帧的 draw call
    renderer.info.autoReset = false;
    this.set(setting);
  }

  /** 改画质设置；设置没变（改别的设置项也会走到这里）就不动，自动档降下来的档位不会被升回去 */
  set(setting: QualitySetting): void {
    if (setting === this.setting) return;
    this.setting = setting;
    this.auto = setting === 'auto';
    this.upsLeft = UP.times;
    this.upAt = -1;
    this.reset(3);
    this.apply(this.auto ? 'high' : (setting as Quality));
  }

  /** 画布像素比上限：3D 档位的像素比，画布版界面不低于 uiDpr */
  get maxDpr(): number {
    return Math.max(TIERS[this.quality].dpr, this.uiDpr);
  }

  /** 帧率上限（0 = 跟屏幕刷新） */
  get fps(): number {
    return TIERS[this.quality].fps;
  }

  private msaa(requested: number): number {
    let samples = 0;
    for (const n of this.samples) if (n <= requested && n > samples) samples = n;
    return this.hdr ? samples : 0;
  }

  /** 3D 画面实际像素比 */
  private get dpr3d(): number {
    return Math.min(window.devicePixelRatio || 1, TIERS[this.quality].dpr);
  }

  /** 画布尺寸变化后调用 */
  resize(): void {
    const size = this.renderer.getSize(new THREE.Vector2());
    const dpr = this.dpr3d;
    this.composer.setPixelRatio(dpr);
    this.composer.setSize(size.x, size.y);
    // 泛光分辨率按档位：高档半分辨率、中档 1/4（UnrealBloomPass 内部还会再减半）
    const b = TIERS[this.quality].bloom;
    if (b > 0) this.bloom.setSize(size.x * dpr * b * 2, size.y * dpr * b * 2);
  }

  /** 泛光脉冲：拉到 strength，seconds 秒内回落（只在有泛光的中 / 高画质看得到） */
  pulse(strength: number, seconds: number): void {
    this.pulseTo = strength;
    this.pulseAt = performance.now();
    this.pulseDur = seconds * 1000;
  }

  /** 走合成（泛光 / 放大）还是直接画到屏幕；画布版低档 3D 低于画布像素比，也走合成（只放大、不泛光） */
  private get composed(): boolean {
    return (this.hdr && TIERS[this.quality].bloom > 0) || this.dpr3d < this.renderer.getPixelRatio() - 0.01;
  }

  render(): void {
    this.renderer.info.reset();
    if (this.pulseDur > 0) {
      const k = Math.max(0, 1 - (performance.now() - this.pulseAt) / this.pulseDur);
      this.bloom.strength = BLOOM + (this.pulseTo - BLOOM) * k;
      if (k <= 0) this.pulseDur = 0;
    }
    if (this.composed) this.composer.render();
    else this.renderer.render(this.scene, this.camera);
  }

  /** 启动预热（T108）：照实际出图的路子（合成画进离屏目标 / 直接画到屏幕）编好 obj 里的材质，灯光按战场场景算 */
  compile(obj: THREE.Object3D = this.scene): void {
    const r = this.renderer;
    const target = r.getRenderTarget();
    r.setRenderTarget(this.composed ? this.composer.readBuffer : null);
    r.compile(obj, this.camera, this.scene);
    r.setRenderTarget(target);
  }

  /** 自动档：攒满最近 3 秒的帧，每 0.5 秒看一次 p30，偏慢就降一档；中档稳够帧按 UP 升回高档 */
  sample(realDelta: number): void {
    if (!this.auto || this.quality === 'low') return;
    this.stay += realDelta;
    if (this.upAt >= 0) this.upAt += realDelta;
    if (this.settle > 0) {
      this.settle -= realDelta;
      return;
    }
    this.frames.push(realDelta);
    this.span += realDelta;
    while (this.span - this.frames[0] >= SPAN) this.span -= this.frames.shift()!;
    this.checkT += realDelta;
    if (this.span < SPAN || this.checkT < 0.5) return;
    const step = this.checkT;
    this.checkT = 0;
    const sorted = [...this.frames].sort((a, b) => a - b);
    if (sorted[Math.floor(sorted.length * 0.3)] > SLOW) {
      if (this.upAt >= 0 && this.upAt < UP.fail) this.upsLeft = 0;
      this.upAt = -1;
      this.apply(ORDER[ORDER.indexOf(this.quality) + 1]);
      this.reset(2);
      return;
    }
    if (this.upsLeft <= 0 || this.quality !== 'medium') return;
    this.fastFor = sorted[Math.floor(sorted.length * 0.9)] <= FAST ? this.fastFor + step : 0;
    if (this.stay < UP.after || this.fastFor < UP.hold) return;
    this.upAt = 0;
    this.upsLeft--;
    this.apply('high');
    this.reset(3);
  }

  private reset(settle: number): void {
    this.frames.length = 0;
    this.span = 0;
    this.checkT = 0;
    this.settle = settle;
    this.stay = 0;
    this.fastFor = 0;
  }

  private apply(q: Quality): void {
    this.quality = q;
    const t = TIERS[q];
    if (this.sun.shadow.mapSize.x !== t.shadow) {
      this.sun.shadow.mapSize.set(t.shadow, t.shadow);
      this.sun.shadow.map?.dispose();
      this.sun.shadow.map = null;
    }
    const cam = this.sun.shadow.camera;
    if (cam.right !== t.reach) {
      cam.left = cam.bottom = -t.reach;
      cam.right = cam.top = t.reach;
      cam.updateProjectionMatrix();
    }
    this.bloom.enabled = this.hdr && t.bloom > 0;
    const samples = this.msaa(t.msaa);
    for (const rt of [this.composer.renderTarget1, this.composer.renderTarget2]) {
      if (rt.samples === samples) continue;
      rt.samples = samples;
      rt.dispose();
    }
    this.resize();
    this.onQuality(q);
  }

  dispose(): void {
    this.composer.dispose();
  }
}
