import { UI_SKIN } from './index';
import { line } from './drawing';
import type { InkContext, Surface } from './types';

let tile: HTMLCanvasElement | null = null;
const patterns = new WeakMap<InkContext, CanvasPattern>();

function canvas(w: number, h: number): HTMLCanvasElement {
  const wx = (globalThis as { wx?: { createCanvas?: () => HTMLCanvasElement } }).wx;
  const el = wx?.createCanvas ? wx.createCanvas() : document.createElement('canvas');
  el.width = w; el.height = h;
  return el;
}

export function grain(): HTMLCanvasElement {
  if (tile) return tile;
  tile = canvas(256, 256);
  UI_SKIN?.texture(tile.getContext('2d')!);
  return tile;
}

function texture(c: InkContext, w: number, h: number, alpha = 1): void {
  let pattern = patterns.get(c);
  if (!pattern) {
    pattern = c.createPattern(grain(), 'repeat') ?? undefined;
    if (pattern) patterns.set(c, pattern);
  }
  if (!pattern) return;
  c.save(); c.globalAlpha *= alpha; c.fillStyle = pattern; c.fillRect(0, 0, w, h); c.restore();
}

function shape(c: InkContext, w: number, h: number, inset = 0): void {
  const k = Math.min(UI_SKIN?.radius ?? 2, w / 4, h / 4);
  const x = inset, y = inset, r = w - inset, b = h - inset;
  c.beginPath();
  if (UI_SKIN?.shape === 'cut') {
    c.moveTo(x + k, y); c.lineTo(r - k, y); c.lineTo(r, y + k);
    c.lineTo(r, b - k); c.lineTo(r - k, b); c.lineTo(x + k, b);
    c.lineTo(x, b - k); c.lineTo(x, y + k); c.closePath();
  } else {
    c.moveTo(x + k, y); c.lineTo(r - k, y); c.arcTo(r, y, r, y + k, k);
    c.lineTo(r, b - k); c.arcTo(r, b, r - k, b, k);
    c.lineTo(x + k, b); c.arcTo(x, b, x, b - k, k);
    c.lineTo(x, y + k); c.arcTo(x, y, x + k, y, k); c.closePath();
  }
}

/** 只画原框内的材质和结构，点击区与布局都不变。 */
export function skinSurface(c: InkContext, x: number, y: number, w: number, h: number, role: Surface = 'panel', active = false): boolean {
  if (!UI_SKIN) return false;
  const p = UI_SKIN.colors, primary = role === 'primary';
  c.save(); c.translate(x, y); shape(c, w, h); c.clip();
  const g = c.createLinearGradient(0, 0, w * 0.65, h);
  g.addColorStop(0, primary ? p.mainHi : p.high);
  g.addColorStop(1, primary ? p.mainLow : p.low);
  c.fillStyle = g; c.fillRect(0, 0, w, h);
  texture(c, w, h);
  UI_SKIN.detail(c, w, h, role);
  shape(c, w, h, 0.5);
  c.strokeStyle = active ? p.accent : p.line; c.lineWidth = active ? 2 : 1; c.stroke();
  line(c, 4, 1.5, w - 4, 1.5, 'rgba(255,255,235,.22)');
  line(c, 1.5, 4, 1.5, h - 4, 'rgba(255,255,235,.12)');
  line(c, 3, h - 1.5, w - 3, h - 1.5, UI_SKIN.light ? 'rgba(35,48,46,.3)' : 'rgba(0,0,0,.6)', 2);
  c.restore();
  return true;
}

export function skinBackdrop(c: InkContext, w: number, h: number): boolean {
  if (!UI_SKIN) return false;
  const p = UI_SKIN.colors;
  c.save();
  const g = c.createLinearGradient(0, 0, w, h);
  g.addColorStop(0, p.backHi); g.addColorStop(0.55, p.back); g.addColorStop(1, p.back);
  c.globalAlpha = 0.96;
  c.fillStyle = g; c.fillRect(0, 0, w, h);
  texture(c, w, h, 0.7);
  UI_SKIN.scene(c, w, h);
  c.restore();
  return true;
}

export function skinTitle(c: InkContext, w: number, compactHeight?: number): boolean {
  if (!UI_SKIN) return false;
  const p = UI_SKIN.colors;
  if (compactHeight) {
    skinSurface(c, 0, 0, w, compactHeight, 'title');
    c.save();
    c.textAlign = 'center'; c.textBaseline = 'middle';
    c.font = `900 ${compactHeight < 54 ? 32 : 36}px sans-serif`; c.fillStyle = p.ink;
    c.shadowColor = p.shadow; c.shadowOffsetY = UI_SKIN.light ? 1 : 3;
    c.fillText('钢铁破坏者', w / 2, compactHeight / 2);
    c.restore();
    return true;
  }
  skinSurface(c, 0, 0, w, 82, 'title');
  c.save();
  c.textAlign = 'center'; c.textBaseline = 'middle';
  c.font = '700 11px sans-serif'; c.fillStyle = p.accent;
  c.fillText(UI_SKIN.name, w / 2, 10);
  line(c, w / 2 - 70, 10, w / 2 - 38, 10, p.line);
  line(c, w / 2 + 38, 10, w / 2 + 70, 10, p.line);
  c.font = '900 40px sans-serif'; c.fillStyle = p.ink;
  c.shadowColor = p.shadow; c.shadowOffsetY = UI_SKIN.light ? 1 : 3;
  const word = '钢铁破坏者', space = 8;
  const total = c.measureText(word).width + space * (word.length - 1);
  let x = (w - total) / 2;
  c.textAlign = 'left';
  for (const ch of word) { c.fillText(ch, x, 40); x += c.measureText(ch).width + space; }
  c.shadowOffsetY = 0; c.font = '400 13px sans-serif'; c.textAlign = 'center';
  c.fillStyle = p.soft; c.fillText('驾驶重坦，碾穿铁狼军团', w / 2, 72);
  c.restore();
  return true;
}

export function meterTicks(c: InkContext, x: number, y: number, w: number, h: number): void {
  if (!UI_SKIN) return;
  c.save();
  for (let i = 1; i < UI_SKIN.ticks; i++) {
    const xx = x + w * i / UI_SKIN.ticks;
    line(c, xx, y + h - (i % 5 === 0 ? h : h * 0.35), xx, y + h, 'rgba(12,18,16,.65)');
  }
  line(c, x + 2, y + 2, x + w - 2, y + 2, 'rgba(255,247,215,.32)');
  c.restore();
}

/** 网页只接颜色与贴图，不参与设备判断。 */
export function installDomSkin(): void {
  if (!UI_SKIN || (globalThis as { wx?: unknown }).wx) return;
  const root = document.documentElement;
  root.dataset.uiSkin = String(UI_SKIN.id);
  root.style.setProperty('--skin-radius', `${UI_SKIN.radius}px`);
  for (const [key, val] of Object.entries(UI_SKIN.colors)) root.style.setProperty(`--skin-${key}`, val);
  root.style.setProperty('--skin-grain', `url("${grain().toDataURL()}")`);
  const kicker = document.querySelector('#title .kicker');
  if (kicker) kicker.textContent = UI_SKIN.name;
  let timer = 0;
  const resize = () => {
    const bg = canvas(window.innerWidth, window.innerHeight);
    skinBackdrop(bg.getContext('2d')!, bg.width, bg.height);
    root.style.setProperty('--skin-backdrop', `url("${bg.toDataURL()}")`);
  };
  resize();
  window.addEventListener('resize', () => { clearTimeout(timer); timer = window.setTimeout(resize, 120); });
}
