import * as THREE from 'three';
import type { Enemy } from '../entities/Enemy';
import type { BulletKind } from '../systems/Bullets';
import { angleTo, type CombatContext } from './behaviors';
import { Core, RECOIL_KICK } from './cores';
import { CORE_STATS } from './defs';
import { rng } from '../game/rng';
import { PelletCrit } from './attacks';
import { RateStack } from './superMods';

const DEG = Math.PI / 180;
/** 管口发红（T088）：暗红 → 暗橙，不到白 */
const HEAT_RED = new THREE.Color(0x5a0c02);
const HEAT_ORANGE = new THREE.Color(0xc8401a);
const rand = (a: number, b: number) => a + Math.random() * (b - a);
const wrap = (a: number) => {
  while (a > Math.PI) a -= Math.PI * 2;
  while (a < -Math.PI) a += Math.PI * 2;
  return a;
};

/**
 * 火神（D1-032 数值；T089 起按 D1-034 改成一条弹药池 + 按住连射）：
 * speed 弹速；idle 停火超过这么久下次重新起转、加速清零；spin / heavySpin 起转（秒 / 从几成爬到满）；
 * accel 连射加速（连射满 from 秒起、to 秒到 ×max，只给轻弹）；pool 轻弹池 = 原来总发数的几成；tap 轻弹点一下打多久；heavyTap 重弹点一下打多久（T124）；
 * lead 引着打（起转那 0.2 秒弹着点从目标距离 55% 往前走）；turn 炮塔转速；gunTurn 其余几门在炮架上的转速；
 * block 分火的炮被挡多久换人、被挡的那个多久不再挑；retarget 目标倒了先在左右 30° 里换；assist 手动点按吸附；bossRange 首领 / 拦路精英按主炮射程；
 * autoStop 自动开火射程里没敌人满这么久才停；pierceK 穿透每层伤害倍率；dryAt 打空以后池子回到几成才算回满速（白汽只喷一次）；
 * gnaw 打穿计时（0.15 秒内挨过一包算咬住、2 秒没挨打清零）
 */
export const VULCAN = {
  /** T086：160 → 360（判定包和曳光同一个弹速，画面和掉血对得上） */
  speed: 360,
  idle: 0.6,
  spin: { t: 0.3, from: 0.4 },
  heavySpin: { t: 0.15, from: 0.6 },
  accel: { from: 1, to: 3, max: 1.3 },
  pool: 2 / 3,
  tap: 0.6,
  /** T124：原来点一下排满一梭（千钧 64 发 = 半池），改成打 0.3 秒（千钧约 20 发） */
  heavyTap: 0.3,
  lead: { t: 0.2, from: 0.55 },
  turn: 8,
  gunTurn: 12,
  /**
   * 画出来的炮塔 / 炮管朝向（T195，制作人「加特林瞄准太乱了，各种摆头感觉在乱打」）：按临界阻尼弹簧跟着瞄准走（ω 弧度/秒、封顶 max 弧度/秒、最多落后 lag 弧度），
   * 曳光、枪口焰跟着画出来的炮管走；判定包、选目标、转速照旧，打到谁、打多少不变
   */
  look: { w: 9, max: 4, lag: 0.45, gunW: 8, gunMax: 3 },
  block: { t: 0.5, ban: 1 },
  retarget: Math.PI / 6,
  assist: 0.25,
  bossRange: 100,
  autoStop: 0.3,
  pierceK: 0.7,
  dryAt: 0.15,
  gnaw: { bite: 0.15, reset: 2 },
  /** 停转惯性（秒）、转管最高角速度（画面，弧度/秒）、虚影门槛 */
  spinDown: 0.8,
  spinMax: 42,
  blurAt: 15,
  /** 管口发红（T088 放慢压暗）：累计连射 3 秒起暗红、8 秒到暗橙封顶（不到白），停火每秒退 1 秒（封顶后 5 秒看不出红） */
  heat: { red: 3, hot: 8, cool: 1 },
  /** 弹带滚动（格 / 秒，一格一发）：开火时最快 fire，补弹时最快 feed */
  belt: { fire: 18, feed: 6 },
  /**
   * 第 8.7 节性能预算（按画质档）：曳光 [每几发画 1 根, 每门每秒上限, 全场在飞上限, 粗细倍率, 长短倍率]；弹壳 [每几发 1 个, 每秒上限, 场上上限]；弹沟留几秒。
   * T085 曳光加密：原来 [2, 45, 100] / [3, 35, 80] / [5, 25, 60]；低档根数少、每颗大一圈（密但省）。
   * T086 流星细了：中 / 低档像素比低，粗细多给一点（1.1 / 1.3，T085 1.05 / 1.2）免得细尾闪；低档长短 1.1、外形换省面的。
   * T088 改成稀疏光点串：轻弹每 5 发 1 颗（低档 6），重弹线 / 千钧每 3 发（heavyEvery）；每门每秒上限 30 / 24 / 18，
   * 弹速 360 时相邻两颗至少隔 12 / 15 / 20 米，比 6.6 米的尾巴长将近一倍，连打第 3 条也不连成线
   */
  trace: { high: [5, 30, 120, 1, 1], medium: [5, 24, 90, 1.1, 1], low: [6, 18, 60, 1.3, 1.1] },
  heavyEvery: 3,
  /** 弹壳 [每几发 1 个, 每秒上限, 场上上限, 躺几秒]（T088：成股、多留） */
  casing: { high: [2, 60, 300, 6], medium: [3, 40, 200, 4], low: [5, 20, 80, 2.5] },
  groove: { high: 18, medium: 12, low: 8 },
  /**
   * 枪口焰（T088）：每发一次爆闪（每帧亮不亮按这一帧打了几发算，轻弹 1 − e^(−发数 × lit)、重弹按发数累计一发亮一次）+
   * 二次火球（每门每几发一团：高 / 中 / 低 5 / 5 / 8）；补光每秒 ≤ 15 次照旧
   */
  flash: { lit: 0.6, ball: { high: 5, medium: 5, low: 8 } },
  /** 抖动（T088）：炮组随机偏移（米）/ 转角（弧度）、炮塔后坐（米，重弹 ×2）、车头抬（弧度，约 0.3°，重弹 ×2） */
  shake: { pos: 0.015, rot: 0.005, back: 0.04, lift: 0.0052 },
} as const;

/** 一种形态（基础 / 弹幕线 / 四联 / 重弹线 / 千钧）的参数；key = 0..4（声音、弹壳用） */
export interface VulcanForm {
  key: 0 | 1 | 2 | 3 | 4;
  guns: number;
  rate: number;
  /** 原来一条弹链（轻弹）/ 一梭（重弹）几发：池子、补弹从它推 */
  per: number;
  dmg: number;
  belts: number | null;
  reload: number | null;
  range: number;
  pierce: number;
  /** 打穿：啃多久、啃的时候 / 打穿后的倍率 */
  need: number;
  during: number;
  after: number;
  /** 压制秒数（0 = 不压制） */
  supp: number;
  /** 越打越准：散布从表上的几倍收到几倍；null = 固定 */
  tight: [number, number] | null;
  /** 千钧小爆半径（米） */
  splash: number;
  /** 轻弹（基础 / 弹幕线 / 四联）：一道连续的弹流、连射加速；否则重弹一梭一梭打 */
  light: boolean;
  /** 无尽弹仓每多一条射速 +10%（弹幕线 / 四联，沿用原弹匣加成） */
  ammoRate: boolean;
  /** 每门炮每秒几包 */
  packets: number;
  /** 分火扇面半角（弧度）：其余几门在主弹流左右这么宽里各挑一个 */
  split: number;
  trace: BulletKind;
}

interface Gun {
  crits: PelletCrit;
  yaw: number;
  target: Enemy | null;
  owed: number;
  packT: number;
  traceAcc: number;
  traceTok: number;
  caseAcc: number;
  caseTok: number;
  /** 第几个弹壳（每 3 个里 1 个是弹链节）、爆闪累计（重弹）、二次火球累计 */
  caseN: number;
  flashAcc: number;
  ballAcc: number;
  /** 最近一包打中的距离（离坦克）和时间：曳光飞到这里就灭，不穿墙 */
  hitD: number;
  hitT: number;
  /** 分火：咬上这个目标的时刻、最近一包打中它 / 打中别的东西的时刻、被挡住换掉的那个和到什么时候能再挑、下次重挑的倒计时 */
  since: number;
  onT: number;
  otherT: number;
  ban: Enemy | null;
  banUntil: number;
  findT: number;
  /** 画出来的炮管偏角 / 角速度（T195） */
  vis: number;
  visV: number;
}

/**
 * 火神流：火神炮塔（T089，D1-034）。一条弹药池，按住一直打、松手停，打着也补：
 * 轻弹（基础 / 弹幕线 / 四联）池子空了按补弹速度接着打，连射越久越快，点一下打 0.6 秒；
 * 重弹（重弹线 / 千钧）T126 起不分梭：按住一口气打到池子见底，松手立刻停，点一下打 0.3 秒（T124）；打空以后整池补满才能再开。
 * 伤害按「包」算（每门每秒 20 包，四联 10 包），曳光另按射速画；打重甲先啃后穿（Game.vulcanHit），分火 / 压制 / 小爆 / 穿透在这里和 Game 里分工
 */
export class VulcanCore extends Core {
  /** 这一帧在出弹 */
  firing = false;
  /** 现在的每秒发数（声音、诊断）；起转爬完以后的每秒发数（声音按它排起转那一段） */
  rateNow = 0;
  fullRate = 0;
  /** 这次 fire() 是自动开火开的（Game 调用前设） */
  auto = false;
  /** 自动开火在打（代替按住的手指，Game.stepVulcanAuto 写） */
  autoHold = false;
  /** 池子打空了：轻弹 = 正按补弹速度打；重弹 = 停火补弹，补满才能再开（T126） */
  dry = false;
  /** 这次开火从起转算的时间（重弹 = 这一梭打了多久）、连射累计（加速）、最后一次出弹的时刻 */
  private sessT = 0;
  private contT = 0;
  private lastT = -99;
  private ramp = false;
  /** 轻弹点射还剩多久 */
  private burstT = 0;
  /** 重弹：点射还要打多久（只在出弹时往下走，打空补弹时点的排着） */
  private tapT = 0;
  private manual = false;
  /** 主弹流的世界朝向（炮塔约定角）/ 想转到的朝向 / 锁住的目标 */
  private aim = 0;
  private want = 0;
  private lock: Enemy | null = null;
  private lockLost = false;
  private findT = 0;
  /** 按方向打（鼠标 / 右摇杆按住）：方向只听 steer */
  private dirMode = false;
  private steerA = 0;
  /** 画出来的炮塔世界角 / 角速度（T195） */
  private visYaw = 0;
  private visV = 0;
  private visOn = false;
  private readonly visGuns: number[] = [0, 0, 0, 0];
  private readonly mv = new THREE.Vector3();
  private readonly guns: Gun[] = Array.from({ length: 4 }, () => ({ crits: new PelletCrit(), yaw: 0, target: null, owed: 0, packT: 0, traceAcc: 0, traceTok: 0, caseAcc: 0, caseTok: 0, caseN: 0, flashAcc: 0, ballAcc: 0, hitD: 0, hitT: -9, since: 0, onT: -9, otherT: -9, ban: null, banUntil: 0, findT: 0, vis: 0, visV: 0 }));
  private readonly traceLive: number[] = [];
  /** 转管角速度、连射累计（管口发红）、白汽剩余、啃甲（声音颤音）剩余 */
  private spin = 0;
  private fireT = 0;
  readonly rateStack = new RateStack();
  private steamT = 0;
  private gnawT = 0;
  private flashT = 0;
  private smokeT = 0;
  /** 炮塔后坐：想顶到多少 / 现在顶了多少（米） */
  private backT = 0;
  private back = 0;
  /** 弹带滚动速度（格 / 秒，平滑过） */
  private beltV = 0;
  private now = 0;
  private formKey = -1;
  private formCache: VulcanForm | null = null;
  private readonly heatC = new THREE.Color();
  private readonly m = new THREE.Vector3();

  /** 这一刻的形态参数（等级 / 分支 / 终极变了才重算） */
  get form(): VulcanForm {
    const key = this.level * 10 + (this.branch === 'A' ? 1 : this.branch === 'B' ? 2 : 0) + (this.ultimate ? 5 : 0);
    if (key !== this.formKey || !this.formCache) {
      this.formKey = key;
      this.formCache = this.makeForm();
    }
    return this.formCache;
  }

  private makeForm(): VulcanForm {
    const st = CORE_STATS.vulcan;
    const L = this.level;
    const base = { rate: st.rate(L), per: st.per(L), dmg: st.damage(L), range: st.range(L) };
    const light = { pierce: 0, need: 1, during: 0.25, after: 0.85, tight: null, splash: 0, light: true, belts: null, reload: null, packets: 20, split: 12 * DEG };
    const heavy = { need: 0.5, during: 0.5, light: false, ammoRate: false, supp: 0, packets: 20, split: 0, guns: 1 };
    if (this.ultimate && this.branch === 'A') return { ...light, key: 2, guns: 4, rate: 320, per: 640, dmg: 3.6, belts: 3, reload: 4, range: base.range, supp: 2, ammoRate: true, packets: 10, split: 20 * DEG, trace: 'vt' };
    // 千钧单发 8 → 10.4（T128，制作人「输出增加 30%」）：小爆、穿透、啃甲都按单发算，跟着涨；射速 / 池子 / 补弹不动
    if (this.ultimate && this.branch === 'B') return { ...heavy, key: 4, rate: 156, per: 64, dmg: 10.4, belts: 4, reload: 1, range: base.range + 16, pierce: 2, after: 1, tight: [1, 0.5], splash: 1.6, trace: 'vtM' };
    if (this.branch === 'A') return { ...light, key: 1, guns: 2, rate: base.rate * 1.7, per: base.per * 2, dmg: base.dmg * 0.55, range: base.range, supp: 1.5, ammoRate: true, trace: 'vt' };
    if (this.branch === 'B') return { ...heavy, key: 3, rate: base.rate * 0.6, per: Math.round(base.per * 0.3), dmg: base.dmg * 3.7, range: base.range + 12, pierce: 1, after: 0.9, tight: [1.2, 0.6], splash: 0, belts: null, reload: null, trace: 'vtH' };
    return { ...light, key: 0, guns: 1, rate: base.rate, per: base.per, dmg: base.dmg, range: base.range, supp: 0, ammoRate: false, trace: 'vt' };
  }

  /** 普通敌人的射程（米） */
  get reach(): number {
    return this.form.range;
  }

  /** 打这个目标够多远：首领部件 / 拦路精英按主炮的 100 米（巨炮在场按对轰射程） */
  rangeOf(ctx: CombatContext, e: Enemy | null): number {
    return e && (e.controller || e.spec.blocker) ? Math.max(VULCAN.bossRange, ctx.duel) : this.form.range;
  }

  protected baseRounds(): number {
    return this.form.belts ?? CORE_STATS.vulcan.belts(this.level);
  }

  protected reload(): number {
    return this.form.reload ?? CORE_STATS.vulcan.reload(this.level);
  }

  /** 池子（发）：轻弹 = 原条数 × 每条发数 × 2/3 + 额外条数 × 每条发数；重弹 = 总条数 × 每条发数。 */
  override get maxRounds(): number {
    const f = this.form;
    const n = this.baseRounds();
    return f.light ? n * f.per * VULCAN.pool + this.extra * f.per : (n + this.extra) * f.per;
  }

  /** 补弹（发/秒）：每条发数 ÷ 换链秒数 ÷（电容冷却 / 基础射速），不吃连射层数。 */
  refill(ctx: CombatContext): number {
    return this.form.per / (this.reload() * ctx.mods.cooldown / ctx.mods.rate);
  }

  protected shoot(): void {}

  /** 轻弹空着按照样按补弹速度打，重弹不够一梭就排上：都不会「打不出」 */
  override get ready(): boolean {
    return true;
  }

  /** 手指按着或自动开火在打 */
  private get held(): boolean {
    return this.holding || this.autoHold;
  }

  /** 打着、或者在按（按着时手指拖动照样走位，Game.stepPlayer） */
  override get busy(): boolean {
    return this.firing || this.held;
  }

  /** 脚下光环：池子剩几成（连续条） */
  override get gauge(): number {
    return this.rounds / Math.max(1, this.maxRounds);
  }

  override get holdFire(): boolean {
    return true;
  }

  override get ring(): number {
    return 2;
  }

  /** 光环闪：轻弹打空降速时；重弹打空停火补弹的整段（T126：一整条连续的池子在往回涨，不画梭的刻度） */
  override get ringDry(): boolean {
    return this.dry && (this.firing || !this.form.light);
  }

  override aimAt(ctx: CombatContext, target: Enemy | null, angle = 0): void {
    if (this.firing) return;
    const P = ctx.tank.group.position;
    // 按着、重弹两梭之间歇着：炮塔照旧指着锁住的目标
    if (this.held && !this.dirMode && this.lock?.alive) {
      this.target = this.lock;
      this.aim = this.turn(ctx, angleTo(P.x, P.z, this.lock.group.position.x, this.lock.group.position.z), VULCAN.turn);
      return;
    }
    if (this.holding && this.dirMode) {
      this.target = null;
      this.aim = this.turn(ctx, this.steerA, VULCAN.turn);
      return;
    }
    this.target = target;
    this.aim = this.turn(ctx, target ? angleTo(P.x, P.z, target.group.position.x, target.group.position.z) : angle, VULCAN.turn);
  }

  override holdDir(): void {
    this.dirMode = true;
    this.steerA = this.aim;
  }

  override steer(angle: number): void {
    this.dirMode = true;
    this.steerA = THREE.MathUtils.clamp(angle, -1.2, 1.2);
  }

  /**
   * 按下 / 点一下（按住由 holding 接着打）：轻弹点射从这一下起打 0.6 秒；重弹点射 0.3 秒（歇着 / 不够一梭就排着，够了自动打）。
   * 正在打时再点 = 弹流甩过去（手动优先；自动开火不抢手动锁的目标）
   */
  override fire(ctx: CombatContext, angle: number, target: Enemy | null): boolean {
    const manual = !this.auto;
    const tgt = target?.alive ? target : null;
    const f = this.form;
    if (!this.firing || manual || !this.manual) {
      this.lock = tgt;
      this.lockLost = false;
      this.want = angle;
      this.manual = manual;
      if (manual) this.dirMode = false;
      if (!this.firing) this.aim = ctx.tank.group.rotation.y + ctx.tank.turret.rotation.y;
    }
    if (!manual) return true;
    if (f.light) this.burstT = VULCAN.tap;
    else this.tapT = VULCAN.heavyTap;
    return true;
  }

  override update(ctx: CombatContext): void {
    this.rateStack.factor(ctx.mods.rate, ctx.time);
    this.extra = ctx.mods.count;
    this.now = ctx.time;
    this.tick(ctx);
    this.stepLook(ctx);
    this.stepVisual(ctx);
  }

  /** 画出来的炮塔 / 炮管朝向（T195）：弹簧跟着瞄准走，绘制时由 Tank 换上（逻辑姿态不动） */
  private stepLook(ctx: CombatContext): void {
    const L = VULCAN.look;
    const t = ctx.tank;
    const dt = ctx.dt;
    const yaw = t.group.rotation.y + t.turret.rotation.y;
    if (!this.visOn) {
      this.visYaw = yaw;
      this.visV = 0;
      this.visOn = true;
    }
    const spring = (x: number, v: number, err: number, w: number, max: number) => {
      const nv = THREE.MathUtils.clamp(v + (err * w * w - v * 2 * w) * dt, -max, max);
      return [x + nv * dt, nv];
    };
    [this.visYaw, this.visV] = spring(this.visYaw, this.visV, wrap(yaw - this.visYaw), L.w, L.max);
    const lag = wrap(this.visYaw - yaw);
    if (Math.abs(lag) > L.lag) this.visYaw = yaw + Math.sign(lag) * L.lag;
    this.visYaw = yaw + wrap(this.visYaw - yaw);
    t.turretDrawYaw = this.visYaw;
    const n = this.form.guns;
    for (let i = 0; i < 4; i++) {
      const g = this.guns[i];
      if (i >= n) g.vis = g.visV = 0;
      else [g.vis, g.visV] = spring(g.vis, g.visV, g.yaw - g.vis, L.gunW, L.gunMax);
      this.visGuns[i] = g.vis;
    }
    t.gunDrawYaw = this.visGuns;
  }

  /** 第 i 门画出来的炮口（T195）：逻辑炮口绕炮塔转到画出来的朝向；返回画出来的朝向 */
  private lookMuzzle(ctx: CombatContext, i: number, out: THREE.Vector3): number {
    const g = this.guns[i];
    const m = ctx.tank.muzzleWorld(i, out);
    const d = wrap(this.visYaw + g.vis - this.aim - g.yaw);
    const c = ctx.tank.turret.getWorldPosition(this.mv);
    const dx = m.x - c.x, dz = m.z - c.z, cs = Math.cos(d), sn = Math.sin(d);
    m.x = c.x + dx * cs + dz * sn;
    m.z = c.z - dx * sn + dz * cs;
    return this.visYaw + g.vis;
  }

  protected override tick(ctx: CombatContext): void {
    if (!this.holding) this.dirMode = false;
    const f = this.form;
    const C = this.maxRounds;
    const g = this.refill(ctx);
    if (f.light) this.stepLight(ctx, f, C, g);
    else this.stepHeavy(ctx, f, C, g);
  }

  /** 轻弹：池里有弹按射速打，空了按补弹速度打；补弹一直在补 */
  private stepLight(ctx: CombatContext, f: VulcanForm, C: number, g: number): void {
    const dt = ctx.dt;
    this.burstT = Math.max(0, this.burstT - dt);
    if (!(this.held || this.burstT > 0)) {
      if (this.firing) this.stop(ctx, f);
      this.rounds = Math.min(C, this.rounds + g * dt);
      if (this.rounds >= C * VULCAN.dryAt) this.dry = false;
      return;
    }
    if (!this.firing) this.start(ctx);
    this.sessT += dt;
    this.contT += dt;
    const A = VULCAN.accel;
    const accel = 1 + (A.max - 1) * THREE.MathUtils.clamp((this.contT - A.from) / (A.to - A.from), 0, 1);
    const full = f.rate * this.modRate(ctx) * (f.ammoRate ? 1 + 0.1 * this.extra : 1) * accel;
    const rate = this.ramp ? full * (VULCAN.spin.from + (1 - VULCAN.spin.from) * Math.min(1, this.sessT / VULCAN.spin.t)) : full;
    const avail = this.rounds + g * dt;
    const use = Math.min(rate * dt, avail);
    this.rounds = Math.min(C, avail - use);
    this.consumeAmmo(ctx, use);
    // 打空那一下：弹箱两侧白汽 + 嘶声（池子回到一成半以上才算回满速，下次打空再喷）
    if (!this.dry && this.rounds < 1 && use < rate * dt - 1e-6) {
      this.dry = true;
      this.steamT = 0.6;
      ctx.audio.play('steam');
    } else if (this.dry && this.rounds >= C * VULCAN.dryAt) this.dry = false;
    this.rateNow = dt > 0 ? use / dt : 0;
    this.fullRate = this.dry ? this.rateNow : full;
    this.emit(ctx, f, use);
  }

  /**
   * 重弹（T126，制作人「不需要那么多弹夹……把总装弹数合并到一起」）：整个池子一口气打，按住一直打到见底（打着照样补），松手 / 点射打完立刻停；
   * 打空那一下白汽 + 嘶声、停火，光环闪着往回涨，整池补满（补弹速度没变，千钧 4 秒）上膛声再开；没打空的时候松手再按马上接着打、池子照样往回补
   */
  private stepHeavy(ctx: CombatContext, f: VulcanForm, C: number, g: number): void {
    const dt = ctx.dt;
    const want = this.held || this.tapT > 0;
    if (want && !this.firing && !this.dry && this.rounds >= 1) {
      this.start(ctx);
      // 开火那一下「嗵」，千钧车身往后仰；画面后坐只给这一下（T134，原来日常档随机抖 0.22 / 0.1），之后连射照旧只有嗡震
      ctx.audio.play('charge', f.key === 4 ? 0.5 : 0.32, f.key === 4 ? 0.42 : 0.56);
      ctx.recoil(-Math.sin(this.aim), -Math.cos(this.aim), ...(f.key === 4 ? RECOIL_KICK.heavyUlt : RECOIL_KICK.heavy));
      if (f.key === 4) ctx.tank.kick(0.25);
    }
    if (this.firing && want) {
      this.tapT = Math.max(0, this.tapT - dt);
      this.sessT += dt;
      const full = f.rate * this.modRate(ctx);
      const rate = this.ramp ? full * (VULCAN.heavySpin.from + (1 - VULCAN.heavySpin.from) * Math.min(1, this.sessT / VULCAN.heavySpin.t)) : full;
      this.fullRate = full;
      const avail = this.rounds + g * dt;
      const use = Math.min(avail, rate * dt);
      this.rounds = Math.min(C, avail - use);
      this.consumeAmmo(ctx, use);
      this.rateNow = dt > 0 ? use / dt : 0;
      this.emit(ctx, f, use);
      if (use < rate * dt - 1e-6 && this.rounds < 1) {
        this.rounds = 0;
        this.dry = true;
        this.steamT = 0.6;
        ctx.audio.play('steam');
        this.stop(ctx, f);
      }
      return;
    }
    if (this.firing) this.stop(ctx, f);
    const before = this.rounds;
    this.rounds = Math.min(C, this.rounds + g * dt);
    if (this.dry && this.rounds >= C - 1e-6) {
      this.dry = false;
      this.markLoaded();
    } else if (before < C && this.rounds >= C) this.markLoaded();
  }

  /** 开始出弹：停火超过 0.6 秒才重新起转（起转声、加速清零），否则接着上次的转速 */
  private start(ctx: CombatContext): void {
    const spinUp = ctx.time - this.lastT > VULCAN.idle;
    this.ramp = spinUp;
    this.sessT = 0;
    if (spinUp) this.contT = 0;
    this.firing = true;
    this.aim = ctx.tank.group.rotation.y + ctx.tank.turret.rotation.y;
    for (const g of this.guns) {
      g.packT = 0;
      g.traceAcc = 0;
      g.caseAcc = 0;
    }
  }

  /** 停火（松手 / 一梭打完）：剩下没出的包打出去，炮口一口烟、弹壳叮当 */
  private stop(ctx: CombatContext, f: VulcanForm): void {
    for (let i = 0; i < f.guns; i++) {
      const g = this.guns[i];
      if (g.owed > 1e-4) this.packet(ctx, f, i, g.owed, this.spreadOf(f));
      g.owed = 0;
    }
    this.firing = false;
    this.rateNow = 0;
    if (!this.held) {
      this.dirMode = false;
      this.manual = false;
    }
    // 停火：炮口最后一团烟多留 1 秒（清膛咔嗒、弹壳叮当在 AudioSystem.vulcan 的收尾里）
    const m = ctx.tank.muzzleWorld(0, this.m);
    ctx.fx.smoke(m.x, m.y, m.z, f.key === 4 ? 0.9 : 0.45, 2.4, 0x8a8478, 0.35);
  }

  /** 散布：重弹每梭里越打越准 */
  private spreadOf(f: VulcanForm): number {
    const dur = f.per / Math.max(1, f.rate);
    return CORE_STATS.vulcan.spread(this.ultimate ? 6 : this.level) * DEG * (f.tight ? f.tight[0] + (f.tight[1] - f.tight[0]) * Math.min(1, this.sessT / dur) : 1);
  }

  /** 这一帧打出 use 发：转炮塔、分火、出包，曳光 / 弹壳 / 火舌按实际打出的发数画 */
  private emit(ctx: CombatContext, f: VulcanForm, use: number): void {
    const dt = ctx.dt;
    const P = ctx.tank.group.position;
    this.lastT = ctx.time;

    // 主弹流：锁住目标跟着打；倒了 / 出了射程先在左右 30° 里接、再在整个扇面里找，都没有就朝原方向接着打（D1-034 第 2.2 节）
    const lk = this.lock;
    if (lk && (!lk.alive || Math.hypot(lk.group.position.x - P.x, lk.group.position.z - P.z) > this.rangeOf(ctx, lk) + 4)) {
      this.lock = null;
      this.lockLost = true;
      this.findT = 0;
    }
    this.findT -= dt;
    if (this.dirMode) {
      this.want = this.steerA;
      if (this.findT <= 0) {
        this.findT = 0.15;
        this.lock = ctx.autoAim ? ctx.aimPick(-this.steerA, VULCAN.assist, f.range) : null;
      }
    } else if (!this.lock && this.lockLost && ctx.autoAim && this.findT <= 0) {
      this.findT = 0.2;
      this.lock = ctx.aimPick(-this.aim, VULCAN.retarget, f.range) ?? ctx.aimPick(null, undefined, f.range);
    }
    if (this.lock) this.want = angleTo(P.x, P.z, this.lock.group.position.x, this.lock.group.position.z);
    // 炮塔转速有上限、车尾挂件挡着的地方转不进去（T127）：换到身后的目标时弹流跟着炮塔甩过去
    this.aim = this.turn(ctx, this.want, VULCAN.turn);
    this.target = this.lock;

    // 分火（第 4.2 节）：其余几门在主弹流左右 12°（四联 20°）里各咬一个还没被咬住的；咬住不换，直到倒了 / 出了扇面或射程 / 被挡 0.5 秒；人不够就和主弹流打同一个
    const G = f.guns;
    const rig = ctx.tank.vulcanRig;
    const now = ctx.time;
    for (let i = 0; i < G; i++) {
      const g = this.guns[i];
      if (i === 0) g.target = this.lock;
      else {
        const t = g.target;
        const fallback = t === this.lock;
        let drop = !t?.alive || fallback;
        if (t && !drop) {
          const d = Math.hypot(t.group.position.x - P.x, t.group.position.z - P.z);
          drop = d > this.rangeOf(ctx, t) + 2 || Math.abs(wrap(angleTo(P.x, P.z, t.group.position.x, t.group.position.z) - this.aim)) > f.split;
          // 被挡：这门的包 0.5 秒没打到它、一直打在别的东西上 → 换人，它 1 秒内不再挑
          if (!drop && now - g.since > VULCAN.block.t && now - g.onT > VULCAN.block.t && now - g.otherT < 0.25) {
            g.ban = t;
            g.banUntil = now + VULCAN.block.ban;
            drop = true;
          }
        }
        g.findT -= dt;
        if (drop && (!fallback || g.findT <= 0)) {
          g.findT = 0.15;
          const next = this.pickSplit(ctx, i, f.split) ?? this.lock;
          if (next !== g.target) {
            g.target = next;
            g.since = now;
            g.onT = now;
          }
        }
      }
      let want = 0;
      if (g.target) want = THREE.MathUtils.clamp(wrap(angleTo(P.x, P.z, g.target.group.position.x, g.target.group.position.z) - this.aim), -f.split, f.split);
      const step = VULCAN.gunTurn * dt;
      g.yaw += THREE.MathUtils.clamp(want - g.yaw, -step, step);
      const node = rig?.guns[i];
      if (node) node.rotation.y = g.yaw;
    }

    // 总射速平分给几门；每门按自己的包频出包
    const each = use / G;
    const tier = ctx.tier;
    const [every, perSec, inFlight, sizeW, sizeL] = VULCAN.trace[tier];
    ctx.bullets.dropLod(tier === 'low');
    // 轻弹每 5 发一颗（低档 6），重弹线 / 千钧每 3 发：稀疏的光点串，打不中的弹看不见，密度靠枪口和弹着撑
    const gap = f.key >= 3 ? VULCAN.heavyEvery : every;
    const [caseEvery, casePerSec, caseCap, caseRest] = VULCAN.casing[tier];
    ctx.fx.casings.limit = caseCap;
    ctx.fx.casings.rest = caseRest;
    const MF = ctx.fx.muzzleFlash;
    MF.variants = tier === 'low' ? 2 : 4;
    const ballEvery = VULCAN.flash.ball[tier];
    const s = f.key === 4 ? 1.7 : f.key === 3 ? 1.25 : f.key === 2 ? 0.85 : 1;
    let lit = 0;
    while (this.traceLive.length && this.traceLive[0] <= ctx.time) this.traceLive.shift();
    const spread = this.spreadOf(f);
    for (let i = 0; i < G; i++) {
      const g = this.guns[i];
      g.owed += each;
      g.packT -= dt;
      if (g.packT <= 0) {
        this.packet(ctx, f, i, g.owed, spread);
        g.owed = 0;
        g.packT = Math.max(g.packT + 1 / f.packets, 0.25 / f.packets);
      }
      // 曳光：按实际打出的发数比例画，每门每秒、全场在飞都有上限；同一帧出的几根按这一帧里的先后往前错开（帧率低也不扎堆）
      g.traceAcc += each;
      g.traceTok = Math.min(perSec * 0.25, g.traceTok + perSec * dt);
      const due = Math.floor(g.traceAcc / gap);
      for (let j = 0; j < due; j++) {
        g.traceAcc -= gap;
        if (g.traceTok < 1 || this.traceLive.length >= inFlight) continue;
        g.traceTok -= 1;
        this.tracer(ctx, f, i, spread, (1 - (j + Math.random()) / due) * VULCAN.speed * dt, sizeW, sizeL);
      }
      // 弹壳成股甩出，每 2 个夹 1 片弹链节
      g.caseAcc += each;
      g.caseTok = Math.min(casePerSec * 0.25, g.caseTok + casePerSec * dt);
      while (g.caseAcc >= caseEvery) {
        g.caseAcc -= caseEvery;
        if (g.caseTok < 1) continue;
        g.caseTok -= 1;
        this.casing(ctx, i, (g.caseN = (g.caseN + 1) % 3) === 0);
      }
      // 枪口：一发一次爆闪。轻弹这一帧亮的概率 1 − e^(−发数 × 0.6)（暗的帧就是两发之间），亮度跟发数走；
      // 重弹按发数累计，攒够一发亮一次（36～78 发/秒在 60 帧下看得出一下一下）
      const m = this.m;
      const yaw = this.lookMuzzle(ctx, i, m);
      let on: boolean;
      if (f.light) on = Math.random() < 1 - Math.exp(-each * VULCAN.flash.lit);
      else {
        g.flashAcc += each;
        on = g.flashAcc >= 1;
        if (on) g.flashAcc -= Math.floor(g.flashAcc);
      }
      if (on) {
        const k = rand(0.6, 1.6) * (1 + 0.12 * Math.min(3, each));
        lit = Math.max(lit, k);
        MF.add(m.x, m.y, m.z, yaw, 2.6 * s * k, 1.25 * s * Math.sqrt(k), Math.min(1.3, 0.75 + 0.3 * k));
      }
      // 二次火球：每几发一团大一号的橙色光团，往前冲一点就散
      g.ballAcc += each;
      if (g.ballAcc >= ballEvery) {
        g.ballAcc -= ballEvery * Math.floor(g.ballAcc / ballEvery);
        const d = rand(0.6, 1.2) * s;
        ctx.fx.glow.emit({ x: m.x - Math.sin(yaw) * d, y: m.y, z: m.z - Math.cos(yaw) * d, vx: -Math.sin(yaw) * 6, vz: -Math.cos(yaw) * 6, life: rand(0.06, 0.08), size: rand(1.6, 2.4) * s, size1: 2.6 * s, color: 0xffb050, color1: 0xc8401a, alpha: 0.7, frame: 0, drag: 8 });
      }
    }
    // 补光每秒最多 15 次，亮度跟这一帧爆闪大小走
    this.flashT -= dt;
    if (this.flashT <= 0 && lit > 0) {
      this.flashT = 1 / 15;
      const m = ctx.tank.muzzleWorld(0, this.m);
      ctx.fx.flash(m.x, m.y + 0.4, m.z, (f.key === 4 ? 260 : 150) * (0.5 + 0.5 * lit));
    }
    // 枪口烟：每秒 10 团，一股灰烟拖在炮口
    this.smokeT -= dt;
    if (this.smokeT <= 0) {
      this.smokeT = 1 / 10;
      const m = ctx.tank.muzzleWorld(Math.floor(Math.random() * G), this.m);
      ctx.fx.smoke(m.x, m.y, m.z, 0.35 * s, 1.3, 0x9a9286, 0.22);
    }
    // 持续嗡震（千钧 0.2）不变；T088 抖动：每门炮组高频抖、炮塔往后顶、车头微微抬起（重弹 ×2）
    ctx.hum(f.key === 4 ? 0.2 : 0.12);
    const S = VULCAN.shake;
    const heavyK = f.light ? 1 : 2;
    for (let i = 0; i < G; i++) {
      const sp = rig?.spinners[i];
      if (sp) sp.position.set((Math.random() - 0.5) * 2 * S.pos * heavyK, (Math.random() - 0.5) * 2 * S.pos * heavyK, sp.position.z);
      if (rig?.guns[i]) rig.guns[i].rotation.z = (Math.random() - 0.5) * 2 * S.rot * heavyK;
    }
    this.backT = S.back * heavyK;
    ctx.tank.brace(S.lift * heavyK);
  }

  /** 分火挑人：扇面里、射程里、没被别的炮咬住、不是 1 秒内刚被挡掉的；打分 =（距离 + 8）÷ 威胁 ×（1 + 偏角 ÷ 上限），小的先 */
  private pickSplit(ctx: CombatContext, i: number, split: number): Enemy | null {
    const P = ctx.tank.group.position;
    const me = this.guns[i];
    let best: Enemy | null = null;
    let score = Infinity;
    for (const e of ctx.enemies) {
      if (!e.alive || e === this.lock || (e === me.ban && ctx.time < me.banUntil)) continue;
      let taken = false;
      for (let j = 1; j < this.form.guns; j++) if (j !== i && this.guns[j].target === e) taken = true;
      if (taken) continue;
      const dx = e.group.position.x - P.x;
      const dz = e.group.position.z - P.z;
      const d = Math.hypot(dx, dz);
      if (d < 3 || d > this.rangeOf(ctx, e)) continue;
      const off = Math.abs(wrap(angleTo(P.x, P.z, e.group.position.x, e.group.position.z) - this.aim));
      if (off > split) continue;
      const s = ((d + 8) / e.spec.threat) * (1 + off / split);
      if (s < score) {
        score = s;
        best = e;
      }
    }
    return best;
  }

  /** 引着打：起转那 0.2 秒弹着点从目标距离的 55% 往前走到目标身上 */
  private leadK(): number {
    if (!this.ramp || this.sessT >= VULCAN.lead.t) return 1;
    return VULCAN.lead.from + (1 - VULCAN.lead.from) * (this.sessT / VULCAN.lead.t);
  }

  /** 出一包：直射弹 360 米/秒，在散布里随机一个方向，带发数；寿命 = 射程（引着打时截短，落地就是弹沟） */
  private packet(ctx: CombatContext, f: VulcanForm, i: number, n: number, spread: number): void {
    if (n <= 1e-4) return;
    const m = ctx.tank.muzzleWorld(i, this.m);
    const tgt = this.guns[i].target;
    const a = this.aim + this.guns[i].yaw + (rng.weapon() * 2 - 1) * spread;
    let reach = this.rangeOf(ctx, tgt);
    const k = this.leadK();
    if (k < 1 && tgt) reach = Math.min(reach, Math.hypot(tgt.group.position.x - m.x, tgt.group.position.z - m.z) * k);
    ctx.bullets.aim = tgt;
    const b = ctx.bullets.spawn('vpack', m.x, m.z, -Math.sin(a) * VULCAN.speed, -Math.cos(a) * VULCAN.speed, n * f.dmg, true);
    ctx.bullets.aim = null;
    b.vul = i;
    b.n = n;
    b.critical = this.guns[i].crits.take(n, ctx.mods.crit);
    b.dtype = 'small';
    b.pierce = f.pierce;
    b.splash = f.splash * ctx.mods.area;
    b.life = reach / VULCAN.speed;
  }

  /** 射速核心：1.4 + 每层 0.2。电容只加快补弹，不参与弹链内射速。 */
  private modRate(ctx: CombatContext): number {
    return this.rateStack.factor(ctx.mods.rate, ctx.time);
  }

  private consumeAmmo(ctx: CombatContext, amount: number): void {
    this.rateStack.fire(amount / 10, ctx.time, ctx.mods.rate);
    const back = this.ammoRefund.consume(amount, this.form.per, ctx.mods.count > 0);
    if (!back) return;
    this.rounds = Math.min(this.maxRounds, this.rounds + back * this.form.per);
    this.markLoaded();
    ctx.ammoReturn?.();
  }

  /** 一根水滴曳光（纯画面）：飞到最近一包打中的距离就灭；ahead = 这一帧里早出膛的已经飞出去多远，sizeW / sizeL = 画质档粗细 / 长短倍率 */
  private tracer(ctx: CombatContext, f: VulcanForm, i: number, spread: number, ahead: number, sizeW: number, sizeL: number): void {
    const g = this.guns[i];
    const m = this.m;
    const tgt = g.target;
    const a = this.lookMuzzle(ctx, i, m) + (Math.random() * 2 - 1) * spread * 0.6;
    let reach = this.rangeOf(ctx, tgt);
    if (tgt) reach = Math.min(reach, Math.hypot(tgt.group.position.x - m.x, tgt.group.position.z - m.z) - tgt.radius * 0.4);
    if (this.now - g.hitT < 0.3) reach = Math.min(reach, g.hitD);
    reach *= this.leadK();
    if (reach < 2) return;
    // 起点 = 这一帧里的先后 + 随机挪一点，同一门炮的水滴间距不齐、一颗颗分得开；每颗粗细 / 长短各自抖一点
    const off = Math.min(reach - 1, ahead + Math.random() * 0.8);
    ctx.bullets.aim = tgt;
    const b = ctx.bullets.spawn(f.trace, m.x - Math.sin(a) * off, m.z - Math.cos(a) * off, -Math.sin(a) * VULCAN.speed, -Math.cos(a) * VULCAN.speed, 0, true);
    ctx.bullets.aim = null;
    b.vul = -2;
    b.life = Math.max(0.02, (reach - off) / VULCAN.speed);
    b.age = off / VULCAN.speed;
    b.sizeW = sizeW * rand(0.85, 1.15);
    b.sizeL = sizeL * rand(0.75, 1.25);
    this.traceLive.push(ctx.time + b.life);
  }

  /** 一个弹壳（link = 弹链节）：出口方向收窄、初速散布小，连着出来是一股 */
  private casing(ctx: CombatContext, i: number, link: boolean): void {
    const rig = ctx.tank.vulcanRig;
    const ej = rig?.ejects[i];
    if (!ej) return;
    const p = ej.o.getWorldPosition(this.m);
    const a = this.aim + ej.side * rand(-0.26, 0.26);
    const rx = Math.cos(a) * ej.side;
    const rz = -Math.sin(a) * ej.side;
    const out = rand(3, 3.6) * (link ? 0.8 : 1);
    ctx.fx.casings.emit(p.x, p.y, p.z, rx * out + Math.sin(this.aim) * rand(0.4, 0.8), rand(3.8, 4.6), rz * out + Math.cos(this.aim) * rand(0.4, 0.8), rig!.casing, link);
  }

  /**
   * 一包打中了（Game 回调）：记距离给曳光截短；打在没打穿的重甲上 = 啃甲（嗡鸣颤音）；
   * e = 打中的敌人（打在路障 / 残骸 / 景物上为 null）——分火的炮按它判断是不是一直被挡
   */
  noteHit(gun: number, x: number, z: number, tankX: number, tankZ: number, gnaw: boolean, e: Enemy | null = null): void {
    const g = this.guns[gun];
    if (!g) return;
    g.hitD = Math.hypot(x - tankX, z - tankZ);
    g.hitT = this.now;
    if (e && e === g.target) g.onT = this.now;
    else g.otherT = this.now;
    if (gnaw) this.gnawT = 0.2;
  }

  /** 转管、虚影、管口发红、白汽、声音 */
  private stepVisual(ctx: CombatContext): void {
    const f = this.form;
    const dt = ctx.dt;
    const rig = ctx.tank.vulcanRig;
    const n = f.key === 4 ? 7 : 6;
    const want = this.firing ? Math.min(VULCAN.spinMax, ((this.rateNow / f.guns) / n) * Math.PI * 2 * 0.6) : 0;
    this.spin = want > this.spin ? want : Math.max(0, this.spin - (VULCAN.spinMax / VULCAN.spinDown) * dt);
    const H = VULCAN.heat;
    this.fireT = this.firing ? Math.min(H.hot, this.fireT + dt) : Math.max(0, this.fireT - H.cool * dt);
    // 炮塔后坐：开火时 0.05 秒顶到位，停火弹簧回位
    this.back += ((this.firing ? this.backT : 0) - this.back) * Math.min(1, dt * (this.firing ? 20 : 8));
    this.gnawT = Math.max(0, this.gnawT - dt);
    if (rig) {
      for (let i = 0; i < rig.spinners.length; i++) {
        rig.spinners[i].rotation.z += this.spin * dt;
        rig.blurs[i].visible = this.spin > VULCAN.blurAt && ctx.tier !== 'low';
        if (!this.firing) {
          const g = this.guns[i];
          if (g) g.yaw *= Math.max(0, 1 - dt * 4);
          rig.guns[i].rotation.y = g ? g.yaw : 0;
          rig.guns[i].rotation.z = 0;
          rig.spinners[i].position.x = rig.spinners[i].position.y = 0;
        }
      }
      // 弹带滚动（T090，D1-034 第十二节第 4 条）：开火时跟实际射速走（画面封顶每秒 18 格，再快就看成倒转），
      // 不开火、池子没满时按补弹速度慢慢走，满了停
      const B = VULCAN.belt;
      const want = this.firing ? Math.min(B.fire, this.rateNow / f.guns) : this.rounds < this.maxRounds - 0.5 ? Math.min(B.feed, this.refill(ctx) / f.guns) : 0;
      this.beltV += (want - this.beltV) * Math.min(1, dt * 8);
      rig.belt.offset.y = (rig.belt.offset.y - this.beltV * dt) % 1;
      // 管口发红：3 秒前不红，3 → 8 秒从暗红走到暗橙
      const k = THREE.MathUtils.clamp((this.fireT - H.red) / (H.hot - H.red), 0, 1);
      this.heatC.copy(HEAT_RED).lerp(HEAT_ORANGE, k);
      rig.heat.emissive.copy(this.heatC);
      rig.heat.emissiveIntensity = k > 0 ? 0.25 + k * 1.1 : 0;
      const T = ctx.tank.turret;
      T.userData.z0 ??= T.position.z;
      T.position.z = T.userData.z0 + this.back;
      if (this.steamT > 0) {
        this.steamT -= dt;
        for (const ej of rig.ejects) {
          const p = ej.o.getWorldPosition(this.m);
          if (Math.random() < 0.6) ctx.fx.steam(p.x, p.y + 0.3, p.z);
        }
      }
    }
    this.sound(ctx);
  }

  /** 双人共用音频通道，游戏层选正在开火的那辆。 */
  sound(ctx: CombatContext): void {
    const f = this.form;
    ctx.audio.vulcan(this.firing ? this.rateNow : 0, this.firing ? this.fullRate : 0, f.guns, this.spin / VULCAN.spinMax, f.key, this.gnawT > 0, ctx.tier === 'low');
    ctx.audio.mgDuck = this.firing ? 0.5 : 1;
  }

  override reset(): void {
    super.reset();
    for (const g of this.guns) g.crits.reset();
    this.rateStack.reset();
    this.firing = false;
    this.tapT = 0;
    this.burstT = 0;
    this.sessT = this.contT = 0;
    this.lastT = -99;
    this.dry = false;
    this.autoHold = false;
    this.lock = null;
    this.dirMode = false;
    this.visOn = false;
    this.spin = this.fireT = this.steamT = this.back = this.backT = 0;
    this.traceLive.length = 0;
    for (const g of this.guns) {
      g.target = g.ban = null;
      g.owed = 0;
      g.vis = g.visV = 0;
    }
  }
}
