import type * as THREE from 'three';
import { camoTexture, grimeTexture, metalNormal } from './textures';

/** 多处共用的程序化贴图，首次使用时生成 */
let metal: THREE.Texture | null = null;
let enemyCamo: THREE.Texture | null = null;
let grime: THREE.Texture | null = null;

export function sharedMetalNormal(): THREE.Texture {
  return (metal ??= metalNormal());
}

/** 敌方涂装：钢灰底 + 深灰 / 锈褐斑块 */
export function sharedEnemyCamo(): THREE.Texture {
  if (!enemyCamo) {
    enemyCamo = camoTexture(0x5c5a57, 0x3e3d3b, 0x6a5444, 311);
    enemyCamo.repeat.set(0.5, 0.5);
  }
  return enemyCamo;
}

export function sharedGrime(): THREE.Texture {
  return (grime ??= grimeTexture());
}
