/**
 * 究极配套（策划 3.8）：配方两件（都已 ★）机身照旧深枪铁 + 一段红铜接线 + 1 个发光件（ultKit），
 * 发光件跟炮塔究极套件的指示灯同色同步亮灭（Tank.kitGlow）
 */
export const ULT_KIT = 'ultKit';

/** 挂件上这一级有的零件（按表的顺序）+ 联动模块 + 究极配套 */
export function formKeys(id: WeaponId, lv: number, link: LinkId | null = null, ult: FusionId | null = null): string[] {
  const form = MOUNT_FORM[id];
  if (!form) return [`legacy-${lv}`];
  const keys = Object.keys(form).filter((k) => lv >= form[k][0] && lv <= form[k][1]);
  const lk = link ? LINK_FORM[link][id] : undefined;
  if (lk) keys.push(lk);
  if (ult) keys.push(ULT_KIT);
  return keys;
}

