/**
 * 军衔（T018-5 局外成长的第一根支柱，策划 `T018-新想法-策划案.md` 6.3 ①）：每局结算得「军功」（只决定军衔、不能花），20 级通用军衔名（不对应任何国家）。
 * 军功 = 推进米数 ÷ 10 + 击毁数 + 首领 × 200 + 合成究极 100 + 本局解锁成就 × 50；第 n 级要 600 × 1.18^(n−1) 军功（满级累计约 8.7 万）。
 * 试玩局不算。车库 / 军工厂 / 每日任务 / 军票没做（见报告）
 */
export const RANKS = ['列兵', '上等兵', '下士', '中士', '上士', '军士长', '准尉', '少尉', '中尉', '上尉', '少校', '中校', '上校', '大校', '准将', '少将', '中将', '上将', '大将', '元帅'];

/** 从第 n 级升到第 n + 1 级要的军功（n 从 1 起） */
export const rankNeed = (n: number) => Math.round(600 * 1.18 ** (n - 1));

export interface MeritRun {
  distance: number;
  kills: number;
  bosses: number;
  fused: boolean;
  achievements: number;
}

export const meritOf = (r: MeritRun) => Math.floor(r.distance / 10) + r.kills + r.bosses * 200 + (r.fused ? 100 : 0) + r.achievements * 50;

/** 累计军功 → 军衔（level 1..20、名字、到下一级的进度 0..1，满级为 1） */
export function rankOf(total: number): { level: number; name: string; progress: number } {
  let left = Math.max(0, total);
  let level = 1;
  while (level < RANKS.length && left >= rankNeed(level)) {
    left -= rankNeed(level);
    level += 1;
  }
  return { level, name: RANKS[level - 1], progress: level >= RANKS.length ? 1 : left / rankNeed(level) };
}
