import * as THREE from 'three';
import { type CrushPartRange } from '../GeoCache';
import { CRUSH_PART } from './crush';
import { houseNoise } from './houseFracture';
import { SURF } from '../sceneryMaterial';

export interface MasonryChunk {
  start: number;
  count: number;
  center: THREE.Vector3;
  normal: THREE.Vector3;
  box: THREE.Box3;
  fixed: boolean;
  glass: boolean;
}

/** 从原残墙的部件范围取尺寸和颜色。完整模型不重建，受击后才沿不规则接缝拆成薄块。 */
export function masonryFracture(source: THREE.BufferGeometry, seed: number) {
  const pos = source.getAttribute('position'), nor = source.getAttribute('normal');
  const col = source.getAttribute('color'), uv = source.getAttribute('uv');
  const positions: number[] = [], normals: number[] = [], colors: number[] = [], uvs: number[] = [], surfs: number[] = [];
  // T184：源模型带表面类别（加细档）时断块沿用，砌体块记砖面
  const srcSurf = source.getAttribute('surf');
  const chunks: MasonryChunk[] = [];
  const ranges = source.userData.crushParts as CrushPartRange[];
  const v = new THREE.Vector3(), ab = new THREE.Vector3(), ac = new THREE.Vector3(), n = new THREE.Vector3();
  const triangle = (a: THREE.Vector3, b: THREE.Vector3, c: THREE.Vector3, color: number[], shade: number) => {
    n.crossVectors(ab.subVectors(b, a), ac.subVectors(c, a)).normalize();
    for (const p of [a, b, c]) {
      positions.push(p.x, p.y, p.z);
      normals.push(n.x, n.y, n.z);
      colors.push(color[0] * shade, color[1] * shade, color[2] * shade);
      uvs.push((p.x + p.z) * .25, p.y * .25);
      surfs.push(SURF.brick);
    }
  };
  for (const range of ranges) {
    const bounds = new THREE.Box3();
    for (let i = range.start; i < range.start + range.count; i++) bounds.expandByPoint(v.fromBufferAttribute(pos, i));
    const side = bounds.max.x - bounds.min.x < bounds.max.z - bounds.min.z;
    const normal = new THREE.Vector3(side ? -1 : 0, 0, side ? 0 : 1);
    if (range.role !== CRUSH_PART.masonry) {
      const start = positions.length / 3;
      for (let i = range.start; i < range.start + range.count; i++) {
        positions.push(pos.getX(i), pos.getY(i), pos.getZ(i));
        normals.push(nor.getX(i), nor.getY(i), nor.getZ(i));
        colors.push(col.getX(i), col.getY(i), col.getZ(i));
        uvs.push(uv?.getX(i) ?? 0, uv?.getY(i) ?? 0);
        surfs.push(srcSurf?.getX(i) ?? 0);
      }
      chunks.push({ start, count: range.count, center: bounds.getCenter(new THREE.Vector3()), normal,
        box: bounds, fixed: range.role !== CRUSH_PART.glass, glass: range.role === CRUSH_PART.glass });
      continue;
    }
    const lo = side ? bounds.min.z : bounds.min.x, hi = side ? bounds.max.z : bounds.max.x;
    const bottom = bounds.min.y, top = bounds.max.y;
    const rows = Math.max(2, Math.ceil((top - bottom) / .65)), columns = 2;
    const grid: [number, number][][] = [];
    for (let row = 0; row <= rows; row++) {
      grid[row] = [];
      for (let c = 0; c <= columns; c++) {
        const key = seed + range.start * 17 + row * 13 + c * 31;
        grid[row][c] = [
          lo + (hi - lo) * (c + (c > 0 && c < columns ? (houseNoise(key) - .5) * .6 : 0)) / columns,
          bottom + (top - bottom) * (row + (row > 0 && row < rows ? (houseNoise(key + 3) - .5) * .55 : 0)) / rows,
        ];
      }
    }
    const color = [col.getX(range.start), col.getY(range.start), col.getZ(range.start)];
    for (let row = 0; row < rows; row++) for (let c = 0; c < columns; c++) {
      const corners = [grid[row][c], grid[row][c + 1], grid[row + 1][c + 1], grid[row + 1][c]];
      const front = corners.map(([u, y]) => new THREE.Vector3(side ? bounds.min.x : u, y, side ? u : bounds.max.z));
      const back = corners.map(([u, y]) => new THREE.Vector3(side ? bounds.max.x : u, y, side ? u : bounds.min.z));
      const start = positions.length / 3;
      triangle(front[0], front[1], front[2], color, 1); triangle(front[0], front[2], front[3], color, 1);
      triangle(back[0], back[2], back[1], color, .83); triangle(back[0], back[3], back[2], color, .83);
      for (let j = 0; j < 4; j++) {
        const k = (j + 1) % 4;
        triangle(front[j], back[j], back[k], color, .9);
        triangle(front[j], back[k], front[k], color, .9);
      }
      const box = new THREE.Box3().setFromPoints([...front, ...back]);
      chunks.push({ start, count: positions.length / 3 - start, center: box.getCenter(new THREE.Vector3()),
        normal, box, fixed: false, glass: false });
    }
  }
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3).setUsage(THREE.DynamicDrawUsage));
  geometry.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3).setUsage(THREE.DynamicDrawUsage));
  geometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
  geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  if (srcSurf) geometry.setAttribute('surf', new THREE.Float32BufferAttribute(surfs, 1));
  geometry.computeBoundingSphere();
  return { geometry, chunks };
}
