import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';

/**
 * 爆炸碎片的程序化外形（T185）：撕开的铁皮 / 装甲板、劈开的木板、扭弯的铁条、揉成团的碎铁。
 * 轮廓是带豁口的不规则多边形，沿一条随机折线弯过去再揉皱；同一位置的顶点位移相同，折线两边不开裂。
 * 固定种子，不占玩法随机源；产出都是非索引几何、平直法线（棱角分明）。
 */

type P = [number, number];

/** 固定种子的小随机数 */
function rand(seed: number): () => number {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** 按顶点位置取 0..1 的散列（同一位置同一个值；不用 sin） */
function hash(x: number, y: number, z: number, k: number): number {
  let h = Math.imul(Math.round(x * 1e4), 73856093) ^ Math.imul(Math.round(y * 1e4), 19349663) ^ Math.imul(Math.round(z * 1e4), 83492791) ^ Math.imul(k, 2654435761);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

/** 多边形留在直线 nx·x + ny·y ≥ c 那一侧的部分（Sutherland–Hodgman） */
function clip(poly: P[], nx: number, ny: number, c: number): P[] {
  const out: P[] = [];
  for (let i = 0; i < poly.length; i++) {
    const a = poly[i], b = poly[(i + 1) % poly.length];
    const da = nx * a[0] + ny * a[1] - c, db = nx * b[0] + ny * b[1] - c;
    if (da >= 0) out.push(a);
    if ((da >= 0) !== (db >= 0)) {
      const t = da / (da - db);
      out.push([a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t]);
    }
  }
  return out;
}

/** 平放的板：轮廓在 xz 平面（轮廓 y → 世界 −z），厚度沿 y、上下居中 */
function slab(poly: P[], thick: number): THREE.BufferGeometry {
  const g = new THREE.ExtrudeGeometry(new THREE.Shape(poly.map(([x, y]) => new THREE.Vector2(x, y))), { depth: thick, bevelEnabled: false, curveSegments: 1 });
  g.translate(0, 0, -thick / 2);
  g.rotateX(-Math.PI / 2);
  g.deleteAttribute('uv');
  g.clearGroups();
  return g;
}

/** 揉皱：按位置散列推顶点，再算平直法线 */
function crumple(g: THREE.BufferGeometry, amount: number, seed: number, flat = 1): THREE.BufferGeometry {
  const p = g.getAttribute('position') as THREE.BufferAttribute;
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i), y = p.getY(i), z = p.getZ(i);
    p.setXYZ(i,
      x + (hash(x, y, z, seed) - 0.5) * amount * 0.5,
      y + (hash(x, y, z, seed + 1) - 0.5) * amount * flat,
      z + (hash(x, y, z, seed + 2) - 0.5) * amount * 0.5);
  }
  g.computeVertexNormals();
  g.computeBoundingBox();
  g.computeBoundingSphere();
  return g;
}

/** 带豁口的不规则轮廓：n 个点绕一圈，少数点往里缩；long 把它拉长 */
function outline(r: () => number, long: number, notch = 0.28): P[] {
  const n = 6 + Math.floor(r() * 4);
  const pts: P[] = [];
  for (let i = 0; i < n; i++) {
    const a = ((i + (r() - 0.5) * 0.7) / n) * Math.PI * 2;
    const rad = r() < notch ? 0.16 + r() * 0.14 : 0.34 + r() * 0.2;
    pts.push([Math.cos(a) * rad * long, Math.sin(a) * rad]);
  }
  return pts;
}

/** 沿一条折线切开，一半绕折线转 bend 弧度；没切到（折线在轮廓外）就原样一块 */
function folded(poly: P[], thick: number, r: () => number, bend: number): THREE.BufferGeometry {
  const phi = r() * Math.PI, nx = Math.cos(phi), ny = Math.sin(phi), c = (r() - 0.5) * 0.24;
  const a = clip(poly, -nx, -ny, -c), b = clip(poly, nx, ny, c);
  if (a.length < 3 || b.length < 3 || Math.abs(bend) < 1e-3) return slab(poly, thick);
  const ga = slab(a, thick), gb = slab(b, thick);
  // 折线在 3D 里：轮廓方向 (−ny, nx) → (−ny, 0, −nx)，过点 (nx·c, 0, −ny·c)
  const axis = new THREE.Vector3(-ny, 0, -nx).normalize();
  const p0 = new THREE.Vector3(nx * c, 0, -ny * c);
  gb.translate(-p0.x, -p0.y, -p0.z);
  gb.applyMatrix4(new THREE.Matrix4().makeRotationAxis(axis, bend));
  gb.translate(p0.x, p0.y, p0.z);
  const g = mergeGeometries([ga, gb])!;
  ga.dispose();
  gb.dispose();
  return g;
}

/** 再折一道：直线一侧的顶点绕这条线转 bend（跨线的三角面跟着斜过去，不开裂） */
function refold(g: THREE.BufferGeometry, r: () => number, bend: number): THREE.BufferGeometry {
  const phi = r() * Math.PI, nx = Math.cos(phi), nz = Math.sin(phi), c = (r() - 0.5) * 0.3;
  const axis = new THREE.Vector3(-nz, 0, nx);
  const m = new THREE.Matrix4().makeRotationAxis(axis, bend);
  const v = new THREE.Vector3();
  const p = g.getAttribute('position') as THREE.BufferAttribute;
  for (let i = 0; i < p.count; i++) {
    v.fromBufferAttribute(p, i);
    if (v.x * nx + v.z * nz - c <= 0) continue;
    v.x -= nx * c; v.z -= nz * c;
    v.applyMatrix4(m);
    p.setXYZ(i, v.x + nx * c, v.y, v.z + nz * c);
  }
  return g;
}

/** 卷边：离中心越远越往上翘（铁皮被炸得卷起来） */
function curl(g: THREE.BufferGeometry, k: number): THREE.BufferGeometry {
  const p = g.getAttribute('position') as THREE.BufferAttribute;
  for (let i = 0; i < p.count; i++) p.setY(i, p.getY(i) + k * p.getX(i) * p.getX(i));
  return g;
}

/** 撕开的薄铁皮：大小约 0.7～1 米（随机缩放前），两道折、卷边、揉皱 */
export function tornSheet(seed: number, thick = 0.04, long = 1.2): THREE.BufferGeometry {
  const r = rand(seed);
  const g = folded(outline(r, long), thick, r, (r() < 0.5 ? -1 : 1) * (0.4 + r() * 0.9));
  refold(g, r, (r() - 0.5) * 1.4);
  return crumple(curl(g, (r() - 0.5) * 0.8), 0.08, seed);
}

/** 崩开的装甲板：比铁皮厚、折得浅，边缘豁口更多 */
export function armorShard(seed: number): THREE.BufferGeometry {
  const r = rand(seed);
  const g = folded(outline(r, 1 + r() * 0.5, 0.4), 0.09 + r() * 0.05, r, (r() - 0.5) * 0.7);
  return crumple(g, 0.06, seed, 0.6);
}

/** 揉成一团的碎铁 / 炸裂的厚铁块：二十面体压扁拉长再大幅揉皱 */
export function scrapLump(seed: number, size = 0.28): THREE.BufferGeometry {
  const r = rand(seed);
  const g = new THREE.IcosahedronGeometry(size, 1);
  g.scale(1 + r() * 0.6, 0.5 + r() * 0.4, 0.7 + r() * 0.5);
  g.deleteAttribute('uv');
  return crumple(g, size * 0.75, seed);
}

/** 扭弯的铁条 / 角铁：两三截首尾相接、每个接头拐一下 */
export function bentStrut(seed: number): THREE.BufferGeometry {
  const r = rand(seed);
  const parts: THREE.BufferGeometry[] = [];
  const at = new THREE.Vector3(), dir = new THREE.Vector3(1, 0, 0), q = new THREE.Quaternion(), m = new THREE.Matrix4();
  const w = 0.05 + r() * 0.04, h = 0.04 + r() * 0.05;
  const n = 2 + Math.floor(r() * 2);
  at.set(-0.4, 0, 0);
  for (let i = 0; i < n; i++) {
    const len = 0.28 + r() * 0.3;
    const box = new THREE.BoxGeometry(len, h, w).toNonIndexed();
    q.setFromUnitVectors(new THREE.Vector3(1, 0, 0), dir);
    m.compose(at.clone().addScaledVector(dir, len / 2), q, new THREE.Vector3(1, 1, 1));
    box.applyMatrix4(m);
    box.deleteAttribute('uv');
    parts.push(box);
    at.addScaledVector(dir, len * 0.96);
    const up = r() < 0.5;
    dir.applyAxisAngle(new THREE.Vector3(0, up ? 1 : 0, up ? 0 : 1), (r() < 0.5 ? -1 : 1) * (0.4 + r() * 0.8)).normalize();
  }
  const g = mergeGeometries(parts)!;
  for (const p of parts) p.dispose();
  g.center();
  return crumple(g, 0.025, seed);
}

/** 劈开的木板：两头是参差的劈口，略微扭一下 */
export function splitPlank(seed: number, len = 1.1, wide = 0.22, thick = 0.07): THREE.BufferGeometry {
  const r = rand(seed);
  const pts: P[] = [];
  const end = (x0: number, sign: number, from: number, to: number) => {
    const teeth = 2 + Math.floor(r() * 3);
    for (let k = 0; k <= teeth; k++) {
      const y = from + ((to - from) * k) / teeth;
      pts.push([x0 - sign * (k % 2 ? r() * 0.3 * len : r() * 0.06), y]);
    }
  };
  end(len / 2, 1, -wide / 2, wide / 2);
  end(-len / 2, -1, wide / 2, -wide / 2);
  const g = slab(pts, thick);
  // 顺着长度方向扭一点
  const p = g.getAttribute('position') as THREE.BufferAttribute;
  const twist = (r() - 0.5) * 0.5;
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i), y = p.getY(i), z = p.getZ(i), a = twist * x;
    p.setXYZ(i, x, y * Math.cos(a) - z * Math.sin(a), y * Math.sin(a) + z * Math.cos(a));
  }
  return crumple(g, 0.02, seed);
}

/** 细长的木刺 */
export function splinter(seed: number): THREE.BufferGeometry {
  const r = rand(seed);
  const l = 0.4 + r() * 0.3, w = 0.04 + r() * 0.04;
  const pts: P[] = [[-l / 2, 0], [-l * 0.2, w * (0.6 + r() * 0.6)], [l * (0.1 + r() * 0.2), w], [l / 2, r() * w * 0.3], [l * 0.15, -w * (0.5 + r() * 0.5)]];
  return crumple(slab(pts, 0.03 + r() * 0.03), 0.015, seed);
}

/** 不规则的混凝土板块：多边形轮廓挤出厚度，再整体揉一下 */
export function concreteSlab(seed: number): THREE.BufferGeometry {
  const r = rand(seed);
  return crumple(slab(outline(r, 1.3 + r() * 0.4, 0.2), 0.16 + r() * 0.08), 0.09, seed, 0.7);
}
