const rand = (a: number, b: number) => a + Math.random() * (b - a);
/** 影响玩法的随机走「我方武器」流（T117，可设种子）；只管好看的照用 rand */
const fireRand = (a: number, b: number) => a + rng.weapon() * (b - a);

/**
 * 「雷云 · 闪电风暴」数值表（T021-b，策划 `T021-极光闪电风暴-策划案.md` 第 2.4 节默认方案 A「跟车雷云」；id / 类名 / 文件名照旧是 aurora / AuroraUlt；
 * 冷却在 FUSIONS.aurora.cd 里固定 40 秒（T066 翻倍））。原来的幕阵 / 翼阵 / 三角盾 / 子弹拦截全部删除（制作人 2026-10-13「三角盾不用了」）。
 * 时间轴：rise 秒无人机螺旋升空 → form 秒结云（全场压暗、地上出云影）→ storm 秒风暴 → fade 秒散云、无人机回停机架；
 * 落雷范围（cloud）：中心在坦克前方 from → to 米（风暴里匀速推）、x = clamp(坦克 x × follow, ±clampX)，左右半轴 rx × 前后半轴 rz 的椭圆（每多 1 架无人机 +perDrone）；
 * 散雷（strike）：每秒 rate 道（每多 1 架 +perDrone），onFoe 劈云下的敌人（权重：亮瞄准线的反坦克单位 threat、车辆 veh、步兵 1；同一个 repeat 秒内不重复）、其余劈地面，
 *   伤害 dmg、半径 r（边缘 edge），车辆麻痹 stun（精英 stunElite，首领部件无）；云下亮瞄准线的反坦克兵 / 反坦克炮 / 光棱坦克 aimPick 秒内必挨一道、麻痹时这一发瞄准作废；
 * 主雷（main）：每 every 秒一道，劈云下落点价值最高的那个（护甲 + 大路 + 精英 + 扎堆）：中心 dmg、半径 r（边缘 edge）+ 连锁 chainR 米内最近 chain 个各 chainDmg，
 *   麻痹 stun、击退 knock、从天上落下（top：T017-6 的掀飞规则）、小坑 pit、重事件震屏 shake；
 * 聚雷（focus，按住激光出光）：落雷范围换成沿主光束 from～to 米、宽 width 的长条，散雷 ×rate、伤害 ×dmg；引雷针每 rod 秒一道 rodDmg（半径 rodR）劈在光束锁点上；
 * 伤害 × 透镜半效（energy、`ult`）。
 * T057（制作人「乌云太扁，位置也太低，比较丑……应该更宏大」，以下都只是画面 / 镜头 / 声音，上面的数值没动）：
 * - 乌云（sky）：云底离地 base 米（比镜头最高的机位还高，永远是抬头看云底），铺在坦克前方 ahead 米为中心、左右 ±w、前后 ±d 米的一大片（deck 团压扁的云底），
 *   中间往上堆 tower 团到 top 米；每团云按种子翻滚鼓包、云底暗、往上亮一点，闪电劈出来的那一片被照亮（1 次绘制，和原来一样）
 * - 氛围 mood：全场压暗、偏冷蓝，天空换成翻滚的乌云，远处的雾一起变暗，影子变淡（fade 秒进出）；主雷让天光 / 曝光闪 flash [倍数, 秒, 下数]，散雷三道里一道小闪 flashSmall
 * - 雨 rain：镜头看得到的整片地面上每秒这么多根（细斜线，共用光条）；crawl：每隔这么多秒一道雷在云底横着爬（抬头才看得见）
 * - 雷声 thunder：主雷按到镜头的距离晚 [最少, 最多] 秒响（先见光后闻声）
 * - 镜头 reveal：本局第一次 / 之后，压低到 tilt、再仰 lift 弧度看云底，inT 秒仰到位、保持 hold 秒、back 秒缓回（HUD 不变淡）
 */
export const AURORA = {
  drones: 6, perSummon: 1, max: 9, rise: 0.8, form: 0.6, storm: 8, fade: 0.8,
  cloud: { from: 34, to: 58, follow: 0.5, clampX: 6, rx: 16, rz: 22, perDrone: 0.05 },
  strike: { rate: 7, perDrone: 0.7, dmg: 110, r: 2.5, edge: 0.5, stun: 0.5, stunElite: 0.25, onFoe: 0.75, repeat: 0.4, threat: 4, veh: 1.5, aimPick: 0.3 },
  main: { every: 1.25, dmg: 520, r: 6, edge: 0.5, chain: 3, chainR: 12, chainDmg: 180, stun: 0.8, knock: 4, pit: 1 as const, shake: 0.18 },
  focus: { from: 15, to: 75, width: 10, rate: 1.4, dmg: 1.2, rod: 0.4, rodDmg: 260, rodR: 3, morph: 0.25 },
  sky: { base: 58, top: 110, ahead: 85, w: 80, d: 130, deck: 32, tower: 16 },
  mood: { light: 0.45, exposure: 0.9, tint: 0x9fb4d4, tintK: 0.55, fog: 0x39414c, fogK: 0.72, storm: 1, shadow: 0.3, fade: 0.6, out: 0.8 },
  flash: [1.55, 0.24, 3] as [number, number, number],
  flashSmall: [1.18, 0.07, 1] as [number, number, number],
  rain: 320,
  crawl: 0.45,
  thunder: [0.12, 0.6],
  reveal: {
    first: { tilt: -1.3, lift: 0.34, hold: 2.1, inT: 0.7, back: 1 },
    again: { tilt: -1.1, lift: 0.18, hold: 1, inT: 0.5, back: 0.7 },
  },
};

/** 聚雷时外晕跟着激光阶段变色：蓝 / 紫 / 金（旧极光的三色留在这里） */
const STAGE_TINT = [0x6ad8ff, 0xc07aff, 0xffd27a];
/** 劈雷前那团云闪成蓝白（实例色 = 自发光，平时是黑 = 不发光） */
const CLOUD_FLASH = new THREE.Color(0x6e8cc0);
const CLOUD_OFF = new THREE.Color(0, 0, 0);

/** 云影（T057）：贴着地面（和弹坑）的一大块，里面一块块暗斑慢慢飘（噪声），外圈淡出 */
const SHADOW_FRAG = /* glsl */ `
uniform float uTime;
uniform float uFade;
varying vec2 vP;
float h2(vec2 p) { vec3 q = fract(p.xyx * 0.1031); q += dot(q, q.yzx + 33.33); return fract((q.x + q.y) * q.z); }
float n2(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(h2(i), h2(i + vec2(1.0, 0.0)), f.x), mix(h2(i + vec2(0.0, 1.0)), h2(i + vec2(1.0, 1.0)), f.x), f.y);
}
void main() {
  float r = length(vP);
  if (r > 1.0) discard;
  float n = n2(vP * 3.0 + vec2(uTime * 0.12, uTime * 0.07)) * 0.6 + n2(vP * 7.0 - vec2(uTime * 0.2, 0.0)) * 0.4;
  float k = (1.0 - smoothstep(0.55, 1.0, r)) * (0.16 + 0.3 * smoothstep(0.35, 0.75, n)) * uFade;
  if (k < 0.005) discard;
  gl_FragColor = vec4(0.02, 0.03, 0.05, k);
  #include <colorspace_fragment>
}`;

/**
 * 乌云（T057）：每个实例一团云（压扁的二十面体球），顶点按两层噪声往外鼓、慢慢翻滚（种子按实例错开，不吃世界坐标）；
 * 云底暗、往上亮一点；闪电劈出来的地方（uBolt）把附近的云照亮成蓝白；实例色 = 劈雷前那团的自发光；边缘按朝向淡出（看不出球的轮廓），吃雾（远处的云融进乌云天）
 */
const PUFF_VERT = /* glsl */ `
attribute float aSeed;
uniform float uTime;
varying vec3 vN;
varying vec3 vV;
varying vec3 vW;
varying float vUp;
varying vec3 vGlow;
#include <fog_pars_vertex>
float h3(vec3 p) { p = fract(p * 0.1031); p += dot(p, p.zyx + 31.32); return fract((p.x + p.y) * p.z); }
float n3(vec3 p) {
  vec3 i = floor(p);
  vec3 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(mix(h3(i), h3(i + vec3(1.0, 0.0, 0.0)), f.x), mix(h3(i + vec3(0.0, 1.0, 0.0)), h3(i + vec3(1.0, 1.0, 0.0)), f.x), f.y),
             mix(mix(h3(i + vec3(0.0, 0.0, 1.0)), h3(i + vec3(1.0, 0.0, 1.0)), f.x), mix(h3(i + vec3(0.0, 1.0, 1.0)), h3(i + vec3(1.0, 1.0, 1.0)), f.x), f.y), f.z);
}
void main() {
  vec3 p = position;
  float n = n3(p * 1.7 + vec3(aSeed * 7.0, uTime * 0.22, aSeed * 3.0)) * 0.65 + n3(p * 3.9 + vec3(uTime * 0.35, aSeed * 11.0, 0.0)) * 0.35;
  p *= 0.76 + 0.48 * n;
  vec4 w = modelMatrix * instanceMatrix * vec4(p, 1.0);
  vW = w.xyz;
  vec4 mvPosition = viewMatrix * w;
  gl_Position = projectionMatrix * mvPosition;
  vN = normalize(normalMatrix * mat3(instanceMatrix) * normal);
  vUp = normal.y;
  vV = normalize(-mvPosition.xyz);
  vGlow = vec3(0.0);
  #ifdef USE_INSTANCING_COLOR
  vGlow = instanceColor;
  #endif
  #include <fog_vertex>
}`;
const PUFF_FRAG = /* glsl */ `
uniform vec3 uDark;
uniform vec3 uLite;
uniform float uOpacity;
uniform vec4 uBolt;
varying vec3 vN;
varying vec3 vV;
varying vec3 vW;
varying float vUp;
varying vec3 vGlow;
#include <fog_pars_fragment>
void main() {
  float facing = abs(dot(normalize(vN), normalize(vV)));
  vec3 c = mix(uDark, uLite, smoothstep(-0.7, 0.9, vUp));
  float d = length(vW - uBolt.xyz);
  c += vec3(0.5, 0.64, 0.95) * uBolt.w * exp(-d / 28.0) + vGlow;
  float a = uOpacity * smoothstep(0.04, 0.5, facing);
  if (a < 0.01) discard;
  gl_FragColor = vec4(c, a);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
  #include <fog_fragment>
}`;

interface Drone {
  x: number;
  y: number;
  z: number;
  /** 在云里的位置（相对落雷范围的中心，-1..1） */
  u: number;
  v: number;
}

/** 一团云：在云层里的位置（u / v = 相对云层中心的 -1..1，dy = 离云底多高）、大小、劈雷前闪的剩余秒数 */
interface Puff {
  u: number;
  v: number;
  dy: number;
  sx: number;
  sy: number;
  sz: number;
  rot: number;
  flash: number;
}

/** 雷云 · 闪电风暴（激光 + 特斯拉★ + 无人机★）：无人机升空结成跟车往前推的乌云，8 秒里一道道闪电劈向前方的敌人；按住激光 = 雷沿光束劈 */
export class AuroraUlt extends UltBase {
  private stormDuration = AURORA.storm;
  private overload = 1;
  /** 按下后几秒；-1 = 不在生效 */
  private t = -1;
  private drones: Drone[] = [];
  private puffs: Puff[] = [];
  private mesh: THREE.InstancedMesh | null = null;
  private cloud: THREE.InstancedMesh | null = null;
  private shadow: THREE.Mesh<THREE.BufferGeometry, THREE.ShaderMaterial> | null = null;
  /** 云中心（世界坐标）和现在的半轴 */
  private cx = 0;
  private cz = 0;
  private rx = 16;
  private rz = 22;
  private strikeAcc = 0;
  private mainT = 0;
  private rodT = 0;
  private rainAcc = 0;
  private focusK = 0;
  /** 氛围改过（被 clear 打断时下一帧退回平时） */
  private dimOn = false;
  private revealed = false;
  /** 乌云层的中心（世界坐标，跟着坦克往前走）、云底横爬的雷 / 远处闷雷的计时、起风扬尘放过没有 */
  private deckX = 0;
  private deckZ = 0;
  private crawlT = 0;
  private rumbleT = 0;
  private gusted = false;
  /** 云里被闪电照亮的那一片（xyz = 位置，w = 亮度，每帧往下退） */
  private readonly glow = new THREE.Vector4();
  private readonly c = new THREE.Color();
  private readonly lastHit = new WeakMap<Enemy, number>();
  /** 诊断：本次散雷 / 主雷 / 引雷针道数、打断反坦克瞄准几次 */
  strikes = 0;
  mains = 0;
  rods = 0;
  breaks = 0;
  private readonly m = new THREE.Matrix4();
  private readonly q = new THREE.Quaternion();
  private readonly e = new THREE.Euler();
  private readonly s = new THREE.Vector3(1, 1, 1);
  private readonly p = new THREE.Vector3();
  private readonly v = new THREE.Vector3();

  /** 预览：前方 34 米、左右 16 × 前后 22 米的椭圆 */
  preview(ctx: UltContext): UltPreview {
    const C = AURORA.cloud;
    const P = ctx.tank.group.position;
    return { x: THREE.MathUtils.clamp(P.x * C.follow, -C.clampX, C.clampX), z: P.z - C.from, r: C.rx, rz: C.rz };
  }

  protected override activeLabel(): string {
    const T = AURORA;
    if (this.t < T.rise) return '升空';
    if (this.t < T.rise + T.form) return '结云';
    const end = T.rise + T.form + this.stormDuration;
    if (this.t < end) return `雷暴 ${Math.max(1, Math.ceil(end - this.t))}`;
    return '收队';
  }

  protected fire(ctx: UltContext): void {
    const T = AURORA;
    this.clear();
    const { count: n, damage } = summonBatch(T.drones, ctx.mods.summon, T.max);
    this.overload = damage;
    this.stormDuration = T.storm * summonDuration(ctx.mods);
    this.drones = Array.from({ length: n }, (_, i) => {
      const h = this.rack(ctx, i);
      const a = (i / n) * Math.PI * 2;
      return { x: h.x, y: h.y, z: h.z, u: Math.cos(a) * 0.55, v: Math.sin(a) * 0.55 };
    });
    const k = 1 + T.cloud.perDrone * (n - T.drones);
    this.rx = T.cloud.rx * k;
    this.rz = T.cloud.rz * k;
    // 乌云层（T057）：云底一大片压扁的云团（4 列 × 8 排，错开摆），中间往上堆一摞
    const S = T.sky;
    const deck = Array.from({ length: S.deck }, (_, i): Puff => {
      const col = i % 4;
      const row = Math.floor(i / 4);
      const r = rand(17, 27);
      const sy = r * rand(0.32, 0.46);
      return { u: -0.82 + col * 0.55 + rand(-0.2, 0.2) + (row % 2) * 0.2, v: -0.92 + row * 0.26 + rand(-0.08, 0.08), dy: sy * 0.55 + rand(-1.5, 2.5), sx: r * rand(0.9, 1.25), sy, sz: r, rot: Math.random() * 6.28, flash: 0 };
    });
    const tower = Array.from({ length: S.tower }, (_, i): Puff => {
      const k2 = i / (S.tower - 1);
      const r = rand(15, 25) * (1 - 0.3 * k2);
      return { u: rand(-0.45, 0.45) * (1 - 0.5 * k2), v: rand(-0.55, 0.15), dy: 8 + k2 * (S.top - S.base - 14), sx: r * rand(0.95, 1.3), sy: r * rand(0.62, 0.9), sz: r, rot: Math.random() * 6.28, flash: 0 };
    });
    this.puffs = [...deck, ...tower];
    this.crawlT = T.crawl;
    this.rumbleT = 1.2;
    this.gusted = false;
    this.glow.set(0, -999, 0, 0);
    this.t = 0;
    this.strikeAcc = 0;
    this.mainT = T.main.every * 0.5;
    this.rodT = 0;
    this.focusK = 0;
    this.strikes = this.mains = this.rods = this.breaks = 0;
    this.active = T.rise + T.form + this.stormDuration + T.fade;
    this.ensureMeshes(ctx);
    this.mesh!.count = n;
    this.mesh!.visible = true;
    this.cloud!.visible = true;
    this.shadow!.visible = true;
    this.place(ctx);
    // 镜头（T057）：压低、抬头看云底——本局第一次 2.1 秒看乌云压城、第一道主雷劈下来，之后短抬头；HUD 不变淡（首领亮相 / 核弹镜头优先，cinema 已有规则）
    const R = this.revealed ? T.reveal.again : T.reveal.first;
    this.revealed = true;
    ctx.cinema(R.tilt, R.hold + 0.2, R.back, false);
    ctx.lookUp(R.lift, R.hold, R.back, R.inT);
    ctx.audio.play('launch', 0.6);
    ctx.audio.play('zap', 0.6, 0.8);
  }

  private ensureMeshes(ctx: UltContext): void {
    const T = AURORA;
    if (!this.mesh) {
      // 特斯拉无人机：扁圆机身 + 一圈铜线圈 + 顶上蓝色电球（合并 1 次绘制，实例化）
      const g = ctx.geo.merged('ult-aurora-tesla-drone', (): PartSpec[] => [
        { geo: new THREE.CylinderGeometry(0.42, 0.5, 0.18, 10), color: 0x3a3e42 },
        { geo: new THREE.TorusGeometry(0.46, 0.07, 5, 12), color: 0xb5653a, pos: [0, 0.06, 0], rot: [Math.PI / 2, 0, 0] },
        { geo: new THREE.CylinderGeometry(0.06, 0.08, 0.22, 6), color: 0x1e1e1e, pos: [0, 0.2, 0] },
        { geo: new THREE.SphereGeometry(0.16, 8, 6), color: 0xbfeeff, pos: [0, 0.38, 0] },
        ...[0, 1, 2, 3].map((i): PartSpec => ({ geo: new THREE.BoxGeometry(0.6, 0.04, 0.08), color: 0x1e1e1e, pos: [0, -0.04, 0], rot: [0, (i * Math.PI) / 4, 0] })),
      ]);
      this.mesh = new THREE.InstancedMesh(g, MAT.painted, T.max);
      this.mesh.frustumCulled = false;
      ctx.scene.add(this.mesh);
    }
    if (!this.cloud) {
      // 乌云（T057）：48 团翻滚的云（实例化 1 次绘制，和原来的 28 团一样是 1 次），每团一个种子；实例色 = 劈雷前那团的自发光
      const count = T.sky.deck + T.sky.tower;
      const geo = new THREE.IcosahedronGeometry(1, 2);
      geo.setAttribute('aSeed', new THREE.InstancedBufferAttribute(Float32Array.from({ length: count }, () => Math.random()), 1));
      const mat = new THREE.ShaderMaterial({
        vertexShader: PUFF_VERT,
        fragmentShader: PUFF_FRAG,
        uniforms: THREE.UniformsUtils.merge([THREE.UniformsLib.fog, {
          uTime: { value: 0 },
          uOpacity: { value: 0 },
          uDark: { value: new THREE.Color(0x15191f) },
          uLite: { value: new THREE.Color(0x4c5562) },
          uBolt: { value: new THREE.Vector4() },
        }]),
        transparent: true,
        depthWrite: false,
        fog: true,
      });
      // UniformsUtils.merge 会复制一份：闪电照亮那一片直接指回 this.glow
      mat.uniforms.uBolt.value = this.glow;
      this.cloud = new THREE.InstancedMesh(geo, mat, count);
      this.cloud.frustumCulled = false;
      this.cloud.renderOrder = 5;
      for (let i = 0; i < count; i++) this.cloud.setColorAt(i, CLOUD_OFF);
      ctx.scene.add(this.cloud);
    }
    if (!this.shadow) {
      this.shadow = new THREE.Mesh(
        new THREE.RingGeometry(0.001, 1, 40, 8).rotateX(-Math.PI / 2),
        new THREE.ShaderMaterial({
          vertexShader: DRAPE_VERT,
          fragmentShader: SHADOW_FRAG,
          uniforms: { uTime: { value: 0 }, uFade: { value: 0 }, uDrape: { value: 1 }, ...ctx.fx.craterU },
          transparent: true,
          depthWrite: false,
        }),
      );
      this.shadow.renderOrder = 1;
      this.shadow.frustumCulled = false;
      ctx.scene.add(this.shadow);
    }
  }

  /** 停机架上第 i 架的位置（世界坐标） */
  private rack(ctx: UltContext, i: number): THREE.Vector3 {
    return ctx.tank.turretPoint(...auroraRack(i), this.v).clone();
  }

  protected step(ctx: UltContext): void {
    if (this.t < 0) {
      // 被 clear 打断（读档 / 重开 / 调试）：氛围退回平时
      if (this.dimOn) {
        this.dimOn = false;
        ctx.mood(null, AURORA.mood.out);
      }
      return;
    }
    const T = AURORA;
    const dt = ctx.dt;
    this.t += dt;
    const t = this.t;
    const formEnd = T.rise + T.form;
    const stormEnd = formEnd + this.stormDuration;
    const end = stormEnd + T.fade;
    // 云跟车：中心从 from 匀速推到 to（风暴 8 秒里），x 跟着走位偏一半
    const P = ctx.tank.group.position;
    const C = T.cloud;
    const k = THREE.MathUtils.clamp((t - formEnd) / this.stormDuration, 0, 1);
    this.cx = THREE.MathUtils.clamp(P.x * C.follow, -C.clampX, C.clampX);
    this.cz = P.z - (C.from + (C.to - C.from) * k);
    // 云的浓淡：结云 0 → 1，散云 1 → 0
    const dens = t < T.rise ? 0 : t < formEnd ? (t - T.rise) / T.form : t < stormEnd ? 1 : Math.max(0, 1 - (t - stormEnd) / T.fade);
    // 结云：全场压暗偏冷蓝、天空换成乌云、远处的雾变暗、影子变淡（升空一半就开始，镜头抬头时看着天黑下来）；一阵闷雷 + 起风扬尘
    if (t >= T.rise * 0.4 && !this.dimOn && t < stormEnd) {
      this.dimOn = true;
      const M = T.mood;
      ctx.mood({ light: M.light, exposure: M.exposure, tint: M.tint, tintK: M.tintK, fog: M.fog, fogK: M.fogK, storm: M.storm, shadow: M.shadow }, M.fade);
      ctx.rumble(0.25, 1.2);
      ctx.audio.play('thunder', 0.55, 0.55, 0.15);
    }
    if (!this.gusted && t >= T.rise) {
      this.gusted = true;
      this.gust(ctx);
    }
    // 雨过天晴：散云时氛围退回平时
    if (t >= stormEnd && this.dimOn) {
      this.dimOn = false;
      ctx.mood(null, T.mood.out);
    }
    this.place(ctx, dens);
    if (t >= formEnd && t < stormEnd) this.storm(ctx);
    if (t >= end) {
      this.end(ctx);
      return;
    }
    this.active = Math.max(0.05, end - t);
  }

  /** 风暴的每一帧：散雷 / 主雷 / 反坦克优先 / 聚雷 + 引雷针 / 雨丝 */
  private storm(ctx: UltContext): void {
    const T = AURORA;
    const dt = ctx.dt;
    const P = ctx.tank.group.position;
    const n = this.drones.length;
    const beam = ctx.beam();
    this.focusK = THREE.MathUtils.clamp(this.focusK + (beam !== null ? dt : -dt) / T.focus.morph, 0, 1);
    const focus = this.focusK >= 0.5 && beam !== null;
    const lens = ultHalf(ctx.mods.energy) * this.overload;
    const S = T.strike;
    const inArea = focus ? (x: number, z: number, pad = 0) => this.inStrip(ctx, beam!, x, z, pad) : (x: number, z: number, pad = 0) => this.inCloud(x, z, pad);
    const foes = ctx.enemies.filter((e) => e.alive && inArea(e.group.position.x, e.group.position.z, e.radius));
    const tint = focus ? STAGE_TINT[ctx.beamStage()] : undefined;
    const dmgK = focus ? T.focus.dmg : 1;
    // 反坦克优先：云下亮瞄准线的反坦克兵 / 反坦克炮 / 光棱坦克，这一刻还没挨过雷的马上劈一道（必在 aimPick 秒内）
    for (const e of foes) {
      if (!e.aiming || !e.spec.telegraph || e.controller) continue;
      if (ctx.time - (this.lastHit.get(e) ?? -9) < S.aimPick) continue;
      this.scatter(ctx, e, e.group.position.x, e.group.position.z, lens * dmgK, tint);
    }
    // 散雷
    this.strikeAcc += dt * (S.rate + S.perDrone * Math.max(0, n - T.drones)) * (focus ? T.focus.rate : 1);
    while (this.strikeAcc >= 1) {
      this.strikeAcc -= 1;
      const pool = foes.filter((e) => e.alive && ctx.time - (this.lastHit.get(e) ?? -9) >= S.repeat);
      if (pool.length && rng.weapon() < S.onFoe) {
        const w = pool.map((e) => (e.aiming && e.spec.telegraph ? S.threat : e.armor === 'none' ? 1 : S.veh));
        let r = rng.weapon() * w.reduce((a, b) => a + b, 0);
        let pick = pool[0];
        for (let i = 0; i < pool.length; i++) {
          r -= w[i];
          if (r <= 0) {
            pick = pool[i];
            break;
          }
        }
        this.scatter(ctx, pick, pick.group.position.x, pick.group.position.z, lens * dmgK, tint);
      } else {
        const g = focus ? this.stripPoint(ctx, beam!) : this.cloudPoint();
        this.scatter(ctx, null, g.x, g.z, lens * dmgK, tint);
      }
    }
    // 主雷：每 every 秒劈一道落点价值最高的
    this.mainT -= dt;
    if (this.mainT <= 0) {
      this.mainT += T.main.every;
      const best = this.bestTarget(foes);
      if (best) this.mainStrike(ctx, best, lens, tint);
      else {
        const g = focus ? this.stripPoint(ctx, beam!) : this.cloudPoint();
        this.mainAt(ctx, g.x, g.z, lens, tint, null);
      }
    }
    // 引雷针：聚雷时每 rod 秒一道劈在光束锁点上（「雷沿光束劈下来」）
    if (focus) {
      this.rodT -= dt;
      const lock = ctx.beamLock();
      if (this.rodT <= 0 && lock) {
        this.rodT = T.focus.rod;
        this.rods += 1;
        const F = T.focus;
        const y = ctx.fx.groundAt(lock.x, lock.z);
        ctx.streaks.arc(lock.x + rand(-2, 2), this.cloudY(), lock.z + rand(-2, 2), lock.x, y + 0.2, lock.z, 'strike', { tint, scale: 1.1 });
        ctx.fx.electric(lock.x, y + 1, lock.z, 8, true);
        for (const e of ctx.enemies) {
          if (!e.alive) continue;
          const d = Math.hypot(e.group.position.x - lock.x, e.group.position.z - lock.z);
          if (d > F.rodR + e.radius) continue;
          ctx.damage(e, F.rodDmg * lens * (1 - 0.5 * Math.min(1, d / F.rodR)), lock.x, lock.z, { type: 'energy', kind: 'elec', summon: true, ult: true });
          this.stun(e, S.stun);
        }
      }
    }
    // 雨（T057）：镜头看得到的整片地面上每秒 rain 根细斜线（共用 Streaks，不加绘制），被风吹斜
    this.rainAcc += dt * T.rain;
    const cam = ctx.camPos();
    while (this.rainAcc >= 1) {
      this.rainAcc -= 1;
      const x = cam.x + rand(-26, 26);
      const z = P.z + rand(-95, 6);
      const y = ctx.fx.groundAt(x, z) + rand(1, 26);
      ctx.streaks.add(x, y, z, x + 0.9, y - 3.2, z + 0.35, 0.045, 0xc8d8ea, 0.2, 0.16, 1);
    }
    // 云底横着爬的雷（抬头看得见）：两团云之间一道，那一片云亮一下
    this.crawlT -= dt;
    if (this.crawlT <= 0) {
      this.crawlT = T.crawl * rand(0.6, 1.4);
      const a = this.puffAt(Math.floor(Math.random() * T.sky.deck), new THREE.Vector3());
      const b = this.puffAt(Math.floor(Math.random() * T.sky.deck), new THREE.Vector3());
      if (a.distanceTo(b) > 25) {
        ctx.streaks.arc(a.x, a.y, a.z, b.x, b.y, b.z, 'strike', { tint: 0x9fc8ff, scale: 0.7, long: true });
        this.lightUp(a.x, a.y, a.z, 0.6);
        ctx.skyBolt(a.x, a.z, 0.4);
      }
    }
    // 远处的闷雷（不管劈没劈）
    this.rumbleT -= dt;
    if (this.rumbleT <= 0) {
      this.rumbleT = rand(1.4, 2.4);
      ctx.audio.play('thunder', rand(0.25, 0.4), 0.5, rand(0.2, 0.6));
    }
  }

  /** 一道散雷：劈在 e（null = 地面 (x, z)）：半径 r 米 dmg（边缘 edge）+ 麻痹；落点 2.5 米内的景物按「电」，每道最多 1 件 */
  private scatter(ctx: UltContext, e: Enemy | null, x: number, z: number, k: number, tint?: number): void {
    const S = AURORA.strike;
    this.strikes += 1;
    const gy = ctx.fx.groundAt(x, z);
    const hy = e ? 1.2 * e.size + gy : gy + 0.2;
    const from = this.flashPuff(x, z);
    // 从云底劈下来、穿过整个画面（T057：长雷多分段）；三道里一道让天光小闪一下
    ctx.streaks.arc(from.x, from.y, from.z, x, hy, z, 'strike', { tint, scale: 0.85, long: true });
    if (ctx.fx.glow.active < 1800) ctx.fx.electric(x, hy, z, 6, true);
    this.lightUp(from.x, from.y, from.z, 0.45);
    if (Math.random() < 0.33) ctx.boltFlash(...AURORA.flashSmall);
    for (const f of ctx.enemies) {
      if (!f.alive) continue;
      const d = Math.hypot(f.group.position.x - x, f.group.position.z - z);
      if (d > S.r + f.radius) continue;
      this.lastHit.set(f, ctx.time);
      ctx.damage(f, S.dmg * k * (1 - S.edge * Math.min(1, d / S.r)), x, z - 0.5, { type: 'energy', kind: 'elec', summon: true, ult: true });
      if (f.armor !== 'none') this.stun(f, f.spec.blocker ? S.stunElite : S.stun);
      else this.stun(f, S.stun);
    }
    const p = ctx.scenery.strike(x, z, S.r);
    if (p && Math.random() < 0.5) ctx.streaks.arc(x, hy, z, p.x, p.y, p.z, 'grid', { tint });
    if (Math.random() < 0.35) ctx.audio.play('zap', 0.45, 0.9);
  }

  /** 主雷：劈中 e，再连锁 chainR 米内最近的 chain 个 */
  private mainStrike(ctx: UltContext, e: Enemy, lens: number, tint?: number): void {
    const M = AURORA.main;
    const x = e.group.position.x;
    const z = e.group.position.z;
    this.mainAt(ctx, x, z, lens, tint, e);
    const near = ctx.enemies
      .filter((f) => f.alive && f !== e && Math.hypot(f.group.position.x - x, f.group.position.z - z) < M.chainR)
      .sort((a, b) => Math.hypot(a.group.position.x - x, a.group.position.z - z) - Math.hypot(b.group.position.x - x, b.group.position.z - z))
      .slice(0, M.chain);
    let px = x;
    let py = ctx.fx.groundAt(x, z) + 1.3;
    let pz = z;
    for (const f of near) {
      const fy = ctx.fx.groundAt(f.group.position.x, f.group.position.z) + 1.2 * f.size;
      ctx.streaks.arc(px, py, pz, f.group.position.x, fy, f.group.position.z, 'evo', { tint });
      ctx.fx.electric(f.group.position.x, fy, f.group.position.z, 8, true);
      ctx.damage(f, M.chainDmg * lens, px, pz, { type: 'energy', kind: 'elec', summon: true, ult: true });
      this.stun(f, M.stun);
      px = f.group.position.x;
      py = fy;
      pz = f.group.position.z;
    }
  }

  /** 主雷落地：最粗一档闪电 + 白闪 + 冲击环 + 小坑 + 点光源 + 重事件震屏；爆炸带 top（天上落下来的：载具掀翻 / 掀飞）、energy（景物按「切」：树 / 杆劈断，房子开顶洞） */
  private mainAt(ctx: UltContext, x: number, z: number, lens: number, tint: number | undefined, e: Enemy | null): void {
    const M = AURORA.main;
    this.mains += 1;
    const gy = ctx.fx.groundAt(x, z);
    const from = this.flashPuff(x, z, true);
    // 最粗的一道从 58 米高的云底劈穿整个画面，旁边再跟一道细的（T057：长雷多分段、分叉更长）
    ctx.streaks.arc(from.x, from.y, from.z, x, gy + 0.2, z, 'storm', { tint, long: true });
    ctx.streaks.arc(from.x + rand(-5, 5), from.y, from.z + rand(-5, 5), x + rand(-1, 1), gy + 0.2, z + rand(-1, 1), 'strike', { tint, long: true });
    ctx.explode(x, z, M.r, M.dmg * lens, { type: 'energy', kind: 'blast', summon: true, ult: true, knock: M.knock, top: true, pit: M.pit, hit: e ?? undefined, hitMul: 1 });
    if (e?.alive) this.stun(e, M.stun);
    ctx.fx.glow.emit({ x, y: gy + 2, z, life: 0.25, size: 9, size1: 14, color: 0xe8f6ff, color1: 0x4aa0ff, alpha: 0.9, frame: 0 });
    // 雷劈下来那一截空气发亮（落点往上一根光柱）
    for (let i = 0; i < 3; i++) ctx.fx.glow.emit({ x, y: gy + 3 + i * 4.5, z, life: 0.18, size: 4.5 - i, size1: 2, color: 0xdff0ff, color1: 0x5a9cff, alpha: 0.7, frame: 0 });
    ctx.fx.shockwave(x, z, M.r * 1.4, 0xbfe6ff, 0.35);
    ctx.fx.flash(x, 10, z, 5000, 0xbcd8ff);
    // 落点冒几秒白汽（雨里被雷劈过的地）
    ctx.fx.burn(x + rand(-1, 1), z + rand(-1, 1), 0.7, 4, false);
    ctx.flash(0.12);
    // 整片战场被照亮：天光 / 曝光「啪—啪—啪」闪三下，天上那片云、云里那一团一起亮
    ctx.boltFlash(...AURORA.flash);
    ctx.skyBolt(x, z, 1);
    this.lightUp(from.x, from.y, from.z, 1.4);
    ctx.shake(M.shake);
    ctx.audio.play('explode', 0.8);
    ctx.audio.play('zap', 1, 0.7);
    // 雷声按到镜头的距离晚一拍（先见光后闻声）
    const cam = ctx.camPos();
    const [d0, d1] = AURORA.thunder;
    ctx.audio.play('thunder', 0.85, 1, THREE.MathUtils.clamp((Math.hypot(x - cam.x, z - cam.z) / 340) * 1.6, d0, d1));
  }

  /** 起风（结云那一下）：一阵贴地往侧面卷的尘土扫过整个画面 */
  private gust(ctx: UltContext): void {
    const P = ctx.tank.group.position;
    for (let i = 0; i < 18; i++) {
      const x = P.x - 30 + rand(-6, 6);
      const z = P.z - rand(-4, 70);
      ctx.fx.smokeP.emit({ x, y: ctx.fx.groundAt(x, z) + rand(0.4, 1.6), z, vx: rand(18, 26), vy: rand(0.2, 1), vz: rand(-2, 2), life: rand(2, 3), size: rand(1.5, 2.5), size1: rand(4, 6), color: 0x8a8070, color1: 0x5a5650, alpha: 0.35, frame: 1, drag: 0.8, spin: rand(-0.5, 0.5) });
    }
  }

  /** 云里那一片被闪电照亮（k = 亮度，取大的；每帧往下退） */
  private lightUp(x: number, y: number, z: number, k: number): void {
    if (k < this.glow.w) return;
    this.glow.set(x, y, z, k);
  }

  /** 麻痹：车辆 / 步兵 stun 秒（精英由调用方给短的），首领部件无；亮着瞄准线的反坦克单位这一发作废（重新瞄） */
  private stun(e: Enemy, sec: number): void {
    if (!e.alive || e.controller) return;
    e.stunTime = Math.max(e.stunTime, sec);
    if (e.aiming) {
      e.aiming = false;
      e.laser.visible = false;
      if (e.spec.telegraph) e.fireTimer = Math.max(e.fireTimer, 1.3);
      this.breaks += 1;
    }
  }

  /** 云下落点价值最高的那个（护甲 3 / 1.5 / 0.3 × 大路 1.5 / 田野 0.6 × 精英 3 + 6 米内邻居的分） */
  private bestTarget(foes: Enemy[]): Enemy | null {
    const val = (e: Enemy) => (e.armor === 'heavy' ? 3 : e.armor === 'light' ? 1.5 : 0.3) * (Math.abs(e.group.position.x) <= 13 ? 1.5 : 0.6) * (e.spec.blocker || e.controller ? 3 : 1);
    let best: Enemy | null = null;
    let bs = 0;
    for (const e of foes) {
      let s = val(e);
      for (const f of foes) if (f !== e && Math.hypot(f.group.position.x - e.group.position.x, f.group.position.z - e.group.position.z) < 6) s += val(f) * 0.5;
      if (s > bs) {
        bs = s;
        best = e;
      }
    }
    return best;
  }

  private inCloud(x: number, z: number, pad = 0): boolean {
    const u = (x - this.cx) / (this.rx + pad);
    const v = (z - this.cz) / (this.rz + pad);
    return u * u + v * v <= 1;
  }

  /** 聚雷长条：沿主光束 from～to 米、宽 width（按光束实际角度） */
  private inStrip(ctx: UltContext, beam: number, x: number, z: number, pad = 0): boolean {
    const F = AURORA.focus;
    const P = ctx.tank.group.position;
    const dx = -Math.sin(beam);
    const dz = -Math.cos(beam);
    const rx = x - P.x;
    const rz = z - P.z;
    const along = rx * dx + rz * dz;
    const lat = Math.abs(rx * -dz + rz * dx);
    return along >= F.from - pad && along <= F.to + pad && lat <= F.width / 2 + pad;
  }

  private cloudPoint(): { x: number; z: number } {
    const a = rng.weapon() * Math.PI * 2;
    const r = Math.sqrt(rng.weapon());
    return { x: this.cx + Math.cos(a) * r * this.rx, z: this.cz + Math.sin(a) * r * this.rz };
  }

  private stripPoint(ctx: UltContext, beam: number): { x: number; z: number } {
    const F = AURORA.focus;
    const P = ctx.tank.group.position;
    const d = fireRand(F.from, F.to);
    const l = fireRand(-F.width / 2, F.width / 2);
    return { x: P.x - Math.sin(beam) * d - Math.cos(beam) * l, z: P.z - Math.cos(beam) * d + Math.sin(beam) * l };
  }

  /** 云底多高（引雷针 / 落雷从这里劈下来） */
  private cloudY(): number {
    return AURORA.sky.base - 1;
  }

  /** 第 i 团云现在的中心（世界坐标） */
  private puffAt(i: number, out = this.p): THREE.Vector3 {
    const S = AURORA.sky;
    const p = this.puffs[i];
    return out.set(this.deckX + p.u * S.w, S.base + p.dy - p.sy * 0.6, this.deckZ + p.v * S.d);
  }

  /** 雷从哪团云劈出来：落点上方离得最近的那团云底（偏到落点这边、高度 = 云底），劈出前那团闪成蓝白 */
  private flashPuff(x: number, z: number, big = false): THREE.Vector3 {
    const S = AURORA.sky;
    let best = -1;
    let bd = Infinity;
    for (let i = 0; i < S.deck; i++) {
      const p = this.puffs[i];
      const d = Math.hypot(this.deckX + p.u * S.w - x, this.deckZ + p.v * S.d - z);
      if (d < bd) {
        bd = d;
        best = i;
      }
    }
    if (best >= 0) this.puffs[best].flash = big ? 0.18 : 0.1;
    const q = best >= 0 ? this.puffAt(best) : this.p.set(x, 0, z);
    // 雷从云底斜着劈下来（起点往落点挪六成，不要一根竖直的棍）
    return this.p.set(q.x + (x - q.x) * 0.6 + rand(-4, 4), this.cloudY() - rand(0, 2), q.z + (z - q.z) * 0.6 + rand(-4, 4));
  }

  /** 无人机 / 云团 / 云影的实例矩阵 */
  private place(ctx: UltContext, dens = 0): void {
    const T = AURORA;
    const t = this.t;
    const alt = this.cloudY() - 2;
    const formEnd = T.rise + T.form;
    const stormEnd = formEnd + this.stormDuration;
    // 乌云层跟着坦克往前走（横向跟镜头一样只跟一半）
    const P = ctx.tank.group.position;
    this.deckX = P.x * 0.55;
    this.deckZ = P.z - T.sky.ahead;
    this.drones.forEach((d, i) => {
      const h = this.rack(ctx, i);
      const sx = this.cx + d.u * this.rx;
      const sz = this.cz + d.v * this.rz;
      let x: number;
      let y: number;
      let z: number;
      if (t < T.rise) {
        // 螺旋升空
        const k = t / T.rise;
        const a = k * Math.PI * 3 + i;
        x = h.x + (sx - h.x) * k * k + Math.cos(a) * 2 * (1 - k);
        z = h.z + (sz - h.z) * k * k + Math.sin(a) * 2 * (1 - k);
        y = h.y + (alt - h.y) * Math.sin((k * Math.PI) / 2);
        if (Math.random() < 0.6) ctx.streaks.add(d.x, d.y, d.z, x, y, z, 0.12, 0x7cc8ff, 0.7, 0.18);
      } else if (t < stormEnd) {
        x = sx + Math.sin(t * 0.8 + i) * 2;
        y = alt - 1 + Math.sin(t * 1.3 + i * 2) * 0.6;
        z = sz + Math.cos(t * 0.7 + i) * 2;
      } else {
        // 俯冲回停机架
        const k = Math.min(1, (t - stormEnd) / T.fade);
        x = sx + (h.x - sx) * k;
        y = alt + (h.y - alt) * k;
        z = sz + (h.z - sz) * k;
      }
      if (Math.random() < 0.15) ctx.fx.glow.emit({ x, y: y + 0.3, z, life: 0.06, size: 0.9, size1: 0.3, color: 0xcfeaff, frame: 0 });
      d.x = x;
      d.y = y;
      d.z = z;
      this.q.setFromEuler(this.e.set(0, t * 3 + i, 0));
      this.mesh!.setMatrixAt(i, this.m.compose(this.p.set(x, y, z), this.q, this.s.set(1, 1, 1)));
    });
    this.mesh!.instanceMatrix.needsUpdate = true;
    // 乌云层（T057）：结云时从中间往外铺开、一团团胀起来（0.3 → 1 倍），散云时变薄；每团慢慢转、轻轻起伏
    const cloud = this.cloud!;
    const S = T.sky;
    const grow = 0.3 + 0.7 * dens;
    const spread = 0.55 + 0.45 * dens;
    const dt = ctx.dt;
    this.puffs.forEach((p, i) => {
      if (p.flash > 0) p.flash = Math.max(0, p.flash - dt);
      const breathe = 1 + 0.04 * Math.sin(t * 0.7 + i * 1.3);
      this.q.setFromEuler(this.e.set(0, p.rot + t * 0.04, 0));
      this.s.set(p.sx * grow * breathe, p.sy * (0.6 + 0.4 * dens), p.sz * grow * breathe);
      cloud.setMatrixAt(i, this.m.compose(this.p.set(this.deckX + p.u * S.w * spread, S.base + p.dy, this.deckZ + p.v * S.d * spread), this.q, this.s));
      cloud.setColorAt(i, p.flash > 0 ? this.c.copy(CLOUD_FLASH).multiplyScalar(p.flash / 0.18) : CLOUD_OFF);
    });
    cloud.instanceMatrix.needsUpdate = true;
    if (cloud.instanceColor) cloud.instanceColor.needsUpdate = true;
    const mat = cloud.material as THREE.ShaderMaterial;
    mat.uniforms.uOpacity.value = 0.94 * dens;
    mat.uniforms.uTime.value = t;
    // 云里被照亮的那一片很快退掉
    this.glow.w = this.glow.w < 0.02 ? 0 : this.glow.w * Math.exp(-dt * 12);
    cloud.visible = dens > 0.01;
    this.s.set(1, 1, 1);
    // 云影（T057）：盖住落雷范围外面一大圈，暗斑慢慢飘
    const sh = this.shadow!;
    sh.position.set(this.cx, 0.12, this.cz);
    sh.scale.set(this.rx * 2.8, 1, this.rz * 2.6);
    sh.material.uniforms.uTime.value = t;
    sh.material.uniforms.uFade.value = dens;
  }

  private end(ctx: UltContext): void {
    this.t = -1;
    if (this.dimOn) ctx.mood(null, AURORA.mood.out);
    this.dimOn = false;
    this.hide();
    this.finish();
  }

  private hide(): void {
    if (this.mesh) this.mesh.visible = false;
    if (this.cloud) this.cloud.visible = false;
    if (this.shadow) this.shadow.visible = false;
  }

  protected clear(): void {
    this.t = -1;
    this.hide();
  }

  override dispose(): void {
    super.dispose();
    for (const o of [this.mesh, this.cloud, this.shadow]) {
      if (!o) continue;
      o.removeFromParent();
      (o.material as THREE.Material).dispose();
    }
    this.mesh?.dispose();
    this.cloud?.dispose();
    this.shadow?.geometry.dispose();
    this.mesh = null;
    this.cloud = null;
    this.shadow = null;
  }
}
