/** 两点之间一根方梁（截面 w × h，长轴沿 a → b） */
function strut(a: [number, number, number], b: [number, number, number], w: number, h: number, color: number): PartSpec {
  const d = v1.set(b[0] - a[0], b[1] - a[1], b[2] - a[2]);
  const len = d.length();
  eA.setFromQuaternion(qA.setFromUnitVectors(X_AXIS, d.normalize()));
  return { geo: box(len, h, w), color, pos: [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2, (a[2] + b[2]) / 2], rot: [eA.x, eA.y, eA.z] };
}

/** 平板（xy 平面的多边形沿 z 拉出厚度 t，中心在 z = 0）：尾翼、舵 */
function slab(pts: V2[], t: number): THREE.BufferGeometry {
  const g = new THREE.ExtrudeGeometry(new THREE.Shape(pts.map(([x, y]) => new THREE.Vector2(x, y))), { depth: t, bevelEnabled: false });
  g.translate(0, 0, -t / 2);
  return g;
}

/** 16 边形截面（平板拼接，上下左右各是一块平面） */
const SIDES = 16;
function ring(r: number): V2[] {
  return Array.from({ length: SIDES }, (_, i) => {
    const a = ((i + 0.5) / SIDES) * Math.PI * 2;
    return [Math.cos(a) * r, Math.sin(a) * r] as V2;
  });
}

/** 沿艇身 x 方向的一段棱柱：x0 处半径 r0 → x1 处半径 r1（frustum 沿 y 建，再转到 x） */
function hullSeg(x0: number, x1: number, r0: number, r1: number, color: number): PartSpec {
  return { geo: frustum(ring(r0), ring(r1), x1 - x0, 0), color, pos: [x0, 0, 0], rot: [0, 0, -Math.PI / 2] };
}

/** 艇身半径轮廓（艇尾 → 艇首）：平直的中段 + 折线收尾，不做圆鼓鼓的曲面（T096 建模语言） */
const PROFILE: [number, number][] = [[-125, 3], [-121, 7], [-114, 11.5], [-104, 15], [-90, 17.4], [-75, 18], [75, 18], [90, 17.4], [104, 15.4], [114, 12.4], [120, 8.6], [124, 4.6], [125.6, 1.4]];
function hullR(x: number): number {
  for (let i = 1; i < PROFILE.length; i++) {
    const [xa, ra] = PROFILE[i - 1];
    const [xb, rb] = PROFILE[i];
    if (x <= xb) return ra + ((rb - ra) * (x - xa)) / (xb - xa);
  }
  return PROFILE[PROFILE.length - 1][1];
}
/** 平面离中心多远（16 边形内切圆） */
const FLAT = Math.cos(Math.PI / SIDES);

/** 艇身：棱柱段 + 12 道装甲环带 + 环带铆钉 + 纵向板缝 + 分块装甲板 + 背脊走道 + 指挥吊舱 + 4 个升力短舱 + 十字尾翼 + 尾部外伸梁 + 压舱水排口 */
function hullParts(): PartSpec[] {
  const p: PartSpec[] = [];
  // 棱柱段：中段每 25 米一段，两种钢灰交替（分块迷彩）
  const xs = [-125, -121, -114, -104, -90, -75, -50, -25, 0, 25, 50, 75, 90, 104, 114, 120, 124, 125.6];
  for (let i = 1; i < xs.length; i++) p.push(hullSeg(xs[i - 1], xs[i], hullR(xs[i - 1]), hullR(xs[i]), i % 2 ? STEEL : STEEL_B));
  // 12 道装甲环带 + 下半圈铆钉
  for (let k = 0; k < 12; k++) {
    const x = -110 + k * 20;
    const r = hullR(x) + 0.35;
    p.push(hullSeg(x - 0.7, x + 0.7, r, r, DARK));
    for (let i = 0; i < SIDES; i++) {
      const a = (i / SIDES) * Math.PI * 2;
      if (Math.sin(a) > 0.45) continue;
      const R = r * FLAT + 0.12;
      for (const dx of [-0.45, 0.45]) p.push({ geo: box(0.32, 0.32, 0.32), color: RIVET, pos: [x + dx, Math.sin(a) * R, Math.cos(a) * R] });
    }
  }
  // 纵向板缝（16 条棱线，中段）
  for (let i = 0; i < SIDES; i++) {
    const a = ((i + 0.5) / SIDES) * Math.PI * 2;
    p.push({ geo: box(150, 0.22, 0.22), color: DARK, pos: [0, Math.sin(a) * 18.04, Math.cos(a) * 18.04] });
  }
  // 分块装甲板：环带之间每一格，两舷各 6 块平面上各贴一块（凸出 0.35 米，颜色错开）
  for (let k = 0; k < 7; k++) {
    const x = -60 + k * 20;
    for (const s of [-1, 1]) {
      for (let f = -3; f <= 2; f++) {
        const a = (f / SIDES) * Math.PI * 2;
        const nY = Math.sin(a);
        const nZ = Math.cos(a) * s;
        const R = 18 * FLAT + 0.17;
        p.push({ geo: box(17.6, 0.35, 6.1), color: (k + f + (s > 0 ? 0 : 1)) % 3 === 0 ? STEEL_D : (k + f) % 2 ? STEEL : STEEL_B, pos: [x, nY * R, nZ * R], rot: [Math.atan2(nZ, nY), 0, 0] });
      }
    }
  }
  // 背脊走道 + 两侧扶栏立柱
  p.push({ geo: box(130, 0.6, 3.2), color: DARK, pos: [0, 18 * FLAT + 0.3, 0] });
  for (let x = -62; x <= 62; x += 8) for (const s of [-1, 1]) p.push({ geo: box(0.2, 1.1, 0.2), color: DARK, pos: [x, 18 * FLAT + 1.1, s * 1.45] });
  // 指挥吊舱（x −30～−6）：倒棱台舱体 + 平板窗带 + 窗框 + 铁狼红腰线 + 两根吊柱
  p.push({ geo: frustum(chamfer(20, 6, 1.2), chamfer(24, 8, 1.4), 6, -25), color: STEEL_D, pos: [-18, 0, 0] });
  p.push({ geo: box(23.4, 1.4, 7.6), color: GLASS, pos: [-18, -21.2, 0] });
  for (let x = -29; x <= -7; x += 2) p.push({ geo: box(0.28, 1.5, 7.8), color: DARK, pos: [x, -21.2, 0] });
  p.push({ geo: box(24.4, 0.45, 8.3), color: RED, pos: [-18, -19.7, 0] });
  for (const x of [-26, -10]) p.push({ geo: box(3, 2.4, 3), color: STEEL_D, pos: [x, -18.4, 0] });
  // 4 个升力短舱：吊架 + 方棱台短舱 + 桨毂（四叶桨 T142 起拆出去单独转，见 propParts）
  for (const [nx, s] of NACELLES) {
    p.push({ geo: box(3, 1.2, 4.4), color: STEEL_D, pos: [nx + 4, -7, s * 17.6] });
    p.push({ geo: frustum(chamfer(3.6, 3.6, 0.8), chamfer(3, 3, 0.6), 9, 0), color: STEEL_B, pos: [nx, -7, s * 20.6], rot: [0, 0, -Math.PI / 2] });
    p.push({ geo: cyl(0.7, 0.9, 1.2, 8), color: DARK, pos: [nx + 9.6, -7, s * 20.6], rot: [0, 0, Math.PI / 2] });
  }
  // 十字尾翼：上 / 下垂直尾 + 两侧水平尾；翼尖一道铁狼红
  const fin: V2[] = [[-120, 7], [-96, 15.5], [-112, 28], [-125, 28]];
  const finD: V2[] = fin.map(([x, y]) => [x, -y]);
  p.push({ geo: slab(fin, 1.1), color: STEEL_D });
  p.push({ geo: slab(finD.slice().reverse(), 1.1), color: STEEL_D });
  p.push({ geo: slab(fin, 1.1), color: STEEL_D, rot: [Math.PI / 2, 0, 0] });
  p.push({ geo: slab(fin, 1.1), color: STEEL_D, rot: [-Math.PI / 2, 0, 0] });
  for (const y of [27.3, -27.3]) p.push({ geo: box(12.6, 1.2, 1.3), color: RED, pos: [-118.5, y, 0] });
  for (const s of [-1, 1]) p.push({ geo: box(12.6, 1.3, 1.2), color: RED, pos: [-118.5, 0, s * 27.3] });
  // 烈风挂架（T105 推进器从艇尾挪到侧舷下沿）：涵道靠艇身那一面两根方柱伸进艇身
  for (const id of ['thrustL', 'thrustR'] as const) {
    const [x, y, z] = GEAR_AT[id];
    for (const dx of [-2.4, 2.4]) p.push(strut([x + dx, y + 1.2, z - 4.4], [x + dx, -10.6, 13.6], 1.1, 1.3, STEEL_D));
  }
  // 压舱水排口（转场 1 往下喷水）
  for (const x of SKY_DRAIN) p.push({ geo: box(2.2, 0.6, 2.2), color: DARK, pos: [x, -18 * FLAT - 0.2, 0] });
  // 蜂鸣机枪 4 挺（T142）：临路侧下舷的小炮塔 + 双联枪管斜着朝下（不是部件，打不掉）
  for (const x of ATK.mg.x) {
    const [mx, my, mz] = MG_AT(x);
    p.push({ geo: frustum(chamfer(3.2, 3.2, 0.6), chamfer(2.4, 2.4, 0.45), 1.6, -0.8), color: STEEL_D, pos: [x, -4.4, 17.6], rot: [1.82, 0, 0] });
    p.push({ geo: box(2.2, 1.4, 2.0), color: STEEL_B, pos: [x, -4.9, 18.8], rot: [-0.25, 0, 0] });
    for (const dx of [-0.45, 0.45]) p.push(strut([x + dx, -5.0, 19.4], [mx + dx, my, mz], 0.32, 0.32, DARK));
  }
  // 锚链绞盘（T142）：艇腹两个 6 × 4 米方箱，锚链从底下垂进坑里
  for (const c of CABLES) {
    if (c.kind !== 'anchor') continue;
    p.push({ geo: box(6, 4, 4), color: STEEL_D, pos: [c.x, WINCH_Y + 2, WINCH_Z] });
    p.push({ geo: cyl(1.4, 1.4, 4.4, 10), color: DARK, pos: [c.x, WINCH_Y + 1.6, WINCH_Z], rot: [Math.PI / 2, 0, 0] });
    p.push({ geo: box(6.2, 0.4, 4.2), color: HAZARD, pos: [c.x, WINCH_Y + 0.3, WINCH_Z] });
  }
  return p;
}
/** 4 个升力短舱（艇本地 x、哪一舷） */
const NACELLES: readonly (readonly [number, number])[] = [[40, -1], [40, 1], [-55, -1], [-55, 1]];
/** 升力短舱的四叶桨（T142 拆出来单独转：1 个实例化网格，绕艇本地 x 转） */
function propParts(): PartSpec[] {
  return [0, 1].map((b): PartSpec => ({ geo: box(0.3, 6, 0.9), color: DARK, rot: [(b * Math.PI) / 2, 0, 0] }));
}
/** 12 盏航行灯（T142：放压舱水那一刻从停泊转战斗，依次亮起）：两舷腰线各 4 盏、背脊 2 盏、艇首 1 盏、下垂直尾尖 1 盏（艇本地） */
const NAV_LIGHTS: readonly (readonly [number, number, number])[] = [
  ...[-90, -30, 30, 90].flatMap((x) => [[x, 0, 18.4], [x, 0, -18.4]] as [number, number, number][]),
  [-100, 18.3, 0], [100, 18.3, 0], [125.4, 0, 0], [-118.5, -28.6, 0],
];
/** 锚链绞盘底面在艇本地的 y / z（锚链从这一点垂下去） */
const WINCH_Y = -18 * FLAT - 4;
const WINCH_Z = -3;
/** 艇腹 6 个压舱水排口的 x（艇本地） */
const SKY_DRAIN = [-62, -42, 22, 42, 62, 82];

/** 下垂直尾上那片能摆的舵（铰链在 x = 0，往后伸 7 米） */
function rudderParts(): PartSpec[] {
  return [{ geo: slab([[0, -14], [0, -27.5], [-7, -27.5], [-7, -15.5]], 0.9), color: STEEL_B }, { geo: box(7, 1, 1), color: RED, pos: [-3.5, -27, 0] }];
}

// ------------------------------------------------------------------ 六个部件（各自一组：body 留在艇上、拆掉换烧黑；loose 被拆时掀飞）

/**
 * 部件在艇本地的位置（D5 3.3 节：背脊 x ∓14 离中线 21、近侧下舷 20°、艇腹 x +12）。
 * 烈风（T105）：原来挂在艇尾外伸梁（x −121），阶段三横过来以后艇尾在画面外、也出了射程，挪到炮廊两头下面（x ±16、近侧下沿），
 * 涵道竖着往下喷；艇首那一台是「左」（横过来时艇首朝左，镜像摆法下 x 反过来）
 */
export const GEAR_AT: Record<AirshipPart, [number, number, number]> = {
  rocket: [-14, 18 * FLAT, 0],
  hive: [14, 18 * FLAT, 0],
  broadside: [0, -6.2, 16.9],
  cannon: [12, -18 * FLAT, 0],
  thrustL: [-MIRROR * 16, -18, 19],
  thrustR: [MIRROR * 16, -18, 19],
};
export type AirshipPart = 'rocket' | 'hive' | 'broadside' | 'cannon' | 'thrustL' | 'thrustR';
export const SKY_PARTS: AirshipPart[] = ['rocket', 'hive', 'broadside', 'cannon', 'thrustL', 'thrustR'];

/** 补丁件（再遇战损，D5 12.2）：两块浅一档的补板 + 一圈焊痕 */
export function patchParts(w: number, y: number, z: number): PartSpec[] {
  return [
    { geo: box(w * 0.42, 0.2, w * 0.36), color: STEEL_L, pos: [-w * 0.18, y, z], rot: [0, 0.2, 0] },
    { geo: box(w * 0.3, 0.2, w * 0.28), color: STEEL_L, pos: [w * 0.22, y + 0.02, z + w * 0.12], rot: [0, -0.3, 0] },
    { geo: box(w * 0.46, 0.08, 0.16), color: 0x45413d, pos: [-w * 0.18, y + 0.11, z + w * 0.18] },
  ];
}

const GEAR_BODY: Record<AirshipPart, () => PartSpec[]> = {
  // 暴雨：底座棱台 + 侧装甲
  rocket: () => [
    { geo: frustum(chamfer(8.6, 8.6, 1.4), chamfer(7.6, 7.6, 1.2), 1.3, -0.2), color: STEEL_D },
    ...[-1, 1].map((s): PartSpec => ({ geo: box(0.5, 1.6, 7.2), color: STEEL_B, pos: [s * 4.1, 0.5, 0], rot: [0, 0, -s * 0.2] })),
  ],
  // 蝗巢：方舱 + 分块侧板 + 舱沿铁狼红
  hive: () => [
    { geo: frustum(chamfer(9.4, 7.4, 1.1), chamfer(8.4, 6.4, 0.9), 4.2, -0.2), color: STEEL_D },
    ...[-1, 1].flatMap((s): PartSpec[] => [-2.4, 0, 2.4].map((x, i) => ({ geo: box(2.2, 3.2, 0.35), color: i === 1 ? STEEL : STEEL_B, pos: [x, 1.8, s * 3.6] }))),
    { geo: box(8.6, 0.35, 6.6), color: RED, pos: [0, 3.9, 0] },
    { geo: box(7.4, 0.2, 5.4), color: DARK, pos: [0, 4.05, 0] },
  ],
  // 排山：沿艇身的长炮廊（倒角方截面）+ 6 块炮盾座 + 下沿红带
  broadside: () => [
    { geo: frustum(chamfer(4.4, 3.8, 0.9), chamfer(4.4, 3.8, 0.9), 37, -18.5), color: STEEL_D, rot: [0, 0, -Math.PI / 2] },
    ...[-15, -9, -3, 3, 9, 15].map((x): PartSpec => ({ geo: frustum(chamfer(3.6, 1.4, 0.4), chamfer(3, 1.1, 0.3), 2.6, -1.3), color: STEEL_B, pos: [x, 0, 1.8], rot: [Math.PI / 2, 0, 0] })),
    { geo: box(37.4, 0.4, 0.5), color: RED, pos: [0, -1.7, 1.75] },
    ...[-12, -6, 0, 6, 12].map((x): PartSpec => ({ geo: box(0.3, 3.4, 0.3), color: RIVET, pos: [x, 0, 1.95] })),
  ],
  // 碾城：倒挂的座圈
  cannon: () => [
    { geo: cyl(4.4, 4.0, 1.4, 16), color: STEEL_D, pos: [0, -0.7, 0] },
    { geo: cyl(4.5, 4.5, 0.3, 16), color: DARK, pos: [0, -1.25, 0] },
  ],
  // 烈风：方截面涵道（车床体，平面拼接）+ 桨毂 + 三根支柱；T105 起竖着装（喷口朝下，挂架在 hullParts）
  thrustL: () => thrusterBody(),
  thrustR: () => thrusterBody(),
};

function thrusterBody(): PartSpec[] {
  const duct = lathe([[3.6, -3.4], [4.5, -3.4], [4.8, -1.6], [4.8, 2.4], [4.4, 3.4], [3.6, 3.4], [3.6, -3.4]], 16);
  duct.computeVertexNormals();
  const lip = lathe([[4.5, -3.6], [5.0, -3.6], [5.0, -3.0], [4.5, -3.0], [4.5, -3.6]], 16);
  lip.computeVertexNormals();
  return [
    { geo: duct, color: STEEL_B },
    { geo: lip, color: STEEL_L },
    { geo: frustum(chamfer(2.2, 2.2, 0.5), chamfer(1.0, 1.0, 0.25), 5.2, -2.2), color: STEEL_D, rot: [Math.PI, 0, 0] },
    ...[0, 1, 2].map((i): PartSpec => ({ geo: box(7.2, 0.4, 0.3), color: STEEL_D, pos: [0, -2.6, 0], rot: [0, (i * Math.PI) / 3 + Math.PI / 6, 0] })),
  ];
}

