// ------------------------------------------------------------------ 材质

let skyPaint: THREE.MeshStandardMaterial | null = null;
/** 艇身涂装：坦克同一套迷彩顶点色，雾因子 × 0.5（照轰天 siegeMat：100～250 米外也是清楚的深色剪影） */
function skyMat(): THREE.MeshStandardMaterial {
  if (skyPaint) return skyPaint;
  const m = enemyPaint().clone();
  fogK(m, 0.5, 'sky-fogless');
  skyPaint = m;
  return m;
}

let hangarPaint: THREE.MeshStandardMaterial | null = null;
/** 机库：混凝土 / 钢架顶点色（不带迷彩花纹），雾因子 × 0.6 */
function hangarMat(): THREE.MeshStandardMaterial {
  if (hangarPaint) return hangarPaint;
  const m = MAT.painted.clone();
  fogK(m, 0.6, 'hangar-fogless');
  hangarPaint = m;
  return m;
}

function fogK(m: THREE.MeshStandardMaterial, k: number, key: string): void {
  m.onBeforeCompile = (sh: THREE.WebGLProgramParametersWithUniforms) => {
    sh.fragmentShader = sh.fragmentShader.replace(
      '#include <fog_fragment>',
      `#ifdef USE_FOG\n  float fogFactor = ${k.toFixed(2)} * smoothstep( fogNear, fogFar, vFogDepth );\n  gl_FragColor.rgb = mix( gl_FragColor.rgb, fogColor, fogFactor );\n#endif`,
    );
  };
  m.customProgramCacheKey = () => key;
}

const glowMats = new Map<number, THREE.MeshBasicMaterial>();
/** 发光件（预警亮光 / 舱灯 / 喷口）：不吃雾、半透明叠加 */
export function glowMat(color: number): THREE.MeshBasicMaterial {
  let m = glowMats.get(color);
  if (!m) {
    m = new THREE.MeshBasicMaterial({ color, fog: false, transparent: true, opacity: 0.9, depthWrite: false, blending: THREE.AdditiveBlending });
    glowMats.set(color, m);
  }
  return m;
}

// ------------------------------------------------------------------ 机库

/** 拱顶高度：两端护墙顶 8 米 → 正中 14 米 */
const archY = (x: number) => AIRSHIP.wall + (AIRSHIP.arch - AIRSHIP.wall) * (1 - (x / AIRSHIP.halfW) ** 2);
const ROOF_W = AIRSHIP.halfW / 4;

/** 机库护墙、两侧放兵门、中央门（关着）和门梁、两头山墙 / 后墙、固定的钢拱架（库顶在上面滑）；临路那道墙（原来的前墙）沿路整段都在画面里 */
function hangarParts(): PartSpec[] {
  const H = AIRSHIP;
  const p: PartSpec[] = [];
  const T = 2.6;
  // 临路墙：门洞（中央 ±10、放兵门 ±16～24）之间的几段
  const segs: [number, number][] = [[-H.halfW, -24], [-16, -10], [10, 16], [24, H.halfW]];
  for (const [a, b] of segs) p.push({ geo: box(b - a, H.wall, T), color: CONCRETE, pos: [(a + b) / 2, H.wall / 2, -T / 2] });
  // 放兵门门楣 + 门洞里的暗处 + 门框
  for (const s of [-1, 1]) {
    p.push({ geo: box(8, 2, T), color: CONCRETE_D, pos: [s * 20, 7, -T / 2] });
    p.push({ geo: box(8, 6, 0.4), color: DARK, pos: [s * 20, 3, -T + 0.2] });
    for (const dx of [-4.2, 4.2]) p.push({ geo: box(0.5, 6.4, T + 0.3), color: HAZARD, pos: [s * 20 + dx, 3.2, -T / 2] });
  }
  // 中央门两扇（T104 起不再开门过桥，一直关着）+ 门梁（加注罐站在上面）
  for (const s of [-1, 1]) for (const d of doorParts()) p.push({ ...d, pos: [(d.pos?.[0] ?? 0) + s * 5, d.pos?.[1] ?? 0, (d.pos?.[2] ?? 0) - 1.9] });
  p.push({ geo: box(21, 1.2, T + 0.6), color: STEEL_D, pos: [0, 7.6, -T / 2] });
  // 墙面竖向壁柱（每 12 米）+ 分块混凝土板色差
  for (let x = -126; x <= 126; x += 12) {
    if (Math.abs(x) < 26) continue;
    p.push({ geo: box(1.4, H.wall, 0.8), color: CONCRETE_D, pos: [x, H.wall / 2, 0.3] });
  }
  for (let x = -130; x < 130; x += 10) {
    if (Math.abs(x + 5) < 26) continue;
    if (((x / 10) | 0) % 2) p.push({ geo: box(9.6, 3.2, 0.12), color: CONCRETE_D, pos: [x + 5, 2.2, 0.06] });
  }
  // 墙顶黄黑警示条（整段）
  for (let x = -H.halfW + 1; x < H.halfW - 1; x += 2) {
    if (Math.abs(x + 1) < 11) continue;
    p.push({ geo: box(2, 0.6, 0.2), color: Math.round(x / 2) % 2 === 0 ? HAZARD : DARK, pos: [x + 1, H.wall - 0.6, 0.1] });
  }
  // 两头山墙、后墙
  for (const s of [-1, 1]) p.push({ geo: box(T, H.wall, H.depth), color: CONCRETE_D, pos: [s * (H.halfW - T / 2), H.wall / 2, -H.depth / 2] });
  p.push({ geo: box(H.halfW * 2, H.wall, T), color: CONCRETE_D, pos: [0, H.wall / 2, -H.depth + T / 2] });
  // 固定的钢拱架：临路 / 后面两道拱梁（分段折线）+ 临路这道的竖撑（门洞上那一段让开）
  const n = 18;
  for (const z of [-0.6, -H.depth + 0.6]) {
    for (let i = 0; i < n; i++) {
      const xa = -H.halfW + (i * 2 * H.halfW) / n;
      const xb = -H.halfW + ((i + 1) * 2 * H.halfW) / n;
      p.push(strut([xa, archY(xa) - 0.6, z], [xb, archY(xb) - 0.6, z], 1.0, 1.2, STEEL_D));
    }
  }
  for (let x = -132; x <= 126; x += 11) {
    if (Math.abs(x) < 12) continue;
    p.push({ geo: box(0.7, archY(x) - H.wall, 0.7), color: STEEL_D, pos: [x, (archY(x) + H.wall) / 2 - 0.6, -0.6] });
    p.push(strut([x, H.wall, -0.6], [x + 5.5, archY(x + 5.5) - 0.8, -0.6], 0.4, 0.4, DARK));
  }
  // 滑轨：沿拱顶前后两根（库顶在上面滑开）
  for (const z of [-3, -H.depth + 3]) p.push({ geo: box(H.halfW * 2, 0.4, 0.6), color: DARK, pos: [0, H.wall + 0.2, z] });
  // 墙顶缆桩（T142）：压顶缆两头各一个——混凝土方墩 + 钢制系缆柱，临路墙、后墙各 6 个
  for (const c of CABLES) {
    if (c.kind !== 'top') continue;
    for (const z of [-CABLE.bollardIn, -H.depth + CABLE.bollardIn]) {
      p.push({ geo: box(3, 1.3, 2.2), color: CONCRETE_D, pos: [c.x, H.wall + 0.65, z] });
      p.push({ geo: cyl(0.55, 0.65, 1.3, 8), color: STEEL_D, pos: [c.x, H.wall + 1.95, z] });
      p.push({ geo: box(1.8, 0.25, 0.35), color: DARK, pos: [c.x, H.wall + 2.5, z] });
    }
  }
  return p;
}

/** 一扇库顶：波纹钢板 + 7 根檩条 + 两头液压缸 */
function roofParts(): PartSpec[] {
  const H = AIRSHIP;
  const p: PartSpec[] = [{ geo: box(ROOF_W, 0.6, H.depth - 1), color: ROOF_C, pos: [0, 0, -H.depth / 2] }];
  for (let i = 0; i < 7; i++) p.push({ geo: box(0.5, 0.9, H.depth - 1), color: DARK, pos: [-ROOF_W / 2 + 1.5 + (i * (ROOF_W - 3)) / 6, 0.5, -H.depth / 2] });
  for (let z = 4; z < H.depth - 2; z += 6.5) p.push({ geo: box(ROOF_W - 0.4, 0.32, 0.32), color: STEEL_D, pos: [0, 0.45, -z] });
  for (const z of [-1.2, -H.depth + 1.2]) p.push({ geo: cyl(0.45, 0.45, 6, 8), color: STEEL_D, pos: [ROOF_W / 2 - 3, -0.6, z], rot: [0, 0, Math.PI / 2] });
  return p;
}

/** 中央门的一扇（10 × 7 米钢门 + 横肋 + 黄黑斜纹） */
function doorParts(): PartSpec[] {
  const p: PartSpec[] = [{ geo: box(10, 7, 0.8), color: STEEL_D, pos: [0, 3.5, 0] }];
  for (const y of [1.2, 3.5, 5.8]) p.push({ geo: box(10, 0.4, 1.0), color: DARK, pos: [0, y, 0] });
  for (let i = 0; i < 4; i++) p.push({ geo: box(1.2, 3.2, 0.3), color: i % 2 ? DARK : HAZARD, pos: [-3.6 + i * 2.4, 2.4, 0.5], rot: [0, 0, 0.6] });
  return p;
}

/** 顶脊液压锁栓（T142，开顶前依次弹开）：钢块 + 黄黑条 + 一根小液压缸 */
function boltParts(): PartSpec[] {
  return [
    { geo: box(2.2, 0.9, 1.3), color: STEEL_D },
    { geo: box(2.26, 0.3, 1.36), color: HAZARD, pos: [0, 0.1, 0] },
    { geo: cyl(0.22, 0.22, 1.6, 6), color: DARK, pos: [0.4, 0.7, 0], rot: [0, 0, 1.1] },
  ];
}

/**
 * 机库的灯（T142）：墙顶 6 盏旋转警示灯（敌方红）+ 后墙里侧 4 排 × 8 盏钠灯（坑里往外依次亮）；一个实例化网格，每盏的颜色就是亮度。
 * 前 6 个是警示灯，后面按排存（第 0 排最低）
 */
const BEACONS: [number, number][] = [[-112, -1.3], [-56, -1.3], [56, -1.3], [112, -1.3], [-56, -AIRSHIP.depth + 1.3], [56, -AIRSHIP.depth + 1.3]];
const LAMP_ROWS = [1.0, 2.8, 4.6, 6.4];
const LAMP_COLS = 8;
const SODIUM = 0xffb347;

const CONE_FRAG = /* glsl */ `
uniform float uK;
uniform vec3 uColor;
varying vec2 vUv;
void main() {
  float y = clamp(vUv.y, 0.0, 1.0);
  float a = pow(1.0 - y, 1.6) * 0.16 * uK;
  gl_FragColor = vec4(uColor * a, a);
}`;
/** 艇影（T142）：路面一张暗色椭圆，中间实、边上虚 */
const SHADE_FRAG = /* glsl */ `
uniform float uK;
varying vec2 vUv;
void main() {
  vec2 p = clamp(vUv, 0.0, 1.0) * 2.0 - 1.0;
  float a = (1.0 - smoothstep(0.45, 1.0, length(p))) * uK;
  gl_FragColor = vec4(0.05, 0.045, 0.04, a);
}`;
const CONE_VERT = /* glsl */ `
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}`;

/** 库沿加注罐（门梁上，6 米高）：立罐 + 两道箍 + 红带 + 一根加注管伸进库里 */
function fuelParts(): PartSpec[] {
  return [
    { geo: cyl(1.5, 1.6, 5.4, 14), color: STEEL_L, pos: [0, 2.9, 0] },
    { geo: cyl(1.1, 1.5, 0.6, 14), color: STEEL_L, pos: [0, 5.9, 0] },
    ...[1.2, 4.4].map((y): PartSpec => ({ geo: cyl(1.68, 1.68, 0.3, 14), color: DARK, pos: [0, y, 0] })),
    { geo: cyl(1.62, 1.62, 0.7, 14), color: RED, pos: [0, 2.8, 0] },
    strut([0, 4.6, -1], [0, 5.4, -8], 0.6, 0.6, DARK),
    { geo: box(2.6, 0.4, 2.6), color: DARK, pos: [0, 0.2, 0] },
  ];
}

/**
 * 机库（D5 1.3 / 9.1 节）：独立挂在场景里（首领本体、开打前的远景都用它）。T104 起沿路摆在路边（AIRSHIP.side；place 给路中心 x 和机库正中的 z），
 * 临路那道墙（原来的前墙）朝路，门洞 / 放兵门开在这道墙上。库顶 8 扇（沿路前后各 4，一个实例化网格），slide[i] = 第 i 扇（0 = 最里面）滑开了多少；
 * 坑口一块暗色平面（库坑 40 米深，临路墙挡住了，只在抬头 / 推近时看得到）。不挡路：临路墙外面离路中心 22 米（车道最多开到 17 米）
 */
export class Hangar {
  readonly root = new THREE.Group();
  /** 库顶每扇滑开了自己那段路的几成（0..1，0 = 最里面那扇；T142 起是线性的，缓动由开顶演出算好） */
  readonly slide = [0, 0, 0, 0];
  /**
   * T142：起步那一下液压顶升（0..1，里面那扇顶得最高，滑的时候一层压一层不打架）；两侧液压缓冲压进去多少米（撞停那一下）；
   * 顶脊 8 个锁栓各弹开多少（0..1）
   */
  lift = 0;
  buffer = 0;
  readonly bolts = [0, 0, 0, 0, 0, 0, 0, 0];
  /** 灯（T142）：警示灯开没开；坑里 4 排钠灯各多亮（0..1，开顶演出 / 断缆写）；坑口跟着亮多少；探照光锥多亮；画质档 */
  beacon = false;
  readonly rows = [0, 0, 0, 0];
  pitGlow = 0;
  coneK = 0;
  q: 'high' | 'medium' | 'low' = 'high';
  /** 艇撤离完了：坦克接着开 */
  private released = false;
  private roadX = 0;
  private clock = 0;
  private readonly roof: THREE.InstancedMesh;
  private readonly boltMesh: THREE.InstancedMesh;
  private readonly lamps: THREE.InstancedMesh;
  private readonly cones: THREE.Mesh[] = [];
  private readonly pitMat: THREE.MeshBasicMaterial;
  /** 两个库沿加注罐（门梁上，前、后） */
  readonly fuel: THREE.Mesh[] = [];

  constructor(geo: GeoCache, scene: THREE.Scene) {
    const H = AIRSHIP;
    const mat = hangarMat();
    const walls = new THREE.Mesh(geo.merged('sky-hangar', hangarParts), mat);
    walls.receiveShadow = true;
    this.root.add(walls);
    this.roof = new THREE.InstancedMesh(geo.merged('sky-hangar-roof', roofParts), mat, 8);
    this.roof.frustumCulled = false;
    this.roof.receiveShadow = true;
    this.root.add(this.roof);
    this.boltMesh = new THREE.InstancedMesh(geo.merged('sky-hangar-bolt', boltParts), mat, 8);
    this.boltMesh.frustumCulled = false;
    this.root.add(this.boltMesh);
    // 灯：前 6 个警示灯，后面 4 排钠灯；一开始全黑（叠加混合，黑 = 看不见）
    const lampMat = new THREE.MeshBasicMaterial({ color: 0xffffff, fog: false, transparent: true, opacity: 0.95, depthWrite: false, blending: THREE.AdditiveBlending });
    this.lamps = new THREE.InstancedMesh(box(1, 1, 1), lampMat, BEACONS.length + LAMP_ROWS.length * LAMP_COLS);
    this.lamps.frustumCulled = false;
    this.lamps.renderOrder = 3;
    const black = new THREE.Color(0);
    BEACONS.forEach(([x, z], i) => {
      mA.compose(v2.set(x, H.wall + 0.75, z), qA.identity(), v1.setScalar(1.3));
      this.lamps.setMatrixAt(i, mA);
      this.lamps.setColorAt(i, black);
    });
    LAMP_ROWS.forEach((y, r) => {
      for (let c = 0; c < LAMP_COLS; c++) {
        const i = BEACONS.length + r * LAMP_COLS + c;
        mA.compose(v2.set(-105 + c * 30 + (r % 2) * 6, y, -H.depth + 2.85), qA.identity(), v1.set(2.0, 0.7, 0.3));
        this.lamps.setMatrixAt(i, mA);
        this.lamps.setColorAt(i, black);
      }
    });
    this.root.add(this.lamps);
    // 探照光锥（只高画质）：坑底往上斜照着艇腹，慢慢扫
    const coneGeo = new THREE.CylinderGeometry(9, 0.6, 70, 16, 1, true);
    coneGeo.translate(0, 35, 0);
    for (const [x, z] of [[-48, -52], [38, -10]] as const) {
      const m = new THREE.Mesh(coneGeo, new THREE.ShaderMaterial({
        vertexShader: CONE_VERT, fragmentShader: CONE_FRAG, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, side: THREE.DoubleSide,
        uniforms: { uK: { value: 0 }, uColor: { value: new THREE.Color(0xffd9a0) } },
      }));
      m.position.set(x, 0, z);
      m.visible = false;
      m.frustumCulled = false;
      m.renderOrder = 3;
      this.root.add(m);
      this.cones.push(m);
    }
    for (const s of [-1, 1]) {
      const f = new THREE.Mesh(geo.merged('sky-hangar-fuel', fuelParts), mat);
      f.position.set(s * 5, 8.2, -1.3);
      this.root.add(f);
      this.fuel.push(f);
    }
    // 坑口：暗色平面，四边亮一点、中间最黑（看起来往下很深）
    const pit = new THREE.PlaneGeometry(H.halfW * 2 - 5.2, H.depth - 5.2, 12, 6);
    pit.rotateX(-Math.PI / 2);
    const pos = pit.getAttribute('position');
    const col = new Float32Array(pos.count * 3);
    for (let i = 0; i < pos.count; i++) {
      const ex = Math.abs(pos.getX(i)) / (H.halfW - 2.6);
      const ez = Math.abs(pos.getZ(i)) / ((H.depth - 5.2) / 2);
      const k = 0.03 + 0.08 * Math.max(ex ** 4, ez ** 3);
      col.set([k * 1.05, k, k * 0.92], i * 3);
    }
    pit.setAttribute('color', new THREE.BufferAttribute(col, 3));
    this.pitMat = new THREE.MeshBasicMaterial({ vertexColors: true, fog: false, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2 });
    const pitMesh = new THREE.Mesh(pit, this.pitMat);
    pitMesh.position.set(0, 0.07, -H.depth / 2);
    this.root.add(pitMesh);
    this.writeRoof();
    scene.add(this.root);
  }

  /** 摆到路边：x = 路中心，z = 机库正中（沿路）；临路墙落在路中心 AIRSHIP.side 米处，库里本地 +x 转到沿路往前、+z 朝路（路右边镜像） */
  place(x: number, z: number): void {
    this.roadX = x;
    this.root.position.set(x + AIRSHIP.side, 0, z);
    this.root.rotation.y = Math.PI / 2;
    this.root.scale.z = MIRROR;
    this.root.updateMatrixWorld(true);
  }

  /** 路中心 x（place 给的） */
  get x(): number {
    return this.roadX;
  }

  /** 机库正中（世界 z） */
  get z(): number {
    return this.root.position.z;
  }

  /** 停车线（世界 z）：机库正中往回 line 米，坦克停在机库旁 */
  get lineZ(): number {
    return this.root.position.z + AIRSHIP.line;
  }

  /** 坦克（z、车速）该不该刹车：艇撤离完以前停在停车线（按刹车距离提前松油门）；远景机库一直停（首领出来以后换成本体） */
  holds(z: number, speed: number): boolean {
    return !this.released && z - this.lineZ < 1.5 + (speed * speed) / 14;
  }

  /** 艇撤离完：放坦克走 */
  release(): void {
    this.released = true;
  }

  update(dt: number): void {
    this.clock += dt;
    this.writeRoof();
    this.writeLamps();
  }

  /** 第 i 扇（0 = 最里面）库顶现在的中心 x（库里本地，往两端为正，不分前后） */
  roofX(i: number): number {
    const x0 = (i + 0.5) * ROOF_W;
    const x1 = AIRSHIP.halfW - ROOF_W / 2 + (3 - i) * 1.6;
    return THREE.MathUtils.lerp(x0, x1, this.slide[i]) + (i < 3 ? this.buffer : 0);
  }

  /** 第 i 扇库顶全程要走多远（米：106 / 71 / 35 / 0） */
  static roofRun(i: number): number {
    return AIRSHIP.halfW - ROOF_W / 2 + (3 - i) * 1.6 - (i + 0.5) * ROOF_W;
  }

  /**
   * 8 扇库顶：沿拱顶往两端滑开，叠在两端（里面那扇在最上面）。T142：先液压顶升（lift，一层比一层高 0.75 米）再滑，滑开的位置由开顶演出按同一条曲线算好（slide 线性）；
   * 撞停那一下两侧液压缓冲压进 buffer 米。8 个锁栓骑在前面那扇最里面的板沿上，弹开 = 往上翻
   */
  private writeRoof(): void {
    const H = AIRSHIP;
    let n = 0;
    let topY = 0;
    let topX = 0;
    for (const s of [-1, 1]) {
      for (let i = 0; i < 4; i++) {
        const x = this.roofX(i);
        const slope = (-2 * (H.arch - H.wall) * x) / H.halfW ** 2;
        const y = archY(x) + 0.3 + (3 - i) * 0.75 * this.lift;
        mA.compose(v2.set(s * x, y, 0), qA.setFromEuler(eA.set(0, 0, s * Math.atan(slope))), SCALE1);
        this.roof.setMatrixAt(n++, mA);
        if (s > 0 && i === 0) {
          topY = y;
          topX = x - ROOF_W / 2;
        }
      }
    }
    this.roof.instanceMatrix.needsUpdate = true;
    for (let i = 0; i < 8; i++) {
      const k = this.bolts[i];
      mA.compose(v2.set(topX + 0.4 * k, topY + 0.75 + 0.5 * k, -4 - (i * (H.depth - 8)) / 7), qA.setFromEuler(eA.set(0, 0, 1.15 * k)), SCALE1);
      this.boltMesh.setMatrixAt(i, mA);
    }
    this.boltMesh.instanceMatrix.needsUpdate = true;
  }

  /**
   * 灯（T142）：警示灯 0.8 秒转一圈（看过去是一闪一闪，低画质只闪不带拖尾）；钠灯按排亮（低画质只开第 0、2 排 = 16 盏）；
   * 坑口暗面跟着暖一点；探照光锥只在高画质、慢慢扫
   */
  private writeLamps(): void {
    const low = this.q === 'low';
    BEACONS.forEach((_, i) => {
      let b = 0;
      if (this.beacon) {
        const ph = (this.clock / 0.8 + i * 0.37) % 1;
        b = low ? (ph < 0.5 ? 1.4 : 0.08) : 0.12 + 1.5 * Math.pow(0.5 + 0.5 * Math.cos(ph * Math.PI * 2), 4);
      }
      this.lamps.setColorAt(i, tmpC.setHex(WARN_ENEMY).multiplyScalar(b));
    });
    for (let r = 0; r < LAMP_ROWS.length; r++) {
      const k = low && r % 2 ? 0 : this.rows[r];
      tmpC.setHex(SODIUM).multiplyScalar(1.4 * k);
      for (let col = 0; col < LAMP_COLS; col++) this.lamps.setColorAt(BEACONS.length + r * LAMP_COLS + col, tmpC);
    }
    if (this.lamps.instanceColor) this.lamps.instanceColor.needsUpdate = true;
    const g = this.pitGlow;
    this.pitMat.color.setRGB(1 + 0.6 * g, 1 + 0.35 * g, 1 + 0.05 * g);
    const on = this.q === 'high' && this.coneK > 0.01;
    this.cones.forEach((m, i) => {
      m.visible = on;
      if (!on) return;
      (m.material as THREE.ShaderMaterial).uniforms.uK.value = this.coneK;
      m.rotation.set(0.32 * Math.sin(this.clock * 0.35 + i * 2.1), 0, 0.28 * Math.sin(this.clock * 0.27 + i));
    });
  }

  dispose(): void {
    this.root.removeFromParent();
  }
}

// ------------------------------------------------------------------ 首领本体

type Stage = 'wait' | 'open' | 'fight' | 'escape' | 'gone';

/** 一个部件这场战斗里的状态：wait 还没进窗口 / open 在窗口里（能打、会打你）/ cut 拆掉了 / lost 升出射界没拆掉（被它带走） */
export interface Gear {
  id: AirshipPart;
  label: string;
  name: string;
  win: [number, number];
  max: number;
  hp: number;
  state: 'wait' | 'open' | 'cut' | 'lost';
  patched: boolean;
  /** 阶段三横过来以后又转回来接着打的（T105：前面升出射界没拆掉的） */
  back: boolean;
  e: Enemy | null;
  /** 下一次攻击倒计时 / 预警还剩几秒（0 = 没在预警）/ 预警总长 / 喷尾流还剩几秒 / 尾流下一跳 */
  cd: number;
  tele: number;
  teleDur: number;
  act: number;
  tick: number;
  /** 碾城锁定的落点 / 尾流红带中线 x */
  ax: number;
  az: number;
  warnT: number;
  /** 拍子表里轮到它的出手时刻 / 打法（T142，补丁件已经往后挪过）；这一拍正在预警的打法 */
  q: number[];
  kinds: BeatKind[];
  beat: BeatKind;
}

/** 库沿加注罐 */
interface FuelTank {
  mesh: THREE.Mesh;
  anchor: THREE.Object3D;
  e: Enemy | null;
  gone: boolean;
}

/** 一个部件的模型（各自一组，挂在艇上的 GEAR_AT 位置） */
interface GearModel {
  group: THREE.Group;
  body: THREE.Mesh;
  loose: THREE.Object3D;
}

/** 首领 5 的设置（Game 刷出来以后给）：met = 这个存档 / 这一局之前交手过几次；patch = 哪几件换补丁件；phase = 直通从第几阶段开始（1～3） */
export interface AirshipSetup {
  met: number;
  last: number;
  patch: AirshipPart[];
  phase: number;
}

/** 首领战要用到的 Game 那边的东西（BossContext 之外，Game 刷出来时给） */
export interface AirshipHooks {
  /** 镜头：首领特写推过去 / 收回、抬头、余震 */
  showcase(x: number, y: number, z: number, r: number, dolly: number, inT: number, elev: number): void;
  release(outT: number): void;
  lookUp(rad: number, hold: number, back: number, inT: number): void;
  rumble(amount: number, sec: number): void;
  /** 画面宽高比（T142：竖屏 / 宽屏的镜头参数不一样） */
  aspect?(): number;
  /** 全场停火（敌人 / 飞蝗）、你无敌几秒 */
  ceasefire(on: boolean): void;
  guard(sec: number): void;
  /** 撤离开始 / 演完 */
  escaped(ship: Airship, stage: 'start' | 'end'): void;
  /** 拆掉一件（高光抓帧） */
  cut(g: Gear): void;
}

