/**
 * 程序化贴图的磁盘缓存（T108，只在微信小游戏里开）：第一次打开照常现算，算完存进用户目录；
 * 之后再打开（热启动）直接读文件，不再在没有 JIT 的 iOS 普通模式里算几秒噪声。
 * 目录按构建号分（tex-<构建号>），换了版本自动重算、旧目录删掉；读写出任何错都当没有缓存
 */

declare const __BUILD_ID__: string;

interface WxFs {
  readFileSync(path: string): ArrayBuffer;
  writeFile(o: { filePath: string; data: ArrayBuffer; fail?: () => void }): void;
  mkdirSync(path: string, recursive?: boolean): void;
  readdirSync(path: string): string[];
  rmdir(o: { dirPath: string; recursive?: boolean; fail?: () => void }): void;
}
const wx = (globalThis as { wx?: { getFileSystemManager?: () => WxFs; env?: { USER_DATA_PATH?: string } } }).wx;
const root = wx?.env?.USER_DATA_PATH;
const fs = root && typeof wx?.getFileSystemManager === 'function' ? wx.getFileSystemManager() : null;
const dir = `${root}/tex-${typeof __BUILD_ID__ === 'string' ? __BUILD_ID__ : 'dev'}`;
/** 文件头：宽、高（Uint16）、是不是 sRGB（Uint8），补齐到 8 字节 */
const HEAD = 8;
let ready = false;

const file = (key: string) => `${dir}/${key.replace(/[^\w-]/g, '_')}.bin`;

export function loadTex(key: string): { data: Uint8Array; w: number; h: number; srgb: boolean } | null {
  if (!fs) return null;
  try {
    const buf = fs.readFileSync(file(key));
    const head = new DataView(buf, 0, HEAD);
    const w = head.getUint16(0, true);
    const h = head.getUint16(2, true);
    if (buf.byteLength !== HEAD + w * h * 4) return null;
    return { data: new Uint8Array(buf, HEAD), w, h, srgb: head.getUint8(4) === 1 };
  } catch {
    return null;
  }
}

export function saveTex(key: string, data: Uint8Array, w: number, h: number, srgb: boolean): void {
  if (!fs) return;
  try {
    if (!ready) {
      ready = true;
      // 旧版本的缓存目录删掉
      for (const name of fs.readdirSync(root!)) if (name.startsWith('tex-') && `${root}/${name}` !== dir) fs.rmdir({ dirPath: `${root}/${name}`, recursive: true, fail() {} });
      try {
        fs.mkdirSync(dir, true);
      } catch {
        /* 已经有了 */
      }
    }
    const buf = new ArrayBuffer(HEAD + data.length);
    const head = new DataView(buf, 0, HEAD);
    head.setUint16(0, w, true);
    head.setUint16(2, h, true);
    head.setUint8(4, srgb ? 1 : 0);
    new Uint8Array(buf, HEAD).set(data);
    fs.writeFile({ filePath: file(key), data: buf, fail() {} });
  } catch {
    /* 存不了下次再算 */
  }
}
