const CORE_NAME: Record<CoreKey, string> = { cannon: '主炮流', rocket: '火箭流', laser: '激光流', vulcan: '火神流' };
const ENTRY_NAME: Record<Entry, string> = { tasks: '每日任务', factory: '军工厂', garage: '车库', bay: '装配车间' };
const FRAME_NAME = { bronze: '铜', silver: '银', gold: '金' };

/**
 * 这一级的奖励（军衔页一行一行列；skip = 已经有了不再写进「本局解锁」的）。
 * 槽位（T033）排在最前面：结算页「再打 N 军功晋升 X · 第一样奖励」写的就是它
 */
export function rankRewardLines(level: number, skip?: (kind: 'core' | 'open' | 'paint' | 'emblem' | 'bay' | 'area', id: string) => boolean): string[] {
  const out: string[] = [];
  if (level === 1) return ['默认涂装「橄榄绿」、纹章「齿轮」', '主炮流'];
  const r = RANK_REWARDS[level] ?? {};
  if (r.general) out.push('将官晋升 · 授衔');
  for (const b of BAY) if (b.rank === level && !skip?.('bay', b.id)) out.push(bayLine(b));
  for (const o of r.open ?? []) if (!skip?.('open', o)) out.push(o === 'factory' ? `军工厂开放（${(r.lines ?? []).map((l) => FACTORY_BY_ID.get(l)!.name).join('、')}）` : `${ENTRY_NAME[o]}开放`);
  if (r.lines && !r.open?.includes('factory') && !skip?.('open', 'factory')) out.push(`军工厂「${r.lines.map((l) => FACTORY_BY_ID.get(l)!.name).join('、')}」`);
  if (r.core && !skip?.('core', r.core)) out.push(`新战车 · ${CORE_NAME[r.core]}`);
  if (r.area && !skip?.('area', 'airfield')) out.push('新战区 · 荒原机场');
  for (const p of PAINTS) if (p.gift === level && !skip?.('paint', p.id)) out.push(`涂装「${p.name}」`);
  for (const e of EMBLEMS) if (e.gift === level && !skip?.('emblem', e.id)) out.push(`纹章「${e.name}」`);
  const shelf = [...PAINTS.filter((p) => p.shelf === level), ...EMBLEMS.filter((e) => e.shelf === level)].map((x) => `「${x.name}」`);
  if (shelf.length && !skip?.('open', 'garage')) out.push(`车库上架${shelf.join('')}`);
  if (level === 18 && !skip?.('open', 'garage')) out.push('车库全部上架');
  if (r.frame && !skip?.('open', 'garage')) out.push(`铭牌边框「${FRAME_NAME[r.frame]}」`);
  if (r.star) out.push('开启将星');
  if (r.ticket) out.push(`军票 ${r.ticket.toLocaleString('en-US')}`);
  return out;
}

/** 军衔章的铭牌边框（8 级铜 / 14 级银 / 18 级金） */
export function frameOf(level: number): 'bronze' | 'silver' | 'gold' | null {
  return level >= 18 ? 'gold' : level >= 14 ? 'silver' : level >= 8 ? 'bronze' : null;
}

