/** 战区威胁 1～10（T028 4.4 ④）：每级在上一级基础上多一条（只加强敌人，玩家这边一点不变） */
export const THREAT = ['敌潮数量 +20%', '敌人耐久 +15%', '精英出现 +50%', '敌人伤害 +15%', '首领耐久 +25%', '背景炮击 +50%（照旧有红圈）', '敌人耐久再 +15%', '首领半血以后攻速 +25%', '敌人伤害再 +15%', '敌潮再 +20%、首领耐久再 +25%'];
export const THREAT_MAX = THREAT.length;
/** 这一级的敌方加成（累计） */
export function threatMods(lv: number): { wave: number; hp: number; elite: number; dmg: number; bossHp: number; arty: number; rage: number } {
  const at = (n: number) => (lv >= n ? 1 : 0);
  return {
    wave: 1 + 0.2 * at(1) + 0.2 * at(10),
    hp: 1 + 0.15 * at(2) + 0.15 * at(7),
    elite: 1 + 0.5 * at(3),
    dmg: 1 + 0.15 * at(4) + 0.15 * at(9),
    bossHp: 1 + 0.25 * at(5) + 0.25 * at(10),
    arty: 1 + 0.5 * at(6),
    rage: at(8) ? 1.25 : 1,
  };
}
/** 每级第一次打掉轰天：军票 1,000 × 级数；5 级 / 10 级称号，10 级再送涂装「战区黑金」 */
export const THREAT_PRIZE = { ticket: 1000, title5: 'thr5', title10: 'thr10', paint10: 'warzone' };
