/**
 * 队友端本车的本地预测（T274）。按键当帧就用本地输入推演位置和车头；房主的权威状态到了，
 * 跟「同一时刻」本地推演的结果比，差多少就把推演状态挪多少，画面上的差值再在 0.1 秒左右慢慢吃掉。
 * 「同一时刻」= 房主回报已用到第 k 号输入、用了多久（age），本地发出 k 号输入那一刻再往后 age 秒。两边都按联机时钟（累计 dt）算。
 */
export interface Kin {
  x: number; z: number; vx: number; speed: number; tx: number; tz: number; yaw: number;
  /** 停车攻坚：TankMovement 的速度、车头、倒车 / 滑停，和前后范围；推进时为 null。 */
  hold: { vx: number; vz: number; yaw: number; reverse: boolean; coasting: boolean; lo: number; hi: number } | null;
}
/** 房主每包随本车状态发的那份：k = 已用到的输入序号，age = 用了多少秒。 */
export interface HostKin extends Kin { k: number; age: number }

const POS = ['x', 'z', 'vx', 'speed', 'tx', 'tz', 'yaw'] as const;
const HOLD = ['vx', 'vz', 'yaw'] as const;
/** 差得比这个远（米）就不追了，直接按房主的来（被掀飞、出了停车线这种）。 */
const SNAP = 6;
/** 画面上残差的衰减时间（秒）。 */
const SMOOTH = 0.1;
/** 回放最多补多久（秒），太久的不补。 */
const REPLAY = 0.5;

const copy = (k: Kin): Kin => ({ ...k, hold: k.hold && { ...k.hold } });
const wrap = (a: number): number => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

export interface PredictInput { x: number; forward: number; dragX: number; dragY: number }

export class OwnPrediction {
  state: Kin | null = null;
  /** 画面残差：显示位置 = 推演位置 + 残差。 */
  readonly offset = { x: 0, z: 0, yaw: 0 };
  /** 最近一次修正的误差（米），调试面板用。 */
  error = 0;
  private history: { t: number; s: Kin }[] = [];
  /** 这一帧还没推演的拖动量（本地输入读完、渲染前用掉）。 */
  private drag = { x: 0, y: 0 };
  private keys = { x: 0, forward: 0 };
  constructor(private readonly step: (s: Kin, input: PredictInput, dt: number) => void) {}

  reset(): void { this.state = null; this.history = []; this.offset.x = this.offset.z = this.offset.yaw = 0; this.drag.x = this.drag.y = 0; }
  /** 本地读到一次输入：拖动量累加，按键取最新。 */
  input(dragX: number, dragY: number, x: number, forward: number): void {
    this.drag.x += dragX; this.drag.y += dragY; this.keys.x = x; this.keys.forward = forward;
  }
  /** 推演一帧并记进历史；还没收到房主状态时不动。 */
  advance(dt: number, clock: number): void {
    const s = this.state;
    if (!s) return;
    this.step(s, { x: this.keys.x, forward: this.keys.forward, dragX: this.drag.x, dragY: this.drag.y }, dt);
    this.drag.x = this.drag.y = 0;
    this.history.push({ t: clock, s: copy(s) });
    while (this.history.length > 2 && clock - this.history[0].t > 2) this.history.shift();
    const k = Math.exp(-dt / SMOOTH);
    this.offset.x *= k; this.offset.z *= k; this.offset.yaw *= k;
  }
  /**
   * 房主的状态到了。sentAt = 本地发出第 host.k 号输入时的联机时钟（没记到为 null），clock = 现在；
   * drawn = 现在画在哪（刚开始预测时从这里平滑接过去）。
   */
  reconcile(host: HostKin, sentAt: number | null, clock: number, drawn: { x: number; z: number; yaw: number }): void {
    const s = this.state;
    const at = sentAt === null ? null : sentAt + host.age;
    const past = at === null ? null : this.sample(at);
    if (!s || !past || !!s.hold !== !!host.hold || Math.hypot(host.x - past.x, host.z - past.z) > SNAP) {
      // 没法比：从房主的状态开始，用当前按键补上它落后的那段。
      const shown = s ? { x: s.x + this.offset.x, z: s.z + this.offset.z, yaw: s.yaw + this.offset.yaw } : drawn;
      const next = copy(host);
      const behind = Math.min(REPLAY, Math.max(0, at === null ? 0 : clock - at));
      for (let t = 0; t < behind; t += 1 / 60) this.step(next, { ...this.keys, dragX: 0, dragY: 0 }, Math.min(1 / 60, behind - t));
      this.state = next; this.history = [{ t: clock, s: copy(next) }];
      const far = Math.hypot(shown.x - next.x, shown.z - next.z) > SNAP;
      this.offset.x = far ? 0 : shown.x - next.x; this.offset.z = far ? 0 : shown.z - next.z; this.offset.yaw = far ? 0 : wrap(shown.yaw - next.yaw);
      // 刚开始预测不算纠正。
      this.error = s ? Math.hypot(shown.x - next.x, shown.z - next.z) : 0;
      return;
    }
    // 同一时刻差多少：推演状态和它之后的历史一起挪，画面残差反向记下来慢慢消。
    const d: Record<string, number> = {};
    for (const key of POS) d[key] = key === 'yaw' ? wrap(host.yaw - past.yaw) : host[key] - past[key];
    const dh: Record<string, number> = {};
    if (host.hold && past.hold) for (const key of HOLD) dh[key] = key === 'yaw' ? wrap(host.hold.yaw - past.hold.yaw) : host.hold[key] - past.hold[key];
    const shift = (k: Kin): void => {
      for (const key of POS) k[key] += d[key];
      if (k.hold && host.hold) {
        for (const key of HOLD) k.hold[key] += dh[key] ?? 0;
        Object.assign(k.hold, { reverse: host.hold.reverse, coasting: host.hold.coasting, lo: host.hold.lo, hi: host.hold.hi });
      }
    };
    shift(s);
    for (const h of this.history) if (h.t >= at!) shift(h.s);
    this.offset.x -= d.x; this.offset.z -= d.z; this.offset.yaw -= d.yaw;
    this.error = Math.hypot(d.x, d.z);
  }
  /** 历史里 t 时刻的状态（两条之间按比例插）；比最早的还早就没有。 */
  private sample(t: number): Kin | null {
    const h = this.history;
    if (!h.length || t < h[0].t) return null;
    for (let i = h.length - 1; i >= 0; i--) {
      if (h[i].t > t) continue;
      const a = h[i], b = h[i + 1];
      if (!b) return a.s;
      const u = (t - a.t) / Math.max(1e-6, b.t - a.t), out = copy(a.s);
      for (const key of POS) out[key] = key === 'yaw' ? a.s.yaw + wrap(b.s.yaw - a.s.yaw) * u : a.s[key] + (b.s[key] - a.s[key]) * u;
      return out;
    }
    return null;
  }
}
