import * as THREE from 'three';
import { MAT } from '../../assets/materials';
import { droneGeo } from '../../assets/models/weapons';
import type { Enemy } from '../../entities/Enemy';
import { ARMOR_MULT, ultHalf } from '../defs';
import { summonBatch, summonDuration } from '../superMods';
import { UltBase, type UltContext, type UltPreview } from './common';
import { rng } from '../../game/rng';

const rand = (a: number, b: number) => a + Math.random() * (b - a);
/** 影响玩法的随机走「我方武器」流（T117，可设种子）；只管好看的照用 rand */
const fireRand = (a: number, b: number) => a + rng.weapon() * (b - a);

/**
 * 「黑潮」数值表（策划案 T007 v3 3.3 的起步值；冷却在 FUSIONS.swarm.cd 里固定 30 秒（T066 翻倍））：
 * count 枚巡飞弹（遥控中继翻倍，上限 max，超出数量折成每枚伤害）。launch 秒依次从蜂箱升空 → strafe 秒（中继 ×1.5）在坦克上空 alt 米、前方 ahead 米、
 * 左右 ±side 米内翻飞扫射（每枚每 mgGap 秒一发 mgDmg 点 small，只打地面投影 mgRange 米内的敌人，步兵 > 轻甲 > 重甲，同级先近的；从天上打不被掩体挡）
 * → pull 秒停火拉高 3 米、机腹灯红变白快闪、一声尖哨 → 俯冲：以 dive 米/秒扎向各自的目标（每枚 diveDmg 爆炸 + 穿甲，半径 diveR × A，按「爆·顶」炸景物），
 * 被扎中的车辆断履带 track 秒（据点精英 trackElite 秒，首领部件无效）。扫射的子弹擦到路边景物只有「扫」的表现（`SceneryDamage.strafe`，不扣结构、不推倒）。
 * 打谁扎谁：重点目标 = 生效期间最后一轮齐射锁定的目标（还活着）；没打过齐射就用拉高那一刻的自动瞄准目标（手动瞄准不设）；
 * 重点目标先分 min(focus, 击毁它要的枚数) 枚，其余按威胁值 + 血量分（每个目标先一枚，血厚、威胁高的多分），范围前方 reach[0] 米、身后 reach[1] 米；
 * 目标在途中被击毁改扎它 retarget 米内最近的活敌人，没有就扎原位置的地面。拉高时没有目标：最多再盘旋 linger 秒，还没有就飞回蜂箱。
 * T057（只是演出，上面的数值没动）：巡飞弹画大 look 倍；扫射期间头顶被遮住、全场压暗（mood）；俯冲那一刻慢放 slow [秒, 倍数]，
 * 每枚拖一道发动机光尾，扎到时多一团火光 + 一点重震 boomShake（一串连着震），第一枚扎到时镜头一缩一放 kick。
 * T060（制作人「无人机只打了一轮，可以多打几轮，火力显得更猛之后再撞上去（总伤害不用加）」）：扫射分 rounds 轮，每两轮之间整群兜一圈 gap 秒、换个方向再压过来。
 * 兜圈时停火，「开火时钟」也停：每枚的开火时长、射速、每发伤害和原来一模一样（发数不变 → 总伤害不变），俯冲的枚数 / 伤害也不变，只是俯冲晚 (rounds − 1) × gap 秒。
 * 每轮的航线（path：每轮 / 每段兜圈结束时整群的中心相对坦克在哪 [横向, 离地, 前后（正 = 坦克身后）]，三次曲线连起来，起止都是原来轨道的中心 center）
 * 只挪画出来的位置，扫射 / 俯冲的命中照旧按原来的轨道算；扫射时整群收拢到原来的 squeeze 倍，每枚按 lag 秒错开走同一条航线，拉成一股；
 * 全场一轮比一轮暗（dark [第一轮, 拉高]），兜圈时亮回 ease；
 * 每轮最后 burst 秒火力收拢、落点崩土，每轮结尾一下震动 endShake（一轮比一轮重，第二轮起带余震）；曳光每发都画（原来三成）、扫射时每枚拖一道细光尾
 */
export const SWARM = {
  // T017-5a：扫射 4 → 3 秒、俯冲每枚 100 → 150
  count: 32, perSummon: 4, max: 44, launch: 0.6, strafe: 3, pull: 0.6, linger: 6,
  alt: [10, 14], ahead: [0, 25], side: 10, mgRange: 40, mgGap: 0.25, mgDmg: 5,
  dive: 60, diveDmg: 150, diveR: 3.5, focus: 6, reach: [95, 10], retarget: 8, track: 1, trackElite: 0.5,
  look: 2, slow: [0.3, 0.45], boomShake: 0.06, kick: 0.25,
  mood: { light: 0.7, exposure: 0.95, tint: 0xc8bca8, tintK: 0.3, fog: 0x4a4844, fogK: 0.25 },
  rounds: 3, gap: 0.7, lag: 0.28, burst: 0.25, squeeze: 0.5, center: [0, 12, -12.5] as [number, number, number],
  // 第一轮从蜂箱往前压过去 → 左转爬高往回绕 → 贴低从左往右斜着扫 → 右转爬高绕回坦克身后 → 从身后压低一路扫到前面 →（第四轮备用：再左转 → 斜着扫回来）
  path: [[0, 9, -13], [-9, 15, 2], [8, 8, -8], [8, 15, 10], [-1, 8, -13], [-9, 15, 3], [7, 8, -10]] as [number, number, number][],
  dark: [0.76, 0.52], ease: 0.1, endShake: [0.1, 0.24],
};

/** 一枚巡飞弹：mode 0 在蜂箱里 / 1 翻飞 / 2 俯冲 / 3 飞回 / 4 结束 */
interface Bird {
  mode: number;
  /** 轨迹：椭圆中心（相对坦克：横向 cx、前方 cz）、高度、半径、相位、角速度、噪声相位 */
  cx: number;
  cz: number;
  alt: number;
  rad: number;
  ph: number;
  sp: number;
  nz: number;
  x: number;
  y: number;
  z: number;
  /** 出蜂箱的时刻、俯冲开始的时刻（开火时钟） */
  at: number;
  diveAt: number;
  mgT: number;
  puffT: number;
  target: Enemy | null;
  tx: number;
  tz: number;
  /** 画出来的位置 = 轨道 + 航线偏移 o（T060）；lag = 在航线上落后几秒；v = 上一帧画出来的位置（算机头朝向）、yaw / roll；l = 光尾上一节的终点 */
  lag: number;
  ox: number;
  oy: number;
  oz: number;
  vx: number;
  vy: number;
  vz: number;
  yaw: number;
  roll: number;
  lx: number;
  ly: number;
  lz: number;
}

/** 航线的关键点：时刻（生效后几秒，含兜圈）、偏移、切线 */
interface Key {
  t: number;
  p: [number, number, number];
  m: [number, number, number];
}

/** 黑潮 · 巡飞弹群（火箭 + 机枪★ + 无人机★）：头顶分三轮扫射，再各自俯冲自爆；最后一轮齐射打谁就有 6 枚扎谁，被扎的车辆断履带 1 秒 */
export class SwarmUlt extends UltBase {
  private strafeDuration = SWARM.strafe;
  private overload = 1;
  /** 按下后几秒；-1 = 没有在生效 */
  private t = -1;
  /** 开火时钟（T060）：兜圈时停，其余时候跟 t 一起走——扫射 / 拉高 / 俯冲的时间轴都按它（和 T060 以前的 t 一样） */
  private ft = 0;
  /** 第几轮（0 起），这段兜圈还剩几秒 */
  private round = 0;
  private gapT = 0;
  private frameN = 0;
  /** 上一帧坦克的位置（兜圈时轨道跟着坦克平移） */
  private px = 0;
  private pz = 0;
  private keys: Key[] = [];
  /** 拉高时没目标：已经多盘旋了几秒 */
  private wait = 0;
  private allotted = false;
  private whistled = false;
  /** 氛围改过（被 clear 打断时下一帧退回平时）、俯冲慢放放过没有 */
  private moody = false;
  private dove = false;
  private kicked = false;
  private birds: Bird[] = [];
  private focus: Enemy | null = null;
  private mesh: THREE.InstancedMesh | null = null;
  private readonly m = new THREE.Matrix4();
  private readonly q = new THREE.Quaternion();
  private readonly e = new THREE.Euler();
  private readonly s = new THREE.Vector3(1, 1, 1);
  private readonly p = new THREE.Vector3();
  private readonly v = new THREE.Vector3();
  private readonly o: [number, number, number] = [0, 0, 0];

  /** 落点价值评分（T017-13A）：重点目标按 8 米一坨评分（俯冲落点 3.5 米，扎堆的一起挨扫射），前方 95 米内 */
  spot(ctx: UltContext): { r: number; min: number; max: number } {
    return { r: 8, min: 0, max: Math.max(SWARM.reach[0], ctx.duel) };
  }

  /** 没有地面预览圈（预览是锁定框旁的「×6」） */
  preview(): UltPreview | null {
    return null;
  }

  /** 第 r 轮扫射在开火时钟上的结束时刻：开火那段（launch / 2 起到 launch + strafe）平分成 rounds 轮 */
  private roundEnd(r: number): number {
    const T = SWARM;
    const f0 = T.launch * 0.5;
    return f0 + ((T.launch + this.strafeDuration - f0) * (r + 1)) / T.rounds;
  }

  /** 扫射还剩几秒（真实时间：开火时钟 + 没兜完的圈） */
  private strafeLeft(): number {
    const T = SWARM;
    return Math.max(0, T.launch + this.strafeDuration - this.ft) + Math.max(0, this.gapT) + Math.max(0, T.rounds - 1 - this.round) * T.gap;
  }

  protected override activeLabel(): string {
    const T = SWARM;
    if (this.ft < T.launch + this.strafeDuration) return `扫射 ${Math.max(1, Math.ceil(this.strafeLeft()))}`;
    return this.allotted || this.ft < T.launch + this.strafeDuration + T.pull ? '俯冲' : '盘旋';
  }

  /** 生效期间的齐射（火箭核心开一轮）：记下锁定的目标，俯冲时先分给它 */
  onSalvo(target: Enemy | null): void {
    if (this.t >= 0 && !this.allotted && target) this.focus = target;
  }

  /** 扫射期间锁定框旁边显示「×N」：重点目标（没打过齐射就是现在的自动瞄准目标）会分到几枚 */
  mark(ctx: UltContext): { e: Enemy; n: number } | null {
    if (this.t < 0 || this.allotted) return null;
    const e = this.focus?.alive ? this.focus : ctx.pick();
    if (!e?.alive) return null;
    return { e, n: Math.min(SWARM.focus, this.need(e), this.birds.length) };
  }

  /** 第 k 轮的氛围：一轮比一轮暗，k = rounds 是拉高（最暗）；兜圈时亮回 ease */
  private dark(ctx: UltContext, k: number, lite: boolean, fade: number): void {
    const T = SWARM;
    const light = T.dark[0] + ((T.dark[1] - T.dark[0]) * k) / T.rounds + (lite ? T.ease : 0);
    ctx.mood({ ...T.mood, light, exposure: 0.9 + light * 0.08 }, fade);
  }

  protected fire(ctx: UltContext): void {
    const T = SWARM;
    this.clear();
    const { count: n, damage } = summonBatch(T.count, ctx.mods.summon, T.max);
    this.overload = damage;
    this.strafeDuration = T.strafe * summonDuration(ctx.mods);
    this.t = 0;
    this.ft = 0;
    this.round = 0;
    this.gapT = 0;
    this.wait = 0;
    this.allotted = false;
    this.whistled = false;
    this.birds = Array.from({ length: n }, (_, i): Bird => ({
      mode: 0,
      cx: fireRand(-T.side, T.side),
      cz: fireRand(T.ahead[0], T.ahead[1]),
      alt: fireRand(T.alt[0], T.alt[1]),
      rad: fireRand(3, 6),
      ph: rng.weapon() * Math.PI * 2,
      sp: fireRand(1.2, 2.2) * (rng.weapon() < 0.5 ? -1 : 1),
      nz: rng.weapon() * 10,
      x: 0, y: 0, z: 0,
      at: (i / n) * T.launch,
      diveAt: 0,
      mgT: fireRand(0, T.mgGap),
      puffT: 0,
      target: null, tx: 0, tz: 0,
      lag: 0, ox: 0, oy: 0, oz: 0, vx: 0, vy: 0, vz: 0, yaw: 0, roll: 0, lx: 0, ly: 0, lz: 0,
    }));
    // 航线错开（T060）：放在上面那串随机数后面，开火 / 俯冲用到的随机数和原来同一个顺序
    for (const b of this.birds) {
      b.lag = rng.weapon() * T.lag;
      b.yaw = rng.weapon() * Math.PI * 2;
    }
    this.plan();
    const P = ctx.tank.group.position;
    this.px = P.x;
    this.pz = P.z;
    if (!this.mesh) {
      this.mesh = new THREE.InstancedMesh(droneGeo(ctx.geo, true), MAT.painted, T.max);
      this.mesh.frustumCulled = false;
      this.mesh.castShadow = true;
      ctx.scene.add(this.mesh);
    }
    this.mesh.count = 0;
    this.mesh.visible = true;
    this.active = this.strafeLeft() + T.pull + 2;
    this.dove = this.kicked = false;
    ctx.audio.play('launch');
    ctx.audio.play('launch', 0.8, 0.8, 0.15);
    ctx.audio.play('launch', 0.7, 1.15, 0.3);
    // 蜂群遮住头顶：全场压暗（一轮比一轮暗）
    this.moody = true;
    this.dark(ctx, 0, false, 0.6);
  }

  /** 航线关键点（整群中心相对坦克）：原来轨道的中心 → 每轮结束 / 每段兜圈结束 → 拉高结束回到原来轨道的中心；切线按前后两个点（Catmull-Rom），起止速度 0 */
  private plan(): void {
    const T = SWARM;
    const k: Key[] = [{ t: 0, p: T.center, m: [0, 0, 0] }];
    for (let r = 0; r < T.rounds; r++) {
      const fe = this.roundEnd(r);
      k.push({ t: fe + r * T.gap, p: T.path[(2 * r) % T.path.length], m: [0, 0, 0] });
      if (r < T.rounds - 1) k.push({ t: fe + (r + 1) * T.gap, p: T.path[(2 * r + 1) % T.path.length], m: [0, 0, 0] });
    }
    k.push({ t: T.launch + this.strafeDuration + T.pull + (T.rounds - 1) * T.gap, p: T.center, m: [0, 0, 0] });
    for (let i = 1; i < k.length - 1; i++) {
      const dt = k[i + 1].t - k[i - 1].t;
      for (let j = 0; j < 3; j++) k[i].m[j] = (k[i + 1].p[j] - k[i - 1].p[j]) / dt;
    }
    this.keys = k;
  }

  /** 航线上 t 秒时整群的中心（相对坦克；三次 Hermite，速度连续；起点以前 / 终点以后 = 原来轨道的中心） */
  private offAt(t: number, o: [number, number, number]): void {
    const k = this.keys;
    o[0] = SWARM.center[0];
    o[1] = SWARM.center[1];
    o[2] = SWARM.center[2];
    if (t <= 0 || t >= k[k.length - 1].t) return;
    let i = 0;
    while (i < k.length - 2 && t >= k[i + 1].t) i++;
    const a = k[i];
    const b = k[i + 1];
    const D = b.t - a.t;
    const u = (t - a.t) / D;
    const u2 = u * u;
    const u3 = u2 * u;
    const h00 = 2 * u3 - 3 * u2 + 1;
    const h10 = u3 - 2 * u2 + u;
    const h01 = -2 * u3 + 3 * u2;
    const h11 = u3 - u2;
    for (let j = 0; j < 3; j++) o[j] = h00 * a.p[j] + h10 * D * a.m[j] + h01 * b.p[j] + h11 * D * b.m[j];
  }

  protected step(ctx: UltContext): void {
    if (this.t < 0) {
      if (this.moody) {
        this.moody = false;
        ctx.mood(null, 0.6);
      }
      return;
    }
    const T = SWARM;
    const dt = ctx.dt;
    this.t += dt;
    this.frameN += 1;
    const P = ctx.tank.group.position;
    const strafeEnd = T.launch + this.strafeDuration;
    const diveAt = strafeEnd + T.pull;
    // 开火时钟：兜圈时停（这段不开火，轨道跟着坦克平移），其余时候和原来的时间轴一模一样地走
    const gapping = this.gapT > 0;
    if (gapping) {
      this.gapT -= dt;
      const mx = P.x - this.px;
      const mz = P.z - this.pz;
      for (const b of this.birds) {
        if (b.mode !== 1) continue;
        b.x += mx;
        b.z += mz;
      }
      // 兜完圈：下一轮压过来
      if (this.gapT <= 0) {
        this.dark(ctx, this.round, false, 0.35);
        ctx.audio.play('mg', 0.5);
        ctx.audio.play('mg', 0.45, 1.05, 0.06);
        ctx.audio.play('mg', 0.4, 0.95, 0.12);
      }
    } else {
      this.ft += dt;
      if (this.round < T.rounds - 1 && this.ft >= this.roundEnd(this.round)) this.endRound(ctx);
    }
    this.px = P.x;
    this.pz = P.z;
    const ft = this.ft;
    // 拉高：一声尖哨；最后一轮的收尾震动
    if (!this.whistled && ft >= strafeEnd) {
      this.whistled = true;
      ctx.audio.play('incoming', 0.9);
      this.roundShake(ctx, T.rounds - 1);
      this.dark(ctx, T.rounds, false, 0.4);
    }
    // 俯冲开始：分配目标；没目标就继续盘旋（最多 linger 秒），之后飞回蜂箱
    if (!this.allotted && ft >= diveAt) {
      if (this.allot(ctx, ft)) {
        this.allotted = true;
        // 黑潮扑下来那一刻：慢放一下，天光回来
        if (!this.dove) {
          this.dove = true;
          ctx.slowmo(T.slow[0], T.slow[1]);
          this.moody = false;
          ctx.mood(null, 1);
        }
      }
      else {
        this.wait += dt;
        if (this.wait >= T.linger) {
          this.allotted = true;
          for (const b of this.birds) if (b.mode === 1) b.mode = 3;
        }
      }
    }
    // 这一轮最后 burst 秒：火力收拢
    const closing = !gapping && ft < strafeEnd && this.roundEnd(this.round) - ft < T.burst;
    let alive = 0;
    let shown = 0;
    for (const b of this.birds) {
      if (b.mode === 4) continue;
      alive += 1;
      if (b.mode === 0) {
        if (ft < b.at) continue;
        // 出蜂箱：从舱口直接冒出来
        const h = ctx.tank.turretPoint(b.cx > 0 ? 0.17 : -0.17, 1.15, 0.92 + (shown % 3) * 0.3, this.v);
        b.x = h.x;
        b.y = h.y;
        b.z = h.z;
        b.lx = h.x;
        b.ly = h.y;
        b.lz = h.z;
        b.vx = h.x;
        b.vy = h.y;
        b.vz = h.z;
        b.mode = 1;
        ctx.fx.smokeP.emit({ x: h.x, y: h.y, z: h.z, vy: 1.5, life: 0.5, size: 0.4, size1: 1.2, color: 0xc8c4bc, alpha: 0.5, frame: 1, drag: 2 });
      }
      if (b.mode === 1) {
        // 画出来的位置 = 航线上整群的中心（落后 lag 秒）+ 自己在原来轨道里的位置收拢 squeeze 倍；刚出蜂箱的那 0.6 秒慢慢接上
        const tt = this.t - b.lag;
        this.offAt(tt, this.o);
        const C = T.center;
        const sq = 1 - (1 - T.squeeze) * Math.min(1, Math.max(0, tt / 0.8), Math.max(0, (this.keys[this.keys.length - 1].t - tt) / T.pull));
        const out = Math.min(1, (ft - b.at) / 0.6);
        b.ox = (this.o[0] - C[0] - (1 - sq) * (b.x - P.x - C[0])) * out;
        b.oy = (this.o[1] - C[1] - (1 - sq) * (b.y - C[1])) * out;
        b.oz = (this.o[2] - C[2] - (1 - sq) * (b.z - P.z - C[2])) * out;
        if (!gapping) this.orbit(ctx, b, ft, P, dt, strafeEnd, closing);
        this.trail(ctx, b, shown);
      } else {
        b.ox = b.oy = b.oz = 0;
        if (b.mode === 2) this.diveStep(ctx, b, dt);
        else if (b.mode === 3) {
          // 飞回蜂箱
          const h = ctx.tank.turretPoint(0, 1.2, 1.2, this.v);
          const dx = h.x - b.x;
          const dy = h.y - b.y;
          const dz = h.z - b.z;
          const d = Math.hypot(dx, dy, dz);
          if (d < 1) b.mode = 4;
          else {
            const k = Math.min(1, (30 * dt) / d);
            b.x += dx * k;
            b.y += dy * k;
            b.z += dz * k;
          }
        }
      }
      if (b.mode !== 4) this.place(b, shown++, dt);
    }
    this.mesh!.count = shown;
    this.mesh!.instanceMatrix.needsUpdate = true;
    if (alive === 0) {
      this.end();
      return;
    }
    this.active = Math.max(0.1, (this.allotted ? 1 : this.strafeLeft() + Math.max(0, diveAt - Math.max(ft, strafeEnd)) + 1.5 + (this.wait > 0 ? T.linger - this.wait : 0)));
  }

  /** 一轮打完：整群停火兜圈 gap 秒；收尾一下震动、电机呼啸，天光亮回来一点 */
  private endRound(ctx: UltContext): void {
    const T = SWARM;
    this.roundShake(ctx, this.round);
    this.round += 1;
    this.gapT = T.gap;
    this.dark(ctx, this.round - 1, true, 0.5);
    ctx.audio.play('swoop', 0.9, 1 + this.round * 0.08);
  }

  /** 第 k 轮收尾的震动：一轮比一轮重；第二轮起带一段余震 */
  private roundShake(ctx: UltContext, k: number): void {
    const T = SWARM;
    const f = T.rounds > 1 ? k / (T.rounds - 1) : 1;
    ctx.shake(T.endShake[0] + (T.endShake[1] - T.endShake[0]) * f);
    if (k > 0) ctx.rumble(0.05 * k, 0.4 + 0.2 * k);
  }

  /** 翻飞：跟着坦克往前走的小椭圆 + 噪声；扫射期间每 mgGap 秒打一发；拉高阶段停火、升高 3 米、机腹灯红白快闪 */
  private orbit(ctx: UltContext, b: Bird, t: number, P: THREE.Vector3, dt: number, strafeEnd: number, closing: boolean): void {
    const T = SWARM;
    b.ph += b.sp * dt;
    const pull = Math.min(1, Math.max(0, (t - strafeEnd) / T.pull));
    const wx = P.x + b.cx + Math.cos(b.ph) * b.rad + Math.sin(t * 0.9 + b.nz) * 1.2;
    const wz = P.z - b.cz + Math.sin(b.ph) * b.rad * 0.6 + Math.cos(t * 0.7 + b.nz) * 1.2;
    const wy = b.alt + pull * 3 + Math.sin(t * 1.7 + b.nz) * 0.6;
    // 刚出蜂箱的那一下快速爬到自己的轨道上
    const k = Math.min(1, dt * (t - b.at < 0.6 ? 6 : 10));
    b.x += (wx - b.x) * k;
    b.y += (wy - b.y) * k;
    b.z += (wz - b.z) * k;
    const vx = b.x + b.ox;
    const vy = b.y + b.oy;
    const vz = b.z + b.oz;
    if (t >= strafeEnd) {
      // 拉高预警：机腹灯从红变白快闪
      if (Math.random() < 0.35) ctx.fx.glow.emit({ x: vx, y: vy - 0.2, z: vz, life: 0.06, size: 0.9, size1: 0.5, color: pull > 0.5 && t % 0.1 < 0.05 ? 0xffffff : 0xff3a22, frame: 0 });
      return;
    }
    if (Math.random() < 0.15) ctx.fx.glow.emit({ x: vx, y: vy - 0.2, z: vz, life: 0.08, size: 0.6, size1: 0.3, color: 0xff3a22, frame: 0 });
    if (t < T.launch * 0.5) return;
    b.mgT -= dt;
    if (b.mgT > 0) return;
    b.mgT += T.mgGap;
    const e = this.strafeTarget(ctx, b.x, b.z);
    if (!e) return;
    const ex = e.group.position.x + rand(-0.6, 0.6);
    const ez = e.group.position.z + rand(-0.6, 0.6);
    ctx.damage(e, T.mgDmg * this.overload, b.x, b.z, { type: 'small', kind: 'bullet', summon: true, ult: true });
    // 子弹擦到旁边的路边景物（扫，T009 第 8 节）：掉针叶、碎玻璃、崩白灰，不扣结构、不推倒
    ctx.scenery.strafe(ex, ez, ex - b.x, ez - b.z);
    // 曳光往下泼（T060 每发都画，同时在场十来根）+ 枪口一闪；每轮收尾那一下落点崩土
    ctx.streaks.add(vx, vy - 0.3, vz, ex, 0.8, ez, 0.07, 0xffd27a, 0.9, 0.07);
    ctx.fx.glow.emit({ x: vx, y: vy - 0.4, z: vz, life: 0.05, size: 0.9, size1: 0.4, color: 0xffe0a0, frame: 0 });
    if (Math.random() < (closing ? 0.4 : 0.2)) ctx.fx.impact(ex, 0.8, ez, closing ? 0.7 : 0.5);
    if (Math.random() < 0.08) ctx.audio.play('mg', 0.35);
  }

  /** 扫射 / 兜圈时每枚拖一道细光尾（隔一帧接一节，两种颜色错开） */
  private trail(ctx: UltContext, b: Bird, i: number): void {
    const x = b.x + b.ox;
    const y = b.y + b.oy;
    const z = b.z + b.oz;
    if ((this.frameN + i) % 2) return;
    if (Math.hypot(x - b.lx, y - b.ly, z - b.lz) > 0.3) ctx.streaks.add(b.lx, b.ly, b.lz, x, y, z, i % 2 ? 0.12 : 0.08, i % 2 ? 0xffb060 : 0xffe2b0, 0.55, 0.32, 1.5);
    b.lx = x;
    b.ly = y;
    b.lz = z;
  }

  /** 扫射目标：地面投影 mgRange 米内，步兵 > 轻甲 > 重甲，同级里先打近的 */
  private strafeTarget(ctx: UltContext, x: number, z: number): Enemy | null {
    const R = SWARM.mgRange;
    let best: Enemy | null = null;
    let bs = Infinity;
    for (const e of ctx.enemies) {
      if (!e.alive) continue;
      const d = Math.hypot(e.group.position.x - x, e.group.position.z - z);
      if (d > R) continue;
      const s = (e.armor === 'none' ? 0 : e.armor === 'light' ? 1 : 2) * 1000 + d;
      if (s < bs) {
        bs = s;
        best = e;
      }
    }
    return best;
  }

  /** 击毁 e 要几枚（按穿甲后的爆炸伤害；重甲净 ×1.2） */
  private need(e: Enemy): number {
    const mult = ARMOR_MULT[e.armor].blast * (e.armor === 'heavy' ? 1.6 : 1);
    return Math.max(1, Math.ceil(Math.max(1, e.hp) / (SWARM.diveDmg * mult)));
  }

  /**
   * 分配目标（拉高结束时）：重点目标先拿 min(focus, 要的枚数)，其余每个目标先一枚，再按「还差几枚 × 威胁值」多分；分完还剩就轮着给威胁最高的。
   * 没有目标返回 false
   */
  private allot(ctx: UltContext, t: number): boolean {
    const T = SWARM;
    const P = ctx.tank.group.position;
    // 巨炮在场时前方够到对轰射程（D5）
    const ahead = Math.max(T.reach[0], ctx.duel);
    const cands = ctx.enemies.filter((e) => e.alive && P.z - e.group.position.z <= ahead && e.group.position.z - P.z <= T.reach[1] && Math.abs(e.group.position.x - P.x) < 45);
    if (!cands.length) return false;
    const birds = this.birds.filter((b) => b.mode === 1);
    if (!birds.length) return true;
    if (!this.focus?.alive) this.focus = ctx.pick();
    const dist = (e: Enemy) => Math.hypot(e.group.position.x - P.x, e.group.position.z - P.z);
    const threat = (e: Enemy) => e.spec.threat ?? 1;
    const plan = new Map<Enemy, number>();
    let left = birds.length;
    const focus = this.focus && cands.includes(this.focus) ? this.focus : null;
    if (focus) {
      const n = Math.min(T.focus, this.need(focus), left);
      plan.set(focus, n);
      left -= n;
    }
    const rest = cands.filter((e) => e !== focus).sort((a, b) => threat(b) - threat(a) || dist(a) - dist(b));
    for (const e of rest) {
      if (left <= 0) break;
      plan.set(e, 1);
      left -= 1;
    }
    while (left > 0) {
      let best: Enemy | null = null;
      let bs = 0;
      for (const e of rest) {
        const short = this.need(e) - (plan.get(e) ?? 0);
        if (short > 0 && short * threat(e) > bs) {
          bs = short * threat(e);
          best = e;
        }
      }
      if (!best) break;
      plan.set(best, (plan.get(best) ?? 0) + 1);
      left -= 1;
    }
    // 还剩：轮着给重点目标以外威胁最高的（首领战里多半扎首领）；只剩重点目标一个时才全给它
    const top = (rest.length ? rest : [...plan.keys()]).sort((a, b) => threat(b) - threat(a));
    for (let i = 0; left > 0; i++, left--) plan.set(top[i % top.length], (plan.get(top[i % top.length]) ?? 0) + 1);
    let i = 0;
    for (const [e, n] of plan) {
      e.ultMark = n;
      for (let k = 0; k < n && i < birds.length; k++, i++) {
        const b = birds[i];
        b.mode = 2;
        b.target = e;
        b.tx = e.group.position.x;
        b.tz = e.group.position.z;
        // 错开出发，约 0.5 秒里依次扎下去
        b.diveAt = t + (i / birds.length) * 0.5;
      }
    }
    return true;
  }

  /** 俯冲：到点出发，以 dive 米/秒追着目标扎下去，拖白烟；碰到地面 / 目标就炸 */
  private diveStep(ctx: UltContext, b: Bird, dt: number): void {
    const T = SWARM;
    if (this.ft < b.diveAt) return;
    if (b.target && !b.target.alive) {
      // 目标在途中被击毁：改扎它 retarget 米内最近的活敌人，没有就扎原位置
      let best: Enemy | null = null;
      let bd = T.retarget;
      for (const e of ctx.enemies) {
        if (!e.alive) continue;
        const d = Math.hypot(e.group.position.x - b.tx, e.group.position.z - b.tz);
        if (d < bd) {
          bd = d;
          best = e;
        }
      }
      b.target = best;
    }
    if (b.target) {
      b.tx = b.target.group.position.x;
      b.tz = b.target.group.position.z;
    }
    // 天上的目标（T105：直升机、「云垒」部件）扎到它那个高度、在它身上空爆；原来一律扎到它正下方的地面，天上的一个都打不到
    const sky = b.target?.alive && b.target.flying ? b.target : null;
    const ty = sky ? sky.group.position.y : ctx.fx.groundAt(b.tx, b.tz) + (b.target ? 0.8 * b.target.size : 0);
    const dx = b.tx - b.x;
    const dy = ty - b.y;
    const dz = b.tz - b.z;
    const d = Math.hypot(dx, dy, dz);
    const step = T.dive * dt;
    b.puffT -= dt;
    if (b.puffT <= 0) {
      b.puffT = 0.125;
      ctx.fx.smokeP.emit({ x: b.x, y: b.y, z: b.z, vx: rand(-0.3, 0.3), vy: rand(0, 0.4), vz: rand(-0.3, 0.3), life: 0.6, size: 0.5, size1: 1.4, color: 0xe8e4dc, alpha: 0.55, frame: 1, drag: 1.5 });
    }
    if (d > step + 1) {
      const ox = b.x;
      const oy = b.y;
      const oz = b.z;
      b.x += (dx / d) * step;
      b.y += (dy / d) * step;
      b.z += (dz / d) * step;
      // 发动机光尾（T057）
      ctx.streaks.add(ox, oy, oz, b.x, b.y, b.z, 0.22, 0xffc880, 0.8, 0.22, 2);
      return;
    }
    // 扎到：100 爆炸 + 穿甲（爆·顶），被扎中的车辆断履带
    const A = ultHalf(ctx.mods.area);
    const tg = b.target;
    ctx.explode(b.tx, b.tz, T.diveR * A, T.diveDmg * this.overload, { type: 'blast', kind: 'blast', summon: true, ap: true, knock: 5, ult: true, top: true, pit: 0, air: sky ? Math.max(0, b.y - ctx.fx.groundAt(b.tx, b.tz)) : undefined });
    // 一串连环爆（T057）：每枚多一团火光、地上一块焦痕，重震一点点叠起来（天上炸的不留焦痕）
    const gy = sky ? b.y - 1.5 : ctx.fx.groundAt(b.tx, b.tz);
    ctx.fx.glow.emit({ x: b.tx, y: gy + 1.5, z: b.tz, life: 0.18, size: 7, size1: 10, color: 0xfff0d0, color1: 0xff8a30, alpha: 0.85, frame: 0 });
    if (!sky) ctx.fx.decals.add(0, b.tx, b.tz, 4.5, 4.5, Math.random() * 6.28, 0.7, 18);
    ctx.shake(T.boomShake);
    if (!this.kicked) {
      this.kicked = true;
      ctx.kick(T.kick);
    }
    if (tg?.alive && !tg.controller && !tg.spec.crushable) tg.track = Math.max(tg.track, tg.spec.blocker ? T.trackElite : T.track);
    if (tg) tg.ultMark = Math.max(0, tg.ultMark - 1);
    b.mode = 4;
  }

  /** 写这枚的实例矩阵：翻飞 / 兜圈时机头朝画出来的飞行方向、转弯时压坡度；俯冲时扎下去 */
  private place(b: Bird, i: number, dt: number): void {
    const x = b.x + b.ox;
    const y = b.y + b.oy;
    const z = b.z + b.oz;
    let yaw: number;
    let pitch = 0.1;
    if (b.mode === 2) {
      yaw = Math.atan2(-(b.tx - b.x), -(b.tz - b.z));
      pitch = -0.9;
      b.roll *= 0.9;
    } else {
      const mx = x - b.vx;
      const my = y - b.vy;
      const mz = z - b.vz;
      const sp = Math.hypot(mx, mz);
      if (sp > 1e-3) {
        const want = Math.atan2(-mx, -mz);
        let dy = want - b.yaw;
        dy -= Math.round(dy / (Math.PI * 2)) * Math.PI * 2;
        const k = Math.min(1, dt * 8);
        b.yaw += dy * k;
        b.roll += (THREE.MathUtils.clamp(dy * 2.5, -0.8, 0.8) - b.roll) * k;
        pitch = THREE.MathUtils.clamp(Math.atan2(my, sp) * 0.6, -0.5, 0.5) + 0.05;
      }
      yaw = b.yaw;
    }
    b.vx = x;
    b.vy = y;
    b.vz = z;
    this.q.setFromEuler(this.e.set(pitch, yaw, b.roll + Math.sin(b.ph) * 0.12, 'YXZ'));
    this.mesh!.setMatrixAt(i, this.m.compose(this.p.set(x, y, z), this.q, this.s.setScalar(SWARM.look)));
  }

  private end(): void {
    this.t = -1;
    if (this.mesh) this.mesh.visible = false;
    for (const b of this.birds) if (b.target) b.target.ultMark = 0;
    this.birds = [];
    this.focus = null;
    this.finish();
  }

  protected clear(): void {
    this.t = -1;
    this.ft = 0;
    this.round = 0;
    this.gapT = 0;
    for (const b of this.birds) if (b.target) b.target.ultMark = 0;
    this.birds = [];
    this.focus = null;
    this.allotted = false;
    if (this.mesh) this.mesh.visible = false;
  }

  override dispose(): void {
    super.dispose();
    this.mesh?.removeFromParent();
    this.mesh?.dispose();
    this.mesh = null;
  }
}
