const STEEL = 0x8e8a86;
const STEEL_D = 0x6a6662;
const DARK = 0x3e3c3a;
const RED = 0xa8382c;
const TRACK = 0x2e2c2a;

const box = (w: number, h: number, d: number) => new THREE.BoxGeometry(w, h, d);
const cyl = (rt: number, rb: number, h: number, s = 12) => new THREE.CylinderGeometry(rt, rb, h, s);
const v = new THREE.Vector3();
const angleTo = (x: number, z: number, tx: number, tz: number) => Math.atan2(tx - x, tz - z);
/** 首领机枪每发伤害（T023-a 减半：猛犸 1.6 → 0.8、铁砧列车 1.1 → 0.55；主炮 / 火箭照旧疼） */
export const BOSS_MG = { mammoth: 0.8, anvil: 0.55 };

/** 瞄准线 → 锁定 → 开火 的通用计时器 */
class Telegraph {
  t = 0;
  angle = 0;
  constructor(
    readonly interval: number,
    readonly aim: number,
    readonly lock = 0.3,
  ) {
    this.t = interval * (0.4 + rng.boss() * 0.5);
  }

  /** 返回 'idle' | 'aim' | 'fire' */
  tick(delta: number, track: () => number): 'idle' | 'aim' | 'fire' {
    this.t -= delta;
    if (this.t > this.aim) return 'idle';
    if (this.t > this.lock) this.angle = track();
    if (this.t > 0) return 'aim';
    this.t = this.interval;
    return 'fire';
  }
}

// ======================================================================
// 区域 1：要塞坦克「猛犸」
// ======================================================================

/** 猛犸车体转向速度（弧度/秒，× 狂暴倍率；T017-8A） */
const MAMMOTH_TURN = 0.45;
/** 最终阶段往前压最远到离停车点多少米（T107：当时的车身限位 15 米 + HOLD_MOVE.room；T109 车身限位改按模型算，猛犸压到哪不跟着变） */
const MAMMOTH_PRESS = 15 + HOLD_MOVE.room;

export class FortressTank extends Boss {
  readonly name = '要塞坦克「猛犸」';
  /** 首领特写（T017-6）：宽 10、长 17、高 6 米 */
  protected override readonly showR = 7.5;
  protected override readonly showY = 2.6;
  /** 车体（含两侧机枪塔、尾部火箭巢）；炮塔单独挂在 root 上，残骸被压时会被顶下车体 */
  private readonly hull: THREE.Group;
  private readonly turret: THREE.Group;
  private readonly sponsons: THREE.Group[] = [];
  private readonly main = new Telegraph(3.4, 1.0);
  private readonly mg = [2.0, 2.6];
  private readonly burst = [0, 0];
  private pod = 4;
  /** 履带约束（T017-8A）：据守的纵向位置（第三阶段往前压时跟着挪）、停下多久了 */
  private homeZ: number;
  private idleT = 0;
  /** 车体在地上占的那一块（车体网格的包围盒：履带 / 侧裙 / 车身，机枪塔座在里面；炮管不算），T109 车身限位跟着车体朝向转 */
  private readonly foot: THREE.Box3;

  constructor(ctx: BossContext, x: number, z: number) {
    super(ctx, x, z);
    this.homeZ = z;
    const r = this.root;
    this.hull = this.group(r, 0, 0, 0);
    const hullMesh = this.mesh(this.hull, 'boss-fortress-hull', () => [
      { geo: frustum(rect(6.6, 10.6), rect(7.0, 11.4), 1.5, 0.7), color: STEEL_D },
      { geo: profileExtrude([[5.7, 2.2], [3.8, 3.6], [-4.6, 3.6], [-5.6, 2.8], [-5.6, 2.2]], 6.2), color: STEEL },
      ...[-1, 1].flatMap((s): PartSpec[] => [
        { geo: profileExtrude(stadium(11.6, 2.2), 1.7), color: TRACK, pos: [s * 3.95, 0, 0] },
        { geo: box(1.9, 0.12, 11.8), color: STEEL_D, pos: [s * 3.95, 2.3, 0] },
        ...[-4, -2, 0, 2, 4].map((zz): PartSpec => ({ geo: box(0.2, 1.3, 1.9), color: STEEL, pos: [s * 4.85, 1.5, zz] })),
      ]),
      { geo: box(6.3, 0.14, 0.4), color: RED, pos: [0, 3.62, -1] },
      ...[-1.6, -0.5, 0.6, 1.7].map((xx): PartSpec => ({ geo: box(0.9, 0.12, 0.6), color: DARK, pos: [xx, 3.2, 4.6], rot: [-0.6, 0, 0] })),
      ...[-1, 1].map((s): PartSpec => ({ geo: cyl(0.3, 0.34, 1.2), color: 0x3a2a22, pos: [s * 2.2, 3.4, -5.6], rot: [-0.4, 0, 0] })),
    ]);
    hullMesh.geometry.computeBoundingBox();
    this.foot = hullMesh.geometry.boundingBox!.clone();
    // 主炮塔（核心）
    this.turret = this.group(r, 0, 3.6, 0.6);
    this.mesh(this.turret, 'boss-fortress-turret', () => [
      { geo: frustum(chamfer(5.0, 5.4, 1.2), chamfer(4.0, 4.2, 1.0), 1.7), color: STEEL },
      { geo: frustum(chamfer(5.05, 5.45, 1.2), chamfer(5.0, 5.4, 1.2), 0.18, 0.4), color: RED },
      { geo: frustum(rect(3.6, 1.8, 0, -3.0), rect(3.2, 1.5, 0, -2.9), 1.2, 0.2), color: STEEL_D },
      { geo: box(3.0, 1.2, 1.2), color: STEEL_D, pos: [0, 0.9, 2.6] },
      ...[-1, 1].map((s): PartSpec => ({ geo: barrel(7.2, 0.36, { brake: true, evacuator: true }), color: STEEL_D, pos: [s * 0.95, 0.9, 2.9] })),
      { geo: cyl(0.6, 0.66, 0.5), color: STEEL_D, pos: [1.1, 1.95, -0.6] },
    ]);
    this.glow(this.turret, 0.16, 'red', -1.2, 1.8, 1.4);
    // 两侧机枪塔
    for (const s of [-1, 1]) {
      const g = this.group(this.hull, s * 3.3, 3.0, 3.4);
      this.mesh(g, 'boss-fortress-sponson', () => [
        { geo: cyl(0.85, 0.95, 0.9), color: STEEL },
        ...[-0.22, 0.22].map((xx): PartSpec => ({ geo: barrel(2.2, 0.08), color: DARK, pos: [xx, 0.1, 0.6] })),
        { geo: box(1.0, 0.12, 0.3), color: RED, pos: [0, 0.48, 0] },
      ]);
      this.sponsons.push(g);
    }
    // 尾部火箭巢
    const pod = this.group(this.hull, 0, 3.7, -3.9);
    this.mesh(pod, 'boss-fortress-pod', () => {
      const p: PartSpec[] = [{ geo: box(3.0, 1.4, 1.8), color: STEEL_D, pos: [0, 0.7, 0] }];
      for (let i = 0; i < 4; i++) for (let j = 0; j < 2; j++) p.push({ geo: cyl(0.2, 0.2, 0.1), color: 0x111111, pos: [-1.05 + i * 0.7, 0.45 + j * 0.55, 0.92], rot: [Math.PI / 2, 0, 0] });
      return p;
    });
    pod.rotation.x = -0.3;
    const s = ctx.hpScale;
    this.addPart(this.turret, 2100 * s, 3.2, true, null, 'core');
    this.sponsons.forEach((g, i) => this.addPart(g, 420 * s, 1.6, false, g, `mg${i}`));
    this.addPart(pod, 500 * s, 2.0, false, pod, 'pod');
  }

  private carpet = 5;

  protected override onPhase(phase: number): void {
    const r = this.root.position;
    if (phase === 1) {
      for (const dx of [-8, 8]) this.ctx.spawn('gunner', r.x + dx, r.z + 6);
      for (let i = 0; i < 6; i++) this.ctx.spawn('infantry', r.x - 6 + i * 2.4, r.z + 10);
    } else {
      for (const dx of [-9, 0, 9]) this.ctx.spawn('rusher', r.x + dx, r.z + 4);
      for (const dx of [-7, 7]) this.ctx.spawn('rocketeer', r.x + dx, r.z + 8);
    }
  }

  protected step(delta: number): void {
    const P = this.target;
    const r = this.root;
    // 横向慢慢对位玩家，纵向据守；最终阶段往前压。履带约束（T017-8A）：车体只能沿车头前进 / 倒车，横向对位要先原地转向（主炮塔单独朝玩家）
    const dx = P.x - r.position.x;
    let vx = Math.abs(dx) > 1.5 && Math.abs(r.position.x + Math.sign(dx)) <= 6 ? Math.sign(dx) * 1.2 * this.rage : 0;
    // 往前压最远到离停车点 MAMMOTH_PRESS 米（T107：原来你往后撤它一路追，停车点被它占掉，再也推不回去）
    const press = this.anchorZ === null ? Infinity : this.anchorZ - MAMMOTH_PRESS;
    if (this.phase === 2 && P.z - r.position.z > 24) this.homeZ = Math.min(r.position.z + 2, Math.max(press, this.homeZ));
    const off = this.homeZ - r.position.z;
    const vz = Math.abs(off) > 0.5 ? THREE.MathUtils.clamp(off * 0.8, -1.6, 1.6) : 0;
    if (Math.abs(off) > 3) vx *= 0.3;
    const hull = this.hull;
    if (vx !== 0 || vz !== 0) {
      this.idleT = 0;
      const [yaw, mx, mz] = trackStep(hull.rotation.y, vx, vz, MAMMOTH_TURN * this.rage, delta, true);
      hull.rotation.y = yaw;
      r.position.x += mx;
      r.position.z += mz;
    } else if ((this.idleT += delta) > 0.8) {
      // 停下来：车头慢慢转回正对道路
      const step = MAMMOTH_TURN * 0.6 * delta;
      hull.rotation.y -= THREE.MathUtils.clamp(hull.rotation.y, -step, step);
    }
    r.position.x = THREE.MathUtils.clamp(r.position.x, -6, 6);
    const yaw = angleTo(r.position.x, r.position.z, P.x, P.z);
    this.turret.rotation.y += (yaw - this.turret.rotation.y) * Math.min(1, delta * 1.5);

    const core = this.alive('core');
    if (core) {
      const st = this.main.tick(delta, () => angleTo(r.position.x, r.position.z, P.x, P.z));
      core.e.laser.visible = st === 'aim' && Math.sin(this.t * 30) > -0.4;
      core.e.laser.rotation.y = this.main.angle;
      core.e.laser.scale.set(2.4, 1, 70);
      core.e.laser.position.y = 4.5;
      if (st === 'fire') {
        core.e.laser.visible = false;
        this.main.t /= this.rage;
        // 第二阶段起主炮三连发扇形
        const fan = this.phase >= 1 ? [-0.12, 0, 0.12] : [0];
        for (const f of fan) for (const s of [-1, 1]) {
          const a = this.main.angle + f;
          const ox = r.position.x + Math.cos(a) * s * 0.95;
          const oz = r.position.z - Math.sin(a) * s * 0.95;
          this.ctx.fire('shell', ox + Math.sin(a) * 9, oz + Math.cos(a) * 9, Math.sin(a), Math.cos(a), 30, 22);
          this.ctx.fx.muzzle(ox + Math.sin(a) * 10, 4.5, oz + Math.cos(a) * 10, Math.sin(a), Math.cos(a), 2.2);
        }
        this.ctx.audio.play('charge');
        this.ctx.shake(0.4);
      }
    }
    this.sponsons.forEach((g, i) => {
      const p = this.alive(`mg${i}`);
      if (!p) return;
      const pos = this.partPos(p, v);
      const a = angleTo(pos.x, pos.z, P.x, P.z);
      // 机枪塔挂在车体上：车体转了多少要减掉
      g.rotation.y = a - this.hull.rotation.y;
      this.mg[i] -= delta;
      if (this.mg[i] <= 0) {
        this.mg[i] = (2.0 + rng.boss() * 0.6) / this.rage;
        this.burst[i] = 8;
      }
      if (this.burst[i] > 0 && rng.boss() < delta * 14) {
        this.burst[i]--;
        const s = a + (rng.boss() - 0.5) * 0.12;
        this.ctx.fire('rifle', pos.x + Math.sin(s) * 2, pos.z + Math.cos(s) * 2, Math.sin(s), Math.cos(s), 70, BOSS_MG.mammoth);
        this.ctx.fx.glint(pos.x + Math.sin(s) * 2.2, pos.y, pos.z + Math.cos(s) * 2.2, 0xfff0b0, 0.9);
        this.ctx.audio.play('mg');
      }
    });
    if (this.alive('pod')) {
      this.pod -= delta;
      if (this.pod <= 0) {
        this.pod = 6.5 / this.rage;
        for (let i = 0; i < 6 + this.phase * 2; i++) {
          this.ctx.artillery(r.position.x, r.position.z - 4, P.x + (rng.boss() - 0.5) * 14, P.z + (rng.boss() - 0.5) * 10, 16, 3.6, 1.6 + i * 0.12);
        }
        this.ctx.audio.play('rocket');
      }
    }
    // 第二阶段起：横跨道路的一排炮击，只留一个缺口
    if (this.phase >= 1) {
      this.carpet -= delta;
      if (this.carpet <= 0) {
        this.carpet = 7 / this.rage;
        this.carpetLine(r.position.x, r.position.z, P.z - 1, 20);
        this.ctx.audio.play('mortar');
      }
    }
  }

  /** 车身限位（T109）：车体那一块跟着车体朝向转（转着对位时斜角伸得最远） */
  override front(): number {
    return this.root.position.z + boxFront(this.foot, this.hull.rotation.y);
  }

  protected override collapse(k: number): void {
    this.turret.rotation.z = k * 0.25;
    this.turret.position.y = 3.6 - k * 0.4;
  }

  /** 残骸被压时炮塔被顶下车体：-1 = 还没开始，0..1 = 翻落进度 */
  private topple = -1;
  private toppleSide = 1;
  private readonly toppleFrom = new THREE.Vector3();
  private toppleYaw = 0;
  private toppleRoll = 0;

  protected override settleWreck(): void {
    // 大块头：压完剩 1 米高的一摊，坦克撞上来那一下先塌到 2 米。
    // 车体可能是转着被毁的（履带约束）：先按不转的样子量包围盒，再把凸起绕 root 原点转回车体的朝向
    const yaw = this.hull.rotation.y;
    this.hull.rotation.y = 0;
    const n = this.pieces.length;
    this.crushable(this.hull, 1.0, 2.0, 9, undefined, 0.12);
    this.hull.rotation.y = yaw;
    this.root.updateMatrixWorld(true);
    const b = this.pieces.length > n ? this.pieces[n].bump : null;
    if (b && yaw !== 0) {
      const ox = b.x - this.root.position.x;
      const oz = b.z - this.root.position.z;
      b.x = this.root.position.x + ox * Math.cos(yaw) + oz * Math.sin(yaw);
      b.z = this.root.position.z - ox * Math.sin(yaw) + oz * Math.cos(yaw);
      b.rot += yaw;
    }
  }

  protected override crush(p: WreckPiece, f: number): void {
    super.crush(p, f);
    if (p.obj !== this.hull || this.topple >= 0) return;
    // 车体一塌，炮塔被顶得滑下车体，翻到远离坦克的一侧（不挡履带）
    const t = this.turret;
    this.topple = 0;
    this.toppleSide = Math.sign(this.root.position.x + t.position.x - this.target.x) || (Math.random() < 0.5 ? -1 : 1);
    this.toppleFrom.copy(t.position);
    this.toppleYaw = t.rotation.y;
    this.toppleRoll = t.rotation.z;
    this.ctx.audio.play('crunch');
  }

  protected override stepWreck(delta: number): void {
    if (this.topple < 0 || this.topple >= 1) return;
    this.topple = Math.min(1, this.topple + delta / 0.6);
    const k = this.topple;
    const e = 1 - (1 - k) * (1 - k);
    const s = this.toppleSide;
    const t = this.turret;
    // 先被顶起一点、往外滑，再一头栽到地上，炮管垂下去
    t.position.x = this.toppleFrom.x + s * 8 * e;
    t.position.y = THREE.MathUtils.lerp(this.toppleFrom.y, 0.25, k * k) + Math.sin(k * Math.PI) * 0.7;
    t.position.z = this.toppleFrom.z + 0.6 * e;
    t.rotation.set(0.14 * e, this.toppleYaw + s * 0.35 * e, THREE.MathUtils.lerp(this.toppleRoll, -s * 0.42, e));
    if (k < 1) return;
    // 砸到地上：扬尘、碎铁，再登记成一块能压扁的残骸
    t.getWorldPosition(v);
    this.ctx.fx.dirt(v.x, v.z, 2.2);
    this.ctx.debris.chunks(v.x, 1, v.z, 6, 'metal', 1);
    this.ctx.audio.play('crunch');
    this.ctx.shake(0.4);
    this.crushable(t, 0.7, 1.5, 3, [2.5, 2.7]);
  }
}

// ======================================================================
// 区域 2：装甲列车「铁砧」
