const RIVET = 0x5a5652;

/** 一排铆钉（沿 z 方向） */
function rivets(x: number, y: number, z0: number, z1: number, step = 0.9): PartSpec[] {
  const p: PartSpec[] = [];
  for (let z = z0; z <= z1; z += step) p.push({ geo: cyl(0.07, 0.07, 0.08, 6), color: RIVET, pos: [x, y, z], rot: [0, 0, Math.PI / 2] });
  return p;
}

/** 转向架：一组大轮 */
function bogie(z: number, r = 0.85): PartSpec[] {
  return [-1, 1].flatMap((s) => [-1.2, 1.2].map((dz): PartSpec => ({ geo: cyl(r, r, 0.35, 16), color: 0x2a2a2a, pos: [s * 2.0, r, z + dz], rot: [0, 0, Math.PI / 2] })));
}

/**
 * 装甲列车「铁砧」：参照甲铁城的巨型装甲列车。
 * 铁轨出现后从玩家身后高速开上来，贴着路左侧并排行驶：车头在前方、炮车一节节排到身边，近距离对轰。
 */
export class ArmoredTrain extends Boss {
  protected override readonly followGround = false;
  readonly name = '装甲列车「铁砧」';
  /** 列车占着左侧路面，玩家不能再往左开 */
  override readonly laneMin = RAIL_X + 5.5;
  override readonly engageDist = 70;
  override readonly cameraX = -5;
  /** 首领特写（T017-6）：框住车头 + 第一节炮车 */
  protected override readonly showR = 10;
  protected override readonly showY = 4;
  private readonly train: THREE.Group;
  /** 车头 + 三节炮车：残骸一节一节压扁 */
  private readonly cars: THREE.Group[] = [];
  private readonly guns: THREE.Group[] = [];
  private readonly ports: THREE.Object3D[] = [];
  private arrived = false;
  private warned = false;
  private readonly art = { t: 3 };
  private readonly mgT = { t: 1.2, burst: 0, warn: 0, tx: 0, tz: 0 };
  private readonly rocket = new Telegraph(5.0, 1.2);
  private broadside = 6;
  private steamT = 0;

  constructor(ctx: BossContext, _x: number, z: number) {
    super(ctx, RAIL_X, z);
    const r = this.root;
    // 铁轨不再是列车自带的（T017-4A）：整个列车区预铺在路左侧（world/Railway.ts），列车只管车本身
    this.train = this.group(r, 0, 0.5, 0);
    // 从玩家身后 80 米开上来
    this.train.position.z = ctx.player.z + 80 - z;

    // ---------------- 车头（核心）：巨型锅炉 + 高耸装甲驾驶塔 + 双烟囱 + 楔形排障铲
    const loco = this.group(this.train, 0, 0, -26);
    this.cars.push(loco);
    this.mesh(loco, 'boss-train2-loco', () => [
      { geo: box(4.8, 1.3, 17), color: DARK, pos: [0, 1.4, 0] },
      ...bogie(-5.5, 1.0), ...bogie(0, 1.0), ...bogie(5.5, 1.0),
      // 侧裙装甲 + 铆钉
      ...[-1, 1].flatMap((s): PartSpec[] => [
        { geo: box(0.35, 1.9, 16.4), color: STEEL_D, pos: [s * 2.55, 1.7, 0] },
        ...rivets(s * 2.75, 2.4, -7.8, 7.8),
        ...rivets(s * 2.75, 1.1, -7.8, 7.8),
      ]),
      // 锅炉：外包装甲的大圆筒
      { geo: cyl(2.0, 2.0, 9.5, 18), color: STEEL, pos: [0, 4.1, -2.6], rot: [Math.PI / 2, 0, 0] },
      ...[-6.4, -4.2, -2.0, 0.2].map((zz): PartSpec => ({ geo: new THREE.TorusGeometry(2.02, 0.12, 6, 20), color: STEEL_D, pos: [0, 4.1, zz] })),
      { geo: frustum(chamfer(4.2, 1.2, 0.5, 0, -7.6), chamfer(3.2, 0.8, 0.4, 0, -7.9), 4.0, 2.1), color: STEEL_D },
      // 双烟囱
      ...[-5.4, -2.6].flatMap((zz): PartSpec[] => [
        { geo: cyl(0.62, 0.75, 2.8, 12), color: DARK, pos: [0, 7.2, zz] },
        { geo: cyl(0.85, 0.85, 0.3, 12), color: RED, pos: [0, 8.6, zz] },
      ]),
      // 驾驶塔：两层斜面装甲，观察缝
      { geo: frustum(rect(5.0, 6.4, 0, 4.8), rect(4.0, 5.2, 0, 4.9), 3.4, 1.9), color: STEEL },
      { geo: frustum(rect(3.6, 4.0, 0, 5.0), rect(2.6, 3.0, 0, 5.1), 1.6, 5.3), color: STEEL_D },
      ...[-1.2, 0, 1.2].map((xx): PartSpec => ({ geo: box(0.8, 0.18, 0.1), color: 0x111111, pos: [xx, 4.6, 1.55] })),
      { geo: frustum(rect(5.02, 6.42, 0, 4.8), rect(5.0, 6.4, 0, 4.8), 0.3, 4.6), color: RED },
      // 楔形排障铲
      { geo: frustum(rect(5.2, 3.2, 0, -9.4), rect(5.0, 0.4, 0, -8.2), 2.2, 0.3), color: STEEL_D },
      { geo: box(5.3, 0.3, 0.4), color: RED, pos: [0, 1.6, -10.8] },
      // 车头红色徽记
      { geo: cyl(0.9, 0.9, 0.1, 16), color: RED, pos: [0, 4.1, -7.95], rot: [Math.PI / 2, 0, 0] },
    ]);
    this.glow(loco, 0.4, 'red', 0, 5.6, -8.1);
    this.glow(loco, 0.18, 'red', -1.6, 5.4, 1.6);
    this.glow(loco, 0.18, 'red', 1.6, 5.4, 1.6);

    // ---------------- 三节炮车：重炮塔楼 / 机枪堡垒 / 火箭发射车
    const cars: { key: 'art' | 'mg' | 'rocket'; z: number; hp: number }[] = [
      { key: 'art', z: -10.5, hp: 560 },
      { key: 'mg', z: 4, hp: 480 },
      { key: 'rocket', z: 18.5, hp: 520 },
    ];
    const anchors: THREE.Group[] = [];
    for (const c of cars) {
      const car = this.group(this.train, 0, 0, c.z);
      this.cars.push(car);
      this.mesh(car, 'boss-train2-car', () => [
        { geo: box(4.8, 1.1, 13.4), color: DARK, pos: [0, 1.3, 0] },
        ...bogie(-4.2), ...bogie(4.2),
        { geo: frustum(rect(5.0, 12.8), rect(3.9, 11.8), 2.8, 1.85), color: STEEL },
        { geo: frustum(rect(5.02, 12.82), rect(5.0, 12.8), 0.25, 3.0), color: RED },
        ...[-1, 1].flatMap((s): PartSpec[] => [...rivets(s * 2.52, 2.4, -6.2, 6.2, 1.0), ...rivets(s * 2.3, 3.6, -5.8, 5.8, 1.0)]),
        // 车顶护栏
        ...[-1, 1].map((s): PartSpec => ({ geo: box(0.08, 0.5, 11.6), color: DARK, pos: [s * 1.9, 4.9, 0] })),
        // 车厢之间的连接器
        { geo: box(1.2, 0.6, 1.6), color: DARK, pos: [0, 1.4, -7.2] },
      ]);
      const gun = this.group(car, 0, 4.65, 0);
      if (c.key === 'art') {
        this.mesh(gun, 'boss-train2-art', () => [
          { geo: frustum(chamfer(4.0, 4.8, 0.9), chamfer(3.0, 3.6, 0.7), 1.8), color: STEEL },
          { geo: frustum(chamfer(4.02, 4.82, 0.9), chamfer(4.0, 4.8, 0.9), 0.2, 0.5), color: RED },
          { geo: barrel(8.5, 0.42, { brake: true, evacuator: true }), color: STEEL_D, pos: [0, 0.9, 2.2] },
          { geo: box(1.6, 1.2, 1.4), color: STEEL_D, pos: [0, 0.9, -2.3] },
        ]);
      } else if (c.key === 'mg') {
        this.mesh(gun, 'boss-train2-mg', () => [
          { geo: cyl(1.4, 1.6, 1.3, 14), color: STEEL },
          ...[-0.35, 0.35].map((xx): PartSpec => ({ geo: barrel(3.0, 0.11), color: DARK, pos: [xx, 0.25, 1.0] })),
          { geo: box(1.8, 0.16, 0.5), color: RED, pos: [0, 0.7, 0] },
        ]);
        // 朝向道路一侧的三个机枪射孔
        for (const zz of [-4, 0, 4]) {
          const port = new THREE.Object3D();
          port.position.set(2.6, 3.2, zz);
          car.add(port);
          this.ports.push(port);
        }
        this.mesh(car, 'boss-train2-ports', () => [-4, 0, 4].flatMap((zz): PartSpec[] => [
          { geo: box(0.4, 0.7, 1.2), color: STEEL_D, pos: [2.5, 3.2, zz] },
          { geo: barrel(1.4, 0.08), color: DARK, pos: [2.7, 3.2, zz], rot: [0, Math.PI / 2, 0] },
        ]));
      } else {
        this.mesh(gun, 'boss-train2-rocket', () => {
          const p: PartSpec[] = [{ geo: box(3.8, 1.8, 3.6), color: STEEL_D, pos: [0, 0.9, 0] }, { geo: box(3.9, 0.2, 3.7), color: RED, pos: [0, 1.85, 0] }];
          for (let i = 0; i < 4; i++) for (let j = 0; j < 3; j++) p.push({ geo: cyl(0.24, 0.24, 0.12), color: 0x111111, pos: [-1.2 + i * 0.8, 0.45 + j * 0.55, 1.82], rot: [Math.PI / 2, 0, 0] });
          return p;
        });
        gun.rotation.x = -0.25;
      }
      this.guns.push(gun);
      anchors.push(gun);
    }
    const s = ctx.hpScale;
    this.addPart(loco, 2400 * s, 3.6, true, null, 'core');
    cars.forEach((c, i) => this.addPart(anchors[i], c.hp * s, 3.0, false, anchors[i], c.key));
  }

  protected override onPhase(phase: number): void {
    // 援军从车厢里跳下来
    const r = this.root.position;
    const z = r.z + this.train.position.z;
    for (let i = 0; i < 5 + phase * 2; i++) this.ctx.spawn(phase === 2 ? 'shock' : 'infantry', RAIL_X + 4 + rng.boss() * 2, z - 10 + i * 3);
    if (phase === 2) this.ctx.spawn('gunner', -2, z - 30);
  }

  protected step(delta: number): void {
    const P = this.target;
    const r = this.root;
    // 从身后高速追上来，然后贴着玩家并排慢慢前后游走
    const want = P.z - 8 + Math.sin(this.t * 0.3) * 7 - r.position.z;
    const diff = want - this.train.position.z;
    const maxSpeed = this.arrived ? 6 : 26;
    this.train.position.z += THREE.MathUtils.clamp(diff * delta * 1.5, -maxSpeed * delta, maxSpeed * delta);
    if (!this.arrived && Math.abs(diff) < 4) {
      this.arrived = true;
      // 路左侧立起一排混凝土掩体：躲在后面能挡住列车的机枪（会被慢慢打碎）
      for (const dz of [-14, -4, 6]) this.ctx.cover(RAIL_X + 6.5, P.z + dz);
      this.ctx.announce('射孔亮红就横移', '左侧掩体能挡子弹');
    }
    if (!this.warned) {
      this.warned = true;
      this.ctx.announce('装甲列车从后方逼近', '击毁车头');
      this.ctx.audio.play('steam');
    }
    // 双烟囱浓烟，跑得越快越浓
    this.steamT -= delta;
    if (this.steamT <= 0) {
      this.steamT = this.arrived ? 0.08 : 0.04;
      this.root.updateMatrixWorld(true);
      for (const zz of [-31.4, -28.6]) {
        v.set(0, 9.2, zz).applyMatrix4(this.train.matrixWorld);
        this.ctx.fx.smoke(v.x, v.y, v.z, 1.6, 3.2, 0x2a2624, 0.6);
      }
    }
    for (const g of this.guns) {
      g.getWorldPosition(v);
      g.rotation.y = angleTo(v.x, v.z, P.x, P.z);
    }
    if (!this.arrived) return;
    const rage = this.rage;
    const art = this.alive('art');
    if (art) {
      this.art.t -= delta;
      if (this.art.t <= 0) {
        this.art.t = 4.0 / rage;
        const pos = this.partPos(art, v);
        for (let i = 0; i < 3 + this.phase; i++) this.ctx.artillery(pos.x, pos.z, P.x + (rng.boss() - 0.5) * 10, P.z + (rng.boss() - 0.5) * 9, 16, 4, 1.5 + i * 0.15);
        this.ctx.fx.muzzle(pos.x + 2, pos.y + 1, pos.z, 0.9, 0.2, 2.4);
        this.ctx.audio.play('charge');
        this.ctx.shake(0.35);
      }
    }
    const mg = this.alive('mg');
    if (mg) {
      this.mgT.t -= delta;
      if (this.mgT.t <= 0 && this.mgT.warn <= 0 && this.mgT.burst <= 0) {
        // 先预警 0.7 秒（射孔亮红、提示音），锁定玩家此刻的位置，再朝那里扫射：看到红光就横移能躲开
        this.mgT.warn = 0.7;
        this.mgT.tx = P.x;
        this.mgT.tz = P.z;
        this.ctx.audio.play('lock');
      }
      if (this.mgT.warn > 0) {
        this.mgT.warn -= delta;
        for (const port of this.ports) {
          port.getWorldPosition(v);
          if (Math.random() < 0.5) this.ctx.fx.glow.emit({ x: v.x + 0.5, y: v.y, z: v.z, life: 0.06, size: 0.9 + (0.7 - this.mgT.warn), color: WARN_ENEMY, frame: 0 });
        }
        if (this.mgT.warn <= 0) {
          this.mgT.burst = 12;
          this.mgT.t = 2.2 / rage;
        }
      }
      if (this.mgT.burst > 0 && rng.boss() < delta * 18) {
        this.mgT.burst--;
        // 射孔轮流开火，曳光弹扫向锁定点（左右各扫开一点）
        const port = this.ports[this.mgT.burst % this.ports.length];
        port.getWorldPosition(v);
        const a = angleTo(v.x, v.z, this.mgT.tx, this.mgT.tz) + Math.sin(this.mgT.burst * 0.8) * 0.05;
        this.ctx.fire('rifle', v.x, v.z, Math.sin(a), Math.cos(a), 75, BOSS_MG.anvil);
        this.ctx.fx.glow.emit({ x: v.x + 0.6, y: v.y, z: v.z, life: 0.05, size: 1.2, color: 0xffe0a0, frame: 0 });
        this.ctx.audio.play('mg');
      }
    }
    const rk = this.alive('rocket');
    if (rk) {
      const pos = this.partPos(rk, v);
      const st = this.rocket.tick(delta, () => angleTo(pos.x, pos.z, P.x, P.z));
      rk.e.laser.visible = st === 'aim' && Math.sin(this.t * 30) > -0.4;
      rk.e.laser.rotation.y = this.rocket.angle;
      rk.e.laser.scale.set(1.8, 1, 70);
      rk.e.laser.position.y = 5;
      if (st === 'fire') {
        rk.e.laser.visible = false;
        this.rocket.t /= rage;
        const n = 4 + this.phase * 2;
        for (let i = 0; i < n; i++) {
          const a = this.rocket.angle + (i - (n - 1) / 2) * 0.06;
          this.ctx.fire('rocket', pos.x, pos.z, Math.sin(a), Math.cos(a), 32, 18);
        }
        this.ctx.audio.play('rocket');
      }
    }
    // 第二阶段起：侧舷齐射，整列车同时开火，一排炮弹横扫道路（留一个缺口）
    if (this.phase >= 1) {
      this.broadside -= delta;
      if (this.broadside <= 0) {
        this.broadside = 7.5 / rage;
        this.carpetLine(RAIL_X, P.z, P.z - 1, 18, 1.6);
        for (const g of this.guns) {
          g.getWorldPosition(v);
          this.ctx.fx.muzzle(v.x + 2, v.y + 0.8, v.z, 1, 0, 2.6);
        }
        this.ctx.audio.play('bigboom');
        this.ctx.shake(0.6);
      }
    }
  }

  /** 坍塌开始时各炮塔的朝向 */
  private gunYaw: number[] = [];

  protected override collapse(k: number): void {
    // 出轨侧翻
    this.train.rotation.z = -k * 0.22;
    this.train.position.x = -k * 1.2;
    // 炮塔被震得转回顺着车身歪着（残骸压扁时炮管不会横在路上）
    if (this.gunYaw.length === 0) this.gunYaw = this.guns.map((g) => g.rotation.y);
    this.guns.forEach((g, i) => {
      const y0 = this.gunYaw[i];
      const rest = Math.abs(y0) < Math.PI / 2 ? (i - 1) * 0.12 : Math.sign(y0) * (Math.PI - 0.1);
      g.rotation.y = THREE.MathUtils.lerp(y0, rest, k);
    });
  }

  /** 残骸只算列车本身（路基铁轨从据点一直铺到玩家身后，不算） */
  protected override get wreckRoot(): THREE.Object3D {
    return this.train;
  }

  protected override settleWreck(): void {
    // 每节单独压：沿着列车开过去，一节一节压扁；车头长，多压一段
    this.cars.forEach((c, i) => this.crushable(c, 1.3, 2.3, i === 0 ? 12 : 9));
  }
}

