/** 远景巨炮的雾因子倍数（SiegeProxy 每帧按离你多远写） */
const siegeFarFog = { value: 0.5 };
/** 远景巨炮融进天际线多少（T048，SiegeProxy 每帧写）：0 = 抗雾涂装（实战本体那样）、1 = 和城市剪影同一套色调 */
const siegeFarSil = { value: 1 };
/**
 * 远景巨炮融进天际线（T048，制作人「我只需要的是一个和背景其他建筑协调的、一样灰蒙蒙的巨炮轮廓，而不是一个凭空出现的突兀模型……现在这样看和飞在空中一样」）：
 * 雾那一步先算原来的抗雾涂装（雾因子 × uFogK），再按 uSil 混向**天际线剪影的同一套色调**（Environment 的 SKYLINE：同一个剪影色对象、同样「雾色 + 剪影色 × 0.55」，
 * 越往下越淡、离地 4 米以下淡进雾里——四五百米外 4 米和天际线最底下淡进雾的那一截一样高）；只按明暗留一点起伏（暗面深一点、亮面浅一点），看得出体积，
 * 炮管 / 舱口 / 吊臂 / 炮弹这些细节都化在里面。实例化的装甲板 / 装填机把实例矩阵算进离地高度
 */
function farShade(sh: THREE.WebGLProgramParametersWithUniforms): void {
  sh.uniforms.uFogK = siegeFarFog;
  sh.uniforms.uSil = siegeFarSil;
  sh.uniforms.uShade = SKYLINE.color;
  sh.vertexShader = sh.vertexShader
    .replace('#include <common>', '#include <common>\nvarying float vFarY;')
    .replace(
      '#include <worldpos_vertex>',
      '#include <worldpos_vertex>\nvec4 farWp = vec4( transformed, 1.0 );\n#ifdef USE_INSTANCING\nfarWp = instanceMatrix * farWp;\n#endif\nvFarY = ( modelMatrix * farWp ).y;',
    );
  sh.fragmentShader = sh.fragmentShader
    .replace('#include <common>', '#include <common>\nuniform float uFogK;\nuniform float uSil;\nuniform vec3 uShade;\nvarying float vFarY;')
    .replace(
      '#include <fog_fragment>',
      `#ifdef USE_FOG
  float fogFactor = uFogK * smoothstep( fogNear, fogFar, vFogDepth );
  vec3 farLit = mix( gl_FragColor.rgb, fogColor, fogFactor );
  float farL = clamp( dot( gl_FragColor.rgb, vec3( 0.299, 0.587, 0.114 ) ) / max( dot( fogColor, vec3( 0.299, 0.587, 0.114 ) ), 1e-3 ), 0.0, 1.0 );
  float farA = ${SKYLINE.alpha.toFixed(2)} * smoothstep( 0.0, 4.0, vFarY ) * ( 0.6 + 0.4 * smoothstep( 0.0, 36.0, vFarY ) ) * mix( 1.15, 0.85, farL );
  gl_FragColor.rgb = mix( farLit, mix( fogColor, uShade, farA ), uSil );
#endif`,
    );
}

