/** 凸多边形的每条边：外法线 (nx, nz)、nx·x + nz·z = d 在边上（大于 d 在外面）；点离多边形多远（里面 ≤ 0，角上偏小一点） */
type Edge = { nx: number; nz: number; d: number };
const edgesOf = (pts: V2[]): Edge[] =>
  pts.map(([ax, az], i) => {
    const [bx, bz] = pts[(i + 1) % pts.length];
    const l = Math.hypot(bx - ax, bz - az);
    const s = (bz - az) * ax - (bx - ax) * az < 0 ? -1 : 1;
    const nx = (s * (bz - az)) / l;
    const nz = (-s * (bx - ax)) / l;
    return { nx, nz, d: nx * ax + nz * az };
  });
const outside = (edges: Edge[], x: number, z: number) => edges.reduce((m, e) => Math.max(m, e.nx * x + e.nz * z - e.d), -Infinity);
