const smooth = (k: number) => k * k * (3 - 2 * k);

/** 竖着的倒角装甲板：w（x）× h（y），厚 t（z），倒角的那一面朝 side（+1 = +z） */
function slab(w: number, h: number, t: number, b: number, side: number): THREE.BufferGeometry {
  const g = frustum(chamfer(w, h, b * 1.6), chamfer(w - 2 * b, h - 2 * b, b), t, -t / 2);
  g.rotateX(side * PI / 2);
  return g;
}

/** 平放的倒角板：w（x）× d（z），厚 t（y），倒角朝上 */
const flat = (w: number, d: number, t: number, b = 0.1) => frustum(chamfer(w, d, b * 1.6), chamfer(w - 2 * b, d - 2 * b, b), t, -t / 2);

const _m = new THREE.Matrix4();
const _g = new THREE.Matrix4();
const _q = new THREE.Quaternion();
const _e = new THREE.Euler();
const _p = new THREE.Vector3();
const _s = new THREE.Vector3();

/** 一组零件整体再挪一次（零件自己的变换先烤进几何体） */
function bake(parts: PartSpec[], pos: V3 = [0, 0, 0], rot: V3 = [0, 0, 0], order: THREE.EulerOrder = 'XYZ'): PartSpec[] {
  _g.compose(_p.set(...pos), _q.setFromEuler(_e.set(rot[0], rot[1], rot[2], order)), _s.set(1, 1, 1));
  return parts.map(({ geo, color, pos: lp = [0, 0, 0], rot: lr = [0, 0, 0], scale = [1, 1, 1] }) => {
    geo.applyMatrix4(_m.compose(_p.set(...lp), _q.setFromEuler(_e.set(lr[0], lr[1], lr[2])), _s.set(...scale)));
    geo.applyMatrix4(_g);
    return { geo, color };
  });
}

/** 螺栓圈：法兰面上一圈螺栓头，轴沿 z，圈面在 z = z0 */
function bolts(r: number, n: number, z0: number, size = 0.16, x = 0, y = 0): PartSpec[] {
  return Array.from({ length: n }, (_, i): PartSpec => {
    const a = (i / n) * PI * 2;
    return { geo: box(size, size, size * 0.8), color: RIVET, pos: [x + Math.cos(a) * r, y + Math.sin(a) * r, z0], rot: [0, 0, a] };
  });
}

/** 一排铆钉（沿 x） */
function rivetRow(x0: number, x1: number, y: number, z: number, step = 0.7): PartSpec[] {
  const p: PartSpec[] = [];
  for (let x = x0; x <= x1 + 1e-6; x += step) p.push({ geo: box(0.13, 0.13, 0.1), color: RIVET, pos: [x, y, z] });
  return p;
}

/** 关节鼓（轴沿 z）：主鼓 + 两侧法兰 + 轮毂盖 + 螺栓圈 */
function joint(x: number, y: number, r: number, len: number, color = DARK): PartSpec[] {
  const ax: V3 = [PI / 2, 0, 0];
  return [
    { geo: cyl(r, r, len, 14), color, pos: [x, y, 0], rot: ax },
    ...[-1, 1].flatMap((s): PartSpec[] => [
      { geo: cyl(r + 0.32, r + 0.32, 0.26, 14), color: STEEL_D, pos: [x, y, s * (len / 2 - 0.12)], rot: ax },
      { geo: cyl(r * 0.5, r * 0.66, 0.36, 8), color: STEEL, pos: [x, y, s * (len / 2 + 0.14)], rot: ax },
      ...bolts(r + 0.12, 6, s * (len / 2 + 0.02), 0.19, x, y),
    ]),
  ];
}

