import * as THREE from 'three';
import type { Enemy } from '../../entities/Enemy';
import { DecalKind } from '../../render/Decals';
import { MARK_SELF } from '../../render/markColors';
import type { ScnSolid } from '../../world/SceneryDamage';
import { ultHalf } from '../defs';
import { UltBase, type UltAim, type UltContext, type UltPreview } from './common';

const rand = (a: number, b: number) => a + Math.random() * (b - a);

/**
 * 「钢幕」数值表（D1-032 第 7.2 节；冷却在 FUSIONS.curtain.cd 里固定 30 秒）：
 * 起手 wind 秒（一脚刹车、发射箱翻起来架到炮上、嘀声越来越快），然后 salvo 秒内一面弹墙沿瞄准方向推出去 len 米；走廊宽 width 米，分 cols 列。
 * 走廊里每个敌人挨一次 dmg（首领每个部件各一次）；活着的车往后推 push 米（重甲 × heavyPush），轻车被冲击掀翻（smash 的掀飞档），步兵倒地 stun 秒。
 * 拆：每 smashStep 米对走廊中线做一次 smash（路障、残骸、掩体、树、电线杆），房子掉一档（directHit，力度 houseF）；
 * 挡：房子、巨石、首领部件挡住那一列后面（每列单独算到哪停）。
 * 弹沟火：grooves 条弹沟从车前一路铺到头，烧 fireT 秒，站在走廊里每秒 fireDps（火，每 tick 秒一跳）。
 * 一次最多 maxBreak 辆车 / 块残骸走完整碎裂流程（同核弹）。
 * 自动释放 / 自动瞄准：车头 ±arc 弧度里 dirs 个方向，数走廊里的敌人（精英、首领部件一个顶 elite 个），够 count 个才放，挑最多的方向
 */
export const CURTAIN = {
  wind: 0.45, salvo: 0.5, len: 130, width: 24, cols: 24, dmg: 700,
  push: 8, heavyPush: 0.6, stun: 1.2, smashStep: 9, smashR: 12, smashF: 10, houseF: 40,
  grooves: 12, grooveSeg: 13, fireT: 4, fireDps: 60, tick: 0.25,
  arc: 1.2, dirs: 9, count: 3, elite: 3,
  beeps: [0, 0.16, 0.28, 0.36, 0.41],
  maxBreak: 5, flash: 0.22, shake: 0.9, freeze: 0.08, slow: [0.4, 0.45] as [number, number],
};

/**
 * 弹墙：竖着的一片亮光，底部最亮往上渐隐，左右两头收掉；uFade 收尾。
 * T128：uv 先夹到 0..1。多重采样下边上那排像素在三角形外取样，vUv.y 略大于 1，pow(负数) 出 NaN，
 * 叠加混合写进合成缓冲、泛光一糊就是整屏黑（uFade = 0 也一样，NaN × 0 还是 NaN）
 */
const WALL_FRAG = /* glsl */ `
uniform float uFade;
varying vec2 vUv;
void main() {
  vec2 uv = clamp(vUv, 0.0, 1.0);
  float edge = smoothstep(0.0, 0.08, uv.x) * (1.0 - smoothstep(0.92, 1.0, uv.x));
  float k = pow(1.0 - uv.y, 1.6) * edge * uFade;
  float flick = 0.8 + 0.2 * sin(uv.x * 90.0);
  vec3 c = mix(vec3(1.0, 0.55, 0.18), vec3(1.0, 0.95, 0.8), pow(1.0 - uv.y, 3.0));
  gl_FragColor = vec4(c * k * flick, k * 0.85);
  #include <colorspace_fragment>
}`;
const WALL_VERT = /* glsl */ `
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}`;

/** 钢幕 · 金属风暴（火神 + 迫击炮★ + 喷火器★）：发射箱 36 管一瞬齐射，前方 130 米一条走廊里的敌人各挨一次，路打平，弹沟烧一阵 */
export class CurtainUlt extends UltBase {
  /** 按下后几秒；-1 = 不在事件里 */
  private t = -1;
  private ang = 0;
  /** 齐射起点 / 方向 / 侧向（齐射那一刻定下） */
  private x0 = 0;
  private z0 = 0;
  private dx = 0;
  private dz = -1;
  private beep = 0;
  private shot = false;
  /** 每列打到多远（房子 / 巨石 / 首领部件挡住） */
  private readonly reach: number[] = [];
  private readonly hit = new Set<Enemy>();
  private smashed = 0;
  private grooveN = 0;
  private fireLeft = 0;
  private tickT = 0;
  private A = 1;
  private wall: THREE.Mesh<THREE.PlaneGeometry, THREE.ShaderMaterial> | null = null;
  private strip: THREE.Mesh<THREE.PlaneGeometry, THREE.MeshBasicMaterial> | null = null;
  private pvT = -1;
  private freed = true;
  private readonly mouthV = new THREE.Vector3();

  /** 走廊里的一点：沿方向多远、离中线多远（正 = 右） */
  private local(x: number, z: number, x0 = this.x0, z0 = this.z0, dx = this.dx, dz = this.dz): { a: number; s: number } {
    const px = x - x0;
    const pz = z - z0;
    return { a: px * dx + pz * dz, s: px * -dz + pz * dx };
  }

  /**
   * 自动释放 / 自动瞄准选方向：车头 ±arc 里 dirs 个方向数走廊里的敌人，min 个以上挑最多的；不够返回 null
   */
  aimAuto(ctx: UltContext, min = CURTAIN.count): UltAim | null {
    const C = CURTAIN;
    const P = ctx.tank.group.position;
    const yaw = ctx.tank.group.rotation.y;
    let best = -1;
    let bestN = 0;
    for (let i = 0; i < C.dirs; i++) {
      const a = yaw - C.arc + (i / (C.dirs - 1)) * C.arc * 2;
      const dx = -Math.sin(a);
      const dz = -Math.cos(a);
      let n = 0;
      for (const e of ctx.enemies) {
        if (!e.alive) continue;
        const l = this.local(e.group.position.x, e.group.position.z, P.x, P.z, dx, dz);
        if (l.a < 2 || l.a > C.len || Math.abs(l.s) > C.width / 2 + e.radius) continue;
        n += e.spec.blocker || e.controller ? C.elite : 1;
      }
      // 一样多挑离车头近的（中间那几个方向）
      if (n > bestN || (n === bestN && n > 0 && Math.abs(a - yaw) < Math.abs(best - yaw))) {
        bestN = n;
        best = a;
      }
    }
    return bestN >= min ? { target: null, angle: best } : null;
  }

  /** 待发预览：车前一条淡淡的走廊（自己画，Game 的圆形预览不用） */
  preview(ctx: UltContext, aim: UltAim): UltPreview | null {
    const P = ctx.tank.group.position;
    const s = (this.strip ??= this.makeStrip(ctx));
    const a = this.clampAngle(ctx, aim.angle);
    s.visible = true;
    s.position.set(P.x - Math.sin(a) * (CURTAIN.len / 2 + 3), 0.18, P.z - Math.cos(a) * (CURTAIN.len / 2 + 3));
    s.rotation.set(-Math.PI / 2, 0, a);
    this.pvT = ctx.time;
    // 待发时弹墙就建好、透明着跟在车上（着色器在这时编译，放的那一下不卡）
    this.wall ??= this.makeWall(ctx);
    if (this.t < 0) {
      this.wall.visible = true;
      this.wall.material.uniforms.uFade.value = 0;
      this.wall.position.copy(P);
    }
    return null;
  }

  private clampAngle(ctx: UltContext, a: number): number {
    const yaw = ctx.tank.group.rotation.y;
    let d = a - yaw;
    while (d > Math.PI) d -= Math.PI * 2;
    while (d < -Math.PI) d += Math.PI * 2;
    return yaw + THREE.MathUtils.clamp(d, -CURTAIN.arc, CURTAIN.arc);
  }

  private makeStrip(ctx: UltContext): THREE.Mesh<THREE.PlaneGeometry, THREE.MeshBasicMaterial> {
    const m = new THREE.Mesh(new THREE.PlaneGeometry(CURTAIN.width, CURTAIN.len), new THREE.MeshBasicMaterial({ color: MARK_SELF, transparent: true, opacity: 0.12, depthWrite: false, blending: THREE.AdditiveBlending }));
    m.renderOrder = 1;
    m.frustumCulled = false;
    ctx.scene.add(m);
    return m;
  }

  protected override activeLabel(): string {
    return this.shot ? `弹沟 ${Math.ceil(this.active)}` : '装填';
  }

  protected fire(ctx: UltContext, aim: UltAim): void {
    this.clear();
    this.ang = this.clampAngle(ctx, aim.angle);
    this.t = 0;
    this.beep = 0;
    this.A = ultHalf(ctx.mods.area);
    this.active = CURTAIN.wind + CURTAIN.salvo + CURTAIN.fireT;
    // 一脚刹车：车头一沉，炮塔转到齐射方向
    ctx.tank.turret.rotation.y = this.ang - ctx.tank.group.rotation.y;
    ctx.punch(0.35);
    ctx.shake(0.15);
    ctx.audio.play('breech', 0.5, 0.8);
    ctx.audio.play('hatch', 0.4, 1.2);
    ctx.cinema(-1, CURTAIN.wind + CURTAIN.salvo + 0.6, 0.7, false);
    // 弹墙先建好、透明着放在车前（起手这 0.45 秒里编译好着色器，齐射那一帧不卡）
    this.wall ??= this.makeWall(ctx);
    this.wall.visible = true;
    this.wall.material.uniforms.uFade.value = 0;
    this.wall.position.copy(ctx.tank.group.position);
  }

  protected step(ctx: UltContext): void {
    if (this.strip && ctx.time - this.pvT > 0.1) {
      this.strip.visible = false;
      if (this.t < 0 && this.wall) this.wall.visible = false;
    }
    if (this.t < 0) {
      ctx.tank.ultRaise(0, ctx.dt);
      if (!this.freed) {
        this.freed = true;
        ctx.breaks(Infinity);
      }
      return;
    }
    const C = CURTAIN;
    const dt = ctx.dt;
    this.t += dt;
    const t = this.t;
    // 起手：发射箱翻起来，嘀声越来越快；炮塔一直对着齐射方向
    if (!this.shot) {
      ctx.tank.turret.rotation.y = this.ang - ctx.tank.group.rotation.y;
      ctx.tank.ultRaise(1, dt * 3);
      while (this.beep < C.beeps.length && t >= C.beeps[this.beep]) {
        ctx.audio.play('beep', 0.5, 1 + this.beep * 0.08);
        this.beep += 1;
      }
      if (t >= C.wind) this.salvoStart(ctx);
      this.active = Math.max(1e-3, C.wind + C.salvo + C.fireT - t);
      return;
    }
    const s = t - C.wind;
    if (s < C.salvo) {
      this.stepWall(ctx, s / C.salvo);
      ctx.tank.turret.rotation.y = this.ang - ctx.tank.group.rotation.y;
    } else {
      if (this.wall?.visible) this.stepWall(ctx, 1);
      ctx.tank.ultRaise(0, dt * 1.5);
    }
    this.stepFire(ctx, dt);
    const left = C.wind + C.salvo + C.fireT - t;
    if (!this.freed && s > C.salvo + 1.5) {
      this.freed = true;
      ctx.breaks(Infinity);
    }
    if (this.active > 0) {
      if (left <= 0) this.finish();
      else this.active = left;
    }
    if (left <= 0 && !this.wall?.visible) this.t = -1;
  }

  /** 齐射开始：定起点 / 方向，算每列打到多远（房子、巨石、首领部件挡住那一列），36 管一齐闪 */
  private salvoStart(ctx: UltContext): void {
    const C = CURTAIN;
    this.shot = true;
    // 一次齐射最多 maxBreak 辆车 / 块残骸走完整碎裂（多的只放尘土和火球），弹沟烧完放开
    ctx.breaks(CURTAIN.maxBreak);
    this.freed = false;
    const P = ctx.tank.group.position;
    this.dx = -Math.sin(this.ang);
    this.dz = -Math.cos(this.ang);
    this.x0 = P.x + this.dx * 3;
    this.z0 = P.z + this.dz * 3;
    const w = C.width / C.cols;
    const rx = -this.dz;
    const rz = this.dx;
    const houses = new Set<unknown>();
    for (let i = 0; i < C.cols; i++) {
      const o = -C.width / 2 + w * (i + 0.5);
      const ax = this.x0 + rx * o;
      const az = this.z0 + rz * o;
      let r = C.len;
      let skip: unknown = null;
      for (let k = 0; k < 4; k++) {
        const s: ScnSolid | null = ctx.scenery.solidOnPath(ax, az, ax + this.dx * C.len, az + this.dz * C.len, false, skip);
        if (!s) break;
        const kind = s.item.kind;
        const d = s.t * C.len;
        if (kind === 'house' || kind === 'ruin' || kind === 'boulder') {
          r = d;
          if (kind !== 'boulder' && !houses.has(s.item)) {
            houses.add(s.item);
            ctx.scenery.directHit(s, this.dx, this.dz, C.houseF, false, false, false);
          }
          break;
        }
        // 墙、空壳车：打碎，接着往后
        ctx.scenery.directHit(s, this.dx, this.dz, C.houseF, false, true, true);
        skip = s.item;
      }
      this.reach[i] = r;
    }
    // 首领部件也挡：那一列打到它为止
    for (const e of ctx.enemies) {
      if (!e.alive || !e.controller) continue;
      const l = this.local(e.group.position.x, e.group.position.z);
      if (l.a < 0) continue;
      for (let i = 0; i < C.cols; i++) {
        const o = -C.width / 2 + w * (i + 0.5);
        if (Math.abs(l.s - o) <= e.radius + w / 2) this.reach[i] = Math.min(this.reach[i], l.a);
      }
    }
    this.wall ??= this.makeWall(ctx);
    this.wall.visible = true;
    this.wall.material.uniforms.uFade.value = 1;
    // 发射箱 36 个管口一齐闪
    const box = ctx.tank.kitMouth(this.mouthV) ?? ctx.tank.turretPoint(0, 1.9, 0.6, this.mouthV);
    for (let i = 0; i < 12; i++) ctx.fx.glow.emit({ x: box.x + rand(-0.7, 0.7), y: box.y + rand(-0.6, 0.6), z: box.z + rand(-0.3, 0.3), vx: this.dx * rand(25, 45), vy: rand(-1, 2), vz: this.dz * rand(25, 45), life: rand(0.06, 0.12), size: rand(0.8, 1.6), size1: 0.5, color: 0xfff4d0, color1: 0xff7a20, frame: 0, drag: 5 });
    for (let i = 0; i < 10; i++) ctx.fx.smokeP.emit({ x: box.x + rand(-1, 1), y: box.y, z: box.z + rand(-1, 1), vx: -this.dx * rand(2, 5) + rand(-2, 2), vy: rand(0.5, 2), vz: -this.dz * rand(2, 5) + rand(-2, 2), life: rand(1.2, 2), size: 1.4, size1: 4.5, color: 0xc8c2b6, alpha: 0.55, frame: 1, drag: 1.4 });
    ctx.fx.flash(box.x + this.dx * 6, box.y + 1, box.z + this.dz * 6, 5000);
    ctx.flash(C.flash);
    ctx.freeze(C.freeze);
    ctx.slowmo(C.slow[0], C.slow[1]);
    ctx.shake(C.shake);
    ctx.kick(0.5);
    ctx.tank.kick(1);
    ctx.audio.play('salvo', 1);
    ctx.audio.play('bigboom', 0.7, 1.15, 0.08);
  }

  private makeWall(ctx: UltContext): THREE.Mesh<THREE.PlaneGeometry, THREE.ShaderMaterial> {
    const m = new THREE.Mesh(
      new THREE.PlaneGeometry(CURTAIN.width + 2, 5).translate(0, 2.5, 0),
      new THREE.ShaderMaterial({ vertexShader: WALL_VERT, fragmentShader: WALL_FRAG, uniforms: { uFade: { value: 1 } }, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, side: THREE.DoubleSide }),
    );
    m.renderOrder = 2;
    m.frustumCulled = false;
    ctx.scene.add(m);
    return m;
  }

  /** 弹墙推到 k（0..1）：扫过的敌人各挨一次、推开；中线每 smashStep 米拆一次；两边掀土墙；弹沟跟着铺 */
  private stepWall(ctx: UltContext, k: number): void {
    const C = CURTAIN;
    const front = k * C.len;
    const wall = this.wall!;
    wall.position.set(this.x0 + this.dx * front, ctx.fx.groundAt(this.x0 + this.dx * front, this.z0 + this.dz * front), this.z0 + this.dz * front);
    wall.rotation.set(0, this.ang, 0);
    const u = wall.material.uniforms;
    if (k >= 1) {
      u.uFade.value = Math.max(0, u.uFade.value - ctx.dt * 4);
      if (u.uFade.value <= 0) wall.visible = false;
      return;
    }
    u.uFade.value = 1;
    const w = C.width / C.cols;
    for (const e of ctx.enemies) {
      if (!e.alive || this.hit.has(e)) continue;
      const l = this.local(e.group.position.x, e.group.position.z);
      if (l.a < -2 || l.a > front || Math.abs(l.s) > C.width / 2 + e.radius) continue;
      const col = THREE.MathUtils.clamp(Math.floor((l.s + C.width / 2) / w), 0, C.cols - 1);
      if (l.a > this.reach[col] + e.radius) continue;
      this.hit.add(e);
      const heavy = e.spec.armor === 'heavy';
      ctx.damage(e, C.dmg, e.group.position.x - this.dx * 3, e.group.position.z - this.dz * 3, { type: 'shell', ult: true, knock: 10 });
      ctx.fx.sparks(e.group.position.x, e.size, e.group.position.z, 8, 0xffd090, 10);
      if (!e.alive || e.controller || e.spec.fixed || e.spec.blocker) continue;
      if (e.spec.crushable) {
        e.stunTime = Math.max(e.stunTime, C.stun);
        e.kvx += this.dx * C.push;
        e.kvz += this.dz * C.push;
      } else {
        // 车：往后推 push 米（滑行按 6 / 秒衰减，初速 = 6 × 距离）
        const v = C.push * 6 * (heavy ? C.heavyPush : 1);
        e.kvx += this.dx * v;
        e.kvz += this.dz * v;
      }
    }
    // 中线拆一路（只拆到中间那两列能打到的地方）；油桶一串引爆
    const mid = Math.min(this.reach[C.cols / 2 - 1], this.reach[C.cols / 2]);
    while (this.smashed * C.smashStep <= Math.min(front, mid)) {
      const d = this.smashed * C.smashStep + C.smashStep * 0.5;
      this.smashed += 1;
      if (d > mid) break;
      const x = this.x0 + this.dx * d;
      const z = this.z0 + this.dz * d;
      ctx.smash(x, z, C.smashR * this.A, C.smashF, false, true);
      for (const [bx, bz] of ctx.barrels(x, z, C.smashR * this.A)) ctx.detonate(bx, bz);
    }
    // 两边掀起一道土墙 + 弹墙前沿的火花
    const rx = -this.dz;
    const rz = this.dx;
    for (const side of [-1, 1]) {
      const x = this.x0 + this.dx * front + rx * side * C.width / 2;
      const z = this.z0 + this.dz * front + rz * side * C.width / 2;
      ctx.fx.smokeP.emit({ x, y: ctx.fx.groundAt(x, z) + 0.5, z, vx: rx * side * rand(2, 5), vy: rand(5, 9), vz: rz * side * rand(2, 5), life: rand(1.2, 1.8), size: 1.6, size1: 4.5, color: 0x8a7458, color1: 0x6a5a48, alpha: 0.7, frame: 1, drag: 1.2, gravity: -6 });
    }
    for (let i = 0; i < 6; i++) {
      const o = rand(-C.width / 2, C.width / 2);
      const x = this.x0 + this.dx * front + rx * o;
      const z = this.z0 + this.dz * front + rz * o;
      ctx.fx.glow.emit({ x, y: ctx.fx.groundAt(x, z) + rand(0.3, 2), z, vx: this.dx * 30, vy: rand(1, 4), vz: this.dz * 30, life: rand(0.1, 0.2), size: rand(1, 2), size1: 0.4, color: 0xfff0c0, color1: 0xff7a20, frame: 0, drag: 4 });
      if (i < 2) ctx.fx.dirt(x, z, 0.8);
    }
    // 曳光：发射箱到弹墙前沿一把亮线
    const box = ctx.tank.kitMouth(this.mouthV) ?? ctx.tank.turretPoint(0, 1.9, 0.6, this.mouthV);
    for (let i = 0; i < 6; i++) {
      const o = rand(-C.width / 2, C.width / 2);
      const x = this.x0 + this.dx * front + rx * o;
      const z = this.z0 + this.dz * front + rz * o;
      ctx.streaks.add(box.x, box.y, box.z, x, ctx.fx.groundAt(x, z) + rand(0.4, 1.6), z, 0.3, 0xffc070, 0.7, 0.08, 1.5);
    }
    // 弹沟：12 条从车前铺到前沿（每段 13 米一块贴花），之后烧 fireT 秒
    const G = C.grooves;
    while (this.grooveN * C.grooveSeg <= front) {
      const d = this.grooveN * C.grooveSeg + C.grooveSeg / 2;
      this.grooveN += 1;
      for (let g = 0; g < G; g++) {
        const o = -C.width / 2 + (C.width / G) * (g + 0.5) + rand(-0.4, 0.4);
        const col = THREE.MathUtils.clamp(Math.floor((o + C.width / 2) / w), 0, C.cols - 1);
        if (d - C.grooveSeg / 2 > this.reach[col]) continue;
        const len = Math.min(C.grooveSeg, this.reach[col] - (d - C.grooveSeg / 2));
        const cd = d - C.grooveSeg / 2 + len / 2;
        ctx.fx.grooves.add(DecalKind.Scorch, this.x0 + this.dx * cd + rx * o, this.z0 + this.dz * cd + rz * o, 1.1, len + 0.6, Math.atan2(-this.dx, this.dz), 0.95, 16);
      }
    }
    this.fireLeft = C.fireT;
  }

  /** 弹沟火：走廊里（每列打到的地方以内）每 tick 秒一跳火，满地火苗 */
  private stepFire(ctx: UltContext, dt: number): void {
    const C = CURTAIN;
    if (this.fireLeft <= 0) return;
    this.fireLeft -= dt;
    const live = Math.max(0, this.fireLeft / C.fireT);
    const w = C.width / C.cols;
    const rx = -this.dz;
    const rz = this.dx;
    this.tickT -= dt;
    if (this.tickT <= 0) {
      this.tickT += C.tick;
      for (const e of ctx.enemies) {
        if (!e.alive) continue;
        const l = this.local(e.group.position.x, e.group.position.z);
        if (l.a < 0 || l.a > C.len || Math.abs(l.s) > C.width / 2) continue;
        const col = THREE.MathUtils.clamp(Math.floor((l.s + C.width / 2) / w), 0, C.cols - 1);
        if (l.a > this.reach[col]) continue;
        ctx.damage(e, C.fireDps * C.tick * ultHalf(ctx.mods.burn), e.group.position.x, e.group.position.z, { type: 'fire', ult: true });
      }
    }
    const n = ctx.quality === 'low' ? 2 : 4;
    for (let i = 0; i < n; i++) {
      const g = Math.floor(Math.random() * C.grooves);
      const o = -C.width / 2 + (C.width / C.grooves) * (g + 0.5);
      const col = THREE.MathUtils.clamp(Math.floor((o + C.width / 2) / w), 0, C.cols - 1);
      const d = rand(2, this.reach[col]);
      const x = this.x0 + this.dx * d + rx * o;
      const z = this.z0 + this.dz * d + rz * o;
      ctx.fx.blaze(x, z, 1.2, 0.3 + Math.random() * 0.4, live);
      if (Math.random() < 0.12) ctx.fx.smoke(x, ctx.fx.groundAt(x, z) + 0.6, z, 0.7, 2.2, 0x3d3834, 0.4 * live);
    }
  }

  protected clear(): void {
    this.t = -1;
    this.shot = false;
    this.hit.clear();
    this.smashed = 0;
    this.grooveN = 0;
    this.fireLeft = 0;
    this.reach.length = 0;
    if (this.wall) this.wall.visible = false;
  }

  override dispose(): void {
    super.dispose();
    for (const m of [this.wall, this.strip]) {
      m?.removeFromParent();
      m?.geometry.dispose();
      m?.material.dispose();
    }
    this.wall = null;
    this.strip = null;
  }
}
