import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { copyGeometry, type GeoCache, type PartSpec } from '../GeoCache';
import { barrel, chamfer, frustum } from '../ModelKit';
import { glslColor, WARN_ENEMY } from '../../render/markColors';
import { sharedEnemyCamo, sharedMetalNormal } from '../../render/sharedTextures';
import { armorPlate, bar, canopy, chamferBox, mergeHeli, pipe, place, plateAt, plates, type HeliPart, type Plate } from './heliKit';

/**
 * 「秃鹫」武装直升机（T091，D1-035 第 4.1 节；T095 加厚；T096 换成和地面坦克同一套建模语言）。机头朝 +Z，原点在机身中心。
 * 机身长约 12 米（楔形机鼻到垂尾）、高 3.8 米（滑橇底到桨毂）；主旋翼直径 12 米由 Air 实例化画（ROTOR），桨毂 / 桨夹 / 桨根也是实例化的（vultureHub）。
 * T096：照中型坦克 / 巨像 / 泰坦的做法——机身是平板拼的硬放样（腰线 + 上下斜板 + 倒角），楔形机鼻顶着方传感器箱，框架式平板玻璃座舱，
 * 两侧分块装甲板（板缝 + 方铆钉），机炮塔是吊着的小棱台，方箱火箭巢（3 × 3 管），发动机舱是棱台 + 散热格栅 + 方排气管，滑橇方管直角相接；
 * 坦克同色（钢灰 + 迷彩）、旋翼整流座一道铁狼红带（同坦克炮塔那道）、火箭巢顶上红条（同火箭炮车）。尾部只有钢灰。
 * 亮件单独一个网格：机鼻橙色感应眼、两个火箭巢前脸（齐射前亮橙）
 */
const STEEL = 0x8e8a86;
const STEEL_D = 0x6e6a66;
const DARK = 0x3e3c3a;
const RED = 0xa8382c;
const GLASS = 0x0e1418;

/** 桨毂中心（模型坐标）、旋翼半径、浅锥上翘（边缘比桨毂高多少） */
export const ROTOR = { hub: [0, 2.0, 0.25] as [number, number, number], r: 6, cone: 0.42 };
/** 挂架亮光件（火箭巢前脸）、机炮口、尾梁火点、发动机（模型坐标，Air 算世界位置用） */
export const VULTURE_PTS = {
  pods: [[-1.95, -1.0, 1.24], [1.95, -1.0, 1.24]] as [number, number, number][],
  chin: [0, -1.16, 4.6] as [number, number, number],
  tail: [0, 0.45, -4.8] as [number, number, number],
  engine: [0, 1.45, -1.25] as [number, number, number],
};

const cyl = (rt: number, rb: number, h: number, s = 8) => new THREE.CylinderGeometry(rt, rb, h, s);
const HALF = Math.PI / 2;

/** 机身硬放样：楔形机鼻（顶面斜着升上来）→ 座舱段 → 发动机段 → 收细成尾梁 */
const BODY: Plate[] = [
  { z: 4.5, y: -0.42, w: 0.4, top: 0.24, bot: 0.3, wt: 0.32, wb: 0.34, ct: 0.06, cb: 0.06 },
  { z: 4.05, y: -0.38, w: 0.62, top: 0.46, bot: 0.5, wt: 0.5, wb: 0.52, ct: 0.1, cb: 0.08 },
  { z: 3.0, y: -0.3, w: 0.9, top: 0.72, bot: 0.76, wt: 0.7, wb: 0.72, ct: 0.16, cb: 0.12 },
  { z: 1.6, y: -0.2, w: 1.04, top: 0.96, bot: 0.92, wt: 0.8, wb: 0.82, ct: 0.2, cb: 0.14 },
  { z: 0.0, y: -0.12, w: 1.1, top: 1.08, bot: 0.98, wt: 0.84, wb: 0.86, ct: 0.22, cb: 0.15 },
  { z: -1.3, y: -0.04, w: 1.02, top: 1.04, bot: 0.86, wt: 0.78, wb: 0.76, ct: 0.2, cb: 0.14 },
  { z: -2.2, y: 0.12, w: 0.68, top: 0.72, bot: 0.5, wt: 0.52, wb: 0.46, ct: 0.14, cb: 0.1 },
  { z: -2.95, y: 0.3, w: 0.4, top: 0.42, bot: 0.3, wt: 0.32, wb: 0.3, ct: 0.08, cb: 0.07 },
  { z: -6.1, y: 0.44, w: 0.27, top: 0.28, bot: 0.21, wt: 0.21, wb: 0.2, ct: 0.06, cb: 0.05 },
  { z: -6.75, y: 0.47, w: 0.23, top: 0.24, bot: 0.19, wt: 0.18, wb: 0.18, ct: 0.05, cb: 0.05 },
];

/** 机身上半截侧板那一面（z 处）：中点高、离中线多远、往里倾多少（贴装甲板用） */
function sidePanel(z: number): { y: number; x: number; tilt: number } {
  const s = plateAt(BODY, z);
  const h = s.top - (s.ct ?? 0.2);
  return { y: s.y + h / 2, x: (s.w + s.wt) / 2, tilt: Math.atan2(s.w - s.wt, h) };
}

function hullParts(): HeliPart[] {
  const p: HeliPart[] = [
    { geo: plates(BODY), color: STEEL_D },
    // 机腹一整块装甲板
    { geo: chamferBox(1.3, 0.14, 3.6, 0.05), color: STEEL_D, pos: [0, -1.16, 0.5] },
    // 机鼻：方传感器箱 + 遮光檐（橙色感应眼在亮件里）
    { geo: chamferBox(0.56, 0.36, 0.42, 0.05), color: STEEL, pos: [0, -0.3, 4.66] },
    { geo: chamferBox(0.66, 0.07, 0.5, 0.02), color: DARK, pos: [0, -0.08, 4.7] },
    // 机炮塔：吊在机鼻下面的小棱台（上宽下窄）+ 双管机炮（炮口制退器）
    { geo: frustum(chamfer(0.5, 0.56, 0.12), chamfer(0.72, 0.8, 0.16), 0.3, -1.3), color: STEEL_D, pos: [0, 0, 3.15] },
    { geo: chamferBox(0.46, 0.22, 0.36, 0.04), color: DARK, pos: [0, -1.16, 3.42] },
    ...[-1, 1].map((s): HeliPart => ({ geo: barrel(1.2, 0.065, { brake: true }), color: DARK, pos: [s * 0.12, -1.16, 3.4] })),
    // 旋翼整流座（小棱台）+ 铁狼红带（同坦克炮塔顶沿那道）+ 主轴 + 倾斜盘
    { geo: frustum(chamfer(1.1, 1.5, 0.22), chamfer(0.8, 1.04, 0.16), 0.36), color: STEEL, pos: [0, 0.9, 0.25] },
    { geo: frustum(chamfer(0.86, 1.1, 0.17), chamfer(0.84, 1.08, 0.17), 0.08), color: RED, pos: [0, 1.2, 0.25] },
    { geo: cyl(0.19, 0.26, 0.75), color: DARK, pos: [0, 1.6, 0.25] },
    { geo: cyl(0.42, 0.42, 0.1, 10), color: STEEL_D, pos: [0, 1.66, 0.25] },
    // 发动机舱：棱台 + 顶上一排斜格栅 + 前面两个方进气口 + 后面两根方排气管（朝后上）
    { geo: frustum(chamfer(1.25, 1.8, 0.22), chamfer(0.98, 1.55, 0.18), 0.6), color: STEEL_D, pos: [0, 0.8, -1.25] },
    ...[0, 1, 2, 3, 4].map((i): HeliPart => ({ geo: chamferBox(0.72, 0.05, 0.14, 0.015), color: DARK, pos: [0, 1.42, -0.7 - i * 0.26], rot: [-0.45, 0, 0] })),
    ...[-1, 1].map((s): HeliPart => ({ geo: chamferBox(0.32, 0.26, 0.08, 0.02), color: DARK, pos: [s * 0.27, 1.08, -0.38] })),
    // 短翼（平板 + 翼尖端板）+ 挂架
    { geo: chamferBox(4.5, 0.2, 1.05, 0.06), color: STEEL_D, pos: [0, -0.3, 0.3] },
    // 尾梁：平尾（带端板）+ 后掠垂尾 + 腹鳍 + 两片桨的尾桨（右侧）
    { geo: chamferBox(2.2, 0.12, 0.62, 0.04), color: STEEL_D, pos: [0, 0.45, -5.55] },
    { geo: chamferBox(0.14, 1.35, 0.95, 0.04), color: STEEL_D, pos: [0, 1.08, -6.4], rot: [-0.32, 0, 0] },
    { geo: chamferBox(0.12, 0.55, 0.6, 0.03), color: STEEL_D, pos: [0, 0.08, -6.45], rot: [0.3, 0, 0] },
    { geo: cyl(0.14, 0.14, 0.26), color: DARK, pos: [0.2, 1.25, -6.62], rot: [0, 0, HALF] },
    { geo: chamferBox(0.04, 1.8, 0.18, 0.01), color: DARK, pos: [0.32, 1.25, -6.62], rot: [0.5, 0, 0] },
  ];
  for (const s of [-1, 1]) {
    const rot: [number, number, number] = [0, s < 0 ? Math.PI : 0, 0];
    // 两侧上半截三块分块装甲板（中间那块往外错一点，板缝 0.1 米）+ 方铆钉
    [[1.95, 1.25], [0.6, 1.3], [-0.78, 1.1]].forEach(([z, d], i) => {
      const P = sidePanel(z);
      const out = 0.06 + (i === 1 ? 0.05 : 0);
      const x = s * (P.x + out * Math.cos(P.tilt));
      p.push(...place(armorPlate(0.1, 0.62, d, i === 1 ? STEEL : STEEL_D, DARK, 4), [x, P.y + out * Math.sin(P.tilt), z], [rot[0], rot[1], P.tilt]));
    });
    // 翼尖端板 + 挂架 + 方箱火箭巢（3 × 3 管口在前脸，两道箍，顶上一道红条）
    const x = s * 1.95;
    p.push({ geo: chamferBox(0.1, 0.5, 0.9, 0.03), color: DARK, pos: [s * 2.27, -0.3, 0.3] });
    p.push({ geo: chamferBox(0.2, 0.22, 0.75, 0.04), color: DARK, pos: [x, -0.5, 0.35] });
    p.push({ geo: chamferBox(0.8, 0.8, 1.7, 0.08), color: STEEL_D, pos: [x, -1.0, 0.36] });
    for (const z of [0.95, -0.25]) p.push({ geo: chamferBox(0.86, 0.86, 0.1, 0.03), color: DARK, pos: [x, -1.0, z] });
    p.push({ geo: chamferBox(0.84, 0.05, 0.42, 0.02), color: RED, pos: [x, -0.585, 0.5] });
    for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) p.push({ geo: cyl(0.085, 0.085, 0.08), color: DARK, pos: [x + (i - 1) * 0.24, -1.0 + (j - 1) * 0.24, 1.23], rot: [HALF, 0, 0] });
    // 方排气管（朝后上斜）+ 黑口
    p.push(...place([{ geo: chamferBox(0.3, 0.3, 0.55, 0.05), color: DARK }, { geo: new THREE.BoxGeometry(0.2, 0.2, 0.04), color: 0x141414, pos: [0, 0, -0.28] }], [s * 0.36, 1.2, -2.2], [0.35, 0, 0]));
    // 滑橇：方管，两道横梁伸出机腹再直角往下接到滑橇，前头一截斜着翘起
    const kx = s * 1.05;
    p.push({ geo: bar([kx, -1.78, -0.9], [kx, -1.78, 2.1], 0.12, 0.1), color: DARK });
    p.push({ geo: bar([kx, -1.78, 2.1], [kx, -1.58, 2.42], 0.12, 0.1), color: DARK });
    for (const z of [-0.3, 1.4]) {
      p.push({ geo: bar([0, -1.3, z], [kx, -1.3, z], 0.1), color: DARK });
      p.push({ geo: bar([kx, -1.3, z], [kx, -1.78, z], 0.1), color: DARK });
    }
    // 平尾端板
    p.push({ geo: chamferBox(0.08, 0.46, 0.5, 0.02), color: DARK, pos: [s * 1.1, 0.5, -5.57] });
  }
  // 框架式座舱：平板玻璃罩（前挡风斜着、侧窗、顶窗）+ 每条棱一根方窗框
  p.push(...canopy(chamfer(1.36, 2.3, 0.3, 0, 2.35), chamfer(0.92, 1.05, 0.22, 0, 1.85), 0.8, 0.2, GLASS, DARK));
  return p;
}

/** 亮件：pyl = 1 是挂架亮光件（亮度由每架自己的 uPyl 管），2 是锁定亮光件（uLock，铁鹰的导弹导引头）；每件记一个中心（低档放大 1.3 倍绕它放大） */
export type GlowPart = { spec: PartSpec; pyl: number };

function glowParts(): GlowPart[] {
  const out: GlowPart[] = [
    // 机鼻传感器箱的橙色感应眼（T096 尾梁上的橙红锯齿条去掉了）
    { spec: { geo: cyl(0.12, 0.12, 0.04, 10), color: 0xff8a28, pos: [0, -0.3, 4.885], rot: [HALF, 0, 0] }, pyl: 0 },
  ];
  // 火箭巢前脸：整块方板亮（管口在机身网格里，盖在亮板前面）
  for (const [x, y, z] of VULTURE_PTS.pods) out.push({ spec: { geo: new THREE.BoxGeometry(0.7, 0.7, 0.03), color: 0xffffff, pos: [x, y, z - 0.035] }, pyl: 1 });
  return out;
}

export function vultureHull(geo: GeoCache): THREE.BufferGeometry {
  return geo.get('vulture-hull', () => mergeHeli('vulture-hull', hullParts()));
}

/** 亮件几何体（秃鹫 / 铁鹰共用写法）：顶点色 + aPyl（0 常亮 / 1 挂架 / 2 锁定）+ aCtr（低档放大的中心） */
export function glowGeometry(key: string, parts: GlowPart[]): THREE.BufferGeometry {
  const m = new THREE.Matrix4();
  const q = new THREE.Quaternion();
  const e = new THREE.Euler();
  const c = new THREE.Color();
  const list = parts.map(({ spec, pyl }) => {
    const g = copyGeometry(spec.geo);
    spec.geo.dispose();
    const pos = spec.pos ?? [0, 0, 0];
    g.applyMatrix4(m.compose(new THREE.Vector3(...pos), q.setFromEuler(e.set(...(spec.rot ?? [0, 0, 0]))), new THREE.Vector3(...(spec.scale ?? [1, 1, 1]))));
    g.deleteAttribute('uv');
    const n = g.getAttribute('position').count;
    c.setHex(spec.color);
    const col = new Float32Array(n * 3);
    const pf = new Float32Array(n);
    const ctr = new Float32Array(n * 3);
    for (let i = 0; i < n; i++) {
      col.set([c.r, c.g, c.b], i * 3);
      pf[i] = pyl;
      ctr.set(pos, i * 3);
    }
    g.setAttribute('color', new THREE.BufferAttribute(col, 3));
    g.setAttribute('aPyl', new THREE.BufferAttribute(pf, 1));
    g.setAttribute('aCtr', new THREE.BufferAttribute(ctr, 3));
    return g;
  });
  const out = mergeGeometries(list, false);
  for (const g of list) g.dispose();
  if (!out) throw new Error(`合并几何体失败: ${key}`);
  return out;
}

export function vultureGlow(geo: GeoCache): THREE.BufferGeometry {
  return geo.get('vulture-glow', () => glowGeometry('vulture-glow', glowParts()));
}

/**
 * 机身材质（只给空中单位，T095 改；T096 底子换成地面坦克那份：顶点色 × 钢灰迷彩 + 金属细节法线，粗糙度 / 金属度同 enemyPaint），再分三层——
 * ①受光面：朝镜头左上那一侧提亮；②背光面：背着的一侧和机腹压暗（不然顺光下整架一个灰度，读不出体积）；③轮廓光：视线掠过的边一圈暖白自发光。
 * 玻璃（aGlass = 1）：深色底 + 按反射方向取的天 / 地两色（中间一道地平线）+ 一道高光，边缘越斜越亮。都写在着色器里，不加绘制次数。
 * rim / shade 由 Air 按画质档改（低档没泛光，轮廓光略亮、机身再压三成）
 */
export const VULTURE_RIM = { value: 0.7 };
export const VULTURE_SHADE = { value: 1 };
/** 补的主光（从镜头左上方打过来，不管太阳在哪都有受光面）、背光面压到多少、机腹压到多少（T095 调参用） */
export const VULTURE_FORM = { key: { value: 0.14 }, back: { value: 0.6 }, belly: { value: 0.55 } };
let skin: THREE.MeshStandardMaterial | null = null;
export function vultureSkin(): THREE.MeshStandardMaterial {
  if (skin) return skin;
  const m = new THREE.MeshStandardMaterial({ vertexColors: true, map: sharedEnemyCamo(), normalMap: sharedMetalNormal(), normalScale: new THREE.Vector2(0.45, 0.45), color: 0xffffff, roughness: 0.62, metalness: 0.38 });
  m.onBeforeCompile = (shader) => {
    shader.uniforms.uRim = VULTURE_RIM;
    shader.uniforms.uShade = VULTURE_SHADE;
    shader.uniforms.uKey = VULTURE_FORM.key;
    shader.uniforms.uBack = VULTURE_FORM.back;
    shader.uniforms.uBelly = VULTURE_FORM.belly;
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', '#include <common>\nattribute float aGlass;\nvarying float vGlass;')
      .replace('#include <begin_vertex>', '#include <begin_vertex>\nvGlass = aGlass;');
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', '#include <common>\nuniform float uRim;\nuniform float uShade;\nuniform float uKey;\nuniform float uBack;\nuniform float uBelly;\nvarying float vGlass;')
      .replace(
        '#include <emissivemap_fragment>',
        `#include <emissivemap_fragment>
// 平板玻璃不吃金属细节法线（T096：不然一块平板上满是碎亮点）
if (vGlass > 0.5) normal = nonPerturbedNormal;
vec3 nV = normalize(normal);
vec3 vV = normalize(vViewPosition);
float rimF = 1.0 - clamp(dot(nV, vV), 0.0, 1.0);
vec3 nW = inverseTransformDirection(nV, viewMatrix);
if (vGlass > 0.5) {
  roughnessFactor = 0.12;
  metalnessFactor = 0.0;
  diffuseColor.rgb = vec3(0.012, 0.016, 0.02);
  vec3 rW = inverseTransformDirection(reflect(-vV, nV), viewMatrix);
  vec3 sky = mix(vec3(0.42, 0.5, 0.58), vec3(0.78, 0.84, 0.9), smoothstep(0.05, 0.7, rW.y));
  vec3 refl = mix(vec3(0.09, 0.085, 0.07), sky, smoothstep(-0.04, 0.06, rW.y));
  float fres = 0.22 + 0.78 * pow(rimF, 2.5);
  // T096 座舱换成平板玻璃：一整块要么全反光、要么不反，反光和高光都压一档（不然一块板整片刷白）
  totalEmissiveRadiance += refl * fres * 0.45 * uShade;
  totalEmissiveRadiance += vec3(1.0, 0.95, 0.86) * smoothstep(0.975, 0.998, dot(rW, normalize(vec3(-0.45, 0.75, 0.5)))) * 0.8;
} else {
  float key = dot(nV, normalize(vec3(-0.5, 0.72, 0.48)));
  float belly = mix(uBelly, 1.0, smoothstep(-0.85, 0.35, nW.y));
  vec3 base = diffuseColor.rgb * uShade * belly;
  diffuseColor.rgb = base * mix(uBack, 1.0, smoothstep(-0.3, 0.4, key));
  totalEmissiveRadiance += base * vec3(1.0, 0.95, 0.86) * smoothstep(0.0, 0.9, key) * uKey;
  // 轮廓光收窄、偏上沿（T095：放样机身 + 方截面在正面看侧壁都是掠射角，原来那一档会把整个侧面刷白）
  totalEmissiveRadiance += vec3(1.0, 0.88, 0.7) * smoothstep(0.86, 0.985, rimF) * (0.3 + 0.7 * smoothstep(-0.3, 0.7, nV.y)) * uRim;
}`,
      )
      // 远处进雾只进六成：150 米外进场时还是一个分得清的暗影（身后的远地进了雾，发亮）
      .replace(
        '#include <fog_fragment>',
        `#ifdef USE_FOG
#ifdef FOG_EXP2
float fogFactor = (1.0 - exp(-fogDensity * fogDensity * vFogDepth * vFogDepth)) * 0.6;
#else
float fogFactor = smoothstep(fogNear, fogFar, vFogDepth) * 0.6;
#endif
gl_FragColor.rgb = mix(gl_FragColor.rgb, fogColor, fogFactor);
#endif`,
      );
  };
  m.customProgramCacheKey = () => 'vulture-rim-t096';
  return (skin = m);
}

/** 低档没泛光：亮件绕各自中心放大这么多（Air 按画质档改；挂架 / 锁定件只在亮起来时放大，平时暗红照原大） */
export const VULTURE_GLOW_SCALE = { value: 1 };

/**
 * 亮件材质（每架一份，挂架 / 锁定亮度各管各的）：不受光、超过 1 的亮度吃泛光；平时暗红，uPyl / uLock → 1 亮成敌方预警红（T130，挂架原来亮橙白）
 */
export function vultureGlowMat(): THREE.MeshBasicMaterial {
  const u = { uPyl: { value: 0 }, uLock: { value: 0 } };
  const m = new THREE.MeshBasicMaterial({ vertexColors: true, toneMapped: false });
  m.onBeforeCompile = (shader) => {
    shader.uniforms.uPyl = u.uPyl;
    shader.uniforms.uLock = u.uLock;
    shader.uniforms.uGlowScale = VULTURE_GLOW_SCALE;
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', '#include <common>\nattribute float aPyl;\nattribute vec3 aCtr;\nuniform float uPyl;\nuniform float uLock;\nuniform float uGlowScale;')
      // color_vertex 在 begin_vertex 前面：p1 / p2 / on 在这里声明，后面放大也用
      .replace(
        '#include <begin_vertex>',
        `#include <begin_vertex>
transformed = aCtr + (transformed - aCtr) * mix(uGlowScale, 1.0 + (uGlowScale - 1.0) * on, p1 + p2);`,
      )
      .replace(
        '#include <color_vertex>',
        `#include <color_vertex>
float p1 = step(0.5, aPyl) * step(aPyl, 1.5);
float p2 = step(1.5, aPyl);
float on = p1 * uPyl + p2 * uLock;
vec3 c1 = mix(vec3(0.1, 0.022, 0.01), ${glslColor(WARN_ENEMY, 2.2)}, uPyl);
vec3 c2 = mix(vec3(0.14, 0.016, 0.01), ${glslColor(WARN_ENEMY, 2.2)}, uLock);
vColor.rgb = vColor.rgb * 1.6 * (1.0 - p1 - p2) + c1 * p1 + c2 * p2;`,
      );
  };
  m.customProgramCacheKey = () => 'vulture-glow-t095';
  m.userData.u = u;
  return m;
}

/**
 * 旋翼盘（全体一个实例化网格）：半透明深色圆盘 + 桨叶 + 一圈亮边，做成浅锥形（边缘上翘 cone 米），平着看也有几像素粗。
 * 顶点色带透明度（RGBA），一个材质画完；low = 低档省面（圆盘 20 段、亮边一层）；blades = 几片桨（秃鹫 2、铁鹰 4）；
 * 桨叶从 r0 起画（里面那截是桨夹 / 加厚的桨根，在 vultureHub 里，实心、受光）
 */
export function rotorGeometry(low: boolean, blades = 2, r0 = 1.85): THREE.BufferGeometry {
  const seg = low ? 20 : 40;
  const R = ROTOR.r;
  const K = ROTOR.cone / R;
  const pos: number[] = [];
  const col: number[] = [];
  const tri = (a: number[], b: number[], c: number[], rgba: number[]) => {
    pos.push(...a, ...b, ...c);
    for (let i = 0; i < 3; i++) col.push(...rgba);
  };
  const quad = (a: number[], b: number[], c: number[], d: number[], rgba: number[]) => {
    tri(a, b, c, rgba);
    tri(a, c, d, rgba);
  };
  const at = (r: number, a: number, dy = 0) => [Math.cos(a) * r, r * K + dy, Math.sin(a) * r];
  const lin = (h: number) => {
    const c = new THREE.Color(h);
    return [c.r, c.g, c.b];
  };
  const disk = lin(0x16181a);
  const blade = lin(0x222426);
  const rim = lin(0xd8d0c2);
  for (let i = 0; i < seg; i++) {
    const a0 = (i / seg) * Math.PI * 2;
    const a1 = ((i + 1) / seg) * Math.PI * 2;
    // 圆盘：里淡外浓（转起来外圈桨尖扫得快、看着实）
    quad(at(0.45, a0), at(R * 0.6, a0), at(R * 0.6, a1), at(0.45, a1), [...disk, 0.2]);
    quad(at(R * 0.6, a0), at(R * 0.97, a0), at(R * 0.97, a1), at(R * 0.6, a1), [...disk, 0.34]);
    // 亮边：一圈平的 + 一圈立着的窄带（平视也是一道亮线）
    quad(at(R * 0.97, a0), at(R * 1.02, a0), at(R * 1.02, a1), at(R * 0.97, a1), [...rim, 0.55]);
    if (!low) quad(at(R * 1.0, a0, -0.06), at(R * 1.0, a0, 0.08), at(R * 1.0, a1, 0.08), at(R * 1.0, a1, -0.06), [...rim, 0.36]);
  }
  // 桨叶（宽 0.42 米），跟着锥面上翘
  for (let b = 0; b < blades; b++) {
    const a = (b / blades) * Math.PI * 2;
    const c = Math.cos(a);
    const s = Math.sin(a);
    const w = 0.21;
    const r1 = R * 0.98;
    const y = (r: number) => r * K + 0.03;
    const P = (r: number, t: number) => [c * r - s * t, y(r), s * r + c * t];
    quad(P(r0, -w), P(r1, -w), P(r1, w), P(r0, w), [...blade, 0.92]);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(pos), 3));
  g.setAttribute('color', new THREE.BufferAttribute(new Float32Array(col), 4));
  return g;
}

/**
 * 旋翼盘材质：半透明顶点色。亮边是给远处认直升机用的（T091：117 米进场也看得出一圈），离镜头 45 米以内慢慢淡掉——
 * 平时离镜头 60～160 米，照旧一圈亮边；只有特写 / 坠到跟前时不再是一个白圈（T095）
 */
export function rotorMaterial(): THREE.MeshBasicMaterial {
  const m = new THREE.MeshBasicMaterial({ vertexColors: true, transparent: true, depthWrite: false, side: THREE.DoubleSide, forceSinglePass: true });
  m.onBeforeCompile = (shader) => {
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', '#include <common>\nvarying float vRimFade;')
      .replace('#include <project_vertex>', '#include <project_vertex>\nvRimFade = smoothstep(28.0, 45.0, -mvPosition.z);');
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', '#include <common>\nvarying float vRimFade;')
      .replace('#include <color_fragment>', '#include <color_fragment>\nif (vColor.r > 0.4) diffuseColor.a *= vRimFade;');
  };
  m.customProgramCacheKey = () => 'heli-rotor';
  return m;
}

/**
 * 桨毂（T095，跟着旋翼转，实心、受光，全体一个实例化网格）：毂筒 + 顶盖 + 每片桨一个桨夹 + 加厚的桨根（到 r0 接上旋翼盘里的桨叶）+ 变距拉杆。
 * T096：顶盖从半球换成八角平顶，毂筒少几段（棱看得出来）
 * 坐标原点 = 桨毂中心（ROTOR.hub）
 */
export function hubParts(blades: number, k = 1): HeliPart[] {
  const p: HeliPart[] = [
    { geo: cyl(0.34 * k, 0.38 * k, 0.32 * k, 10), color: STEEL_D, pos: [0, 0, 0] },
    { geo: cyl(0.2 * k, 0.3 * k, 0.12 * k, 8), color: STEEL, pos: [0, 0.22 * k, 0] },
    { geo: cyl(0.42 * k, 0.42 * k, 0.08 * k, 10), color: DARK, pos: [0, -0.2 * k, 0] },
  ];
  for (let b = 0; b < blades; b++) {
    const a = (b / blades) * Math.PI * 2;
    const rot: [number, number, number] = [0, -a, 0];
    const at = (r: number, dy = 0, t = 0): [number, number, number] => [Math.cos(a) * r - Math.sin(a) * t, dy, Math.sin(a) * r + Math.cos(a) * t];
    p.push({ geo: chamferBox(0.85 * k, 0.24 * k, 0.32 * k, 0.05 * k), color: STEEL_D, pos: at(0.62 * k), rot });
    // 桨根：从桨夹往外收薄的一截（厚 0.16 → 0.07）
    const root = new THREE.CylinderGeometry(0.5, 0.5, 1, 4, 1);
    root.rotateY(Math.PI / 4);
    root.rotateZ(HALF);
    const pa = root.getAttribute('position') as THREE.BufferAttribute;
    for (let i = 0; i < pa.count; i++) {
      const t = pa.getX(i) + 0.5;
      pa.setY(i, pa.getY(i) * (0.16 - 0.09 * t) * 1.41 * k);
      pa.setZ(i, pa.getZ(i) * (0.46 - 0.04 * t) * 1.41 * k);
      pa.setX(i, (1.0 + t * 0.9) * k);
      pa.setY(i, pa.getY(i) + (1.0 + t * 0.9) * k * (ROTOR.cone / ROTOR.r));
    }
    root.computeVertexNormals();
    p.push({ geo: root, color: DARK, pos: [0, 0.03, 0], rot });
    p.push({ geo: pipe(at(0.45 * k, -0.2 * k, 0.2 * k), at(0.52 * k, 0.02, 0.2 * k), 0.035 * k, 5), color: DARK });
  }
  return p;
}

export function vultureHub(geo: GeoCache): THREE.BufferGeometry {
  return geo.get('vulture-hub', () => mergeHeli('vulture-hub', hubParts(2)));
}

/** 正下方软圆影的贴图：中心实、边缘柔和淡出（白色，透明度在 alpha 通道） */
export function shadowTexture(): THREE.DataTexture {
  const n = 64;
  const data = new Uint8Array(n * n * 4);
  for (let y = 0; y < n; y++) {
    for (let x = 0; x < n; x++) {
      const d = Math.hypot(x + 0.5 - n / 2, y + 0.5 - n / 2) / (n / 2);
      const a = Math.max(0, 1 - THREE.MathUtils.smoothstep(d, 0.35, 1));
      const i = (y * n + x) * 4;
      data[i] = data[i + 1] = data[i + 2] = 255;
      data[i + 3] = Math.round(a * 255);
    }
  }
  const t = new THREE.DataTexture(data, n, n, THREE.RGBAFormat);
  t.needsUpdate = true;
  t.magFilter = THREE.LinearFilter;
  t.minFilter = THREE.LinearFilter;
  return t;
}
