/**
 * 武器挂件模型：都以 -Z 为"枪口朝向"，原点在安装座底部。
 * 返回 Group：base（不转）+ head（会转向目标）。
 * T143：按 weapons/subTiers.ts 的 MOUNT_FORM 表搭——这一级有哪些零件、每个零件挂在哪个枢轴、用什么材质；同一个枢轴同一种材质的零件合成一个网格
 */
export interface MountModel {
  root: THREE.Group;
  head: THREE.Object3D;
  /** 枪口 / 发射点（head 局部坐标里） */
  muzzles: THREE.Object3D[];
  /** 需要旋转的部件（转管、线圈） */
  spinner: THREE.Object3D | null;
  /** 整体放大倍数（焊装弹一下时 root 会临时变，按这个算占地） */
  scale: number;
  /** head 会不会转向目标（机枪 / 迫击炮 / 喷火器；T127 炮塔转身限位按它各个朝向都算） */
  turns: boolean;
  /** 形态等级（1～5，★ = 6）和这一级有的零件（T143） */
  lv: number;
  keys: string[];
  /** 会动的枢轴（head / 转管 / 弹鼓 / 后坐…），按名字取 */
  pivots: Record<string, THREE.Object3D>;
  /** 发光件的亮度（这件挂件自己一份；0 = 不亮，上限 GLOW_MAX）；没有发光件为 null */
  glow: { value: number } | null;
  /** 联动模块 / 究极配套发光件的颜色 × 亮度（没有为 null） */
  glow2: { value: THREE.Color } | null;
  /** 特斯拉线圈逐圈点亮：fill = 亮到多高（挂件局部 y）、glow = 亮度 */
  coil: { fill: { value: number }; glow: { value: number } } | null;
  /** 会烧红的枪管（机枪 5 级起，emissiveIntensity 跟着连射热度）；没有为 null */
  heat: THREE.MeshStandardMaterial | null;
  /** 实例化的一排：shells 立弹 / parked 停着的无人机 / navs 航行灯 / lids 舱盖 / lamps 信号灯（count、矩阵、颜色由武器逻辑改；userData.rest = 摆放位置） */
  racks: Record<string, THREE.InstancedMesh>;
  /** 安装演出时单独画的新零件（holder 在铰点上，演完并回主体） */
  fresh: FreshPart[];
  /** 这个模型自己建的材质（换模型时释放） */
  mats: THREE.Material[];
}

/** 新零件进场的方式：rise = 从铰点往上长出来 / slide = 从 from 偏移滑进来 / pop = 从 0 放大 */
export interface Enter {
  kind: 'rise' | 'slide' | 'pop';
  from?: V3;
  hinge?: V3;
}
export interface FreshPart {
  holder: THREE.Object3D;
  enter: Enter;
  mat: THREE.MeshStandardMaterial;
}

function muzzle(parent: THREE.Object3D, x: number, y: number, z: number): THREE.Object3D {
  const o = new THREE.Object3D();
  o.position.set(x, y, z);
  parent.add(o);
  return o;
}

// ------------------------------------------------------------------ T143 分级挂件

/** paint / metal = 共用的车漆 / 枪铁；glow = 本件发光件；glow2 = 联动模块 / 究极配套的发光件（颜色由 glow2 给）；heat = 会烧红的枪管；coil = 特斯拉铜线圈（放电前从下往上逐圈点亮） */
type MatKey = 'paint' | 'metal' | 'glow' | 'glow2' | 'heat' | 'coil';

/** 搭零件时能用到的：形态等级、档、装在车的哪一侧（往外长的零件按它镜像）、是不是炮塔挂点、配色、这一级有的零件、联动、究极 */
export interface MountCtx {
  lv: number;
  grade: Grade;
  side: 1 | -1;
  turret: boolean;
  pal: Palette;
  keys: Set<string>;
  link: LinkId | null;
  ult: FusionId | null;
}

/** 一块零件（可以单独指定材质：天线杆是车漆、顶灯是发光件，同一个零件表项里写） */
type MPart = PartSpec & { mat?: MatKey };

interface PartDef {
  /** 挂在哪个枢轴上（默认 head；root = 不转的底座） */
  pivot?: string;
  mat?: MatKey | ((c: MountCtx) => MatKey);
  /** 安装演出的进场方式（不写 = pop） */
  enter?: Enter;
  build(c: MountCtx): MPart[];
}

/** 实例化的一排同样的东西（立着的炮弹、停着的无人机、舱盖、信号灯）：count 由武器逻辑按每轮几发 / 装填进度改；lamp = 自发光灯（每个实例的颜色 = 亮 / 灭） */
interface RackDef {
  name: string;
  pivot: string;
  /** 几何体缓存键（同一种外形写同一个） */
  geo: string;
  parts: () => PartSpec[];
  mat: 'paint' | 'lamp';
  at: { pos: V3; rot?: V3 }[];
  count: number;
}

interface WeaponForm {
  /** 枢轴：父枢轴 + 位置 + 转角（按顺序建，父的要先写） */
  pivots: Record<string, { parent: string; pos: V3 | ((c: MountCtx) => V3); rot?: V3 }>;
  parts: Record<string, PartDef>;
  racks?(c: MountCtx): RackDef[];
  muzzles(c: MountCtx): { pivot: string; pos: V3 }[];
  spinner?(c: MountCtx): string | null;
  turns: boolean;
}

const box = (w: number, h: number, d: number, color: number, pos: V3, rot?: V3): PartSpec => ({ geo: new THREE.BoxGeometry(w, h, d), color, pos, rot });
const cyl = (rt: number, rb: number, h: number, color: number, pos: V3, rot?: V3, seg = 12): PartSpec => ({ geo: new THREE.CylinderGeometry(rt, rb, h, seg), color, pos, rot });
const ball = (r: number, color: number, pos: V3, seg = 12): PartSpec => ({ geo: new THREE.SphereGeometry(r, seg, Math.max(6, seg - 2)), color, pos });
/** 指定这一块的材质 */
const as = (mat: MatKey, ...parts: PartSpec[]): MPart[] => parts.map((p) => ({ ...p, mat }));
/** 沿 Z 的圆柱（top = -Z 那头） */
const zc = (r: number, len: number, color: number, pos: V3, seg = 12, r1 = r): PartSpec => cyl(r, r1, len, color, pos, [-Math.PI / 2, 0, 0], seg);
/** 沿 X 的圆柱 */
const xc = (r: number, len: number, color: number, pos: V3, seg = 12): PartSpec => cyl(r, r, len, color, pos, [0, 0, Math.PI / 2], seg);
/** 竖边倒角的方块（平直块面 + 小倒角，T096 那套建模语言） */
const cbox = (w: number, h: number, d: number, c: number, color: number, pos: V3, rotY = 0): PartSpec => {
  const outline = chamfer(w, d, c);
  return { geo: frustum(outline, outline, h, -h / 2), color, pos, rot: [0, rotY, 0] };
};
/** 一排铆钉（沿 a → b 均匀摆 n 个） */
const studs = (n: number, a: V3, b: V3, color: number, s = 0.035): PartSpec[] =>
  Array.from({ length: n }, (_, i) => {
    const k = n === 1 ? 0.5 : i / (n - 1);
    return box(s, s, s, color, [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k]);
  });
const HOLE = 0x121314;
const RUST = 0x7a3a22;

/** 机枪枪管（直径 0.25 米 + 带孔散热套）：x = 左右位置 */
function mgGun(x: number, dark: number): PartSpec[] {
  const out: PartSpec[] = [
    { geo: barrel(1.2, 0.08), color: 0x5c6164, pos: [x, 0.22, -0.3], rot: [0, Math.PI, 0] },
    zc(0.115, 0.56, dark, [x, 0.22, -0.63], 12),
    zc(0.125, 0.05, dark, [x, 0.22, -0.36], 12),
  ];
  for (let i = 0; i < 4; i++) {
    const z = -0.45 - i * 0.12;
    out.push(box(0.05, 0.03, 0.06, HOLE, [x, 0.337, z]), box(0.03, 0.05, 0.06, HOLE, [x + 0.116, 0.22, z]), box(0.03, 0.05, 0.06, HOLE, [x - 0.116, 0.22, z]));
  }
  return out;
}

const _q = new THREE.Quaternion();
const _e = new THREE.Euler();
const _v = new THREE.Vector3();
const _z = new THREE.Vector3(0, 0, 1);
/** 从 a 到 b 的一根方条（接线、支架、驻锄） */
function bar(a: V3, b: V3, w: number, color: number): PartSpec {
  _v.set(b[0] - a[0], b[1] - a[1], b[2] - a[2]);
  const len = _v.length();
  _e.setFromQuaternion(_q.setFromUnitVectors(_z, _v.normalize()));
  return box(w, w, len, color, [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2, (a[2] + b[2]) / 2], [_e.x, _e.y, _e.z]);
}

/** 究极配套（策划 3.8）：两股红铜接线 a → b + 灯座 + 一盏灯（glow2：颜色跟炮塔究极套件的指示灯） */
function ultKit(c: MountCtx, lamp: V3, a: V3, b: V3): MPart[] {
  return [
    bar(a, b, 0.045, COPPER),
    bar([a[0], a[1] + 0.06, a[2]], [b[0], b[1] + 0.06, b[2]], 0.035, COPPER),
    box(0.15, 0.08, 0.15, c.pal.dark, [lamp[0], lamp[1] - 0.04, lamp[2]]),
    ...as('glow2', box(0.1, 0.08, 0.1, 0xffffff, [lamp[0], lamp[1] + 0.04, lamp[2]])),
  ];
}

/** 联动模块的发光件（glow2，平时 LINK_GLOW.base 亮，联动触发时闪）：partner = 对方的识别色 */
const lkLamp = (partner: WeaponId, pos: V3, s = 0.08): MPart[] => as('glow2', box(s, s, s, SUB_ID[partner], pos));

/**
 * 底座（T177，制作人「机枪和特斯拉是圆形底盘舵上去的，和炮塔的结合不够丝滑」）：原来四件都是一只 0.5 米半径的圆台直接摆在挂点上。
 * 炮塔挂点（0 / 1）：方形转接板（四角螺栓），坐在炮塔上的车漆托架（playerTank.turretPad）里；会转的头（机枪 / 喷火器）上面一圈深色座圈 + 短立柱，不转的（特斯拉 / 空袭）是一只收口方座。
 * 车体挂点：八角倒角装甲座 + 座圈 / 盖板。顶面都在 0.22（head 的高度不变）
 */
function pedestal(c: MountCtx, turns: boolean): MPart[] {
  const top: PartSpec[] = turns
    ? [cyl(0.3, 0.33, 0.06, c.pal.dark, [0, c.turret ? 0.1 : 0.19, 0], undefined, 18), ...(c.turret ? [cyl(0.19, 0.23, 0.09, c.pal.body, [0, 0.175, 0], undefined, 14)] : [])]
    : c.turret ? [{ geo: frustum(chamfer(0.54, 0.54, 0.08), chamfer(0.46, 0.46, 0.06), 0.15, 0.07), color: c.pal.body }] : [cbox(0.56, 0.06, 0.56, 0.13, c.pal.trim, [0, 0.19, 0])];
  if (c.turret) {
    return [
      cbox(0.56, 0.07, 0.56, 0.08, c.pal.trim, [0, 0.035, 0]),
      ...[-1, 1].flatMap((i) => [-1, 1].map((k) => cyl(0.03, 0.03, 0.03, c.pal.dark, [i * 0.21, 0.08, k * 0.21], undefined, 6))),
      ...top,
    ];
  }
  return [{ geo: frustum(chamfer(0.68, 0.68, 0.18), chamfer(0.58, 0.58, 0.14), 0.16), color: c.pal.body }, ...top, ...studs(4, [-0.2, 0.165, 0.27], [0.2, 0.165, 0.27], c.pal.dark, 0.035)];
}

