/** 车上停着的无人机（实例，原点在导轨面）：橄榄机身（T177，原来浅钢灰 0xa4abb0，车身迷彩材质）+ 机腹红弹头（5 级加大到 0.4 米）+ 四个旋翼盘；武装无人机机腹多一挺吊舱机枪 */
function parkedDrone(big: boolean, pod: boolean): PartSpec[] {
  const parts: PartSpec[] = [
    cbox(0.34, 0.12, 0.56, 0.05, 0x8c9078, [0, 0.11, 0]),
    box(big ? 0.24 : 0.16, big ? 0.13 : 0.09, big ? 0.3 : 0.2, 0x9a2a1e, [0, big ? 0.0 : 0.02, -0.1]),
    box(0.12, 0.05, 0.14, 0x2a2d2f, [0, 0.19, 0.12]),
    box(0.02, 0.12, 0.12, 0x2a2d2f, [0, 0.2, 0.26]),
  ];
  for (const [x, z] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) {
    parts.push(box(0.5, 0.03, 0.05, 0x2a2d2f, [x * 0.2, 0.13, z * 0.2], [0, x * z > 0 ? -0.78 : 0.78, 0]));
    parts.push(cyl(0.15, 0.15, 0.015, 0x3a3d40, [x * 0.35, 0.16, z * 0.35], undefined, 12));
  }
  if (pod) parts.push(box(0.08, 0.07, 0.18, 0x2a2d2f, [0.12, 0.02, -0.08]), zc(0.025, 0.2, BRASS, [0.12, 0.02, -0.26], 6));
  return parts;
}

