const FORMS: Partial<Record<WeaponId, WeaponForm>> = { mg: MG_FORM, flamer: FLAMER_FORM, mortar: MORTAR_FORM, tesla: TESLA_FORM, drones: DRONES_FORM, airstrike: AIRSTRIKE_FORM };

/** 发光件材质：顶点色既是底色（压暗）也是发光色，亮度 uSubGlow（这件挂件自己的 glow.value）；所有挂件共用一个着色器程序 */
function glowMaterial(u: { value: number }): THREE.MeshStandardMaterial {
  const m = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.4, metalness: 0.15 });
  m.onBeforeCompile = (s) => {
    s.uniforms.uSubGlow = u;
    s.fragmentShader = s.fragmentShader
      .replace('#include <common>', '#include <common>\nuniform float uSubGlow;')
      .replace('#include <color_fragment>', '#include <color_fragment>\ndiffuseColor.rgb *= 0.25;')
      .replace('#include <emissivemap_fragment>', '#include <emissivemap_fragment>\ntotalEmissiveRadiance = vColor.rgb * uSubGlow;');
  };
  m.customProgramCacheKey = () => 'subGlow';
  return m;
}

/** 联动模块 / 究极配套的发光件：发光 = 顶点色 × uSubGlow2（颜色向量：联动 = 灰度亮度，究极 = 炮塔套件指示灯的颜色） */
function glow2Material(u: { value: THREE.Color }): THREE.MeshStandardMaterial {
  const m = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.4, metalness: 0.15 });
  m.onBeforeCompile = (s) => {
    s.uniforms.uSubGlow2 = u;
    s.fragmentShader = s.fragmentShader
      .replace('#include <common>', '#include <common>\nuniform vec3 uSubGlow2;')
      .replace('#include <color_fragment>', '#include <color_fragment>\ndiffuseColor.rgb *= 0.25;')
      .replace('#include <emissivemap_fragment>', '#include <emissivemap_fragment>\ntotalEmissiveRadiance = vColor.rgb * uSubGlow2;');
  };
  m.customProgramCacheKey = () => 'subGlow2';
  return m;
}

/** 特斯拉铜线圈：平时是铜；放电前 uCoilFill 从下往上扫，扫过的那几圈电蓝发光（亮度 uCoilGlow）——按挂件局部高度算，一个网格画完 */
function coilMaterial(u: { fill: { value: number }; glow: { value: number } }): THREE.MeshStandardMaterial {
  // T177：粗糙度 0.35 → 0.6（旧铜，不再一圈圈反橙光）
  const m = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.6, metalness: 0.65 });
  m.onBeforeCompile = (s) => {
    s.uniforms.uCoilFill = u.fill;
    s.uniforms.uCoilGlow = u.glow;
    s.vertexShader = s.vertexShader.replace('#include <common>', '#include <common>\nvarying float vCoilY;').replace('#include <begin_vertex>', '#include <begin_vertex>\nvCoilY = position.y;');
    s.fragmentShader = s.fragmentShader
      .replace('#include <common>', '#include <common>\nuniform float uCoilFill;\nuniform float uCoilGlow;\nvarying float vCoilY;')
      .replace('#include <emissivemap_fragment>', '#include <emissivemap_fragment>\ntotalEmissiveRadiance += vec3(0.18, 0.46, 1.0) * uCoilGlow * (1.0 - smoothstep(uCoilFill - 0.05, uCoilFill + 0.05, vCoilY));');
  };
  m.customProgramCacheKey = () => 'subCoil';
  return m;
}

/** 安装演出新零件用的白闪材质（emissiveIntensity 由演出改） */
function flashMaterial(): THREE.MeshStandardMaterial {
  return new THREE.MeshStandardMaterial({ vertexColors: true, map: (MAT.painted as THREE.MeshStandardMaterial).map, roughness: 0.6, metalness: 0.2, emissive: 0xffffff, emissiveIntensity: 0 });
}

export interface MountOpts {
  /** 装在车的哪一侧（挂点 x 的正负）：往外长的零件按它镜像 */
  side?: 1 | -1;
  /** 车尾挂点（3 / 5）：★ 放大照旧 1.85 */
  rear?: boolean;
  /** 炮塔挂点（0 / 1，T177）：底座换成坐进炮塔托架的方形转接板 */
  turret?: boolean;
  /** 车漆件的材质（T177：传车身迷彩材质，挂件和车身同一块漆、车库换涂装跟着变）；不传用通用车漆 MAT.painted */
  paint?: THREE.Material;
  /** 挂点在父件（车体 / 炮塔）里的位置：迷彩接着挂点下面那块车身的斑块铺（T177） */
  uvAt?: [number, number, number];
  /** 安装演出：这几个零件先单独画（白闪材质、可以滑进来），不进主体网格 */
  fresh?: string[];
  /** 这件参与的联动（插上联动模块）、合成的究极（插上究极配套） */
  link?: LinkId | null;
  ult?: FusionId | null;
}

const _m4 = new THREE.Matrix4();
const _rq = new THREE.Quaternion();
const _re = new THREE.Euler();
const _one = new THREE.Vector3(1, 1, 1);
const _p3 = new THREE.Vector3();

export function mountModel(geo: GeoCache, id: WeaponId, level: number, evolved: boolean, opts: MountOpts = {}): MountModel {
  const form = FORMS[id]!;
  const lv = formLevel(level, evolved);
  const grade = gradeOf(lv);
  const side = opts.side ?? 1;
  const link = opts.link ?? null;
  const ult = opts.ult ?? null;
  const keys = formKeys(id, lv, link, ult);
  const c: MountCtx = { lv, grade, side, turret: !!opts.turret, pal: PALETTE[lv >= EVO ? 'evo' : 'steel'], keys: new Set(keys), link, ult };
  const fresh = new Set(opts.fresh ?? []);
  const root = new THREE.Group();
  const pivots: Record<string, THREE.Object3D> = { root };
  for (const [name, p] of Object.entries(form.pivots)) {
    const o = new THREE.Group();
    o.position.set(...(typeof p.pos === 'function' ? p.pos(c) : p.pos));
    if (p.rot) o.rotation.set(...p.rot);
    pivots[p.parent].add(o);
    pivots[name] = o;
  }
  const mats: THREE.Material[] = [];
  let glow: { value: number } | null = null;
  let glow2: { value: THREE.Color } | null = null;
  let coil: { fill: { value: number }; glow: { value: number } } | null = null;
  let heat: THREE.MeshStandardMaterial | null = null;
  const own = new Map<MatKey, THREE.Material>();
  const matOf = (k: MatKey): THREE.Material => {
    if (k === 'paint') return opts.paint ?? MAT.painted;
    if (k === 'metal') return MAT.gunmetal;
    let m = own.get(k);
    if (m) return m;
    if (k === 'glow') m = glowMaterial((glow = { value: 0 }));
    else if (k === 'glow2') m = glow2Material((glow2 = { value: new THREE.Color(0, 0, 0) }));
    else if (k === 'coil') m = coilMaterial((coil = { fill: { value: 0 }, glow: { value: 0 } }));
    else m = heat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.42, metalness: 0.7, emissive: 0xff3a10, emissiveIntensity: 0 });
    own.set(k, m);
    mats.push(m);
    return m;
  };
  // 每个零件按枢轴分组（新零件单独一组），零件里每一块按材质再分；同一枢轴同一种材质合成一个网格
  // （几何体按「武器 + 等级 + 侧 + 联动 + 究极 + 枢轴 + 材质 + 零件表」缓存；缓存命中时搭出来的零件块只是丢掉，不上显卡）
  const uvAt = opts.uvAt ?? [0, 0, 0];
  const tag = `sub:${id}:${lv}:${side}:${link}:${ult}:${c.turret ? 't' : 'h'}:${uvAt.map((v) => v.toFixed(2)).join(',')}`;
  const groups = new Map<string, { keys: string[]; parts: PartSpec[] }>();
  const freshGroups = new Map<string, { keys: string[]; parts: PartSpec[] }>();
  for (const k of keys) {
    // 表里只管「有没有」的实例化一排（立弹 / 停着的无人机 / 舱盖）在 racks 里搭，这里跳过
    const def = form.parts[k];
    if (!def) continue;
    const pivot = def.pivot ?? 'head';
    const dm = typeof def.mat === 'function' ? def.mat(c) : def.mat ?? 'paint';
    for (const part of def.build(c)) {
      const g = fresh.has(k) ? freshGroups : groups;
      const gk = fresh.has(k) ? pivot : `${pivot}|${part.mat ?? dm}`;
      const e = g.get(gk) ?? { keys: [], parts: [] };
      if (!e.keys.includes(k)) e.keys.push(k);
      e.parts.push(part);
      g.set(gk, e);
    }
  }
  // 车漆件按米铺迷彩 UV（T177，乘上挂件放大倍数，斑块和车身一样大）
  const uvScale = MOUNT_SCALE[grade];
  for (const [g, e] of groups) {
    const [pivot, mk] = g.split('|') as [string, MatKey];
    const mg = geo.merged(`${tag}:${g}:${e.keys.join('+')}`, () => e.parts);
    if (mk === 'paint') mountUV(mg, uvScale, uvAt);
    const m = new THREE.Mesh(mg, matOf(mk));
    m.castShadow = mk === 'paint' || mk === 'metal' || mk === 'heat';
    m.userData.cast = m.castShadow;
    pivots[pivot].add(m);
  }
  const freshParts: FreshPart[] = [];
  for (const [pivot, e] of freshGroups) {
    const enter = form.parts[e.keys[0]].enter ?? { kind: 'pop' };
    const hinge = enter.hinge ?? [0, 0, 0];
    const holder = new THREE.Group();
    holder.position.set(...hinge);
    const mat = flashMaterial();
    mats.push(mat);
    const m = new THREE.Mesh(geo.merged(`${tag}:${pivot}|fresh:${e.keys.join('+')}`, () => e.parts), mat);
    m.position.set(-hinge[0], -hinge[1], -hinge[2]);
    m.userData.noArc = true;
    holder.add(m);
    pivots[pivot].add(holder);
    freshParts.push({ holder, enter, mat });
  }
  // 实例化的一排（立弹 / 停着的无人机 / 舱盖 / 信号灯）
  const racks: Record<string, THREE.InstancedMesh> = {};
  for (const r of form.racks?.(c) ?? []) {
    const rg = geo.merged(`rack:${r.geo}:${r.mat === 'paint' ? `${uvScale}:${tag}` : ''}`, r.parts);
    if (r.mat === 'paint') mountUV(rg, uvScale, uvAt);
    const im = new THREE.InstancedMesh(rg, r.mat === 'lamp' ? MAT.lamp : matOf('paint'), r.at.length);
    r.at.forEach((a, i) => {
      im.setMatrixAt(i, _m4.compose(_p3.set(...a.pos), _rq.setFromEuler(_re.set(...(a.rot ?? [0, 0, 0]))), _one));
      if (r.mat === 'lamp') im.setColorAt(i, LAMP_OFF_C);
    });
    im.count = r.count;
    im.castShadow = r.mat !== 'lamp';
    im.userData.cast = im.castShadow;
    im.frustumCulled = false;
    im.userData.rest = r.at;
    pivots[r.pivot].add(im);
    racks[r.name] = im;
  }
  const muzzles = form.muzzles(c).map((p) => muzzle(pivots[p.pivot], ...p.pos));
  const spin = form.spinner?.(c);
  const scale = lv >= EVO && opts.rear ? REAR_EVO_SCALE : MOUNT_SCALE[grade];
  root.scale.setScalar(scale);
  return { root, head: pivots.head, muzzles, spinner: spin ? pivots[spin] : null, scale, turns: form.turns, lv, keys, pivots, glow, glow2, coil, heat, racks, fresh: freshParts, mats };
}

const LAMP_OFF_C = new THREE.Color(0x1a1612);

/** 挂件车漆件铺迷彩（T177）：挂件局部坐标 × 放大倍数 + 挂点位置 = 车身（炮塔）坐标，按它铺，斑块大小和位置都接着挂点下面那块车身走 */
function mountUV(g: THREE.BufferGeometry, k: number, at: [number, number, number]): void {
  if (g.userData.paintUV) return;
  g.translate(at[0] / k, at[1] / k, at[2] / k);
  paintUV(g, 1.06, k);
  g.translate(-at[0] / k, -at[1] / k, -at[2] / k);
}

