import { ICON_SVG } from '../icons';
import { skinColor, UI_SKIN } from '../skins';
import { skinSurface } from '../skins/art';

/**
 * 画布版界面的 2D 绘制工具。
 * 只用微信小游戏真机 2D 上下文也有的接口：没有 roundRect / letterSpacing / filter / Path2D / ellipse，
 * 圆角、字间距、SVG 图标都在这里自己画。
 */
type Ctx = CanvasRenderingContext2D;

const g = globalThis as { wx?: unknown };
/** 小游戏真机的 2D 上下文不认字体列表，用系统默认无衬线（iOS 上就是苹方） */
const FAMILY = typeof g.wx === 'object' ? 'sans-serif' : "-apple-system, BlinkMacSystemFont, 'PingFang SC', 'Segoe UI', sans-serif";

export const C = {
  amber: '#f0a73c',
  steel: skinColor('#9aa3b0'),
  text: skinColor('#eceff4'),
  dim: skinColor('#9aa0a8'),
  soft: skinColor('#c9ced6'),
  gold: skinColor('#ffd98a'),
  goldHi: skinColor('#ffe0a0'),
  panel: 'rgba(10, 12, 16, 0.6)',
  line: UI_SKIN?.colors.line ?? 'rgba(255, 255, 255, 0.14)',
};

export function font(px: number, weight = 400): string {
  return `${weight} ${px}px ${FAMILY}`;
}

/** 圆角矩形路径（不填不描） */
export function rr(ctx: Ctx, x: number, y: number, w: number, h: number, r: number): void {
  const k = Math.max(0, Math.min(r, w / 2, h / 2));
  ctx.beginPath();
  ctx.moveTo(x + k, y);
  ctx.lineTo(x + w - k, y);
  ctx.arcTo(x + w, y, x + w, y + k, k);
  ctx.lineTo(x + w, y + h - k);
  ctx.arcTo(x + w, y + h, x + w - k, y + h, k);
  ctx.lineTo(x + k, y + h);
  ctx.arcTo(x, y + h, x, y + h - k, k);
  ctx.lineTo(x, y + k);
  ctx.arcTo(x, y, x + k, y, k);
  ctx.closePath();
}

/** 圆角框：fill / stroke 可以是颜色或渐变；lw = 描边宽度（像素，描在框内侧半像素处） */
export function box(ctx: Ctx, x: number, y: number, w: number, h: number, r: number, fill: string | CanvasGradient | null, stroke: string | null = null, lw = 1): void {
  if (fill) {
    rr(ctx, x, y, w, h, r);
    ctx.fillStyle = fill;
    ctx.fill();
  }
  if (stroke) {
    const o = lw / 2;
    rr(ctx, x + o, y + o, w - lw, h - lw, Math.max(0, r - o));
    ctx.strokeStyle = stroke;
    ctx.lineWidth = lw;
    ctx.stroke();
  }
}

/** 设计副本的蒙皮；薄条和数字标签仍走原画法。 */
export function skinBox(ctx: Ctx, x: number, y: number, w: number, h: number, r: number, fill: string | CanvasGradient | null, stroke: string | null = null, lw = 1): void {
  if (UI_SKIN && fill && w >= (UI_SKIN.light ? 18 : 28) && h >= (UI_SKIN.light ? 18 : 24)) {
    const pressed = typeof fill === 'string' && fill === 'rgba(255, 207, 106, 0.25)';
    skinSurface(ctx, x, y, w, h, 'panel', pressed || stroke === '#ffcf6a');
    return;
  }
  if (typeof fill === 'string') {
    if (UI_SKIN?.light && (fill === '#1a1d22' || fill.startsWith('rgba(10, 12, 16,'))) fill = UI_SKIN.colors.low;
    else fill = skinColor(fill);
  }
  const radius = UI_SKIN?.shape === 'cut' ? 0 : UI_SKIN ? Math.min(r, UI_SKIN.radius) : r;
  box(ctx, x, y, w, h, radius, fill, stroke ? skinColor(stroke) : null, lw);
}

export function vgrad(ctx: Ctx, y0: number, y1: number, a: string, b: string): CanvasGradient {
  const gr = ctx.createLinearGradient(0, y0, 0, y1);
  gr.addColorStop(0, skinColor(a));
  gr.addColorStop(1, skinColor(b));
  return gr;
}

export function hgrad(ctx: Ctx, x0: number, x1: number, a: string, b: string): CanvasGradient {
  const gr = ctx.createLinearGradient(x0, 0, x1, 0);
  gr.addColorStop(0, skinColor(a));
  gr.addColorStop(1, skinColor(b));
  return gr;
}

/** 文字阴影（CSS text-shadow 的近似）；null = 关掉 */
export function shadow(ctx: Ctx, color: string | null, blur = 3, oy = 1, ox = 0): void {
  ctx.shadowColor = color ?? 'rgba(0,0,0,0)';
  ctx.shadowBlur = color ? blur : 0;
  ctx.shadowOffsetX = color ? ox : 0;
  ctx.shadowOffsetY = color ? oy : 0;
}

/** 带字间距的文字宽度 */
export function measure(ctx: Ctx, text: string, ls = 0): number {
  if (!text) return 0;
  return ctx.measureText(text).width + (ls ? ls * (text.length - 1) : 0);
}

/**
 * 画一行字（textBaseline 统一用 middle，y 是这一行的竖直中线）；ls = 字间距（逐字画，真机没有 letterSpacing）。
 * 返回画出来的宽度
 */
export function text(ctx: Ctx, s: string, x: number, y: number, color: string, align: CanvasTextAlign = 'left', ls = 0): number {
  ctx.fillStyle = skinColor(color);
  ctx.textBaseline = 'middle';
  const w = measure(ctx, s, ls);
  if (!ls) {
    ctx.textAlign = align;
    ctx.fillText(s, x, y);
    return w;
  }
  ctx.textAlign = 'left';
  let cx = align === 'center' ? x - w / 2 : align === 'right' ? x - w : x;
  for (const ch of s) {
    ctx.fillText(ch, cx, y);
    cx += ctx.measureText(ch).width + ls;
  }
  return w;
}

/** 超出 maxW 用「…」截断 */
export function ellipsize(ctx: Ctx, s: string, maxW: number): string {
  if (ctx.measureText(s).width <= maxW) return s;
  let t = s;
  while (t.length > 1 && ctx.measureText(`${t}…`).width > maxW) t = t.slice(0, -1);
  return `${t}…`;
}

const WORD = /[A-Za-z0-9.%+\-×/~～·]/;
const NO_HEAD = '，。、；：！？）」』》】,.;:!?)%';

/** 中文按字断行（字母数字连在一起不拆，标点不放行首） */
export function wrap(ctx: Ctx, s: string, maxW: number): string[] {
  const out: string[] = [];
  // 切成不可拆的小块：一个汉字 / 一串字母数字
  const tokens: string[] = [];
  for (const ch of s) {
    const last = tokens.length - 1;
    if (last >= 0 && WORD.test(ch) && WORD.test(tokens[last][tokens[last].length - 1])) tokens[last] += ch;
    else if (last >= 0 && NO_HEAD.includes(ch)) tokens[last] += ch;
    else tokens.push(ch);
  }
  let line = '';
  for (const t of tokens) {
    if (line && ctx.measureText(line + t).width > maxW) {
      out.push(line);
      line = t.trimStart();
    } else line += t;
  }
  if (line) out.push(line);
  return out.length ? out : [''];
}

// ------------------------------------------------------------------ 图标（解析 icons.ts 的 SVG，自己画）

type Op = [string, ...number[]];
interface Shape {
  ops: Op[];
  fill: boolean;
  color?: string;
  alpha?: number;
  width?: number;
}

const cache = new Map<string, Shape[]>();

function attr(tag: string, name: string): number {
  const m = new RegExp(`\\b${name}="([^"]*)"`).exec(tag);
  return m ? Number(m[1]) : 0;
}

/** SVG 路径 → moveTo / lineTo / bezier / arc 指令（支持 M L H V C S Q T A Z 及小写相对指令、省略重复指令字母） */
function parsePath(d: string): Op[] {
  const tok = d.match(/[a-zA-Z]|[-+]?(?:\d*\.\d+|\d+\.?)(?:[eE][-+]?\d+)?/g) ?? [];
  const ops: Op[] = [];
  let i = 0;
  let cmd = '';
  let x = 0;
  let y = 0;
  let sx = 0;
  let sy = 0;
  let cx = 0;
  let cy = 0;
  const num = () => Number(tok[i++]);
  while (i < tok.length) {
    if (/[a-zA-Z]/.test(tok[i])) cmd = tok[i++];
    const rel = cmd === cmd.toLowerCase();
    const c = cmd.toUpperCase();
    const bx = rel ? x : 0;
    const by = rel ? y : 0;
    if (c === 'Z') {
      ops.push(['Z']);
      x = sx;
      y = sy;
      cmd = '';
      continue;
    }
    if (c === 'M') {
      x = bx + num();
      y = by + num();
      sx = x;
      sy = y;
      ops.push(['M', x, y]);
      cmd = rel ? 'l' : 'L';
    } else if (c === 'L') {
      x = bx + num();
      y = by + num();
      ops.push(['L', x, y]);
    } else if (c === 'H') {
      x = bx + num();
      ops.push(['L', x, y]);
    } else if (c === 'V') {
      y = by + num();
      ops.push(['L', x, y]);
    } else if (c === 'C' || c === 'S') {
      let x1: number;
      let y1: number;
      if (c === 'C') {
        x1 = bx + num();
        y1 = by + num();
      } else {
        const last = ops[ops.length - 1];
        x1 = last && last[0] === 'C' ? 2 * x - cx : x;
        y1 = last && last[0] === 'C' ? 2 * y - cy : y;
      }
      cx = bx + num();
      cy = by + num();
      x = bx + num();
      y = by + num();
      ops.push(['C', x1, y1, cx, cy, x, y]);
    } else if (c === 'Q' || c === 'T') {
      if (c === 'Q') {
        cx = bx + num();
        cy = by + num();
      } else {
        const last = ops[ops.length - 1];
        cx = last && last[0] === 'Q' ? 2 * x - cx : x;
        cy = last && last[0] === 'Q' ? 2 * y - cy : y;
      }
      x = bx + num();
      y = by + num();
      ops.push(['Q', cx, cy, x, y]);
    } else if (c === 'A') {
      const rx = num();
      const ry = num();
      num(); // x 轴旋转：图标里都是圆弧，用不到
      const large = num();
      const sweep = num();
      const x2 = bx + num();
      const y2 = by + num();
      arcOps(ops, x, y, x2, y2, (Math.abs(rx) + Math.abs(ry)) / 2, large, sweep);
      x = x2;
      y = y2;
    } else {
      i++; // 不认识的指令：跳过一个数，防无限循环
    }
  }
  return ops;
}

/** SVG 端点圆弧 → canvas arc（圆心参数化，半径不够时按规范放大） */
function arcOps(ops: Op[], x1: number, y1: number, x2: number, y2: number, r: number, large: number, sweep: number): void {
  const dx = (x1 - x2) / 2;
  const dy = (y1 - y2) / 2;
  const d2 = dx * dx + dy * dy;
  if (d2 === 0 || r === 0) {
    ops.push(['L', x2, y2]);
    return;
  }
  r = Math.max(r, Math.sqrt(d2));
  const k = (large === sweep ? -1 : 1) * Math.sqrt(Math.max(0, (r * r - d2) / d2));
  const ccx = (x1 + x2) / 2 + k * dy;
  const ccy = (y1 + y2) / 2 - k * dx;
  const a0 = Math.atan2(y1 - ccy, x1 - ccx);
  const a1 = Math.atan2(y2 - ccy, x2 - ccx);
  // SVG sweep=1 = 角度增大方向（y 向下时顺时针），对应 canvas 的 anticlockwise = false
  ops.push(['A', ccx, ccy, r, a0, a1, sweep ? 0 : 1]);
}

function shapes(id: string): Shape[] {
  let s = cache.get(id);
  if (s) return s;
  s = [];
  const svg = ICON_SVG[id] ?? ICON_SVG.main;
  for (const tag of svg.match(/<(path|rect|circle)\b[^>]*>/g) ?? []) {
    const fillColor = /\bfill="([^"]*)"/.exec(tag)?.[1];
    const strokeColor = /\bstroke="([^"]*)"/.exec(tag)?.[1];
    const fill = !!fillColor && fillColor !== 'none';
    const color = fill ? fillColor : strokeColor;
    const style = {
      fill,
      color: color && color !== 'currentColor' && color !== 'none' ? color : undefined,
      alpha: /\bopacity="/.test(tag) ? attr(tag, 'opacity') : 1,
      width: /\bstroke-width="/.test(tag) ? attr(tag, 'stroke-width') : undefined,
    };
    if (tag.startsWith('<path')) {
      const m = /\bd="([^"]*)"/.exec(tag);
      if (m) s.push({ ops: parsePath(m[1]), ...style });
    } else if (tag.startsWith('<rect')) {
      const x = attr(tag, 'x');
      const y = attr(tag, 'y');
      const w = attr(tag, 'width');
      const h = attr(tag, 'height');
      const r = Math.min(attr(tag, 'rx'), w / 2, h / 2);
      s.push({
        ...style,
        ops: r > 0
          ? [['M', x + r, y], ['L', x + w - r, y], ['T2', x + w, y, x + w, y + r, r], ['L', x + w, y + h - r], ['T2', x + w, y + h, x + w - r, y + h, r], ['L', x + r, y + h], ['T2', x, y + h, x, y + h - r, r], ['L', x, y + r], ['T2', x, y, x + r, y, r], ['Z']]
          : [['M', x, y], ['L', x + w, y], ['L', x + w, y + h], ['L', x, y + h], ['Z']],
      });
    } else {
      s.push({ ...style, ops: [['A', attr(tag, 'cx'), attr(tag, 'cy'), attr(tag, 'r'), 0, Math.PI * 2, 0], ['Z']] });
    }
  }
  cache.set(id, s);
  return s;
}

function trace(ctx: Ctx, ops: Op[]): void {
  ctx.beginPath();
  for (const o of ops) {
    switch (o[0]) {
      case 'M': ctx.moveTo(o[1], o[2]); break;
      case 'L': ctx.lineTo(o[1], o[2]); break;
      case 'C': ctx.bezierCurveTo(o[1], o[2], o[3], o[4], o[5], o[6]); break;
      case 'Q': ctx.quadraticCurveTo(o[1], o[2], o[3], o[4]); break;
      case 'A': ctx.arc(o[1], o[2], o[3], o[4], o[5], o[6] === 1); break;
      case 'T2': ctx.arcTo(o[1], o[2], o[3], o[4], o[5]); break;
      case 'Z': ctx.closePath(); break;
    }
  }
}

/** 共用图标；逐层保留剪影、蚀刻高光与透明度，不用 Path2D。 */
export function icon(ctx: Ctx, id: string, x: number, y: number, size: number, color: string, stroke = 1.7, alpha = 1): void {
  color = skinColor(color);
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(size / 24, size / 24);
  const opacity = ctx.globalAlpha * alpha;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  for (const s of shapes(id)) {
    ctx.globalAlpha = opacity * (s.alpha ?? 1);
    ctx.strokeStyle = s.color ?? color;
    ctx.fillStyle = s.color ?? color;
    ctx.lineWidth = s.width ?? stroke;
    trace(ctx, s.ops);
    if (s.fill) ctx.fill();
    else ctx.stroke();
  }
  ctx.restore();
}

/** 自由路径图标（index.html 里那几个按钮的 SVG）：d 是 24×24 视图框里的路径 */
export function pathIcon(ctx: Ctx, d: string, x: number, y: number, size: number, color: string, stroke = 2, fill = false): void {
  color = skinColor(color);
  let ops = cache.get(`d:${d}`)?.[0]?.ops;
  if (!ops) {
    ops = parsePath(d);
    cache.set(`d:${d}`, [{ ops, fill }]);
  }
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(size / 24, size / 24);
  ctx.strokeStyle = color;
  ctx.fillStyle = color;
  ctx.lineWidth = stroke;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  trace(ctx, ops);
  if (fill) ctx.fill();
  else ctx.stroke();
  ctx.restore();
}
