import { cssHex, cssRgb } from '../render/markColors';

/**
 * 精良卡（三选一里一次 +2 级的那张，rarity 'rare'）的荧光（T132，制作人「这个蓝色的特效光效不是很明显……加一层荧光，有一种暴击了升 2 级的感觉」）。
 * 两套界面共用这里的颜色和节奏：网页版 Hud 构造时写成 CSS 变量（--rare-*，styles.css「精良卡」一段），画布版 CanvasHud 直接用。
 * 金色那一套（流派 / 进化 / 合成卡）不归这里，也不许借这里的蓝。
 */

/** 荧光蓝：外圈柔光、卡面那层荧光、光带、点下去的光爆 */
export const RARE_GLOW = 0x3ca2ff;
/** 灯管芯：卡框、「精良 +2 级」字条的边、新长出来的等级刻度 */
export const RARE_EDGE = 0x8fd3ff;
/** 按下时的卡框（近白的冷蓝；普通卡按下是金边） */
export const RARE_HOT = 0xe2f5ff;
/** 卡面上 / 下（深钢蓝；改前是暗青 #20332c） */
export const RARE_FACE: readonly [number, number] = [0x1b3446, 0x122332];
/** 卡面顶边那道细线、图标底座的边、图标 */
export const RARE_LINE = 0x6fa9cf;
export const RARE_PLATE = 0x6aaee0;
export const RARE_ICON = 0xd4ecff;
/** 字条上的字 */
export const RARE_INK = 0xeef8ff;

/** 呼吸一周（秒）：慢，不像故障闪 */
export const RARE_BREATH = 2.8;
/** 外圈柔光 / 卡面荧光的亮度：最暗 / 最亮（再乘 RARE_MANY） */
export const RARE_PULSE: readonly [number, number] = [0.5, 1];
/** 同屏 1 / 2 / 3 张精良时每张的荧光乘多少（三张都是蓝卡不过曝）；几张之间呼吸错开，不一起闪 */
export const RARE_MANY: readonly number[] = [1, 0.8, 0.66];
/** 低画质：不呼吸、不扫光，荧光停在这个亮度（再乘 RARE_MANY） */
export const RARE_LOW = 0.8;
/** 光带斜扫过卡面：每 every 秒一次，一次扫 dur 秒 */
export const RARE_SWEEP = { every: 4.2, dur: 1.1 };
/** 点下精良卡的光爆（卡片顶一下、震一下、亮一下、散开）：总长（秒） */
export const RARE_BURST = 0.5;

/** 同屏 n 张精良时每张的荧光倍数 */
export const rareMany = (n: number): number => RARE_MANY[Math.max(1, Math.min(n, RARE_MANY.length)) - 1];

/** 同屏 n 张精良里的第 i 张：呼吸相位往前错 i / n 周（秒，给 CSS animation-delay 用负数） */
export const rarePhase = (i: number, n: number): number => (i / Math.max(1, n)) * RARE_BREATH;

/** 第 i 张（共 n 张）此刻的荧光亮度，t = 秒；low = 低画质（固定亮度） */
export function rarePulse(t: number, i: number, n: number, low = false): number {
  if (low) return RARE_LOW * rareMany(n);
  const s = 0.5 - 0.5 * Math.cos(((t + rarePhase(i, n)) / RARE_BREATH) * Math.PI * 2);
  return rareMany(n) * (RARE_PULSE[0] + (RARE_PULSE[1] - RARE_PULSE[0]) * s);
}

/** 光带此刻在哪（0..1 沿卡面对角线，扫完到下一次之间 = -1） */
export function rareSweep(t: number, i: number, n: number): number {
  const k = ((t + rarePhase(i, n)) % RARE_SWEEP.every) / RARE_SWEEP.dur;
  return k > 1 ? -1 : -0.15 + 1.3 * k;
}

/** 网页版的 CSS 变量：--rare-glow / --rare-edge / --rare-hot …（颜色各带一份 -rgb）、--rare-breath / --rare-sweep（秒） */
export function rareCssVars(el: HTMLElement): void {
  const colors = { glow: RARE_GLOW, edge: RARE_EDGE, hot: RARE_HOT, 'face-a': RARE_FACE[0], 'face-b': RARE_FACE[1], line: RARE_LINE, plate: RARE_PLATE, icon: RARE_ICON, ink: RARE_INK };
  for (const [k, c] of Object.entries(colors)) {
    el.style.setProperty(`--rare-${k}`, cssHex(c));
    el.style.setProperty(`--rare-${k}-rgb`, cssRgb(c));
  }
  el.style.setProperty('--rare-breath', `${RARE_BREATH}s`);
  el.style.setProperty('--rare-sweep', `${RARE_SWEEP.every}s`);
  el.style.setProperty('--rare-burst', `${RARE_BURST}s`);
  el.style.setProperty('--rare-lo', String(RARE_PULSE[0]));
  el.style.setProperty('--rare-low', String(RARE_LOW));
}
