import type { GroundKind, RoadKind } from '../render/textures';
import { cyc } from '../game/cycle';

export type SceneryId = 'rock' | 'boulder' | 'pole' | 'trap' | 'pine' | 'bush' | 'house' | 'ruin' | 'wall' | 'hulk' | 'sandbag' | 'hay' | 'hedge' | 'log' | 'crater';
export type PropKind = 'car' | 'truckProp' | 'fence' | 'crates' | 'barrels' | 'hay' | 'cart' | 'rubble' | 'log';

/** 路肩带（T009 3.4）：路边 16～27 米另开一排可破坏景物，保证默认视角看得见破坏。soft = 软件（16～20 米，坦克能碰到），hard = 硬件和高的（20.5～27 米，房屋 / 残楼 23.5～27 米） */
export interface Roadside {
  /** 每侧每 step 米抽一次，chance 概率生成 */
  step: number;
  chance: number;
  soft: Partial<Record<SceneryId, number>>;
  hard: Partial<Record<SceneryId, number>>;
}

export interface Theme {
  id: 'farmland' | 'forest' | 'village' | 'foundry' | 'airfield' | 'desert';
  name: string;
  road: RoadKind;
  ground: GroundKind;
  /** 地面着色器里的路面类型编号：0 泥路 / 1 土路 / 2 石子路 / 3 水泥板路 / 4 机场水泥板（滑行道黄线；跑道段换白线，T093） */
  roadIndex: number;
  /** 桥的样式 */
  /** 桥的样式（T019-c：钢铁厂区是钢板梁 + 桁架的钢桥） */
  bridge: 'wood' | 'stone' | 'steel';
  fog: number;
  fogNear: number;
  fogFar: number;
  sun: number;
  sunIntensity: number;
  hemiSky: number;
  hemiGround: number;
  hemiIntensity: number;
  exposure: number;
  /** 路边景物的出现权重 */
  scenery: Partial<Record<SceneryId, number>>;
  roadside: Roadside;
  props: PropKind[];
  /** 是否沿路立电线杆 */
  poles: boolean;
  /** 履带印深浅、扬尘颜色 */
  treadAlpha: number;
  dust: number;
  /** 黄昏（T122 沙漠油井）：天顶深蓝紫、地平线一道橙粉（Environment 按它染天空） */
  dusk?: boolean;
  /** 太阳摆在哪（同 Environment.SUN_AT 的写法；不给 = 默认那个正午偏后的太阳） */
  sunAt?: { x: number; y: number; z: number; tz: number };
  /** 路边景物染色（T122：灌木染成灰绿带刺的骆驼刺、车壳 / 沙袋染沙色）；r / g / b 乘在原来的颜色上 */
  scnTint?: Partial<Record<SceneryId, [number, number, number]>>;
}

