/**
 * 敌方「铁狼军团」的程序化模型。车头 / 枪口朝 +Z（敌人面朝玩家）。
 * hull 合并成一个网格；turret 单独一组（被击毁时会炸飞）；plates 是可崩落的装甲板。
 */
export interface EnemyModel {
  hull: () => PartSpec[];
  turret?: { pos: [number, number, number]; parts: () => PartSpec[] };
  plates?: (() => PartSpec[])[];
  /** 自发光小件（警示灯、电击背包） */
  glow?: { pos: [number, number, number]; r: number; color: 'red' | 'blue' }[];
  /** 被打爆后的残骸外形（摩托：骑手被甩出去，只剩车架和边斗） */
  wreck?: () => PartSpec[];
  /** 车头能量盾（精英「铁壁」）：以车体原点为圆心、朝 +Z 的一段圆柱面（半径 r、高 h、中心高 y、张角 arc 弧度），活着时显示、被击毁后熄灭 */
  shield?: { r: number; h: number; y: number; arc: number };
}

/** 精英的红金识别带（T017-9A） */
const GOLD = 0xd8a940;
const STEEL = 0x8e8a86;
const STEEL_D = 0x6e6a66;
const DARK = 0x3e3c3a;
const RED = 0xa8382c;
const TRACK = 0x2e2c2a;
const RUBBER = 0x202020;
const COAT = 0x5a5e50;
const SKIN = 0xc4a07c;

const box = (w: number, h: number, d: number) => new THREE.BoxGeometry(w, h, d);
const cyl = (rt: number, rb: number, h: number, s = 10) => new THREE.CylinderGeometry(rt, rb, h, s);

/** 履带组：外侧跑道形 + 一排负重轮露在下面 */
function tracks(x: number, len: number, h: number, w: number, wheels: number): PartSpec[] {
  const out: PartSpec[] = [];
  for (const s of [-1, 1]) {
    out.push({ geo: profileExtrude(stadiumPts(len, h), w), color: TRACK, pos: [s * x, 0, 0] });
    for (let i = 0; i < wheels; i++) {
      out.push({ geo: cyl(h * 0.36, h * 0.36, w + 0.06, 12), color: STEEL_D, pos: [s * x, h * 0.42, -len / 2 + 0.6 + (i * (len - 1.2)) / Math.max(1, wheels - 1)], rot: [0, 0, Math.PI / 2] });
    }
  }
  return out;
}

function stadiumPts(len: number, h: number): [number, number][] {
  const pts: [number, number][] = [];
  const r = h / 2;
  const half = len / 2 - r;
  for (let i = 0; i <= 6; i++) {
    const a = -Math.PI / 2 + (i / 6) * Math.PI;
    pts.push([half + Math.cos(a) * r, r + Math.sin(a) * r]);
  }
  for (let i = 0; i <= 6; i++) {
    const a = Math.PI / 2 + (i / 6) * Math.PI;
    pts.push([-half + Math.cos(a) * r, r + Math.sin(a) * r]);
  }
  return pts;
}

/** 士兵（约 2.3 高，比真人放大，俯视镜头下才看得清） */
function soldier(extra: PartSpec[] = [], kneel = false): PartSpec[] {
  const k = kneel ? 0.62 : 1;
  const p: PartSpec[] = [
    { geo: box(0.25, 0.95 * k, 0.3), color: 0x3a3a32, pos: [-0.16, 0.48 * k, 0] },
    { geo: box(0.25, 0.95 * k, 0.3), color: 0x3a3a32, pos: [0.16, 0.48 * k, kneel ? 0.25 : 0] },
    { geo: box(0.28, 0.16, 0.38), color: 0x1e1c1a, pos: [-0.16, 0.08, 0.04] },
    { geo: box(0.28, 0.16, 0.38), color: 0x1e1c1a, pos: [0.16, 0.08, kneel ? 0.29 : 0.04] },
    { geo: box(0.66, 0.78, 0.4), color: COAT, pos: [0, 0.95 * k + 0.4, 0] },
    { geo: box(0.7, 0.1, 0.44), color: 0x2a2620, pos: [0, 0.95 * k + 0.05, 0] },
    { geo: box(0.19, 0.68, 0.22), color: COAT, pos: [-0.44, 0.95 * k + 0.36, 0.1], rot: [-0.5, 0, 0.1] },
    { geo: box(0.19, 0.68, 0.22), color: COAT, pos: [0.44, 0.95 * k + 0.36, 0.12], rot: [-0.7, 0, -0.1] },
    { geo: box(0.21, 0.12, 0.24), color: RED, pos: [-0.44, 0.95 * k + 0.55, 0.05], rot: [-0.5, 0, 0.1] },
    { geo: box(0.32, 0.32, 0.32), color: SKIN, pos: [0, 0.95 * k + 0.98, 0.02] },
    { geo: new THREE.SphereGeometry(0.25, 10, 6, 0, Math.PI * 2, 0, Math.PI / 2), color: 0x3a3e34, pos: [0, 0.95 * k + 1.08, 0.02], scale: [1.15, 0.9, 1.2] },
    { geo: box(0.46, 0.5, 0.24), color: 0x4a4434, pos: [0, 0.95 * k + 0.45, -0.32] },
  ];
  return p.concat(extra);
}

/**
 * 图鉴标本照（T022-b）用的步兵造型：战场上的步兵由 Infantry 系统实例化画（会动），这里拼一个静态的「端枪站立」——
 * 步枪兵 / 反坦克兵（肩扛火箭筒）/ 电击兵（背后电池 + 线圈）/ 爆破兵（胸前红色炸药包）/ 机枪组（趴着的机枪手 + 两脚架机枪 + 副射手）
 */
export function soldierFigure(kind: string): PartSpec[] {
  const shift = (parts: PartSpec[], dx: number, dz: number, ry = 0): PartSpec[] => parts.map((q) => ({ ...q, pos: [(q.pos?.[0] ?? 0) + dx, q.pos?.[1] ?? 0, (q.pos?.[2] ?? 0) + dz], rot: q.rot ? [q.rot[0], q.rot[1] + ry, q.rot[2]] : ry ? [0, ry, 0] : undefined }));
  const rifle: PartSpec[] = [{ geo: box(0.1, 0.12, 1.1), color: 0x2a2420, pos: [0.3, 1.45, 0.45] }];
  switch (kind) {
    case 'rocketeer':
      return soldier([{ geo: cyl(0.13, 0.13, 1.5, 10), color: 0x4a5040, pos: [0.42, 1.95, 0.15], rot: [Math.PI / 2, 0, 0] }, { geo: cyl(0.18, 0.13, 0.3, 10), color: 0x3a3a32, pos: [0.42, 1.95, 0.9], rot: [Math.PI / 2, 0, 0] }]);
    case 'shock':
      return soldier([...rifle, { geo: box(0.5, 0.62, 0.3), color: 0x2a3a4a, pos: [0, 1.4, -0.4] }, { geo: cyl(0.06, 0.06, 0.7, 8), color: 0x9fd8ff, pos: [0.18, 2.0, -0.42] }]);
    case 'sapper':
      return soldier([{ geo: box(0.5, 0.42, 0.24), color: 0xa8382c, pos: [0, 1.35, 0.3] }, { geo: box(0.52, 0.06, 0.26), color: 0x2a2620, pos: [0, 1.5, 0.3] }]);
    case 'mgteam':
      return [
        ...shift(soldier([], true), -0.9, -0.4, 0.2),
        { geo: box(0.12, 0.16, 1.4), color: 0x2a2420, pos: [0.4, 0.55, 0.6] },
        { geo: box(0.3, 0.3, 0.4), color: 0x3a3630, pos: [0.4, 0.55, 0.05] },
        { geo: box(0.04, 0.5, 0.04), color: 0x2a2420, pos: [0.25, 0.25, 1.1], rot: [0, 0, 0.4] },
        { geo: box(0.04, 0.5, 0.04), color: 0x2a2420, pos: [0.55, 0.25, 1.1], rot: [0, 0, -0.4] },
        ...shift(soldier(rifle, true), 1.0, -0.6, -0.3),
      ];
    case 'locust':
      // 飞蝗（T093）：背上黄铜双罐喷气背包 + 喷口火苗，脸被面罩 / 护目镜挡住，钢盔一道橙红条
      return soldier([
        ...rifle,
        ...[-0.17, 0.17].flatMap((x): PartSpec[] => [
          { geo: cyl(0.15, 0.15, 0.78, 10), color: 0xb4893c, pos: [x, 1.55, -0.52] },
          { geo: new THREE.ConeGeometry(0.13, 0.7, 8).rotateX(Math.PI), color: 0xff9a38, pos: [x, 0.85, -0.52] },
        ]),
        { geo: box(0.34, 0.2, 0.06), color: 0x2a2826, pos: [0, 1.88, 0.2] },
        { geo: box(0.08, 0.05, 0.5), color: 0xd4552a, pos: [0, 2.3, 0.02] },
      ]);
    default:
      return soldier(rifle);
  }
}

/** 摩托（带边斗）的车架：被打爆后的残骸就是这一部分 */
function motoBike(): PartSpec[] {
  return [
    ...wheel(0.38, 0.18, RUBBER, 0x666666, [0, 0.38, 0.85]),
    ...wheel(0.38, 0.18, RUBBER, 0x666666, [0, 0.38, -0.8]),
    { geo: box(0.32, 0.4, 1.4), color: STEEL_D, pos: [0, 0.75, 0] },
    { geo: box(0.36, 0.28, 0.5), color: DARK, pos: [0, 0.95, 0.15] },
    { geo: box(0.7, 0.06, 0.06), color: DARK, pos: [0, 1.2, 0.65] },
    // 边斗
    { geo: frustum(rect(0.8, 1.4), rect(0.9, 1.5), 0.55, 0.3), color: STEEL, pos: [0.8, 0, 0] },
    ...wheel(0.3, 0.14, RUBBER, 0x666666, [1.15, 0.3, 0]),
    { geo: box(0.08, 0.08, 0.9), color: 0x2a2a2a, pos: [0.8, 1.2, 0.7] },
  ];
}

