const IRON = 0x34322f;
const IRON_L = 0x57524b;
const BOLT = 0x6e675d;
/** 撞梁锤面：磨亮的旧铁 */
const WORN = 0x7a746a;

/** 一排铆钉（小方块）沿 z 方向排开：外露钢架上用 */
function rivetsZ(count: number, z0: number, z1: number, x: number, y: number, size = 0.09): PartSpec[] {
  return Array.from({ length: count }, (_, i): PartSpec => ({ geo: box(size, size, size), color: BOLT, pos: [x, y, z0 + ((z1 - z0) * i) / Math.max(1, count - 1)] }));
}

