import { AIR_RUN, ZONE5_KEY } from '../game/cycle';
import { ACHIEVEMENTS, TIER_NAME, type MedalTier } from './achievements';
import { dayKey } from './day';
import { rollDay, swapTask, TASK_BY_ID, TASK_REWARD, taskText, type TaskStat } from './daily';
import { ACH_TICKET, BAY, BAY_BASE, CORE_ACH, CORE_UNLOCK, EMBLEM_BY_ID, EMBLEMS, ENTRY_RANK, FACTORY_BY_ID, LIVE, PAINT_BY_ID, PAINTS, POLISH, PRESET_POOL, RANK_REWARDS, rankRewardLines, SASH, STAR, starsOf, SUM_TICKET, SUM_TIERS, SUMS, sumValue, THREAT_MAX, THREAT_PRIZE, threatTier, TICKET, type BayDef, type Entry, type FactoryId } from './econ';
import type { DailyState, Profile } from './Profile';
import { rankOf } from './ranks';

/** 一局里新拿到的一枚勋章（结算页「本局解锁」那一排依次弹出，T038）：名字、金属档、中间的图标 */
export interface RunMedal {
  name: string;
  tier: MedalTier;
  icon: string;
}

type CoreKey = 'cannon' | 'rocket' | 'laser' | 'vulcan';

/**
 * 局外成长的规则（T030）：军票、军衔奖励、流派解锁、军工厂、每日任务——Game 和界面都通过它改存档（Profile.data.econ）。
 * 数据表在 meta/econ.ts / meta/daily.ts
 */
export class Career {
  constructor(private readonly profile: Profile) {}

  get e() {
    return this.profile.data.econ;
  }

  rank(): { level: number; name: string; progress: number } {
    return rankOf(this.profile.data.meta.merit);
  }

  hasCore(id: CoreKey): boolean {
    return this.e.cores.includes(id);
  }

  /** 开始界面「荒原机场」入口开了没有（T099：上校发的军衔奖励；老存档打穿过第 8 区 / T099 以前解锁过的照旧开） */
  hasArea(): boolean {
    return this.profile.data.unlocks.includes(ZONE5_KEY);
  }

  /** 开一个流派（新开的记进「新」，开始界面那张卡右上角金色「新」字，点过一次消失）；本来就有返回 false */
  unlockCore(id: CoreKey): boolean {
    if (this.hasCore(id)) return false;
    this.e.cores.push(id);
    this.e.coreNew.push(id);
    this.profile.commit();
    return true;
  }

  seeCore(id: CoreKey): void {
    const i = this.e.coreNew.indexOf(id);
    if (i < 0) return;
    this.e.coreNew.splice(i, 1);
    this.profile.commit();
  }

  /** 入口开没开（军衔到了 + 这一批已经做好） */
  open(entry: Entry): boolean {
    return LIVE.has(entry) && this.rank().level >= ENTRY_RANK[entry];
  }

  addTicket(n: number): void {
    const v = Math.max(0, Math.floor(n));
    this.e.ticket += v;
    this.e.ticketAll += v;
  }

  /**
   * 开局对账（每次打开游戏）：成就军票按已拿到的一次性补发、军衔奖励补发到现在的军衔、击败过猛犸 / 铁砧的流派补开、
   * 存档里「上次选的流派」不能是锁着的。
   * 火神（T092）：只看军衔，现在军衔 ≥ 上校就开（军衔奖励按「上次发到哪一级」补，老玩家早过了上校会漏，所以按现在军衔判）；
   * 已经开了的（T092 以前打泰坦 / 升准尉开的）留着不收；返回这次新开的火神（开始界面弹一次「新战车 · 火神流」）。
   * 荒原机场入口（T099）同理按现在军衔判（老玩家早过了上校）；开没开 Game 开局前后比一下 hasArea 自己弹提示
   */
  sync(): CoreKey[] {
    const e = this.e;
    const unlocks = this.profile.data.unlocks;
    const had = this.hasCore('vulcan');
    if (!e.achPaid) {
      for (const a of ACHIEVEMENTS) if (unlocks.includes(`ach:${a.id}`)) this.addTicket(ACH_TICKET[a.tier]);
      e.achPaid = true;
    }
    for (const [ach, core] of Object.entries(CORE_ACH)) if (unlocks.includes(`ach:${ach}`) && !this.hasCore(core)) e.cores.push(core);
    if (this.rank().level >= CORE_UNLOCK.vulcan.rank) this.unlockCore('vulcan');
    if (this.rank().level >= AIR_RUN.rank && !this.hasArea()) unlocks.push(ZONE5_KEY);
    this.initSums();
    this.grantRanks();
    this.grantStars();
    if (!this.hasCore(this.profile.data.core)) this.profile.data.core = 'cannon';
    this.profile.commit();
    return !had && this.hasCore('vulcan') ? ['vulcan'] : [];
  }

  /** 军衔奖励：上次发到的那一级之后、到现在的军衔，每级发一次；返回「本局解锁」要写的（已经有了的流派 / 槽位、还没做好的入口不写） */
  grantRanks(): string[] {
    const e = this.e;
    const now = this.rank().level;
    const out: string[] = [];
    for (let lv = e.rankPaid + 1; lv <= now; lv++) {
      const r = RANK_REWARDS[lv] ?? {};
      const had = r.core ? this.hasCore(r.core) : true;
      const hadArea = this.hasArea();
      const hadBay = new Set(e.bay);
      if (r.ticket) this.addTicket(r.ticket);
      if (r.core) this.unlockCore(r.core);
      if (r.area && !hadArea) this.profile.data.unlocks.push(ZONE5_KEY);
      for (const b of BAY) if (b.rank === lv) this.addBay(b);
      for (const p of PAINTS) if (p.gift === lv && !e.paints.includes(p.id)) e.paints.push(p.id);
      for (const m of EMBLEMS) if (m.gift === lv && !e.emblems.includes(m.id)) e.emblems.push(m.id);
      out.push(...rankRewardLines(lv, (kind, id) => (kind === 'core' ? had : kind === 'area' ? hadArea : kind === 'bay' ? hadBay.has(id) : kind === 'open' ? !LIVE.has(id as Entry) : !LIVE.has('garage'))));
    }
    // 槽位表以后调了（某个槽挪到更低的军衔）：军衔已经到了的补上
    let changed = now > e.rankPaid;
    for (const b of BAY) if (now >= b.rank && this.addBay(b)) changed = true;
    if (!changed) return out;
    e.rankPaid = Math.max(e.rankPaid, now);
    this.profile.commit();
    return out;
  }

  // ------------------------------------------------------------------ 装配车间（T033）：槽位

  /** 副武器槽：新玩家 3 个，满配 6 个。旧改装槽记录不再参与。 */
  slots(): { weapon: number } {
    const s = { ...BAY_BASE };
    for (const b of BAY) if (this.e.bay.includes(b.id)) s[b.kind] = Math.max(s[b.kind], b.n);
    return s;
  }

  hasBay(id: string): boolean {
    return this.e.bay.includes(id);
  }

  /** 下一个要装上的槽位（全开了 = null） */
  nextBay(): BayDef | null {
    return BAY.find((b) => !this.hasBay(b.id)) ?? null;
  }

  /** 装上一个槽位，记进「新」（装配车间里那一格金色「新」、开始界面入口亮小点）；本来就有返回 false */
  private addBay(b: BayDef): boolean {
    if (this.hasBay(b.id)) return false;
    this.e.bay.push(b.id);
    this.e.bayNew.push(b.id);
    return true;
  }

  /** 打开装配车间看过了：「新」清掉，返回刚才是新的那几个（这一次打开还接着标「新」） */
  seeBay(): string[] {
    const fresh = this.e.bayNew.filter((id) => BAY.some((b) => b.id === id));
    if (!fresh.length) return [];
    this.e.bayNew = [];
    this.profile.commit();
    return fresh;
  }

  /**
   * 一局结算的军票：军功 × 0.25，今天第一局 × 1.5，上限 800 × (1 + 战区等级 × 10%)（军功本身已经带了战区加成）；
   * 返回这局得了多少、是不是今天第一局
   */
  settle(merit: number, threat = 0): { gain: number; first: boolean; cap: number } {
    const d = dayKey();
    const first = d > this.e.firstDay;
    const cap = Math.round(TICKET.cap * (1 + threat * 0.1));
    const gain = Math.min(cap, Math.floor(merit * TICKET.rate * (first ? TICKET.first : 1)));
    if (first) this.e.firstDay = d;
    this.addTicket(gain);
    this.profile.commit();
    return { gain, first, cap };
  }

  // ------------------------------------------------------------------ 累计勋章（勋章墙「累计」页）

  /** 老存档第一次打开：累计从图鉴的累计击毁 / 首领、排行榜的推进 / 流派局数里取得到的取（取不到的从 0 开始），已到的档补发军票 */
  private initSums(): void {
    const e = this.e;
    if (e.seen.includes('sums')) return;
    e.seen.push('sums');
    if (!e.vet) return;
    const fk = this.profile.data.meta.foeKills;
    const s = e.sums;
    s.kills = Object.entries(fk).filter(([k]) => k.startsWith('foe:')).reduce((a, [, n]) => a + n, 0);
    s.boss = Object.entries(fk).filter(([k]) => k.startsWith('boss:')).reduce((a, [, n]) => a + n, 0);
    const lb = this.profile.data.leaderboard;
    s.dist = lb.reduce((a, r) => a + r.distance, 0);
    for (const c of ['cannon', 'rocket', 'laser', 'vulcan']) s[c] = lb.filter((r) => r.core === c).length;
    this.paySums();
  }

  /** 第几档了（0 = 还没到铁） */
  sumTier(id: string): number {
    const d = SUMS.find((x) => x.id === id);
    if (!d) return 0;
    const v = sumValue(d, this.e.sums[id] ?? 0);
    return d.tiers.filter((t) => v >= t).length;
  }

  /** 新到的档发军票，返回「累计勋章 · 推进 · 铁」这些 */
  private paySums(): RunMedal[] {
    const out: { name: string; tier: MedalTier; icon: string }[] = [];
    for (const d of SUMS) {
      const got = this.sumTier(d.id);
      for (let t = this.e.sumPaid[d.id] ?? 0; t < got; t++) {
        this.addTicket(SUM_TICKET[t]);
        out.push({ name: `${d.name} · ${TIER_NAME[SUM_TIERS[t]]}`, tier: SUM_TIERS[t], icon: d.icon });
      }
      this.e.sumPaid[d.id] = Math.max(this.e.sumPaid[d.id] ?? 0, got);
    }
    return out;
  }

  /** 一局打完记一笔累计（试玩局不算，Game 判断），返回新到的档 */
  addRun(r: { kills: number; dist: number; boss: number; fused: boolean; core: string }): RunMedal[] {
    const s = this.e.sums;
    const add = (k: string, n: number) => (s[k] = (s[k] ?? 0) + Math.max(0, Math.floor(n)));
    add('kills', r.kills);
    add('dist', r.dist);
    add('boss', r.boss);
    add('fuse', r.fused ? 1 : 0);
    add(r.core, 1);
    const out = this.paySums();
    this.profile.commit();
    return out;
  }

  // ------------------------------------------------------------------ 将星（元帅以后）

  stars(): number {
    return starsOf(this.profile.data.meta.merit);
  }

  /** 新攒到的将星：每颗 300 军票，5 / 10 / 25 / 50 颗将星勋带（10 / 50 颗还有称号）；返回「解锁」要写的、要发的称号、新拿到的勋带（结算页勋章一排，T038） */
  grantStars(): { lines: string[]; titles: string[]; medals: RunMedal[] } {
    const e = this.e;
    const n = this.stars();
    const lines: string[] = [];
    const titles: string[] = [];
    const medals: RunMedal[] = [];
    for (let i = e.starPaid + 1; i <= n; i++) {
      this.addTicket(STAR.ticket);
      lines.push(`将星 ★${i} · 军票 ${STAR.ticket}`);
      const s = SASH.find((x) => x.n === i);
      if (s) {
        lines.push(`将星勋带「${TIER_NAME[s.tier]}」`);
        medals.push({ name: `将星勋带「${TIER_NAME[s.tier]}」`, tier: s.tier, icon: 'shield' });
        if (s.title) titles.push(s.title);
      }
    }
    if (n > e.starPaid) {
      e.starPaid = n;
      this.profile.commit();
    }
    return { lines, titles, medals };
  }

  // ------------------------------------------------------------------ 战区威胁（打掉过轰天才开）

  /** 开放了没有（打掉过一次轰天）、能选到第几级 */
  get threatMax(): number {
    return this.e.threatMax;
  }

  setThreat(lv: number): void {
    if (lv < 0 || lv > Math.max(0, this.e.threatMax)) return;
    this.e.threat = lv;
    this.profile.commit();
  }

  /** 选中的那一级（还没开放 = 0） */
  get threat(): number {
    return this.e.threatMax >= 1 ? Math.min(this.e.threat, this.e.threatMax) : 0;
  }

  /**
   * 在 lv 级打掉了轰天：开下一级；这一级第一次打通发威胁勋章 + 军票 1,000 × 级数，5 级 / 10 级称号，10 级再送涂装「战区黑金」。
   * 返回「解锁」要写的、要发的称号、新拿到的威胁勋章（结算页勋章一排，T038）
   */
  clearThreat(lv: number): { lines: string[]; titles: string[]; medals: RunMedal[] } {
    const e = this.e;
    const lines: string[] = [];
    const titles: string[] = [];
    const medals: RunMedal[] = [];
    const next = Math.min(THREAT_MAX, lv + 1);
    if (next > e.threatMax) {
      e.threatMax = next;
      lines.push(lv === 0 ? '战区威胁开放（开始界面选）' : `战区威胁 ${next} 级开放`);
    }
    if (lv >= 1 && !e.threatClear.includes(lv)) {
      e.threatClear.push(lv);
      this.addTicket(THREAT_PRIZE.ticket * lv);
      lines.push(`威胁勋章 · ${lv} 级`, `军票 ${THREAT_PRIZE.ticket * lv}`);
      medals.push({ name: `威胁勋章 · ${lv} 级`, tier: threatTier(lv), icon: 'threat' });
      if (lv === 5) titles.push(THREAT_PRIZE.title5);
      if (lv === 10) {
        titles.push(THREAT_PRIZE.title10);
        if (!e.paints.includes(THREAT_PRIZE.paint10)) e.paints.push(THREAT_PRIZE.paint10);
        lines.push('涂装「战区黑金」');
      }
    }
    this.profile.commit();
    return { lines, titles, medals };
  }

  // ------------------------------------------------------------------ 佩戴（勋章墙里挑 3 枚，结算页 / 战绩卡上显示）

  /** 戴上 / 取下；满 3 枚再戴就把最早戴的那枚换下来 */
  toggleWear(id: string): void {
    const w = this.e.wear;
    const i = w.indexOf(id);
    if (i >= 0) w.splice(i, 1);
    else {
      w.push(id);
      while (w.length > 3) w.shift();
    }
    this.profile.commit();
  }

  // ------------------------------------------------------------------ 军工厂

  fac(id: FactoryId): number {
    return this.e.factory[id] ?? 0;
  }

  facOpen(id: FactoryId): boolean {
    return this.open('factory') && this.rank().level >= FACTORY_BY_ID.get(id)!.rank;
  }

  /** 下一级要多少军票；满级 = null */
  facCost(id: FactoryId): number | null {
    const f = FACTORY_BY_ID.get(id)!;
    const lv = this.fac(id);
    return lv >= f.cost.length ? null : f.cost[lv];
  }

  buyFac(id: FactoryId): boolean {
    const cost = this.facCost(id);
    if (cost === null || !this.facOpen(id) || this.e.ticket < cost) return false;
    this.e.ticket -= cost;
    this.e.factory[id] = this.fac(id) + 1;
    if (id === 'preset' && !this.e.preset) this.e.preset = PRESET_POOL[0];
    this.profile.commit();
    return true;
  }

  /** 装甲强化 / 后勤补给：耐久上限、经验各 +2% 一级 */
  get hpMul(): number {
    return 1 + 0.02 * this.fac('armor');
  }

  get xpMul(): number {
    return 1 + 0.02 * this.fac('supply');
  }

  /** 参谋部：每局免费换卡 3 + 等级 */
  get freeRerolls(): number {
    return 3 + this.fac('staff');
  }

  /** 应急预案：抢修回 50% / 65% / 80% */
  get fixPct(): number {
    return [0.5, 0.65, 0.8][this.fac('fix')] ?? 0.5;
  }

  /** 战备预置能选的副武器（1 级 2 件，每级多 2 件）、现在选的那件（没开 / 选的不在池子里 = null） */
  presetPool(): string[] {
    return PRESET_POOL.slice(0, this.fac('preset') * 2);
  }

  preset(): string | null {
    const p = this.e.preset;
    return p && this.presetPool().includes(p) ? p : null;
  }

  setPreset(id: string): void {
    if (!this.presetPool().includes(id)) return;
    this.e.preset = id;
    this.profile.commit();
  }

  // ------------------------------------------------------------------ 车库（纯外观）

  owns(kind: 'paint' | 'emblem', id: string): boolean {
    return (kind === 'paint' ? this.e.paints : this.e.emblems).includes(id);
  }

  /** 上架了（军衔到了）没有；军衔送的 / 战区的不上架 */
  onShelf(kind: 'paint' | 'emblem', id: string): boolean {
    const d = kind === 'paint' ? PAINT_BY_ID.get(id) : EMBLEM_BY_ID.get(id);
    return !!d?.shelf && this.open('garage') && this.rank().level >= d.shelf;
  }

  /** 送一套外观（T110 今日任务累计奖励；纯外观）：还没有就加进拥有的，返回 true；已经有了返回 false。调用方负责 commit */
  giveLook(kind: 'paint' | 'emblem', id: string): boolean {
    if (this.owns(kind, id) || !(kind === 'paint' ? PAINT_BY_ID : EMBLEM_BY_ID).has(id)) return false;
    (kind === 'paint' ? this.e.paints : this.e.emblems).push(id);
    return true;
  }

  /** 军票买下（买完直接装上） */
  buyLook(kind: 'paint' | 'emblem', id: string): boolean {
    const d = kind === 'paint' ? PAINT_BY_ID.get(id) : EMBLEM_BY_ID.get(id);
    if (!d?.cost || this.owns(kind, id) || !this.onShelf(kind, id) || this.e.ticket < d.cost) return false;
    this.e.ticket -= d.cost;
    (kind === 'paint' ? this.e.paints : this.e.emblems).push(id);
    this.equip(kind, id);
    return true;
  }

  equip(kind: 'paint' | 'emblem', id: string): void {
    if (!this.owns(kind, id)) return;
    if (kind === 'paint') this.e.paint = id;
    else this.e.emblem = id;
    this.profile.commit();
  }

  /** 精工（T028 4.4 ②）：这套涂装买到第几档（0..3）、下一档多少军票（满了 = null） */
  polish(paint: string): number {
    return this.e.polish[paint] ?? 0;
  }

  polishCost(paint: string): number | null {
    const lv = this.polish(paint);
    return lv >= POLISH.length ? null : POLISH[lv].cost;
  }

  buyPolish(paint: string): boolean {
    const cost = this.polishCost(paint);
    if (cost === null || !this.owns('paint', paint) || this.e.ticket < cost) return false;
    this.e.ticket -= cost;
    this.e.polish[paint] = this.polish(paint) + 1;
    this.profile.commit();
    return true;
  }

  /** 车上的样子：装备的（或 over 里指定的预览 / 试驾）涂装 + 那套的精工档 + 纹章 */
  look(over: { paint?: string; emblem?: string } = {}): { colors: [number, number, number]; pattern: 'blot' | 'stripe' | 'digital' | 'solid' | 'plain'; wear: number; sheen: number; emblem: string } {
    const p = PAINT_BY_ID.get(over.paint ?? this.e.paint) ?? PAINTS[0];
    const emblem = EMBLEM_BY_ID.has(over.emblem ?? this.e.emblem) ? (over.emblem ?? this.e.emblem) : EMBLEMS[0].id;
    return { colors: p.colors, pattern: p.pattern, wear: this.owns('paint', p.id) ? this.polish(p.id) : 0, sheen: p.sheen ?? 0, emblem };
  }

  // ------------------------------------------------------------------ 每日任务

  /** 今天的任务（没开放 = null）；换天了重抽 */
  daily(): DailyState | null {
    if (!this.open('tasks')) return null;
    const d = dayKey();
    if (!this.e.daily || d > this.e.daily.day) {
      this.e.daily = rollDay(this.profile.data.bestZone, this.e.cores, d, this.slots().weapon);
      this.profile.commit();
    }
    return this.e.daily;
  }

  /**
   * 本局进度记一笔：add = 累计类的增量，now = 本局现在的值（单局类按最大值）；完成的当场发奖（150 军功 + 军票），三项全完成再 +120。
   * 返回刚完成的（局内右侧提示）
   */
  taskTick(add: Partial<Record<TaskStat, number>>, now: Partial<Record<TaskStat, number>>): { text: string; ticket: number; icon: string }[] {
    const d = this.daily();
    if (!d) return [];
    const done: { text: string; ticket: number; icon: string }[] = [];
    for (const t of d.tasks) {
      const def = TASK_BY_ID.get(t.id);
      if (!def || t.done) continue;
      t.n = def.single ? Math.max(t.n, now[def.stat] ?? 0) : t.n + Math.max(0, add[def.stat] ?? 0);
      if (t.n < def.n) continue;
      t.n = def.n;
      t.done = true;
      const ticket = TASK_REWARD.ticket[def.tier];
      this.addTicket(ticket);
      this.profile.data.meta.merit += TASK_REWARD.merit;
      done.push({ text: taskText(def), ticket, icon: def.icon });
    }
    if (!d.bonus && d.tasks.every((t) => t.done)) {
      d.bonus = true;
      this.addTicket(TASK_REWARD.bonus);
      done.push({ text: '今日任务全部完成', ticket: TASK_REWARD.bonus, icon: 'shield' });
    }
    if (done.length || Object.values(add).some((v) => (v ?? 0) > 0)) this.profile.commit();
    return done;
  }

  /** 换一个：ad = false 用今天的免费那次；ad = true 是看完广告的那次 */
  swapTask(i: number, ad: boolean): boolean {
    const d = this.daily();
    if (!d || (ad ? d.adSwap : d.freeSwap)) return false;
    if (!swapTask(d, i, this.profile.data.bestZone, this.e.cores, this.slots().weapon)) return false;
    if (ad) d.adSwap = true;
    else d.freeSwap = true;
    this.profile.commit();
    return true;
  }
}
