import type { ConfirmBox } from './missionUi';

type FullscreenRoot = HTMLElement & { webkitRequestFullscreen?: () => Promise<void> | void };
type FullscreenDocument = Document & {
  webkitFullscreenElement?: Element | null;
  webkitFullscreenEnabled?: boolean;
  webkitExitFullscreen?: () => Promise<void> | void;
};
interface InstallPrompt extends Event {
  prompt(): Promise<void>;
  userChoice: Promise<{ outcome: 'accepted' | 'dismissed' }>;
}

/** 网页显示方式；只响应按钮，不改作战状态或画质。两套菜单共用。 */
class BrowserDisplay {
  onGuide: ((box: ConfirmBox) => void) | null = null;
  private readonly events = new AbortController();
  private readonly listeners = new Set<() => void>();
  private readonly standalone = matchMedia('(display-mode: standalone)');
  private readonly fullscreen = matchMedia('(display-mode: fullscreen)');
  private readonly launchedAsApp = this.inApp;
  private installPrompt: InstallPrompt | null = null;
  private installed = false;
  private busy = false;
  private resizeFrame = 0;

  constructor() {
    const { signal } = this.events;
    document.addEventListener('fullscreenchange', this.refresh, { signal });
    document.addEventListener('webkitfullscreenchange', this.refresh, { signal });
    this.standalone.addEventListener('change', this.refresh, { signal });
    this.fullscreen.addEventListener('change', this.refresh, { signal });
    window.visualViewport?.addEventListener('resize', this.refresh, { signal });
    window.addEventListener('pageshow', this.refresh, { signal });
    window.addEventListener('beforeinstallprompt', event => {
      event.preventDefault();
      this.installPrompt = event as InstallPrompt;
      this.emit();
    }, { signal });
    window.addEventListener('appinstalled', () => {
      this.installed = true;
      this.installPrompt = null;
      this.emit();
    }, { signal });
  }

  private get element(): Element | null {
    const doc = document as FullscreenDocument;
    return doc.fullscreenElement ?? doc.webkitFullscreenElement ?? null;
  }

  private get inApp(): boolean {
    return !!(navigator as Navigator & { standalone?: boolean }).standalone
      || this.standalone.matches || (this.fullscreen.matches && !this.element);
  }

  private get canRequest(): boolean {
    const root = document.documentElement as FullscreenRoot;
    const doc = document as FullscreenDocument;
    return typeof root.requestFullscreen === 'function' ? doc.fullscreenEnabled !== false
      : typeof root.webkitRequestFullscreen === 'function' && doc.webkitFullscreenEnabled !== false;
  }

  get state(): { label: string; active: boolean; disabled: boolean; install: boolean } {
    const nativeFull = this.fullscreen.matches && !this.element;
    const app = this.launchedAsApp || this.inApp;
    return {
      label: this.element ? '退出全屏' : nativeFull ? '已全屏' : app && !this.canRequest ? '已独立打开' : '全屏',
      active: !!this.element || nativeFull,
      disabled: this.busy || nativeFull || (app && !this.canRequest),
      install: !this.installed && !app,
    };
  }

  subscribe(update: () => void): void {
    this.listeners.add(update);
    update();
  }

  private emit(): void {
    this.listeners.forEach(update => update());
  }

  private readonly refresh = () => {
    this.emit();
    // 系统栏变化后再读安全区；尺寸没变时，画布菜单也要重排。
    if (this.resizeFrame) return;
    this.resizeFrame = requestAnimationFrame(() => {
      this.resizeFrame = 0;
      window.dispatchEvent(new Event('resize'));
    });
  };

  async toggle(): Promise<void> {
    if (this.state.disabled) return;
    const exiting = !!this.element;
    if (!exiting && !this.canRequest) return this.guide('fullscreen');
    this.busy = true;
    this.emit();
    try {
      const doc = document as FullscreenDocument;
      const root = document.documentElement as FullscreenRoot;
      // 必须在这次点按里直接请求，整页进入，菜单和工具键一起保留。
      if (exiting) {
        if (doc.exitFullscreen) await doc.exitFullscreen();
        else await doc.webkitExitFullscreen?.();
      } else if (root.requestFullscreen) {
        await root.requestFullscreen({ navigationUI: 'hide' });
      } else {
        await root.webkitRequestFullscreen?.();
      }
    } catch {
      this.guide(exiting ? 'exit' : 'fullscreen');
    } finally {
      this.busy = false;
      this.refresh();
    }
  }

  async install(): Promise<void> {
    if (this.busy) return;
    const prompt = this.installPrompt;
    if (!prompt) return this.guide('install');
    this.installPrompt = null;
    this.busy = true;
    this.emit();
    try {
      await prompt.prompt();
      if ((await prompt.userChoice).outcome === 'accepted') this.installed = true;
    } catch {
      this.guide('install');
    } finally {
      this.busy = false;
      this.refresh();
    }
  }

  private guide(reason: 'install' | 'fullscreen' | 'exit'): void {
    const apple = /iPhone|iPad|iPod/.test(navigator.userAgent)
      || (/Macintosh/.test(navigator.userAgent) && navigator.maxTouchPoints > 1);
    const embedded = /Lark|Feishu|MicroMessenger|QQ\//i.test(navigator.userAgent);
    const mobile = apple || /Android/i.test(navigator.userAgent);
    const lines = reason === 'exit'
      ? ['可用系统返回手势退出全屏。', '电脑也可按退出键离开全屏。']
      : apple
        ? [embedded ? '在外部浏览器中打开，点分享。' : '用苹果自带浏览器打开，点分享。',
          '添加到主屏幕，开启网页应用。', '从桌面图标进入，再横拿手机。']
        : mobile
          ? [embedded ? '先从右上角菜单在浏览器中打开。'
            : reason === 'fullscreen' ? '此浏览器未允许网页全屏。' : '打开浏览器菜单，选择安装应用。',
          '也可选择「添加到主屏幕」。', '从桌面图标打开，横屏查看。']
          : reason === 'fullscreen'
            ? ['此浏览器未允许网页全屏。', '可从浏览器菜单开启全屏。', '或换用支持全屏的浏览器。']
            : ['在浏览器菜单中安装此游戏。', '安装后从桌面或应用列表打开。', '也可返回游戏，点「全屏」。'];
    this.onGuide?.({
      title: reason === 'install' ? '添加到桌面' : reason === 'exit' ? '退出全屏' : '全屏查看',
      lines, cancel: '知道了',
    });
  }

  dispose(): void {
    this.events.abort();
    cancelAnimationFrame(this.resizeFrame);
    this.listeners.clear();
    this.onGuide = null;
  }
}

let display: BrowserDisplay | null = null;
export function browserDisplay(): BrowserDisplay | null {
  if (__WX__) return null;
  return display ??= new BrowserDisplay();
}

export function disposeBrowserDisplay(): void {
  display?.dispose();
  display = null;
}
