import * as THREE from 'three';
import type { GeoCache } from '../assets/GeoCache';
import { MAT } from '../assets/materials';
import { bombGeo, bomberGeo, droneGeo, rocketGeo, siegeShellGeo } from '../assets/models/weapons';
import type { Enemy } from '../entities/Enemy';
import type { Fx } from '../render/Fx';
import { SubMark, type SubFx } from '../render/SubFx';
import { MARK_SELF, WARN_ENEMY } from '../render/markColors';
import type { Hazards } from './Hazards';
import { dmgSrc, withPlayer } from './DamageLog';
import type { DmgType, LinkId } from '../weapons/defs';
import type { AttackOpts } from '../weapons/attacks';
import { rng } from '../game/rng';

export type ProjKind = 'rocket' | 'shell' | 'drone' | 'minidrone' | 'bomb' | 'siege';

/**
 * 敌方抛射物（背景炮击 / 自行火炮 / 首领炮击）落地：离落点「半径 + ENEMY_SPLASH」米内的玩家挨打（Game.onProjectileImpact）。
 * 红圈按这个真实范围画（T017-1A；原来只画「半径」，圈外 2.4 米也会挨打，自行火炮打中的 35% 是在圈外挨的）
 */
export const ENEMY_SPLASH = 2.4;

export interface ImpactOpts extends AttackOpts {
  /** 发射时属于哪组副武器联动；其他同型挂件不复制这次效果。 */
  subLink?: LinkId;
  /** 伤害类型（默认爆炸） */
  type?: DmgType;
  /** 穿甲：对重甲不打折 */
  ap?: boolean;
  /** 击退力度 */
  knock?: number;
  /** 显示伤害数字 */
  show?: boolean;
  /** 不画落点预警圈（背景炮击的近失弹） */
  noMarker?: boolean;
  /** 把步兵炸飞 */
  fling?: boolean;
  /** 落点留下火焰区（每秒伤害） */
  napalm?: number;
  /** 子母弹：分裂出几枚小爆炸 */
  bomblets?: number;
  /** 子母弹怎么撒（T237 重磅炮弹）：落点圈半径、每枚半径、每枚伤害，都是主爆炸的倍数；不写 = 0.9 / 0.45 / 0.4 */
  spread?: { ring: number; size: number; dmg: number };
  /**
   * 炸出的实体弹坑档位（T016-1）：0 无坑只留焦痕 / 1 小 / 2 中；不写按半径兜底（< 3.5 米无坑，否则小坑）。
   * 小：主炮所有爆炸、迫击炮、无人机、空袭、集束火箭 / 喀秋莎、油桶；中：重型穿甲火箭 / 温压弹、自爆卡车、敌方重炮、炼狱弹着点；
   * 无：机枪、步枪、普通火箭、子母弹、激光、穿甲贯穿的小爆炸、黑潮俯冲、天火坍缩
   */
  pit?: 0 | 1 | 2;
  /** 被炮弹直接砸中的目标（T016 D2，榴弹线）：吃 伤害 × hitMul、不按距离打折；子母弹围着它落 */
  hit?: Enemy;
  hitMul?: number;
  /** 实际碰到的表面，只管地面效果；与 hit / hitMul 的伤害倍率无关。 */
  contact?: 'vehicle' | 'ground';
  /** 终极伤害（来源 'ult'）：不暴击、计入 dmgUlt，视觉爆炸有每秒上限 ULT_FX_RATE（Game.explode） */
  ult?: boolean;
  /** 从天上落下的爆炸（迫击炮 / 空袭 / 无人机 / 火箭落地）：景物按「爆·顶」处理（屋顶开天窗、树冠削顶）；T024 起不再管掀不掀车（只有「火葬」卡车照旧按它掀飞） */
  top?: boolean;
  /** 掀飞档（T024）：究极、殉爆和首领冲击波；T154 增加火控暴击的榴弹，未暴击仍是普通档。 */
  heave?: boolean;
  /** 爆炸画面放大（T018-1：迫击炮 / 空袭随等级 1 → 1.3），只管火球大小，不改伤害半径 */
  fxScale?: number;
  /** 空爆霰弹（T018-link「迫击炮 × 机枪」）：在目标头上 6 米空爆，洒下 n 道霰弹、每道 dmg（small） */
  airburst?: { n: number; dmg: number };
  /** 重武器（核弹火球、双联重炮）：能劈开巨石 */
  heavy?: boolean;
  /** 巨炮「轰天」的巨弹 / 远方炮击（T019-b）：落地大爆炸 */
  siege?: boolean;
  /** 大炮弹（汇总第 62 条迫击炮进化的重磅炮弹 / 第 65 条巨炮巨弹）：弹体放大这么多倍、拖尾加粗；玩家的落地再加一套大爆炸演出（Game.bigShellFx） */
  big?: number;
  /** 空爆高度（离地米数）：伤害仍按高度分层；空中载具接住冲击时不挖地面，空地上的空爆可留坑。 */
  air?: number;
  /** 火球画在这一点（T048：砸在首领本体上的抛射物——火球在砸到的那一点 / 那个高度，伤害、景物照旧按原来会落到的地面点算）；不写 = 爆心，落在首领外形里就抬到它的顶面 */
  fx?: { x: number; y: number; z: number };
  /** 副武器的形态等级（T143，1～5、★ = 6）：只管看——拖尾、落地的尘环 / 焦痕发光边 / 光斑按它分档，伤害不看它 */
  look?: number;
  /** 爆炸烟团数的倍数（T143，只管看；不写 = 1） */
  smoke?: number;
}

export interface Proj {
  player?: number;
  kind: ProjKind;
  /** 伤害来源（战报） */
  src: string;
  alive: boolean;
  obj: THREE.Mesh;
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  vz: number;
  t: number;
  life: number;
  target: Enemy | null;
  tx: number;
  tz: number;
  /** 抛物线：起点与飞行时间；ty = 落点离地多高（打天上的高抛弹落在目标那个高度，T105 喀秋莎；平时 0） */
  sx: number;
  sy: number;
  sz: number;
  ty: number;
  flight: number;
  apex: number;
  damage: number;
  radius: number;
  speed: number;
  /** 追踪火箭：转向力度 / 极速 / 起飞后按初速直飞的秒数（目标越近拐得越急，见 ROCKET_TURN） */
  steer: number;
  vmax: number;
  boost: number;
  opts: ImpactOpts;
  enemy: boolean;
  /** 走抛物线（迫击炮、火箭雨、敌方炮击） */
  arc: boolean;
  /** 武装无人机（T018-link「机枪 × 无人机」）：扎下去之前先在目标头上悬停 dur 秒扫射（每秒 rate 发，交给 onStrafe）；t = 已经扫了几秒，shot = 下一发倒计时 */
  strafe?: { dur: number; rate: number; t: number; shot: number } | null;
}

interface Bomber {
  player?: number;
  obj: THREE.Mesh;
  x: number;
  z: number;
  y: number;
  speed: number;
  drops: number[];
  dropped: number;
  damage: number;
  radius: number;
  napalm: number;
  src: string;
  /** 投下的炸弹额外带的选项 */
  opts: ImpactOpts;
  /** ★ 地毯轰炸贴地跟着走的掠影（SubFx 留痕下标，-1 = 没有） */
  shadow: number;
}

/**
 * 追踪火箭的飞法：far 米外先按初速散开 boost 秒、再以 steer 力度拐向目标（极速 vmax）；
 * 目标近于 far 米时逐渐换成 near 这一套（起飞就拐、拐得急、飞得慢），near.at 米内全按近距离飞，贴近的目标也扎得下去
 */
const ROCKET_TURN = { far: 16, steer: 6, vmax: 58, boost: 0.25, near: { at: 6, steer: 18, vmax: 28, boost: 0.15 } };

/**
 * 巨炮巨弹的飞法（D5 C6「这一炮直接对着天空打出去，我们都看不见炮弹」）：出膛 up 秒顺着 pitch 度的炮口以 speed 米/秒冲上天（带粗火光拖尾）就出画；
 * 飞行中不画；落地前 drop 秒从落点头顶 h 米几乎垂直砸下来（从巨炮那一侧斜 slant）。飞行时间 / 落点 / 红圈都不变
 */
export const SIEGE_ARC = { up: 0.25, pitch: 55, speed: 260, drop: 0.4, h: 70, slant: 0.18 };

/** 会拐弯 / 抛物线 / 自己找目标的飞行物：火箭、迫击炮弹、无人机、航弹、轰炸机 */
export class Projectiles {
  networkObjects() { return this.list.filter(p => p.alive); }
  networkBombers() { return this.bombers; }
  networkModel(kind: ProjKind | 'bomber'): THREE.Mesh {
    const mesh = new THREE.Mesh(kind === 'bomber' ? this.bomberGeometry : this.geos[kind], MAT.painted);
    mesh.castShadow = true;
    this.scene.add(mesh);
    return mesh;
  }
  onImpact: ((p: Proj) => void) | null = null;
  /** (x, z) 处首领本体的顶面离地多高（T048，Game 接上；外面 = 0）：玩家的抛射物落进去就在那儿炸 */
  topAt: ((x: number, z: number) => number) | null = null;
  /** 武装无人机悬停扫射的一发（Game 结算伤害 + 画曳光） */
  onStrafe: ((p: Proj) => void) | null = null;
  /** 我方无人机爬升完开始俯冲（T143：Game 放俯冲尖啸、5 级起目标脚下小方框） */
  onDive: ((p: Proj) => void) | null = null;
  /** 副武器分级特效（T143，Game 接上）：★ 地毯轰炸的掠影走它的留痕池 */
  sub: SubFx | null = null;
  /** 画质档（Game 每帧写，T247）：低档拖烟减半 */
  tier: 'high' | 'medium' | 'low' = 'high';
  private readonly list: Proj[] = [];
  private readonly bombers: Bomber[] = [];
  private readonly geos: Record<ProjKind, THREE.BufferGeometry>;
  private readonly bomberGeometry: THREE.BufferGeometry;
  /** 3 级起机身带白识别带的那一款（T143） */
  private readonly bomberBand: THREE.BufferGeometry;
  private readonly tmp = new THREE.Vector3();

  constructor(
    private readonly scene: THREE.Scene,
    geo: GeoCache,
    private readonly fx: Fx,
    private readonly hazards: Hazards,
  ) {
    this.geos = { rocket: rocketGeo(geo), shell: bombGeo(geo), bomb: bombGeo(geo), drone: droneGeo(geo, false), minidrone: droneGeo(geo, true), siege: siegeShellGeo(geo) };
    this.bomberGeometry = bomberGeo(geo);
    this.bomberBand = bomberGeo(geo, true);
  }

  /** 追踪火箭：初速随机向上/向外，之后拐弯追 target */
  rocket(x: number, y: number, z: number, vx: number, vy: number, vz: number, target: Enemy | null, damage: number, radius: number, opts: ImpactOpts = {}, big = false, tx?: number, tz?: number): void {
    const p = this.take('rocket', x, y, z, damage, radius);
    p.opts = { ...opts, kind: 'blast' };
    p.obj.scale.setScalar(big ? 1.8 : 1);
    p.vx = vx; p.vy = vy; p.vz = vz;
    p.target = target;
    p.tx = target ? target.group.position.x : tx ?? x + vx;
    p.tz = target ? target.group.position.z : tz ?? z - 40;
    p.life = 3.2;
    p.speed = 18;
    p.arc = false;
    const T = ROCKET_TURN;
    const n = THREE.MathUtils.clamp((T.far - Math.hypot(p.tx - x, p.tz - z)) / (T.far - T.near.at), 0, 1);
    p.steer = T.steer + (T.near.steer - T.steer) * n;
    p.vmax = T.vmax + (T.near.vmax - T.vmax) * n;
    p.boost = T.boost + (T.near.boost - T.boost) * n;
  }

  /** 抛射弹：从起点画抛物线落到 (tx, tz)，落点先出预警圈 */
  shell(x: number, y: number, z: number, tx: number, tz: number, flight: number, apex: number, damage: number, radius: number, opts: ImpactOpts = {}, enemy = false, kind: ProjKind = 'shell'): Proj {
    const p = this.take(kind, x, y, z, damage, radius);
    p.sx = x; p.sy = y; p.sz = z;
    p.tx = tx; p.tz = tz;
    p.flight = flight;
    p.apex = apex;
    // 池里的弹体会复用：每次按这一发重新定大小（大炮弹 × big）；巨炮巨弹是自己的模型，原大
    p.obj.scale.setScalar(kind === 'siege' ? 1 : (kind === 'rocket' ? 1.3 : 0.9) * (opts.big ?? 1));
    p.life = flight + 0.5;
    p.opts = { ...opts, kind: 'blast' };
    p.enemy = enemy;
    p.arc = true;
    // 巨炮巨弹的红圈中心带一团越来越大、越来越黑的影子（D5 C7：天上有东西砸下来）
    if (!opts.noMarker) this.hazards.marker(tx, tz, enemy ? radius + ENEMY_SPLASH : radius, flight, enemy ? 'enemy' : 'self', undefined, 0, kind === 'siege');
    return p;
  }

  /**
   * 自动无人机：先爬升，再飞向目标俯冲。look = 形态等级（T143，只管看）：2 级起机尾闪绿灯（原来红）、★ 飞出去的改回正常大小
   * （mini 照旧决定速度，蜂群 0.7 倍小号机的外形放大回 1 倍，原来「进化反而变小」）
   */
  drone(x: number, y: number, z: number, target: Enemy | null, damage: number, radius: number, mini: boolean, strafe: { dur: number; rate: number } | null = null, look = 0, subLink?: LinkId): void {
    const p = this.take(mini ? 'minidrone' : 'drone', x, y, z, damage, radius);
    p.opts = { look, kind: 'blast', summon: true, subLink };
    p.obj.scale.setScalar(mini && look >= 6 ? 1 / 0.7 : 1);
    p.strafe = strafe ? { ...strafe, t: 0, shot: 0 } : null;
    const a = rng.weapon() * Math.PI * 2;
    p.vx = Math.cos(a) * 3;
    p.vz = Math.sin(a) * 3 - 4;
    p.vy = 9;
    p.target = target;
    p.tx = target ? target.group.position.x : x;
    p.tz = target ? target.group.position.z : z - 40;
    p.speed = mini ? 34 : 26;
    p.life = strafe ? 8.5 : 6;
    p.arc = false;
  }

  /** 呼叫一架轰炸机从左到右飞过 z 线，在 [x0, x1] 之间均匀投弹；opts 会带到每枚炸弹上 */
  bomber(z: number, x0: number, x1: number, bombs: number, damage: number, radius: number, napalm: number, delay = 0, offsetZ = 0, opts: ImpactOpts = {}): void {
    // T143：3 级起机身一道白识别带；★ 贴地跟一张掠影（不投真影子：阴影范围装不下飞机，手机上全场阴影会变糊）
    const look = opts.look ?? 0;
    const obj = new THREE.Mesh(look >= 3 ? this.bomberBand : this.bomberGeometry, MAT.painted);
    obj.castShadow = look < 6;
    obj.scale.setScalar(1.4);
    this.scene.add(obj);
    const drops: number[] = [];
    for (let i = 0; i < bombs; i++) drops.push(x0 + ((x1 - x0) * (i + 0.5)) / bombs);
    const x = -110 - delay * 60;
    const shadow = look >= 6 && this.sub ? this.sub.mark(SubMark.Shadow, x, z + offsetZ, 14, 21, 0, 4.5 + delay, 0, 0, 0.5, true) : -1;
    // 投弹点要提前量：炸弹会继续往前飘一段
    this.bombers.push({ obj, x, z: z + offsetZ, y: 30, speed: 60, drops: drops.map((d) => d - 19), dropped: 0, damage, radius, napalm, src: dmgSrc.cur, player: dmgSrc.player, opts: { ...opts, kind: 'blast', summon: true, airstrike: true }, shadow });
  }

  update(delta: number): void {
    for (const p of this.list) {
      if (!p.alive) continue;
      p.t += delta;
      p.life -= delta;
      if (p.arc) this.stepShell(p);
      else switch (p.kind) {
        case 'rocket': this.stepRocket(p, delta); break;
        case 'shell': this.stepShell(p); break;
        case 'drone':
        case 'minidrone': this.stepDrone(p, delta); break;
        case 'bomb': this.stepBomb(p, delta); break;
        case 'siege': this.stepShell(p); break;
      }
      // 落进首领本体的外形里（T048：低于那一处的顶面）就在那儿炸——火箭 / 迫击炮 / 无人机 / 空袭砸在巨炮的炮室顶、台面、外墙上，不再穿进去落到地面才炸
      if (p.alive && !p.enemy && this.topAt && p.y < this.topAt(p.x, p.z)) this.impact(p);
      if (p.alive && p.life <= 0) this.impact(p);
      if (!p.alive) continue;
      p.obj.position.set(p.x, p.y, p.z);
      // 机头朝速度方向（模型机头 -Z）
      this.tmp.set(p.x - p.vx, p.y - p.vy, p.z - p.vz);
      p.obj.lookAt(this.tmp);
    }

    for (let i = this.bombers.length - 1; i >= 0; i--) {
      const b = this.bombers[i];
      b.x += b.speed * delta;
      b.obj.position.set(b.x, b.y, b.z);
      b.obj.rotation.set(0, 0, Math.sin(b.x * 0.02) * 0.05);
      if (b.shadow >= 0) this.sub?.moveMark(b.shadow, b.x, b.z);
      while (b.dropped < b.drops.length && b.x >= b.drops[b.dropped]) {
        const p = this.take('bomb', b.x, b.y - 1, b.z, b.damage, b.radius);
        p.src = b.src;
        p.player = b.player;
        p.vx = b.speed * 0.25;
        p.vy = -2;
        p.vz = 0;
        p.life = 3;
        p.arc = false;
        p.opts = { fling: true, napalm: b.napalm, ...b.opts };
        // ★ 投弹时弹舱口一闪（T143）
        if ((b.opts.look ?? 0) >= 6) this.fx.glow.emit({ x: b.x, y: b.y - 1.2, z: b.z, life: 0.08, size: 2.2, size1: 0.8, color: 0xfff0c0, color1: 0xffa040, frame: 0 });
        b.dropped++;
      }
      if (b.x > 140) {
        b.obj.removeFromParent();
        this.bombers.splice(i, 1);
      }
    }
  }

  clear(): void {
    for (const p of this.list) {
      p.alive = false;
      p.obj.visible = false;
    }
    for (const b of this.bombers) b.obj.removeFromParent();
    this.bombers.length = 0;
  }

  get activeCount(): number {
    let n = this.bombers.length;
    for (const p of this.list) if (p.alive) n++;
    return n;
  }

  private stepRocket(p: Proj, delta: number): void {
    if (p.target?.alive) {
      p.tx = p.target.group.position.x;
      p.tz = p.target.group.position.z;
    }
    // 目标在天上（T091）：追到它的高度，在空中炸
    const ty = p.target?.alive ? (p.target.flying ? p.target.group.position.y : 1.2) : 0;
    p.speed = Math.min(p.vmax, p.speed + delta * 70);
    const dx = p.tx - p.x;
    const dy = ty - p.y;
    const dz = p.tz - p.z;
    const len = Math.hypot(dx, dy, dz) || 1;
    // 起飞头 boost 秒按初速飞，之后转向目标
    const steer = p.t < p.boost ? 0.6 : p.steer;
    const k = Math.min(1, steer * delta);
    const cur = Math.hypot(p.vx, p.vy, p.vz) || 1;
    p.vx += ((dx / len) * cur - p.vx) * k;
    p.vy += ((dy / len) * cur - p.vy) * k;
    p.vz += ((dz / len) * cur - p.vz) * k;
    const sp = Math.hypot(p.vx, p.vy, p.vz) || 1;
    p.vx = (p.vx / sp) * p.speed;
    p.vy = (p.vy / sp) * p.speed;
    p.vz = (p.vz / sp) * p.speed;
    p.x += p.vx * delta;
    p.y += p.vy * delta;
    p.z += p.vz * delta;
    const [ex, ey, ez] = this.tail(p, 0.9);
    if (this.tier !== 'low' || Math.random() < 0.6) this.fx.smokeTrail(ex, ey, ez);
    if (len < (p.target?.flying ? 2 : 1.4) || p.y < 0.3) this.impact(p);
  }

  /** 弹尾那一点：从弹体中心顺着飞行方向往后退 d 米（× 弹体缩放） */
  private tail(p: Proj, d: number): [number, number, number] {
    const l = Math.hypot(p.vx, p.vy, p.vz);
    const k = l > 1e-6 ? (d * p.obj.scale.x) / l : 0;
    return [p.x - p.vx * k, p.y - p.vy * k, p.z - p.vz * k];
  }

  private stepShell(p: Proj): void {
    if (p.kind === 'siege') {
      this.stepSiege(p);
      return;
    }
    const t = Math.min(1, p.t / p.flight);
    const nx = p.sx + (p.tx - p.sx) * t;
    const nz = p.sz + (p.tz - p.sz) * t;
    const ny = p.sy * (1 - t) + p.ty * t + p.apex * 4 * t * (1 - t);
    p.vx = nx - p.x;
    p.vy = ny - p.y;
    p.vz = nz - p.z;
    p.x = nx;
    p.y = ny;
    p.z = nz;
    const big = p.opts.big;
    // 尾迹画在弹尾（T247）：弹体模型在前，发光和烟跟在后面，不罩住弹头
    const [ex, ey, ez] = this.tail(p, p.kind === 'rocket' ? 0.9 : 0.5);
    const low = this.tier === 'low';
    if (big) {
      // 大炮弹：火光拖尾 + 每帧一团翻滚的烟；敌方的拖红尾
      if (p.enemy) this.fx.trail(ex, ey, ez, WARN_ENEMY, 0.6 * big, WARN_ENEMY);
      else this.fx.trail(ex, ey, ez, MARK_SELF, 0.5 * big);
      if (!low || Math.random() < 0.5) this.fx.smokeTrail(ex, ey, ez, p.kind === 'rocket');
    }
    // 敌方炮弹 / 火箭：红色拖尾，重炮（自行火炮 / 首领炮击，半径 ≥ 4）更粗（T017-1A：看得出从哪打来的）；火箭另拖烟
    else if (p.enemy) {
      this.fx.trail(ex, ey, ez, WARN_ENEMY, p.radius >= 4 ? 0.9 : 0.5, WARN_ENEMY);
      if (p.kind === 'rocket' ? !low || Math.random() < 0.5 : this.tier === 'high' && Math.random() < 0.4) this.fx.smokeTrail(ex, ey, ez, p.kind === 'rocket');
    }
    // 副武器炮弹（T143）：每帧拖烟（原来一半帧）；燃烧炮击的弹拖一道橙色火尾
    else if (p.opts.look) {
      if (!low || Math.random() < 0.5) this.fx.smokeTrail(ex, ey, ez, p.kind === 'rocket');
      if (p.opts.napalm) this.fx.trail(ex, ey, ez, 0xffb050, 0.9);
    } else if (p.kind === 'rocket' || Math.random() < 0.5) this.fx.smokeTrail(ex, ey, ez, p.kind === 'rocket');
    if (t >= 1) this.impact(p);
  }

  /** 巨炮巨弹（SIEGE_ARC）：出膛冲上天 → 看不见 → 落地前从头顶垂直砸下来 */
  private stepSiege(p: Proj): void {
    const S = SIEGE_ARC;
    let hx = p.tx - p.sx;
    let hz = p.tz - p.sz;
    const hl = Math.hypot(hx, hz) || 1;
    hx /= hl;
    hz /= hl;
    const left = p.flight - p.t;
    let nx: number;
    let ny: number;
    let nz: number;
    if (p.t < S.up) {
      const a = THREE.MathUtils.degToRad(S.pitch);
      const d = S.speed * p.t;
      nx = p.sx + hx * Math.cos(a) * d;
      ny = p.sy + Math.sin(a) * d;
      nz = p.sz + hz * Math.cos(a) * d;
      p.obj.visible = true;
    } else if (left > S.drop) {
      // 飞行中：不画，也不拖尾
      p.obj.visible = false;
      nx = p.tx;
      ny = S.h * 4;
      nz = p.tz;
    } else {
      const k = Math.max(0, left / S.drop);
      ny = S.h * k;
      nx = p.tx - hx * ny * S.slant;
      nz = p.tz - hz * ny * S.slant;
      if (!p.obj.visible) {
        // 刚从天上掉进画面：上一帧的位置放在它正上方，弹头朝下
        p.obj.visible = true;
        p.x = nx - hx * 3 * S.slant;
        p.y = ny + 3;
        p.z = nz - hz * 3 * S.slant;
      }
    }
    p.vx = nx - p.x;
    p.vy = ny - p.y;
    p.vz = nz - p.z;
    p.x = nx;
    p.y = ny;
    p.z = nz;
    if (p.obj.visible) {
      // 粗火光拖尾 + 一团翻滚的烟
      this.fx.trail(p.x, p.y, p.z, 0xffb070, 4.2);
      this.fx.trail(p.x - p.vx * 0.5, p.y - p.vy * 0.5, p.z - p.vz * 0.5, WARN_ENEMY, 3, WARN_ENEMY);
      this.fx.smokeTrail(p.x, p.y, p.z);
    }
    if (left <= 0) this.impact(p);
  }

  private stepDrone(p: Proj, delta: number): void {
    if (p.target?.alive) {
      p.tx = p.target.group.position.x;
      p.tz = p.target.group.position.z;
    }
    const look = p.opts.look ?? 0;
    if (p.t < 0.6) {
      // 爬升
      p.vy = Math.max(0, p.vy - delta * 12);
      if (p.t + delta >= 0.6 && !p.enemy) this.onDive?.(p);
    } else {
      const dx = p.tx - p.x;
      const dz = p.tz - p.z;
      const dist = Math.hypot(dx, dz) || 1;
      // 武装无人机：飞到目标前上方就悬停扫射 dur 秒，再照常俯冲
      const S = p.strafe;
      if (S && S.t < S.dur && dist < 9) {
        const k = Math.min(1, delta * 5);
        p.vx += ((dx / dist) * Math.min(p.speed, Math.max(0, dist - 3) * 3) - p.vx) * k;
        p.vz += ((dz / dist) * Math.min(p.speed, Math.max(0, dist - 3) * 3) - p.vz) * k;
        p.vy += ((6 - p.y) * 3 - p.vy) * k;
        p.x += p.vx * delta;
        p.y += p.vy * delta;
        p.z += p.vz * delta;
        S.t += delta;
        S.shot -= delta;
        while (S.shot <= 0) {
          S.shot += 1 / S.rate;
          withPlayer(p.player ?? 0, () => this.onStrafe?.(p));
        }
        if (Math.random() < 0.3) this.fx.glint(p.x, p.y - 0.2, p.z, 0xff3a2a, 0.35);
        return;
      }
      // 目标在天上（T091）：按三维距离扎中，巡航高度跟着它
      const air = p.target?.alive && p.target.flying ? p.target.group.position.y : -1;
      const cruise = air >= 0 ? air + Math.min(4, dist * 0.2) : Math.max(1.2, Math.min(9, dist * 0.45));
      const k = Math.min(1, delta * 4);
      p.vx += ((dx / dist) * p.speed - p.vx) * k;
      p.vz += ((dz / dist) * p.speed - p.vz) * k;
      p.vy += ((cruise - p.y) * 3 - p.vy) * k;
      if (air >= 0 ? Math.hypot(dist, p.y - air) < 2.6 : dist < 2.2 && p.y < 2.5) this.impact(p);
    }
    p.x += p.vx * delta;
    p.y += p.vy * delta;
    p.z += p.vz * delta;
    // 机尾灯：2 级起换成识别色绿（T143，原来红）；★ 俯冲尾迹加亮
    if (Math.random() < (look >= 2 ? 0.45 : 0.3)) this.fx.glint(p.x, p.y - 0.2, p.z, look >= 2 ? 0x46f07a : 0xff3a2a, look >= 2 ? 0.45 : 0.35);
    // 俯冲拖一道细白烟（T018-1，黑潮同款细一号）
    if (p.t >= 0.6 && Math.random() < 0.5) this.fx.smokeP.emit({ x: p.x, y: p.y, z: p.z, vy: 0.3, life: 0.6, size: 0.35, size1: 1.1, color: 0xe8e6e0, alpha: 0.45, frame: 1, drag: 1.5 });
    if (look >= 6 && p.t >= 0.6) this.fx.trail(p.x, p.y, p.z, 0xffe0a0, 0.55);
  }

  private stepBomb(p: Proj, delta: number): void {
    p.vy -= 32 * delta;
    p.x += p.vx * delta;
    p.y += p.vy * delta;
    // 3 级起航弹拖细烟（T143）；燃烧弹（5 级起）拖橙色尾光
    const look = p.opts.look ?? 0;
    if (look >= 3 && Math.random() < 0.6) this.fx.smokeP.emit({ x: p.x, y: p.y, z: p.z, vy: 0.4, life: 0.7, size: 0.4, size1: 1.3, color: 0xe0dcd4, alpha: 0.4, frame: 1, drag: 1.5 });
    if (look >= 5 && p.opts.napalm) this.fx.trail(p.x, p.y, p.z, 0xffa040, 0.7);
    if (p.y <= 0.3) this.impact(p);
  }

  private impact(p: Proj): void {
    if (!p.alive) return;
    p.alive = false;
    p.obj.visible = false;
    withPlayer(p.player ?? 0, () => this.onImpact?.(p));
  }

  private take(kind: ProjKind, x: number, y: number, z: number, damage: number, radius: number): Proj {
    let p = this.list.find((item) => !item.alive && item.kind === kind);
    if (!p) {
      const obj = new THREE.Mesh(this.geos[kind], MAT.painted);
      obj.castShadow = kind !== 'rocket';
      if (kind === 'shell') obj.scale.setScalar(0.9);
      this.scene.add(obj);
      p = {
        kind, alive: false, obj, x, y, z, vx: 0, vy: 0, vz: 0, t: 0, life: 1, target: null, tx: 0, tz: 0,
        sx: 0, sy: 0, sz: 0, ty: 0, flight: 1, apex: 10, damage: 0, radius: 0, speed: 0, steer: ROCKET_TURN.steer, vmax: ROCKET_TURN.vmax, boost: ROCKET_TURN.boost, opts: {}, enemy: false, arc: false, src: 'other',
      };
      this.list.push(p);
    }
    p.alive = true;
    p.src = dmgSrc.cur;
    p.player = dmgSrc.player;
    p.obj.visible = true;
    p.x = x; p.y = y; p.z = z;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.t = 0;
    p.ty = 0;
    p.target = null;
    p.damage = damage;
    p.radius = radius;
    p.opts = {};
    p.enemy = false;
    p.strafe = null;
    p.obj.position.set(x, y, z);
    return p;
  }
}
