import { atkKind, type AtkKind, type DmgType } from './defs';
import { rng } from '../game/rng';

/** 攻击身份随弹丸、延迟命中一起传递，不用战报来源猜类型。 */
export interface AttackOpts {
  /** 主炮榴弹线、迫击炮及各自子母弹，给火控掀飞用。 */
  grenade?: boolean;
  /** 空袭信标航弹，给全氮离子的易伤用。 */
  airstrike?: boolean;
  /** 连锁本身不能再触发连锁。 */
  chain?: boolean;
  /** 身上余烧已保存燃烧加成后的每秒伤害，跳伤不再乘一次。 */
  burnTick?: boolean;
  type?: DmgType;
  kind?: AtkKind;
  summon?: boolean;
  crit?: boolean;
  ult?: boolean;
  fixed?: boolean;
}

export const canCrit = (opts: AttackOpts): boolean =>
  !opts.ult && !opts.fixed && ['bullet', 'blast'].includes(opts.kind ?? atkKind(opts.type));

/** 在一颗弹丸 / 一次爆炸的入口判定；贯穿和范围内所有目标共用结果。 */
export function rollCrit(opts: AttackOpts, chance: number): boolean {
  return canCrit(opts) && (opts.crit ?? (chance > 0 && rng.weapon() < chance));
}

export function directAttack<T extends AttackOpts>(opts: T, chance: number): T & { kind: AtkKind; crit: boolean } {
  const kind = opts.kind ?? atkKind(opts.type);
  return { ...opts, kind, crit: rollCrit({ ...opts, kind }, chance) };
}

export function blastAttack<T extends AttackOpts>(opts: T, chance: number): T & { kind: 'blast'; crit: boolean } {
  return { ...opts, kind: 'blast', crit: rollCrit({ ...opts, kind: 'blast' }, chance) };
}

/**
 * 火神仍按包碰撞，每颗弹各判一次。跨帧的半颗弹沿用同一次结果，
 * 包只存暴击发数，最多拆成普通 / 暴击两笔伤害，不增加弹体。
 */
export class PelletCrit {
  private left = 0;
  private crit = false;

  take(count: number, chance: number): number {
    let critical = 0;
    while (count > 1e-8) {
      if (this.left <= 1e-8) {
        this.left = 1;
        this.crit = rollCrit({ kind: 'bullet' }, chance);
      }
      const part = Math.min(count, this.left);
      if (this.crit) critical += part;
      count -= part;
      this.left -= part;
    }
    return critical;
  }

  reset(): void { this.left = 0; }
}
