import * as THREE from 'three';
import type { PartSpec } from '../GeoCache';
import { chamfer, frustum } from '../ModelKit';
import type { Branch } from '../../weapons/defs';

/**
 * 激光流炮塔「炉脊光矛」（D1-014 方案一，制作人 2026-10-16「就用 1 号吧」；草模在 D1 副本 scripts/laser-studies/models.ts 的 lance()）：
 * 两条装甲脊夹着一条开放长腔，三段聚焦镜组沿炮轴排，前端八角镜口；尾部双储能罐 + 护线 + 横向散热排。
 * 分四层各合一件网格：armor 迷彩装甲 / steel 金属件 / lens 镜片（顶点色，跟着光束阶段发光）/ glow 发光晶体线圈（MAT.prism）。
 * 棱镜折射多两只侧翼折射镜（棱镜风暴 4 只）；聚焦长枪腔里多两段镜组、镜口加聚焦环（脉冲长枪的环发光）；终极镜口和脊线镶金
 */
export interface PrismParts {
  armor: PartSpec[];
  steel: PartSpec[];
  lens: PartSpec[];
  glow: PartSpec[];
}

type V3 = [number, number, number];
type Layer = keyof PrismParts;

/** 光束出口（炮塔组坐标）：x / z 和原来的光棱炮塔一样（光束起点不变），高度对准镜组中轴 */
export const LANCE_AXIS_Y = 1.59;

const C = {
  armor: 0xb5b8a2, shade: 0x879185, dark: 0x243136,
  steel: 0x62777b, edge: 0x879b97, copper: 0x967344,
  rubber: 0x19262b, ceramic: 0xcecdb2, orange: 0xdba055, gold: 0xd8a84a,
};

function put(p: PrismParts, layer: Layer, geo: THREE.BufferGeometry, color: number, pos: V3 = [0, 0, 0], rot?: V3) {
  p[layer].push({ geo, color, pos, rot });
}

function box(p: PrismParts, layer: Layer, size: V3, pos: V3, color = C.steel, rot?: V3) {
  put(p, layer, new THREE.BoxGeometry(...size), color, pos, rot);
}

function castBlock(w: number, h: number, d: number, cut = 0.12) {
  return frustum(chamfer(w, d, cut), chamfer(w - 0.10, d - 0.10, cut), h, -h / 2);
}

/** 带倒角的圆环（轴沿 z） */
function ring(outer: number, inner: number, depth: number, segments = 20) {
  const b = Math.min(depth * 0.23, (outer - inner) * 0.25);
  return new THREE.LatheGeometry([
    new THREE.Vector2(inner, -depth / 2),
    new THREE.Vector2(outer - b, -depth / 2),
    new THREE.Vector2(outer, -depth / 2 + b),
    new THREE.Vector2(outer, depth / 2 - b),
    new THREE.Vector2(outer - b, depth / 2),
    new THREE.Vector2(inner, depth / 2),
    new THREE.Vector2(inner, -depth / 2),
  ], segments).rotateX(Math.PI / 2);
}

function pipe(p: PrismParts, points: V3[], radius = 0.085, color = C.copper) {
  const curve = new THREE.CatmullRomCurve3(points.map((v) => new THREE.Vector3(...v)));
  put(p, 'steel', new THREE.TubeGeometry(curve, 16, radius, 6, false), color);
}

function bolt(p: PrismParts, x: number, y: number, z: number, front = false, radius = 0.045) {
  put(p, 'steel', new THREE.CylinderGeometry(radius, radius, 0.05, 6), C.edge, [x, y, z], front ? [Math.PI / 2, 0, 0] : undefined);
}

/** 镜片曲面：中间往里凹 sag，法线按曲面算（看得出弧度） */
function lensSurface(inner: number, outer: number, radius: number, sag: number, from = 0, sweep = Math.PI * 2) {
  const positions: number[] = [];
  const uv: number[] = [];
  const point = (r: number, a: number) => [Math.cos(a) * r, Math.sin(a) * r, -sag * (1 - (r / radius) ** 2)];
  const push = (v: number[]) => {
    positions.push(...v);
    uv.push(v[0] / radius / 2 + 0.5, v[1] / radius / 2 + 0.5);
  };
  const n = sweep < 6 ? 8 : radius < 0.23 ? 16 : 28;
  for (let i = 0; i < n; i++) {
    const a = from + (sweep * i) / n;
    const b = from + (sweep * (i + 1)) / n;
    const v0 = point(inner, a), v1 = point(outer, a), v2 = point(outer, b), v3 = point(inner, b);
    push(v0); push(v2); push(v1);
    if (inner > 0) { push(v0); push(v3); push(v2); }
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geo.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  const nrm = new THREE.Vector3();
  const normals: number[] = [];
  for (let i = 0; i < positions.length; i += 3) {
    nrm.set((2 * sag * positions[i]) / (radius * radius), (2 * sag * positions[i + 1]) / (radius * radius), -1).normalize();
    normals.push(nrm.x, nrm.y, nrm.z);
  }
  geo.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));
  return geo;
}

/** 一片镜：四圈深浅不同的同心带 + 一道高光弧 */
function lens(p: PrismParts, x: number, y: number, z: number, radius: number) {
  const bands: [number, number, number][] = [[0, 0.38, 0x23414f], [0.38, 0.68, 0x34606f], [0.68, 0.91, 0x4a7d8c], [0.91, 1, 0x1d3644]];
  for (const [a, b, color] of bands) put(p, 'lens', lensSurface(radius * a, radius * b, radius, radius * 0.23), color, [x, y, z]);
  put(p, 'lens', lensSurface(radius * 0.78, radius * 0.81, radius, radius * 0.23, 0.72, 1.1), 0x9cc4cc, [x, y, z - 0.007]);
}

/** 镜口：外框 + 压圈 + 胶圈 + 镜片 + 四颗螺栓；octagonal = 八角外框 */
function eye(p: PrismParts, pos: V3, radius: number, depth = 0.36, octagonal = false, bezel = C.edge) {
  const [x, y, z] = pos;
  const n = octagonal ? 8 : radius < 0.3 ? 12 : 24;
  put(p, 'steel', ring(radius, radius * 0.76, depth, n), C.steel, [x, y, z + depth / 2]);
  put(p, 'steel', ring(radius * 0.94, radius * 0.79, 0.075, n), bezel, [x, y, z - 0.018]);
  put(p, 'steel', ring(radius * 0.78, radius * 0.66, 0.14, n), C.rubber, [x, y, z + 0.048]);
  lens(p, x, y, z + 0.075, radius * 0.68);
  for (let i = 0; i < 4; i++) {
    const a = Math.PI / 4 + (i * Math.PI) / 2;
    bolt(p, x + Math.cos(a) * radius * 0.86, y + Math.sin(a) * radius * 0.86, z - 0.067, true, radius * 0.043);
  }
}

function radiator(p: PrismParts, pos: V3, width: number, height: number, depth = 0.25, count = 7) {
  const [x, y, z] = pos;
  box(p, 'steel', [width, height, depth], pos, C.rubber);
  for (let i = 0; i < count; i++) {
    box(p, 'steel', [width + 0.06, 0.045, depth + 0.12], [x, y - height * 0.4 + (i * height * 0.8) / (count - 1), z + 0.035], i % 2 ? C.steel : C.shade);
  }
  for (const s of [-1, 1]) {
    box(p, 'steel', [0.075, height + 0.12, depth + 0.12], [x + s * width * 0.47, y, z + 0.035], C.edge);
    bolt(p, x + s * width * 0.47, y, z + depth / 2 + 0.13, true);
  }
}

/** 储能罐（轴沿 z）：罐身 + 两道铜箍 + 陶瓷端盖 + 顶上一条橙色指示片 */
function capacitor(p: PrismParts, pos: V3, radius = 0.27, length = 0.93) {
  const [x, y, z] = pos;
  put(p, 'steel', new THREE.CylinderGeometry(radius * 0.94, radius, length, 12), C.dark, pos, [Math.PI / 2, 0, 0]);
  for (const end of [-1, 1]) {
    put(p, 'steel', ring(radius * 1.1, radius * 0.88, 0.1, 12), C.copper, [x, y, z + end * length * 0.38]);
    put(p, 'steel', new THREE.CylinderGeometry(radius * 0.7, radius * 0.7, 0.1, 12), C.ceramic, [x, y, z + (end * length) / 2], [Math.PI / 2, 0, 0]);
  }
  box(p, 'steel', [radius * 0.32, radius * 0.22, length * 0.56], [x, y + radius * 0.98, z], C.orange);
}

/** 侧翼折射镜（棱镜折射）：钢托架伸出去，上面一颗发光的六棱晶体 */
function refractor(p: PrismParts, x: number, y: number, z: number, size: number) {
  const s = Math.sign(x);
  box(p, 'steel', [Math.abs(x) - 0.75, 0.12, 0.26], [s * (0.75 + (Math.abs(x) - 0.75) / 2), y - 0.32 * size, z], C.dark);
  put(p, 'steel', new THREE.CylinderGeometry(0.2 * size, 0.26 * size, 0.18, 6), C.steel, [x, y - 0.3 * size, z]);
  put(p, 'steel', ring(0.3 * size, 0.22 * size, 0.1, 6).rotateX(Math.PI / 2), C.edge, [x, y - 0.2 * size, z]);
  const crystal = new THREE.OctahedronGeometry(0.24 * size, 0).scale(1, 1.7, 1).rotateY(Math.PI / 4);
  put(p, 'glow', crystal, 0xffffff, [x, y + 0.14 * size, z]);
}

export function prismTurret(branch: Branch | null, ultimate: boolean): PrismParts {
  const p: PrismParts = { armor: [], steel: [], lens: [], glow: [] };
  const Y = LANCE_AXIS_Y;
  const trim = ultimate ? C.gold : C.edge;
  // 转台底座
  // T175：底面从 0.1 抬到 0.16（playerTank.ts 的 TURRET_GAP），和甲板之间露出座圈，顶面不变
  put(p, 'armor', frustum(chamfer(3.25, 3.05, 0.46), chamfer(2.95, 2.75, 0.4), 0.3, 0.16), C.armor, [0, 0, 0.25]);
  put(p, 'steel', new THREE.CylinderGeometry(1.5, 1.58, 0.14, 32), C.dark, [0, 0.51, 0.25]);
  put(p, 'steel', new THREE.CylinderGeometry(1.33, 1.45, 0.1, 32), C.steel, [0, 0.62, 0.25]);
  for (const x of [-1.24, 1.24]) for (const z of [-0.72, 0.25, 1.2]) bolt(p, x, 0.47, z);
  // 下车体与腔底
  put(p, 'armor', frustum(chamfer(2.45, 2.46, 0.32), chamfer(1.98, 2.12, 0.25), 0.65, 0.65), C.armor, [0, 0, 0.58]);
  box(p, 'steel', [1.08, 0.18, 3.62], [0, 1.1, -0.86], C.dark);
  // 两条装甲脊夹住开放长腔，镜组从顶上和侧面都看得见
  for (const s of [-1, 1]) {
    put(p, 'armor', castBlock(0.3, 0.65, 3.3, 0.06), C.armor, [s * 0.63, 1.73, -0.91]);
    box(p, 'steel', [0.08, 0.1, 3.17], [s * 0.81, 1.97, -0.91], trim);
    for (let i = 0; i < 7; i++) put(p, 'steel', castBlock(0.21, 0.77, 0.105, 0.025), i % 2 ? C.steel : C.dark, [s * 0.83, 1.57, -1.98 + i * 0.38]);
    capacitor(p, [s * 0.75, 1.42, 1.25], 0.31, 1.16);
    pipe(p, [[s * 0.75, 1.42, 1.95], [s * 1.22, 1.22, 1.74], [s * 1.12, 0.98, 0.25], [s * 0.55, 1.31, -0.05]], 0.095);
    box(p, 'steel', [0.32, 0.05, 0.28], [s * 0.72, 2.07, 0.41], C.orange);
  }
  // 三段聚焦镜组（聚焦长枪五段，更密）
  const stages = branch === 'B' ? [-0.22, -0.66, -1.11, -1.58, -2.05] : [-0.22, -1.11, -2.05];
  for (const z of stages) {
    put(p, 'steel', ring(0.51, 0.36, 0.18, 16), C.edge, [0, Y, z]);
    put(p, 'steel', ring(0.38, 0.32, 0.1, 16), C.copper, [0, Y, z - 0.06]);
    lens(p, 0, Y, z + 0.025, 0.31);
    box(p, 'steel', [0.12, 0.5, 0.18], [0, 1.12, z], C.steel);
  }
  // 前端八角镜口（终极镶金）
  eye(p, [0, Y, -2.75], 0.68, 0.36, true, trim);
  // 尾部：散热排 + 储能罐中间的接线盒（三道镜片窄缝，战场机位从车后也认得出光学件）
  radiator(p, [0, 1.08, 1.92], 1.48, 0.53, 0.23, 6);
  box(p, 'steel', [0.8, 0.12, 0.63], [0, 1.73, 1.12], C.dark);
  for (const x of [-0.28, 0, 0.28]) box(p, 'lens', [0.11, 0.025, 0.43], [x, 1.8, 1.12], 0x5a9ba9);

  if (branch === 'A') {
    // 棱镜折射：镜口两侧各一只折射镜；棱镜风暴再在腔中段加一对、整体放大
    const k = ultimate ? 1.25 : 1;
    for (const s of [-1, 1]) {
      refractor(p, s * 1.18, Y + 0.12, -2.25, k);
      if (ultimate) refractor(p, s * 1.18, Y + 0.12, -1.05, 0.9);
    }
  }
  if (branch === 'B') {
    // 聚焦长枪：镜口外再套一圈聚焦环 + 四根拉杆；脉冲长枪三道线圈跟着光束阶段发光
    put(p, 'steel', ring(0.6, 0.5, 0.16, 8), C.dark, [0, Y, -2.95]);
    for (let i = 0; i < 4; i++) {
      const a = Math.PI / 4 + (i * Math.PI) / 2;
      box(p, 'steel', [0.06, 0.06, 0.62], [Math.cos(a) * 0.62, Y + Math.sin(a) * 0.62, -2.62], C.steel);
    }
    if (ultimate) for (const z of [-0.66, -1.58, -2.95]) put(p, 'glow', new THREE.TorusGeometry(z === -2.95 ? 0.56 : 0.44, 0.035, 5, 16), 0xffffff, [0, Y, z]);
  }
  if (ultimate) {
    // 终极：底座一圈金边
    put(p, 'steel', frustum(chamfer(3.0, 2.8, 0.42), chamfer(2.98, 2.78, 0.42), 0.06, 0.44), C.gold, [0, 0, 0.25]);
  }
  return p;
}
