export const lookByCode = (code: string): ShellLook | undefined => SHELL_LOOKS.find((l) => l.code === code.toUpperCase());

export type ShellPick = Record<ShellStage, ShellLook | null>;

/** 定版（T252）：分支前 P、穿甲 A、榴弹 G */
export const SHELL_DEFAULT: Record<ShellStage, string> = { base: 'P', ap: 'A', he: 'G' };

export const defaultPick = (): ShellPick => ({ base: lookByCode(SHELL_DEFAULT.base)!, ap: lookByCode(SHELL_DEFAULT.ap)!, he: lookByCode(SHELL_DEFAULT.he)! });

/** 地址栏 ?shell=B,F（逗号 / 空格隔开，字母决定是哪个阶段，没写的阶段照定版）；?shell=0 = 三个阶段都用 T249 圆弹；小游戏里只用定版 */
export function shellPickFromUrl(): ShellPick {
  const pick = defaultPick();
  if (__WX__) return pick;
  try {
    const q = new URLSearchParams(location.search).get('shell');
    if (!q) return pick;
    if (q === '0') return { base: null, ap: null, he: null };
    for (const c of q.split(/[,，\s]+/)) {
      const l = c && lookByCode(c);
      if (l) pick[l.stage] = l;
    }
  } catch {
    /* 拿不到地址栏就用定版 */
  }
  return pick;
}

/** 低档弹体棱数：减到四分之三，最少 12（T252：别减成看得出棱角的六 / 八边形） */
const lowSides = (n: number) => Math.max(12, Math.round(n * 0.75));
/** 光带（尾焰 / 曳光）棱数：高中档 24、低档 12，外轮廓再由材质淡出（T252：G 的粗尾焰原来 6 棱，侧看是六边形光环） */
const STREAK_SIDES: [number, number] = [24, 12];
const streakGeometry = (low: boolean) => (low ? dropGeometry(DROP_LOW, STREAK_SIDES[1]) : dropGeometry(DROP, STREAK_SIDES[0]));

function lookGeometry(l: ShellLook, low: boolean): THREE.BufferGeometry {
  const sides = low ? lowSides(l.sides) : l.sides;
  const parts: THREE.BufferGeometry[] = [new THREE.LatheGeometry(l.pts.map(([r, t]) => new THREE.Vector2(r, t)), sides)];
  const c = new THREE.Color();
  const paint = (g: THREE.BufferGeometry, at: (x: number, y: number, z: number) => number) => {
    const pos = g.getAttribute('position');
    const col = new Float32Array(pos.count * 3);
    for (let i = 0; i < pos.count; i++) {
      c.setHex(at(pos.getX(i), pos.getY(i), pos.getZ(i)));
      col.set([c.r, c.g, c.b], i * 3);
    }
    g.setAttribute('color', new THREE.BufferAttribute(col, 3));
  };
  paint(parts[0], (x, y, z) => {
    if (l.stripe && y > l.stripe[1] && y < l.stripe[2] && x > 0 && Math.abs(Math.atan2(z, x)) < 0.4) return l.stripe[0];
    for (const [t, col] of l.bands) if (y <= t) return col;
    return l.bands[l.bands.length - 1][1];
  });
  const f = l.fins;
  if (f) {
    for (let i = 0; i < f.n; i++) {
      const g = new THREE.BoxGeometry(f.thick, f.t1 - f.t0, f.r1 - f.r0);
      g.translate(0, (f.t0 + f.t1) / 2, (f.r0 + f.r1) / 2);
      g.rotateY((i / f.n) * Math.PI * 2);
      paint(g, () => f.color);
      parts.push(g);
    }
  }
  const g = parts.length > 1 ? mergeGeometries(parts)! : parts[0];
  if (g !== parts[0]) for (const p of parts) p.dispose();
  g.rotateX(Math.PI / 2);
  g.translate(0, 0, -0.5);
  return g;
}

/** 一套方案的账：每发三角面（弹体 + 光带，高中档 / 低档）、要几次绘制、几种材质、新建了几个粒子系统 */
export function lookStats(l: ShellLook): { tris: number; trisLow: number; draws: number; mats: number; particles: number; streak: boolean } {
  const count = (g: THREE.BufferGeometry) => {
    const n = (g.index ? g.index.count : g.getAttribute('position').count) / 3;
    g.dispose();
    return n;
  };
  const st = (low: boolean) => (l.streak ? count(streakGeometry(low)) : 0);
  return { tris: count(lookGeometry(l, false)) + st(false), trisLow: count(lookGeometry(l, true)) + st(true), draws: l.streak ? 2 : 1, mats: l.streak ? 2 : 1, particles: 0, streak: !!l.streak };
}

/** 画一颗方案弹要往子弹那一批（白热）里放的实例，Bullets 接着抄进去 */
export interface LookOut {
  glows: number;
  glowM: THREE.Matrix4[];
  glowC: THREE.Color[];
}

interface Batch { mesh: THREE.InstancedMesh; geo: [THREE.BufferGeometry, THREE.BufferGeometry]; n: number }

/** 判定数据里只要这些（Bullets.Bullet 的子集，免得两边互相引用） */
export interface LookBullet {
  kind: string;
  fromPlayer: boolean;
  ap: boolean;
  grenade?: boolean;
  x: number;
  y: number;
  z: number;
  vx: number;
  vz: number;
  life: number;
  sizeW: number;
  sizeL: number;
  yd: number;
  y0: number;
  y1: number;
  fly: number;
  reach: number;
}

const CAP = 32;

export class ShellLooks {
  networkMeshes(): [string, THREE.InstancedMesh][] {
    return [
      ...Object.entries(this.pick).filter((entry): entry is [string, ShellLook] => !!entry[1]).map(([name, look]): [string, THREE.InstancedMesh] => [name, this.batch(look).mesh]),
      ['streak', this.streakBatch().mesh],
    ];
  }
  pick: ShellPick;
  /** 尾迹往哪喷（游戏里是 Game.fx，预览页是自己的 Fx）；没接上就只画弹体 */
  fx: Fx | null = null;
  private low = false;
  private readonly scene: THREE.Scene;
  private readonly batches = new Map<ShellLook, Batch>();
  private readonly mat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.38, metalness: 0.45 });
  private readonly out: LookOut = { glows: 0, glowM: [new THREE.Matrix4(), new THREE.Matrix4()], glowC: [new THREE.Color(), new THREE.Color()] };
  /** 光带：所有方案共用一批，第一次用到才建 */
  private streaks: Batch | null = null;
  private readonly m = new THREE.Matrix4();
  private readonly c = new THREE.Color();
  private readonly at: TrailAt = { x: 0, y: 0, z: 0, fx: 0, fy: 0, fz: 1, w: 0, len: 0, s: 1, roll: 0, k: 0, dt: 0, low: false };
  private readonly q = new THREE.Quaternion();
  private readonly e = new THREE.Euler(0, 0, 0, 'YXZ');
  private readonly p = new THREE.Vector3();
  private readonly v = new THREE.Vector3();
  private readonly s = new THREE.Vector3();
  private readonly f = new THREE.Vector3();

  constructor(scene: THREE.Scene, pick: ShellPick) {
    this.scene = scene;
    this.pick = pick;
  }

  /** 这颗弹该用哪套（没挑 = null，走 T249 圆弹） */
  of(b: LookBullet): ShellLook | null {
    if (!b.fromPlayer) return null;
    return this.pick[b.ap ? 'ap' : b.grenade ? 'he' : 'base'];
  }

  lod(low: boolean): void {
    this.low = low;
    for (const b of this.all()) b.mesh.geometry = b.geo[low ? 1 : 0];
  }

  private *all(): Iterable<Batch> {
    yield* this.batches.values();
    if (this.streaks) yield this.streaks;
  }

  private make(geo: [THREE.BufferGeometry, THREE.BufferGeometry], mat: THREE.Material): Batch {
    const mesh = new THREE.InstancedMesh(geo[this.low ? 1 : 0], mat, CAP);
    mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    mesh.frustumCulled = false;
    mesh.count = 0;
    mesh.visible = false;
    this.scene.add(mesh);
    return { mesh, geo, n: 0 };
  }

  private batch(l: ShellLook): Batch {
    let b = this.batches.get(l);
    if (!b) {
      b = this.make([lookGeometry(l, false), lookGeometry(l, true)], this.mat);
      this.batches.set(l, b);
    }
    return b;
  }

  private streakBatch(): Batch {
    if (!this.streaks) {
      this.streaks = this.make([streakGeometry(false), streakGeometry(true)], dropMaterial(true));
      this.streaks.mesh.setColorAt(0, this.c.setHex(0xffffff));
      this.streaks.mesh.renderOrder = 3;
    }
    return this.streaks;
  }

  begin(): void {
    for (const b of this.all()) b.n = 0;
  }

  /** 摆一颗弹：弹体、光带进自己的批，白热写进 out 交回 Bullets；顺手喷尾迹 */
  draw(b: LookBullet, l: ShellLook, dt: number): LookOut {
    const o = this.out;
    o.glows = 0;
    const bt = this.batch(l);
    const big = b.kind === 'mega' ? 1.6 : 1;
    const w = l.size[0] * big * b.sizeW;
    const len = l.size[1] * big * b.sizeL;
    const sp = Math.hypot(b.vx, b.vz) || 1;
    const k = b.fly / Math.max(1e-3, b.fly + Math.max(0, b.life));
    // 曲射（只是画面）：从出膛到瞄准点（没瞄准 = 射程尽头）抛一道弧，过了瞄准点贴回原来的高度
    let h = 0;
    let slope = b.yd > 0 ? (b.y1 - b.y0) / b.yd : 0;
    if (l.arc && b.yd <= 0) {
      const R = b.reach > 0 ? b.reach : sp * (b.fly + Math.max(0, b.life));
      const u = (sp * b.fly) / R;
      if (u < 1) {
        h = l.arc * 4 * u * (1 - u);
        slope += (l.arc * 4 * (1 - 2 * u)) / R;
      }
    }
    const roll = (l.spin ?? 0) * b.fly;
    this.q.setFromEuler(this.e.set(-Math.atan(slope), Math.atan2(b.vx, b.vz), roll));
    this.f.set(0, 0, 1).applyQuaternion(this.q);
    this.p.set(b.x, b.y + h, b.z);
    if (bt.n < CAP) bt.mesh.setMatrixAt(bt.n++, o.glowM[0].compose(this.p, this.q, this.s.set(w, w, len)));
    // 弹底：一团压扁的白热，朝后贴在弹底
    this.v.copy(this.p).addScaledVector(this.f, -len * 0.5);
    const g = l.glow[0] * w;
    o.glowM[0].compose(this.v, this.q, this.s.set(g, g, g * 0.5));
    o.glowC[0].setHex(l.glow[1]);
    o.glows = 1;
    if (l.land !== undefined && k > l.land) {
      // 快落地：弹体中间亮起我方浅黄，越近越大、一闪一闪
      const r = (k - l.land) / (1 - l.land);
      const pulse = 0.75 + 0.25 * Math.sin(b.fly * 40);
      const gs = w * (2 + 3 * r) * pulse;
      o.glowM[1].compose(this.p, this.q, this.s.set(gs, gs, gs * 1.4));
      o.glowC[1].setHex(MARK_SELF).multiplyScalar(0.6 + 0.6 * r);
      o.glows = 2;
    }
    const st = l.streak;
    const sb = st && this.streakBatch();
    if (st && sb && sb.n < CAP) {
      const sl = Math.min(st.len * big * (1 + (st.flicker ? rand(-st.flicker, st.flicker) : 0)), Math.max(len, sp * b.fly));
      const sw = st.w * big;
      const at = st.at === 'nose' ? this.s.copy(this.p).addScaledVector(this.f, len * 0.5 + w * 0.6) : this.s.copy(this.v);
      sb.mesh.setMatrixAt(sb.n, this.m.compose(at, this.q, this.v.set(sw, sw, sl)));
      sb.mesh.setColorAt(sb.n++, this.c.setHex(st.color));
    }
    if (this.fx) {
      const t = this.at;
      const tail = this.v.copy(this.p).addScaledVector(this.f, -len * 0.5);
      t.x = tail.x;
      t.y = tail.y;
      t.z = tail.z;
      t.fx = this.f.x;
      t.fy = this.f.y;
      t.fz = this.f.z;
      t.w = w;
      t.len = len;
      t.s = big;
      t.roll = roll;
      t.k = k;
      t.dt = dt;
      t.low = this.low;
      l.trail(this.fx, t);
    }
    return o;
  }

  end(): void {
    for (const b of this.all()) {
      b.mesh.count = b.n;
      b.mesh.visible = b.n > 0;
      if (b.n === 0) continue;
      b.mesh.instanceMatrix.needsUpdate = true;
      if (b.mesh.instanceColor) b.mesh.instanceColor.needsUpdate = true;
    }
  }

  clear(): void {
    this.begin();
    this.end();
  }
}
