import * as THREE from 'three';
import { MAT } from '../assets/materials';
import { sceneryMaterial } from '../assets/sceneryMaterial';
import { SCN_MAT } from './sceneryDetail';
import { houseNoise } from '../assets/models/houseFracture';
import { masonryFracture, type MasonryChunk } from '../assets/models/masonryFracture';
import type { Scenery, ScnItem } from './Scenery';

interface Motion {
  time: number;
  delay: number;
  duration: number;
  to: THREE.Vector3;
  rotation: THREE.Quaternion;
}
interface Chunk extends MasonryChunk {
  loose: boolean;
  motion: Motion | null;
}
interface Masonry {
  mesh: THREE.Mesh;
  chunks: Chunk[];
  positions: Float32Array;
  normals: Float32Array;
  pigment: Float32Array;
  holes: { point: THREE.Vector3; radius: number; normal: THREE.Vector3 }[];
  x: number;
  z: number;
  tint: number;
  collapsed: boolean;
}

/** 残楼和独立砖墙的显示。结构值、挡弹、砸落范围与软凸起仍由原入口负责。 */
export class MasonryDamage {
  private readonly items = new Map<ScnItem, Masonry>();
  private readonly moving = new Set<ScnItem>();
  private readonly hidden = new THREE.Matrix4().makeScale(0, 0, 0);
  private readonly v = new THREE.Vector3();
  private readonly q = new THREE.Quaternion();
  private readonly up = new THREE.Vector3(0, 1, 0);
  private readonly identity = new THREE.Quaternion();

  constructor(private readonly scn: Scenery) {}

  private get(it: ScnItem): Masonry {
    let h = this.items.get(it);
    if (h) return h;
    const model = masonryFracture(this.scn.pool(it.kind).mesh.geometry, it.id);
    const mesh = new THREE.Mesh(model.geometry, model.geometry.getAttribute('surf') && SCN_MAT ? sceneryMaterial() : MAT.painted);
    mesh.name = 'masonry-fracture';
    mesh.castShadow = mesh.receiveShadow = true;
    h = {
      mesh, chunks: model.chunks.map(p => ({ ...p, loose: false, motion: null })),
      positions: new Float32Array(model.geometry.getAttribute('position').array),
      normals: new Float32Array(model.geometry.getAttribute('normal').array),
      pigment: new Float32Array(model.geometry.getAttribute('color').array),
      holes: [], x: it.x, z: it.z, tint: NaN, collapsed: false,
    };
    this.items.set(it, h);
    this.scn.group.add(mesh);
    return h;
  }

  sync(it: ScnItem): boolean {
    const h = this.items.get(it);
    if (!h) return false;
    if (!it.alive || it.state === 'gone' || it.state === 'melted') { this.forget(it); return false; }
    if (!h.collapsed && (it.state === 'rubble' || it.state === 'strip')) this.collapse(it, true);
    if (it.main) it.main.pool.set(it.main, this.hidden);
    h.mesh.position.set(h.x, it.y, h.z);
    h.mesh.rotation.y = it.rot;
    h.mesh.scale.setScalar(it.s);
    if (h.tint !== it.tint) {
      const color = h.mesh.geometry.getAttribute('color') as THREE.BufferAttribute;
      for (let i = 0; i < h.pigment.length; i++) color.array[i] = h.pigment[i] * it.tint;
      color.needsUpdate = true;
      h.tint = it.tint;
    }
    return true;
  }

  hit(it: ScnItem, x: number, z: number, size: number, y: number, cut: boolean, vertical: boolean): void {
    const h = this.get(it), c = Math.cos(it.rot), s = Math.sin(it.rot);
    const point = new THREE.Vector3(((x - it.x) * c - (z - it.z) * s) / it.s, y,
      ((x - it.x) * s + (z - it.z) * c) / it.s);
    // 残楼只有两面残墙；弹道从空的一侧来时，找实际仍在的砖面。
    let nearest: Chunk | undefined, dist = Infinity;
    for (const p of h.chunks) {
      if (p.fixed || p.glass) continue;
      const d = p.box.distanceToPoint(point);
      if (d < dist) { nearest = p; dist = d; }
    }
    if (!nearest) return;
    nearest.box.clampPoint(point, point);
    const normal = nearest.normal;
    let hole = h.holes.find(b => b.normal.dot(normal) > .9 && b.point.distanceTo(point) < 1);
    const radius = Math.max(.4, size * .62);
    if (hole) hole.radius = Math.min(2.8, Math.hypot(hole.radius, radius * .7));
    else { hole = { point, radius, normal }; h.holes.push(hole); }
    const animate = this.canAnimate(it);
    const detached: Chunk[] = [];
    for (const p of h.chunks) {
      if (p.fixed || p.loose || p.normal.dot(normal) < .9) continue;
      const dx = p.center.x - hole.point.x, dz = p.center.z - hole.point.z;
      const across = dx * normal.z - dz * normal.x, depth = dx * normal.x + dz * normal.z;
      const width = hole.radius * (cut && vertical ? .4 : 1);
      const height = hole.radius * (cut && !vertical ? .35 : 1);
      const d = (across / (width + .22)) ** 2 + ((p.center.y - hole.point.y) / (height + .22)) ** 2;
      if (d > 1 || Math.abs(depth) > .65) continue;
      this.detach(it, h, p, animate, 0);
      detached.push(p);
    }
    // 缺口上方同一窄条失去承托，随后落下；旁边与另一堵墙保留。
    for (const p of h.chunks) {
      if (p.fixed || p.loose) continue;
      if (detached.some(d => !d.glass && p.center.y > d.center.y &&
          Math.hypot(p.center.x - d.center.x, p.center.z - d.center.z) < .45)) {
        this.detach(it, h, p, animate, .12);
      }
    }
    this.flush(h);
    this.sync(it);
  }

  collapse(it: ScnItem, instant: boolean, dx = 0, dz = 0): void {
    if (it.kind !== 'ruin' && it.kind !== 'wall') return;
    const h = this.get(it);
    if (h.collapsed) return;
    h.collapsed = true;
    const animate = !instant && this.canAnimate(it);
    const c = Math.cos(it.rot), s = Math.sin(it.rot);
    for (const p of h.chunks) if (!p.fixed && !p.loose)
      this.detach(it, h, p, animate, p.center.y * .018, dx * c - dz * s, dx * s + dz * c);
    this.flush(h);
    this.sync(it);
  }

  private canAnimate(it: ScnItem): boolean {
    return this.scn.visible(it.x, it.z) && (this.moving.has(it) || this.moving.size < 6);
  }

  private detach(it: ScnItem, h: Masonry, p: Chunk, animate: boolean, delay: number, dx = 0, dz = 0): void {
    p.loose = true;
    const seed = it.id * 313 + p.start, r = houseNoise(seed), r2 = houseNoise(seed + 7);
    const to = p.center.clone();
    const directed = dx !== 0 || dz !== 0;
    const inward = h.collapsed && it.kind === 'ruin';
    if (inward) { to.x *= .6; to.z *= .6; }
    const scatter = h.collapsed ? 1.8 : .4;
    to.x += (directed ? dx : p.normal.x) * (inward ? -.3 : .6 + r) + (r2 - .5) * scatter;
    to.z += (directed ? dz : p.normal.z) * (inward ? -.3 : .6 + r) + (r - .5) * scatter;
    const rotation = new THREE.Quaternion().setFromUnitVectors(p.normal, this.up);
    rotation.premultiply(this.q.setFromAxisAngle(this.up, (r - .5) * 1.8));
    rotation.premultiply(this.q.setFromAxisAngle(this.v.set(1, 0, 0), (r2 - .5) * .6));
    let low = Infinity;
    for (let i = p.start * 3; i < (p.start + p.count) * 3; i += 3) {
      this.v.set(h.positions[i], h.positions[i + 1], h.positions[i + 2]).sub(p.center).applyQuaternion(rotation);
      low = Math.min(low, this.v.y);
    }
    const c = Math.cos(it.rot), s = Math.sin(it.rot);
    const floor = (this.scn.groundAt(h.x + (to.x * c + to.z * s) * it.s,
      h.z + (-to.x * s + to.z * c) * it.s) - it.y) / it.s;
    to.y = Math.max(floor, it.kind === 'ruin' && Math.abs(to.x) < 4 && Math.abs(to.z) < 3.5 ? .5 : floor) - low + .03 + r * (inward ? .35 : .1);
    const motion: Motion = { time: 0, delay: delay + r2 * .08,
      duration: Math.max(.22, Math.sqrt(Math.max(.05, p.center.y - to.y) / 8) + .12), to, rotation };
    if (animate) { p.motion = motion; this.moving.add(it); }
    else this.pose(h, p, motion, 1);
  }

  private pose(h: Masonry, p: Chunk, m: Motion, k: number): void {
    this.q.slerpQuaternions(this.identity, m.rotation, Math.min(1, k * 1.3));
    const x = THREE.MathUtils.lerp(p.center.x, m.to.x, k), z = THREE.MathUtils.lerp(p.center.z, m.to.z, k);
    const y = THREE.MathUtils.lerp(p.center.y, m.to.y, k * k) + Math.sin(k * Math.PI) * .12;
    const position = h.mesh.geometry.getAttribute('position') as THREE.BufferAttribute;
    const normal = h.mesh.geometry.getAttribute('normal') as THREE.BufferAttribute;
    for (let i = p.start; i < p.start + p.count; i++) {
      const j = i * 3;
      this.v.set(h.positions[j], h.positions[j + 1], h.positions[j + 2]).sub(p.center).applyQuaternion(this.q);
      position.setXYZ(i, this.v.x + x, this.v.y + y, this.v.z + z);
      this.v.set(h.normals[j], h.normals[j + 1], h.normals[j + 2]).applyQuaternion(this.q);
      normal.setXYZ(i, this.v.x, this.v.y, this.v.z);
    }
  }

  private flush(h: Masonry): void {
    h.mesh.geometry.getAttribute('position').needsUpdate = true;
    h.mesh.geometry.getAttribute('normal').needsUpdate = true;
    h.mesh.geometry.computeBoundingSphere();
  }

  update(dt: number): void {
    for (const [it, h] of this.items) {
      if (!it.alive || it.state === 'gone' || it.state === 'melted') { this.forget(it); continue; }
      this.sync(it);
      if (!this.moving.has(it)) continue;
      let active = false;
      for (const p of h.chunks) {
        const m = p.motion;
        if (!m) continue;
        m.time += dt;
        const k = THREE.MathUtils.clamp((m.time - m.delay) / m.duration, 0, 1);
        this.pose(h, p, m, k);
        if (k >= 1) p.motion = null;
        else active = true;
      }
      this.flush(h);
      if (!active) this.moving.delete(it);
    }
  }

  forget(it: ScnItem): void {
    const h = this.items.get(it);
    if (!h) return;
    h.mesh.removeFromParent(); h.mesh.geometry.dispose();
    this.items.delete(it); this.moving.delete(it);
  }

  reset(): void { for (const it of this.items.keys()) this.forget(it); }
  describe(it: ScnItem) {
    const h = this.items.get(it);
    return h ? { chunks: h.chunks.length, loose: h.chunks.filter(p => p.loose).length,
      moving: h.chunks.filter(p => p.motion).length, holes: h.holes.length, collapsed: h.collapsed } : null;
  }
  stats() { return { items: this.items.size, moving: this.moving.size, draws: this.items.size * 2 }; }
}
