export function computeModStats(mods: Map<ModId, number>): ModStats {
  const s: ModStats = { rate: 1, count: 0, crit: 0, energy: 1, cooldown: 1, burn: 1, summon: 1, area: 1, armor: 0, magnet: 1, xp: 1, scrapHeal: 0, scrapGrow: 0, growCap: 0, smallArmor: 1, maxHpBonus: 0, shield: 0, shieldRegen: 0 };
  for (const [id, level] of mods) {
    const l = isSuperMod(id) ? MAX_LEVEL : level;
    switch (id) {
      case 'cooling': s.rate = 1.4; break;
      case 'ammo': s.count = 2; break;
      case 'firecontrol': s.crit = 0.3; break;
      case 'lens': s.energy = 1.6; break;
      case 'capacitor': s.cooldown = 0.7; break;
      case 'fuel': s.burn = 2; break;
      case 'relay': s.summon = 2; break;
      case 'explosive': s.area = 1.5; break;
      case 'armor': s.maxHpBonus = l * 35; s.armor = l * SURVIVE.armorPer; s.smallArmor = SURVIVE.smallArmor; break;
      case 'magnet': s.magnet = 1 + l * 0.25; s.xp = 1 + l * 0.1; s.scrapHeal = lv(SURVIVE.heal, l) / 10; s.scrapGrow = lv(SURVIVE.grow, l); s.growCap = l * SURVIVE.growCap; break;
      case 'shield': s.shield = l * SURVIVE.shieldPer; s.shieldRegen = 2 + l * 2; break;
    }
  }
  return s;
}

// ------------------------------------------------------------------ 流派核心

function lv<T>(arr: T[], level: number): T {
  return arr[Math.max(0, Math.min(arr.length - 1, level - 1))];
}

