const KIT_POINT: Record<FusionId, [number, number, number]> = { nuke: [0.95, 1.3, 1.2], inferno: [0, 1.2, 2.4], snare: [0, 1.4, 0.45], swarm: [0, 1.05, 1.22], skyfire: [-0.25, 1.5, 1.95], aurora: [0.98, 1.2, 1.75], gunship: [1.12, 1.1, 0.5], curtain: [0.3, 1.3, 0.3] };
/** 火焰统一按 fire 结算（拍板 1-8）：地面火 / 身上的余烧；终极留下的火再带 ult（不暴击、计入 dmgUlt） */
const FIRE: DamageOpts = { type: 'fire', kind: 'fire' };

/**
 * 步兵被什么打掉（T248）：火 = 烧起来，电 / 光束 = 电击化灰，爆炸 = 炸飞（大爆炸有四成震散），
 * 主炮直击（击退 ≥ 4 的炮弹）= 连枪一起打飞，其余小口径 = 中弹仰倒
 */
function infDeath(o: DamageOpts, knock: number, big: boolean): InfDeath {
  const t = o.type ?? 'shell';
  if (t === 'fire' || o.kind === 'fire') return 'burn';
  if (t === 'energy' || o.kind === 'elec' || o.kind === 'energy') return 'zap';
  if (t === 'blast' || o.kind === 'blast') return big && Math.random() < 0.4 ? 'scatter' : 'blast';
  return t === 'shell' && knock >= 4 ? 'shell' : 'shot';
}
