function parseTrial(): { id: FusionId; branch: Branch } | null {
  const q = new URLSearchParams(location.search);
  const raw = q.get('fusion');
  const id = raw ? FUSION_ALIAS[raw] ?? raw : null;
  if (!id || !(id in FUSIONS)) return null;
  return { id: id as FusionId, branch: q.get('branch')?.toUpperCase() === 'B' ? 'B' : 'A' };
}

