/** 解析直通入口；不带 zone / 不合法返回 null（流程和平时完全一样） */
function parseJump(): { zone: number; t: number; skip: boolean; boss: boolean; phase: number; patch: boolean } | null {
  const q = new URLSearchParams(location.search);
  const zone = Math.floor(Number(q.get('zone')));
  if (!(zone >= 1 && zone <= 99)) return null;
  // &gate=0（T050）：巨炮区跳过「轰天」卫队，180 秒直接出巨炮
  // &boss=1（T100B）：区域 5 跳过 180 秒和空中卫队，直接出「云垒」（机库在路右边，正中在车前 200 米）；&phase=2 / 3 从阶段二 / 三开始；&patch=1 六件全换补丁件
  return {
    zone, t: THREE.MathUtils.clamp(Number(q.get('t')) || 0, 0, ZONE_TIME), skip: q.get('gate') === '0',
    boss: q.get('boss') === '1', phase: THREE.MathUtils.clamp(Math.floor(Number(q.get('phase')) || 1), 1, 3), patch: q.get('patch') === '1',
  };
}

