const ULT_SPOT = { armor: { heavy: 3, light: 1.5, none: 0.3 }, road: 13, onRoad: 1.5, field: 0.6, elite: 3, far: 100, fall: 0.2, reach: 0.35, near: 15, crowd: 5, cone: 1.3 };
