const DEBUG_DMG: [number, number, string][] | null = new URLSearchParams(location.search).has('debug') ? [] : null;
if (DEBUG_DMG) (window as unknown as { __DMG__: unknown }).__DMG__ = DEBUG_DMG;

/**
 * 经验曲线（T041 = T039 方案 D 第一批，制作人 2026-10-15「那经验值这个事全按推荐就行」）：1 级升 2 级要 XP_CURVE.start，之后每一级 = 上一级的需求 × XP_CURVE.mult（四舍五入，见 nextXpNeed）。
 * T036 是 20 起 ×1.2（开局太慢）；再往前（T017-6A / T017-3）是 4 起、前 14 级 ×1.24、15 级起 ×1.16、每级再 +1。
 * 正常升级（gainXp）、试玩 / 直通入口预先滚的等级（rollLevel）、读档（loadRun）共用这一条，别只改一处
 */
export const XP_CURVE = { start: 8, mult: 1.25 };
/** ×1.25 会碰到正好 .5（10 × 1.25 = 12.5）：取偶数（12.5 → 12、37.5 → 38），和 T039 定下的那张表一个数不差（8 / 10 / 12 / 15 / 19 …，20 级 564、22 级 881） */
export function nextXpNeed(need: number): number {
  const v = need * XP_CURVE.mult;
  const r = Math.round(v);
  return r - v === 0.5 && r % 2 ? r - 1 : r;
}
/** level 级升下一级要多少经验 */
export function xpNeedAt(level: number): number {
  let need = XP_CURVE.start;
  for (let i = 1; i < level; i++) need = nextXpNeed(need);
  return need;
}

