  private drawFrame(): void {
    this.overlay?.prepare();
    const view = this.phase === 'title' ? this.menu.turntableView() : null;
    this.studio.preview(view);
    const began = this.online?.active ? performance.now() : 0;
    if (!view) {
      if (this.online?.room.playing && !this.onlineGuest) this.blendOnlinePose(true);
      for (const player of this.playerStates) player.tank.beginHullDraw();
      this.enemies.beginGroundDraw();
      try {
        this.post.render();
      } finally {
        this.enemies.endGroundDraw();
        for (const player of this.playerStates) player.tank.endHullDraw();
        if (this.online?.room.playing && !this.onlineGuest) this.blendOnlinePose(false);
      }
    }
    // 截图那一帧：画布版界面不画（DOM 版界面本来就不在画布里），渲染完马上读；高光抓帧（T018-2）同理，在画界面之前读
    if (this.capReq) this.capture();
    if (this.deathCap) this.captureDeath();
    if (this.shotReq) this.takeShot();
    else this.overlay?.render();
    if (began) this.online?.drawn(performance.now() - began);
  }

