    this.world.scnHooks.fire = (x, z, r, life, dps) => this.hazards.fire(x, z, r, life, dps, 'neutral');
    this.world.scnHooks.crushLine = (x0, z0, x1, z1, w, dmg) => this.crushLine(x0, z0, x1, z1, w, dmg);
