import type { EnemyKind } from '../entities/Enemy';

/**
 * 伤害来源：武器更新 / 开火时写入 cur，子弹、抛射物、火焰区在生成时把它记下来，
 * 命中结算前再写回 cur，这样每一点伤害都能算到对应的武器头上。
 * 取值：'core'（主武器）、副武器 id、'crush'（碾压）、'barrel'（油桶）、'other'。
 * tag 只管战报记在哪一行：联动打出的伤害记 'link:<联动 id>'，玩法判定（倍率、击毁归属）照旧看 cur。
 */
export const dmgSrc = { cur: 'other', tag: '', player: 0 };

/** 玩家归属贯穿同步调用；延后事件另存玩家号。 */
export function withPlayer<T>(player: number, fn: () => T): T {
  const previous = dmgSrc.player;
  dmgSrc.player = player;
  try { return fn(); } finally { dmgSrc.player = previous; }
}

/** 在指定来源下执行一段结算；tag 给联动用 */
export function withSrc<T>(src: string, fn: () => T, tag = ''): T {
  const prev = dmgSrc.cur;
  const prevTag = dmgSrc.tag;
  dmgSrc.cur = src;
  dmgSrc.tag = tag;
  try {
    return fn();
  } finally {
    dmgSrc.cur = prev;
    dmgSrc.tag = prevTag;
  }
}

/** 战报记账的行 */
export const logSrc = (): string => dmgSrc.tag || dmgSrc.cur;

/** 本局战报：每种来源的输出 + 每种敌人的击毁数 */
export class DamageLog {
  readonly dmg = new Map<string, number>();
  readonly kills = new Map<EnemyKind, number>();
  /** 「生存」一栏（T023-a）：'regen' 自动维修 / 'scrap' 回收修车 / 'shield' 护盾挡下 / 'armor' 护甲挡下 */
  readonly surv = new Map<string, number>();

  add(src: string, amount: number): void {
    if (amount <= 0) return;
    this.dmg.set(src, (this.dmg.get(src) ?? 0) + amount);
  }

  survive(src: string, amount: number): void {
    if (amount <= 0) return;
    this.surv.set(src, (this.surv.get(src) ?? 0) + amount);
  }

  kill(kind: EnemyKind): void {
    this.kills.set(kind, (this.kills.get(kind) ?? 0) + 1);
  }

  reset(): void {
    this.dmg.clear();
    this.kills.clear();
    this.surv.clear();
  }

  get total(): number {
    let t = 0;
    for (const v of this.dmg.values()) t += v;
    return t;
  }

  /** 存档用 */
  toJSON(): { dmg: [string, number][]; kills: [EnemyKind, number][]; surv: [string, number][] } {
    return { dmg: [...this.dmg], kills: [...this.kills], surv: [...this.surv] };
  }

  load(data: { dmg: [string, number][]; kills: [EnemyKind, number][]; surv?: [string, number][] }): void {
    this.reset();
    for (const [k, v] of data.dmg) this.dmg.set(k, v);
    for (const [k, v] of data.kills) this.kills.set(k, v);
    for (const [k, v] of data.surv ?? []) this.surv.set(k, v);
  }
}
