import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';

export interface PartSpec {
  geo: THREE.BufferGeometry;
  color: number;
  pos?: [number, number, number];
  rot?: [number, number, number];
  scale?: [number, number, number];
  /** 只登记碾压部件；完好模型的顶点、颜色和绘制方式不变。 */
  crush?: number;
  /** 景物表面类别（T184 加细景物的程序纹理）；有任何部件给了就整件带 surf 属性，没给的部件记 0。 */
  surf?: number;
}

export interface CrushPartRange {
  start: number;
  count: number;
  role: number;
  pivot: [number, number, number];
}

/**
 * 几何体检视诊断（微信小游戏真机用）：
 * 真机（JSC）曾在 BufferGeometry.clone() 里抛 "n.clone is not a function"，
 * 模拟器/桌面不复现。这里对每个部件只读数据属性做指纹留档，
 * 异常部件会写进 wx 本地存储 __tank_geo / __tank_geo_err（桌面端只留在 globalThis.__TANK_GEO__）。
 */
interface GeoDiagState {
  scanned: number;
  keys: string[];
  ctors: Record<string, number>;
  sample: string;
  bad: string[];
}

function geoDiag(): GeoDiagState {
  const g = globalThis as any;
  if (!g.__TANK_GEO__) g.__TANK_GEO__ = { scanned: 0, keys: [], ctors: {}, sample: '', bad: [] } as GeoDiagState;
  return g.__TANK_GEO__;
}

function wxWrite(key: string, value: string): void {
  try {
    const g = globalThis as any;
    const w = g.wx ?? g.GameGlobal?.wx;
    if (w && typeof w.setStorageSync === 'function') w.setStorageSync(key, value.slice(0, 1800));
  } catch { /* 诊断通道失败绝不影响游戏 */ }
}

/** 每次 merged() 完成都落盘（启动期调用次数有限），异常时立即强制落盘 */
function flushGeoDiag(): void {
  const d = geoDiag();
  wxWrite('__tank_geo', JSON.stringify({ scanned: d.scanned, keys: d.keys.slice(-40), ctors: d.ctors, sample: d.sample, bad: d.bad.slice(0, 8) }));
}

/** 部件指纹：构造器名（含 is* 标记，防 minify 后类名不可读）+ 每个 attribute 的形态。自身绝不抛错。 */
function fingerprint(geo: THREE.BufferGeometry | null | undefined): string {
  try {
    if (!geo) return 'geo=null';
    const proto = Object.getPrototypeOf(geo) as object | null;
    const ownCopy = proto ? Object.prototype.hasOwnProperty.call(proto, 'copy') : false;
    const idx = geo.index;
    const head = `${geo.constructor?.name ?? '?'}(isBG=${!!(geo as any).isBufferGeometry},ownCopy=${ownCopy},idx=${idx ? `${idx.array?.constructor?.name ?? '?'}#${idx.count}` : 'null'})`;
    const attrs: string[] = [];
    const bag = (geo.attributes ?? {}) as Record<string, any>;
    for (const name of Object.keys(bag)) {
      const a = bag[name];
      if (!a) { attrs.push(`${name}:null!`); continue; }
      attrs.push(`${name}:${a.constructor?.name ?? typeof a}{isBA=${!!a.isBufferAttribute},isIBA=${!!a.isInterleavedBufferAttribute},clone=${typeof a.clone},arr=${a.array?.constructor?.name ?? (a.data ? 'interleaved' : '?')},sz=${a.itemSize},n=${a.count}}`);
    }
    return `${head}[${attrs.join(',')}]`;
  } catch (e) {
    return `fingerprint-fail:${(e as Error)?.message ?? e}`;
  }
}

/** 指纹里的异常点（没有就返回 null） */
function badReason(fp: string): string | null {
  if (fp.includes('geo=null') || fp.includes('fingerprint-fail')) return '部件几何体异常';
  if (fp.includes('isBG=false')) return '不是真正的 BufferGeometry';
  if (/clone=(?!function)/.test(fp)) return 'attribute 缺少 clone 方法';
  if (/isBA=false,isIBA=false/.test(fp)) return 'attribute 不是 BufferAttribute';
  if (/arr=\?/.test(fp)) return 'attribute 没有 array 数据';
  return null;
}

/**
 * 手工把几何体拷成非索引几何体：只读源对象的 array/itemSize/normalized 等数据属性，
 * 不调 clone/toNonIndexed 等方法 —— 彻底躲开真机上「某个对象没有 clone」的引擎差异。
 * 逻辑与 BufferGeometry.toNonIndexed 等价（含 InterleavedBufferAttribute 分支）。
 */
export function copyGeometry(geo: THREE.BufferGeometry): THREE.BufferGeometry {
  const g = new THREE.BufferGeometry();
  const idxArr = geo.index ? (geo.index.array as unknown as ArrayLike<number>) : null;
  const bag = geo.attributes as Record<string, any>;
  for (const name of Object.keys(bag)) {
    const a = bag[name];
    const itemSize: number = a.itemSize;
    let dst: any;
    if (a.isInterleavedBufferAttribute) {
      const n = idxArr ? idxArr.length : (a.count as number);
      dst = new Float32Array(n * itemSize);
      for (let i = 0; i < n; i++) {
        const s = idxArr ? idxArr[i] : i;
        for (let k = 0; k < itemSize; k++) dst[i * itemSize + k] = a.getComponent(s, k);
      }
    } else if (idxArr) {
      const src = a.array as any;
      const n = idxArr.length;
      dst = new (src.constructor)(n * itemSize);
      for (let i = 0; i < n; i++) {
        const s = idxArr[i] * itemSize;
        const d = i * itemSize;
        for (let k = 0; k < itemSize; k++) dst[d + k] = src[s + k];
      }
    } else {
      dst = a.array.slice(0);
    }
    g.setAttribute(name, new THREE.BufferAttribute(dst, itemSize, !!a.normalized));
  }
  return g;
}

/** 共享几何体缓存，避免每个实体都新建 */
export class GeoCache {
  private readonly map = new Map<string, THREE.BufferGeometry>();
  private readonly shared = new WeakSet<THREE.BufferGeometry>();

  box(w: number, h: number, d: number): THREE.BufferGeometry {
    return this.get(`b${w},${h},${d}`, () => new THREE.BoxGeometry(w, h, d));
  }
  cone(r: number, h: number, seg: number): THREE.BufferGeometry {
    return this.get(`c${r},${h},${seg}`, () => new THREE.ConeGeometry(r, h, seg));
  }
  cyl(rt: number, rb: number, h: number, seg: number): THREE.BufferGeometry {
    return this.get(`y${rt},${rb},${h},${seg}`, () => new THREE.CylinderGeometry(rt, rb, h, seg));
  }
  sphere(r: number, seg: number): THREE.BufferGeometry {
    return this.get(`s${r},${seg}`, () => new THREE.SphereGeometry(r, seg, seg));
  }
  octa(r: number): THREE.BufferGeometry {
    return this.get(`o${r}`, () => new THREE.OctahedronGeometry(r));
  }

  /** 沿 +Z 伸出、长度为 1 的细条，用于瞄准线（按 scale.z 拉长） */
  laser(): THREE.BufferGeometry {
    return this.get('laser', () => new THREE.BoxGeometry(0.16, 0.06, 1).translate(0, 0, 0.5));
  }

  /**
   * 把多个基础几何体按各自变换和颜色合并成一个带顶点色的几何体，
   * 配合 MAT.painted 一次 draw call 画完整个小模型。
   */
  merged(key: string, parts: () => PartSpec[]): THREE.BufferGeometry {
    return this.get(`m:${key}`, () => {
      const m = new THREE.Matrix4();
      const q = new THREE.Quaternion();
      const e = new THREE.Euler();
      const c = new THREE.Color();
      const diag = geoDiag();
      let specs: PartSpec[];
      try {
        specs = parts();
      } catch (err) {
        const msg = `GeoCache[${key}]parts() :: ${(err as Error)?.message ?? err}`;
        wxWrite('__tank_geo_err', `${msg}\n${(err as Error)?.stack ?? ''}`);
        const wrapped = new Error(msg);
        wrapped.stack = `${msg}\n${(err as Error)?.stack ?? ''}`;
        throw wrapped;
      }
      const crushParts: CrushPartRange[] | undefined = specs.some(p => p.crush !== undefined) ? [] : undefined;
      const surfaced = specs.some(p => p.surf !== undefined);
      let vertexOffset = 0;
      const list = specs.map(({ geo, color, pos = [0, 0, 0], rot = [0, 0, 0], scale = [1, 1, 1], crush = 0, surf = 0 }, pi) => {
        diag.scanned++;
        if (!diag.keys.includes(key)) diag.keys.push(key);
        const fp = fingerprint(geo);
        if (!diag.sample) diag.sample = `${key}#${pi} ${fp}`.slice(0, 400);
        const cn = (geo as any)?.constructor?.name ?? '?';
        diag.ctors[cn] = (diag.ctors[cn] ?? 0) + 1;
        const bad = badReason(fp);
        if (bad) {
          diag.bad.push(`${key}#${pi} ${bad} ${fp}`.slice(0, 400));
          flushGeoDiag();
          console.warn(`[GeoCache] 部件异常 ${key}#${pi}: ${bad} ${fp}`);
        }
        try {
          // 统一转成非索引几何，基础体和自定义体（棱台、车床体）才能合并；
          // 手工拷贝代替 toNonIndexed/clone（真机 clone 路径踩过引擎差异，见 __tank_geo）
          const g = copyGeometry(geo);
          geo.dispose();
          if (!g.getAttribute('uv')) g.setAttribute('uv', new THREE.BufferAttribute(new Float32Array(g.getAttribute('position').count * 2), 2));
          g.applyMatrix4(m.compose(new THREE.Vector3(...pos), q.setFromEuler(e.set(...rot)), new THREE.Vector3(...scale)));
          c.setHex(color);
          const n = g.getAttribute('position').count;
          if (crushParts) {
            g.computeBoundingBox();
            const b = g.boundingBox!;
            crushParts.push({ start: vertexOffset, count: n, role: crush, pivot: [
              (b.min.x + b.max.x) / 2, (b.min.y + b.max.y) / 2, (b.min.z + b.max.z) / 2,
            ] });
          }
          vertexOffset += n;
          const colors = new Float32Array(n * 3);
          for (let i = 0; i < n; i++) colors.set([c.r, c.g, c.b], i * 3);
          g.setAttribute('color', new THREE.BufferAttribute(colors, 3));
          if (surfaced) g.setAttribute('surf', new THREE.BufferAttribute(new Float32Array(n).fill(surf), 1));
          return g;
        } catch (err) {
          const msg = `GeoCache[${key}]part#${pi} ${fp} :: ${(err as Error)?.message ?? err}`;
          wxWrite('__tank_geo_err', `${msg}\n${(err as Error)?.stack ?? ''}`);
          const wrapped = new Error(msg);
          wrapped.stack = `${msg}\n${(err as Error)?.stack ?? ''}`;
          throw wrapped;
        }
      });
      flushGeoDiag();
      const out = mergeGeometries(list, false);
      for (const g of list) g.dispose();
      if (!out) throw new Error(`合并几何体失败: ${key}`);
      if (crushParts) out.userData.crushParts = crushParts;
      return out;
    });
  }

  get(key: string, make: () => THREE.BufferGeometry): THREE.BufferGeometry {
    let g = this.map.get(key);
    if (!g) {
      g = make();
      this.map.set(key, g);
      this.shared.add(g);
    }
    return g;
  }

  /** 这个几何体是不是缓存里的（共享的，用的人不能自己 dispose） */
  owns(g: THREE.BufferGeometry): boolean {
    return this.shared.has(g);
  }

  /** 换画质后旧的那套不用了：移出缓存、释放显存（还在用它的网格下次画时会重新上传，不出错） */
  drop(g: THREE.BufferGeometry): void {
    for (const [k, v] of this.map) if (v === g) this.map.delete(k);
    this.shared.delete(g);
    g.dispose();
  }

  dispose(): void {
    for (const g of this.map.values()) g.dispose();
    this.map.clear();
  }
}
