import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { copyGeometry } from '../GeoCache';
import { frustum, type V2, type V3 } from '../ModelKit';

/**
 * 直升机建模工具（T095 起；T096 换成地面坦克那套建模语言）：硬放样机身（平板 + 倒角）、框架座舱、倒角方块、方条、带「玻璃」标记的合并。
 * 机身材质（vulture.ts 的 vultureSkin）按 aGlass 区分：0 = 钢板（受光 / 背光 / 轮廓光三层），1 = 座舱玻璃（深色 + 天空反光 + 一道高光）
 */
export interface HeliPart {
  geo: THREE.BufferGeometry;
  color: number;
  pos?: [number, number, number];
  rot?: [number, number, number];
  scale?: [number, number, number];
  glass?: boolean;
}

/**
 * 硬放样截面（T096，照地面坦克的棱台装甲）：机头朝 +Z。y = 腰线高、w = 腰线半宽（最宽处）；
 * 上半截 top 高、顶面半宽 wt、顶角倒角 ct；下半截 bot 深、底面半宽 wb、底角倒角 cb
 */
export interface Plate {
  z: number;
  y: number;
  w: number;
  top: number;
  bot: number;
  wt: number;
  wb: number;
  ct?: number;
  cb?: number;
}

/** 截面一圈 10 个点（从右腰线起逆时针：右上斜板 → 顶面 → 左上斜板 → 左腰线 → 左下斜板 → 底面 → 右下斜板） */
export function plateRing(s: Plate): V2[] {
  const ct = s.ct ?? Math.min(s.wt, s.top) * 0.22;
  const cb = s.cb ?? Math.min(s.wb, s.bot) * 0.18;
  const yt = s.y + s.top;
  const yb = s.y - s.bot;
  return [
    [s.w, s.y], [s.wt, yt - ct], [s.wt - ct, yt], [-(s.wt - ct), yt], [-s.wt, yt - ct],
    [-s.w, s.y], [-s.wb, yb + cb], [-(s.wb - cb), yb], [s.wb - cb, yb], [s.wb, yb + cb],
  ];
}

/** 截面在 z 处的插值（挂件贴着机身放用） */
export function plateAt(secs: Plate[], z: number): Plate {
  for (let i = 0; i < secs.length - 1; i++) {
    const a = secs[i];
    const b = secs[i + 1];
    if ((z <= a.z && z >= b.z) || (z >= a.z && z <= b.z)) {
      const t = (z - a.z) / (b.z - a.z || 1);
      const l = (p: number, q: number) => p + (q - p) * t;
      return { z, y: l(a.y, b.y), w: l(a.w, b.w), top: l(a.top, b.top), bot: l(a.bot, b.bot), wt: l(a.wt, b.wt), wb: l(a.wb, b.wb), ct: l(a.ct ?? 0.2, b.ct ?? 0.2), cb: l(a.cb ?? 0.15, b.cb ?? 0.15) };
    }
  }
  return z > secs[0].z ? secs[0] : secs[secs.length - 1];
}

/**
 * 硬放样（T096）：相邻截面连成一块块平板，两头平板封口，法线按面算——和坦克车体、炮塔的棱台一样棱角分明，没有大曲面。
 * 贴图 4 米一格（和 ModelKit.frustum 一样，迷彩贴图对得上）
 */
export function plates(secs: Plate[], caps = true): THREE.BufferGeometry {
  const pos: number[] = [];
  const uv: number[] = [];
  const idx: number[] = [];
  const rings = secs.map(plateRing);
  const n = rings[0].length;
  const ring = n + 1;
  const z0 = secs[0].z;
  secs.forEach((s, k) => {
    let per = 0;
    for (let i = 0; i <= n; i++) {
      const [x, y] = rings[k][i % n];
      if (i) per += Math.hypot(x - rings[k][i - 1][0], y - rings[k][i - 1][1]);
      pos.push(x, y, s.z);
      uv.push(per / 4, Math.abs(s.z - z0) / 4);
    }
  });
  // 截面从前往后排、每圈逆时针：法线朝外
  for (let k = 0; k < secs.length - 1; k++) {
    for (let i = 0; i < n; i++) {
      const a = k * ring + i;
      const b = a + ring;
      idx.push(a, b, a + 1, a + 1, b, b + 1);
    }
  }
  if (caps) {
    for (const [k, flip] of [[0, false], [secs.length - 1, true]] as const) {
      const c = pos.length / 3;
      pos.push(0, secs[k].y, secs[k].z);
      uv.push(0, 0);
      for (let i = 0; i < n; i++) {
        const a = k * ring + i;
        if (flip) idx.push(c, a + 1, a);
        else idx.push(c, a, a + 1);
      }
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  g.setIndex(idx);
  return facet(g);
}

/** 方条：从 a 到 b、截面 w × h 的细长方块（窗框、撑杆、起落架管） */
export function bar(a: V3, b: V3, w: number, h = w): THREE.BufferGeometry {
  const va = new THREE.Vector3(...a);
  const vb = new THREE.Vector3(...b);
  const g = new THREE.BoxGeometry(w, h, va.distanceTo(vb));
  const up = Math.abs(vb.y - va.y) > 0.98 * va.distanceTo(vb) ? new THREE.Vector3(0, 0, 1) : new THREE.Vector3(0, 1, 0);
  g.applyMatrix4(new THREE.Matrix4().lookAt(vb, va, up));
  g.translate((va.x + vb.x) / 2, (va.y + vb.y) / 2, (va.z + vb.z) / 2);
  return g;
}

/**
 * 框架式座舱（T096）：玻璃罩是一个棱台（底圈 / 顶圈两个倒角矩形，点为 [x, z]），块块平板玻璃；每条斜棱、顶圈每条边一根方条窗框，前挡风中间一根竖框
 */
export function canopy(bottom: V2[], top: V2[], h: number, y0: number, glass: number, frame: number, t = 0.07): HeliPart[] {
  const p: HeliPart[] = [{ geo: frustum(bottom, top, h, y0), color: glass, glass: true }];
  const n = bottom.length;
  const B = (i: number): V3 => [bottom[i % n][0], y0, bottom[i % n][1]];
  const T = (i: number): V3 => [top[i % n][0], y0 + h, top[i % n][1]];
  for (let i = 0; i < n; i++) {
    p.push({ geo: bar(B(i), T(i), t), color: frame });
    p.push({ geo: bar(T(i), T(i + 1), t), color: frame });
  }
  // 前挡风竖框：前沿（z 最大的那条边）的中点从底到顶
  let f = 0;
  for (let i = 0; i < n; i++) if (bottom[i][1] + bottom[(i + 1) % n][1] > bottom[f][1] + bottom[(f + 1) % n][1]) f = i;
  const mid = (a: V3, b: V3): V3 => [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2, (a[2] + b[2]) / 2];
  p.push({ geo: bar(mid(B(f), B(f + 1)), mid(T(f), T(f + 1)), t), color: frame });
  return p;
}

/** 一组零件整体摆到 pos、转 rot（各件先按自己的 pos / rot / scale 摆好，再一起变换；左右镜像的装甲板 + 铆钉用） */
export function place(parts: HeliPart[], pos: V3, rot: V3 = [0, 0, 0]): HeliPart[] {
  const M = new THREE.Matrix4().compose(new THREE.Vector3(...pos), new THREE.Quaternion().setFromEuler(new THREE.Euler(...rot)), new THREE.Vector3(1, 1, 1));
  const L = new THREE.Matrix4();
  return parts.map((p) => {
    p.geo.applyMatrix4(L.compose(new THREE.Vector3(...(p.pos ?? [0, 0, 0])), new THREE.Quaternion().setFromEuler(new THREE.Euler(...(p.rot ?? [0, 0, 0]))), new THREE.Vector3(...(p.scale ?? [1, 1, 1]))));
    p.geo.applyMatrix4(M);
    return { geo: p.geo, color: p.color, glass: p.glass };
  });
}

/**
 * 分块装甲板（T096，照泰坦的叠层裙板）：一块倒角钢板（厚 t、高 h、长 d，外表面朝 +x）+ 上下两排方铆钉（每排 n 颗）。
 * 用 place() 摆到机身两侧（左边转 180°）
 */
export function armorPlate(t: number, h: number, d: number, color: number, rivet: number, n: number, rs = 0.07): HeliPart[] {
  const p: HeliPart[] = [{ geo: chamferBox(t, h, d, Math.min(0.05, t * 0.35)), color }];
  for (let i = 0; i < n; i++) {
    const z = -d / 2 + 0.16 + (i * (d - 0.32)) / Math.max(1, n - 1);
    for (const y of [h / 2 - 0.1, -h / 2 + 0.1]) p.push({ geo: new THREE.BoxGeometry(rs, rs, rs), color: rivet, pos: [t / 2 + rs * 0.3, y, z] });
  }
  return p;
}

/** 倒角方块（所有棱都切一刀，棱上亮一道，看得出钢板厚度） */
export function chamferBox(w: number, h: number, d: number, c = Math.min(w, h, d) * 0.18): THREE.BufferGeometry {
  const x = w / 2 - c;
  const y = h / 2 - c;
  const k = Math.min(c, x * 0.9, y * 0.9);
  const s = new THREE.Shape();
  s.moveTo(-x + k, -y);
  s.lineTo(x - k, -y);
  s.lineTo(x, -y + k);
  s.lineTo(x, y - k);
  s.lineTo(x - k, y);
  s.lineTo(-x + k, y);
  s.lineTo(-x, y - k);
  s.lineTo(-x, -y + k);
  s.closePath();
  const depth = Math.max(0.001, d - 2 * c);
  const g = new THREE.ExtrudeGeometry(s, { depth, bevelEnabled: true, bevelThickness: c, bevelSize: c, bevelSegments: 1, curveSegments: 1 });
  g.translate(0, 0, -depth / 2);
  return g;
}

/** 管子：从 a 到 b 的圆柱（外露管线 / 支柱） */
export function pipe(a: [number, number, number], b: [number, number, number], r: number, seg = 6): THREE.BufferGeometry {
  const va = new THREE.Vector3(...a);
  const vb = new THREE.Vector3(...b);
  const len = va.distanceTo(vb);
  const g = new THREE.CylinderGeometry(r, r, len, seg);
  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), vb.clone().sub(va).normalize());
  g.applyQuaternion(q);
  const m = va.add(vb).multiplyScalar(0.5);
  g.translate(m.x, m.y, m.z);
  return g;
}

/** 合并成一个带顶点色 + aGlass 的几何体（一次绘制） */
export function mergeHeli(key: string, parts: HeliPart[]): THREE.BufferGeometry {
  const m = new THREE.Matrix4();
  const q = new THREE.Quaternion();
  const e = new THREE.Euler();
  const c = new THREE.Color();
  const list = parts.map((p) => {
    const g = copyGeometry(p.geo);
    p.geo.dispose();
    for (const name of Object.keys(g.attributes)) if (name !== 'position' && name !== 'normal' && name !== 'uv') g.deleteAttribute(name);
    const n = g.getAttribute('position').count;
    if (!g.getAttribute('uv')) g.setAttribute('uv', new THREE.BufferAttribute(new Float32Array(n * 2), 2));
    if (!g.getAttribute('normal')) g.computeVertexNormals();
    g.applyMatrix4(m.compose(new THREE.Vector3(...(p.pos ?? [0, 0, 0])), q.setFromEuler(e.set(...(p.rot ?? [0, 0, 0]))), new THREE.Vector3(...(p.scale ?? [1, 1, 1]))));
    c.setHex(p.color);
    const col = new Float32Array(n * 3);
    const gl = new Float32Array(n);
    for (let i = 0; i < n; i++) {
      col.set([c.r, c.g, c.b], i * 3);
      gl[i] = p.glass ? 1 : 0;
    }
    g.setAttribute('color', new THREE.BufferAttribute(col, 3));
    g.setAttribute('aGlass', new THREE.BufferAttribute(gl, 1));
    return g;
  });
  const out = mergeGeometries(list, false);
  for (const g of list) g.dispose();
  if (!out) throw new Error(`合并几何体失败: ${key}`);
  return out;
}

/** 拆成每个面各自的法线（多面体玻璃 / 硬棱整流罩用：一块块平面各亮各的） */
export function facet(g: THREE.BufferGeometry): THREE.BufferGeometry {
  const f = copyGeometry(g);
  g.dispose();
  f.deleteAttribute('normal');
  f.computeVertexNormals();
  return f;
}

/** 截面的一圈箍（硬放样两圈、不封口，比机身外扩 out）：板缝 / 识别带 */
export function plateBand(s: Plate, width: number, out = 0.03): THREE.BufferGeometry {
  const a: Plate = { ...s, z: s.z + width / 2, w: s.w + out, wt: s.wt + out, wb: s.wb + out, top: s.top + out, bot: s.bot + out };
  return plates([a, { ...a, z: s.z - width / 2 }], false);
}
