import * as THREE from 'three';
import { MAT } from '../assets/materials';
import { sceneryMaterial } from '../assets/sceneryMaterial';
import { SCN_MAT } from './sceneryDetail';
import { houseFracture, houseNoise, type HouseChunk } from '../assets/models/houseFracture';
import { houseRoofHeight, houseStyle } from '../assets/models/houseStyles';
import type { Handle, Scenery, ScnItem } from './Scenery';

interface Motion {
  time: number;
  delay: number;
  duration: number;
  rise: number;
  to: THREE.Vector3;
  rotation: THREE.Quaternion;
}
interface Chunk extends HouseChunk {
  loose: boolean;
  motion: Motion | null;
}
interface Breach {
  point: THREE.Vector3;
  normal: THREE.Vector3;
  radius: number;
  height: number;
  roof: boolean;
}
interface House {
  mesh: THREE.Mesh;
  chunks: Chunk[];
  positions: Float32Array;
  normals: Float32Array;
  pigment: Float32Array;
  breaches: Breach[];
  hidden: Handle | null;
  tint: number;
}

/** 只管显示。结构值、挡弹、倒塌伤害和奖励仍由 SceneryDamage 结算。 */
export class HouseDamage {
  private readonly houses = new Map<ScnItem, House>();
  private readonly moving = new Set<ScnItem>();
  private readonly hidden = new THREE.Matrix4().makeScale(0, 0, 0);
  private readonly q = new THREE.Quaternion();
  private readonly v = new THREE.Vector3();
  private readonly up = new THREE.Vector3(0, 1, 0);
  private readonly identity = new THREE.Quaternion();
  /** 同时最多八栋播碎块运动，其余直接摆到落定位置；洞口不会因额度回收而补上。 */
  private readonly maxMoving = 8;

  constructor(private readonly scn: Scenery) {}

  private get(it: ScnItem): House {
    let h = this.houses.get(it);
    if (h) return h;
    const model = houseFracture(it.id, it.look);
    const mesh = new THREE.Mesh(model.geometry, model.geometry.getAttribute('surf') && SCN_MAT ? sceneryMaterial() : MAT.painted);
    mesh.name = 'house-fracture';
    mesh.castShadow = mesh.receiveShadow = true;
    h = {
      mesh, chunks: model.chunks.map(p => ({ ...p, loose: false, motion: null })),
      positions: new Float32Array(model.geometry.getAttribute('position').array),
      normals: new Float32Array(model.geometry.getAttribute('normal').array),
      pigment: new Float32Array(model.geometry.getAttribute('color').array),
      breaches: [], hidden: null, tint: NaN,
    };
    this.houses.set(it, h);
    this.scn.group.add(mesh);
    this.sync(it);
    return h;
  }

  /** 保留原实例槽位和池容量，只把它隐藏；回收仍走原来的句柄。 */
  sync(it: ScnItem): boolean {
    const h = this.houses.get(it);
    if (!h) return false;
    if (it.main) it.main.pool.set(it.main, this.hidden);
    h.hidden = it.main;
    h.mesh.position.set(it.x, it.y, it.z);
    h.mesh.rotation.y = it.rot;
    h.mesh.scale.setScalar(it.s);
    this.tint(it, h);
    return true;
  }

  private tint(it: ScnItem, h: House): void {
    if (h.tint === it.tint) return;
    const color = h.mesh.geometry.getAttribute('color') as THREE.BufferAttribute;
    for (let i = 0; i < h.pigment.length; i++) color.array[i] = h.pigment[i] * it.tint;
    color.needsUpdate = true;
    h.tint = it.tint;
  }

  private local(it: ScnItem, x: number, y: number, z: number): THREE.Vector3 {
    const c = Math.cos(it.rot), s = Math.sin(it.rot);
    return new THREE.Vector3(((x - it.x) * c - (z - it.z) * s) / it.s, y, ((x - it.x) * s + (z - it.z) * c) / it.s);
  }

  /** 命中点附近的墙块脱落；重复命中扩大同一个缺口，离开的旧洞永久保留。 */
  hit(it: ScnItem, x: number, z: number, size: number, y: number, roof = false, cut = false, vertical = false): void {
    const h = this.get(it), point = this.local(it, x, y, z);
    const normal = new THREE.Vector3();
    if (roof) {
      point.x = THREE.MathUtils.clamp(point.x, -3.5, 3.5);
      point.z = THREE.MathUtils.clamp(point.z, -2.8, 2.8);
      point.y = houseRoofHeight(houseStyle(it.look), point.x, point.z);
      normal.set(0, 1, 0);
    } else if (Math.abs(point.x) / 3.5 > Math.abs(point.z) / 2.8) {
      normal.x = Math.sign(point.x) || 1;
      point.x = normal.x * 3.5;
      point.z = THREE.MathUtils.clamp(point.z, -2.8, 2.8);
    } else {
      normal.z = Math.sign(point.z) || 1;
      point.z = normal.z * 2.8;
      point.x = THREE.MathUtils.clamp(point.x, -3.5, 3.5);
    }
    let breach = h.breaches.find(b => b.roof === roof && b.normal.dot(normal) > .9 && b.point.distanceTo(point) < .9);
    const radius = size * (cut && vertical ? .24 : .62);
    const height = size * (cut ? (vertical ? .65 : .2) : .56);
    if (breach) {
      breach.radius = Math.min(2.8, Math.hypot(breach.radius, radius * .65));
      breach.height = Math.min(2.6, Math.hypot(breach.height, height * .65));
    } else {
      breach = { point, normal, radius, height, roof };
      h.breaches.push(breach);
    }
    const animate = this.canAnimate(it);
    for (const p of h.chunks) {
      if (p.loose || (roof ? p.part !== 'roof' : p.part !== 'wall')) continue;
      const dx = p.center.x - breach.point.x, dy = p.center.y - breach.point.y, dz = p.center.z - breach.point.z;
      const along = dx * normal.x + dz * normal.z;
      const across = dx * normal.z - dz * normal.x;
      const d = roof ? Math.hypot(dx, dz) / breach.radius
        : Math.sqrt((across / breach.radius) ** 2 + (dy / breach.height) ** 2 + (along / (breach.radius * .55)) ** 2);
      if (d < 1.05) this.detach(it, h, p, animate, 0, .8);
    }
    // 断口周围的白灰变暗，露出的截面已经是砖色；不把整栋房子统一染黑。
    for (let i = 0; i < h.positions.length; i += 3) {
      const dx = h.positions[i] - point.x, dy = h.positions[i + 1] - point.y, dz = h.positions[i + 2] - point.z;
      const d = roof ? Math.hypot(dx, dz) : Math.hypot(dx * normal.z - dz * normal.x, dy);
      if (d > radius * 1.35 || (!roof && Math.abs(dx * normal.x + dz * normal.z) > .4)) continue;
      const shade = .72 + .28 * Math.min(1, d / (radius * 1.35));
      for (let k = 0; k < 3; k++) h.pigment[i + k] *= shade;
    }
    h.tint = NaN;
    this.tint(it, h);
    this.flush(h);
  }

  /** 到原有半塌阈值，缺口向上贯通；失去这侧支撑的屋顶和梁随后落下。 */
  partial(it: ScnItem, x: number, z: number, top: boolean, instant: boolean): void {
    const h = this.get(it);
    const contact = this.local(it, x, 1.4, z), normal = new THREE.Vector3();
    if (top) normal.y = 1;
    else if (Math.abs(contact.x) / 3.5 > Math.abs(contact.z) / 2.8) {
      normal.x = Math.sign(contact.x) || 1;
      contact.x = normal.x * 3.5;
    } else {
      normal.z = Math.sign(contact.z) || 1;
      contact.z = normal.z * 2.8;
    }
    contact.x = THREE.MathUtils.clamp(contact.x, -3.5, 3.5);
    contact.z = THREE.MathUtils.clamp(contact.z, -2.8, 2.8);
    // 穿甲弹最后记录的是出口。坍落仍从本次入口附近开始，不误选背墙或之前的屋顶洞。
    let hit: Breach | undefined, nearest = 4;
    for (const b of h.breaches) {
      if (b.roof !== top || b.normal.dot(normal) < .9) continue;
      const d = (b.point.x - contact.x) ** 2 + (b.point.z - contact.z) ** 2;
      if (d < nearest) { nearest = d; hit = b; }
    }
    const point = hit?.point ?? contact;
    const n = hit?.normal ?? normal;
    const animate = !instant && this.canAnimate(it);
    for (const p of h.chunks) {
      if (p.loose || p.part === 'base') continue;
      const dx = p.center.x - point.x, dz = p.center.z - point.z;
      let unsupported: boolean;
      if (top) unsupported = p.part !== 'wall' && Math.hypot(dx, dz) < 3.1;
      else if (p.part === 'wall') {
        const depth = Math.abs(dx * n.x + dz * n.z);
        const across = Math.abs(dx * n.z - dz * n.x);
        unsupported = depth < .8 && across < 1.5 + p.center.y * .16 && p.center.y > .65;
      } else {
        // 侧墙承托同侧屋面；端墙缺口则带下房屋这一端，两侧未受击的墙仍站着。
        unsupported = Math.abs(n.x) > .5 ? Math.abs(dx) < 2.4
          : Math.abs(dx) < 2.2 && (p.part === 'beam' || p.center.z * n.z > -.2);
      }
      if (unsupported) this.detach(it, h, p, animate, p.part === 'wall' ? .02 : .16, .55);
    }
    this.flush(h);
  }

  /** 起火或冲击波掀顶也沿用现有缺口，不能换壳后把墙补回去。 */
  shell(it: ScnItem, instant: boolean): void {
    const h = this.get(it), animate = !instant && this.canAnimate(it);
    for (const p of h.chunks) if (p.part === 'roof' || p.part === 'beam') this.detach(it, h, p, animate, .1, .55);
    this.sync(it);
    this.flush(h);
  }

  collapse(it: ScnItem, instant: boolean): void {
    const h = this.get(it), animate = !instant && this.canAnimate(it);
    for (const p of h.chunks) {
      if (p.part === 'base' || (p.part === 'wall' && p.center.y < .95 && houseNoise(p.start + it.id) < .6)) continue;
      this.detach(it, h, p, animate, p.part === 'wall' ? .02 : .18, 1);
    }
    this.sync(it);
    this.flush(h);
  }

  private canAnimate(it: ScnItem): boolean {
    return this.scn.visible(it.x, it.z) && (this.moving.has(it) || this.moving.size < this.maxMoving);
  }

  private detach(it: ScnItem, h: House, p: Chunk, animate: boolean, delay: number, force: number): void {
    if (p.loose) return;
    p.loose = true;
    const seed = it.id * 313 + p.start;
    const r = houseNoise(seed), r2 = houseNoise(seed + 11);
    const wall = p.part === 'wall';
    const to = p.center.clone();
    if (wall) {
      to.addScaledVector(p.normal, (.55 + r * 1.05) * force);
      to.x += (r2 - .5) * .5;
      to.z += (houseNoise(seed + 21) - .5) * .5;
    } else {
      to.x = to.x * .78 + (r - .5) * 1.2;
      to.z = to.z * .75 + (r2 - .5) * 1.2;
    }
    const rotation = new THREE.Quaternion().setFromUnitVectors(p.normal, this.up);
    rotation.premultiply(this.q.setFromAxisAngle(this.up, (r - .5) * 1.8));
    rotation.premultiply(this.q.setFromAxisAngle(this.v.set(1, 0, 0), (r2 - .5) * .3));
    let low = Infinity;
    for (let i = p.start * 3; i < (p.start + p.count) * 3; i += 3) {
      this.v.set(h.positions[i], h.positions[i + 1], h.positions[i + 2]).sub(p.center).applyQuaternion(rotation);
      low = Math.min(low, this.v.y);
    }
    const c = Math.cos(it.rot), s = Math.sin(it.rot);
    const ground = (this.scn.groundAt(it.x + (to.x * c + to.z * s) * it.s, it.z + (-to.x * s + to.z * c) * it.s) - it.y) / it.s;
    const onFloor = Math.abs(to.x) < 3.6 && Math.abs(to.z) < 2.9;
    to.y = Math.max(ground, onFloor ? .4 : ground) - low + .025 + (wall ? .03 : .12 + r * .32);
    const rise = wall ? .8 + r * .6 : .15;
    const duration = (rise + Math.sqrt(rise * rise + 32 * Math.max(0, p.center.y - to.y))) / 16;
    const motion: Motion = { time: 0, delay: delay + r2 * .08, duration: Math.max(.18, duration), rise, to, rotation };
    if (animate) {
      p.motion = motion;
      this.moving.add(it);
    } else this.pose(h, p, motion, 1);
  }

  /** 固定起点的抛物线和重力下落；落地后停止更新顶点。 */
  private pose(h: House, p: Chunk, m: Motion, k: number): void {
    const t = Math.min(k, 1) * m.duration;
    const x = p.center.x + (m.to.x - p.center.x) * Math.min(k, 1);
    const z = p.center.z + (m.to.z - p.center.z) * Math.min(k, 1);
    const y = k < 1 ? Math.max(m.to.y, p.center.y + m.rise * t - 8 * t * t) : m.to.y;
    this.q.slerpQuaternions(this.identity, m.rotation, Math.min(1, k * 1.25));
    const position = h.mesh.geometry.getAttribute('position') as THREE.BufferAttribute;
    const normal = h.mesh.geometry.getAttribute('normal') as THREE.BufferAttribute;
    for (let i = p.start; i < p.start + p.count; i++) {
      const j = i * 3;
      this.v.set(h.positions[j], h.positions[j + 1], h.positions[j + 2]).sub(p.center).applyQuaternion(this.q);
      position.setXYZ(i, this.v.x + x, this.v.y + y, this.v.z + z);
      this.v.set(h.normals[j], h.normals[j + 1], h.normals[j + 2]).applyQuaternion(this.q);
      normal.setXYZ(i, this.v.x, this.v.y, this.v.z);
    }
  }

  private flush(h: House): void {
    h.mesh.geometry.getAttribute('position').needsUpdate = true;
    h.mesh.geometry.getAttribute('normal').needsUpdate = true;
  }

  update(dt: number): void {
    for (const [it, h] of this.houses) {
      if (h.hidden !== it.main) this.sync(it);
      this.tint(it, h);
    }
    for (const it of this.moving) {
      const h = this.houses.get(it)!;
      let active = false;
      for (const p of h.chunks) {
        const m = p.motion;
        if (!m) continue;
        m.time += dt;
        const k = this.scn.visible(it.x, it.z) ? Math.max(0, (m.time - m.delay) / m.duration) : 1;
        if (k > 0) this.pose(h, p, m, k);
        if (k >= 1) p.motion = null;
        else active = true;
      }
      this.flush(h);
      if (!active) this.moving.delete(it);
    }
  }

  forget(it: ScnItem): void {
    const h = this.houses.get(it);
    if (!h) return;
    h.mesh.removeFromParent();
    h.mesh.geometry.dispose();
    this.houses.delete(it);
    this.moving.delete(it);
  }

  reset(): void {
    for (const it of this.houses.keys()) this.forget(it);
  }

  describe(it: ScnItem) {
    const h = this.houses.get(it);
    return h ? {
      chunks: h.chunks.length, loose: h.chunks.filter(p => p.loose).length,
      moving: h.chunks.filter(p => p.motion).length, vertices: h.positions.length / 3,
      holes: h.breaches.map(b => ({ at: b.point.toArray(), radius: b.radius, roof: b.roof })),
    } : null;
  }

  stats() { return { houses: this.houses.size, moving: this.moving.size, draws: this.houses.size * 2 }; }
}
