import * as THREE from 'three';
import type { GeoCache, PartSpec } from '../assets/GeoCache';
import { MAT } from '../assets/materials';
import type { Enemy, EnemyController, EnemyKind, EnemySpec } from '../entities/Enemy';
import type { SandEvent } from '../game/Director';
import { rng } from '../game/rng';
import type { Fx } from '../render/Fx';
import { groundTexture } from '../render/textures';
import type { Hazards } from './Hazards';

/**
 * 区域 6「沙漠油井」的沙下伏兵（T122，D3 区域 6 策划 1.3 节）：沙子鼓包 = 下面是伏兵的掩体坑（盖板 + 帆布，盖了沙），不是人被埋在沙里。
 * 三种：小包（步枪兵 3 + 反坦克兵 1）/ 黑烟包（一辆轻坦或一门反坦克炮，排气冒两股黑烟）/ 沙浪（沙下车队：一条沙脊顺着路肩迎面跑过来）。
 * 鼓包本身是一个「部件」敌人（controller = 这里）：自动瞄准、副武器照常打它，打到掀开值（乘血量倍率）= 提前掀出来；坦克碾过去、8 米内有爆炸也直接掀。
 * 提前掀出来：小包里 4 个人全部倒下（算击毁），车被顶翻剩 30% 耐久、2 秒不能开火；废铁多一半（碾的翻倍）。不管它：到时间盖板翻开、满编的兵 / 车钻出来从侧面打你
 */
export const AMBUSH = {
  small: { r: 1.7, h: 0.75, rise: 1.6, hp: 30, threat: 3, armor: 'none' as const },
  smoke: { r: 2.5, h: 1.1, rise: 2.2, hp: 80, threat: 4.5, armor: 'light' as const },
  /** 沙浪：宽 w、长 len、高 h，车前 start 米起跑、每秒 speed 米迎着你，run 秒后（或离你 pop 米）在侧前方钻出来；x = 沿哪条路肩跑 */
  wave: { w: 4, len: 14, h: 1.5, speed: 9, start: 75, run: 4, pop: 20, hp: 120, threat: 5, x: 11.5 },
  /** 摆在哪：离你横向 lat 米、离路中心不超过 road 米、车前 ahead 米 */
  lat: [5, 13] as [number, number],
  road: 15,
  ahead: [32, 50] as [number, number],
  /** 8 米内有爆炸直接掀；坦克中心进到 半径 + crush 米 = 碾过去 */
  blast: 8,
  crush: 1.4,
  /** 提前掀出来的车剩多少耐久、几秒不能开火、掀起几度；废铁多拿几成（碾的翻倍） */
  left: 0.3,
  stun: 2,
  toss: 45,
  scrap: 0.5,
  /** 一串：同一侧 n 个小包，前后隔 gap 米，一个比一个晚 lag 秒冒 */
  string: { n: 3, gap: 6, lag: 0.4 },
  /** 掀开以后盖板翻起来、坑留多久（秒） */
  open: 3,
  /** 150 秒的大沙浪：相对坦克（横向按起跑那一刻坦克的位置）从 from 斜着冲到 to（米，dur 秒），宽 w、长 len；从车底下过去那一下车身顶起来 */
  surge: { from: [-17, -70] as [number, number], to: [6, 12] as [number, number], dur: 3.4, w: 7, len: 26, h: 1.6 },
};

/** 每局第一次各弹一次的教学提示（左侧提示条，≤ 16 字） */
export const TUT = ['沙子鼓包，先打它', '冒黑烟的是车，先打它', '爆炸能把伏兵震出来', '沙浪底下是车队，打浪头'];

export type MoundKind = 'small' | 'smoke' | 'wave';
type How = 'emerge' | 'shot' | 'blast' | 'crush';

interface Mound {
  kind: MoundKind;
  x: number;
  z: number;
  /** 冒出来多久了（负 = 一串里还没轮到它） */
  t: number;
  e: Enemy | null;
  side: number;
  load: EnemyKind[];
  /** 掀开以后过了几秒（−1 = 还没掀） */
  open: number;
  how: How | null;
  /** 一串的编号（一串算一处） */
  group: number;
  yaw: number;
}

/** Game 给的钩子 */
export interface AmbushCtx {
  /** 鼓包的部件敌人（spawnPart） */
  part(spec: EnemySpec, x: number, z: number): Enemy | null;
  /** 刷一个敌人（Game.spawnEnemy：血量按区域倍率） */
  spawn(kind: EnemyKind, x: number, z: number): Enemy | null;
  /** 提前掀出来的人当场倒下（crush = 碾的；算击毁、照常给经验 / 废铁） */
  down(e: Enemy, fromX: number, fromZ: number, crush: boolean): void;
  /** 多给的废铁 */
  scrap(x: number, z: number, n: number): void;
  /** 头顶飘黄字「掀出来」 */
  label(x: number, y: number, z: number): void;
  sfx(tone: 'explode' | 'crunch' | 'bigboom' | 'hit' | 'breach', x: number, z: number, vol?: number): void;
  shake(x: number, z: number, a: number): void;
  /** 区内秒数（90 秒以后小包里四成换一个爆破兵） */
  zoneTime(): number;
  /** 前方 a～b 米里最近的一台磕头机（44 秒那个小包贴着它冒）；没有 null */
  jackNear(z: number, a: number, b: number): { x: number; z: number } | null;
  /** 大沙浪从车底下过去：车身顶起来、余震 */
  heave(k: number): void;
  /** 大沙浪顺路拖走一件路边的油田大件 */
  swallow(x: number, z: number): void;
}

const _m = new THREE.Matrix4();
const _q = new THREE.Quaternion();
const _p = new THREE.Vector3();
const _s = new THREE.Vector3();
const _e = new THREE.Euler();
const UP = new THREE.Vector3(0, 1, 0);
const WHITE = new THREE.Color(0xffffff);
const SAND_LIT = 0xe4d2b0;

/** 鼓包：半个扁球，顶点色从坡脚的深沙到顶上的亮沙（单位大小，按半径 / 高度缩放）；T125 沙地换成浅黄沙，顶点色从橙褐换成偏灰的米色（乘贴图 = 新沙色） */
function moundGeometry(): THREE.BufferGeometry {
  const g = new THREE.SphereGeometry(1, 16, 7, 0, Math.PI * 2, 0, Math.PI / 2);
  const pos = g.getAttribute('position');
  const col = new Float32Array(pos.count * 3);
  const a = new THREE.Color(0xd2c8b8);
  const b = new THREE.Color(0xf6efe2);
  const c = new THREE.Color();
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i);
    const y = pos.getY(i);
    const z = pos.getZ(i);
    pos.setY(i, Math.max(0, y * (1 + Math.sin(x * 4.3 + z * 3.1) * 0.08) - 0.04));
    c.copy(a).lerp(b, Math.min(1, y * 1.2));
    col.set([c.r, c.g, c.b], i * 3);
  }
  g.computeVertexNormals();
  g.setAttribute('color', new THREE.BufferAttribute(col, 3));
  return g;
}

/** 伪装盖板：一块木板拼的盖子 + 一片帆布（原点在铰链那条边，掀开时绕它翻） */
function boardParts(): PartSpec[] {
  return [
    { geo: new THREE.BoxGeometry(1.8, 0.08, 1.3), color: 0x6e5a3c, pos: [0, 0.04, 0.65] },
    { geo: new THREE.BoxGeometry(1.84, 0.1, 0.12), color: 0x544430, pos: [0, 0.09, 0.3] },
    { geo: new THREE.BoxGeometry(1.84, 0.1, 0.12), color: 0x544430, pos: [0, 0.09, 1.0] },
    { geo: new THREE.BoxGeometry(1.6, 0.03, 1.1), color: 0x8a7a5a, pos: [0.1, 0.11, 0.7], rot: [0, 0.08, 0] },
  ];
}

export class Ambush implements EnemyController {
  readonly name = '沙下伏兵';
  readonly engageDist = 0;
  readonly mounds: Mound[] = [];
  private readonly mesh: THREE.InstancedMesh;
  private readonly boards: THREE.InstancedMesh;
  private readonly ridge: THREE.InstancedMesh;
  private group = 0;
  private tank = { x: 0, z: 0 };
  /** 150 秒的大沙浪：t = 跑了几秒（< 0 = 没有）、lifted = 车身顶过没有、swallowed = 拖走过没有 */
  private surge = { t: -1, lifted: false, swallowed: false, x0: 0 };

  constructor(
    scene: THREE.Scene,
    geo: GeoCache,
    private readonly fx: Fx,
    private readonly hazards: Hazards,
    private readonly ctx: AmbushCtx,
  ) {
    const sand = new THREE.MeshStandardMaterial({ vertexColors: true, map: groundTexture('sand'), roughness: 1, metalness: 0 });
    const make = (g: THREE.BufferGeometry, cap: number, mat: THREE.Material) => {
      const m = new THREE.InstancedMesh(g, mat, cap);
      m.castShadow = true;
      m.receiveShadow = true;
      m.frustumCulled = false;
      m.count = 0;
      m.visible = false;
      m.setColorAt(0, WHITE);
      scene.add(m);
      return m;
    };
    const dome = moundGeometry();
    this.mesh = make(dome, 16, sand);
    this.boards = make(geo.merged('ambush-board', boardParts), 32, MAT.painted);
    this.ridge = make(dome, 6, sand);
  }

  /** 新开一局 / 换区：场上的全收掉 */
  reset(): void {
    for (const m of this.mounds) if (m.e?.alive) m.e.kill();
    this.mounds.length = 0;
    this.surge.t = -1;
    this.sync();
  }

  /** 场上还在鼓 / 在跑的几处（一串算一处；Director 按它控「一屏最多 2 个」） */
  active(): number {
    const seen = new Set<number>();
    for (const m of this.mounds) if (m.open < 0) seen.add(m.group);
    return seen.size;
  }

  /** 已经有伏兵的那一侧（第二个一定和第一个同侧）；没有 0 */
  private sideNow(): number {
    for (const m of this.mounds) if (m.open < 0) return m.side;
    return 0;
  }

  /** 按定点表来一次（Director.hooks.ambush → Game → 这里）；tx / tz = 坦克 */
  event(ev: SandEvent, tx: number, tz: number): void {
    const side = this.sideNow() || (rng.spawn() < 0.5 ? -1 : 1);
    if (ev.both) {
      this.add('smoke', -1, tx, tz);
      this.add('smoke', 1, tx, tz);
      return;
    }
    if (ev.wave) this.add('wave', side, tx, tz);
    if (ev.string) {
      const g = ++this.group;
      const S = AMBUSH.string;
      const z0 = tz - (AMBUSH.ahead[0] + rng.spawn() * 8);
      const lat = AMBUSH.lat[0] + rng.spawn() * (AMBUSH.lat[1] - AMBUSH.lat[0]);
      for (let i = 0; i < S.n; i++) this.put('small', side, tx + side * lat, z0 - i * S.gap, -i * S.lag, g);
    }
    for (let i = 0; i < (ev.smoke ?? 0); i++) this.add('smoke', side, tx, tz, i * 9);
    for (let i = 0; i < (ev.small ?? 0); i++) {
      if (ev.near && i === 0) {
        const j = this.ctx.jackNear(tz, 36, 62);
        if (j) {
          this.put('small', Math.sign(j.x) || side, Math.sign(j.x) * AMBUSH.road * 0.97, j.z + 2, 0, ++this.group);
          continue;
        }
      }
      this.add('small', side, tx, tz, (ev.smoke ?? 0) * 9 + i * 8);
    }
  }

  /** 一个包：离你横向 lat 米（离路中心不超过 road 米）、车前 ahead 米；extra = 再往前挪几米（同一次的第二个） */
  private add(kind: MoundKind, side: number, tx: number, tz: number, extra = 0): void {
    if (kind === 'wave') {
      const W = AMBUSH.wave;
      this.put('wave', side, side * W.x, tz - W.start, 0, ++this.group);
      return;
    }
    const lat = AMBUSH.lat[0] + rng.spawn() * (AMBUSH.lat[1] - AMBUSH.lat[0]);
    this.put(kind, side, tx + side * lat, tz - (AMBUSH.ahead[0] + rng.spawn() * (AMBUSH.ahead[1] - AMBUSH.ahead[0])) - extra, 0, ++this.group);
  }

  private put(kind: MoundKind, side: number, x: number, z: number, t: number, group: number): void {
    const R = AMBUSH.road;
    const load: EnemyKind[] = kind === 'small'
      ? ['infantry', 'infantry', 'infantry', 'rocketeer']
      : kind === 'smoke'
        ? [rng.spawn() < 0.6 ? 'gunner' : 'atgun']
        : rng.spawn() < 0.5 ? ['gunner', 'gunner', 'apc'] : ['gunner', 'gunner', 'gunner'];
    // 90 秒以后四成的小包里有一个步枪兵换成爆破兵
    if (kind === 'small' && this.ctx.zoneTime() >= 90 && rng.spawn() < 0.4) load[0] = 'sapper';
    this.mounds.push({ kind, x: THREE.MathUtils.clamp(x, -R, R), z, t, e: null, side, load, open: -1, how: null, group, yaw: rng.spawn() * Math.PI * 2 });
  }

  /** 首领「穿山」阶段一的小包（T122，2.5 节）：贴着坦克一侧冒一个 */
  bossSmall(tx: number, tz: number): void {
    this.add('small', rng.spawn() < 0.5 ? -1 : 1, tx, tz);
  }

  /** 这个包的部件：耐久 = 掀开值 × 血量倍率；沙浪的判定在浪头 */
  private arm(m: Mound, hpScale: number): void {
    const K = m.kind === 'wave' ? AMBUSH.wave : AMBUSH[m.kind];
    const spec: EnemySpec = {
      hp: K.hp * hpScale, speed: 0, radius: m.kind === 'wave' ? 2.2 : AMBUSH[m.kind].r, contactDamage: 0, fireInterval: 0, shot: 'none', bulletDamage: 0, bulletSpeed: 0,
      scrap: 0, standoff: 0, crushable: false, blocker: false, fixed: true, armor: m.kind === 'small' ? 'none' : 'light', threat: K.threat,
    };
    const e = this.ctx.part(spec, m.x, m.z);
    if (!e) return;
    e.controller = this;
    m.e = e;
  }

  hpRatio(): number {
    return 1;
  }

  /** 部件被打到掀开值（Game.killEnemy）：提前掀出来 */
  onPartKilled(e: Enemy): void {
    const m = this.mounds.find((x) => x.e === e && x.open < 0);
    if (!m) return;
    m.e = null;
    this.reveal(m, 'shot');
  }

  /** 爆炸（Game.explode 每一下都转进来）：8 米内的包直接掀 */
  blast(x: number, z: number): void {
    for (const m of this.mounds) {
      if (m.open >= 0 || m.t < 0) continue;
      if (Math.hypot(m.x - x, m.z - z) <= AMBUSH.blast) this.reveal(m, 'blast');
    }
  }

  /** 150 秒的大沙浪（Director.hooks.surge） */
  startSurge(): void {
    this.surge = { t: 0, lifted: false, swallowed: false, x0: this.tank.x };
    this.ctx.sfx('breach', this.tank.x - 10, this.tank.z - 60, 0.8);
  }

  update(dt: number, tx: number, tz: number, hpScale: number): void {
    this.tank.x = tx;
    this.tank.z = tz;
    for (let i = this.mounds.length - 1; i >= 0; i--) {
      const m = this.mounds[i];
      if (m.open >= 0) {
        m.open += dt;
        if (m.open > AMBUSH.open) this.mounds.splice(i, 1);
        continue;
      }
      if (m.t < 0) {
        m.t += dt;
        continue;
      }
      if (!m.e) {
        this.arm(m, hpScale);
        // 刚鼓起来：外面一圈红细圈（敌方提示，不是伤害范围，所以没有加粗外圈和十字；T130 起红，原来白边）
        if (m.kind !== 'wave') this.hazards.marker(m.x, m.z, AMBUSH[m.kind].r + 0.8, AMBUSH[m.kind].rise + 0.3, 'hint');
      } else if (!m.e.alive) {
        // 被别处收掉了（不该发生）：当它没来过
        this.mounds.splice(i, 1);
        continue;
      }
      m.t += dt;
      // 甩到身后的不要了
      if (m.z > tz + 30) {
        if (m.e?.alive) m.e.kill();
        this.mounds.splice(i, 1);
        continue;
      }
      if (m.kind === 'wave') {
        const W = AMBUSH.wave;
        m.z += W.speed * dt;
        m.e?.group.position.set(m.x, 0, m.z);
        this.spray(m, dt);
        if (m.t >= W.run || tz - m.z <= W.pop) this.reveal(m, 'emerge');
        continue;
      }
      this.spray(m, dt);
      if (Math.hypot(m.x - tx, m.z - tz) < AMBUSH[m.kind].r + AMBUSH.crush) this.reveal(m, 'crush');
      else if (m.t >= AMBUSH[m.kind].rise) this.reveal(m, 'emerge');
    }
    if (this.surge.t >= 0) this.stepSurge(dt);
    this.sync();
  }

  /** 鼓的时候顶上冒白沙；黑烟包再冒两股排气黑烟；沙浪浪头翻沙、身后一路扬尘 */
  private spray(m: Mound, dt: number): void {
    const f = this.fx;
    if (m.kind === 'wave') {
      // 浪头翻起一道沙帘（亮沙 + 翻上来的深沙），身后一路扬尘
      const W = AMBUSH.wave;
      if (Math.random() < dt * 34) f.smokeP.emit({ x: m.x + (Math.random() - 0.5) * W.w, y: 0.8, z: m.z + Math.random() * 1.5, vx: (Math.random() - 0.5) * 3.5, vy: 3.5 + Math.random() * 3.5, vz: 2 + Math.random() * 2.5, life: 1, size: 0.9, size1: 2.8, color: Math.random() < 0.35 ? 0x8a6a48 : SAND_LIT, color1: 0xb09070, alpha: 0.72, frame: 1, gravity: -6 });
      if (Math.random() < dt * 12) f.dust(m.x + (Math.random() - 0.5) * W.w, m.z - Math.random() * W.len, 3, 0xb89670, 0.5);
      return;
    }
    const K = AMBUSH[m.kind];
    const k = Math.min(1, m.t / K.rise);
    if (Math.random() < dt * (6 + 10 * k)) f.smokeP.emit({ x: m.x + (Math.random() - 0.5) * K.r, y: K.h * k + 0.2, z: m.z + (Math.random() - 0.5) * K.r, vx: (Math.random() - 0.5) * 1.6, vy: 1.6 + Math.random() * 2, vz: (Math.random() - 0.5) * 1.6, life: 0.8, size: 0.35, size1: 1.2, color: SAND_LIT, color1: 0xc8b090, alpha: 0.7, frame: 1, gravity: -4 });
    if (m.kind === 'smoke' && Math.random() < dt * 9) for (const s of [-1, 1]) f.smoke(m.x + s * 0.9, K.h * k + 0.4, m.z - 0.6, 0.45, 1.6, 0x1e1b19, 0.6);
  }

  /**
   * 掀开：沙柱 + 一圈沙浪 + 闷响 + 轻震屏，盖板翻起来，坑留一会儿。emerge = 到时间自己钻出来（满编）；
   * 别的（打到掀开值 / 8 米内爆炸 / 碾过）= 提前掀出来：人全倒下、车被顶翻剩 30%、2 秒不能开火，废铁多一半（碾的翻倍），头顶飘「掀出来」
   */
  private reveal(m: Mound, how: How): void {
    if (m.open >= 0) return;
    m.open = 0;
    m.how = how;
    if (m.e?.alive) {
      const e = m.e;
      m.e = null;
      e.kill();
    }
    const early = how !== 'emerge';
    const f = this.fx;
    const r = m.kind === 'wave' ? AMBUSH.wave.w : AMBUSH[m.kind].r;
    // 沙柱 4 米 + 一圈贴地的沙浪
    for (let i = 0; i < (early ? 14 : 8); i++) {
      const a = Math.random() * Math.PI * 2;
      f.smokeP.emit({ x: m.x + Math.cos(a) * r * 0.4, y: 0.5, z: m.z + Math.sin(a) * r * 0.4, vx: Math.cos(a) * 1.5, vy: (early ? 7 : 4.5) + Math.random() * 4, vz: Math.sin(a) * 1.5, life: 1.2 + Math.random() * 0.5, size: 0.8, size1: 2.6, color: SAND_LIT, color1: 0xa88a66, alpha: 0.75, frame: 1, gravity: -9, drag: 0.6 });
    }
    f.shockwave(m.x, m.z, r * 2.6, 0xd8c098, 0.5);
    for (let i = 0; i < 6; i++) f.dust(m.x + Math.cos(i) * r, m.z + Math.sin(i) * r, 2.4, 0xb89a76, 0.5);
    f.crater(m.x, m.z, r * 2.3);
    this.ctx.sfx(early ? 'breach' : 'crunch', m.x, m.z, early ? 0.6 : 0.7);
    this.ctx.shake(m.x, m.z, early ? 0.22 : 0.12);
    if (early) this.ctx.label(m.x, 3.2, m.z);
    this.unload(m, early, how === 'crush');
  }

  /** 坑里的兵 / 车出来：满编照常打你；提前掀出来的倒下 / 顶翻 */
  private unload(m: Mound, early: boolean, crush: boolean): void {
    const ctx = this.ctx;
    const lead = this.tank;
    if (m.kind === 'small') {
      let scrap = 0;
      for (let i = 0; i < m.load.length; i++) {
        const kind = m.load[i];
        const a = (i / m.load.length) * Math.PI * 2 + m.yaw;
        const x = m.x + Math.cos(a) * 1.1;
        const z = m.z + Math.sin(a) * 1.1;
        if (early && kind === 'sapper') {
          // 爆破兵当场炸在坑里：不伤你，8 米内别的鼓包跟着掀
          this.fx.explosion(x, z, 1.6, 1.2);
          ctx.sfx('explode', x, z, 0.7);
          this.blast(x, z);
          continue;
        }
        const e = ctx.spawn(kind, x, z);
        if (!e) continue;
        if (early) {
          scrap += e.spec.scrap;
          ctx.down(e, m.x, m.z, crush);
        } else e.hopV = 3.2 + Math.random();
      }
      if (early) ctx.scrap(m.x, m.z, scrap * AMBUSH.scrap);
      return;
    }
    // 车：黑烟包 1 辆在坑里；沙浪 3 辆顺着沙脊排开
    const n = m.load.length;
    let scrap = 0;
    for (let i = 0; i < n; i++) {
      const x = m.x + (m.kind === 'wave' ? (i % 2 ? 1.4 : -1.4) : 0);
      const z = m.z - i * 5.5;
      const e = ctx.spawn(m.load[i], x, z);
      if (!e) continue;
      e.group.rotation.y = Math.atan2(lead.x - x, lead.z - z);
      const fx = x + Math.sin(e.group.rotation.y) * 3;
      const fz = z + Math.cos(e.group.rotation.y) * 3;
      if (early) {
        e.hp = e.maxHp * AMBUSH.left;
        e.power = Math.max(e.power, AMBUSH.stun);
        e.tiltKick(x - (fx - x), z - (fz - z), AMBUSH.toss);
        scrap += e.spec.scrap;
      } else {
        // 车头上扬着从坑里开出来、沙子往下淌
        e.tiltKick(fx, fz, 30);
        for (let k = 0; k < 4; k++) this.fx.dust(x + (Math.random() - 0.5) * 3, z + (Math.random() - 0.5) * 3, 2, 0xc0a07a, 0.5);
      }
    }
    // 车被碾翻（剩 30%）的废铁翻倍
    if (early) ctx.scrap(m.x, m.z, scrap * (crush ? 1 : AMBUSH.scrap));
  }

  /** 大沙浪：相对坦克斜着冲过来，从车底下穿过去（车身顶起来、余震），顺路拖走右边一件油田大件；不伤人 */
  private stepSurge(dt: number): void {
    const S = AMBUSH.surge;
    const s = this.surge;
    s.t += dt;
    const k = Math.min(1, s.t / S.dur);
    const x = THREE.MathUtils.clamp(s.x0, -10, 10) + S.from[0] + (S.to[0] - S.from[0]) * k;
    const z = this.tank.z + S.from[1] + (S.to[1] - S.from[1]) * k;
    if (Math.random() < dt * 40) this.fx.smokeP.emit({ x: x + (Math.random() - 0.5) * S.w, y: 0.8, z: z + Math.random() * 3, vx: (Math.random() - 0.5) * 4, vy: 4 + Math.random() * 4, vz: 3 + Math.random() * 3, life: 1.1, size: 1, size1: 3.2, color: SAND_LIT, color1: 0xa88a66, alpha: 0.7, frame: 1, gravity: -7 });
    if (Math.random() < dt * 14) this.fx.dust(x + (Math.random() - 0.5) * S.w, z - Math.random() * S.len, 3.4, 0xb89a76, 0.5);
    if (!s.lifted && Math.abs(z - this.tank.z) < 3 && Math.abs(x - this.tank.x) < S.w) {
      s.lifted = true;
      this.ctx.heave(1);
    }
    if (!s.swallowed && k > 0.75) {
      s.swallowed = true;
      this.ctx.swallow(x + 10, z - 20);
    }
    if (k >= 1) s.t = -1;
    this.surgeAt.set(x, 0, z);
  }

  private readonly surgeAt = new THREE.Vector3();

  private sync(): void {
    let n = 0;
    let b = 0;
    let r = 0;
    const put = (mesh: THREE.InstancedMesh, i: number, x: number, y: number, z: number, q: THREE.Quaternion, sx: number, sy: number, sz: number) => {
      _m.compose(_p.set(x, y, z), q, _s.set(sx, sy, sz));
      mesh.setMatrixAt(i, _m);
    };
    for (const m of this.mounds) {
      if (m.t < 0) continue;
      if (m.kind === 'wave') {
        if (m.open >= 0 || r >= 6) continue;
        const W = AMBUSH.wave;
        // 沙脊：浪头在 +z 那头（迎着你），往后拖 len 米；高度起伏一点
        const h = W.h * (0.85 + 0.15 * Math.sin(m.t * 9));
        put(this.ridge, r++, m.x, -0.1, m.z - W.len * 0.42, _q.identity(), W.w / 2, h, W.len / 2);
        continue;
      }
      const K = AMBUSH[m.kind];
      if (n >= 16) continue;
      // 掀开以后鼓包塌下去（沙往坑里淌）
      const k = m.open >= 0 ? Math.max(0, 1 - m.open * 2.5) : Math.min(1, m.t / K.rise);
      const h = K.h * (m.open >= 0 ? k : 0.35 + 0.65 * k) + 0.02;
      if (h > 0.03) put(this.mesh, n++, m.x, -0.03, m.z, _q.setFromAxisAngle(UP, m.yaw), K.r * (0.75 + 0.25 * k), h, K.r * (0.75 + 0.25 * k));
      // 盖板：两块，鼓着时扣在包顶下面看不见，掀开那一下翻起来甩到两边
      if (m.open >= 0 && b < 31) {
        const fl = Math.min(1, m.open * 3);
        for (const s of [-1, 1]) {
          const yaw = m.yaw + (s > 0 ? 0 : Math.PI);
          const ang = (m.how === 'emerge' ? 1.6 : 2.6) * fl;
          _q.setFromEuler(_e.set(-ang, yaw, 0, 'YXZ'));
          put(this.boards, b++, m.x + Math.sin(yaw) * 0.2, 0.15 + Math.sin(fl * Math.PI) * 0.8, m.z + Math.cos(yaw) * 0.2, _q, K.r * 0.55, 1, 1);
        }
      }
    }
    if (this.surge.t >= 0 && r < 6) {
      const S = AMBUSH.surge;
      const a = Math.atan2(S.to[0] - S.from[0], S.to[1] - S.from[1]);
      put(this.ridge, r++, this.surgeAt.x, -0.2, this.surgeAt.z - Math.cos(a) * S.len * 0.4, _q.setFromAxisAngle(UP, a), S.w / 2, S.h, S.len / 2);
    }
    for (const [mesh, count] of [[this.mesh, n], [this.boards, b], [this.ridge, r]] as [THREE.InstancedMesh, number][]) {
      mesh.count = count;
      mesh.visible = count > 0;
      if (count) mesh.instanceMatrix.needsUpdate = true;
    }
  }
}
