import type { Enemy } from '../../entities/Enemy';
import { DecalKind } from '../../render/Decals';
import { ultHalf } from '../defs';
import { UltBase, type UltAim, type UltContext, type UltHit, type UltPreview } from './common';

const rand = (a: number, b: number) => a + Math.random() * (b - a);

/**
 * 「炼狱」数值表（策划案 T007 v3 3.2 / 7 节的起步值；冷却在 FUSIONS.inferno.cd 里固定 24 秒（T066 翻倍））：
 * 炼狱弹初速 speed 米/秒、射程 range 米（第一次碰到敌人 / 撞上路障或残骸 / 打中油桶 / 飞满射程就起爆）；
 * 弹着：hitR 米（× A = 爆破药半效）爆炸 hitDmg（blast，击退 knock）+ 小号蘑菇云（规模 cloud）+ 白闪 flash + 顿帧 freeze + 震屏 shake。
 * 火海：以弹着点为中心、顺着道路的椭圆，左右半轴 rx、前后半轴 rz（不吃爆破药）；spread 秒内火线从中心烧开（伤害只算已经烧到的部分），
 * 烧 dur 秒（最后 fade 秒画面退成余烬和黑烟，伤害和熔甲算满 dur 秒）；每 tick 秒结算一次，火海里每个敌人每秒 dps × 燃料半效（fire）；
 * 离开火海（或火海结束时还在里面）的再烧 igniteT 秒，每秒 ignite × 燃料半效（fire）。
 * 熔甲：受伤那一刻在已经烧到的火海里，主武器的伤害 × melt（多出来的记在「炼狱」名下 'ult-melt'）。
 * 画面：每秒 fps 团火舌、smokes 个烟火点、scorch 块焦痕（留 scorchT 秒）；油桶由近到远每 barrelGap 秒引爆一个；
 * 待发预览：锁定目标处（没有目标就是炮口方向 preview 米）的椭圆。
 * T057（只是演出，上面的数值没动）：弹着处火柱 pillar [高, 粗, 秒] 冲天 + 大一号的蘑菇云（cloud 宽、cloudTall 高）+ 火线烧开时沿着火线一圈火浪（wave 团 / 帧）+ 热浪冲击环；
 * 慢放 slow [秒, 倍数]；镜头轻轻抬一下 look [弧度, 秒] 看火柱；火海期间全场偏暖 mood、火光照亮四周（glow 功率）；烧完地上往上飘余烬 embers [秒, 每秒片数]
 */
export const INFERNO = {
  speed: 95, range: 100,
  // T017-5a（方案 A，制作人「全按默认」）：弹着 260 → 900、半径 7 → 10；火海每秒 55 → 150 且对车辆不打折（pure）；冷却 10 → 12（FUSIONS.inferno.cd）
  hitR: 10, hitDmg: 900, knock: 10, cloud: 0.5, flash: 0.25, freeze: 0.06, shake: 0.5,
  rx: 18, rz: 24, spread: 0.5, dur: 5, fade: 0.6, tick: 0.25, dps: 150, ignite: 20, igniteT: 3,
  melt: 1.5,
  fps: 90, smokes: 8, scorch: 8, scorchT: 20, barrelGap: 0.14, preview: 45,
  pillar: [26, 1.7, 1.3], cloudTall: 0.75, wave: 6, slow: [0.3, 0.45], look: [0.12, 0.7], glow: 2600, embers: [5, 26],
  mood: { light: 0.82, exposure: 0.98, tint: 0xffa860, tintK: 0.4, fog: 0x7a5038, fogK: 0.22 },
};

/** 炼狱 · 核子燃烧弹（主炮 + 机枪★ + 火焰★）：主炮打出一发不占弹匣的核子燃烧弹，命中处烧成大片火海 5 秒；火海里的敌人受主炮伤害 +50%（熔甲） */
export class InfernoUlt extends UltBase {
  /** 炼狱弹在飞（等 onShellHit） */
  private flying = false;
  private flight = 0;
  /** 这一发的射程（平时 INFERNO.range，巨炮在场时对轰射程） */
  private range = INFERNO.range;
  /** 出膛点和方向（炮弹意外丢了的时候，按射程尽头兜底起爆） */
  private sx = 0;
  private sz = 0;
  private dx = 0;
  private dz = -1;
  /** 火海已经烧了几秒；-1 = 没有火海 */
  private t = -1;
  private cx = 0;
  private cz = 0;
  /** 已结算的跳数（第 i 跳在 i × tick 秒） */
  private ticks = 0;
  /** 上一跳还在火海里的敌人（这一跳不在了 = 离开火海，点燃余烧） */
  private inside = new Set<Enemy>();
  private next = new Set<Enemy>();
  private readonly chain: [number, number][] = [];
  private chainT = 0;
  /** 氛围改过（被 clear 打断时下一帧退回平时） */
  private moody = false;

  /** 现在按下会烧到哪：锁定目标处，没有目标就是炮口方向 preview 米 */
  preview(ctx: UltContext, aim: UltAim): UltPreview {
    const T = INFERNO;
    const P = ctx.tank.group.position;
    const tg = aim.target;
    const x = tg ? tg.group.position.x : P.x - Math.sin(aim.angle) * T.preview;
    const z = tg ? tg.group.position.z : P.z - Math.cos(aim.angle) * T.preview;
    return { x, z, r: T.rx, rz: T.rz };
  }

  /** 落点价值评分（T017-13A）：火海左右半轴那么大，15～100 米（巨炮在场时最远放到对轰射程，D5） */
  spot(ctx: UltContext): { r: number; min: number; max: number } {
    return { r: INFERNO.rx, min: 15, max: Math.max(INFERNO.range, ctx.duel) };
  }

  protected fire(ctx: UltContext, aim: UltAim): void {
    const T = INFERNO;
    this.clear();
    this.range = Math.max(T.range, ctx.duel);
    const b = ctx.shell(aim.angle, T.speed, this.range);
    if (!b) {
      this.finish();
      return;
    }
    // 有选好的落点（T017-5d，落点价值评分选中的那一坨）：炮弹从小兵头上飞过去，飞到它跟前（离炮口的距离 − 它的半径）再炸；
    // 没有（手动瞄准 / 前方没敌人）照旧碰到第一个东西 / 飞满射程起爆
    const tg = aim.target;
    if (tg) {
      const d = Math.hypot(tg.group.position.x - b.x, tg.group.position.z - b.z) - tg.radius;
      b.life = Math.max(2, Math.min(this.range, d)) / T.speed;
      b.ultPass = true;
    }
    this.flying = true;
    this.flight = 0;
    this.sx = b.x;
    this.sz = b.z;
    this.dx = -Math.sin(aim.angle);
    this.dz = -Math.cos(aim.angle);
    this.active = this.range / T.speed + T.dur;
  }

  onShellHit(ctx: UltContext, hit: UltHit): void {
    if (!this.flying) return;
    this.ignite(ctx, hit.x, hit.z);
  }

  /** 熔甲：受伤那一刻在已经烧到的火海里 → 主武器伤害 × melt */
  coreMult(e: Enemy): number {
    if (this.t < 0 || this.t > INFERNO.dur) return 1;
    return this.covers(e, this.reach()) ? INFERNO.melt : 1;
  }

  protected override activeLabel(): string {
    return this.flying ? '飞行' : `火海 ${Math.ceil(this.active)}`;
  }

  protected step(ctx: UltContext): void {
    const T = INFERNO;
    const dt = ctx.dt;
    if (this.flying) {
      this.flight += dt;
      const left = this.range / T.speed - this.flight;
      this.active = Math.max(1e-3, left) + T.dur;
      // 兜底：炮弹被回收了却没落地（不该发生），按射程尽头起爆
      if (left < -0.5) this.ignite(ctx, this.sx + this.dx * this.range, this.sz + this.dz * this.range);
      return;
    }
    if (this.t < 0) {
      if (this.moody) {
        this.moody = false;
        ctx.mood(null, 0.6);
      }
      return;
    }
    this.t += dt;
    // 路边景物（T009 第 8 节）：火线往外烧开的那 0.5 秒里每帧点一次，烧到哪里哪里 0.2 秒内着（不等 0.25 秒一跳）
    if (this.t <= T.spread + 0.05) {
      const k = this.reach();
      ctx.scenery.igniteEllipse(this.cx, this.cz, T.rx * k, T.rz * k);
      // 火浪（T057）：沿着正在往外推的火线窜起一圈高火
      for (let i = 0; i < T.wave; i++) {
        const a = Math.random() * Math.PI * 2;
        ctx.fx.blaze(this.cx + Math.cos(a) * T.rx * k, this.cz + Math.sin(a) * T.rz * k, 2.4, 0.8, 1);
      }
    }
    // 火光照亮四周（T057）：火海烧着的时候一直续着暖光，收尾时退下去
    if (this.t < T.dur) ctx.fx.flash(this.cx, ctx.fx.groundAt(this.cx, this.cz) + 4, this.cz, T.glow * (0.75 + 0.25 * Math.sin(this.t * 9)) * Math.min(1, (T.dur - this.t) / T.fade));
    // 第 i 跳结算第 i 个 tick 秒（在 i × tick 秒时），一共 dur ÷ tick 跳（伤害和熔甲算满 dur 秒）
    const total = Math.round(T.dur / T.tick);
    while (this.ticks < total && (this.ticks + 1) * T.tick <= this.t + 1e-6) {
      this.ticks += 1;
      this.burn(ctx);
    }
    if (this.chain.length) {
      this.chainT -= dt;
      if (this.chainT <= 0) {
        this.chainT = T.barrelGap;
        const [x, z] = this.chain.shift()!;
        ctx.detonate(x, z);
      }
    }
    if (this.t >= T.dur && this.ticks >= total) {
      this.end(ctx);
      return;
    }
    this.active = Math.max(1e-3, T.dur - this.t);
  }

  /** 弹着：小号蘑菇云 + 爆炸 + 白闪 / 顿帧 / 震屏，火海开始烧 */
  private ignite(ctx: UltContext, x: number, z: number): void {
    const T = INFERNO;
    const A = ultHalf(ctx.mods.area);
    this.flying = false;
    this.t = 0;
    this.ticks = 0;
    this.cx = x;
    this.cz = z;
    this.inside.clear();
    this.active = T.dur;
    ctx.explode(x, z, T.hitR * A, T.hitDmg, { type: 'blast', knock: T.knock, ult: true, pit: 2 });
    // 火柱冲天 + 大一号的蘑菇云 + 一圈热浪（T057）
    const [ph, ps, pt] = T.pillar;
    ctx.fx.pillar(x, z, ph, ps, pt);
    ctx.fx.mushroom(x, z, T.cloud, ctx.quality === 'high', { tall: T.cloudTall });
    ctx.fx.shockwave(x, z, T.rz * 1.15, 0xffb070, 0.6);
    ctx.hazards.burnField(x, z, T.rx, T.rz, T.dur, T.spread, T.fade, T.fps);
    // 不规则分布的烟火点（被风吹斜的黑烟柱），火苗烧到火海结束前后
    for (let i = 0; i < T.smokes; i++) {
      const a = Math.random() * Math.PI * 2;
      const r = Math.sqrt(Math.random()) * 0.85;
      ctx.fx.burn(x + Math.cos(a) * T.rx * r, z + Math.sin(a) * T.rz * r, rand(1.3, 2.1), T.dur * rand(1.1, 1.3));
    }
    // 焦土：几块焦痕拼成不规则的一片
    for (let i = 0; i < T.scorch; i++) {
      const a = (i / T.scorch) * Math.PI * 2 + rand(-0.4, 0.4);
      const r = i === 0 ? 0 : rand(0.25, 0.7);
      const w = rand(0.6, 0.95) * T.rx;
      ctx.fx.decals.add(DecalKind.Scorch, x + Math.cos(a) * T.rx * r, z + Math.sin(a) * T.rz * r, w, w * rand(0.9, 1.3), Math.random() * 6.28, rand(0.7, 0.9), T.scorchT);
    }
    ctx.flash(T.flash);
    ctx.freeze(T.freeze);
    ctx.slowmo(T.slow[0], T.slow[1]);
    ctx.shake(T.shake);
    ctx.lookUp(T.look[0], T.look[1], 0.6, 0.35);
    this.moody = true;
    ctx.mood(T.mood, 0.3);
    ctx.audio.play('nuke', 0.45);
    ctx.audio.play('flame');
    ctx.audio.play('gust', 0.45, 1, 0.1);
  }

  /** 一跳：已经烧到的火海里的敌人各受一次燃烧伤害，步兵四散；离开火海的点燃余烧；场景跟着火线点着 */
  private burn(ctx: UltContext): void {
    const T = INFERNO;
    const B = ultHalf(ctx.mods.burn);
    const k = this.reach();
    const amount = T.dps * B * T.tick;
    const next = this.next;
    next.clear();
    for (const e of ctx.enemies) {
      if (!e.alive || !this.covers(e, k)) continue;
      next.add(e);
      ctx.damage(e, amount, e.group.position.x, e.group.position.z, { type: 'fire', ult: true, pure: true });
      // 着火的步兵四散奔逃（爆破兵不躲，照冲）
      if (e.alive && e.spec.crushable && e.kind !== 'sapper' && !e.spec.fixed) {
        const ox = e.group.position.x - this.cx;
        const oz = e.group.position.z - this.cz;
        const len = Math.hypot(ox, oz) || 1;
        e.panic = Math.max(e.panic, 1.2);
        e.panicX = ox / len;
        e.panicZ = oz / len;
      }
    }
    for (const e of this.inside) if (!next.has(e)) this.afterburn(e, B, ctx.playerId ?? 0);
    this.next = this.inside;
    this.inside = next;
    this.chain.push(...ctx.kindle(this.cx, this.cz, T.rx * k, T.rz * k));
  }

  /** 火海结束：还在里面的点燃余烧；收尾的黑烟 */
  private end(ctx: UltContext): void {
    const B = ultHalf(ctx.mods.burn);
    for (const e of this.inside) this.afterburn(e, B, ctx.playerId ?? 0);
    this.inside.clear();
    // 余韵（T057）：烧过的地上往上飘火星和灰，暖光退掉
    ctx.fx.fallout(this.cx, this.cz, INFERNO.rx, 4, INFERNO.embers[0], INFERNO.embers[1], 0.7, true);
    this.moody = false;
    ctx.mood(null, 1.2);
    for (let i = 0; i < 3; i++) {
      const a = Math.random() * Math.PI * 2;
      const r = Math.sqrt(Math.random()) * 0.6;
      ctx.fx.burn(this.cx + Math.cos(a) * INFERNO.rx * r, this.cz + Math.sin(a) * INFERNO.rz * r, rand(1.4, 2), rand(5, 7), false);
    }
    this.t = -1;
    this.finish();
  }

  /** 点燃：再烧 igniteT 秒（身上已经有更旺的火就不换） */
  private afterburn(e: Enemy, B: number, player: number): void {
    if (!e.alive) return;
    const dps = INFERNO.ignite * B;
    if (dps < e.burnDps && e.burnTime > 0) return;
    e.burnDps = dps;
    e.burnTime = Math.max(e.burnTime, INFERNO.igniteT);
    e.burnSrc = 'ult';
    e.burnPlayer = player;
    e.burnSummon = false;
  }

  /** 火线烧到的比例（0..1） */
  private reach(): number {
    return Math.min(1, this.t / INFERNO.spread);
  }

  /** 敌人（按半径算，露出一部分也算）在已经烧到 k 的椭圆里 */
  private covers(e: Enemy, k: number): boolean {
    const T = INFERNO;
    const r = e.radius;
    const u = (e.group.position.x - this.cx) / (T.rx * k + r);
    const v = (e.group.position.z - this.cz) / (T.rz * k + r);
    return u * u + v * v <= 1;
  }

  protected clear(): void {
    this.flying = false;
    this.t = -1;
    this.ticks = 0;
    this.inside.clear();
    this.next.clear();
    this.chain.length = 0;
  }
}
