import type { Arsenal, Card } from '../weapons/Arsenal';
import { LINKS, WEAPONS } from '../weapons/defs';
import { isReserve, isSubSlot, planSub, RESERVE_SLOTS, SUB_POSITION, SUB_SLOTS, subDirection, subLevelName, type SubItem, type SubPlan, type SubReward } from '../weapons/subMerge';

export type WorkshopSource = number | 'reward';
export interface WorkshopCell {
  item: SubItem | null;
  slot: number;
  position: string;
  name: string;
  icon: string;
  level: number;
  selected: boolean;
  target: boolean;
  consumed: boolean;
  locked: boolean;
  link: boolean;
}
export interface WorkshopView {
  title: string;
  caption: string;
  reward: (SubReward & { name: string; icon: string; selected: boolean }) | null;
  cells: WorkshopCell[];
  /** 储备格（T243）：三格，不开火 */
  reserve: WorkshopCell[];
  lines: string[];
  warning: boolean;
  confirm: string;
  canConfirm: boolean;
  cancel: string;
}

/** 两套界面共用装配规则；拖动松手只提交一次，替换仍需确认。 */
export class SubWorkshop {
  private source: WorkshopSource | undefined;
  private target: number | undefined;
  private message = '';
  readonly reward: SubReward | null;

  constructor(readonly arsenal: Arsenal, readonly card: Card | null, private readonly cancel = card ? '返回选卡' : '返回') {
    this.reward = card ? { id: card.id as SubReward['id'], level: card.to } : null;
    if (this.reward) {
      this.source = 'reward';
      this.target = this.parkSlot();
      if (this.target !== undefined) this.message = '挂位已满，可先放进储备';
    }
  }

  /** 挂位全满、哪里都合不上时，默认把新武器放进第一个空储备格。 */
  private parkSlot(): number | undefined {
    const items = this.arsenal.subItems(), r = this.reward!;
    if (SUB_SLOTS.some(s => !items.some(w => w.slot === s))) return undefined;
    if (items.some(w => planSub(items, w.slot, r)?.kind === 'merge')) return undefined;
    return RESERVE_SLOTS.find(s => !items.some(w => w.slot === s));
  }

  get usingReward(): boolean { return this.source === 'reward'; }

  get plan(): SubPlan | null {
    return this.target === undefined ? null : this.arsenal.planSub(
      this.target, this.usingReward ? this.reward : null, typeof this.source === 'number' ? this.source : undefined,
    );
  }

  /** 松手直接生效；替换和会拆掉联动的操作要再按确认。 */
  get needsConfirm(): boolean {
    const p = this.plan;
    return !!p && (p.kind === 'replace' || !!p.lostLink);
  }

  drop(source: WorkshopSource, target: number): void {
    this.source = source;
    this.target = target;
    this.message = this.plan ? '' : '此处不能放入';
  }

  select(action: string): void {
    if (action === 'reward' && this.reward) {
      this.source = 'reward';
      this.target = undefined;
      this.message = '';
      return;
    }
    if (!action.startsWith('slot:')) return;
    const slot = Number(action.slice(5));
    if (!isSubSlot(slot)) return;
    const w = this.arsenal.subItems().find(x => x.slot === slot);
    this.message = '';
    if (this.source === undefined || this.source === slot) {
      this.source = w && this.source !== slot ? slot : undefined;
      this.target = undefined;
    } else this.target = slot;
    if (this.usingReward && w?.locked) this.message = '究极材料可换位，不能替换';
    else if (this.target !== undefined && !this.plan && isReserve(this.target)) this.message = '究极材料不能放进储备';
  }

  confirm(): SubPlan | null {
    const plan = this.plan;
    if (!plan) return null;
    if (!this.arsenal.commitSub(plan)) {
      this.target = undefined;
      this.message = '装备已变化，请重新选择';
      return null;
    }
    this.message = plan.kind === 'merge' ? `已合成${WEAPONS[plan.result.id].short}${subLevelName(plan.result.level)}`
      : isReserve(plan.result.slot) && plan.kind !== 'swap' ? '已放进储备' : '挂位已调整';
    this.source = this.reward ? 'reward' : undefined;
    this.target = undefined;
    return plan;
  }

  view(): WorkshopView {
    const p = this.plan, items = this.arsenal.subItems();
    const selected = items.find(w => w.slot === this.source);
    const lines = this.message && !p ? [this.message] : p ? this.previewLines(p) : [
      this.usingReward ? '拖动待装武器，选择挂位' : '按住武器，拖到目标挂位',
      '同型同级合一级，其他互换',
    ];
    if (this.message && p) lines.unshift(this.message);
    const id = this.usingReward ? this.reward?.id : selected?.id;
    if (id && lines.length < 3) lines.push(subDirection(id, p?.result.slot ?? selected?.slot ?? this.target ?? 2));
    const cell = (slot: number): WorkshopCell => {
      const w = items.find(x => x.slot === slot);
      return {
        item: w ?? null,
        slot, position: SUB_POSITION[slot], name: w ? WEAPONS[w.id].short : isReserve(slot) ? '空储备' : '空挂位',
        icon: w?.id ?? 'slot-w', level: w?.level ?? 0,
        selected: this.source === slot, target: this.target === slot,
        consumed: !!w && !!p?.consumed.includes(w.uid), locked: !!w?.locked, link: !!w?.link,
      };
    };
    return {
      title: '武器改装', caption: '车头朝上 · 拖动装配',
      reward: this.reward ? { ...this.reward, name: WEAPONS[this.reward.id].short, icon: this.reward.id, selected: this.usingReward } : null,
      cells: SUB_SLOTS.map(cell), reserve: RESERVE_SLOTS.map(cell),
      lines: lines.slice(0, 3), warning: this.needsConfirm,
      confirm: !p ? '先选挂位' : p.kind === 'merge' ? '确认合成' : p.kind === 'replace' ? '确认替换'
        : p.kind !== 'swap' && isReserve(p.result.slot) ? '放进储备' : p.kind === 'install' ? '确认装入' : '确认换位',
      canConfirm: !!p, cancel: this.cancel,
    };
  }

  private previewLines(p: SubPlan): string[] {
    const name = WEAPONS[p.result.id].short, pos = SUB_POSITION[p.result.slot];
    const lost = p.lostLink ? `「${LINKS[p.lostLink].name}」将失效` : '';
    if (p.kind === 'merge') return [
      `${name}${subLevelName(p.result.level)}保留在${pos}`,
      lost || `只升一级 · ${p.freed ? `空出 ${p.freed} 格` : '无需空格'}`,
    ];
    if (p.kind === 'replace') {
      const old = this.arsenal.subItems().find(w => w.uid === p.target)!;
      return [`移除${WEAPONS[old.id].short}${subLevelName(old.level)}`, lost || `${name}${subLevelName(p.result.level)}装入${pos}`];
    }
    return [p.kind === 'swap' ? `两件互换，${name}移到${pos}` : `${name}${subLevelName(p.result.level)}${isReserve(p.result.slot) ? '放进' : '装入'}${pos}`,
      lost || (isReserve(p.result.slot) ? '储备中不开火，随时取用' : p.kind === 'install' ? '同型号可以并排开火' : '保留冷却、热度和联动')];
  }
}

export const workshopCells = (view: WorkshopView) => [...view.cells, ...view.reserve];

export function workshopItem(view: WorkshopView, source: WorkshopSource) {
  return source === 'reward' ? view.reward : workshopCells(view).find(c => c.slot === source && c.item) ?? null;
}

/** 鼠标和触屏共用手势阈值；预览直接复用合成规则，不另存装备。 */
export class WorkshopDrag {
  current: {
    id: number; source: WorkshopSource; x0: number; y0: number; x: number; y: number;
    moved: boolean; target: number | null; plan: SubPlan | null;
  } | null = null;

  begin(view: WorkshopView, source: WorkshopSource, id: number, x: number, y: number): boolean {
    if (this.current || !workshopItem(view, source)) return false;
    this.current = { id, source, x0: x, y0: y, x, y, moved: false, target: null, plan: null };
    return true;
  }

  move(view: WorkshopView, id: number, x: number, y: number, target: number | null): void {
    const d = this.current;
    if (!d || d.id !== id) return;
    d.x = x; d.y = y;
    d.moved ||= Math.hypot(x - d.x0, y - d.y0) > 10;
    d.target = d.moved ? target : null;
    d.plan = d.target === null ? null : planSub(
      workshopCells(view).flatMap(c => c.item ? [c.item] : []), d.target,
      d.source === 'reward' ? view.reward : null, typeof d.source === 'number' ? d.source : undefined,
    );
  }

  end(view: WorkshopView, id: number, x: number, y: number, target: number | null, cancelled = false): { handled: boolean; action?: string } {
    const d = this.current;
    if (!d || d.id !== id) return { handled: true };
    this.move(view, id, x, y, target);
    this.current = null;
    if (cancelled) return { handled: true };
    return { handled: d.moved, action: d.moved && d.plan ? `drop:${d.source}:${d.target}` : undefined };
  }

  cancel(): void { this.current = null; }

  get label(): string {
    const d = this.current, p = d?.plan;
    if (!p) return d?.target === null || d?.target === d?.source ? '拖到目标挂位' : '此处不能放入';
    if (p.kind === 'merge') return `松手合成${subLevelName(p.result.level)}`;
    if (p.kind === 'replace') return '松手预览替换';
    if (p.lostLink) return '松手后再确认';
    if (isReserve(p.result.slot) && p.kind !== 'swap') return '松手放进储备';
    return p.kind === 'swap' ? '松手互换' : p.kind === 'move' ? '松手移动' : '松手装入';
  }
}
