import * as THREE from 'three';
import { DecalKind } from '../render/Decals';
import type { Fx } from '../render/Fx';
import { dmgSrc } from '../systems/DamageLog';
import type { Prop, World } from '../systems/World';
import type { ScnItem } from './Scenery';
import { FireField } from './FireField';

const rand = (a: number, b: number) => a + Math.random() * (b - a);

/**
 * 草地火 + 火势传染（T027-a，策划 `tank-rogue-docs/T027-策划案-D5版.md` 第 1 节，制作人「树木，草堆，草地这些东西应该可以燃烧，并且有一个传染的效果，
 * 然后被喷火武器攻击的附近也会被点燃」）。点燃途径：喷火锥 / 爆炸和地面火 / 邻居传染，T032 A2 加上激光主光束（照到的树木草堆、命中点脚下的草）：
 * - cell / grassFrom / themes：田野 / 林地（泥泞乡间、林间小道两个主题）格子中心离路中心 grassFrom 米外的地面按 cell 米一格能烧（河道 + 岸边、铁路路基、车站、深弹坑底不算）；
 *   格子按 x 错开半格（中心在 ±15 / 20 / 25… 米），最靠路的一格正好盖住路肩外那条更茂的草（默认镜头画面两边看得到）
 * - burn：一格草烧多久（秒）；ignite：喷火锥照多久点着一格（和灌木一样）
 * - spread：每个刚烧起来的东西（草格子 / 路边景物 / 木头路障）往 r ± wind 米（顺风 12、逆风 8）里还没烧过的可燃物传火，每次最多 per 个、
 *   延迟 delay（顺风短、逆风长，再 ± jitter），同一把火（同一个起火点）最多烧 chain 样；隔着水面 / 河道的不传
 * - cap：同时在烧的草格子上限（沿用「燃烧点 40」）；fx：草火火苗 / 烟每秒的总预算（不按格子数涨，低画质 × low）
 * - scorch：烧完的焦痕（倍格子边长、不透明度、秒）；ash：余烟秒数（灌木 / 草堆 / 篱墙烧完也有）
 * - hurt：敌我都伤、很轻（每秒，不叠加，tick 秒结算一次）；near = 贴着烧着的景物多近算挨烧
 * - wind：风向（和烟柱飘的方向一致：往右、略偏前）
 */
export const WILDFIRE = {
  cell: 5,
  grassFrom: 14,
  themes: ['farmland', 'forest'] as readonly string[],
  burn: [6, 9] as const,
  ignite: 0.36,
  spread: { r: 10, wind: 2, delay: [0.3, 0.8] as const, jitter: 0.1, per: 3, chain: 12 },
  cap: 40,
  fx: { blaze: 120, perCell: 16, smoke: 6, low: 0.5 },
  scorch: { size: 1.45, alpha: 0.8, life: 50 },
  ash: 6,
  hurt: { player: 2, enemy: 1.5, tick: 0.25, near: 1.5 },
  wind: { x: 0.91, z: -0.41 },
};

/** 格子在 x 方向错开半格：中心在 ±15、±20…（路面半宽 13 + 路肩） */
const X0 = 2.5;

/** 直接点着的草离已经在烧的火这么近（米，按 x / z 各自算）就并进那一把火 */
const JOIN = 7;

/** 能被传上火的路边景物（T126 加上房子：成排的房子、房子和树之间也互相点着） */
const SPREAD_KINDS = new Set(['pine', 'bush', 'hay', 'hedge', 'log', 'house']);

/** 一把火：从同一个起火点传出去的东西一共烧了几样（含起火点） */
interface Blaze {
  n: number;
}

/** 草地格子：0 = 没着（喷火锥在烤）、1 = 排队等传上、2 = 在烧、3 = 烧过了 */
interface Cell {
  key: number;
  x: number;
  z: number;
  y: number;
  state: 0 | 1 | 2 | 3;
  heat: number;
  t: number;
  dur: number;
  fire: Blaze | null;
}

interface Pending {
  t: number;
  fire: Blaze;
  cell: Cell | null;
  item: ScnItem | null;
  prop: Prop | null;
}

/** 烧完冒余烟的地方 */
interface Ash {
  x: number;
  y: number;
  z: number;
  t: number;
}

/** 挨烧要的游戏层钩子（Game 构造时填，伤害走地面火同一个口子） */
export interface WildfireCtx {
  players?: readonly { readonly x: number; readonly z: number; readonly alive?: boolean }[];
  forEachEnemy(fn: (x: number, z: number, radius: number, hit: (amount: number) => void) => void): void;
  damagePlayer(amount: number, player?: number): void;
  sfx?(x: number, z: number): void;
}

/** 草火从点着到烧旺用掉一格燃烧时间的多少（之后火慢慢退、只剩焦黑余烬） */
const FRONT = 0.22;

/**
 * 地面火场里各种火的强度（T126，见 FireField）：草格子按烧到哪算（FRONT 前烧旺、一半以后退）；正在烧的路边景物按种类给一块（half = 半宽：占地半径 × k，夹在 min～max 米；树按树冠算到 min）；
 * link = 两处火（景物 / 草格子）边到边隔这么近就连一条火带（米）、linkMax = 中心最远多少米
 */
const FIELD = {
  item: { pine: 0.75, house: 0.85, bush: 0.7, hay: 0.75, hedge: 0.7, log: 0.65, pole: 0.55, other: 0.65 } as Record<string, number>,
  half: { k: 0.6, min: 1.5, max: 3.2 },
  link: 6,
  linkMax: 16,
  char: 0.8,
};

/** 草地火 + 传染（World 持有，World.update 每帧调） */
export class Wildfire {
  readonly mesh: THREE.Mesh;
  ctx: WildfireCtx | null = null;
  /** 低画质时火苗 / 烟减半（Game 按画质改） */
  low = false;
  private readonly cells = new Map<number, Cell>();
  private readonly burning: Cell[] = [];
  private readonly pending: Pending[] = [];
  private readonly ashes: Ash[] = [];
  private readonly fireOf = new WeakMap<object, Blaze>();
  private readonly queued = new WeakSet<object>();
  /** 地面火场（T126）：草火、烧着的景物、两处火之间的火带都写进去，连成一片画 */
  readonly field: FireField;
  /** 这一帧正在烧的景物（位置 / 半宽 / 火）和连起来的火带（两端 + 火），火舌按它们挑落点 */
  private readonly hot: { x: number; z: number; r: number; h: number }[] = [];
  private readonly links: { x0: number; z0: number; x1: number; z1: number; h: number }[] = [];
  private time = 0;
  private blazeAcc = 0;
  private smokeAcc = 0;
  private ashAcc = 0;
  private rr = 0;
  private hurtT = 0;
  private sweepT = 0;
  private sfxT = 0;
  /** 诊断：累计点着的草格子 / 传染了几次 / 因为上限没点着的 / 隔水没传的 */
  /** kindled = 烧起来的景物 / 木头路障（每日任务「点燃 N 处草木」= lit + kindled，T030） */
  readonly stats = { lit: 0, spread: 0, capped: 0, wet: 0, maxBurning: 0, kindled: 0 };

  constructor(
    private readonly world: World,
    private readonly fx: Fx,
  ) {
    this.field = new FireField(fx.craterU);
    this.mesh = this.field.mesh;
  }

  reset(): void {
    this.cells.clear();
    this.burning.length = 0;
    this.pending.length = 0;
    this.ashes.length = 0;
    this.hot.length = 0;
    this.links.length = 0;
    this.field.reset();
  }

  /** 在烧的草格子数 */
  get count(): number {
    return this.burning.length;
  }

  /** (x, z) 这里是不是能烧的草地：田野 / 林地主题、离路中心 grassFrom 米外、不在河道 / 铁路 / 车站、不在深弹坑底 */
  isGrass(x: number, z: number): boolean {
    if (Math.abs(x) < WILDFIRE.grassFrom) return false;
    if (!WILDFIRE.themes.includes(this.world.themeAt(z).id)) return false;
    const w = this.world;
    if (w.rivers.inRiverAt(x, z, 1) || w.railway.blocked(x, z)) return false;
    return w.groundAt(x, z) > -0.6;
  }

  private key(cx: number, cz: number): number {
    return cz * 256 + cx + 128;
  }

  /** 格子中心在 (x, z) 附近的那一格（能烧才建） */
  private cellAt(cx: number, cz: number): Cell | null {
    const k = this.key(cx, cz);
    const c = this.cells.get(k);
    if (c) return c;
    const S = WILDFIRE.cell;
    const x = X0 + (cx + 0.5) * S;
    const z = (cz + 0.5) * S;
    if (!this.isGrass(x, z)) return null;
    const cell: Cell = { key: k, x, z, y: this.world.groundAt(x, z), state: 0, heat: 0, t: 0, dur: 0, fire: null };
    this.cells.set(k, cell);
    return cell;
  }

  /**
   * 旁边（JOIN 米内）已经有一把在烧的火，就并进那一把（同一片地方的火一共最多 chain 样：同一摊地面火每 0.5 秒烤一次、喷火锥一路扫过去，都不会一次次开新火）；没有就开一把新火
   */
  private fireNear(x: number, z: number): Blaze {
    for (const c of this.burning) if (c.fire && Math.abs(c.x - x) < JOIN && Math.abs(c.z - z) < JOIN) return c.fire;
    return { n: 0 };
  }

  /** 草地火 / 燃烧弹 / 地面火 / 普通爆炸留下的火落在 (x, z) 半径 r：点着脚下的草（旁边有火就并进那一把，否则一把新火），返回点着了几格 */
  igniteAt(x: number, z: number, r: number): number {
    if (Math.abs(x) + r + WILDFIRE.cell < WILDFIRE.grassFrom) return 0;
    const S = WILDFIRE.cell;
    let fire: Blaze | null = null;
    let n = 0;
    for (let cx = Math.floor((x - r - X0) / S); cx <= Math.floor((x + r - X0) / S); cx++) {
      for (let cz = Math.floor((z - r) / S); cz <= Math.floor((z + r) / S); cz++) {
        const cx0 = X0 + (cx + 0.5) * S;
        const cz0 = (cz + 0.5) * S;
        if (Math.hypot(cx0 - x, cz0 - z) > r + S * 0.5) continue;
        const c = this.cellAt(cx, cz);
        if (!c || c.state !== 0) continue;
        fire ??= this.fireNear(x, z);
        fire.n += 1;
        if (this.start(c, fire)) n++;
      }
    }
    return n;
  }

  /** 喷火锥（和 SceneryDamage.flame 同一个锥形判定）：扫到的草每格照 WILDFIRE.ignite 秒点着（离已经在烧的火 JOIN 米内就并进那一把，否则一把新火）；扫到水面冒白汽 */
  flame(ox: number, oz: number, ang: number, range: number, cone: number, dt: number): void {
    const dx = -Math.sin(ang);
    const dz = -Math.cos(ang);
    const tipX = ox + dx * range * 0.8;
    const tipZ = oz + dz * range * 0.8;
    if (Math.random() < dt * 5 && this.world.rivers.waterAt(tipX, tipZ)) this.fx.steam(tipX, 0.6 + this.world.rivers.levelAt(tipX, tipZ), tipZ);
    if (Math.max(Math.abs(ox + dx * range), Math.abs(ox)) + WILDFIRE.cell < WILDFIRE.grassFrom) return;
    const S = WILDFIRE.cell;
    const x0 = Math.min(ox, ox + dx * range) - S;
    const x1 = Math.max(ox, ox + dx * range) + S;
    const z0 = Math.min(oz, oz + dz * range) - S;
    const z1 = Math.max(oz, oz + dz * range) + S;
    for (let cx = Math.floor((x0 - X0) / S); cx <= Math.floor((x1 - X0) / S); cx++) {
      const x = X0 + (cx + 0.5) * S;
      if (Math.abs(x) < WILDFIRE.grassFrom) continue;
      for (let cz = Math.floor(z0 / S); cz <= Math.floor(z1 / S); cz++) {
        const z = (cz + 0.5) * S;
        const px = x - ox;
        const pz = z - oz;
        const d = Math.hypot(px, pz);
        if (d > range + S * 0.5) continue;
        let diff = Math.atan2(-px, -pz) - ang;
        while (diff > Math.PI) diff -= Math.PI * 2;
        while (diff < -Math.PI) diff += Math.PI * 2;
        if (Math.abs(diff) > cone + (S * 0.5) / Math.max(3, d)) continue;
        const c = this.cellAt(cx, cz);
        if (!c || c.state !== 0) continue;
        c.heat += dt;
        if (c.heat < WILDFIRE.ignite) continue;
        const fire = this.fireNear(c.x, c.z);
        fire.n += 1;
        this.start(c, fire);
      }
    }
  }

  /** 激光主光束的命中点（T032 A2，和喷火锥一样算点燃途径）：落在草地上，那一格照 WILDFIRE.ignite 秒点着（离已经在烧的火 JOIN 米内就并进那一把） */
  heat(x: number, z: number, dt: number): void {
    if (Math.abs(x) + WILDFIRE.cell < WILDFIRE.grassFrom) return;
    const S = WILDFIRE.cell;
    const c = this.cellAt(Math.floor((x - X0) / S), Math.floor(z / S));
    if (!c || c.state !== 0) return;
    c.heat += dt;
    if (c.heat < WILDFIRE.ignite) return;
    const fire = this.fireNear(c.x, c.z);
    fire.n += 1;
    this.start(c, fire);
  }

  /** 炼狱火海（顺着道路的椭圆）里的草算已经烧过：火海自己画了一大片火，不再叠草火（火海边上的树 / 灌木照样往外传） */
  scorchEllipse(x: number, z: number, rx: number, rz: number): void {
    if (rx <= 0 || rz <= 0 || Math.abs(x) + rx + WILDFIRE.cell < WILDFIRE.grassFrom) return;
    const S = WILDFIRE.cell;
    for (let cx = Math.floor((x - rx - X0) / S); cx <= Math.floor((x + rx - X0) / S); cx++) {
      for (let cz = Math.floor((z - rz) / S); cz <= Math.floor((z + rz) / S); cz++) {
        const u = (X0 + (cx + 0.5) * S - x) / rx;
        const w = ((cz + 0.5) * S - z) / rz;
        if (u * u + w * w > 1) continue;
        const c = this.cellAt(cx, cz);
        if (c && c.state < 2) c.state = 3;
      }
    }
  }

  /** 路边景物烧起来了（SceneryDamage 的点着回调）：往外传 */
  onScenery(it: ScnItem): void {
    this.stats.kindled++;
    const fire = this.fireOf.get(it) ?? { n: 1 };
    this.queued.delete(it);
    this.spread(it.x, it.z, fire);
  }

  /** 木头路障被点着了（World.kindleProp 回调）：往外传 */
  onProp(p: Prop): void {
    this.stats.kindled++;
    const fire = this.fireOf.get(p) ?? { n: 1 };
    this.queued.delete(p);
    this.spread(p.mesh.position.x, p.mesh.position.z, fire);
  }

  /** 点着一格草：上限满了不点；不在画面里的直接烧成焦黑（不冒火、不传） */
  private start(c: Cell, fire: Blaze): boolean {
    if (this.burning.length >= WILDFIRE.cap) {
      c.state = 0;
      this.stats.capped++;
      return false;
    }
    c.fire = fire;
    c.heat = 0;
    if (!this.world.scenery.visible(c.x, c.z)) {
      c.state = 3;
      this.scorch(c);
      return true;
    }
    c.state = 2;
    c.t = 0;
    c.dur = rand(WILDFIRE.burn[0], WILDFIRE.burn[1]);
    c.y = this.world.groundAt(c.x, c.z);
    this.burning.push(c);
    this.stats.lit++;
    this.stats.maxBurning = Math.max(this.stats.maxBurning, this.burning.length);
    for (let i = 0; i < 2; i++) this.fx.blaze(c.x + rand(-1.5, 1.5), c.z + rand(-1.5, 1.5), 1.6, 0.6, 0.6);
    if (this.sfxT <= 0) {
      this.sfxT = 0.35;
      this.ctx?.sfx?.(c.x, c.z);
    }
    this.spread(c.x, c.z, fire);
    return true;
  }

  /** 隔着水：目标在河道里、或者两者之间（1/4、1/2、3/4 处）是水面 */
  private wet(x0: number, z0: number, x1: number, z1: number): boolean {
    const R = this.world.rivers;
    if (R.list.length === 0) return false;
    if (R.inRiverAt(x1, z1, 0)) return true;
    for (const t of [0.25, 0.5, 0.75]) if (R.waterAt(x0 + (x1 - x0) * t, z0 + (z1 - z0) * t)) return true;
    return false;
  }

  /**
   * 传火：(x, z) 刚烧起来，往 WILDFIRE.spread.r ± wind 米（顺风远、逆风近）里还没烧过的草格子 / 景物 / 木头路障挑最多 per 个（顺风的、近的优先），
   * 每个延迟 0.3～0.8 秒点着；同一把火最多 chain 样
   */
  private spread(x: number, z: number, fire: Blaze): void {
    const P = WILDFIRE.spread;
    const room = P.chain - fire.n;
    if (room <= 0) return;
    const W = WILDFIRE.wind;
    const reachMax = P.r + P.wind;
    const cand: { score: number; cos: number; cell: Cell | null; item: ScnItem | null; prop: Prop | null; x: number; z: number }[] = [];
    const consider = (tx: number, tz: number, pad: number, cell: Cell | null, item: ScnItem | null, prop: Prop | null) => {
      const dx = tx - x;
      const dz = tz - z;
      const d = Math.hypot(dx, dz);
      if (d < 0.3) return;
      const cos = (dx * W.x + dz * W.z) / d;
      const reach = P.r + P.wind * cos;
      if (d - pad > reach) return;
      // 景物 / 路障比草格子优先一点（一把火 12 样，别全被草格子占满、树一棵都没着）
      cand.push({ score: ((d - pad) / reach) * (cell ? 1 : 0.75) + Math.random() * 0.15, cos, cell, item, prop, x: tx, z: tz });
    };
    const S = WILDFIRE.cell;
    if (Math.abs(x) + reachMax + S >= WILDFIRE.grassFrom) {
      const n = Math.ceil(reachMax / S);
      const ccx = Math.floor((x - X0) / S);
      const ccz = Math.floor(z / S);
      for (let cx = ccx - n; cx <= ccx + n; cx++) {
        if (Math.abs(X0 + (cx + 0.5) * S) < WILDFIRE.grassFrom) continue;
        for (let cz = ccz - n; cz <= ccz + n; cz++) {
          const c = this.cellAt(cx, cz);
          if (c && c.state === 0) consider(c.x, c.z, S * 0.35, c, null, null);
        }
      }
    }
    const dmg = this.world.scenery.damage;
    this.world.scenery.query(x, z, reachMax + 2, (it) => {
      if (!SPREAD_KINDS.has(it.kind) || this.queued.has(it) || !dmg.spreadable(it)) return;
      consider(it.x, it.z, this.world.scenery.radiusOf(it.kind, it.s) * 0.6, null, it, null);
    });
    for (const p of this.world.props) {
      if (!this.world.kindleable(p) || this.queued.has(p)) continue;
      consider(p.mesh.position.x, p.mesh.position.z, Math.max(p.halfW, p.halfD) * 0.6, null, null, p);
    }
    if (!cand.length) return;
    cand.sort((a, b) => a.score - b.score);
    let took = 0;
    for (const c of cand) {
      if (took >= Math.min(P.per, room)) break;
      if (this.wet(x, z, c.x, c.z)) {
        this.stats.wet++;
        continue;
      }
      took++;
      fire.n += 1;
      const delay = THREE.MathUtils.clamp(P.delay[1] - (P.delay[1] - P.delay[0]) * (c.cos + 1) * 0.5 + rand(-P.jitter, P.jitter), P.delay[0], P.delay[1]);
      if (c.cell) c.cell.state = 1;
      if (c.item) this.queued.add(c.item);
      if (c.prop) this.queued.add(c.prop);
      this.pending.push({ t: this.time + delay, fire, cell: c.cell, item: c.item, prop: c.prop });
      this.stats.spread++;
    }
  }

  private scorch(c: Cell): void {
    const S = WILDFIRE.scorch;
    this.fx.decals.add(DecalKind.Scorch, c.x + rand(-0.6, 0.6), c.z + rand(-0.6, 0.6), WILDFIRE.cell * S.size * rand(0.9, 1.1), WILDFIRE.cell * S.size * rand(0.9, 1.1), Math.random() * 6.28, S.alpha, S.life);
  }

  /** 灌木 / 草堆 / 篱墙 / 草格子烧完：原地冒一会儿余烟（走余烟预算，不占燃烧点） */
  ash(x: number, z: number, y = this.world.groundAt(x, z)): void {
    if (this.ashes.length >= WILDFIRE.cap) this.ashes.shift();
    this.ashes.push({ x, y, z, t: WILDFIRE.ash });
  }

  /** rear = 甩到身后多远收掉按的位置（T107 停车攻坚时是能退到的最远处，平时就是玩家） */
  update(dt: number, playerX: number, playerZ: number, rear = playerZ): void {
    if (dt <= 0) return;
    this.time += dt;
    this.sfxT -= dt;
    // 排队传上的：到点点着（景物 / 路障走它们自己的燃烧，点着以后再往外传）
    for (let i = this.pending.length - 1; i >= 0; i--) {
      const p = this.pending[i];
      if (p.t > this.time) continue;
      this.pending.splice(i, 1);
      if (p.cell) {
        if (p.cell.state === 1 && this.cells.get(p.cell.key) === p.cell) {
          p.cell.state = 0;
          this.start(p.cell, p.fire);
        }
      } else if (p.item) {
        this.queued.delete(p.item);
        if (p.item.alive && this.world.scenery.damage.spreadable(p.item)) {
          this.fireOf.set(p.item, p.fire);
          this.world.scenery.damage.kindle(p.item);
        }
      } else if (p.prop) {
        this.queued.delete(p.prop);
        if (this.world.kindleable(p.prop)) {
          this.fireOf.set(p.prop, p.fire);
          this.world.igniteProp(p.prop);
        }
      }
    }
    // 在烧的格子：烧够时间变焦黑 + 余烟
    for (let i = this.burning.length - 1; i >= 0; i--) {
      const c = this.burning[i];
      c.t += dt;
      if (c.t < c.dur && c.z <= rear + 60) continue;
      this.burning.splice(i, 1);
      c.state = 3;
      this.scorch(c);
      if (Math.random() < 0.5 && this.world.scenery.visible(c.x, c.z)) this.ash(c.x, c.z, c.y);
    }
    this.sync(dt, playerZ);
    this.emit(dt);
    this.hurt(dt, playerX, playerZ);
    // 甩到身后的格子收掉
    this.sweepT -= dt;
    if (this.sweepT <= 0) {
      this.sweepT = 1;
      for (const [k, c] of this.cells) if (c.z > rear + 60 && c.state !== 2) this.cells.delete(k);
      for (let i = this.pending.length - 1; i >= 0; i--) {
        const p = this.pending[i];
        const pz = p.cell?.z ?? p.item?.z ?? p.prop?.mesh.position.z ?? 0;
        if (pz > rear + 60) this.pending.splice(i, 1);
      }
    }
    this.field.commit(this.time);
  }

  /** 火苗 / 烟 / 余烟按总预算发：不管多少格在烧，每秒最多 fx.blaze 团火苗（每格 perCell 团）、fx.smoke 根烟（低画质 × low） */
  private emit(dt: number): void {
    const F = WILDFIRE.fx;
    const q = this.low ? F.low : 1;
    const n = this.burning.length;
    const nl = this.links.length;
    if (n + nl > 0) {
      this.blazeAcc += dt * Math.min(F.blaze, (n + nl) * F.perCell) * q;
      this.smokeAcc += dt * Math.min(F.smoke, n * 0.9) * q;
      while (this.blazeAcc >= 1) {
        this.blazeAcc -= 1;
        // 火舌（T126）：在草格子里 / 两处火之间的火带上随便挑一点，那里的地面火够旺才冒（火场连成片，火舌也跟着连成片，不再绕格子中心一圈）
        const r = this.rr++ % (n + nl);
        let x: number;
        let z: number;
        if (r < n) {
          const c = this.burning[r];
          const half = WILDFIRE.cell * 0.65;
          x = c.x + rand(-half, half);
          z = c.z + rand(-half, half);
        } else {
          const l = this.links[r - n];
          const t = Math.random();
          x = l.x0 + (l.x1 - l.x0) * t + rand(-1.2, 1.2);
          z = l.z0 + (l.z1 - l.z0) * t + rand(-1.2, 1.2);
        }
        const h = this.field.heatAt(x, z);
        if (h < 0.45) continue;
        this.fx.blaze(x, z, rand(1.4, 2.6), 0.25 + 0.3 * Math.min(1, h), Math.min(1, 0.3 + h));
      }
      while (this.smokeAcc >= 1 && n > 0) {
        this.smokeAcc -= 1;
        const c = this.burning[Math.floor(Math.random() * n)];
        this.fx.column(c.x + rand(-1.5, 1.5), c.y + 1.4, c.z + rand(-1.5, 1.5), 1.05, c.t / c.dur > 0.7 ? 0 : 1);
      }
    } else {
      this.blazeAcc = 0;
      this.smokeAcc = 0;
    }
    if (this.ashes.length) {
      this.ashAcc += dt * Math.min(F.smoke * 0.5, this.ashes.length * 0.35) * q;
      for (const a of this.ashes) a.t -= dt;
      while (this.ashes.length && this.ashes[0].t <= 0) this.ashes.shift();
      while (this.ashAcc >= 1 && this.ashes.length) {
        this.ashAcc -= 1;
        const a = this.ashes[Math.floor(Math.random() * this.ashes.length)];
        this.fx.column(a.x + rand(-1, 1), a.y + 0.6, a.z + rand(-1, 1), 0.7, 0);
      }
    }
  }

  /** 挨烧（很轻，不叠加）：车身在烧着的草格子里、或贴着烧着的景物；敌人同样（首领不吃，钩子里挡掉） */
  private hurt(dt: number, px: number, pz: number): void {
    const ctx = this.ctx;
    if (!ctx) return;
    this.hurtT -= dt;
    if (this.hurtT > 0) return;
    const H = WILDFIRE.hurt;
    this.hurtT = H.tick;
    if (this.burning.length === 0 && this.world.scenery.damage.burningCount === 0) return;
    const hot = (x: number, z: number, r: number): boolean => {
      const S = WILDFIRE.cell;
      if (Math.abs(x) + r + S >= WILDFIRE.grassFrom && this.burning.length) {
        for (let cx = Math.floor((x - r - X0) / S); cx <= Math.floor((x + r - X0) / S); cx++) {
          for (let cz = Math.floor((z - r) / S); cz <= Math.floor((z + r) / S); cz++) {
            const c = this.cells.get(this.key(cx, cz));
            if (c && c.state === 2 && c.t / c.dur < 0.85) return true;
          }
        }
      }
      return this.world.scenery.damage.burningNear(x, z, r + H.near);
    };
    if (ctx.players) {
      for (let i = 0; i < ctx.players.length; i++) {
        const p = ctx.players[i];
        if (p.alive !== false && hot(p.x, p.z, 1.8)) ctx.damagePlayer(H.player * H.tick, i);
      }
    } else if (hot(px, pz, 1.8)) ctx.damagePlayer(H.player * H.tick);
    const prev = dmgSrc.cur;
    dmgSrc.cur = 'barrel';
    ctx.forEachEnemy((x, z, radius, hit) => {
      if (hot(x, z, Math.min(radius, 2))) hit(H.enemy * H.tick);
    });
    dmgSrc.cur = prev;
  }

  /**
   * 写火场（T126）：草格子按烧到哪（FRONT 前烧旺，一半以后慢慢退）；正在烧的景物各写一块（FIELD.item）；
   * 两处火（景物—景物、景物—草格子）边到边不到 FIELD.link 米就连一条火带——挨着的树、成排的房子烧成一片
   */
  private sync(dt: number, pz: number): void {
    const F = this.field;
    F.decay(dt, pz);
    const S = WILDFIRE.cell;
    for (const c of this.burning) {
      const k = c.t / c.dur;
      const u = Math.min(1, k / FRONT);
      const h = k < FRONT ? u * u * (3 - 2 * u) : k < 0.5 ? 1 : Math.max(0, 1 - ((k - 0.5) / 0.4) * 0.75);
      const ch = THREE.MathUtils.smoothstep(k, 0.05, 0.45);
      F.box(c.x, c.z, S / 2, S / 2, h, ch);
    }
    const hot = this.hot;
    hot.length = 0;
    const scn = this.world.scenery;
    const H = FIELD.half;
    scn.damage.forBurning((it) => {
      if (Math.abs(it.z - pz) > 150) return;
      const h = (FIELD.item[it.kind] ?? FIELD.item.other) * Math.min(1, 0.4 + it.burn / 1.2);
      const r = THREE.MathUtils.clamp(scn.radiusOf(it.kind, it.s) * H.k, H.min, H.max);
      hot.push({ x: it.x, z: it.z, r, h });
      F.box(it.x, it.z, r, r, h, h * FIELD.char);
    });
    const links = this.links;
    links.length = 0;
    const link = (x0: number, z0: number, x1: number, z1: number, h: number) => {
      links.push({ x0, z0, x1, z1, h });
      F.line(x0, z0, x1, z1, h, h * FIELD.char * 0.8);
    };
    for (let i = 0; i < hot.length; i++) {
      const a = hot[i];
      for (let j = i + 1; j < hot.length; j++) {
        const b = hot[j];
        const d = Math.hypot(a.x - b.x, a.z - b.z);
        if (d < FIELD.linkMax && d - a.r - b.r < FIELD.link) link(a.x, a.z, b.x, b.z, Math.min(a.h, b.h) * 0.85);
      }
      // 景物和最近的一格在烧的草连起来
      let best: Cell | null = null;
      let bd = FIELD.link + S / 2 + a.r;
      for (const c of this.burning) {
        const d = Math.hypot(a.x - c.x, a.z - c.z);
        if (d < bd) {
          bd = d;
          best = c;
        }
      }
      if (best) link(a.x, a.z, best.x, best.z, a.h * 0.85);
    }
  }

  /** 调试 / 测试：格子状态统计 */
  debug(): { burning: number; burnt: number; queued: number; pending: number; cells: number; ashes: number; stats: Wildfire['stats'] } {
    let burnt = 0;
    let queued = 0;
    for (const c of this.cells.values()) {
      if (c.state === 3) burnt++;
      else if (c.state === 1) queued++;
    }
    return { burning: this.burning.length, burnt, queued, pending: this.pending.length, cells: this.cells.size, ashes: this.ashes.length, stats: { ...this.stats } };
  }

  /** 调试 / 测试：(x, z) 那一格的状态（-1 = 不是草地） */
  stateAt(x: number, z: number): number {
    const S = WILDFIRE.cell;
    const cx = Math.floor((x - X0) / S);
    const cz = Math.floor(z / S);
    const c = this.cells.get(this.key(cx, cz));
    if (c) return c.state;
    return this.isGrass(X0 + (cx + 0.5) * S, (cz + 0.5) * S) ? 0 : -1;
  }

  dispose(): void {
    this.field.dispose();
  }
}
