import * as THREE from 'three';
import type { NetValues } from './onlineProtocol';

export interface VisualRoot { object: THREE.Object3D; kind: string; args: unknown[]; nodes?: THREE.Object3D[] }
export function treeNodes(object: THREE.Object3D): THREE.Object3D[] {
  const nodes: THREE.Object3D[] = [];
  object.traverse(o => nodes.push(o));
  return nodes;
}
const q = (v: number): number => Math.round(v * 1000) / 1000;
export class VisualWriter {
  private readonly ids = new WeakMap<THREE.Object3D, number>();
  private next = 0;
  capture(roots: VisualRoot[], state: NetValues): void {
    for (const root of roots) {
      let id = this.ids.get(root.object);
      if (id === undefined) { id = ++this.next; this.ids.set(root.object, id); }
      state[`e:${id}`] = [root.kind, root.args];
      let index = 0;
      for (const o of root.nodes ?? treeNodes(root.object)) {
        const key = `n:${id}:${index++}`;
        state[key] = [
          ...o.position.toArray().map(q), ...o.quaternion.toArray().map(q), ...o.scale.toArray().map(q), +o.visible,
        ];
        const material = (o as THREE.Mesh).material as THREE.ShaderMaterial | undefined;
        if (material?.isShaderMaterial) {
          const uniforms: Record<string, number | number[]> = {};
          for (const name of ['uColor', 'uProgress', 'uTime', 'uStrong', 'uOutline', 'uShadow']) {
            const v = material.uniforms[name]?.value;
            if (typeof v === 'number') uniforms[name] = q(v);
            else if (v?.isColor) uniforms[name] = v.toArray().map(q);
          }
          state[`u:${key}`] = uniforms;
        }
      }
    }
  }
}
interface NodeView {
  object: THREE.Object3D; p: THREE.Vector3; q: THREE.Quaternion; s: THREE.Vector3;
  fromP: THREE.Vector3; fromQ: THREE.Quaternion; fromS: THREE.Vector3;
}
/** 只摆模型；不调用任何实体的战斗 update。 */
export class VisualReader {
  private readonly roots = new Map<string, { root: THREE.Object3D; signature: string; nodes: NodeView[] }>();
  private age = 1;
  /** 插值窗口（毫秒）。 */
  readonly window = 100;
  /** 本车根节点：不往模型上写，房主的姿态插值进 ownPose，由本地预测决定画在哪。 */
  own: THREE.Object3D | null = null;
  readonly ownPose = { p: new THREE.Vector3(), q: new THREE.Quaternion(), s: new THREE.Vector3(1, 1, 1) };
  constructor(private readonly create: (kind: string, args: any[]) => { object: THREE.Object3D; nodes?: THREE.Object3D[] } | null, private readonly release: (object: THREE.Object3D) => void) {}
  apply(state: NetValues): void {
    this.age = 0;
    for (const [key, item] of this.roots) if (!(key in state)) { this.release(item.root); this.roots.delete(key); }
    for (const [key, data] of Object.entries(state)) {
      if (!key.startsWith('e:')) continue;
      const [kind, args] = data as [string, any[]];
      const signature = JSON.stringify(data);
      let item = this.roots.get(key);
      if (!item || item.signature !== signature) {
        if (item) this.release(item.root);
        const made = this.create(kind, args);
        if (!made) continue;
        const root = made.object;
        const nodes: NodeView[] = [];
        for (const object of made.nodes ?? treeNodes(root)) nodes.push({ object, p: object.position.clone(), q: object.quaternion.clone(), s: object.scale.clone(), fromP: object.position.clone(), fromQ: object.quaternion.clone(), fromS: object.scale.clone() });
        item = { root, signature, nodes }; this.roots.set(key, item);
        // 新模型第一帧直接摆位，避免从原点飞来。
        for (let i = 0; i < nodes.length; i++) this.target(nodes[i], state[`n:${key.slice(2)}:${i}`], true);
      } else for (let i = 0; i < item.nodes.length; i++) this.target(item.nodes[i], state[`n:${key.slice(2)}:${i}`], false);
      for (let i = 0; i < item.nodes.length; i++) {
        const u = state[`u:n:${key.slice(2)}:${i}`] as Record<string, unknown> | undefined;
        const material = (item.nodes[i].object as THREE.Mesh).material as THREE.ShaderMaterial | undefined;
        if (!u || !material?.isShaderMaterial) continue;
        for (const [name, value] of Object.entries(u)) {
          const uniform = material.uniforms[name];
          if (!uniform) continue;
          if (typeof value === 'number' && Number.isFinite(value)) uniform.value = value;
          else if (Array.isArray(value) && uniform.value?.isColor) uniform.value.fromArray(value);
        }
      }
    }
  }
  private target(n: NodeView, raw: unknown, snap: boolean): void {
    if (!Array.isArray(raw) || raw.length !== 11 || !raw.every(Number.isFinite)) return;
    const o = this.shown(n);
    n.fromP.copy(o.p); n.fromQ.copy(o.q); n.fromS.copy(o.s);
    n.p.fromArray(raw); n.q.fromArray(raw, 3).normalize(); n.s.fromArray(raw, 7);
    n.object.visible = !!raw[10];
    if (snap || n.fromP.distanceToSquared(n.p) > 1600) {
      o.p.copy(n.p); o.q.copy(n.q); o.s.copy(n.s);
      n.fromP.copy(n.p); n.fromQ.copy(n.q); n.fromS.copy(n.s);
    }
  }
  private shown(n: NodeView): { p: THREE.Vector3; q: THREE.Quaternion; s: THREE.Vector3 } {
    if (n.object === this.own) return this.ownPose;
    const v = this.scratch;
    v.p = n.object.position; v.q = n.object.quaternion; v.s = n.object.scale;
    return v;
  }
  private readonly scratch = { p: new THREE.Vector3(), q: new THREE.Quaternion(), s: new THREE.Vector3() };
  render(dt: number): void {
    this.age = Math.min(1, this.age + dt / 0.1);
    for (const item of this.roots.values()) for (const n of item.nodes) {
      const o = this.shown(n);
      o.p.lerpVectors(n.fromP, n.p, this.age);
      o.q.slerpQuaternions(n.fromQ, n.q, this.age);
      o.s.lerpVectors(n.fromS, n.s, this.age);
    }
  }
  clear(): void { for (const item of this.roots.values()) this.release(item.root); this.roots.clear(); }
}

/** 绘制池按实例做差量。静态景物首次传矩阵，之后只传改过的槽。 */
export function captureInstances(mesh: THREE.Mesh, key: string, state: NetValues): void {
  const instanced = mesh as THREE.InstancedMesh;
  const geometry = mesh.geometry as THREE.InstancedBufferGeometry;
  const count = instanced.isInstancedMesh ? instanced.count : geometry.instanceCount;
  if (!Number.isFinite(count)) return;
  state[`c:${key}`] = count;
  state[`v:${key}`] = mesh.visible;
  const attrs: Record<string, THREE.BufferAttribute> = {};
  if (instanced.isInstancedMesh) {
    attrs.matrix = instanced.instanceMatrix;
    if (instanced.instanceColor) attrs.color = instanced.instanceColor;
  }
  for (const [name, attr] of Object.entries(geometry.attributes)) if ((attr as THREE.InstancedBufferAttribute).isInstancedBufferAttribute) attrs[name] = attr as THREE.BufferAttribute;
  for (const [name, attr] of Object.entries(attrs)) {
    for (let i = 0; i < Math.min(count, attr.count); i++) {
      state[`i:${key}:${name}:${i}`] = Array.from(attr.array.slice(i * attr.itemSize, (i + 1) * attr.itemSize)).map(q);
    }
  }
}
export function applyInstances(mesh: THREE.Mesh, key: string, state: NetValues): void {
  const instanced = mesh as THREE.InstancedMesh, geometry = mesh.geometry as THREE.InstancedBufferGeometry;
  const count = state[`c:${key}`];
  if (typeof count !== 'number' || !Number.isSafeInteger(count) || count < 0) return;
  mesh.visible = state[`v:${key}`] !== false;
  const attrs: Record<string, THREE.BufferAttribute> = {};
  if (instanced.isInstancedMesh) {
    instanced.count = Math.min(count, instanced.instanceMatrix.count);
    attrs.matrix = instanced.instanceMatrix;
    if (instanced.instanceColor) attrs.color = instanced.instanceColor;
  } else geometry.instanceCount = count;
  for (const [name, attr] of Object.entries(geometry.attributes)) if ((attr as THREE.InstancedBufferAttribute).isInstancedBufferAttribute) attrs[name] = attr as THREE.BufferAttribute;
  for (const [name, attr] of Object.entries(attrs)) {
    for (let i = 0; i < Math.min(count, attr.count); i++) {
      const a = state[`i:${key}:${name}:${i}`];
      if (Array.isArray(a) && a.length === attr.itemSize && a.every(Number.isFinite)) attr.array.set(a, i * attr.itemSize);
    }
    attr.needsUpdate = true;
  }
}
