/**
 * 火神炮声的采样合成（T088，0 字节包体）：一发 = 一个宽频爆音颗粒（脆响 + 炮口冲击 + 低频闷击 + 机件咔嗒），
 * 按每门射速 + 随机抖动排成一段可无缝循环的颗粒串；几门炮各排一股、相位错开，叠在同一段里。
 * 嗡声的音高就是射速（颗粒间隔），不是振荡器。只产出 Float32Array，AudioSystem 写进 AudioBuffer
 */

/** 两种口径的颗粒：轻 = 偏 M61 的脆（基础 / 弹幕线 / 四联），重 = 偏 GAU-8 的沉（重弹线 / 千钧） */
const GRAIN = {
  light: { len: 0.07, crack: 0.00035, crackK: 0.8, blastF: 750, blastT: 0.009, body: 0.55, bodyT: 0.018, click: 0.12 },
  heavy: { len: 0.12, crack: 0.0005, crackK: 0.55, blastF: 430, blastT: 0.017, body: 0.85, bodyT: 0.03, click: 0.08 },
} as const;
const VARIANTS = 6;
const grains = new Map<string, Float32Array[]>();

/** 一阶低通 / 高通的系数 */
const lpK = (f: number, sr: number) => 1 - Math.exp((-2 * Math.PI * f) / sr);

function peakNorm(d: Float32Array, to: number): void {
  let p = 0;
  for (let i = 0; i < d.length; i++) p = Math.max(p, Math.abs(d[i]));
  if (p > 0) for (let i = 0; i < d.length; i++) d[i] *= to / p;
}

function makeGrain(sr: number, heavy: boolean): Float32Array {
  const G = heavy ? GRAIN.heavy : GRAIN.light;
  const n = Math.floor(G.len * sr);
  const crack = new Float32Array(n);
  const blast = new Float32Array(n);
  const body = new Float32Array(n);
  const click = new Float32Array(n);
  const kHp = lpK(1200, sr);
  const kBl = lpK(G.blastF * (0.85 + Math.random() * 0.3), sr);
  const kBd = lpK(140, sr);
  const kCl = lpK(3200, sr);
  let hp = 0;
  let b1 = 0;
  let b2 = 0;
  let d1 = 0;
  let d2 = 0;
  let c1 = 0;
  const clickAt = Math.floor((0.002 + Math.random() * 0.003) * sr);
  for (let i = 0; i < n; i++) {
    const t = i / sr;
    const w = Math.random() * 2 - 1;
    hp += (w - hp) * kHp;
    crack[i] = (w - hp) * Math.exp(-t / G.crack);
    b1 += (w - b1) * kBl;
    b2 += (b1 - b2) * kBl;
    blast[i] = b2 * Math.min(1, t / 0.0004) * Math.exp(-t / G.blastT);
    d1 += (w - d1) * kBd;
    d2 += (d1 - d2) * kBd;
    body[i] = d2 * Math.min(1, t / 0.001) * Math.exp(-t / G.bodyT);
    const tc = (i - clickAt) / sr;
    c1 += (w - c1) * kCl;
    click[i] = tc >= 0 ? (w - c1) * Math.exp(-tc / 0.0003) : 0;
  }
  peakNorm(crack, G.crackK);
  peakNorm(blast, 1);
  peakNorm(body, G.body);
  peakNorm(click, G.click);
  const out = new Float32Array(n);
  const drive = Math.tanh(1.6);
  for (let i = 0; i < n; i++) out[i] = Math.tanh((crack[i] + blast[i] + body[i] + click[i]) * 1.6) / drive;
  // 最后 5 毫秒收到 0（叠的时候不咔）
  const fade = Math.floor(0.005 * sr);
  for (let i = 0; i < fade; i++) out[n - 1 - i] *= i / fade;
  return out;
}

function variants(sr: number, heavy: boolean): Float32Array[] {
  const key = `${sr}:${heavy ? 1 : 0}`;
  let v = grains.get(key);
  if (!v) {
    v = Array.from({ length: VARIANTS }, () => makeGrain(sr, heavy));
    grains.set(key, v);
  }
  return v;
}

/** 往 out 的 at 处叠一颗（loop = 绕回开头，循环段用） */
function place(out: Float32Array, g: Float32Array, at: number, k: number, loop: boolean): void {
  const N = out.length;
  for (let j = 0; j < g.length; j++) {
    let i = at + j;
    if (i >= N) {
      if (!loop) return;
      i -= N;
    }
    out[i] += g[j] * k;
  }
}

const jitterK = () => Math.pow(10, (Math.random() * 4 - 2) / 20);

/**
 * 一段循环：每门每秒 rate 发、guns 门，约 1 秒（取整到整数发，首尾接得上）；每发间隔 ±4%、音量 ±2 分贝、颗粒 6 选 1。
 * 几门炮相位随机错开、互不同步；整体按 1/√门数 收，门数多是更厚，不是更响（更响由 AudioSystem 的三档定）
 */
export function vulcanLoop(sr: number, rate: number, guns: number, heavy: boolean): Float32Array {
  const V = variants(sr, heavy);
  const n = Math.max(2, Math.round(rate));
  const N = Math.round((n / rate) * sr);
  const out = new Float32Array(N);
  const step = sr / rate;
  const amp = 1 / Math.sqrt(guns);
  for (let g = 0; g < guns; g++) {
    const phase = Math.random() * step;
    for (let k = 0; k < n; k++) {
      const at = Math.round(phase + k * step + (Math.random() * 2 - 1) * 0.04 * step);
      place(out, V[Math.floor(Math.random() * VARIANTS)], ((at % N) + N) % N, amp * jitterK(), true);
    }
  }
  return out;
}

/** 起转那一段（不循环）：dur 秒里每门射速从 from 成爬到 rate（由疏到密，不是滑音） */
export function vulcanSpinUp(sr: number, rate: number, guns: number, heavy: boolean, dur: number, from: number): Float32Array {
  const V = variants(sr, heavy);
  const out = new Float32Array(Math.ceil((dur + V[0].length / sr) * sr));
  const amp = 1 / Math.sqrt(guns);
  for (let g = 0; g < guns; g++) {
    let t = (Math.random() / (rate * from)) * 0.8;
    while (t < dur) {
      place(out, V[Math.floor(Math.random() * VARIANTS)], Math.round(t * sr), amp * jitterK() * (0.7 + 0.3 * (t / dur)), false);
      t += (1 / (rate * (from + (1 - from) * (t / dur)))) * (1 + (Math.random() * 2 - 1) * 0.04);
    }
  }
  return out;
}
