import * as THREE from 'three';
import type { GeoCache, PartSpec } from '../assets/GeoCache';
import { MAT } from '../assets/materials';
import { rockify } from '../assets/ModelKit';
import { bentStrut, splitPlank, tornSheet } from '../assets/models/shards';

/** 景物碎屑的 10 种外形（T009 4.4）：按材质分，不是规则小方块 */
export type ScnChip = 'plank' | 'branch' | 'needles' | 'brick' | 'plaster' | 'tile' | 'stone' | 'sack' | 'straw' | 'angle';

const CHIPS: ScnChip[] = ['plank', 'branch', 'needles', 'brick', 'plaster', 'tile', 'stone', 'sack', 'straw', 'angle'];
/** 一次大事件（核弹）期间只放木条和砖块两种：每种碎屑占 1 次绘制，起爆后 3 秒内景物新增绘制 ≤ 8（T009 第 8 节）；叶子 / 白灰 / 尘土用粒子 */
const EVENT_CHIPS = new Set<ScnChip>(['plank', 'brick']);
const GRAVITY = 26;

function chipParts(id: ScnChip): PartSpec[] {
  switch (id) {
    case 'plank':
      return [{ geo: splitPlank(181, 0.9, 0.18, 0.07), color: 0x7a5e40 }];
    case 'branch':
      return [
        { geo: new THREE.CylinderGeometry(0.03, 0.05, 1.1, 4), color: 0x4a3a2a, rot: [0, 0, Math.PI / 2] },
        { geo: rockify(new THREE.IcosahedronGeometry(0.28, 0), 0.35, 3), color: 0x34482b, pos: [0.35, 0.05, 0], scale: [1.4, 0.7, 1] },
        { geo: rockify(new THREE.IcosahedronGeometry(0.22, 0), 0.35, 4), color: 0x2f4027, pos: [-0.15, 0.04, 0.1], scale: [1.2, 0.7, 1] },
      ];
    case 'needles':
      return [{ geo: rockify(new THREE.IcosahedronGeometry(0.3, 0), 0.4, 5), color: 0x3a5030, scale: [1.3, 0.8, 1.1] }];
    case 'brick':
      return [{ geo: rockify(new THREE.BoxGeometry(0.28, 0.13, 0.14, 2, 1, 1), 0.12, 6), color: 0x8a5040 }];
    case 'plaster':
      return [{ geo: rockify(new THREE.BoxGeometry(0.4, 0.07, 0.32, 2, 1, 2), 0.3, 7), color: 0xd6cfbe }];
    case 'tile':
      return [{ geo: new THREE.BoxGeometry(0.32, 0.035, 0.22), color: 0x7a3b2c }];
    case 'stone':
      return [{ geo: rockify(new THREE.IcosahedronGeometry(0.22, 0), 0.4, 8), color: 0x7a7266 }];
    case 'sack':
      return [{ geo: new THREE.SphereGeometry(0.3, 6, 4), color: 0x9a8a62, scale: [1.4, 0.55, 0.8] }];
    case 'straw':
      return [
        { geo: new THREE.BoxGeometry(0.5, 0.03, 0.04), color: 0xc8a856 },
        { geo: new THREE.BoxGeometry(0.42, 0.03, 0.04), color: 0xb8994e, rot: [0, 0.6, 0.1] },
      ];
    case 'angle':
      // 撕下来的铁皮 + 一截扭弯的铁条（T185，原来是两根笔直的角铁）
      return [
        { geo: tornSheet(183, 0.035, 1.3), color: 0x4a3f36, scale: [0.8, 1, 0.55] },
        { geo: bentStrut(184), color: 0x433931, pos: [0.1, 0.08, -0.05], scale: [0.9, 1, 1] },
      ];
  }
}

interface Chip {
  alive: boolean;
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  vz: number;
  rx: number;
  ry: number;
  rz: number;
  sx: number;
  sz: number;
  s: number;
  /** 长、宽各自再乘一点（T185：同一种碎屑不再一样大小一样比例） */
  ax: number;
  az: number;
  life: number;
  ground: number;
  rest: boolean;
}

/** 一种碎屑：一个 InstancedMesh（不投影），环形复用最旧的 */
class ChipPool {
  readonly mesh: THREE.InstancedMesh;
  readonly chips: Chip[] = [];
  private next = 0;
  live = 0;

  constructor(geo: THREE.BufferGeometry, cap: number) {
    this.mesh = new THREE.InstancedMesh(geo, MAT.painted, cap);
    this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.mesh.frustumCulled = false;
    this.mesh.castShadow = false;
    this.mesh.receiveShadow = false;
    this.mesh.count = 0;
    for (let i = 0; i < cap; i++) this.chips.push({ alive: false, x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, rx: 0, ry: 0, rz: 0, sx: 0, sz: 0, s: 1, ax: 1, az: 1, life: 0, ground: 0, rest: false });
  }

  take(): Chip {
    // 先找空位，没有就复用最旧的
    for (let k = 0; k < this.chips.length; k++) {
      const i = (this.next + k) % this.chips.length;
      if (!this.chips[i].alive) {
        this.next = (i + 1) % this.chips.length;
        return this.chips[i];
      }
    }
    const c = this.chips[this.next];
    this.next = (this.next + 1) % this.chips.length;
    return c;
  }
}

/**
 * 景物碎屑池（T009 4.4 / 6.1）：10 种外形各一个 InstancedMesh、每种最多 40 块（合计 300），不投影；
 * 抛出去 → 落地弹一下 → 停 1.5～3 秒 → 沉进地里。没有活着的碎屑时 count = 0，不出绘制
 */
export class SceneryDebris {
  private readonly pools = new Map<ScnChip, ChipPool>();
  private readonly m = new THREE.Matrix4();
  private readonly q = new THREE.Quaternion();
  private readonly e = new THREE.Euler();
  private readonly p = new THREE.Vector3();
  private readonly sv = new THREE.Vector3();
  /** 地面高度（弹坑里落在坑底） */
  groundAt: (x: number, z: number) => number = () => 0;
  /** 本次大事件（核弹）还能放多少块：超出只放尘土；Infinity = 不限（不在大事件里）。大事件期间只放 EVENT_CHIPS 那几种 */
  eventLeft = Infinity;
  /** 合计上限（每种 perKind、合计 total，超出时复用同一种里最旧的） */
  private alive = 0;

  constructor(parent: THREE.Object3D, geo: GeoCache, perKind: number, private readonly total = 300) {
    for (const id of CHIPS) {
      const pool = new ChipPool(geo.merged(`scn-chip-${id}`, () => chipParts(id)), perKind);
      this.pools.set(id, pool);
      parent.add(pool.mesh);
    }
  }

  /** 抛出 n 块：从 (x, y, z) 附近，主要朝 (dx, dz) 方向（都是 0 = 四散），力度 power */
  spray(id: ScnChip, n: number, x: number, y: number, z: number, power = 1, dx = 0, dz = 0, spread = 1): number {
    if (this.eventLeft !== Infinity && !EVENT_CHIPS.has(id)) return 0;
    const pool = this.pools.get(id)!;
    let made = 0;
    for (let i = 0; i < n; i++) {
      if (this.eventLeft <= 0) break;
      if (this.eventLeft !== Infinity) this.eventLeft -= 1;
      const c = pool.take();
      // 合计满了：只能复用同一种里还活着的（最旧的），不再占新位子
      if (!c.alive && this.alive >= this.total) break;
      if (!c.alive) this.alive += 1;
      const a = Math.random() * Math.PI * 2;
      const sp = (1.5 + Math.random() * 4) * power;
      c.alive = true;
      c.rest = false;
      c.x = x + (Math.random() - 0.5) * spread;
      c.y = y + Math.random() * 0.4;
      c.z = z + (Math.random() - 0.5) * spread;
      c.vx = Math.cos(a) * sp + dx * (3 + Math.random() * 5) * power;
      c.vz = Math.sin(a) * sp + dz * (3 + Math.random() * 5) * power;
      c.vy = (3 + Math.random() * 6) * power;
      c.rx = Math.random() * 6;
      c.ry = Math.random() * 6;
      c.rz = Math.random() * 6;
      c.sx = (Math.random() - 0.5) * 12;
      c.sz = (Math.random() - 0.5) * 12;
      c.s = 0.7 + Math.random() * 0.7;
      c.ax = 0.6 + Math.random() * 0.8;
      c.az = 0.6 + Math.random() * 0.8;
      c.life = 1.6 + Math.random() * 1.6;
      c.ground = 0.04 * c.s;
      made += 1;
    }
    return made;
  }

  update(delta: number): void {
    for (const pool of this.pools.values()) {
      let n = 0;
      const mesh = pool.mesh;
      for (const c of pool.chips) {
        if (!c.alive) continue;
        c.life -= delta;
        if (c.life <= 0) {
          c.alive = false;
          this.alive -= 1;
          continue;
        }
        if (!c.rest) {
          c.vy -= GRAVITY * delta;
          c.x += c.vx * delta;
          c.y += c.vy * delta;
          c.z += c.vz * delta;
          c.rx += c.sx * delta;
          c.rz += c.sz * delta;
          const g = this.groundAt(c.x, c.z) + c.ground;
          if (c.y <= g && c.vy < 0) {
            c.y = g;
            if (Math.abs(c.vy) < 3.5) {
              c.rest = true;
              c.rx = Math.round(c.rx / Math.PI) * Math.PI;
            } else {
              c.vy *= -0.3;
              c.vx *= 0.45;
              c.vz *= 0.45;
              c.sx *= 0.4;
              c.sz *= 0.4;
            }
          }
        }
        // 最后半秒沉进地里
        const sink = c.life < 0.5 ? (0.5 - c.life) * 0.5 : 0;
        this.p.set(c.x, c.y - sink, c.z);
        this.q.setFromEuler(this.e.set(c.rx, c.ry, c.rz));
        mesh.setMatrixAt(n++, this.m.compose(this.p, this.q, this.sv.set(c.s * c.ax, c.s, c.s * c.az)));
      }
      pool.live = n;
      if (mesh.count !== n || n > 0) {
        mesh.count = n;
        mesh.instanceMatrix.needsUpdate = true;
      }
    }
  }

  /** 这一帧碎屑占的绘制次数（没有活着的碎屑的那种不出绘制） */
  get draws(): number {
    let n = 0;
    for (const p of this.pools.values()) if (p.mesh.count > 0) n += 1;
    return n;
  }

  /** 正在飞 / 躺着的碎屑总数（诊断） */
  get live(): number {
    let n = 0;
    for (const p of this.pools.values()) n += p.live;
    return n;
  }

  clear(): void {
    for (const p of this.pools.values()) {
      for (const c of p.chips) c.alive = false;
      p.live = 0;
      this.alive = 0;
      p.mesh.count = 0;
    }
  }
}
