/** 战报数据：每种来源的输出 + 每种敌人的击毁数 */
/** 结算页的军功一行（T018-5）：「军功 +1240 → 中士 72%」，升级了写「晋升中士！」 */
export function meritLine(extra: GameOverExtra): string {
  const m = extra.merit;
  if (!m) return '';
  return m.up ? `军功 +${m.gain} → 晋升${m.rank}！` : `军功 +${m.gain} → ${m.rank} ${Math.floor(m.progress * 100)}%`;
}

