  tasks?: string;
  /** 车库试驾（T030）「试驾：虎纹 · 喜欢就攒军票买下（还差 1,200）」 */
  drive?: string;
  /** 佩戴的勋章（勋章墙挑的最多 3 枚）、这局的战区威胁 */
  wear?: { tier: MedalTier; icon: string }[];
  threat?: string;
