/** 结算页「本局解锁」的勋章最多摆几枚（两行 × 7，T038）、每枚隔多久翻出来、第一枚等多久（结算页先淡入） */
export const MEDAL_ROW = { max: 14, perRow: 7, gap: 0.22, delay: 0.45, flip: 0.42, sweep: 0.6 };

/** 结算页勋章一排（DOM 版，T038）：每枚一个 .gm（勋章 SVG + 扫光），按顺序错开动画；多出来的写「+N」 */
function medalRowHtml(list: NonNullable<GameOverExtra['medals']>): string {
  const R = MEDAL_ROW;
  const shown = list.slice(0, list.length > R.max ? R.max - 1 : R.max);
  const cells = shown.map((m, i) => `<span class="gm ${m.tier}" style="--d:${(R.delay + i * R.gap).toFixed(2)}s" title="${m.name}">${medalSvg(m.tier, m.icon, true, 36)}<i></i></span>`);
  if (shown.length < list.length) cells.push(`<span class="gm more" style="--d:${(R.delay + shown.length * R.gap).toFixed(2)}s">+${list.length - shown.length}</span>`);
  return cells.join('');
}

/** 结算页军票一行的文字（两套界面一样） */
export function ticketText(t: NonNullable<GameOverExtra['ticket']>): { line: string; sub: string; btn: string } {
  return {
    line: `军票 +${t.doubled ? t.gain * 2 : t.gain}`,
    sub: t.doubled ? '（已翻倍）' : t.first ? '（今日首局 ×1.5）' : '',
    btn: t.dbl === 'off' ? '广告暂不可用' : `看广告 · 军票 +${t.gain} → +${t.gain * 2}`,
  };
}

/** 晋升那一块的标题（上将 = 将官晋升，元帅 = 授衔） */
export const promoTitle = (p: NonNullable<GameOverExtra['promo']>) => (p.level >= 20 ? `授衔 · ${p.name}` : p.level === 18 ? `将官晋升 · ${p.name}` : `晋升 ${p.name}`);

export interface ReportData {
  players?: { name: string; report: ReportData }[];
  total: number;
  /** sub = 缩进挂在上一行下面的明细（炼狱的「└ 熔甲加成」） */
  rows: { label: string; icon: string; value: number; sub?: boolean }[];
  kills: { label: string; n: number }[];
  /** 副武器合计占总输出的比例（0..1，T018-1「副武器贡献 38%」）；没有副武器输出时不写 */
  subShare?: number;
  /** 「生存」一栏（T023-a）：自动维修 / 回收修车 / 护盾挡下 / 护甲挡下 */
  survive?: { label: string; value: number }[];
}

/** 战报「武器输出」那一节的标题：有副武器输出时带上「副武器贡献 N%」（T018-1） */
export const reportTitle = (d: ReportData) => (d.subShare ? `武器输出 · 副武器贡献 ${Math.round(d.subShare * 100)}%` : '武器输出');

/** 大数写「1.0 万」（T018-2：玩家看得到的文案不用英文字母） */
export const fmtNum = (v: number) => (v >= 10000 ? `${(v / 10000).toFixed(1)} 万` : String(Math.round(v)));

/** 战报 HTML（战斗中的面板和结算页共用） */
function reportHtml(d: ReportData, killLimit = 99): string {
  if (d.players) return d.players.map(p => `<section class="coop-report"><h3>${p.name} · 总输出 ${fmtNum(p.report.total)}</h3>${reportHtml(p.report, killLimit)}</section>`).join('');
  const max = Math.max(1, ...d.rows.map((r) => r.value));
  const rows = d.rows.length
    ? d.rows
        .map((r) => `<div class="rep-row${r.sub ? ' sub' : ''}">${r.icon ? icon(r.icon) : '<i></i>'}<span class="name">${r.label}</span><span class="val">${fmtNum(r.value)} · ${Math.round((r.value / Math.max(1, d.total)) * 100)}%</span><span class="bar"><i style="width:${(r.value / max) * 100}%"></i></span></div>`)
        .join('')
    : '<div class="rep-kill">还没有输出</div>';
  const kills = d.kills.length
    ? d.kills.slice(0, killLimit).map((k) => `<div class="rep-kill"><span>${k.label}</span><b>×${k.n}</b></div>`).join('')
    : '<div class="rep-kill">还没有击毁</div>';
  const surv = d.survive ? `<div class="rep-sec">生存</div>${d.survive.map((r) => `<div class="rep-kill surv"><span>${r.label}</span><b>${fmtNum(r.value)}</b></div>`).join('')}` : '';
  return `<div class="rep-sec">${reportTitle(d)}</div>${rows}${surv}<div class="rep-sec">击毁敌军</div>${kills}`;
}

