import type { HouseLook } from '../assets/models/houseStyles';
import type { SceneryLook, TreeLook } from '../assets/models/sceneryLooks';
import type { Theme } from './themes';

export const DRESS_STEP = 48;
export const DRESS_AHEAD = 240;

export interface ScenerySite {
  kind: 'pine' | 'house' | 'bush';
  x: number;
  z: number;
  rot: number;
  scale: number;
  look?: SceneryLook;
}

/** 只读区块坐标，不消费原远景、路肩、路障或刷怪的随机序列。 */
const noise = (n: number) => {
  const v = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return v - Math.floor(v);
};

/** 每侧四十八米一块。林间留空隙，街区留巷口；原来零散的景物继续做前景。 */
export function sceneryLayout(top: number, side: number, theme: Theme['id'], put: (site: ScenerySite) => void): void {
  const block = Math.round(-top / DRESS_STEP), phase = Math.abs(block) + (side > 0 ? 1 : 0);
  const seed = block * 193 + side * 71;
  const tree = (x: number, z: number, n: number, forest = false) => {
    const pick = noise(n + 7);
    const look: TreeLook = pick < (forest ? .48 : .18) ? 'spruce' : pick < .76 ? 'oak' : 'birch';
    put({ kind: 'pine', x: side * x, z, look, scale: .86 + noise(n + 3) * .29, rot: noise(n + 5) * Math.PI * 2 });
  };
  const house = (x: number, z: number, n: number, looks: HouseLook[]) => put({
    kind: 'house', x: side * x, z, look: looks[Math.floor(noise(n + 11) * looks.length)],
    scale: .94 + noise(n + 13) * .1, rot: -side * Math.PI / 2,
  });

  if (theme === 'farmland' || theme === 'forest') {
    const forest = theme === 'forest', grove = forest || phase % 3 === 0;
    if (grove) {
      const rows = forest && phase % 5 === 4 ? 2 : 4;
      for (let row = 0; row < rows; row++) for (let col = 0; col < 7; col++) {
        // 椭圆林缘加错位，避免整片树林排成苗圃方格。
        if (((row - 1.5) / 1.85) ** 2 + ((col - 3) / 3.6) ** 2 > 1.3) continue;
        const n = seed + row * 47 + col * 17;
        const x = 24.8 + row * 5.6 + (noise(n) - .5) * 3;
        const z = top - 5 - col * 5.9 + (noise(n + 1) - .5) * 3;
        tree(x, z, n, forest);
        if (col % 3 === 1 && row < 2) put({ kind: 'bush', x: side * (x + 1.5), z: z + 2,
          rot: noise(n + 2) * 6.28, scale: .8 + noise(n + 4) * .35 });
      }
    } else {
      for (let i = 0; i < 3; i++) tree(29 + noise(seed + i * 5) * 20, top - 8 - i * 14, seed + i * 13);
      if (phase % 4 === 1) {
        house(31, top - 15, seed, ['cottage', 'timber']);
        house(42, top - 21, seed + 31, ['cottage']);
      }
    }
    return;
  }
  if (theme === 'village') {
    const front = 26.4 + (noise(seed) - .5) * .8;
    for (let i = 0; i < 5; i++) house(front, top - 5 - i * 8.6, seed + i * 19, ['town', 'timber', 'brick', 'cottage']);
    // 后排与临街排错开；每块末端空出巷道，远处仍能看见第二层屋顶。
    for (let i = 0; i < 4; i++) house(37.2 + noise(seed + i) * 2, top - 8 - i * 10.8, seed + i * 37, ['town', 'brick', 'timber']);
    tree(26.5, top - 46, seed + 113);
  } else if (theme === 'foundry' && phase % 2 === 0) {
    // 厂区只补职工街屋，保留烟囱、储罐和厂棚的主轮廓。
    for (let i = 0; i < 3; i++) house(29.5, top - 8 - i * 9, seed + i * 19, ['brick', 'town']);
    for (let i = 0; i < 2; i++) house(40, top - 12 - i * 11, seed + i * 37, ['brick']);
  }
}
