import type { CoreId } from '../weapons/defs';
import type { Card } from '../weapons/Arsenal';
import type { Overlay } from '../ui/canvas/Overlay';
import { OnlineLobby } from '../ui/onlineLobby';
import { OnlineRoom, hasInvite, takeInvite } from './onlineRoom';
import { NetStats, NET_DEBUG } from './netStats';
import { DeltaReceiver, DeltaSender, ONLINE_INPUT, ONLINE_SEND, ONLINE_STEP, ONLINE_TIMEOUT, RemoteInput, validInput, validPacket, type NetDelta, type NetInput, type NetValues } from './onlineProtocol';

export interface OnlineBridge {
  begin(cores: [CoreId, CoreId], guest: boolean): void;
  step(dt: number, elapsed: number): void;
  state(): NetValues;
  receive(state: NetValues): void;
  render(dt: number): void;
  input(previous: NetInput): NetInput;
  remote(input: RemoteInput): void;
  pick(player: 0 | 1, key: string, offer: number): void;
  stop(): void;
  back(): void;
  notice(title: string, sub: string): void;
  result(): string[] | null;
  /** 队友端插值窗口（毫秒），调试面板用。 */
  buffer(): number;
}
export class OnlineBattle {
  readonly room = new OnlineRoom();
  readonly lobby: OnlineLobby;
  readonly remote = new RemoteInput();
  readonly stats = new NetStats();
  private work = 0;
  active = false;
  private clock = 0;
  private accumulator = 0;
  private sendAt = 0;
  private sender = new DeltaSender();
  private receiver = new DeltaReceiver();
  private received: NetValues = Object.create(null);
  private lastInput = -1;
  private inputSeq = 0;
  private input: NetInput = { x: 0, forward: 0, dragX: 0, dragY: 0, sweep: 0, held: false, aim: null, fire: 0, ult: 0 };
  private pickRequest: { key: string; offer: number } | null = null;
  private ended = false;
  private progressAt = 0;
  private inputAt = 0;
  /** 队友端：每号输入发出时的联机时钟，对时用。 */
  private readonly inputClock = new Map<number, number>();
  get alpha(): number { return Math.min(1, this.accumulator / ONLINE_STEP); }
  /** 联机时钟（累计 dt，秒）。 */
  get now(): number { return this.clock; }
  /** 下一包输入的序号：这一帧读到的按键会跟它一起发。 */
  get nextInput(): number { return this.inputSeq + 1; }
  sentAt(seq: number): number | null { return this.inputClock.get(seq) ?? null; }
  constructor(overlay: Overlay | null, private readonly bridge: OnlineBridge) {
    this.lobby = new OnlineLobby(overlay, this.room, () => { this.active = false; bridge.back(); });
    this.room.onChange = () => this.lobby.refresh();
    this.room.stats = this.stats;
    this.room.onStart = () => {
      this.sender = new DeltaSender(); this.receiver = new DeltaReceiver(); this.received = Object.create(null);
      this.lastInput = -1; this.inputSeq = 0; this.inputClock.clear(); this.clock = this.accumulator = this.sendAt = 0;
      this.progressAt = this.inputAt = 0;
      this.input = { x: 0, forward: 0, dragX: 0, dragY: 0, sweep: 0, held: false, aim: null, fire: 0, ult: 0 };
      this.remote.accept({ ...this.input }); this.remote.clear();
      this.pickRequest = null; this.ended = false;
      this.lobby.result = []; this.lobby.show(false);
      bridge.begin([...this.room.view.cores], !this.room.view.host);
      bridge.remote(this.remote);
    };
    this.room.onStop = () => {
      if (!__WX__) this.lobby.result = [];
      bridge.stop(); this.lobby.show(true);
    };
    this.room.onHeld = held => { if (this.room.playing) bridge.notice(held ? '等待队友' : '队友已返回', held ? '队友暂时离开，战场已停住' : ''); };
    this.room.onMessage = (kind, data) => {
      if (!this.room.playing) return;
      if (this.room.view.host) {
        if (kind === 'input' && Number.isSafeInteger(data?.seq) && data.seq > this.lastInput && validInput(data.value)) {
          this.lastInput = data.seq; this.inputAt = this.clock; this.remote.accept(data.value);
        } else if (kind === 'ack' && Number.isSafeInteger(data)) {
          if (this.sender.ack(data)) this.progressAt = this.clock;
        }
        else if (kind === 'pick' && typeof data?.key === 'string' && Number.isSafeInteger(data.offer)) bridge.pick(1, data.key, data.offer);
      } else if (kind === 'state' && validPacket(data)) {
        const state = this.receiver.accept(data);
        if (!state) { this.stats.dropped(); return; }
        this.received = state;
        this.progressAt = this.clock;
        this.room.send('ack', data.seq);
        this.stats.state(this.room.lastSize);
        if (Number.isSafeInteger(state.ack)) this.stats.inputAck(state.ack as number);
        bridge.receive(state);
        const pick = state.pick as { offer?: number } | null | undefined;
        if (pick?.offer !== this.pickRequest?.offer) this.pickRequest = null;
      }
    };
  }
  /** restore：冷启动时有房间缓存，回原房间。 */
  open(restore = false): void {
    this.active = true; this.lobby.result = []; this.lobby.show(true);
    if (this.room.view.room || this.room.view.busy) return;
    // 从邀请卡片进来的直接加入。
    if (hasInvite()) void this.room.enter(takeInvite());
    else if (restore) this.room.restore();
  }
  /** 返回 true 表示本帧由联机分支接管。 */
  update(dt: number): boolean {
    if (!this.active) return false;
    const began = performance.now();
    try { return this.tick(dt); } finally { this.work += performance.now() - began; }
  }
  /** 画面那一半耗时由 Game.drawFrame 报上来。 */
  drawn(ms: number): void { this.work += ms; }
  private tick(dt: number): boolean {
    if (this.room.playing) { this.stats.role = this.room.view.host ? '房主' : '队友'; this.stats.buffer = this.bridge.buffer(); this.stats.frame(dt, this.work); }
    this.work = 0;
    this.lobby.tick(dt);
    this.room.tick(dt);
    if (!__WX__ && document.hidden) return true;
    if (!this.room.playing) { this.bridge.render(dt); return true; }
    this.clock += dt;
    // 队友暂离时不计同步超时，房主也不推进战场。
    if (this.room.held) this.progressAt = this.inputAt = this.clock;
    if (this.clock - this.progressAt > ONLINE_TIMEOUT) { this.room.stop('同步中断，本局结束'); return true; }
    if (this.room.view.host) {
      if (this.clock - this.inputAt > 0.4) this.remote.clear();
      if (this.clock - this.inputAt > ONLINE_TIMEOUT) { this.room.stop('输入中断，本局结束'); return true; }
      if (this.room.held) { this.remote.clear(); return true; }
      this.accumulator += Math.min(dt, 0.1);
      while (this.accumulator >= ONLINE_STEP && !this.ended) {
        this.bridge.step(ONLINE_STEP, this.clock - this.accumulator);
        this.accumulator -= ONLINE_STEP;
        const result = this.bridge.result();
        if (result) { this.ended = true; this.lobby.result = result; this.lobby.show(true); }
      }
      if (this.due(ONLINE_SEND)) {
        const state = this.bridge.state();
        state.result = this.ended ? this.lobby.result : null;
        state.ack = this.lastInput;
        state.ackAge = Math.round((this.clock - this.inputAt) * 1000) / 1000;
        const packet = this.sender.next(state);
        this.stats.state(this.room.send('state', packet)); this.stats.behind(packet.seq - packet.base); this.stats.keys = Object.keys(state).length;
        if (NET_DEBUG) this.stats.top = families(packet.delta);
      }
    } else {
      this.input = this.bridge.input(this.input);
      if (this.due(ONLINE_INPUT)) {
        this.room.send('input', { seq: ++this.inputSeq, value: this.input });
        this.inputClock.set(this.inputSeq, this.clock);
        if (this.inputClock.size > 200) this.inputClock.delete(this.inputClock.keys().next().value!);
        this.stats.inputOut(this.inputSeq);
        if (this.pickRequest) this.room.send('pick', this.pickRequest);
      }
      this.bridge.render(dt);
      if (Array.isArray(this.received.result) && !this.ended) {
        this.ended = true; this.lobby.result = this.received.result as string[]; this.lobby.show(true);
      }
    }
    return true;
  }
  /** 发包按真实时间排：掉帧时主循环的 dt 封顶 0.05 秒，按它数会越发越慢。 */
  private due(every: number): boolean {
    const now = performance.now() / 1000;
    if (now < this.sendAt) return false;
    this.sendAt = Math.max(this.sendAt + every, now - every);
    return true;
  }
  pick(card: Card, offer: number): void {
    if (this.room.view.host) this.bridge.pick(0, card.key, offer);
    else { this.pickRequest = { key: card.key, offer }; this.room.send('pick', this.pickRequest); }
  }
  ult(): void { this.input.ult++; }
  dispose(): void { this.lobby.show(false); this.stats.dispose(); void this.room.leave(); }
}
/** 差量里各类条目的字节，取前四。 */
function families(delta: NetDelta): string {
  const size = new Map<string, number>();
  for (const [key, value] of [...Object.entries(delta.put), ...Object.entries(delta.part ?? {})]) {
    const parts = key.split(':');
    const name = parts[0] === 'i' || parts[0] === 'c' || parts[0] === 'v' ? `${parts[0]}:${parts[1].split('/')[0]}` : parts[0] === 'u' ? 'u' : parts[0];
    size.set(name, (size.get(name) ?? 0) + key.length + JSON.stringify(value).length);
  }
  return [...size].sort((a, b) => b[1] - a[1]).slice(0, 4).map(([k, v]) => `${k}=${(v / 1024).toFixed(1)}`).join(' ');
}
