/** 一局里的统计（判定用；不进存档：读档后重新累计，长期统计按 Profile） */
export interface RunTally {
  crush: number;
  barrels: number;
  burnt: number;
  rods: number;
  /** 每日任务（T030）：击毁的精英 / 副武器击毁 / 击败泰坦 / 满耐久击败首领 / 击败轰天 / 一次究极最多击毁几个 */
  elites: number;
  subKills: number;
  titan: number;
  fullBoss: number;
  siege: number;
  ultBest: number;
}
export const freshTally = (): RunTally => ({ crush: 0, barrels: 0, burnt: 0, rods: 0, elites: 0, subKills: 0, titan: 0, fullBoss: 0, siege: 0, ultBest: 0 });

/** 已经拿到的成就点 */
export function achPoints(unlocks: readonly string[]): number {
  let n = 0;
  for (const a of ACHIEVEMENTS) if (unlocks.includes(`ach:${a.id}`)) n += TIER_POINTS[a.tier];
  return n;
}
