/** 房间广播只转发数据；只有房主推进战斗。 */
export const ONLINE_VERSION = 2;
export const ONLINE_STEP = 1 / 60;
export const ONLINE_SEND = 0.1;
/** 队友输入每秒 30 包（小游戏 20 包，官方建议 40 毫秒左右一批）：本车走位已在本地预测，这里只缩短房主那边的判定延迟。 */
export const ONLINE_INPUT = __WX__ ? 1 / 20 : 1 / 30;
export const ONLINE_TIMEOUT = 8;
export type NetValues = Record<string, unknown>;
/** part：对象值只发改了的字段（字段名 → 新值；drop 是删掉的字段）。 */
export interface NetDelta { put: NetValues; drop: string[]; part?: Record<string, { put: NetValues; drop: string[] }> }
/** 一包状态：base = 差量基于哪一包（0 = 空状态）。 */
export interface NetPacket { seq: number; base: number; delta: NetDelta }

const unsafe = (key: string): boolean => key === '__proto__' || key === 'constructor' || key === 'prototype';
const plain = (v: unknown): v is NetValues => !!v && typeof v === 'object' && !Array.isArray(v);
/** 每个键的序列化结果，比对和下一包复用，不重复序列化。 */
type Sent = { values: NetValues; json: Map<string, string> };
const EMPTY: Sent = { values: Object.create(null), json: new Map() };

function diff(before: Sent, after: NetValues): { delta: NetDelta; json: Map<string, string> } {
  const put: NetValues = Object.create(null), json = new Map<string, string>();
  const part: NonNullable<NetDelta['part']> = Object.create(null);
  let parts = false;
  for (const key of Object.keys(after)) {
    const value = after[key], text = JSON.stringify(value) ?? 'null';
    json.set(key, text);
    if (before.json.get(key) === text) continue;
    const old = before.values[key];
    if (plain(old) && plain(value)) {
      // 两边都是对象：逐字段比，只发变了的那几个。
      // 值为 undefined 的字段序列化时会消失，按删掉算。
      const p: NetValues = Object.create(null);
      for (const field of Object.keys(value)) if (value[field] !== undefined && JSON.stringify(old[field]) !== JSON.stringify(value[field])) p[field] = value[field];
      part[key] = { put: p, drop: Object.keys(old).filter(field => old[field] !== undefined && value[field] === undefined) };
      parts = true;
    } else put[key] = value;
  }
  const delta: NetDelta = { put, drop: [...before.json.keys()].filter(key => !json.has(key)) };
  if (parts) delta.part = part;
  return { delta, json };
}
export function patchValues(state: NetValues, delta: NetDelta): void {
  for (const key of delta.drop) delete state[key];
  for (const key of Object.keys(delta.put)) if (!unsafe(key)) state[key] = delta.put[key];
  for (const key of Object.keys(delta.part ?? {})) {
    const p = delta.part![key];
    if (unsafe(key) || !plain(p?.put) || !Array.isArray(p.drop)) continue;
    // 拼成新对象，不改留着当基线的旧对象。
    const next: NetValues = Object.assign(Object.create(null), plain(state[key]) ? state[key] : null);
    for (const field of p.drop) delete next[field];
    for (const field of Object.keys(p.put)) if (!unsafe(field)) next[field] = p.put[field];
    state[key] = next;
  }
}
export function validPacket(data: any): data is NetPacket {
  return !!data && Number.isSafeInteger(data.seq) && data.seq > 0 && Number.isSafeInteger(data.base) && data.base >= 0 && data.base < data.seq
    && plain(data.delta?.put) && Array.isArray(data.delta.drop) && (data.delta.part === undefined || plain(data.delta.part));
}

/**
 * 不等确认：每包都以对方最近确认的那包为基线算差量，发出就不管。
 * 丢了一包，下一包的差量照样从已确认的基线算，丢掉的内容自然带上；没确认前，选卡、结算这类关键内容每包都在。
 */
export class DeltaSender {
  private readonly sent = new Map<number, Sent>();
  private base = 0;
  private seq = 0;
  next(state: NetValues): NetPacket {
    const { delta, json } = diff(this.sent.get(this.base) ?? EMPTY, state);
    const seq = ++this.seq;
    this.sent.set(seq, { values: state, json });
    // 对方很久没确认：只留基线和最近几包，免得越攒越多。
    if (this.sent.size > 64) for (const key of this.sent.keys()) { if (key !== this.base) { this.sent.delete(key); break; } }
    return { seq, base: this.base, delta };
  }
  /** 对方收到第 seq 包；更早的包不用再留。 */
  ack(seq: number): boolean {
    if (seq <= this.base || !this.sent.has(seq)) return false;
    this.base = seq;
    for (const key of this.sent.keys()) if (key < seq) this.sent.delete(key);
    return true;
  }
}

/** 队友端：留着最近收到的完整状态，新包按它声明的基线拼出来；比已显示的旧的包直接丢。 */
export class DeltaReceiver {
  private readonly kept = new Map<number, NetValues>();
  latest = 0;
  accept(packet: NetPacket): NetValues | null {
    if (packet.seq <= this.latest) return null;
    const from = packet.base === 0 ? EMPTY.values : this.kept.get(packet.base);
    if (!from) return null;
    const state: NetValues = Object.assign(Object.create(null), from);
    patchValues(state, packet.delta);
    this.kept.set(packet.seq, state);
    this.latest = packet.seq;
    // 房主的基线只会往后走，比这包基线早的用不上了。
    for (const key of this.kept.keys()) if (key < packet.base || this.kept.size > 64) this.kept.delete(key);
    return state;
  }
}

export interface NetInput {
  x: number; forward: number; dragX: number; dragY: number;
  sweep: number; held: boolean; aim: number | null;
  fire: number; ult: number;
}
export function validInput(value: unknown): value is NetInput {
  if (!value || typeof value !== 'object') return false;
  const v = value as NetInput;
  return ['x', 'forward', 'dragX', 'dragY', 'sweep', 'fire', 'ult'].every(k => Number.isFinite(v[k as keyof NetInput]))
    && Math.abs(v.x) <= 1 && Math.abs(v.forward) <= 1
    && (v.aim === null || (Number.isFinite(v.aim) && Math.abs(v.aim) <= Math.PI))
    && typeof v.held === 'boolean' && Number.isSafeInteger(v.fire) && Number.isSafeInteger(v.ult)
    && v.fire >= 0 && v.ult >= 0;
}

/** 手势累计量和按钮计数随包携带，重发不会重复消费。 */
export class RemoteInput {
  value: NetInput = { x: 0, forward: 0, dragX: 0, dragY: 0, sweep: 0, held: false, aim: null, fire: 0, ult: 0 };
  private used = { dragX: 0, dragY: 0, sweep: 0, fire: 0, ult: 0 };
  accept(value: NetInput): void { this.value = value; }
  take(key: keyof RemoteInput['used']): number {
    const delta = this.value[key] - this.used[key];
    this.used[key] = this.value[key];
    return key === 'fire' || key === 'ult' ? Math.max(0, Math.min(1, delta)) : Math.max(-1, Math.min(1, delta));
  }
  clear(): void {
    this.value.x = this.value.forward = 0;
    this.value.held = false;
    for (const key of Object.keys(this.used) as (keyof RemoteInput['used'])[]) this.used[key] = this.value[key];
  }
}
