import type { InkContext } from './types';

/** 纹理独立取样，不占用游戏的随机序列。 */
export function random(seed: number): () => number {
  let n = seed >>> 0;
  return () => {
    n ^= n << 13; n ^= n >>> 17; n ^= n << 5;
    return (n >>> 0) / 4294967296;
  };
}

export function line(c: InkContext, x: number, y: number, x2: number, y2: number, color: string, width = 1): void {
  c.beginPath(); c.moveTo(x, y); c.lineTo(x2, y2);
  c.strokeStyle = color; c.lineWidth = width; c.stroke();
}

export function rivet(c: InkContext, x: number, y: number, size = 2, brass = false): void {
  const g = c.createLinearGradient(x - size, y - size, x + size, y + size);
  g.addColorStop(0, brass ? '#d0b180' : '#aeb5a2');
  g.addColorStop(0.45, brass ? '#87714b' : '#616b5b');
  g.addColorStop(1, '#101512');
  c.fillStyle = '#0b100c';
  c.beginPath(); c.arc(x, y + 1, size + 1, 0, Math.PI * 2); c.fill();
  c.fillStyle = g;
  c.beginPath(); c.arc(x, y, size, 0, Math.PI * 2); c.fill();
  line(c, x - size * 0.6, y, x + size * 0.6, y, '#293026', 0.7);
}

export function hatch(c: InkContext, x: number, y: number, w: number, h: number, ink: string, step = 12): void {
  c.save(); c.beginPath(); c.rect(x, y, w, h); c.clip();
  c.fillStyle = ink;
  for (let i = -h; i < w + h; i += step) {
    c.beginPath(); c.moveTo(x + i, y); c.lineTo(x + i + step * 0.46, y);
    c.lineTo(x + i + step * 0.46 - h, y + h); c.lineTo(x + i - h, y + h);
    c.closePath(); c.fill();
  }
  c.restore();
}

export function scratches(c: InkContext, seed: number, count: number, warm = false): void {
  const rnd = random(seed);
  for (let i = 0; i < count; i++) {
    const x = rnd() * 256, y = rnd() * 256;
    const bright = rnd() > 0.5;
    c.fillStyle = bright ? `rgba(240,233,204,${rnd() * 0.075})` : `rgba(0,0,0,${rnd() * 0.16})`;
    c.fillRect(x, y, rnd() * 1.5 + 0.4, rnd() * 1.5 + 0.4);
    if (i % 8 === 0) line(c, x, y, x + 2 + rnd() * 20, y - rnd() * 2, bright ? 'rgba(229,225,192,.14)' : 'rgba(0,0,0,.22)', 0.6);
    if (warm && i % 35 === 0) {
      c.fillStyle = 'rgba(147,88,44,.18)';
      c.beginPath(); c.arc(x, y, rnd() * 7 + 1, 0, Math.PI * 2); c.fill();
    }
  }
}
