/** 储备格里的副武器只是一条记录：不建模型、不更新、不进联动和战报。 */
export interface ReserveItem { uid: number; id: WeaponId; level: number; slot: number }

const createCore = (id: CoreId): Core => (id === 'vulcan' ? new VulcanCore(CORES.vulcan) : baseCore(id));

export type CardKind = 'core' | 'branch' | 'coreEvo' | 'weapon' | 'evolve' | 'mod' | 'super' | 'heal' | 'fusion' | 'link';
export type Rarity = 'common' | 'rare' | 'legend' | 'super';

export interface Card {
  key: string;
  kind: CardKind;
  id: string;
  name: string;
  /** 图标 id（见 ui/icons.ts） */
  icon: string;
  tag: string;
  from: number;
  to: number;
  max: number;
  rarity: Rarity;
  /** 副武器的蓝卡是成品等级，不是给现有武器加两级。 */
  rareLabel?: string;
  lines: string[];
  hint?: string;
  /** 合成卡的公式条：〔核心〕+〔A〕+〔B〕→〔结果〕的图标 id */
  formula?: string[];
  /** 红字警告（合成不可撤销） */
  warn?: string;
  /** 固定卡与超级改装不能单卡重抽。 */
  fixed?: boolean;
  /** 这张是换上来的（这一格这次升级已经换过一次，不能再换） */
  rerolled?: boolean;
}

export interface SlotView {
  kind: 'core' | 'weapon' | 'mod' | 'empty-weapon' | 'empty-mod';
  /** 详情面板用：core / 武器 / 改装件 id */
  id: string;
  icon: string;
  level: number;
  evolved: boolean;
  /** 核心格：已合成的终极图标 id（红铜边框 + 右上角小图标，★ 保留） */
  ult?: string;
  /** 核心格：合成条件已满足（呼吸光 + 「可合成」角标） */
  ready?: boolean;
  /** 副武器格：参与了哪组联动（T018-link，右下角「联」角标） */
  link?: string;
  /** 空格：点开说明里多一行（这一局几个槽、去哪里加开，T033） */
  note?: string;
  slot?: number;
  uid?: number;
  locked?: boolean;
}

/** 终极行 / 终极键要显示的状态（Hud.setUlt） */
export interface UltView {
  id: string;
  icon: string;
  name: string;
  state: UltState;
  /** 冷却进度 0..1 */
  progress: number;
  label: string;
}

/** 军械库：流派核心 + 副武器 + 改装件，负责抽卡与升级 */
export class Arsenal {
  core: Core = createCore('cannon');
  readonly weapons: Weapon[] = [];
  /** 储备格（T243，三格）：装配页可以放进、取出、合成。 */
  readonly reserve: ReserveItem[] = [];
  readonly mods = new Map<ModId, number>();
  /** 本局打出的联动改装（T018-link） */
  readonly links = new Set<LinkId>();
  /** 合成出来的终极武器（独立模块，见 fusions/）；没合成为 null */
  ult: Ultimate | null = null;
  /** 这一局有几个副武器槽（装配车间；reset 不动它）。改装不设槽位限制。 */
  weaponSlots = WEAPON_SLOTS;
  playerLevel = 1;
  private nextUid = 1;
  /** 究极怎么放（T055：合成卡提示行 / 核心格详情按设置写，Game 设成 ui/ctrlText.ts 的 ultHow）：自动 / 手动、电脑多一个右键 */
  ultHow = '点究极键发射';
  private readonly view: UltView = { id: '', icon: '', name: '', state: 'ready', progress: 1, label: '' };
  stats: ModStats = computeModStats(new Map());
  /** 改装件变化时回调（耐久、护盾、拾取范围由游戏层同步到坦克） */
  onStats: ((s: ModStats) => void) | null = null;
  /** 核心等级 / 分支 / 终极变化时回调（换炮塔模型） */
  onCore: ((core: Core) => void) | null = null;
  /** 选了合成卡：交给游戏层做合成演出（焊接电弧 + 套件弹出），换炮塔套件也在演出里做；没设置时直接走 onCore */
  onFuse: ((def: FusionDef) => void) | null = null;
  /** 炮塔转身限位（T127）：按车尾挂件算，写进 Tank.arc */
  private readonly traverse = new Traverse();

  constructor(
    private readonly geo: GeoCache,
    private readonly anchors: THREE.Object3D[],
  ) {}

  /** 合成试玩开局就开放六格；局外军衔记录仍保留。 */
  setSlots(_weapon: number): void {
    this.weaponSlots = WEAPON_SLOTS;
  }

  /** 开新局：选定流派，清空所有改装 */
  reset(coreId: CoreId = this.core.id): void {
    for (const w of this.weapons) w.dispose();
    this.weapons.length = 0;
    this.reserve.length = 0;
    this.nextUid = 1;
    this.playerLevel = 1;
    this.mods.clear();
    this.links.clear();
    this.ult?.dispose();
    this.ult = null;
    this.core = createCore(coreId);
    this.core.reset();
    this.refresh();
    this.onCore?.(this.core);
  }

  update(ctx: CombatContext): void {
    const previousPlayer = dmgSrc.player;
    dmgSrc.player = ctx.playerId ?? 0;
    this.traverse.update(ctx.tank, this.weapons);
    // 每件武器更新时标上伤害来源，战报按武器统计输出
    dmgSrc.cur = 'core';
    this.core.update(ctx);
    ctx.tank.beginHullDraw();
    ctx.tank.group.updateMatrixWorld(true);
    try {
      for (const w of this.weapons) {
        dmgSrc.cur = w.def.id;
        w.prepareFrame(ctx);
        w.animate(ctx);
        w.update(ctx);
        w.after(ctx);
      }
    } finally {
      ctx.tank.endHullDraw();
      dmgSrc.cur = 'other';
      dmgSrc.player = previousPlayer;
    }
  }

  /** 挂位在前、储备在后；装配页和合成规则都读这一份。 */
  subItems(): SubItem[] {
    return [
      ...this.weapons.map(w => ({ uid: w.uid, id: w.def.id, level: w.level, slot: w.slot, link: w.link, locked: !!w.ult })),
      ...this.reserve.map(r => ({ uid: r.uid, id: r.id, level: r.level, slot: r.slot, link: null, locked: false })),
    ];
  }

  bestWeapon(id: WeaponId): Weapon | undefined {
    return this.weapons.filter(w => w.def.id === id).sort((a, b) => b.level - a.level || Number(!!b.link) - Number(!!a.link) || a.uid - b.uid)[0];
  }

  planSub(target: number, reward: SubReward | null, source?: number): SubPlan | null {
    return planSub(this.subItems(), target, reward, source);
  }

  /** 独立装备实例。读档和调试也经过同一条入口，不覆盖同型号的另一件。 */
  addSub(id: WeaponId, level = 1, slot = SUB_PREFERS[id].find(s => !this.weapons.some(w => w.slot === s))): Weapon | null {
    if (slot === undefined || !SUB_SLOTS.includes(slot as typeof SUB_SLOTS[number]) || this.weapons.some(w => w.slot === slot) || this.weapons.length >= WEAPON_SLOTS) return null;
    return this.spawnSub(id, level, slot, this.nextUid++);
  }

  private spawnSub(id: WeaponId, level: number, slot: number, uid: number): Weapon {
    const w = createWeapon(WEAPONS[id], this.anchors[slot], slot, this.geo);
    w.uid = uid;
    w.order = w.uid;
    w.level = Math.max(1, Math.min(SUB_MAX, Math.round(level) || 1));
    w.evolved = w.level === SUB_MAX;
    w.rebuild();
    this.weapons.push(w);
    return w;
  }

  /** 放进储备格；slot 省略时找第一个空格。满了返回 null。 */
  addReserve(id: WeaponId, level = 1, slot: number | undefined = RESERVE_SLOTS.find(s => !this.reserve.some(r => r.slot === s)), uid = this.nextUid++): ReserveItem | null {
    if (slot === undefined || !isReserve(slot) || this.reserve.some(r => r.slot === slot)) return null;
    const r = { uid, id, level: Math.max(1, Math.min(SUB_MAX, Math.round(level) || 1)), slot };
    this.reserve.push(r);
    return r;
  }

  private findSub(uid: number | undefined): Weapon | ReserveItem | undefined {
    return uid === undefined ? undefined : this.weapons.find(w => w.uid === uid) ?? this.reserve.find(r => r.uid === uid);
  }

  private dropSub(item: Weapon | ReserveItem): void {
    if (!('def' in item)) { this.reserve.splice(this.reserve.indexOf(item), 1); return; }
    item.dispose();
    this.weapons.splice(this.weapons.indexOf(item), 1);
  }

  /** 把一件挪到 slot：挂位之间照旧换锚点；跨进储备就拆下模型、解除联动，取出来时按原编号重新装上。 */
  private placeSub(item: Weapon | ReserveItem, slot: number): void {
    const toReserve = isReserve(slot);
    if (!('def' in item)) {
      if (toReserve) { item.slot = slot; return; }
      this.dropSub(item);
      this.spawnSub(item.id, item.level, slot, item.uid);
      return;
    }
    if (!toReserve) { item.moveTo(this.anchors[slot], slot); return; }
    if (item.link) this.removeLink(item.link);
    this.dropSub(item);
    this.reserve.push({ uid: item.uid, id: item.def.id, level: item.level, slot });
  }

  commitSub(plan: SubPlan): boolean {
    if (plan.signature !== subSignature(this.subItems())) return false;
    const source = this.findSub(plan.source);
    const target = this.findSub(plan.target);
    const locked = (x: Weapon | ReserveItem | undefined) => !!x && 'def' in x && !!x.ult;
    if (plan.kind === 'move' || plan.kind === 'swap') {
      if (!source) return false;
      const old = source.slot;
      // 先把要进储备的那件拆下，另一件再落到它空出来的挂位
      const pair: [Weapon | ReserveItem, number][] = [[source, plan.result.slot], ...(target ? [[target, old] as [Weapon | ReserveItem, number]] : [])];
      pair.sort((a, b) => Number(isReserve(b[1])) - Number(isReserve(a[1])));
      for (const [item, slot] of pair) this.placeSub(item, slot);
      return true;
    }
    if (locked(source) || locked(target)) return false;
    const keep = this.findSub(plan.result.uid || undefined);
    if (plan.kind === 'merge' && (!keep || locked(keep))) return false;
    for (const uid of plan.consumed) {
      const w = this.findSub(uid);
      if (!w || locked(w)) return false;
    }
    for (const uid of plan.consumed) {
      const w = this.findSub(uid)!;
      if ('def' in w) {
        if (keep && 'def' in keep) keep.absorbRuntime(w);
        if (w.link && w.link !== (keep && 'def' in keep ? keep.link : null)) this.removeLink(w.link);
      }
      this.dropSub(w);
    }
    if (keep) {
      keep.level = plan.result.level;
      if ('def' in keep) keep.evolved = keep.level === SUB_MAX;
      if (keep.slot !== plan.result.slot) this.placeSub(keep, plan.result.slot);
      else if ('def' in keep) keep.rebuild();
    } else if (isReserve(plan.result.slot)) {
      if (!this.addReserve(plan.result.id, plan.result.level, plan.result.slot)) return false;
    } else if (!this.addSub(plan.result.id, plan.result.level, plan.result.slot)) return false;
    return true;
  }

  private removeLink(id: LinkId): void {
    this.links.delete(id);
    for (const w of this.weapons) if (w.link === id) { w.link = null; w.rebuild(); }
  }

  /** 从存档的 summary() 恢复整套配置 */
  restore(summary: Record<string, number>): void {
    const coreKey = Object.keys(summary).find((k) => k.startsWith('core:')) ?? 'core:cannon';
    const tail = coreKey.slice(5);
    const branch = /[AB]$/.test(tail) ? (tail.slice(-1) as Branch) : undefined;
    const rawId = branch ? tail.slice(0, -1) : tail;
    const id = (rawId in CORES ? rawId : 'cannon') as CoreId;
    this.reset(id);
    this.grant('core', summary[coreKey], branch);
    for (const [k, v] of Object.entries(summary)) if (k in MODS) this.grant(k, v);
    if (summary['sub:v'] === 1) {
      for (const [k, v] of Object.entries(summary)) {
        const match = /^sub:(\d):([a-z]+)$/.exec(k);
        if (!match || !(match[2] in WEAPONS) || !Number.isFinite(v)) continue;
        const slot = Number(match[1]);
        if (isReserve(slot)) {
          const uid = summary[`sub:uid:${slot}`];
          const r = this.addReserve(match[2] as WeaponId, v, slot, 0);
          if (r) r.uid = Number.isSafeInteger(uid) && uid > 0 ? uid : 0;
          continue;
        }
        const w = this.addSub(match[2] as WeaponId, v, slot);
        if (!w) continue;
        const uid = summary[`sub:uid:${slot}`];
        if (Number.isSafeInteger(uid) && uid > 0 && !this.weapons.some(x => x !== w && x.uid === uid)) w.uid = uid;
        w.order = w.uid;
        this.nextUid = Math.max(this.nextUid, w.uid + 1);
        const state: Record<string, number> = {};
        for (const key of Object.keys(w.saveRuntime())) {
          const value = summary[`sub:time:${slot}:${key}`];
          if (Number.isFinite(value) && value >= 0) state[key] = value;
        }
        w.restoreRuntime(state);
      }
      for (const r of this.reserve) this.nextUid = Math.max(this.nextUid, r.uid + 1);
      for (const r of this.reserve) if (r.uid <= 0 || this.subItems().some(x => x.uid === r.uid && x.slot !== r.slot)) r.uid = this.nextUid++;
    } else {
      // 合并前的旧存档、旧调试配置按原形态迁入（6→4、5→3、3～4→2、1～2→1）。
      for (const wid of SUB_IDS) if (summary[wid] > 0) this.addSub(wid, summary[wid] > MAX_LEVEL ? 4 : summary[wid] >= 5 ? 3 : summary[wid] >= 3 ? 2 : 1);
    }
    for (const lid of Object.keys(LINKS) as LinkId[]) if (summary[`link:${lid}`]) {
      const members = LINKS[lid].parts.map((wid, i) => this.weapons.find(w => w.uid === summary[`sub:link:${lid}:${i}`] && w.def.id === wid) ?? this.bestWeapon(wid));
      if (members.every(w => w && !w.link)) {
        this.links.add(lid);
        for (const w of members) { w!.link = lid; w!.rebuild(); }
      }
    }
    for (const key of Object.keys(summary)) if (key.startsWith('fusion:')) this.grant(key, summary[key]);
    if (this.ult && summary['sub:v'] === 1) {
      for (const wid of this.ult.def.parts) {
        const selected = this.weapons.find(w => w.def.id === wid && w.evolved && summary[`sub:ult:${w.uid}`] === 1);
        if (!selected) continue;
        for (const w of this.weapons) if (w.def.id === wid) { w.ult = w === selected ? this.ult.def.id : null; w.rebuild(); }
      }
    }
    // 火神弹药池（T089）：读档按这一级的池子装满（存档里没有弹药字段，老存档的弹链也不用迁移）
    if (this.core instanceof VulcanCore) this.core.rounds = this.core.maxRounds;
    // 终极的剩余冷却（老存档没有这个键 = 直接待发）
    this.ult?.restore(summary['ult:cd'] ?? 0, summary['ult:cooldown']);
  }

  summary(): Record<string, number> {
    const c = this.core;
    const out: Record<string, number> = { [`core:${c.id}${c.branch ?? ''}`]: c.ultimate ? 7 : c.level };
    out['sub:v'] = 1;
    for (const w of this.weapons) {
      out[`sub:${w.slot}:${w.def.id}`] = w.level;
      out[`sub:uid:${w.slot}`] = w.uid;
      for (const [key, value] of Object.entries(w.saveRuntime())) out[`sub:time:${w.slot}:${key}`] = Math.max(0, value);
      if (w.link) out[`sub:link:${w.link}:${LINKS[w.link].parts.indexOf(w.def.id)}`] = w.uid;
      if (w.ult) out[`sub:ult:${w.uid}`] = 1;
    }
    for (const r of this.reserve) {
      out[`sub:${r.slot}:${r.id}`] = r.level;
      out[`sub:uid:${r.slot}`] = r.uid;
    }
    for (const [id, l] of this.mods) out[id] = l;
    for (const l of this.links) out[`link:${l}`] = 1;
    // 合成记成 fusion:<id> + 剩余冷却 ult:cd（保留一位小数）
    if (this.ult) {
      out[`fusion:${this.ult.def.id}`] = 1;
      out['ult:cd'] = Math.round(this.ult.cd * 10) / 10;
      out['ult:cooldown'] = this.ult.cooldown;
    }
    return out;
  }

  slots(): SlotView[] {
    const c = this.core;
    const out: SlotView[] = [{
      kind: 'core', id: c.id, icon: `core-${c.id}`, level: c.level, evolved: c.ultimate,
      ult: this.ult ? `ult-${this.ult.def.id}` : undefined, ready: this.fusionsReady().length > 0,
    }];
    // 超级改装在图鉴查；原改装行只放三个属性件，HUD 位置不变。
    for (const slot of SUB_SLOTS) {
      const w = this.weapons.find(x => x.slot === slot);
      out.push(w
        ? { kind: 'weapon', id: w.def.id, icon: w.def.id, level: w.level, evolved: w.evolved, link: w.link ? LINKS[w.link].name : undefined, slot, uid: w.uid, locked: !!w.ult }
        : { kind: 'empty-weapon', id: '', icon: '', level: 0, evolved: false, note: `${SUB_POSITION[slot]} · 暂停时装配`, slot });
    }
    const mods = [...this.mods.entries()].filter(([id]) => !isSuperMod(id));
    for (let i = 0; i < ATTR_MODS.length; i++) {
      const m = mods[i];
      out.push(m ? { kind: 'mod', id: m[0], icon: m[0], level: m[1], evolved: false } : { kind: 'empty-mod', id: '', icon: '', level: 0, evolved: false, note: this.slotNote('mod') });
    }
    return out;
  }

  /** 点空槽位的说明（T033）：这一局有几个槽、没满配时提一句去哪里加 */
  private slotNote(kind: 'weapon' | 'mod'): string {
    if (kind === 'mod') return '护盾、装甲、回收 · 各 5 级';
    return '六个挂位 · 同型同级可合成';
  }

  /** 槽位详情面板的文字（T049：标题 + 副标题 + 最多两三行，数值和规则在图鉴里） */
  describe(slot: SlotView): { title: string; sub: string; lines: string[] } | null {
    if (slot.kind === 'core') {
      const c = this.core;
      const def = c.def;
      const b = c.branch ? def.branches[c.branch] : null;
      const lines = [c.ultimate && b ? `${b.ultName}：${b.ultBlurb}` : b ? `${b.name}：${b.blurb}` : def.strong];
      if (!b && def.slot) return { title: `${def.turret}（${def.name}）`, sub: `等级 ${c.level}/${CORE_MAX}`, lines: def.slot };
      if (this.ult) lines.push(`究极「${this.ult.def.name}」：${this.ultHow}`);
      else if (this.fusionsReady().length) lines.push('可合成：升级时选合成卡');
      else if (c.ultimate) lines.push(this.recipes().length ? `究极：${this.recipes().map((f) => f.name).join(' / ')}` : '究极下一批开放');
      else if (b) lines.push(`满级 + ${MODS[def.evolveWith].name} → ${b.ultName}`);
      else lines.push(`${BRANCH_LEVEL} 级选分支`);
      return { title: `${def.turret}（${def.name}）`, sub: `等级 ${c.level}/${CORE_MAX}${c.ultimate ? ' · 终极' : ''}`, lines };
    }
    if (slot.kind === 'weapon') {
      const w = this.weapons.find((x) => x.uid === slot.uid);
      if (!w) return null;
      const def = w.def;
      const lines = [subDirection(def.id, w.slot), w.evolved ? '四级满级，重复件各自开火' : '同型号同级合成，不消耗选卡'];
      if (w.ult) lines.push('究极材料 · 可换位，不可替换');
      else if (w.link) lines.push(`联动：${LINKS[w.link].name}`);
      return { title: w.evolved ? def.evoName : def.name, sub: `${SUB_POSITION[w.slot]} · ${subLevelName(w.level)}`, lines };
    }
    if (slot.kind === 'mod') {
      const def = MODS[slot.id as ModId];
      const users = this.evolvesWhat(def.id);
      const lines = [def.line(slot.level)];
      if (users) lines.push(`相关武器：${users}`);
      return { title: def.name, sub: isSuperMod(def.id) ? '超级改装 · 本局生效' : `属性件 · 等级 ${slot.level}/${MAX_LEVEL}`, lines };
    }
    return null;
  }

  /** 终极行 / 终极键要显示的状态（每帧调用，复用同一个对象）；没合成返回 null */
  ultView(): UltView | null {
    const u = this.ult;
    if (!u) return null;
    const v = this.view;
    if (v.id !== u.def.id) {
      v.id = u.def.id;
      v.icon = `ult-${u.def.id}`;
      v.name = u.def.name;
    }
    v.state = u.state;
    v.progress = u.progress;
    v.label = u.label;
    return v;
  }

  /** 长按终极行 / 终极键的说明（T049：一句话 + 冷却；范围、伤害、配方在图鉴「究极」页） */
  describeUlt(): { title: string; sub: string; lines: string[] } | null {
    const u = this.ult;
    if (!u) return null;
    const f = u.def;
    return { title: `${f.name} · ${f.sub}`, sub: `究极武器 · ${f.role}`, lines: [f.blurb, `冷却 ${this.ultCooldown(f.id)} 秒 · 打首领全额`] };
  }

  /** 图鉴与长按显示本局下一次触发的冷却，避免显示浮点尾数。 */
  ultCooldown(id: FusionId): number {
    return Math.round(FUSIONS[id].cd * this.stats.cooldown * 10) / 10;
  }

  // ------------------------------------------------------------ 抽卡

  get superRemaining(): number {
    return SUPER_MODS.filter((id) => !this.mods.has(id)).length;
  }

  /** 无权重、无钥匙保底；不重复，也不进入普通升级的换卡池。 */
  drawSuper(): Card[] {
    const pool = SUPER_MODS.filter((id) => !this.mods.has(id));
    const out: Card[] = [];
    while (out.length < 3 && pool.length) out.push(this.superCard(pool.splice(Math.floor(rng.cards() * pool.length), 1)[0]));
    return out;
  }

  superCard(id: SuperModId): Card {
    const d = MODS[id];
    const users = this.core.def.evolveWith === id ? this.core.def.turret : '';
    return { key: `s:${id}`, kind: 'super', id, name: d.name, icon: id, tag: '超级改装', from: 0, to: 1, max: 0, rarity: 'super', lines: [d.blurb], hint: users ? `${users}的进化钥匙` : '本局一直生效', fixed: true };
  }

  /** 固定奖励优先，其余随机；保留一个无需腾格的选项。 */
  draw(n = 3, rare = false): Card[] {
    const c = this.core;
    this.offered.clear();
    this.rareOffer = rare;
    // 流派抉择：到 3 级必须先选分支
    if (c.level >= BRANCH_LEVEL && !c.branch) return (['A', 'B'] as Branch[]).map((b) => ({ ...this.branchCard(b), fixed: true }));
    const { forced, pool } = this.candidates();
    for (const f of forced) f.fixed = true;

    const picks: Card[] = forced.slice(0, n);
    if (picks.length < n && (rare || this.weapons.length === 0)) {
      const id = SUB_IDS[Math.floor(rng.cards() * SUB_IDS.length)];
      const i = pool.findIndex(p => p.card.kind === 'weapon' && p.card.id === id);
      if (i >= 0) {
        const card = rare ? this.weaponCard(id, rollSubLevel(this.playerLevel, true, rng.cards())) : pool[i].card;
        picks.push({ ...card, fixed: true, hint: rare ? '精英补件 · 可返回换选' : card.hint });
        pool.splice(i, 1);
      }
    }
    while (picks.length < n && pool.length) picks.push(pool.splice(this.weighted(pool), 1)[0].card);
    if (picks.length && picks.every(p => p.kind === 'weapon')) {
      const safe = pool.filter(p => p.card.kind !== 'weapon');
      let i = picks.length - 1;
      while (i >= 0 && picks[i].fixed) i--;
      if (i >= 0) picks[i] = safe.length ? safe[this.weighted(safe)].card : this.healCard();
    }
    if (picks.length === 0) picks.push({ ...this.healCard(), fixed: true });
    if (rare && !picks.some((p) => p.rarity === 'rare')) this.ensureRare(picks, pool, forced.length);
    for (const p of picks) this.offered.add(p.key);
    return picks;
  }

  /** 战备预置只在首次普通选卡给一张补件。 */
  presetCard(id: string): Card | null {
    if (!(id in WEAPONS)) return null;
    const card = this.weaponCard(id as WeaponId, rollSubLevel(this.playerLevel, false, rng.cards()));
    this.offered.add(card.key);
    return card;
  }

  /**
   * 单卡重抽（T017-6B，制作人「每个选项有一次重新肉鸽的机会」，策划 7.2 方案 A）：把第 i 张换成一张这次升级还没出现过的（按同样的权重随机），
   * 另外两张不动；强制卡、已经换过的那一格不能换。精英战利品里换掉的正好是唯一那张精良，换上来的也保底精良。没得换返回 null
   */
  reroll(cards: Card[], i: number): Card | null {
    const old = cards[i];
    if (!old || old.kind === 'super' || old.fixed || old.rerolled) return null;
    const needsSafe = old.kind !== 'weapon' && cards.every((c, j) => j === i || c.kind === 'weapon');
    const left = this.candidates().pool.filter((p) => !this.offered.has(p.card.key) && !cards.some((x) => x.key === p.card.key) && (!needsSafe || p.card.kind !== 'weapon'));
    if (!left.length && needsSafe && old.kind !== 'heal') return { ...this.healCard(), rerolled: true };
    if (!left.length) return null;
    const keepRare = this.rareOffer && old.rarity === 'rare' && !cards.some((x, j) => j !== i && x.rarity === 'rare');
    const eligible = keepRare ? left.filter((p) => this.canRare(p.card)) : left;
    const from = eligible.length ? eligible : left;
    let card = from[this.weighted(from)].card;
    if (keepRare && this.canRare(card)) card = this.remake(card, true) ?? card;
    this.offered.add(card.key);
    return { ...card, rerolled: true };
  }

  /** 这次升级出现过 / 被换掉的卡（单卡重抽不会换回来）；这次是不是精英战利品（换掉保底的那张时补一张精良） */
  private readonly offered = new Set<string>();
  private rareOffer = false;

  /** 按权重随机挑一个下标 */
  private weighted(pool: { card: Card; w: number }[]): number {
    const total = pool.reduce((s, p) => s + p.w, 0);
    let roll = rng.cards() * total;
    let idx = 0;
    for (; idx < pool.length - 1; idx++) {
      roll -= pool[idx].w;
      if (roll <= 0) break;
    }
    return idx;
  }

  /** 核心 / 属性件沿用精良加两级；副武器成品等级单独抽。 */
  private canRare(c: Card): boolean {
    if (c.kind !== 'core' && c.kind !== 'mod') return false;
    const max = c.kind === 'core' && !this.core.branch ? BRANCH_LEVEL : c.max;
    return c.from > 0 && c.from + 2 <= max;
  }

  /** 按同一件东西重新生成一张卡（rare = 强制精良 +2 级） */
  private remake(c: Card, rare: boolean): Card | null {
    if (c.kind === 'core') return { ...this.coreCard(rare), fixed: c.fixed };
    if (c.kind === 'mod') return { ...this.modCard(c.id as ModId, c.from, rare), fixed: c.fixed };
    return null;
  }

  /** 精英战利品的保底：先在已经抽出来的卡里找一张能 +2 的（优先随机卡）换成精良版，没有就从剩下的候选里拿一张换掉最后一张随机卡 */
  private ensureRare(picks: Card[], pool: { card: Card; w: number }[], forcedN: number): void {
    const order = [...picks.keys()].sort((a, b) => Number(a < forcedN) - Number(b < forcedN));
    for (const i of order) {
      if (!this.canRare(picks[i])) continue;
      picks[i] = this.remake(picks[i], true) ?? picks[i];
      return;
    }
    const spare = pool.filter((p) => this.canRare(p.card));
    const slot = picks.length - 1;
    if (!spare.length || slot < forcedN) return;
    picks[slot] = this.remake(spare[this.weighted(spare)].card, true) ?? picks[slot];
  }

  /** 这次能出的卡：forced = 必出（按顺序排在前面），pool = 其余按权重随机的候选 */
  private candidates(): { forced: Card[]; pool: { card: Card; w: number }[] } {
    const c = this.core;
    // 三合一合成：条件满足后合成卡固定排第一张（两条配方都满足就都出，选了一条另一条作废）
    const forced: Card[] = this.fusionsReady().map((f) => this.fusionCard(f.id));
    const pool: { card: Card; w: number }[] = [];
    if (c.maxed && c.branch && !c.ultimate && this.mods.has(c.def.evolveWith)) forced.push(this.coreEvoCard());
    // 分支前核心卡每次必出，尽快让玩家走到流派抉择；之后权重也偏高
    if (!c.maxed) {
      if (c.level < BRANCH_LEVEL) forced.push(this.coreCard());
      else pool.push({ card: this.coreCard(), w: 1.6 });
    }
    // 选完分支后，本核心配方里的副武器（新武器卡 / 升级卡）更容易出现：引导但不强制
    const recipe = c.branch && !this.ult ? new Set(this.recipes().flatMap((f) => f.parts)) : null;
    const wk = (id: WeaponId) => (recipe?.has(id) ? FUSION_WEIGHT : 1);
    for (const id of SUB_IDS) pool.push({ card: this.weaponCard(id, rollSubLevel(this.playerLevel, false, rng.cards())), w: 0.9 * wk(id) });
    // 联动仍由选卡获得，只绑定具体两件。
    for (const l of this.linkable()) pool.push({ card: this.linkCard(l), w: LINK_WEIGHT });
    for (const id of ATTR_MODS) {
      const l = this.mods.get(id) ?? 0;
      if (l < MAX_LEVEL) pool.push({ card: this.modCard(id, l), w: l ? 0.6 : 0.35 });
    }
    return { forced, pool };
  }

  apply(card: Card): void {
    switch (card.kind) {
      case 'core':
        this.core.level = card.to;
        this.onCore?.(this.core);
        break;
      case 'branch':
        this.core.branch = card.id as Branch;
        this.onCore?.(this.core);
        break;
      case 'coreEvo':
        this.core.ultimate = true;
        this.onCore?.(this.core);
        break;
      case 'weapon': {
        // 正常选卡由装配页决定落位；直接调用只找空格，不代替玩家合成。挂位满了先进储备。
        if (!this.addSub(card.id as WeaponId, card.to)) this.addReserve(card.id as WeaponId, card.to);
        break;
      }
      case 'evolve': {
        const w = this.weapons.find((x) => x.def.id === card.id);
        if (w) {
          w.level = SUB_MAX;
          w.evolved = true;
          w.rebuild();
        }
        break;
      }
      case 'mod':
        this.mods.set(card.id as ModId, card.to);
        break;
      case 'super':
        if (isSuperMod(card.id)) this.mods.set(card.id, 1);
        break;
      case 'fusion':
        this.fuse(card.id as FusionId, true);
        break;
      case 'link':
        this.bindLink(card.id as LinkId);
        break;
      case 'heal':
        break;
    }
    this.refresh();
  }

  /**
   * 调试 / 试玩：副武器给到一至四级，旧入口的五、六也按四级；重复装备用 addSub。
   * core 7 = 终极，branch 用 'A' / 'B'。
   */
  grant(id: string, level: number, branch?: Branch): boolean {
    if (id === 'core' || id === 'main') {
      this.core.level = Math.min(CORE_MAX, level);
      if (this.core.level >= BRANCH_LEVEL) this.core.branch = branch ?? this.core.branch ?? 'A';
      this.core.ultimate = level > CORE_MAX;
      this.onCore?.(this.core);
    } else if (id in WEAPONS) {
      const wid = id as WeaponId;
      let w = this.bestWeapon(wid);
      if (!w) {
        w = this.addSub(wid, level) ?? undefined;
        if (!w) return false;
      }
      w.level = Math.max(1, Math.min(SUB_MAX, Math.round(level)));
      w.evolved = w.level === SUB_MAX;
      w.rebuild();
    } else if (id in MODS) {
      this.mods.set(id as ModId, isSuperMod(id) ? 1 : Math.min(MAX_LEVEL, level));
    } else if (id.startsWith('link:')) {
      // 读档 / 调试：link:<id>（不检查等级）
      const lid = id.slice(5) as LinkId;
      if (!LINKS[lid]) return false;
      if (!this.bindLink(lid)) return false;
    } else if (id.startsWith('fusion:')) {
      // 读档：fusion:<id>（不检查前提）；老存档的 fusion:tieli 读成核弹，并补回当时被吸收、没写进存档的两件副武器（进化）
      const raw = id.slice(7);
      const fid = (FUSION_ALIAS[raw] ?? raw) as FusionId;
      if (raw in FUSION_ALIAS && FUSIONS[fid]) for (const p of FUSIONS[fid].parts) if (!this.weapons.some((w) => w.def.id === p)) this.grant(p, MAX_LEVEL + 1);
      if (!this.fuse(fid, false)) return false;
    } else {
      return false;
    }
    this.refresh();
    return true;
  }

  private refresh(): void {
    this.stats = computeModStats(this.mods);
    this.onStats?.(this.stats);
  }

  private bindLink(id: LinkId): boolean {
    if (this.links.has(id)) return true;
    if (LINKS[id].parts.some(p => this.linkOf(p))) return false;
    const members = LINKS[id].parts.map(p => this.bestWeapon(p));
    if (members.some(w => !w || w.link)) return false;
    this.links.add(id);
    for (const w of members) { w!.link = id; w!.rebuild(); }
    return true;
  }

  // ------------------------------------------------------------ 联动改装（T018-link）

  /** 这件副武器参与的联动（没有为 null） */
  linkOf(id: WeaponId): (typeof LINKS)[LinkId] | null {
    for (const l of this.links) if (LINKS[l].parts.includes(id)) return LINKS[l];
    return null;
  }

  /** 同型号最多一件参与联动，其他副本继续各自开火。 */
  linkable(): LinkId[] {
    return (Object.keys(LINKS) as LinkId[]).filter((l) => !this.links.has(l) && LINKS[l].parts.every((p) => (this.bestWeapon(p)?.level ?? 0) >= SUB_LINK_LEVEL && !this.linkOf(p)));
  }

  linkCard(id: LinkId): Card {
    const d = LINKS[id];
    return {
      key: `link:${id}`, kind: 'link', id, name: d.name, icon: d.icon, tag: '联动改装',
      from: 0, to: 0, max: 0, rarity: 'common', lines: [d.blurb],
      formula: [d.parts[0], d.parts[1], d.icon],
      hint: `${WEAPONS[d.parts[0]].short} × ${WEAPONS[d.parts[1]].short} · 不用多占副武器槽`,
    };
  }

  // ------------------------------------------------------------ 合成

  /** 本核心的合成配方（只列 FUSIONS 里已开放的） */
  recipes(): FusionDef[] {
    return Object.values(FUSIONS).filter((f) => f.core === this.core.id);
  }

  /** 条件已满足的合成：核心终极（A / B 都行）、配方里两件副武器都已进化、本局还没合成过 */
  fusionsReady(): FusionDef[] {
    const c = this.core;
    if (this.ult || !c.ultimate) return [];
    return this.recipes().filter((f) => f.parts.every((p) => this.mods.has(WEAPONS[p].evolveWith) && this.weapons.some((w) => w.def.id === p && w.evolved)));
  }

  /**
   * 调试 / 试玩：把合成的前提凑齐（换到对应流派、核心终极、两件材料进化、缺的进化钥匙补到 keyLevel 级），
   * 之后下一次抽卡第一张就是合成卡；返回条件是否满足
   */
  prepareFusion(id: FusionId, branch: Branch = 'A', keyLevel = 3): boolean {
    const def = FUSIONS[id] as FusionDef | undefined;
    if (!def) return false;
    if (this.core.id !== def.core || this.ult) this.reset(def.core);
    this.grant('core', CORE_MAX + 1, branch);
    for (const p of def.parts) this.grant(p, MAX_LEVEL + 1);
    for (const m of new Set([this.core.def.evolveWith, ...def.parts.map((p) => WEAPONS[p].evolveWith)])) if (!this.mods.has(m)) this.grant(m, keyLevel);
    return this.fusionsReady().some((f) => f.id === id);
  }

  /**
   * 合成：什么都不拆，车上多一件独立的终极武器（合成完直接待发）；每局一次。
   * show = 选卡（交给游戏层演出）；否则直接换炮塔套件（读档 / 调试）
   */
  private fuse(id: FusionId, show: boolean): boolean {
    const def = FUSIONS[id] as FusionDef | undefined;
    const c = this.core;
    if (!def || c.id !== def.core || this.ult) return false;
    this.ult = createUlt(id);
    for (const p of def.parts) {
      const w = this.bestWeapon(p);
      if (w) { w.ult = id; w.rebuild(); }
    }
    if (show && this.onFuse) this.onFuse(def);
    else this.onCore?.(c);
    return true;
  }

  private evolvesWhat(mod: ModId): string {
    const names: string[] = [];
    if (this.core.def.evolveWith === mod) names.push(this.core.def.turret);
    for (const w of Object.values(WEAPONS)) if (w.evolveWith === mod) names.push(w.name);
    return names.join(' / ');
  }

  // ------------------------------------------------------------ 卡片文案

  /** force = 精英战利品的保底：能 +2 就一定是精良 */
  private rarityStep(from: number, max: number, force = false): { to: number; rarity: Rarity } {
    const rare = (force || rng.cards() < 0.22) && from + 2 <= max && from > 0;
    return { to: from + (rare ? 2 : 1), rarity: rare ? 'rare' : 'common' };
  }

  private coreCard(rare = false): Card {
    const c = this.core;
    const from = c.level;
    const { to, rarity } = this.rarityStep(from, c.branch ? CORE_MAX : BRANCH_LEVEL, rare);
    const lines: string[] = [];
    for (let l = from + 1; l <= to; l++) if (c.def.notes[l]) lines.push(c.def.notes[l]);
    const b = c.branch ? c.def.branches[c.branch] : null;
    return {
      key: 'core', kind: 'core', id: c.id, name: c.def.turret, icon: `core-${c.id}`, tag: '核心强化',
      from, to, max: CORE_MAX, rarity, lines,
      hint: b ? `钥匙：${MODS[c.def.evolveWith].name}` : `${BRANCH_LEVEL} 级选分支`,
    };
  }

  private branchCard(b: Branch): Card {
    const def = this.core.def;
    const br = def.branches[b];
    return {
      key: `b:${b}`, kind: 'branch', id: b, name: br.name, icon: `core-${def.id}`, tag: '流派分支',
      from: 0, to: 0, max: 0, rarity: 'legend', lines: [br.blurb],
      hint: `终极：${br.ultName}`,
    };
  }

  private coreEvoCard(): Card {
    const c = this.core;
    const br = c.def.branches[c.branch ?? 'A'];
    return {
      key: 'core-evo', kind: 'coreEvo', id: c.id, name: br.ultName, icon: `core-${c.id}`, tag: '终极进化',
      from: CORE_MAX, to: CORE_MAX, max: CORE_MAX, rarity: 'legend', lines: [br.ultBlurb],
      hint: `${c.def.turret} + ${MODS[c.def.evolveWith].name}`,
    };
  }

  weaponCard(id: WeaponId, level = 1): Card {
    const def = WEAPONS[id];
    const to = Math.max(1, Math.min(3, Math.round(level)));
    const match = this.subItems().find(w => w.id === id && w.level === to && !w.locked);
    const plan = match ? this.planSub(match.slot, { id, level: to }) : null;
    return {
      key: `w:${id}`, kind: 'weapon', id, name: `${def.short} · ${subLevelName(to)}`, icon: id, tag: '副武器补件',
      from: 0, to, max: SUB_MAX, rarity: to >= 2 ? 'rare' : 'common', rareLabel: `${subLevelName(to)}成品`,
      lines: [SUB_FORMS[id][to - 1], plan?.kind === 'merge' ? `可合成${subLevelName(plan.result.level)}` : '装上就会自动攻击'],
      hint: '拖动装配 · 每次只合一级',
    };
  }

  /** 合成卡：公式条〔核心〕+〔A〕+〔B〕→〔终极〕+ 红字（每局一次、不可撤销），什么都不拆；提示行后半句按设置写（T055） */
  fusionCard(id: FusionId): Card {
    const def = FUSIONS[id];
    const [a, b] = def.parts.map((p) => WEAPONS[p]);
    return {
      key: `f:${id}`, kind: 'fusion', id, name: `${def.name} · ${def.sub}`, icon: `ult-${id}`, tag: '三合一',
      from: 0, to: 0, max: 0, rarity: 'legend', lines: [def.blurb],
      hint: `什么都不拆 · ${this.ultHow}`,
      formula: [`core-${def.core}`, a.id, b.id, `ult-${id}`],
      warn: `锁定${def.parts.map(p => SUB_POSITION[this.bestWeapon(p)?.slot ?? 0]).join('、')}材料`,
    };
  }

  private modCard(id: ModId, from: number, rare = false): Card {
    const def = MODS[id];
    const { to, rarity } = this.rarityStep(from, MAX_LEVEL, rare);
    const lines = from === 0 ? [def.blurb, def.line(to)] : [def.line(to)];
    const users = this.evolvesWhat(id);
    return {
      key: `m:${id}`, kind: 'mod', id, name: def.name, icon: id, tag: from === 0 ? '新属性件' : '属性升级',
      from, to, max: MAX_LEVEL, rarity, lines,
      hint: users ? `${users}的进化钥匙` : undefined,
    };
  }

  private healCard(): Card {
    return {
      key: 'heal', kind: 'heal', id: 'heal', name: '战地维修', icon: 'heal', tag: '补给',
      from: 0, to: 0, max: 0, rarity: 'common', lines: ['回复 60 耐久'],
    };
  }
}
