import * as THREE from 'three';
import { dmgSrc, withPlayer } from './DamageLog';
import type { Fx } from '../render/Fx';
import { DRAPE_VERT, WATER_GLSL } from '../world/Craters';
import { MARK_GAP, MARK_SELF, WARN_ENEMY } from '../render/markColors';

// 落点预警：外圈（加粗）+ 中心十字 + 由内向外填充的进度，快落地时闪烁；uPreview > 0 = 终极落点预览（淡、不闪、不填充进度）
// （顶点着色器 DRAPE_VERT：圈贴着实体弹坑的地面，vP = 单位圆盘上的本地坐标）
const RING_FRAG = /* glsl */ `
uniform vec3 uColor;
uniform float uProgress;
uniform float uTime;
uniform float uPreview;
uniform float uStrong;
uniform float uShadow;
uniform float uOutline;
varying vec2 vP;
void main() {
  float r = length(vP);
  float rim = smoothstep(0.86, 0.92, r) * (1.0 - smoothstep(0.97, 1.0, r));
  // 敌方攻击的预警圈（T017-1B，uStrong = 1）：外圈加粗 + 中心十字（圈画的就是真实伤害范围）；我方落点照旧细圈
  float rim2 = mix(rim, smoothstep(0.8, 0.86, r) * (1.0 - smoothstep(0.97, 1.0, r)), uStrong);
  float cross = (1.0 - smoothstep(0.022, 0.04, min(abs(vP.x), abs(vP.y)))) * (1.0 - smoothstep(0.13, 0.17, r)) * uStrong;
  float fill = (1.0 - smoothstep(uProgress - 0.04, uProgress, r)) * 0.28;
  float blink = uProgress > 0.75 ? 0.6 + 0.4 * sin(uTime * 40.0) : 1.0;
  float a = uPreview > 0.0 ? (rim * 1.6 + 0.3) * uPreview : (rim2 * 0.95 + fill + cross * 0.85) * blink;
  // 巨炮巨弹（D5 C7，uShadow = 1）：圈中心一团影子，从 0 涨到 0.3 倍半径、越来越黑——炮弹越近影子越大（不闪）
  float shR = 0.3 * uProgress;
  float sh = uShadow * (1.0 - smoothstep(shR * 0.7, shR + 0.001, r)) * (0.3 + 0.55 * uProgress);
  vec3 col = mix(uColor, vec3(0.06, 0.03, 0.02), clamp(sh * 1.6, 0.0, 1.0));
  a = max(a, sh);
  // 圈里侧一道深色描边（uOutline = 1）：沙漠油井的敌方红圈（T122）、我方浅黄圈一直带（T130），浅色地面上也看得清；细圈的描边贴着细圈往外挪
  float o0 = mix(0.79, 0.72, uStrong);
  float ol = uOutline * smoothstep(o0, o0 + 0.04, r) * (1.0 - smoothstep(o0 + 0.07, o0 + 0.09, r));
  col = mix(col, vec3(0.08, 0.04, 0.02), ol);
  a = max(a, ol * 0.75 * (uPreview > 0.0 ? min(1.0, uPreview * 2.0) : blink));
  if (a < 0.01) discard;
  gl_FragColor = vec4(col, a);
  #include <colorspace_fragment>
}`;

// 炼狱火场的地面辉光（燃烧模式）：顺着道路的椭圆（网格按左右 / 前后半轴缩放），火线从中心烧开（uK = 已烧到的比例），
// 边缘参差、亮度随时间慢慢起伏（不闪），中心白热、边缘暗红；收尾时 uFade 降下去，只剩暗红余烬
const FIELD_FRAG = /* glsl */ `
${WATER_GLSL}
uniform float uK;
uniform float uFade;
uniform float uTime;
uniform float uSeed;
varying vec2 vP;
varying vec2 vWorldXZ;
float h(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7)) + uSeed) * 43758.5453); }
float n2(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(h(i), h(i + vec2(1.0, 0.0)), f.x), mix(h(i + vec2(0.0, 1.0)), h(i + vec2(1.0, 1.0)), f.x), f.y);
}
void main() {
  if (waterH(vWorldXZ) > -999.0) discard;
  vec2 vPos = vP;
  float r = length(vPos);
  float a = atan(vPos.y, vPos.x);
  // 参差的火线：按角度的低频大起伏 + 高频毛边（角度用 cos / sin 取样，接缝处连续）
  vec2 d = vec2(cos(a), sin(a));
  float edge = uK * (0.84 + 0.12 * n2(d * 2.2 + 7.0) + 0.05 * n2(d * 8.0 + 3.0));
  if (r > edge) discard;
  float inner = r / max(edge, 0.001);
  // 亮度起伏：两层慢慢漂移的噪声（不闪）+ 一块块明暗不均的余烬
  float flick = 0.7 + 0.3 * n2(vPos * 5.0 + vec2(uTime * 0.6, -uTime * 0.45));
  float blot = 0.6 + 0.4 * n2(vPos * 11.0 - vec2(uTime * 0.2, 0.0));
  vec3 col = mix(vec3(1.0, 0.85, 0.5), vec3(1.0, 0.42, 0.1), smoothstep(0.0, 0.5, inner));
  col = mix(col, vec3(0.55, 0.09, 0.02), smoothstep(0.55, 1.0, inner));
  // 收尾：整片退成暗红余烬
  col = mix(vec3(0.45, 0.07, 0.02), col, uFade);
  // 火线前沿更亮，最外一圈淡出
  float front = smoothstep(0.82, 0.96, inner) * (1.0 - smoothstep(0.96, 1.0, inner)) * 0.5 * uFade;
  float a0 = (0.5 * flick * blot + front) * (1.0 - smoothstep(0.9, 1.0, inner)) * (0.35 + 0.65 * uFade);
  if (a0 < 0.01) discard;
  gl_FragColor = vec4(col, a0);
  #include <colorspace_fragment>
}`;

interface Marker {
  mesh: THREE.Mesh<THREE.RingGeometry, THREE.ShaderMaterial>;
  t: number;
  dur: number;
  alive: boolean;
}

/** player 只烧敌人；enemy 只烧玩家；neutral（油桶）谁都烧 */
export type HazardOwner = 'player' | 'enemy' | 'neutral';

/**
 * 圈归谁（T130，颜色见 render/markColors）：enemy = 敌方攻击（红，外圈加粗 + 中心十字，圈 = 真实伤害范围）；
 * hint = 敌方提示（红细圈，不是伤害范围：沙下伏兵）；self = 我方落点 / 范围（浅黄细圈 + 里侧深色描边）；gap = 弹幕缺口（冷白）
 */
export type MarkSide = 'enemy' | 'hint' | 'self' | 'gap';
const MARK_COLOR: Record<MarkSide, number> = { enemy: WARN_ENEMY, hint: WARN_ENEMY, self: MARK_SELF, gap: MARK_GAP };

interface FirePatch {
  player?: number;
  x: number;
  z: number;
  r: number;
  life: number;
  dps: number;
  owner: HazardOwner;
  tick: number;
  emit: number;
  /** 伤害来源（战报） */
  src: string;
  /** 终极留下的火（按 fire 结算、不暴击，计入 dmgUlt） */
  ult: boolean;
  summon: boolean;
  /** 点燃路边景物的计时（每 0.5 秒一次） */
  scn: number;
}

/** 终极火场（炼狱）的画面：只管地面辉光、火苗和收尾的烟，伤害由终极模块结算 */
interface Field {
  x: number;
  z: number;
  rx: number;
  rz: number;
  t: number;
  dur: number;
  spread: number;
  fade: number;
  fps: number;
  acc: number;
}

export interface HazardContext {
  /** 遍历敌人：回调返回敌人位置与半径，hit 时调用 damage（ult = 终极留下的火） */
  forEachEnemy(fn: (x: number, z: number, radius: number, hit: (amount: number, ult: boolean, summon?: boolean) => void) => void): void;
  /** 主玩家位置：甩到身后多远收掉火场按它 */
  playerX: number;
  playerZ: number;
  /** 每辆玩家车的位置（T117，实时引用）：地面火烫谁按它；damagePlayer 的 i = 第几辆（不给 = 主玩家） */
  players: readonly { readonly x: number; readonly z: number }[];
  damagePlayer(amount: number, i?: number): void;
  /** 地面火烤路边景物（每 0.5 秒一次，dt = 0.5）：植被立刻着、木头烤 1 秒才着 */
  ignite?(x: number, z: number, r: number, dt: number): void;
}

/** 地面危险区：落点预警圈、火焰区 */
export class Hazards {
  networkMarkers() { return this.markers.filter(p => p.alive); }
  networkRing(): THREE.Mesh<THREE.RingGeometry, THREE.ShaderMaterial> { return this.ringMesh(0); }
  private readonly markers: Marker[] = [];
  private readonly fires: FirePatch[] = [];
  /** 圈 / 火场辉光共用的圆盘：径向细分 12 圈（贴着弹坑往下凹） */
  private readonly geo = new THREE.RingGeometry(0.001, 1, 40, 12);
  private time = 0;
  /** 待发预览亮一下的剩余秒数（T017-13b） */
  private flashT = 0;
  /** 终极落点预览圈（一个常驻网格，+1 次绘制，不用时隐藏） */
  private previewMesh: THREE.Mesh<THREE.RingGeometry, THREE.ShaderMaterial> | null = null;
  /** 终极火场（同一时间最多一片，不占 40 片地面火的名额）和它的地面辉光（一个常驻网格，+1 次绘制） */
  private field: Field | null = null;
  private fieldMesh: THREE.Mesh<THREE.RingGeometry, THREE.ShaderMaterial> | null = null;

  /** 所有圈都加深色描边（T122 沙漠油井那一区开，Game 进区时设；我方的圈平时就带） */
  outline = false;

  constructor(
    private readonly scene: THREE.Scene,
    private readonly fx: Fx,
  ) {
    this.geo.rotateX(-Math.PI / 2);
  }

  private ringMesh(preview: number): THREE.Mesh<THREE.RingGeometry, THREE.ShaderMaterial> {
    const mesh = new THREE.Mesh(
      this.geo,
      new THREE.ShaderMaterial({
        vertexShader: DRAPE_VERT,
        fragmentShader: RING_FRAG,
        uniforms: { uColor: { value: new THREE.Color() }, uProgress: { value: 0 }, uTime: { value: 0 }, uPreview: { value: preview }, uStrong: { value: 0 }, uShadow: { value: 0 }, uOutline: { value: 0 }, uDrape: { value: 1 }, ...this.fx.craterU },
        transparent: true,
        depthWrite: false,
      }),
    );
    mesh.renderOrder = 2;
    mesh.frustumCulled = false;
    this.scene.add(mesh);
    return mesh;
  }

  /** 终极待发时的地面落点预览：淡淡的圈 / 顺着道路的椭圆（rz = 前后半轴），约 20% 不透明度，不闪；null = 隐藏。六件究极一个颜色（我方浅黄，T130） */
  preview(p: { x: number; z: number; r: number; rz?: number } | null): void {
    if (!p) {
      if (this.previewMesh) this.previewMesh.visible = false;
      return;
    }
    const m = (this.previewMesh ??= this.ringMesh(0.2));
    m.visible = true;
    m.position.set(p.x, 0.08, p.z);
    m.scale.set(p.r, 1, p.rz ?? p.r);
    m.material.uniforms.uColor.value.setHex(MARK_SELF);
    m.material.uniforms.uOutline.value = 1;
    // 锁到新的一坨时亮一下（T017-13b）：20% → 60% 再 0.45 秒退回
    m.material.uniforms.uPreview.value = 0.2 + 0.4 * Math.max(0, this.flashT / 0.45);
  }

  /** 终极待发预览亮一下（锁定的那一坨换了，T017-13b） */
  previewFlash(): void {
    this.flashT = 0.45;
  }

  /**
   * 终极火场（炼狱）的画面：以 (x, z) 为中心、左右半轴 rx / 前后半轴 rz 的椭圆，spread 秒内火线从中心烧开，dur 秒结束，
   * 最后 fade 秒退成余烬和黑烟；地面辉光 +1 次绘制，按面积每秒发 fps 团火舌（中心白热、边缘橙红）。只管画面，伤害由终极模块结算
   */
  burnField(x: number, z: number, rx: number, rz: number, dur: number, spread: number, fade: number, fps: number): void {
    this.field = { x, z, rx, rz, t: 0, dur, spread, fade, fps, acc: 0 };
    const m = (this.fieldMesh ??= this.makeFieldMesh());
    m.visible = true;
    m.position.set(x, 0.1, z);
    m.scale.set(rx, 1, rz);
    m.material.uniforms.uSeed.value = Math.random() * 100;
    m.material.uniforms.uK.value = 0;
    m.material.uniforms.uFade.value = 1;
  }

  private makeFieldMesh(): THREE.Mesh<THREE.RingGeometry, THREE.ShaderMaterial> {
    const mesh = new THREE.Mesh(
      this.geo,
      new THREE.ShaderMaterial({
        vertexShader: DRAPE_VERT,
        fragmentShader: FIELD_FRAG,
        uniforms: { uK: { value: 0 }, uFade: { value: 1 }, uTime: { value: 0 }, uSeed: { value: 0 }, uDrape: { value: 1 }, ...this.fx.craterU },
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
      }),
    );
    mesh.renderOrder = 1;
    mesh.frustumCulled = false;
    this.scene.add(mesh);
    return mesh;
  }

  /** 火场画面每帧：火线烧开、火舌、收尾的余烬和黑烟 */
  private stepField(delta: number, playerZ: number): void {
    const f = this.field;
    const m = this.fieldMesh;
    if (!f || !m) return;
    f.t += delta;
    // 结束后余烬再暗 0.4 秒；甩到身后就收掉
    if (f.t >= f.dur + 0.4 || f.z - Math.max(f.rx, f.rz) > playerZ + 40) {
      this.field = null;
      m.visible = false;
      return;
    }
    const k = Math.min(1, f.t / f.spread);
    const live = THREE.MathUtils.clamp((f.dur - f.t) / f.fade, 0, 1);
    const u = m.material.uniforms;
    u.uK.value = k;
    u.uFade.value = f.t <= f.dur ? live : 0;
    u.uTime.value = this.time;
    if (f.t > f.dur) return;
    f.acc += delta * f.fps * (0.25 + 0.75 * live);
    while (f.acc >= 1) {
      f.acc -= 1;
      const a = Math.random() * Math.PI * 2;
      const rr = Math.sqrt(Math.random());
      const x = f.x + Math.cos(a) * f.rx * k * rr;
      const z = f.z + Math.sin(a) * f.rz * k * rr;
      if (this.fx.waterAt(x, z) !== -Infinity) continue;
      this.fx.blaze(x, z, 1.9 + Math.random() * 1.5, 1 - rr, live);
      // 收尾：火舌少了，黑烟多了
      if (Math.random() < 0.12 + (1 - live) * 0.5) this.fx.smoke(x, this.fx.groundAt(x, z) + 1.4, z, 1.6, 3.4, 0x221d1a, 0.55);
    }
  }

  /** 落点预警圈（纯视觉），dur 秒后消失；rz / rot：画成椭圆（一排落点合用一个圈，省绘制次数） */
  /** side = 归谁（颜色和样式跟着走，见 MarkSide）；shadow = 巨炮巨弹（中心影子越来越大，D5） */
  marker(x: number, z: number, r: number, dur: number, side: MarkSide, rz = r, rot = 0, shadow = false): void {
    let m = this.markers.find((item) => !item.alive);
    if (!m) {
      const mesh = this.ringMesh(0);
      m = { mesh, t: 0, dur: 1, alive: false };
      this.markers.push(m);
    }
    m.alive = true;
    m.t = 0;
    m.dur = dur;
    m.mesh.visible = true;
    m.mesh.position.set(x, 0.09, z);
    m.mesh.scale.set(r, 1, rz);
    m.mesh.rotation.y = rot;
    // 外观方案（?skin=）也不换色：红只给敌方（T130）
    m.mesh.material.uniforms.uColor.value.setHex(MARK_COLOR[side]);
    m.mesh.material.uniforms.uStrong.value = side === 'enemy' ? 1 : 0;
    m.mesh.material.uniforms.uOutline.value = side === 'self' || this.outline ? 1 : 0;
    m.mesh.material.uniforms.uShadow.value = shadow ? 1 : 0;
  }

  /** 一片燃烧区：对所属阵营的敌对方持续造成伤害；dps = 0 只有火苗、不伤人（核弹爆心那圈火，伤害起爆时已经结算完） */
  fire(x: number, z: number, r: number, life: number, dps: number, owner: HazardOwner, ult = false, summon = false): void {
    if (!this.fx.hasLand(x, z, r)) return;
    if (this.fires.length > 40) this.fires.shift();
    this.fires.push({ x, z, r, life, dps, owner, tick: 0, emit: 0, src: owner === 'neutral' ? 'barrel' : dmgSrc.cur, player: dmgSrc.player, ult, summon, scn: 0.5 });
    this.fx.decals.add(0, x, z, r * 2.4, r * 2.4, Math.random() * 6.28, 0.7, 20);
  }

  update(delta: number, ctx: HazardContext): void {
    this.time += delta;
    this.flashT = Math.max(0, this.flashT - delta);
    this.stepField(delta, ctx.playerZ);
    for (const m of this.markers) {
      if (!m.alive) continue;
      m.t += delta;
      if (m.t >= m.dur) {
        m.alive = false;
        m.mesh.visible = false;
        continue;
      }
      m.mesh.material.uniforms.uProgress.value = m.t / m.dur;
      m.mesh.material.uniforms.uTime.value = this.time;
    }

    // 我方的火同时烧着超过 10 摊（满级空袭一趟地毯 30 摊燃烧弹）就按比例少冒烟（T143 满级同屏不糊；火苗、伤害照旧）
    let mine = 0;
    for (const f of this.fires) if (f.owner !== 'neutral') mine++;
    const mineSmoke = Math.min(1, 10 / Math.max(1, mine));
    for (let i = this.fires.length - 1; i >= 0; i--) {
      const f = this.fires[i];
      f.life -= delta;
      if (f.life <= 0 || f.z > ctx.playerZ + 50) {
        this.fires.splice(i, 1);
        continue;
      }
      f.emit -= delta;
      if (f.emit <= 0) {
        f.emit = 0.09;
        const a = Math.random() * Math.PI * 2;
        const rr = Math.sqrt(Math.random()) * f.r;
        const x = f.x + Math.cos(a) * rr, z = f.z + Math.sin(a) * rr;
        const fg = this.fx.groundAt(x, z);
        const dry = this.fx.waterAt(x, z) === -Infinity;
        if (dry) this.fx.fire(x, fg + 0.4, z, 1.1 + Math.random() * 0.6);
        // 油桶火：更大的火舌和一根黑烟柱
        if (f.owner === 'neutral' && this.fx.waterAt(f.x + Math.cos(a) * rr * 0.5, f.z + Math.sin(a) * rr * 0.5) === -Infinity) this.fx.fire(f.x + Math.cos(a) * rr * 0.5, fg + 1.0, f.z + Math.sin(a) * rr * 0.5, 2.0);
        if (Math.random() < (f.owner === 'neutral' ? 0.6 : 0.25 * mineSmoke) && dry) this.fx.smoke(x, fg + 1.2, z, f.owner === 'neutral' ? 1.3 : 0.8, f.owner === 'neutral' ? 3.2 : 1.6, 0x24201e, 0.5);
      }
      f.scn -= delta;
      if (f.scn <= 0) {
        f.scn = 0.5;
        ctx.ignite?.(f.x, f.z, f.r, 0.5);
      }
      f.tick -= delta;
      if (f.tick > 0) continue;
      f.tick = 0.25;
      const amount = f.dps * 0.25;
      if (f.owner !== 'enemy' && f.dps > 0) {
        dmgSrc.cur = f.src;
        withPlayer(f.player ?? 0, () => ctx.forEachEnemy((x, z, radius, hit) => {
          if (Math.hypot(x - f.x, z - f.z) < f.r + radius && this.fx.waterAt(x, z) === -Infinity) hit(amount, f.ult, f.summon);
        }));
        dmgSrc.cur = 'other';
      }
      if (f.owner === 'player') continue;
      for (let i = 0; i < ctx.players.length; i++) {
        const p = ctx.players[i];
        if (Math.hypot(p.x - f.x, p.z - f.z) < f.r + 2.4 && this.fx.waterAt(p.x, p.z) === -Infinity) ctx.damagePlayer(amount * (f.owner === 'neutral' ? 0.4 : 1), i);
      }
    }
  }

  clear(): void {
    for (const m of this.markers) {
      m.alive = false;
      m.mesh.visible = false;
    }
    this.fires.length = 0;
    this.preview(null);
    this.field = null;
    if (this.fieldMesh) this.fieldMesh.visible = false;
  }
}
