import type { UiSkin } from './types';
import { line, random, rivet } from './drawing';

export const scheme4: UiSkin = {
  id: 4, name: '夜战电台', shape: 'round', radius: 4, ticks: 20,
  colors: {
    back: '#090f0d', backHi: '#1c2c24', high: '#273c31', low: '#0f1b16', line: '#536c58',
    ink: '#e4edda', soft: '#c2d3bc', dim: '#9eaf9c', accent: '#a5cc83', cool: '#a2cbb1',
    mainHi: '#314636', mainLow: '#17291e', mainInk: '#e3efc9', shadow: '#030a06',
  },
  texture(c) {
    const rnd = random(447);
    for (let i = 0; i < 8; i++) {
      const x = rnd() * 256, y = rnd() * 256, r = rnd() * 45 + 30;
      c.fillStyle = i % 2 ? 'rgba(61,75,44,.17)' : 'rgba(1,8,5,.2)';
      c.beginPath();
      for (let j = 0; j < 10; j++) {
        const a = j * Math.PI / 5, s = r * (0.6 + rnd() * 0.4);
        const px = x + Math.cos(a) * s, py = y + Math.sin(a) * s;
        if (j === 0) c.moveTo(px, py); else c.lineTo(px, py);
      }
      c.closePath(); c.fill();
    }
    for (let y = 0; y < 256; y += 3) line(c, 0, y, 256, y, 'rgba(0,5,2,.12)', 0.5);
    for (let i = 0; i < 900; i++) {
      c.fillStyle = i % 2 ? 'rgba(198,218,162,.04)' : 'rgba(0,4,0,.18)';
      c.fillRect(rnd() * 256, rnd() * 256, 0.7, 0.7);
    }
  },
  detail(c, w, h, role) {
    if (h < 27) return;
    line(c, 4, 4, w - 4, 4, '#71816350');
    if (w > 68 && h > 36) {
      line(c, 8, 7, 20, 7, '#93a37b');
      line(c, 8, 7, 8, 16, '#93a37b');
      line(c, w - 20, h - 7, w - 8, h - 7, '#657858');
      line(c, w - 8, h - 16, w - 8, h - 7, '#657858');
    }
    if (role === 'primary') {
      for (const x of [14, w - 14]) {
        c.fillStyle = '#080e08'; c.beginPath(); c.arc(x, h / 2, 4, 0, Math.PI * 2); c.fill();
        c.fillStyle = '#a5cc83'; c.beginPath(); c.arc(x, h / 2, 2, 0, Math.PI * 2); c.fill();
      }
    }
    if (role === 'card') {
      line(c, 4, 18, 4, h - 18, '#9fc37d', 2);
      for (let x = 14; x < 44; x += 5) line(c, x, h - 9, x, h - 5, '#67835e');
    }
  },
  scene(c, w, h) {
    const l = Math.max(9, (w - 530) / 2), r = w - l;
    for (const x of [l, r]) {
      line(c, x, 20, x, h - 20, '#54644c');
      for (let y = 42; y < h - 22; y += 6) {
        c.fillStyle = '#030906'; c.beginPath(); c.arc(x, y, 1.1, 0, Math.PI * 2); c.fill();
      }
      rivet(c, x, 20, 2); rivet(c, x, h - 20, 2);
    }
    c.save(); c.translate(w / 2, 20);
    c.strokeStyle = '#708761'; c.lineWidth = 1;
    c.beginPath(); c.arc(0, 0, 70, 0.12, Math.PI - 0.12); c.stroke();
    for (let i = 1; i < 24; i++) {
      const a = i / 24 * Math.PI, small = i % 4 ? 65 : 59;
      line(c, Math.cos(a) * small, Math.sin(a) * small, Math.cos(a) * 69, Math.sin(a) * 69, '#708761');
    }
    line(c, 0, 0, 31, 54, '#9bb77d', 1.4);
    c.restore();
    for (let i = 0; i < 3; i++) {
      const x = w / 2 - 18 + i * 18;
      c.fillStyle = i === 1 ? '#9fba7b' : '#354b36';
      c.beginPath(); c.arc(x, h - 24, 2.2, 0, Math.PI * 2); c.fill();
    }
  },
};
