/**
 * 河道剖面（T034，制作人「河流应该比地面低，岸边要有岸坡」）：河床真的下沉。水边线还在原来的半宽 half 处（涉水 / 敌人过河 / 刷点避河的语义不变），
 * 往外 bank 米是岸坡：坡顶圆润地接地面、上三分之一最陡（站在岸上看得出「河比地面低一截」），往下缓成水边的湿泥滩；往里是水下坡、缓成河床。
 * - 浅滩：水面比地面低 ford.water 米、河床最深 ford.bed 米（水深 0.6，坦克半个车轮泡在水里），岸坡在水边最陡约 26°；深水河（有桥那条）：deep，约 34°
 * - 坡顶线在田野里起伏（wob：|x| < from 米的路面上固定 bank 米，to 米外起伏满）
 * - 浅滩（没桥的河）路面那一段是过水路面的坡道：岸坡放宽到 ramp.w 米（坦克开下去是缓坡，两边的岸照旧陡，像在岸上切出来的一道坡口），|x| from → to 米过渡
 * - 岸坡剖面 S(v) = 1 − (1 − v)³(1 + 3v)（v = 0 坡顶 → 1 水边，两头斜率都是 0，最陡 1.78 × water ÷ bank 在离坡顶三分之一处）；
 *   水下 = smoothstep，水下坡长 U = (bed − water) × 3.5（1.5 米起、最多到离河心 0.5 米）
 * CPU 的 bedAt / profile 和 GLSL 的 RIVER_BED_GLSL 同一个公式
 */
export const RIVER_BED = {
  bank: 3.6,
  ramp: { w: 6.5, from: 14, to: 20 },
  wob: { from: 16, to: 34, a: [0.12, 0.06], k: [0.11, 0.29], ph: [1.7, 0.6], side: [1.3, 2.9] },
  ford: { water: 1.1, bed: 1.7 },
  deep: { water: 1.5, bed: 3.0 },
};

const smooth = (a: number, b: number, x: number) => {
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
};

/** (x 处、side = 哪一岸 ±1) 的岸坡宽度（水边线 → 坡顶，米）；ramp = 浅滩（路面那一段是过水路面的缓坡） */
export function bankW(x: number, side: number, phase: number, ramp: boolean): number {
  const W = RIVER_BED.wob;
  const ax = Math.abs(x);
  const w = smooth(W.from, W.to, ax);
  const T = w === 0 ? RIVER_BED.bank : RIVER_BED.bank * (1 + w * (W.a[0] * Math.sin(x * W.k[0] + phase * W.ph[0] + side * W.side[0]) + W.a[1] * Math.sin(x * W.k[1] + phase * W.ph[1] + side * W.side[1])));
  const R = RIVER_BED.ramp;
  return ramp && ax < R.to ? T + (R.w - T) * (1 - smooth(R.from, R.to, ax)) : T;
}

/** 河床剖面：d = 离水边线多远（米，水里为负），T = 这里的岸坡宽，W / B = 水面 / 河床低于地面多少，U = 水下坡长；返回地面高度（≤ 0） */
export function bedProfile(d: number, T: number, W: number, B: number, U: number): number {
  if (d >= T) return 0;
  if (d >= 0) {
    const u = d / T;
    return -W * (1 - u * u * u * (4 - 3 * u));
  }
  const t = Math.min(1, -d / U);
  return -W - (B - W) * t * t * (3 - 2 * t);
}

/** 水下坡长（见 RIVER_BED） */
export function underLen(half: number, W: number, B: number): number {
  return Math.min(half - 0.5, Math.max(1.5, (B - W) * 3.5));
}

/** GLSL 版（同一个公式）：岸坡宽 riverBankW、剖面 riverProfile */
export const RIVER_BED_GLSL = /* glsl */ `
float riverBankW(float x, float side, float ph, float ramp) {
  float w = smoothstep(${RIVER_BED.wob.from.toFixed(1)}, ${RIVER_BED.wob.to.toFixed(1)}, abs(x));
  float T = ${RIVER_BED.bank.toFixed(2)};
  if (w > 0.0) T *= (1.0 + w * (${RIVER_BED.wob.a[0].toFixed(3)} * sin(x * ${RIVER_BED.wob.k[0]} + ph * ${RIVER_BED.wob.ph[0].toFixed(2)} + side * ${RIVER_BED.wob.side[0].toFixed(2)}) + ${RIVER_BED.wob.a[1].toFixed(3)} * sin(x * ${RIVER_BED.wob.k[1]} + ph * ${RIVER_BED.wob.ph[1].toFixed(2)} + side * ${RIVER_BED.wob.side[1].toFixed(2)})));
  return mix(T, ${RIVER_BED.ramp.w.toFixed(2)}, ramp * (1.0 - smoothstep(${RIVER_BED.ramp.from.toFixed(1)}, ${RIVER_BED.ramp.to.toFixed(1)}, abs(x))));
}
float riverProfile(float d, float T, float W, float B, float U) {
  if (d >= T) return 0.0;
  if (d >= 0.0) {
    float u = d / T;
    return -W * (1.0 - u * u * u * (4.0 - 3.0 * u));
  }
  float t = min(1.0, -d / U);
  return -W - (B - W) * t * t * (3.0 - 2.0 * t);
}
float riverUnder(float hw, float W, float B) {
  return min(hw - 0.5, max(1.5, (B - W) * 3.5));
}
`;

/**
 * 河道弯曲（T017-3A，策划 4.2 方案 A「田野里蜿蜒、路口拉直」）：三个正弦叠加（振幅 13 / 6 / 2.5 米、波长约 115 / 62 / 37 米，每条河的相位、振幅倍率 amp 各不相同），
 * 再乘「离路越近越小」的系数：|x| < 14 米完全不弯（过路口时和路垂直，桥、涉水、过桥限宽都不用改），40 米外全弯。
 * 地面着色器（河床湿泥）、水面顶点着色器、涉水判定 waterAt、景物 / 弹坑避让 inRiverAt 四处用同一个公式（GLSL 版是 RIVER_BEND_GLSL）
 */
export const RIVER_BEND = { inner: 14, outer: 40, a: [13, 6, 2.5], k: [0.0546, 0.101, 0.17], ph: [1, 2.3, 3.7], off: [0, 1.1, 2.0] };
export function riverBend(x: number, phase: number, amp: number): number {
  const B = RIVER_BEND;
  const t = Math.min(1, Math.max(0, (Math.abs(x) - B.inner) / (B.outer - B.inner)));
  const w = t * t * (3 - 2 * t);
  if (w === 0) return 0;
  let s = 0;
  for (let i = 0; i < 3; i++) s += B.a[i] * Math.sin(x * B.k[i] + phase * B.ph[i] + B.off[i]);
  return w * amp * s;
}
export const RIVER_BEND_GLSL = /* glsl */ `
float riverBend(float x, float ph, float amp) {
  float w = smoothstep(${RIVER_BEND.inner.toFixed(1)}, ${RIVER_BEND.outer.toFixed(1)}, abs(x));
  if (w <= 0.0) return 0.0;
  return w * amp * (${RIVER_BEND.a.map((a, i) => `${a.toFixed(2)} * sin(x * ${RIVER_BEND.k[i]} + ph * ${RIVER_BEND.ph[i].toFixed(2)} + ${RIVER_BEND.off[i].toFixed(2)})`).join(' + ')});
}
`;

/** 水面网格比水边线宽出这么多（米）：多出来的一截藏在岸坡底下，岸线 = 水面和岸坡的真实交线（T034） */
const SHEET_PAD = 0.8;

const VERT = /* glsl */ `
uniform float uPhase;
uniform float uAmp;
varying vec2 vWorld;
varying float vAcross;
#include <fog_pars_vertex>
${RIVER_BEND_GLSL}
void main() {
  vec3 p = position;
  // 与地面河道同样的弯曲
  p.z += riverBend(p.x, uPhase, uAmp);
  vec4 world = modelMatrix * vec4(p, 1.0);
  vWorld = world.xz;
  // 离河心多远（带符号插值：只有两岸两排顶点，取绝对值会全一样）
  vAcross = position.z;
  vec4 mvPosition = viewMatrix * world;
  gl_Position = projectionMatrix * mvPosition;
  #include <fog_vertex>
}`;

/** 水面（T034）：按水深上色——水边浅处透出河床、偏亮，河心发暗；白沫顺着真实岸线（水深很浅的那一圈）走 */
const FRAG = /* glsl */ `
uniform sampler2D uNoise;
uniform float uTime;
uniform vec3 uDeep;
uniform vec3 uShallow;
uniform float uAlpha;
uniform float uHalf;
uniform float uW;
uniform float uB;
uniform float uU;
varying vec2 vWorld;
varying float vAcross;
#include <fog_pars_fragment>
void main() {
  // 水边线外（藏在岸坡底下那一截）不画：岸线就是水边线，岸坡贴近水面的那一点不会和水面打架
  if (abs(vAcross) > uHalf) discard;
  // 水深：和河床剖面同一个公式（水边 0 → 水下坡长 uU 处到河床最深）
  float t = clamp((uHalf - abs(vAcross)) / uU, 0.0, 1.0);
  float depth = (uB - uW) * t * t * (3.0 - 2.0 * t);
  vec2 a = vWorld * 0.06 + vec2(uTime * 0.05, uTime * 0.02);
  vec2 b = vWorld * 0.11 - vec2(uTime * 0.03, -uTime * 0.04);
  float n = texture2D(uNoise, a).r * 0.6 + texture2D(uNoise, b).g * 0.4;
  vec3 c = mix(uDeep, uShallow, smoothstep(0.35, 0.75, n));
  // 浅处：透出河床的黄绿色、更亮
  float sh = 1.0 - smoothstep(0.0, 0.6, depth);
  c = mix(c, uShallow * vec3(1.18, 1.14, 0.92), sh * 0.6);
  // 波光
  float glint = smoothstep(0.66, 0.74, texture2D(uNoise, vWorld * 0.045 + vec2(uTime * 0.03, 0.0)).r) * smoothstep(0.5, 0.7, n);
  c += vec3(0.5, 0.56, 0.52) * glint * 0.25;
  // 顺流的长条波纹
  float streak = smoothstep(0.55, 0.75, texture2D(uNoise, vec2(vWorld.x * 0.01 - uTime * 0.04, vWorld.y * 0.15)).g);
  c = mix(c, uShallow * 1.25, streak * 0.25);
  // 岸边白沫：贴着岸线断断续续一圈（离水边 0.1～0.5 米），被水流推着抖
  float fn = texture2D(uNoise, vWorld * 0.55 + vec2(uTime * 0.08, uTime * 0.03)).r;
  float edge = uHalf - abs(vAcross);
  float foam = (1.0 - smoothstep(0.0, 0.1 + 0.35 * fn, edge)) * smoothstep(0.45, 0.75, fn);
  c = mix(c, vec3(0.62, 0.66, 0.6), foam * 0.45);
  float alpha = mix(uAlpha * 0.35, uAlpha, smoothstep(0.0, 0.45, depth)) + foam * 0.12;
  gl_FragColor = vec4(c, min(1.0, alpha));
  #include <colorspace_fragment>
  #include <fog_fragment>
}`;

export interface River {
  z: number;
  half: number;
  phase: number;
  /** 弯曲振幅倍率（0.8～1.2，见 riverBend） */
  amp: number;
  kind: 'ford' | 'bridge';
  /** 水面 / 河床低于地面多少（米，T034，见 RIVER_BED）、水下坡长 */
  water: number;
  bed: number;
  under: number;
  /** 桥面半宽（0 = 没桥）/ 桥面半长（不含两头坡道；桥长盖满整个河道：水面 + 两边岸坡） */
  deck: number;
  deckLen: number;
  sheet: THREE.Mesh<THREE.PlaneGeometry, THREE.ShaderMaterial>;
  /** 桥（深水河的桥 / 钢铁厂区浅滩的平板桥）或浅滩的踏步石（村镇），没有就 null */
  bridge: THREE.Object3D | null;
  /** 已经布置过守军 */
  manned: boolean;
}

/** 浅滩的一根水位标杆（T034）：t = 0 立着 → 1 倒平，朝 (dx, dz) 倒 */
interface Marker {
  river: River;
  x: number;
  y: number;
  z: number;
  t: number;
  dx: number;
  dz: number;
}

const _m = new THREE.Matrix4();
const _q = new THREE.Quaternion();
const _p = new THREE.Vector3();
const _a = new THREE.Vector3();
const _one = new THREE.Vector3(1, 1, 1);

/**
 * 固定河位（T027-d，策划 `T027-策划案-D5版.md` 第 4 节，制作人「只设计几个固定的地方有河流」）：每区两条，按「进区多远」摆（区域 1 = 开局，之后 = 上一个首领被击败的地方）；
 * 种类 / 半宽固定（浅滩水面 11 米、深水河 15 米，区域 2 的窄一点 13 米），无尽按区域 1～4 轮回。表里的 at 是区域 1（开局）的距离：260 / 640 米；
 * 区域 2 起（含无尽）都往后挪 LATE 米 = 380 / 760 米——进区那一刻前方 340 米的路障、300 米的景物已经摆好了，第一条河得摆在它们外面（不然路障 / 灌木会泡在河里）；
 * 第二条之后到首领（一般在进区 900～1100 米处出来）不再有河；首领出来以后这一区还没摆的河位不再摆，首领战场附近还没进画面的河收掉（clearArena）
 */
export const RIVER_PLAN: { at: number; kind: River['kind']; half: number }[][] = [
  [{ at: 260, kind: 'ford', half: 5.5 }, { at: 640, kind: 'bridge', half: 7.5 }],
  [{ at: 260, kind: 'bridge', half: 6.5 }, { at: 640, kind: 'ford', half: 5.5 }],
  [{ at: 260, kind: 'ford', half: 5.5 }, { at: 640, kind: 'bridge', half: 7.5 }],
  [{ at: 260, kind: 'bridge', half: 7.5 }, { at: 640, kind: 'ford', half: 5.5 }],
  // 区域 5「荒原机场」（T093）：进区 380 米浅滩、760 米钢桥河，跑道段（400～650 米）夹在中间
  [{ at: 260, kind: 'ford', half: 5.5 }, { at: 640, kind: 'bridge', half: 7.5 }],
  // 区域 6「沙漠油井」（T122）：沙漠里没水，不放河
  [],
];
/** 每条河 3 套弯法（相位, 振幅倍率）：田野里往哪边拐、拐多大，每局每条随机抽一套（再按区号 / 第几条错开相位，同一局两条河不一样）；路面上一律笔直 */
export const RIVER_BENDS: [number, number][] = [[0.6, 1.0], [2.4, 1.15], [4.3, 0.85]];
/**
 * 河段离坦克前方多远就摆好：要比路障（340 米 + 河道 / 岸边 / 路障避河的 6 米 ≈ 357）、铁路（330）、景物（300）都早，它们一开始就知道这里是河
 * （改前河在 330 米才生成，路障偶尔摆进水里）
 */
const PLACE_AHEAD = 380;
/** 区域 2 起河位往后挪多少米（见 RIVER_PLAN） */
const LATE = 120;
/** 首领战场附近的河：离首领 ARENA 米内、还在坦克前方 ARENA_HIDE 米外（没进画面）的收掉 */
const ARENA = 150;
const ARENA_HIDE = 140;
/** 河心 z 离 (x, z) 超过 half + REACH 米就肯定不在河道里（岸坡最宽 6.5 + 河道在田野里最多弯开 25 米） */
const REACH = 32;

/** 河流：每区两条固定河位（T027-d），浅滩（涉水减速、水花）和深水桥（桥面窄，桥头常有守军） */
export class Rivers {
  readonly group = new THREE.Group();
  readonly list: River[] = [];
  /** 当前区号、这一区开始的地方（z）、下一个要摆的河位；stop = 这一区的首领出来了，不再摆（Game 每帧写） */
  private zone = 1;
  private zoneStart = 0;
  private site = 0;
  stop = false;
  private time = 0;
  private readonly noise = grayNoise();
  /** 浅滩的水位标杆（所有河一个实例化网格，1 次绘制） */
  private readonly markers: Marker[] = [];
  private readonly markerMesh: THREE.InstancedMesh;
  private markerDirty = false;

  constructor(
    private readonly geo: GeoCache,
    private readonly terrain: Terrain,
  ) {
    this.noise.wrapS = this.noise.wrapT = THREE.RepeatWrapping;
    // 水位标杆：白漆木桩 + 两道红箍 + 顶上一截红（原点在桩脚，倒的时候绕桩脚转）
    const mg = geo.merged('river-marker', () => [
      { geo: new THREE.BoxGeometry(0.16, MARKER.h, 0.16), color: 0xd8d4c8, pos: [0, MARKER.h / 2, 0] },
      { geo: new THREE.BoxGeometry(0.17, 0.22, 0.17), color: 0xa8281e, pos: [0, MARKER.h - 0.11, 0] },
      { geo: new THREE.BoxGeometry(0.17, 0.18, 0.17), color: 0xa8281e, pos: [0, MARKER.h * 0.55, 0] },
      { geo: new THREE.BoxGeometry(0.17, 0.18, 0.17), color: 0xa8281e, pos: [0, MARKER.h * 0.22, 0] },
    ]);
    this.markerMesh = new THREE.InstancedMesh(mg, MAT.painted, MARKER.max);
    this.markerMesh.count = 0;
    this.markerMesh.castShadow = true;
    this.markerMesh.frustumCulled = false;
    this.group.add(this.markerMesh);
  }

  reset(): void {
    for (const r of this.list) this.remove(r);
    this.list.length = 0;
    this.markers.length = 0;
    this.markerDirty = true;
    this.zone = 1;
    this.zoneStart = 0;
    this.site = 0;
    this.stop = false;
    this.terrain.setRivers([]);
  }

  /** 进了新的一区（Game 在区号变的那一帧调）：从 z 开始按这一区的河位表摆 */
  enterZone(zone: number, z: number): void {
    this.zone = zone;
    this.zoneStart = z;
    this.site = 0;
  }

  /** 读档 / 试玩开局（直接从第 zone 区开始）：开局按区域 1 摆好的河清掉，从 z 开始按这一区的表摆 */
  restart(zone: number, z: number): void {
    this.reset();
    this.enterZone(zone, z);
  }

  /** 首领要刷出来了（DirectorHooks.arena）：首领战场附近、还没进画面的河收掉，这一区剩下的河位不再摆 */
  clearArena(z: number, playerZ: number): void {
    this.site = RIVER_PLAN[cyc(this.zone)].length;
    for (let i = this.list.length - 1; i >= 0; i--) {
      const r = this.list[i];
      if (Math.abs(r.z - z) > ARENA || r.z > playerZ - ARENA_HIDE) continue;
      this.remove(r);
      this.list.splice(i, 1);
    }
    this.terrain.setRivers(this.list);
  }

  /** rear = 身后收掉按的位置（T107 停车攻坚时是能退到的最远处，平时就是玩家） */
  update(delta: number, playerZ: number, themeAt: (z: number) => Theme, rear = playerZ): void {
    this.time += delta;
    const zi = cyc(this.zone);
    const plan = RIVER_PLAN[zi];
    while (!this.stop && this.site < plan.length) {
      const p = plan[this.site];
      const z = this.zoneStart - p.at - (this.zone > 1 ? LATE : 0);
      if (z < playerZ - PLACE_AHEAD) break;
      // 已经开过去了（读档 / 跳区）的就不摆了
      if (z < playerZ - 15) {
        const bend = RIVER_BENDS[Math.floor(rng.map() * RIVER_BENDS.length)];
        this.spawn(z, themeAt(z), p.kind, p.half, bend[0] + (zi * 2 + this.site) * 0.9, bend[1]);
      }
      this.site++;
    }
    for (let i = this.list.length - 1; i >= 0; i--) {
      if (this.list[i].z > rear + 70) {
        this.remove(this.list[i]);
        this.list.splice(i, 1);
      }
    }
    for (const r of this.list) r.sheet.material.uniforms.uTime.value = this.time;
    this.terrain.setRivers(this.list);
    // 碰倒的水位标杆：越倒越快，倒平为止
    for (const m of this.markers) {
      if (m.t <= 0 || m.t >= 1) continue;
      m.t = Math.min(1, m.t + delta / MARKER.knock);
      this.markerDirty = true;
    }
    if (this.markerDirty) this.syncMarkers();
  }

  /** 坦克压过（World.press）：车身（中心 x, z、半宽 halfW、半长 halfL、朝向 yaw）碰到的水位标杆往外 / 往前倒；返回这一下碰倒了几根 */
  press(x: number, z: number, halfW: number, halfL: number, yaw: number): number {
    let n = 0;
    const c = Math.cos(yaw);
    const s = Math.sin(yaw);
    for (const m of this.markers) {
      if (m.t > 0) continue;
      const dx = m.x - x;
      const dz = m.z - z;
      if (Math.abs(dx * c - dz * s) > halfW + 0.15 || Math.abs(dx * s + dz * c) > halfL + 0.15) continue;
      // 往车头方向 + 往车身外侧倒
      this.knock(m, -s + Math.sign(dx) * 0.6, -c);
      n++;
    }
    return n;
  }

  /** 爆炸（World.blast）：半径 + 0.5 米里的水位标杆背离爆心倒 */
  blast(x: number, z: number, radius: number): void {
    for (const m of this.markers) {
      if (m.t > 0) continue;
      const dx = m.x - x;
      const dz = m.z - z;
      const d = Math.hypot(dx, dz);
      if (d < radius + 0.5) this.knock(m, d > 0.1 ? dx : 1, d > 0.1 ? dz : 0);
    }
  }

  private knock(m: Marker, dx: number, dz: number): void {
    const l = Math.hypot(dx, dz) || 1;
    m.dx = dx / l;
    m.dz = dz / l;
    m.t = 1e-3;
    this.markerDirty = true;
  }

  private syncMarkers(): void {
    this.markerDirty = false;
    const mm = this.markerMesh;
    this.markers.forEach((m, i) => {
      const e = m.t * m.t;
      _q.setFromAxisAngle(_a.set(m.dz, 0, -m.dx), 1.45 * e);
      _m.compose(_p.set(m.x, m.y, m.z), _q, _one);
      mm.setMatrixAt(i, _m);
    });
    mm.count = this.markers.length;
    mm.instanceMatrix.needsUpdate = true;
  }

  /** 路面上（|x| < 14 米河道是直的）z 附近是不是河道（路障不往河里摆） */
  inRiver(z: number, margin = 0): boolean {
    return this.inRiverAt(0, z, margin);
  }

  /** (x, z) 是不是在河道里（水面 + 岸坡到坡顶 + margin，T034：原来是「岸边 3 米」；景物、弹坑避让用，T017-3A：沿河岸摆，不再整排空出来） */
  inRiverAt(x: number, z: number, margin = 0): boolean {
    for (const r of this.list) {
      const dz = z - r.z - riverBend(x, r.phase, r.amp);
      if (Math.abs(dz) < r.half + bankW(x, dz < 0 ? -1 : 1, r.phase, !r.deck) + margin) return true;
    }
    return false;
  }

  /** 坦克是否在水里（桥面上不算） */
  waterAt(x: number, z: number): River | null {
    for (const r of this.list) {
      if (Math.abs(z - r.z) > r.half + REACH) continue;
      const bend = r.z + riverBend(x, r.phase, r.amp);
      if (Math.abs(z - bend) > r.half) continue;
      if (r.deck > 0 && Math.abs(x) < r.deck - (BRIDGE.halfW - BRIDGE.dry)) return null;
      return r;
    }
    return null;
  }

  /** 地面效果是否碰到干地。只在落点生成时查中心和八个边点，跨岸的边缘再由着色器逐像素裁掉。 */
  hasLand(x: number, z: number, radius: number): boolean {
    if (!this.waterAt(x, z)) return true;
    // 桥可能整个落在圆内，中心和圆周都在水里；单独算圆与桥面矩形的相交。
    for (const r of this.list) {
      if (r.deck && Math.hypot(Math.max(0, Math.abs(x) - r.deck + BRIDGE.halfW - BRIDGE.dry), Math.max(0, Math.abs(z - r.z) - r.deckLen)) < radius) return true;
    }
    for (const [dx, dz] of SURFACE_RING) if (!this.waterAt(x + dx * radius, z + dz * radius)) return true;
    return false;
  }

  /** 爆炸圆里最近的水点，供岸上的爆炸分一部分原有粒子给水花；桥面仍算干地。 */
  waterNear(x: number, z: number, radius: number): WaterContact | null {
    let best: WaterContact | null = null;
    for (const r of this.list) {
      if (Math.abs(z - r.z) > r.half + REACH + radius) continue;
      for (let i = -2; i <= 2; i++) {
        let sx = x + i * radius * 0.5;
        if (r.deck && Math.abs(sx) < r.deck - (BRIDGE.halfW - BRIDGE.dry)) {
          sx = (sx < 0 ? -1 : 1) * (r.deck - (BRIDGE.halfW - BRIDGE.dry) + 0.02);
        }
        const center = r.z + riverBend(sx, r.phase, r.amp);
        const sz = Math.max(center - r.half + 0.02, Math.min(center + r.half - 0.02, z));
        const distance = Math.hypot(sx - x, sz - z);
        if (distance > radius || (best && distance >= best.distance)) continue;
        best = { x: sx, z: sz, y: -r.water, distance };
      }
    }
    return best;
  }

  /** 敌人用（T025）：(x, z) 在水里就返回 { deep = 有桥的深水河（桥面上不算水）, near / far = 这个 x 上两岸的 z（离坦克近的一侧 near = z 大的那侧） }，不在水里 null */
  riverAt(x: number, z: number): { deep: boolean; near: number; far: number } | null {
    const r = this.waterAt(x, z);
    if (!r) return null;
    const c = r.z + riverBend(x, r.phase, r.amp);
    return { deep: r.kind === 'bridge', near: c + r.half + 0.6, far: c - r.half - 0.6 };
  }

  /** 河道让地面下沉多少（≤ 0，T034：河床 + 岸坡；和 GLSL riverBedH 同一个公式，河道外 0） */
  bedAt(x: number, z: number): number {
    let h = 0;
    for (const r of this.list) {
      if (Math.abs(z - r.z) > r.half + REACH) continue;
      const dz = z - r.z - riverBend(x, r.phase, r.amp);
      const T = bankW(x, dz < 0 ? -1 : 1, r.phase, !r.deck);
      const d = Math.abs(dz) - r.half;
      if (d < T) h = Math.min(h, bedProfile(d, T, r.water, r.bed, r.under));
    }
    return h;
  }

  /** 桥面高度（绝对高度，含两头坡道；T034：原来是「比地面高 0.5」的凸起，河床一下沉桥面会跟着陷下去）；不在桥面上 −∞。和 GLSL deckH 同一个公式 */
  deckAt(x: number, z: number): number {
    for (const r of this.list) {
      if (!r.deck || Math.abs(x) > r.deck) continue;
      const end = r.deckLen + BRIDGE.ramp;
      const dz = Math.abs(z - r.z);
      if (dz < end) return BRIDGE.deck * Math.min(1, (end - dz) / BRIDGE.ramp);
    }
    return -Infinity;
  }

  /** 水面高度（T034：水面低于地面 water 米；桥面上 / 不在水里 −∞） */
  levelAt(x: number, z: number): number {
    const r = this.waterAt(x, z);
    return r ? -r.water : -Infinity;
  }

  /**
   * 刷点避河（T025）：(x, z) 压到河道（水面 + 岸坡 + margin）就往前（远离坦克，z 更小）挪到对岸坡顶外；不压返回原来的 z
   */
  dryZ(x: number, z: number, margin = 0): number {
    for (let k = 0; k < 3; k++) {
      let moved = false;
      for (const r of this.list) {
        const c = r.z + riverBend(x, r.phase, r.amp);
        if (Math.abs(z - c) < r.half + bankW(x, z < c ? -1 : 1, r.phase, !r.deck) + margin) {
          z = c - r.half - bankW(x, -1, r.phase, !r.deck) - margin - 0.5;
          moved = true;
        }
      }
      if (!moved) break;
    }
    return z;
  }

  /**
   * 过桥时的横向限制 |x| ≤ 返回值，null 表示不限（laneMax = 平时的限宽）。桥面 + 两头坡道上是 BRIDGE.lane；桥头收窄那一段跟着路面一起收
   * （坦克外沿始终在护栏里），再往外 lead 米从收窄段起点的宽度慢慢放回 laneMax；平板桥只在桥面上限到 CULVERT.lane（两头 lead 米放回去）
   */
  laneLimit(z: number, laneMax = APPROACH.road + 4): number | null {
    let lim: number | null = null;
    const A = APPROACH;
    for (const r of this.list) {
      if (!r.deck) continue;
      const a = Math.abs(z - r.z) - r.deckLen - BRIDGE.ramp;
      let L: number;
      if (r.deck > A.road) {
        if (a > A.lead) continue;
        L = CULVERT.lane + (laneMax - CULVERT.lane) * Math.max(0, a / A.lead);
      } else {
        if (a > A.funnel + A.lead) continue;
        const wide = A.road - (r.deck - 0.2);
        L = BRIDGE.lane + wide * smooth(0, A.funnel, a);
        if (a > A.funnel) L += (laneMax - BRIDGE.lane - wide) * ((a - A.funnel) / A.lead);
      }
      lim = lim === null ? L : Math.min(lim, L);
    }
    return lim;
  }

  /** 桥头收窄（T034）：z 处路面半宽（没在收窄段里 = APPROACH.road）；和地面着色器里收窄的那段同一个公式 */
  roadHalfAt(z: number): number {
    let w = APPROACH.road;
    for (const r of this.list) {
      if (!r.deck || r.deck > APPROACH.road) continue;
      const a = Math.abs(z - r.z) - r.deckLen - BRIDGE.ramp;
      if (a < APPROACH.funnel) w = Math.min(w, r.deck - 0.2 + (APPROACH.road - (r.deck - 0.2)) * smooth(0, APPROACH.funnel, a));
    }
    return w;
  }

  private spawn(z: number, theme: Theme, kind: River['kind'], half: number, phase: number, amp: number): void {
    const D = kind === 'ford' ? RIVER_BED.ford : RIVER_BED.deep;
    const under = underLen(half, D.water, D.bed);
    // 192 段（约 4 米一段，T017-3A：原来 96 段，河湾的最短波长 37 米要画得圆）；比水边线宽 SHEET_PAD，多出来的藏在岸坡底下
    const geo = new THREE.PlaneGeometry(760, (half + SHEET_PAD) * 2, 192, 1);
    geo.rotateX(-Math.PI / 2);
    const mat = new THREE.ShaderMaterial({
      vertexShader: VERT,
      fragmentShader: FRAG,
      uniforms: THREE.UniformsUtils.merge([
        THREE.UniformsLib.fog,
        {
          uNoise: { value: null },
          uTime: { value: 0 },
          uPhase: { value: phase },
          uAmp: { value: amp },
          uHalf: { value: half },
          uW: { value: D.water },
          uB: { value: D.bed },
          uU: { value: under },
          uDeep: { value: new THREE.Color(kind === 'ford' ? 0x2e4c50 : 0x18303a) },
          uShallow: { value: new THREE.Color(kind === 'ford' ? 0x5a8080 : 0x2e5260) },
          uAlpha: { value: kind === 'ford' ? 0.8 : 0.95 },
        },
      ]),
      transparent: true,
      depthWrite: false,
      // 水边浅处水面和河床挨得很近：水面往镜头这边让一点，不和河床抢深度
      polygonOffset: true,
      polygonOffsetFactor: -1,
      polygonOffsetUnits: -2,
      fog: true,
    });
    mat.uniforms.uNoise.value = this.noise;
    const sheet = new THREE.Mesh(geo, mat);
    // 水面在下沉的河道里（T034：原来铺在地面上 0.12～0.22 米）
    sheet.position.set(0, -D.water, z);
    sheet.renderOrder = 1;
    sheet.frustumCulled = false;
    this.group.add(sheet);

    let bridge: THREE.Object3D | null = null;
    let deck = 0;
    let deckLen = 0;
    // 钢铁厂区（城市）的浅滩不涉水，换成和路一样宽的混凝土平板桥（T034 第 2 批）
    const culvert = kind === 'ford' && theme.id === 'foundry';
    if (kind === 'bridge' || culvert) {
      // 路面上河道是直的（riverBend 在 |x| < 14 米为 0），桥就架在河心；桥长盖满整个河道（水面 + 两边岸坡），桥面在坡顶的高度，两头坡道落在平地上
      deck = culvert ? CULVERT.halfW : BRIDGE.halfW;
      deckLen = half + RIVER_BED.bank;
      bridge = culvert ? this.buildCulvert(half, D, under) : this.buildBridge(theme.bridge, half, D, under);
    } else if (theme.bridge === 'stone') bridge = this.buildStones(half, D, under, phase);
    if (bridge) {
      bridge.position.set(0, 0, z);
      this.group.add(bridge);
    }
    const r: River = { z, half, phase, amp, kind, water: D.water, bed: D.bed, under, deck, deckLen, sheet, bridge, manned: false };
    this.list.push(r);
    // 浅滩（田野 / 林间 / 村镇）：过水路面两边各一排水位标杆，从坡顶一直插到河心
    if (kind === 'ford' && !culvert) {
      const T = RIVER_BED.ramp.w;
      const n = Math.floor(((half + T) * 2) / MARKER.gap);
      for (const sd of [-1, 1]) {
        for (let i = 0; i <= n; i++) {
          if (this.markers.length >= MARKER.max) break;
          const zl = -(half + T) + 0.4 + (i * ((half + T) * 2 - 0.8)) / n;
          this.markers.push({ river: r, x: sd * MARKER.x, y: bedProfile(Math.abs(zl) - half, T, D.water, D.bed, under), z: z + zl, t: 0, dx: 0, dz: 1 });
        }
      }
      this.markerDirty = true;
    }
  }

  /**
   * 桥头护栏（T034 第 2 批）：路面在桥头坡道外 APPROACH.funnel 米里收窄到桥面宽，收窄那一段两边沿着路边各一排护栏（坡道那 2 米是直的）；
   * 钢铁厂区 = 波形钢护栏 + 桥头黄黑立柱，田野 / 林间 = 木桩 + 横木，村镇 = 一排石墩。坐标相对河心
   */
  private approach(style: Theme['bridge'], len: number): PartSpec[] {
    const p: PartSpec[] = [];
    const A = APPROACH;
    const W = BRIDGE.halfW;
    const R = BRIDGE.ramp;
    const edge = (s: number) => (s <= 0 ? W : W - 0.2 + (A.road - (W - 0.2)) * smooth(0, A.funnel, s) + 0.5);
    for (const e of [-1, 1]) {
      for (const sd of [-1, 1]) {
        const pts: [number, number][] = [];
        for (let s = -R; s <= A.funnel + 0.01; s += 1) pts.push([sd * edge(s), e * (len / 2 + R + s)]);
        pts.forEach(([x, z], i) => {
          if (style === 'stone') {
            if (i % 2 === 0) p.push({ geo: new THREE.BoxGeometry(0.45, 0.6, 0.45), color: i % 4 ? 0x8a847a : 0x7e786e, pos: [x, 0.3, z] });
            return;
          }
          if (i % 2 === 0) p.push({ geo: new THREE.BoxGeometry(style === 'steel' ? 0.14 : 0.2, style === 'steel' ? 0.85 : 1.0, style === 'steel' ? 0.14 : 0.2), color: style === 'steel' ? 0x4a4a48 : 0x4a3a2a, pos: [x, style === 'steel' ? 0.425 : 0.5, z] });
          const nx = pts[i + 1];
          if (!nx) return;
          const L = Math.hypot(nx[0] - x, nx[1] - z);
          p.push({ geo: new THREE.BoxGeometry(style === 'steel' ? 0.08 : 0.12, style === 'steel' ? 0.3 : 0.14, L + 0.02), color: style === 'steel' ? 0x8a8c88 : 0x5a4632, pos: [(x + nx[0]) / 2, style === 'steel' ? 0.6 : 0.9, (z + nx[1]) / 2], rot: [0, Math.atan2(nx[0] - x, nx[1] - z), 0] });
        });
        // 钢铁厂区：桥头一根黄黑相间的防撞立柱
        if (style === 'steel') for (let k = 0; k < 4; k++) p.push({ geo: new THREE.BoxGeometry(0.42, 0.28, 0.42), color: k % 2 ? 0x1e1e1c : 0xc8a020, pos: [sd * (W + 0.1), 0.14 + k * 0.28, e * (len / 2 + R + 0.3)] });
      }
    }
    return p;
  }

  /**
   * 混凝土平板桥（T034 第 2 批，钢铁厂区的浅滩）：桥面 31 米宽盖住整条路 + 路肩，路面画白边线 + 中间虚线；两侧混凝土矮墙 + 钢栏杆 + 路灯、
   * 矮墙两头黄黑警示；水里两排墙式桥墩，两头桥台落在坡顶
   */
  private buildCulvert(half: number, D: { water: number; bed: number }, under: number): THREE.Mesh {
    const len = (half + RIVER_BED.bank) * 2;
    const W = CULVERT.halfW;
    const R = BRIDGE.ramp;
    const H = BRIDGE.deck;
    const bed = (zl: number) => bedProfile(Math.abs(zl) - half, RIVER_BED.bank, D.water, D.bed, under);
    const g = this.geo.merged(`culvert-${half}-${D.bed}`, () => {
      const p: PartSpec[] = [];
      p.push({ geo: new THREE.BoxGeometry(W * 2, 0.7, len), color: 0x5a5852, pos: [0, H - 0.35, 0] });
      for (const e of [-1, 1]) p.push({ geo: new THREE.BoxGeometry(W * 2 - 0.4, 0.24, Math.hypot(R, H)), color: 0x66635c, pos: [0, 0.14, e * (len / 2 + R / 2)], rot: [e * Math.atan2(H, R), 0, 0] });
      // 路面标线：两条白边线 + 中间虚线
      for (const sd of [-1, 1]) p.push({ geo: new THREE.BoxGeometry(0.25, 0.02, len), color: 0xb4b0a4, pos: [sd * (APPROACH.road - 0.5), H + 0.01, 0] });
      for (let zz = -len / 2 + 1; zz < len / 2 - 1; zz += 4) p.push({ geo: new THREE.BoxGeometry(0.2, 0.02, 2), color: 0xb4b0a4, pos: [0, H + 0.01, zz + 1] });
      for (const sd of [-1, 1]) {
        // 矮墙 + 钢栏杆
        p.push({ geo: new THREE.BoxGeometry(0.45, 0.85, len), color: 0x8a867c, pos: [sd * (W - 0.25), H + 0.425, 0] });
        p.push({ geo: new THREE.BoxGeometry(0.08, 0.08, len), color: 0x4e5054, pos: [sd * (W - 0.25), H + 1.45, 0] });
        const posts = Math.round(len / 2);
        for (let i = 0; i <= posts; i++) p.push({ geo: new THREE.BoxGeometry(0.08, 0.6, 0.08), color: 0x4e5054, pos: [sd * (W - 0.25), H + 1.15, -len / 2 + (i * len) / posts] });
        // 矮墙两头黄黑警示
        for (const e of [-1, 1]) for (let k = 0; k < 3; k++) p.push({ geo: new THREE.BoxGeometry(0.5, 0.29, 0.5), color: k % 2 ? 0x1e1e1c : 0xc8a020, pos: [sd * (W - 0.25), H + 0.145 + k * 0.29, e * (len / 2 - 0.25)] });
        // 路灯：灯杆 + 挑臂 + 灯罩
        for (const e of [-1, 1]) {
          p.push({ geo: new THREE.CylinderGeometry(0.09, 0.12, 5.2, 8), color: 0x3e4042, pos: [sd * (W - 0.25), H + 3.45, e * len * 0.25] });
          p.push({ geo: new THREE.BoxGeometry(1.6, 0.1, 0.12), color: 0x3e4042, pos: [sd * (W - 1.0), H + 6.0, e * len * 0.25] });
          p.push({ geo: new THREE.BoxGeometry(0.5, 0.18, 0.3), color: 0x2a2a28, pos: [sd * (W - 1.7), H + 5.9, e * len * 0.25] });
        }
      }
      // 水里两排墙式桥墩（墩帽略宽），两头桥台
      for (const zl of [-half * 0.45, half * 0.45]) {
        const top = H - 0.7;
        const bot = bed(zl) - 0.5;
        p.push({ geo: new THREE.BoxGeometry(W * 2 - 3, top - bot, 0.9), color: 0x7a766c, pos: [0, (top + bot) / 2, zl] });
        p.push({ geo: new THREE.BoxGeometry(W * 2 - 2.4, 0.3, 1.3), color: 0x8a867c, pos: [0, top - 0.15, zl] });
      }
      for (const e of [-1, 1]) p.push({ geo: new THREE.BoxGeometry(W * 2, 1.3, 1.0), color: 0x77726a, pos: [0, -0.5, e * (len / 2 - 0.5)] });
      return p;
    });
    const m = new THREE.Mesh(g, MAT.painted);
    m.castShadow = true;
    m.receiveShadow = true;
    return m;
  }

  /** 踏步石（T034 第 2 批，村镇的浅滩）：路左边 3 米外一溜扁石头横过河道，水里的冒出水面一点，岸坡上的平铺在坡上 */
  private buildStones(half: number, D: { water: number; bed: number }, under: number, phase: number): THREE.Mesh {
    const x = -(APPROACH.road + 3.2);
    const g = this.geo.merged(`ford-stones-${half}-${D.bed}`, () => {
      const p: PartSpec[] = [];
      const T = bankW(x, 1, phase, true);
      for (let zl = -(half + T) + 0.5, i = 0; zl < half + T - 0.4; zl += 0.85, i++) {
        const gy = bedProfile(Math.abs(zl) - half, T, D.water, D.bed, under);
        const top = Math.max(gy + 0.14, -D.water + 0.12);
        const r = 0.36 + ((i * 37) % 7) * 0.025;
        p.push({ geo: new THREE.CylinderGeometry(r, r * 1.15, top - gy + 0.3, 7), color: i % 3 ? 0x8a847a : 0x7a746a, pos: [x + ((i * 53) % 5) * 0.08 - 0.16, (top + gy - 0.3) / 2, zl], rot: [0, i * 0.7, 0] });
      }
      return p;
    });
    const m = new THREE.Mesh(g, MAT.painted);
    m.castShadow = true;
    m.receiveShadow = true;
    return m;
  }

  /**
   * 桥（T034 重做：架在下沉的河道上）：桥长 = 水面 + 两边岸坡，桥面在原来的高度（地面 + 0.5），桥墩 / 木桩一直插到河床，两头桥台落在坡顶；
   * 桥面 13.2 米宽（BRIDGE.halfW），坦克靠边过桥也不碰护栏 / 桁架
   */
  private buildBridge(style: Theme['bridge'], half: number, D: { water: number; bed: number }, under: number): THREE.Mesh {
    const len = (half + RIVER_BED.bank) * 2;
    const W = BRIDGE.halfW;
    const R = BRIDGE.ramp;
    const H = BRIDGE.deck;
    // 桥下（路面上，河道是直的）离河心 zl 处的地面高度
    const bed = (zl: number) => bedProfile(Math.abs(zl) - half, RIVER_BED.bank, D.water, D.bed, under);
    // 桥头斜板（坡道）：从桥面斜到地面
    const ramps = (w: number, th: number, y: number, color: number): PartSpec[] => [-1, 1].map((e) => ({ geo: new THREE.BoxGeometry(w, th, Math.hypot(R, H)), color, pos: [0, y, e * (len / 2 + R / 2)], rot: [e * Math.atan2(H, R), 0, 0] }));
    // 河道里每隔 gap 米一排桥墩（落在比地面低 deep 米以下的地方）
    const bents = (gap: number, deep: number) => {
      const n = Math.max(2, Math.round(len / gap));
      const out: number[] = [];
      for (let i = 1; i < n; i++) if (bed(-len / 2 + (i * len) / n) < -deep) out.push(-len / 2 + (i * len) / n);
      return out;
    };
    const g = this.geo.merged(`bridge-${style}-${half}-${D.bed}`, () => {
      const p: PartSpec[] = [];
      if (style === 'wood') {
        // 木桥：横铺木板 + 纵梁 + 栏杆 + 木桩排架（帽梁 + 剪刀撑）+ 两头木垛桥台
        const planks = Math.round(len / 0.55);
        const step = len / planks;
        for (let i = 0; i < planks; i++) p.push({ geo: new THREE.BoxGeometry(W * 2, 0.14, step - 0.05), color: i % 3 === 0 ? 0x6a5236 : i % 3 === 1 ? 0x7a5e40 : 0x5e4830, pos: [0, 0.44, -len / 2 + step * (i + 0.5)], rot: [0, (i % 5) * 0.004, 0] });
        for (const x of [-5.4, -2.7, 0, 2.7, 5.4]) p.push({ geo: new THREE.BoxGeometry(0.4, 0.4, len), color: 0x4a3a2a, pos: [x, 0.17, 0] });
        p.push(...ramps(W * 2 - 0.6, 0.12, 0.22, 0x5e4830));
        const posts = Math.round(len / 2.4);
        for (const sd of [-1, 1]) {
          p.push({ geo: new THREE.BoxGeometry(0.16, 0.16, len), color: 0x5a4632, pos: [sd * (W - 0.1), 1.4, 0] });
          p.push({ geo: new THREE.BoxGeometry(0.12, 0.12, len), color: 0x5a4632, pos: [sd * (W - 0.1), 0.95, 0] });
          for (let i = 0; i <= posts; i++) p.push({ geo: new THREE.BoxGeometry(0.22, 1.1, 0.22), color: 0x4a3a2a, pos: [sd * (W - 0.1), 0.95, -len / 2 + (i * len) / posts] });
        }
        for (const zl of bents(4.5, 0.25)) {
          const top = -0.33;
          const bot = bed(zl) - 0.5;
          p.push({ geo: new THREE.BoxGeometry(W * 2 - 0.4, 0.3, 0.4), color: 0x4a3a2a, pos: [0, -0.18, zl] });
          for (const x of [-5.4, -2.7, 0, 2.7, 5.4]) p.push({ geo: new THREE.CylinderGeometry(0.2, 0.24, top - bot, 7), color: 0x3a2e22, pos: [x, (top + bot) / 2, zl] });
          // 剪刀撑：水面以上交叉两根
          const lo = -D.water + 0.25;
          const span = 10.8;
          const dy = top - 0.1 - lo;
          for (const s of [-1, 1]) p.push({ geo: new THREE.BoxGeometry(Math.hypot(span, dy), 0.14, 0.14), color: 0x43352a, pos: [0, (top - 0.1 + lo) / 2, zl + 0.22], rot: [0, 0, s * Math.atan2(dy, span)] });
        }
        for (const e of [-1, 1]) p.push({ geo: new THREE.BoxGeometry(W * 2, 1.0, 1.0), color: 0x4a3a2a, pos: [0, -0.18, e * (len / 2 - 0.5)] });
      } else if (style === 'steel') {
        // 钢桥（T019-c 钢铁厂区）：钢板梁桥面 + 两侧下承式桁架（上下弦 + 斜腹杆）+ 混凝土桥墩（墩帽 + 墩身插到河床）+ 两头混凝土桥台，配色照铁路桥
        p.push({ geo: new THREE.BoxGeometry(W * 2 + 0.2, 0.36, len), color: 0x55524e, pos: [0, 0.32, 0] });
        for (const x of [-4.8, -1.6, 1.6, 4.8]) p.push({ geo: new THREE.BoxGeometry(0.5, 0.9, len), color: 0x46433f, pos: [x, -0.3, 0] });
        p.push(...ramps(W * 2 - 0.2, 0.24, 0.14, 0x6a6660));
        const bay = len / Math.max(2, Math.round(len / 3.2));
        const X = W + 0.15;
        for (const sd of [-1, 1]) {
          p.push({ geo: new THREE.BoxGeometry(0.34, 0.34, len), color: 0x5e3a2e, pos: [sd * X, 0.7, 0] });
          p.push({ geo: new THREE.BoxGeometry(0.34, 0.34, len - bay), color: 0x5e3a2e, pos: [sd * X, 3.0, 0] });
          for (let z = -len / 2; z <= len / 2 + 0.01; z += bay) p.push({ geo: new THREE.BoxGeometry(0.26, 2.3, 0.26), color: 0x6a4234, pos: [sd * X, 1.85, z] });
          for (let z = -len / 2; z < len / 2 - 0.01; z += bay) p.push({ geo: new THREE.BoxGeometry(0.2, Math.hypot(2.3, bay), 0.2), color: 0x6a4234, pos: [sd * X, 1.85, z + bay / 2], rot: [Math.atan2(bay, 2.3) * (Math.round((z + len / 2) / bay) % 2 ? 1 : -1), 0, 0] });
        }
        for (const zl of bents(8, 0.4)) {
          const top = -0.9;
          const bot = bed(zl) - 0.6;
          p.push({ geo: new THREE.BoxGeometry(W * 2 - 0.8, 0.32, 1.7), color: 0x8a847a, pos: [0, -0.9, zl] });
          p.push({ geo: new THREE.BoxGeometry(W * 2 - 1.8, top - bot, 1.2), color: 0x7e786e, pos: [0, (top + bot) / 2, zl] });
        }
        for (const e of [-1, 1]) p.push({ geo: new THREE.BoxGeometry(W * 2 + 0.6, 1.4, 1.2), color: 0x77726a, pos: [0, -0.5, e * (len / 2 - 0.6)] });
      } else {
        // 石拱桥（T034 重做）：整座桥身是一块挤出的石砌体——两孔扁拱 + 河心桥墩（插到河床，迎水面分水尖）+ 两头桥台埋进坡顶；石砌护墙 + 腰线 + 引坡
        const pier = 1.1;
        const s1 = half + 0.6;
        const vs = -D.water + 0.15;
        const vc = -0.2;
        const sh = new THREE.Shape();
        const arch = (from: number, to: number) => {
          const m = (from + to) / 2;
          const a = (from - to) / 2;
          for (let k = 1; k <= 14; k++) {
            const th = (Math.PI * k) / 14;
            sh.lineTo(m + a * Math.cos(th), vs + (vc - vs) * Math.sin(th));
          }
        };
        sh.moveTo(-len / 2, H);
        sh.lineTo(len / 2, H);
        sh.lineTo(len / 2, -0.8);
        sh.lineTo(s1, bed(s1) - 0.6);
        sh.lineTo(s1, vs);
        arch(s1, pier);
        sh.lineTo(pier, bed(0) - 0.6);
        sh.lineTo(-pier, bed(0) - 0.6);
        sh.lineTo(-pier, vs);
        arch(-pier, -s1);
        sh.lineTo(-s1, bed(s1) - 0.6);
        sh.lineTo(-len / 2, -0.8);
        sh.closePath();
        const body = new THREE.ExtrudeGeometry(sh, { depth: W * 2, bevelEnabled: false, curveSegments: 1 });
        body.translate(0, 0, -W);
        body.rotateY(-Math.PI / 2);
        p.push({ geo: body, color: 0x8a847a });
        // 分水尖：河心桥墩两头的三棱柱（尖朝外）
        const ch = vs + 0.3 - (bed(0) - 0.6);
        for (const sd of [-1, 1]) p.push({ geo: new THREE.CylinderGeometry(pier, pier, ch, 3), color: 0x7e786e, pos: [sd * W, (vs + 0.3 + bed(0) - 0.6) / 2, 0], rot: [0, sd * (Math.PI / 2), 0] });
        p.push(...ramps(W * 2 - 0.4, 0.3, 0.12, 0x7e786e));
        const blocks = Math.round(len / 1.2);
        const bl = len / blocks;
        for (let i = 0; i < blocks; i++) {
          for (const sd of [-1, 1]) p.push({ geo: new THREE.BoxGeometry(0.6, 0.8, bl - 0.05), color: i % 2 ? 0x9a9488 : 0x8a847a, pos: [sd * (W - 0.3), 0.9, -len / 2 + bl * (i + 0.5)] });
        }
        for (const sd of [-1, 1]) p.push({ geo: new THREE.BoxGeometry(0.2, 0.18, len), color: 0x9a9488, pos: [sd * (W + 0.05), 0.4, 0] });
      }
      p.push(...this.approach(style, len));
      return p;
    });
    const m = new THREE.Mesh(g, MAT.painted);
    m.castShadow = true;
    m.receiveShadow = true;
    return m;
  }

  private remove(r: River): void {
    r.sheet.removeFromParent();
    r.sheet.geometry.dispose();
    r.sheet.material.dispose();
    r.bridge?.removeFromParent();
    for (let i = this.markers.length - 1; i >= 0; i--) if (this.markers[i].river === r) this.markers.splice(i, 1);
    this.markerDirty = true;
  }

  dispose(): void {
    this.reset();
    this.noise.dispose();
  }
}
