import * as THREE from 'three';
import type { GeoCache } from '../assets/GeoCache';
import { MAT } from '../assets/materials';
import { FX_TIERS, type Quality } from '../render/Post';
import { rockify } from '../assets/ModelKit';
import { armorShard, bentStrut, concreteSlab, scrapLump, splinter, splitPlank, tornSheet } from '../assets/models/shards';

export type ChunkKind = 'metal' | 'wood' | 'concrete' | 'armor' | 'sand';

interface Piece {
  obj: THREE.Object3D;
  /** 池化碎块可复用；部件拷贝用完就丢 */
  pooled: boolean;
  alive: boolean;
  vx: number;
  vy: number;
  vz: number;
  sx: number;
  sz: number;
  life: number;
  ground: number;
  bounced: boolean;
  /** 池化碎块落稳后慢慢躺平：目标俯仰 / 侧倾、已经沉下去多少 */
  tx: number;
  tz: number;
  sink: number;
  /** 落稳后交出去的部件（T194 卡车半截）：先按外形找到能躺稳的姿态翻过去，再交给 onRest，不再沉进地里消失 */
  rest?: { onRest: (obj: THREE.Object3D) => void; t: number; q0: THREE.Quaternion; q1: THREE.Quaternion; y0: number; y1: number };
}

const GRAVITY = 30;
/** 部件落地后翻到躺稳姿态用的秒数 */
const SETTLE = 0.3;

const restCache = new WeakMap<THREE.BufferGeometry, { pitch: number; lift: number }>();

/**
 * 部件（自身坐标原点在底面，如卡车半截）平放在地上会往哪边倒、倒多少：绕自身 x 轴从 0 往重心降低的方向转，转到再转重心反而升高为止
 * （断口那头没轮子，车头半截往后栽、车尾半截往前栽，断口 / 大梁杵在地上）；lift = 这个姿态下原点离地多高。重心按包围盒中心估
 */
function restPose(geo: THREE.BufferGeometry): { pitch: number; lift: number } {
  let r = restCache.get(geo);
  if (r) return r;
  const pos = geo.getAttribute('position');
  if (!geo.boundingBox) geo.computeBoundingBox();
  const box = geo.boundingBox!;
  const cy = (box.min.y + box.max.y) / 2, cz = (box.min.z + box.max.z) / 2;
  const low = (a: number) => {
    const c = Math.cos(a), s = Math.sin(a);
    let m = Infinity;
    for (let i = 0; i < pos.count; i++) m = Math.min(m, pos.getY(i) * c - pos.getZ(i) * s);
    return m;
  };
  const h = (a: number) => cy * Math.cos(a) - cz * Math.sin(a) - low(a);
  const step = 0.01;
  const dir = h(step) < h(-step) ? 1 : -1;
  let a = 0, cur = h(0);
  while (Math.abs(a) < 0.55) {
    const next = h(a + dir * step);
    if (next >= cur - 1e-5) break;
    a += dir * step;
    cur = next;
  }
  r = { pitch: a, lift: -low(a) };
  restCache.set(geo, r);
  return r;
}

const CHUNK_MAT: Record<ChunkKind, THREE.Material> = {
  metal: MAT.debrisMetal,
  wood: MAT.debrisWood,
  concrete: MAT.debrisConcrete,
  armor: MAT.debrisArmor,
  sand: MAT.debrisSand,
};

const range = (n: number, make: (i: number) => THREE.BufferGeometry) => Array.from({ length: n }, (_, i) => make(i));

/**
 * 每种材质的碎片外形（单位尺寸，生成时再按三个方向分别随机缩放）：
 * 混凝土 = 不规则碎块 / 板块 / 带钢筋的块；木头 = 劈开的木板 / 木刺；金属 = 撕开折弯的铁皮 / 扭弯的铁条 / 车轮 / 揉成团的碎铁；装甲 = 崩开的厚板 / 炸裂的铁块。
 * T185：铁皮、装甲板、木板都换成带豁口的不规则轮廓 + 随机折线 + 揉皱，每种多备几份外形轮着用
 */
function shapes(geo: GeoCache): Record<ChunkKind, THREE.BufferGeometry[]> {
  return {
    concrete: [
      geo.get('deb-rock-a', () => rockify(new THREE.IcosahedronGeometry(0.35, 0), 0.35, 11)),
      geo.get('deb-rock-b', () => rockify(new THREE.DodecahedronGeometry(0.32, 0), 0.3, 12)),
      ...range(2, (i) => geo.get(`deb-slab-${i}`, () => concreteSlab(130 + i))),
      geo.merged('deb-rebar', () => [
        { geo: rockify(new THREE.BoxGeometry(0.5, 0.3, 0.4, 2, 1, 2), 0.3, 14), color: 0xffffff },
        { geo: new THREE.CylinderGeometry(0.025, 0.025, 0.9, 4), color: 0x5a3a2a, pos: [0.2, 0.1, 0], rot: [0, 0, 1.1] },
      ]),
    ],
    wood: [
      ...range(3, (i) => geo.get(`deb-plank-${i}`, () => splitPlank(150 + i, 0.9 + i * 0.15))),
      geo.get('deb-beam', () => splitPlank(160, 0.7, 0.11, 0.1)),
      ...range(2, (i) => geo.get(`deb-splinter-${i}`, () => splinter(170 + i))),
    ],
    metal: [
      ...range(5, (i) => geo.get(`deb-sheet-${i}`, () => tornSheet(110 + i, 0.035 + (i % 2) * 0.015, 1 + (i % 3) * 0.25))),
      ...range(2, (i) => geo.get(`deb-strut-${i}`, () => bentStrut(120 + i))),
      geo.get('deb-wheel', () => new THREE.CylinderGeometry(0.3, 0.3, 0.18, 10).rotateZ(Math.PI / 2)),
      ...range(2, (i) => geo.get(`deb-scrap-${i}`, () => scrapLump(125 + i))),
    ],
    armor: [
      ...range(4, (i) => geo.get(`deb-plate-${i}`, () => armorShard(140 + i))),
      ...range(2, (i) => geo.get(`deb-chunk-${i}`, () => scrapLump(145 + i, 0.24))),
    ],
    // 沙袋：压扁的半个袋子 / 一团沙土 / 撕开的麻袋片
    sand: [
      geo.get('deb-bag', () => rockify(new THREE.SphereGeometry(0.4, 6, 4).scale(1.2, 0.45, 0.8), 0.2, 19)),
      geo.get('deb-clod', () => rockify(new THREE.IcosahedronGeometry(0.28, 0), 0.4, 20)),
      geo.get('deb-sack', () => rockify(new THREE.BoxGeometry(0.6, 0.05, 0.45, 2, 1, 2), 0.3, 21)),
    ],
  };
}

/** 飞出去的东西：被炸飞的炮塔、崩落的装甲板、碎块 */
export class Debris {
  /** 新飞出去的碎片投不投影（终极事件里一次炸碎好几辆车时关掉，省一半绘制次数；远处的小碎片影子看不出来） */
  castShadows = true;
  /** 池化碎块最多几块（T245 按画质 FX_TIERS.debris；满了拿剩余寿命最短的那块来用，Infinity = 不限）；低档碎片一律不投影 */
  private cap = Infinity;
  private noShadow = false;
  private pooled = 0;
  /** 地面高度（实体弹坑）：碎片落在坑底 */
  groundAt: (x: number, z: number) => number = () => 0;
  private readonly pieces: Piece[] = [];
  /** 最近一次 chunks() 用到的槽位 */
  private lastIndex = 0;
  private readonly tmpPos = new THREE.Vector3();
  private readonly tmpQuat = new THREE.Quaternion();
  private readonly tmpScale = new THREE.Vector3();

  private readonly shapes: Record<ChunkKind, THREE.BufferGeometry[]>;

  constructor(
    private readonly scene: THREE.Scene,
    private readonly geo: GeoCache,
  ) {
    this.shapes = shapes(geo);
  }

  setQuality(q: Quality): void {
    this.cap = FX_TIERS[q].debris;
    this.noShadow = q === 'low';
  }

  /** 把一个部件的拷贝按它当前的世界姿态抛出去（原件由调用方隐藏）；onRest：落稳翻正后把这个拷贝交出去（不再按 life 消失） */
  launchPart(source: THREE.Object3D, power: number, dirX = 0, dirZ = 0, life = 6, onRest?: (obj: THREE.Object3D) => void): void {
    source.updateWorldMatrix(true, true);
    const clone = source.clone();
    clone.visible = true;
    source.matrixWorld.decompose(this.tmpPos, this.tmpQuat, this.tmpScale);
    clone.position.copy(this.tmpPos);
    clone.quaternion.copy(this.tmpQuat);
    clone.scale.copy(this.tmpScale);
    clone.traverse((o) => {
      if (!(o instanceof THREE.Mesh)) return;
      o.material = MAT.wreck;
      o.castShadow = this.castShadows && !this.noShadow;
    });
    this.scene.add(clone);
    const a = Math.random() * Math.PI * 2;
    // 指定了方向就主要朝那边飞（卡车两截分别往前后飞）
    const directed = dirX !== 0 || dirZ !== 0;
    this.pieces.push({
      obj: clone,
      pooled: false,
      alive: true,
      vx: directed ? dirX * (6 + Math.random() * 3) * power : Math.cos(a) * 3 * power,
      vy: directed ? 6 + power * 4 : 11 + power * 5,
      vz: directed ? dirZ * (6 + Math.random() * 3) * power : Math.sin(a) * 3 * power,
      sx: (Math.random() - 0.5) * (directed ? 4 : 9),
      sz: (Math.random() - 0.5) * (directed ? 4 : 9),
      life: onRest ? Infinity : life,
      ground: 0.5 * this.tmpScale.y,
      bounced: false,
      tx: 0,
      tz: 0,
      sink: 0,
      rest: onRest ? { onRest, t: -1, q0: new THREE.Quaternion(), q1: new THREE.Quaternion(), y0: 0, y1: 0 } : undefined,
    });
  }

  /** 部件落稳：按外形算出躺稳姿态（保留落地时的朝向），SETTLE 秒翻过去 */
  private beginRest(p: Piece): void {
    const o = p.obj, r = p.rest!;
    const mesh = o as THREE.Mesh;
    const pose = mesh.geometry ? restPose(mesh.geometry) : { pitch: 0, lift: 0 };
    const yaw = new THREE.Euler().setFromQuaternion(o.quaternion, 'YXZ').y;
    r.q0.copy(o.quaternion);
    r.q1.setFromEuler(new THREE.Euler(pose.pitch, yaw, (Math.random() - 0.5) * 0.06, 'YXZ'));
    r.y0 = o.position.y;
    r.y1 = this.groundAt(o.position.x, o.position.z) + pose.lift * o.scale.y;
    r.t = 0;
  }

  /** size：碎块整体缩放（摩托这种小车的碎铁 < 1）；shadow：投不投影（小碎铁的影子看不出来，关掉省一半绘制） */
  chunks(x: number, y: number, z: number, count: number, kind: ChunkKind, power = 1, size = 1, shadow = this.castShadows): void {
    for (let i = 0; i < count; i++) {
      let p = this.pieces.find((item) => item.pooled && !item.alive);
      if (!p && this.pooled >= this.cap) {
        for (const item of this.pieces) if (item.pooled && (!p || item.life < p.life)) p = item;
      }
      if (!p) {
        this.pooled++;
        const mesh = new THREE.Mesh(this.geo.box(0.5, 0.5, 0.5), CHUNK_MAT[kind]);
        mesh.castShadow = true;
        this.scene.add(mesh);
        p = { obj: mesh, pooled: true, alive: false, vx: 0, vy: 0, vz: 0, sx: 0, sz: 0, life: 0, ground: 0.2, bounced: false, tx: 0, tz: 0, sink: 0 };
        this.pieces.push(p);
      }
      this.lastIndex = this.pieces.indexOf(p);
      const mesh = p.obj as THREE.Mesh;
      mesh.material = CHUNK_MAT[kind];
      mesh.castShadow = shadow && !this.noShadow;
      const list = this.shapes[kind];
      mesh.geometry = list[Math.floor(Math.random() * list.length)];
      // 大小差异拉开：少数大块 + 一堆小碎片；长宽厚各自随机，同一种外形也不会一模一样
      const s = (Math.random() < 0.2 ? 1 + Math.random() * 0.5 : 0.3 + Math.random() * 0.6) * size;
      mesh.scale.set(s * (0.6 + Math.random() * 0.8), s * (0.7 + Math.random() * 0.6), s * (0.6 + Math.random() * 0.8));
      mesh.position.set(x + (Math.random() - 0.5) * 1.5, y, z + (Math.random() - 0.5) * 1.5);
      mesh.rotation.set(Math.random() * Math.PI * 2, Math.random() * Math.PI * 2, Math.random() * Math.PI * 2);
      mesh.visible = true;
      const a = Math.random() * Math.PI * 2;
      const sp = (3 + Math.random() * 6) * power;
      p.alive = true;
      p.vx = Math.cos(a) * sp;
      p.vz = Math.sin(a) * sp;
      p.vy = (6 + Math.random() * 8) * power;
      p.sx = (Math.random() - 0.5) * 14;
      p.sz = (Math.random() - 0.5) * 14;
      p.life = 1.2 + Math.random() * 0.6;
      p.ground = 0.15 * s;
      p.bounced = false;
      p.sink = 0;
    }
  }

  /**
   * 车辆被炸碎：装甲板和零件朝爆炸反方向四散，落地后停留一会儿。
   * (dirX, dirZ) 为从爆心指向车辆的方向。
   */
  shatter(x: number, y: number, z: number, size: number, dirX: number, dirZ: number, power = 1): void {
    const n = Math.round(8 + size * 3);
    // T185：平时再多崩一把小碎铁（不投影）；终极事件里一次炸碎好几辆车时（castShadows 关）不加
    const bits = this.castShadows ? Math.round(4 + size * 4) : 0;
    for (let i = 0; i < n + bits; i++) {
      const bit = i >= n;
      const plate = !bit && i % 3 !== 2;
      this.chunks(x, y, z, 1, bit || i % 4 === 3 ? 'metal' : 'armor', power * (bit ? 1.5 : 1.3), 1, bit ? false : this.castShadows);
      const p = this.pieces[this.lastIndex];
      const mesh = p.obj as THREE.Mesh;
      // 大小、长宽比都拉开：大板少、碎片多
      const s = size * (bit ? 0.3 + Math.random() * 0.4 : Math.random() < 0.3 ? 1.2 + Math.random() * 0.5 : 0.55 + Math.random() * 0.6);
      if (plate) mesh.scale.set(s * (0.9 + Math.random() * 1.0), s * (0.8 + Math.random() * 0.5), s * (0.6 + Math.random() * 0.9));
      else mesh.scale.set(s * (0.8 + Math.random() * 0.8), s * (0.8 + Math.random() * 0.8), s * (0.8 + Math.random() * 0.8));
      p.ground = plate ? 0.06 * s : 0.2 * s;
      p.vx += dirX * (6 + Math.random() * 6) * power;
      p.vz += dirZ * (6 + Math.random() * 6) * power;
      p.vy = (8 + Math.random() * 10) * power;
      p.life = bit ? 2 + Math.random() * 1.5 : 3 + Math.random() * 1.5;
    }
  }

  /** 正在飞 / 躺着的碎片数（诊断） */
  get live(): number {
    let n = 0;
    for (const p of this.pieces) if (p.alive) n++;
    return n;
  }

  update(delta: number): void {
    for (let i = this.pieces.length - 1; i >= 0; i--) {
      const p = this.pieces[i];
      if (!p.alive) continue;
      p.life -= delta;
      const o = p.obj;
      if (p.life <= 0) {
        p.alive = false;
        o.visible = false;
        if (!p.pooled) {
          o.removeFromParent();
          this.pieces.splice(i, 1);
        }
        continue;
      }
      const r = p.rest;
      if (r && r.t >= 0) {
        r.t = Math.min(1, r.t + delta / SETTLE);
        const k = r.t * r.t * (3 - 2 * r.t);
        o.quaternion.slerpQuaternions(r.q0, r.q1, k);
        o.position.y = r.y0 + (r.y1 - r.y0) * k;
        if (r.t >= 1) {
          this.pieces.splice(i, 1);
          r.onRest(o);
        }
        continue;
      }
      const resting = p.bounced && p.vy === 0;
      if (!resting) {
        p.vy -= GRAVITY * delta;
        o.position.x += p.vx * delta;
        o.position.y += p.vy * delta;
        o.position.z += p.vz * delta;
        o.rotation.x += p.sx * delta;
        o.rotation.z += p.sz * delta;
        const floor = p.ground + this.groundAt(o.position.x, o.position.z);
        if (o.position.y <= floor && p.vy < 0) {
          o.position.y = floor;
          if (p.bounced || Math.abs(p.vy) < 4) {
            p.vx = p.vz = p.vy = 0;
            p.bounced = true;
            // 池化碎块落稳后朝最近的平躺姿态倒下去（留一点歪斜），不再按飞行时的随机角度立着 / 插进地里
            p.tx = Math.round(o.rotation.x / Math.PI) * Math.PI + (Math.random() - 0.5) * 0.3;
            p.tz = Math.round(o.rotation.z / Math.PI) * Math.PI + (Math.random() - 0.5) * 0.3;
            if (p.rest) this.beginRest(p);
          } else {
            p.vy *= -0.3;
            p.vx *= 0.5;
            p.vz *= 0.5;
            p.sx *= 0.4;
            p.sz *= 0.4;
            p.bounced = true;
          }
        }
      }
      if (resting && p.pooled) {
        const k = Math.min(1, delta * 10);
        o.rotation.x += (p.tx - o.rotation.x) * k;
        o.rotation.z += (p.tz - o.rotation.z) * k;
        const mesh = o as THREE.Mesh;
        const box = mesh.geometry.boundingBox ?? (mesh.geometry.computeBoundingBox(), mesh.geometry.boundingBox!);
        // 躺平后最低点贴地：正面朝上看包围盒底，翻过来看顶
        const up = Math.cos(o.rotation.x) * Math.cos(o.rotation.z) >= 0;
        const rest = this.groundAt(o.position.x, o.position.z) + (up ? -box.min.y : box.max.y) * o.scale.y - p.sink;
        o.position.y += (rest - o.position.y) * k;
      }
      // 最后一小段时间沉进地里消失
      if (p.life < 0.6) {
        const d = delta * (p.pooled ? 0.6 : 1.5);
        o.position.y -= d;
        p.sink += d;
      }
    }
  }

  clear(): void {
    for (let i = this.pieces.length - 1; i >= 0; i--) {
      const p = this.pieces[i];
      p.alive = false;
      p.obj.visible = false;
      if (!p.pooled) {
        p.obj.removeFromParent();
        this.pieces.splice(i, 1);
      }
    }
  }
}
