import type { Card } from '../weapons/Arsenal';
import { icon } from './icons';
import { PICK_LOCK } from './cardPick';
import { RARE_EDGE, RARE_FACE } from './rareFx';
import { cssHex } from '../render/markColors';
import type { Overlay, Panel } from './canvas/Overlay';
import { armorPanel, armorMeter } from './canvas/widgets';
import { font, text, ellipsize, wrap, icon as paintIcon } from './canvas/paint';

/**
 * 联机选卡条（T275）：战场不停，不盖自己的车。竖屏横排在槽位下面，横屏竖排在左边槽位下面。
 * 可以收成一个小牌，倒计时到 0 由房主自动选第一张。两套界面各自摆放。
 */
export interface PickDockView {
  /** 这一组卡的编号；换了编号才重新计防误触、自动展开 */
  id: number;
  title: string;
  cards: Card[];
  /** 剩余秒数 */
  left: number;
  total: number;
}

export const DOCK_SUB = '到时自动选第一张';
/** 选卡条上沿离安全区顶多少：让出耐久块和三行槽位 */
const DOCK_TOP = 170;
const SLOP = 12;

const kindEdge = (c: Card): string => c.rarity === 'rare' ? cssHex(RARE_EDGE) : c.kind === 'super' ? '#b48ad8' : c.fixed ? '#d9b36a' : '#6f7d68';
const secs = (v: PickDockView): string => `${Math.max(0, Math.ceil(v.left))}秒`;

export class DomPickDock {
  private el: HTMLElement | null = null;
  private view: PickDockView | null = null;
  private shownAt = 0;
  private picked = -1;
  private folded = false;
  private press: { id: number; el: Element | null; x: number; y: number; ok: boolean } | null = null;
  constructor(private readonly pick: (card: Card) => void) {}

  set(v: PickDockView | null): void {
    if (v && v.id === this.picked) v = null;
    if (!v) { this.view = null; if (this.el) this.el.hidden = true; return; }
    const el = this.build();
    const fresh = this.view?.id !== v.id;
    this.view = v;
    if (fresh) {
      this.folded = false;
      this.shownAt = performance.now() / 1000;
      el.querySelector('.pd-title')!.textContent = v.title;
      el.querySelector('.pd-cards')!.innerHTML = v.cards.map((c, i) => `<button type="button" class="pd-card r-${c.rarity} k-${c.kind}" data-i="${i}" style="--edge:${kindEdge(c)}"><span class="pd-head">${icon(c.icon)}<b>${c.name}</b></span><small>${c.lines[0] ?? ''}</small></button>`).join('');
    }
    el.hidden = false;
    el.classList.toggle('fold', this.folded);
    for (const s of el.querySelectorAll('.pd-left')) s.textContent = secs(v);
    (el.querySelector('.pd-bar i') as HTMLElement).style.width = `${Math.max(0, Math.min(1, v.left / v.total)) * 100}%`;
  }

  private build(): HTMLElement {
    if (this.el) return this.el;
    const el = this.el = document.createElement('section');
    el.id = 'pick-dock';
    el.setAttribute('aria-label', '选卡');
    el.innerHTML = `<div class="pd-open"><header><b class="pd-title"></b><span class="pd-sub">${DOCK_SUB}</span><span class="pd-left"></span><button type="button" class="pd-fold">收起</button></header><div class="pd-bar"><i></i></div><div class="pd-cards"></div></div><button type="button" class="pd-pill" aria-label="展开选卡">改装 <span class="pd-left"></span></button>`;
    el.addEventListener('pointerdown', e => {
      const t = (e.target as HTMLElement).closest('.pd-card');
      this.press = { id: e.pointerId, el: t, x: e.clientX, y: e.clientY, ok: performance.now() / 1000 - this.shownAt >= PICK_LOCK };
    });
    el.addEventListener('pointermove', e => {
      const p = this.press;
      if (p && p.id === e.pointerId && Math.hypot(e.clientX - p.x, e.clientY - p.y) > SLOP) p.ok = false;
    });
    el.addEventListener('click', e => {
      const t = e.target as HTMLElement;
      if (t.closest('.pd-fold')) { this.folded = true; el.classList.add('fold'); return; }
      if (t.closest('.pd-pill')) { this.folded = false; el.classList.remove('fold'); return; }
      const card = t.closest<HTMLElement>('.pd-card'), p = this.press, v = this.view;
      this.press = null;
      if (!card || !v) return;
      // 防误触：弹出 0.35 秒内按下的、按下和松手不在同一张卡上的、中途滑开的都不算
      const ok = p ? p.ok && p.el === card : e.detail === 0 && performance.now() / 1000 - this.shownAt >= PICK_LOCK;
      const c = v.cards[Number(card.dataset.i)];
      if (!ok || !c) return;
      this.picked = v.id;
      this.set(null);
      this.pick(c);
    });
    document.body.append(el);
    return el;
  }
}

/** 画布版：只用真机 2D 接口，计时看 Overlay.now。 */
export class CanvasPickDock {
  private view: PickDockView | null = null;
  private shownAt = 0;
  private picked = -1;
  private folded = false;
  private shown = '';
  private readonly panel: Panel;
  constructor(private readonly ov: Overlay, private readonly pick: (card: Card) => void) {
    this.panel = ov.panel('pick-dock', 7, (g, w, h) => this.paint(g, w, h));
    ov.onFrame(() => this.frame());
  }

  set(v: PickDockView | null): void {
    if (v && v.id === this.picked) v = null;
    if (v && this.view?.id !== v.id) { this.folded = false; this.shownAt = this.ov.now; }
    this.view = v;
    this.panel.visible = !!v;
    const key = v ? `${v.id}|${secs(v)}|${this.folded}|${Math.round(v.left / v.total * 50)}` : '';
    if (key !== this.shown) { this.shown = key; this.panel.dirty = true; }
  }

  private get side(): boolean { return this.ov.W > this.ov.H; }
  private rect(): { x: number; y: number; w: number; h: number } {
    const { W, insets } = this.ov, y = insets.top + DOCK_TOP;
    if (this.folded) return { x: insets.left + 10, y, w: 104, h: 44 };
    if (this.side) return { x: insets.left + 10, y, w: 240, h: 36 + 3 * 50 };
    const w = Math.min(W - insets.left - insets.right - 20, 520);
    return { x: insets.left + 10 + (W - insets.left - insets.right - 20 - w) / 2, y, w, h: 98 };
  }
  /** 第 i 张卡在面板里的位置 */
  private cell(i: number, w: number): { x: number; y: number; w: number; h: number } {
    if (this.side) return { x: 8, y: 36 + i * 50, w: w - 16, h: 46 };
    const cw = (w - 16 - 12) / 3;
    return { x: 8 + i * (cw + 6), y: 36, w: cw, h: 56 };
  }

  private frame(): void {
    const v = this.view;
    if (!v) return;
    const r = this.rect();
    this.panel.place(r.x, r.y, r.w, r.h);
    this.ov.region({ id: 'pick-dock-block', z: 7, ...r, panel: this.panel });
    if (this.folded) {
      this.ov.region({ id: 'pick-dock-pill', z: 8, ...r, panel: this.panel, tap: () => { this.folded = false; this.set(this.view); } });
      return;
    }
    this.ov.region({ id: 'pick-dock-fold', z: 8, x: r.x + r.w - 58, y: r.y, w: 58, h: 34, panel: this.panel, tap: () => { this.folded = true; this.set(this.view); } });
    v.cards.forEach((c, i) => { const k = this.cell(i, r.w); this.ov.region({
      id: `pick-dock-${i}`, z: 8, x: r.x + k.x, y: r.y + k.y, w: k.w, h: k.h, panel: this.panel,
      ready: () => this.ov.now - this.shownAt >= PICK_LOCK,
      tap: () => {
        if (this.view?.id !== v.id) return;
        this.picked = v.id;
        this.set(null);
        this.pick(c);
      },
    }); });
  }

  private paint(g: CanvasRenderingContext2D, w: number, h: number): void {
    const v = this.view;
    if (!v) return;
    armorPanel(g, 0, 0, w, h, '#18241fee', '#879b86', 6);
    if (this.folded) {
      g.font = font(13, 700);
      text(g, `改装 ${secs(v)}`, w / 2, h / 2, '#f0d995', 'center');
      return;
    }
    g.font = font(13, 700);
    const tw = text(g, v.title, 10, 14, '#f0d995');
    g.font = font(10);
    if (!this.side) text(g, DOCK_SUB, 18 + tw, 14, '#aeb8a3');
    g.font = font(12, 700);
    text(g, secs(v), w - 64, 14, '#f0d995', 'right');
    armorPanel(g, w - 54, 3, 46, 22, '#2b3a30', '#687962', 4);
    g.font = font(11);
    text(g, '收起', w - 31, 14, '#e0e4cc', 'center');
    armorMeter(g, 10, 28, w - 20, 3, v.left / v.total, '#d9b36a');
    v.cards.forEach((c, i) => {
      const { x, y, w: cw, h: ch } = this.cell(i, w), down = this.ov.pressed === `pick-dock-${i}`;
      armorPanel(g, x, y, cw, ch, c.rarity === 'rare' ? cssHex(RARE_FACE[down ? 0 : 1]) : down ? '#33463a' : '#22302a', kindEdge(c), 5);
      paintIcon(g, c.icon, x + 6, y + 6, 16, '#e7ce91');
      g.font = font(12, 700);
      text(g, ellipsize(g, c.name, cw - 30), x + 26, y + 14, '#eef0e0');
      g.font = font(10);
      wrap(g, c.lines[0] ?? '', cw - 12).slice(0, ch > 50 ? 2 : 1).forEach((line, k) => text(g, ellipsize(g, line, cw - 12), x + 6, y + 34 + k * 14, '#c4cbb6'));
    });
  }
}
