import * as THREE from 'three';
import type { PartSpec } from '../GeoCache';
import { frustum, rect, rockify } from '../ModelKit';
import { SURF as S } from '../sceneryMaterial';
import { SCN_TESS } from '../../world/sceneryDetail';
import { CRUSH_PART as C } from './crush';
import { houseStyle, houseTrim, styledHouseParts, type HouseLook } from './houseStyles';

/**
 * T184 加细景物（建筑 / 树木 / 草丛，5 倍档约为原模型五倍面数）。
 * 外轮廓、占地、断口高度、原点都按原模型摆：碰撞、挡弹、倒伏 / 切断 / 拔根的位置不变，只换外形细节和表面类别。
 * 分段数按 SCN_TESS 缩放（?scnx=N → N/5），同一套形体找性能拐点。
 */
const sg = (n: number, min = 3) => Math.max(min, Math.round(n * SCN_TESS));
const icoDetail = (d: number) => Math.max(0, Math.round((d + 1) * Math.sqrt(SCN_TESS)) - 1);
const r = (a: number, b: number, s: number) => {
  const h = Math.sin(s * 91.7) * 43758.5453;
  return a + (h - Math.floor(h)) * (b - a);
};
const CUT = 1.0;

type V3 = [number, number, number];

// ------------------------------------------------------------------ T195 写实枝叶（制作人「灌木丛和树木的多边形面数还是太低，感觉可以再写实很多」）
// 原来一层层星形圆锥 / 几团多面球 → 针叶树一轮轮下垂的枝片、阔叶树和灌木几十团带凹凸的叶簇 + 外沿零碎的小叶片，
// 法线朝树冠中心往外掰（叶团整体受光、背光面柔和，不再一块块平面反光）；外轮廓仍在原来的范围内

const _v = new THREE.Vector3();
const _n = new THREE.Vector3();
const _m = new THREE.Matrix4();
const _q = new THREE.Quaternion();
const _e = new THREE.Euler();

/** 叶团：多面球按位置散列起伏（同一位置同样起伏，不裂缝），套上变换后法线按 center 往外掰 bend 成 */
function clumpGeo(radius: number, detail: number, amount: number, seed: number, pos: V3, scale: V3, rot: V3, center: V3 | null, bend = 0.65): THREE.BufferGeometry {
  const g = new THREE.IcosahedronGeometry(radius, Math.max(0, detail));
  const p = g.getAttribute('position') as THREE.BufferAttribute;
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i), y = p.getY(i), z = p.getZ(i);
    const k = 1 + (r(0, 1, Math.round(x * 173 + y * 311 + z * 97) + seed) - 0.5) * amount;
    p.setXYZ(i, x * k, y * k, z * k);
  }
  g.computeVertexNormals();
  g.applyMatrix4(_m.compose(_v.set(...pos), _q.setFromEuler(_e.set(...rot)), _n.set(...scale)));
  if (center) radialNormals(g, center, bend);
  return g;
}

/** 法线往「离 center 的方向」掰 k 成（叶团整体受光） */
function radialNormals(g: THREE.BufferGeometry, center: V3, k: number, yScale = 1): void {
  const p = g.getAttribute('position') as THREE.BufferAttribute;
  const n = g.getAttribute('normal') as THREE.BufferAttribute;
  for (let i = 0; i < p.count; i++) {
    _v.set(p.getX(i) - center[0], (p.getY(i) - center[1]) * yScale, p.getZ(i) - center[2]).normalize();
    _n.set(n.getX(i), n.getY(i), n.getZ(i)).lerp(_v, k).normalize();
    n.setXYZ(i, _n.x, _n.y, _n.z);
  }
}

/**
 * 阔叶树冠 / 灌木：椭球里撒 count 团叶簇（越靠外越多），下半、里面的颜色深；外沿再撒 bits 片小叶片（四面体）打碎轮廓。
 * 叶簇按 SCN_TESS 调细分
 */
function foliage(center: V3, rad: V3, count: number, size: [number, number], seed: number, colors: number[], bits = 0, flatBottom = 0.35): PartSpec[] {
  const T = SCN_TESS;
  const out: PartSpec[] = [];
  const det = T >= 0.6 ? 1 : 0;
  const n = Math.max(6, Math.round(count * Math.min(1.6, Math.max(0.4, T))));
  for (let i = 0; i < n; i++) {
    const s = seed + i * 13;
    const u = r(-1, 1, s), a = r(0, Math.PI * 2, s + 1), rr = Math.pow(r(0.15, 1, s + 2), 0.45);
    const sq = Math.sqrt(1 - u * u);
    let ly = u;
    if (ly < -flatBottom) ly = -flatBottom - (ly + flatBottom) * 0.35;
    const x = Math.cos(a) * sq * rr, z = Math.sin(a) * sq * rr, y = ly * rr;
    const k = r(size[0], size[1], s + 3) * (0.75 + 0.35 * rr);
    const shade = (y + 1) * 0.5 * 0.6 + rr * 0.4;
    const color = colors[Math.min(colors.length - 1, Math.floor(shade * colors.length * 0.999 + r(-0.6, 0.6, s + 4)))] ?? colors[0];
    const pos: V3 = [center[0] + x * rad[0], center[1] + y * rad[1], center[2] + z * rad[2]];
    out.push({ geo: clumpGeo(k, rr < 0.62 ? 0 : det, 0.38, s, pos, [1, r(0.62, 0.85, s + 5), 1], [r(0, 3, s + 6), r(0, 3, s + 7), 0], center, 0.82), color, surf: S.leaf });
  }
  const nb = Math.round(bits * Math.min(1.6, Math.max(0.3, T)));
  for (let i = 0; i < nb; i++) {
    const s = seed + 5000 + i * 7;
    const u = r(-0.55, 1, s), a = r(0, Math.PI * 2, s + 1), sq = Math.sqrt(1 - u * u), rr = r(0.92, 1.12, s + 2);
    const pos: V3 = [center[0] + Math.cos(a) * sq * rad[0] * rr, center[1] + u * rad[1] * rr, center[2] + Math.sin(a) * sq * rad[2] * rr];
    const g = new THREE.TetrahedronGeometry(r(0.08, 0.15, s + 3));
    g.applyMatrix4(_m.compose(_v.set(...pos), _q.setFromEuler(_e.set(r(0, 3, s + 4), r(0, 3, s + 5), r(0, 3, s + 6))), _n.set(1, 0.35, 1.6)));
    radialNormals(g, center, 0.8);
    out.push({ geo: g, color: colors[Math.min(colors.length - 1, 1 + (i % (colors.length - 1)))], surf: S.leaf });
  }
  return out;
}

/** 一根针叶枝片：沿 +x 伸出 len 米的薄枝片，梢头往下垂 droop 米、两侧边沿往下弯，边上一串锯齿（一簇簇针叶），表面细碎起伏 */
function boughGeo(len: number, wid: number, thick: number, droop: number, seed: number): THREE.BufferGeometry {
  const g = new THREE.SphereGeometry(1, sg(10, 6), sg(3, 3));
  const p = g.getAttribute('position') as THREE.BufferAttribute;
  const ph = r(0, 6, seed);
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i), y = p.getY(i), z = p.getZ(i);
    const t = (x + 1) / 2;
    const saw = 0.62 + 0.38 * Math.abs(Math.sin(t * Math.PI * 5.5 + ph));
    const w = Math.sin(Math.PI * Math.min(1, t * 1.1 + 0.04)) * (0.5 + 0.5 * t) * saw;
    const jag = 1 + (r(0, 1, Math.round(x * 211 + y * 97 + z * 157) + seed) - 0.5) * 0.35;
    const zz = z * wid * w * jag;
    p.setXYZ(i, t * len, y * thick * (0.45 + 0.55 * (1 - t)) * jag - droop * t * t - Math.abs(zz) * 0.38, zz);
  }
  g.computeVertexNormals();
  return g;
}

/**
 * 针叶树冠：y0 → y1 一轮一轮的枝片（每轮 n 片、按黄金角错开），半径按 radius(t) 收、下面几轮下垂多上面翘起；
 * 树顶一根细尖。lift = 整体上下挪（断下来的树冠）
 */
function conifer(y0: number, y1: number, radius: (t: number) => number, whorls: number, per: number, seed: number, colors: number[], lift = 0, thick = 0.16): PartSpec[] {
  const T = SCN_TESS;
  const out: PartSpec[] = [];
  const nw = Math.max(5, Math.round(whorls * Math.min(1.5, Math.max(0.5, T))));
  for (let w = 0; w < nw; w++) {
    const t = w / (nw - 1);
    const y = y0 + (y1 - y0) * t;
    const R = radius(t);
    const n = Math.max(4, Math.round(per * (1 - t * 0.45)));
    for (let k = 0; k < n; k++) {
      const s = seed + w * 31 + k * 7;
      const a = k * (Math.PI * 2 / n) + w * 2.39996 + r(-0.25, 0.25, s);
      const len = R * r(0.82, 1.08, s + 1);
      const tilt = (t - 0.55) * 0.5 + r(-0.12, 0.12, s + 2);
      const g = boughGeo(len, Math.max(0.24, len * 0.5), thick * (0.8 + 0.4 * (1 - t)), len * (0.34 - 0.2 * t), s);
      g.applyMatrix4(_m.compose(_v.set(Math.cos(a) * 0.12, y + lift + r(-0.1, 0.1, s + 3), -Math.sin(a) * 0.12), _q.setFromEuler(_e.set(0, a, tilt, 'YXZ')), _n.set(1, 1, 1)));
      radialNormals(g, [0, y + lift - R * 0.6, 0], 0.4, 0.6);
      const ci = Math.min(colors.length - 1, Math.floor((t * 0.7 + r(0, 0.45, s + 4)) * colors.length));
      out.push({ geo: g, color: colors[ci], surf: S.leaf });
    }
  }
  return out;
}

/** 树干：竖向树皮棱，粗细不变 */
function trunkGeo(rTop: number, rBot: number, h: number, seed: number, ridges = 7): THREE.BufferGeometry {
  const g = new THREE.CylinderGeometry(rTop, rBot, h, sg(10), sg(2, 1));
  const p = g.getAttribute('position') as THREE.BufferAttribute;
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i), z = p.getZ(i);
    if (Math.hypot(x, z) < 1e-5) continue;
    const k = 1 + 0.07 * Math.cos(Math.atan2(z, x) * ridges + seed);
    p.setX(i, x * k); p.setZ(i, z * k);
  }
  g.computeVertexNormals();
  return g;
}

/** 根部伸出去的几条根 */
function roots(radius: number, n: number, seed: number, color = 0x463626, y = 0.08): PartSpec[] {
  return Array.from({ length: n }, (_, i): PartSpec => {
    const a = (i / n) * Math.PI * 2 + r(0, 0.8, seed + i);
    return { geo: new THREE.CylinderGeometry(0.04, 0.12, 0.9, sg(5), 1, true), color, surf: S.bark,
      pos: [Math.cos(a) * radius, y, Math.sin(a) * radius], rot: [Math.sin(a) * 1.3, 0, -Math.cos(a) * 1.3 + r(-0.2, 0.2, seed + i + 5)] };
  });
}

/** 断口的木刺 */
function splinters(y: number, rad: number, seed: number, color = 0x9a7e56, n = 7): PartSpec[] {
  return Array.from({ length: n }, (_, i): PartSpec => {
    const a = (i / n) * Math.PI * 2 + r(0, 1, seed + i);
    return { geo: new THREE.BoxGeometry(0.08, r(0.16, 0.44, seed + i + 9), 0.06), color, surf: S.wood,
      pos: [Math.cos(a) * rad * 0.7, y, Math.sin(a) * rad * 0.7], rot: [r(-0.35, 0.35, seed + i + 3), a, r(-0.35, 0.35, seed + i + 5)] };
  });
}

/** 光秃的枝杈（秃干 / 阔叶树骨架） */
function twigs(n: number, y0: number, dy: number, len: number, seed: number, color: number): PartSpec[] {
  return Array.from({ length: n }, (_, i): PartSpec => {
    const a = i * 2.39996 + seed, l = len * r(0.6, 1.2, seed + i * 3) * (1 - i * 0.04);
    return { geo: new THREE.CylinderGeometry(0.018, 0.05, l, sg(5), 1, true), color, surf: S.bark,
      pos: [Math.cos(a) * l * 0.45, y0 + i * dy + 0.15, Math.sin(a) * l * 0.45], rot: [Math.sin(a) * 1.05, 0, -Math.cos(a) * 1.05] };
  });
}

// ------------------------------------------------------------------ 默认松树（原 sceneryGeo('pine') 及四个破坏变体）

export type PineState = 'pine' | 'pineStump' | 'pineTop' | 'pineRoot' | 'pineBald';

export function richPine(state: PineState): PartSpec[] {
  const bark = 0x4a3a2a;
  if (state === 'pineStump') return [
    { geo: trunkGeo(0.27, 0.34, CUT, 3), color: bark, pos: [0, CUT / 2, 0], surf: S.bark },
    { geo: new THREE.CylinderGeometry(0.255, 0.255, 0.04, sg(10)), color: 0x9a7e56, pos: [0, CUT, 0], surf: S.wood },
    ...splinters(CUT + 0.12, 0.27, 3),
    ...roots(0.35, 4, 11),
  ];
  if (state === 'pineBald') return [
    { geo: trunkGeo(0.2, 0.32, 2.4, 2), color: 0x5a4a3a, pos: [0, 1.2, 0], surf: S.bark },
    { geo: trunkGeo(0.05, 0.2, 4.2, 4), color: 0x544434, pos: [0, 4.5, 0], surf: S.bark },
    ...twigs(14, 2.5, 0.3, 1.25, 41, 0x4e3e30),
    ...roots(0.34, 4, 19),
  ];
  const lift = state === 'pineTop' ? -CUT : 0;
  const parts: PartSpec[] = state === 'pineTop'
    ? [{ geo: trunkGeo(0.2, 0.265, 1.4, 2), color: bark, pos: [0, 0.7, 0], surf: S.bark }, ...splinters(-0.1, 0.26, 7)]
    : [{ geo: trunkGeo(0.2, 0.32, 2.4, 2), color: bark, pos: [0, 1.2, 0], surf: S.bark }, ...roots(0.34, 4, 23)];
  // 树冠：原来五层星形圆锥（底层半径 2.2、顶到 7.9 米）→ 15 轮下垂枝片 + 树顶细尖，外轮廓不变
  parts.push({ geo: trunkGeo(0.05, 0.2, 5.4, 4), color: bark, pos: [0, 4.9 + lift, 0], surf: S.bark });
  parts.push(...conifer(2.05, 7.35, (t) => 0.35 + 1.95 * Math.pow(1 - t, 1.05), 13, 9, 7, [0x24331f, 0x2b3b24, 0x31442a, 0x384d2f, 0x41583a], lift));
  parts.push({ geo: new THREE.ConeGeometry(0.16, 0.9, sg(7)), color: 0x3e5634, pos: [0, 7.55 + lift, 0], surf: S.leaf });
  if (state === 'pineRoot') {
    parts.push({ geo: rockify(new THREE.DodecahedronGeometry(1.15, icoDetail(0)), 0.35, 5), color: 0x4e3e2c, pos: [0, -0.05, 0], scale: [1, 0.38, 1], surf: S.stone });
    parts.push(...roots(0.7, 6, 2, 0x3e3024, -0.25));
  }
  return parts;
}

// ------------------------------------------------------------------ 云杉 / 栎树 / 白桦（sceneryLooks 同一套状态）

export function richLookTree(look: 'spruce' | 'oak' | 'birch', state: string): PartSpec[] {
  const birch = look === 'birch', spruce = look === 'spruce';
  const bark = birch ? 0xb9b6a4 : spruce ? 0x514432 : 0x63513b;
  const stump = state === 'pineStump', top = state === 'pineTop', bare = state === 'pineBald';
  const parts: PartSpec[] = [
    { geo: trunkGeo(stump ? .27 : .14, .32, stump ? 1 : 5.9, 5), color: bark, pos: [0, stump ? .5 : 2.95, 0], surf: S.bark },
  ];
  if (stump) {
    parts.push({ geo: new THREE.CylinderGeometry(.27, .27, .035, sg(10)), color: 0xa18a63, pos: [0, 1, 0], surf: S.wood });
    parts.push(...splinters(1.1, .27, 13, 0xa18a63), ...roots(.36, 4, 29, bark));
  } else {
    for (let i = 0; i < (spruce ? 4 : 5); i++) {
      const a = i * 2.4 + .4, y = 2.2 + i * .6;
      parts.push({ geo: new THREE.CylinderGeometry(.045, .12, 1.6, sg(6), 1, true), color: bark, surf: S.bark,
        pos: [Math.cos(a) * .52, y + .45, Math.sin(a) * .52], rot: [Math.sin(a) * .9, 0, -Math.cos(a) * .9] });
    }
    if (!spruce) parts.push(...twigs(bare ? 10 : 6, 3.4, .32, 1.1, 61, bark));
    if (birch) for (let i = top ? 1 : 0; i < 6; i++) {
      parts.push({ geo: new THREE.BoxGeometry(.3, .07, .34), color: 0x655e4d, pos: [i % 2 ? .03 : -.03, .7 + i * .72, .02] });
      parts.push({ geo: new THREE.BoxGeometry(.34, .045, .26), color: 0x4f493c, pos: [0, 1.05 + i * .72, 0], rot: [0, 1.3 + i, 0] });
    }
    if (!bare) {
      // T195：云杉 = 14 轮下垂枝片；栎树 / 白桦 = 几十团叶簇 + 外沿小叶片（外轮廓在原来几团叶球的范围内）
      if (spruce) {
        parts.push(...conifer(1.75, 7.15, (t) => 0.3 + 1.62 * Math.pow(1 - t, 1.1), 12, 9, 53, [0x2c3f2d, 0x324832, 0x3a5139, 0x425a40, 0x496246], 0, 0.15));
        parts.push({ geo: new THREE.ConeGeometry(0.14, 0.8, sg(7)), color: 0x496246, pos: [0, 7.45, 0], surf: S.leaf });
      } else if (birch) parts.push(...foliage([0, 4.9, 0], [1.5, 2.05, 1.4], 48, [0.3, 0.5], 71, [0x58663f, 0x63714a, 0x6d7a4b, 0x76844f], 110, 0.6));
      else parts.push(...foliage([0, 4.85, 0], [2.25, 1.7, 2.05], 58, [0.42, 0.7], 73, [0x3d4f2d, 0x485b35, 0x53663c, 0x5f7240], 130, 0.5));
    }
  }
  if (state === 'pineRoot') {
    parts.push({ geo: rockify(new THREE.IcosahedronGeometry(.85, icoDetail(1)), .25, 81), color: 0x64573b, pos: [0, .05, 0], scale: [1.4, .45, 1.1], surf: S.stone });
    parts.push(...roots(.6, 5, 37, bark, -.15));
  }
  if (top) {
    parts[0].geo.dispose();
    parts[0] = { geo: trunkGeo(.14, .27, 4.9, 5), color: bark, pos: [0, 3.45, 0], surf: S.bark };
    for (const p of parts) if (p.pos) p.pos[1] -= 1; else p.pos = [0, -1, 0];
    parts.push(...splinters(-.1, .26, 17, 0xa18a63));
  }
  return parts;
}

// ------------------------------------------------------------------ 灌木 / 篱墙（草丛）

export function richBush(): PartSpec[] {
  // T195：原来七团多面球 → 34 团叶簇 + 外沿小叶片，几根枝条从根部伸进去，根部一圈草叶
  const parts: PartSpec[] = foliage([0.1, 0.74, 0], [1.5, 0.92, 1.25], 24, [0.34, 0.58], 4, [0x3a4a26, 0x46572e, 0x50633a, 0x5c6f42], 80, 0.62);
  for (let i = 0; i < 5; i++) {
    const a = i * 1.26 + .3;
    parts.push({ geo: new THREE.CylinderGeometry(0.015, 0.04, 1.1, sg(5), 1, true), color: 0x4a3c2a, surf: S.bark,
      pos: [Math.cos(a) * .3, .45, Math.sin(a) * .25], rot: [Math.sin(a) * .7, 0, -Math.cos(a) * .7] });
  }
  for (let i = 0; i < 18; i++) {
    const a = i * 2.2 + .3, d = r(.75, 1.35, i + 21);
    parts.push({ geo: new THREE.ConeGeometry(.06, r(.4, .8, i + 31), 4, 2, true), color: [0x5d6b35, 0x6a7440, 0x4f5f2e][i % 3],
      pos: [Math.cos(a) * d, .25, Math.sin(a) * d * .8], rot: [r(-.4, .4, i + 41), 0, r(-.4, .4, i + 51)], surf: S.leaf });
  }
  return parts;
}

export function richHedge(): PartSpec[] {
  // T195：原来六团多面球 → 64 团叶簇 + 外沿小叶片，压在原来的土埂上
  const parts: PartSpec[] = foliage([0, 1.28, 0], [2.2, 0.95, 0.95], 42, [0.34, 0.56], 31, [0x34431f, 0x3e4e28, 0x46582e, 0x506334], 100, 0.75);
  const bank = rockify(new THREE.BoxGeometry(4.1, .5, 1.6, sg(4), 1, sg(2)), .08, 9);
  parts.push({ geo: bank, color: 0x4a3e2a, pos: [0, .2, 0], surf: S.stone });
  return parts;
}

// ------------------------------------------------------------------ 房屋

/** 墙面局部 (u, y, 离墙外移) → 房屋坐标与朝向；face 0 = +z 正面、1 = -z、2 = +x、3 = -x（与 houseTrim 一致） */
function onFace(face: number, u: number, y: number, out: number, hw = 3.5, hd = 2.8): { pos: V3; rot: V3 } {
  const pos: V3 = face === 0 ? [u, y, hd + out] : face === 1 ? [-u, y, -hd - out] : face === 2 ? [hw + out, y, -u] : [-hw - out, y, u];
  return { pos, rot: [0, [0, Math.PI, Math.PI / 2, -Math.PI / 2][face], 0] };
}

/** 一扇窗的窗台、窗楣和两侧窗套（立体件，盖在原来的平面窗格外沿） */
function windowDress(face: number, u: number, y: number, w: number, h: number, color: number, out: number, hw?: number, hd?: number): PartSpec[] {
  return [
    { geo: new THREE.BoxGeometry(w + .22, .09, .22), color, ...onFace(face, u, y - h / 2 - .05, out + .08, hw, hd), surf: S.wood },
    { geo: new THREE.BoxGeometry(w + .18, .11, .12), color, ...onFace(face, u, y + h / 2 + .06, out + .04, hw, hd), surf: S.wood },
    { geo: new THREE.BoxGeometry(.08, h, .08), color, ...onFace(face, u - w / 2 - .04, y, out + .03, hw, hd), surf: S.wood },
    { geo: new THREE.BoxGeometry(.08, h, .08), color, ...onFace(face, u + w / 2 + .04, y, out + .03, hw, hd), surf: S.wood },
  ];
}

/** 屋面附件：屋脊压条、檐口封檐板、檐沟、落水管、瓦行凸棱（坡面、四坡的两端） */
function roofDress(eave: number, ridgeX: number, roof: number, trim: number): PartSpec[] {
  const parts: PartSpec[] = [];
  const rise = 6 - eave, len = Math.hypot(rise, 2.95), th = Math.atan2(rise, 2.95);
  parts.push({ geo: new THREE.BoxGeometry(ridgeX * 2 + .2, .13, .38), color: roof, pos: [0, 6.03, 0], surf: S.roof });
  for (const sz of [1, -1]) {
    parts.push({ geo: new THREE.BoxGeometry(7.72, .17, .08), color: trim, pos: [0, eave + .02, sz * 3.13], surf: S.wood });
    const gutter = new THREE.CylinderGeometry(.075, .075, 7.5, sg(8), 1, true);
    parts.push({ geo: gutter, color: 0x5c605e, pos: [0, eave - .06, sz * 3.22], rot: [0, 0, Math.PI / 2] });
    for (let i = 1; i <= 4; i++) {
      const t = i / 5, w = 2 * (3.8 - t * (3.8 - ridgeX)) - .1;
      const y = eave + t * rise + (2.95 / len) * .03, z = sz * (3.1 - t * 2.95 + (rise / len) * .03);
      parts.push({ geo: new THREE.BoxGeometry(w, .05, .12), color: roof, pos: [0, y, z], rot: [sz * th, 0, 0], surf: S.roof });
    }
  }
  for (const sx of [1, -1]) parts.push({ geo: new THREE.CylinderGeometry(.05, .05, eave - .1, sg(6), 1, true), color: 0x575b59, pos: [sx * 3.62, (eave - .1) / 2, 3.22] });
  const hip = 3.8 - ridgeX;
  if (hip > .1) {
    const lh = Math.hypot(rise, hip), ph = Math.atan2(rise, hip);
    for (const sx of [1, -1]) for (let i = 1; i <= 3; i++) {
      const t = i / 4, w = 2 * (3.1 - t * 2.95) - .1;
      parts.push({ geo: new THREE.BoxGeometry(.12, .05, w), color: roof, surf: S.roof,
        pos: [sx * (3.8 - t * hip + (rise / lh) * .03), eave + t * rise + (hip / lh) * .03, 0], rot: [0, 0, -sx * ph] });
    }
  }
  return parts;
}

/** 烟囱顶：挑檐 + 烟囱罐 */
const chimneyCap = (x: number, top: number, z: number): PartSpec[] => [
  { geo: new THREE.BoxGeometry(.9, .12, .9), color: 0x6e6457, pos: [x, top + .06, z], surf: S.stone },
  { geo: new THREE.CylinderGeometry(.12, .15, .34, sg(8), 1, true), color: 0x8a5a44, pos: [x, top + .29, z], surf: S.brick },
];

/** 原农舍（sceneryGeo('house')） */
export function richFarmHouse(): PartSpec[] {
  const glass = 0x2e3438, wood = 0x4a3626, trim = 0x6a5e4c;
  const parts: PartSpec[] = [
    { geo: new THREE.BoxGeometry(7, 3.6, 5.6), color: 0xcfc6b2, pos: [0, 1.8, 0], surf: S.plaster },
    { geo: new THREE.BoxGeometry(7.2, .4, 5.8), color: 0x6a5e4c, pos: [0, .2, 0], surf: S.stone },
    { geo: frustum(rect(7.6, 6.2), rect(7.6, .3), 2.4, 3.6), color: 0x7a3b2c, surf: S.roof },
    { geo: new THREE.BoxGeometry(.7, 2.2, .7), color: 0x8a7b68, pos: [2.2, 5.2, .8], surf: S.brick },
    ...chimneyCap(2.2, 6.3, .8),
    { geo: new THREE.BoxGeometry(1.1, 2.0, .1), color: wood, pos: [0, 1.0, 2.82], surf: S.wood },
    { geo: new THREE.BoxGeometry(1.5, .2, .55), color: 0x7a7266, pos: [0, .1, 3.1], surf: S.stone },
    { geo: new THREE.BoxGeometry(1.42, .14, .2), color: trim, pos: [0, 2.08, 2.86], surf: S.wood },
    ...[-.62, .62].map((x): PartSpec => ({ geo: new THREE.BoxGeometry(.12, 2.05, .16), color: trim, pos: [x, 1.02, 2.85], surf: S.wood })),
  ];
  const win = (face: number, u: number) => {
    const at = onFace(face, u, 2.1, .02, 3.5, 2.8);
    parts.push({ geo: new THREE.BoxGeometry(1.1, 1.0, .1), color: glass, ...at, surf: S.glass });
    parts.push({ geo: new THREE.BoxGeometry(.05, 1.0, .05), color: trim, ...onFace(face, u, 2.1, .08, 3.5, 2.8) });
    parts.push({ geo: new THREE.BoxGeometry(1.1, .05, .05), color: trim, ...onFace(face, u, 2.1, .08, 3.5, 2.8) });
    parts.push(...windowDress(face, u, 2.1, 1.1, 1.0, trim, .03, 3.5, 2.8));
    for (const s of [-1, 1]) parts.push({ geo: new THREE.BoxGeometry(.5, 1.05, .05), color: 0x4a5a47, ...onFace(face, u + s * .85, 2.1, .05, 3.5, 2.8), surf: S.wood });
  };
  win(0, -2.4); win(0, 2.4); win(2, 1.4); win(2, -1.4);
  // 山墙封檐（两端各两根，沿坡）
  const th = Math.atan2(2.4, 2.95);
  for (const sx of [1, -1]) for (const sz of [1, -1]) {
    parts.push({ geo: new THREE.BoxGeometry(.1, .2, 3.85), color: trim, pos: [sx * 3.83, 4.8, sz * 1.625], rot: [sz * th, 0, 0], surf: S.wood });
  }
  parts.push(...roofDress(3.6, 3.8, 0x6e3428, trim));
  return parts;
}

/** 四种新房型：原 styledHouseParts 全保留（窗格、木构、山墙），再加立体窗套、门檐、台阶、屋面附件 */
export function richStyledHouse(look: HouseLook): PartSpec[] {
  const s = houseStyle(look);
  const parts = styledHouseParts(look);
  const wall = look === 'brick' ? S.brick : S.plaster;
  parts.forEach((p, i) => {
    p.surf = i === 0 ? wall : i === 1 ? S.stone : i === 2 ? S.roof : i === 3 ? S.brick
      : p.color === 0x303a3b ? S.glass : p.color === s.gable ? S.plaster : S.wood;
  });
  parts.push(...chimneyCap(2.2, 6.3, .8));
  for (let face = 0; face < 4; face++) {
    for (const [x0, y0, x1, y1, color] of houseTrim(s, face)) {
      if (color !== 0x303a3b) continue;
      parts.push(...windowDress(face, (x0 + x1) / 2, (y0 + y1) / 2, x1 - x0, y1 - y0, s.trim, .02));
    }
  }
  parts.push({ geo: new THREE.BoxGeometry(1.8, .1, .75), color: s.roof, pos: [0, 2.52, 3.17], rot: [.12, 0, 0], surf: S.roof });
  for (const x of [-.8, .8]) parts.push({ geo: new THREE.BoxGeometry(.08, .5, .08), color: s.trim, pos: [x, 2.28, 3.42], rot: [-.7, 0, 0], surf: S.wood });
  parts.push({ geo: new THREE.BoxGeometry(1.6, .2, .6), color: 0x7a7266, pos: [0, .1, 3.15], surf: S.stone });
  parts.push(...roofDress(s.eave, s.ridgeX, s.roof, s.trim));
  return parts;
}

// ------------------------------------------------------------------ 残楼 / 砖墙（砌体部件仍各是一整块，受击后的断墙照旧按部件包围盒重建）

/** 一段残墙：分段的砖块体，顶面参差、棱角磕缺，仍在原尺寸的包围盒内 */
function slab(w: number, h: number, d: number, seed: number): THREE.BufferGeometry {
  const g = new THREE.BoxGeometry(w, h, d, sg(4), sg(4), 1);
  const p = g.getAttribute('position') as THREE.BufferAttribute;
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i), y = p.getY(i), z = p.getZ(i);
    const n = r(0, 1, Math.round(x * 131 + z * 71 + y * 37) + seed);
    const t = (y + h / 2) / h;
    const top = y > h / 2 - 1e-4 ? -n * Math.min(.45, h * .14) : 0;
    const chip = t > .05 ? (n - .5) * .06 : 0;
    p.setXYZ(i, x * (1 - Math.abs(chip)), y + top, z * (1 - Math.abs(chip) * 1.5));
  }
  g.computeVertexNormals();
  return g;
}

export function richRuin(): PartSpec[] {
  const parts: PartSpec[] = [{ geo: rockify(new THREE.BoxGeometry(8, .5, 7, sg(4), 1, sg(4)), .05, 3), color: 0x5a524a, pos: [0, .25, 0], surf: S.stone }];
  const brick = [0x8a5440, 0x7a4a38, 0x6a4234];
  for (let i = 0; i < 6; i++) {
    const h = r(2.5, 7.5, i + 1);
    parts.push({ geo: slab(1.4, h, .6, i * 17), color: brick[i % 3], pos: [-3.3 + i * 1.32, h / 2, 3.2], crush: C.masonry, surf: S.brick });
  }
  for (let i = 0; i < 5; i++) {
    const h = r(1.5, 6.5, i + 11);
    parts.push({ geo: slab(.6, h, 1.4, i * 23 + 5), color: brick[(i + 1) % 3], pos: [-3.7, h / 2, 2.5 - i * 1.4], crush: C.masonry, surf: S.brick });
  }
  for (let i = 0; i < 3; i++) parts.push({ geo: new THREE.BoxGeometry(.9, 1.2, .08), color: 0x1e1a18, pos: [-2.4 + i * 2.2, r(3, 5, i + 21), 3.52], crush: C.glass });
  for (let i = 0; i < 10; i++) {
    const big = i < 7;
    parts.push({ geo: rockify(new THREE.BoxGeometry(big ? 1.2 : .55, big ? .7 : .3, big ? 1.0 : .45, 2, 1, 2), .3, i), color: [0x6e5a4a, 0x7a4a38, 0x8a8070][i % 3], surf: i % 3 === 2 ? S.stone : S.brick,
      pos: [r(-3, 3, i + 31), big ? .5 : .55, r(-2.5, 2, i + 41)], rot: [r(0, 1, i), r(0, 3, i + 5), 0] });
  }
  for (let i = 0; i < 3; i++) parts.push({ geo: new THREE.BoxGeometry(.2, .2, r(2.6, 3.8, i + 51)), color: 0x241c16, surf: S.wood,
    pos: [r(-2.2, 2.2, i + 61), .62 + i * .1, r(-1.8, 1.2, i + 71)], rot: [r(-.3, .3, i + 81), r(0, 3, i + 91), r(-.2, .2, i + 101)] });
  return parts;
}

export function richWall(): PartSpec[] {
  const parts: PartSpec[] = [];
  for (let i = 0; i < 5; i++) {
    const h = r(1.2, 3.6, i + 3);
    parts.push({ geo: slab(1.25, h, .5, i * 29 + 3), color: i % 2 ? 0x84503e : 0x7a4a3a, pos: [-2.5 + i * 1.24, h / 2, 0], crush: C.masonry, surf: S.brick });
  }
  for (let i = 0; i < 10; i++) parts.push({ geo: new THREE.BoxGeometry(.5, .25, .3), color: [0x8a5a44, 0x7a4a3a, 0x6e6458][i % 3], surf: S.brick,
    pos: [r(-2.6, 2.6, i + 9), .15 + (i % 3 === 0 ? .2 : 0), r(.4, 1.5, i + 13) * (i % 2 ? 1 : -1)], rot: [r(-.2, .2, i + 17), r(0, 3, i), r(-.2, .2, i + 19)] });
  return parts;
}
