import type { InkContext, UiSkin } from './types';
import { line, random } from './drawing';

function screw(c: InkContext, x: number, y: number): void {
  const g = c.createLinearGradient(x - 3, y - 3, x + 3, y + 3);
  g.addColorStop(0, '#f2f4e8'); g.addColorStop(0.45, '#b5c1b8'); g.addColorStop(1, '#5b7071');
  c.fillStyle = g; c.beginPath(); c.arc(x, y, 2.8, 0, Math.PI * 2); c.fill();
  c.strokeStyle = '#758987'; c.lineWidth = 0.5; c.stroke();
  line(c, x - 1.3, y + 1.3, x + 1.3, y - 1.3, '#536969', 0.8);
}

export const scheme5: UiSkin = {
  id: 5, name: '精工试制', shape: 'square', radius: 3, light: true, ticks: 10,
  colors: {
    back: '#b8c2b9', backHi: '#e7e9de', high: '#f0f1e7', low: '#c8d0c7', line: '#7f9290',
    ink: '#21393e', soft: '#354f54', dim: '#40585c', accent: '#315e67', cool: '#397781',
    mainHi: '#497982', mainLow: '#274a53', mainInk: '#f8f6e9', shadow: '#6c7e7b',
  },
  texture(c) {
    const rnd = random(561);
    for (let i = 0; i < 1800; i++) {
      const x = rnd() * 256, y = rnd() * 256;
      line(c, x, y, x + rnd() * 70 + 6, y, i % 3 ? 'rgba(255,255,248,.055)' : 'rgba(30,60,63,.02)', 0.45);
    }
  },
  detail(c, w, h, role) {
    line(c, 5, 3, w - 5, 3, 'rgba(255,255,250,.65)');
    if (role === 'primary') {
      screw(c, 10, h / 2); screw(c, w - 10, h / 2);
      line(c, 19, h - 5, w - 19, h - 5, '#11343d', 1);
    } else if (w > 76 && h > 35) {
      for (const x of [7, w - 7]) for (const y of [7, h - 7]) screw(c, x, y);
      if (role === 'card') line(c, 58, 12, 58, h - 12, '#7a9492');
      if (role === 'title') {
        line(c, 19, h - 4, w - 19, h - 4, '#4b7277', 2);
      }
    }
  },
  scene(c, w, h) {
    const l = Math.max(8, (w - 530) / 2), r = w - l;
    c.strokeStyle = '#778c89'; c.lineWidth = 1;
    c.strokeRect(l + 0.5, 12.5, r - l - 1, h - 25);
    c.strokeStyle = '#f1f3e5';
    c.strokeRect(l + 3.5, 15.5, r - l - 7, h - 31);
    for (const x of [l + 5, r - 5]) for (const y of [22, h / 2, h - 22]) screw(c, x, y);
    for (let y = 48; y < h - 40; y += 8) {
      line(c, l + 1, y, l + (y % 40 === 8 ? 7 : 4), y, '#668181');
      line(c, r - 4, y, r - 1, y, '#8fa39c');
    }
    line(c, w / 2 - 36, 26, w / 2 + 36, 26, '#5d7e80', 2);
    line(c, w / 2 - 22, 31, w / 2 + 22, 31, '#9caea3');
    c.fillStyle = '#3b626b'; c.fillRect(r - 62, h - 28, 42, 4);
    c.fillStyle = '#d99b4e'; c.fillRect(r - 72, h - 28, 6, 4);
  },
};
