import type { CoreId } from '../weapons/defs';
import type { ModeView } from './modeBook';
import type { RoutePageId } from './routeBook';

/** 两套界面共用准备状态。浏览选择不启动作战，也不覆盖本局。 */
export type MissionKind = 'run' | 'zone' | 'boss' | 'daily';
export const MISSION_TABS: [MissionKind, string][] = [
  ['run', '连续作战'], ['zone', '自选关卡'], ['boss', '首领演练'], ['daily', '每日挑战'],
];
export interface MissionItem {
  id: number;
  name: string;
  sub: string;
  lock?: string | null;
}
export interface MissionView {
  name: string;
  summary: string;
  reward: string;
  brief: string[];
  items: MissionItem[];
  selected: number;
  lock: string | null;
  action: string;
}
export class Preparation {
  kind: MissionKind = 'run';
  zone = 1;
  boss = 0;

  select(id: number): void {
    if (this.kind === 'zone') this.zone = id;
    else if (this.kind === 'boss') this.boss = id;
  }

  view(data: ModeView | null): MissionView {
    const base: MissionView = {
      name: '连续作战',
      summary: '从乡间出发，突破四区防线',
      reward: '军功、军票照常结算',
      brief: ['敌军封锁了通往厂区的公路。', '突破沿线防区，打通补给线。'],
      items: [], selected: 0, lock: null, action: 'mode:run',
    };
    if (!data || this.kind === 'run') return base;
    if (this.kind === 'zone') {
      const zone = data.levels?.find(l => l.zone === this.zone);
      return {
        ...base, name: zone?.name ?? '自选关卡',
        summary: zone?.picks ? `先选 ${zone.picks} 次升级，再从本区出发` : '从选定区域开始作战',
        reward: '正式作战，军功军票照常',
        brief: this.zone === 5 ? ['解除空中封锁，迫使云垒撤离。']
          : this.zone === 6 ? ['压制穿山，打通油井通路。']
            : ['沿公路突破，后续区域照常推进。'],
        items: data.levels?.map(l => ({ id: l.zone, name: l.name, sub: l.lock ?? `首领：${l.boss}`, lock: l.lock })) ?? [],
        selected: this.zone, lock: zone?.lock ?? (zone ? null : '当前关卡不可用'), action: `mode:zone:${this.zone}`,
      };
    }
    if (this.kind === 'boss') {
      const boss = data.boss?.list[this.boss];
      return {
        ...base, name: `首领演练${boss ? ` · ${boss.code}` : ''}`,
        summary: `先选 ${data.boss?.picks ?? 20} 次升级，直接挑战首领`,
        reward: '槽位满配，不给军功军票',
        brief: [],
        items: data.boss?.list.map((b, i) => ({ id: i, name: b.code, sub: b.kind })) ?? [],
        selected: this.boss, lock: boss ? null : '当前首领不可用', action: `mode:boss:${this.boss}`,
      };
    }
    const daily = data.boss?.daily;
    return {
      ...base, name: `每日挑战${daily ? ` · ${daily.boss}` : ''}`,
      summary: `先选 ${daily?.picks ?? 20} 次升级，挑战带词缀的首领`,
      reward: daily?.reward ?? '当前挑战不可用',
      brief: daily?.affixes.map(a => `${a.name}：${a.line}`) ?? [],
      lock: daily ? null : '当前挑战不可用', action: 'mode:daily',
    };
  }
}

export interface ResumeSummary {
  core: CoreId;
  mode: string;
  progress: string;
  saved: string;
}
export interface SessionUi {
  canSave: boolean;
  note: string;
  summary: string;
}
export interface ConfirmBox {
  title: string;
  lines: string[];
  accept?: string;
  cancel: string;
}
export const replaceRunBox = (settles: boolean): ConfirmBox => ({
  title: '开始新局？',
  lines: settles ? ['原局将按战绩结算。', '结束后无法继续。'] : ['原局不会结算。', '开始后清除本局进度。'],
  accept: settles ? '结束并出击' : '放弃并出击',
  cancel: '保留原局',
});
export const quitRunBox = (settles: boolean): ConfirmBox => ({
  title: '结束本局？',
  lines: [settles ? '按当前战绩结算。' : '本次不会结算。', '结束后无法继续。'],
  accept: '结束本局', cancel: '继续作战',
});
export type HubKind = 'archive' | 'factory' | 'rank' | 'load';
interface HubView {
  title: string;
  sub: string;
  items: { id: string; name: string; sub: string; icon: string; page?: RoutePageId; disabled?: boolean }[];
}
const HUBS: Record<HubKind, HubView> = {
  archive: {
    title: '战情室', sub: '资料、委托与作战纪录',
    items: [
      { id: 'book', name: '资料图鉴', sub: '武器 · 敌人 · 解锁资料', icon: 'category-weapon', page: 'core' },
      { id: 'guide', name: '操作指南', sub: '走位 · 开火 · 本局成长', icon: 'aim', page: 'help-ctrl' },
      { id: 'records', name: '作战纪录', sub: '本机纪录', icon: 'report' },
      { id: 'tasks', name: '每日委托', sub: '查看今日目标', icon: 'tasks', page: 'task' },
    ],
  },
  factory: {
    title: '军工厂', sub: '升级、武器槽与战车外观',
    items: [
      { id: 'factory', name: '永久升级', sub: '军票换作战加成', icon: 'factory', page: 'fac' },
      { id: 'bay', name: '武器槽', sub: '槽位随军衔开放', icon: 'bay', page: 'bay' },
      { id: 'garage', name: '涂装与纹章', sub: '外观不加作战属性', icon: 'garage', page: 'gar-p' },
    ],
  },
  rank: {
    title: '军衔', sub: '晋升、勋章与称号',
    items: [
      { id: 'rank', name: '晋升奖励', sub: '军衔条件与将星奖励', icon: 'rank', page: 'rank-a' },
      { id: 'medal', name: '勋章', sub: '成就 · 称号 · 佩戴', icon: 'medal', page: 'medal-b' },
    ],
  },
  load: {
    title: '加载存档', sub: '',
    items: [
      { id: 'continue', name: '继续作战', sub: '从保存进度继续', icon: 'report' },
      { id: 'import', name: '导入存档', sub: '从文件恢复本机存档', icon: 'bay' },
    ],
  },
};

/** 存档页只读取现有摘要；继续和导入仍走原入口。 */
export function hubView(kind: HubKind, resume?: ResumeSummary, canImport = false): HubView {
  const hub = HUBS[kind];
  if (kind !== 'load') return hub;
  return {
    ...hub,
    sub: resume ? `${resume.mode} · ${resume.progress}\n${resume.saved}` : '暂无本局存档',
    items: hub.items.filter(item => item.id !== 'import' || canImport).map(item => item.id === 'continue'
      ? { ...item, disabled: !resume, sub: resume ? item.sub : '出击后可保存进度' } : item),
  };
}
