import { ATTR_MODS, SUPER_MODS, isSuperMod, BRANCH_LEVEL, CORE_MAX, CORE_STATS, CORES, FUSIONS, LINKS, MAX_LEVEL, MODS, WEAPONS, type CoreId, type FusionDef, type LinkId, type ModId, type WeaponId } from '../weapons/defs';
import { SUB_FORMS, SUB_LINK_LEVEL, SUB_MAX, SUB_POSITION, SUB_SLOTS, subDirection, subStats } from '../weapons/subMerge';
