/**
 * 局内可查的「武器路线」（T020-b，策划 `T020-镜头与武器路线表-策划案.md` 第 3～4 节）：
 * 数据只写一份（纯函数，读 defs.ts + 当前 Arsenal），DOM 版（ui/Menu.ts）和画布版（ui/canvas/CanvasMenu.ts）各画一层皮。
 * 6 页「本局 / 流派 / 副武器 / 究极 / 改装 / 联动」，每页一屏放完不滚动（画布版没有滚动）；开始界面打开时没有「本局」页。
 * T049 起卡面 / 槽位详情 / 长按只留一句，数值和细节都在这里查（「联动」页、究极页的详细数值、流派页的「特点」都是这时加的）
 */
export type RouteState = 'done' | 'now' | 'next' | 'off';
export interface RouteRow {
  super?: boolean;
  /** 未合成的究极只画占位，不提供图标或配方。 */
  unknown?: boolean;
  icon: string;
  title: string;
  /** 标题后面的小标签（分支名 / 定位 / 冷却） */
  tag?: string;
  lines: string[];
  /** 等级小点 */
  pips?: { max: number; on: number };
  /** 已完成 / 当前 / 下一步可拿 / 没走这条（压暗） */
  state: RouteState;
  /** 成就页（D4 / 汇总第 26 条）：图标换成程序化勋章（没拿到 = 灰色剪影）；称号页：标题画成铭牌 */
  medal?: { tier: MedalTier; got: boolean };
  plate?: PlateTier;
  /** 局外成长各页（T030）：图标换成军衔肩章（第几级）/ 涂装色块 / 纹章；一条进度条；一排按钮（点了走 Menu.onAct(id)） */
  board?: number;
  swatch?: string[];
  emblem?: string;
  bar?: { p: number; text: string };
  acts?: RouteAct[];
  /** 整行可点（车库里点一格 = 预览这一套），点了走 onAct(tap) */
  tap?: string;
  /** 整行高亮（车库里正在预览的那一格） */
  sel?: boolean;
}
/** 行里的按钮：gold 金色主按钮、outline 描边、warn 橙色描边（点两下的第一下，T053）、ad 看广告（带播放图标）、off 灰（点了没反应）、chip / chipOn 小选项 */
export interface RouteAct {
  id: string;
  label: string;
  kind: 'gold' | 'outline' | 'warn' | 'ad' | 'off' | 'chip' | 'chipOn';
}
export interface RouteSection {
  title: string;
  rows: RouteRow[];
  /** 1 列 / 2 列 */
  cols?: 1 | 2;
  /** 装配车间（T033）：这一节画「装配板」（rows 为空） */
  bay?: BayView;
}

/** 装配板的一格：开着 / 刚装上还没看过（金边 +「新」）/ 锁着（label = 哪一级军衔开） */
export interface BayCell {
  on: boolean;
  fresh?: boolean;
  label?: string;
}
/** 装配板：核心一格，副武器一排。 */
export interface BayView {
  /** 核心格的图标 / 名字（开始界面选中的流派） */
  core: string;
  coreName: string;
  weapon: BayCell[];
  head: string;
  caption: string;
}
export type RoutePageId =
  | 'run'
  | 'core'
  | 'weapons'
  | 'ults'
  | 'mods'
  | 'links'
  // T049 图鉴第三段「玩法」：操作 / 成长 / 生存 / 局外（规则类说明都在这里，见 helpBook.ts）
  | 'help-ctrl'
  | 'help-pad'
  | 'help-grow'
  | 'help-live'
  | 'help-meta'
  // T110 作战模式 + 词缀
  | 'help-mode'
  | 'medal-b'
  | 'medal-s'
  | 'medal-g'
  | 'titles'
  // T030 局外成长：军衔 / 军工厂 / 每日任务 / 车库 / 战区 / 勋章墙新加的两页
  | 'rank-a'
  | 'rank-b'
  | 'rank-c'
  | 'fac'
  | 'task'
  | 'gar-p'
  | 'gar-e'
  | 'gar-x'
  | 'thr'
  | 'thr-b'
  | 'wall-sum'
  | 'wall-sash'
  // T033 装配车间
  | 'bay'
  // T110 作战模式：连续作战 / 自选关卡 / 首领挑战
  | 'mode-run'
  | 'mode-zone'
  | 'mode-boss';
export interface RoutePage {
  id: RoutePageId;
  label: string;
  /** 「流派」页顶上的三段切换 */
  cores?: { id: CoreId; label: string; on: boolean }[];
  /** 标签下面一行（军票余额之类） */
  head?: string;
  sections: RouteSection[];
}

/** 浮层是哪一本：图鉴（武器 / 敌人 / 玩法）、勋章墙、军衔、军工厂、每日任务、车库、战区、装配车间、作战模式（T110） */
export type Book = 'weapons' | 'foes' | 'help' | 'medal' | 'rank' | 'factory' | 'tasks' | 'garage' | 'threat' | 'bay' | 'modes';
export function bookOf(tab: string): Book {
  if (tab.startsWith('foe')) return 'foes';
  if (tab.startsWith('help')) return 'help';
  if (tab.startsWith('mode')) return 'modes';
  if (tab.startsWith('medal') || tab === 'titles' || tab.startsWith('wall')) return 'medal';
  if (tab.startsWith('rank')) return 'rank';
  if (tab === 'fac') return 'factory';
  if (tab === 'task') return 'tasks';
  if (tab.startsWith('gar')) return 'garage';
  if (tab.startsWith('thr')) return 'threat';
  if (tab === 'bay') return 'bay';
  return 'weapons';
}
/** 图鉴顶上的三段（T049 加「玩法」） */
export const BOOKS: [Book, string][] = [
  ['weapons', '武器'],
  ['foes', '敌人'],
  ['help', '指南'],
];
export const BOOK_TITLE: Record<Book, string> = { weapons: '资料图鉴', foes: '资料图鉴', help: '操作指南', medal: '勋章墙', rank: '军衔', factory: '军工厂', tasks: '每日委托', garage: '涂装与纹章', threat: '战区', bay: '武器槽', modes: '作战模式' };

export const ROUTE_TABS: [RoutePageId, string][] = [
  ['run', '本局'],
  ['core', '流派'],
  ['weapons', '副武器'],
  ['ults', '究极'],
  ['mods', '改装'],
  ['links', '联动'],
];

const WIDS = Object.keys(WEAPONS) as WeaponId[];
const CIDS = Object.keys(CORES) as CoreId[];
const n1 = (v: number) => (Number.isInteger(v) ? String(v) : v.toFixed(v < 1 ? 2 : 1));

/** 本局：还差哪几步能合成这条究极——steps 按件分组的说明，n = 一共还差几步（升级 / 拿钥匙 / 拿武器各算一步；n = 0 条件满足） */
export function fusionSteps(a: Arsenal, f: FusionDef): { steps: string[]; n: number } {
  const steps: string[] = [];
  let n = 0;
  const c = a.core;
  if (!c.ultimate) {
    const parts: string[] = [];
    if (c.level < CORE_MAX) parts.push(`${c.def.turret}升到 ${CORE_MAX} 级`);
    if (!a.mods.has(c.def.evolveWith)) parts.push(`拿${MODS[c.def.evolveWith].name}`);
    n += Math.max(1, parts.length);
    steps.push(parts.length ? `${parts.join('并')}（终极进化）` : '终极进化（升级时选卡）');
  }
  for (const p of f.parts) {
    const def = WEAPONS[p];
    const w = a.bestWeapon(p);
    const parts: string[] = [];
    if (!w) parts.push(`拿到${def.name}`);
    if ((w?.level ?? 0) < SUB_MAX) parts.push(`${def.short}合成到四级`);
    if (!a.mods.has(def.evolveWith)) parts.push(`拿${MODS[def.evolveWith].name}`);
    n += parts.length;
    if (parts.length) steps.push(parts.join('、'));
  }
  return { steps, n };
}

/** 本核心两条配方的公式（〔核心终极〕+〔A★〕+〔B★〕） */
const recipe = (f: FusionDef) => `${CORES[f.core].name}终极 + ${f.parts.map(p => `${WEAPONS[p].short}四级及${MODS[WEAPONS[p].evolveWith].name}`).join(' + ')}`;
const formula = (f: FusionDef) => `${f.name} = ${recipe(f)}`;

type KnowsFusion = (f: FusionDef) => boolean;
const unknownWeapon = (): RouteRow => ({ icon: '', title: '未知', lines: ['合成后解锁资料'], state: 'off', unknown: true });

function runPage(a: Arsenal, known: KnowsFusion): RoutePage {
  const c = a.core;
  const br = c.branch ? c.def.branches[c.branch] : null;
  const key = MODS[c.def.evolveWith].name;
  const coreRow: RouteRow = {
    icon: `core-${c.id}`,
    title: `${c.def.turret} · ${c.def.name}`,
    tag: br ? br.name : `${BRANCH_LEVEL} 级选分支`,
    pips: { max: CORE_MAX, on: c.level },
    lines: [
      c.ultimate && br
        ? `已终极进化：${br.ultName}`
        : br
          ? `满级 + ${key} → ${br.ultName}　满级 ${c.level >= CORE_MAX ? '✓' : '✗'}　${key} ${a.mods.has(c.def.evolveWith) ? '✓' : '✗'}`
          : `${BRANCH_LEVEL} 级选分支：${c.def.branches.A.name} / ${c.def.branches.B.name}`,
    ],
    state: c.ultimate ? 'done' : 'now',
  };
  const weapons: RouteRow[] = [...a.weapons]
    .sort((x, y) => SUB_SLOTS.indexOf(x.slot as typeof SUB_SLOTS[number]) - SUB_SLOTS.indexOf(y.slot as typeof SUB_SLOTS[number]))
    .map((w) => {
      const def = w.def;
      return {
        icon: def.id,
        title: `${SUB_POSITION[w.slot]} · ${w.evolved ? def.evoName : def.short}`,
        pips: { max: SUB_MAX, on: w.level },
        lines: [SUB_FORMS[def.id][w.level - 1], subDirection(def.id, w.slot), w.ult ? '究极材料已锁定，继续开火' : w.link ? `联动：${LINKS[w.link].name}` : '同型同级可合成'],
        state: w.evolved ? 'done' : 'now',
      };
    });
  const sections: RouteSection[] = [{ title: '流派', rows: [coreRow] }];
  sections.push({ title: `副武器 ${a.weapons.length} / ${a.weaponSlots}`, rows: weapons.length ? weapons : [{ icon: 'mg', title: '还没有副武器', lines: ['升级选补件，再选挂位装入'], state: 'next' }] });
  const ult = a.ult;
  if (ult) {
    sections.push({ title: '究极', rows: [{ icon: `ult-${ult.def.id}`, title: `${ult.def.name} · ${ult.def.sub}`, tag: `${a.ultCooldown(ult.def.id)} 秒`, lines: [ult.def.blurb, ult.def.detail[0]], state: 'done' }] });
  } else {
    const rows = a.recipes().map((f): RouteRow => {
      if (!known(f)) return unknownWeapon();
      const { steps, n } = fusionSteps(a, f);
      return {
        icon: `ult-${f.id}`,
        title: `${f.name} · ${f.sub}`,
        tag: n ? `还差 ${n} 步` : '可合成',
        lines: [formula(f), n ? `还差 ${n} 步：${steps.join('；')}` : '条件已满足：下次升级第一张就是合成卡'],
        state: n ? 'next' : 'now',
      };
    });
    sections.push({ title: '究极进度（每局只能合成一次）', rows });
  }
  // 联动改装（T018-link）：已打出的 + 现在能出的
  const linkRows: RouteRow[] = (Object.keys(LINKS) as LinkId[])
    .filter((l) => a.links.has(l) || a.linkable().includes(l))
    .map((l) => ({ icon: LINKS[l].icon, title: LINKS[l].name, tag: a.links.has(l) ? '已联动' : '卡池里有', lines: [pair(l), LINKS[l].lines[0]], state: a.links.has(l) ? 'done' : 'next' }));
  if (linkRows.length) sections.push({ title: '联动改装', rows: linkRows });
  const mods = [...a.mods].map(([id, l]) => `${MODS[id].name} ${l} 级`);
  if (mods.length) {
    const supers = [...a.mods.keys()].filter(isSuperMod);
    const attrs = [...a.mods.entries()].filter(([id]) => !isSuperMod(id));
    if (supers.length) sections.push({ title: `超级改装 ${supers.length} / 8`, cols: 2, rows: supers.map((id) => ({ icon: id, title: MODS[id].name, lines: [MODS[id].blurb], state: 'now', super: true })) });
    if (attrs.length) sections.push({ title: '属性件', rows: attrs.map(([id, l]) => ({ icon: id, title: `${MODS[id].name} · ${l} 级`, lines: [MODS[id].line(l)], state: 'now' })) });
  }
  return { id: 'run', label: '本局', sections };
}

/** 主炮 / 火箭 / 激光 / 火神每一级的关键数值（一行） */
function coreLevelLine(id: CoreId, l: number): string {
  if (id === 'cannon') {
    const s = CORE_STATS.cannon;
    return `弹匣 ${s.rounds(l)} 发 · 装填 ${n1(s.reload(l))} 秒 · 伤害 ${s.damage(l)}`;
  }
  if (id === 'rocket') {
    const s = CORE_STATS.rocket;
    return `每轮 ${s.count(l)} 发 · 装填 ${n1(s.reload(l))} 秒 · 单发 ${s.damage(l)}`;
  }
  if (id === 'vulcan') {
    const s = CORE_STATS.vulcan;
    return `每秒 ${s.rate(l)} 发 · 弹药 ${Math.round(s.belts(l) * s.per(l) * VULCAN.pool)} 发 · 补弹每秒 ${Math.round(s.per(l) / s.reload(l))} 发`;
  }
  const s = CORE_STATS.laser;
  return `输出 ${n1(s.output(l))} 秒 · 每秒 ${s.dps(l)} · 折射 ${s.bounces(l)}`;
}

function corePage(a: Arsenal | null, tab: CoreId, known: KnowsFusion): RoutePage {
  const def = CORES[tab];
  const mine = a?.core.id === tab ? a.core : null;
  const key = MODS[def.evolveWith].name;
  const branch = (b: 'A' | 'B'): RouteRow => {
    const br = def.branches[b];
    const state: RouteState = !mine?.branch ? 'next' : mine.branch === b ? (mine.ultimate ? 'done' : 'now') : 'off';
    return { icon: `core-${tab}`, title: br.name, tag: br.ultName, lines: [br.detail, `终极「${br.ultName}」：满级 + ${key}`, br.ultDetail].flat(), state, pips: mine?.branch === b ? { max: CORE_MAX, on: mine.level } : undefined };
  };
  const recipes = Object.values(FUSIONS).filter((f) => f.core === tab);
  const st: RouteState = mine ? 'now' : 'next';
  return {
    id: 'core',
    label: '流派',
    cores: CIDS.map((id) => ({ id, label: CORES[id].name, on: id === tab })),
    sections: [
      {
        title: `${def.turret} · ${def.tag}`,
        rows: [
          { icon: `core-${tab}`, title: '特点', lines: def.detail, state: st },
          { icon: 'bay', title: '推荐搭配', lines: [def.pair], state: st },
          {
            icon: `core-${tab}`,
            title: '各级数值',
            lines: Array.from({ length: CORE_MAX }, (_, i) => `${i + 1} 级　${coreLevelLine(tab, i + 1)}${i + 1 === BRANCH_LEVEL ? '　选分支' : ''}`),
            state: mine ? (mine.maxed ? 'done' : 'now') : 'next',
            pips: mine ? { max: CORE_MAX, on: mine.level } : undefined,
          },
        ],
      },
      { title: `两条分支（${BRANCH_LEVEL} 级选一条）`, cols: 2, rows: [branch('A'), branch('B')] },
      { title: '能合成的究极', rows: recipes.map((f) => known(f) ? { icon: `ult-${f.id}`, title: formula(f), lines: [f.blurb], state: st } : unknownWeapon()) },
    ],
  };
}

/** 开始页只留一行解锁条件；完整条件和军功进度放流派图鉴。 */
export function withCoreLock(pages: RoutePage[], lock?: CoreLock): RoutePage[] {
  if (!lock) return pages;
  return pages.map((p) => p.id !== 'core' ? p : {
    ...p,
    sections: [
      { title: '解锁条件', rows: [{ icon: 'rank', title: lock.title, lines: lock.lines, state: 'next' }] },
      ...p.sections,
    ],
  });
}

/** 一件副武器在 l 级的全部数值（「伤害 2.8 · 射速 12/秒 · …」） */
const statsAt = (id: WeaponId, l: number) => {
  const def = WEAPONS[id];
  return Object.entries(subStats(id, l)).map(([k, v]) => `${k} ${n1(v)}${def.units[k] ?? ''}`).join(' · ');
};
/** 1 级 → 5 级变了的数值（「伤害 2 → 3.6 · 射速 12 → 16/秒」） */
const statsGrow = (id: WeaponId) => {
  const def = WEAPONS[id];
  const s1 = subStats(id, 1);
  const s5 = subStats(id, SUB_MAX);
  return Object.keys(s5).filter((k) => s1[k] !== s5[k]).map((k) => `${k} ${n1(s1[k])} → ${n1(s5[k])}${def.units[k] ?? ''}`).join(' · ');
};

function weaponsPage(a: Arsenal | null, slots: Slots, known: KnowsFusion): RoutePage {
  const rows = WIDS.map((id): RouteRow => {
    const def = WEAPONS[id];
    const w = a?.bestWeapon(id);
    const notes = SUB_FORMS[id].map((t, i) => `${i + 1} 级${t}`);
    const ults = Object.values(FUSIONS).filter((f) => f.parts.includes(id)).map((f) => known(f) ? f.name : '未知');
    return {
      icon: id,
      title: w?.evolved ? def.evoName : def.name,
      tag: def.role,
      pips: w ? { max: SUB_MAX, on: w.level } : undefined,
      lines: [
        def.detail,
        w ? `最高 ${w.level} 级：${statsAt(id, w.level)}` : `1 → ${SUB_MAX} 级：${statsGrow(id)}`,
        notes.join('；'),
        '同型同级合成；四级直接达到终态',
        `参与究极还需${MODS[def.evolveWith].name}；配方：${ults.join(' / ')}`,
      ].filter(Boolean),
      state: w ? (w.evolved ? 'done' : 'now') : 'next',
    };
  });
  return { id: 'weapons', label: '副武器', sections: [{ title: `6 件副武器 · ${slotText(slots.weapon, '副武器槽')}`, cols: 2, rows }] };
}

/** 联动的两件（「机枪 × 无人机」） */
const pair = (l: LinkId) => LINKS[l].parts.map((p) => WEAPONS[p].short).join(' × ');

/** 联动页（T049）：6 组都列，卡面上只有一句，效果的细节都在这里 */
function linksPage(a: Arsenal | null): RoutePage {
  const rows = (Object.keys(LINKS) as LinkId[]).map((l): RouteRow => {
    const has = a?.links.has(l);
    const can = a?.linkable().includes(l);
    return { icon: LINKS[l].icon, title: LINKS[l].name, tag: has ? '已联动' : can ? '卡池里有' : pair(l), lines: has || can ? [pair(l), ...LINKS[l].lines] : [...LINKS[l].lines], state: has ? 'done' : can ? 'now' : 'next' };
  });
  return { id: 'links', label: '联动', sections: [
    { title: `两件都 ${SUB_LINK_LEVEL} 级才可能出 · 不用多占副武器槽`, rows },
    { title: '同型号只绑定一件', rows: [{ icon: 'slot-w', title: '跟着实例走', lines: ['合成保留联动件和挂位，其他同型件不复制联动', '替换联动件会取消这一组，可再抽联动卡'], state: 'next' }] },
  ] };
}

function ultsPage(a: Arsenal | null, tab: CoreId, known: KnowsFusion): RoutePage {
  const core = a?.core.id ?? tab;
  const sections = CIDS.map((cid): RouteSection => ({
    title: CORES[cid].name,
    rows: Object.values(FUSIONS)
      .filter((f) => f.core === cid)
      .map((f) => {
        if (!known(f)) return unknownWeapon();
        const steps = a && cid === core && !a.ult ? fusionSteps(a, f) : null;
        const done = a?.ult?.def.id === f.id;
        return {
          icon: `ult-${f.id}`,
          title: `${f.name} · ${f.sub}`,
          tag: `${a ? a.ultCooldown(f.id) : f.cd} 秒`,
          lines: [`配方：${recipe(f)}`, ...f.detail, done ? '本局已合成' : steps ? (steps.n ? `本局还差 ${steps.n} 步` : '本局条件已满足') : ''].filter(Boolean),
          state: done ? 'done' : cid === core ? 'now' : 'off',
        };
      }),
  }));
  return { id: 'ults', label: '究极', sections: sections.filter((s) => s.rows.length) };
}

function modsPage(a: Arsenal | null, known: KnowsFusion): RoutePage {
  const names = (line: string) => Object.values(FUSIONS).reduce((text, f) => known(f) ? text : text.split(f.name).join('未知'), line);
  const keyOf = (m: ModId) => {
    const users = [...CIDS.filter((c) => CORES[c].evolveWith === m).map((c) => CORES[c].name), ...WIDS.filter((w) => WEAPONS[w].evolveWith === m).map((w) => WEAPONS[w].name)];
    return users.length ? `钥匙：${users.join(' / ')}` : '纯属性';
  };
  const row = (id: ModId): RouteRow => {
    const d = MODS[id];
    const l = a?.mods.get(id);
    const special = isSuperMod(id);
    const detail = d.detail ?? d.blurb;
    return { icon: id, title: d.name, tag: special ? `${l ? '已装配' : '超级改装'} · ${keyOf(id)}` : '属性件', lines: [...(Array.isArray(detail) ? detail : [detail]), ...(!special ? [`1 级：${d.line(1)}　${MAX_LEVEL} 级：${d.line(MAX_LEVEL)}`] : [])].map(names), pips: !special && l ? { max: MAX_LEVEL, on: l } : undefined, state: l ? 'now' : 'next', super: special };
  };
  return { id: 'mods', label: '改装', sections: [
    { title: '8 件超级改装 · 选中后本局生效', cols: 2, rows: SUPER_MODS.map(row) },
    { title: '3 件属性件 · 各 5 级', rows: ATTR_MODS.map(row) },
  ] };
}

/** 这辆车几个槽（T033 装配车间）：局内按这一局的、开始界面按存档的 */
type Slots = { weapon: number };
const slotText = (_n: number, name: string) => `${name} 6 个全开`;

/** arsenal = null：开始界面打开（没有「本局」页）；coreTab = 「流派」页显示哪个流派；slots = 这辆车几个副武器槽。 */
export function routeBook(arsenal: Arsenal | null, coreTab: CoreId, slots: Slots = { weapon: 6 }, unlocks: readonly string[] = []): RoutePage[] {
  const known: KnowsFusion = f => unlocks.includes(`fusion:${f.id}`) || arsenal?.ult?.def.id === f.id;
  const pages: RoutePage[] = [];
  if (arsenal) pages.push(runPage(arsenal, known));
  pages.push(corePage(arsenal, coreTab, known), weaponsPage(arsenal, slots, known), ultsPage(arsenal, coreTab, known), modsPage(arsenal, known), linksPage(arsenal));
  return pages;
}

/**
 * 成就页（T018-3）：和武器路线同一套界面（标签页 + 行），4 页「铜勋章 / 银勋章 / 金勋章 / 称号」；
 * 拿到的亮（done），没拿到的压暗显示条件，隐藏称号没拿到写「？？？」；佩戴中的称号标「佩戴中」
 */
export function medalBook(unlocks: readonly string[], equipped: string | null, wear: readonly string[] = []): RoutePage[] {
  const pts = achPoints(unlocks);
  const tierPage = (tier: MedalTier, id: RoutePageId): RoutePage => {
    const list = ACHIEVEMENTS.filter((a) => a.tier === tier);
    const got = list.filter((a) => unlocks.includes(`ach:${a.id}`)).length;
    return {
      id,
      label: `${TIER_NAME[tier]}勋章`,
      sections: [
        {
          title: `${TIER_NAME[tier]}勋章 ${got} / ${list.length} · 成就点 ${pts} / 890`,
          cols: 2,
          rows: list.map((a) => {
            const ok = unlocks.includes(`ach:${a.id}`);
            // T030 勋章墙：拿到的点一下佩戴 / 取下（最多 3 枚）
            const on = wear.includes(`ach:${a.id}`);
            return { icon: a.icon, title: a.name, tag: on ? '佩戴中' : ok ? '已获得' : '', lines: [a.cond], state: on ? 'now' : ok ? 'done' : 'off', medal: { tier: a.tier, got: ok }, tap: ok ? `wear:ach:${a.id}` : undefined };
          }),
        },
      ],
    };
  };
  const titles: RoutePage = {
    id: 'titles',
    label: '称号',
    sections: [
      {
        title: '称号（自动佩戴最高档）',
        cols: 2,
        rows: TITLES.map((t) => {
          const ok = unlocks.includes(`title:${t.id}`);
          return { icon: 'shield', title: ok || !t.hidden ? t.name : '？？？', tag: equipped === t.id ? '佩戴中' : `${PLATE_NAME[t.plate]}铭牌`, lines: [ok || !t.hidden ? t.cond : '隐藏称号'], state: ok ? (equipped === t.id ? 'now' : 'done') : 'off', plate: ok ? t.plate : undefined };
        }),
      },
    ],
  };
  return [tierPage('bronze', 'medal-b'), tierPage('silver', 'medal-s'), tierPage('gold', 'medal-g'), titles];
}
