import * as THREE from 'three';
import type { GeoCache, PartSpec } from '../assets/GeoCache';
import type { Bump } from '../systems/World';
import type { BossContext } from './Boss';
import { clamp01, smooth } from './airshipPath';

/**
 * 「云垒」的 8 根巨缆（T142，D5 2.5 / 第 3 节）：6 道横跨艇背的压顶缆（两头拴在临路墙、后墙墙顶的缆桩上）+ 2 条艇腹锚链（垂进坑里）。
 * 每根：松垂 → 绷紧 → 预警抖动 → 断 → 甩（横砸路面）/ 滑落（进库）/ 落坑（锚链）→ 躺地 → 收走。
 * 断的时刻只看时间（序幕两根按开顶秒数、其余按时间轴），不进存档；直通 / 跳时间轴跨过去的直接算解开（不演）。
 * 坐标全是库里本地（和机库、首领 root 同一个变换：+x 沿路往前，+z 朝路，临路墙外面 z = 0）
 */
export interface CableDef {
  id: 'S1' | 'S2' | 'S3' | 'S4' | 'S5' | 'S6' | 'A1' | 'A2';
  kind: 'top' | 'anchor';
  /** 库里本地 x（压顶缆横跨艇背的位置 / 锚链绞盘在艇腹的位置） */
  x: number;
  /** whip = 后墙那头解扣、绕临路墙缆桩翻过来横砸路面；slide = 临路墙那头解扣、从艇背滑进库里；drop = 锚链从绞盘脱开掉进坑里 */
  mode: 'whip' | 'slide' | 'drop';
  /** 序幕里断（开顶第几秒：长版 / 短版）；没有 = 按时间轴 tl 断 */
  open?: readonly [number, number];
  tl?: number;
  /** 断的时候艇身往上抬多少米、预警几秒 */
  lift: number;
  warn: number;
  /** 缆鞭：砸到路面上离临路墙多远（米，路中心在 22 米处）、伤不伤人（序幕那根只示范） */
  reach?: number;
  hurt?: boolean;
}

export const CABLES: readonly CableDef[] = [
  { id: 'S1', kind: 'top', x: -70, mode: 'whip', open: [12.6, 5.2], lift: 0.5, warn: 1.6, reach: 28, hurt: false },
  { id: 'S2', kind: 'top', x: 70, mode: 'slide', open: [9.6, 4.6], lift: 0.5, warn: 1.6 },
  { id: 'S3', kind: 'top', x: -40, mode: 'whip', tl: 7.0, lift: 0.7, warn: 1.6, reach: 31, hurt: true },
  { id: 'S4', kind: 'top', x: 100, mode: 'slide', tl: 16.0, lift: 0.6, warn: 1.6 },
  { id: 'S5', kind: 'top', x: -100, mode: 'whip', tl: 25.0, lift: 0.9, warn: 2.0, reach: 37, hurt: true },
  { id: 'S6', kind: 'top', x: 40, mode: 'slide', tl: 42.0, lift: 0.8, warn: 1.6 },
  { id: 'A1', kind: 'anchor', x: 50, mode: 'drop', tl: 58.0, lift: 1.2, warn: 2.0 },
  { id: 'A2', kind: 'anchor', x: -60, mode: 'drop', tl: 76.0, lift: 1.8, warn: 2.0 },
];

/**
 * 尺寸 / 时长：缆桩顶（拴缆那一点）离地 bollardY、离临路墙外面 / 后墙里面多远；压顶缆松着时最多垂 sag 米（艇顶低于墙顶时搭在艇背上）、
 * 艇中线 A 从 slack[0] 升到 slack[1] 之间垂度收到 0；预警横抖 shake 米（hz 赫兹）；甩 / 滑落 / 落坑 / 躺地 / 收走各几秒；锚链一节多长
 */
export const CABLE = {
  bollardY: 10.0, bollardIn: 2.2, sag: 9, slack: [-10, -2] as const, shake: 0.25, hz: 9,
  whip: 0.9, slide: 1.2, drop: 1.5, lie: 6, reel: 2.5, link: 2.6,
  /** 每根压顶缆几段 / 每条锚链几节（高 / 中 / 低） */
  segs: { high: 16, medium: 10, low: 6 } as const,
  links: { high: 24, medium: 16, low: 10 } as const,
  /** 缆鞭红带沿路方向宽（米）、伤害（第 1 区基准）、往左推开几米 */
  band: 3.5, dmg: 14, push: 2,
};
const MAX_SEGS = CABLE.segs.high;
const MAX_LINKS = CABLE.links.high;

const DARK = 0x3a3836;
const STEEL_D = 0x706c67;
const RIVET = 0x54504c;
const HAZARD = 0xd2a22e;
const box = (w: number, h: number, d: number) => new THREE.BoxGeometry(w, h, d);

/** 压顶缆一段（沿 +x 长 1，按段长拉伸）：3 股钢缆并成一束（2.4 × 1.0 米扁带）+ 段头一道箍（钢灰 + 黄黑警示条） */
function ropeParts(): PartSpec[] {
  const strand = (z: number): PartSpec => ({ geo: new THREE.CylinderGeometry(0.42, 0.42, 1, 6), color: DARK, pos: [0.5, 0, z], rot: [0, 0, Math.PI / 2] });
  return [strand(-0.8), strand(0), strand(0.8), { geo: box(0.07, 1.25, 2.65), color: STEEL_D, pos: [0.035, 0, 0] }, { geo: box(0.05, 1.27, 2.67), color: HAZARD, pos: [0.095, 0, 0] }];
}
/** 缆扣：2.4 × 2.4 × 1.6 米方块 + 一圈铆钉 */
function claspParts(): PartSpec[] {
  const p: PartSpec[] = [{ geo: box(1.6, 2.4, 2.4), color: STEEL_D }];
  for (const y of [-0.9, 0.9]) for (const z of [-0.9, 0.9]) p.push({ geo: box(1.7, 0.28, 0.28), color: RIVET, pos: [0, y, z] });
  return p;
}
/** 锚链一环：3.2 米长、2.0 米宽、钢条 0.5 米 */
function linkParts(): PartSpec[] {
  return [
    { geo: box(0.5, 3.2, 0.5), color: DARK, pos: [-0.75, 0, 0] },
    { geo: box(0.5, 3.2, 0.5), color: DARK, pos: [0.75, 0, 0] },
    { geo: box(2.0, 0.5, 0.5), color: DARK, pos: [0, 1.35, 0] },
    { geo: box(2.0, 0.5, 0.5), color: DARK, pos: [0, -1.35, 0] },
  ];
}

/** 艇身在库里本地 x 处的截面：圆心（库里本地 y / z）和半径（含背脊走道和缆的厚度） */
export interface HullSection {
  y: number;
  z: number;
  r: number;
}

/** 断缆的回调（艇身上抬 / 侧倾、镜头、伤害由首领本体做） */
export interface CableEvents {
  /** 进预警（红带、横幅） */
  warn(c: CableDef, reachX: number): void;
  /** 断的那一下 */
  snap(c: CableDef): void;
  /** 缆鞭砸到路面：库里本地 x */
  slam(c: CableDef): void;
}

type Stage = 'hold' | 'snap' | 'lie' | 'reel' | 'gone';
interface Cable {
  def: CableDef;
  stage: Stage;
  /** 这一段演了几秒（真实时间）；预警进度 0..1（0 = 没在预警）；进过预警没有 */
  t: number;
  warnK: number;
  warned: boolean;
  /** 节点（库里本地）：压顶缆 MAX_SEGS + 1 个，锚链 MAX_LINKS 个（每环中心） */
  nodes: THREE.Vector3[];
  from: THREE.Vector3[];
  /** 缆鞭：前半截（绕临路墙缆桩翻过来的）到第几个节点、躺在路上的软凸起 */
  split: number;
  bump: Bump | null;
  /** 滑落时这一帧有没有节点蹭着艇身（冒火花） */
  rub: THREE.Vector3 | null;
}

const tv = new THREE.Vector3();
const tw = new THREE.Vector3();
const ex = new THREE.Vector3();
const ey = new THREE.Vector3();
const ez = new THREE.Vector3();
const mA = new THREE.Matrix4();
const qA = new THREE.Quaternion();
const sA = new THREE.Vector3();
const HIDE = new THREE.Matrix4().makeScale(0, 0, 0);

export class SkyCables {
  readonly cables: Cable[];
  private readonly ropes: THREE.InstancedMesh;
  private readonly clasps: THREE.InstancedMesh;
  private readonly links: THREE.InstancedMesh;
  /** 压顶缆两头缆桩的 (z, y)：临路墙那头 / 后墙那头 */
  private readonly p0: [number, number];
  private readonly p1: [number, number];
  private q: 'high' | 'medium' | 'low' = 'high';
  private clock = 0;
  private fxT = 0;
  /** 2D 折线采样用 */
  private readonly samp: [number, number][] = Array.from({ length: MAX_SEGS + 1 }, () => [0, 0] as [number, number]);

  constructor(
    geo: GeoCache,
    mat: THREE.Material,
    parent: THREE.Object3D,
    depth: number,
    private readonly ctx: BossContext,
    private readonly root: THREE.Object3D,
    private readonly ev: CableEvents,
    private readonly take: (n: number) => number,
  ) {
    this.p0 = [-CABLE.bollardIn, CABLE.bollardY];
    this.p1 = [-depth + CABLE.bollardIn, CABLE.bollardY];
    const tops = CABLES.filter((c) => c.kind === 'top').length;
    const anchors = CABLES.length - tops;
    this.ropes = new THREE.InstancedMesh(geo.merged('sky-rope', ropeParts), mat, tops * MAX_SEGS);
    this.clasps = new THREE.InstancedMesh(geo.merged('sky-clasp', claspParts), mat, tops * 2);
    this.links = new THREE.InstancedMesh(geo.merged('sky-link', linkParts), mat, anchors * MAX_LINKS);
    for (const m of [this.ropes, this.clasps, this.links]) {
      m.frustumCulled = false;
      for (let i = 0; i < m.count; i++) m.setMatrixAt(i, HIDE);
      parent.add(m);
    }
    this.cables = CABLES.map((def) => {
      const n = def.kind === 'top' ? MAX_SEGS + 1 : MAX_LINKS;
      return { def, stage: 'hold' as Stage, t: 0, warnK: 0, warned: false, nodes: Array.from({ length: n }, () => new THREE.Vector3()), from: Array.from({ length: n }, () => new THREE.Vector3()), split: 0, bump: null, rub: null };
    });
  }

  /** 拍标本照 / 收掉 */
  detach(): void {
    for (const m of [this.ropes, this.clasps, this.links]) m.removeFromParent();
  }

  /**
   * 每帧（艇身姿态写好以后）：key(c) = 这一根现在离断还有几秒（负 = 已经过了；Infinity = 还没轮到它的时间轴），跨过 0 就断（一下跨过 2 秒以上 = 跳过去的，不演直接解开）；
   * hull(x) = 艇身在 x 处的截面；winch(x, out) = 锚链绞盘底下那一点；A = 艇中线离地
   */
  update(dt: number, q: 'high' | 'medium' | 'low', key: (c: CableDef) => number, hull: (x: number, out: HullSection) => void, winch: (x: number, out: THREE.Vector3) => void, A: number): void {
    this.clock += dt;
    this.q = q;
    this.fxT -= dt;
    const fx = this.fxT <= 0;
    if (fx) this.fxT = 0.1;
    let ri = 0;
    let ci = 0;
    let li = 0;
    const sec: HullSection = { y: 0, z: 0, r: 0 };
    for (const c of this.cables) {
      const d = c.def;
      if (c.stage === 'hold') {
        const left = key(d);
        c.warnK = left > 0 && left <= d.warn ? 1 - left / d.warn : 0;
        if (left <= d.warn && left > 0 && !c.warned) {
          c.warned = true;
          this.ev.warn(d, this.reachX(d));
        }
        if (left <= 0) {
          if (left < -2) c.stage = 'gone';
          else this.snap(c);
        }
      } else {
        c.t += dt;
        c.warnK = 0;
      }
      if (d.kind === 'top') {
        hull(d.x, sec);
        this.stepTop(c, sec, A, fx);
        ri = this.drawRope(c, ri);
        ci = this.drawClasps(c, ci);
      } else {
        winch(d.x, tw);
        this.stepAnchor(c, tw, fx);
        li = this.drawChain(c, li);
      }
    }
    this.ropes.instanceMatrix.needsUpdate = true;
    this.clasps.instanceMatrix.needsUpdate = true;
    this.links.instanceMatrix.needsUpdate = true;
    // 全解开了就不画（省 3 次绘制）
    const tops = this.cables.some((c) => c.def.kind === 'top' && c.stage !== 'gone');
    this.ropes.visible = this.clasps.visible = tops;
    this.links.visible = this.cables.some((c) => c.def.kind === 'anchor' && (c.stage === 'hold' || c.stage === 'snap'));
  }

  /** 缆鞭砸到路面最远那一头离路中心多远（世界横向，正 = 路右边；机库在路右边，临路墙外面 22 米） */
  reachX(d: CableDef): number {
    return 22 - (d.reach ?? 0);
  }

  private segs(): number {
    return CABLE.segs[this.q];
  }

  // -------------------------------------------------------------- 压顶缆

  private stepTop(c: Cable, sec: HullSection, A: number, fx: boolean): void {
    const N = this.segs();
    const nodes = c.nodes;
    const x = c.def.x;
    switch (c.stage) {
      case 'hold': {
        // 松垂 → 绷紧：艇顶低于墙顶时两墙之间垂下来搭在艇背上，艇中线升过 slack 那一段垂度收到 0，之后是压在艇背上的倒 V（越升越陡）
        const k = smooth((CABLE.slack[1] - A) / (CABLE.slack[1] - CABLE.slack[0]));
        this.topPath(sec, CABLE.sag * k, N);
        const shake = c.warnK > 0 ? CABLE.shake * Math.sin(this.clock * CABLE.hz * Math.PI * 2) * (0.6 + 0.4 * c.warnK) : 0;
        for (let i = 0; i <= N; i++) nodes[i].set(x + shake * Math.sin((Math.PI * i) / N), this.samp[i][1], this.samp[i][0]);
        // 预警：缆扣那头每 0.15 秒崩一簇火花，最后 0.5 秒喷白汽
        if (c.warnK > 0 && fx) {
          const end = c.def.mode === 'whip' ? nodes[N] : nodes[0];
          this.world(end, tv);
          this.ctx.fx.sparks(tv.x, tv.y, tv.z, Math.max(2, Math.round(6 * this.fxK)), 0xffc070, 6);
          if (c.warnK > 1 - 0.5 / c.def.warn && this.take(2)) this.ctx.fx.steam(tv.x, tv.y + 0.6, tv.z);
        }
        break;
      }
      case 'snap':
        if (c.def.mode === 'whip') this.whip(c, N, fx);
        else this.slide(c, sec, N, fx);
        break;
      case 'lie':
        // 躺在路上：最后那个姿态不动
        if (c.t >= CABLE.lie) this.next(c, 'reel');
        break;
      case 'reel':
        this.reel(c, N, fx);
        break;
      default:
        break;
    }
  }

  /**
   * 压在艇背上的形状（库里本地 (z, y)，写进 samp）：两头缆桩之间，艇背高过两桩连线时 = 两条切线 + 包住艇背的一段弧；
   * sag = 两段悬空的部分各往下垂多少（按段长折算），垂进艇身的推回艇身表面（搭在艇背上）
   */
  private topPath(sec: HullSection, sag: number, N: number): number {
    const [z0, y0] = this.p0;
    const [z1, y1] = this.p1;
    const { z: cz, y: cy, r: R } = sec;
    const span = z0 - z1;
    let t0z = z0;
    let t0y = y0;
    let t1z = z1;
    let t1y = y1;
    let th0 = 0;
    let th1 = 0;
    const touch = cy + R > Math.min(y0, y1) && cz < z0 && cz > z1 && Math.hypot(z0 - cz, y0 - cy) > R && Math.hypot(z1 - cz, y1 - cy) > R;
    if (touch) {
      const a0 = Math.atan2(y0 - cy, z0 - cz);
      th0 = a0 + Math.acos(R / Math.hypot(z0 - cz, y0 - cy));
      const a1 = Math.atan2(y1 - cy, z1 - cz);
      th1 = a1 - Math.acos(R / Math.hypot(z1 - cz, y1 - cy));
      while (th1 < th0) th1 += Math.PI * 2;
      if (th1 - th0 > Math.PI * 1.5) th1 = th0;
      t0z = cz + R * Math.cos(th0);
      t0y = cy + R * Math.sin(th0);
      t1z = cz + R * Math.cos(th1);
      t1y = cy + R * Math.sin(th1);
    }
    const L1 = touch ? Math.hypot(t0z - z0, t0y - y0) : span;
    const La = touch ? R * (th1 - th0) : 0;
    const L2 = touch ? Math.hypot(z1 - t1z, y1 - t1y) : 0;
    const L = L1 + La + L2;
    for (let i = 0; i <= N; i++) {
      const s = (L * i) / N;
      let pz: number;
      let py: number;
      if (s <= L1 || !touch) {
        const f = L1 > 0 ? Math.min(1, s / L1) : 0;
        const ez0 = touch ? t0z : z1;
        const ey0 = touch ? t0y : y1;
        pz = z0 + (ez0 - z0) * f;
        py = y0 + (ey0 - y0) * f - 4 * f * (1 - f) * sag * (L1 / span);
      } else if (s <= L1 + La) {
        const th = th0 + (s - L1) / R;
        pz = cz + R * Math.cos(th);
        py = cy + R * Math.sin(th);
      } else {
        const f = Math.min(1, (s - L1 - La) / L2);
        pz = t1z + (z1 - t1z) * f;
        py = t1y + (y1 - t1y) * f - 4 * f * (1 - f) * sag * (L2 / span);
      }
      // 垂进艇身的推回表面
      const dz = pz - cz;
      const dy = py - cy;
      const d = Math.hypot(dz, dy);
      if (d < R && d > 1e-3) {
        pz = cz + (dz / d) * R;
        py = cy + (dy / d) * R;
      }
      this.samp[i][0] = pz;
      this.samp[i][1] = py;
    }
    return L;
  }

  /** 断：拍下这一刻的形状，按断法演 */
  private snap(c: Cable): void {
    const d = c.def;
    c.stage = 'snap';
    c.t = 0;
    for (let i = 0; i < c.nodes.length; i++) c.from[i].copy(c.nodes[i]);
    const ctx = this.ctx;
    if (d.kind === 'top') {
      const N = this.segs();
      // 缆鞭从艇背最高那一点分开：前半截（绕临路墙缆桩翻过来的）重新分到 3/4 的节点上，后半截掉进库里
      if (d.mode === 'whip') this.resplit(c, N);
      // 缆扣炸开：火花 20 粒 + 小爆 + 金属碎块 3 块；临路墙那头的缆桩崩掉一角（砖石碎块 4 块）
      const end = d.mode === 'whip' ? c.nodes[N] : c.nodes[0];
      this.world(end, tv);
      ctx.fx.sparks(tv.x, tv.y, tv.z, 20, 0xffc070, 12);
      ctx.fx.explosion(tv.x, tv.z, 1.2, tv.y, false);
      ctx.debris.chunks(tv.x, tv.y, tv.z, 3, 'metal', 1);
      this.world(tw.set(d.x, CABLE.bollardY - 1, this.p0[0]), tv);
      ctx.debris.chunks(tv.x, tv.y, tv.z, 4, 'concrete', 0.9);
      ctx.audio.play('bigboom', 0.5, 1.3);
      ctx.audio.play('crunch', 0.8, 0.8);
    } else {
      // 锚链从绞盘脱开：绞盘那一下喷汽 + 火花，链子连响 1.5 秒
      this.world(c.nodes[0], tv);
      ctx.fx.sparks(tv.x, tv.y, tv.z, 16, 0xffc070, 10);
      ctx.fx.explosion(tv.x, tv.z, 1.4, tv.y, false);
      for (let i = 0; i < 6; i++) ctx.audio.play('chain', 0.9, 0.8 + i * 0.04, i * 0.25);
    }
    this.ev.snap(d);
  }

  /** 缆鞭断开那一刻：找艇背最高点（中间节点里最高的；没压在艇背上 = 正中），前半截按长度重新分到 0..k（k = 3/4 N）、后半截分到 k..N，写进 from */
  private resplit(c: Cable, N: number): void {
    const src = c.nodes.slice(0, N + 1).map((v) => v.clone());
    let hi = Math.round(N / 2);
    for (let i = 1; i < N; i++) if (src[i].y > src[hi].y + 0.2) hi = i;
    const cum = [0];
    for (let i = 1; i <= N; i++) cum.push(cum[i - 1] + src[i].distanceTo(src[i - 1]));
    const at = (s: number, out: THREE.Vector3) => {
      let j = 1;
      while (j < N && cum[j] < s) j++;
      const u = (s - cum[j - 1]) / Math.max(1e-6, cum[j] - cum[j - 1]);
      return out.lerpVectors(src[j - 1], src[j], clamp01(u));
    };
    const k = Math.max(2, Math.round(N * 0.75));
    const Lf = cum[hi];
    const L = cum[N];
    for (let j = 0; j <= N; j++) at(j <= k ? (Lf * j) / k : Lf + ((L - Lf) * (j - k)) / (N - k), c.from[j]);
    c.split = k;
  }

  /** 甩：前半截以临路墙缆桩为轴翻过来（根先动、梢后到，越甩越快），0.9 秒砸到路面成一条横跨路面的直线；后半截往库里掉 */
  private whip(c: Cable, N: number, fx: boolean): void {
    const d = c.def;
    const [z0, y0] = this.p0;
    const k = c.split;
    const reach = d.reach ?? 30;
    // 落地的样子：缆桩 → 翻过临路墙外沿 → 顺墙面垂下 → 贴着路面伸到 reach
    const drape: [number, number][] = [[z0, y0], [0.4, 8.3], [1.0, 0.35], [reach, 0.35]];
    const dl = [0];
    for (let i = 1; i < drape.length; i++) dl.push(dl[i - 1] + Math.hypot(drape[i][0] - drape[i - 1][0], drape[i][1] - drape[i - 1][1]));
    const total = dl[dl.length - 1];
    const lag = 0.35;
    const T = CABLE.whip;
    for (let i = 0; i <= k; i++) {
      const f = i / k;
      const from = c.from[i];
      // 最后的位置
      const s = f * total;
      let j = 1;
      while (j < drape.length - 1 && dl[j] < s) j++;
      const u = (s - dl[j - 1]) / Math.max(1e-6, dl[j] - dl[j - 1]);
      const fz = drape[j - 1][0] + (drape[j][0] - drape[j - 1][0]) * u;
      const fy = drape[j - 1][1] + (drape[j][1] - drape[j - 1][1]) * u;
      const e0 = clamp01((c.t - lag * f) / (T - lag));
      const e = e0 * e0;
      const pI = Math.atan2(from.y - y0, from.z - z0);
      let pF = Math.atan2(fy - y0, fz - z0);
      while (pF > pI) pF -= Math.PI * 2;
      const rI = Math.hypot(from.y - y0, from.z - z0);
      const rF = Math.hypot(fy - y0, fz - z0);
      const p = pI + (pF - pI) * e;
      const r = rI + (rF - rI) * e;
      c.nodes[i].set(d.x, Math.max(0.35, y0 + r * Math.sin(p)), z0 + r * Math.cos(p));
    }
    // 后半截：往后墙那边掉进库里（坑口以下看不见）
    for (let i = k + 1; i <= N; i++) {
      const from = c.from[i];
      c.nodes[i].set(d.x, from.y - 10 * c.t * c.t, from.z - 4 * c.t);
    }
    if (c.t >= T) {
      this.next(c, 'lie');
      this.slamFx(c, N);
      this.ev.slam(d);
    } else if (fx && c.t > T * 0.5) this.ctx.audio.play('gust', 0.4, 1.4);
  }

  /** 砸到路面：每 3 米一团扬尘 + 一声；躺地的软凸起（压过去车身一颠，不减速） */
  private slamFx(c: Cable, N: number): void {
    const ctx = this.ctx;
    const reach = c.def.reach ?? 30;
    for (let z = 1.5; z <= reach; z += 3) {
      this.world(tw.set(c.def.x, 0, z), tv);
      if (this.take(1.6)) ctx.fx.dust(tv.x, tv.z, 2.6, 0x9c8f78, 0.55);
    }
    ctx.audio.play('slam', 1, 0.7);
    ctx.audio.play('bigboom', 0.5, 0.9);
    ctx.shake(0.4);
    const a = this.world(tw.set(c.def.x, 0, 1.2), new THREE.Vector3());
    const b = this.world(tw.set(c.def.x, 0, reach), new THREE.Vector3());
    c.bump = ctx.world.addBump({ x: (a.x + b.x) / 2, z: (a.z + b.z) / 2, halfW: Math.abs(b.x - a.x) / 2, halfD: 0.9, rot: 0, h0: 0.9, h1: 0.45, soft: true, debris: 'metal' });
    void N;
  }

  /** 滑落：临路墙那头解扣，松开的那头先走、从艇背上滑下去（贴着装甲板一路冒火花），整根顺着后墙里侧垂进坑里 */
  private slide(c: Cable, sec: HullSection, N: number, fx: boolean): void {
    const d = c.def;
    const [z1, y1] = this.p1;
    let L = 0;
    for (let i = 1; i <= N; i++) L += c.from[i].distanceTo(c.from[i - 1]);
    let acc = 0;
    c.rub = null;
    for (let i = 0; i <= N; i++) {
      if (i > 0) acc += c.from[i].distanceTo(c.from[i - 1]);
      const left = L - acc;
      const hz = z1 + 1.4;
      const hy = y1 - left;
      const e = smooth((c.t - 0.5 * (acc / L)) / 0.7);
      let pz = c.from[i].z + (hz - c.from[i].z) * e;
      let py = c.from[i].y + (hy - c.from[i].y) * e;
      const dz = pz - sec.z;
      const dy = py - sec.y;
      const dd = Math.hypot(dz, dy);
      if (dd < sec.r && dd > 1e-3) {
        pz = sec.z + (dz / dd) * sec.r;
        py = sec.y + (dy / dd) * sec.r;
        if (e > 0.05 && e < 0.95) c.rub = c.nodes[i];
      }
      c.nodes[i].set(d.x, py, pz);
    }
    if (fx && c.rub && c.t < CABLE.slide) {
      this.world(c.rub, tv);
      this.ctx.fx.sparks(tv.x, tv.y, tv.z, Math.max(3, Math.round(8 * this.fxK)), 0xffc070, 8);
      if (Math.random() < 0.5) this.ctx.audio.play('crunch', 0.4, 0.75);
    }
    if (c.t >= CABLE.slide + 0.8) this.next(c, 'reel');
  }

  /** 收走：缆鞭被临路墙上的绞车拖回去（一路火花）；滑进库里的被后墙绞车收上去 */
  private reel(c: Cable, N: number, fx: boolean): void {
    const k = smooth(c.t / CABLE.reel);
    const whip = c.def.mode === 'whip';
    // 节点沿原来的形状往拴着的那头挪：缆鞭往缆桩（第 0 个）收，滑落的往后墙缆桩（最后一个）收
    for (let i = 0; i <= N; i++) {
      const f = whip ? i / N : 1 - i / N;
      const g = f - k;
      const src = g <= 0 ? 0 : g * N;
      const a = Math.floor(src);
      const b = Math.min(N, a + 1);
      const u = src - a;
      const ia = whip ? a : N - a;
      const ib = whip ? b : N - b;
      c.nodes[i].lerpVectors(c.from[ia], c.from[ib], u);
    }
    if (fx && whip && k < 0.98) {
      const tip = c.nodes[N];
      this.world(tip, tv);
      this.ctx.fx.sparks(tv.x, 0.4, tv.z, Math.max(2, Math.round(5 * this.fxK)), 0xffc070, 6);
    }
    if (c.t >= CABLE.reel) this.next(c, 'gone');
  }

  private next(c: Cable, s: Stage): void {
    if (s === 'reel') {
      for (let i = 0; i < c.nodes.length; i++) c.from[i].copy(c.nodes[i]);
      if (c.bump) {
        c.bump.alive = false;
        c.bump = null;
      }
      this.ctx.audio.play('hoist', 0.6, 0.9);
    }
    c.stage = s;
    c.t = 0;
  }

  // -------------------------------------------------------------- 锚链

  private stepAnchor(c: Cable, top: THREE.Vector3, fx: boolean): void {
    const n = CABLE.links[this.q];
    if (c.stage === 'hold') {
      // 竖着从艇腹绞盘垂进坑里；预警时绞盘冒汽、链环抖
      const j = c.warnK > 0 ? 0.15 * Math.sin(this.clock * CABLE.hz * Math.PI * 2) : 0;
      for (let i = 0; i < n; i++) c.nodes[i].set(top.x + j * (i % 2 ? 1 : -1), top.y - 1.6 - i * CABLE.link, top.z);
      if (c.warnK > 0 && fx && this.take(2)) {
        this.world(top, tv);
        this.ctx.fx.steam(tv.x + (Math.random() - 0.5) * 4, tv.y + 1, tv.z);
        this.ctx.fx.steam(tv.x + (Math.random() - 0.5) * 4, tv.y + 1, tv.z);
      }
      return;
    }
    if (c.stage !== 'snap') return;
    // 落坑：整条往下掉，坑里冲起一根灰白尘柱
    for (let i = 0; i < n; i++) c.nodes[i].set(c.from[i].x, c.from[i].y - 12.5 * c.t * c.t, c.from[i].z);
    if (fx && c.t < 1.2) {
      this.world(tw.set(c.from[0].x, 0, c.from[0].z), tv);
      const m = this.take(5);
      for (let i = 0; i < m; i++) this.ctx.fx.smokeP.emit({ x: tv.x + (Math.random() - 0.5) * 6, y: 1 + Math.random() * 2, z: tv.z + (Math.random() - 0.5) * 6, vx: (Math.random() - 0.5) * 2, vy: 12 + Math.random() * 10, vz: (Math.random() - 0.5) * 2, life: 2.8, size: 4, size1: 12, color: 0xc8c0b2, alpha: 0.5, frame: 1, drag: 0.6 });
    }
    if (c.t >= CABLE.drop) this.next(c, 'gone');
  }

  // -------------------------------------------------------------- 画

  private drawRope(c: Cable, i0: number): number {
    const N = this.segs();
    const vis = c.stage !== 'gone';
    for (let i = 0; i < MAX_SEGS; i++) {
      const idx = i0 + i;
      if (!vis || i >= N) {
        this.ropes.setMatrixAt(idx, HIDE);
        continue;
      }
      const a = c.nodes[i];
      const b = c.nodes[i + 1];
      // 掉进坑口以下的、收进缆桩的不画
      const len = a.distanceTo(b);
      if (len < 0.05 || (a.y < -1 && b.y < -1)) {
        this.ropes.setMatrixAt(idx, HIDE);
        continue;
      }
      ex.subVectors(b, a).divideScalar(len);
      ez.set(1, 0, 0);
      ey.crossVectors(ez, ex);
      if (ey.lengthSq() < 1e-6) ey.set(0, 1, 0);
      ey.normalize();
      ez.crossVectors(ex, ey).normalize();
      mA.makeBasis(ex, ey, ez);
      qA.setFromRotationMatrix(mA);
      mA.compose(a, qA, sA.set(len + 0.05, 1, 1));
      this.ropes.setMatrixAt(idx, mA);
    }
    return i0 + MAX_SEGS;
  }

  /** 缆扣：拴着的那头留着，解扣（炸开）的那头不画；缆收走了一起收 */
  private drawClasps(c: Cable, i0: number): number {
    const N = this.segs();
    const whip = c.def.mode === 'whip';
    const ends: [THREE.Vector3, boolean][] = [
      [c.nodes[0], c.stage === 'hold' || (whip && c.stage !== 'gone')],
      [c.nodes[N], c.stage === 'hold' || (!whip && c.stage !== 'gone')],
    ];
    ends.forEach(([p, on], k) => {
      if (!on) {
        this.clasps.setMatrixAt(i0 + k, HIDE);
        return;
      }
      tv.set(c.def.x, this.p0[1], k ? this.p1[0] : this.p0[0]);
      mA.compose(c.stage === 'hold' ? p : tv, qA.identity(), sA.set(1, 1, 1));
      this.clasps.setMatrixAt(i0 + k, mA);
    });
    return i0 + 2;
  }

  private drawChain(c: Cable, i0: number): number {
    const n = CABLE.links[this.q];
    const vis = c.stage === 'hold' || c.stage === 'snap';
    for (let i = 0; i < MAX_LINKS; i++) {
      const p = c.nodes[i];
      if (!vis || i >= n || p.y < -1.6) {
        this.links.setMatrixAt(i0 + i, HIDE);
        continue;
      }
      mA.compose(p, qA.setFromAxisAngle(ey.set(0, 1, 0), i % 2 ? Math.PI / 2 : 0), sA.set(1, 1, 1));
      this.links.setMatrixAt(i0 + i, mA);
    }
    return i0 + MAX_LINKS;
  }

  /** 库里本地 → 世界 */
  private world(p: THREE.Vector3, out: THREE.Vector3): THREE.Vector3 {
    return this.root.localToWorld(out.copy(p));
  }

  private get fxK(): number {
    return this.q === 'high' ? 1 : this.q === 'medium' ? 0.6 : 0.35;
  }

  /** 这一根还拴着没有（hold） */
  holding(id: CableDef['id']): boolean {
    return this.cables.find((c) => c.def.id === id)?.stage === 'hold';
  }
}

