import * as THREE from 'three';
import { GeoCache, type PartSpec } from '../assets/GeoCache';
import { createCanvas } from '../ui/canvas/Overlay';
import { sharedMetalNormal } from './sharedTextures';

/** 开始页独立的钢铁整备库。道具只含建筑、灯具与检修设施。 */
export function buildTurntableBackdrop(geo: GeoCache) {
  const group = new THREE.Group();
  group.name = 'turntable-workshop';
  // 车照旧绕世界原点旋转；库房正对原来的三分之四机位。
  group.rotation.y = Math.atan2(0.76, 1);
  const materials = new Set<THREE.Material>();
  const textures = new Set<THREE.Texture>();
  const add = (g: THREE.BufferGeometry, m: THREE.Material, name: string) => {
    const mesh = new THREE.Mesh(g, m);
    mesh.name = name;
    group.add(mesh); materials.add(m);
    return mesh;
  };
  const { ground, floorMap } = buildTurntableFloor();
  textures.add(floorMap);
  materials.add(ground.material);
  group.add(ground);
  const structure = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.8, metalness: 0.38 });
  add(geo.merged('turntable-workshop-structure', () => {
    const p: PartSpec[] = [];
    const box = (w: number, h: number, d: number, x: number, y: number, z: number, color: number, roll = 0) =>
      p.push({ geo: new THREE.BoxGeometry(w, h, d), color, pos: [x, y, z], rot: [0, 0, roll] });
    // 后墙与卷门有前后层次，轮廓不贴着车辆边缘。
    box(37, 14, 0.45, 0, 6.8, 13.1, 0x1b292e);
    box(12.4, 7.5, 0.2, 0, 3.65, 12.68, 0x25353b);
    for (let i = 0; i < 12; i++) {
      box(12.2, 0.46, 0.12, 0, 0.18 + i * 0.59, 12.5, i % 3 ? 0x2b3b41 : 0x2f4045);
      box(12.2, 0.038, 0.18, 0, 0.38 + i * 0.59, 12.42, 0x3a4a4d);
    }
    box(0.06, 7.2, 0.1, 0, 3.5, 12.33, 0x152328);
    for (const s of [-1, 1]) {
      box(0.42, 7.7, 0.65, s * 6.4, 3.7, 12.18, 0x3b4b4e);
      // 工字柱、底板、三角撑板与横梁；零件统一合并。
      for (const z of [7.7, 12.1]) {
        box(0.24, 10.2, 0.65, s * 8.0, 4.9, z, 0x334449);
        for (const f of [-1, 1]) box(0.76, 10.2, 0.1, s * 8.0, 4.9, z + f * 0.33, 0x3d4e51);
        box(1.08, 0.25, 1.1, s * 8.0, -0.03, z, 0x323d40);
        box(0.22, 2.9, 0.25, s * 7.0, 8.3, z, 0x34464b, -s * 0.72);
        // 柱脚的暗橙检修标线。
        for (let i = 0; i < 4; i++) box(0.66, 0.16, 0.04, s * 8.0, 0.3 + i * 0.34, z - 0.4, 0x816743, s * 0.32);
      }
      // 两边的检修柜、百叶与管线，中央留给车。
      box(3.1, 3.0, 1.2, s * 10.15, 1.3, 11.5, 0x2a383c);
      box(2.82, 2.68, 0.1, s * 10.15, 1.3, 10.84, 0x36464a);
      box(0.08, 2.68, 0.12, s * 10.15, 1.3, 10.76, 0x1b292d);
      for (let i = 0; i < 8; i++) box(2.3, 0.045, 0.18, s * 10.15, 1.1 + i * 0.16, 10.7, 0x202f34);
      p.push({ geo: new THREE.CylinderGeometry(0.11, 0.11, 6.0, 8), color: 0x4d5a58, pos: [s * 11.95, 3.0, 12] });
      for (const y of [0.7, 2.8, 5.2]) box(0.38, 0.12, 0.24, s * 11.95, y, 12.04, 0x616a62);
      // 地面检修线与排水槽在转盘外侧。
      box(0.09, 0.015, 24, s * 7.35, -0.19, 2.5, 0x75694c);
      box(0.32, 0.02, 18, s * 9, -0.18, 2.5, 0x162326);
      for (let i = 0; i < 20; i++) box(0.3, 0.025, 0.055, s * 9, -0.16, -5.5 + i * 0.8, 0x374449);
    }
    for (const z of [7.7, 12.1]) {
      box(16.9, 0.16, 0.85, 0, 9.95, z, 0x465453);
      box(16.9, 0.72, 0.17, 0, 9.5, z, 0x2c3b40);
      box(16.9, 0.16, 0.85, 0, 9.08, z, 0x3c4c50);
      for (let i = -7; i <= 7; i += 2) box(0.10, 1.1, 0.15, i, 9.5, z - 0.2, 0x4d5c5d, Math.PI / 4);
    }
    // 顶部检修灯的防护罩与支臂。
    box(2.0, 0.24, 0.68, -4.5, 7.4, 11.8, 0x4c5858);
    box(0.16, 1.45, 0.16, -4.5, 8.16, 12.0, 0x3b4a4e);
    box(13.1, 0.25, 0.66, 0, 7.56, 12.14, 0x394b50);
    return p;
  }), structure, 'workshop-steel');
  const lights = new THREE.MeshBasicMaterial({ vertexColors: true, toneMapped: false });
  add(geo.merged('turntable-workshop-lamps', () => {
    const p: PartSpec[] = [];
    for (const s of [-1, 1]) {
      p.push({ geo: new THREE.BoxGeometry(0.10, 3.5, 0.08), color: 0x8caaa9, pos: [s * 6.13, 5.1, 12.05] });
      for (const x of [9.4, 10.9]) {
        p.push({ geo: new THREE.BoxGeometry(0.26, 0.06, 0.04), color: 0x8e754d, pos: [s * x, 0.82, 10.61] });
      }
    }
    p.push({ geo: new THREE.BoxGeometry(1.64, 0.06, 0.44), color: 0xb8ab87, pos: [-4.5, 7.26, 11.79] });
    return p;
  }), lights, 'workshop-lamps');
  // 只有后墙上的光斑缓慢移动。没有额外实时灯、阴影或全屏叠色。
  const clock = { value: 0 };
  const sweep = new THREE.ShaderMaterial({
    uniforms: { clock },
    transparent: true, depthWrite: false, side: THREE.DoubleSide, toneMapped: false,
    vertexShader: 'varying vec2 vUv; void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',
    fragmentShader: `
      uniform float clock;
      varying vec2 vUv;
      void main() {
        float down = 1.0 - vUv.y;
        float center = .16 + down * (.32 + sin(clock * .18) * .12);
        float width = .014 + down * .16;
        float beam = 1.0 - smoothstep(width * .38, width, abs(vUv.x - center));
        float ends = smoothstep(0., .1, vUv.y) * smoothstep(0., .06, down);
        gl_FragColor = vec4(.45, .53, .51, beam * ends * .13);
      }`,
  });
  const wash = add(new THREE.PlaneGeometry(12.0, 7.0), sweep, 'workshop-sweep');
  wash.position.set(0, 3.65, 12.21);
  return { group, materials, textures, update: (time: number) => { clock.value = time; } };
}

/**
 * T183 默认：开阔展场（参照战车 360° 预览页的空间）。四周不设墙，镜头绕车一整圈都不穿模；
 * 大块水泥地坪带接缝，转动时有远近参照，远处融进雾色。
 */
export function buildShowroomBackdrop() {
  const group = new THREE.Group();
  group.name = 'turntable-showroom';
  const c = createCanvas();
  c.width = c.height = 256;
  const ctx = c.getContext('2d')!;
  ctx.fillStyle = '#353d40'; ctx.fillRect(0, 0, 256, 256);
  let seed = 18311;
  const rand = () => ((seed = Math.imul(seed, 1664525) + 1013904223 | 0) >>> 0) / 4294967296;
  for (let i = 0; i < 2600; i++) {
    ctx.fillStyle = i % 2 ? '#10191c12' : '#b5c2b80a';
    ctx.fillRect(rand() * 256, rand() * 256, 1 + rand() * 5, 1);
  }
  for (let i = 0; i < 4; i++) {
    const g = ctx.createRadialGradient(0, 0, 0, 0, 0, 1);
    g.addColorStop(0, '#1a222510'); g.addColorStop(1, '#1a222500');
    ctx.save(); ctx.translate(rand() * 256, rand() * 256); ctx.scale(30 + rand() * 50, 20 + rand() * 40);
    ctx.fillStyle = g; ctx.beginPath(); ctx.arc(0, 0, 1, 0, Math.PI * 2); ctx.fill(); ctx.restore();
  }
  // 一张图 = 2×2 块 4 米地坪；接缝一暗一亮
  ctx.fillStyle = '#1d272a';
  for (const v of [0, 128]) { ctx.fillRect(v, 0, 2, 256); ctx.fillRect(0, v, 256, 2); }
  ctx.fillStyle = '#4a5457';
  for (const v of [2, 130]) { ctx.fillRect(v, 0, 1, 256); ctx.fillRect(0, v, 256, 1); }
  const floorMap = new THREE.CanvasTexture(c);
  floorMap.colorSpace = THREE.SRGBColorSpace;
  floorMap.wrapS = floorMap.wrapT = THREE.RepeatWrapping;
  floorMap.anisotropy = 4;
  const R = 180;
  floorMap.repeat.set(R * 2 / 8, R * 2 / 8);
  const floor = new THREE.MeshStandardMaterial({
    color: 0x8a9496, map: floorMap, roughness: 0.9, metalness: 0.08,
    normalMap: sharedMetalNormal(), normalScale: new THREE.Vector2(0.02, 0.02),
  });
  const ground = new THREE.Mesh(new THREE.CircleGeometry(R, 72), floor);
  ground.name = 'showroom-floor';
  ground.rotation.x = -Math.PI / 2;
  ground.position.y = -0.21;
  ground.receiveShadow = true;
  group.add(ground);
  return {
    group, materials: new Set<THREE.Material>([floor]), textures: new Set<THREE.Texture>([floorMap]),
    update: (_time: number) => {}, sky: new THREE.Color(0x1a2326), fog: [48, 150] as [number, number],
  };
}

/** 三套候选沿用同一块地面，尺寸与材质不随方案变化。 */
export function buildTurntableFloor() {
  const floorMap = floorTexture();
  const floor = new THREE.MeshStandardMaterial({
    color: 0x454e4f, map: floorMap, roughness: 0.94, metalness: 0.12,
    normalMap: sharedMetalNormal(), normalScale: new THREE.Vector2(0.025, 0.025),
  });
  const ground = new THREE.Mesh(new THREE.PlaneGeometry(140, 140), floor);
  ground.name = 'workshop-floor';
  ground.rotation.x = -Math.PI / 2;
  ground.position.y = -0.21;
  ground.receiveShadow = true;
  return { ground, floorMap };
}

function floorTexture(): THREE.CanvasTexture {
  const c = createCanvas();
  c.width = c.height = 256;
  const ctx = c.getContext('2d')!;
  ctx.fillStyle = '#3a4649'; ctx.fillRect(0, 0, 256, 256);
  let seed = 12012;
  const rand = () => ((seed = Math.imul(seed, 1664525) + 1013904223 | 0) >>> 0) / 4294967296;
  for (let i = 0; i < 1800; i++) {
    ctx.fillStyle = i % 2 ? '#111c2014' : '#aab8ae0a';
    ctx.fillRect(rand() * 256, rand() * 256, 1 + rand() * 4, 1);
  }
  ctx.strokeStyle = '#202d30'; ctx.lineWidth = 1;
  ctx.strokeRect(1, 1, 254, 254);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(28, 28);
  return t;
}
