/**
 * 车漆件按米重铺 UV（T164）：每个三角形按朝向投到 xz / zy / xy 平面，大板和小件上的斑块一样大、跨折角连续；
 * 朝上的面顶点色提亮一档（顶光读形）。几何体有缓存，标过就跳过。
 * k = 几何体放大倍数（T177：副武器挂件按 1.5～1.95 倍放大挂上车，UV 先乘上，斑块和车身一样大）
 */
export function paintUV(g: THREE.BufferGeometry, lift = 1.06, k = 1): THREE.BufferGeometry {
  if (g.userData.paintUV || g.index) return g;
  g.userData.paintUV = true;
  const p = g.getAttribute('position');
  const uv = g.getAttribute('uv');
  const col = g.getAttribute('color');
  if (!uv) return g;
  const a = new THREE.Vector3(), b = new THREE.Vector3(), c = new THREE.Vector3();
  for (let i = 0; i + 2 < p.count; i += 3) {
    a.fromBufferAttribute(p, i);
    b.fromBufferAttribute(p, i + 1).sub(a);
    c.fromBufferAttribute(p, i + 2).sub(a);
    const n = b.cross(c).normalize();
    const ax = Math.abs(n.x), ay = Math.abs(n.y), az = Math.abs(n.z);
    for (let j = i; j < i + 3; j++) {
      const x = p.getX(j) * k, y = p.getY(j) * k, z = p.getZ(j) * k;
      if (ay >= ax && ay >= az) uv.setXY(j, x, z);
      else if (ax >= az) uv.setXY(j, z, y);
      else uv.setXY(j, x, y);
      if (col && n.y > 0.7) col.setXYZ(j, col.getX(j) * lift, col.getY(j) * lift, col.getZ(j) * lift);
    }
  }
  uv.needsUpdate = true;
  if (col) col.needsUpdate = true;
  return g;
}

/**
 * 轮子刷车漆（T175）：先按米铺 UV，再把整只轮子缩 0.6 倍挪到默认迷彩图里一块纯底色的地方（贴图像素 (58, 116) 附近半径 16 像素都是底色），
 * 轮子看着是整片橄榄底漆 + 灰尘，不会正好压上一大块土黄斑变成黄轮子；换车库涂装时一样跟着变
 */
const WHEEL_UV: [number, number] = [(58.5 / 256) * 6, (116.5 / 256) * 6];
function wheelPaint(g: THREE.BufferGeometry): THREE.BufferGeometry {
  if (g.userData.wheelUV) return g;
  paintUV(g);
  g.userData.wheelUV = true;
  const uv = g.getAttribute('uv');
  for (let i = 0; i < uv.count; i++) uv.setXY(i, WHEEL_UV[0] + uv.getX(i) * 0.6, WHEEL_UV[1] + uv.getY(i) * 0.6);
  uv.needsUpdate = true;
  return g;
}

/** 挂在子节点上的车漆件（炮管、发射舱，T172）：按它在父件坐标里的位置 at 铺迷彩，斑块接着炮塔走，左右两件不再取同一块 */
function paintUVAt(g: THREE.BufferGeometry, at: [number, number, number]): THREE.BufferGeometry {
  if (g.userData.paintUV) return g;
  g.translate(...at);
  paintUV(g);
  return g.translate(-at[0], -at[1], -at[2]);
}

/** 一个组里所有车漆件按米铺迷彩 */
function paintBody(group: THREE.Object3D, body: THREE.Material): void {
  group.traverse((o) => {
    const m = o as THREE.Mesh;
    if (m.isMesh && m.material === body) paintUV(m.geometry);
  });
}

/** 首上装甲（倾斜 28°）上的点：f = 从下沿往上的比例，h = 离板面的高度 */
const GLACIS_TILT = -Math.atan2(0.7, 1.3);
function glacis(f: number, x: number, h: number): [number, number, number] {
  const k = h + 0.06;
  return [x, 1.3 + f * 0.7 + k * 0.881, -3.35 + f * 1.3 - k * 0.474];
}
/** 车尾斜甲板（往后下斜 0.47 弧度）上的点：z 处、离板面 h */
const REAR_TILT = Math.atan2(0.38, 0.75);
/**
 * 炮塔座圈间隙（T175）：四种炮塔的底面都从炮塔组 y = 0 抬到这个高度（炮塔组原点、挂点、炮口一个没动）。
 * 车顶甲板实际在 y = 0.06（上车体拉伸带 6 厘米倒角），T172 及以前炮塔底面在 0，等于炮塔下沿埋进甲板 6 厘米，转起来要切过甲板上的舱盖、格栅、拖缆。
 * 抬到 0.16 以后炮塔底和甲板之间空出 10 厘米，中间露出深色座圈；甲板上炮塔扫得到的东西都压到 2.13 以下
 */
export const TURRET_GAP = 0.16;
/**
 * 火箭发射舱整体抬高（T175）：发射舱抬头 0.22 弧度挂在炮塔两侧，屁股下沿原来只比甲板高 -1～+1 厘米，转起来贴着甲板、压过检修盖和舱盖。
 * 抬 0.12 米后下沿在 2.16 以上；炮口跟着发射舱走（同样抬 0.12），火箭是抛射，出膛点高一点不影响落点和判定
 */
const POD_LIFT = 0.12;
/**
 * 车尾挂点（T177，3 / 5 号，x 取正）：原来 (±0.95, 2.06, 2.6) 在甲板内侧、紧挨炮塔尾舱；挪到车尾两角的平台上。
 * 再往外（试过 2.1）挂件更靠炮管转到车尾那条路的外沿，T127 转身限位窄得多；1.8 又会蹭到主炮炮塔尾舱两侧的储物箱。1.95 是两头的折中
 */
export const REAR_SEAT: [number, number, number] = [1.95, 1.95, 2.8];
function rearDeck(z: number, x: number, h: number): [number, number, number] {
  const y = 2.06 - ((z - 2.5) / 0.75) * 0.38;
  return [x, y + h * 0.892, z + h * 0.452];
}
/** 带盖板的箱子：箱体 + 稍大一圈的盖 */
function lidBox(w: number, h: number, d: number, color: number, pos: [number, number, number], rot: [number, number, number] = [0, 0, 0]): PartSpec[] {
  const m = new THREE.Matrix4().makeRotationFromEuler(new THREE.Euler(...rot));
  const up = new THREE.Vector3(0, h / 2, 0).applyMatrix4(m);
  return [
    { geo: bevelBox(w, h, d, 0.025), color, pos, rot },
    { geo: bevelBox(w + 0.04, 0.05, d + 0.04, 0.015), color: color - 0x0a0a0a, pos: [pos[0] + up.x, pos[1] + up.y, pos[2] + up.z], rot },
  ];
}
/** 油桶（方形野战油桶）：桶身 + 加油口 + 提手 */
function jerryCan(pos: [number, number, number], rot: [number, number, number] = [0, 0, 0]): PartSpec[] {
  const [x, y, z] = pos;
  return [
    { geo: bevelBox(0.16, 0.46, 0.34, 0.035), color: 0x55603e, pos, rot },
    { geo: new THREE.CylinderGeometry(0.035, 0.035, 0.06, 8), color: DARK, pos: [x, y + 0.25, z - 0.1], rot },
    { geo: bevelBox(0.05, 0.05, 0.16, 0.01), color: 0x45503a, pos: [x, y + 0.25, z + 0.06], rot },
  ];
}

/**
 * 炮塔挂点托架（T177，替换 T164 的圆形钢座圈）：副武器的方形转接板坐在一块车漆托架上，托架顶面 = 挂点高度（比炮塔顶高 6 厘米，露出一圈板边），
 * 块体往下收进炮塔；挂点伸出炮塔边的部分，外沿底下一道斜撑一直接到炮塔侧壁（wall = 侧壁上、下两个点的 [半宽, 高度]），看着是焊在炮塔上的耳座，不是摆上去的圆盘。
 * 并进炮塔车漆网格，不加绘制次数
 */
function turretPad(at: [number, number, number], wall: [[number, number], [number, number]], size = 1.15, depth = 0.3): PartSpec[] {
  const [x, y, z] = at;
  const s = Math.sign(x);
  const ax = Math.abs(x);
  const [[wx0, wy0], [wx1, wy1]] = wall;
  const wallX = (yy: number) => wx0 + ((wy0 - yy) * (wx1 - wx0)) / (wy0 - wy1);
  const xi = ax - size / 2, xo = ax + size / 2;
  // 斜撑：外沿往下 0.1 起，按 1 : 1.1 的坡落到侧壁上（最低落到 wall 的下点）；没伸出炮塔边就是一块平底的块
  const yg = Math.max(wy1, y - 0.1 - Math.max(0, xo - wallX(y)) * 1.1);
  const yb = Math.min(y - depth, yg);
  const prof: [number, number][] = [[xi, yb], [Math.min(xo, wallX(yb) - 0.02), yb], [xo, y - 0.1], [xo, y - 0.025], [xo - 0.025, y], [xi + 0.025, y], [xi, y - 0.025]];
  const shape = new THREE.Shape(prof.map(([px, py]) => new THREE.Vector2(s * px, py)));
  const block = new THREE.ExtrudeGeometry(shape, { depth: size, bevelEnabled: false });
  block.translate(0, 0, -size / 2);
  const bolts = [-1, 1].flatMap((i) => [-1, 1].map((k): PartSpec => ({ geo: new THREE.CylinderGeometry(0.035, 0.035, 0.03, 8), color: DARK, pos: [x + i * (size / 2 - 0.08), y + 0.01, z + k * (size / 2 - 0.08)] })));
  return [
    { geo: block, color: OLIVE_D, pos: [0, 0, z] },
    // 外沿一道加强筋 + 四颗螺栓
    { geo: bevelBox(0.05, 0.08, size - 0.1, 0.015), color: OLIVE_D, pos: [s * (xo - 0.03), y - 0.065, z] },
    ...bolts,
  ];
}
/** 炮塔挂点比炮塔顶面抬高的量（T177：托架顶板露出来） */
const PAD_LIFT = 0.06;

/** 车长塔：塔身 + 底环 + 一圈观察窗（带遮檐）+ 掀开的舱盖；k = 尺寸倍数 */
function cupola(x: number, y: number, z: number, k = 1, color = OLIVE_D): PartSpec[] {
  const r = 0.4 * k;
  const p: PartSpec[] = [
    { geo: new THREE.CylinderGeometry(r, r * 1.1, 0.36 * k, 20), color, pos: [x, y, z] },
    { geo: new THREE.CylinderGeometry(r * 1.2, r * 1.25, 0.07, 20), color, pos: [x, y - 0.17 * k, z] },
    { geo: new THREE.CylinderGeometry(r * 0.92, r * 0.92, 0.05, 20), color: DARK, pos: [x, y + 0.2 * k, z] },
    // 掀开的舱盖 + 铰链
    { geo: new THREE.CylinderGeometry(r * 0.88, r * 0.88, 0.06, 20), color, pos: [x, y + 0.42 * k, z + r * 0.5], rot: [-0.9, 0, 0] },
    { geo: new THREE.CylinderGeometry(0.05, 0.05, 0.3 * k, 8), color: DARK, pos: [x, y + 0.22 * k, z + r * 0.92], rot: [0, 0, Math.PI / 2] },
  ];
  for (let i = 0; i < 7; i++) {
    const a = Math.PI * 0.62 + (i / 6) * Math.PI * 1.76;
    const cx = x + Math.cos(a) * r * 0.98, cz = z + Math.sin(a) * r * 0.98;
    p.push({ geo: new THREE.BoxGeometry(0.17 * k, 0.11 * k, 0.07), color: GLASS, pos: [cx, y + 0.04 * k, cz], rot: [0, -a + Math.PI / 2, 0] });
    p.push({ geo: new THREE.BoxGeometry(0.22 * k, 0.035, 0.12), color, pos: [cx + Math.cos(a) * 0.03, y + 0.12 * k, cz + Math.sin(a) * 0.03], rot: [0, -a + Math.PI / 2, 0] });
  }
  return p;
}

