/** 一侧三联烟幕弹发射器：底板 + 三根筒（朝外、朝前上） */
function smoke(x: number, y: number, z: number, s: number, yaw = 0.5): PartSpec[] {
  const p: PartSpec[] = [{ geo: bevelBox(0.3, 0.1, 0.5, 0.02), color: DARK, pos: [x, y - 0.09, z + 0.18] }];
  for (let k = 0; k < 3; k++) p.push({ geo: new THREE.CylinderGeometry(0.065, 0.065, 0.32, 12), color: DARK, pos: [x + s * k * 0.05, y, z + k * 0.17], rot: [Math.PI / 2 - 0.4, s * yaw, 0] });
  return p;
}

/** 尾舱顶的置物架：四周护栏（立柱 + 上横杆）+ 篷布卷 + 弹药箱；stow = false 只留护栏 */
function roofRack(x0: number, x1: number, z0: number, z1: number, y: number, stow: boolean, h = 0.2): PartSpec[] {
  const c = 0x40453f, r = 0.026;
  const p: PartSpec[] = [];
  const corners: [number, number][] = [[x0, z0], [x1, z0], [x1, z1], [x0, z1]];
  corners.forEach(([x, z], i) => {
    const [nx, nz] = corners[(i + 1) % 4];
    p.push({ geo: tube([x, y, z], [x, y + h, z], r), color: c });
    p.push({ geo: tube([x, y + h, z], [nx, y + h, nz], r), color: c });
  });
  for (const x of [x0 + (x1 - x0) / 3, x0 + (2 * (x1 - x0)) / 3]) p.push({ geo: tube([x, y + h, z0], [x, y, z0], r), color: c }, { geo: tube([x, y + h, z1], [x, y, z1], r), color: c });
  p.push({ geo: new THREE.BoxGeometry(x1 - x0, 0.03, z1 - z0), color: 0x34382f, pos: [(x0 + x1) / 2, y + 0.015, (z0 + z1) / 2] });
  if (stow) {
    const w = (x1 - x0) * 0.82;
    p.push(
      { geo: new THREE.CylinderGeometry(0.14, 0.14, w, 14), color: CANVAS, pos: [(x0 + x1) / 2, y + 0.16, z1 - 0.22], rot: [0, 0, Math.PI / 2] },
      ...[-0.32, 0.32].map((f): PartSpec => ({ geo: new THREE.TorusGeometry(0.145, 0.022, 4, 14), color: 0x2e2a22, pos: [(x0 + x1) / 2 + f * w, y + 0.16, z1 - 0.22], rot: [0, Math.PI / 2, 0] })),
      ...lidBox(0.5, 0.22, 0.34, CRATE, [x0 + 0.4, y + 0.13, z0 + 0.3]),
      ...lidBox(0.4, 0.2, 0.3, 0x5c5236, [x1 - 0.35, y + 0.12, z0 + 0.3]),
    );
  }
  return p;
}

/** 炮塔侧壁挂的备用链板：n 节竖着挂，s = 哪一侧（链板外面朝外），z0 = 第一节的位置，往后排 */
function sideLinks(geo: GeoCache, x: number, y: number, z0: number, s: number, n: number, dz = 0.36): PartSpec[] {
  const rot = new THREE.Euler().setFromRotationMatrix(new THREE.Matrix4().makeBasis(new THREE.Vector3(0, 0, s), new THREE.Vector3(s, 0, 0), new THREE.Vector3(0, 1, 0)));
  const r: [number, number, number] = [rot.x, rot.y, rot.z];
  const p: PartSpec[] = [];
  for (let i = 0; i < n; i++) p.push({ geo: geo.merged('pt-link-hang', () => linkParts(true)).clone(), color: DARK, pos: [x, y, z0 + i * dz], rot: r });
  // 挂杆
  p.push({ geo: bevelBox(0.06, 0.06, n * dz + 0.1, 0.012), color: 0x4a4e50, pos: [x + s * 0.06, y + 0.12, z0 + ((n - 1) * dz) / 2] });
  return p;
}

/** 舱盖上的防空机枪：枢轴座 + 机匣 + 枪管（带散热套）+ 弹箱 + 小护盾；朝前 */
function aaGun(x: number, y: number, z: number): PartSpec[] {
  return [
    { geo: new THREE.CylinderGeometry(0.035, 0.05, 0.36, 8), color: DARK, pos: [x, y + 0.18, z] },
    { geo: bevelBox(0.13, 0.15, 0.55, 0.025), color: 0x2a2c2e, pos: [x, y + 0.42, z - 0.05] },
    { geo: new THREE.CylinderGeometry(0.045, 0.045, 0.5, 12), color: 0x3a3c3e, pos: [x, y + 0.43, z - 0.55], rot: [Math.PI / 2, 0, 0] },
    { geo: new THREE.CylinderGeometry(0.025, 0.025, 0.42, 8), color: 0x1e1e1e, pos: [x, y + 0.43, z - 1.0], rot: [Math.PI / 2, 0, 0] },
    { geo: bevelBox(0.14, 0.18, 0.24, 0.02), color: 0x55603e, pos: [x + 0.14, y + 0.36, z] },
    { geo: bevelBox(0.44, 0.3, 0.035, 0.01), color: OLIVE_D, pos: [x, y + 0.46, z - 0.32] },
  ];
}

/** 探照灯（红外灯）：灯座 + 灯筒 + 镜片 + 遮光百叶 */
function searchlight(x: number, y: number, z: number): PartSpec[] {
  return [
    { geo: bevelBox(0.16, 0.1, 0.2, 0.02), color: DARK, pos: [x, y, z] },
    { geo: new THREE.CylinderGeometry(0.17, 0.19, 0.32, 16), color: OLIVE_D, pos: [x, y + 0.2, z], rot: [Math.PI / 2, 0, 0] },
    { geo: new THREE.CylinderGeometry(0.15, 0.15, 0.02, 16), color: 0x8a9aa0, pos: [x, y + 0.2, z - 0.165], rot: [Math.PI / 2, 0, 0] },
    ...[-0.07, 0, 0.07].map((dy): PartSpec => ({ geo: new THREE.BoxGeometry(0.3, 0.015, 0.03), color: DARK, pos: [x, y + 0.2 + dy, z - 0.18] })),
  ];
}

/** 体视测距仪：横贯炮塔的长筒 + 两头装甲镜罩（带镜片）+ 中间两个托座 */
function rangefinder(x: number, y: number, z: number, span: number): PartSpec[] {
  return [
    { geo: new THREE.CylinderGeometry(0.07, 0.07, span, 14), color: OLIVE_D, pos: [x, y, z], rot: [0, 0, Math.PI / 2] },
    ...[-1, 1].flatMap((s): PartSpec[] => [
      { geo: new THREE.SphereGeometry(0.15, 14, 8), color: OLIVE_D, pos: [x + s * span / 2, y, z] },
      { geo: new THREE.CylinderGeometry(0.06, 0.06, 0.03, 12), color: GLASS, pos: [x + s * span / 2, y, z - 0.14], rot: [Math.PI / 2, 0, 0] },
      { geo: bevelBox(0.12, 0.16, 0.14, 0.02), color: DARK, pos: [x + s * span * 0.22, y - 0.1, z] },
    ]),
  ];
}

/** 炮塔侧面扶手（一根管 + 两个脚） */
function grabRail(x: number, y: number, z0: number, z1: number): PartSpec[] {
  return [
    { geo: tube([x, y, z0], [x, y, z1], 0.025), color: 0x40453f },
    { geo: tube([x, y, z0], [x * 0.96, y - 0.1, z0], 0.025), color: 0x40453f },
    { geo: tube([x, y, z1], [x * 0.96, y - 0.1, z1], 0.025), color: 0x40453f },
  ];
}

export function buildPlayerTank(geo: GeoCache): PlayerTankModel {
  const normal = sharedMetalNormal();
  const body = new THREE.MeshStandardMaterial({
    vertexColors: true,
    map: playerPaint(PLAYER_PAINT.colors, PLAYER_PAINT.seed),
    normalMap: normal,
    normalScale: new THREE.Vector2(0.5, 0.5),
    roughness: 0.66,
    metalness: 0.32,
  });
  body.map!.repeat.set(CAMO_REPEAT, CAMO_REPEAT);
  const metal = new THREE.MeshStandardMaterial({ vertexColors: true, normalMap: normal, normalScale: new THREE.Vector2(0.4, 0.4), roughness: 0.48, metalness: 0.72 });
  const trackMaps: THREE.Texture[] = [];
  const mk = (g: THREE.BufferGeometry, m: THREE.Material) => {
    const mesh = new THREE.Mesh(g, m);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    return mesh;
  };

  const hull = new THREE.Group();

  // ---------------- 车体（一次绘制：车壳、挡泥板、侧裙、首上、车尾甲板、工具箱……全在这一个网格里）
  hull.add(mk(paintUV(geo.merged('pt-hull-hi', () => {
    const spareLink = () => geo.merged('pt-link-spare', () => linkParts(false)).clone();
    const p: PartSpec[] = [
      // 下车体
      { geo: frustum(rect(3.1, 5.9), rect(3.3, 6.3), 0.8, 0.55), color: OLIVE_D },
      // 上车体：倾斜首上 + 斜后甲板
      { geo: profileExtrude([[-3.35, 1.3], [-2.05, 2.0], [2.5, 2.0], [3.25, 1.62], [3.25, 1.3]], 3.9), color: OLIVE },
      // 下车体首尾的加强板（倒角，压在下车体斜面上）
      ...[-1, 1].map((s): PartSpec => ({ geo: bevelBox(2.9, 0.5, 0.12, 0.04), color: OLIVE, pos: [0, 0.98, s * 3.12], rot: [s * 0.12, 0, 0] })),
    ];
    // 挡泥板：主板 + 外沿挂板条 + 前后斜挡泥。
    // T175 去掉了挡泥板下面四个托架：它们往下伸到 1.12，正好插在履带顶边里（顶边链板 1.10～1.24）
    for (const s of [-1, 1]) {
      p.push(
        { geo: new THREE.BoxGeometry(0.95, 0.1, 6.7), color: OLIVE_D, pos: [s * 2.2, 1.42, 0] },
        { geo: bevelBox(0.05, 0.13, 6.6, 0.02), color: OLIVE, pos: [s * 2.66, 1.44, 0] },
        { geo: bevelBox(0.95, 0.06, 0.55, 0.02), color: OLIVE_D, pos: [s * 2.2, 1.31, -3.58], rot: [-0.45, 0, 0] },
        { geo: bevelBox(0.95, 0.06, 0.55, 0.02), color: OLIVE_D, pos: [s * 2.2, 1.31, 3.58], rot: [0.45, 0, 0] },
      );
      // 侧裙板（一块块装甲挂板，八角切边、略有歪斜），每块顶上两个挂钩
      [-2.6, -1.3, 0, 1.3, 2.6].forEach((z, i) => {
        p.push({
          geo: prismX([[-0.58, -0.36], [0.58, -0.36], [0.62, -0.3], [0.62, 0.36], [-0.62, 0.36], [-0.62, -0.3]], -0.035, 0.035),
          color: i % 2 ? OLIVE : OLIVE_D,
          pos: [s * 2.72, 1.05, z],
          rot: [0, 0, s * (0.04 + (i % 3) * 0.02)],
        });
        for (const dz of [-0.38, 0.38]) p.push({ geo: bevelBox(0.1, 0.16, 0.1, 0.02), color: DARK, pos: [s * 2.7, 1.36, z + dz] });
      });
      // 前挂点座（2 / 4 号，T164）：挡泥板上一块方座 + 钢框，座顶就是挂点高度
      p.push({ geo: new THREE.BoxGeometry(0.86, 0.04, 0.86), color: OLIVE, pos: [s * 2.15, 1.475, -2.05] });
      for (const [dx, dz, w, d] of [[0, -0.45, 0.94, 0.06], [0, 0.45, 0.94, 0.06], [-0.45, 0, 0.06, 0.84], [0.45, 0, 0.06, 0.84]] as const) {
        p.push({ geo: new THREE.BoxGeometry(w, 0.07, d), color: 0x4a4e50, pos: [s * 2.15 + dx, 1.49, -2.05 + dz] });
      }
    }
    // 炮塔座圈（T175）：甲板上一圈护环 + 深色座圈，座圈顶离炮塔底（2.0 + TURRET_GAP）留 1 厘米，四种炮塔共用（座圈半径 1.2 比哪种炮塔底面都小）。
    // 炮塔转轴在 z = 0.15（buildPlayerTank 里 turret.position）
    p.push(
      { geo: new THREE.CylinderGeometry(1.2, 1.22, TURRET_GAP - 0.03, 36, 1, true), color: 0x26292b, pos: [0, 2.0 + (TURRET_GAP + 0.03) / 2 - 0.01, 0.15] },
      { geo: new THREE.CylinderGeometry(1.3, 1.33, 0.035, 36, 1, true), color: 0x3c3f3a, pos: [0, 2.075, 0.15] },
      { geo: new THREE.RingGeometry(1.2, 1.3, 36, 1).rotateX(-Math.PI / 2), color: 0x3c3f3a, pos: [0, 2.0925, 0.15] },
    );
    // 首上：左边三节备用履带 + 压杆；右边机枪球座；顶上驾驶员观察窗
    for (const f of [0.22, 0.44, 0.66]) p.push({ geo: spareLink(), color: DARK, pos: glacis(f, -0.7, 0.05), rot: [GLACIS_TILT, 0, 0] });
    p.push({ geo: bevelBox(0.95, 0.06, 0.08, 0.015), color: 0x4a4e50, pos: glacis(0.44, -0.7, 0.15), rot: [GLACIS_TILT, 0, 0] });
    p.push(
      { geo: new THREE.SphereGeometry(0.21, 16, 10), color: DARK, pos: [0.85, 1.6, -2.88] },
      { geo: new THREE.TorusGeometry(0.22, 0.06, 6, 16), color: OLIVE_D, pos: glacis(0.36, 0.85, 0.02), rot: [GLACIS_TILT + Math.PI / 2, 0, 0] },
      { geo: new THREE.CylinderGeometry(0.04, 0.04, 0.62, 8), color: DARK, pos: [0.85, 1.6, -3.2], rot: [Math.PI / 2, 0, 0] },
      { geo: new THREE.CylinderGeometry(0.055, 0.055, 0.14, 8), color: 0x222222, pos: [0.85, 1.6, -3.5], rot: [Math.PI / 2, 0, 0] },
      // 驾驶员观察窗（T175 压低 4 厘米：首上顶沿就在炮盾底下，榴弹炮的防盾转过来会擦到）
      { geo: bevelBox(0.55, 0.12, 0.2, 0.035), color: OLIVE_D, pos: glacis(0.9, -0.85, 0.04), rot: [GLACIS_TILT, 0, 0] },
      { geo: new THREE.BoxGeometry(0.4, 0.03, 0.02), color: GLASS, pos: glacis(0.86, -0.85, 0.055), rot: [GLACIS_TILT, 0, 0] },
    );
    // 驾驶员 / 机枪手舱盖 + 潜望镜（甲板最前沿）；T175 起贴着甲板压低（顶 ≤ 2.13），炮塔前沿转过来从上面扫过去
    for (const s of [-1, 1]) {
      p.push(
        { geo: new THREE.CylinderGeometry(0.3, 0.32, 0.03, 18), color: OLIVE_D, pos: [s * 0.88, 2.065, -1.86] },
        { geo: new THREE.CylinderGeometry(0.26, 0.26, 0.03, 18), color: OLIVE, pos: [s * 0.88, 2.083, -1.86] },
        { geo: bevelBox(0.04, 0.02, 0.42, 0.006), color: DARK, pos: [s * 0.88 + s * 0.18, 2.105, -1.86] },
        { geo: bevelBox(0.2, 0.07, 0.14, 0.02), color: OLIVE_D, pos: [s * 0.88, 2.075, -2.2] },
        { geo: new THREE.BoxGeometry(0.15, 0.03, 0.02), color: GLASS, pos: [s * 0.88, 2.085, -2.28] },
      );
    }
    // 车头大灯（灯座 + 灯罩 + 镜片）、拖钩（底板 + 钩）
    for (const s of [-1, 1]) {
      p.push(
        { geo: bevelBox(0.18, 0.12, 0.22, 0.02), color: DARK, pos: [s * 1.45, 1.47, -3.05] },
        { geo: new THREE.CylinderGeometry(0.13, 0.15, 0.22, 16), color: RUBBER, pos: [s * 1.45, 1.62, -3.1], rot: [Math.PI / 2, 0, 0] },
        { geo: new THREE.CylinderGeometry(0.1, 0.1, 0.04, 16), color: 0xf2eed8, pos: [s * 1.45, 1.62, -3.21], rot: [Math.PI / 2, 0, 0] },
        { geo: new THREE.CylinderGeometry(0.16, 0.16, 0.05, 16, 1, false, 0, Math.PI), color: DARK, pos: [s * 1.45, 1.72, -3.17], rot: [Math.PI / 2, 0, Math.PI / 2] },
        { geo: bevelBox(0.24, 0.36, 0.16, 0.03), color: DARK, pos: [s * 1.2, 0.95, -3.24] },
        { geo: new THREE.TorusGeometry(0.11, 0.04, 6, 12, Math.PI), color: 0x2c2e30, pos: [s * 1.2, 0.86, -3.36], rot: [0, Math.PI / 2, Math.PI] },
      );
    }
    // 发动机舱：格栅框 + 九片斜百叶 + 两侧检修盖（带铰链）。
    // T175：格栅往后让出座圈（前沿从 1.1 挪到 1.45，原来伸进座圈底下），百叶放平一点压进格栅框；铰链压低。整片都在炮塔尾舱底下，顶 ≤ 2.12
    p.push({ geo: bevelBox(2.3, 0.05, 1.1, 0.02), color: 0x2c2e2c, pos: [0, 2.08, 2.0] });
    for (let i = 0; i < 9; i++) p.push({ geo: new THREE.BoxGeometry(0.2, 0.03, 0.98), color: 0x4a4c48, pos: [-0.96 + i * 0.24, 2.07, 2.0], rot: [0, 0, 0.28] });
    for (const s of [-1, 1]) {
      p.push({ geo: bevelBox(0.62, 0.05, 1.3, 0.02), color: OLIVE_D, pos: [s * 1.5, 2.085, 1.7] });
      for (const z of [1.25, 2.15]) p.push({ geo: new THREE.CylinderGeometry(0.03, 0.03, 0.16, 8), color: DARK, pos: [s * 1.82, 2.085, z], rot: [Math.PI / 2, 0, 0] });
    }
    // 车尾挂点平台（T177，3 / 5 号）：往车尾两角挪——外移 1.0 米、后移 0.2 米，离炮塔转轴 2.63 → 3.3 米，迫击炮 / 空袭不再挤着炮塔尾舱。
    // 平台是一只倒角箱从挡泥板（1.47）垫到 1.95（比炮塔底 2.16 低，炮塔转过去从上面扫过），往里铺到 x = 0.62（中线 ±0.5 米给炮管让路）盖住斜甲板外角，迫击炮的立弹放在这块上；顶上一块座板 + 钢框，座板顶就是挂点高度。
    // 原来甲板内侧的两块平台、车尾外沿两只放倒的油桶、斜甲板边上的深色压条一起去掉；空出来的斜甲板上铺两块检修盖
    for (const s of [-1, 1]) {
      p.push({ geo: prismX([[2.22, 1.47], [3.3, 1.47], [3.3, 1.8], [3.16, 1.95], [2.3, 1.95], [2.22, 1.88]], s > 0 ? 0.62 : -2.68, s > 0 ? 2.68 : -0.62), color: OLIVE_D });
      p.push({ geo: new THREE.BoxGeometry(0.86, 0.04, 0.86), color: OLIVE, pos: [s * REAR_SEAT[0], 1.955, REAR_SEAT[2]] });
      for (const [dx, dz, w, d] of [[0, -0.45, 0.94, 0.06], [0, 0.45, 0.94, 0.06], [-0.45, 0, 0.06, 0.84], [0.45, 0, 0.06, 0.84]] as const) {
        p.push({ geo: new THREE.BoxGeometry(w, 0.07, d), color: 0x4a4e50, pos: [s * REAR_SEAT[0] + dx, 1.97, REAR_SEAT[2] + dz] });
      }
      // 平台外侧两颗吊耳、车体侧壁上一条焊缝压条
      for (const z of [2.45, 3.1]) p.push({ geo: new THREE.TorusGeometry(0.06, 0.018, 6, 10, Math.PI), color: DARK, pos: [s * 2.69, 1.82, z], rot: [0, Math.PI / 2, 0] });
      p.push({ geo: bevelBox(0.04, 0.05, 1.0, 0.01), color: DARK, pos: [s * 1.96, 1.93, 2.76] });
      // 平台顶面内侧一排防滑压条
      for (let i = 0; i < 4; i++) p.push({ geo: new THREE.BoxGeometry(0.4, 0.02, 0.05), color: 0x4a4e50, pos: [s * 0.95, 1.96, 2.45 + i * 0.25] });
    }
    p.push({ geo: bevelBox(0.9, 0.05, 0.62, 0.015), color: 0x3a3d38, pos: rearDeck(2.87, 0, 0.0), rot: [REAR_TILT, 0, 0] });
    for (let i = 0; i < 5; i++) p.push({ geo: new THREE.BoxGeometry(0.8, 0.03, 0.07), color: 0x52554e, pos: rearDeck(2.65 + i * 0.11, 0, 0.04), rot: [REAR_TILT - 0.35, 0, 0] });
    // 车尾板：横置消音器 + 隔热罩（七条横板）+ 两根出口；正中挂备用负重轮；牵引钩
    p.push({ geo: new THREE.CylinderGeometry(0.17, 0.17, 2.3, 16), color: 0x4a3a30, pos: [0, 1.12, 3.36], rot: [0, 0, Math.PI / 2] });
    for (let i = 0; i < 7; i++) p.push({ geo: bevelBox(2.38, 0.05, 0.04, 0.01), color: OLIVE_D, pos: [0, 0.96 + i * 0.055, 3.56] });
    for (const s of [-1, 1]) p.push({ geo: new THREE.CylinderGeometry(0.08, 0.09, 0.3, 10), color: 0x3a2e28, pos: [s * 1.25, 1.12, 3.5], rot: [0.6, 0, 0] });
    p.push(...roadWheelParts().map((w): PartSpec => ({ ...w, pos: [0, 1.4, 3.66], rot: [0, Math.PI / 2, 0] })));
    p.push({ geo: bevelBox(0.3, 0.26, 0.16, 0.03), color: DARK, pos: [0, 0.72, 3.22] }, { geo: new THREE.TorusGeometry(0.1, 0.04, 6, 12, Math.PI), color: 0x2c2e30, pos: [0, 0.62, 3.33], rot: [0, Math.PI / 2, Math.PI] });
    // 右挡泥板上盘一卷拖缆、左挡泥板上的铁锹和十字镐、甲板加油口和两个进气帽、挡泥板前端储物箱。
    // T175：拖缆原来盘在右侧检修盖上（顶 2.21，炮塔尾舱转过来正好压上去），挪到右挡泥板中段；加油口原来在座圈里面，挪到甲板前沿两个舱盖中间；进气帽压扁
    p.push({ geo: new THREE.TorusGeometry(0.28, 0.05, 6, 20), color: 0x2c2a26, pos: [2.2, 1.52, -0.75], rot: [Math.PI / 2, 0, 0] });
    p.push(
      { geo: bevelBox(0.05, 0.05, 1.3, 0.012), color: 0x5a4a34, pos: [-2.05, 1.5, -0.65] },
      { geo: bevelBox(0.24, 0.03, 0.3, 0.01), color: 0x4a4e50, pos: [-2.05, 1.49, -1.43] },
      { geo: bevelBox(0.05, 0.05, 1.1, 0.012), color: 0x5a4a34, pos: [-2.35, 1.5, -0.55] },
      { geo: bevelBox(0.5, 0.05, 0.07, 0.012), color: 0x4a4e50, pos: [-2.35, 1.5, -1.12] },
    );
    for (const s of [-1, 1]) {
      p.push(
        { geo: new THREE.CylinderGeometry(0.11, 0.12, 0.04, 16), color: DARK, pos: [s * 0.3, 2.08, -1.92] },
        { geo: new THREE.SphereGeometry(0.2, 14, 6, 0, Math.PI * 2, 0, Math.PI / 2), color: OLIVE_D, pos: [s * 1.5, 2.08, 2.6], scale: [1, 0.22, 1] },
        { geo: new THREE.CylinderGeometry(0.2, 0.2, 0.04, 14), color: DARK, pos: [s * 1.5, 2.07, 2.6] },
        ...lidBox(0.7, 0.24, 0.4, 0x5a5a44, [s * 2.2, 1.59, -2.9]),
      );
    }
    // 工具箱（带盖）、左侧挡泥板两只油桶
    p.push(...lidBox(0.42, 0.3, 1.6, 0x5a5a44, [2.25, 1.62, 1.6]), ...lidBox(0.42, 0.3, 1.2, 0x5a5a44, [-2.25, 1.62, 1.9]));
    for (const z of [0.3, 1.0]) p.push(...jerryCan([-2.28, 1.71, z]));
    return p;
  })), body));

  // ---------------- 行走机构
  const wheels: THREE.Object3D[] = [];
  const materials: THREE.Material[] = [body, metal];
  // 实体链板履带（T171）：88 节链板一侧一个网格，跟着贴图偏移在着色器里走
  const belt = geo.get('pt-track-links', trackLinks);
  // T175：轮子刷车身漆（车身材质，见 wheelPaint，跟着车库涂装变），不再用钢件材质；绘制次数、材质数不变
  const wheelGeo = wheelPaint(geo.merged('pt-wheel-hi', () => roadWheelParts()));
  const sprocketGeo = wheelPaint(geo.merged('pt-sprocket-hi', sprocketParts));
  const idlerGeo = wheelPaint(geo.merged('pt-idler-hi', idlerParts));
  for (const s of [-1, 1]) {
    // 两侧独立滚动，原地转向时一正一反；沿用 round-191 的贴图和材质参数。
    const trackMap = trackTexture();
    trackMaps.push(trackMap);
    const trackMat = new THREE.MeshStandardMaterial({ map: trackMap, normalMap: normal, normalScale: new THREE.Vector2(0.22, 0.22), roughness: 0.78, metalness: 0.5, color: 0xbbbbbb });
    materials.push(trackMat);
    const track = mk(belt, trackMat);
    track.name = 'track-belt';
    track.position.set(s * 2.15, 0, 0);
    rigTrack(track, trackMat, trackMap);
    hull.add(track);
    // 双联负重轮骑在履带中线上（导向齿卡在两片轮中间）；T175 起按 GEAR 布局：负重轮落在底边，主动轮 / 诱导轮抬高、往外挪，互不相叠。
    // userData.r = 滚动半径（Tank.update 按它算转速，链板走多快轮子就转多快）
    for (const z of GEAR.road.z) {
      const w = mk(wheelGeo, body);
      w.position.set(s * 2.15, GEAR.road.y, z);
      w.userData.r = GEAR.road.r;
      hull.add(w);
      wheels.push(w);
    }
    for (const [g, at] of [[sprocketGeo, GEAR.sprocket], [idlerGeo, GEAR.idler]] as const) {
      const sp = mk(g, body);
      sp.position.set(s * 2.15, at.y, at.z);
      sp.userData.r = at.rp;
      hull.add(sp);
      wheels.push(sp);
    }
  }

  // ---------------- 炮塔（外形由流派核心决定，见 buildCoreTurret）
  const turret = new THREE.Group();
  turret.position.set(0, 2.0, 0.15);

  // ---------------- 武器挂点
  const anchors = [
    anchor(turret, 1.05, 1.0, 0.05),
    anchor(turret, -1.05, 1.0, 0.05),
    anchor(hull, -2.15, 1.47, -2.05),
    anchor(hull, -REAR_SEAT[0], REAR_SEAT[1], REAR_SEAT[2]),
    anchor(hull, 2.15, 1.47, -2.05),
    anchor(hull, REAR_SEAT[0], REAR_SEAT[1], REAR_SEAT[2]),
  ];

  // 副武器挂件刷车漆（T177）：挂件建模时从挂点上取车身材质（车库换涂装跟着变）
  for (const a of anchors) a.userData.paint = body;
  hull.add(turret);
  return { hull, turret, wheels, trackMaps, anchors, body, metal, materials };
}

export interface CoreTurret {
  group: THREE.Group;
  /** 后坐件（炮管）；没有时为 null */
  recoil: THREE.Object3D | null;
  recoilRest: number;
  muzzles: THREE.Object3D[];
  /** 炮塔顶两个副武器挂点的位置 */
  anchorPos: [number, number, number][];
  /** 终极武器的车上套件（会变的部分）；没合成时为 null */
  ult: UltKit | null;
  /** 火神炮塔的活动件（转管、分火偏转、发红；不是火神为空） */
  vulcan?: VulcanRig;
  /** 炮塔上伸出去的那截（主炮管 / 火箭发射箱 / 火神炮 / 光矛前段）的包围盒，炮塔局部坐标（T127：转到车尾会不会扫到挂件，weapons/traverse.ts） */
  gun: THREE.Box3[];
}

/** 炮塔组里炮塔本体前沿（局部 z < front）以外的所有顶点的包围盒；炮塔组这时还没挂到车上，世界坐标就是炮塔局部 */
function frontBox(group: THREE.Group, front: number): THREE.Box3 {
  const box = new THREE.Box3();
  const v = new THREE.Vector3();
  group.updateMatrixWorld(true);
  group.traverse((o) => {
    const m = o as THREE.Mesh;
    if (!m.isMesh) return;
    const p = m.geometry.getAttribute('position');
    for (let i = 0; i < p.count; i++) {
      v.fromBufferAttribute(p, i).applyMatrix4(m.matrixWorld);
      if (v.z < front) box.expandByPoint(v);
    }
  });
  return box;
}

/**
 * 终极套件里会变的部分（Tank 负责）：指示灯（实例化，亮灭改实例颜色，不受光照）。
 * heat = 发热件（炼狱的散热套环 + 排气口）：颜色跟着装载进度从冷铁变红热，不按指示灯闪；
 * recoil = 跟着炮管后坐的实例（散热套环套在炮管根部），每帧传入后坐位移
 */
export interface UltKit {
  lamp: THREE.InstancedMesh;
  heat?: boolean;
  recoil?: (dz: number) => void;
  /** 指示灯亮 / 灭的颜色（不填 = 红色 LAMP_ON / LAMP_OFF）；所有实例一起亮灭 */
  on?: number;
  off?: number;
  /** 生效中把指示灯藏起来（极光：停机架上的浮游炮飞出去了） */
  hideActive?: boolean;
  /** 会翻起来的部分（钢幕发射箱，k = 0 收起 / 1 架好，Tank.ultRaise 调） */
  raise?: (k: number) => void;
  /** 套件的出口（炮塔局部坐标，架好时）：钢幕 36 个管口的中心 */
  mouth?: [number, number, number];
}

const GOLD = 0xd8a84a;
/** 合成环：金色终极环之上再加一圈红铜色（每种终极通用） */
const COPPER = 0xb5653a;

/** 套件指示灯：亮 / 灭的颜色 */
export const LAMP_ON = 0xff3a22;
export const LAMP_OFF = 0x3a1410;
/** 发热件：冷铁 / 红热 */
export const HEAT_COLD = 0x2a2522;
export const HEAT_HOT = 0xff6a1e;

/** 黄黑辐射标（朝 +Z，贴在 (x, y, z) 的面上）：黄底 + 黑边 + 三叶 + 中心圆 */
function radSign(x: number, y: number, z: number, size = 0.36): PartSpec[] {
  const k = size / 0.36;
  return [
    { geo: new THREE.BoxGeometry(0.36 * k, 0.36 * k, 0.02), color: 0x1a1a14, pos: [x, y, z] },
    { geo: new THREE.BoxGeometry(0.31 * k, 0.31 * k, 0.02), color: 0xe8c22a, pos: [x, y, z + 0.007] },
    ...[0, 1, 2].map((i): PartSpec => ({ geo: new THREE.RingGeometry(0.045 * k, 0.13 * k, 6, 1, Math.PI / 2 + (i * Math.PI * 2) / 3 - Math.PI / 6, Math.PI / 3), color: 0x14140e, pos: [x, y, z + 0.019] })),
    { geo: new THREE.CircleGeometry(0.03 * k, 10), color: 0x14140e, pos: [x, y, z + 0.019] },
  ];
}

/**
 * 「核弹」套件（叠在主炮终极炮塔上，2 次绘制）：炮塔右后方的野战电台箱 + 高鞭天线（顶上一盏红色指示灯，单独 1 次绘制）
 * + 朝后的黄黑核标牌 + 红铜合成环。避开炮塔顶两侧的 0 / 1 号副武器挂点和指挥塔。
 */
function nukeKit(geo: GeoCache, group: THREE.Group, metal: THREE.Material): UltKit {
  // 天线：从电台箱顶 (1.05, 1.44, 1.35) 往上 3.2 米，略向后仰
  const tilt = 0.12;
  const top = new THREE.Vector3(1.05, 1.44 + Math.cos(tilt) * 3.2, 1.35 + Math.sin(tilt) * 3.2);
  const fixed = new THREE.Mesh(geo.merged('pt-ult-nuke', () => [
    // 合成环
    { geo: frustum(chamfer(2.66, 3.09, 0.62), chamfer(2.64, 3.07, 0.62), 0.08, 0.68), color: COPPER },
    // 野战电台箱：箱体 + 前面板 + 旋钮 + 提手
    { geo: new THREE.BoxGeometry(0.42, 0.44, 0.6), color: 0x4a5038, pos: [0.95, 1.22, 1.2] },
    { geo: new THREE.BoxGeometry(0.02, 0.24, 0.4), color: 0x1e1e1e, pos: [0.73, 1.24, 1.2] },
    ...[1.08, 1.32].map((z): PartSpec => ({ geo: new THREE.CylinderGeometry(0.035, 0.035, 0.03, 8), color: 0xd8d0b0, pos: [0.72, 1.28, z], rot: [0, 0, Math.PI / 2] })),
    { geo: new THREE.BoxGeometry(0.3, 0.04, 0.05), color: DARK, pos: [0.95, 1.46, 1.05] },
    // 天线座 + 高鞭天线
    { geo: new THREE.CylinderGeometry(0.06, 0.07, 0.14, 8), color: DARK, pos: [1.05, 1.5, 1.35] },
    { geo: new THREE.CylinderGeometry(0.014, 0.03, 3.2, 4), color: 0x1e1e1e, pos: [1.05, 1.44 + Math.cos(tilt) * 1.6, 1.35 + Math.sin(tilt) * 1.6], rot: [tilt, 0, 0] },
    // 黄黑核标牌（朝后，镜头看得见）
    ...radSign(0.95, 1.22, 1.505),
  ]), metal);
  fixed.castShadow = true;
  group.add(fixed);
  const lamp = new THREE.InstancedMesh(geo.sphere(0.09, 8), MAT.lamp, 1);
  lamp.setMatrixAt(0, new THREE.Matrix4().makeTranslation(top.x, top.y + 0.05, top.z));
  lamp.setColorAt(0, new THREE.Color(LAMP_OFF));
  group.add(lamp);
  return { lamp };
}

/**
 * 「炼狱」套件（叠在主炮终极炮塔上，2 次绘制）：炮塔尾舱顶上的铅灰装甲弹药箱（背面贴黄黑辐射标）+ 红铜合成环（合并 1 次）；
 * 炮管根部的散热套环（雷霆双联是两个）和弹药箱背面的两根排气管合成 1 次实例化绘制，颜色跟着装载进度从冷铁变红热（Tank.setUltKit）。
 * 弹药箱在尾舱顶后半（地毯炮击的三个弹药架前面一点），避开炮塔两侧的副武器挂点和车尾平台的挂点；套环跟着炮管后坐
 */
function infernoKit(geo: GeoCache, group: THREE.Group, metal: THREE.Material, xs: number[], r: number): UltKit {
  const fixed = new THREE.Mesh(geo.merged('pt-ult-inferno', () => [
    // 合成环
    { geo: frustum(chamfer(2.66, 3.09, 0.62), chamfer(2.64, 3.07, 0.62), 0.08, 0.68), color: COPPER },
    // 铅灰装甲弹药箱：箱体 + 盖板 + 两侧提手 + 一排螺栓
    { geo: new THREE.BoxGeometry(1.2, 0.48, 0.42), color: 0x55595c, pos: [0, 1.14, 2.38] },
    { geo: new THREE.BoxGeometry(1.26, 0.07, 0.48), color: 0x44474a, pos: [0, 1.41, 2.38] },
    ...[-1, 1].map((sx): PartSpec => ({ geo: new THREE.BoxGeometry(0.04, 0.06, 0.24), color: DARK, pos: [sx * 0.63, 1.2, 2.38] })),
    ...[-0.45, -0.15, 0.15, 0.45].map((x): PartSpec => ({ geo: new THREE.BoxGeometry(0.05, 0.05, 0.03), color: 0x3a3c3e, pos: [x, 1.32, 2.6] })),
    // 背面：辐射标 + 两根排气管的管座
    ...radSign(-0.28, 1.1, 2.6, 0.3),
    ...[0.24, 0.46].map((x): PartSpec => ({ geo: new THREE.CylinderGeometry(0.075, 0.075, 0.04, 10), color: DARK, pos: [x, 1.1, 2.61], rot: [Math.PI / 2, 0, 0] })),
  ]), metal);
  fixed.castShadow = true;
  group.add(fixed);
  // 发热件：单位尺寸的带散热鳍片短管（轴沿 z），按实例缩放成炮管根部的套环 / 弹药箱背面的排气管
  const unit = geo.merged('pt-ult-heat', () => [
    { geo: new THREE.CylinderGeometry(1, 1, 1, 14, 1), color: 0xffffff, rot: [Math.PI / 2, 0, 0] },
    ...[-0.36, -0.12, 0.12, 0.36].map((z): PartSpec => ({ geo: new THREE.TorusGeometry(1.12, 0.08, 6, 16), color: 0xffffff, pos: [0, 0, z] })),
  ]);
  const lamp = new THREE.InstancedMesh(unit, MAT.lamp, xs.length + 2);
  const m = new THREE.Matrix4();
  const q = new THREE.Quaternion();
  const sc = new THREE.Vector3();
  const pos = new THREE.Vector3();
  // 套环：炮管露出防盾的那一段（炮管组在 (0, 0.55, -2.2)，防盾到 -0.25），比炮管根部粗一圈
  const sleeve = (i: number, dz: number) => lamp.setMatrixAt(i, m.compose(pos.set(xs[i], 0.55, -2.2 - 0.66 + dz), q, sc.set(r * 1.42, r * 1.42, 0.52)));
  xs.forEach((_, i) => sleeve(i, 0));
  [0.24, 0.46].forEach((x, i) => lamp.setMatrixAt(xs.length + i, m.compose(pos.set(x, 1.1, 2.68), q, sc.set(0.055, 0.055, 0.16))));
  const cold = new THREE.Color(HEAT_COLD);
  for (let i = 0; i < lamp.count; i++) lamp.setColorAt(i, cold);
  group.add(lamp);
  return {
    lamp,
    heat: true,
    recoil: (dz) => {
      xs.forEach((_, i) => sleeve(i, dz));
      lamp.instanceMatrix.needsUpdate = true;
    },
  };
}

