/**
 * 「极光」套件（叠在激光终极炮塔上，2 次绘制）：炮塔尾部两只储能罐顶上各一个停机架 + 红铜合成环（合并 1 次）；
 * 架上各挂 3 颗小棱镜（浮游炮，实例化成指示灯 1 次：待发时亮青色，出阵时藏起来）。停机架在副武器挂点后面
 */
function auroraKit(geo: GeoCache, group: THREE.Group, metal: THREE.Material): UltKit {
  const fixed = new THREE.Mesh(geo.merged('pt-ult-aurora', () => [
    lanceCopper(),
    ...[-1, 1].flatMap((s): PartSpec[] => [
      { geo: new THREE.BoxGeometry(0.22, 0.07, 0.95), color: 0x2a2c2e, pos: [s * 0.75, 1.8, 1.25] },
      ...[0.95, 1.25, 1.55].map((z): PartSpec => ({ geo: new THREE.CylinderGeometry(0.03, 0.03, 0.12, 5), color: 0x1e1e1e, pos: [s * 0.75, 1.87, z] })),
    ]),
  ]), metal);
  fixed.castShadow = true;
  group.add(fixed);
  // T021-b：棱镜换成特斯拉无人机顶上的电球（电球蓝）
  const crystal = new THREE.IcosahedronGeometry(0.12, 0);
  const lamp = new THREE.InstancedMesh(crystal, MAT.lamp, 6);
  const m = new THREE.Matrix4();
  for (let i = 0; i < 6; i++) {
    lamp.setMatrixAt(i, m.makeTranslation(...auroraRack(i)));
    lamp.setColorAt(i, new THREE.Color(0x1c2a32));
  }
  group.add(lamp);
  return { lamp, on: 0x7cc8ff, off: 0x1c2a32, hideActive: true };
}

