/**
 * 「钢幕」套件（叠在火神终极炮塔上，3 次绘制）：炮塔后背一个方形发射箱（D1-032 第 7.2 节），平时盖板合着、平躺在支架上；
 * 放的时候绕前沿翻起来立在炮上，顶面 6 × 6 个管口转成朝前，盖板往后掀开。两侧两条琥珀色指示灯（1 次）+ 红铜合成环
 */
function curtainKit(geo: GeoCache, group: THREE.Group, metal: THREE.Material, w: number, mega: boolean): UltKit {
  // 放在炮塔顶中间偏右（车长塔右边、炮摇架后面），两侧副武器挂点和千钧弹带都让开；架好时抬高 lift 米、立在摇架后沿上
  const px = 0.3;
  const py = mega ? 1.66 : 1.06;
  const hz = -0.2;
  const lift = 0.6;
  group.add(new THREE.Mesh(geo.merged(`pt-ult-curtain-base-${w}-${mega}`, () => [
    vulcanCopper(w),
    ...[-0.42, 0.42].map((x): PartSpec => ({ geo: new THREE.BoxGeometry(0.12, py - 0.75, 0.5), color: DARK, pos: [px + x, 0.75 + (py - 0.75) / 2, hz + 0.5] })),
    { geo: new THREE.BoxGeometry(1.0, 0.08, 0.16), color: DARK, pos: [px, py - 0.04, hz + 0.05] },
  ]), metal));
  const pivot = new THREE.Group();
  pivot.position.set(px, py, hz);
  group.add(pivot);
  const box = new THREE.Mesh(geo.merged('pt-ult-curtain-box', () => {
    const p: PartSpec[] = [
      { geo: new THREE.BoxGeometry(1.1, 0.46, 1.0), color: 0x55593e, pos: [0, 0.23, 0.5] },
      { geo: new THREE.BoxGeometry(1.14, 0.08, 1.04), color: 0x3e4230, pos: [0, 0.05, 0.5] },
      ...[-0.57, 0.57].map((x): PartSpec => ({ geo: new THREE.BoxGeometry(0.04, 0.28, 0.7), color: 0x3a3c30, pos: [x, 0.26, 0.5] })),
    ];
    for (let i = 0; i < 6; i++) for (let j = 0; j < 6; j++) p.push({ geo: new THREE.CylinderGeometry(0.06, 0.06, 0.04, 8), color: 0x141414, pos: [-0.44 + i * 0.176, 0.465, 0.12 + j * 0.152] });
    return p;
  }), metal);
  box.castShadow = true;
  pivot.add(box);
  const lid = new THREE.Group();
  lid.position.set(0, 0.48, 1.0);
  pivot.add(lid);
  const plate = new THREE.Mesh(geo.merged('pt-ult-curtain-lid', () => [
    { geo: new THREE.BoxGeometry(1.12, 0.05, 1.02), color: 0x5e6246, pos: [0, 0, -0.51] },
    { geo: new THREE.BoxGeometry(0.8, 0.03, 0.08), color: 0xd8a83a, pos: [0, 0.035, -0.5] },
  ]), metal);
  plate.castShadow = true;
  lid.add(plate);
  const lamp = new THREE.InstancedMesh(new THREE.BoxGeometry(0.04, 0.06, 0.4), MAT.lamp, 2);
  const m = new THREE.Matrix4();
  [-1, 1].forEach((sx, i) => {
    lamp.setMatrixAt(i, m.makeTranslation(px + sx * 0.49, py - 0.22, hz + 0.5));
    lamp.setColorAt(i, new THREE.Color(0x2a1c0a));
  });
  group.add(lamp);
  return {
    lamp,
    on: 0xffb040,
    off: 0x2a1c0a,
    mouth: [px, py + lift + 0.5, hz - 0.46],
    raise: (k) => {
      const e = k * k * (3 - 2 * k);
      pivot.rotation.x = (-Math.PI / 2) * e;
      pivot.position.y = py + lift * e;
      lid.rotation.x = Math.min(1, k * 1.6) * 2.1;
    },
  };
}

/** 按流派 / 分支 / 终极搭出炮塔：主炮流长管重炮、火箭流火箭炮塔、激光流棱镜炮塔、火神流火神炮塔（vulcanTurret.ts）；合成后再叠加终极套件 */
export function buildCoreTurret(geo: GeoCache, core: CoreId, branch: Branch | null, ultimate: boolean, body: THREE.Material, metal: THREE.Material, fusion: FusionId | null = null, tier = 1): CoreTurret {
  const group = new THREE.Group();
  const mk = (g: THREE.BufferGeometry, m: THREE.Material, parent: THREE.Object3D = group) => {
    const mesh = new THREE.Mesh(g, m);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    parent.add(mesh);
    return mesh;
  };
  const muzzles: THREE.Object3D[] = [];
  const point = (parent: THREE.Object3D, x: number, y: number, z: number) => {
    const o = new THREE.Object3D();
    o.position.set(x, y, z);
    parent.add(o);
    muzzles.push(o);
  };
  const glow = (r: number, x: number, y: number, z: number, sy = 1) => {
    const m = mk(geo.sphere(r, 10), MAT.energyCyan);
    m.position.set(x, y, z);
    m.scale.y = sy;
    return m;
  };
  /**
   * 共用：天线（钢件）一个网格——原来天线自己就是这一次绘制。天线的位置 / 后仰直接烘进几何体，网格本身留在原点。
   * T177：两个炮塔挂点的圆形钢座圈去掉了，换成并进炮塔车漆网格的托架（turretPad）
   */
  const steel = (key: string, at: [number, number, number]) => mk(geo.merged(`pt-steel-${key}`, () => [
    { geo: new THREE.CylinderGeometry(0.015, 0.025, 3.0, 4), color: 0x1e1e1e, pos: [at[0], at[1] + Math.cos(0.35) * 1.5, at[2] + Math.sin(0.35) * 1.5], rot: [0.35, 0, 0] },
  ]), metal);
  /** 两侧挂点（同一个 x / y / z 左右镜像）+ 托架 */
  const side = (x: number, y: number, z: number): [number, number, number][] => [[x, y + PAD_LIFT, z], [-x, y + PAD_LIFT, z]];
  const pads = (anchors: [number, number, number][], wall: [[number, number], [number, number]], size?: number, depth?: number) => anchors.flatMap((a) => turretPad(a, wall, size, depth));

  if (core === 'cannon') {
    const stow = !ultimate;
    const seats = side(1.05, 1.0, 0.05);
    mk(paintUV(geo.merged(`pt-turret-hi-${ultimate}`, () => [
      // 铸造炮塔分上下两段收口（T175：下段底面抬到 TURRET_GAP，尾舱、炮盾座底面一起抬，顶面不变）
      { geo: frustum(chamfer(3.0, 3.5, 0.75, 0, -0.1), chamfer(2.84, 3.34, 0.71, 0, -0.07), 0.5 - TURRET_GAP, TURRET_GAP), color: OLIVE },
      { geo: frustum(chamfer(2.84, 3.34, 0.71, 0, -0.07), chamfer(2.4, 2.8, 0.55, 0, 0.05), 0.5, 0.5), color: OLIVE },
      { geo: frustum(rect(2.3, 1.2, 0, 2.0), rect(2.1, 1.0, 0, 1.95), 0.9 - TURRET_GAP, TURRET_GAP), color: OLIVE_D },
      { geo: frustum(rect(1.6, 0.7, 0, -1.85), rect(1.35, 0.55, 0, -1.85), 0.98 - TURRET_GAP, TURRET_GAP), color: OLIVE_D },
      // 前脸两侧斜切面的附加装甲板 + 每块两个托架（T175：下沿收到 0.19，不再低过炮塔底）
      ...[-1, 1].flatMap((s): PartSpec[] => [
        { geo: bevelBox(0.1, 0.56, 0.95, 0.03), color: OLIVE_D, pos: [s * 1.2, 0.47, -1.56], rot: [0, s * Math.PI / 4, 0] },
        ...[-0.25, 0.25].map((d): PartSpec => ({ geo: bevelBox(0.14, 0.12, 0.08, 0.02), color: DARK, pos: [s * (1.13 + d * 0.707), 0.72, -1.49 + d * 0.707], rot: [0, s * Math.PI / 4, 0] })),
      ]),
      // 车长塔、装填手舱盖、炮长瞄准镜罩（带遮雨檐）、左前潜望镜、通风帽
      ...cupola(0.3, 1.18, 0.75),
      ...hatch(-0.45, 1.0, 0.85),
      { geo: bevelBox(0.36, 0.26, 0.44, 0.05), color: OLIVE_D, pos: [0.65, 1.1, -0.78] },
      { geo: new THREE.BoxGeometry(0.26, 0.1, 0.02), color: GLASS, pos: [0.65, 1.13, -1.005] },
      { geo: bevelBox(0.42, 0.03, 0.18, 0.01), color: OLIVE_D, pos: [0.65, 1.245, -1.02] },
      { geo: bevelBox(0.2, 0.14, 0.16, 0.02), color: OLIVE_D, pos: [-0.6, 1.07, -0.75] },
      { geo: new THREE.BoxGeometry(0.15, 0.05, 0.02), color: GLASS, pos: [-0.6, 1.09, -0.835] },
      { geo: new THREE.CylinderGeometry(0.15, 0.17, 0.09, 14), color: OLIVE_D, pos: [-0.25, 1.04, -0.25] },
      // 烟幕弹、侧挂甲（每块一个挂钩）
      ...[-1, 1].flatMap((s) => smoke(s * 1.2, 0.74, -1.08, s)),
      ...[-1, 1].flatMap((s) => [-0.5, 0, 0.5].flatMap((z): PartSpec[] => [
        { geo: bevelBox(0.06, 0.32, 0.42, 0.015), color: DARK, pos: [s * 1.38, 0.5, z], rot: [0, 0, s * 0.18] },
        { geo: bevelBox(0.08, 0.1, 0.08, 0.015), color: 0x2a2c2e, pos: [s * 1.36, 0.69, z] },
      ])),
      // 尾舱两侧储物箱、后壁储物箱
      ...[-1, 1].flatMap((s) => lidBox(0.28, 0.44, 0.46, CRATE, [s * 1.25, 0.48, 2.0])),
      ...lidBox(1.5, 0.34, 0.18, 0x5c5236, [0, 0.46, 2.7]),
      // 识别白条
      ...[-1, 1].flatMap((s): PartSpec[] => [
        { geo: new THREE.BoxGeometry(0.02, 0.07, 0.42), color: 0xe8e4d4, pos: [s * 1.32, 0.55, -0.3], rot: [0.6, 0, s * 0.2] },
        { geo: new THREE.BoxGeometry(0.02, 0.07, 0.42), color: 0xe8e4d4, pos: [s * 1.32, 0.55, 0.0], rot: [-0.6, 0, s * 0.2] },
      ]),
      // 天线座、尾舱顶置物架（T164：护栏 + 篷布卷 + 弹药箱；终极形态只留护栏）
      { geo: new THREE.CylinderGeometry(0.06, 0.08, 0.14, 8), color: DARK, pos: [-1.0, 1.06, 1.3] },
      ...roofRack(-0.95, 0.95, 1.5, 2.5, 0.9, stow),
      ...(stow ? [...jerryCan([-0.6, 1.16, 2.25], [0, Math.PI / 2, 0]), ...jerryCan([0.6, 1.16, 2.25], [0, Math.PI / 2, 0])] : []),
      // 尾舱两侧逃生门（T175：原来贴在甲板上的防溅环去掉了，换成 steel() 里统一的座圈）
      ...[-1, 1].flatMap((s): PartSpec[] => [
        { geo: new THREE.CylinderGeometry(0.22, 0.22, 0.05, 18), color: OLIVE_D, pos: [s * 1.12, 0.52, 1.6], rot: [0, 0, Math.PI / 2] },
        { geo: bevelBox(0.05, 0.05, 0.3, 0.01), color: DARK, pos: [s * 1.15, 0.52, 1.6] },
      ]),
      // 车长塔上的防空机枪、左前探照灯、两侧备用链板和扶手
      ...aaGun(0.3, 1.36, 0.75),
      ...searchlight(-0.78, 1.0, -1.3),
      ...[-1, 1].flatMap((s) => [...sideLinks(geo, s * 1.33, 0.45, 0.95, s, 2), ...grabRail(s * 1.18, 0.98, -0.6, 0.6)]),
      // 副武器托架（T177）：上段侧壁从顶面 (1.2, 1.0) 斜到 (1.42, 0.5)
      ...pads(seats, [[1.2, 1.0], [1.42, 0.5]]),
    ])), body);
    glow(0.11, 0.3, 1.38, 0.32);
    // 炮管：穿甲线细长、榴弹线粗短；雷霆重炮是双联装粗炮管
    const twin = ultimate && branch === 'A';
    const len = twin ? 6.4 : branch === 'A' ? 6.6 : branch === 'B' ? 4.6 : 5.4;
    const r = twin ? 0.25 : branch === 'A' ? 0.17 : branch === 'B' ? 0.28 : 0.19;
    const gun = new THREE.Group();
    gun.position.set(0, 0.55, -2.2);
    const xs = twin ? [-0.42, 0.42] : [0];
    // T172：炮管、防盾改用车漆材质并接着炮塔铺迷彩（原来是钢件材质 + 浅橄榄 0x8c9078，和车身差太多）；制退器压暗一档当火药熏黑
    mk(paintUVAt(geo.merged(`pt-barrel-hi-${twin ? 'twin' : branch ?? 'base'}`, () => [
      // 炮管朝 -z：高段数管身 + 三道炮管箍 + 抽气装置 + 开窗制退器
      ...xs.flatMap((x) => barrelHi(len, r, { evacuator: branch !== 'B' }).map((q): PartSpec => {
        const [px, py, pz] = q.pos ?? [0, 0, 0];
        return { ...q, color: q.color === 0xffffff ? OLIVE : SOOT, pos: [x - px, py, -pz], rot: [0, Math.PI, 0] };
      })),
      // 防盾：倒角方块 + 每根炮管一圈护套 + 同轴机枪口
      { geo: bevelBox(twin ? 1.7 : (r + 0.14) * 2, (r + 0.14) * 2, 0.7, 0.07), color: OLIVE_D, pos: [0, 0, 0.1] },
      // 护套（T175：粗炮管的护套封顶在比管身粗 0.1～0.12，不再比防盾还大一圈；榴弹线原来下沿低到 2.10，转到侧后方会蹭车尾平台和检修盖）
      ...xs.map((x): PartSpec => ({ geo: new THREE.CylinderGeometry(Math.min(r * 1.45, r + 0.1), Math.min(r * 1.6, r + 0.12), 0.3, 18), color: OLIVE_D, pos: [x, 0, -0.38], rot: [Math.PI / 2, 0, 0] })),
      { geo: new THREE.CylinderGeometry(0.05, 0.05, 0.22, 8), color: DARK, pos: [twin ? 0 : r + 0.22, -0.05, -0.32], rot: [Math.PI / 2, 0, 0] },
    ]), [BARREL_CAMO_X, 0.55, -2.2]), body, gun);
    if (ultimate) mk(geo.merged('pt-gold-band', () => [{ geo: frustum(chamfer(3.02, 3.52, 0.75, 0, -0.1), chamfer(3.0, 3.5, 0.75, 0, -0.1), 0.12, 0.35), color: GOLD }]), metal);
    if (ultimate && branch === 'B') {
      mk(paintUV(geo.merged('pt-ammo-racks-hi', () => [...[-0.6, 0, 0.6].flatMap((x) => lidBox(0.5, 0.33, 0.5, 0x5a5a3a, [x, 1.05, 1.95]))])), body);
    }
    group.add(gun);
    for (const x of xs) point(group, x, 0.55, -2.2 - len - 0.3);
    steel('cannon', [-1.0, 1.0, 1.3]);
    const kit = fusion === 'nuke' ? nukeKit(geo, group, metal) : fusion === 'inferno' ? infernoKit(geo, group, metal, xs, r) : null;
    // 只算防盾前沿往外的炮管：炮塔本体不算（朝前时尾舱本来就挨着车尾挂件）
    return { group, recoil: gun, recoilRest: -2.2, muzzles, anchorPos: seats, ult: kit, gun: [frontBox(group, -2.25)] };
  }

  if (core === 'rocket') {
    // T177：挂点往外 7 厘米、往前 17 厘米，托架让开舱盖和尾舱储物箱
    const seats = side(0.82, 0.8, 0.78);
    mk(paintUV(geo.merged(`pt-rturret-hi-${ultimate}`, () => [
      // T175：下段 / 尾舱底面抬到 TURRET_GAP，顶面不变
      { geo: frustum(chamfer(2.8, 3.2, 0.6), chamfer(2.66, 3.06, 0.57), 0.4 - TURRET_GAP, TURRET_GAP), color: OLIVE },
      { geo: frustum(chamfer(2.66, 3.06, 0.57), chamfer(2.3, 2.6, 0.5), 0.4, 0.4), color: OLIVE },
      { geo: frustum(rect(2.0, 1.0, 0, 1.75), rect(1.8, 0.8, 0, 1.7), 0.7 - TURRET_GAP, TURRET_GAP), color: OLIVE_D },
      { geo: new THREE.CylinderGeometry(0.34, 0.38, 0.3, 20), color: OLIVE_D, pos: [0, 0.95, -0.2] },
      { geo: bevelBox(0.5, 0.28, 0.3, 0.04), color: 0x2a3034, pos: [0, 1.2, -0.3] },
      // 两侧发射架支臂（T175 跟着发射舱抬高）
      ...[-1, 1].map((s): PartSpec => ({ geo: bevelBox(0.6, 0.3, 0.8, 0.05), color: DARK, pos: [s * 1.3, 0.55 + POD_LIFT, -0.1] })),
      ...[-1, 1].flatMap((s): PartSpec[] => [
        { geo: new THREE.BoxGeometry(0.02, 0.07, 0.36), color: 0xe8e4d4, pos: [s * 1.16, 0.45, 0.7], rot: [0.6, 0, 0] },
        { geo: new THREE.BoxGeometry(0.02, 0.07, 0.36), color: 0xe8e4d4, pos: [s * 1.16, 0.45, 0.95], rot: [-0.6, 0, 0] },
      ]),
      // 舱盖、前沿两个潜望镜、烟幕弹、尾舱两侧和后壁储物箱、尾舱顶置物架
      ...hatch(0, 0.8, 0.45, 0.27),
      ...[-1, 1].flatMap((s): PartSpec[] => [
        { geo: bevelBox(0.2, 0.14, 0.16, 0.02), color: OLIVE_D, pos: [s * 0.6, 0.86, -0.95] },
        { geo: new THREE.BoxGeometry(0.15, 0.05, 0.02), color: GLASS, pos: [s * 0.6, 0.88, -1.035] },
      ]),
      ...[-1, 1].flatMap((s) => smoke(s * 1.0, 0.62, -1.3, s, 0.3)),
      ...[-1, 1].flatMap((s) => lidBox(0.26, 0.38, 0.5, CRATE, [s * 1.06, 0.42, 1.75])),
      ...lidBox(1.4, 0.3, 0.16, 0x5c5236, [0, 0.4, 2.33]),
      { geo: new THREE.CylinderGeometry(0.06, 0.08, 0.14, 8), color: DARK, pos: [-0.7, 0.86, 1.2] },
      ...roofRack(-0.82, 0.82, 1.45, 2.15, 0.7, !ultimate, 0.18),
      // 前脸附加装甲、舱盖上的防空机枪、探照灯、两侧备用链板和扶手、发射架耳轴座
      ...[-1, 1].map((s): PartSpec => ({ geo: bevelBox(0.1, 0.46, 0.8, 0.03), color: OLIVE_D, pos: [s * 1.05, 0.42, -1.42], rot: [0, s * Math.PI / 4, 0] })),
      ...aaGun(0, 0.86, 0.45),
      ...searchlight(0.62, 0.8, -0.55),
      ...[-1, 1].flatMap((s) => [...sideLinks(geo, s * 1.22, 0.38, 0.85, s, 2), ...grabRail(s * 1.0, 0.82, 0.2, 1.1)]),
      ...rangefinder(0, 1.02, -0.62, 1.6),
      ...[-1, 1].flatMap((s): PartSpec[] => [
        { geo: new THREE.CylinderGeometry(0.2, 0.2, 0.2, 16), color: DARK, pos: [s * 1.62, 0.85 + POD_LIFT, -0.1], rot: [0, 0, Math.PI / 2] },
        { geo: new THREE.CylinderGeometry(0.12, 0.12, 0.26, 12), color: 0x4a4e50, pos: [s * 1.66, 0.85 + POD_LIFT, -0.1], rot: [0, 0, Math.PI / 2] },
      ]),
      ...pads(seats, [[1.15, 0.8], [1.33, 0.4]], 1.05),
    ])), body);
    glow(0.1, 0, 1.25, -0.48);
    const pods: THREE.Group[] = [];
    for (const s of [-1, 1]) {
      const pod = new THREE.Group();
      pod.position.set(s * 1.95, 0.85 + POD_LIFT, -0.1);
      pod.rotation.x = 0.22;
      group.add(pod);
      pods.push(pod);
      const at: [number, number, number] = [s * 1.95, 0.85 + POD_LIFT, -0.1];
      if (ultimate && branch === 'A') {
        // 喀秋莎：一排导轨 + 导轨上的火箭（带尾翼）；T172 起整架刷车漆（原来是钢件材质的深灰），导轨 / 尾翼压暗
        mk(paintUVAt(geo.merged(`pt-katyusha-hi-${s}`, () => {
          const p: PartSpec[] = [{ geo: bevelBox(1.2, 0.2, 2.6, 0.04), color: OLIVE_D }];
          for (let i = 0; i < 4; i++) {
            const x = -0.45 + i * 0.3;
            p.push({ geo: new THREE.BoxGeometry(0.08, 0.12, 2.8), color: SOOT, pos: [x, 0.16, 0] });
            p.push({ geo: new THREE.CylinderGeometry(0.1, 0.1, 1.6, 12), color: OLIVE, pos: [x, 0.32, -0.3], rot: [Math.PI / 2, 0, 0] });
            p.push({ geo: new THREE.ConeGeometry(0.1, 0.3, 12), color: OLIVE_D, pos: [x, 0.32, -1.25], rot: [-Math.PI / 2, 0, 0] });
            for (const a of [0, Math.PI / 2]) p.push({ geo: new THREE.BoxGeometry(0.3, 0.02, 0.22), color: SOOT, pos: [x, 0.32, 0.55], rot: [0, 0, a] });
            p.push({ geo: new THREE.CylinderGeometry(0.115, 0.115, 0.05, 12), color: 0x8a7a50, pos: [x, 0.32, -0.6], rot: [Math.PI / 2, 0, 0] });
            for (const z of [-1.1, 0, 1.1]) p.push({ geo: bevelBox(0.14, 0.2, 0.08, 0.02), color: DARK, pos: [x, 0.2, z] });
          }
          return p;
        }), at), body, pod);
        for (let i = 0; i < 4; i++) point(pod, -0.45 + i * 0.3, 0.32, -1.2);
      } else if (branch === 'B') {
        // 重型穿甲：两根粗管（终极为带警示条的温压弹罐）
        mk(paintUVAt(geo.merged(`pt-heavy-pod-hi-${ultimate}-${s}`, () => [
          { geo: bevelBox(1.0, 1.1, 2.3, 0.06), color: OLIVE },
          ...[-0.24, 0.24].flatMap((x): PartSpec[] => [
            { geo: new THREE.CylinderGeometry(0.33, 0.33, 0.08, 16), color: OLIVE_D, pos: [x, 0.1, -1.15], rot: [Math.PI / 2, 0, 0] },
            { geo: new THREE.CylinderGeometry(0.27, 0.27, 0.1, 16), color: 0x111111, pos: [x, 0.1, -1.17], rot: [Math.PI / 2, 0, 0] },
          ]),
          ...[-0.75, 0, 0.75].map((z): PartSpec => ({ geo: bevelBox(1.06, 1.16, 0.08, 0.02), color: OLIVE_D, pos: [0, 0, z] })),
          // 管里的弹头、两侧提手、顶上吊耳、后盖
          ...[-0.24, 0.24].map((x): PartSpec => ({ geo: new THREE.ConeGeometry(0.22, 0.4, 16, 1, true), color: 0x6a5a3a, pos: [x, 0.1, -1.0], rot: [-Math.PI / 2, 0, 0] })),
          ...[-1, 1].flatMap((sx) => [-0.45, 0.45].map((z): PartSpec => ({ geo: new THREE.TorusGeometry(0.08, 0.02, 6, 10, Math.PI), color: DARK, pos: [sx * 0.52, 0.2, z], rot: [0, Math.PI / 2, -Math.PI / 2] }))),
          ...[-0.6, 0.6].map((z): PartSpec => ({ geo: new THREE.TorusGeometry(0.07, 0.025, 6, 10, Math.PI), color: DARK, pos: [0, 0.58, z], rot: [0, Math.PI / 2, 0] })),
          { geo: bevelBox(0.9, 1.0, 0.06, 0.02), color: OLIVE_D, pos: [0, 0, 1.17] },
          ...(ultimate ? [-0.36, 0, 0.36].map((z): PartSpec => ({ geo: new THREE.BoxGeometry(1.08, 0.12, 0.14), color: z === 0 ? 0x1a1a1a : 0xd8a83a, pos: [0, 0.52, z] })) : []),
        ]), at), body, pod);
        for (const x of [-0.24, 0.24]) point(pod, x, 0.1, -1.25);
      } else {
        const cols = branch === 'A' ? 3 : 2;
        const rows = branch === 'A' ? 3 : 3;
        const w = cols * 0.32 + 0.2;
        const h = rows * 0.32 + 0.2;
        // T172：箱体 / 加强箍 / 后盖 / 管口圈从奶白（0xd4d8bc 等）改成车身两档橄榄；
        // T181：箱侧整圈奶白识别条（顶面和两侧一整条，比车身任何一处白条都长）改成深一档车漆的压条，发射舱和车身同一块漆
        mk(paintUVAt(geo.merged(`pt-pod-hi-${cols}x${rows}-${s}`, () => {
          const p: PartSpec[] = [
            { geo: bevelBox(w, h, 2.2, 0.05), color: OLIVE },
            { geo: new THREE.BoxGeometry(w + 0.06, 0.08, 2.24), color: OLIVE_D, pos: [0, h / 2 - 0.25, 0] },
            // 箱体三道加强箍 + 后盖
            ...[-0.7, 0, 0.7].map((z): PartSpec => ({ geo: bevelBox(w + 0.05, h + 0.05, 0.08, 0.02), color: OLIVE_D, pos: [0, 0, z] })),
            { geo: bevelBox(w - 0.1, h - 0.1, 0.06, 0.02), color: OLIVE_D, pos: [0, 0, 1.12] },
          ];
          for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) {
            const x = -w / 2 + 0.26 + c * 0.32, y = -h / 2 + 0.26 + r * 0.32;
            p.push({ geo: new THREE.CylinderGeometry(0.135, 0.135, 0.04, 12), color: OLIVE_D, pos: [x, y, -1.11], rot: [Math.PI / 2, 0, 0] });
            p.push({ geo: new THREE.CylinderGeometry(0.105, 0.105, 0.06, 12), color: 0x121212, pos: [x, y, -1.125], rot: [Math.PI / 2, 0, 0] });
            p.push({ geo: new THREE.ConeGeometry(0.08, 0.16, 10, 1, true), color: 0x6a5a3a, pos: [x, y, -1.08], rot: [-Math.PI / 2, 0, 0] });
          }
          return p;
        }), at), body, pod);
        for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) point(pod, -w / 2 + 0.26 + c * 0.32, -h / 2 + 0.26 + r * 0.32, -1.2);
      }
    }
    paintBody(group, body);
    if (ultimate) mk(geo.merged('pt-rgold', () => [{ geo: frustum(chamfer(2.82, 3.22, 0.6), chamfer(2.8, 3.2, 0.6), 0.1, 0.3), color: GOLD }]), metal);
    steel('rocket', [-0.7, 0.8, 1.2]);
    const kit = fusion === 'snare' ? snareKit(geo, group, metal) : fusion === 'swarm' ? swarmKit(geo, group, metal) : null;
    group.updateMatrixWorld(true);
    return { group, recoil: null, recoilRest: 0, muzzles, anchorPos: seats, ult: kit, gun: pods.map((p) => new THREE.Box3().setFromObject(p)) };
  }

  if (core === 'vulcan') {
    const v = vulcanTurret(geo, group, branch, ultimate, body, metal, muzzles, tier);
    const mega = ultimate && branch === 'B';
    const quad = ultimate && branch === 'A';
    const t5 = tier >= 5 && !ultimate;
    const w = mega ? 3.0 : 2.7;
    const vk = `${quad ? 'quad' : mega ? 'mega' : 'std'}${t5 ? '5' : ''}-${branch}`;
    // 车长塔、舱盖、烟幕弹、尾舱后壁储物箱；尾舱顶置物架（四联两个挂点在尾舱上，不放）；两侧储物箱（5 级换挂甲以后不放）
    const shell = group.children.find((o) => (o as THREE.Mesh).isMesh && (o as THREE.Mesh).material === body) as THREE.Mesh | undefined;
    // T177 托架：四联的挂点在尾舱上方（侧壁 = 尾舱侧面），其余在炮塔两侧（侧壁 = 炮塔斜侧面）
    const seats = v.anchors.map(([x, y, z]): [number, number, number] => [x, y + PAD_LIFT, z]);
    const seatWall: [[number, number], [number, number]] = quad ? [[0.9, 0.75], [1.0, 0.16]] : [[w / 2 - 0.25, 0.85], [w / 2, 0.16]];
    if (shell) augment(geo, shell, `vul-kit-${vk}`, () => [
      ...pads(seats, seatWall, quad ? 1.15 : 1.05, quad ? 0.32 : 0.3),
      ...cupola(-0.7, 1.0, 0.55, 0.92),
      ...hatch(0.45, 0.85, 0.6, 0.26),
      ...[-1, 1].flatMap((s) => smoke(s * 1.0, 0.68, -1.38, s, 0.4)),
      ...lidBox(w - 1.1, 0.3, 0.18, 0x5c5236, [0, 0.42, 2.18]),
      ...(quad ? [] : roofRack(-0.8, 0.8, 1.25, 2.0, 0.75, !ultimate, 0.18)),
      ...(t5 ? [] : [-1, 1].flatMap((s) => lidBox(0.24, 0.36, 0.5, CRATE, [s * ((w - 0.7) / 2 + 0.14), 0.42, 1.6]))),
      { geo: new THREE.CylinderGeometry(0.06, 0.08, 0.14, 8), color: DARK, pos: [-1.0, 0.92, 1.3] },
      // 车长塔防空机枪、探照灯、前脸附加装甲、尾舱油桶；两侧备用链板（四联 / 千钧的挂点在两侧，不放）
      ...aaGun(-0.7, 1.17, 0.55),
      ...searchlight(0.95, 0.86, 0.2),
      ...[-1, 1].map((s): PartSpec => ({ geo: bevelBox(0.1, 0.46, 0.75, 0.03), color: OLIVE_D, pos: [s * (w / 2 - 0.12), 0.42, -1.3], rot: [0, s * Math.PI / 4, 0] })),
      ...(ultimate ? [] : [...jerryCan([-0.45, 1.0, 1.65], [0, Math.PI / 2, 0]), ...jerryCan([0.45, 1.0, 1.65], [0, Math.PI / 2, 0])]),
      ...(quad ? [] : [-1, 1].flatMap((s) => sideLinks(geo, s * (w / 2 + 0.03), 0.38, mega ? 0.62 : 0.35, s, t5 && branch === 'A' ? 1 : mega ? 3 : 2))),
      // 弹幕线（双联）以外：车长塔前的测距仪、两侧挂甲
      ...(branch === 'A' ? [] : [
        ...rangefinder(-0.1, 1.0, -0.15, 1.5),
        ...[-1, 1].flatMap((s): PartSpec[] => [
          { geo: bevelBox(0.2, 0.14, 0.16, 0.02), color: OLIVE_D, pos: [s * 0.55, 0.92, -0.7] },
          { geo: new THREE.BoxGeometry(0.15, 0.05, 0.02), color: GLASS, pos: [s * 0.55, 0.94, -0.785] },
        ]),
        // T177：三块挂甲整体往前挪 0.3（最后一块原来伸到尾舱后角 z = 2.33，正好蹭车尾挂件）
        ...[-1, 1].flatMap((s) => [-0.05, 0.55, 1.15].flatMap((z): PartSpec[] => [
          { geo: bevelBox(0.06, 0.28, 0.55, 0.015), color: DARK, pos: [s * (w / 2 + 0.02), 0.35, z + 0.6], rot: [0, 0, s * 0.18] },
          { geo: bevelBox(0.08, 0.09, 0.08, 0.015), color: 0x2a2c2e, pos: [s * (w / 2 + 0.0), 0.5, z + 0.6] },
        ])),
      ]),
    ]);
    paintBody(group, body);
    steel(`vulcan-${vk}`, [-1.0, 0.85, 1.3]);
    const kit = fusion === 'gunship' ? gunshipKit(geo, group, metal, w) : fusion === 'curtain' ? curtainKit(geo, group, metal, w, mega) : null;
    // 火神炮：炮耳座前沿往外（机匣 + 管簇）
    return { group, recoil: null, recoilRest: 0, muzzles, anchorPos: seats, ult: kit, vulcan: v.rig, gun: [frontBox(group, -1.7)] };
  }

  // ---------------- 激光：炉脊光矛（D1-014 方案一，模型在 prismTurret.ts）：装甲 / 金属 / 镜片 / 发光晶体各合一件
  const mats: Record<keyof PrismParts, THREE.Material> = { armor: body, steel: metal, lens: MAT.prismLens, glow: MAT.prism };
  let parts: PrismParts | undefined;
  // T177：挂点抬到托架顶（原来压在转台钢圈边上，半个座圈悬空），托架斜撑落到转台底座侧面
  const seats = side(1.3, 0.66, 0.9);
  for (const layer of ['armor', 'steel', 'lens', 'glow'] as const) {
    const key = `pt-lance-${layer}-${branch}-${ultimate}`;
    // 发光晶体只有棱镜折射（侧翼折射镜）和脉冲长枪（线圈）才有
    if (layer === 'glow' && branch !== 'A' && !(branch === 'B' && ultimate)) continue;
    const mesh = mk(geo.merged(key, () => (parts ??= prismTurret(branch, ultimate))[layer]), mats[layer]);
    mesh.name = `prism-${layer}`;
    if (layer === 'lens' || layer === 'glow') mesh.castShadow = false;
    // 装甲件加：转台两侧挂甲、前角烟幕弹、天线座；聚焦长枪那一路镜组更长更重，尾部弹药箱不放
    if (layer === 'armor') augment(geo, mesh, `lance-kit-${branch}-${ultimate}`, () => [
      ...[-1, 1].flatMap((s) => [-0.55, 0.15].flatMap((z): PartSpec[] => [
        { geo: bevelBox(0.07, 0.28, 0.62, 0.015), color: DARK, pos: [s * 1.7, 0.33, z], rot: [0, 0, s * 0.16] },
        { geo: bevelBox(0.09, 0.09, 0.08, 0.015), color: 0x2a2c2e, pos: [s * 1.68, 0.46, z] },
      ])),
      ...(branch === 'B' ? [] : [-1, 1].flatMap((s) => smoke(s * 1.18, 0.6, -1.05, s, 0.4))),
      ...(branch === 'B' ? [] : [-1, 1].flatMap((s) => lidBox(0.46, 0.24, 0.34, CRATE, [s * 0.75, 0.58, 1.5]))),
      { geo: new THREE.CylinderGeometry(0.06, 0.08, 0.14, 8), color: DARK, pos: [0.9, 0.66, 1.7] },
      ...pads(seats, [[1.475, 0.46], [1.625, 0.16]], 1.1, 0.3),
    ]);
  }
  paintBody(group, body);
  // 光束从镜组中轴出来：x / z 和原来一样（打击判定不变），高度对准镜组
  point(group, 0, LANCE_AXIS_Y, branch === 'B' ? -2.9 : -0.45);
  steel('laser', [0.9, 0.6, 1.7]);
  const ult = fusion === 'skyfire' ? skyfireKit(geo, group, metal) : fusion === 'aurora' ? auroraKit(geo, group, metal) : null;
  // 光矛：转台座圈前沿往外（镜组长腔 + 镜口，棱镜折射的两只侧镜也算）
  return { group, recoil: null, recoilRest: 0, muzzles, anchorPos: seats, ult, gun: [frontBox(group, -1.4)] };
}

function anchor(parent: THREE.Object3D, x: number, y: number, z: number): THREE.Object3D {
  const o = new THREE.Object3D();
  o.position.set(x, y, z);
  parent.add(o);
  return o;
}
