import { DROP, DROP_LOW, dropGeometry } from '../render/dropTracer';
import { ShellLooks, shellPickFromUrl, type ShellPick } from '../render/shellLooks';

/**
 * 玩家：主炮/机枪/重炮/霰弹/炼狱弹；敌方：步枪/炮弹/反坦克火箭。
 * 火神（D1-032 第 4.1 / 8.3 节）：vpack = 判定包（不画，带发数）；vt / vth / vtH / vtM = 纯画面曳光（基础 / 每 5 根一根热弹 / 重弹线 / 千钧，不判定）
 */
export type BulletKind = 'shell' | 'mg' | 'heavy' | 'mega' | 'pellet' | 'inferno' | 'rifle' | 'eshell' | 'erocket' | 'ecannon' | 'vpack' | 'vt' | 'vth' | 'vtH' | 'vtM';

/**
 * 子弹沿飞行方向拉长成曳光弹；颜色是显示用的亮色；hidden = 不画（火神判定包）；drop = 画成水滴（scale = 头部半径 / 半径 / 全长，米）；
 * body = 画成金属弹体（T249，主炮）：[半径, 全长]（米），弹底一团白热，color 是弹底的颜色
 */
const LOOK: Record<BulletKind, { color: number; scale: [number, number, number]; y: number; trail: boolean; hidden?: boolean; drop?: boolean; body?: [number, number] }> = {
  shell: { color: 0xffe2a0, scale: [0.8, 0.8, 3.2], y: 2.5, trail: true },
  mg: { color: 0xffc860, scale: [0.17, 0.17, 3.4], y: 2.1, trail: false },
  heavy: { color: 0xffd8a0, scale: [1.7, 1.7, 4.4], y: 2.5, trail: true, body: [0.38, 2.6] },
  /** 双联重炮的特大号炮弹 */
  mega: { color: 0xffd8a0, scale: [2.7, 2.7, 7.0], y: 2.6, trail: true, body: [0.6, 4.2] },
  pellet: { color: 0xffd890, scale: [0.4, 0.4, 1.6], y: 2.3, trail: false },
  /** 炼狱弹（终极特种弹）：红橙色的大号炮弹，拖火尾 */
  inferno: { color: 0xff8a3a, scale: [2.2, 2.2, 5.6], y: 2.5, trail: true },
  /** 敌方步枪 / 机枪（T247）：红色细长曳光线，白热弹头 */
  rifle: { color: WARN_ENEMY, scale: [0.075, 0.075, 4.6], y: 1.8, trail: false, drop: true },
  eshell: { color: WARN_ENEMY, scale: [1.3, 1.3, 4.8], y: 2.3, trail: true },
  erocket: { color: WARN_ENEMY, scale: [0.9, 0.9, 3.6], y: 1.9, trail: true },
  /** 秃鹫机炮（T091）：从天上斜着打下来的曳光，比步枪弹粗一圈 */
  ecannon: { color: WARN_ENEMY, scale: [0.11, 0.11, 5.6], y: 1.8, trail: false, drop: true },
  vpack: { color: 0, scale: [0, 0, 0], y: 2.2, trail: false, hidden: true },
  // 流星曳光（T086）：头粗 0.18 / 0.2 / 0.24 / 0.34 米（T085 0.3 / 0.36 / 0.42 / 0.6），全长 6.6 / 7.6 / 7 / 7.8 米（T085 3.4 / 4 / 3.8 / 4.4），细尾拉长渐隐
  vt: { color: 0xffa040, scale: [0.09, 0.09, 6.6], y: 2.2, trail: false, drop: true },
  vth: { color: 0xffc070, scale: [0.1, 0.1, 7.6], y: 2.2, trail: false, drop: true },
  vtH: { color: 0xe88a34, scale: [0.12, 0.12, 7], y: 2.2, trail: false, drop: true },
  vtM: { color: 0xd06424, scale: [0.17, 0.17, 7.8], y: 2.4, trail: false, drop: true },
};

/**
 * 主炮弹体外形（T249）：[半径, 从弹底量起的位置]，最粗 1、全长 1。平弹底 → 船尾收口 → 弹带（略鼓）→ 圆柱弹身 → 尖拱弹头。
 * 每段颜色：弹底暗钢、弹身枪铁灰、弹带紫铜、弹头下一道黄色标识带、弹头钢灰
 */
const SHELL: [number, number][] = [
  [0, 0], [0.7, 0], [0.76, 0.03], [0.86, 0.1], [0.94, 0.16], [0.95, 0.19], [1, 0.2], [1, 0.26], [0.95, 0.27],
  [0.95, 0.5], [0.95, 0.56], [0.94, 0.62], [0.9, 0.69], [0.83, 0.76], [0.72, 0.83], [0.57, 0.89], [0.4, 0.94], [0.22, 0.975], [0.06, 0.997], [0, 1],
];
const SHELL_SIDES = 24;

/** 敌方炮弹 / 火箭、炼狱弹等的弹体外形（T247，头在 z = 0，弹底在 -1，半径最粗 1）：尖拱弹头、圆柱弹身、弹带凸一圈、船尾收口 */
const BODY_SHAPE: [number, number][] = [[0, 0], [0.3, 0.05], [0.58, 0.12], [0.8, 0.2], [0.95, 0.3], [1, 0.38], [1, 0.76], [1.08, 0.78], [1.08, 0.84], [1, 0.86], [0.92, 0.9], [0.72, 1], [0, 1]];

/**
 * 有弹体的弹种（T247，制作人「炮弹像光球」）：弹体半径 r / 全长 len（米）、弹头白热 hot、花纹 band（0 无 / 1 榴弹竖纹，转起来看得出 / 2 火箭红色预警环）、
 * 弹底拖的速度尾迹粗 tw / 长 tl（米）、尾迹颜色（我方浅黄 / 敌方红，取 markColors）。低档不画弹体，只剩尾迹。
 * 重炮 / 双联重炮（heavy / mega）不在这里：走弹道方案（T252 定版 P / A / G），?shell=0 走 T249 圆弹
 */
interface BodyLook { r: number; len: number; hot: number; band: number; tw: number; tl: number; tail: number }
const BODY: Partial<Record<BulletKind, BodyLook>> = {
  shell: { r: 0.15, len: 1.1, hot: 0.5, band: 0, tw: 0.2, tl: 5, tail: MARK_SELF },
  inferno: { r: 0.3, len: 2.2, hot: 1, band: 0, tw: 0.4, tl: 9, tail: MARK_SELF },
  eshell: { r: 0.2, len: 1.5, hot: 0.4, band: 0, tw: 0.26, tl: 7, tail: WARN_ENEMY },
  erocket: { r: 0.17, len: 1.7, hot: 0, band: 2, tw: 0.32, tl: 3.2, tail: WARN_ENEMY },
};
/** 榴弹线（grenade）：短粗弹体、竖纹跟着自旋（圈 / 秒）、尾迹短，主要靠拖烟；lob = 画面上的抛物线最高点（按目标距离 × k，夹在 min～max 米） */
const HOWITZER: BodyLook & { spin: number; lob: { k: number; min: number; max: number } } = { r: 0.25, len: 1.25, hot: 0, band: 1, tw: 0.16, tl: 2.6, tail: MARK_SELF, spin: 9, lob: { k: 0.09, min: 1.2, max: 4.5 } };
/** 画面上最少几个像素宽（远处飞来的也看得见） */
const MIN_PX = { drop: 1.6, body: 2 };

/** 远处变细时按屏幕像素撑宽（局部 xy = 截面方向）；uPx = 2 ÷ 画面高（像素） */
const WIDEN = /* glsl */ `
  uniform float uPx;
  uniform float uMinPx;
  vec3 widen(vec3 p) {
    vec4 c = modelViewMatrix * instanceMatrix * vec4(0.0, 0.0, 0.0, 1.0);
    float w = max(length(instanceMatrix[0].xyz), 1e-4);
    float need = 0.5 * uMinPx * uPx * max(-c.z, 0.05) / projectionMatrix[1][1];
    return vec3(p.xy * max(1.0, need / w), p.z);
  }`;

/** 弹体：钢灰弹身 + 铜弹带，正对视线亮、边缘暗；弹头按 hot 白热，弹底一圈曳光（实例色）；不透明 */
function bodyMaterial(px: { value: number }): THREE.ShaderMaterial {
  return new THREE.ShaderMaterial({
    uniforms: { uPx: px, uMinPx: { value: MIN_PX.body } },
    vertexShader: /* glsl */ `
      attribute float aT;
      attribute vec2 iLook;
      varying float vT;
      varying float vF;
      varying vec2 vP;
      varying vec2 vL;
      varying vec3 vC;
      ${WIDEN}
      void main() {
        vec4 mv = modelViewMatrix * instanceMatrix * vec4(widen(position), 1.0);
        mat3 im = mat3(instanceMatrix);
        vec3 n = normalMatrix * (im * (normal / vec3(dot(im[0], im[0]), dot(im[1], im[1]), dot(im[2], im[2]))));
        vF = clamp(abs(dot(n, -mv.xyz)) * inversesqrt(max(dot(n, n) * dot(mv.xyz, mv.xyz), 1e-12)), 0.0, 1.0);
        vT = aT;
        vP = position.xy;
        vL = iLook;
        vC = instanceColor;
        gl_Position = projectionMatrix * mv;
      }`,
    fragmentShader: /* glsl */ `
      varying float vT;
      varying float vF;
      varying vec2 vP;
      varying vec2 vL;
      varying vec3 vC;
      void main() {
        float ring = step(0.76, vT) * step(vT, 0.86);
        vec3 col = mix(vec3(0.3, 0.29, 0.27), vec3(0.62, 0.45, 0.22), ring);
        float side = abs(vP.y) * inversesqrt(max(dot(vP, vP), 1e-8));
        if (vL.y > 0.5 && vL.y < 1.5) col = mix(vec3(0.33, 0.35, 0.24), vec3(0.85, 0.82, 0.7), step(0.9, side) * (1.0 - ring));
        col *= 0.45 + 0.9 * vF;
        if (vL.y > 1.5) col = mix(col, vC * 2.2, step(0.24, vT) * step(vT, 0.34));
        col = mix(col, vec3(1.0, 0.95, 0.86) * 2.6, vL.x * (1.0 - smoothstep(0.0, 0.22, vT)));
        col = mix(col, vC * 2.4, smoothstep(0.9, 1.0, vT));
        gl_FragColor = vec4(col, 1.0);
        #include <colorspace_fragment>
      }`,
  });
}

function shellGeometry(): THREE.BufferGeometry {
  const g = new THREE.LatheGeometry(SHELL.map(([r, t]) => new THREE.Vector2(r, t)), SHELL_SIDES);
  g.rotateX(Math.PI / 2);
  g.translate(0, 0, -0.5);
  const pos = g.getAttribute('position');
  const col = new Float32Array(pos.count * 3);
  const c = new THREE.Color();
  for (let i = 0; i < pos.count; i++) {
    const t = pos.getZ(i) + 0.5;
    c.setHex(t < 0.02 ? 0x3a3834 : t < 0.185 ? 0x6e6c66 : t < 0.275 ? 0xb06a38 : t < 0.5 ? 0x7c7a72 : t < 0.56 ? 0xc8a03a : 0x8e8c84);
    col.set([c.r, c.g, c.b], i * 3);
  }
  g.setAttribute('color', new THREE.BufferAttribute(col, 3));
  return g;
}

/** 头部亮实（芯发白、正对视线最亮），往尾巴按距离渐隐；叠加混合，不写深度 */
function dropMaterial(px: { value: number }): THREE.ShaderMaterial {
  return new THREE.ShaderMaterial({
    uniforms: { uPx: px, uMinPx: { value: MIN_PX.drop } },
    vertexShader: /* glsl */ `
      attribute float aT;
      varying float vT;
      varying float vF;
      varying vec3 vC;
      ${WIDEN}
      void main() {
        vec4 mv = modelViewMatrix * instanceMatrix * vec4(widen(position), 1.0);
        mat3 im = mat3(instanceMatrix);
        vec3 n = normalMatrix * (im * (normal / vec3(dot(im[0], im[0]), dot(im[1], im[1]), dot(im[2], im[2]))));
        vF = clamp(abs(dot(n, -mv.xyz)) * inversesqrt(max(dot(n, n) * dot(mv.xyz, mv.xyz), 1e-12)), 0.0, 1.0);
        vT = aT;
        vC = instanceColor;
        gl_Position = projectionMatrix * mv;
      }`,
    fragmentShader: /* glsl */ `
      varying float vT;
      varying float vF;
      varying vec3 vC;
      void main() {
        float head = 1.0 - smoothstep(0.0, 0.12, vT);
        float a = min(1.0, pow(clamp(1.0 - vT, 0.0, 1.0), 1.05) * (0.65 + 0.35 * vF) + 0.3 * head);
        vec3 tail = mix(vC * 1.6, vC * vec3(1.0, 0.65, 0.4), smoothstep(0.1, 0.95, vT));
        vec3 col = mix(tail, vec3(1.0, 0.93, 0.78) * vC.r, head * (0.5 + 0.4 * vF)) * (1.0 + 3.2 * head * (0.5 + 0.5 * vF));
        gl_FragColor = vec4(col, a);
        #include <colorspace_fragment>
      }`,
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    toneMapped: false,
  });
}

export interface Bullet {
  kind: BulletKind;
  alive: boolean;
  fromPlayer: boolean;
  x: number;
  y: number;
  z: number;
  vx: number;
  vz: number;
  damage: number;
  life: number;
  /** >0 时为爆炸弹，命中后产生范围伤害 */
  blastRadius: number;
  /** 还能再穿透几个目标（穿甲弹、机枪满级） */
  pierce: number;
  /** 命中附带燃烧（每秒伤害） */
  burn: number;
  /** 打中过的敌人，避免穿透弹同一帧重复结算 */
  lastHit: unknown;
  dtype: DmgType;
  atk: AtkKind;
  summon: boolean;
  /** 同一颗贯穿弹沿用结果；火神包另存暴击发数。 */
  crit?: boolean;
  critical: number;
  grenade?: boolean;
  /** 穿甲（对重甲 +50%） */
  ap: boolean;
  /** 命中后分裂的子母弹数 */
  bomblets: number;
  /** 直接砸中倍率（T016 D2，榴弹线）：> 0 时被炮弹砸中的那个目标吃 damage × direct、不按爆炸距离打折，溅射到的其他人照旧 */
  direct: number;
  /** 击退力度 */
  knock: number;
  /** 命中时显示伤害数字（主炮） */
  show: boolean;
  /** 贯穿弹每个命中点的小爆炸半径 */
  splash: number;
  /** 伤害来源（战报） */
  src: string;
  player?: number;
  /** 终极特种弹（炼狱弹，阶段 2）：第一次命中敌人 / 撞上障碍 / 打中油桶 / 飞到射程尽头时调一次 Ultimate.onShellHit，之后清掉 */
  ultShell: boolean;
  /** 终极特种弹飞到落点再炸（T017-5d，炼狱）：一路不碰敌人 / 路障，飞满 life 秒在落点起爆 */
  ultPass: boolean;
  /** 火神：-1 不是火神；-2 纯画面曳光；≥ 0 判定包，值 = 第几门炮 */
  vul: number;
  /** 火神判定包里有几发（打路障 / 景物按发数扣耐久） */
  n: number;
  /** 火神穿透包已经穿过的敌人 / 路障 / 残骸（T089：不再重复结算） */
  passed: unknown[];
  /** 水滴曳光：粗细 / 长短倍率、离开管口多久（秒，尾巴从管口长出来）；普通曳光弹也按 sizeW / sizeL 放大（T143 机枪按档加粗） */
  sizeW: number;
  sizeL: number;
  age: number;
  /** 换显示颜色（0 = 照 LOOK）、副武器分级特效的档（-1 = 不是，T143：机枪命中尘柱 / 白闪 / 跳飞 / 弹孔按它） */
  tint: number;
  grade: number;
  /**
   * 两层弹道（T091）：玩家的打天弹（出膛时目标在天上）只撞空中目标、不被房子 / 路障 / 残骸 / 地面敌人挡；敌人的 = 从天上打下来的（秃鹫机炮），地上的掩体不挡。
   * 高度：yd > 0 时飞过 yd 米从 y0 爬到 / 落到 y1（离地米数），之后照这个斜率接着飞；yGo = 已经飞了多远
   */
  air: boolean;
  y0: number;
  y1: number;
  yd: number;
  yGo: number;
  /** 榴弹画面抛物线（T247，只管画，判定照旧贴地平飞）：lob = 预计飞多远（米，0 = 不抛），lobH = 最高点，lift = 这一帧画高了多少 */
  lob: number;
  lobH: number;
  lift: number;
  /** 出膛以后飞了几秒、瞄准点有多远（米，0 = 没瞄地面目标）：只给弹道方案画曲射（T250），判定不用 */
  fly: number;
  reach: number;
}

/** 玩家/敌人共用的子弹池：一个 InstancedMesh 画完所有子弹 */
export class Bullets {
  /** 联机显示读取绘制池，不读取或推进命中判定。 */
  networkMeshes(): THREE.InstancedMesh[] { return [this.mesh, this.drops, this.bodies, this.shells]; }
  readonly list: Bullet[] = [];
  /** 带金属弹体的子弹弹底离中心多远（米，T249）：尾迹从弹底往后喷，不盖住弹体；其他子弹 = 0 */
  static tail(b: Bullet): number {
    const body = LOOK[b.kind].body;
    return body ? body[1] * b.sizeL * 0.5 : 0;
  }

  /** 每帧回调：给带尾迹的子弹喷粒子 */
  onTrail: ((b: Bullet) => void) | null = null;
  /** 飞到寿命尽头（没打中东西）时回调：机枪弹落地溅土 */
  onExpire: ((b: Bullet) => void) | null = null;
  private readonly mesh: THREE.InstancedMesh;
  /** 火神水滴曳光单独一批（+1 次绘制，没有在飞的就不画） */
  private readonly drops: THREE.InstancedMesh;
  private readonly dropGeo = [dropGeometry(DROP, 6), dropGeometry(DROP_LOW, 4)];
  /** 炮弹弹体（T247）一批：+1 次绘制、1 个材质，没有在飞的就不画；尾迹 / 高档光晕并进 drops */
  private readonly bodies: THREE.InstancedMesh;
  private readonly bodyLook: THREE.InstancedBufferAttribute;
  /** 画质档（Game 每帧写）：高 = 弹体 + 尾迹 + 光晕，中 = 弹体 + 尾迹，低 = 只剩尾迹 */
  tier: 'high' | 'medium' | 'low' = 'high';
  private readonly px = { value: 2 / 664 };
  private readonly size = new THREE.Vector2();
  private readonly dir = new THREE.Vector3();
  private readonly qs = new THREE.Quaternion();
  private readonly zAxis = new THREE.Vector3(0, 0, 1);
  /** 主炮金属弹体单独一批（T249，+1 次绘制，没有在飞的就不画）；弹底白热画在曳光那一批里 */
  private readonly shells: THREE.InstancedMesh;
  private readonly fwd = new THREE.Vector3();
  private readonly m = new THREE.Matrix4();
  private readonly q = new THREE.Quaternion();
  private readonly s = new THREE.Vector3();
  private readonly p = new THREE.Vector3();
  private readonly up = new THREE.Vector3(0, 1, 0);
  private readonly c = new THREE.Color();
  private readonly e = new THREE.Euler(0, 0, 0, 'YXZ');
  /** 玩家武器出膛那一刻打的是谁（Core.fire / 机枪 / 火神设、打完清掉）：在天上就出打天弹 */
  aim: Enemy | null = null;
  /** 主炮弹道方案（T250；T252 定版默认 P / A / G，地址栏 ?shell= 或预览页可换） */
  looks: ShellLooks | null = null;
  private readonly scene: THREE.Scene;

  constructor(scene: THREE.Scene, geo: GeoCache, capacity = 700) {
    this.scene = scene;
    this.mesh = new THREE.InstancedMesh(geo.sphere(0.34, 8), new THREE.MeshBasicMaterial({ color: 0xffffff, toneMapped: false }), capacity);
    this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.mesh.setColorAt(0, this.c.setHex(0xffffff));
    this.mesh.frustumCulled = false;
    this.mesh.count = 0;
    this.mesh.renderOrder = 2;
    scene.add(this.mesh);
    this.drops = new THREE.InstancedMesh(this.dropGeo[0], dropMaterial(this.px), 512);
    this.drops.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.drops.setColorAt(0, this.c.setHex(0xffffff));
    this.drops.frustumCulled = false;
    this.drops.count = 0;
    this.drops.visible = false;
    this.drops.renderOrder = 3;
    this.drops.onBeforeRender = (renderer) => {
      renderer.getSize(this.size);
      if (this.size.y > 0) this.px.value = 2 / this.size.y;
    };
    scene.add(this.drops);
    const bodyGeo = dropGeometry(BODY_SHAPE, 10);
    this.bodyLook = new THREE.InstancedBufferAttribute(new Float32Array(160 * 2), 2);
    this.bodyLook.setUsage(THREE.DynamicDrawUsage);
    bodyGeo.setAttribute('iLook', this.bodyLook);
    this.bodies = new THREE.InstancedMesh(bodyGeo, bodyMaterial(this.px), 160);
    this.bodies.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.bodies.setColorAt(0, this.c.setHex(0xffffff));
    this.bodies.frustumCulled = false;
    this.bodies.count = 0;
    this.bodies.visible = false;
    this.bodies.renderOrder = 2;
    this.bodies.onBeforeRender = this.drops.onBeforeRender;
    scene.add(this.bodies);
    this.shells = new THREE.InstancedMesh(shellGeometry(), new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.38, metalness: 0.45 }), 32);
    this.shells.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.shells.frustumCulled = false;
    this.shells.count = 0;
    this.shells.visible = false;
    scene.add(this.shells);
    this.useLooks(shellPickFromUrl());
  }

  /** 榴弹画面抛物线：按预计射程 dist 米定最高点（打天弹不抛） */
  lob(b: Bullet, dist: number): void {
    if (b.yd > 0) return;
    const L = HOWITZER.lob;
    b.lob = Math.max(1, dist);
    b.lobH = THREE.MathUtils.clamp(dist * L.k, L.min, L.max);
  }

  /** 换弹道方案（T250）：三个阶段各一套，null = 那个阶段用 T249 圆弹 */
  useLooks(pick: ShellPick): ShellLooks {
    if (this.looks) this.looks.pick = pick;
    else this.looks = new ShellLooks(this.scene, pick);
    return this.looks;
  }

  /** T249 圆弹每发几个三角面（预览页报账用） */
  get bodyTris(): number {
    const g = this.shells.geometry;
    return (g.index ? g.index.count : g.getAttribute('position').count) / 3;
  }

  spawn(kind: BulletKind, x: number, z: number, vx: number, vz: number, damage: number, fromPlayer: boolean, blastRadius = 0): Bullet {
    let b = this.list.find((item) => !item.alive);
    if (!b) {
      b = { kind, alive: false, fromPlayer, x: 0, y: 0, z: 0, vx: 0, vz: 0, damage: 0, life: 0, blastRadius: 0, pierce: 0, burn: 0, lastHit: null, dtype: 'shell', atk: 'bullet', summon: false, critical: 0, ap: false, bomblets: 0, direct: 0, knock: 0, show: false, splash: 0, src: 'other', ultShell: false, ultPass: false, vul: -1, n: 0, passed: [], sizeW: 1, sizeL: 1, age: 9, tint: 0, grade: -1, air: false, y0: 0, y1: 0, yd: 0, yGo: 0, lob: 0, lobH: 0, lift: 0, fly: 0, reach: 0 };
      this.list.push(b);
    }
    b.kind = kind;
    b.alive = true;
    b.fromPlayer = fromPlayer;
    b.x = x;
    b.z = z;
    b.y = LOOK[kind].y;
    b.vx = vx;
    b.vz = vz;
    b.damage = damage;
    b.life = kind === 'pellet' ? 0.45 : 3.2;
    b.blastRadius = blastRadius;
    b.pierce = 0;
    b.burn = 0;
    b.lastHit = null;
    b.dtype = kind === 'pellet' ? 'small' : blastRadius > 0 ? 'blast' : 'shell';
    b.atk = blastRadius > 0 || kind === 'eshell' || kind === 'erocket' || kind === 'inferno' ? 'blast' : 'bullet';
    b.summon = false;
    b.crit = undefined;
    b.critical = 0;
    b.grenade = false;
    b.ap = false;
    b.bomblets = 0;
    b.direct = 0;
    b.knock = 0;
    b.show = false;
    b.splash = 0;
    b.src = dmgSrc.cur;
    b.player = dmgSrc.player;
    b.ultShell = false;
    b.ultPass = false;
    b.vul = -1;
    b.n = 0;
    b.passed.length = 0;
    b.sizeW = b.sizeL = 1;
    // 尾迹从管口长出来（T247 起敌方曳光和炮弹也这样）
    b.age = BODY[kind] || kind === 'rifle' || kind === 'ecannon' ? 0 : 9;
    b.lob = b.lobH = b.lift = 0;
    b.tint = 0;
    b.grade = -1;
    b.air = false;
    b.yd = b.yGo = 0;
    b.fly = 0;
    const t = this.aim;
    b.reach = t && !t.flying ? Math.hypot(t.group.position.x - x, t.group.position.z - z) : 0;
    if (fromPlayer && t?.flying) this.arc(b, LOOK[kind].y, t.alt + t.aimLift, Math.hypot(t.group.position.x - x, t.group.position.z - z), true);
    return b;
  }

  /** 改成斜着飞的弹道：飞过 dist 米从 y0 到 y1（离地米数）；air = 走天上那一层 */
  arc(b: Bullet, y0: number, y1: number, dist: number, air: boolean): void {
    b.air = air;
    b.y0 = y0;
    b.y1 = y1;
    b.yd = Math.max(1, dist);
    b.yGo = 0;
  }

  /** 地面高度（实体弹坑）：弹道贴着地形飞（坦克在坑里开炮，炮弹从坑里出来） */
  groundAt: ((x: number, z: number) => number) | null = null;

  update(delta: number): void {
    let n = 0;
    let d = 0;
    let k = 0;
    let ks = 0;
    const max = this.mesh.instanceMatrix.count;
    const maxD = this.drops.instanceMatrix.count;
    const maxK = this.bodies.instanceMatrix.count;
    const solid = this.tier !== 'low';
    const halo = this.tier === 'high';
    const maxS = this.shells.instanceMatrix.count;
    const looks = this.looks;
    looks?.begin();
    this.dropLod(!solid);
    for (const b of this.list) {
      if (!b.alive) continue;
      b.x += b.vx * delta;
      b.z += b.vz * delta;
      let h = LOOK[b.kind].y;
      if (b.yd > 0) {
        b.yGo += Math.hypot(b.vx, b.vz) * delta;
        h = Math.max(0.2, b.y0 + ((b.y1 - b.y0) * b.yGo) / b.yd);
      }
      b.y = h + (this.groundAt ? this.groundAt(b.x, b.z) : 0);
      b.life -= delta;
      b.age += delta;
      b.fly += delta;
      if (b.life <= 0) {
        b.alive = false;
        withPlayer(b.player ?? 0, () => this.onExpire?.(b));
        continue;
      }
      const look = LOOK[b.kind];
      // 榴弹画面抛物线：u = 飞了预计射程的几成，画高 4H·u(1-u)，弹头跟着抬 / 压
      let pitch = 0;
      b.lift = 0;
      if (b.lob > 0) {
        const u = b.age * Math.hypot(b.vx, b.vz) / b.lob;
        if (u < 1) {
          b.lift = 4 * b.lobH * u * (1 - u);
          pitch = Math.atan((4 * b.lobH * (1 - 2 * u)) / b.lob);
        }
      }
      const alt = look.body && looks ? looks.of(b) : null;
      if (look.trail && !alt) this.onTrail?.(b);
      if (look.hidden) continue;
      if (alt) {
        // 弹道方案（T250）：弹体、光带进方案自己的批，弹底白热抄进这里的子弹那一批，尾迹方案自己喷
        const o = looks!.draw(b, alt, delta);
        for (let i = 0; i < o.glows && n < max; i++, n++) {
          this.mesh.setMatrixAt(n, o.glowM[i]);
          this.mesh.setColorAt(n, o.glowC[i]);
        }
        continue;
      }
      if (b.yd > 0) this.q.setFromEuler(this.e.set(-Math.atan2(b.y1 - b.y0, b.yd), Math.atan2(b.vx, b.vz), 0));
      else if (pitch) this.q.setFromEuler(this.e.set(-pitch, Math.atan2(b.vx, b.vz), 0));
      else this.q.setFromAxisAngle(this.up, Math.atan2(b.vx, b.vz));
      if (look.body) {
        // 主炮没挑方案（?shell=0）：T249 金属弹体 + 弹底一团压扁的白热（朝后贴在弹底上，不盖住弹身）
        if (ks >= maxS) continue;
        const [r, L] = look.body;
        const w = r * b.sizeW, len = L * b.sizeL;
        const y = b.y + b.lift;
        this.shells.setMatrixAt(ks++, this.m.compose(this.p.set(b.x, y, b.z), this.q, this.s.set(w, w, len)));
        if (n >= max) continue;
        this.fwd.set(0, 0, 1).applyQuaternion(this.q).multiplyScalar(-len * 0.5);
        this.mesh.setMatrixAt(n, this.m.compose(this.p.set(b.x, y, b.z).add(this.fwd), this.q, this.s.set(w * 2.2, w * 2.2, w * 1.1)));
        this.mesh.setColorAt(n, this.c.setHex(b.tint || look.color));
        n++;
        continue;
      }
      const body = b.grenade ? HOWITZER : BODY[b.kind];
      if (body) {
        const v = Math.hypot(b.vx, b.vz);
        const y = b.y + b.lift;
        const w = body.r * b.sizeW;
        const len = body.len * b.sizeL;
        this.dir.copy(this.zAxis).applyQuaternion(this.q);
        if (solid && k < maxK) {
          if (b.grenade) this.qs.setFromAxisAngle(this.zAxis, b.age * HOWITZER.spin * Math.PI * 2);
          else this.qs.identity();
          this.bodies.setMatrixAt(k, this.m.compose(this.p.set(b.x, y, b.z), this.qs.premultiply(this.q), this.s.set(w, w, len)));
          this.bodies.setColorAt(k, this.c.setHex(body.tail));
          this.bodyLook.setXY(k, body.hot, body.band);
          k++;
        }
        // 速度尾迹接在弹底（低档没有弹体，尾迹头顶到弹头位置，就是一根曳光线）
        const back = solid ? len * 0.9 : 0;
        const tl = body.tl * b.sizeL;
        const tlen = Math.max(tl * 0.3, Math.min(tl, b.age * v));
        const tw = body.tw * b.sizeW;
        if (d < maxD) {
          this.drops.setMatrixAt(d, this.m.compose(this.p.set(b.x - this.dir.x * back, y - this.dir.y * back, b.z - this.dir.z * back), this.q, this.s.set(tw, tw, tlen)));
          this.drops.setColorAt(d, this.c.setHex(body.tail));
          d++;
        }
        // 高档：弹身外一层淡光晕，短而宽、很暗（不是光球）
        if (halo && d < maxD) {
          this.drops.setMatrixAt(d, this.m.compose(this.p.set(b.x - this.dir.x * len * 0.3, y - this.dir.y * len * 0.3, b.z - this.dir.z * len * 0.3), this.q, this.s.set(w * 2.6, w * 2.6, len * 1.6 + tlen * 0.25)));
          this.drops.setColorAt(d, this.c.setHex(body.tail).multiplyScalar(0.16));
          d++;
        }
        continue;
      }
      if (look.drop) {
        if (d >= maxD) continue;
        // 尾巴从管口长出来：刚出膛时只有飞过的那一段长（至少三成）
        const L = look.scale[2] * b.sizeL;
        const len = Math.max(L * 0.3, Math.min(L, b.age * Math.hypot(b.vx, b.vz)));
        const w = look.scale[0] * b.sizeW;
        this.drops.setMatrixAt(d, this.m.compose(this.p.set(b.x, b.y, b.z), this.q, this.s.set(w, w, len)));
        this.drops.setColorAt(d, this.c.setHex(look.color).multiplyScalar(b.sizeW));
        d++;
        continue;
      }
      if (n >= max) continue;
      this.mesh.setMatrixAt(n, this.m.compose(this.p.set(b.x, b.y, b.z), this.q, this.s.set(look.scale[0] * b.sizeW, look.scale[1] * b.sizeW, look.scale[2] * b.sizeL)));
      this.mesh.setColorAt(n, this.c.setHex(b.tint || look.color));
      n++;
    }
    looks?.end();
    this.mesh.count = n;
    this.mesh.instanceMatrix.needsUpdate = true;
    if (this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate = true;
    this.shells.count = ks;
    this.shells.visible = ks > 0;
    if (ks > 0) this.shells.instanceMatrix.needsUpdate = true;
    this.drops.count = d;
    this.drops.visible = d > 0;
    if (d > 0) {
      this.drops.instanceMatrix.needsUpdate = true;
      if (this.drops.instanceColor) this.drops.instanceColor.needsUpdate = true;
    }
    this.bodies.count = k;
    this.bodies.visible = k > 0;
    if (k > 0) {
      this.bodies.instanceMatrix.needsUpdate = true;
      if (this.bodies.instanceColor) this.bodies.instanceColor.needsUpdate = true;
      this.bodyLook.needsUpdate = true;
    }
  }

  /** 低画质档换省面的流星外形（每颗 144 → 56 个三角形） */
  dropLod(low: boolean): void {
    this.drops.geometry = this.dropGeo[low ? 1 : 0];
  }

  /** 低画质档：弹道方案的弹体、光带换少棱的外形，尾迹减半（T250） */
  lod(low: boolean): void {
    this.looks?.lod(low);
  }

  retire(b: Bullet): void {
    b.alive = false;
  }

  clear(): void {
    for (const b of this.list) b.alive = false;
    this.mesh.count = 0;
    this.drops.count = 0;
    this.drops.visible = false;
    this.bodies.count = 0;
    this.bodies.visible = false;
    this.shells.count = 0;
    this.shells.visible = false;
    this.looks?.clear();
  }

  get activeCount(): number {
    let n = 0;
    for (const b of this.list) if (b.alive) n++;
    return n;
  }
}
