import { strFromU8, strToU8, zlibSync, unzlibSync } from 'fflate';

const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
/** 不依赖小游戏里可能没有的 btoa、TextEncoder 或 CompressionStream。 */
export function encodePacket(text: string): string {
  if (text.length < 1000) return text;
  const raw = strToU8(text), packed = zlibSync(raw, { level: 1 });
  let out = '';
  for (let i = 0; i < packed.length; i += 3) {
    const n = (packed[i] << 16) | ((packed[i + 1] ?? 0) << 8) | (packed[i + 2] ?? 0);
    out += alphabet[n >>> 18] + alphabet[(n >>> 12) & 63] + (i + 1 < packed.length ? alphabet[(n >>> 6) & 63] : '=') + (i + 2 < packed.length ? alphabet[n & 63] : '=');
  }
  return `~${raw.length}:${out}`;
}
export function decodePacket(text: string): string {
  if (!text.startsWith('~')) return text;
  const split = text.indexOf(':');
  const length = Number(text.slice(1, split)), body = text.slice(split + 1);
  if (!Number.isSafeInteger(length) || length < 1 || length > 1_600_000 || body.length % 4 || !/^[A-Za-z0-9+/]*={0,2}$/.test(body)) throw new Error('invalid packet');
  const padding = body.endsWith('==') ? 2 : body.endsWith('=') ? 1 : 0;
  const packed = new Uint8Array(body.length / 4 * 3 - padding);
  let at = 0;
  for (let i = 0; i < body.length; i += 4) {
    const n = (alphabet.indexOf(body[i]) << 18) | (alphabet.indexOf(body[i + 1]) << 12) | (Math.max(0, alphabet.indexOf(body[i + 2])) << 6) | Math.max(0, alphabet.indexOf(body[i + 3]));
    if (at < packed.length) packed[at++] = n >>> 16;
    if (at < packed.length) packed[at++] = n >>> 8;
    if (at < packed.length) packed[at++] = n;
  }
  return strFromU8(unzlibSync(packed, { out: new Uint8Array(length) }));
}
