import type { Hud } from '../systems/Hud';
import type { DamageNumbers } from './DamageNumbers';
import type { Menu } from './Menu';

/**
 * 界面层接口：Game 只通过这三个接口操作界面。
 * - DOM 版（网页默认）：`systems/Hud.ts`、`ui/Menu.ts`、`ui/DamageNumbers.ts`
 * - 画布版（微信小游戏 / 网页加 `?ui=canvas`）：`ui/canvas/`
 * 接口直接取 DOM 版的公开成员：DOM 版加了新方法，画布版不跟着实现就编译不过。
 */
export type HudApi = { [K in keyof Hud]: Hud[K] };
export type MenuApi = { [K in keyof Menu]: Menu[K] };
export type NumbersApi = { [K in keyof DamageNumbers]: DamageNumbers[K] };

/** 小游戏里没有 HTML/CSS，界面一律画在画布上；网页加 ?ui=canvas 也走画布版（测试 / 对照用） */
export function wantCanvasUi(): boolean {
  const g = globalThis as { wx?: { createCanvas?: unknown }; __WX_CANVAS__?: unknown };
  if (g.__WX_CANVAS__ || typeof g.wx?.createCanvas === 'function') return true;
  try {
    return new URLSearchParams(location.search).get('ui') === 'canvas';
  } catch {
    return false;
  }
}
