import * as THREE from 'three';
import { uploadHead } from './Particles';
import { CRATER_GLSL, WATER_GLSL, type CraterUniforms } from '../world/Craters';

const VERT = /* glsl */ `
${CRATER_GLSL}
attribute vec4 iXform; // x, z, rotation, frame
attribute vec3 iMisc;  // scaleX, scaleZ, alpha
varying vec2 vUv;
varying float vAlpha;
varying vec2 vWorldXZ;
#include <fog_pars_vertex>
void main() {
  // 淡完的槽位（环形缓冲里还占着位）直接丢到裁剪空间外，不算地面高度、不进光栅（T245）
  if (iMisc.z <= 0.0) {
    vUv = vec2(0.0);
    vAlpha = 0.0;
    vWorldXZ = vec2(0.0);
    gl_Position = vec4(2.0, 2.0, 2.0, 1.0);
    return;
  }
  vec2 p = position.xy * iMisc.xy;
  float c = cos(iXform.z);
  float s = sin(iXform.z);
  vec4 world = vec4(iXform.x + p.x * c - p.y * s, 0.05, iXform.y + p.x * s + p.y * c, 1.0);
  // 贴着实体弹坑 / 河道 / 桥面走（平面细分成 3×3，坑里不会悬空；T034 起是 floorH：桥上的履带印在桥面上）
  world.y += floorH(world.xz);
  vWorldXZ = world.xz;
  vec4 mvPosition = viewMatrix * world;
  gl_Position = projectionMatrix * mvPosition;
  vUv = vec2((uv.x + iXform.w) * 0.25, uv.y);
  vAlpha = iMisc.z;
  #include <fog_vertex>
}`;

const FRAG = /* glsl */ `
${WATER_GLSL}
uniform sampler2D map;
varying vec2 vUv;
varying float vAlpha;
varying vec2 vWorldXZ;
#include <fog_pars_fragment>
void main() {
  if (waterH(vWorldXZ) > -999.0) discard;
  vec4 t = texture2D(map, vUv);
  float a = t.a * vAlpha;
  if (a < 0.004) discard;
  gl_FragColor = vec4(t.rgb, a);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
  #include <fog_fragment>
}`;

export const DecalKind = { Scorch: 0, Crater: 1, Tread: 2, Stain: 3 } as const;
export type DecalKind = (typeof DecalKind)[keyof typeof DecalKind];

/** 地面贴花：焦痕、弹坑、履带印、油污。环形缓冲，满了覆盖最老的（弹坑贴花单独一个池子，见 Fx.craterDecals） */
export class Decals {
  readonly mesh: THREE.Mesh;
  /** 全在水里的贴花不入池；跨岸的贴花只画干地片元。 */
  hasLand: (x: number, z: number, radius: number) => boolean = () => true;
  private readonly cap: number;
  /** 这一档的环形缓冲长度（T245 按画质，≤ cap） */
  private limit: number;
  private head = 0;
  private live = 0;
  private readonly x: Float32Array;
  private readonly z: Float32Array;
  private readonly age: Float32Array;
  private readonly life: Float32Array;
  private readonly alpha: Float32Array;
  private readonly aXform: THREE.InstancedBufferAttribute;
  private readonly aMisc: THREE.InstancedBufferAttribute;
  private readonly geometry: THREE.InstancedBufferGeometry;

  /** craters = 实体弹坑的 uniform（和地面共用同一份，坑一变贴花跟着变）；behind = 甩到身后这么多米就回收 */
  constructor(scene: THREE.Scene, atlas: THREE.Texture, capacity: number, craters: CraterUniforms, private readonly behind = 70) {
    this.cap = capacity;
    this.limit = capacity;
    this.x = new Float32Array(capacity);
    this.z = new Float32Array(capacity);
    this.age = new Float32Array(capacity);
    this.life = new Float32Array(capacity);
    this.alpha = new Float32Array(capacity);

    const base = new THREE.PlaneGeometry(1, 1, 3, 3);
    const geo = new THREE.InstancedBufferGeometry();
    geo.index = base.index;
    geo.setAttribute('position', base.getAttribute('position'));
    geo.setAttribute('uv', base.getAttribute('uv'));
    this.aXform = new THREE.InstancedBufferAttribute(new Float32Array(capacity * 4), 4);
    this.aMisc = new THREE.InstancedBufferAttribute(new Float32Array(capacity * 3), 3);
    this.aXform.setUsage(THREE.DynamicDrawUsage);
    this.aMisc.setUsage(THREE.DynamicDrawUsage);
    geo.setAttribute('iXform', this.aXform);
    geo.setAttribute('iMisc', this.aMisc);
    geo.instanceCount = 0;
    this.geometry = geo;

    const mat = new THREE.ShaderMaterial({
      vertexShader: VERT,
      fragmentShader: FRAG,
      uniforms: { ...THREE.UniformsUtils.merge([THREE.UniformsLib.fog, { map: { value: atlas } }]), ...craters },
      transparent: true,
      depthWrite: false,
      fog: true,
      // 平面是在顶点着色器里铺到地上的，原始朝向从上往下看是背面
      side: THREE.DoubleSide,
      polygonOffset: true,
      polygonOffsetFactor: -2,
      polygonOffsetUnits: -2,
    });
    mat.uniforms.map.value = atlas;
    this.mesh = new THREE.Mesh(geo, mat);
    this.mesh.frustumCulled = false;
    this.mesh.renderOrder = 1;
    scene.add(this.mesh);
  }

  /** 调小时超出新长度的那些马上不画，环从头接着写 */
  setLimit(n: number): void {
    const limit = Math.max(1, Math.min(this.cap, n));
    if (limit === this.limit) return;
    this.limit = limit;
    this.head %= limit;
    this.live = Math.min(this.live, limit);
    this.geometry.instanceCount = this.live;
  }

  /** w/d：贴花在 x/z 方向的尺寸；rot：绕竖轴旋转 */
  add(kind: DecalKind, x: number, z: number, w: number, d: number, rot: number, alpha: number, life: number): void {
    if (!this.hasLand(x, z, Math.hypot(w, d) * 0.5)) return;
    const i = this.head;
    this.head = (this.head + 1) % this.limit;
    this.live = Math.min(this.limit, this.live + 1);
    this.x[i] = x;
    this.z[i] = z;
    this.age[i] = 0;
    this.life[i] = life;
    this.alpha[i] = alpha;
    const xf = this.aXform.array as Float32Array;
    xf[i * 4] = x;
    xf[i * 4 + 1] = z;
    xf[i * 4 + 2] = rot;
    xf[i * 4 + 3] = kind;
    const m = this.aMisc.array as Float32Array;
    m[i * 3] = w;
    m[i * 3 + 1] = d;
    m[i * 3 + 2] = alpha;
    this.aXform.addUpdateRange(i * 4, 4);
    this.aXform.needsUpdate = true;
  }

  update(delta: number, playerZ: number): void {
    const m = this.aMisc.array as Float32Array;
    for (let i = 0; i < this.live; i++) {
      if (this.life[i] <= 0) continue;
      this.age[i] += delta;
      // 落到身后很远的直接消失（寿命 Infinity = 不按时间淡出，只按距离回收）
      const t = this.z[i] > playerZ + this.behind ? 1 : this.age[i] / this.life[i];
      if (t >= 1) {
        this.life[i] = 0;
        m[i * 3 + 2] = 0;
        continue;
      }
      // 最后 30% 淡出
      m[i * 3 + 2] = this.alpha[i] * Math.min(1, (1 - t) / 0.3);
    }
    this.geometry.instanceCount = this.live;
    if (this.live) uploadHead(this.aMisc, this.live);
  }

  clear(): void {
    this.live = 0;
    this.head = 0;
    this.geometry.instanceCount = 0;
  }

  dispose(): void {
    this.geometry.dispose();
    (this.mesh.material as THREE.Material).dispose();
  }
}
