import * as THREE from 'three';
import type { Enemy } from '../entities/Enemy';

type Kind = 'hit' | 'big' | 'crit' | 'deflect' | 'player' | 'heal' | 'sub' | 'pbig' | 'warn' | 'pierce' | 'reveal' | 'high';

interface Num {
  el: HTMLSpanElement;
  alive: boolean;
  /** 世界坐标（player 类为屏幕坐标，z = 飘的方向：1 往下、-1 往上） */
  x: number;
  y: number;
  z: number;
  t: number;
  life: number;
  kind: Kind;
  drift: number;
}

interface Pending {
  amount: number;
  t: number;
  /** 合并进来的伤害里有熔甲加成过的（橙色） */
  melt: boolean;
  x: number;
  y: number;
  z: number;
}

const MERGE = 0.22;
/** 副武器伤害数字（T018-1）：同一目标 0.3 秒合并，合起来不到 8 不显示；池子满了不顶掉别的数字 */
const SUB_MERGE = 0.3;
const SUB_MIN = 8;
const POOL = 36;

/**
 * 关键伤害数字：只显示主炮、暴击、首领部件的伤害；同一个敌人 0.22 秒内的伤害合并成一个数。
 * 机枪打重甲显示灰色"偏转"，自己挨重击在血条旁跳红字；炼狱火场里熔甲加成过的主炮伤害是橙色。
 */
export class DamageNumbers {
  enabled = true;
  private readonly layer = document.createElement('div');
  private readonly pool: Num[] = [];
  private readonly pending = new Map<Enemy, Pending>();
  private readonly pendingSub = new Map<Enemy, Pending>();
  private readonly deflected = new WeakMap<Enemy, number>();
  private readonly v = new THREE.Vector3();
  private time = 0;

  constructor(
    private readonly camera: THREE.Camera,
    root: HTMLElement,
  ) {
    this.layer.id = 'dmg-layer';
    root.append(this.layer);
    for (let i = 0; i < POOL; i++) {
      const el = document.createElement('span');
      el.className = 'dmg';
      el.style.display = 'none';
      this.layer.append(el);
      this.pool.push({ el, alive: false, x: 0, y: 0, z: 0, t: 0, life: 0, kind: 'hit', drift: 0 });
    }
  }

  hit(e: Enemy, amount: number, crit: boolean, melt = false): void {
    if (!this.enabled || amount < 0.5) return;
    const p = e.group.position;
    if (crit) {
      this.spawn('crit', `${Math.round(amount)}!`, p.x, 3.2 + e.radius * 0.5 + e.alt, p.z, melt);
      return;
    }
    const cur = this.pending.get(e);
    if (cur) {
      cur.amount += amount;
      cur.melt ||= melt;
      cur.x = p.x;
      cur.z = p.z;
    } else {
      this.pending.set(e, { amount, t: MERGE, melt, x: p.x, y: 2.8 + e.radius * 0.5 + e.alt, z: p.z });
    }
  }

  /** 副武器打出的伤害（T018-1）：小一号、浅钢蓝 */
  sub(e: Enemy, amount: number): void {
    if (!this.enabled || amount <= 0) return;
    const p = e.group.position;
    const cur = this.pendingSub.get(e);
    if (cur) {
      cur.amount += amount;
      cur.x = p.x;
      cur.z = p.z;
    } else this.pendingSub.set(e, { amount, t: SUB_MERGE, melt: false, x: p.x, y: 2.4 + e.radius * 0.5 + e.alt, z: p.z });
  }

  /** 小口径打重甲：灰色"偏转"，同一个敌人 1 秒最多一次 */
  deflect(e: Enemy): void {
    if (!this.enabled) return;
    const last = this.deflected.get(e) ?? -9;
    if (this.time - last < 1) return;
    this.deflected.set(e, this.time);
    const p = e.group.position;
    this.spawn('deflect', '偏转', p.x, 3 + e.radius * 0.5 + e.alt, p.z);
  }

  /** 自己挨的重击：血条旁边跳红字（手机在条下面往下飘、电脑在条上方往上飘，见 nearBar）；big = 巨炮巨弹砸中（特大号，D5） */
  player(amount: number, big = false): void {
    if (!this.enabled || amount < 4) return;
    const [cx, y, dir] = this.nearBar(big ? 26 : 14, big ? 30 : 16);
    this.spawn(big ? 'pbig' : 'player', `-${Math.round(amount)}`, cx + (big ? 0 : (Math.random() - 0.5) * 60), y, dir);
  }

  /** 擦边被巨弹掀起来、没挨打（D5）：坦克头顶弹一个「险！」 */
  warn(x: number, y: number, z: number): void {
    if (!this.enabled) return;
    this.spawn('warn', '险！', x, y, z);
  }

  /** 火神打穿重甲（D1-032 第 4.3 节）：车头上方橙色「击穿」0.6 秒，在伤害数字上面；屏上最多 3 个 */
  pierce(e: Enemy): void {
    if (!this.enabled || this.pool.filter((n) => n.alive && n.kind === 'pierce').length >= 3) return;
    const p = e.group.position;
    this.spawn('pierce', '击穿', p.x, 3.9 + e.radius * 0.6, p.z);
  }

  /** 沙下伏兵被提前掀出来（T122）：鼓包上方黄色「掀出来」 */
  reveal(x: number, y: number, z: number): void {
    if (!this.enabled) return;
    this.spawn('reveal', '掀出来', x, y, z);
  }

  /** 天上的目标太高、主武器抬不上去（T131）：它头上灰色「仰角不够」。是操作提示不是伤害数字，关了伤害数字也照弹 */
  high(e: Enemy): void {
    const p = e.group.position;
    this.spawn('high', '仰角不够', p.x, 3.4 + e.radius * 0.5 + e.alt, p.z);
  }

  /** 回血：血条旁边跳绿色 +数字（同红字） */
  heal(amount: number): void {
    if (!this.enabled) return;
    const [x, y, dir] = this.nearBar(14, 16);
    this.spawn('heal', `+${amount}`, x, y, dir);
  }

  /**
   * 自己的数字跟着耐久条走（T046）：条在顶部（手机）→ 从条下面 below 像素起往下飘；条在左下角（电脑，T036）→ 从条上方 above 像素起往上飘。
   * 返回 [条的中点 x, 起点 y, 方向]
   */
  private nearBar(below: number, above: number): [number, number, number] {
    const bar = document.querySelector('#hp-fill')?.getBoundingClientRect();
    if (!bar) return [120, 60, 1];
    const low = bar.top > window.innerHeight / 2;
    return [bar.left + bar.width * 0.5, low ? bar.top - above : bar.bottom + below, low ? -1 : 1];
  }

  update(delta: number): void {
    this.time += delta;
    for (const [e, p] of this.pending) {
      p.t -= delta;
      if (p.t > 0 && e.alive) continue;
      this.pending.delete(e);
      this.spawn(p.amount >= 100 ? 'big' : 'hit', String(Math.round(p.amount)), p.x, p.y, p.z, p.melt);
    }
    for (const [e, p] of this.pendingSub) {
      p.t -= delta;
      if (p.t > 0 && e.alive) continue;
      this.pendingSub.delete(e);
      if (p.amount >= SUB_MIN) this.spawn('sub', String(Math.round(p.amount)), p.x, p.y, p.z);
    }
    const w = this.layer.clientWidth;
    const h = this.layer.clientHeight;
    for (const n of this.pool) {
      if (!n.alive) continue;
      n.t += delta;
      const k = n.t / n.life;
      if (k >= 1) {
        n.alive = false;
        n.el.style.display = 'none';
        continue;
      }
      // 先弹大再缩回，最后淡出
      const pop = k < 0.12 ? 0.6 + (k / 0.12) * 0.6 : 1.2 - Math.min(0.2, (k - 0.12) * 0.8);
      const alpha = k > 0.7 ? 1 - (k - 0.7) / 0.3 : 1;
      let sx: number;
      let sy: number;
      if (n.kind === 'player' || n.kind === 'heal' || n.kind === 'pbig') {
        sx = n.x;
        sy = n.y + n.z * k * 26;
      } else {
        this.v.set(n.x + n.drift * k, n.y + k * 2.2, n.z).project(this.camera);
        if (this.v.z > 1) {
          n.el.style.opacity = '0';
          continue;
        }
        sx = (this.v.x * 0.5 + 0.5) * w;
        sy = (-this.v.y * 0.5 + 0.5) * h;
      }
      n.el.style.transform = `translate(${sx.toFixed(1)}px, ${sy.toFixed(1)}px) translate(-50%, -50%) scale(${pop.toFixed(3)})`;
      n.el.style.opacity = alpha.toFixed(3);
    }
  }

  clear(): void {
    this.pending.clear();
    this.pendingSub.clear();
    for (const n of this.pool) {
      n.alive = false;
      n.el.style.display = 'none';
    }
  }

  private spawn(kind: Kind, text: string, x: number, y: number, z: number, melt = false): void {
    let n = this.pool.find((it) => !it.alive);
    if (!n) {
      // 池满：顶掉最老的（副武器的小数字不顶别人）
      if (kind === 'sub') return;
      n = this.pool.reduce((a, b) => (a.t / a.life > b.t / b.life ? a : b));
    }
    n.alive = true;
    n.kind = kind;
    n.x = x + (kind === 'player' || kind === 'heal' || kind === 'pbig' || kind === 'warn' || kind === 'pierce' || kind === 'reveal' || kind === 'high' ? 0 : (Math.random() - 0.5) * 1.2);
    n.y = y;
    n.z = z;
    n.t = 0;
    n.life = kind === 'pbig' ? 1.3 : kind === 'warn' || kind === 'reveal' || kind === 'high' ? 1.1 : kind === 'crit' || kind === 'big' ? 0.9 : kind === 'player' || kind === 'heal' ? 0.9 : kind === 'pierce' ? 0.6 : 0.7;
    n.drift = kind === 'warn' || kind === 'pierce' || kind === 'reveal' || kind === 'high' ? 0 : (Math.random() - 0.5) * 1.5;
    n.el.className = `dmg ${kind}${melt ? ' melt' : ''}`;
    n.el.textContent = text;
    n.el.style.display = 'block';
  }
}
