import * as THREE from 'three';
import { Casings } from './Casings';
import { Decals, DecalKind } from './Decals';
import { MuzzleFlash } from './MuzzleFlash';
import { Particles, type EmitOpts } from './Particles';
import { decalAtlas, particleAtlas } from './textures';
import { DRAPE_VERT, WATER_GLSL, craterUniforms } from '../world/Craters';
import type { WaterContact } from '../world/Rivers';

const rand = (a: number, b: number) => a + Math.random() * (b - a);
/** 冒烟的东西甩到坦克身后多远就不再冒烟柱（T017-15c）：燃烧点 10 米（原来 34）、车辆残骸 8 米（原来 45，在 Enemies 里用） */
export const SMOKE_BEHIND = { burn: 10, wreck: 8 };

/**
 * 着火的步兵（T249）：h 人高（米），每跳发 tongues 条火舌、smoke 概率冒一缕黑烟；
 * 同时烧的超过 crowd 个，每人按比例少发，总量不再涨；被毁时身上的火再烧 after 秒
 */
export const TORCH = { h: 1.8, tongues: 4, smoke: 0.6, crowd: 5, after: 2.4 };

// 冲击波：半径随角度抖动的气浪前沿 + 断裂的缺口 + 内部一层薄尘；颜色由暖白过渡到尘土色
const SHOCK_FRAG = /* glsl */ `
${WATER_GLSL}
uniform float uK;
uniform float uSeed;
uniform vec3 uWarm;
uniform float uWaterOnly;
varying vec2 vP;
varying vec2 vWorldXZ;
float h(float n) { return fract(sin(n) * 43758.5453); }
float n1(float x) {
  float i = floor(x);
  float f = fract(x);
  f = f * f * (3.0 - 2.0 * f);
  return mix(h(i + uSeed), h(i + 1.0 + uSeed), f);
}
void main() {
  bool wet = waterH(vWorldXZ) > -999.0;
  if (uWaterOnly > 0.5 && !wet) discard;
  float r = length(vP);
  float a = atan(vP.y, vP.x) / 6.2831853 + 0.5;
  // 前沿半径：低频大起伏 + 高频毛边
  float jag = (n1(a * 7.0) - 0.5) * 0.22 + (n1(a * 23.0 + 5.0) - 0.5) * 0.08;
  float front = 0.25 + uK * 0.75 + jag * (0.4 + uK);
  float width = 0.12 + 0.24 * (1.0 - uK);
  float band = smoothstep(front - width, front, r) * (1.0 - smoothstep(front, front + 0.04, r));
  // 断裂：沿圆周有几段变淡
  float gaps = mix(0.25, 1.0, smoothstep(0.3, 0.65, n1(a * 11.0 + uK * 3.0)));
  // 前沿后面拖着一层薄尘
  float trail = smoothstep(0.0, front, r) * (1.0 - smoothstep(front - 0.02, front, r)) * 0.22;
  float fade = 1.0 - uK;
  float alpha = (band * gaps + trail * n1(a * 17.0)) * fade;
  vec3 col = mix(uWarm * 1.15, vec3(0.86, 0.8, 0.68), smoothstep(0.1, 0.55, uK));
  if (wet) col = vec3(0.72, 0.82, 0.82);
  gl_FragColor = vec4(col, min(1.0, alpha * 1.25));
}`;

// 火球体（T027-c 巨炮巨弹落地）：一个会翻滚的火球网格——顶点按两层噪声往外鼓（翻滚的火团），越往后越往上鼓；
// 正对镜头的地方白热、边上橙、最后退成暗褐的烟色淡掉（暖色，不用大红）；0 粒子，在场时 +1 次绘制
const BALL_VERT = /* glsl */ `
uniform float uT;
uniform float uSeed;
varying vec3 vN;
varying vec3 vV;
varying float vNoise;
#include <fog_pars_vertex>
float hash3(vec3 p) { return fract(sin(dot(p, vec3(127.1, 311.7, 74.7)) + uSeed) * 43758.5453); }
float noise3(vec3 p) {
  vec3 i = floor(p);
  vec3 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash3(i), b = hash3(i + vec3(1.0, 0.0, 0.0)), c = hash3(i + vec3(0.0, 1.0, 0.0)), d = hash3(i + vec3(1.0, 1.0, 0.0));
  float e = hash3(i + vec3(0.0, 0.0, 1.0)), g = hash3(i + vec3(1.0, 0.0, 1.0)), h = hash3(i + vec3(0.0, 1.0, 1.0)), k = hash3(i + vec3(1.0, 1.0, 1.0));
  return mix(mix(mix(a, b, f.x), mix(c, d, f.x), f.y), mix(mix(e, g, f.x), mix(h, k, f.x), f.y), f.z);
}
void main() {
  vec3 p = position;
  float n = noise3(p * 2.1 + vec3(0.0, -uT * 2.5, 0.0));
  float n2 = noise3(p * 4.3 + vec3(uT * 1.7, 0.0, 3.1));
  vNoise = n * 0.65 + n2 * 0.35;
  p *= 0.82 + vNoise * 0.42;
  p.y *= 0.85 + 0.25 * uT;
  vec4 mvPosition = modelViewMatrix * vec4(p, 1.0);
  vN = normalize(normalMatrix * normal);
  vV = normalize(-mvPosition.xyz);
  gl_Position = projectionMatrix * mvPosition;
  #include <fog_vertex>
}`;
const BALL_FRAG = /* glsl */ `
uniform float uT;
uniform float uAlpha;
varying vec3 vN;
varying vec3 vV;
varying float vNoise;
#include <fog_pars_fragment>
void main() {
  float facing = abs(dot(normalize(vN), normalize(vV)));
  float heat = clamp((1.0 - uT * 1.3) * 0.75 + (vNoise - 0.5) * 0.85 + facing * 0.2, 0.0, 1.0);
  vec3 c = mix(vec3(0.18, 0.11, 0.07), vec3(0.98, 0.42, 0.08), smoothstep(0.1, 0.42, heat));
  c = mix(c, vec3(1.0, 0.64, 0.24), smoothstep(0.5, 0.8, heat));
  c = mix(c, vec3(1.0, 0.8, 0.48), smoothstep(0.9, 1.0, heat));
  c *= 1.0 + 0.5 * smoothstep(0.6, 1.0, heat);
  // 边上软、团块状的缺口（看着是一团团翻滚的火，不是一个光滑的球）
  float lump = smoothstep(0.28, 0.55, vNoise + (1.0 - uT) * 0.15);
  float a = uAlpha * smoothstep(0.05, 0.6, facing) * lump * smoothstep(0.0, 0.06, uT) * (1.0 - smoothstep(0.5, 1.0, uT)) * 0.92;
  if (a < 0.02) discard;
  gl_FragColor = vec4(c, a);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
  #include <fog_fragment>
}`;

/**
 * 一朵正在长的蘑菇云：t 起爆后秒数，s 宽度规模（帽宽、烟团大小），h 高度规模（云顶多高），rise 云顶升到顶要几秒，life 烟团寿命倍数，n 发射密度（大号云少而大），
 * ring 要不要凝结环；surge / condensed 已放过底涌 / 凝结环，stem / cap / fire 烟柱 / 云帽 / 火柱的发射计时
 */
interface Cloud {
  x: number;
  z: number;
  s: number;
  h: number;
  rise: number;
  life: number;
  n: number;
  /** 烟柱粗细倍数（核弹的柱子相对帽子细一些） */
  w: number;
  t: number;
  ring: boolean;
  surge: boolean;
  condensed: boolean;
  stem: number;
  cap: number;
  fire: number;
}

/** 蘑菇云的可选项（T057）：tall = 高度规模（默认和宽度一样）、rise = 云顶升到顶的秒数（默认 3）、linger = 烟团寿命倍数（核弹留得久）、n = 发射密度（默认按规模算）、stem = 烟柱粗细倍数 */
export interface CloudOpts {
  tall?: number;
  rise?: number;
  linger?: number;
  n?: number;
  stem?: number;
}

/** 飘落的灰 / 余烬（T057 余韵）：(x, z) 周围 r 米、高 top 米以下，dur 秒，每秒 rate 片；ember = 其中几成是发红的火星；up = 从烧过的地上往上飘（不是从天上落） */
interface Fallout {
  x: number;
  z: number;
  r: number;
  top: number;
  t: number;
  dur: number;
  rate: number;
  ember: number;
  up: boolean;
  acc: number;
}

/** 特效预设：火光、烟尘、火花、闪光、地面焦痕。底层是两套实例化粒子 + 一套贴花 */
export class Fx {
  onNetworkExplosion: ((x: number, z: number, size: number, y: number, scorch: boolean, smoke: number, surface: boolean) => void) | null = null;
  readonly glow: Particles;
  readonly smokeP: Particles;
  readonly decals: Decals;
  /** 弹坑贴花单独一个池子（T016-1）：不按时间淡出、甩到身后 40 米才回收，不再和履带印抢环形缓冲；+1 次绘制 */
  readonly craterDecals: Decals;
  /** 火神弹沟（D1-032 第 8.4 节）：单独一个池（160），不挤掉弹坑 / 焦痕；+1 次绘制 */
  readonly grooves: Decals;
  /** 火神弹壳（+1 次绘制） */
  readonly casings: Casings;
  /** 火神枪口爆闪（T088，+1 次绘制） */
  readonly muzzleFlash: MuzzleFlash;
  private readonly light = new THREE.PointLight(0xffa860, 0, 38, 1.6);
  private lightPower = 0;
  /** 地面冲击波环：爆炸时贴地扩散 */
  private readonly rings: { mesh: THREE.Mesh; t: number; dur: number; r: number; alive: boolean }[] = [];
  /** 冲击波环的网格：径向细分 16 圈（贴着弹坑往下凹时不会切进坑壁） */
  private readonly ringGeo = new THREE.RingGeometry(0.001, 1, 48, 16);
  private readonly scene: THREE.Scene;
  /** 实体弹坑的 uniform（T014-3）：地面、坑、贴花、冲击波环、预警圈都引用这同一份（Craters 每次挖坑 / 回收时改里面的值） */
  readonly craterU = craterUniforms();
  /** 持续燃烧点：地面火、燃烧的残骸、远处的黑烟柱 */
  private readonly burners: { x: number; z: number; g: number; t: number; dur: number; size: number; fire: boolean; acc: number }[] = [];
  /** 最近在烧的步兵大约有几个（每跳 +1、按 4 跳 / 秒衰减） */
  private torchLoad = 0;
  /** 风：烟柱往一边斜 */
  private wind = 0.9;
  /** 正在长的蘑菇云（核弹 / 炼狱 / 天火坍缩） */
  private readonly clouds: Cloud[] = [];
  /** 正在飘的灰 / 余烬（T057） */
  private readonly fallouts: Fallout[] = [];
  /** 正在往上窜的火柱（T057 炼狱 / 天火坍缩）：t 秒、dur 总长、h 多高、s 多粗、acc 发射计时 */
  private readonly pillars: { x: number; z: number; g: number; t: number; dur: number; h: number; s: number; acc: number }[] = [];
  /** 地面高度（实体弹坑）：贴地的爆炸 / 尘土 / 冲击波 / 燃烧点落在坑底 */
  groundAt: (x: number, z: number) => number = () => 0;
  /** 现有河道数据查表；干地 / 桥面返回 −∞。 */
  waterAt: (x: number, z: number) => number = () => -Infinity;
  waterNear: (x: number, z: number, radius: number) => WaterContact | null = () => null;
  hasLand: (x: number, z: number, radius: number) => boolean = () => true;
  /** 火球体（T027-c）：两个网格轮流用 */
  private readonly balls: { mesh: THREE.Mesh<THREE.SphereGeometry, THREE.ShaderMaterial>; t: number; dur: number; r0: number; r1: number; y0: number; rise: number; alive: boolean }[] = [];
  private readonly ballGeo = new THREE.SphereGeometry(1, 28, 20);

  constructor(scene: THREE.Scene) {
    this.scene = scene;
    this.ringGeo.rotateX(-Math.PI / 2);
    const atlas = particleAtlas();
    this.smokeP = new Particles(scene, atlas, false, 2400);
    this.glow = new Particles(scene, atlas, true, 1600);
    const decalTex = decalAtlas();
    this.decals = new Decals(scene, decalTex, 1100, this.craterU);
    this.craterDecals = new Decals(scene, decalTex, 160, this.craterU, 40);
    this.grooves = new Decals(scene, decalTex, 160, this.craterU, 40);
    this.casings = new Casings(scene);
    this.muzzleFlash = new MuzzleFlash(scene);
    this.light.position.set(0, -100, 0);
    scene.add(this.light);
  }

  /** 炮口焰：向前的火舌 + 侧向烟环 + 闪光 */
  muzzle(x: number, y: number, z: number, dx: number, dz: number, scale = 1): void {
    for (let i = 0; i < 4; i++) {
      const sp = rand(6, 18) * scale;
      this.glow.emit({ x, y, z, vx: dx * sp, vz: dz * sp, vy: rand(-0.5, 1), life: rand(0.06, 0.12), size: rand(1.4, 2.4) * scale, size1: 0.6 * scale, color: 0xfff1c0, color1: 0xff7a20, frame: 0, drag: 6 });
    }
    for (let i = 0; i < 5 * scale; i++) {
      const a = Math.random() * Math.PI * 2;
      this.smokeP.emit({ x: x + dx * 0.6, y, z: z + dz * 0.6, vx: Math.cos(a) * 3 + dx * 3, vy: rand(0.5, 2), vz: Math.sin(a) * 3 + dz * 3, life: rand(0.6, 1.2), size: 1.2 * scale, size1: 3.2 * scale, color: 0x9a9286, alpha: 0.45, frame: 1, drag: 2.5, gravity: 1 });
    }
    this.flash(x, y + 0.5, z, 220 * scale);
  }

  /** 炮弹尾迹 */
  trail(x: number, y: number, z: number, color = 0xffc070, size = 0.7, color1 = 0xff5a10): void {
    this.glow.emit({ x, y, z, life: 0.14, size, size1: 0.15, color, color1, frame: 0, alpha: 0.8 });
  }

  /** 烟迹（火箭、导弹）；flame = 带一点尾焰（榴弹拖烟不带，T247） */
  smokeTrail(x: number, y: number, z: number, flame = true): void {
    this.smokeP.emit({ x, y, z, vx: rand(-0.4, 0.4), vy: rand(0.2, 0.8), vz: rand(-0.4, 0.4), life: rand(0.6, 1.1), size: 0.6, size1: 1.8, color: 0xb8b0a4, color1: 0x7a746c, alpha: 0.5, frame: 1, drag: 1.5 });
    if (flame) this.glow.emit({ x, y, z, life: 0.08, size: 0.9, size1: 0.3, color: 0xffd080, color1: 0xff6020, frame: 0 });
  }

  /** 高速弹身后一缕淡热气（T247，高档穿甲弹）：细、短命、几乎透明 */
  smokeWisp(x: number, y: number, z: number, scale = 1): void {
    this.smokeP.emit({ x, y, z, vx: rand(-0.2, 0.2), vy: rand(0.1, 0.4), vz: rand(-0.2, 0.2), life: rand(0.3, 0.5), size: 0.3 * scale, size1: 1.1 * scale, color: 0xd8d2c8, alpha: 0.22, frame: 1, drag: 2 });
  }

  /** 小口径命中：火花 + 一点灰 */
  impact(x: number, y: number, z: number, scale = 1, color = 0xffd27a): void {
    this.sparks(x, y, z, Math.round(4 * scale), color, 9 * scale);
    this.smokeP.emit({ x, y, z, vy: 1, life: 0.5, size: 0.8 * scale, size1: 2 * scale, color: 0x8a8274, alpha: 0.4, frame: 1, drag: 2 });
  }

  sparks(x: number, y: number, z: number, count: number, color = 0xffc060, speed = 10, surface = 0): void {
    for (let i = 0; i < count; i++) {
      const a = Math.random() * Math.PI * 2;
      const sp = rand(0.4, 1) * speed;
      this.emitSurface({ x, y, z, vx: Math.cos(a) * sp, vy: rand(2, 8), vz: Math.sin(a) * sp, life: rand(0.2, 0.45), size: rand(0.25, 0.45), size1: 0.08, color, color1: 0xff4a10, frame: 0, gravity: -22, drag: 1 }, surface, true);
    }
  }

  /** 原来的一颗地面粒子在水里换成一颗水滴，数量不变；强度决定抛高和散开范围。 */
  emitSurface(o: EmitOpts, strength: number, glow = false): void {
    const water = strength > 0 ? this.waterAt(o.x, o.z) : -Infinity;
    if (water === -Infinity) {
      (glow ? this.glow : this.smokeP).emit(o);
      return;
    }
    const k = Math.min(4, strength / 3);
    const speed = Math.hypot(o.vx ?? 0, o.vz ?? 0) || 1;
    const spread = (1 + k) / speed;
    o.y = water + 0.25;
    o.vx = (o.vx ?? 0) * spread;
    o.vz = (o.vz ?? 0) * spread;
    o.vy = (5 + Math.abs(o.vy ?? 0) % 5) * (0.8 + k * 0.6);
    o.life = 0.7 + k * 0.25;
    o.size = 0.25 + k * 0.12;
    o.size1 = 0.5 + k * 0.24;
    o.color = 0xdce8e8;
    o.color1 = 0xc8d2d2;
    o.alpha = 0.78;
    o.frame = 1;
    o.gravity = -12;
    o.drag = 0;
    o.hold = false;
    o.tall = false;
    this.smokeP.emit(o);
  }

  /** 爆炸：火球 + 翻滚黑烟 + 火花 + 闪光 + 地面焦痕 */
  /** smoke = 烟团数的倍数（T143：副武器同 0.2 秒超出完整大命中个数的那些只放三分之一的烟，满级同屏不糊） */
  explosion(x: number, z: number, size: number, y = 1.4, scorch = true, smoke = 1, surface = true): void {
    this.onNetworkExplosion?.(x, z, size, y, scorch, smoke, surface);
    y += this.groundAt(x, z);
    const n = Math.round(6 + size * 3);
    const strength = surface ? size * 2 : 0;
    const wet = surface && this.waterAt(x, z) !== -Infinity;
    const edge = surface && !wet ? this.waterNear(x, z, strength) : null;
    const waterSmoke = edge ? Math.max(1, Math.round(n * 0.25 * (1 - edge.distance / strength))) : 0;
    for (let i = 0; i < n; i++) {
      const a = Math.random() * Math.PI * 2;
      const r = Math.random() * size * 0.6;
      this.emitSurface({
        x: x + Math.cos(a) * r, y: y + Math.random() * size * 0.5, z: z + Math.sin(a) * r,
        vx: Math.cos(a) * size * rand(1, 3), vy: rand(1, 4) * size * 0.6, vz: Math.sin(a) * size * rand(1, 3),
        life: rand(0.25, 0.5), size: size * rand(0.9, 1.6), size1: size * rand(1.8, 2.6),
        color: 0xffe0a0, color1: 0xc8401a, frame: 0, drag: 4, alpha: 0.95,
      }, strength, true);
    }
    for (let i = 0, ns = Math.round(n * smoke); i < ns; i++) {
      const a = Math.random() * Math.PI * 2;
      const o: EmitOpts = {
        x: x + Math.cos(a) * size * 0.4, y: y + Math.random() * size * 0.4, z: z + Math.sin(a) * size * 0.4,
        vx: Math.cos(a) * size * 1.2, vy: rand(1.5, 4), vz: Math.sin(a) * size * 1.2,
        life: rand(1.2, 2.4), size: size * 1.2, size1: size * rand(2.6, 3.6),
        color: 0x4a4440, color1: 0x2a2725, alpha: 0.75, frame: 1, drag: 1.6, gravity: 1.2, spin: rand(-0.6, 0.6),
      };
      // 爆心在岸上也要溅水；从本来那批烟里分出几颗，沿最近水点发射。
      if (edge && i < waterSmoke) { o.x = edge.x; o.z = edge.z; }
      this.emitSurface(o, strength);
    }
    this.sparks(x, y, z, Math.round(4 + size * 2), 0xffc060, 8 + size * 3, strength);
    // 中心白炽闪光 + 贴地冲击波 + 掀土
    this.emitSurface({ x, y: y + 0.4, z, life: 0.12, size: size * 3.2, size1: size * 4.2, color: 0xfff6e0, frame: 0 }, strength, true);
    if (!wet) this.flash(x, y + 1, z, 420 * size);
    if (scorch) {
      this.decals.add(DecalKind.Scorch, x, z, size * 3.2, size * 3.2, Math.random() * 6.28, 0.85, 26);
      this.shockwave(x, z, size * 4.2);
      this.dirt(x, z, size);
    }
  }

  /**
   * 贴地冲击波：边缘参差、断断续续的气浪环（先亮后变成尘色），
   * 再加一圈贴地向外扑的扇形尘土，不再是规整的圆环。
   */
  shockwave(x: number, z: number, radius: number, color = 0xffe0b0, dur = 0.4, y = 0.15, dust = true, waterOnly = false): void {
    const g = this.groundAt(x, z);
    let r = this.rings.find((it) => !it.alive);
    if (!r) {
      // 贴地的环每个顶点贴着弹坑的地面（核弹的底涌环一半在坑里、一半在坑外）
      const mat = new THREE.ShaderMaterial({
        vertexShader: DRAPE_VERT,
        fragmentShader: SHOCK_FRAG,
        uniforms: { uK: { value: 0 }, uSeed: { value: 0 }, uWarm: { value: new THREE.Color() }, uDrape: { value: 1 }, uWaterOnly: { value: 0 }, ...this.craterU },
        transparent: true,
        depthWrite: false,
        side: THREE.DoubleSide,
      });
      const mesh = new THREE.Mesh(this.ringGeo, mat);
      mesh.renderOrder = 3;
      mesh.frustumCulled = false;
      this.scene.add(mesh);
      r = { mesh, t: 0, dur, r: radius, alive: false };
      this.rings.push(r);
    }
    r.alive = true;
    r.t = 0;
    r.dur = dur;
    r.r = radius;
    r.mesh.visible = true;
    r.mesh.position.set(x, y, z);
    r.mesh.rotation.y = Math.random() * Math.PI * 2;
    r.mesh.scale.setScalar(radius);
    const u = (r.mesh.material as THREE.ShaderMaterial).uniforms;
    u.uSeed.value = Math.random() * 100;
    u.uK.value = 0;
    u.uWaterOnly.value = waterOnly ? 1 : 0;
    // 抬到半空的（凝结环）不贴地
    u.uDrape.value = y > 1 ? 0 : 1;
    (u.uWarm.value as THREE.Color).setHex(color);
    if (!dust) return;
    // 贴地向外扑的尘土
    const n = Math.round(10 + radius * 1.5);
    for (let i = 0; i < n; i++) {
      const a = (i / n) * Math.PI * 2 + rand(-0.2, 0.2);
      const sp = radius * rand(1.6, 2.6);
      const o = { x: x + Math.cos(a) * radius * 0.2, y: g + 0.5, z: z + Math.sin(a) * radius * 0.2, vx: Math.cos(a) * sp, vy: rand(0.3, 1.2), vz: Math.sin(a) * sp, life: rand(0.5, 0.8), size: rand(0.8, 1.4), size1: radius * 0.45, color: 0x9a8a6c, alpha: 0.55, frame: 1, drag: 3.2 };
      if (waterOnly && this.waterAt(o.x, o.z) === -Infinity) { o.x = x; o.z = z; }
      this.emitSurface(o, y > 1 ? 0 : radius);
    }
  }

  /** 爆炸掀起的土块和尘柱 */
  dirt(x: number, z: number, size: number, color = 0x6a5844): void {
    const g = this.groundAt(x, z);
    const n = Math.round(4 + size * 3);
    for (let i = 0; i < n; i++) {
      const a = Math.random() * Math.PI * 2;
      const sp = rand(3, 9) * (0.6 + size * 0.3);
      this.emitSurface({ x: x + Math.cos(a) * size * 0.3, y: g + 0.4, z: z + Math.sin(a) * size * 0.3, vx: Math.cos(a) * sp, vy: rand(6, 13) * (0.6 + size * 0.25), vz: Math.sin(a) * sp, life: rand(0.6, 1.0), size: rand(0.35, 0.7), size1: 0.3, color, alpha: 0.95, frame: 1, gravity: -24, drag: 0.6 }, size * 2);
    }
    for (let i = 0; i < 3; i++) this.dust(x + rand(-1, 1) * size, z + rand(-1, 1) * size, size * 1.1, 0x8a7a60, 0.5);
  }

  /**
   * 蘑菇云（核弹 1.8 宽 × 2.7 高，炼狱 0.5，天火坍缩 0.5）：只用两套实例化粒子 + 冲击波环 + 点光源，不新增绘制次数。
   * 0～0.25 秒闪光；0～1.2 秒火球（白 → 橙 → 暗褐，边升边胀）；0.1 秒底涌（亮环 + 慢速尘环 + 贴地滚出去的尘土）；火柱（前 1/3 段，烟柱里往上窜的火）；
   * 0.2 秒起烟柱（云顶 rise 秒内从 6 × h 升到 24 × h 米）；0.3 秒起云帽（沿 5 → 12 × s 米的圆环往外翻、往上卷，前一半帽底透橙光）；
   * 0.6 秒凝结环（抬到云柱半腰，ring = false 时不放）；之后粒子自己变大变淡、被风吹斜。颜色用暖灰褐（不用血红）。
   * T057：宽 / 高分开（o.tall），大号云少而大（o.n，烟团大小跟着 s 涨、个数按 n 减，免得叠太多层），烟团寿命 × o.linger（核弹的云留得久）
   */
  mushroom(x: number, z: number, s = 1, ring = true, o: CloudOpts = {}): void {
    if (this.clouds.length > 2) this.clouds.shift();
    const h = o.tall ?? s;
    // 小号蘑菇云烟团本身就小，发得稀一些（最少四成）
    const n = o.n ?? Math.min(1, Math.max(0.4, s));
    this.clouds.push({ x, z, s, h, rise: o.rise ?? 3, life: o.linger ?? 1, n, w: o.stem ?? 1, t: 0, ring, surge: false, condensed: false, stem: 0, cap: 0, fire: 0 });
    const g = this.groundAt(x, z);
    // 闪光 + 火球
    this.emitSurface({ x, y: g + 8 * Math.min(s, h), z, life: s > 1 ? 0.16 : 0.25, size: 55 * s, size1: 70 * s, color: 0xfff8ec, alpha: 1, frame: 0 }, 16 * s, true);
    if (this.waterAt(x, z) === -Infinity) this.flash(x, g + 10 * h, z, 9000 * s);
    for (let i = 0; i < 30; i++) {
      const a = Math.random() * Math.PI * 2;
      const r = Math.random() * 6 * s;
      // 白热的只占一小半（大号云更少，不然一整团发白、看不出火球）
      const hot = i < (s > 1 ? 8 : 15);
      this.emitSurface({
        x: x + Math.cos(a) * r, y: g + rand(2, 9) * s, z: z + Math.sin(a) * r,
        vx: Math.cos(a) * rand(2, 6) * s, vy: rand(4, 9) * h, vz: Math.sin(a) * rand(2, 6) * s,
        life: hot ? rand(0.7, 0.9) : rand(1.05, 1.3) * Math.sqrt(h), size: rand(8, 16) * s, size1: rand(14, 22) * s,
        color: hot ? 0xfff2d8 : 0xffa040, color1: hot ? 0xff9a36 : 0x5a2a12, alpha: s > 1 ? 0.8 : 0.95, frame: 0, drag: 1.5,
      }, 16 * s, true);
    }
  }

  private stepCloud(c: Cloud, delta: number): boolean {
    const { x, z, s, h, n } = c;
    c.t += delta;
    const t = c.t;
    const g = this.groundAt(x, z);
    const L = c.life;
    // 底涌：46 米亮环 + 30 米慢速尘环 + 一圈贴地往外滚的尘土（× s）
    if (!c.surge && t >= 0.1) {
      c.surge = true;
      this.shockwave(x, z, 46 * s, 0xfff0d8, 1.1);
      this.shockwave(x, z, 30 * s, 0xb8a080, 1.6);
      for (let i = 0; i < 60; i++) {
        if (n < 1 && Math.random() > n) continue;
        const a = (i / 60) * Math.PI * 2 + rand(-0.05, 0.05);
        const sp = rand(16, 30) * s;
        // 烟团大小最多按 1.3 倍算（大号云的底涌照样滚得远，但不一层层糊满整个画面）
        const ss = Math.min(s, 1.3);
        this.emitSurface({ x: x + Math.cos(a) * 4 * s, y: g + rand(0.6, 2) * ss, z: z + Math.sin(a) * 4 * s, vx: Math.cos(a) * sp, vy: rand(0.5, 2), vz: Math.sin(a) * sp, life: rand(2.6, 3.6) * Math.sqrt(L), size: rand(3, 5) * ss, size1: rand(10, 14) * ss, color: 0xa08e72, color1: 0x7a6e60, alpha: 0.6, frame: 1, drag: 1.3, spin: rand(-0.4, 0.4) }, 16 * s);
      }
    }
    // 云顶：rise 秒内从 6 × h 升到 24 × h 米（先快后慢）；之后再慢慢往上飘一点
    const k = Math.min(1, Math.max(0, (t - 0.2) / c.rise));
    const top = g + (6 + 18 * (1 - (1 - k) ** 2)) * h + Math.max(0, t - 0.2 - c.rise) * 0.8 * h;
    // 凝结环：白色，抬到云柱半腰
    if (c.ring && !c.condensed && t >= 0.6) {
      c.condensed = true;
      this.shockwave(x, z, 30 * s, 0xffffff, 1.0, top * 0.5, false);
    }
    // 火柱（T057）：起爆后前 1/3 段，烟柱里一路往上窜的火（白热 → 橙 → 暗褐），看得出火是从地上冲上去的
    const fireEnd = 0.2 + c.rise * 0.35;
    if (t >= 0.08 && t < fireEnd) {
      c.fire += delta;
      while (c.fire >= 0.04) {
        c.fire -= 0.04;
        for (let i = 0; i < 2; i++) {
          if (n < 1 && Math.random() > n) continue;
          const a = Math.random() * Math.PI * 2;
          const y = g + rand(1, Math.max(2, (top - g) * 0.75));
          const r = rand(0.3, 1.6) * s;
          const hot = Math.random() < 0.25;
          this.emitSurface({
            x: x + Math.cos(a) * r, y, z: z + Math.sin(a) * r, vx: this.wind * 0.2, vy: rand(6, 10) * h, vz: 0,
            life: rand(0.45, 0.7), size: rand(3.5, 6) * s * c.w, size1: rand(5, 8) * s * c.w,
            color: hot ? 0xffe2a8 : 0xff8a30, color1: 0x5a2a12, alpha: 0.55, frame: 0, drag: 1,
          }, 16 * s, true);
        }
      }
    }
    // 烟柱：每 0.05 秒 3 × n 团，在地面和当前云顶之间往上走（暗褐，比云帽深，看得出一根柱子）
    if (t >= 0.2 && t < c.rise + 0.5) {
      c.stem += delta;
      while (c.stem >= 0.05) {
        c.stem -= 0.05;
        for (let i = 0; i < 3; i++) {
          if (n < 1 && Math.random() > n) continue;
          const a = Math.random() * Math.PI * 2;
          const y = g + rand(0.5, (top - g) * 0.9);
          const ws = s * c.w;
          const r = rand(0.4, 2.2) * ws * (1 + Math.max(0, 1 - (y - g) / (4 * h)) * 1.2);
          this.emitSurface({
            x: x + Math.cos(a) * r, y, z: z + Math.sin(a) * r,
            vx: this.wind * 0.25, vy: rand(2.5, 4.5) * h, vz: 0, life: rand(3, 4.5) * L, size: rand(3.5, 5) * ws, size1: rand(7, 9) * ws,
            color: 0x6e5a48, color1: 0x463c34, alpha: 0.82, frame: 1, drag: 0.6, spin: rand(-0.6, 0.6), hold: L > 1,
          }, 16 * s);
        }
      }
    }
    // 云帽：每 0.04 秒沿圆环 4 × n 团大烟往外翻、往上卷（上半亮、帽底暗）+ n 团盖顶；前一半帽底透橙光
    if (t >= 0.3 && t < c.rise + 1) {
      c.cap += delta;
      const R = (5 + 7 * Math.min(1, (t - 0.3) / c.rise)) * s;
      while (c.cap >= 0.04) {
        c.cap -= 0.04;
        for (let i = 0; i < 4; i++) {
          if (n < 1 && Math.random() > n) continue;
          const a = Math.random() * Math.PI * 2;
          const r = R * rand(0.6, 1.05);
          const under = i % 2 === 1;
          this.emitSurface({
            x: x + Math.cos(a) * r, y: top + (under ? rand(-3.2, -1) : rand(-0.5, 2.5)) * s, z: z + Math.sin(a) * r,
            vx: Math.cos(a) * rand(1.4, 3) * s + this.wind * 0.6, vy: (under ? rand(1.8, 3) : rand(0.6, 1.6)) * s, vz: Math.sin(a) * rand(1.4, 3) * s,
            life: rand(4, 5.5) * L, size: rand(6, 8) * s, size1: rand(10, 13) * s,
            color: under ? 0x4e3e32 : 0xd8c4a4, color1: under ? 0x3a2f28 : 0xa49482, alpha: 0.88, frame: 1, drag: 0.35, spin: rand(-0.4, 0.4), hold: L > 1,
          }, 16 * s);
        }
        if (Math.random() < n) {
          const a = Math.random() * Math.PI * 2;
          const r = R * rand(0, 0.45);
          this.emitSurface({
            x: x + Math.cos(a) * r, y: top + rand(1, 3.5) * s, z: z + Math.sin(a) * r,
            vx: this.wind * 0.6, vy: rand(0.8, 1.6) * s, vz: 0, life: rand(4, 5.5) * L, size: rand(7, 9) * s, size1: rand(11, 14) * s,
            color: 0xead8ba, color1: 0xb0a08c, alpha: 0.88, frame: 1, drag: 0.35, spin: rand(-0.4, 0.4), hold: L > 1,
          }, 16 * s);
        }
        if (t < 0.3 + c.rise * 0.65) {
          for (let i = 0; i < 3; i++) {
            if (n < 1 && Math.random() > Math.sqrt(n)) continue;
            const b = Math.random() * Math.PI * 2;
            const rr = R * rand(0.15, 0.6);
            this.emitSurface({ x: x + Math.cos(b) * rr, y: top - rand(1.5, 3.5) * s, z: z + Math.sin(b) * rr, vy: 1.5 * s, life: rand(0.4, 0.6), size: rand(4, 6.5) * s, size1: rand(6, 8) * s, color: 0xff8a3a, color1: 0x7a3414, alpha: 0.7, frame: 0 }, 16 * s, true);
          }
        }
      }
    }
    return t < c.rise + 1.2;
  }

  /**
   * 火柱（T057）：(x, z) 处 dur 秒里一股往上窜到 h 米的火（白热芯 → 橙 → 暗褐的烟），s = 多粗；火柱顶上冒黑烟。只用两套粒子，不加绘制
   */
  pillar(x: number, z: number, h: number, s: number, dur: number): void {
    if (this.pillars.length > 3) this.pillars.shift();
    this.pillars.push({ x, z, g: this.groundAt(x, z), t: 0, dur, h, s, acc: 0 });
  }

  private stepPillar(p: { x: number; z: number; g: number; t: number; dur: number; h: number; s: number; acc: number }, delta: number): boolean {
    p.t += delta;
    const k = p.t / p.dur;
    p.acc += delta;
    while (p.acc >= 0.03) {
      p.acc -= 0.03;
      const live = 1 - k;
      // 火：从地面往上冲，速度够它在寿命里冲到 h 米
      for (let i = 0; i < 2; i++) {
        const a = Math.random() * Math.PI * 2;
        const r = rand(0, 0.9) * p.s;
        const life = rand(0.55, 0.8);
        const hot = Math.random() < 0.45 * live + 0.15;
        this.emitSurface({
          x: p.x + Math.cos(a) * r, y: p.g + rand(0.5, 2), z: p.z + Math.sin(a) * r, vx: Math.cos(a) * 0.8 + this.wind * 0.3, vy: (p.h / life) * rand(0.75, 1.1) * (0.55 + 0.45 * live), vz: Math.sin(a) * 0.8,
          life, size: rand(2.2, 3.4) * p.s * (0.6 + 0.4 * live), size1: rand(3, 4.5) * p.s,
          color: hot ? 0xfff0c4 : 0xffa040, color1: 0x6a2c10, alpha: 0.85, frame: 0, drag: 0.6,
        }, p.h * 0.5, true);
      }
      // 顶上冒出来的黑烟
      if (Math.random() < 0.5) {
        this.emitSurface({
          x: p.x + rand(-1, 1) * p.s, y: p.g + p.h * rand(0.65, 0.95) * (0.6 + 0.4 * live), z: p.z + rand(-1, 1) * p.s, vx: this.wind * 0.6, vy: rand(2, 4), vz: 0,
          life: rand(2.5, 3.5), size: rand(2.5, 3.5) * p.s, size1: rand(5, 7) * p.s, color: 0x3a302a, color1: 0x5a524a, alpha: 0.7, frame: 1, drag: 0.5, spin: rand(-0.5, 0.5),
        }, p.h * 0.5);
      }
    }
    return p.t < p.dur;
  }

  /**
   * 余韵（T057）：(x, z) 周围 r 米里，dur 秒内从 top 米高往下飘的灰（暗灰小片，慢慢转着落）和发红的火星（ember 成），每秒 rate 片；
   * 粒子很小，几乎不占填充
   */
  fallout(x: number, z: number, r: number, top: number, dur: number, rate: number, ember = 0.3, up = false): void {
    if (this.fallouts.length > 3) this.fallouts.shift();
    this.fallouts.push({ x, z, r, top, t: 0, dur, rate, ember, up, acc: 0 });
  }

  private stepFallout(f: Fallout, delta: number): boolean {
    f.t += delta;
    // 先多后少：前三成满量，之后慢慢变少
    const k = Math.min(1, Math.max(0, 1 - (f.t / f.dur - 0.3) / 0.7));
    f.acc += delta * f.rate * k;
    while (f.acc >= 1) {
      f.acc -= 1;
      const a = Math.random() * Math.PI * 2;
      const rr = Math.sqrt(Math.random()) * f.r;
      const x = f.x + Math.cos(a) * rr;
      const z = f.z + Math.sin(a) * rr;
      const g = this.groundAt(x, z);
      const y = f.up ? g + rand(0.2, 1.2) : g + rand(0.4, 1) * f.top;
      const vy = f.up ? rand(0.8, 2.4) : rand(-1.6, -0.6);
      if (Math.random() < f.ember) {
        this.emitSurface({ x, y, z, vx: this.wind * rand(0.6, 1.4), vy, vz: rand(-0.6, 0.6), life: rand(2, 3.5), size: rand(0.18, 0.32), size1: 0.08, color: 0xffc070, color1: 0xa84a12, alpha: 0.9, frame: 0, drag: 0.4 }, f.r, true);
      } else {
        this.emitSurface({ x, y, z, vx: this.wind * rand(0.6, 1.4), vy: vy * 0.85, vz: rand(-0.6, 0.6), life: rand(3, 5), size: rand(0.25, 0.5), size1: rand(0.3, 0.6), color: 0x5a5450, color1: 0x8a8278, alpha: 0.75, frame: 1, drag: 0.5, gravity: f.up ? 0 : -0.1, spin: rand(-2, 2) }, f.r);
      }
    }
    return f.t < f.dur;
  }

  /**
   * 火球体（T027-c）：(x, y, z) 处一团翻滚的火球，dur 秒里半径从 r0 胀到 r1、升起 rise 米，白热 → 橙 → 暗褐淡出；alpha 压低（贴着坦克落下时）。
   * 0 粒子，在场时每个 +1 次绘制（最多同时 2 个，再多顶掉最老的）
   */
  fireball(x: number, y: number, z: number, r0: number, r1: number, rise: number, dur: number, alpha = 1): void {
    if (this.waterAt(x, z) !== -Infinity) return;
    let b = this.balls.find((o) => !o.alive);
    if (!b && this.balls.length >= 2) b = this.balls.reduce((p, q) => (q.t / q.dur > p.t / p.dur ? q : p));
    if (!b) {
      const mat = new THREE.ShaderMaterial({
        vertexShader: BALL_VERT,
        fragmentShader: BALL_FRAG,
        uniforms: THREE.UniformsUtils.merge([THREE.UniformsLib.fog, { uT: { value: 0 }, uSeed: { value: 0 }, uAlpha: { value: 1 } }]),
        transparent: true,
        depthWrite: false,
        fog: true,
      });
      const mesh = new THREE.Mesh(this.ballGeo, mat);
      mesh.renderOrder = 3;
      mesh.frustumCulled = false;
      mesh.visible = false;
      this.scene.add(mesh);
      b = { mesh, t: 0, dur, r0, r1, y0: y, rise, alive: false };
      this.balls.push(b);
    }
    Object.assign(b, { t: 0, dur, r0, r1, y0: y, rise, alive: true });
    b.mesh.position.set(x, y, z);
    b.mesh.scale.setScalar(r0);
    b.mesh.rotation.set(0, Math.random() * Math.PI * 2, 0);
    b.mesh.visible = true;
    const u = b.mesh.material.uniforms;
    u.uT.value = 0;
    u.uSeed.value = Math.random() * 50;
    u.uAlpha.value = alpha;
  }

  private stepBalls(delta: number): void {
    for (const b of this.balls) {
      if (!b.alive) continue;
      b.t += delta;
      const k = b.t / b.dur;
      if (k >= 1) {
        b.alive = false;
        b.mesh.visible = false;
        continue;
      }
      const e = 1 - (1 - k) * (1 - k);
      b.mesh.scale.setScalar(b.r0 + (b.r1 - b.r0) * e);
      b.mesh.position.y = b.y0 + b.rise * e;
      b.mesh.rotation.y += delta * 0.4;
      b.mesh.material.uniforms.uT.value = k;
    }
  }

  /** 主炮炮弹直接命中：小火球 + 火花 + 冲击波 */
  shellHit(x: number, z: number, scale = 1): void {
    this.explosion(x, z, 1.1 * scale, 1.6, false);
    this.sparks(x, 1.6, z, Math.round(10 * scale), 0xffd090, 12 * scale, 2.2 * scale);
    this.shockwave(x, z, 4.5 * scale, 0xffd8a0, 0.28);
    this.dirt(x, z, 0.8 * scale);
  }

  smoke(x: number, y: number, z: number, size: number, life = 2.6, color = 0x3d3834, alpha = 0.6, surface = 0): void {
    this.emitSurface({ x: x + rand(-0.5, 0.5), y, z: z + rand(-0.5, 0.5), vx: rand(-0.4, 0.4), vy: rand(1.2, 2.4), vz: rand(-0.4, 0.4), life, size, size1: size * 3, color, color1: 0x24211f, alpha, frame: 1, drag: 0.6, spin: rand(-0.5, 0.5) }, surface);
  }

  /** 履带扬尘 / 碾压扬尘 */
  dust(x: number, z: number, size: number, color = 0xa08f6c, alpha = 0.35): void {
    this.emitSurface({ x: x + rand(-0.4, 0.4), y: this.groundAt(x, z) + 0.5, z: z + rand(-0.4, 0.4), vx: rand(-1, 1), vy: rand(0.4, 1.4), vz: rand(-0.5, 1.5), life: rand(0.9, 1.6), size, size1: size * 2.6, color, alpha, frame: 1, drag: 1.4 }, size * 2);
  }

  /**
   * 持续燃烧：火苗 + 一根往上翻滚、被风吹斜的黑烟柱，持续 dur 秒（最后两成时间只剩烟）。
   * fire=false 时只冒烟（弹坑余烟）。
   */
  burn(x: number, z: number, size: number, dur: number, fire = true): void {
    if (this.waterAt(x, z) !== -Infinity) return;
    if (this.burners.length > 40) this.burners.shift();
    this.burners.push({ x, z, g: this.groundAt(x, z), t: 0, dur, size, fire, acc: 0 });
  }

  /** 浓烟柱里的一团烟：越往上越大越淡 */
  column(x: number, y: number, z: number, size: number, dark = 1): void {
    // 刚冒出来是浓黑的，升高后散开变成灰色
    const c = dark > 0.5 ? 0x26221f : 0x5a554e;
    this.smokeP.emit({
      x: x + rand(-0.4, 0.4) * size, y, z: z + rand(-0.4, 0.4) * size,
      vx: this.wind * rand(0.6, 1.2), vy: rand(2.4, 3.8), vz: rand(-0.3, 0.3) - 0.4,
      // 寿命 3.5～5 秒（T017-15d，原来 4.2～6）
      life: rand(3.5, 5), size: size * rand(1, 1.4), size1: size * rand(5, 6.5),
      color: c, color1: 0x77716a, alpha: 0.6, frame: 1, drag: 0.3, spin: rand(-0.4, 0.4),
    });
  }

  /** 一团火苗（燃烧中的残骸 / 着火的敌人 / 地面火） */
  fire(x: number, y: number, z: number, size: number): void {
    if (y <= this.waterAt(x, z) + 0.8) return;
    this.glow.emit({ x: x + rand(-0.4, 0.4) * size, y, z: z + rand(-0.4, 0.4) * size, vx: rand(-0.5, 0.5), vy: rand(2, 4), vz: rand(-0.5, 0.5), life: rand(0.3, 0.55), size: size * rand(0.8, 1.2), size1: size * 0.3, color: 0xffd080, color1: 0xd03a10, frame: 0, alpha: 0.9 });
  }

  /**
   * 着火的步兵（T249，敌人燃烧每跳调一次）：(x, y, z) 是脚底。照炼狱火舌的做法，从腿到头顶窜几条火舌，
   * 身上一团橙色火光，头顶冒黑烟；同时烧的人多了每人少发、火光变淡
   */
  torch(x: number, y: number, z: number): void {
    if (y <= this.waterAt(x, z) + 0.3) return;
    this.torchLoad += 1;
    const k = Math.min(1, TORCH.crowd / this.torchLoad);
    const h = TORCH.h;
    this.glow.emit({
      x, y: y + h * 0.5, z, vx: this.wind * 0.3, vy: rand(0.6, 1.4), life: rand(0.4, 0.55), size: h * rand(0.9, 1.1), size1: h * 0.6,
      color: 0xff9a3a, color1: 0x801804, alpha: 0.35 + 0.25 * k, frame: 0,
    });
    const n = Math.max(1, Math.round(TORCH.tongues * k));
    for (let i = 0; i < n; i++) {
      const hot = Math.random() < 0.35;
      this.glow.emit({
        x: x + rand(-0.35, 0.35), y: y + rand(0.15, 0.85) * h, z: z + rand(-0.35, 0.35),
        vx: rand(-0.4, 0.4) + this.wind * 0.4, vy: rand(2.6, 4.6), vz: rand(-0.4, 0.4),
        life: rand(0.45, 0.75), size: rand(0.6, 0.95), size1: 0.15,
        color: hot ? 0xfff2d0 : 0xffaa48, color1: hot ? 0xff6a1a : 0xa82408, alpha: 0.95, frame: 0,
      });
    }
    if (Math.random() < TORCH.smoke * k) {
      this.smokeP.emit({
        x: x + rand(-0.2, 0.2), y: y + h + 0.2, z: z + rand(-0.2, 0.2), vx: this.wind * rand(0.6, 1.2), vy: rand(1.6, 2.6), vz: rand(-0.3, 0.3),
        life: rand(1.4, 2.2), size: 0.5, size1: rand(2, 2.6), color: 0x26221f, color1: 0x5a554e, alpha: 0.55, frame: 1, drag: 0.5, spin: rand(-0.5, 0.5),
      });
    }
  }

  /** 着火的步兵被毁：身上的火在原地再烧一会儿、冒烟（人多时不加，免得满地火堆） */
  torchOut(x: number, z: number): void {
    if (this.torchLoad < TORCH.crowd * 2) this.burn(x, z, 0.5, TORCH.after);
  }

  /**
   * 炼狱火海的一团火舌：比普通火苗更大、窜得更高；hot（0..1，越靠近火场中心越大）决定颜色——中心白热、边缘橙红；
   * live（0..1）收尾时降下去，火舌变矮变暗
   */
  blaze(x: number, z: number, size: number, hot: number, live = 1): void {
    if (this.waterAt(x, z) !== -Infinity) return;
    const s = size * (0.45 + 0.55 * live);
    const core = hot > 0.55;
    const g = this.groundAt(x, z);
    // 贴地的一团火光（烧着的地面）+ 往上窜的火舌
    this.glow.emit({
      x, y: g + 0.5, z, vx: this.wind * 0.2, vy: rand(0.4, 1.2), life: rand(0.5, 0.8), size: s * rand(1.6, 2.2), size1: s * 1.2,
      color: core ? 0xffc060 : 0xff7a26, color1: 0x801804, alpha: 0.55, frame: 0,
    });
    this.glow.emit({
      x: x + rand(-0.5, 0.5), y: g + 0.6 + rand(0, 0.6), z: z + rand(-0.5, 0.5),
      vx: rand(-0.6, 0.6) + this.wind * 0.4, vy: rand(4, 7.5) * (0.75 + hot * 0.5) * (0.5 + 0.5 * live), vz: rand(-0.6, 0.6),
      life: rand(0.5, 0.85), size: s * rand(0.9, 1.3), size1: s * 0.25,
      color: core ? 0xfff2d0 : 0xffaa48, color1: core ? 0xff6a1a : 0xa82408, alpha: 0.95, frame: 0,
    });
  }

  /** 电火花（特斯拉 / 电击兵）；big（T021-a，满级特斯拉 / 落雷）= 光团 3.5 米、火花至少 10 颗、地上一块小焦痕 */
  electric(x: number, y: number, z: number, count = 5, big = false): void {
    this.sparks(x, y, z, big ? Math.max(10, count) : count, 0x9fd8ff, big ? 9 : 7);
    this.glow.emit({ x, y, z, life: big ? 0.16 : 0.12, size: big ? 3.5 : 2.2, size1: 0.8, color: 0xcfeaff, color1: 0x4aa0ff, frame: 0 });
    if (big) this.decals.add(DecalKind.Scorch, x, z, 1.8, 1.8, Math.random() * 6.28, 0.5, 2);
  }

  /** 拾取 / 治疗的小闪光 */
  glint(x: number, y: number, z: number, color: number, size = 1.2): void {
    this.glow.emit({ x, y, z, vy: 2, life: 0.35, size, size1: size * 2.2, color, frame: 0, alpha: 0.9 });
  }

  /** 过热蒸汽 */
  steam(x: number, y: number, z: number): void {
    this.smokeP.emit({ x, y, z, vx: rand(-0.6, 0.6), vy: rand(1.5, 3), vz: rand(-0.6, 0.6), life: rand(0.5, 0.9), size: 0.5, size1: 1.6, color: 0xe8eef0, alpha: 0.4, frame: 1, drag: 1.5 });
  }

  /** 瞬时补光：炮口、爆炸照亮周围；color（T057）= 灯的颜色（默认暖橙，闪电用冷白） */
  flash(x: number, y: number, z: number, power: number, color = 0xffa860): void {
    if (power < this.lightPower * 0.6) return;
    this.light.position.set(x, y, z);
    this.light.color.setHex(color);
    this.lightPower = power;
  }

  // ---------------------------------------------------------- 景物破坏（T009）的 6 个预设

  /** 叶团：针叶 / 灌木叶被打飞，绿色的一蓬往外散、慢慢落 */
  foliage(x: number, y: number, z: number, size: number, n = 6): void {
    for (let i = 0; i < n; i++) {
      const a = Math.random() * Math.PI * 2;
      const sp = rand(1.5, 4) * size;
      this.smokeP.emit({ x: x + rand(-0.5, 0.5) * size, y: y + rand(-0.4, 0.6) * size, z: z + rand(-0.5, 0.5) * size, vx: Math.cos(a) * sp, vy: rand(0.5, 2.5), vz: Math.sin(a) * sp, life: rand(0.8, 1.5), size: rand(0.5, 0.9) * size, size1: rand(1.2, 1.8) * size, color: i % 2 ? 0x3e5228 : 0x56683a, color1: 0x6a6a48, alpha: 0.75, frame: 1, drag: 2.4, gravity: -2.5, spin: rand(-1, 1) });
    }
  }

  /** 白灰：砖墙 / 房子被打出来的一团灰白粉尘 */
  plaster(x: number, y: number, z: number, size: number, dx = 0, dz = 0): void {
    for (let i = 0; i < 4; i++) {
      this.smokeP.emit({ x: x + rand(-0.3, 0.3), y: y + rand(-0.3, 0.3), z: z + rand(-0.3, 0.3), vx: dx * rand(2, 5) + rand(-1, 1), vy: rand(0.3, 1.4), vz: dz * rand(2, 5) + rand(-1, 1), life: rand(1.2, 2.2), size: size * rand(0.6, 1), size1: size * rand(2.2, 3), color: 0xd8d0c0, color1: 0xa8a090, alpha: 0.55, frame: 1, drag: 2, spin: rand(-0.4, 0.4) });
    }
  }

  /** 塌房尘云：贴地翻滚的一大团灰尘（dur 秒内慢慢散），房屋全塌再加一根尘柱 */
  collapse(x: number, z: number, size: number, column = false): void {
    const g = this.groundAt(x, z);
    for (let i = 0; i < 14; i++) {
      const a = (i / 14) * Math.PI * 2 + rand(-0.2, 0.2);
      const sp = rand(1.5, 3.5) * size * 0.4;
      this.smokeP.emit({ x: x + Math.cos(a) * size * 0.3, y: g + rand(0.5, 2), z: z + Math.sin(a) * size * 0.3, vx: Math.cos(a) * sp, vy: rand(0.2, 1), vz: Math.sin(a) * sp, life: rand(3, 4.5), size: size * rand(0.4, 0.6), size1: size * rand(1.1, 1.5), color: 0xb0a490, color1: 0x8a8070, alpha: 0.6, frame: 1, drag: 1.1, spin: rand(-0.3, 0.3) });
    }
    if (!column) return;
    for (let i = 0; i < 8; i++) {
      this.smokeP.emit({ x: x + rand(-1, 1) * size * 0.2, y: g + rand(1, 4), z: z + rand(-1, 1) * size * 0.2, vx: this.wind * 0.3, vy: rand(2, 4), vz: 0, life: rand(4.5, 6), size: size * rand(0.5, 0.7), size1: size * rand(1.4, 1.8), color: 0xa89a84, color1: 0x7a7266, alpha: 0.55, frame: 1, drag: 0.5, spin: rand(-0.3, 0.3) });
    }
  }

  /** 一串往下掉的电火花（电线杆横担、被引雷的树） */
  sparkShower(x: number, y: number, z: number, n = 10, color = 0xbfe6ff): void {
    for (let i = 0; i < n; i++) {
      const a = Math.random() * Math.PI * 2;
      const sp = rand(1, 4);
      this.glow.emit({ x, y, z, vx: Math.cos(a) * sp, vy: rand(-1, 3), vz: Math.sin(a) * sp, life: rand(0.4, 0.8), size: rand(0.18, 0.32), size1: 0.06, color: 0xffffff, color1: color, frame: 0, gravity: -14, drag: 0.6 });
    }
    this.glow.emit({ x, y, z, life: 0.1, size: 2, size1: 0.6, color: 0xe8f6ff, color1: color, frame: 0 });
  }

  /** 窗口往外喷火（房子烧起来 / 温压弹） */
  windowFire(x: number, y: number, z: number, nx: number, nz: number, size = 1): void {
    this.glow.emit({ x: x + nx * 0.3, y: y + rand(-0.2, 0.3), z: z + nz * 0.3, vx: nx * rand(0.6, 1.8), vy: rand(1.5, 3), vz: nz * rand(0.6, 1.8), life: rand(0.35, 0.6), size: size * rand(0.8, 1.3), size1: size * 0.4, color: 0xffd080, color1: 0xc8401a, frame: 0, alpha: 0.9 });
    if (Math.random() < 0.35) this.smokeP.emit({ x: x + nx * 0.5, y: y + 0.6, z: z + nz * 0.5, vx: nx + this.wind * 0.4, vy: rand(1.5, 2.5), vz: nz, life: rand(1.5, 2.5), size: size * 0.8, size1: size * 2.6, color: 0x2a2624, color1: 0x5a554e, alpha: 0.55, frame: 1, drag: 0.6 });
  }

  /** 切口红热：白 → 橙 → 暗红（k = 剩余红热比例 1 → 0） */
  hot(x: number, y: number, z: number, k: number, size = 0.5): void {
    const c = k > 0.75 ? 0xfff2d0 : k > 0.45 ? 0xffa040 : 0xc0300a;
    this.glow.emit({ x, y, z, life: 0.12, size: size * (0.6 + k * 0.6), size1: size * 0.4, color: c, color1: 0x801404, alpha: 0.5 + k * 0.4, frame: 0 });
  }

  /**
   * 激光烧金属（T070）：白热光斑（每帧一颗）+ 往回溅的橙色火花 + 往下掉的熔滴；照久了（heat 0..1）发红、冒烟；借现有补光灯照亮车身。
   * (bx, bz) = 指回炮口的单位向量，size = 光斑大小，acc = 调用方的发射计时（每条光束每秒合计约 30 颗）
   */
  beamBurn(x: number, y: number, z: number, bx: number, bz: number, heat: number, size: number, dt: number, acc: { spark: number; drip: number; red: number; smoke: number }): void {
    const fx = x + bx * 0.15;
    const fz = z + bz * 0.15;
    this.glow.emit({ x: fx, y, z: fz, life: 0.05, size, size1: size * 0.8, color: 0xffffff, color1: 0xfff0c8, frame: 0 });
    const back = Math.atan2(bx, bz);
    for (acc.spark += dt * 12; acc.spark >= 1; acc.spark--) {
      // 往回、往两边斜着溅（正对镜头溅回来的会叠在光束上看不见）
      const a = back + (Math.random() < 0.5 ? -1 : 1) * rand(0.5, 1.5);
      const sp = rand(5, 10);
      this.glow.emit({ x: fx, y, z: fz, vx: Math.sin(a) * sp, vy: rand(3, 7), vz: Math.cos(a) * sp, life: rand(0.35, 0.6), size: rand(0.32, 0.5), size1: 0.08, color: 0xffe0a0, color1: 0xff5a10, frame: 0, gravity: -20, drag: 0.8 });
    }
    for (acc.drip += dt * (4 + heat * 2); acc.drip >= 1; acc.drip--) {
      const s = rand(-1, 1);
      this.glow.emit({ x: fx + bz * s * 0.5, y: y - 0.15, z: fz - bx * s * 0.5, vx: bx * rand(0.3, 1) + bz * s * 0.8, vy: rand(-0.2, 0.6), vz: bz * rand(0.3, 1) - bx * s * 0.8, life: rand(0.5, 0.75), size: rand(0.3, 0.42), size1: 0.14, color: 0xffb040, color1: 0xb02408, frame: 0, gravity: -7, drag: 0.3 });
    }
    if (heat > 0) {
      for (acc.red += dt * 6; acc.red >= 1; acc.red--) {
        this.glow.emit({ x: x + bx * 0.08, y, z: z + bz * 0.08, life: 0.25, size: size * (1 + heat * 0.5), size1: size * (0.9 + heat * 0.4), color: 0xff4a12, color1: 0x8a1404, alpha: 0.3 + heat * 0.45, frame: 0 });
      }
      for (acc.smoke += dt * 6 * heat; acc.smoke >= 1; acc.smoke--) {
        this.smokeP.emit({ x: fx, y: y + 0.3, z: fz, vx: bx * 0.6 + this.wind * 0.3, vy: rand(1.5, 2.5), vz: bz * 0.6, life: rand(1.2, 1.8), size: 0.8, size1: 3, color: 0x5a5450, color1: 0x9a948c, alpha: 0.5 + heat * 0.25, frame: 1, drag: 0.8, spin: rand(-0.5, 0.5) });
      }
    }
    this.flash(x + bx * 1.2, y + 0.5, z + bz * 1.2, 50 + heat * 90, heat > 0.5 ? 0xff7a3a : 0xffc890);
  }

  tread(x: number, z: number, rot: number, alpha: number): void {
    this.decals.add(DecalKind.Tread, x, z, 1.15, 0.6, rot, alpha, 16);
  }

  /** 弹坑贴花（直径 size 米）：放进单独的池子，不按时间淡出（T016-1） */
  crater(x: number, z: number, size: number): void {
    this.craterDecals.add(DecalKind.Crater, x, z, size, size, Math.random() * 6.28, 0.8, Infinity);
  }

  stain(x: number, z: number, size: number): void {
    this.decals.add(DecalKind.Stain, x, z, size, size, Math.random() * 6.28, 0.7, 30);
  }

  /** 火神弹着区的一团贴地尘（T088）：低低地鼓起来、往风向飘，连着打就是一道翻滚的尘线 */
  vulcanDust(x: number, z: number, life: number, size = 1): void {
    this.smokeP.emit({ x: x + rand(-0.5, 0.5), y: this.groundAt(x, z) + rand(0.2, 0.6), z: z + rand(-0.5, 0.5), vx: this.wind * rand(0.5, 1) + rand(-0.6, 0.6), vy: rand(0.3, 1.1), vz: rand(-0.6, 0.6), life: life * rand(0.8, 1.2), size: 0.9 * size, size1: 2.8 * size, color: 0x8c7a5c, color1: 0x7e705c, alpha: 0.5, frame: 1, drag: 1.2, spin: rand(-0.5, 0.5) });
  }

  /** 火神弹沟一段：中心 (x, z)、沿 rot 方向长 len 米（焦痕贴图拉成细长条） */
  groove(x: number, z: number, rot: number, len: number, life: number): void {
    this.grooves.add(DecalKind.Scorch, x, z, 0.55, Math.max(0.7, len), rot, 0.75, life);
  }

  /** px / camX / camZ：坦克的横向位置和镜头的地面投影（近身清烟，T017-15c） */
  update(delta: number, playerZ: number, px = 0, camX = px, camZ = playerZ + 25): void {
    const cz = (this.smokeP.clearZone ??= { x: 0, z: 0, cx: 0, cz: 0 });
    cz.x = px;
    cz.z = playerZ;
    cz.cx = camX;
    cz.cz = camZ;
    for (let i = this.burners.length - 1; i >= 0; i--) {
      const b = this.burners[i];
      b.t += delta;
      // 烧完或者已经甩到镜头后面就移除
      if (b.t >= b.dur || b.z > playerZ + 34 || this.waterAt(b.x, b.z) !== -Infinity) {
        this.burners.splice(i, 1);
        continue;
      }
      // 甩到坦克身后 10 米就不再冒烟柱（T017-15c，原来到 34 米），火苗照旧烧到看不见
      const smoky = b.z <= playerZ + SMOKE_BEHIND.burn;
      const k = b.t / b.dur;
      const far = playerZ - b.z > 150;
      if (far) continue;
      b.acc += delta;
      const step = b.fire ? 0.16 : 0.32;
      while (b.acc >= step) {
        b.acc -= step;
        const fade = 1 - Math.max(0, k - 0.6) / 0.4;
        if (smoky) this.column(b.x, b.g + 1 + b.size * 0.4, b.z, b.size * (0.6 + 0.4 * fade), b.fire ? 1 : 0);
        if (b.fire && k < 0.8) {
          for (let j = 0; j < 2; j++) this.fire(b.x + rand(-0.6, 0.6) * b.size, b.g + 0.5 + rand(0, 0.6) * b.size, b.z + rand(-0.6, 0.6) * b.size, b.size * rand(0.7, 1.1) * (1 - k * 0.6));
        }
      }
    }
    this.torchLoad *= Math.exp(-delta * 4);
    for (let i = this.clouds.length - 1; i >= 0; i--) if (!this.stepCloud(this.clouds[i], delta)) this.clouds.splice(i, 1);
    for (let i = this.pillars.length - 1; i >= 0; i--) if (!this.stepPillar(this.pillars[i], delta)) this.pillars.splice(i, 1);
    for (let i = this.fallouts.length - 1; i >= 0; i--) if (!this.stepFallout(this.fallouts[i], delta)) this.fallouts.splice(i, 1);
    this.stepBalls(delta);
    for (const r of this.rings) {
      if (!r.alive) continue;
      r.t += delta;
      const k = r.t / r.dur;
      if (k >= 1) {
        r.alive = false;
        r.mesh.visible = false;
        continue;
      }
      (r.mesh.material as THREE.ShaderMaterial).uniforms.uK.value = 1 - (1 - k) * (1 - k);
    }
    this.glow.update(delta);
    this.smokeP.update(delta);
    this.decals.update(delta, playerZ);
    this.craterDecals.update(delta, playerZ);
    this.grooves.update(delta, playerZ);
    this.casings.update(delta, this.groundAt);
    this.muzzleFlash.update();
    this.lightPower = Math.max(0, this.lightPower - delta * this.lightPower * 14 - delta * 40);
    this.light.intensity = this.lightPower;
  }

  clear(): void {
    this.burners.length = 0;
    this.torchLoad = 0;
    this.clouds.length = 0;
    this.pillars.length = 0;
    this.fallouts.length = 0;
    for (const b of this.balls) {
      b.alive = false;
      b.mesh.visible = false;
    }
    for (const r of this.rings) {
      r.alive = false;
      r.mesh.visible = false;
    }
    this.glow.clear();
    this.smokeP.clear();
    this.decals.clear();
    this.craterDecals.clear();
    this.grooves.clear();
    this.casings.clear();
    this.muzzleFlash.clear();
    this.lightPower = 0;
    this.light.intensity = 0;
  }

  /** 按画质收紧粒子 / 贴花池（T245，FX_TIERS；弹坑贴花、弹沟池不动） */
  setLimits(l: { smoke: number; glow: number; decals: number }): void {
    this.smokeP.setLimit(l.smoke);
    this.glow.setLimit(l.glow);
    this.decals.setLimit(l.decals);
  }

  dispose(): void {
    this.ballGeo.dispose();
    for (const b of this.balls) b.mesh.material.dispose();
    this.glow.dispose();
    this.smokeP.dispose();
    this.decals.dispose();
    this.craterDecals.dispose();
    this.grooves.dispose();
    this.casings.dispose();
    this.muzzleFlash.dispose();
  }
}
