/** 机身顶面在 z 处多高 */
const topAt = (z: number) => {
  const s = plateAt(BODY, z);
  return s.y + s.top;
};

/** 一排方铆钉（从 a 到 b，n 颗） */
function rivets(p: HeliPart[], a: V3, b: V3, n: number, s = 0.07): void {
  for (let i = 0; i < n; i++) {
    const t = n > 1 ? i / (n - 1) : 0.5;
    p.push({ geo: new THREE.BoxGeometry(s, s, s), color: DARK, pos: [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t] });
  }
}

/** 一枚导弹（弹体 + 平头导引头 + 尾翼），弹头朝 +Z；导引头亮片在亮件里 */
function missile(p: HeliPart[], x: number, y: number, z: number, len = 1.3, r = 0.1): void {
  p.push({ geo: cyl(r, r, len), color: 0x5a5e50, pos: [x, y, z], rot: [HALF, 0, 0] });
  p.push({ geo: cyl(r * 0.85, r, 0.14), color: DARK, pos: [x, y, z + len / 2 + 0.07], rot: [HALF, 0, 0] });
  for (let i = 0; i < 2; i++) p.push({ geo: new THREE.BoxGeometry(0.02, r * 3.2, 0.22), color: DARK, pos: [x, y, z - len / 2 + 0.14], rot: [0, 0, Math.PI / 4 + (i * Math.PI) / 2] });
}

/** 一对并排的轮子（胎 + 轮毂）+ 轮轴，中心在 (x, y, z) */
function wheels(p: HeliPart[], x: number, y: number, z: number, r: number, gap: number): void {
  p.push({ geo: cyl(0.06, 0.06, gap * 2 + 0.3), color: DARK, pos: [x, y, z], rot: [0, 0, HALF] });
  for (const d of [-gap, gap]) {
    p.push({ geo: cyl(r, r, 0.22, 12), color: TIRE, pos: [x + d, y, z], rot: [0, 0, HALF] });
    p.push({ geo: cyl(r * 0.52, r * 0.52, 0.26), color: STEEL_D, pos: [x + d, y, z], rot: [0, 0, HALF] });
  }
}

