import { SUB_DMG, WEAPONS, type LinkId, type WeaponId } from './defs';

/** 试玩的四级成长独立于核心、属性件和超级改装。 */
export const SUB_MAX = 4;
export const SUB_LINK_LEVEL = 2;
export const SUB_IDS = Object.keys(WEAPONS) as WeaponId[];
/** 从车头往车尾读；中排是炮塔左、右托架，沿用模型的挂点编号。 */
export const SUB_SLOTS = [2, 4, 1, 0, 3, 5] as const;
/** 储备格（T243）接在六个挂位后面编号；放在里面的武器不上车、不开火。 */
export const RESERVE_SLOTS = [6, 7, 8] as const;
export const isReserve = (slot: number) => RESERVE_SLOTS.includes(slot as typeof RESERVE_SLOTS[number]);
export const isSubSlot = (slot: number) => SUB_SLOTS.includes(slot as typeof SUB_SLOTS[number]) || isReserve(slot);
export const SUB_POSITION = ['右肩', '左肩', '左前', '左后', '右前', '右后', '储备一', '储备二', '储备三'];
export const SUB_PREFERS: Record<WeaponId, readonly number[]> = {
  mg: [0, 1, 2, 4, 3, 5], tesla: [1, 0, 3, 5, 2, 4], flamer: [2, 4, 1, 0, 3, 5],
  mortar: [3, 5, 2, 4, 1, 0], drones: [4, 2, 5, 3, 0, 1], airstrike: [5, 3, 4, 2, 1, 0],
};
export const subLevelName = (level: number) => `${['', '一', '二', '三', '四'][level] ?? level}级`;
export const subForm = (id: WeaponId, level: number) => level >= 4 ? 6 : level >= 3 ? 5 : level >= 2 ? (id === 'flamer' ? 4 : 3) : 1;

/** 复用原来的四种形态；合成后的火力按各武器的弹数、间隔分别加重。重复件完整享受改装。 */
export const SUB_POWER: Record<WeaponId, readonly number[]> = {
  mg: [1, 1.1, 1.9, 3.2],
  mortar: [1, 1.2, 2, 2.6],
  tesla: [1, 1.8, 2.8, 3],
  flamer: [1, 1.6, 3.2, 5.5],
  drones: [1, 1, 1.25, 1.7],
  airstrike: [1, 1.2, 1.5, 1.6],
};
export const subPower = (id: WeaponId, level: number) => SUB_POWER[id][Math.max(0, Math.min(3, level - 1))];
export const EVO_SHOT: Record<WeaponId, number> = { mg: 1.25 * SUB_DMG, mortar: 40 * SUB_DMG, tesla: 24 * SUB_DMG, flamer: 11 * SUB_DMG, drones: 48 * SUB_DMG, airstrike: 50 * SUB_DMG };
export const EVO_BURN = 7 * SUB_DMG;
export const SUB_FORMS: Record<WeaponId, readonly string[]> = {
  mg: ['单管连射', '双联机枪', '穿透弹流', '加特林风暴'],
  mortar: ['单发落弹', '双发齐射', '三发子母弹', '巨弹带 6 枚子母弹'],
  tesla: ['短闪电链', '延长连锁', '连锁附带麻痹', '多道雷暴'],
  flamer: ['窄扇喷火', '宽扇喷火', '留下地面火', '地狱火与火环'],
  drones: ['单机俯冲', '双机俯冲', '三机范围爆炸', '蜂群与护航机'],
  airstrike: ['一条轰炸线', '增加航弹', '燃烧轰炸线', '三机编队'],
};

/** 卡面先定型号，再抽成品级别；精英只对一张保底副武器使用后两行概率。 */
export function rollSubLevel(playerLevel: number, elite: boolean, roll: number): number {
  if (elite) return playerLevel >= 15 && roll < 0.02 ? 3 : 2;
  if (playerLevel >= 15) return roll < 0.01 ? 3 : roll < 0.30 ? 2 : 1;
  return roll < (playerLevel >= 8 ? 0.25 : 0.10) ? 2 : 1;
}

/** 数值说明也读这张表；前三档沿用原形态的射速、弹数、射程。 */
export function subStats(id: WeaponId, level: number): Record<string, number> {
  const s = { ...WEAPONS[id].stats(subForm(id, level)) };
  if (level >= 4) {
    s.伤害 = EVO_SHOT[id];
    if (id === 'mg') Object.assign(s, { 射速: 48, 枪管: 2, 射程: 66 });
    if (id === 'mortar') Object.assign(s, { 伤害: EVO_SHOT.mortar * 3.5, 炮弹: 1, 间隔: 4.5 });
    if (id === 'tesla') Object.assign(s, { 连锁: 5, 冷却: 0.55, 射程: 46 });
    if (id === 'flamer') Object.assign(s, { 燃烧: EVO_BURN, 射程: 28 });
    if (id === 'drones') Object.assign(s, { 每轮: 5, 间隔: 2 });
    if (id === 'airstrike') Object.assign(s, { 炸弹: 30, 冷却: 8 });
  }
  for (const key of ['伤害', '燃烧']) if (s[key]) s[key] = Math.round(s[key] * subPower(id, level) * 100) / 100;
  return s;
}

export interface SubArc { center: number; half: number }
/** 角度和炮塔一致：零是车头，正数朝左。机枪和喷火器只打挂位朝外的半圈。 */
export function subArc(id: WeaponId, slot: number): SubArc {
  if (id !== 'mg' && id !== 'flamer') return { center: 0, half: Math.PI };
  if (slot === 0 || slot === 1) return { center: slot === 1 ? Math.PI / 2 : -Math.PI / 2, half: Math.PI / 2 };
  return { center: slot === 3 || slot === 5 ? Math.PI : 0, half: Math.PI / 2 };
}
export const subAngle = (angle: number) => Math.atan2(Math.sin(angle), Math.cos(angle));
export function subCanAim(id: WeaponId, slot: number, frameYaw: number, dx: number, dz: number): boolean {
  const arc = subArc(id, slot);
  return arc.half === Math.PI || Math.abs(subAngle(Math.atan2(-dx, -dz) - frameYaw - arc.center)) <= arc.half + 1e-6;
}
export function subDirection(id: WeaponId, slot: number): string {
  if (isReserve(slot)) return '储备中不开火';
  if (id === 'mg') return slot === 0 || slot === 1
    ? `随炮塔转 · ${slot === 1 ? '左' : '右'}侧半圈 · 可对空`
    : `${slot === 3 || slot === 5 ? '后' : '前'}方及两侧 · 可对空`;
  if (id === 'mortar') return '全向抛射 · 近身不打';
  if (id === 'tesla') return '全向放电 · 连锁绕行';
  if (id === 'drones') return '全向追踪 · 可对空';
  if (id === 'airstrike') return '全向呼叫 · 近身不炸';
  if (slot === 0 || slot === 1) return `随炮塔转 · ${slot === 1 ? '左' : '右'}侧半圈`;
  return `${slot === 3 || slot === 5 ? '后' : '前'}方及两侧`;
}

export interface SubItem {
  uid: number;
  id: WeaponId;
  level: number;
  slot: number;
  link: LinkId | null;
  locked: boolean;
}
export interface SubReward { id: WeaponId; level: number }
export interface SubPlan {
  signature: string;
  kind: 'install' | 'merge' | 'replace' | 'move' | 'swap';
  result: SubReward & { slot: number; uid: number };
  consumed: number[];
  source?: number;
  target?: number;
  lostLink: LinkId | null;
  freed: number;
}
export const subSignature = (items: readonly SubItem[]) => items.map(w => `${w.uid}:${w.id}:${w.level}:${w.slot}:${w.link}:${w.locked}`).join('|');

/** 每次只处理来源和目标两件；奖励未入车，满六格也能直接合成一次。储备格和挂位共用同一套规则，究极材料不进储备。 */
export function planSub(items: readonly SubItem[], targetSlot: number, reward: SubReward | null, sourceSlot?: number): SubPlan | null {
  if (!isSubSlot(targetSlot)) return null;
  const source = reward ? null : items.find(w => w.slot === sourceSlot);
  const incoming = reward ?? source;
  if (!incoming || source?.slot === targetSlot) return null;
  const target = items.find(w => w.slot === targetSlot);
  if (reward && target?.locked) return null;
  if ((source?.locked && isReserve(targetSlot)) || (target?.locked && source && isReserve(source.slot))) return null;
  const plan = planPair(items, targetSlot, incoming, source, target);
  // 带联动的那件最后落进储备，联动解除
  const parked = isReserve(targetSlot) ? (plan.kind === 'merge' ? items.find(w => w.uid === plan.result.uid) : source)
    : plan.kind === 'swap' && source && isReserve(source.slot) ? target : undefined;
  if (parked?.link) plan.lostLink = parked.link;
  return plan;
}

function planPair(items: readonly SubItem[], targetSlot: number, incoming: SubItem | SubReward, source: SubItem | null | undefined, target: SubItem | undefined): SubPlan {
  const plan: SubPlan = {
    signature: subSignature(items), kind: 'install',
    result: { id: incoming.id, level: incoming.level, slot: targetSlot, uid: source?.uid ?? 0 },
    consumed: [], source: source?.uid, target: target?.uid, lostLink: null, freed: 0,
  };
  if (!target) { plan.kind = source ? 'move' : 'install'; return plan; }
  if (target.id !== incoming.id || target.level !== incoming.level || incoming.level >= SUB_MAX || source?.locked || target.locked) {
    plan.kind = source ? 'swap' : 'replace';
    if (!source) { plan.consumed.push(target.uid); plan.lostLink = target.link; }
    return plan;
  }
  plan.kind = 'merge';
  const keep = source?.link ? source : target;
  plan.result = { id: incoming.id, level: incoming.level + 1, slot: targetSlot, uid: keep.uid };
  plan.consumed = [target.uid, ...(source ? [source.uid] : [])].filter(uid => uid !== keep.uid);
  plan.freed = plan.consumed.length;
  return plan;
}
