import * as THREE from 'three';
import type { GeoCache } from '../assets/GeoCache';
import { MAT } from '../assets/materials';
import { rng } from '../game/rng';
import { nearestPlayer } from '../game/players';

/**
 * scrap 不再掉落实体，只作为经验结算的类别；repair = 首领战前的两个维修箱；elite = 精英战利品箱（T017-9B；T041 起首领倒下也掉一个）。
 * T036（制作人「删除掉所有路上的升级箱，现在只有击败精英会掉箱子」）：空投补给箱（每 70 秒一个、捡到免费挑一个部件）删掉，压碎路障随机掉的维修箱也删掉
 */
export type PickupKind = 'scrap' | 'repair' | 'elite';

interface Pickup {
  kind: PickupKind;
  obj: THREE.Group;
  alive: boolean;
  value: number;
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  vz: number;
  t: number;
  lift: number;
}

const REST_Y = 0.7;
const COLLECT_RADIUS = 2.8;
const GRAVITY = 25;
/** 精英战利品箱（T017-9B）：这么远就开始吸过来（米，比普通拾取范围远得多：开过精英残骸附近就一定捡到） */
const ELITE_MAGNET = 30;
/** T239：吸附圈外的精英箱子照样飞过来，速度 = 10 + 超出圈外的米数 × 这个（米 / 秒），封顶 ELITE_FAR_MAX；倒在身后 65 米，约 3.3 秒捡到（含蹦起落地） */
const ELITE_FAR_GAIN = 1.2;
const ELITE_FAR_MAX = 60;
/** 精英箱子在车后面时多加的速度（米 / 秒）：车往前开 6.5，不加的话圈边上只比车快一点，追得很慢；在前方的箱子不加 */
const ELITE_CHASE = 8;
/** 远距离飞行时离地抬高多少（米） */
const ELITE_FAR_LIFT = 3;

/** 地上可以捡的东西：首领战前的维修箱、精英战利品箱；靠近会被吸过来（经验在击毁时直接给，不掉落） */
export class Pickups {
  networkObjects() { return this.list.filter(p => p.alive); }
  networkModel(kind: PickupKind): THREE.Group {
    const group = this.build(kind);
    this.scene.add(group);
    return group;
  }
  /** who = 哪一辆捡到的（update 传进来的 players 里的下标，T117） */
  onCollect: ((kind: PickupKind, value: number, x: number, z: number, who: number) => void) | null = null;
  private readonly list: Pickup[] = [];

  /** 地面高度（T025 顺手：掉进坑里的箱子贴着坑底 / 桥面，不再悬在半空） */
  groundAt: ((x: number, z: number) => number) | null = null;

  constructor(
    private readonly scene: THREE.Scene,
    private readonly geo: GeoCache,
  ) {}

  /**
   * pop = 从 (x, z) 蹦出来的力度（0 = 直接放在地上）；
   * from = 改成从 [x, 离地高, z] 抛过来、[3] 秒后落到 (x, z)（T041 首领战利品箱：坍塌完最后一声大爆炸把它从残骸里抛出来）
   */
  spawn(kind: PickupKind, x: number, z: number, value = 1, pop = 1, from?: readonly [number, number, number, number]): void {
    let p = this.list.find((item) => item.kind === kind && !item.alive);
    if (!p) {
      p = { kind, obj: this.build(kind), alive: false, value: 0, x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, t: 0, lift: 0 };
      this.scene.add(p.obj);
      this.list.push(p);
    }
    const a = rng.loot() * Math.PI * 2;
    const sp = (1.5 + rng.loot() * 3) * pop;
    p.alive = true;
    p.value = value;
    p.x = x;
    p.z = z;
    p.y = REST_Y + (pop > 0 ? 0.5 : 0);
    p.vx = Math.cos(a) * sp;
    p.vz = Math.sin(a) * sp;
    p.vy = pop > 0 ? 6 + rng.loot() * 4 : 0;
    p.t = Math.random() * 10;
    p.lift = 0;
    if (from) {
      const [fx, fy, fz, t] = from;
      const rest = REST_Y + (this.groundAt ? this.groundAt(x, z) : 0);
      p.x = fx;
      p.y = fy;
      p.z = fz;
      p.vx = (x - fx) / t;
      p.vz = (z - fz) / t;
      p.vy = (rest - fy) / t + 0.5 * GRAVITY * t;
    }
    p.obj.visible = true;
    p.obj.position.set(p.x, p.y, p.z);
  }

  /**
   * players：每辆车的位置和磁吸范围；magnet 是单人默认范围。
   * rear：甩到身后多远回收按的位置（T106 停车攻坚时是能退到的最远处，平时就是玩家）
   */
  update(delta: number, players: readonly { readonly x: number; readonly z: number; readonly magnet?: number }[], magnet: number, rear = players[0].z): void {
    for (const p of this.list) {
      if (!p.alive) continue;
      p.t += delta;
      const rest = REST_Y + (this.groundAt ? this.groundAt(p.x, p.z) : 0);
      if (p.vy !== 0 || p.y > rest + 0.01) {
        p.vy -= GRAVITY * delta;
        p.x += p.vx * delta;
        p.z += p.vz * delta;
        p.y += p.vy * delta;
        if (p.y <= rest) {
          p.y = rest;
          p.vx = p.vy = p.vz = 0;
        }
      } else p.y = rest;

      const near = nearestPlayer(players, p.x, p.z);
      const dx = near.x - p.x;
      const dz = near.z - p.z;
      const d = Math.hypot(dx, dz) || 1;
      const elite = p.kind === 'elite';
      const ownMagnet = near.magnet ?? magnet;
      const mag = elite ? Math.max(ownMagnet, ELITE_MAGNET) : ownMagnet;
      let far = 0;
      // 精英战利品箱蹦出来落地后才吸（别还在半空就飞过来）；T239：落地后多远都飞向最近的车，吸附圈外按距离提速
      if (elite ? p.vy === 0 : d < mag) {
        const chase = elite && p.z > near.z ? ELITE_CHASE : 0;
        const pull = chase + (d < mag ? 10 + (1 - d / mag) * 34 : Math.min(ELITE_FAR_MAX, 10 + (d - mag) * ELITE_FAR_GAIN));
        const step = Math.min(pull * delta, d);
        p.x += (dx / d) * step;
        p.z += (dz / d) * step;
        far = d < mag ? 0 : 1;
      }
      if (d < COLLECT_RADIUS) {
        p.alive = false;
        p.obj.visible = false;
        p.lift = 0;
        this.onCollect?.(p.kind, p.value, p.x, p.z, players.indexOf(near));
        continue;
      }
      // 甩到身后的回收只管维修箱；精英箱子不回收，会自己追上来（T239）
      if (!elite && p.z > rear + 25) {
        p.alive = false;
        p.obj.visible = false;
        continue;
      }

      // 远距离飞行时抬高，从残骸、掩体上面越过去（箱子本身不做碰撞，不会被卡住）
      p.lift += (far * ELITE_FAR_LIFT - p.lift) * Math.min(1, delta * 3);
      const bob = elite ? 0.6 + Math.sin(p.t * 2) * 0.25 : Math.sin(p.t * 5) * 0.18;
      p.obj.position.set(p.x, p.y + bob + p.lift, p.z);
      p.obj.rotation.y += delta;
    }
  }

  clear(): void {
    for (const p of this.list) {
      p.alive = false;
      p.obj.visible = false;
    }
  }

  private build(kind: PickupKind): THREE.Group {
    const g = new THREE.Group();
    if (kind === 'repair') {
      g.add(
        new THREE.Mesh(
          this.geo.merged('repair', () => [
            { geo: new THREE.BoxGeometry(1.4, 1.0, 1.4), color: 0x3f8f4a },
            { geo: new THREE.BoxGeometry(1.0, 0.14, 0.3), color: 0xf2f2ee, pos: [0, 0.55, 0] },
            { geo: new THREE.BoxGeometry(0.3, 0.14, 1.0), color: 0xf2f2ee, pos: [0, 0.55, 0] },
          ]),
          MAT.painted,
        ),
      );
      return g;
    }
    // 精英战利品箱：暗红箱体 + 金色包角 / 箍条 + 金色徽记，红金光柱
    const box = new THREE.Mesh(
      this.geo.merged('crate-elite', () => [
        { geo: new THREE.BoxGeometry(2.1, 2.1, 2.1), color: 0x7a2a22 },
        { geo: new THREE.BoxGeometry(2.18, 0.26, 2.18), color: 0xd8a940, pos: [0, 0.65, 0] },
        { geo: new THREE.BoxGeometry(2.18, 0.26, 2.18), color: 0xd8a940, pos: [0, -0.65, 0] },
        ...[-1, 1].flatMap((sx) => [-1, 1].map((sz) => ({ geo: new THREE.BoxGeometry(0.3, 2.16, 0.3), color: 0xc8962e, pos: [sx * 0.95, 0, sz * 0.95] as [number, number, number] }))),
        { geo: new THREE.BoxGeometry(0.95, 0.95, 0.06), color: 0xffd76a, pos: [0, 0, 1.1] },
        { geo: new THREE.BoxGeometry(0.95, 0.95, 0.06), color: 0xffd76a, pos: [0, 0, -1.1] },
        { geo: new THREE.BoxGeometry(0.4, 0.4, 0.08), color: 0x8a1e14, pos: [0, 0, 1.14], rot: [0, 0, Math.PI / 4] },
      ]),
      MAT.painted,
    );
    box.castShadow = true;
    g.add(box);
    const beam = new THREE.Mesh(this.geo.box(0.5, 14, 0.5), MAT.beaconElite);
    beam.position.y = 7.5;
    g.add(beam);
    return g;
  }
}
