import type { MoveIntent } from './TankMovement';
import { GamepadInput } from './GamepadInput';
import type { SeatBinding } from './seats';
import { gameplayKey } from './controlBindings';

/**
 * 点按判定：手指落下到抬起，位移不超过 TAP_SLOP 像素、时长不超过 TAP_MAX_MS，算「点一下」（开炮）。
 * 位移一超过 TAP_SLOP，这根手指这次按下就只管走位，松手也不开炮。
 */
const TAP_SLOP = 12;
const TAP_MAX_MS = 350;
/** 激光 / 火神：手指落下后 HOLD_MS 内没拖出 TAP_SLOP，就算「按住」开始输出 */
const HOLD_MS = 180;
/** 终极键：手指落在键上不动这么久 = 看说明（这次不发射） */
const ULT_INFO_MS = 500;

/**
 * 双摇杆（T017-18B，设置「操作 双摇杆」）：坦克那条横线往上 TWIN.above 像素以下是拇指区，左半 = 走位（和经典的拖动一样），
 * 右半 = 瞄准摇杆（按下去拖 = 瞄准、松手 = 开炮；激光按下就出光、拖动扫射）；拖动不到 TWIN.dead 像素算没指方向（交给自动瞄准）
 */
export const TWIN = { above: 30, dead: 14 };

/** 键盘开火：Space 不指定方向（交给自动瞄准），Q / E 斜射（T124：W / ↑ 改成前进，不再开火） */
const KEY_AIM: Record<string, number | null> = { Space: null, KeyQ: -0.45, KeyE: 0.45 };
/** 前后方向键；F 保留为前进的备用键。 */
const KEY_FWD = ['KeyW', 'ArrowUp', 'KeyF'];
const KEY_BACK = ['KeyS', 'ArrowDown'];
const KEY_SIDE = ['KeyA', 'KeyD', 'ArrowLeft', 'ArrowRight'];
const KEY_MOVE = [...KEY_FWD, ...KEY_BACK, ...KEY_SIDE];
/** 有精确指针（电脑鼠标）的设备才认悬停瞄准；触屏设备上模拟出来的鼠标事件不算（T055：操作提示按它分电脑 / 触屏写） */
export const FINE_POINTER = (() => {
  try {
    return typeof matchMedia === 'function' && matchMedia('(pointer: fine)').matches;
  } catch {
    return false;
  }
})();

/**
 * 每根手指这次按下扮演的角色：
 * - pending：刚落下还没判定；先跟随拖动，判成点按 / 按住时撤销
 * - steer：拖动走位
 * - hold：按住开火（激光），之后的左右移动用来扫射
 * - none：已有别的手指在走位，这根拖动的手指不起作用
 * - aim：双摇杆的右手瞄准摇杆（主炮 / 火箭：拖着瞄准，松手开炮）
 */
type Role = 'pending' | 'steer' | 'hold' | 'none' | 'aim';

interface Touch {
  x0: number;
  y0: number;
  t0: number;
  lastX: number;
  lastY: number;
  role: Role;
  /** 判定前顺带的拖动量（横 / 竖），判成点按 / 按住时撤销。 */
  temp: number;
  tempY: number;
  /** 落在终极键上：不会变成激光按住；点一下 = 发射终极（不开炮），拖出去 = 照常走位，按住 = 看说明 */
  ult: boolean;
  /** 终极键上按住看说明中（松手不发射） */
  info: boolean;
  /** 双摇杆：右手瞄准摇杆（按住的那根手指现在的位置在 x / y）；左手区的手指（不会变成激光按住） */
  stick: boolean;
  left: boolean;
  x: number;
  y: number;
  /** 电脑鼠标左键（有精确指针的设备）：激光按住时光束方向跟着鼠标位置走（汇总第 63 条） */
  mouse: boolean;
}

/** 终极键的判定圆（屏幕坐标）；键不显示时为 null */
export interface UltZone {
  x: number;
  y: number;
  r: number;
}

/** 开火事件：at = 点按 / 按住的屏幕位置（键盘开火为 null）；aim = 键盘指定的偏角（null = 不指定方向）；stick = 双摇杆瞄准摇杆的 [起点 x, y, 现在 x, y]（拖动不到 TWIN.dead 为 null） */
export interface Trigger {
  at: [number, number] | null;
  aim: number | null;
  stick?: [number, number, number, number] | null;
  /** 触屏短点按；按住开火、瞄准摇杆和鼠标不算。 */
  touchTap?: boolean;
}

/** 双摇杆的瞄准摇杆（按住中）：起点、现在的位置、拖出去够不够远（dir） */
export interface StickState {
  x0: number;
  y0: number;
  x: number;
  y: number;
  dir: boolean;
}

/**
 * 操作模型（手指落下后先看它动不动）：
 * - 普通推进：横拖平移目标位置，手指不动就停；上下无效
 * - 拦路（T234）：同一个手势，上下拖也平移目标位置（比例和横拖一样），手指不动就停
 * - 开炮：点一下（主炮 / 火箭一下一发，不连发）；Game 按设备和瞄准设置决定是否采用点按方向
 * - 激光：落下不动就按住输出，手指不抬持续输出；按住时左右移动 = 扫射光束（不走位）
 * - 双指：一指拖着走位，另一指点按开炮 / 按住扫射
 * - 终极键（右下，键本身不接事件，这里按判定圆认手指）：点一下发射终极（不开炮）、拖出去照常走位、按住 0.5 秒看说明；激光的按住判定对它不生效
 * - 键盘：A/D 或 ←/→ 只管走位（汇总第 63 条起激光输出时也一样，绝不转炮塔 / 光束），Space 开火（按住持续），Q/E 斜射，R 发射终极；
 *   停车攻坚时 W / ↑ 前进、S / ↓ 后退（T124；F 也能前进；滚轮不再前后挪）
 * - 双摇杆（T017-18B，mode = 'twin'）：拇指区左半走位、右半瞄准摇杆（拖着瞄准、松手开炮；激光按下出光、拖动扫射），上半屏沿用普通点按规则
 * - 电脑（T017-18a）：鼠标悬停 = 炮塔指着鼠标（hover），左键点 = 开炮，激光按下左键就出光、移动鼠标扫射，A / D 走位；
 *   汇总第 63 条：激光按住左键时光束方向完全由鼠标位置决定（mouse / mouseSeq / mouseHeld，Game.stepMouseBeam），键盘只走位
 * - 电脑右键（汇总第 60 条）：右键按下 = 发射当前究极（和点究极键一样，设置「究极」是自动还是手动都能用；左键按着时再按右键也算）；浏览器右键菜单屏蔽掉。触屏不受影响
 */
export class TankInput {
  readonly gamepad: GamepadInput;
  /** 键盘横向轴，-1..1 */
  axis = 0;
  /** 键盘前后轴：1 = 前进，-1 = 后退 */
  axisZ = 0;
  /** 精英 / 首领拦路中：上下拖动也算走位。 */
  free = false;
  /** 当前武器按住开火（激光）：由游戏层每帧写入 */
  holdToFire = false;
  /** 右摇杆 / 鼠标左键按住开火（激光和火神都开；经典触屏按住只看 holdToFire，T089 起火神经典触屏也按住开火） */
  holdStick = false;
  /** 终极键按下 / 松开（按压反馈：键缩小一点，因为键本身不接 pointer 事件） */
  onUltPress: ((down: boolean) => void) | null = null;
  /** 终极键按住满 ULT_INFO_MS：显示 / 隐藏说明气泡 */
  onUltInfo: ((show: boolean) => void) | null = null;
  /** 操作模式（T017-18c，设置「操作 经典 / 双摇杆」，默认经典） */
  mode: 'classic' | 'twin' = 'classic';
  /** 瞄准摇杆松手的次数（教学提示用过 3 次淡出） */
  stickUses = 0;
  /** 电脑鼠标悬停（T017-18a）：鼠标没按键、在画面上的位置；鼠标离开画面 / 触屏设备为 null */
  hover: [number, number] | null = null;
  /**
   * 电脑鼠标在画面上的位置（汇总第 63 条：按着键也算，按着左键拖出画面也跟着走）；鼠标离开画面（没按键）/ 触屏设备为 null。
   * mouseSeq = 鼠标每挪一次 +1（光束方向只在鼠标真的动了才重算，坦克横移、镜头跟着走都不算）
   */
  mouse: [number, number] | null = null;
  mouseSeq = 0;

  private readonly moveIntent: MoveIntent = { active: false, x: 0, forward: 0 };
  private dragX = 0;
  private dragY = 0;
  /** 按住开火那根手指的原始拖动量，激光扫射沿用。 */
  private holdX = 0;
  private holdMX = 0;
  private holdY = 0;
  private trigger: Trigger | null = null;
  private ultTap = false;
  /** 鼠标右键现在按着（左键按着时再按右键，浏览器只发 pointermove，要靠它认出「按下」那一下） */
  private rightDown = false;
  private firstTouch = false;
  private readonly touches = new Map<number, Touch>();
  private readonly keys = new Set<string>();

  constructor(
    private readonly layer: HTMLElement,
    /** 终极键的判定圆（每次手指落下时取一次，键的位置由 HUD 缓存） */
    private readonly ultZone: () => UltZone | null = () => null,
    /** 画布版界面：手指落在界面上（按钮 / 卡片 / 浮层）就不接这根手指（DOM 版靠元素盖在触控层上面） */
    private readonly blocked: (x: number, y: number) => boolean = () => false,
    /** 坦克在屏幕上的高度（像素，双摇杆拇指区的上沿按它算） */
    private readonly tankLine: () => number = () => this.layer.clientHeight * 0.71,
    private readonly seat?: SeatBinding,
  ) {
    this.gamepad = new GamepadInput(seat);
    // 手柄席位不监听键鼠；菜单仍由界面自己的监听器处理。
    if (seat && !seat.seats.acceptsKeyboard(seat.id)) return;
    layer.addEventListener('pointerdown', this.onDown);
    layer.addEventListener('pointermove', this.onMove);
    layer.addEventListener('pointerleave', this.onLeave);
    layer.addEventListener('pointerup', this.onUp);
    layer.addEventListener('pointercancel', this.onCancel);
    this.menuRoot.addEventListener('contextmenu', this.onContextMenu);
    window.addEventListener('keydown', this.onKeyDown);
    window.addEventListener('keyup', this.onKeyUp);
    window.addEventListener('blur', this.releaseAll);
  }

  /** 屏蔽浏览器右键菜单的范围：整个游戏画面（走位层的父节点，DOM 版界面的按钮上右键也不弹菜单） */
  private get menuRoot(): HTMLElement {
    return this.layer.parentElement ?? this.layer;
  }

  /** 普通推进只读横向键；前后键不改变横移幅度，也不参与斜向归一化。 */
  get cruiseAxis(): number {
    if (KEY_SIDE.some(k => this.keys.has(k))) return this.axis;
    return this.steering ? 0 : this.gamepad.move.x;
  }

  /** 原版拖动量，以屏宽为 1；到达目标后，按住不动也不继续横移。 */
  consumeDragX(): number {
    const v = this.dragX;
    this.dragX = 0;
    return v;
  }

  /** 拦路时的上下拖动量（以屏宽为 1，往下为正）；普通推进也照常清空。 */
  consumeDragY(): number {
    const v = this.dragY;
    this.dragY = 0;
    return v;
  }

  /** 拦路时键盘 / 手柄的走位方向（键盘优先，斜向归一化）；有手指在走位时手柄不算，和 cruiseAxis 一样。 */
  movement(): Readonly<MoveIntent> {
    const m = this.moveIntent;
    m.active = KEY_MOVE.some(k => this.keys.has(k));
    m.x = m.active ? this.axis : 0;
    m.forward = m.active ? this.axisZ : 0;
    if (m.active) {
      const length = Math.hypot(m.x, m.forward);
      if (length > 1) { m.x /= length; m.forward /= length; }
      return m;
    }
    if (!this.steering && this.gamepad.move.active) return this.gamepad.move;
    return m;
  }

  /**
   * 读取并清空按住开火那根手指本帧的移动量（以屏宽为 1 归一化）：sweep = 左右原样（激光输出中扫射用）；
   * x / y 保留原始两轴拖动，行驶方向另由 movement 读取
   */
  consumeHold(): { sweep: number; x: number; y: number } {
    const v = { sweep: this.holdX, x: this.holdMX, y: this.holdY };
    this.holdX = this.holdMX = this.holdY = 0;
    return v;
  }

  /** 定格、选卡、暂停时清掉扫射量并重置走位原点，恢复后不补走旧手势。 */
  clearDrag(): void {
    this.dragX = this.dragY = this.holdX = this.holdMX = this.holdY = 0;
    for (const t of this.touches.values()) t.temp = t.tempY = 0;
  }

  reset(): void {
    this.releaseAll();
    this.gamepad.suspend();
    this.clearDrag();
    this.free = false;
    this.trigger = null;
    this.ultTap = false;
  }

  /** 读取并清空开火事件（点按松手 / 激光按住满 HOLD_MS / 键盘开火键按下） */
  consumeTrigger(): Trigger | null {
    const pad = this.gamepad.consumeTrigger();
    const v = this.trigger ?? pad;
    this.trigger = null;
    return v;
  }

  /** 读取并清空「发射终极」（终极键上点一下 / 键盘 R） */
  consumeUlt(): boolean {
    const pad = this.gamepad.consumeUlt();
    const v = this.ultTap || pad;
    this.ultTap = false;
    return v;
  }

  /** 双摇杆的瞄准摇杆（正按着的那根手指；主炮 / 火箭的 aim 和激光的 hold 都算）；没有为 null */
  get stick(): StickState | null {
    for (const t of this.touches.values()) {
      if (!t.stick) continue;
      return { x0: t.x0, y0: t.y0, x: t.x, y: t.y, dir: Math.hypot(t.x - t.x0, t.y - t.y0) >= TWIN.dead };
    }
    return null;
  }

  /** 电脑：激光是鼠标左键按住出的光（光束方向跟鼠标走，汇总第 63 条） */
  get mouseHeld(): boolean {
    for (const t of this.touches.values()) if (t.role === 'hold' && t.mouse) return true;
    return false;
  }

  /** 有精确指针（电脑鼠标）的设备 */
  get fine(): boolean {
    return FINE_POINTER;
  }

  /** 有手指按住开火（或键盘开火键按着）：激光持续输出用 */
  get held(): boolean {
    if (this.gamepad.fireHeld) return true;
    for (const t of this.touches.values()) if (t.role === 'hold') return true;
    for (const k of Object.keys(KEY_AIM)) if (this.keys.has(k)) return true;
    return false;
  }

  /** 玩家是否已经碰过操作（用来淡出提示文字） */
  consumeFirstTouch(): boolean {
    const t = this.firstTouch;
    this.firstTouch = false;
    return t;
  }

  update(): void {
    if (this.seat && !this.seat.seats.acceptsKeyboard(this.seat.id)) this.releaseAll();
    let kb = 0;
    if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) kb -= 1;
    if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) kb += 1;
    this.axis = kb;
    this.axisZ = (KEY_FWD.some((k) => this.keys.has(k)) ? 1 : 0) - (KEY_BACK.some((k) => this.keys.has(k)) ? 1 : 0);
    const now = performance.now();
    // 终极键上按住不动：弹说明（这次松手不发射）
    for (const t of this.touches.values()) {
      if (!t.ult || t.info || t.role !== 'pending' || now - t.t0 < ULT_INFO_MS) continue;
      t.info = true;
      this.onUltInfo?.(true);
    }
    // 激光：落下后一直没拖出去，满 HOLD_MS 就算按住，开始输出（终极键上的手指、双摇杆左手区的手指不算）
    if (!this.holdToFire) return;
    for (const t of this.touches.values()) {
      if (t.ult || t.left || t.role !== 'pending' || now - t.t0 < HOLD_MS) continue;
      t.role = 'hold';
      this.settle(t);
      this.trigger = { at: [t.x0, t.y0], aim: null };
    }
  }

  dispose(): void {
    this.gamepad.dispose();
    this.layer.removeEventListener('pointerdown', this.onDown);
    this.layer.removeEventListener('pointermove', this.onMove);
    this.layer.removeEventListener('pointerleave', this.onLeave);
    this.layer.removeEventListener('pointerup', this.onUp);
    this.layer.removeEventListener('pointercancel', this.onCancel);
    this.menuRoot.removeEventListener('contextmenu', this.onContextMenu);
    window.removeEventListener('keydown', this.onKeyDown);
    window.removeEventListener('keyup', this.onKeyUp);
    window.removeEventListener('blur', this.releaseAll);
  }

  /** 已经有一根手指在走位（另一根就不再参与走位；火神按着开火的手指拖动也让给它） */
  get steering(): boolean {
    for (const t of this.touches.values()) if (t.role === 'steer') return true;
    return false;
  }

  /** 点按 / 按住不留下试探性的横移目标。 */
  private settle(t: Touch): void {
    this.dragX -= t.temp;
    this.dragY -= t.tempY;
    t.temp = t.tempY = 0;
  }

  private readonly onDown = (e: PointerEvent) => {
    if (this.seat && !this.seat.seats.acceptsKeyboard(this.seat.id)) return;
    // 电脑鼠标：右键 = 发射究极（不开炮、不走位），中键 / 侧键不管
    if (e.pointerType === 'mouse' && e.button !== 0) {
      if (this.blocked(e.clientX, e.clientY)) this.rightDown = (e.buttons & 2) !== 0;
      else this.mouseButtons(e);
      return;
    }
    // 最多认两根手指：一指走位、一指开火
    if (this.touches.size >= 2 || this.touches.has(e.pointerId) || this.blocked(e.clientX, e.clientY)) return;
    const z = this.ultZone();
    const ult = !!z && Math.hypot(e.clientX - z.x, e.clientY - z.y) <= z.r;
    // 双摇杆：拇指区（坦克线往上 TWIN.above 像素以下）左半走位、右半瞄准摇杆（同时只认一根）；鼠标不算（电脑照经典 + 悬停瞄准）
    const r = this.layer.getBoundingClientRect();
    const thumb = this.mode === 'twin' && e.pointerType !== 'mouse' && !ult && e.clientY - r.top >= this.tankLine() - TWIN.above;
    const right = thumb && e.clientX - r.left >= r.width / 2 && !this.stick;
    const mouse = e.pointerType === 'mouse' && FINE_POINTER;
    if (mouse) this.moveMouse(e);
    const t: Touch = { x0: e.clientX, y0: e.clientY, t0: performance.now(), lastX: e.clientX, lastY: e.clientY, role: 'pending', temp: 0, tempY: 0, ult, info: false, stick: right, left: thumb && !right, x: e.clientX, y: e.clientY, mouse };
    this.touches.set(e.pointerId, t);
    if (right) {
      // 主炮 / 火箭：拖着瞄准、松手开炮；激光：按下就出光，拖动扫射
      t.role = this.holdToFire || this.holdStick ? 'hold' : 'aim';
      if (t.role === 'hold') this.trigger = { at: null, aim: null, stick: null };
    } else if (mouse && (this.holdToFire || this.holdStick) && !ult) {
      // 电脑（T017-18a）：激光按下鼠标左键就出光（朝鼠标指的地方），移动鼠标 = 扫射；走位用 A / D
      t.role = 'hold';
      this.trigger = { at: [e.clientX, e.clientY], aim: null };
    }
    if (ult) this.onUltPress?.(true);
    this.firstTouch = true;
    try { this.layer.setPointerCapture(e.pointerId); } catch { /* 合成事件无法捕获 */ }
  };

  private readonly onMove = (e: PointerEvent) => {
    if (this.seat && !this.seat.seats.acceptsKeyboard(this.seat.id)) return;
    const t = this.touches.get(e.pointerId);
    if (e.pointerType === 'mouse') {
      if (FINE_POINTER) this.moveMouse(e);
      // 多个键一起按 / 松开时浏览器只发 pointermove（button = 变化的那个键，平常移动是 -1）：右键按下 = 究极；
      // 右键按着时左键按下 / 松开 = 照常开始 / 结束这次左键
      this.mouseButtons(e);
      if (e.button === 0 && !t && e.buttons & 1) return this.onDown(e);
      if (e.button === 0 && t && !(e.buttons & 1)) return this.onUp(e);
    }
    if (t) this.track(t, e);
    // 电脑鼠标悬停（没按键）：炮塔指着鼠标所指的地面点（触屏设备不算）
    else if (e.pointerType === 'mouse' && e.buttons === 0 && FINE_POINTER) this.hover = [e.clientX, e.clientY];
  };

  private readonly onLeave = (e: PointerEvent) => {
    if (e.pointerType !== 'mouse') return;
    this.hover = null;
    // 没按键时鼠标离开画面 = 没在指方向（退回自动瞄准）；按着左键拖出去的照样跟着
    if (e.buttons === 0) this.mouse = null;
  };

  /** 电脑鼠标挪到了 (x, y)：真的挪了才算一次（mouseSeq + 1） */
  private moveMouse(e: PointerEvent): void {
    if (this.mouse && this.mouse[0] === e.clientX && this.mouse[1] === e.clientY) return;
    this.mouse = [e.clientX, e.clientY];
    this.mouseSeq += 1;
  }

  private readonly onUp = (e: PointerEvent) => {
    if (e.pointerType === 'mouse') this.mouseButtons(e);
    const t = this.touches.get(e.pointerId);
    if (!t) return;
    this.track(t, e);
    if (t.role === 'aim') {
      // 瞄准摇杆松手 = 开炮（拖动不够远 = 没指方向，交给自动瞄准）
      this.stickUses += 1;
      this.trigger = { at: null, aim: null, stick: Math.hypot(t.x - t.x0, t.y - t.y0) >= TWIN.dead ? [t.x0, t.y0, t.x, t.y] : null };
    } else if (t.stick) this.stickUses += 1;
    // 没拖出去、时间又短 = 点一下：开炮（激光点一下是一次短点射）；落在终极键上 = 发射终极，不开炮
    if (t.role === 'pending' && performance.now() - t.t0 <= TAP_MAX_MS) {
      this.settle(t);
      if (t.ult) this.ultTap = true;
      else this.trigger = { at: [t.x0, t.y0], aim: null, touchTap: e.pointerType !== 'mouse' };
    } else if (t.role === 'pending' && t.ult) this.settle(t);
    this.releaseUlt(t);
    this.touches.delete(e.pointerId);
  };

  private readonly onCancel = (e: PointerEvent) => {
    const t = this.touches.get(e.pointerId);
    if (!t) return;
    if (t.role === 'pending') this.settle(t);
    this.releaseUlt(t);
    this.touches.delete(e.pointerId);
  };

  /** 鼠标按键变化：右键从松开变成按下 = 发射究极（汇总第 60 条） */
  private mouseButtons(e: PointerEvent): void {
    const right = (e.buttons & 2) !== 0;
    if (right && !this.rightDown) {
      this.ultTap = true;
      this.firstTouch = true;
    }
    this.rightDown = right;
  }

  /** 浏览器右键菜单：游戏画面里一律屏蔽（右键 = 发射究极）；分享预览的截图上照常能右键另存 */
  private readonly onContextMenu = (e: Event) => {
    if (!(e.target instanceof HTMLImageElement)) e.preventDefault();
  };

  /** 终极键上的手指抬起 / 拖出去：松开按压反馈、收起说明 */
  private releaseUlt(t: Touch): void {
    if (!t.ult) return;
    t.ult = false;
    this.onUltPress?.(false);
    if (t.info) {
      t.info = false;
      this.onUltInfo?.(false);
    }
  }

  private track(t: Touch, e: PointerEvent): void {
    // 走位和扫射都按屏宽换算；上下只在拦路时算走位。
    const w = this.width();
    const raw = (e.clientX - t.lastX) / w;
    const dy = (e.clientY - t.lastY) / w;
    t.lastX = e.clientX;
    t.lastY = e.clientY;
    t.x = e.clientX;
    t.y = e.clientY;
    if (t.role === 'aim') return;
    const dyMove = this.free ? dy : 0;
    if (t.role === 'steer') {
      this.dragX += raw;
      this.dragY += dyMove;
    } else if (t.role === 'hold') {
      this.holdX += raw;
      this.holdMX += raw;
      this.holdY += dy;
    }
    if (t.role !== 'pending') return;
    const free = !this.steering;
    if (free) {
      this.dragX += raw;
      this.dragY += dyMove;
      t.temp += raw;
      t.tempY += dyMove;
    }
    if (Math.hypot(e.clientX - t.x0, e.clientY - t.y0) <= TAP_SLOP) return;
    // 拖出去了：这次按下只管走位（从终极键上拖出去也一样，不发射）；已有手指在走位就忽略这根
    this.releaseUlt(t);
    if (free) {
      t.role = 'steer';
      t.temp = t.tempY = 0;
    } else {
      t.role = 'none';
      this.settle(t);
    }
  }

  private width(): number {
    return Math.max(1, this.layer.clientWidth);
  }

  private readonly onKeyDown = (e: KeyboardEvent) => {
    if (this.seat && !this.seat.seats.acceptsKeyboard(this.seat.id)) return;
    if ((e.target as HTMLElement)?.matches?.('input, select, textarea')) return;
    const code = gameplayKey(e.code);
    this.keys.add(code);
    if (e.code.startsWith('Arrow')) e.preventDefault();
    // R：发射终极（桌面调试、自动化测试用）
    if (code === 'KeyR' && !e.repeat) {
      this.ultTap = true;
      this.firstTouch = true;
      return;
    }
    if (e.repeat || !(code in KEY_AIM)) return;
    this.trigger = { at: null, aim: KEY_AIM[code] };
    this.firstTouch = true;
    e.preventDefault();
  };

  private readonly onKeyUp = (e: KeyboardEvent) => {
    this.keys.delete(gameplayKey(e.code));
  };

  private readonly releaseAll = () => {
    this.keys.clear();
    for (const t of this.touches.values()) {
      if (t.role === 'pending') this.settle(t);
      this.releaseUlt(t);
    }
    this.touches.clear();
    this.axis = this.axisZ = 0;
    this.holdX = this.holdMX = this.holdY = 0;
    this.rightDown = false;
  };
}
