import { ModeSave, type ModeData } from './modeSave';
import { Profile, type ProfileData } from './Profile';
import { rankOf } from './ranks';
import { lockSaves, saveStore, type RawSave, type SaveIo } from './saveStore';

/**
 * 存档文件（T116）：导出 / 导入用的一份 JSON，以后 Steam 云 / 微信云同步也用这个格式。
 * kind 认文件；format = 外壳的版本；slots 里每个槽原样放、各带各的版本号，导入时走和读档同一条迁移链
 */
export const SAVE_KIND = 'tank-rogue-save';
export const SAVE_FORMAT = 1;

export interface SaveFile {
  kind: typeof SAVE_KIND;
  format: number;
  game: string;
  /** 导出时间（ISO） */
  at: string;
  /** 给人看的一行（导入时不认它，按存档重算） */
  summary: string;
  slots: { profile: ProfileData; modes?: ModeData };
}

/** 导入读出来的两个槽 + 导出时间 */
export interface Unpacked {
  profile: ProfileData;
  modes: ModeData | null;
  at: number;
}

/** 存档弹窗（DOM 版 #save-box / 画布版同一套内容）：标题、几行字、红字一行、粘贴框（只有 DOM 版画）、一排按钮 */
export interface SaveBox {
  title: string;
  lines: string[];
  warn?: string;
  paste?: boolean;
  buttons: { id: string; label: string; main?: boolean }[];
}

const BAD_TEXT = '文本不完整，读不出来';
const NOT_OURS = '不是钢铁破坏者的存档';
const TOO_NEW = '存档来自新版本，先更新';
/** 导入成功到重新载入之间停多久（毫秒） */
const RELOAD_MS = 1500;

const pad = (n: number) => String(n).padStart(2, '0');
const fileName = (d: Date) => `钢铁破坏者存档-${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}-${pad(d.getHours())}${pad(d.getMinutes())}.json`;
const when = (t: number) => {
  const d = new Date(t);
  return `${d.getMonth() + 1} 月 ${d.getDate()} 日 ${pad(d.getHours())}:${pad(d.getMinutes())}`;
};

/** 摘要一行：上尉 · 最远 3120 米 · 出击 42 次 */
export function saveSummary(p: ProfileData): string {
  return p.runs > 0 ? `${rankOf(p.meta.merit).name} · 最远 ${p.bestDistance} 米 · 出击 ${p.runs} 次` : '新存档 · 还没出击';
}

/** 导出文件一行最多多宽（字符） */
const WIDTH = 128;

/** 缩进排版，但放得下一行的对象 / 数组写成一行、只有简单值的长数组一行排几个：文件短，打开就看得出结构。lead = 同一行前面已经有的字（键名） */
const pretty = (v: unknown, pad = '', lead = 0): string => {
  const flat = JSON.stringify(v ?? null);
  if (v === null || typeof v !== 'object' || pad.length + lead + flat.length <= WIDTH) return flat;
  const inner = `${pad}  `;
  const items: string[] = [];
  if (Array.isArray(v) && v.every((x) => x === null || typeof x !== 'object')) {
    for (const s of v.map((x) => JSON.stringify(x ?? null))) {
      const last = items.length - 1;
      if (last >= 0 && items[last].length + s.length + 3 <= WIDTH) items[last] += `, ${s}`;
      else items.push(inner + s);
    }
  } else if (Array.isArray(v)) items.push(...v.map((x) => inner + pretty(x, inner)));
  else {
    for (const [k, x] of Object.entries(v)) {
      const key = `${JSON.stringify(k)}: `;
      if (x !== undefined) items.push(inner + key + pretty(x, inner, key.length));
    }
  }
  const [open, close] = Array.isArray(v) ? ['[', ']'] : ['{', '}'];
  return `${open}\n${items.join(',\n')}\n${pad}${close}`;
};

export function packSave(profile: ProfileData, modes: ModeData | null, now = new Date()): string {
  const file: SaveFile = { kind: SAVE_KIND, format: SAVE_FORMAT, game: '钢铁破坏者', at: now.toISOString(), summary: saveSummary(profile), slots: { profile, ...(modes ? { modes } : {}) } };
  return `${pretty(file)}\n`;
}

/** 导入前的粗查：读档那边宽松照旧，导入多查一道字段类型，免得坏文件导进来开不了游戏 */
const sane = (d: ProfileData) =>
  [d.runs, d.bestDistance, d.bestZone, d.totalScrap, d.meta.merit, d.econ.ticket].every((n) => Number.isFinite(n)) &&
  [d.unlocks, d.leaderboard, d.econ.cores, d.econ.paints, d.econ.emblems, d.meta.coresDone].every((a) => Array.isArray(a)) &&
  typeof d.settings === 'object' && typeof d.meta.foeKills === 'object' && typeof d.run === 'object';

/** 读导入的文本：成功返回两个槽，失败返回给玩家看的一句（红字） */
export function unpackSave(text: string): Unpacked | string {
  let f: RawSave | null;
  try {
    f = JSON.parse(text.trim()) as RawSave | null;
  } catch {
    return BAD_TEXT;
  }
  if (!f || typeof f !== 'object') return NOT_OURS;
  // 也认直接从本地存储抄出来的局外存档（没有外壳）
  const slots = (f.kind === SAVE_KIND ? f.slots : typeof f.version === 'number' ? { profile: f } : null) as RawSave | null;
  if (!slots || typeof slots !== 'object') return NOT_OURS;
  if (typeof f.format === 'number' && f.format > SAVE_FORMAT) return TOO_NEW;
  const p = Profile.parse(slots.profile);
  const m = slots.modes === undefined ? null : ModeSave.parse(slots.modes);
  if (p?.newer || m?.newer) return TOO_NEW;
  if (!p || !sane(p.data)) return NOT_OURS;
  return { profile: p.data, modes: m?.data ?? null, at: Date.parse(String(f.at)) || 0 };
}

/**
 * 设置页「存档」一行的流程（T116）：导出 = 下载文件，下载不了再复制文本；导入 = 选文件 / 粘贴 → 看摘要确认覆盖 → 写进存档、锁住、重新载入。
 * 界面只管画 SaveBox，按钮 id 回到 act
 */
export class SaveFlow {
  private text = '';
  private name = '';
  private copied = false;
  private pending: Unpacked | null = null;

  constructor(
    private readonly io: SaveIo,
    private readonly profile: Profile,
    private readonly modes: ModeSave,
    private readonly show: (box: SaveBox | null) => void,
    /** 界面有没有粘贴框（DOM 版有，画布版没有） */
    private readonly paste: boolean,
  ) {}

  /** 按钮：export / import 是设置页那两个，其余是弹窗里的；typed = 粘贴框里的字 */
  act(id: string, typed = ''): void {
    if (id === 'export') return this.exportNow();
    if (id === 'copy') return void this.copy();
    if (id === 'import') return this.importBox();
    // 选文件要在点按的同一拍里调起来（iOS 不让延后）
    if (id === 'file') return void this.io.pick().then((t) => t !== null && this.check(t));
    if (id === 'paste') return this.check(typed);
    if (id === 'apply') return this.apply();
    this.pending = null;
    this.show(null);
  }

  private exportNow(): void {
    const now = new Date();
    this.text = packSave(this.profile.data, this.modes.data, now);
    this.name = fileName(now);
    this.copied = false;
    this.io.download(this.name, this.text);
    this.exportBox();
  }

  private exportBox(warn?: string): void {
    this.show({
      title: '导出存档',
      lines: [saveSummary(this.profile.data), `文件：${this.name}`, '没下载下来就复制文本，发给自己存着'],
      warn,
      buttons: [{ id: 'copy', label: this.copied ? '已复制' : '复制文本' }, { id: 'close', label: '好', main: true }],
    });
  }

  private async copy(): Promise<void> {
    this.copied = await this.io.copy(this.text);
    this.exportBox(this.copied ? undefined : '复制不了，换个浏览器试试');
  }

  private importBox(warn?: string): void {
    this.pending = null;
    if (!this.profile.slot) return this.show({ title: '导入存档', lines: ['这次打开存档只读，不能导入'], buttons: [{ id: 'close', label: '好', main: true }] });
    this.show({
      title: '导入存档',
      lines: [this.paste ? '选导出的文件，或粘贴存档文本' : '选导出的存档文件'],
      warn,
      paste: this.paste,
      buttons: [{ id: 'file', label: '选择文件', main: true }, ...(this.paste ? [{ id: 'paste', label: '导入文本' }] : []), { id: 'close', label: '取消' }],
    });
  }

  private check(text: string): void {
    const r = text.trim() ? unpackSave(text) : BAD_TEXT;
    if (typeof r === 'string') return this.importBox(r);
    this.pending = r;
    this.confirmBox();
  }

  private confirmBox(warn = '本机的进度会被覆盖'): void {
    const r = this.pending!;
    this.show({
      title: '覆盖本机存档？',
      lines: [saveSummary(r.profile), r.at ? `${when(r.at)} 导出` : '导出时间不明', `本机：${saveSummary(this.profile.data)}`],
      warn,
      buttons: [{ id: 'apply', label: '导入', main: true }, { id: 'close', label: '取消' }],
    });
  }

  private apply(): void {
    const r = this.pending;
    const slot = this.profile.slot;
    if (!r || !slot) return this.act('close');
    r.profile.savedAt = Date.now();
    if (!saveStore.write(slot, JSON.stringify(r.profile))) return this.confirmBox('写不进本机存储');
    if (r.modes && this.modes.slot) saveStore.write(this.modes.slot, JSON.stringify(r.modes));
    lockSaves();
    this.show({ title: '导入成功', lines: [saveSummary(r.profile), '正在重新载入…'], buttons: [] });
    setTimeout(() => this.io.reload(), RELOAD_MS);
  }
}
