/** 步兵脚下的挡路判定（T246）：圆形的人被障碍物推出去。位移累加进 out，碰到返回 true */
export interface Push {
  x: number;
  z: number;
}

/** 旋转矩形（中心 cx, cz，转角 rot，半宽 hw、半深 hd；局部轴和 World.overlaps 一致） */
export function pushFromBox(x: number, z: number, r: number, cx: number, cz: number, rot: number, hw: number, hd: number, out: Push): boolean {
  const c = Math.cos(rot);
  const s = Math.sin(rot);
  const dx = x - cx;
  const dz = z - cz;
  const lx = dx * c - dz * s;
  const lz = dx * s + dz * c;
  if (Math.abs(lx) >= hw + r || Math.abs(lz) >= hd + r) return false;
  const ex = lx - Math.max(-hw, Math.min(hw, lx));
  const ez = lz - Math.max(-hd, Math.min(hd, lz));
  const d = Math.hypot(ex, ez);
  let px = 0;
  let pz = 0;
  if (d > 1e-6) {
    if (d >= r) return false;
    px = (ex * (r - d)) / d;
    pz = (ez * (r - d)) / d;
  } else {
    // 圆心已经在矩形里：从最近的那条边出去
    const ox = hw - Math.abs(lx);
    const oz = hd - Math.abs(lz);
    if (ox < oz) px = (Math.sign(lx) || 1) * (ox + r);
    else pz = (Math.sign(lz) || 1) * (oz + r);
  }
  out.x += px * c + pz * s;
  out.z += -px * s + pz * c;
  return true;
}

/** 圆形占地（树干、杆身、巨石、活着的车） */
export function pushFromCircle(x: number, z: number, r: number, cx: number, cz: number, R: number, out: Push): boolean {
  const dx = x - cx;
  const dz = z - cz;
  const reach = r + R;
  const d2 = dx * dx + dz * dz;
  if (d2 >= reach * reach) return false;
  const d = Math.sqrt(d2);
  if (d < 1e-6) {
    out.x += reach;
    return true;
  }
  out.x += (dx * (reach - d)) / d;
  out.z += (dz * (reach - d)) / d;
  return true;
}
