import * as THREE from 'three';

/**
 * 火神弹壳（D1-032 第 8.2 / 8.7 节）：黄铜小圆柱从抛壳口往外侧上方甩，落地弹两下（第二下很低）、躺 rest 秒沉下去；只落地面，不碰车和景物。
 * T088：弹链节（暗钢色扁片，同一个网格换实例颜色）夹在里面一起甩。
 * 一个实例化网格（1 次绘制），池子 300 循环用，满了顶掉最老的；limit = 这一档最多同时几个（高 300 / 中 200 / 低 80），rest 高 6 / 中 4 / 低 2.5 秒
 */
const CAP = 300;
const SINK = 0.5;
const BRASS = new THREE.Color(0xc89a48);
const LINK = new THREE.Color(0x3c3e40);

interface Shell {
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  vz: number;
  rx: number;
  rz: number;
  spin: number;
  t: number;
  /** 0 飞 / 1 弹过一次 / 2 弹过两次 / 3 躺着 */
  stage: number;
  s: number;
  link: boolean;
  alive: boolean;
}

export class Casings {
  limit = CAP;
  rest = 6;
  /** 落地那一下叮当（Game 接音效，每秒有上限） */
  onLand: ((x: number, z: number) => void) | null = null;
  private readonly mesh: THREE.InstancedMesh;
  private readonly list: Shell[] = [];
  private head = 0;
  private readonly m = new THREE.Matrix4();
  private readonly q = new THREE.Quaternion();
  private readonly e = new THREE.Euler();
  private readonly p = new THREE.Vector3();
  private readonly sc = new THREE.Vector3();

  constructor(scene: THREE.Scene) {
    const geo = new THREE.CylinderGeometry(0.045, 0.045, 0.2, 6);
    this.mesh = new THREE.InstancedMesh(geo, new THREE.MeshStandardMaterial({ color: 0xffffff, metalness: 0.85, roughness: 0.35, emissive: 0x1a1206 }), CAP);
    this.mesh.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(CAP * 3), 3);
    this.mesh.instanceColor.setUsage(THREE.DynamicDrawUsage);
    this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.mesh.frustumCulled = false;
    this.mesh.count = 0;
    scene.add(this.mesh);
    for (let i = 0; i < CAP; i++) this.list.push({ x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, rx: 0, rz: 0, spin: 0, t: 0, stage: 0, s: 1, link: false, alive: false });
  }

  /** 从 (x, y, z) 抛一个，初速 (vx, vy, vz)；s = 个头，link = 弹链节 */
  emit(x: number, y: number, z: number, vx: number, vy: number, vz: number, s = 1, link = false): void {
    let c = this.list.find((it) => !it.alive);
    if (!c || this.live >= this.limit) {
      c = this.list[this.head];
      this.head = (this.head + 1) % CAP;
    }
    Object.assign(c, { x, y, z, vx, vy, vz, rx: Math.random() * 6, rz: Math.random() * 6, spin: 10 + Math.random() * 14, t: 0, stage: 0, s, link, alive: true });
  }

  private get live(): number {
    let n = 0;
    for (const c of this.list) if (c.alive) n++;
    return n;
  }

  update(dt: number, groundAt: (x: number, z: number) => number): void {
    let n = 0;
    for (const c of this.list) {
      if (!c.alive) continue;
      c.t += dt;
      const g = groundAt(c.x, c.z) + 0.04 * c.s;
      if (c.stage < 3) {
        c.vy -= 22 * dt;
        c.x += c.vx * dt;
        c.y += c.vy * dt;
        c.z += c.vz * dt;
        c.rx += c.spin * dt;
        if (c.y <= g) {
          c.y = g;
          if (c.stage === 0) this.onLand?.(c.x, c.z);
          c.stage += 1;
          c.vy = c.stage === 1 ? -c.vy * 0.3 : c.stage === 2 ? -c.vy * 0.18 : 0;
          c.vx *= 0.45;
          c.vz *= 0.45;
          c.spin *= 0.35;
          if (c.stage === 3 || Math.abs(c.vy) < 0.4) {
            c.stage = 3;
            c.rx = Math.PI / 2;
            c.t = 0;
          }
        }
      } else if (c.t > this.rest) {
        c.y -= dt * 0.25;
        if (c.t > this.rest + SINK) {
          c.alive = false;
          continue;
        }
      }
      this.q.setFromEuler(this.e.set(c.rx, 0, c.rz));
      // 弹链节：扁一点、宽一点的小片
      if (c.link) this.sc.set(c.s * 1.5, c.s * 0.45, c.s * 1.5);
      else this.sc.setScalar(c.s);
      this.mesh.setColorAt(n, c.link ? LINK : BRASS);
      this.mesh.setMatrixAt(n++, this.m.compose(this.p.set(c.x, c.y, c.z), this.q, this.sc));
    }
    this.mesh.count = n;
    if (n) {
      this.mesh.instanceMatrix.needsUpdate = true;
      this.mesh.instanceColor!.needsUpdate = true;
    }
  }

  clear(): void {
    for (const c of this.list) c.alive = false;
    this.mesh.count = 0;
  }

  dispose(): void {
    this.mesh.geometry.dispose();
    (this.mesh.material as THREE.Material).dispose();
    this.mesh.dispose();
  }
}
