import * as THREE from 'three';
import type { PartSpec } from '../GeoCache';
import { frustum, rect } from '../ModelKit';

export type HouseLook = 'cottage' | 'timber' | 'town' | 'brick';
export interface HouseStyle {
  wall: number;
  roof: number;
  trim: number;
  shutter: number;
  /** 外轮廓仍在原房屋的占地和六米屋脊内，只改变檐高与屋顶结构。 */
  eave: number;
  ridgeX: number;
  storeys: 1 | 2;
  timber?: boolean;
  gable?: number;
}

export const HOUSE_STYLES: Record<HouseLook | 'farm', HouseStyle> = {
  farm: { wall: 0xcfc6b2, roof: 0x7a3b2c, trim: 0x6a5e4c, shutter: 0x4a3626, eave: 3.6, ridgeX: 3.8, storeys: 1 },
  cottage: { wall: 0xb9b9a3, roof: 0x535a5b, trim: 0x888271, shutter: 0x4a5a47, eave: 3.4, ridgeX: 2.0, storeys: 1 },
  timber: { wall: 0xd2c4a4, roof: 0x754c38, trim: 0x514333, shutter: 0x485247, eave: 4.4, ridgeX: 3.8, storeys: 2, timber: true, gable: 0xc6b797 },
  town: { wall: 0xc4ad81, roof: 0x50575e, trim: 0xd3c8af, shutter: 0x43544e, eave: 4.7, ridgeX: 3.8, storeys: 2, gable: 0xc4ad81 },
  brick: { wall: 0x946e58, roof: 0x655d55, trim: 0xb6aa92, shutter: 0x535148, eave: 4.6, ridgeX: 2.5, storeys: 2 },
};

export function houseStyle(look?: string): HouseStyle {
  return HOUSE_STYLES[look as HouseLook] ?? HOUSE_STYLES.farm;
}

/** 墙面局部坐标中的门窗、窗套与木构；完整模型和断墙共用，缺口里不会留下悬空窗框。 */
export type HouseTrim = [number, number, number, number, number];
export function houseTrim(style: HouseStyle, face: number): HouseTrim[] {
  if (face > 3) return [];
  if (style === HOUSE_STYLES.farm) {
    return face === 0
      ? [[-.55, 0, .55, 2, 0x4a3626], [-2.95, 1.6, -1.85, 2.6, 0x2e3438], [1.85, 1.6, 2.95, 2.6, 0x2e3438]]
      : face === 2 ? [[-1.9, 1.6, -.9, 2.6, 0x2e3438], [.9, 1.6, 1.9, 2.6, 0x2e3438]] : [];
  }
  const width = face < 2 ? 3.5 : 2.8;
  const out: HouseTrim[] = [[-width, .4, width, .58, style.trim], [-width, style.eave - .18, width, style.eave, style.trim]];
  if (style.storeys === 2) out.push([-width, 2.6, width, 2.76, style.trim]);
  if (style.timber) {
    for (const x of [-width + .09, -1.1, 1.1, width - .09]) out.push([x - .08, .4, x + .08, style.eave, style.trim]);
  } else {
    for (const x of [-width + .1, width - .1]) out.push([x - .1, .4, x + .1, style.eave, style.trim]);
  }
  const ys = style.storeys === 2 ? [1.45, 3.55] : [2.05];
  for (const y of ys) for (const x of face < 2 ? [-2.35, 2.35] : [-1.4, 1.4]) {
    out.push([x - .62, y - .59, x + .62, y + .59, style.trim]);
    out.push([x - .49, y - .48, x + .49, y + .48, 0x303a3b]);
    out.push([x - .035, y - .48, x + .035, y + .48, style.trim]);
    out.push([x - .49, y - .035, x + .49, y + .035, style.trim]);
    if (style.storeys === 1 || style.timber) {
      out.push([x - .87, y - .48, x - .65, y + .48, style.shutter], [x + .65, y - .48, x + .87, y + .48, style.shutter]);
    }
  }
  if (face === 0) out.push([-.73, .4, .73, 2.3, style.trim], [-.58, .4, .58, 2.12, 0x4a4031]);
  return out;
}

export function styledHouseParts(look: HouseLook): PartSpec[] {
  const s = houseStyle(look);
  const parts: PartSpec[] = [
    { geo: new THREE.BoxGeometry(7, s.eave, 5.6), color: s.wall, pos: [0, s.eave / 2, 0] },
    { geo: new THREE.BoxGeometry(7.2, .4, 5.8), color: 0x6a5e4c, pos: [0, .2, 0] },
    { geo: frustum(rect(7.6, 6.2), rect(s.ridgeX * 2, .3), 6 - s.eave, s.eave), color: s.roof },
    { geo: new THREE.BoxGeometry(.7, 2.2, .7), color: 0x8a7b68, pos: [2.2, 5.2, .8] },
  ];
  for (let face = 0; face < 4; face++) {
    for (const [i, [x0, y0, x1, y1, color]] of houseTrim(s, face).entries()) {
      const u = (x0 + x1) / 2, y = (y0 + y1) / 2;
      // 后画的窗格比底色向外多半毫米，避免共面闪纹。
      const depth = .012 + i * .0005;
      const pos: [number, number, number] = face === 0 ? [u, y, 2.8 + depth]
        : face === 1 ? [-u, y, -2.8 - depth] : face === 2 ? [3.5 + depth, y, -u] : [-3.5 - depth, y, u];
      const angle = [0, Math.PI, Math.PI / 2, -Math.PI / 2][face];
      parts.push({ geo: new THREE.PlaneGeometry(x1 - x0, y1 - y0), color, pos, rot: [0, angle, 0] });
    }
  }
  if (s.gable !== undefined) for (const sign of [-1, 1]) {
    const p = [
      [sign * 3.801, s.eave, -sign * 3.1], [sign * 3.801, s.eave, sign * 3.1],
      [sign * 3.801, 6, sign * .15], [sign * 3.801, 6, -sign * .15],
    ];
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute([p[0], p[2], p[1], p[0], p[3], p[2]].flat(), 3));
    g.computeVertexNormals();
    parts.push({ geo: g, color: s.gable });
  }
  return parts;
}

export function houseRoofHeight(style: HouseStyle, x: number, z: number): number {
  const side = Math.max(0, (Math.abs(z) - .15) / 2.95);
  const hip = style.ridgeX < 3.8 ? Math.max(0, (Math.abs(x) - style.ridgeX) / (3.8 - style.ridgeX)) : 0;
  return 6 - Math.min(1, Math.max(side, hip)) * (6 - style.eave);
}
