/**
 * 提示跟着设置走（T055，D1 × D5 对齐第 3 批第 8 条）：操作说明按「电脑 / 触屏、经典 / 双摇杆、自动开火、究极自动」拼，两套界面共用。
 * 用到的地方：底部操作提示（#hint / 画布 HINT）、开始界面三条提示、六件究极第一次待发的提示条、合成卡提示行、核心格的槽位详情。
 * 电脑 = 有鼠标（pointer: fine，和 TankInput 认悬停瞄准同一条）：鼠标不认双摇杆，照经典 + 方向键走位写。
 * 文案规矩见 AGENTS.md：提示条 ≤ 16 字、卡面提示行 ≤ 20 字，不出现英文字母和忌讳字
 */
import { padBinding, PAD_NAMES } from '../core/controlBindings';

export interface CtrlMode {
  mouse: boolean;
  gamepad?: boolean;
  twin: boolean;
  autoFire: boolean;
  ultAuto: boolean;
  /** 现在的流派是激光（按住出光）；开始界面三条提示各流派都写，不看它 */
  laser: boolean;
  /** 现在的流派是火神（按住连射，T089） */
  vulcan?: boolean;
}

/** 底部操作提示（开局显示，碰过操作就淡出） */
export function ctrlHint(m: CtrlMode): string {
  if (m.gamepad) return padBattleHint(!!(m.laser || m.vulcan));
  if (m.vulcan) {
    if (m.mouse) return m.autoFire ? '方向键走位 · 有敌人自动开火' : '方向键走位 · 按住左键一直打';
    if (m.twin) return m.autoFire ? '左手走位 · 自动开火 · 右手接管' : '左手走位 · 右手按住一直打';
    return m.autoFire ? '拖动走位 · 有敌人自动开火' : '拖动走位 · 按住开火';
  }
  if (m.mouse) return m.laser ? (m.autoFire ? '方向键走位 · 能量满了自动出光' : '方向键走位 · 按住左键出光') : m.autoFire ? '方向键走位 · 自动开炮' : '方向键走位 · 鼠标点哪打哪';
  if (m.twin) return m.laser ? '左手走位 · 右手按住扫射' : m.autoFire ? '左手走位 · 右手瞄准 · 自动开炮' : '左手走位 · 右手瞄准 · 松手开炮';
  return m.laser ? (m.autoFire ? '拖动走位 · 能量满了自动出光' : '拖动走位 · 按住出光') : m.autoFire ? '拖动走位 · 自动开炮' : '拖动走位 · 点一下开炮';
}

/** 开始界面三条提示：[金色两三个字, 后面的说明] */
export function titleTips(m: CtrlMode): [string, string][] {
  if (m.gamepad) return [[padBinding('move') === 0 ? '左杆' : '右杆', '走位'], [padBinding('aim') === 0 ? '左杆' : '右杆', '瞄准'], [PAD_NAMES[padBinding('fire')], '开炮，激光和火神按住打']];
  const auto: [string, string][] = [['自动开火', '装填好就开炮'], ['激光', '能量满了自动出光']];
  if (m.mouse) return [['方向键', '走位'], ...(m.autoFire ? auto : ([['鼠标点一下', '开炮，点哪打哪'], ['按住左键', '激光持续输出']] as [string, string][]))];
  if (m.twin) return [['左手拖动', '走位'], ['右手拖动', m.autoFire ? '瞄准，自动开炮' : '瞄准，松手开炮'], ['右手按住', '激光持续输出']];
  return [['拖动', '走位'], ...(m.autoFire ? auto : ([['点一下', '开炮，点哪打哪'], ['按住', '激光持续输出']] as [string, string][]))];
}

/** 第一次拦路时说明怎么前后挪；两套界面共用。 */
export function holdHow(m: Pick<CtrlMode, 'mouse' | 'twin' | 'gamepad'>): string {
  if (m.gamepad) return `${padBinding('move') === 0 ? '左杆' : '右杆'}走位，回中停稳`;
  return m.mouse ? '方向键走位，松开停稳' : m.twin ? '左手上下拖能前后挪' : '上下拖也能前后挪';
}

/** 究极怎么放（待发提示条 / 合成卡提示行 / 核心格详情共用一个说法）：自动 = 敌人够多自己放；手动 = 点究极键（电脑多一个右键） */
export function ultHow(m: Pick<CtrlMode, 'mouse' | 'ultAuto' | 'gamepad'>): string {
  return m.ultAuto ? '敌人够多自动放' : m.gamepad ? `${PAD_NAMES[padBinding('ult')]}发射究极` : m.mouse ? '右键或点究极键发射' : '点究极键发射';
}

export function padBattleHint(hold = false): string {
  return `${padBinding('move') === 0 ? '左杆' : '右杆'}走位 · ${PAD_NAMES[padBinding('fire')]}${hold ? '按住打' : '开炮'}`;
}
