import * as THREE from 'three';
import { sharedGrime } from '../render/sharedTextures';

/** 加细景物的表面类别（顶点属性 surf）；0 = 原来的顶点色涂装，不加纹理 */
export const SURF = { plain: 0, leaf: 1, bark: 2, plaster: 3, roof: 4, brick: 5, wood: 6, stone: 7, glass: 8 } as const;

/**
 * T184 加细景物共用的一套材质（建筑 / 树木 / 草丛，一个着色器程序）：
 * 仍是顶点色 × 实例色（烧焦、熏黑照旧），在此之上按 surf 叠程序纹理——叶簇明暗与上亮下暗、树皮竖纹、灰泥污渍与墙根泥、
 * 瓦片行列、砖缝、木纹；同一张高度场给一点凹凸，远处淡出防闪。
 * 噪声按世界坐标先取模 256 米、哈希不用 sin（同 burntSteel 的教训：手机 GPU 上大参数 sin 塌成常数）
 */
let mat: THREE.MeshStandardMaterial | null = null;
export function sceneryMaterial(): THREE.MeshStandardMaterial {
  if (mat) return mat;
  mat = new THREE.MeshStandardMaterial({ vertexColors: true, map: sharedGrime(), roughness: 0.88, metalness: 0.04 });
  mat.name = 'scenery-rich';
  mat.onBeforeCompile = (shader) => {
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', `#include <common>
attribute float surf;
varying float vSurf;
varying vec3 vSp;
varying vec3 vSl;
varying vec3 vSn;`)
      .replace('#include <worldpos_vertex>', `#include <worldpos_vertex>
vec4 sWp = vec4(transformed, 1.0);
vec3 sN = objectNormal;
#ifdef USE_INSTANCING
sWp = instanceMatrix * sWp;
sN = mat3(instanceMatrix) * sN;
#endif
sWp = modelMatrix * sWp;
vSp = mod(sWp.xyz, 256.0);
vSl = transformed;
vSn = normalize(mat3(modelMatrix) * sN);
vSurf = surf;`);
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', `#include <common>
varying float vSurf;
varying vec3 vSp;
varying vec3 vSl;
varying vec3 vSn;
float sHash(vec3 p) { p = fract(p * 0.1031); p += dot(p, p.zyx + 31.32); return fract((p.x + p.y) * p.z); }
float sNoise(vec3 p) {
  vec3 i = floor(p); vec3 f = fract(p); f = f * f * (3.0 - 2.0 * f);
  return mix(mix(mix(sHash(i), sHash(i + vec3(1,0,0)), f.x), mix(sHash(i + vec3(0,1,0)), sHash(i + vec3(1,1,0)), f.x), f.y),
             mix(mix(sHash(i + vec3(0,0,1)), sHash(i + vec3(1,0,1)), f.x), mix(sHash(i + vec3(0,1,1)), sHash(i + vec3(1,1,1)), f.x), f.y), f.z);
}
vec3 sPerturb(vec3 pos, vec3 n, vec2 dh, float face) {
  vec3 sx = normalize(dFdx(pos)); vec3 sy = normalize(dFdy(pos));
  vec3 r1 = cross(sy, n); vec3 r2 = cross(n, sx);
  float det = dot(sx, r1) * face;
  vec3 grad = sign(det) * (dh.x * r1 + dh.y * r2);
  return normalize(abs(det) * n - grad);
}
/** 行列砖 / 瓦：返回 (缝 0..1, 块号)；按屏幕导数淡出，远处不出摩尔纹 */
vec2 sCourse(float u, float v, float w, float h, float gap) {
  float row = v / h; float col = u / w + mod(floor(row), 2.0) * 0.5;
  vec2 f = fract(vec2(col, row));
  vec2 aa = clamp(fwidth(vec2(col, row)) * 2.0, 0.0, 1.0);
  float joint = max((1.0 - smoothstep(0.0, gap * 1.6, f.y)) * (1.0 - aa.y), (1.0 - smoothstep(0.0, gap, f.x)) * (1.0 - aa.x));
  return vec2(joint, sHash(vec3(floor(col), floor(row), 7.0)));
}`)
      .replace('#include <normal_fragment_maps>', `#include <normal_fragment_maps>
float sk = floor(vSurf + 0.5);
if (sk > 0.5) {
  vec3 p = vSp;
  float sh = 0.0;
  float sr = roughnessFactor;
  vec3 st = vec3(1.0);
  float up = clamp(vSn.y * 0.5 + 0.5, 0.0, 1.0);
  if (sk < 1.5) {
    float n1 = sNoise(p * 1.6), n2 = sNoise(p * 5.7 + 7.1);
    sh = n1 * 0.45 + n2 * 0.55;
    st *= 0.7 + 0.52 * sh;
    st *= mix(0.68, 1.12, up);
    st = mix(st, st * vec3(1.12, 1.08, 0.78), smoothstep(0.62, 0.85, n1) * 0.7);
    sr = 0.9;
  } else if (sk < 2.5) {
    float n = sNoise(vec3(p.x * 9.0, p.y * 1.1, p.z * 9.0)), m = sNoise(p * 2.7);
    sh = n;
    st *= (0.68 + 0.5 * n) * (0.86 + 0.26 * m);
    sr = 0.95;
  } else if (sk < 3.5) {
    float stain = sNoise(p * 0.55), sp = sNoise(p * 8.5);
    float streak = sNoise(vec3(p.x * 2.4 + p.z * 2.4, p.y * 0.22, 0.0));
    sh = sp * 0.35;
    st *= (0.86 + 0.24 * stain) * (0.95 + 0.08 * sp);
    st *= 1.0 - 0.16 * smoothstep(0.55, 0.85, streak);
    st *= mix(0.6, 1.0, smoothstep(0.35, 1.5, vSl.y));
    sr = 0.94;
  } else if (sk < 4.5) {
    vec2 c = sCourse(vSl.x + vSl.z, vSl.y, 0.42, 0.24, 0.16);
    sh = (1.0 - c.x) * 0.6;
    st *= (0.8 + 0.32 * c.y) * (1.0 - 0.35 * c.x);
    st *= 0.84 + 0.26 * sNoise(p * 0.7);
    st = mix(st, st * vec3(0.82, 0.95, 0.7), smoothstep(0.62, 0.8, sNoise(p * 0.45 + 3.0)) * 0.5);
    sr = 0.78;
  } else if (sk < 5.5) {
    vec2 c = sCourse(vSl.x + vSl.z, vSl.y, 0.5, 0.17, 0.12);
    sh = (1.0 - c.x) * 0.7;
    st *= mix(0.82 + 0.3 * c.y, 1.25, c.x * 0.55);
    st *= 0.86 + 0.22 * sNoise(p * 0.9);
    st *= mix(0.65, 1.0, smoothstep(0.2, 1.2, vSl.y));
    sr = 0.92;
  } else if (sk < 6.5) {
    float g = sNoise(vec3(p.x * 1.6 + p.z * 1.6, p.y * 16.0, 1.0));
    sh = g * 0.6;
    st *= 0.78 + 0.36 * g;
    sr = 0.88;
  } else if (sk < 7.5) {
    float n = sNoise(p * 3.1) * 0.6 + sNoise(p * 11.0) * 0.4;
    sh = n;
    st *= 0.78 + 0.4 * n;
    st *= mix(0.72, 1.06, up);
    sr = 0.97;
  } else {
    st *= 0.9 + 0.2 * sNoise(p * 1.3);
    sr = 0.16;
  }
  diffuseColor.rgb *= st;
  roughnessFactor = sr;
  float fade = 1.0 - smoothstep(35.0, 95.0, length(vViewPosition));
  vec2 dh = vec2(dFdx(sh), dFdy(sh)) * 0.9 * fade;
  normal = sPerturb(-vViewPosition, normal, dh, faceDirection);
}`);
  };
  return mat;
}

export function disposeSceneryMaterial(): void {
  mat?.dispose();
  mat = null;
}
