import * as THREE from 'three';
import { MAT } from '../../assets/materials';
import { heavyBomberGeo, nukeGeo } from '../../assets/models/weapons';
import type { Enemy, EnemyController } from '../../entities/Enemy';
import { ultHalf } from '../defs';
import { UltBase, type UltAim, type UltContext, type UltPreview } from './common';

const rand = (a: number, b: number) => a + Math.random() * (b - a);

/**
 * 「核弹」数值表（T013 制作人定稿：固定全屏 999；冷却在 FUSIONS.nuke.cd 里固定 40 秒（T066 翻倍）；场景半径都要乘 A = 爆破药半效倍率）：
 * 按下后 delay 秒起爆，dropAt 秒时轰炸机在爆心上空投下伞降核弹；爆心 = 坦克前方 dist 米 + 车速 × delay（起爆时坦克正好在爆心后方 dist 米），
 * 首领战对准首领核心部件 delay 秒后的预测位置，近于 bossMin 米就推到坦克前方 bossMin 米。
 * 伤害：起爆那一刻屏幕上的每个敌人各受 dmg 点固定伤害——不分远近、不吃护甲克制 / 首领瘫痪加成 / 改装件、不暴击、不封顶；
 * 首领作为一个整体只结算一次（T014-1，每发总共 dmg，扣在核心部件上），部件不再各吃一份；
 * 扛得住的从爆心往外推 knock（首领部件不动）。屏幕外的敌人不受影响。
 * 场景：r 米内路障按力度 propForce、fireball 米内的残骸直接炸碎；冲击环（ring 米/秒往外扫）扫过 r 米时 shove 米内的路障再按 propOuter 推一次、shellR 米内的车烧成空壳；
 * barrelR 米内的油桶由近到远每 barrelGap 秒引爆一个；实体弹坑 pit（T014-3：坑口半径 r、深 d、坑沿高 rim、抛土到 out，坑里烧焦、坑外放射状抛土和焦痕都在地面着色器里画），
 * 爆心 6～10 米的圆环上 fires 处地面火（半径 fireR、fireT 秒，只有火苗不伤人，落在坑底）；坑底 smolder 处闷烧的细烟（22～28 秒，余烟）；
 * 一次最多 maxBreak 辆车 / 块残骸走完整的碎裂流程。
 * 路边景物（T009 第 8 节，SceneryDamage.nuke，跟着冲击环走）：fireball 内汽化、r 内全部到终态、r～shove 放射状倒伏、scnIgnite 米内植被和木头全部点燃；
 * 上面那几次 smash 不再碰景物。
 * 演出：白闪 flash、泛光 bloom、顿帧 freeze、震屏 shake（起爆 / 冲击环扫到 40 米）、余震 rumble [强度, 秒]。
 * T057（制作人「蘑菇云太小了，投放轰炸的飞机飞的也太低」，以下都只是演出，伤害 / 起爆时刻 / 起爆那一刻的镜头都没动）：
 * - 轰炸机 bomber：四发战略轰炸机（heavyBomberGeo × scale），从坦克身后 from 米、离地 alt 米飞来，dropAt 秒在爆心前 lead 米投弹（核弹往前、往下落到爆心），
 *   之后同样的速度往前、每秒爬高 climb 米飞出画面（exit 秒收掉）；四台发动机拖白色尾迹（每 trail 秒一节光条，留 trailLife 秒）；核弹放大 bomb 倍（高处看得见）
 * - 镜头 cam：按下就压低、抬头看天（sky：机位 tilt、再仰 lift 弧度，保持 hold 秒；轰炸机从头顶压过去，投弹那一刻正好在画面中间）→
 *   投弹时放回 ▲▲（tilt −1）跟着核弹落下，起爆那一刻和原来一样（「屏幕上的敌人」不变）→
 *   起爆后 rise.at 秒再压低抬头看蘑菇云升起来（rise），back 秒缓回；冲击环扫到坦克时镜头一缩一放 kick + 狂风声
 * - 起爆：慢放 slow [秒, 倍数]；核爆声晚 boom 秒（先见光后闻声）；蘑菇云 cloud（宽 s × 高 tall，rise 秒升到顶，烟团寿命 × linger，发射密度 n / 低画质 nLow）；
 *   火球的橙光照亮周围 glow 秒；氛围 mood：起爆时暖橙 + 尘霾（hit），haze 秒后退成褐色尘霾（haze），calm 秒后回到平时；
 *   fall 秒起飘灰 / 火星（坦克周围 r 米、top 米高往下，dur 秒，每秒 rate 片，ember 成是火星）；end 秒后演出结束
 */
export const NUKE = {
  delay: 3.4, dropAt: 2.0, dist: 58, bossMin: 30,
  dmg: 999, knock: 12,
  r: 27, fireball: 13.5, shove: 46, ring: 40, propForce: 30, propOuter: 8, shellR: 40, barrelR: 28, barrelGap: 0.14, scnIgnite: 40,
  fires: 8, fireR: 4, fireT: 8, pit: { r: 16, d: 4, rim: 1.6, out: 30 }, smolder: 5, maxBreak: 6,
  bomber: { enter: 0.2, scale: 0.75, alt: 72, from: 20, lead: 24, climb: 9, exit: 5.2, trail: 0.08, trailLife: 2.4, bomb: 1.8 },
  flash: 0.55, bloom: 1.6, freeze: 0.12, shake: [0.6, 1.1], rumble: [0.2, 2.5], slow: [0.55, 0.38], boom: 0.35, kick: 0.7,
  cam: {
    tilt: -1,
    sky: { tilt: -1.35, lift: 0.72, hold: 1.9, inT: 0.9 },
    rise: { at: 0.3, tilt: -1.5, lift: 0.32, hold: 3.4, inT: 1.3, back: 1.2 },
  },
  cloud: { s: 2, tall: 2.3, rise: 4.2, linger: 1.9, n: 0.42, nLow: 0.26, stem: 0.65 },
  glow: 2.2,
  mood: {
    sky: { storm: 0.75, skyDark: 0x6e8090, skyLite: 0xf4f6f6 },
    hit: { light: 0.5, exposure: 1.02, tint: 0xffb070, tintK: 0.6, fog: 0x4a3426, fogK: 0.62, shadow: 0.7, storm: 0.85, skyDark: 0x2a1c14, skyLite: 0x6a4a34 },
    haze: { light: 0.7, exposure: 0.96, tint: 0xd8a878, tintK: 0.35, fog: 0x5a4a3e, fogK: 0.5, shadow: 0.8, storm: 0.6, skyDark: 0x3a3029, skyLite: 0x7a6a5c },
    at: [2.5, 7.5], fade: [0.12, 1.5, 2.5],
  },
  fall: { at: 2.5, dur: 9, r: 38, top: 32, rate: 50, ember: 0.35 },
  end: 9.5,
};

/** 轰炸机的漆：和 MAT.painted 一样，加一点自发光（从下往上看机腹背光，不然是一块纯黑的剪纸） */
let bomberMat: THREE.MeshStandardMaterial | null = null;

/** 四台发动机在机身上的位置（heavyBomberGeo 的局部坐标，尾迹从这里拖出来） */
const ENGINES: [number, number, number][] = [[-0.6, -0.15, -12.5], [-0.6, -0.15, -6], [-0.6, -0.15, 6], [-0.6, -0.15, 12.5]];

/** 核弹 · 战略核轰炸（主炮 + 迫击炮★ + 空袭★）：呼叫重型轰炸机在前方投下伞降核弹，起爆瞬间屏幕上的每个敌人各受 999 点伤害（首领整体总共 999），用来清场 */
export class NukeUlt extends UltBase {
  /** 本次事件已经过的秒数；-1 = 不在事件中 */
  private t = -1;
  private detonated = false;
  private bx = 0;
  private bz = 0;
  /** 按下那一刻坦克的位置（轰炸机航线） */
  private sx = 0;
  private sz = 0;
  private bomber: THREE.Mesh | null = null;
  private bomb: THREE.Mesh | null = null;
  private overhead = false;
  private outer = false;
  private aftershock = false;
  /** 演出各段放过没有：冲击环扫到坦克、碎裂名额放开、尘霾、回到平时、飘灰、起爆后抬头 */
  private kicked = false;
  private freed = false;
  private hazed = false;
  private calmed = false;
  private fell = false;
  private rose = false;
  /** 氛围改过（被 clear 打断时下一帧退回平时） */
  private moody = false;
  private trailT = 0;
  private readonly trails: THREE.Vector3[] = ENGINES.map(() => new THREE.Vector3());
  private readonly v = new THREE.Vector3();
  private readonly chain: [number, number][] = [];
  private chainT = 0;
  /** 首领核心部件的速度估计（预测 delay 秒后的位置） */
  private core: Enemy | null = null;
  private coreX = 0;
  private coreZ = 0;
  private coreVx = 0;
  private coreVz = 0;

  protected override activeLabel(): string {
    return '已呼叫';
  }

  /** 现在按下会落在哪 */
  private aimPoint(ctx: UltContext): { x: number; z: number } {
    const T = NUKE;
    const P = ctx.tank.group.position;
    const ahead = P.z - ctx.speed * T.delay;
    const core = this.core?.alive ? this.core : null;
    if (core) {
      const x = core.group.position.x + this.coreVx * T.delay;
      const z = core.group.position.z + this.coreVz * T.delay;
      return { x, z: Math.min(z, ahead - T.bossMin) };
    }
    return { x: 0, z: ahead - T.dist };
  }

  preview(ctx: UltContext, _aim: UltAim): UltPreview | null {
    const p = this.aimPoint(ctx);
    return { x: p.x, z: p.z, r: NUKE.r * ultHalf(ctx.mods.area) };
  }

  protected fire(ctx: UltContext): void {
    const T = NUKE;
    const S = T.cam.sky;
    const P = ctx.tank.group.position;
    const p = this.aimPoint(ctx);
    this.clear();
    this.t = 0;
    this.bx = p.x;
    this.bz = p.z;
    this.sx = P.x;
    this.sz = P.z;
    this.active = T.delay;
    // 防空警报 + 无线电；镜头压低抬头看天（轰炸机从头顶飞过去）
    ctx.audio.play('radio');
    ctx.audio.play('airRaid', 0.8);
    ctx.cinema(S.tilt, T.dropAt - 0.1, 0.6);
    ctx.lookUp(S.lift, S.hold, 0.8, S.inT);
    // 天上浮起一层高空云（抬头看得到）
    this.moody = true;
    ctx.mood(T.mood.sky, 0.8);
  }

  protected step(ctx: UltContext): void {
    this.trackCore(ctx);
    if (this.t < 0) {
      // 被 clear 打断（读档 / 重开 / 调试）：氛围和抬头退回平时
      if (this.moody) {
        this.moody = false;
        ctx.mood(null, 0.5);
        ctx.lookUp(0, 0, 0.6);
      }
      return;
    }
    const T = NUKE;
    const B = T.bomber;
    const dt = ctx.dt;
    this.t += dt;
    const t = this.t;
    if (!this.detonated) this.active = Math.max(1e-3, T.delay - t);

    // 四发战略轰炸机：从坦克身后高空飞来，飞到爆心上空投弹，再往前爬高飞出画面
    if (t >= B.enter && t < B.exit) {
      if (!this.bomber) {
        bomberMat ??= Object.assign(MAT.painted.clone(), { emissive: new THREE.Color(0x2c3236) });
        this.bomber = new THREE.Mesh(heavyBomberGeo(ctx.geo), bomberMat);
        this.bomber.scale.setScalar(B.scale);
        this.bomber.castShadow = true;
        ctx.scene.add(this.bomber);
        ctx.audio.play('bomber');
        this.flyBomber(t);
        ENGINES.forEach((e, i) => this.trails[i].set(...e).applyMatrix4(this.bomber!.matrixWorld));
      }
      this.flyBomber(t);
      // 起爆以后飞机已经很远了，不再拖尾迹（剩下的自己淡掉）
      if (!this.detonated) this.contrail(ctx, dt);
      // 机群从头顶压过去：一阵低频余震
      if (!this.overhead && t >= 0.6) {
        this.overhead = true;
        ctx.rumble(0.12, 1.4);
      }
    } else if (this.bomber && t >= B.exit) {
      this.bomber.removeFromParent();
      this.bomber = null;
    }

    // 投弹：核弹从机腹落下，爆心出现我方浅黄落点圈（T130，红只给敌方）；镜头放回 ▲▲、跟着核弹往下看（起爆那一刻和原来一样）
    if (!this.bomb && !this.detonated && t >= T.dropAt) {
      this.bomb = new THREE.Mesh(nukeGeo(ctx.geo), MAT.painted);
      this.bomb.scale.setScalar(B.bomb);
      ctx.scene.add(this.bomb);
      const R = T.r * ultHalf(ctx.mods.area);
      ctx.hazards.marker(this.bx, this.bz, R, T.delay - T.dropAt, 'self');
      // 镜头按真实时间走、起爆后有慢放：保持得比「起爆后 rise.at 秒」长一截，接上后面的抬头
      ctx.cinema(T.cam.tilt, T.delay - T.dropAt + T.cam.rise.at + 1.5, 0.6);
      ctx.lookUp(0, 0, 0.45);
      ctx.audio.play('fall');
    }
    if (this.bomb) {
      // 从机腹往前、往下落到爆心：越落越快，前冲越来越慢，微微晃
      const k = Math.min(1, (t - T.dropAt) / (T.delay - T.dropAt));
      const y0 = B.alt - 3;
      this.bomb.position.set(this.bx + Math.sin(t * 2.1) * 0.4, y0 + (1.3 - y0) * k ** 1.6, this.bz + B.lead * (1 - k) ** 1.5);
      this.bomb.rotation.set(Math.sin(t * 2.7) * 0.06 - 0.3 * (1 - k), t * 0.6, Math.sin(t * 3.1) * 0.08);
    }

    if (!this.detonated && t >= T.delay) this.detonate(ctx);
    if (!this.detonated) return;

    const A = ultHalf(ctx.mods.area);
    const since = t - T.delay;
    // 冲击环以 ring 米/秒往外扫（只管场景和震屏，伤害起爆那一刻已经结算完）
    const front = since * T.ring;
    // 冲击环扫过 r 米：外圈路障再推一次、车烧成空壳，残骸推开
    if (!this.outer && front >= T.r * A) {
      this.outer = true;
      ctx.smash(this.bx, this.bz, T.shove * A, T.propOuter, false, false);
      ctx.ignite(this.bx, this.bz, T.shellR * A);
    }
    // 冲击环扫到 40 米：第二下震屏，之后低频余震
    if (!this.aftershock && front >= 40) {
      this.aftershock = true;
      ctx.shake(T.shake[1]);
      ctx.rumble(T.rumble[0], T.rumble[1]);
    }
    // 冲击环扫到坦克：镜头一缩一放 + 狂风声（T057）
    const P = ctx.tank.group.position;
    if (!this.kicked && front >= Math.hypot(P.x - this.bx, P.z - this.bz)) {
      this.kicked = true;
      ctx.kick(T.kick);
      ctx.audio.play('gust', 0.9);
    }
    // 起爆后再抬头看蘑菇云升起来
    const R = T.cam.rise;
    if (!this.rose && since >= R.at) {
      this.rose = true;
      ctx.cinema(R.tilt, R.hold + 0.2, R.back);
      ctx.lookUp(R.lift, R.hold, R.back, R.inT);
    }
    // 火球的橙光照亮爆心周围（一直续着，慢慢退）
    if (since < T.glow) ctx.fx.flash(this.bx, ctx.fx.groundAt(this.bx, this.bz) + 14, this.bz, 8000 * (1 - since / T.glow));
    // 余韵：尘霾、飘灰、回到平时
    const M = T.mood;
    if (!this.hazed && since >= M.at[0]) {
      this.hazed = true;
      ctx.mood(M.haze, M.fade[1]);
    }
    if (!this.fell && since >= T.fall.at) {
      this.fell = true;
      const F = T.fall;
      ctx.fx.fallout(P.x, P.z - 10, F.r, F.top, F.dur, ctx.quality === 'low' ? F.rate * 0.6 : F.rate, F.ember);
    }
    if (!this.calmed && since >= M.at[1]) {
      this.calmed = true;
      this.moody = false;
      ctx.mood(null, M.fade[2]);
    }
    // 油桶由近到远一串二次爆炸
    if (this.chain.length) {
      this.chainT -= dt;
      if (this.chainT <= 0) {
        this.chainT = T.barrelGap;
        const [x, z] = this.chain.shift()!;
        ctx.detonate(x, z);
      }
    }
    // 碎裂名额 / 景物碎屑的事件限额放到起爆后 3.2 秒（景物最后几棵树落地、塌房扬尘也算在这次事件里）
    if (!this.freed && since > 3.2 && this.chain.length === 0) {
      this.freed = true;
      ctx.breaks(Infinity);
    }
    if (this.freed && since > T.end && !this.bomber) this.t = -1;
  }

  /** 轰炸机航线：enter 秒在坦克身后 from 米、离地 alt 米 → dropAt 秒到爆心前 lead 米（投弹）→ 之后同样的速度往前飞、每秒爬高 climb 米 */
  private flyBomber(t: number): void {
    const T = NUKE;
    const B = T.bomber;
    const o = this.bomber!;
    const z0 = this.sz + B.from;
    const z1 = this.bz + B.lead;
    const v = (z0 - z1) / (T.dropAt - B.enter);
    let x: number;
    let y: number;
    let z: number;
    let pitch = 0.04;
    let bank = 0;
    if (t < T.dropAt) {
      const k = (t - B.enter) / (T.dropAt - B.enter);
      const e = k * k * (3 - 2 * k);
      z = z0 + (z1 - z0) * k;
      x = this.sx + (this.bx - this.sx) * e;
      y = B.alt;
      bank = (this.bx - this.sx) * 0.01 * Math.sin(k * Math.PI);
    } else {
      const k = t - T.dropAt;
      x = this.bx;
      z = z1 - v * k;
      y = B.alt + B.climb * k;
      pitch = 0.1;
    }
    o.position.set(x, y, z);
    // 机头（模型 +X）转到 -Z
    o.rotation.set(bank, Math.PI / 2, pitch, 'YXZ');
    o.updateMatrixWorld();
  }

  /** 四道白色尾迹：每 trail 秒从上一节的终点接到发动机现在的位置（白芯 + 一层更宽的淡白），留 trailLife 秒 */
  private contrail(ctx: UltContext, dt: number): void {
    const B = NUKE.bomber;
    this.trailT -= dt;
    if (this.trailT > 0) return;
    this.trailT = B.trail;
    ENGINES.forEach((e, i) => {
      const p = this.v.set(...e).applyMatrix4(this.bomber!.matrixWorld);
      const q = this.trails[i];
      ctx.streaks.add(q.x, q.y, q.z, p.x, p.y, p.z, 0.9, 0xf4f6f8, 0.28, B.trailLife, 2);
      ctx.streaks.add(q.x, q.y + 0.2, q.z, p.x, p.y + 0.2, p.z, 3, 0xdfe6ec, 0.08, B.trailLife * 0.8, 4);
      q.copy(p);
    });
  }

  /** 起爆：屏幕上的敌人各受一次固定伤害、火球内炸碎、场景、蘑菇云、屏幕演出 */
  private detonate(ctx: UltContext): void {
    const T = NUKE;
    const A = ultHalf(ctx.mods.area);
    const { bx: x, bz: z } = this;
    const contact = ctx.groundContact(x, z, T.pit.r * A);
    this.detonated = true;
    this.finish();
    this.bomb?.removeFromParent();
    this.bomb = null;
    ctx.breaks(T.maxBreak);
    // 屏幕上的每个敌人各受 dmg 点固定伤害，不分远近；扛得住的被往外推。
    // 首领（T014-1 制作人：「首领总共掉 999」）作为一个整体只结算一次：只要有部件在屏幕上，就在首领本体（核心部件）上扣一次 dmg，部件不再各吃一份
    const bosses = new Set<EnemyController>();
    for (const e of ctx.screenFoes()) {
      const boss = e.controller;
      if (boss) {
        if (bosses.has(boss)) continue;
        bosses.add(boss);
      }
      const target = boss ? (boss.coreEnemy ?? e) : e;
      if (target.alive) ctx.damage(target, T.dmg, x, z, { type: 'blast', knock: T.knock, ult: true, fixed: true });
    }
    // 火球里被炸毁的车辆不留残骸；r 米内的路障、掩体、残骸按力度 propForce 结算（路边景物单独走 scenery.nuke）
    ctx.smash(x, z, T.fireball * A, T.propForce, true, false);
    ctx.smash(x, z, T.r * A, T.propForce, false, false);
    ctx.scenery.nuke(x, z, { fireball: T.fireball * A, r: T.r * A, shove: T.shove * A, ignite: T.scnIgnite * A });
    this.chain.push(...ctx.barrels(x, z, T.barrelR * A));
    this.chainT = T.barrelGap;
    // 地面：真的炸出一个大坑（口径 32 米、深 4 米、坑沿抛土环；原来 20 米的弹坑贴花 + 38 米焦痕由地面着色器的烧焦 / 放射状抛土代替）+ 一圈地面火（只有火苗）+ 不起火的黑烟柱
    ctx.dig(x, z, T.pit.r * A, T.pit.d, T.pit.rim, T.pit.out * A, 1, 4, contact);
    for (let i = 0; i < T.fires; i++) {
      const a = (i / T.fires) * Math.PI * 2 + rand(-0.3, 0.3);
      const rr = rand(6, 10) * A;
      ctx.hazards.fire(x + Math.cos(a) * rr, z + Math.sin(a) * rr, T.fireR, T.fireT, 0, 'player');
    }
    for (let i = 0; i < 3; i++) {
      const a = Math.random() * Math.PI * 2;
      ctx.fx.burn(x + Math.cos(a) * rand(8, 16) * A, z + Math.sin(a) * rand(8, 16) * A, 2.2, 14, false);
    }
    // 余烟：坑底几处闷烧的细烟，比黑烟柱多冒十来秒（开进坑里时还在冒）
    for (let i = 0; i < T.smolder; i++) {
      const a = (i / T.smolder) * Math.PI * 2 + rand(-0.4, 0.4);
      const rr = rand(0.15, 0.7) * T.pit.r * A;
      ctx.fx.burn(x + Math.cos(a) * rr, z + Math.sin(a) * rr, 1.1, rand(22, 28), false);
    }
    // 蘑菇云（T057：宽 2 × 高 2.3，云顶约 55 米、帽宽约 50 米、柱子细一些；少而大，低画质再少一些）
    const C = T.cloud;
    ctx.fx.mushroom(x, z, C.s, ctx.quality === 'high', { tall: C.tall, rise: C.rise, linger: C.linger, n: ctx.quality === 'low' ? C.nLow : C.n, stem: C.stem });
    ctx.flash(T.flash);
    ctx.pulse(T.bloom, 0.4);
    ctx.freeze(T.freeze);
    ctx.slowmo(T.slow[0], T.slow[1]);
    ctx.shake(T.shake[0]);
    // 先见光后闻声：核爆声晚一拍
    ctx.audio.play('nuke', 1, 1, T.boom);
    this.moody = true;
    ctx.mood(T.mood.hit, T.mood.fade[0]);
  }

  /** 首领核心部件的位置 / 速度（平滑），用来预测起爆时它在哪 */
  private trackCore(ctx: UltContext): void {
    const core = ctx.bossCore();
    if (!core) {
      this.core = null;
      return;
    }
    const p = core.group.position;
    if (core !== this.core || ctx.dt <= 0) {
      this.core = core;
      this.coreVx = this.coreVz = 0;
    } else {
      const k = Math.min(1, ctx.dt * 3);
      this.coreVx += ((p.x - this.coreX) / ctx.dt - this.coreVx) * k;
      this.coreVz += ((p.z - this.coreZ) / ctx.dt - this.coreVz) * k;
    }
    this.coreX = p.x;
    this.coreZ = p.z;
  }

  protected clear(): void {
    this.bomber?.removeFromParent();
    this.bomber = null;
    this.bomb?.removeFromParent();
    this.bomb = null;
    this.t = -1;
    this.detonated = false;
    this.overhead = false;
    this.outer = false;
    this.aftershock = false;
    this.kicked = this.freed = this.hazed = this.calmed = this.fell = this.rose = false;
    this.trailT = 0;
    this.chain.length = 0;
  }
}
