import type { UltView } from '../weapons/Arsenal';
import { type SuperModId } from '../weapons/defs';
import { icon } from './icons';
import { RAIL } from './rail';
import type { Overlay, Panel } from './canvas/Overlay';
import { button, armorMeter } from './canvas/widgets';
import { font, text, icon as paintIcon } from './canvas/paint';

export interface CoopHudView {
  label?: '一号' | '二号';
  readOnly?: boolean;
  hp: number;
  maxHp: number;
  shield: number;
  ult: UltView | null;
  supers: SuperModId[];
  next: number;
}
const TOOLS = RAIL.filter(c => c.seat === 2);
const LABEL: Record<string, string> = { ult: '究极', workshop: '改装', report: '战报' };
export type CoopHudAction = 'ult' | 'workshop' | 'report' | 'supers';

export class DomCoopHud {
  private el: HTMLElement | null = null;
  private key = '';
  constructor(private readonly act: (id: CoopHudAction) => void) {}
  set(v: CoopHudView | null): void {
    if (!v) { if (this.el) this.el.hidden = true; return; }
    if (!this.el) {
      this.el = document.createElement('section');
      this.el.id = 'coop-hud';
      this.el.setAttribute('aria-label', '二号战车');
      this.el.innerHTML = `<header><b>二号耐久</b><span data-hp></span></header><div class="coop-hp"><i></i></div><div class="coop-tools">${TOOLS.map(c => `<button type="button" data-coop-tool="${c.id}">${icon(c.id === 'workshop' ? 'category-mod' : c.id === 'ult' ? 'auto' : 'report')}<span>${LABEL[c.id]}</span></button>`).join('')}</div><button type="button" class="coop-supers" data-coop-tool="supers" aria-label="二号超级改装"></button>`;
      this.el.addEventListener('click', e => {
        const id = (e.target as HTMLElement).closest<HTMLElement>('[data-coop-tool]')?.dataset.coopTool;
        if (id) this.act(id as CoopHudAction);
      });
      document.body.append(this.el);
    }
    this.el.hidden = false;
    for (const button of this.el.querySelectorAll<HTMLButtonElement>('button')) button.disabled = !!v.readOnly;
    this.el.querySelector('header b')!.textContent = `${v.label ?? '二号'}耐久`;
    this.el.setAttribute('aria-label', `${v.label ?? '二号'}战车`);
    this.el.querySelector('[data-hp]')!.textContent = v.hp > 0 ? `${Math.ceil(v.hp)} / ${Math.ceil(v.maxHp)}` : '已被毁';
    (this.el.querySelector('.coop-hp i') as HTMLElement).style.width = `${Math.max(0, v.hp / v.maxHp * 100)}%`;
    const ult = this.el.querySelector<HTMLButtonElement>('[data-coop-tool="ult"]')!;
    ult.querySelector('span')!.textContent = v.ult ? v.ult.label : '未合成';
    ult.title = v.ult ? `${v.ult.name} · ${v.ult.label}` : '二号究极未合成';
    ult.disabled = !!v.readOnly || v.hp <= 0 || v.ult?.state !== 'ready';
    ult.classList.toggle('ready', v.ult?.state === 'ready');
    ult.style.setProperty('--charge', `${(v.ult?.progress ?? 0) * 100}%`);
    const key = v.supers.join(',');
    if (key !== this.key || !this.key) {
      this.key = key;
      this.el.querySelector('.coop-supers')!.innerHTML = v.supers.length ? v.supers.map(id => `<i>${icon(id)}</i>`).join('') : '<span>超级改装待选</span>';
    }
    this.el.querySelector<HTMLButtonElement>('[data-coop-tool="supers"]')!.title = `二号超级改装 ${v.supers.length} / 8`;
  }
}

/** 画布版独立摆放；不调用 DOM 的尺寸或样式。 */
export class CanvasCoopHud {
  private view: CoopHudView | null = null;
  private panel: Panel;
  constructor(private readonly ov: Overlay, private readonly act: (id: CoopHudAction) => void) {
    this.panel = ov.panel('coop-hud', 6, (g, w, h) => {
      const v = this.view;
      if (!v) return;
      g.fillStyle = '#1a2c27ed'; g.fillRect(0, 0, w, h);
      g.strokeStyle = '#879b86'; g.strokeRect(0.5, 0.5, w - 1, h - 1);
      g.font = font(12, 700);
      text(g, `${v.label ?? '二号'}耐久`, 8, 12, '#e0e8ca');
      text(g, v.hp > 0 ? `${Math.ceil(v.hp)} / ${Math.ceil(v.maxHp)}` : '已被毁', w - 8, 12, '#e0e8ca', 'right');
      armorMeter(g, 8, 24, w - 16, 5, Math.max(0, v.hp / v.maxHp), '#b5ca9a');
      const bw = (w - 20) / 3;
      if (!v.readOnly) TOOLS.forEach((tool, i) => button(g, 6 + i * (bw + 4), 35, bw, 44, 'outline', tool.id === 'ult' ? v.ult?.label ?? '未合成' : LABEL[tool.id], { size: 11 }));
      const sy = v.readOnly ? 42 : 92;
      v.supers.forEach((id, i) => paintIcon(g, id, 10 + i * (w - 20) / 8, sy, 17, '#d6b8ef'));
      if (!v.supers.length) { g.font = font(11); text(g, '超级改装待选', w / 2, sy + 8, '#c2afd6', 'center'); }
    });
    ov.onFrame(() => this.frame());
  }
  set(view: CoopHudView | null): void { this.view = view; this.panel.visible = !!view; this.panel.dirty = true; }
  private frame(): void {
    if (!this.view) return;
    const { W, H, insets } = this.ov;
    const wide = W >= 560 && W > H;
    const w = wide ? 230 : 182, h = this.view.readOnly ? 72 : 122;
    const x = W - insets.right - w - 14, y = wide ? H - insets.bottom - h - 122 : insets.top + 280;
    this.panel.place(x, y, w, h);
    this.ov.region({ id: 'coop-hud-block', z: 6, x, y, w, h, panel: this.panel });
    if (this.view.readOnly) return;
    const bw = (w - 20) / 3;
    TOOLS.forEach((tool, i) => this.ov.region({
      id: `coop-${tool.id}`, z: 7, x: x + 6 + i * (bw + 4), y: y + 35, w: bw, h: 44, panel: this.panel,
      tap: () => this.act(tool.id as CoopHudAction),
    }));
    this.ov.region({ id: 'coop-supers', z: 7, x, y: y + 80, w, h: 42, tap: () => this.act('supers'), panel: this.panel });
  }
}
