import * as THREE from 'three';
import { copyGeometry, type CrushPartRange, type PartSpec } from '../GeoCache';

/** 标记现有零件，不拆换 round-191 的完整模型。 */
export const CRUSH_PART = { skin: 0, frame: 1, roof: 2, glass: 3, wheel: 4, bed: 5, canopy: 6, board: 7, sack: 8, drum: 9, hoop: 10, straw: 11, masonry: 12 } as const;
export type CrushKind = 'truck' | 'car' | 'barrel' | 'wood' | 'sand' | 'hulk' | 'rubble' | 'hay';
export interface CrushShape {
  animated: THREE.BufferGeometry;
  settled: THREE.BufferGeometry;
  heights: readonly number[];
  key: string;
}

export function markCrush(parts: PartSpec[], role: number): PartSpec[] {
  for (const part of parts) part.crush = role;
  return parts;
}

const cache = new WeakMap<THREE.BufferGeometry, { base: THREE.BufferGeometry; parts: CrushPartRange[]; shapes: Map<string, CrushShape> }>();
const clamp = THREE.MathUtils.clamp;
const smooth = (x: number) => { const t = clamp(x, 0, 1); return t * t * (3 - 2 * t); };
const point = new THREE.Vector3();

/**
 * 第一次受压才补折点。只细分需折弯的长面，最多两轮；轮胎、玻璃、木板和沙袋整件移动。
 * 插值沿用原位置、法线、颜色和 UV，完好源几何始终不改。
 */
function prepare(source: THREE.BufferGeometry, fine = false): { base: THREE.BufferGeometry; parts: CrushPartRange[] } {
  const copy = copyGeometry(source);
  const ranges: CrushPartRange[] = source.userData.crushParts ?? [
    { start: 0, count: copy.getAttribute('position').count, role: CRUSH_PART.skin, pivot: [0, 0, 0] },
  ];
  const names = Object.keys(copy.attributes);
  const attrs = names.map(name => copy.getAttribute(name) as THREE.BufferAttribute);
  const pos = copy.getAttribute('position');
  const segments = new Uint8Array(pos.count / 3);
  const parts: CrushPartRange[] = [];
  const distance = (a: number, b: number) =>
    (pos.getX(a) - pos.getX(b)) ** 2 + (pos.getY(a) - pos.getY(b)) ** 2 + (pos.getZ(a) - pos.getZ(b)) ** 2;
  let count = 0;
  for (const part of ranges) {
    const rigid = part.role === CRUSH_PART.wheel || part.role === CRUSH_PART.glass ||
      part.role === CRUSH_PART.board || part.role === CRUSH_PART.sack || part.role === CRUSH_PART.hoop;
    const edge = part.role === CRUSH_PART.drum ? 0.35 : 1.1;
    const start = count;
    for (let i = part.start; i < part.start + part.count; i += 3) {
      const length2 = rigid ? 0 : Math.max(distance(i, i + 1), distance(i, i + 2), distance(i + 1, i + 2));
      const n = fine ? Math.min(LOCAL.maxSeg, Math.max(1, Math.ceil(Math.sqrt(length2) / LOCAL.edge)))
        : length2 > edge * edge * 4 ? 4 : length2 > edge * edge ? 2 : 1;
      segments[i / 3] = n;
      count += n * n * 3;
    }
    parts.push({ ...part, start, count: count - start });
  }
  const values = attrs.map(a => new Float32Array(count * a.itemSize));
  let vertex = 0;
  const emit = (i: number, u: number, v: number) => {
    const w = 1 - u - v;
    for (let j = 0; j < attrs.length; j++) {
      const a = attrs[j], size = a.itemSize, offset = i * size, dst = vertex * size;
      for (let k = 0; k < size; k++)
        values[j][dst + k] = a.array[offset + k] * w + a.array[offset + size + k] * u + a.array[offset + size * 2 + k] * v;
    }
    vertex++;
  };
  for (let i = 0; i < pos.count; i += 3) {
    const n = segments[i / 3];
    for (let u = 0; u < n; u++) for (let v = 0; v < n - u; v++) {
      emit(i, u / n, v / n); emit(i, (u + 1) / n, v / n); emit(i, u / n, (v + 1) / n);
      if (v < n - u - 1) {
        emit(i, (u + 1) / n, v / n); emit(i, (u + 1) / n, (v + 1) / n); emit(i, u / n, (v + 1) / n);
      }
    }
  }
  const base = new THREE.BufferGeometry();
  names.forEach((name, i) => base.setAttribute(name, new THREE.BufferAttribute(values[i], attrs[i].itemSize)));
  copy.dispose();
  return { base, parts };
}

/** 每种模型 / 受力方向缓存三个形状；动画只改权重，结束换静态几何。 */
export function crushShape(source: THREE.BufferGeometry, kind: CrushKind, side: number): CrushShape {
  let entry = cache.get(source);
  if (!entry) {
    entry = { ...prepare(source), shapes: new Map() };
    cache.set(source, entry);
    source.addEventListener('dispose', () => {
      for (const shape of entry!.shapes.values()) { shape.animated.dispose(); shape.settled.dispose(); }
      entry!.base.dispose();
      cache.delete(source);
    });
  }
  const key = `${kind}-${side}`;
  const found = entry.shapes.get(key);
  if (found) return found;
  source.computeBoundingBox();
  const box = source.boundingBox!;
  const hw = Math.max(0.2, Math.abs(box.min.x), Math.abs(box.max.x));
  const hd = Math.max(0.2, Math.abs(box.min.z), Math.abs(box.max.z));
  const top = Math.max(0.2, box.max.y);
  const dx = side === 0 ? 1 : side === 1 ? -1 : 0;
  const dz = side === 2 ? 1 : side === 3 ? -1 : 0;
  const base = new THREE.BufferGeometry();
  for (const name of Object.keys(entry.base.attributes)) base.setAttribute(name, entry.base.getAttribute(name));
  const pos = base.getAttribute('position');
  const positions: THREE.BufferAttribute[] = [], normals: THREE.BufferAttribute[] = [];
  const heights = [top];
  let settled = base;
  for (let stage = 0; stage < 3; stage++) {
    const arr = new Float32Array(pos.count * 3);
    let height = 0;
    for (const part of entry.parts) {
      for (let i = part.start; i < part.start + part.count; i++) {
        deform(point, pos.getX(i), pos.getY(i), pos.getZ(i), part, kind, stage, dx, dz, hw, hd, top);
        arr[i * 3] = point.x; arr[i * 3 + 1] = point.y; arr[i * 3 + 2] = point.z;
        height = Math.max(height, point.y);
      }
    }
    const target = new THREE.BufferGeometry();
    target.setAttribute('position', new THREE.BufferAttribute(arr, 3));
    target.computeVertexNormals();
    roundNormals(target, base, entry.parts, kind, stage, top);
    positions.push(target.getAttribute('position') as THREE.BufferAttribute);
    normals.push(target.getAttribute('normal') as THREE.BufferAttribute);
    heights.push(height);
    if (stage === 2) {
      settled = target;
      for (const name of Object.keys(base.attributes))
        if (name !== 'position' && name !== 'normal') settled.setAttribute(name, base.getAttribute(name));
      settled.computeBoundingBox(); settled.computeBoundingSphere();
    }
  }
  base.morphAttributes.position = positions;
  base.morphAttributes.normal = normals;
  base.computeBoundingBox(); base.computeBoundingSphere();
  const shape = { animated: base, settled, heights, key: `pressed-${source.id}-${key}` };
  entry.shapes.set(key, shape);
  return shape;
}

/** 沙袋和轮胎保持原来的圆滑表面；折板和铁皮才按折面重算法线。 */
function roundNormals(target: THREE.BufferGeometry, base: THREE.BufferGeometry, parts: CrushPartRange[], kind: CrushKind, stage: number, top: number): void {
  const src = base.getAttribute('normal'), dst = target.getAttribute('normal');
  const load = stage === 0 ? 0.24 : stage === 1 ? 0.86 : 1;
  const bend = stage === 0 ? 0 : stage === 1 ? 0.8 : 1;
  for (const part of parts) {
    const sack = kind === 'sand' && part.role !== CRUSH_PART.board;
    const wheel = part.role === CRUSH_PART.wheel;
    if (!sack && !wheel) continue;
    const [cx, cy] = part.pivot;
    const upper = smooth((cy - 0.35) / Math.max(0.3, top - 0.5));
    const angle = sack ? bend * (0.2 + upper * 0.28) * (cx < 0 ? -1 : 1) : bend * Math.sign(cx) * 0.26;
    const c = Math.cos(angle), s = Math.sin(angle), squeeze = 1 - load * 0.16;
    const determinant = c * c * squeeze + s * s;
    for (let i = part.start; i < part.start + part.count; i++) {
      const x = src.getX(i), y = src.getY(i), z = src.getZ(i);
      if (sack) point.set(x, (c * y - s * z) / determinant, (s * y + c * squeeze * z) / determinant);
      else point.set(x * c - y * s, x * s + y * c, z);
      point.normalize();
      dst.setXYZ(i, point.x, point.y, point.z);
    }
  }
}

function deform(out: THREE.Vector3, x: number, y: number, z: number, part: CrushPartRange, kind: CrushKind, stage: number, dx: number, dz: number, hw: number, hd: number, top: number): void {
  const [cx, cy, cz] = part.pivot;
  const role = part.role;
  const near = smooth(0.5 + 0.5 * (dx * x / hw + dz * z / hd));
  const load = stage === 0 ? 0.24 : stage === 1 ? 0.86 : 1;
  const bend = stage === 0 ? 0 : stage === 1 ? 0.8 : 1;
  out.set(x, y, z);
  if (kind === 'hay') {
    // 草束先塌顶，再向两侧摊开；不套木板的折转，也不保留直立的圆筒端面。
    const squeeze = stage === 0 ? .28 + near * .24 : stage === 1 ? .7 + near * .08 : .78;
    const edge = Math.sin(x * 7.1 + z * 4.3) * Math.sin(y * 5.7);
    out.x = cx + (x - cx) * (1 + load * .38) - dx * load * .18 + bend * edge * .09;
    out.z = cz + (z - cz) * (1 + load * .3) - dz * load * .14 + bend * edge * .07;
    out.y = Math.max(.025, y * (1 - squeeze) + bend * edge * .035 * Math.min(1, y));
    return;
  }
  if (kind === 'sand' && role !== CRUSH_PART.board) {
    // 上层错位滑落，底层向外挤；每袋自身最多压低 16%。
    const upper = smooth((cy - 0.35) / Math.max(0.3, top - 0.5));
    const a = bend * (0.2 + upper * 0.28) * (cx < 0 ? -1 : 1);
    const yy = y - cy, zz = z - cz;
    out.y = Math.max(0.04, cy - upper * bend * 0.55 + yy * Math.cos(a) * (1 - load * 0.16) - zz * Math.sin(a));
    out.z = cz + zz * Math.cos(a) + yy * Math.sin(a) - dz * load * (0.2 + upper * 0.45);
    out.x += load * (Math.sign(cx || 1) * (0.12 + upper * 0.48) - dx * 0.2);
    return;
  }
  if (kind === 'wood' || role === CRUSH_PART.board) {
    // 木板绕接头折倒，断口错开，保持板厚。
    const a = load * (0.35 + near * 0.9);
    const yy = y - cy, along = (x - cx) * dx + (z - cz) * dz;
    const shift = along * (Math.cos(a) - 1) - yy * Math.sin(a);
    out.x += dx * (shift - bend * 0.35) + Math.sign(cx) * bend * 0.16;
    out.z += dz * (shift - bend * 0.35) + Math.sin(cx * 2.1 + cz) * bend * 0.18;
    out.y = Math.max(0.06, cy * (1 - load * 0.7) + yy * Math.cos(a) + along * Math.sin(a));
    return;
  }
  if (kind === 'barrel') {
    const h = clamp(y / top, 0, 1);
    const pleat = Math.sin(h * Math.PI * 3) * Math.sin(h * Math.PI);
    const radial = bend * (role === CRUSH_PART.hoop ? 0.16 : 0.24 * pleat);
    out.x += Math.sign(x - cx || x) * radial - dx * load * h * 0.3;
    out.z += Math.sign(z - cz || z) * radial - dz * load * h * 0.25;
    out.y = Math.max(0.04, y - load * (0.25 + 0.5 * near) * y + bend * 0.07 * Math.cos(h * Math.PI * 4));
    return;
  }
  if (kind === 'rubble') {
    out.x += bend * Math.sign(x) * 0.12; out.z += bend * Math.sign(z) * 0.1;
    out.y = Math.max(0.05, y - load * near * 0.12);
    return;
  }
  const floor = kind === 'truck' ? 0.58 : 0.32;
  const upper = Math.max(0, y - floor);
  if (role === CRUSH_PART.wheel) {
    const a = bend * Math.sign(cx) * 0.26, xx = x - cx, yy = y - cy;
    out.x = cx + xx * Math.cos(a) - yy * Math.sin(a) + Math.sign(cx) * bend * 0.12;
    out.y = Math.max(0.03, cy + xx * Math.sin(a) + yy * Math.cos(a) - load * 0.06);
    return;
  }
  if (role === CRUSH_PART.glass) {
    const shrink = stage === 0 ? 0.85 : 0;
    out.set(cx + (x - cx) * shrink, floor + (cy - floor) * (1 - load * 0.7) + (y - cy) * shrink, cz + (z - cz) * shrink);
    return;
  }
  if (role === CRUSH_PART.frame) {
    const arch = Math.abs(z / hd);
    out.y = Math.max(0.08, y + bend * (0.2 * arch * arch - 0.18));
    out.x += bend * Math.sign(x) * 0.06 * (1 - arch);
    return;
  }
  const roof = role === CRUSH_PART.roof || role === CRUSH_PART.canopy;
  const cargo = role === CRUSH_PART.bed || role === CRUSH_PART.canopy;
  const contact = stage === 0 ? near : 0.85 + near * 0.15;
  const high = smooth(upper / 0.8);
  // 完整驾驶室的顶沿与车顶共用折线，车顶不会折进一块仍然立着的实心驾驶室。
  const collapse = roof ? 0.77 : cargo ? 0.62 : 0.2 + high * 0.57;
  out.y = Math.max(0.08, y - upper * load * collapse * contact);
  const crease = Math.sin(z / hd * Math.PI * 2) * (role === CRUSH_PART.canopy ? 0.22 : cargo ? 0.035 : 0.12 * high) * bend;
  out.y += crease + bend * (cargo && !roof ? 0.06 : 0.14 * high) * Math.abs(x / hw) - (cargo && !roof ? 0 : 0.14 * high * load * near);
  out.x += bend * Math.sign(x) * upper * (cargo ? 0.28 : 0.09) - dx * load * upper * 0.12 * contact;
  out.z += bend * Math.sign(z) * upper * 0.045 - dz * load * upper * 0.1 * contact;
}

/** 权重总和不超过 1；返回外形高度，只供绘制支撑读取。 */
export function poseCrush(mesh: THREE.Mesh, shape: CrushShape, progress: number): number {
  const a = smooth(progress / 0.24), b = smooth((progress - 0.24) / 0.54), c = smooth((progress - 0.78) / 0.22);
  const weights = mesh.morphTargetInfluences!;
  weights[0] = a * (1 - b); weights[1] = b * (1 - c); weights[2] = c;
  return shape.heights[0] * (1 - a) + shape.heights[1] * weights[0] + shape.heights[2] * weights[1] + shape.heights[3] * weights[2];
}

/**
 * 局部碾压（T181）：草垛、卡车、轿车不再整件按一个进度压扁，只压车体实际盖住的部分。
 * 物件自身 xz 平面铺一张 0.2 米的网格，每个格点记「被盖住的程度 / 压到的高度」；车体盖到哪里、压到哪里，
 * 履带底下压到最低，两条履带中间只压到车腹离地高度，盖住范围外 margin 米内按比例折下来，接触边缘出一道折痕。
 * 只改显示几何；碰撞、凸起、伤害、奖励仍走原来的判定。
 */
export const LOCAL = { edge: 0.45, maxSeg: 6, cell: 0.2, rate: 5 } as const;
/** 走局部碾压的物件；其他小件仍按原来的整件折叠 */
export const LOCAL_KINDS: ReadonlySet<CrushKind> = new Set<CrushKind>(['hay', 'truck', 'car']);
/** 压实以后履带底下剩的高度（米）：卡车 / 轿车与原凸起压平高度一致（2.2 × 0.32、0.6），草垛压成薄草垫 */
const LOCAL_FLOOR: Partial<Record<CrushKind, number>> = { truck: 0.704, car: 0.6, hay: 0.12 };
/** 压在底层以上的部分保留几成厚度（层层叠起，不压成一张纸）、盖住范围外折下来的宽度 */
const LOCAL_KEEP: Partial<Record<CrushKind, number>> = { truck: 0.14, car: 0.14, hay: 0.28 };
const LOCAL_MARGIN: Partial<Record<CrushKind, number>> = { truck: 0.95, car: 0.85, hay: 0.45 };
/**
 * 车体下沿：两条履带内侧在车体中线外 1.55 米，中间车腹离履带底 0.55 米。草垛在地上压，车腹底下留一道草垄；
 * 卡车 / 轿车绘制时车体骑在残骸上（T157R 支撑），车下整片压到同一高度，免得车腹插进残骸
 */
const TRACK_IN = 1.55;
const BELLY: Partial<Record<CrushKind, number>> = { hay: 0.55 };

export interface Presser { x: number; z: number; yaw: number; hw: number; hl: number }

export interface LocalCrush {
  kind: CrushKind;
  geo: THREE.BufferGeometry;
  rest: ArrayLike<number>;
  restN: ArrayLike<number>;
  parts: CrushPartRange[];
  /** 源几何最高点 / 最宽半宽（局部坐标） */
  top: number;
  hw: number;
  x0: number;
  z0: number;
  nx: number;
  nz: number;
  goal: Float32Array;
  shown: Float32Array;
  floor: Float32Array;
  amount: Float32Array;
  /** 上一帧还有格点没走到目标（车走远、全部到位以后不再逐格检查） */
  busy: boolean;
  /** 车体压过来的方向（物件自身坐标、单位向量）：铁皮顺着它往前拱、起褶（T195） */
  px: number;
  pz: number;
}

const fine = new WeakMap<THREE.BufferGeometry, { base: THREE.BufferGeometry; parts: CrushPartRange[] }>();

/** 细分只做一次（物件刷出来时先算，接触那一帧不卡） */
export function prepareLocal(source: THREE.BufferGeometry): { base: THREE.BufferGeometry; parts: CrushPartRange[] } {
  let entry = fine.get(source);
  if (!entry) {
    entry = prepare(source, true);
    entry.base.computeBoundingSphere();
    source.computeBoundingBox();
    fine.set(source, entry);
    const e = entry;
    source.addEventListener('dispose', () => { e.base.dispose(); fine.delete(source); });
  }
  return entry;
}

/** 每件受压物件一份可写的位置 / 法线；网格 grid 传进来时沿用（原系统换烧毁外形后折痕接着用） */
export function localCrush(source: THREE.BufferGeometry, kind: CrushKind, grid?: LocalCrush): LocalCrush {
  const { base, parts } = prepareLocal(source);
  const geo = new THREE.BufferGeometry();
  for (const name of Object.keys(base.attributes)) {
    const a = base.getAttribute(name) as THREE.BufferAttribute;
    geo.setAttribute(name, name === 'position' || name === 'normal' ? a.clone() : a);
  }
  if (!source.boundingBox) source.computeBoundingBox();
  const box = source.boundingBox!;
  geo.boundingSphere = base.boundingSphere!.clone();
  geo.boundingSphere.radius += 0.8;
  const pad = (LOCAL_MARGIN[kind] ?? 0.5) + LOCAL.cell;
  const lc: LocalCrush = grid ? { ...grid } : (() => {
    const x0 = box.min.x - pad, z0 = box.min.z - pad;
    const nx = Math.ceil((box.max.x - box.min.x + pad * 2) / LOCAL.cell) + 1;
    const nz = Math.ceil((box.max.z - box.min.z + pad * 2) / LOCAL.cell) + 1;
    const n = nx * nz;
    return {
      kind, geo, rest: [], restN: [], parts, top: 0, hw: 0, x0, z0, nx, nz,
      goal: new Float32Array(n), shown: new Float32Array(n), floor: new Float32Array(n).fill(1e3), amount: new Float32Array(0), busy: false, px: 0, pz: -1,
    };
  })();
  lc.geo = geo;
  lc.parts = parts;
  lc.rest = base.getAttribute('position').array;
  lc.restN = base.getAttribute('normal').array;
  lc.top = Math.max(0.2, box.max.y);
  lc.hw = Math.max(0.2, Math.abs(box.min.x), Math.abs(box.max.x));
  lc.amount = new Float32Array(base.getAttribute('position').count);
  return lc;
}

/** 压在车体底下时的最高点（世界米，绘制支撑读取）：floorW = 当前履带底下压到的高度 */
export function localHeight(lc: LocalCrush, floorW: number, scaleY: number): number {
  const top = lc.top * scaleY;
  return floorW >= top ? top : floorW + (top - floorW) * (LOCAL_KEEP[lc.kind] ?? 0.2);
}

/** 履带底下最终压到的高度（世界米） */
export function localFloor(kind: CrushKind): number {
  return LOCAL_FLOOR[kind] ?? 0.3;
}

/**
 * 车体（世界坐标下的矩形）这一帧盖住的格点：盖住程度取历史最大、压到高度取历史最低，再按 rate 往目标走。
 * floorW = 履带底下这一帧压到的高度（世界米）。返回是否需要重算顶点；hit 记下这一帧新压下去的地方（世界坐标，碎屑 / 尘土从这里冒）。
 * ground：给了就按「世界地面 + floorW」换算每个格点在自身坐标里的高度（T194 卡车半截躺稳时是斜的）；不给 = 原点贴地、物件只绕竖轴转（原来的算法）
 */
export function pressLocal(lc: LocalCrush, matrix: THREE.Matrix4, t: Presser | null, floorW: number, dt: number,
  hit: { x: number; z: number; w: number }, ground?: number): boolean {
  const e = matrix.elements;
  const scaleY = Math.hypot(e[4], e[5], e[6]) || 1;
  const margin = LOCAL_MARGIN[lc.kind] ?? 0.5;
  const { nx, nz, x0, z0, goal, shown, floor } = lc;
  const cell = LOCAL.cell;
  let changed = false;
  hit.x = hit.z = hit.w = 0;
  const c = t ? Math.cos(t.yaw) : 1, s = t ? Math.sin(t.yaw) : 0;
  if (t) {
    // 车头朝向（世界 −sin, −cos）换到物件自身的水平坐标
    const ax = Math.hypot(e[0], e[2]) || 1, az = Math.hypot(e[8], e[10]) || 1;
    const fx = -s, fz = -c;
    const lx = (fx * e[0] + fz * e[2]) / ax, lz = (fx * e[8] + fz * e[10]) / az, l = Math.hypot(lx, lz) || 1;
    lc.px = lx / l; lc.pz = lz / l;
  }
  for (let j = 0; j < nz; j++) {
    const lz = z0 + j * cell;
    for (let i = 0; i < nx; i++) {
      const k = j * nx + i, lx = x0 + i * cell;
      const wx = e[0] * lx + e[8] * lz + e[12], wz = e[2] * lx + e[10] * lz + e[14];
      if (t) {
        const dx = wx - t.x, dz = wz - t.z;
        const u = Math.abs(dx * c - dz * s), w = Math.abs(dx * s + dz * c);
        const d = Math.hypot(Math.max(0, u - t.hw), Math.max(0, w - t.hl));
        if (d < margin) {
          const weight = d <= 0 ? 1 : 1 - smooth(d / margin);
          const belly = (1 - smooth((Math.min(u, t.hw) - (TRACK_IN - 0.15)) / 0.3)) * (BELLY[lc.kind] ?? 0);
          const fl = ground === undefined ? (floorW + belly) / scaleY
            : (ground + floorW + belly - e[13] - e[1] * lx - e[9] * lz) / Math.max(0.3 * scaleY, e[5]);
          if (weight > goal[k]) goal[k] = weight;
          if (fl < floor[k] - 1e-3) { floor[k] = fl; if (shown[k] > 0) changed = true; }
        }
      }
      if (shown[k] < goal[k]) {
        const inc = Math.min(goal[k] - shown[k], dt * LOCAL.rate);
        shown[k] += inc;
        hit.x += wx * inc; hit.z += wz * inc; hit.w += inc;
        changed = true;
      }
    }
  }
  if (hit.w > 0) { hit.x /= hit.w; hit.z /= hit.w; }
  lc.busy = hit.w > 0;
  return changed;
}

/** 按格点重算顶点：盖住的部分压到底层上面、往外摊开并起皱，折痕外的部分原样；轮子整只外翻、玻璃碎掉 */
export function applyLocal(lc: LocalCrush): void {
  const pos = lc.geo.getAttribute('position') as THREE.BufferAttribute;
  const nrm = lc.geo.getAttribute('normal') as THREE.BufferAttribute;
  const p = pos.array as Float32Array, n = nrm.array as Float32Array, rest = lc.rest, restN = lc.restN, amount = lc.amount;
  const hay = lc.kind === 'hay';
  const keep = LOCAL_KEEP[lc.kind] ?? 0.2;
  const { nx, nz, x0, z0, shown, floor } = lc;
  const inv = 1 / LOCAL.cell;
  let sa = 0, sf = 0;
  const sample = (x: number, z: number) => {
    const fx = clamp((x - x0) * inv, 0, nx - 1.001), fz = clamp((z - z0) * inv, 0, nz - 1.001);
    const i = Math.floor(fx), j = Math.floor(fz), tx = fx - i, tz = fz - j, k = j * nx + i;
    const w0 = (1 - tx) * (1 - tz), w1 = tx * (1 - tz), w2 = (1 - tx) * tz, w3 = tx * tz;
    const a0 = shown[k] * w0, a1 = shown[k + 1] * w1, a2 = shown[k + nx] * w2, a3 = shown[k + nx + 1] * w3;
    sa = a0 + a1 + a2 + a3;
    sf = sa > 1e-4 ? (a0 * floor[k] + a1 * floor[k + 1] + a2 * floor[k + nx] + a3 * floor[k + nx + 1]) / sa : 1e3;
  };
  const px = lc.px, pz = lc.pz;
  for (const part of lc.parts) {
    const end = part.start + part.count;
    const [cx, cy, cz] = part.pivot;
    if (part.role === CRUSH_PART.wheel || part.role === CRUSH_PART.glass) {
      sample(cx, cz);
      const k = sa * clamp((cy * 1.7 - sf) / 0.5, 0, 1);
      // 挂得高的（备胎）跟着压下来的车体一起落到底层上面
      const sink = 0.05 * k + sa * Math.max(0, cy - (sf + 0.25));
      const a = part.role === CRUSH_PART.wheel ? k * Math.sign(cx || 1) * 0.32 : 0;
      const ca = Math.cos(a), sn = Math.sin(a), shrink = part.role === CRUSH_PART.glass ? Math.max(0, 1 - k * 2.5) : 1;
      for (let v = part.start; v < end; v++) {
        const o = v * 3, x = rest[o] - cx, y = rest[o + 1] - cy, z = rest[o + 2] - cz;
        p[o] = cx + (x * ca - y * sn) * shrink + Math.sign(cx || 1) * 0.14 * k;
        p[o + 1] = Math.max(0.02, cy + (x * sn + y * ca) * shrink - sink);
        p[o + 2] = cz + z * shrink;
        amount[v] = k;
      }
      continue;
    }
    for (let v = part.start; v < end; v++) {
      const o = v * 3, x = rest[o], y = rest[o + 1], z = rest[o + 2];
      if (hay) {
        sample(x, z);
        amount[v] = sa;
        if (sa < 1e-4) { p[o] = x; p[o + 1] = y; p[o + 2] = z; continue; }
        const target = y > sf ? sf + (y - sf) * keep : y * 0.94;
        let yd = y + (target - y) * sa;
        const drop = y - yd;
        const wr = Math.sin(x * 7.3 + z * 3.1 + y * 2.2) * Math.sin(z * 6.1 - x * 2.3 + y * 4.7);
        yd += wr * Math.min(drop, 0.6) * 0.07;
        const dx = x - cx, dz = z - cz, l = Math.hypot(dx, dz) || 1;
        p[o] = x + (dx / l) * drop * 0.3 + wr * drop * 0.05; p[o + 1] = Math.max(0.02, yd); p[o + 2] = z + (dz / l) * drop * 0.3;
        continue;
      }
      // 车体（T195）：折线不再是一道直的平面——顺着车头方向、按横向位置和高度错开取样；盖住一半的那条带子上铁皮往上拱、
      // 往前推，压下去的部分厚度不均、顺着压过来的方向起一道道褶、两侧往外鼓
      const along = x * px + z * pz, lat = x * pz - z * px;
      const jag = 0.3 * Math.sin(lat * 2.7 + y * 1.3) + 0.16 * Math.sin(lat * 6.3 - y * 2.9 + along * 1.7) + Math.max(0, y - 0.8) * 0.16;
      sample(x + px * jag, z + pz * jag);
      amount[v] = sa;
      if (sa < 1e-4) { p[o] = x; p[o + 1] = y; p[o + 2] = z; continue; }
      const press = smooth((sa - 0.18) / 0.82);
      const band = sa * (1 - sa) * 4;
      const n1 = 0.5 + 0.5 * Math.sin(x * 3.7 + z * 2.3) * Math.sin(z * 4.1 - x * 1.7 + y * 2.1);
      const target = y > sf ? sf + (y - sf) * keep * (0.55 + 0.9 * n1) : y * 0.94;
      let yd = y + (target - y) * press;
      const drop = y - yd;
      const above = Math.max(0, y - Math.min(sf, 1e2));
      const pleat = Math.sin(along * 6.2 + n1 * 2.4 + lat * 0.9);
      const wr = Math.sin(x * 7.3 + z * 3.1 + y * 2.2) * Math.sin(z * 6.1 - x * 2.3 + y * 4.7);
      yd += pleat * Math.min(drop, 0.9) * 0.2 + wr * Math.min(drop, 0.6) * 0.12;
      yd += band * Math.min(0.4, above * 0.26) * (0.55 + 0.45 * Math.sin(lat * 3.1 + along * 4.7));
      const shove = drop * 0.2 + band * Math.min(0.22, above * 0.12);
      const side = Math.sign(x || 1) * Math.min(1, Math.abs(x) / lc.hw);
      const bulge = drop * (0.16 + 0.12 * n1) * (0.6 + 0.4 * Math.abs(pleat));
      p[o] = x + px * shove + side * bulge + wr * drop * 0.05;
      p[o + 1] = Math.max(0.02, yd);
      p[o + 2] = z + pz * shove + wr * drop * 0.05;
    }
  }
  // 压过的面按折面重算法线，没压到的保留原来的圆滑法线；草是软的，折面法线只混一半（不压成揉皱的纸）
  const facet = hay ? 0.5 : 1;
  for (let v = 0; v + 2 < pos.count; v += 3) {
    const o = v * 3;
    const ax = p[o + 3] - p[o], ay = p[o + 4] - p[o + 1], az = p[o + 5] - p[o + 2];
    const bx = p[o + 6] - p[o], by = p[o + 7] - p[o + 1], bz = p[o + 8] - p[o + 2];
    let fx = ay * bz - az * by, fy = az * bx - ax * bz, fz = ax * by - ay * bx;
    const fl = Math.hypot(fx, fy, fz) || 1;
    fx /= fl; fy /= fl; fz /= fl;
    for (let q = 0; q < 3; q++) {
      const vo = o + q * 3, k = Math.min(1, amount[v + q] * 2.5) * facet;
      let x = restN[vo] * (1 - k) + fx * k, y = restN[vo + 1] * (1 - k) + fy * k, z = restN[vo + 2] * (1 - k) + fz * k;
      const l = Math.hypot(x, y, z) || 1;
      n[vo] = x / l; n[vo + 1] = y / l; n[vo + 2] = z / l;
    }
  }
  pos.needsUpdate = true;
  nrm.needsUpdate = true;
}
