import * as THREE from 'three';
import type { PartSpec } from '../../assets/GeoCache';
import { MAT } from '../../assets/materials';
import { heavyBomberGeo } from '../../assets/models/weapons';
import type { Enemy } from '../../entities/Enemy';
import { glslColor, MARK_SELF } from '../../render/markColors';
import { DRAPE_VERT } from '../../world/Craters';
import { ultHalf } from '../defs';
import { summonDuration } from '../superMods';
import { UltBase, type UltAim, type UltContext, type UltPreview } from './common';
import { rng } from '../../game/rng';

const rand = (a: number, b: number) => a + Math.random() * (b - a);

/**
 * 「铁雨」数值表（D1-032 第 7.1 节；冷却在 FUSIONS.gunship.cd 里固定 40 秒）：
 * 炮艇 enter 秒从坦克身后进场，接着绕火力圈左转一圈 fire 秒，边转边打；火力圈半径 r，中心在坦克前方 near～far 米、左右 side 米内，跟车往前走；
 * 放出后点一下 = 火力圈往点的地方挪（每秒 move 米）。
 * 25 毫米双管：圈里每个敌人每秒 dps（每 tick 秒结算一次，炮弹类型、从天上打、掩体不挡）；
 * 40 毫米：每 g40.every 秒一发，g40.r 米、g40.dmg；105 毫米：每 g105.every 秒打圈里血最厚的，g105.r 米、g105.dmg，中坑；这两种都不掀车。
 * 收尾 finale：n 发 105 齐落（中心 + 左右 spread 米），各 r 米、dmg，掀车（这件究极「带冲击的那一下」），最多 maxBreak 辆车走完整碎裂；爆炸半径 × 爆破药半效。
 * 画面：炮艇 ship（重型轰炸机机身 × scale，离地 alt 米、绕圈半径 orbit 米、压坡度 bank）；左舷两根转管每门每秒画 trace 根曳光，
 * 弹着点沿两条「一圈一圈」的扫线走，地上留弹沟；临走爬升、两侧撒热焰弹 flares（每 every 秒一对，共 n 对）；
 * 镜头 cam：放出时压低、稍微抬头看炮艇压坡度
 */
export const GUNSHIP = {
  enter: 0.8, fire: 8, r: 20, near: 34, far: 80, side: 34, move: 12, preview: 52,
  dps: 140, tick: 0.2,
  g40: { every: 0.4, r: 3.5, dmg: 120, flight: 0.18 },
  g105: { every: 2, r: 8, dmg: 500, flight: 0.4 },
  finale: { n: 3, r: 9, dmg: 600, spread: 7, flight: 0.6, knock: 12, maxBreak: 6 },
  ship: { scale: 0.6, alt: 28, orbit: 30, bank: 0.42, from: 60, exit: 2.4, climb: 5 },
  trace: 26,
  flares: { every: 0.07, n: 14, life: 1.7 },
  cam: { tilt: -1.15, hold: 1.5, back: 0.9, lift: 0.22, liftHold: 0.7, liftIn: 0.5 },
};

/** 左舷炮位（机身局部坐标：机头 +X、左舷 −Z）：两根 25 毫米转管、40 毫米、105 毫米，炮口朝左下 */
const DOWN = new THREE.Vector3(0, -0.5, -1).normalize();
const GUNS: { at: [number, number, number]; len: number; r: number }[] = [
  { at: [4.5, -0.6, -1.45], len: 2.4, r: 0.16 },
  { at: [2.6, -0.6, -1.5], len: 2.4, r: 0.16 },
  { at: [-2.2, -0.5, -1.55], len: 2.8, r: 0.22 },
  { at: [-5.6, -0.4, -1.5], len: 3.6, r: 0.34 },
];

/** 火力圈地面圈：我方浅黄圈边 + 里侧深色描边 + 很淡的里层，慢慢转的虚线；uFade 收尾（T130：原来琥珀色加色，沙地上发白看不清） */
const RING_FRAG = /* glsl */ `
uniform float uTime;
uniform float uFade;
varying vec2 vP;
void main() {
  float r = length(vP);
  if (r > 1.0) discard;
  float a = atan(vP.y, vP.x);
  float rim = smoothstep(0.9, 0.97, r) * (1.0 - smoothstep(0.97, 1.0, r));
  float dash = step(0.5, fract(a * 4.7746 - uTime * 0.6));
  float ol = smoothstep(0.84, 0.87, r) * (1.0 - smoothstep(0.9, 0.92, r));
  float k = max(rim * (0.45 + 0.4 * dash) + (1.0 - r) * 0.06, ol * 0.55) * uFade;
  if (k < 0.01) discard;
  gl_FragColor = vec4(mix(${glslColor(MARK_SELF)}, vec3(0.08, 0.04, 0.02), ol), k);
  #include <colorspace_fragment>
}`;

let shipMat: THREE.MeshStandardMaterial | null = null;

interface Shell {
  x: number;
  z: number;
  t: number;
  kind: 40 | 105 | 0;
}
interface Flare {
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  vz: number;
  t: number;
}

/** 铁雨 · 空中炮艇（火神 + 机枪★ + 空袭★）：炮艇绕前方盘旋 8 秒，火力圈里泼弹；点一下挪圈；收尾三发重炮齐落 */
export class GunshipUlt extends UltBase {
  private fireDuration = GUNSHIP.fire;
  /** 按下后几秒；-1 = 不在事件里（炮艇飞走、热焰弹落完才算完） */
  private t = -1;
  /** 火力圈中心相对坦克的偏移（跟车）、想挪到的偏移 */
  private ox = 0;
  private oz = -GUNSHIP.preview;
  private wx = 0;
  private wz = -GUNSHIP.preview;
  private cx = 0;
  private cz = 0;
  private R = GUNSHIP.r;
  private A = 1;
  private tickT = 0;
  private g40T = 0;
  private g105T = 0;
  private traceAcc = [0, 0];
  private grooveT = 0;
  private sweep: [number, number][] = [[0, 0], [0, 0]];
  private brrtT = 0;
  private finaleDone = false;
  private freed = true;
  private flareT = 0;
  private flareN = 0;
  /** 进场起点、绕圈起始角、最后一刻的朝向（飞走用） */
  private sx = 0;
  private sz = 0;
  private th0 = 0;
  private hx = 1;
  private hz = 0;
  private exitX = 0;
  private exitY = 0;
  private exitZ = 0;
  private ship: THREE.Group | null = null;
  private ring: THREE.Mesh<THREE.RingGeometry, THREE.ShaderMaterial> | null = null;
  private readonly shells: Shell[] = [];
  private readonly flares: Flare[] = [];
  private readonly v = new THREE.Vector3();
  private readonly muzzles = GUNS.map((g) => new THREE.Vector3(...g.at).addScaledVector(DOWN, g.len));

  spot(): { r: number; min: number; max: number } {
    return { r: GUNSHIP.r, min: GUNSHIP.near, max: GUNSHIP.far };
  }

  /** 现在按下火力圈在哪：瞄准的目标处（夹到前方 near～far 米），没有目标就是炮塔方向 preview 米 */
  private landing(ctx: UltContext, aim: UltAim): { ox: number; oz: number } {
    const P = ctx.tank.group.position;
    const T = GUNSHIP;
    let ox = aim.target ? aim.target.group.position.x - P.x : -Math.sin(aim.angle) * T.preview;
    let oz = aim.target ? aim.target.group.position.z - P.z : -Math.cos(aim.angle) * T.preview;
    oz = THREE.MathUtils.clamp(oz, -T.far, -T.near);
    ox = THREE.MathUtils.clamp(ox, -T.side, T.side);
    return { ox, oz };
  }

  preview(ctx: UltContext, aim: UltAim): UltPreview {
    const P = ctx.tank.group.position;
    const p = this.landing(ctx, aim);
    // 待发时火力圈就建好、透明着放在车下（着色器这时编译，放的那一下不卡）
    if (this.t < 0) {
      this.ring ??= this.makeRing(ctx);
      this.ring.visible = true;
      this.ring.material.uniforms.uFade.value = 0;
      this.ring.position.set(P.x, 0.12, P.z);
    }
    return { x: P.x + p.ox, z: P.z + p.oz, r: GUNSHIP.r };
  }

  /** 放出后点一下（地面坐标）：火力圈往那里挪 */
  tapAt(x: number, z: number): boolean {
    if (this.t < 0 || this.t >= GUNSHIP.enter + this.fireDuration) return false;
    const T = GUNSHIP;
    this.wx = THREE.MathUtils.clamp(x - (this.cx - this.ox), -T.side, T.side);
    this.wz = THREE.MathUtils.clamp(z - (this.cz - this.oz), -T.far, -T.near);
    return true;
  }

  protected override activeLabel(): string {
    return this.t < GUNSHIP.enter ? '进场' : `生效 ${Math.ceil(this.active)}`;
  }

  protected fire(ctx: UltContext, aim: UltAim): void {
    const T = GUNSHIP;
    this.clear();
    this.fireDuration = T.fire * summonDuration(ctx.mods);
    const P = ctx.tank.group.position;
    const p = this.landing(ctx, aim);
    this.ox = this.wx = p.ox;
    this.oz = this.wz = p.oz;
    this.cx = P.x + p.ox;
    this.cz = P.z + p.oz;
    this.A = ultHalf(ctx.mods.area);
    this.t = 0;
    this.tickT = 0;
    this.g40T = T.g40.every * 0.5;
    this.g105T = 0.6;
    this.active = T.enter + this.fireDuration + T.finale.flight;
    // 从坦克身后左侧进场，切进绕圈起点（圈的近端偏左一点，左转）
    this.sx = P.x - 26;
    this.sz = P.z + T.ship.from;
    this.th0 = Math.PI / 2 + 0.5;
    this.ship ??= this.makeShip(ctx);
    this.ship.visible = true;
    this.ring ??= this.makeRing(ctx);
    this.ring.visible = true;
    this.ring.scale.set(T.r, 1, T.r);
    this.place(0);
    ctx.audio.play('radio');
    ctx.audio.play('bomber', 0.7);
    ctx.cinema(T.cam.tilt, T.cam.hold, T.cam.back);
    ctx.lookUp(T.cam.lift, T.cam.liftHold, 0.8, T.cam.liftIn);
  }

  /** 炮艇：重型轰炸机机身 + 左舷四根炮管（合并成 2 次绘制） */
  private makeShip(ctx: UltContext): THREE.Group {
    shipMat ??= Object.assign(MAT.painted.clone(), { emissive: new THREE.Color(0x2c3236) });
    const g = new THREE.Group();
    const body = new THREE.Mesh(heavyBomberGeo(ctx.geo), shipMat);
    body.castShadow = true;
    g.add(body);
    const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), DOWN);
    const e = new THREE.Euler().setFromQuaternion(q);
    const guns = new THREE.Mesh(ctx.geo.merged('ult-gunship-guns', (): PartSpec[] => [
      ...GUNS.map((s): PartSpec => {
        const c = new THREE.Vector3(...s.at).addScaledVector(DOWN, s.len / 2);
        return { geo: new THREE.CylinderGeometry(s.r, s.r * 1.25, s.len, 8), color: 0x2a2c2a, pos: [c.x, c.y, c.z], rot: [e.x, e.y, e.z] };
      }),
      ...GUNS.map((s): PartSpec => ({ geo: new THREE.BoxGeometry(s.r * 6, s.r * 5, 0.3), color: 0x3a3e36, pos: [s.at[0], s.at[1], s.at[2] + 0.1] })),
      // 机腹前面的光电转塔
      { geo: new THREE.SphereGeometry(0.55, 10, 8), color: 0x22262a, pos: [9.5, -1.5, -0.3] },
    ]), shipMat);
    g.add(guns);
    g.scale.setScalar(GUNSHIP.ship.scale);
    ctx.scene.add(g);
    return g;
  }

  private makeRing(ctx: UltContext): THREE.Mesh<THREE.RingGeometry, THREE.ShaderMaterial> {
    const m = new THREE.Mesh(
      new THREE.RingGeometry(0.001, 1, 56, 10).rotateX(-Math.PI / 2),
      new THREE.ShaderMaterial({
        vertexShader: DRAPE_VERT,
        fragmentShader: RING_FRAG,
        uniforms: { uTime: { value: 0 }, uFade: { value: 0 }, uDrape: { value: 1 }, ...ctx.fx.craterU },
        transparent: true,
        depthWrite: false,
      }),
    );
    m.renderOrder = 1;
    m.frustumCulled = false;
    ctx.scene.add(m);
    return m;
  }

  /** 炮艇这一刻在哪、朝哪：进场 → 绕圈（左转、左舷朝圈心）→ 爬升飞走 */
  private place(t: number): void {
    const T = GUNSHIP;
    const S = T.ship;
    const o = this.ship!;
    const w = (Math.PI * 2) / this.fireDuration;
    const orbit = (k: number) => {
      const th = this.th0 - w * k;
      return { x: this.cx + Math.cos(th) * S.orbit, z: this.cz + Math.sin(th) * S.orbit, hx: Math.sin(th), hz: -Math.cos(th) };
    };
    let x: number;
    let y: number;
    let z: number;
    let hx: number;
    let hz: number;
    let bank = -S.bank;
    let pitch = 0;
    if (t < T.enter) {
      const k = t / T.enter;
      const e = k * k * (3 - 2 * k);
      const p = orbit(0);
      x = this.sx + (p.x - this.sx) * e;
      z = this.sz + (p.z - this.sz) * e;
      y = S.alt + 10 * (1 - e);
      // 朝向从「往前飞」转到绕圈切线
      hx = p.hx * e;
      hz = -(1 - e) + p.hz * e;
      bank = -S.bank * e;
    } else if (t < T.enter + this.fireDuration) {
      const p = orbit(t - T.enter);
      x = p.x;
      z = p.z;
      y = S.alt + Math.sin(t * 1.3) * 0.8;
      hx = p.hx;
      hz = p.hz;
      this.exitX = x;
      this.exitY = y;
      this.exitZ = z;
      this.hx = hx;
      this.hz = hz;
    } else {
      // 改平、爬升，沿最后的切线方向飞出去
      const k = t - T.enter - this.fireDuration;
      const sp = S.orbit * w * 1.5;
      x = this.exitX + this.hx * sp * k;
      z = this.exitZ + this.hz * sp * k;
      y = this.exitY + S.climb * k * k * 0.6 + S.climb * k * 0.5;
      hx = this.hx;
      hz = this.hz;
      bank = -S.bank * Math.max(0, 1 - k * 1.5);
      pitch = Math.min(0.25, k * 0.2);
    }
    const len = Math.hypot(hx, hz) || 1;
    o.position.set(x, y, z);
    o.rotation.set(bank, Math.atan2(-hz / len, hx / len), pitch, 'YXZ');
    o.updateMatrixWorld();
  }

  protected step(ctx: UltContext): void {
    if (this.t < 0) {
      if (!this.freed) {
        this.freed = true;
        ctx.breaks(Infinity);
      }
      return;
    }
    const T = GUNSHIP;
    const dt = ctx.dt;
    this.t += dt;
    const t = this.t;
    const P = ctx.tank.group.position;
    const firing = t >= T.enter && t < T.enter + this.fireDuration;
    // 火力圈跟车，往点过的地方挪（每秒 move 米）
    const dx = this.wx - this.ox;
    const dz = this.wz - this.oz;
    const d = Math.hypot(dx, dz);
    const stepM = T.move * dt;
    if (d > 1e-3) {
      const k = Math.min(1, stepM / d);
      this.ox += dx * k;
      this.oz += dz * k;
    }
    if (t < T.enter + this.fireDuration) {
      this.cx = P.x + this.ox;
      this.cz = P.z + this.oz;
    }
    this.place(t);
    const ring = this.ring!;
    const u = ring.material.uniforms;
    u.uTime.value += dt;
    u.uFade.value = t < T.enter + this.fireDuration ? Math.min(1, t / 0.4) : Math.max(0, 1 - (t - T.enter - this.fireDuration) / 0.6);
    ring.position.set(this.cx, 0.12, this.cz);
    if (firing) this.stepFire(ctx, t - T.enter, dt);
    if (!this.finaleDone && t >= T.enter + this.fireDuration) this.finale(ctx);
    this.stepShells(ctx);
    this.stepFlares(ctx, dt, t);
    if (this.active > 0) {
      const left = T.enter + this.fireDuration + T.finale.flight - t;
      if (left <= 0 && !this.shells.length) this.finish();
      else this.active = Math.max(1e-3, left);
    }
    if (!this.freed && t >= T.enter + this.fireDuration + 2) {
      this.freed = true;
      ctx.breaks(Infinity);
    }
    if (t >= T.enter + this.fireDuration + T.ship.exit && !this.flares.length) {
      this.ship!.visible = false;
      ring.visible = false;
      this.t = -1;
    }
  }

  /** 绕圈这 8 秒：25 毫米按秒结算 + 曳光 / 弹沟，40 毫米 / 105 毫米按间隔点名 */
  private stepFire(ctx: UltContext, k: number, dt: number): void {
    const T = GUNSHIP;
    const R = this.R;
    const inside: Enemy[] = [];
    for (const e of ctx.enemies) {
      if (!e.alive) continue;
      if (Math.hypot(e.group.position.x - this.cx, e.group.position.z - this.cz) <= R + e.radius) inside.push(e);
    }
    this.tickT -= dt;
    if (this.tickT <= 0) {
      this.tickT += T.tick;
      for (const e of inside) if (e.alive) ctx.damage(e, T.dps * T.tick, this.cx, this.cz, { type: 'shell', kind: 'bullet', summon: true, ult: true, top: true, knock: 0 });
    }
    // 两根转管：弹着点沿两条扫线走（转着圈、半径一呼一吸），三成曳光打在圈里的敌人身上
    for (let g = 0; g < 2; g++) {
      const a = k * 2.6 + g * Math.PI;
      const rr = R * (0.3 + 0.6 * Math.abs(Math.sin(k * 0.9 + g * 1.7)));
      const px = this.cx + Math.cos(a) * rr;
      const pz = this.cz + Math.sin(a) * rr;
      const m = this.muzzle(g);
      this.traceAcc[g] += T.trace * dt;
      while (this.traceAcc[g] >= 1) {
        this.traceAcc[g] -= 1;
        const foe = inside.length && Math.random() < 0.3 ? inside[Math.floor(Math.random() * inside.length)] : null;
        const tx = foe ? foe.group.position.x : px + rand(-1.5, 1.5);
        const tz = foe ? foe.group.position.z : pz + rand(-1.5, 1.5);
        const ty = foe ? foe.size * 0.8 : ctx.fx.groundAt(tx, tz);
        ctx.streaks.add(m.x, m.y, m.z, tx, ty, tz, 0.22, 0xffb860, 0.85, 0.06, 1.5);
        if (foe) ctx.fx.sparks(tx, ty + 0.4, tz, 3, 0xffd090, 7);
        else if (Math.random() < 0.5) ctx.fx.dirt(tx, tz, 0.5);
      }
      ctx.fx.glow.emit({ x: m.x, y: m.y, z: m.z, life: 0.05, size: rand(1.2, 2), size1: 0.6, color: 0xfff0c8, color1: 0xff8a30, frame: 0 });
      const [lx, lz] = this.sweep[g];
      const sl = Math.hypot(px - lx, pz - lz);
      if (this.grooveT <= 0 && sl > 0.5 && sl < 12) ctx.fx.groove((px + lx) / 2, (pz + lz) / 2, Math.atan2(-(px - lx), pz - lz), sl, 12);
      if (this.grooveT <= 0 || sl >= 12) this.sweep[g] = [px, pz];
    }
    this.grooveT = this.grooveT <= 0 ? 0.1 : this.grooveT - dt;
    this.brrtT -= dt;
    if (this.brrtT <= 0) {
      this.brrtT = 0.16;
      ctx.audio.play('brrt', 0.55);
    }
    // 40 毫米：每 0.4 秒点一个圈里的敌人（没有就打圈里随便一点）
    this.g40T -= dt;
    if (this.g40T <= 0) {
      this.g40T += T.g40.every;
      const e = inside.length ? inside[Math.floor(rng.weapon() * inside.length)] : null;
      const a = rng.weapon() * Math.PI * 2;
      const rr = Math.sqrt(rng.weapon()) * R * 0.8;
      this.launch(ctx, 2, e ? e.group.position.x : this.cx + Math.cos(a) * rr, e ? e.group.position.z : this.cz + Math.sin(a) * rr, 40, T.g40.flight);
    }
    // 105 毫米：每 2 秒砸圈里血最厚的那个
    this.g105T -= dt;
    if (this.g105T <= 0) {
      this.g105T += T.g105.every;
      let best: Enemy | null = null;
      for (const e of inside) if (!best || e.hp > best.hp) best = e;
      this.launch(ctx, 3, best ? best.group.position.x : this.cx, best ? best.group.position.z : this.cz, 105, T.g105.flight);
    }
  }

  /** 第 i 根炮管的炮口（世界坐标） */
  private muzzle(i: number): THREE.Vector3 {
    return this.v.copy(this.muzzles[i]).applyMatrix4(this.ship!.matrixWorld);
  }

  /** 一发炮弹：炮口到落点一道粗曳光，flight 秒后落地 */
  private launch(ctx: UltContext, gun: number, x: number, z: number, kind: 40 | 105 | 0, flight: number): void {
    const m = this.muzzle(gun);
    const y = ctx.fx.groundAt(x, z);
    const big = kind === 105 || kind === 0;
    ctx.streaks.add(m.x, m.y, m.z, x, y + 0.5, z, big ? 0.7 : 0.4, big ? 0xffd8a0 : 0xffc070, 0.9, flight + 0.05, 2);
    ctx.fx.glow.emit({ x: m.x, y: m.y, z: m.z, life: 0.1, size: big ? 5 : 3, size1: 1, color: 0xfff4d0, color1: 0xff7a20, frame: 0 });
    ctx.fx.smokeP.emit({ x: m.x, y: m.y, z: m.z, vx: rand(-1, 1), vy: rand(-0.5, 0.5), vz: rand(-1, 1), life: rand(0.8, 1.2), size: big ? 2 : 1.2, size1: big ? 5 : 3, color: 0xb8b2a8, alpha: 0.5, frame: 1, drag: 1.5 });
    ctx.audio.play(big ? 'charge' : 'shot', big ? 0.35 : 0.3, big ? 0.62 : 0.85);
    this.shells.push({ x, z, t: flight, kind });
  }

  private stepShells(ctx: UltContext): void {
    for (let i = this.shells.length - 1; i >= 0; i--) {
      const s = this.shells[i];
      s.t -= ctx.dt;
      if (s.t > 0) continue;
      this.shells.splice(i, 1);
      this.impact(ctx, s);
    }
  }

  /** 落地：40 毫米小爆、105 毫米中坑（都不掀车）；收尾那三发走掀飞档的大爆炸 */
  private impact(ctx: UltContext, s: Shell): void {
    const T = GUNSHIP;
    const A = this.A;
    const { x, z } = s;
    if (s.kind === 0) {
      const F = T.finale;
      ctx.explode(x, z, F.r * A, F.dmg, { kind: 'blast', summon: true, ult: true, knock: F.knock, pit: 2, top: true, fxScale: 1.3 });
      ctx.fx.shockwave(x, z, F.r * A * 2.2, 0xffe0b0, 0.55);
      ctx.fx.flash(x, 10, z, 7000);
      return;
    }
    const g = s.kind === 105 ? T.g105 : T.g40;
    const r = g.r * A;
    for (const e of ctx.enemies) {
      if (!e.alive) continue;
      const d = Math.hypot(e.group.position.x - x, e.group.position.z - z);
      const reach = r + e.radius;
      if (d > reach) continue;
      const k = 0.45 + (1 - d / reach) * 0.55;
      ctx.damage(e, g.dmg * k, x, z, { type: 'blast', kind: 'blast', summon: true, ult: true, top: true, knock: 2 * k });
    }
    if (s.kind === 105) {
      ctx.fx.explosion(x, z, r * 0.45, 1.4, true);
      ctx.fx.shockwave(x, z, r, 0xffe0b0, 0.4);
      ctx.dig(x, z, r * 0.55, 1.1, 0.45, r * 1.1, 0.6, 2);
      ctx.fx.crater(x, z, r * 1.4);
      ctx.cut(x, z, r * 0.6, 6);
      ctx.shake(0.3);
      ctx.audio.play('bigboom', 0.55);
      for (const [bx, bz] of ctx.barrels(x, z, r * 0.6)) ctx.detonate(bx, bz);
    } else {
      ctx.fx.explosion(x, z, r * 0.45, 1.2, true);
      ctx.fx.dirt(x, z, 1.2);
      ctx.audio.play('explode', 0.45);
    }
  }

  /** 收尾：三发 105 齐射（中心 + 左右），掀车；炮艇改平爬升 */
  private finale(ctx: UltContext): void {
    const F = GUNSHIP.finale;
    this.finaleDone = true;
    const px = -this.hz;
    const pz = this.hx;
    for (let i = 0; i < F.n; i++) {
      const o = (i - (F.n - 1) / 2) * F.spread;
      this.launch(ctx, 3, this.cx + px * o, this.cz + pz * o, 0, F.flight + i * 0.06);
    }
    ctx.flash(0.18);
    ctx.shake(0.4);
    ctx.slowmo(0.35, 0.55);
    // 齐落那一下最多 maxBreak 辆车走完整碎裂（同核弹），飞走时放开
    ctx.breaks(F.maxBreak);
    this.freed = false;
    this.flareT = 0;
    this.flareN = 0;
  }

  /** 热焰弹：爬升时两侧各撒一串，往外、往下落，拖一道白烟（像两只翅膀） */
  private stepFlares(ctx: UltContext, dt: number, t: number): void {
    const T = GUNSHIP;
    const Fl = T.flares;
    if (this.finaleDone && this.flareN < Fl.n && t < T.enter + this.fireDuration + T.ship.exit) {
      this.flareT -= dt;
      if (this.flareT <= 0) {
        this.flareT += Fl.every;
        this.flareN += 1;
        const o = this.ship!;
        for (const s of [-1, 1]) {
          const p = this.v.set(-2, -0.6, s * 4).applyMatrix4(o.matrixWorld);
          const sx = -this.hz * s;
          const sz = this.hx * s;
          this.flares.push({ x: p.x, y: p.y, z: p.z, vx: this.hx * 6 + sx * rand(9, 13), vy: rand(-1, 2), vz: this.hz * 6 + sz * rand(9, 13), t: Fl.life });
        }
        if (this.flareN === 1) ctx.audio.play('launch', 0.4, 1.4);
      }
    }
    for (let i = this.flares.length - 1; i >= 0; i--) {
      const f = this.flares[i];
      f.t -= dt;
      if (f.t <= 0) {
        this.flares.splice(i, 1);
        continue;
      }
      const drag = Math.exp(-dt * 1.6);
      f.vx *= drag;
      f.vz *= drag;
      f.vy = f.vy * drag - 7 * dt;
      f.x += f.vx * dt;
      f.y += f.vy * dt;
      f.z += f.vz * dt;
      const k = f.t / Fl.life;
      ctx.fx.glow.emit({ x: f.x, y: f.y, z: f.z, life: 0.22, size: 1.4 * (0.5 + k), size1: 0.4, color: 0xffffff, color1: 0xffa040, frame: 0 });
      if (Math.random() < 0.35) ctx.fx.smokeP.emit({ x: f.x, y: f.y, z: f.z, vy: 0.3, life: rand(1, 1.6), size: 0.6, size1: 2.2, color: 0xe8e6e0, alpha: 0.4 * k, frame: 1, drag: 1 });
    }
  }

  protected clear(): void {
    this.t = -1;
    this.finaleDone = false;
    this.shells.length = 0;
    this.flares.length = 0;
    this.traceAcc = [0, 0];
    this.sweep = [[0, 0], [0, 0]];
    this.grooveT = 0;
    if (this.ship) this.ship.visible = false;
    if (this.ring) this.ring.visible = false;
  }

  override dispose(): void {
    super.dispose();
    this.ship?.removeFromParent();
    this.ring?.removeFromParent();
    this.ring?.geometry.dispose();
    this.ring?.material.dispose();
    this.ship = null;
    this.ring = null;
  }
}
