    if (!inner) this.stats?.rx(res.msg.length);
    let packet: Envelope;
    try { packet = JSON.parse(decodePacket(res.msg)); } catch { return; }
    if (!packet || typeof packet !== 'object') return;
    if (packet.v !== ONLINE_VERSION || packet.room !== this.view.room || packet.client !== this.peer?.clientId || packet.player !== 1 - this.player || !Number.isSafeInteger(packet.seq)) return;
