import * as THREE from 'three';
import { copyGeometry } from '../GeoCache';
import { houseStyle, houseTrim } from './houseStyles';
import { SURF } from '../sceneryMaterial';
import { SCN_RICH } from '../../world/sceneryDetail';

type Point = [number, number];
type Vec = [number, number, number];
export type HousePart = 'wall' | 'roof' | 'beam' | 'base';

/** 每块保留原位置和顶点范围；断裂后仍画同一块，不换另一栋房子的模型。 */
export interface HouseChunk {
  start: number;
  count: number;
  center: THREE.Vector3;
  normal: THREE.Vector3;
  part: HousePart;
  face: number;
}

interface Surface {
  origin: Vec;
  u: Vec;
  v: Vec;
  normal: Vec;
  outline: Point[];
  columns: number;
  rows: number;
  depth: number;
  color: number;
  part: HousePart;
  face: number;
}

/** 独立的几何随机数，不消费刷怪、掉落或特效的随机序列。 */
export function houseNoise(seed: number): number {
  let n = Math.imul(seed ^ 0x45d9f3b, 0x45d9f3b);
  n = Math.imul(n ^ (n >>> 16), 0x45d9f3b);
  return ((n ^ (n >>> 16)) >>> 0) / 4294967296;
}

const rect = (x0: number, y0: number, x1: number, y1: number): Point[] =>
  [[x0, y0], [x1, y0], [x1, y1], [x0, y1]];

/** 凸多边形裁到半平面；墙块用不等距种子的 Voronoi 分区，避免规则方格断口。 */
function clip(poly: Point[], nx: number, ny: number, limit: number): Point[] {
  const out: Point[] = [];
  for (let i = 0; i < poly.length; i++) {
    const a = poly[i], b = poly[(i + 1) % poly.length];
    const da = a[0] * nx + a[1] * ny - limit, db = b[0] * nx + b[1] * ny - limit;
    if (da <= 1e-7) out.push(a);
    if ((da < 0 && db > 0) || (da > 0 && db < 0)) {
      const t = da / (da - db);
      out.push([a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t]);
    }
  }
  return out;
}

function cells(s: Surface, seed: number): Point[][] {
  const xs = s.outline.map(p => p[0]), ys = s.outline.map(p => p[1]);
  const x0 = Math.min(...xs), y0 = Math.min(...ys);
  const dx = (Math.max(...xs) - x0) / s.columns, dy = (Math.max(...ys) - y0) / s.rows;
  const sites: Point[] = [];
  for (let y = 0; y < s.rows; y++) for (let x = 0; x < s.columns; x++) {
    const n = seed + (y * s.columns + x) * 17;
    sites.push([x0 + (x + 0.15 + houseNoise(n) * 0.7) * dx, y0 + (y + 0.15 + houseNoise(n + 3) * 0.7) * dy]);
  }
  return sites.map((a, i) => {
    let poly = s.outline;
    for (let j = 0; j < sites.length && poly.length >= 3; j++) {
      if (i === j) continue;
      const b = sites[j];
      poly = clip(poly, b[0] - a[0], b[1] - a[1], (b[0] ** 2 + b[1] ** 2 - a[0] ** 2 - a[1] ** 2) / 2);
    }
    return poly;
  }).filter(p => p.length >= 3);
}

/** 农舍受击后才建薄墙、瓦片和房梁；尺寸、外墙色、屋顶轮廓沿用完整模型。 */
export function houseFracture(seed: number, look?: string): { geometry: THREE.BufferGeometry; chunks: HouseChunk[] } {
  const style = houseStyle(look);
  const positions: number[] = [], normals: number[] = [], colors: number[] = [], uvs: number[] = [], surfs: number[] = [];
  // T184 加细档：断墙也带表面类别，受击前后墙面 / 瓦面纹理一致
  let sf = 0;
  const chunks: HouseChunk[] = [];
  const color = new THREE.Color();
  const normal = new THREE.Vector3(), ab = new THREE.Vector3(), ac = new THREE.Vector3();
  const tri = (a: Vec, b: Vec, c: Vec, hex: number, uv: Point[] = [[0, 0], [1, 0], [0, 1]]) => {
    color.setHex(hex);
    ab.set(b[0] - a[0], b[1] - a[1], b[2] - a[2]);
    ac.set(c[0] - a[0], c[1] - a[1], c[2] - a[2]);
    normal.crossVectors(ab, ac).normalize();
    for (const [i, p] of [a, b, c].entries()) {
      positions.push(...p);
      normals.push(normal.x, normal.y, normal.z);
      colors.push(color.r, color.g, color.b);
      uvs.push(...uv[i]);
      surfs.push(sf);
    }
  };
  const map = (s: Surface, p: Point, depth: number): Vec => [
    s.origin[0] + s.u[0] * p[0] + s.v[0] * p[1] + s.normal[0] * depth,
    s.origin[1] + s.u[1] * p[0] + s.v[1] * p[1] + s.normal[1] * depth,
    s.origin[2] + s.u[2] * p[0] + s.v[2] * p[1] + s.normal[2] * depth,
  ];
  const polygon = (s: Surface, p: Point[], depth: number, hex: number, reverse = false) => {
    for (let i = 1; i < p.length - 1; i++) {
      const q = reverse ? [p[0], p[i + 1], p[i]] : [p[0], p[i], p[i + 1]];
      tri(map(s, q[0], depth), map(s, q[1], depth), map(s, q[2], depth), hex,
        q.map(v => [(v[0] + 3.8) / 7.6, v[1] / 6]));
    }
  };
  const surface = (s: Surface) => {
    for (const p of cells(s, seed + s.face * 691)) {
      const start = positions.length / 3;
      sf = s.part === 'wall' ? (look === 'brick' ? SURF.brick : SURF.plaster) : SURF.roof;
      polygon(s, p, 0, s.color);
      sf = 0;
      polygon(s, p, -s.depth, s.part === 'wall' ? 0x655c4e : 0x4e382b, true);
      for (let i = 0; i < p.length; i++) {
        const a = p[i], b = p[(i + 1) % p.length];
        // 前后墙包住转角；这里是完整外墙，内部分块的截面才露砖色。
        const corner = s.part === 'wall' && s.face < 2 && Math.abs(Math.abs(a[0]) - 3.5) < 1e-6 && Math.abs(a[0] - b[0]) < 1e-6;
        const edge = corner ? s.color : s.part === 'wall' ? (i % 2 ? 0x997158 : 0x8a5943) : 0x654732;
        tri(map(s, a, 0), map(s, a, -s.depth), map(s, b, -s.depth), edge);
        tri(map(s, a, 0), map(s, b, -s.depth), map(s, b, 0), edge);
      }
      // 门窗裁到各墙块上，断口里的门窗随墙一起掉，不会悬在洞中。
      for (const [i, [x0, y0, x1, y1, tint]] of houseTrim(style, s.face).entries()) {
        let q = clip(clip(p, 1, 0, x1), -1, 0, -x0);
        q = clip(clip(q, 0, 1, y1), 0, -1, -y0);
        sf = tint === 0x303a3b || tint === 0x2e3438 ? SURF.glass : SURF.wood;
        if (q.length >= 3) polygon(s, q, look ? .012 + i * .0005 : .071, tint);
        sf = 0;
      }
      const center: Point = [p.reduce((n, v) => n + v[0], 0) / p.length, p.reduce((n, v) => n + v[1], 0) / p.length];
      chunks.push({ start, count: positions.length / 3 - start, center: new THREE.Vector3(...map(s, center, -s.depth / 2)),
        normal: new THREE.Vector3(...s.normal), part: s.part, face: s.face });
    }
  };
  const box = (size: Vec, at: Vec, hex: number, part: HousePart) => {
    const source = new THREE.BoxGeometry(...size);
    const g = copyGeometry(source);
    source.dispose();
    g.translate(...at);
    const start = positions.length / 3;
    const p = g.getAttribute('position'), n = g.getAttribute('normal'), uv = g.getAttribute('uv');
    color.setHex(hex);
    for (let i = 0; i < p.count; i++) {
      positions.push(p.getX(i), p.getY(i), p.getZ(i));
      normals.push(n.getX(i), n.getY(i), n.getZ(i));
      colors.push(color.r, color.g, color.b);
      uvs.push(uv.getX(i), uv.getY(i));
      surfs.push(part === 'base' ? SURF.stone : part === 'beam' ? SURF.wood : SURF.brick);
    }
    chunks.push({ start, count: p.count, center: new THREE.Vector3(...at), normal: new THREE.Vector3(0, 1, 0), part, face: -1 });
    g.dispose();
  };

  box([7.2, .4, 5.8], [0, .2, 0], 0x6a5e4c, 'base');
  const wall = { v: [0, 1, 0] as Vec, rows: 4, depth: .28, color: style.wall, part: 'wall' as const };
  surface({ ...wall, origin: [0, 0, 2.8], u: [1, 0, 0], normal: [0, 0, 1], outline: rect(-3.5, .4, 3.5, style.eave), columns: 8, face: 0 });
  surface({ ...wall, origin: [0, 0, -2.8], u: [-1, 0, 0], normal: [0, 0, -1], outline: rect(-3.5, .4, 3.5, style.eave), columns: 8, face: 1 });
  surface({ ...wall, origin: [3.5, 0, 0], u: [0, 0, -1], normal: [1, 0, 0], outline: rect(-2.52, .4, 2.52, style.eave), columns: 6, face: 2 });
  surface({ ...wall, origin: [-3.5, 0, 0], u: [0, 0, 1], normal: [-1, 0, 0], outline: rect(-2.52, .4, 2.52, style.eave), columns: 6, face: 3 });
  const rise = 6 - style.eave, length = Math.hypot(rise, 2.95);
  for (const sign of [1, -1]) {
    surface({ origin: [0, style.eave, sign * 3.1], u: [sign, 0, 0], v: [0, rise / length, -sign * 2.95 / length],
      normal: [0, 2.95 / length, sign * rise / length], outline: [[-3.8, 0], [3.8, 0], [style.ridgeX, length], [-style.ridgeX, length]],
      columns: 7, rows: 3, depth: .16, color: style.roof, part: 'roof', face: sign > 0 ? 4 : 5 });
    const hip = 3.8 - style.ridgeX, hipLength = Math.hypot(rise, hip);
    surface({ origin: [sign * 3.8, style.eave, 0], u: [0, 0, -sign], v: [-sign * hip / hipLength, rise / hipLength, 0],
      normal: [sign * rise / hipLength, hip / hipLength, 0],
      outline: [[-3.1, 0], [3.1, 0], [.15, hipLength], [-.15, hipLength]], columns: 5, rows: 2,
      depth: .18, color: style.gable ?? style.roof, part: 'roof', face: sign > 0 ? 6 : 7 });
  }
  surface({ origin: [0, 6, .15], u: [1, 0, 0], v: [0, 0, -1], normal: [0, 1, 0], outline: rect(-style.ridgeX, 0, style.ridgeX, .3),
    columns: 5, rows: 1, depth: .16, color: style.roof, part: 'roof', face: 8 });
  for (const x of [-2.4, 0, 2.4]) box([.18, .22, 5.6], [x, style.eave - .18, 0], 0x5a4530, 'beam');
  // 屋脊梁分三段，局部塌顶时只落下失去支撑的一段。
  const ridgeBeam = (style.ridgeX * 2 - .55) / 3;
  for (const x of [-ridgeBeam, 0, ridgeBeam]) box([ridgeBeam, .22, .2], [x, 5.7, 0], 0x5a4530, 'beam');
  for (const y of [4.65, 5.75]) box([.7, 1.1, .7], [2.2, y, .8], 0x8a7b68, 'roof');

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3).setUsage(THREE.DynamicDrawUsage));
  geometry.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3).setUsage(THREE.DynamicDrawUsage));
  geometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3).setUsage(THREE.DynamicDrawUsage));
  geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  if (SCN_RICH) geometry.setAttribute('surf', new THREE.Float32BufferAttribute(surfs, 1));
  // 碎块只在房屋周围落地；固定保守包围球，动画中不用逐帧扫描全部顶点。
  geometry.boundingSphere = new THREE.Sphere(new THREE.Vector3(0, 2, 0), 15);
  return { geometry, chunks };
}
