/**
 * T184 场景加细试验档：建筑 / 树木 / 草丛的面数倍数（网页默认 5，微信按画质高 3 / 中 2 / 低 1）。
 * `?scnx=1` 回到原模型、原材质、原阴影（对照用）；`?scnx=N`（2～40）按 N/5 缩放同一套加细模型的分段数，找性能拐点。
 * 只改外观，不碰结构值、碰撞、挡弹、奖励。
 */
function param(key: string): string | null {
  try {
    return new URLSearchParams(location.search).get(key);
  } catch { /* 小游戏没有 location：用默认档 */ }
  return null;
}
function read(): number {
  const v = Number(param('scnx'));
  return Number.isFinite(v) && v >= 1 && v <= 40 ? v : __WX__ ? 2 : 5;
}

export let SCN_DETAIL = read();
/** 加细模型开着（倍数 > 1） */
export let SCN_RICH = SCN_DETAIL > 1;
/** 分段倍率：5 倍档 = 1 */
export let SCN_TESS = SCN_DETAIL / 5;
/** 程序纹理材质（拆分性能用：`?scnmat=0` 加细模型仍用原顶点色材质） */
export let SCN_MAT = SCN_RICH && param('scnmat') !== '0';
/** 高档阴影贴图边长（拆分性能用：`?scnshadow=2048` 只换回原阴影分辨率） */
export const SCN_SHADOW_HIGH = __WX__ ? 2048 : Number(param('scnshadow')) >= 512 ? Number(param('scnshadow')) : SCN_RICH ? 4096 : 2048;

/** 地址里写了 ?scnx（对照 / 找拐点用）：倍数固定，不跟画质换 */
const PINNED = param('scnx') !== null && Number.isFinite(Number(param('scnx')));

/**
 * 各画质档的面数倍数（T245）：微信高 3 / 中 2 / 低 1；网页高 5 同改前，中 3（= 微信高档那套）、低 2。
 * 网页中 / 低档仍是加细模型和同一个材质，只是分段少；固定时用地址里的数
 */
export function sceneryDetailFor(quality: 'high' | 'medium' | 'low'): number {
  if (PINNED) return read();
  const [high, medium, low] = __WX__ ? [3, 2, 1] : [5, 3, 2];
  return quality === 'high' ? high : quality === 'medium' ? medium : low;
}

export function setSceneryDetail(detail: number): void {
  (globalThis as { __SCN_DETAIL__?: number }).__SCN_DETAIL__ = detail;
  SCN_DETAIL = detail;
  SCN_RICH = detail > 1;
  SCN_TESS = detail / 5;
  SCN_MAT = SCN_RICH && param('scnmat') !== '0';
}

setSceneryDetail(SCN_DETAIL);
