const ease = (k: number) => 1 - (1 - k) * (1 - k);

/** 抖一下（没装好 / 生效中点了终极）：0.32 秒左右晃 */
function shake(t: number): number {
  if (t >= 1) return 0;
  const keys = [0, 0, 0.2, -5, 0.45, 4, 0.7, -3, 1, 0];
  for (let i = 2; i < keys.length; i += 2) {
    if (t <= keys[i]) {
      const k = (t - keys[i - 2]) / (keys[i] - keys[i - 2]);
      return keys[i - 1] + (keys[i + 1] - keys[i - 1]) * k;
    }
  }
  return 0;
}

