  constructor(private readonly ov: Overlay) {
    this.sheet = new Sheet(ov);
    this.workshop = new CanvasSubWorkshop(ov, id => this.onWorkshopAction?.(id));
    this.pickGuard = new PickGuard(ov.fingers);
    this.pBanner = ov.panel('banner', 3, (c, w, h) => this.paintBanner(c, w, h));
    this.pSky = ov.panel('sky-card', 4, (c, w, h) => this.paintSkyCard(c, w, h));
    this.pVig = ov.panel('vignette', 1, (c, w, h) => {
      const g = c.createRadialGradient(w / 2, h / 2, w * 0.22, w / 2, h / 2, w / 2);
      g.addColorStop(0, 'rgba(0, 0, 0, 0)');
      g.addColorStop(1, 'rgba(0, 0, 0, 0.55)');
      c.fillStyle = g;
      c.fillRect(0, 0, w, h);
    });
    this.pHint = ov.panel('hint', 3, (c, w) => this.paintHint(c, w));
    this.pPrompt = ov.panel('prompt', 3, (c, w) => this.paintPrompt(c, w));
    this.pRing = ov.panel('ring', 3, (c, w) => this.paintRing(c, w));
    this.pBars = ov.panel('bars', 5, (c) => this.paintBars(c));
    this.pBars.interval = 1 / 15;
    this.pSlots = ov.panel('slots', 5, (c) => this.paintSlots(c));
    this.pSupBar = ov.panel('super-bar', 5, (c) => this.paintSupBar(c));
    this.pSupList = ov.panel('super-list', 8, (c, w, h) => this.paintSupList(c, w, h));
    this.pUltRow = ov.panel('ult-row', 5, (c) => this.paintUltRow(c));
    this.pUltRow.interval = 1 / 15;
    this.pElite = ov.panel('elite', 5, (c, w) => this.paintElite(c, w));
    this.pElite.interval = 1 / 15;
    this.pMark = ov.panel('ult-mark', 5, (c, w, h) => this.paintMark(c, w, h));
    this.pTwin.push(
      ov.panel('twin-l', 3, (c, w, h) => this.paintTwinHint(c, w, h, '拖动走位', '')),
      ov.panel('twin-r', 3, (c, w, h) => this.paintTwinHint(c, w, h, this.twinVulcan ? '按住一直打' : this.twinLaser ? '按住出光' : '拖动瞄准', this.twinVulcan ? '拖动瞄准' : this.twinLaser ? '拖动扫射' : '松手开炮')),
      ov.panel('twin-ring', 3, (c, w, h) => this.paintTwinRing(c, w, h)),
      ov.panel('twin-knob', 3, (c, w, h) => this.paintTwinKnob(c, w, h)),
    );
    for (let i = 0; i < 3; i++) {
      this.pArty.push(ov.panel(`arty${i}`, 7, (c, w, h) => this.paintArty(c, w, h, i)));
      this.artyKey.push('');
    }
    this.pIntel = ov.panel('intel', 5, (c, w, h) => this.paintIntel(c, w, h));
    this.pAch = ov.panel('ach-toast', 6, (c, w, h) => this.paintAch(c, w, h));
    this.pUltKey = ov.panel('ult-key', 6, (c, w) => this.paintUltKey(c, w));
    this.pUltKey.interval = 1 / 20;
    this.pRepBtn = ov.panel('report-btn', 6, (c, w, h) => this.paintRepBtn(c, w, h));
    this.pReport = ov.panel('report', 6, (c, w, h) => this.paintReportPanel(c, w, h));
    this.pTip = ov.panel('slot-tip', 8, (c) => this.tip && paintTip(c, this.tip));
    this.pUltTip = ov.panel('ult-tip', 8, (c) => this.ultTip && paintTip(c, this.ultTip));
    this.pModal = ov.panel('hud-modal', 10, (c, w, h) => {
      // 抢修复活卡（T030）：画面冻结着、压一层暗褐的半透明（看得见被围的局面；警示色用暖色，不用血红），其余浮层照旧
      if (this.mode === 'revive' && !UI_SKIN) {
        const g = c.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.2, w / 2, h / 2, Math.max(w, h) * 0.7);
        g.addColorStop(0, 'rgba(10, 8, 8, 0.55)');
        g.addColorStop(1, 'rgba(48, 22, 8, 0.82)');
        c.fillStyle = g;
        c.fillRect(0, 0, w, h);
      } else backdrop(c, w, h);
      // 选卡（T058）：弹窗挪到耐久块下面以后，压在后面的那行数字和槽位条再暗一层（网页版靠模糊），耐久块照旧
      if (this.mode === 'levelup' && w >= 560 && w > h) {
        c.fillStyle = '#0d1715';
        c.fillRect(0, 0, w, h);
      } else if (this.mode === 'levelup') {
        const y = this.ov.insets.top + CARD_TOP - 12;
        const g = c.createLinearGradient(0, y - 6, 0, y);
        g.addColorStop(0, 'rgba(8, 10, 14, 0)');
        g.addColorStop(1, 'rgba(8, 10, 14, 0.6)');
        c.fillStyle = g;
        c.fillRect(0, y - 6, w, 6);
        c.fillStyle = 'rgba(8, 10, 14, 0.6)';
        c.fillRect(0, y, w, h - y);
      }
      this.sheet.paint(c);
    });
    for (let i = 0; i < 3; i++) {
      const uniforms = { gain: { value: 1 }, box: { value: new Vector4() }, size: { value: new Vector2() }, cut: { value: 9 }, band: { value: -1 }, sweep: { value: 0 } };
      this.pRare.push(ov.panel(`rare-glow${i}`, 10.2, (c) => this.paintRareGlow(c, i), { frag: RARE_FRAG, uniforms, blending: AdditiveBlending }));
    }
    const add = { frag: ADD_FRAG, blending: AdditiveBlending };
    for (let i = 0; i < 3; i++) {
      const uniforms = { gain: { value: 1 }, box: { value: new Vector4() }, size: { value: new Vector2() }, cut: { value: 2 }, bar: { value: SUPER_PLATE.bar }, band: { value: -1 }, sweep: { value: 0 }, flash: { value: 0 } };
      this.pSuper.push({
        card: ov.panel(`super-card${i}`, 10.15, (c) => this.paintSuperPanel(c, i, false)),
        glow: ov.panel(`super-glow${i}`, 10.2, (c) => this.paintSuperPanel(c, i, true), { frag: SUPER_FRAG, uniforms, blending: AdditiveBlending }),
        down: false,
      });
    }
    this.pSuperIn = {
      flash: ov.panel('super-in-flash', 10.05, (c, w, h) => this.paintSuperIn(c, w, h, 'flash'), add),
      streak: ov.panel('super-in-streak', 10.3, (c, w, h) => this.paintSuperIn(c, w, h, 'streak'), add),
      title: ov.panel('super-in-title', 10.3, (c, w, h) => this.paintSuperIn(c, w, h, 'title'), add),
    };
    this.pSuperBurst = {
      screen: ov.panel('super-screen', 10.25, (c, w, h) => this.paintBurst(c, w, h, 'screen'), add),
      ring: ov.panel('super-ring', 10.55, (c, w, h) => this.paintBurst(c, w, h, 'ring'), add),
      flareV: ov.panel('super-flare-v', 10.6, (c, w, h) => this.paintBurst(c, w, h, 'flareV'), add),
    };
    this.pIntro = ov.panel('super-intro', 10.7, (c, w, h) => this.paintSuperIntro(c, w, h));
    this.pBurst = {
      wave: ov.panel('rare-wave', 10.3, (c, w, h) => this.paintBurst(c, w, h, 'wave'), add),
      ghost: ov.panel('rare-ghost', 10.4, (c, w, h) => this.paintBurst(c, w, h, 'ghost')),
      tag: ov.panel('rare-tag', 10.45, (c, w, h) => this.paintBurst(c, w, h, 'tag')),
      flash: ov.panel('rare-flash', 10.5, (c, w, h) => this.paintBurst(c, w, h, 'flash'), add),
      flare: ov.panel('rare-flare', 10.6, (c, w, h) => this.paintBurst(c, w, h, 'flare'), add),
    };
    ov.onFrame((dt) => this.frame(dt));
  }

