  private paintAch(ctx: Ctx, w: number, h: number): void {
    const a = this.achNow;
    if (!a) return;
    const t = this.achT;
    armorSurface(ctx, 0, 0, w, h, '#aa9768');
    ctx.font = font(10, 700);
    if (a.plate) {
      text(ctx, '解锁称号', 12, 14, '#ffcf6a', 'left', 2);
      const drop = Math.max(0, 1 - t / 0.35);
      ctx.save();
      ctx.globalAlpha = 1 - drop;
      paintPlate(ctx, 12, 24 - drop * 18, 24, a.plate, a.name, 14);
      ctx.restore();
      return;
    }
    if (a.head) {
      const cx = 6 + 23;
      const cy = h / 2;
      const sc = Math.min(1, t / 0.3);
      ctx.save();
      ctx.translate(cx, cy);
      ctx.scale(sc, sc);
      ctx.beginPath();
      ctx.arc(0, 0, 22, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(60, 46, 18, 0.95)';
      ctx.fill();
      ctx.lineWidth = 1.5;
      ctx.strokeStyle = '#ffcf6a';
      ctx.stroke();
      icon(ctx, a.icon, -13, -13, 26, '#ffe08a', 1.8);
      ctx.restore();
      ctx.font = font(10, 700);
      text(ctx, a.head, 58, 18, '#ffcf6a', 'left', 2);
      ctx.font = font(14, 700);
      text(ctx, ellipsize(ctx, a.name, w - 66), 58, 37, '#f2ead8');
      return;
    }
    // 勋章：先翻进来（横向从 0 拉到 1），再一道高光扫过
    const cx = 6 + 23;
    const cy = h / 2;
    const flip = Math.min(1, t / 0.4);
    ctx.save();
    ctx.translate(cx, cy);
    ctx.scale(Math.max(0.05, Math.sin((flip * Math.PI) / 2)), 1);
    paintMedal(ctx, 0, 0, 22, a.tier, a.icon, true);
    ctx.restore();
    const sw = (t - 0.35) / 0.7;
    if (sw > 0 && sw < 1) {
      ctx.save();
      ctx.beginPath();
      ctx.arc(cx, cy, 22, 0, Math.PI * 2);
      ctx.clip();
      const sx = cx - 30 + sw * 60;
      const sg = ctx.createLinearGradient(sx - 10, 0, sx + 10, 0);
      sg.addColorStop(0, 'rgba(255, 255, 255, 0)');
      sg.addColorStop(0.5, 'rgba(255, 255, 255, 0.75)');
      sg.addColorStop(1, 'rgba(255, 255, 255, 0)');
      ctx.fillStyle = sg;
      ctx.fillRect(cx - 22, cy - 22, 44, 44);
      ctx.restore();
    }
    text(ctx, '成就达成', 58, 18, '#ffcf6a', 'left', 2);
    ctx.font = font(14, 700);
    text(ctx, ellipsize(ctx, a.name, w - 66), 58, 37, '#f2ead8');
  }

  /** 联动卡打出（D4 / 汇总第 27 条）：两件副武器的格子之间拉一道铜色电弧 1.4 秒（paintSlots 里画） */
