  setSlots(slots: SlotView[]): void {
    this.slots = slots;
    const key = slots.map((s) => `${s.kind}:${s.icon}:${s.level}:${s.evolved}:${s.ult}:${s.ready}:${s.link ?? ''}:${s.note ?? ''}:${s.slot}:${s.uid}:${s.locked}`).join('|');
    if (key === this.slotsKey) return;
    this.slotsKey = key;
    this.fusable = slots.some((s) => s.ready);
    this.pSlots.dirty = true;
    if (this.tipIndex >= 0) this.toggleTip(this.tipIndex, true);
  }

  setUlt(v: UltView | null, visible: boolean, slide = false): void {
    if (!v) {
      this.ult = null;
      this.ultVisible = false;
      this.showUltKey(false);
      return;
    }
    this.ult = { ...v };
    if (slide) this.ultSlide = 0;
    this.ultVisible = visible;
    this.showUltKey(visible);
    const p = v.state === 'ready' ? 1 : v.progress;
    const key = `${v.id}|${v.state}|${v.label}|${Math.round(p * 400)}`;
    if (key !== this.ultKey) {
      this.ultKey = key;
      this.pUltRow.dirty = true;
      this.pUltKey.dirty = true;
    }
  }

