  /**
   * 结算页「本局解锁」的勋章一排（T038，和 DOM 版 #go-medals 一样）：最多两行 × 7，一枚一枚翻出来（从侧面翻正 + 放大回弹）+ 翻正后一道高光扫过，金 / 鎏金带光晕；
   * 多出来的写「+N」。翻的时候整张结算页每帧重画（bounceUntil），翻完就停
   */
  private medalRow(list: NonNullable<GameOverExtra['medals']>): Block {
    const R = MEDAL_ROW;
    const shown = list.slice(0, list.length > R.max ? R.max - 1 : R.max);
    const more = list.length - shown.length;
    const n = shown.length + (more ? 1 : 0);
    const rows = Math.ceil(n / R.perRow);
    const S = 36;
    const G = 6;
    this.bounceUntil = Math.max(this.bounceUntil, this.goT0 + R.delay + n * R.gap + R.flip + R.sweep);
    return {
      h: rows * S + (rows - 1) * G,
      gap: 6,
      paint: (c, w) => {
        for (let i = 0; i < n; i++) {
          const row = Math.floor(i / R.perRow);
          const inRow = Math.min(R.perRow, n - row * R.perRow);
          const cx = w / 2 + ((i % R.perRow) - (inRow - 1) / 2) * (S + G);
          const cy = row * (S + G) + S / 2;
          const t = this.ov.now - this.goT0 - (R.delay + i * R.gap);
          if (t <= 0) continue;
          const k = Math.min(1, t / R.flip);
          const sc = k < 0.6 ? 0.6 + (1.12 - 0.6) * (k / 0.6) : 1.12 - 0.12 * ((k - 0.6) / 0.4);
          c.save();
          c.globalAlpha = Math.min(1, k / 0.6);
          c.translate(cx, cy);
          c.scale(sc * Math.max(0.05, Math.sin((Math.min(1, k / 0.6) * Math.PI) / 2)), sc);
          if (i >= shown.length) {
            c.beginPath();
            c.arc(0, 0, S / 2, 0, Math.PI * 2);
            c.fillStyle = 'rgba(40, 30, 12, 0.8)';
            c.fill();
            c.strokeStyle = 'rgba(255, 207, 106, 0.5)';
            c.stroke();
            c.font = font(12, 800);
            text(c, `+${more}`, 0, 0, '#ffd98a', 'center');
            c.restore();
            continue;
          }
          const m = shown[i];
          if (m.tier === 'gold' || m.tier === 'gilt') shadow(c, 'rgba(255, 210, 110, 0.6)', 10);
          paintMedal(c, 0, 0, S / 2, m.tier, m.icon, true);
          c.restore();
          const sw = (t - R.flip * 0.85) / R.sweep;
          if (sw > 0 && sw < 1) {
            c.save();
            c.beginPath();
            c.arc(cx, cy, S / 2, 0, Math.PI * 2);
            c.clip();
            const sx = cx - S * 0.7 + sw * S * 1.4;
            const sg = c.createLinearGradient(sx - 8, 0, sx + 8, 0);
            sg.addColorStop(0, 'rgba(255, 255, 255, 0)');
            sg.addColorStop(0.5, 'rgba(255, 255, 255, 0.8)');
            sg.addColorStop(1, 'rgba(255, 255, 255, 0)');
            c.fillStyle = sg;
            c.fillRect(cx - S / 2, cy - S / 2, S, S);
            c.restore();
          }
        }
      },
    };
  }

