import type { GamepadInput, PadDirection } from '../core/GamepadInput';
import type { Overlay, Panel, Rect } from './canvas/Overlay';
import { padBattleHint } from './ctrlText';

interface PadTarget {
  id: string;
  rect: () => Rect;
  activate: () => void;
  reveal?: () => void;
  back: boolean;
}

interface PadMenu {
  id: string;
  targets: PadTarget[];
  scroll?: (amount: number) => void;
}

const BACK_IDS = new Set(['sub-back', 'confirm-cancel', 'main-back', 'multiplayer-back', 'prepare-back', 'deploy-back', 'hub-back', 'prep-exit-no', 'ad-close', 'shot-close', 'ranks-close', 'route-back', 'route-close', 'title-set-back', 'settings-back-btn', 'set-back', 'bgm-back', 'save:close', 'save:cancel', 'save:back', 'resume-btn', 'resume', 'menu-btn', 'menu']);
const FIRST_IDS = ['confirm-cancel', 'prep-exit-no', 'card:0', 'single-btn', 'single', 'hub-continue', 'hub:continue', 'start-btn', 'start', 'deploy-btn', 'deploy', 'resume-btn', 'resume', 'revive-btn', 'revive', 'restart'];

function visible(el: HTMLElement): boolean {
  return !el.closest('.hidden, [hidden]') && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== 'hidden';
}

/** 手柄只调用现有按钮。选卡防误触、换卡次数、购买确认仍由原界面处理。 */
export class GamepadUi {
  enabled = true;
  activating = false;
  private menuId = '';
  private selected = '';
  private target: PadTarget | null = null;
  private caption = '';
  private hint = '';
  private hintEl: HTMLElement | null = null;
  private focusEl: HTMLElement | null = null;
  private hintPanel: Panel | null = null;
  private focusPanel: Panel | null = null;
  private inBattle = false;
  private disposed = false;
  private keyboard = false;
  private phase = 'title';

  constructor(private readonly pad: GamepadInput, private readonly overlay: Overlay | null, private readonly acceptsKeyboard = true) {
    document.addEventListener('keydown', this.onKey, true);
    document.addEventListener('pointerdown', this.onPointer, true);
  }

  /** 右杆只有聚焦展示区时才环视；列表聚焦时用于滚动。 */
  get orbitFocused(): boolean {
    return this.selected === 'core-pick' || this.selected === 'core-stage' || this.selected.startsWith('core:');
  }

  private readonly onPointer = () => { this.keyboard = false; };

  private readonly onKey = (event: KeyboardEvent) => {
    if (!this.enabled || !this.acceptsKeyboard || this.disposed || this.phase === 'running' || event.altKey || event.ctrlKey || event.metaKey) return;
    if ((event.target as HTMLElement)?.matches?.('input, textarea, select, [contenteditable="true"]')) return;
    const directions: Record<string, PadDirection> = { ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right' };
    if (!directions[event.key] && !['Enter', ' ', 'Escape', 'Tab', 'PageUp', 'PageDown'].includes(event.key)) return;
    const menu = this.readMenu();
    if (!menu) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    if (event.repeat && ['Enter', ' ', 'Escape'].includes(event.key)) return;
    this.keyboard = true;
    this.menuId = `${this.phase}:${menu.id}`;
    const focused = !this.overlay && document.activeElement?.id;
    this.target = menu.targets.find(t => t.id === focused) ?? menu.targets.find(t => t.id === this.selected)
      ?? FIRST_IDS.map(id => menu.targets.find(t => t.id === id)).find(Boolean) ?? menu.targets[0] ?? null;
    this.selected = this.target?.id ?? '';
    if (directions[event.key]) this.navigate(menu.targets, directions[event.key]);
    else if (event.key === 'Tab') {
      const i = menu.targets.findIndex(t => t.id === this.selected);
      this.target = menu.targets[(i + (event.shiftKey ? -1 : 1) + menu.targets.length) % menu.targets.length] ?? null;
      this.selected = this.target?.id ?? '';
      this.target?.reveal?.();
    }
    else if (event.key === 'PageUp' || event.key === 'PageDown') menu.scroll?.(event.key === 'PageUp' ? -280 : 280);
    else if (event.key === 'Escape') {
      const back = menu.targets.find(t => t.back);
      if (back) this.activate(back);
    } else if (this.target) this.activate(this.target);
    this.createView();
    this.drawView();
  };

  /** 返回 true 时由游戏按原流程暂停。 */
  update(phase: string, dt: number): boolean {
    if (!this.enabled) {
      this.target = null;
      this.keyboard = false;
      if (this.hintEl) this.hintEl.hidden = true;
      if (this.focusEl) this.focusEl.hidden = true;
      if (this.hintPanel) this.hintPanel.visible = false;
      if (this.focusPanel) this.focusPanel.visible = false;
      return false;
    }
    this.phase = phase;
    const pad = this.pad;
    this.inBattle = phase === 'running';
    const padActive = pad.active && pad.index !== null;
    const active = padActive || this.keyboard;
    const menu = active && phase !== 'running' ? this.readMenu() : null;
    const id = `${phase}:${menu?.id ?? ''}`;
    if (id !== this.menuId) {
      this.menuId = id;
      this.selected = '';
      this.target = null;
      // 菜单里按着方向切到另一页，先回中；战斗按钮不带进选卡。
      if (padActive) pad.suspend();
    }
    this.target = menu?.targets.find(t => t.id === this.selected) ?? null;
    if (active && menu && !this.target) {
      this.target = FIRST_IDS.map(key => menu.targets.find(t => t.id === key)).find(Boolean) ?? menu.targets[0] ?? null;
      this.selected = this.target?.id ?? '';
    }
    if (padActive && menu) {
      if (pad.direction) this.navigate(menu.targets, pad.direction);
      if (pad.scroll && !this.orbitFocused) menu.scroll?.(pad.scroll * dt * 520);
      if (pad.cancel || pad.pause) {
        const back = menu.targets.find(t => t.back);
        if (back) this.activate(back);
      } else if (pad.confirm && this.target) this.activate(this.target);
    }
    const pause = padActive && pad.pause && phase === 'running';
    if (pause) pad.suspend();
    if (!active) this.target = null;
    this.caption = padActive ? pad.label : '';
    this.hint = padActive
      ? pad.waiting ? '松开按键，摇杆回中'
        : phase === 'running' ? padBattleHint()
          : pad.family === 'nintendo' ? '右键确认 · 下键返回' : pad.family === 'sony' ? '× 确认 · ○ 返回' : '下键确认 · 右键返回'
      : performance.now() < pad.noticeUntil ? pad.notice : '';
    if (this.hint) this.createView();
    this.drawView();
    return pause;
  }

  private activate(target: PadTarget): void {
    // 在回调之前清状态，回调可能直接开始下一局或连着弹下一组选项。
    this.pad.suspend();
    this.target = null;
    this.activating = true;
    try { target.activate(); } finally { this.activating = false; }
  }

  private navigate(targets: PadTarget[], direction: PadDirection): void {
    const current = this.target;
    if (!current || targets.length < 2) return;
    const from = current.rect();
    const horizontal = direction === 'left' || direction === 'right';
    const sign = direction === 'left' || direction === 'up' ? -1 : 1;
    let next: PadTarget | null = null;
    let best = Infinity;
    for (const t of targets) {
      if (t.id === current.id) continue;
      const r = t.rect();
      const dx = r.x + r.w / 2 - from.x - from.w / 2;
      const dy = r.y + r.h / 2 - from.y - from.h / 2;
      const along = (horizontal ? dx : dy) * sign;
      if (along <= 3) continue;
      const across = Math.abs(horizontal ? dy : dx);
      const score = along + across * 2.5;
      if (score < best) { best = score; next = t; }
    }
    // 到边沿后循环，滚动区外的按钮也能逐个到达。
    if (!next) {
      const i = targets.findIndex(t => t.id === current.id);
      next = targets[(i + sign + targets.length) % targets.length];
    }
    this.target = next;
    this.selected = next.id;
    next.reveal?.();
  }

  private readMenu(): PadMenu | null {
    if (this.overlay) {
      const menu = this.overlay.gamepadMenu();
      if (!menu) return null;
      const targets: PadTarget[] = menu.regions.map(r => ({
        id: r.id,
        rect: () => this.overlay!.rect(r.id) ?? r,
        activate: () => { if (!r.ready || r.ready()) r.tap?.(); },
        back: BACK_IDS.has(r.id),
      }));
      // 同一个画布面板承载开始、设置和图鉴，返回键能区分当前子页。
      const back = targets.find(t => t.back)?.id ?? targets[0]?.id ?? '';
      return { id: `${menu.id}:${back}`, targets, scroll: amount => this.overlay!.menuScroll?.(amount) };
    }
    const roots = [...document.querySelectorAll<HTMLElement>('.overlay')].filter(visible);
    const root = roots.reduce<HTMLElement | null>((top, el) => !top || Number(getComputedStyle(el).zIndex) >= Number(getComputedStyle(top).zIndex) ? el : top, null);
    if (!root) return null;
    const elements = [...root.querySelectorAll<HTMLElement>('button, a.btn, [role="button"], summary')]
      .filter(el => visible(el) && !el.matches(':disabled, [aria-disabled="true"]') && getComputedStyle(el).pointerEvents !== 'none');
    let card = 0;
    const targets: PadTarget[] = elements.map((el, i) => ({
      id: el.id || (el.classList.contains('card') ? `card:${card++}` : `item:${i}`),
      rect: () => {
        const r = el.getBoundingClientRect();
        return { x: r.x, y: r.y, w: r.width, h: r.height };
      },
      activate: () => el.click(),
      reveal: () => { el.focus({ preventScroll: true }); el.scrollIntoView({ block: 'nearest', inline: 'nearest' }); },
      back: BACK_IDS.has(el.id) || /^(关闭|返回|取消|接着选)$/.test(el.textContent?.trim() ?? '')
        || (root.id === 'save-box' && el.textContent?.trim() === '好'),
    }));
    const sub = root.id === 'pause' && root.querySelector('.pause-main.hidden') ? ':settings'
      : root.id === 'title' ? root.classList.contains('preparing') ? ':prepare' : root.classList.contains('main-screen') ? ':main' : ':single' : '';
    return {
      id: root.id + sub,
      targets,
      scroll: amount => {
        const body = [...root.querySelectorAll<HTMLElement>('.route-body, .prepare-config, .home-menu')].find(visible);
        const scroller = body && body.scrollHeight > body.clientHeight && /auto|scroll/.test(getComputedStyle(body).overflowY) ? body : root;
        scroller.scrollTop += amount;
      },
    };
  }

  private createView(): void {
    if (this.hintEl || this.hintPanel) return;
    if (this.overlay) {
      this.hintPanel = this.overlay.panel('gamepad-hint', 40, (ctx, w, h) => {
        ctx.fillStyle = 'rgba(15, 23, 22, 0.94)';
        ctx.fillRect(0, 0, w, h);
        ctx.strokeStyle = '#9c875e';
        ctx.strokeRect(0.5, 0.5, w - 1, h - 1);
        ctx.font = '600 11px -apple-system, "PingFang SC", sans-serif';
        ctx.fillStyle = '#c0b796';
        ctx.fillText(this.caption || '手柄', 10, 16);
        ctx.font = '13px -apple-system, "PingFang SC", sans-serif';
        ctx.fillStyle = '#f0ead8';
        ctx.fillText(this.hint, 10, 35);
      });
      this.focusPanel = this.overlay.panel('gamepad-focus', 39, (ctx, w, h) => {
        ctx.strokeStyle = '#f3d58e';
        ctx.lineWidth = 2;
        ctx.strokeRect(2, 2, w - 4, h - 4);
      });
      this.overlay.onFrame(() => { if (!this.disposed) this.drawView(); });
    } else {
      this.hintEl = document.createElement('div');
      this.hintEl.id = this.acceptsKeyboard ? 'gamepad-hint' : 'gamepad-hint-two';
      this.hintEl.className = 'gamepad-hint';
      this.hintEl.setAttribute('role', 'status');
      this.hintEl.setAttribute('aria-live', 'polite');
      this.focusEl = document.createElement('div');
      this.focusEl.id = this.acceptsKeyboard ? 'gamepad-focus' : 'gamepad-focus-two';
      this.focusEl.className = 'gamepad-focus';
      this.focusEl.setAttribute('aria-hidden', 'true');
      document.body.append(this.hintEl, this.focusEl);
    }
  }

  private drawnText = '';

  private drawView(): void {
    if (!this.enabled) {
      if (this.hintEl) this.hintEl.hidden = true;
      if (this.focusEl) this.focusEl.hidden = true;
      if (this.hintPanel) this.hintPanel.visible = false;
      if (this.focusPanel) this.focusPanel.visible = false;
      return;
    }
    const text = `${this.caption || '手柄'}\n${this.hint}`;
    if (this.hintEl) {
      this.hintEl.hidden = !this.hint;
      this.hintEl.classList.toggle('in-battle', this.inBattle);
      if (this.drawnText !== text) this.hintEl.textContent = text;
    }
    if (this.hintPanel && this.overlay) {
      this.hintPanel.visible = !!this.hint;
      const bottom = this.inBattle && this.overlay.W >= 720 ? 88 : 12;
      this.hintPanel.place(this.overlay.insets.left + 12, this.overlay.H - this.overlay.insets.bottom - bottom - 46, Math.min(248, this.overlay.W - 24), 46);
      if (this.drawnText !== text) this.hintPanel.dirty = true;
    }
    this.drawnText = text;
    const r = this.target?.rect();
    const show = !!r && r.w > 0 && r.h > 0;
    if (this.focusEl) {
      this.focusEl.hidden = !show;
      if (r) Object.assign(this.focusEl.style, { left: `${r.x - 4}px`, top: `${r.y - 4}px`, width: `${r.w + 8}px`, height: `${r.h + 8}px` });
    }
    if (this.focusPanel) {
      this.focusPanel.visible = show;
      if (r) this.focusPanel.place(r.x - 4, r.y - 4, r.w + 8, r.h + 8);
    }
  }

  dispose(): void {
    this.disposed = true;
    document.removeEventListener('keydown', this.onKey, true);
    document.removeEventListener('pointerdown', this.onPointer, true);
    this.hintEl?.remove();
    this.focusEl?.remove();
    if (this.hintPanel) this.hintPanel.visible = false;
    if (this.focusPanel) this.focusPanel.visible = false;
  }
}
