import { subLevelName } from '../../weapons/subMerge';
import { WorkshopDrag, workshopItem, type WorkshopSource, type WorkshopView } from '../SubWorkshop';
import { menuScale } from '../viewport';
import type { Drag, Overlay, Panel } from './Overlay';
import { C, ellipsize, font, icon, text } from './paint';
import { armorSurface, backdrop, button, heading, Sheet, type Block } from './widgets';

export class CanvasSubWorkshop {
  private view: WorkshopView | null = null;
  private readonly panel: Panel;
  private readonly ghost: Panel;
  private readonly drag = new WorkshopDrag();
  private dragLayout = '';
  private dragRect: (() => ReturnType<Sheet['blockRect']>) | null = null;
  private readonly left: Sheet;
  private readonly right: Sheet;
  private landscape = false;
  private layoutKey = '';
  private readyAt = 0;
  private previousScroll: Overlay['menuScroll'] = null;

  constructor(private readonly ov: Overlay, private readonly action: (id: string) => void) {
    this.left = new Sheet(ov);
    this.right = new Sheet(ov);
    this.panel = ov.panel('sub-workshop', 16, (ctx, w, h) => {
      backdrop(ctx, w, h);
      ctx.fillStyle = 'rgba(10,19,17,.92)'; ctx.fillRect(0, 0, w, h);
      this.left.paint(ctx);
      if (this.landscape) this.right.paint(ctx);
    });
    this.ghost = ov.panel('sub-workshop-drag', 17, (c, w, h) => {
      const d = this.drag.current, item = d && this.view ? workshopItem(this.view, d.source) : null;
      if (!item) return;
      armorSurface(c, 0, 0, w, h, '#edcf8b', '#24352f');
      icon(c, item.icon, 8, 18, 28, '#edcf8b');
      c.font = font(13, 700); text(c, `${item.name} · ${subLevelName(item.level)}`, 43, 22, '#f1e9cf');
      c.font = font(11); text(c, this.drag.label, 43, 45, '#edcf8b');
    });
    this.ghost.visible = false;
    ov.onFrame(() => this.frame());
  }

  show(view: WorkshopView | null): void {
    this.cancelDrag();
    if (view && !this.view) {
      this.readyAt = this.ov.now + 0.25;
      this.previousScroll = this.ov.menuScroll;
      this.ov.menuScroll = amount => {
        this.cancelDrag();
        if (this.left.scrollBy(amount)) this.panel.dirty = true;
        if (this.landscape && this.right.scrollBy(amount)) this.panel.dirty = true;
      };
      this.left.resetScroll(); this.right.resetScroll();
    } else if (!view && this.view) this.ov.menuScroll = this.previousScroll;
    this.view = view;
    this.layoutKey = '';
    this.panel.dirty = true;
  }

  private tap = (id: string) => { if (!this.drag.current && this.ov.now >= this.readyAt) this.action(id); };

  private frame(): void {
    const ov = this.ov, p = this.panel;
    p.visible = !!this.view;
    this.ghost.visible = !!this.view && !!this.drag.current?.moved;
    if (!this.view) return;
    p.place(0, 0, ov.W, ov.H);
    const key = `${ov.W}:${ov.H}:${JSON.stringify(ov.insets)}`;
    if (key !== this.layoutKey) { this.cancelDrag(); this.layout(); this.layoutKey = key; p.dirty = true; }
    ov.region({ id: 'sub-backdrop', z: 16, x: 0, y: 0, w: ov.W, h: ov.H });
    this.left.regions(17, p, 'sub-scroll-left');
    if (this.landscape) this.right.regions(17, p, 'sub-scroll-right');
    const r = this.dragRect?.();
    if (this.drag.current && (!r || this.dragLayout !== `${r.x}:${r.y}:${r.s}`)) this.cancelDrag();
    const d = this.drag.current;
    if (d?.moved) {
      this.ghost.place(Math.max(4, Math.min(ov.W - 176, d.x - 86)), Math.max(4, d.y - 82), 172, 64);
      this.ghost.visible = true;
    }
  }

  /** rect = 起手那一块在屏幕上的位置；挂位和储备格可能在不同的栏里。 */
  private dragFor(source: WorkshopSource, rect: () => ReturnType<Sheet['blockRect']>): Drag {
    const point = (x: number, y: number) => {
      const r = rect();
      return { x: r.x + x * r.s, y: r.y + y * r.s };
    };
    const target = (x: number, y: number) => {
      const hit = this.ov.hit(x, y), match = hit && /^sub-slot-([0-8])$/.exec(hit.id);
      return match ? Number(match[1]) : null;
    };
    return {
      start: (x, y, id) => {
        if (!this.view || this.ov.now < this.readyAt) return false;
        const p = point(x, y), r = rect();
        if (!this.drag.begin(this.view, source, id, p.x, p.y)) return false;
        this.dragLayout = `${r.x}:${r.y}:${r.s}`;
        this.dragRect = rect;
        return true;
      },
      move: (x, y, id) => {
        if (!this.view) return;
        const p = point(x, y);
        this.drag.move(this.view, id, p.x, p.y, target(p.x, p.y));
        this.panel.dirty = this.ghost.dirty = true;
      },
      end: (x, y, id, cancelled) => {
        if (!this.view) return true;
        const p = point(x, y);
        const result = this.drag.end(this.view, id, p.x, p.y, target(p.x, p.y), cancelled);
        this.panel.dirty = true;
        this.ghost.visible = false;
        if (result.action) this.action(result.action);
        return result.handled;
      },
    };
  }

  private cancelDrag(): void {
    if (this.drag.current) this.panel.dirty = true;
    this.drag.cancel();
    this.ghost.visible = false;
  }

  private layout(): void {
    const v = this.view!, { W, H, insets } = this.ov;
    this.landscape = W >= 560 && W > H;
    const scale = Math.min(1.5, menuScale(W, H));
    const available = W - insets.left - insets.right - 28;
    const totalW = Math.min(740 * scale, available);
    const cw = this.landscape ? (totalW / scale - 22) / 2 : Math.min(380, available / scale);
    const cellW = (cw - 8) / 2, gridTop = v.reward ? 64 : 24;
    const gridRect = () => this.left.blockRect(1);
    const cellH = this.landscape ? Math.max(52, Math.min(68, Math.floor(((H - insets.top - insets.bottom - 20) / scale - 78 - gridTop) / 3))) : 68;
    const head: Block = {
      h: 54, paint: (c, w) => {
        heading(c, v.title, w / 2, 14, 21, C.text, 1);
        c.font = font(12); text(c, v.caption, w / 2, 43, '#bcc6b1', 'center');
      },
    };
    const grid: Block = {
      h: gridTop + cellH * 3 + 16,
      paint: c => {
        const d = this.drag.current;
        if (v.reward) {
          c.globalAlpha = d?.moved && d.source === 'reward' ? 0.45 : 1;
          armorSurface(c, 0, 0, cw, 56, v.reward.selected ? '#ebca87' : '#bda66c', '#303726');
          icon(c, v.reward.icon, 12, 13, 28, '#edcf8b');
          c.font = font(11); text(c, '待装 · 拖到挂位', 50, 15, '#c1c7ae');
          c.font = font(14, 700); text(c, `${v.reward.name} · ${subLevelName(v.reward.level)}`, 50, 38, '#edcf8b');
          c.globalAlpha = 1;
        } else {
          c.font = font(13); text(c, '整理不消耗选卡', cw / 2, 10, '#b5c0ad', 'center');
        }
        v.cells.forEach((cell, i) => {
          const x = i % 2 * (cellW + 8), y = gridTop + Math.floor(i / 2) * (cellH + 8);
          const over = d?.moved && d.target === cell.slot && d.source !== cell.slot;
          c.globalAlpha = d?.moved && d.source === cell.slot ? 0.45 : 1;
          armorSurface(c, x, y, cellW, cellH, over ? d.plan ? '#f0cc7e' : '#e69c5b' : cell.target ? '#f0cc7e' : cell.selected ? '#8cb5a5' : '#63725b', over && d.plan ? '#434d32' : cell.target ? '#3c4330' : '#223028');
          icon(c, cell.icon, x + 8, y + (cellH - 28) / 2, 28, '#ddcf9e');
          c.font = font(10);
          text(c, `${cell.position}${cell.locked ? ' · 材料' : cell.link ? ' · 联动' : cell.consumed ? ' · 合入' : ''}`, x + 44, y + 11, '#b2bfa5');
          c.font = font(14, 700); text(c, cell.name, x + 44, y + cellH / 2, '#e8e5d6');
          c.font = font(12); text(c, cell.level ? subLevelName(cell.level) : '可装入', x + 44, y + cellH - 11, '#e5cc8e');
          c.globalAlpha = 1;
        });
      },
      hits: [...(v.reward ? [{ id: 'sub-reward', x: 0, y: 0, w: cw, h: 56, tap: () => this.tap('reward'), drag: this.dragFor('reward', gridRect) }] : []), ...v.cells.map(cell => {
        const i = v.cells.indexOf(cell);
        return { id: `sub-slot-${cell.slot}`, x: i % 2 * (cellW + 8), y: gridTop + Math.floor(i / 2) * (cellH + 8), w: cellW, h: cellH, tap: () => this.tap(`slot:${cell.slot}`), drag: cell.item ? this.dragFor(cell.slot, gridRect) : undefined };
      })],
    };
    // 储备格（T243）：一行三格；横屏放右栏最上面，竖屏接在六格下面
    const resW = (cw - 12) / 3, resH = this.landscape ? 44 : 50, resTop = 20;
    const reserveRect = () => this.landscape ? this.right.blockRect(0) : this.left.blockRect(2);
    const reserve: Block = {
      h: resTop + resH + 6,
      paint: c => {
        const d = this.drag.current;
        c.font = font(11); text(c, '储备 · 不开火', 0, 9, '#9bab96');
        v.reserve.forEach((cell, i) => {
          const x = i * (resW + 6), y = resTop;
          const over = d?.moved && d.target === cell.slot && d.source !== cell.slot;
          c.globalAlpha = d?.moved && d.source === cell.slot ? 0.45 : 1;
          armorSurface(c, x, y, resW, resH, over ? d.plan ? '#f0cc7e' : '#e69c5b' : cell.target ? '#f0cc7e' : cell.selected ? '#8cb5a5' : '#4f5d4a', over && d.plan ? '#434d32' : cell.target ? '#3c4330' : '#1b2420');
          icon(c, cell.icon, x + 5, y + (resH - 22) / 2, 22, cell.item ? '#ddcf9e' : '#7d8a74');
          c.font = font(13, 700); text(c, ellipsize(c, cell.name, resW - 36), x + 32, y + resH / 2 - 8, cell.item ? '#e8e5d6' : '#a5ae9a');
          c.font = font(11); text(c, cell.level ? subLevelName(cell.level) : '可存放', x + 32, y + resH / 2 + 9, '#e5cc8e');
          c.globalAlpha = 1;
        });
      },
      hits: v.reserve.map((cell, i) => ({
        id: `sub-slot-${cell.slot}`, x: i * (resW + 6), y: resTop, w: resW, h: resH,
        tap: () => this.tap(`slot:${cell.slot}`), drag: cell.item ? this.dragFor(cell.slot, reserveRect) : undefined,
      })),
    };
    const info: Block = {
      h: 74, paint: (c, w) => {
        armorSurface(c, 0, 0, w, 74, v.warning ? '#e69c5b' : '#bda66c', '#17221b');
        c.font = font(12);
        v.lines.forEach((line, i) => text(c, ellipsize(c, line, w - 18), 9, 15 + i * 22, v.warning ? '#ffc58f' : '#dce2d2'));
      },
    };
    const note: Block = {
      h: 24, paint: c => {
        c.font = font(11); text(c, '也可点选来源、目标，再确认', 0, 12, '#9bab96');
      },
    };
    const actions: Block = {
      h: 46, paint: c => {
        button(c, 0, 0, cellW, 46, 'outline', v.cancel, { size: 14 });
        c.globalAlpha = v.canConfirm ? 1 : 0.45;
        button(c, cellW + 8, 0, cellW, 46, v.warning ? 'warn' : 'gold', v.confirm, { size: 14 });
        c.globalAlpha = 1;
      },
      hits: [
        { id: 'sub-back', x: 0, y: 0, w: cellW, h: 46, tap: () => this.tap('back') },
        ...(v.canConfirm ? [{ id: 'sub-confirm', x: cellW + 8, y: 0, w: cellW, h: 46, tap: () => this.tap('confirm') }] : []),
      ],
    };
    if (this.landscape) {
      const x = insets.left + (W - insets.left - insets.right - totalW) / 2;
      const h = H - insets.top - insets.bottom - 20, y = insets.top + 10;
      const lh = Math.min(h, (head.h + grid.h + 8) * scale), rh = Math.min(h, (reserve.h + info.h + note.h + actions.h + 24) * scale);
      this.left.setInRect([head, grid], { x, y: y + (h - lh) / 2, w: cw * scale, h: lh }, 8, scale);
      this.right.setInRect([reserve, info, note, actions], { x: x + (cw + 22) * scale, y: y + (h - rh) / 2, w: cw * scale, h: rh }, 8, scale);
    } else this.left.setScrolling([head, grid, reserve, info, note, actions], cw, 8);
  }
}
