import { icon } from './icons';
import { WorkshopDrag, workshopItem, type WorkshopCell, type WorkshopSource, type WorkshopView } from './SubWorkshop';
import { isReserve, subLevelName } from '../weapons/subMerge';

/** 六格装配面板，只发操作，不保存第二份装备数据。 */
export class DomSubWorkshop {
  private readonly root: HTMLElement;
  private readyAt = 0;
  private view: WorkshopView | null = null;
  private readonly drag = new WorkshopDrag();
  private ghost: HTMLElement | null = null;
  private ignoreClick = false;
  constructor(private readonly action: (id: string) => void) {
    this.root = document.createElement('section');
    this.root.id = 'sub-workshop';
    this.root.className = 'overlay hidden';
    this.root.setAttribute('role', 'dialog');
    this.root.setAttribute('aria-modal', 'true');
    this.root.setAttribute('aria-label', '武器改装');
    this.root.addEventListener('click', e => {
      if (this.drag.current || (this.ignoreClick && e.detail !== 0)) { e.preventDefault(); return; }
      const button = (e.target as HTMLElement).closest<HTMLButtonElement>('button[data-sub-action]');
      if (button && !button.disabled && performance.now() >= this.readyAt) this.action(button.dataset.subAction!);
    });
    this.root.addEventListener('pointerdown', this.down);
    this.root.addEventListener('pointermove', this.move);
    this.root.addEventListener('pointerup', this.up);
    this.root.addEventListener('pointercancel', e => { if (this.drag.current?.id === e.pointerId) this.cancelDrag(); });
    this.root.addEventListener('lostpointercapture', e => { if (this.drag.current?.id === e.pointerId) this.cancelDrag(); });
    this.root.addEventListener('dragstart', e => e.preventDefault());
    this.root.addEventListener('contextmenu', e => { if ((e.target as Element).closest('[data-sub-source]')) e.preventDefault(); });
    this.root.addEventListener('scroll', () => this.cancelDrag());
    globalThis.addEventListener('blur', () => this.cancelDrag());
    globalThis.addEventListener('resize', () => this.cancelDrag());
    document.addEventListener('visibilitychange', () => { if (document.hidden) this.cancelDrag(); });
    document.querySelector('#app')!.append(this.root);
  }

  show(v: WorkshopView | null): void {
    this.cancelDrag();
    this.view = v;
    if (v && this.root.classList.contains('hidden')) this.readyAt = performance.now() + 250;
    this.root.classList.toggle('hidden', !v);
    if (!v) return;
    const active = this.root.contains(document.activeElement) ? document.activeElement?.id : null;
    this.root.innerHTML = `<div class="sub-workshop-panel">
      <h2>${v.title}</h2><p class="sub-workshop-caption">${v.caption}</p>
      <div class="sub-workshop-body"><div>${v.reward ? `<button type="button" id="sub-reward" data-sub-action="reward" data-sub-source="reward"
        class="sub-workshop-reward${v.reward.selected ? ' selected' : ''}" aria-label="待装 ${v.reward.name} ${subLevelName(v.reward.level)}，可拖动">
        ${icon(v.reward.icon)}<span><small>待装 · 拖到挂位</small><strong>${v.reward.name} · ${subLevelName(v.reward.level)}</strong></span></button>`
        : '<p class="sub-workshop-idle">整理不消耗选卡</p>'}
      <div class="sub-workshop-grid">${v.cells.map(cell).join('')}</div></div>
      <div><div class="sub-reserve"><p class="sub-reserve-head">储备 · 不开火</p>
      <div class="sub-reserve-grid">${v.reserve.map(cell).join('')}</div></div>
      <div class="sub-workshop-info${v.warning ? ' warning' : ''}" aria-live="polite">${v.lines.join('<br>')}</div>
      <p class="sub-workshop-note">也可点选来源、目标，再确认</p>
      <div class="sub-workshop-actions"><button type="button" class="outline" id="sub-back" data-sub-action="back">${v.cancel}</button>
      <button type="button" id="sub-confirm" data-sub-action="confirm" ${v.canConfirm ? '' : 'disabled'}>${v.confirm}</button></div></div></div>
      </div>`;
    if (active) this.root.querySelector<HTMLElement>(`#${active}`)?.focus({ preventScroll: true });
  }

  private targetAt(x: number, y: number): number | null {
    const cell = document.elementFromPoint(x, y)?.closest<HTMLElement>('[data-sub-slot]');
    return cell && this.root.contains(cell) ? Number(cell.dataset.subSlot) : null;
  }

  private readonly down = (e: PointerEvent): void => {
    if (!e.isPrimary || this.drag.current) { e.preventDefault(); return; }
    this.ignoreClick = false;
    if (e.button !== 0 || !this.view || performance.now() < this.readyAt) return;
    const button = (e.target as Element).closest<HTMLElement>('[data-sub-source]');
    if (!button) return;
    const key = button.dataset.subSource!, source: WorkshopSource = key === 'reward' ? key : Number(key);
    if (!this.drag.begin(this.view, source, e.pointerId, e.clientX, e.clientY)) return;
    e.preventDefault();
    e.stopPropagation();
    this.root.setPointerCapture(e.pointerId);
  };

  private readonly move = (e: PointerEvent): void => {
    if (!this.view || this.drag.current?.id !== e.pointerId) return;
    e.preventDefault();
    this.drag.move(this.view, e.pointerId, e.clientX, e.clientY, this.targetAt(e.clientX, e.clientY));
    this.paintDrag();
  };

  private readonly up = (e: PointerEvent): void => {
    const source = this.drag.current?.source;
    if (!this.view || source === undefined || this.drag.current?.id !== e.pointerId) return;
    e.preventDefault();
    e.stopPropagation();
    const result = this.drag.end(this.view, e.pointerId, e.clientX, e.clientY, this.targetAt(e.clientX, e.clientY));
    this.ignoreClick = true;
    this.clearDrag();
    if (this.root.hasPointerCapture(e.pointerId)) this.root.releasePointerCapture(e.pointerId);
    if (result.action) this.action(result.action);
    else if (!result.handled) this.action(source === 'reward' ? 'reward' : `slot:${source}`);
  };

  private paintDrag(): void {
    const d = this.drag.current;
    if (!d?.moved || !this.view) return;
    const item = workshopItem(this.view, d.source)!;
    if (!this.ghost) {
      this.ghost = document.createElement('div');
      this.ghost.className = 'sub-drag-ghost';
      this.ghost.setAttribute('aria-hidden', 'true');
      this.ghost.innerHTML = `${icon(item.icon)}<strong>${item.name} · ${subLevelName(item.level)}</strong><span></span>`;
      document.body.append(this.ghost);
    }
    this.ghost.style.left = `${Math.max(88, Math.min(innerWidth - 88, d.x))}px`;
    this.ghost.style.top = `${Math.max(84, d.y - 14)}px`;
    this.ghost.querySelector('span')!.textContent = this.drag.label;
    this.root.querySelectorAll('.drag-source, .drag-target, .drag-invalid').forEach(el => el.classList.remove('drag-source', 'drag-target', 'drag-invalid'));
    this.root.querySelector(`[data-sub-source="${d.source}"]`)?.classList.add('drag-source');
    if (d.target !== null && d.target !== d.source) {
      this.root.querySelector(`#sub-slot-${d.target}`)?.classList.add(d.plan ? 'drag-target' : 'drag-invalid');
    }
  }

  private clearDrag(): void {
    this.ghost?.remove();
    this.ghost = null;
    this.root.querySelectorAll('.drag-source, .drag-target, .drag-invalid').forEach(el => el.classList.remove('drag-source', 'drag-target', 'drag-invalid'));
  }

  private cancelDrag(): void {
    const id = this.drag.current?.id;
    if (id !== undefined) this.ignoreClick = true;
    this.drag.cancel();
    this.clearDrag();
    if (id !== undefined && this.root.hasPointerCapture(id)) this.root.releasePointerCapture(id);
  }
}

/** 挂位和储备格同一种按钮，储备格靠 .reserve 换紧凑排版。 */
function cell(c: WorkshopCell): string {
  const reserve = isReserve(c.slot);
  return `<button type="button" id="sub-slot-${c.slot}" data-sub-action="slot:${c.slot}"
    data-sub-slot="${c.slot}" ${c.item ? `data-sub-source="${c.slot}"` : ''}
    class="sub-cell${reserve ? ' reserve' : ''}${c.selected ? ' selected' : ''}${c.target ? ' target' : ''}${c.consumed ? ' consumed' : ''}"
    aria-label="${c.position} ${c.name} ${c.level ? subLevelName(c.level) : ''}${c.locked ? ' 究极材料，可换位' : ''}">
    ${icon(c.icon)}${reserve ? '' : `<small>${c.position}${c.locked ? ' · 材料' : c.link ? ' · 联动' : ''}</small>`}<strong>${c.name}</strong>
    <em>${c.level ? subLevelName(c.level) : reserve ? '可存放' : '可装入'}</em></button>`;
}
