import * as THREE from 'three';
import { GeoCache, type PartSpec } from '../assets/GeoCache';
import { buildTurntableFloor } from './TurntableBackdrop';

/** 原出图候选进入真实开始页；建筑合批，切换后缓存。 */
export function buildGarageBackdrop(geo: GeoCache, kind: 'yard' | 'corridor') {
  const group = new THREE.Group();
  group.name = `turntable-${kind}`;
  group.rotation.y = Math.atan2(0.76, 1);
  const { ground, floorMap } = buildTurntableFloor();
  group.add(ground);
  const materials = new Set<THREE.Material>([ground.material]);
  const textures = new Set<THREE.Texture>([floorMap]);
  const parts: PartSpec[] = [], lamps: PartSpec[] = [];
  const box = (w: number, h: number, d: number, x: number, y: number, z: number, color: number, roll = 0) =>
    parts.push({ geo: new THREE.BoxGeometry(w, h, d), color, pos: [x, y, z], rot: [0, 0, roll] });
  if (kind === 'yard') {
    for (const s of [-1, 1]) {
      box(7.5, 4.1, 7, s * 11, 1.9, 18, 0x26363d);
      box(4.3, 0.15, 8, s * 9.4, 4.7, 18, 0x36454c, s * 0.38);
      box(4.3, 0.15, 8, s * 13.0, 4.7, 18, 0x36454c, -s * 0.38);
      box(0.17, 9.0, 0.17, s * 9, 4.3, 9, 0x43565b);
      box(1.2, 0.48, 0.6, s * 9, 8.7, 9, 0x5b6b6d);
      lamps.push({ geo: new THREE.BoxGeometry(0.95, 0.12, 0.03), color: 0x99afab, pos: [s * 9, 8.7, 8.65] });
      for (let i = 0; i < 4; i++) lamps.push({ geo: new THREE.BoxGeometry(1.0, 0.5, 0.04), color: 0x686a52, pos: [s * (8.4 + i * 1.5), 2.2, 14.45] });
    }
    for (let i = -7; i <= 7; i++) {
      box(0.07, 1.8, 0.07, i * 2.2, 0.8, 12.5, 0x475956);
      box(2.1, 0.06, 0.06, i * 2.2, 1.6, 12.5, 0x42514f);
    }
  } else {
    for (const z of [7, 13, 19, 25, 31]) {
      for (const s of [-1, 1]) {
        box(0.44, 6.6, 0.48, s * 8, 3.1, z, 0x344950);
        box(0.42, 4.6, 0.48, s * 6.7, 7.65, z, 0x3c5258, s * 0.64);
        lamps.push({ geo: new THREE.BoxGeometry(0.13, 2.6, 0.10), color: 0x8d9992, pos: [s * 7.72, 4.8, z - 0.25] });
      }
      box(8.0, 0.4, 0.48, 0, 9.44, z, 0x3c5258);
    }
    box(16, 10, 0.2, 0, 4.7, 34, 0x14242b);
    for (const s of [-1, 1]) {
      box(0.22, 0.1, 50, s * 6.8, -0.1, 12, 0x6c7470);
      for (let i = 0; i < 24; i++) box(1.1, 0.015, 0.3, s * 7.5, -0.16, -8 + i * 2, 0x716b52);
    }
  }
  const add = (name: string, specs: PartSpec[], material: THREE.Material) => {
    materials.add(material);
    const mesh = new THREE.Mesh(geo.merged(`garage-${name}`, () => specs), material);
    mesh.name = name;
    group.add(mesh);
  };
  add(`${kind}-steel`, parts, new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.83, metalness: 0.35 }));
  add(`${kind}-lamps`, lamps, new THREE.MeshBasicMaterial({ vertexColors: true, toneMapped: false }));
  if (kind === 'yard') {
    add('yard-beams', [-1, 1].map((s): PartSpec => ({
      geo: new THREE.ConeGeometry(2.7, 19, 24, 1, true), color: 0xffffff, pos: [s * 6, 10, 15], rot: [0, 0, s * 0.48],
    })), new THREE.MeshBasicMaterial({
      color: 0x8fbfc8, transparent: true, opacity: 0.055, depthWrite: false, side: THREE.DoubleSide,
    }));
  }
  return { group, materials, textures, update: (_time: number) => {} };
}
