/** 固定种子（残骸里乱摆的东西每次一样） */
function seeded(seed: number): () => number {
  let s = seed;
  return () => {
    s = (s * 16807) % 2147483647;
    return (s - 1) / 2147483646;
  };
}

type V3 = [number, number, number];
/** a → b 的一根方钢（桁架、支腿） */
function strut(a: V3, b: V3, w: number, color: number): PartSpec {
  const d = _v.set(b[0] - a[0], b[1] - a[1], b[2] - a[2]);
  const len = d.length();
  _q.setFromUnitVectors(UP, d.normalize());
  _e.setFromQuaternion(_q, 'XYZ');
  return { geo: box(w, len, w), color, pos: [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2, (a[2] + b[2]) / 2], rot: [_e.x, _e.y, _e.z] };
}

