import * as THREE from 'three';
import { CRATER_GLSL, WATER_GLSL, type CraterUniforms } from './Craters';

/**
 * 地面火场（T126，制作人「烧路边的树木和房子的时候会形成一个个火圈……应该是连成片的火焰，不应该是太规则的圈状」）：
 * 原来每格草火各画一块贴地火面、火线从格子中心一圈往外烧，几格挨着就是几个火圈。现在所有地面火写进同一张世界坐标的「火场图」，
 * 每格 T 米、x 方向 NX 格（±80 米）、z 方向 NZ 格循环（320 米一圈）；r = 火（heat）、g = 烧焦（char），双线性插值后再用噪声扭一下，
 * 火线是整张图的等值线——挨着的格子、树、房子之间的火自然连成一片，边沿参差、不成圆。
 * 画法：亮着的格子和它周围 8 格各一块 T × T 的贴地小方片（贴弹坑地面），一个实例化网格、一次绘制，和原来一样。
 * decay：每秒退多少（火 / 焦黑），源头不再续就慢慢熄、焦黑慢慢淡（换成焦痕贴花）；cap：最多几块方片；near：离玩家前后多远以内才写（循环一圈 320 米，不串）
 */
export const FIRE_FIELD = { decay: { heat: 1.2, char: 0.15 }, cap: 1200, near: 150 };

const T = 2.5;
const NX = 64;
const NZ = 128;
const HALF = NX / 2;
const SPAN = T * NZ;

const VERT = /* glsl */ `
${CRATER_GLSL}
attribute vec2 iPos;
varying vec2 vW;
#include <fog_pars_vertex>
void main() {
  vec2 w = iPos + position.xz;
  vW = w;
  vec4 mvPosition = viewMatrix * vec4(w.x, groundH(w) + 0.12, w.y, 1.0);
  gl_Position = projectionMatrix * mvPosition;
  #include <fog_vertex>
}`;

// 噪声按世界坐标取（格点 mod 289 再哈希，不用 sin：手机 GPU 上世界坐标几千米也不塌，T048 的教训）
const FRAG = /* glsl */ `
${WATER_GLSL}
uniform sampler2D uField;
uniform float uTime;
uniform float uZoff;
varying vec2 vW;
#include <fog_pars_fragment>
float hs(vec2 i) {
  i = mod(i, 289.0);
  vec3 p = fract(vec3(i.xyx) * 0.1031);
  p += dot(p, p.yzx + 33.33);
  return fract((p.x + p.y) * p.z);
}
float vn(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hs(i), hs(i + vec2(1.0, 0.0)), f.x), mix(hs(i + vec2(0.0, 1.0)), hs(i + vec2(1.0, 1.0)), f.x), f.y);
}
void main() {
  if (waterH(vW) > -999.0) discard;
  float tm = mod(uTime, 300.0);
  // 取样点按噪声扭一下：格子的方块感没了，火场的边是一条随形的毛边
  vec2 warp = vec2(vn(vW * 0.23 + 3.1), vn(vW * 0.23 + 11.7)) - 0.5;
  vec2 q = vW + warp * 2.6;
  vec2 f = texture2D(uField, vec2(q.x / ${T.toFixed(1)} + ${HALF.toFixed(1)}, (q.y - uZoff) / ${T.toFixed(1)}) / vec2(${NX.toFixed(1)}, ${NZ.toFixed(1)})).rg;
  if (f.r + f.g < 0.02) discard;
  float heat = f.r + 0.26 * (vn(vW * 0.37 + 5.0) - 0.5) + 0.1 * (vn(vW * 1.3 + vec2(0.0, -tm * 0.9)) - 0.5);
  float burnt = f.g + 0.22 * (vn(vW * 0.3 + 17.0) - 0.5) + 0.08 * (vn(vW * 2.1) - 0.5);
  // 火线里面（火烧过的地）和烧焦的地都是焦黑
  float inside = max(smoothstep(0.5, 0.6, burnt), smoothstep(0.5, 0.6, heat));
  // 火线：火场边沿一道一闪一闪、粗细不匀的亮带（跟着火场的形状走），外面一圈烤焦的橙色热晕
  float e = heat - 0.52;
  float gaps = smoothstep(0.2, 0.55, vn(vW * 0.7 + vec2(tm * 0.8, -tm * 0.5)));
  float flick = 0.65 + 0.35 * vn(vW * 1.6 + vec2(-tm * 2.2, tm * 1.4));
  float wide = 0.006 + 0.012 * vn(vW * 0.5 + 23.0);
  float front = exp(-(e * e) / wide) * (0.45 + 0.55 * gaps) * flick;
  float halo = smoothstep(0.3, 0.5, heat) * (1.0 - smoothstep(0.5, 0.56, heat)) * 0.4;
  // 火场里面：零零星星、慢慢游走的几簇火（两层噪声叠，不成方块），越热越多
  vec2 r1 = mat2(0.8, -0.6, 0.6, 0.8) * vW;
  vec2 r2 = mat2(0.5, 0.87, -0.87, 0.5) * vW;
  float fb = vn(r1 * 0.55 + vec2(tm * 0.5, -tm * 0.9)) * 0.6 + vn(r2 * 1.7 + vec2(-tm * 0.8, tm * 0.4)) * 0.4;
  float lick = smoothstep(0.55, 0.9, heat) * smoothstep(0.58, 0.82, fb) * 0.6;
  // 焦黑地上的余烬
  float en = vn(r1 * 2.0 + 7.0) * 0.6 + vn(r2 * 4.4 - 3.0) * 0.4;
  float ember = smoothstep(0.68, 0.88, en) * inside * clamp(heat * 1.6 + 0.2, 0.0, 1.0) * (0.6 + 0.4 * sin(tm * 4.0 + en * 31.0));
  vec3 col = vec3(0.07, 0.055, 0.043) * (0.75 + 0.5 * vn(r2 * 1.3));
  vec3 fire = mix(vec3(1.0, 0.58, 0.18), vec3(0.95, 0.32, 0.05), smoothstep(0.3, 0.8, vn(vW * 0.75 + tm * 0.5)));
  col = mix(col, vec3(0.95, 0.4, 0.08), ember * 0.8);
  col = mix(col, vec3(0.9, 0.34, 0.06), lick);
  float glow = clamp(front + halo, 0.0, 1.0);
  col = mix(col, fire, glow);
  float alpha = max(0.82 * inside, max(max(glow, lick) * 0.92, ember * 0.75));
  if (alpha < 0.01) discard;
  gl_FragColor = vec4(col, alpha);
  #include <colorspace_fragment>
  #include <fog_fragment>
}`;

const mod = (j: number) => ((j % NZ) + NZ) % NZ;

export class FireField {
  readonly mesh: THREE.Mesh;
  private readonly heat = new Float32Array(NX * NZ);
  private readonly char = new Float32Array(NX * NZ);
  /** 每一行现在装的是哪一行（世界 z 格号）：循环到别的行先清空 */
  private readonly rowZ = new Int32Array(NZ).fill(-0x7fffffff);
  private readonly live: number[] = [];
  private readonly isLive = new Uint8Array(NX * NZ);
  private readonly data = new Uint8Array(NX * NZ * 4);
  private readonly tex: THREE.DataTexture;
  private readonly stamp = new Int32Array(NX * NZ);
  private stampN = 0;
  private readonly aPos: THREE.InstancedBufferAttribute;
  private readonly geometry: THREE.InstancedBufferGeometry;
  private readonly mat: THREE.ShaderMaterial;
  private pz = 0;
  private dirty = false;

  constructor(craters: CraterUniforms) {
    this.tex = new THREE.DataTexture(this.data, NX, NZ, THREE.RGBAFormat, THREE.UnsignedByteType);
    this.tex.magFilter = this.tex.minFilter = THREE.LinearFilter;
    this.tex.wrapS = THREE.ClampToEdgeWrapping;
    this.tex.wrapT = THREE.RepeatWrapping;
    this.tex.generateMipmaps = false;
    this.tex.needsUpdate = true;
    const base = new THREE.PlaneGeometry(T, T, 2, 2).rotateX(-Math.PI / 2);
    const geo = new THREE.InstancedBufferGeometry();
    geo.index = base.index;
    geo.setAttribute('position', base.getAttribute('position'));
    this.aPos = new THREE.InstancedBufferAttribute(new Float32Array(FIRE_FIELD.cap * 2), 2);
    this.aPos.setUsage(THREE.DynamicDrawUsage);
    geo.setAttribute('iPos', this.aPos);
    geo.instanceCount = 0;
    this.geometry = geo;
    this.mat = new THREE.ShaderMaterial({
      vertexShader: VERT,
      fragmentShader: FRAG,
      uniforms: { ...THREE.UniformsUtils.merge([THREE.UniformsLib.fog, { uTime: { value: 0 }, uZoff: { value: 0 } }]), uField: { value: this.tex }, ...craters },
      transparent: true,
      depthWrite: false,
      side: THREE.DoubleSide,
      fog: true,
    });
    this.mesh = new THREE.Mesh(geo, this.mat);
    this.mesh.frustumCulled = false;
    this.mesh.renderOrder = 1;
    this.mesh.visible = false;
  }

  /** 亮着的方片数（诊断） */
  get count(): number {
    return this.geometry.instanceCount;
  }

  /** 每次更新先退一点：火每秒退 decay.heat、焦黑退 decay.char，退到 0 的格子收掉；pz = 玩家 z（只写它前后 near 米） */
  decay(dt: number, pz: number): void {
    this.pz = pz;
    const dh = FIRE_FIELD.decay.heat * dt;
    const dc = FIRE_FIELD.decay.char * dt;
    for (let n = this.live.length - 1; n >= 0; n--) {
      const k = this.live[n];
      this.heat[k] = Math.max(0, this.heat[k] - dh);
      this.char[k] = Math.max(0, this.char[k] - dc);
      if (this.heat[k] > 0 || this.char[k] > 0) continue;
      this.isLive[k] = 0;
      this.data[k * 4] = this.data[k * 4 + 1] = 0;
      this.live[n] = this.live[this.live.length - 1];
      this.live.pop();
    }
    this.dirty = true;
  }

  private put(i: number, jz: number, h: number, c: number): void {
    if (i < 0 || i >= NX) return;
    const row = mod(jz);
    if (this.rowZ[row] !== jz) {
      this.rowZ[row] = jz;
      for (let x = 0; x < NX; x++) {
        const k = row * NX + x;
        this.heat[k] = this.char[k] = 0;
        this.data[k * 4] = this.data[k * 4 + 1] = 0;
      }
    }
    const k = row * NX + i;
    if (h > this.heat[k]) this.heat[k] = h;
    if (c > this.char[k]) this.char[k] = c;
    if (!this.isLive[k]) {
      this.isLive[k] = 1;
      this.live.push(k);
    }
  }

  /** 盒子 [x ± hx, z ± hz] 里的格子（格心在盒子里的；每个方向至少取最近的 2 格）取大：火 h、焦黑 c（0..1） */
  box(x: number, z: number, hx: number, hz: number, h: number, c: number): void {
    if (Math.abs(z - this.pz) > FIRE_FIELD.near || Math.abs(x) > T * (HALF - 1)) return;
    let i0 = Math.ceil((x - hx) / T + HALF - 0.5);
    let i1 = Math.floor((x + hx) / T + HALF - 0.5);
    if (i1 - i0 < 1) i1 = (i0 = Math.floor(x / T + HALF - 0.5)) + 1;
    let j0 = Math.ceil((z - hz) / T - 0.5);
    let j1 = Math.floor((z + hz) / T - 0.5);
    if (j1 - j0 < 1) j1 = (j0 = Math.floor(z / T - 0.5)) + 1;
    for (let j = j0; j <= j1; j++) for (let i = i0; i <= i1; i++) this.put(i, j, h, c);
  }

  /** 两点之间一条火带（每半格一个 2 × 2）：隔得近的两处火连起来 */
  line(x0: number, z0: number, x1: number, z1: number, h: number, c: number): void {
    const n = Math.max(1, Math.ceil(Math.hypot(x1 - x0, z1 - z0) / (T * 0.5)));
    for (let s = 0; s <= n; s++) this.box(x0 + ((x1 - x0) * s) / n, z0 + ((z1 - z0) * s) / n, 0, 0, h, c);
  }

  /** (x, z) 这里火有多旺（和着色器一样双线性，不含噪声）：粒子火舌挑落点用 */
  heatAt(x: number, z: number): number {
    const fx = x / T + HALF - 0.5;
    const fz = z / T - 0.5;
    const i0 = Math.floor(fx);
    const j0 = Math.floor(fz);
    const tx = fx - i0;
    const tz = fz - j0;
    const at = (i: number, j: number) => (i < 0 || i >= NX || this.rowZ[mod(j)] !== j ? 0 : this.heat[mod(j) * NX + i]);
    return (at(i0, j0) * (1 - tx) + at(i0 + 1, j0) * tx) * (1 - tz) + (at(i0, j0 + 1) * (1 - tx) + at(i0 + 1, j0 + 1) * tx) * tz;
  }

  /** 上传火场图 + 摆方片（亮着的格子和周围 8 格，各一块）；time = 着色器里火苗游走的时钟 */
  commit(time: number): void {
    this.mat.uniforms.uTime.value = time;
    if (!this.dirty) return;
    this.dirty = false;
    const n0 = this.live.length;
    this.mesh.visible = n0 > 0;
    if (n0 === 0) {
      this.geometry.instanceCount = 0;
      this.tex.needsUpdate = true;
      return;
    }
    this.stampN++;
    const pos = this.aPos.array as Float32Array;
    let n = 0;
    for (const k of this.live) {
      this.data[k * 4] = Math.round(this.heat[k] * 255);
      this.data[k * 4 + 1] = Math.round(this.char[k] * 255);
      const i = k % NX;
      const jz = this.rowZ[(k - i) / NX];
      for (let dj = -1; dj <= 1; dj++) {
        for (let di = -1; di <= 1; di++) {
          const ii = i + di;
          if (ii < 0 || ii >= NX || n >= FIRE_FIELD.cap) continue;
          const key = mod(jz + dj) * NX + ii;
          if (this.stamp[key] === this.stampN) continue;
          this.stamp[key] = this.stampN;
          pos[n * 2] = (ii - HALF + 0.5) * T;
          pos[n * 2 + 1] = (jz + dj + 0.5) * T;
          n++;
        }
      }
    }
    this.geometry.instanceCount = n;
    this.aPos.needsUpdate = true;
    this.tex.needsUpdate = true;
    this.mat.uniforms.uZoff.value = Math.floor(this.pz / SPAN) * SPAN;
  }

  reset(): void {
    for (const k of this.live) {
      this.heat[k] = this.char[k] = 0;
      this.isLive[k] = 0;
    }
    this.live.length = 0;
    this.data.fill(0);
    this.rowZ.fill(-0x7fffffff);
    this.geometry.instanceCount = 0;
    this.mesh.visible = false;
    this.tex.needsUpdate = true;
  }

  dispose(): void {
    this.geometry.dispose();
    this.mat.dispose();
    this.tex.dispose();
  }
}
