/**
 * 开始界面整备台的背景（D1-012 / D1-013 五案）：默认 1 钢铁整备库；其余只给制作人挑方案用，玩家看不到入口。
 * T183 起默认改为 0 开阔展场（360° 环视不穿墙）；原 1～5 仍可用 ?bg= 打开对照，带墙的方案转到背面会看到墙外。
 * 网页链接加 ?bg=0～5；老链接 ?backdrop=foundry / forest 照旧认；小游戏写 globalThis.__TANK_BACKDROP__ = '4' 之类。不写存档
 */
export type BackdropKey = 'showroom' | 'workshop' | 'yard' | 'corridor' | 'foundry' | 'forest';

export const BACKDROPS: readonly { id: string; key: BackdropKey; name: string }[] = [
  { id: '0', key: 'showroom', name: '开阔展场' },
  { id: '1', key: 'workshop', name: '钢铁整备库' },
  { id: '2', key: 'yard', name: '夜间试车坪' },
  { id: '3', key: 'corridor', name: '装甲输送廊' },
  { id: '4', key: 'foundry', name: '钢铁厂区' },
  { id: '5', key: 'forest', name: '林间小道' },
];

export function pickBackdrop(): (typeof BACKDROPS)[number] {
  let value = (globalThis as { __TANK_BACKDROP__?: string }).__TANK_BACKDROP__ ?? null;
  try {
    const q = new URLSearchParams(location.search);
    value = q.get('bg') ?? q.get('backdrop') ?? value;
  } catch { /* 小游戏没有 location，读全局 */ }
  return BACKDROPS.find((b) => b.id === value || b.key === value) ?? BACKDROPS[0];
}
