import { CORES, type CoreId } from '../weapons/defs';
import type { Overlay, Panel } from './canvas/Overlay';
import { button, backdrop } from './canvas/widgets';
import { font, text } from './canvas/paint';

export interface CoopLobbyView {
  cores: [CoreId, CoreId];
  ready: [boolean, boolean];
  connected: boolean;
  reconnect: boolean;
}
export const COOP_CORES: CoreId[] = ['cannon', 'rocket', 'laser', 'vulcan'];
export function localCoopLink(enabled: boolean): void {
  if (__WX__) return;
  const url = new URL(location.href);
  for (const key of ['debug', 'autostart', 'coop', 'core', 'fusion', 'zone', 't', 'boss', 'gate']) url.searchParams.delete(key);
  if (enabled) url.searchParams.set('coop', '1');
  location.assign(url.href);
}

/** 两套菜单各持一份；手柄二号只由游戏的席位输入驱动。 */
export class CoopLobby {
  private view: CoopLobbyView | null = null;
  private el: HTMLElement | null = null;
  private panel: Panel | null = null;
  private signature = '';
  constructor(private readonly act: (id: string) => void, ov?: Overlay) {
    if (ov) {
      this.panel = ov.panel('coop-lobby', 30, (g, w, h) => {
        if (!this.view) return;
        backdrop(g, w, h);
        const x = (w - 300) / 2, y = Math.max(12, (h - 310) / 2);
        g.font = font(22, 800);
        text(g, this.view.reconnect ? '连接已暂停' : '本地双人', w / 2, y + 18, '#ead5a6', 'center');
        g.font = font(14);
        this.lines().forEach((line, i) => text(g, line, w / 2, y + 58 + i * 26, '#d8dec9', 'center'));
        for (const b of this.buttons()) button(g, x + b.x, y + b.y, b.w, 44, 'outline', b.name);
      });
      ov.onFrame(() => {
        if (!this.panel || !this.view) return;
        this.panel.place(0, 0, ov.W, ov.H);
        const x = (ov.W - 300) / 2, y = Math.max(12, (ov.H - 310) / 2);
        ov.region({ id: 'coop-block', z: 30, x: 0, y: 0, w: ov.W, h: ov.H });
        for (const b of this.buttons()) ov.region({ id: `coop-${b.id}`, z: 31, x: x + b.x, y: y + b.y, w: b.w, h: 44, tap: () => this.act(b.id), panel: this.panel });
      });
    }
  }
  private lines(): string[] {
    const v = this.view!;
    return [
      `一号 · ${CORES[v.cores[0]].name} · ${v.ready[0] ? '已准备' : '待确认'}`,
      `二号 · ${CORES[v.cores[1]].name} · ${!v.connected ? '待连接' : v.ready[1] ? '已准备' : '待确认'}`,
      v.reconnect ? '两人确认后继续' : !v.ready[0] ? '一号先选流派并准备' : !v.connected ? '二号按手柄确认认领' : '二号左右选流派，确认出击',
    ];
  }
  private buttons(): { id: string; name: string; x: number; y: number; w: number }[] {
    const v = this.view!;
    return [
      ...(!v.reconnect && !v.ready[0] ? COOP_CORES.map((id, i) => ({ id: `core:${id}`, name: CORES[id].name, x: i * 76, y: 150, w: 72 })) : []),
      { id: 'ready', name: v.ready[0] ? '取消准备' : '一号准备', x: 0, y: 208, w: 145 },
      { id: 'back', name: '主菜单', x: 155, y: 208, w: 145 },
    ];
  }
  show(view: CoopLobbyView | null): void {
    this.view = view;
    if (this.panel) this.panel.visible = !!view;
    if (!view) { this.el?.remove(); this.el = null; this.signature = ''; return; }
    const signature = JSON.stringify(view);
    if (signature === this.signature) return;
    this.signature = signature;
    if (this.panel) { this.panel.dirty = true; return; }
    if (!this.el) {
      this.el = document.createElement('section');
      this.el.id = 'coop-lobby';
      this.el.className = 'overlay coop-lobby';
      this.el.addEventListener('click', e => {
        const id = (e.target as HTMLElement).closest<HTMLElement>('[data-coop]')?.dataset.coop;
        if (id) this.act(id);
      });
      document.body.append(this.el);
    }
    this.el.innerHTML = `<div class="coop-sheet"><h2>${view.reconnect ? '连接已暂停' : '本地双人'}</h2>${this.lines().map(s => `<p>${s}</p>`).join('')}<div class="coop-core-picks">${this.buttons().map(b => `<button type="button" data-coop="${b.id}"${b.id === `core:${view.cores[0]}` ? ' class="on"' : ''}>${b.name}</button>`).join('')}</div></div>`;
  }
}
