import * as THREE from 'three';

/**
 * 护盾发生器给我方的能量盾（T195，制作人「被打应该有个波纹的效果，类似星际争霸中神族护盾」）：
 * 平时只剩一圈很淡的边缘光；挨打那一点亮起六角格和一团白光，一圈波纹顺着盾面往外扩散、表面跟着鼓一下，
 * 打得越疼波纹越亮越大；同时最多 HITS 道，满了顶掉最老的。盾被打穿整面闪一下再灭。
 * 一个椭球、一次绘制、叠加混合；挨打方向记在盾自己的坐标里，车转盾面上的波纹跟着转。
 */
const HITS = 8;
/** 波纹寿命（秒）、扩散速度（球面弧度 / 秒）、鼓起高度（米） */
const RIPPLE = { life: 0.85, speed: 3.4, bulge: 0.14 };
/** 盾的形状：半径 × 各轴（贴着车身的扁椭球） */
const RADIUS = 4.6;
const SHAPE = new THREE.Vector3(1, 0.72, 1.14);

const COMMON = /* glsl */ `
uniform vec4 uHit[${HITS}];
uniform float uTime;
float ripple(vec3 d, vec4 h, out float core) {
  core = 0.0;
  if (h.w < 0.0 || h.w > ${RIPPLE.life.toFixed(2)}) return 0.0;
  float a = acos(clamp(dot(d, normalize(h.xyz)), -1.0, 1.0));
  float t = h.w;
  float life = 1.0 - t / ${RIPPLE.life.toFixed(2)};
  float r = t * ${RIPPLE.speed.toFixed(2)};
  float w = 0.1 + t * 0.22;
  float k = length(h.xyz);
  core = exp(-a * a / (0.05 + 0.1 * k)) * exp(-t * 7.0) * k;
  return exp(-pow((a - r) / w, 2.0)) * life * life * k;
}`;

const VERT = /* glsl */ `
${COMMON}
varying vec3 vDir;
varying vec3 vP;
varying vec3 vN;
varying vec3 vV;
varying float vWave;
void main() {
  vec3 d = normalize(position);
  float wave = 0.0;
  for (int i = 0; i < ${HITS}; i++) {
    float c;
    wave += ripple(d, uHit[i], c);
  }
  vWave = wave;
  vDir = d;
  vP = position;
  vec3 p = position + normal * min(wave, 1.5) * ${RIPPLE.bulge.toFixed(2)} / ${SHAPE.y.toFixed(2)};
  vec4 wp = modelMatrix * vec4(p, 1.0);
  vN = normalize(mat3(modelMatrix) * normal);
  vV = normalize(cameraPosition - wp.xyz);
  gl_Position = projectionMatrix * viewMatrix * wp;
}`;

const FRAG = /* glsl */ `
${COMMON}
uniform float uLevel;
uniform float uFlash;
varying vec3 vDir;
varying vec3 vP;
varying vec3 vN;
varying vec3 vV;
varying float vWave;
float sHash(vec2 p) { vec3 q = fract(vec3(p.xyx) * 0.1031); q += dot(q, q.yzx + 33.33); return fract((q.x + q.y) * q.z); }
// 六角格：x = 离格边多远（0 = 格边），yz = 格号
vec3 hexCell(vec2 p) {
  const vec2 s = vec2(1.0, 1.7320508);
  vec4 hc = floor(vec4(p, p - vec2(0.5, 1.0)) / s.xyxy) + 0.5;
  vec4 h = vec4(p - hc.xy * s, p - (hc.zw + 0.5) * s);
  bool a = dot(h.xy, h.xy) < dot(h.zw, h.zw);
  vec2 q = abs(a ? h.xy : h.zw);
  return vec3(0.5 - max(dot(q, s * 0.5), q.x), a ? hc.xy : hc.zw + 0.5);
}
void main() {
  float fres = pow(1.0 - abs(dot(normalize(vN), normalize(vV))), 2.2);
  float glow = 0.0;
  for (int i = 0; i < ${HITS}; i++) {
    float c;
    float w = ripple(vDir, uHit[i], c);
    glow += w * 0.9 + c * 1.6;
  }
  // 三面投影的六角格（球面上不拉扯），格子各自明暗一点
  vec3 bw = pow(abs(vDir), vec3(4.0));
  bw /= bw.x + bw.y + bw.z;
  vec3 hx = hexCell(vP.zy * 1.25), hy = hexCell(vP.xz * 1.25), hz = hexCell(vP.xy * 1.25);
  float edge = hx.x * bw.x + hy.x * bw.y + hz.x * bw.z;
  float cell = sHash(hx.yz) * bw.x + sHash(hy.yz + 17.0) * bw.y + sHash(hz.yz + 31.0) * bw.z;
  float line = 1.0 - smoothstep(0.015, 0.07, edge);
  float lit = clamp(glow, 0.0, 2.0);
  float idle = fres * (0.05 + 0.07 * uLevel) * (0.85 + 0.15 * sin(uTime * 2.3 + vDir.y * 4.0));
  float a = idle + uFlash * (0.12 + fres * 0.5) + lit * (0.16 + line * 0.75 + cell * 0.18) * (0.35 + fres * 0.9);
  a += line * fres * 0.06 * uLevel;
  vec3 col = mix(vec3(0.16, 0.48, 1.0), vec3(0.72, 0.92, 1.0), clamp(lit * 0.55 + line * lit * 0.4 + uFlash * 0.5, 0.0, 1.0));
  gl_FragColor = vec4(col * (1.0 + lit * 0.9), clamp(a, 0.0, 1.0));
}`;

export class PlayerShield {
  readonly mesh: THREE.Mesh<THREE.SphereGeometry, THREE.ShaderMaterial>;
  private readonly hits = Array.from({ length: HITS }, () => new THREE.Vector4(0, 1, 0, -1));
  private readonly v = new THREE.Vector3();
  private readonly w = new THREE.Vector3();
  private readonly m = new THREE.Matrix4();
  private next = 0;
  private flash = 0;

  constructor() {
    this.mesh = new THREE.Mesh(
      new THREE.SphereGeometry(RADIUS, 56, 36),
      new THREE.ShaderMaterial({
        vertexShader: VERT,
        fragmentShader: FRAG,
        uniforms: { uHit: { value: this.hits }, uTime: { value: 0 }, uLevel: { value: 1 }, uFlash: { value: 0 } },
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
        side: THREE.DoubleSide,
      }),
    );
    this.mesh.scale.copy(SHAPE);
    this.mesh.position.y = 1.5;
    this.mesh.renderOrder = 4;
    this.mesh.visible = false;
  }

  /** 挨了一下：from = 来向的世界坐标（null = 随手挑一个朝上的方向），power = 这一下打掉的盾占满盾几成，broke = 盾被打穿了 */
  hit(from: readonly [number, number, number] | null, power: number, broke: boolean): void {
    const m = this.mesh;
    const d = this.v;
    if (from) {
      m.updateWorldMatrix(true, false);
      d.set(from[0], from[1], from[2]).applyMatrix4(this.m.copy(m.matrixWorld).invert());
      if (d.lengthSq() < 1e-6) d.set(0, 1, 0);
    } else d.set(Math.random() - 0.5, 0.3 + Math.random() * 0.6, Math.random() - 0.5);
    d.normalize();
    // 小口径打一下也看得见，重炮一下波纹拉满（方向向量的长度 = 强度）
    const k = THREE.MathUtils.clamp(0.42 + Math.sqrt(Math.max(0, power)) * 2.2, 0.42, 1.25);
    // 0.04 秒内同一处又挨一下：叠进刚才那道，不另开
    const last = this.hits[(this.next + HITS - 1) % HITS];
    if (last.w >= 0 && last.w < 0.04 && d.dot(this.w.set(last.x, last.y, last.z).normalize()) > 0.95) {
      const len = Math.hypot(last.x, last.y, last.z) || 1;
      const s = Math.min(1.25, len + k * 0.3) / len;
      last.set(last.x * s, last.y * s, last.z * s, last.w);
    } else {
      this.hits[this.next].set(d.x * k, d.y * k, d.z * k, 0);
      this.next = (this.next + 1) % HITS;
    }
    if (broke) this.flash = 1;
  }

  /** level = 剩余护盾占满盾几成（≤ 0 = 没盾，波纹放完再藏） */
  update(delta: number, level: number): void {
    const u = this.mesh.material.uniforms;
    u.uTime.value += delta;
    let live = false;
    for (const h of this.hits) {
      if (h.w < 0) continue;
      h.w += delta;
      if (h.w > RIPPLE.life) h.w = -1;
      else live = true;
    }
    this.flash = Math.max(0, this.flash - delta * 3);
    u.uLevel.value = THREE.MathUtils.clamp(level, 0, 1);
    u.uFlash.value = this.flash;
    this.mesh.visible = level > 0.01 || live || this.flash > 0;
  }

  dispose(): void {
    this.mesh.geometry.dispose();
    this.mesh.material.dispose();
  }
}
