import * as THREE from 'three';
import type { GeoCache } from '../assets/GeoCache';
import { MAT, enemyPaint } from '../assets/materials';
import { ENEMY_MODELS, soldierFigure } from '../assets/models/enemies';
import { ROTOR, rotorGeometry, vultureHub, vultureHull } from '../assets/models/vulture';
import { GUNSHIP_BLADES, GUNSHIP_ROTOR, gunshipHub, gunshipHull, gunshipRadar } from '../assets/models/gunship';
import { ELITE } from '../entities/Enemy';
import { createBoss } from '../bosses/bosses';
import type { BossContext } from '../bosses/Boss';
import { createCanvas } from '../ui/canvas/Overlay';
import { Turntable, type TurntableView } from './Turntable';

/**
 * 图鉴的「标本照」（T022-b，策划 `T022-文案与图鉴-策划案.md` 4.3 方案一）：用游戏自己的渲染器、真模型，在一个小摄影棚场景里拍 3/4 前侧俯视的小图——
 * 主光 + 补光 + 轮廓光（透明底，格子底色由界面画），按包围盒（首领按特写框）自动取景；步兵用 `soldierFigure` 拼的静态造型，首领建一份不进战场的展示模型（`BossContext` 给空实现）、拍完就丢。
 * 第一次要哪张才拍（游戏暂停着），按键缓存到关游戏；2 倍像素渲染到渲染目标 → 读像素（渲染目标里是线性色，手动转 sRGB）→ 缩到 W × H 的 2D 小画布（顺带抗锯齿）。
 * 没遇到过的 = 同一张图把不透明像素涂成深灰 + 一圈暗金描边（剪影）。DOM 版用 dataURL，画布版直接 drawImage 小画布
 */
export const PHOTO = { w: 192, h: 128 };

const SRGB = new Uint8Array(256);
for (let i = 0; i < 256; i++) {
  const c = i / 255;
  SRGB[i] = Math.round(255 * (c <= 0.0031308 ? c * 12.92 : 1.055 * Math.pow(c, 1 / 2.4) - 0.055));
}

export class Studio {
  private readonly cache = new Map<string, HTMLCanvasElement | null>();
  private readonly urls = new Map<string, string>();
  private turntable: Turntable | null = null;

  constructor(
    private readonly renderer: THREE.WebGLRenderer,
    private readonly geo: GeoCache,
  ) {}

  /** 静态标本照与实时整备台共用渲染器和三面布光。 */
  preview(view: TurntableView | null): void {
    if (!view || (typeof document !== 'undefined' && document.hidden)) {
      this.turntable?.pause();
      return;
    }
    this.prepare().render(view);
  }

  /** 整备台（四辆展示车、背景、环境光）：启动时在加载页里先建好（T108），别等开始界面第一帧 */
  prepare(): Turntable {
    return (this.turntable ??= new Turntable(this.renderer, studioLights(-1)));
  }

  dispose(): void {
    this.turntable?.dispose();
    this.turntable = null;
    this.cache.clear();
    this.urls.clear();
  }

  /** key = 图鉴条目的键（foe:<兵种> / boss:<序号> / gate:0），locked = 剪影；拍不出来返回 null */
  photo(key: string, locked: boolean): HTMLCanvasElement | null {
    const id = `${key}|${locked ? 1 : 0}`;
    if (this.cache.has(id)) return this.cache.get(id)!;
    let out: HTMLCanvasElement | null = null;
    try {
      const base = locked ? this.photo(key, false) : this.shoot(key);
      out = base && locked ? silhouette(base) : base;
    } catch {
      out = null;
    }
    this.cache.set(id, out);
    return out;
  }

  /** DOM 版用的 dataURL（拍不出来 = 空字符串） */
  url(key: string, locked: boolean): string {
    const id = `${key}|${locked ? 1 : 0}`;
    let u = this.urls.get(id);
    if (u === undefined) {
      const c = this.photo(key, locked);
      u = c ? c.toDataURL('image/png') : '';
      this.urls.set(id, u);
    }
    return u;
  }

  private shoot(key: string): HTMLCanvasElement | null {
    const scene = new THREE.Scene();
    const center = new THREE.Vector3();
    let radius = 2;
    let dispose = () => {};
    const [type, id] = key.split(':');
    if (type === 'boss') {
      const player = new THREE.Vector3(0, 0, 60);
      const noop = (): unknown => new Proxy(() => undefined, { get: (_t, p) => (p === 'then' ? undefined : noop()), apply: () => undefined });
      const ctx = new Proxy({ scene, geo: this.geo, player, nearest: () => player, hpScale: 1, spawnPart: () => null } as Record<string, unknown>, { get: (t, p: string) => (p in t ? t[p] : noop()) }) as unknown as BossContext;
      const boss = createBoss(Number(id), ctx, 0, 0);
      // 有专门的标本照姿势就摆上（D5 巨炮：炮管抬到 32°，看得出三层本体和整根炮管）
      (boss as { studioPose?: () => void }).studioPose?.();
      // 构造里顺手摆进场景的别的东西不拍
      for (const c of [...scene.children]) if (c !== boss.root) c.removeFromParent();
      radius = boss.showcase(center) * 1.25;
      // 列车（几十米长、部件没登记所以特写点落在原点）：只框最前面的车头；巨炮（炮管 60 多米）：框整门炮
      const box = new THREE.Box3().setFromObject(boss.root);
      if (!box.isEmpty() && box.max.z - box.min.z > 45) {
        if (Number(id) % 4 === 1) {
          center.set((box.min.x + box.max.x) / 2, (box.min.y + box.max.y) / 2, box.min.z + 11);
          radius = 13;
        } else {
          box.getCenter(center);
          radius = box.getSize(new THREE.Vector3()).length() * 0.42;
        }
      }
      dispose = () => boss.root.removeFromParent();
    } else {
      const g = type === 'gate' ? (id === '1' ? this.model('vulture') : this.crew()) : this.model(id);
      if (!g) return null;
      scene.add(g);
      const box = new THREE.Box3().setFromObject(g);
      if (box.isEmpty()) return null;
      box.getCenter(center);
      radius = box.getSize(new THREE.Vector3()).length() / 2;
    }
    // 灯：天光 + 左前上主光 + 右前补光 + 背后轮廓光（不放地台：剪影要按不透明像素描，格子底色由界面画）
    scene.add(studioLights(1));
    // 3/4 前侧俯视约 20°，按半径自动退到框得住的距离
    const W = PHOTO.w * 2;
    const H = PHOTO.h * 2;
    const cam = new THREE.PerspectiveCamera(26, W / H, 0.1, 2000);
    const dir = new THREE.Vector3(-0.62, 0.42, 1).normalize();
    const fit = Math.min(Math.tan(THREE.MathUtils.degToRad(13)), Math.tan(THREE.MathUtils.degToRad(13)) * cam.aspect);
    cam.position.copy(center).addScaledVector(dir, (radius / fit) * 1.02);
    cam.lookAt(center);
    const r = this.renderer;
    const rt = new THREE.WebGLRenderTarget(W, H);
    const prevTarget = r.getRenderTarget();
    const prevColor = r.getClearColor(new THREE.Color());
    const prevAlpha = r.getClearAlpha();
    const prevAuto = r.autoClear;
    const buf = new Uint8Array(W * H * 4);
    try {
      r.setRenderTarget(rt);
      r.setClearColor(0x000000, 0);
      r.autoClear = true;
      r.clear();
      r.render(scene, cam);
      r.readRenderTargetPixels(rt, 0, 0, W, H, buf);
    } finally {
      r.setRenderTarget(prevTarget);
      r.setClearColor(prevColor, prevAlpha);
      r.autoClear = prevAuto;
      rt.dispose();
      dispose();
    }
    // 上下翻转 + 线性 → sRGB，再缩到一半（抗锯齿）
    const big = createCanvas();
    big.width = W;
    big.height = H;
    const bg = big.getContext('2d')!;
    const img = bg.createImageData(W, H);
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        const s = ((H - 1 - y) * W + x) * 4;
        const d = (y * W + x) * 4;
        img.data[d] = SRGB[buf[s]];
        img.data[d + 1] = SRGB[buf[s + 1]];
        img.data[d + 2] = SRGB[buf[s + 2]];
        img.data[d + 3] = buf[s + 3];
      }
    }
    bg.putImageData(img, 0, 0);
    const out = createCanvas();
    out.width = PHOTO.w;
    out.height = PHOTO.h;
    const og = out.getContext('2d')!;
    og.imageSmoothingEnabled = true;
    og.drawImage(big, 0, 0, PHOTO.w, PHOTO.h);
    return out;
  }

  /** 「轰天」卫队合照（T050）：三个按实战体型、照战场上的站位排开（间距收到八成），都朝镜头这边 */
  private crew(): THREE.Object3D {
    const g = new THREE.Group();
    for (const [kind, x, z] of ELITE.gate.at) {
      const m = this.model(kind);
      if (!m) continue;
      m.scale.setScalar(ELITE.size[kind] ?? 1);
      m.position.set(x * 0.8, 0, z * 0.8);
      g.add(m);
    }
    return g;
  }

  /** 普通敌人的展示模型：车辆 = ENEMY_MODELS（车体 + 炮塔 + 装甲板 + 发光件 + 能量盾），步兵 = soldierFigure */
  private model(kind: string): THREE.Object3D | null {
    const g = new THREE.Group();
    // 秃鹫（T093）/ 铁鹰（T095）：机身 + 桨毂 + 旋翼盘（铁鹰再加桅顶雷达罩）；T096 起和地面车辆同一份涂装（钢灰迷彩）
    if (kind === 'vulture' || kind === 'gunship') {
      const big = kind === 'gunship';
      const hub = big ? GUNSHIP_ROTOR.hub : ROTOR.hub;
      const paint = enemyPaint();
      g.add(new THREE.Mesh(big ? gunshipHull(this.geo) : vultureHull(this.geo), paint));
      const head = new THREE.Mesh(big ? gunshipHub(this.geo) : vultureHub(this.geo), paint);
      head.position.set(...hub);
      g.add(head);
      const rotor = new THREE.Mesh(rotorGeometry(false, big ? GUNSHIP_BLADES : 2), new THREE.MeshBasicMaterial({ vertexColors: true, transparent: true, depthWrite: false, side: THREE.DoubleSide }));
      rotor.position.set(...hub);
      g.add(rotor);
      if (big) {
        const radar = new THREE.Mesh(gunshipRadar(this.geo), paint);
        radar.position.set(...GUNSHIP_ROTOR.radar);
        g.add(radar);
      }
      return g;
    }
    const m = ENEMY_MODELS[kind];
    if (!m) {
      g.add(new THREE.Mesh(this.geo.merged(`studio-soldier-${kind}`, () => soldierFigure(kind)), MAT.painted));
      return g;
    }
    const soft = kind === 'moto';
    const paint = soft ? MAT.painted : enemyPaint();
    g.add(new THREE.Mesh(this.geo.merged(`enemy-${kind}-hull`, m.hull), paint));
    if (m.turret) {
      const t = new THREE.Mesh(this.geo.merged(`enemy-${kind}-turret`, m.turret.parts), paint);
      t.position.set(...m.turret.pos);
      g.add(t);
    }
    m.plates?.forEach((p, i) => g.add(new THREE.Mesh(this.geo.merged(`enemy-${kind}-plate${i}`, p), paint)));
    for (const gl of m.glow ?? []) {
      const s = new THREE.Mesh(this.geo.sphere(gl.r, 10), gl.color === 'red' ? MAT.signalRed : MAT.energyBlue);
      s.position.set(...gl.pos);
      g.add(s);
    }
    const sh = m.shield;
    if (sh) {
      const s = new THREE.Mesh(this.geo.get(`shield${sh.r},${sh.h},${sh.arc}`, () => new THREE.CylinderGeometry(sh.r, sh.r, sh.h, 28, 1, true, -sh.arc / 2, sh.arc)), MAT.eliteShield);
      s.position.y = sh.y;
      g.add(s);
    }
    return g;
  }
}

function studioLights(front: number): THREE.Group {
  const lights = new THREE.Group();
  lights.add(new THREE.HemisphereLight(0xe6ecf4, 0x4a443c, 1.3));
  const key = new THREE.DirectionalLight(0xfff2e0, 3);
  key.name = 'studio-key';
  key.position.set(-6, 10, 8 * front);
  const fill = new THREE.DirectionalLight(0xc8d8ff, 0.9);
  fill.position.set(8, 4, 6 * front);
  const rim = new THREE.DirectionalLight(0xffffff, 2);
  rim.name = 'studio-rim';
  rim.position.set(2, 6, -10 * front);
  lights.add(key, fill, rim);
  return lights;
}

/** 剪影：不透明像素涂深灰，挨着透明像素的一圈涂暗金 */
function silhouette(src: HTMLCanvasElement): HTMLCanvasElement {
  const w = src.width;
  const h = src.height;
  const out = createCanvas();
  out.width = w;
  out.height = h;
  const sg = src.getContext('2d')!;
  const a = sg.getImageData(0, 0, w, h).data;
  const og = out.getContext('2d')!;
  const img = og.createImageData(w, h);
  const on = (x: number, y: number) => x >= 0 && y >= 0 && x < w && y < h && a[(y * w + x) * 4 + 3] > 40;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      if (!on(x, y)) continue;
      const edge = !on(x - 1, y) || !on(x + 1, y) || !on(x, y - 1) || !on(x, y + 1);
      const d = (y * w + x) * 4;
      img.data[d] = edge ? 0xb8 : 0x24;
      img.data[d + 1] = edge ? 0x91 : 0x26;
      img.data[d + 2] = edge ? 0x3a : 0x2a;
      img.data[d + 3] = 255;
    }
  }
  og.putImageData(img, 0, 0);
  return out;
}
